def public_release_readiness_table() -> pd.DataFrame:
    """Repository-level public beta readiness checks."""
    root = Path(__file__).resolve().parent

    def exists(rel_path: str) -> bool:
        return (root / rel_path).exists()

    dependency_contract = _distribution.requirements_floor_contract_from_file(
        root / "requirements.txt",
        RUNTIME_PACKAGE_FLOORS,
    )
    dependency_total = len(dependency_contract)
    dependency_ready_count = int(dependency_contract["Status"].eq("Ready").sum()) if dependency_total else 0
    dependency_issues = dependency_contract.loc[
        dependency_contract["Status"].ne("Ready"),
        "Package",
    ].astype(str).tolist() if dependency_total else []
    dependency_ready = exists("requirements.txt") and dependency_total > 0 and not dependency_issues

    rows = [
        {
            "Check": "License",
            "Status": "Ready" if exists("LICENSE") else "Blocker",
            "Evidence": (
                "MIT LICENSE and plain-language responsible-use notice are present."
                if exists("LICENSE") and exists("LICENSE_NOTICE.md") else
                "LICENSE or LICENSE_NOTICE.md is missing."
            ),
            "Action": (
                "Keep commercial-use permission and as-is/no-warranty language visible."
                if exists("LICENSE") and exists("LICENSE_NOTICE.md") else
                "Add a project license and responsible-use notice before public release."
            ),
        },
        {
            "Check": "Runtime dependencies",
            "Status": "Ready" if dependency_ready else "Blocker",
            "Evidence": (
                f"requirements.txt matches {dependency_ready_count}/{dependency_total} doctor runtime floors."
                if dependency_ready else
                f"{dependency_ready_count}/{dependency_total} dependency floor rows are ready; review: {', '.join(dependency_issues[:5]) or 'requirements.txt missing'}."
            ),
            "Action": "Keep requirements.txt and `python streamlit_app.py --doctor` runtime floors in lockstep.",
        },
        {
            "Check": "Development verification",
            "Status": "Ready" if exists("requirements-dev.txt") and exists("tests") else "Blocker",
            "Evidence": "requirements-dev.txt and tests/ are present." if exists("requirements-dev.txt") and exists("tests") else "Development verification files are incomplete.",
            "Action": "Run `make verify` before release.",
        },
        {
            "Check": "GitHub Actions",
            "Status": "Ready" if exists(".github/workflows/python-streamlit.yml") else "Blocker",
            "Evidence": ".github/workflows/python-streamlit.yml is present." if exists(".github/workflows/python-streamlit.yml") else "CI workflow is missing.",
            "Action": "Confirm the latest main-branch Actions run passes before tagging.",
        },
        {
            "Check": "Data privacy disclosure",
            "Status": "Ready" if exists("SECURITY.md") and exists("DEPLOYMENT.md") else "Review",
            "Evidence": "SECURITY.md and DEPLOYMENT.md are present." if exists("SECURITY.md") and exists("DEPLOYMENT.md") else "Security/deployment docs need review.",
            "Action": "Keep hosted-deployment privacy warnings visible in README and app.",
        },
        {
            "Check": "Public beta limitations",
            "Status": "Ready" if not public_beta_limitations_table().empty else "Blocker",
            "Evidence": f"{len(public_beta_limitations_table())} limitation rows documented.",
            "Action": "Do not publish claims that exceed these boundaries.",
        },
        {
            "Check": "External validation stance",
            "Status": "Documented",
            "Evidence": "Cross-package validation plan and tolerance policy are available.",
            "Action": "Treat TAM/sirt/mirt/FACETS/mfrmr equality as validation evidence only after explicit cross-checks.",
        },
        {
            "Check": "Archived validation artifact inventory",
            "Status": "Documented",
            "Evidence": f"{len(external_simulation_reference_inventory())} archived validation-artifact rows are documented.",
            "Action": "Use the inventory for numerical validation planning; do not bundle private or large validation data in the public app.",
        },
        {
            "Check": "Simulation validation templates",
            # The Status predicate and the Evidence string both now read from
            # external_simulation_template_inventory (3 rows: Python / R / Julia),
            # so the "X template rows are documented" sentence and the
            # Ready / Review flag cannot drift apart as they did in v0.2.2-beta
            # where Status consulted the 4-key scripts dict while Evidence
            # quoted the 3-row inventory.
            "Status": "Ready" if len(external_simulation_template_inventory()) >= 3 else "Review",
            "Evidence": f"{len(external_simulation_template_inventory())} Python/R/Julia template rows are documented.",
            "Action": "Use sanitized templates for external validation handoff; keep machine-specific paths and sensitive data out of the public repo.",
        },
        {
            "Check": "Cross-language reproducibility scripts",
            "Status": "Ready" if len(reproducibility_script_export_matrix()) >= 7 else "Review",
            "Evidence": f"{len(reproducibility_script_export_matrix())} Python/R/Julia/Stan reproducibility rows are documented.",
            "Action": "Archive the exact script, config, data fingerprint, package versions, and sampler settings used for each reproducibility claim.",
        },
        {
            "Check": "Uto-family Bayesian MFRM Stan roadmap",
            "Status": "Documented" if not bayesian_mfrm_stan_refinement_plan().empty else "Review",
            "Evidence": "Uto & Ueno (2020), Uto (2021), and Uto (2023) are mapped to Stan implementation layers and claim boundaries.",
            "Action": "Treat Uto-family Stan output as a Bayesian extension until model parameterization, priors, and diagnostics are validated.",
        },
        {
            "Check": "mfrmr 0.2.0 migration coverage",
            "Status": "Ready" if not mfrmr_020_migration_coverage_table().empty else "Review",
            "Evidence": f"{len(mfrmr_020_migration_coverage_table())} migration-scope rows documented through mfrmr 0.2.0 (inherits the 0.1.5 / 0.1.6 surface).",
            "Action": "Use this table to avoid overstating one-to-one coverage of the R package surface.",
        },
        {
            "Check": "Release checklist",
            "Status": "Ready" if exists("RELEASE_CHECKLIST.md") else "Review",
            "Evidence": "RELEASE_CHECKLIST.md is present." if exists("RELEASE_CHECKLIST.md") else "Release checklist is missing.",
            "Action": "Use it before creating a tag or GitHub Release.",
        },
    ]
    return pd.DataFrame(rows)


def _compact_label(value, max_chars: int = 34) -> str:
    """Shorten dense axis labels while preserving full values for hover text."""
    text = str(value)
    if len(text) <= max_chars:
        return text
    if max_chars <= 4:
        return text[:max_chars]
    return text[: max_chars - 3] + "..."


def _compact_label_list(values, max_chars: int = 34) -> list[str]:
    prefs = get_visualization_preferences()
    policy = str(prefs.get("label_policy", VISUAL_LABEL_POLICY_DEFAULT))
    if policy == "Hover only":
        return ["" for _ in values]
    pref_max = int(prefs.get("label_max_chars", max_chars))
    effective_max = pref_max if policy == "Show all" else min(int(max_chars), pref_max)
    return [_compact_label(value, max_chars=effective_max) for value in values]


def _normalize_plot_label_mode(value: object) -> str:
    mode = str(value or PLOT_LABEL_MODE_DEFAULT).strip()
    aliases = {
        "numbers": "Number",
        "number": "Number",
        "plotnumber": "Number",
        "plot number": "Number",
        "short": "Short label",
        "short label": "Short label",
        "full": "Full label",
        "full label": "Full label",
        "hide": "None",
        "hidden": "None",
        "none": "None",
        "auto": "Auto",
    }
    if mode in PLOT_LABEL_MODE_OPTIONS:
        return mode
    return aliases.get(mode.lower(), PLOT_LABEL_MODE_DEFAULT)


def _plot_label_group_name(row: pd.Series) -> str:
    role = str(row.get("Role", "")).strip()
    if role == "Person":
        return "Person"
    if role == "Threshold":
        return "Thresholds"
    facet = str(row.get("Facet", "")).strip()
    plot_column = str(row.get("PlotColumn", "")).strip()
    return facet or plot_column or role or "Element"


def _plot_label_prefix_map(group_names: list[str]) -> dict[str, str]:
    known_prefixes = {
        "person": "P",
        "persons": "P",
        "rater": "R",
        "raters": "R",
        "criterion": "C",
        "criteria": "C",
        "task": "T",
        "tasks": "T",
        "item": "I",
        "items": "I",
        "region": "REG",
        "regions": "REG",
        "threshold": "TH",
        "thresholds": "TH",
    }
    used: set[str] = set()
    prefixes: dict[str, str] = {}
    for group in group_names:
        key = str(group)
        if key in prefixes:
            continue
        normalized = re.sub(r"\s+", " ", key.strip()).lower()
        alnum = re.sub(r"[^A-Za-z0-9]", "", key).upper()
        words = re.findall(r"[A-Za-z0-9]+", key)
        candidates: list[str] = []
        if normalized in known_prefixes:
            candidates.append(known_prefixes[normalized])
        if words:
            candidates.append("".join(word[0].upper() for word in words[:3]))
        if alnum:
            candidates.extend([alnum[:1], alnum[:2], alnum[:3]])
        candidates.append("X")
        chosen = ""
        for candidate in candidates:
            candidate = candidate[:3] or "X"
            if candidate not in used:
                chosen = candidate
                break
        if not chosen:
            base = (alnum[:1] or "X")
            suffix = 2
            while f"{base}{suffix}" in used:
                suffix += 1
            chosen = f"{base}{suffix}"
        used.add(chosen)
        prefixes[key] = chosen
    return prefixes


def build_plot_label_lookup(
    plot_rows: pd.DataFrame,
    *,
    label_mode: str | None = None,
    max_chars: int | None = None,
) -> pd.DataFrame:
    """Attach PLOTNUMBER-style label IDs and selected display labels.

    The helper keeps the full label, compact label, and generated ID in
    separate columns so exported figures can be reproduced even when the
    visible plot chooses short labels, numeric IDs, or no text.
    """
    if not isinstance(plot_rows, pd.DataFrame) or plot_rows.empty:
        cols = list(getattr(plot_rows, "columns", [])) + [
            "PlotLabelID",
            "PlotLabelShort",
            "PlotLabelFull",
            "PlotLabelMode",
            "PlotLabelGroup",
        ]
        return pd.DataFrame(columns=list(dict.fromkeys(cols)))

    prefs = get_visualization_preferences()
    mode = _normalize_plot_label_mode(label_mode if label_mode is not None else prefs.get("plot_label_mode"))
    policy = str(prefs.get("label_policy", VISUAL_LABEL_POLICY_DEFAULT))
    effective_max = int(max_chars if max_chars is not None else prefs.get("label_max_chars", VISUAL_LABEL_MAX_CHARS_DEFAULT))
    effective_max = _clamp_int(effective_max, VISUAL_LABEL_MAX_CHARS_DEFAULT, 4, 160)

    out = plot_rows.copy()
    groups = [_plot_label_group_name(row) for _, row in out.iterrows()]
    ordered_groups = list(dict.fromkeys(groups))
    prefixes = _plot_label_prefix_map(ordered_groups)
    counters: dict[str, int] = {}
    ids: list[str] = []
    for group in groups:
        counters[group] = counters.get(group, 0) + 1
        ids.append(f"{prefixes[group]}{counters[group]:03d}")

    full_labels: list[str] = []
    for _, row in out.iterrows():
        role = str(row.get("Role", "")).strip()
        raw = str(row.get("RawLabel", "")).strip()
        display = str(row.get("DisplayLabel", "")).strip()
        if role == "Threshold":
            full_labels.append(display or raw)
        else:
            full_labels.append(raw or display)

    short_labels = [_compact_label(label, max_chars=effective_max) for label in full_labels]
    if mode == "Number":
        display_labels = ids
    elif mode == "Full label":
        display_labels = full_labels
    elif mode == "Short label":
        display_labels = short_labels
    elif mode == "None":
        display_labels = ["" for _ in full_labels]
    elif policy == "Hover only":
        display_labels = ["" for _ in full_labels]
    elif policy == "Show all":
        display_labels = full_labels
    else:
        display_labels = short_labels

    out["PlotLabelID"] = ids
    out["PlotLabelShort"] = short_labels
    out["PlotLabelFull"] = full_labels
    out["PlotLabelMode"] = mode
    out["PlotLabelGroup"] = groups
    out["DisplayLabel"] = display_labels
    return out


def _readable_plot_margins(
    y_labels: list[str] | None = None,
    x_labels: list[str] | None = None,
    base_left: int = 90,
    base_bottom: int = 70,
) -> dict[str, int]:
    """Dynamic margins for plots with categorical labels."""
    y_len = max((len(str(v)) for v in (y_labels or [])), default=0)
    x_len = max((len(str(v)) for v in (x_labels or [])), default=0)
    return {
        "l": int(min(260, max(base_left, 7 * min(y_len, 30) + 40))),
        "r": 30,
        "t": 80,
        "b": int(min(180, max(base_bottom, 6 * min(x_len, 24) + 45))),
    }


def _select_heatmap_labels(pivot: pd.DataFrame, max_rows: int = 35, max_cols: int = 35) -> tuple[list, list, bool]:
    """Select the strongest heatmap rows/columns when all labels would be unreadable."""
    if not isinstance(pivot, pd.DataFrame) or pivot.empty:
        return [], [], False
    n_rows, n_cols = pivot.shape
    needs_filter = n_rows > max_rows or n_cols > max_cols or n_rows * n_cols > max_rows * max_cols
    if not needs_filter:
        return list(pivot.index), list(pivot.columns), False
    abs_vals = pivot.abs()
    row_scores = abs_vals.max(axis=1).replace([np.inf, -np.inf], np.nan).fillna(-np.inf)
    col_scores = abs_vals.max(axis=0).replace([np.inf, -np.inf], np.nan).fillna(-np.inf)
    selected_rows = set(row_scores.sort_values(ascending=False).head(max_rows).index)
    selected_cols = set(col_scores.sort_values(ascending=False).head(max_cols).index)
    rows = [label for label in pivot.index if label in selected_rows]
    cols = [label for label in pivot.columns if label in selected_cols]
    return rows, cols, True


def category_probability_curve_options(result: dict) -> pd.DataFrame:
    """Return available category-curve scopes for the fitted model."""
    config = result.get("config", {}) if isinstance(result, dict) else {}
    prep = result.get("prep", {}) if isinstance(result, dict) else {}
    params = result.get("params", {}) if isinstance(result, dict) else {}
    model = config.get("model", "RSM")
    step_facet = config.get("step_facet")
    average_label = (
        "Shared rating-scale thresholds"
        if model == "RSM" else
        f"Average across {step_facet} levels" if step_facet else "Average across step-facet levels"
    )
    rows = [
        {
            "OptionIndex": 0,
            "Label": average_label,
            "IsAverage": True,
            "StepFacet": step_facet,
            "Level": "",
            "LevelIndex": np.nan,
            "Slope": _category_curve_mean_slope(params, model),
        }
    ]
    if model not in {"PCM", "GPCM"}:
        return pd.DataFrame(rows)

    levels = list((prep.get("levels", {}) or {}).get(step_facet, []))
    slopes = np.asarray(params.get("slopes", []), dtype=float)
    for idx, level in enumerate(levels):
        slope = 1.0
        if model == "GPCM" and idx < len(slopes) and np.isfinite(slopes[idx]) and slopes[idx] > 0:
            slope = float(slopes[idx])
        rows.append(
            {
                "OptionIndex": idx + 1,
                "Label": f"{step_facet} = {level}",
                "IsAverage": False,
                "StepFacet": step_facet,
                "Level": str(level),
                "LevelIndex": idx,
                "Slope": slope,
            }
        )
    return pd.DataFrame(rows)


def _category_curve_mean_slope(params: dict, model: str) -> float:
    if model != "GPCM":
        return 1.0
    slopes = np.asarray(params.get("slopes", []), dtype=float)
    finite = slopes[np.isfinite(slopes) & (slopes > 0)]
    return float(np.nanmean(finite)) if finite.size else 1.0


def build_category_probability_curve_data(
    result: dict,
    step_level_index: int | None = None,
    theta_grid: np.ndarray | None = None,
    theta_points: int = 121,
) -> dict:
    """Build category probability and expected-score curves for UI/tests."""
    params = result.get("params", {}) if isinstance(result, dict) else {}
    config = result.get("config", {}) if isinstance(result, dict) else {}
    prep = result.get("prep", {}) if isinstance(result, dict) else {}
    model = config.get("model", "RSM")
    rating_min = int(prep.get("rating_min", 0) or 0)
    n_cat = config.get("n_cat")
    step_facet = config.get("step_facet")
    level_label = ""
    level_index = np.nan
    is_average = True
    slope = 1.0

    if model == "RSM":
        steps = params.get("steps")
        if steps is None or len(steps) == 0:
            return {"available": False, "reason": "Step parameters not available."}
        step_params = np.asarray(steps, dtype=float)
        scope = "Shared RSM rating-scale thresholds"
    elif model in {"PCM", "GPCM"}:
        steps_mat = params.get("steps_mat")
        if steps_mat is None or len(steps_mat) == 0:
            return {"available": False, "reason": "Step-facet threshold parameters not available."}
        steps_mat = np.asarray(steps_mat, dtype=float)
        levels = list((prep.get("levels", {}) or {}).get(step_facet, []))
        if step_level_index is None:
            step_params = np.nanmean(steps_mat, axis=0)
            scope = f"Average across {step_facet} levels" if step_facet else "Average across step-facet levels"
            slope = _category_curve_mean_slope(params, model)
        else:
            idx = int(step_level_index)
            if idx < 0 or idx >= steps_mat.shape[0]:
                return {"available": False, "reason": f"Step-facet level index {idx} is out of range."}
            step_params = steps_mat[idx]
            level_label = str(levels[idx]) if idx < len(levels) else str(idx)
            level_index = idx
            is_average = False
            scope = f"{step_facet} = {level_label}" if step_facet else f"Step-facet level {level_label}"
            if model == "GPCM":
                slopes = np.asarray(params.get("slopes", []), dtype=float)
                if idx < len(slopes) and np.isfinite(slopes[idx]) and slopes[idx] > 0:
                    slope = float(slopes[idx])
        if model == "PCM":
            slope = 1.0
    else:
        return {"available": False, "reason": f"Category curves are not available for model {model}."}

    step_cum = np.concatenate([[0.0], np.cumsum(step_params)])
    if n_cat is None or int(n_cat) != len(step_cum):
        n_cat = len(step_cum)
    else:
        n_cat = int(n_cat)
    if theta_grid is None:
        theta_lo = min(-4.0, float(np.nanmin(step_cum)) - 3.0)
        theta_hi = max(4.0, float(np.nanmax(step_cum)) + 3.0)
        theta_grid = np.linspace(theta_lo, theta_hi, int(theta_points))
    else:
        theta_grid = np.asarray(theta_grid, dtype=float)
        theta_lo = float(np.nanmin(theta_grid)) if theta_grid.size else -4.0
        theta_hi = float(np.nanmax(theta_grid)) if theta_grid.size else 4.0

    eta_mat = np.outer(theta_grid, np.arange(n_cat, dtype=float))
    log_num = float(slope) * (eta_mat - step_cum)
    log_denom = logsumexp(log_num, axis=1, keepdims=True)
    probs = np.exp(log_num - log_denom)
    category_values = np.arange(n_cat) + rating_min
    prob_wide = pd.DataFrame(probs, columns=[f"Cat {int(v)}" for v in category_values])
    prob_wide.insert(0, "Theta", theta_grid)
    prob_long = prob_wide.melt(id_vars="Theta", var_name="Category", value_name="Probability")
    category_map = {f"Cat {int(v)}": int(v) for v in category_values}
    prob_long["CategoryValue"] = prob_long["Category"].map(category_map)
    expected = pd.DataFrame({
        "Theta": theta_grid,
        "ExpectedScore": probs.dot(category_values.astype(float)),
    })
    thresholds = pd.DataFrame({
        "Step": [f"Step_{idx + 1}" for idx in range(len(step_params))],
        "Estimate": np.asarray(step_params, dtype=float),
    })
    if not thresholds.empty:
        boundary = [
            _yardstick_step_boundary(label, rating_min=rating_min)
            for label in thresholds["Step"].astype(str).tolist()
        ]
        thresholds["DisplayLabel"] = [item[0] for item in boundary]
        thresholds["BoundaryLower"] = [item[1] for item in boundary]
        thresholds["BoundaryUpper"] = [item[2] for item in boundary]
    metadata = {
        "Model": model,
        "Scope": scope,
        "StepFacet": step_facet,
        "Level": level_label,
        "LevelIndex": level_index,
        "IsAverage": is_average,
        "Slope": float(slope),
        "ThetaMin": theta_lo,
        "ThetaMax": theta_hi,
        "NCategories": n_cat,
        "RatingMin": rating_min,
        "RatingMax": int(rating_min + n_cat - 1),
    }
    return {
        "available": True,
        "probability": prob_long,
        "probability_wide": prob_wide,
        "expected": expected,
        "thresholds": thresholds,
        "metadata": metadata,
    }


# Canonical numeric rounding for user-facing measure tables.
# The audit found inconsistent rounding across tables (3 / 4 / 6 decimals
# mixed). Standard: measures / SE / CI / eigenvalues / reliability all
# at 3 decimals; RMSE / Variance / Separation at 3 decimals; probabilities
# at 4 decimals (to avoid "1.00" collapsing to 1). Use this helper for
# any table going into the UI so rounding drifts toward one place.

_MEASURE_DECIMALS: int = 3
_PROBABILITY_DECIMALS: int = 4


def _render_run_breadcrumb(result: dict, facet_cols: list[str]) -> None:
    """Render a compact one-line banner showing which run is currently
    displayed — model, method, convergence status, iterations, n obs /
    persons / facets, and an abbreviated data fingerprint.

    Helps users orient themselves when they have multiple runs in the
    history stack and are clicking Restore between them: previously the
    results area gave no "where am I?" signal after a restore.
    """
    if not isinstance(result, dict):
        return
    config = result.get("config", {}) or {}
    prep = result.get("prep", {}) or {}
    summary = result.get("summary")

    model = str(config.get("model", "?"))
    method = str(config.get("method", "?"))
    n_obs = prep.get("n_obs", "?")
    n_person = prep.get("n_person", "?")
    n_facets = len(facet_cols) if isinstance(facet_cols, (list, tuple)) else "?"
    converged = "?"
    iterations = "?"
    if isinstance(summary, pd.DataFrame) and not summary.empty:
        row = summary.iloc[0]
        converged = "converged" if bool(row.get("Converged", False)) else "not converged"
        try:
            iterations = f"{int(row.get('Iterations', 0))} iter"
        except (TypeError, ValueError):
            iterations = "? iter"
    fingerprint = str(config.get("run_fingerprint", config.get("analysis_config_fingerprint", "")))
    fingerprint_short = fingerprint[:8] if fingerprint else "—"

    with st.container(border=True):
        st.markdown(
            f"**Current run** · `{model}` / `{method}` · {converged} · "
            f"{iterations} · **{n_obs:,}** obs × **{n_person:,}** persons × "
            f"**{n_facets}** facets · fingerprint `{fingerprint_short}`"
            if isinstance(n_obs, int) and isinstance(n_person, int)
            else
            f"**Current run** · `{model}` / `{method}` · {converged} · "
            f"{iterations} · **{n_obs}** obs × **{n_person}** persons × "
            f"**{n_facets}** facets · fingerprint `{fingerprint_short}`"
        )


_MFRM_GLOSSARY: dict[str, str] = {
    "logit": "log-odds scale; 1 logit ≈ one step on the linear trait axis.",
    "infit": "inlier-sensitive information-weighted mean-square; 0.5–1.5 ≈ acceptable.",
    "outfit": "outlier-sensitive unweighted mean-square; same 0.5–1.5 interpretation band.",
    "mnsq": "mean-square fit statistic (observed / expected variance ratio); 1.0 = perfect fit.",
    "zstd": "approximate standardised z-score of the mean-square; |z| > 2 ≈ statistically significant misfit. FACETS uses additional df handling, so exact parity is not guaranteed.",
    "jmle": "joint maximum likelihood estimation; estimates person and facet parameters together.",
    "mml": "marginal maximum likelihood estimation; integrates over the person ability distribution.",
    "step facet": "facet whose levels carry separate step thresholds in PCM / GPCM / GRM.",
    "anchor": "fixing an element's measure to a known value so other parameters are estimated relative to it.",
    "separation": "ratio of true variance to error variance; separation ≥ 2 is a common floor.",
    "strata": "reliably distinguishable performance levels ≈ (4·separation + 1) / 3.",
    "rsm": "Rating Scale Model (Andrich 1978); all items share one set of step thresholds.",
    "pcm": "Partial Credit Model (Masters 1982); each item has its own step thresholds.",
    "gpcm": "Generalized PCM (Muraki 1992); PCM plus a positive slope per step-facet level.",
    "sesoi": "smallest effect size of interest; used in equivalence / bias claim tests.",
    "se": "standard error of a measure, in logits.",
    "ci": "confidence interval (default 95% = estimate ± 1.96 × SE).",
    "dif": "differential item functioning: an item is scored differently by an external person group (e.g. L1, gender) after matching on overall ability. Screening evidence, not a fairness verdict.",
    "uniform dif": "DIF that is constant across the ability range (a group-level shift); detected by the ordinal-logistic M1-vs-M0 likelihood-ratio test. Non-uniform DIF instead varies with ability (M2-vs-M1).",
    "population prior sd": "the person ability SD used by MML quadrature — set by the user (fixed, the default) or estimated from the data by EM (free, the opt-in 'Estimate person SD'). When estimated it makes the person metric data-determined and comparable to engines that estimate the variance; separate from facet regularization.",
    "facet regularization": "optional Gaussian MAP-style penalty on selected free non-person facet effects.",
    "penalized objective": "negative log-likelihood plus regularization penalty; not itself an ordinary likelihood.",
    "rhat": "potential scale reduction factor (Gelman & Rubin 1992); > 1.01 flags non-mixing.",
    "ess": "effective sample size of posterior draws; < 400 flags sampling inefficiency.",
    "divergent": "HMC transition that fell off the typical set; indicates posterior geometry issues.",
    "ebfmi": "energy Bayesian fraction of missing information; < 0.3 flags poor energy exploration.",
}


def render_glossary_expander(scope: str = "global") -> None:
    """Render the MFRM / Bayesian glossary as a collapsed expander.

    Call once per tab / section where Rasch vocabulary shows up. The
    glossary text is single-sourced from ``_MFRM_GLOSSARY`` so adding a
    new term propagates everywhere.
    """
    with st.expander("MFRM / Bayesian glossary", expanded=False):
        st.caption(
            "Quick reference for terms used across this app. Hover over "
            "column headers in result tables (where available) to see "
            "the same definitions as tooltips."
        )
        glossary_rows = [
            {"Term": term.upper() if len(term) <= 4 else term.title(), "Definition": defn}
            for term, defn in _MFRM_GLOSSARY.items()
        ]
        st.dataframe(
            pd.DataFrame(glossary_rows),
            width="stretch",
            hide_index=True,
        )


_MEASURE_COLUMN_PRIORITY: list[str] = [
    # Identifying columns first, then key measurement columns, then fit
    # statistics, then anchor / metadata. Anything not listed here keeps
    # its original order and lands at the end.
    "Facet", "Level", "Person", "Element",
    "Estimate", "Measure",
    "SE", "CI_Lower", "CI_Upper",
    "SE_Method", "SE_Status", "CI_Method", "CI_Status", "UncertaintyCaution",
    "Infit", "InfitMnSq", "InfitZStd", "Infit_ZSTD",
    "Outfit", "OutfitMnSq", "OutfitZStd", "Outfit_ZSTD",
    "PtMeaCorr",
    "Reliability", "Separation", "Strata",
    "Bias", "Bias Size", "Bias_t",
    "N", "N_Fit", "N_Bias", "TotalCount", "TotalCountAll",
    "Anchor", "Status",
    "ReliabilityNote", "FitNote",
]


def reorder_measure_columns(df: "pd.DataFrame") -> "pd.DataFrame":
    """Return ``df`` with columns reordered so identity + measure columns
    appear before fit statistics, and low-priority metadata (anchors,
    count columns, notes) move to the end.

    The priority list is a guide, not a schema — columns that are not in
    the list keep their original order and land after the ranked ones.
    Non-DataFrame / schema-less inputs pass through untouched. Empty
    rowcount DataFrames are still reordered so tables whose data arrives
    later render consistently.
    """
    if not isinstance(df, pd.DataFrame) or len(df.columns) == 0:
        return df
    ranked = [c for c in _MEASURE_COLUMN_PRIORITY if c in df.columns]
    remaining = [c for c in df.columns if c not in set(ranked)]
    ordered = ranked + remaining
    if ordered == list(df.columns):
        return df
    return df.reindex(columns=ordered)


def style_fit_columns(df: "pd.DataFrame"):
    """Return a Styler that highlights Infit / Outfit mean-square columns.

    Mean-square interpretation (Wright & Linacre 1994):
      * < 0.50          over-fit   (too predictable)        — yellow
      * 0.50 – 1.50     acceptable                          — green
      * 1.50 – 2.00     noisy                               — orange
      * ≥ 2.00          distorting (significant misfit)     — red

    The helper returns a Styler if the DataFrame has Infit / Outfit-like
    columns, else the DataFrame untouched. Callers pass the result to
    `st.dataframe(...)`, which renders the styled cells unchanged.
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df

    def _fit_color(value: float) -> str:
        if value is None or pd.isna(value):
            return ""
        if value >= 2.0:
            return "background-color: #fde0dc"  # light red
        if value >= 1.5:
            return "background-color: #ffe8cc"  # light orange
        if value < 0.5:
            return "background-color: #fff4cc"  # light yellow
        return "background-color: #dff5e4"      # light green (acceptable)

    fit_cols = [
        c for c in df.columns
        if any(tok in str(c).lower() for tok in ("infit", "outfit"))
        and "zstd" not in str(c).lower()  # ZSTD uses a different scale
        and "note" not in str(c).lower()
        and pd.api.types.is_numeric_dtype(df[c])
    ]
    if not fit_cols:
        return df
    try:
        return df.style.map(_fit_color, subset=fit_cols)
    except Exception:
        # Older pandas Styler used .applymap(); fall back.
        try:
            return df.style.applymap(_fit_color, subset=fit_cols)
        except Exception:
            return df


def format_measure_table(
    df: "pd.DataFrame",
    *,
    measure_decimals: int = _MEASURE_DECIMALS,
    probability_decimals: int = _PROBABILITY_DECIMALS,
) -> "pd.DataFrame":
    """Return ``df`` with standardised numeric rounding for display.

    Measure-like columns (Estimate, SE, CI_*, Infit, Outfit, RMSE,
    Separation, Strata, Reliability, Eigenvalue, etc.) round to
    ``measure_decimals`` (default 3); columns whose names look like
    probabilities or shares round to ``probability_decimals`` (default
    4). Non-numeric columns pass through untouched.
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df
    out = df.copy()
    measure_patterns = (
        "estimate", "se", "ci_", "infit", "outfit", "zstd",
        "rmse", "separation", "strata", "reliability",
        "eigenvalue", "measure", "logit", "theta", "bias",
    )
    prob_patterns = (
        "prob", "proportion", "pct", "percent", "share", "rate",
        "variance",
    )
    for col in out.columns:
        if not pd.api.types.is_numeric_dtype(out[col]):
            continue
        lower = str(col).lower()
        if any(p in lower for p in prob_patterns):
            out[col] = out[col].round(probability_decimals)
        elif any(p in lower for p in measure_patterns):
            out[col] = out[col].round(measure_decimals)
    return out


def stable_json_fingerprint(payload: object, length: int = 16) -> str:
    """Stable short SHA-256 digest for reproducibility metadata."""
    text = json.dumps(
        payload,
        sort_keys=True,
        ensure_ascii=False,
        default=str,
        separators=(",", ":"),
    )
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[: int(length)]


def dataframe_fingerprint(df: pd.DataFrame | None, length: int = 16) -> str | None:
    """Fingerprint DataFrame content without storing the DataFrame in Streamlit cache."""
    if df is None:
        return None
    if not isinstance(df, pd.DataFrame):
        return stable_json_fingerprint({"type": type(df).__name__, "repr": repr(df)}, length=length)

    digest = hashlib.sha256()
    digest.update(json.dumps([str(c) for c in df.columns], ensure_ascii=False).encode("utf-8"))
    digest.update(json.dumps([str(t) for t in df.dtypes], ensure_ascii=False).encode("utf-8"))
    digest.update(np.asarray(df.shape, dtype=np.int64).tobytes())
    try:
        normalized = df.astype("string").where(pd.notna(df), "<NA>")
        row_hashes = pd.util.hash_pandas_object(normalized, index=True).to_numpy(dtype=np.uint64, copy=False)
        digest.update(row_hashes.tobytes())
    except Exception:
        digest.update(df.to_csv(index=True).encode("utf-8"))
    return digest.hexdigest()[: int(length)]


def uploaded_file_fingerprint(file_obj, length: int = 16) -> str | None:
    """Fingerprint uploaded-file content for session-state staleness checks."""
    if file_obj is None:
        return None
    declared_size = getattr(file_obj, "size", None)
    try:
        declared_size_int = int(declared_size) if declared_size is not None else None
    except (TypeError, ValueError):
        declared_size_int = None
    if declared_size_int is not None and declared_size_int >= TABLE_FILE_HARD_LIMIT_BYTES:
        return stable_json_fingerprint(
            {
                "name": getattr(file_obj, "name", None),
                "size": declared_size_int,
                "sha256": None,
                "content_hash_skipped": "file exceeds hard table-upload limit",
            },
            length=length,
        )
    raw = b""
    try:
        raw = file_obj.getvalue()
    except Exception:
        try:
            pos = file_obj.tell()
        except Exception:
            pos = None
        try:
            raw = file_obj.read()
        except Exception:
            raw = b""
        finally:
            if pos is not None:
                try:
                    file_obj.seek(pos)
                except Exception:
                    pass
    if raw is None:
        raw = b""
    if isinstance(raw, str):
        raw = raw.encode("utf-8")
    raw = bytes(raw)
    return stable_json_fingerprint(
        {
            "name": getattr(file_obj, "name", None),
            "size": getattr(file_obj, "size", len(raw)),
            "sha256": hashlib.sha256(raw).hexdigest(),
        },
        length=length,
    )


def table_source_fingerprint(
    *,
    text_value: str | None = None,
    file_input=None,
    delimiter: str | None = None,
    length: int = 16,
) -> str | None:
    """Fingerprint raw table input controls for stale-result detection."""
    text_norm = None
    if text_value is not None and str(text_value).strip():
        text_norm = str(text_value).replace("\r\n", "\n").replace("\r", "\n").strip()
    file_fp = uploaded_file_fingerprint(file_input, length=32)
    if text_norm is None and file_fp is None:
        return None
    return stable_json_fingerprint(
        {
            "text": text_norm,
            "file": file_fp,
            "file_name": getattr(file_input, "name", None) if file_input is not None else None,
            "file_size": getattr(file_input, "size", None) if file_input is not None else None,
            "delimiter": delimiter or "auto",
        },
        length=length,
    )


def config_fingerprint(config: dict | None, length: int = 16) -> str:
    """Fingerprint analysis settings while excluding derived fingerprint fields."""
    if not isinstance(config, dict):
        return stable_json_fingerprint({}, length=length)
    excluded = {
        "run_fingerprint",
        "analysis_config_fingerprint",
        "config_export_fingerprint",
    }
    payload = {str(k): v for k, v in config.items() if str(k) not in excluded}
    return stable_json_fingerprint(payload, length=length)


def _load_shared_simulation_engine():
    """Load the improved Simulation Python engine when available.

    The app keeps its embedded legacy engine as a fallback, but for the default
    JMLE route we prefer the shared engine so the Streamlit app benefits from
    the same analytical-gradient and optimizer improvements used in the
    simulation study.
    """
    engine_path = (
        Path(__file__).resolve().parents[2]
        / "Simulation"
        / "engines"
        / "mfrm_python.py"
    )
    if not engine_path.exists():
        return None
    spec = importlib.util.spec_from_file_location("simulation_mfrm_python", engine_path)
    if spec is None or spec.loader is None:
        return None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


try:
    SHARED_SIM_ENGINE = _load_shared_simulation_engine()
    SHARED_SIM_ENGINE_LOAD_ERROR = None
except Exception as exc:
    SHARED_SIM_ENGINE = None
    SHARED_SIM_ENGINE_LOAD_ERROR = str(exc)


USE_EMBEDDED_ENGINE_ONLY = True

FINAL_RESIDUAL_PCT_GE2_READY = 5.0
FINAL_RESIDUAL_PCT_GE2_REVIEW = 10.0
FINAL_PERSON_RELIABILITY_READY = 0.80
FINAL_PERSON_RELIABILITY_REVIEW = 0.50
FINAL_PCA_EIGENVALUE_READY = 2.0
FINAL_PCA_EIGENVALUE_REVIEW = 3.0


# ---------------------------------------------------------------------------
# Embedded MFRM core computation engine (self-contained)
