def get_custom_simulation_design_preset_settings(preset_key: str) -> dict[str, object]:
    """Return a copy of a custom-simulation design preset."""
    selected = str(preset_key or "balanced")
    settings = CUSTOM_SIMULATION_DESIGN_PRESETS.get(
        selected,
        CUSTOM_SIMULATION_DESIGN_PRESETS["balanced"],
    )
    return {
        **settings,
        "facet_names": list(settings["facet_names"]),
        "facet_level_counts": list(settings["facet_level_counts"]),
        "facet_sds": list(settings["facet_sds"]),
    }


def parse_custom_simulation_thresholds(
    text: str,
    n_categories: int,
) -> np.ndarray:
    """Parse comma/space/semicolon separated thresholds for custom simulation."""
    tokens = [tok for tok in re.split(r"[,\s;]+", str(text).strip()) if tok]
    expected = int(n_categories) - 1
    if len(tokens) != expected:
        raise ValueError(
            f"Expected {expected} thresholds for {n_categories} score categories; "
            f"got {len(tokens)}."
        )
    try:
        values = np.asarray([float(tok) for tok in tokens], dtype=float)
    except ValueError as exc:
        raise ValueError("Thresholds must be numeric values.") from exc
    if not np.all(np.isfinite(values)):
        raise ValueError("Thresholds must be finite numeric values.")
    return values


def default_custom_simulation_facet_names(n_facets: int) -> list[str]:
    """Return readable default facet names for synthetic MFRM designs."""
    base = ["Rater", "Task", "Criterion"]
    n_facets = max(1, int(n_facets))
    return base[:n_facets] + [f"Facet{idx}" for idx in range(4, n_facets + 1)]


def sanitize_custom_simulation_facet_names(names: Iterable[str]) -> list[str]:
    """Make generated facet column names unique and estimator-safe."""
    out: list[str] = []
    seen: set[str] = {"Person", "Score", "Weight"}
    for idx, raw in enumerate(names, start=1):
        name = re.sub(r"\s+", "_", str(raw).strip()) or f"Facet{idx}"
        name = re.sub(r"[^0-9A-Za-z_]+", "_", name).strip("_") or f"Facet{idx}"
        if name[0].isdigit():
            name = f"Facet_{name}"
        if name in {"Person", "Score", "Weight"}:
            name = f"{name}_Facet"
        candidate = name
        suffix = 2
        while candidate in seen:
            candidate = f"{name}_{suffix}"
            suffix += 1
        seen.add(candidate)
        out.append(candidate)
    return out


def _custom_simulation_level_labels(facet_name: str, n_levels: int) -> list[str]:
    """Create compact level labels without assuming a specific facet role."""
    letters = "".join(ch for ch in facet_name.upper() if ch.isalpha())
    if facet_name.lower() == "rater":
        prefix = "R"
    elif facet_name.lower() == "task":
        prefix = "T"
    elif facet_name.lower() in {"criterion", "criteria"}:
        prefix = "C"
    else:
        prefix = (letters[:2] or "F")
    return [f"{prefix}{idx:02d}" for idx in range(1, int(n_levels) + 1)]


def _coerce_custom_simulation_facets(
    *,
    facet_names: Iterable[str] | None,
    facet_level_counts: Iterable[int] | None,
    facet_sds: Iterable[float] | None,
    n_rater: int,
    n_task: int,
    n_criterion: int,
    rater_sd: float,
    task_sd: float,
    criterion_sd: float,
) -> tuple[list[str], list[int], list[float]]:
    """Resolve old 3-facet args and new arbitrary-facet args to one spec."""
    facet_level_counts_list = list(facet_level_counts) if facet_level_counts is not None else None
    facet_sds_list = list(facet_sds) if facet_sds is not None else None
    if facet_names is None and facet_level_counts is None:
        names = ["Rater", "Task", "Criterion"]
        counts = [int(n_rater), int(n_task), int(n_criterion)]
        sds = [float(rater_sd), float(task_sd), float(criterion_sd)]
    else:
        if facet_names is None:
            count_len = len(facet_level_counts_list) if facet_level_counts_list is not None else 3
            raw_names = default_custom_simulation_facet_names(count_len)
        else:
            raw_names = list(facet_names)
        names = sanitize_custom_simulation_facet_names(raw_names)
        if facet_level_counts_list is None:
            default_counts = ([4, 2, 4] + [2] * max(0, len(names) - 3))[:len(names)]
            counts = default_counts
        else:
            counts = [int(x) for x in facet_level_counts_list]
        if facet_sds_list is None:
            default_sds = ([0.35, 0.25, 0.25] + [0.20] * max(0, len(names) - 3))[:len(names)]
            sds = default_sds
        else:
            sds = [float(x) for x in facet_sds_list]

    if len(names) < 1:
        raise ValueError("At least one facet is required.")
    if len(counts) != len(names):
        raise ValueError("facet_level_counts must have one value per facet.")
    if len(sds) != len(names):
        raise ValueError("facet_sds must have one value per facet.")
    if any(int(c) < 1 for c in counts):
        raise ValueError("All facet level counts must be positive integers.")
    if any((not np.isfinite(float(sd))) or float(sd) < 0 for sd in sds):
        raise ValueError("All facet SDs must be finite non-negative values.")
    return names, [int(c) for c in counts], [float(sd) for sd in sds]


def generate_custom_mfrm_simulation_bundle(
    *,
    n_person: int = 50,
    facet_names: Iterable[str] | None = None,
    facet_level_counts: Iterable[int] | None = None,
    facet_sds: Iterable[float] | None = None,
    first_facet_levels_per_person: int | None = None,
    n_rater: int = 4,
    n_task: int = 2,
    n_criterion: int = 4,
    raters_per_person: int | None = None,
    n_categories: int = 5,
    theta_sd: float = 1.0,
    rater_sd: float = 0.35,
    task_sd: float = 0.25,
    criterion_sd: float = 0.25,
    thresholds: Iterable[float] | None = None,
    step_span: float = 2.0,
    noise_sd: float = 0.0,
    missing_rate: float = 0.0,
    zero_count_score: int | None = None,
    seed: int = 20260515,
) -> dict:
    """Generate synthetic long-format MFRM data plus preview truth tables.

    The generator uses the same adjacent-category RSM-family probability
    contract as the built-in sample scenarios.  It supports both the earlier
    Rater/Task/Criterion call signature and an arbitrary number of named
    facets for manuscript-ready synthetic examples.
    """
    n_person = int(n_person)
    n_categories = int(n_categories)
    if n_person < 1:
        raise ValueError("n_person must be a positive integer.")
    if n_categories < 2:
        raise ValueError("n_categories must be at least 2.")
    facet_names, facet_level_counts, facet_sds = _coerce_custom_simulation_facets(
        facet_names=facet_names,
        facet_level_counts=facet_level_counts,
        facet_sds=facet_sds,
        n_rater=int(n_rater),
        n_task=int(n_task),
        n_criterion=int(n_criterion),
        rater_sd=float(rater_sd),
        task_sd=float(task_sd),
        criterion_sd=float(criterion_sd),
    )

    if first_facet_levels_per_person is None:
        first_facet_levels_per_person = raters_per_person
    if first_facet_levels_per_person is None:
        first_facet_levels_per_person = facet_level_counts[0]
    first_facet_levels_per_person = max(
        1,
        min(int(first_facet_levels_per_person), int(facet_level_counts[0])),
    )
    missing_rate = min(max(float(missing_rate), 0.0), 0.95)
    noise_sd = max(float(noise_sd), 0.0)
    tail_rows = int(np.prod(facet_level_counts[1:], dtype=np.int64)) if len(facet_level_counts) > 1 else 1
    full_rows = int(n_person * first_facet_levels_per_person * tail_rows)
    if full_rows > 100_000:
        raise ValueError(
            "Custom simulation is capped at 100,000 rows before missingness "
            "for hosted-app responsiveness."
        )

    if thresholds is None:
        tau = default_custom_simulation_thresholds(n_categories, step_span=step_span)
    else:
        tau = np.asarray(list(thresholds), dtype=float)
    if tau.size != n_categories - 1:
        raise ValueError("thresholds must have length n_categories - 1.")
    if not np.all(np.isfinite(tau)):
        raise ValueError("thresholds must contain finite numeric values.")
    if zero_count_score is not None:
        zero_count_score = int(zero_count_score)
        if zero_count_score < 0 or zero_count_score >= n_categories:
            raise ValueError("zero_count_score must be inside the generated score range.")

    rng = np.random.default_rng(int(seed))
    persons = [f"P{idx:03d}" for idx in range(1, n_person + 1)]
    facet_levels = [
        _custom_simulation_level_labels(name, n_levels)
        for name, n_levels in zip(facet_names, facet_level_counts)
    ]

    theta = rng.normal(0.0, float(theta_sd), n_person)
    theta = theta - float(np.mean(theta))
    facet_effects: list[np.ndarray] = []
    for n_levels, sd in zip(facet_level_counts, facet_sds):
        effects = rng.normal(0.0, float(sd), int(n_levels))
        effects = effects - float(np.mean(effects))
        facet_effects.append(effects)

    cum_thresholds = np.zeros(n_categories, dtype=float)
    for k in range(1, n_categories):
        cum_thresholds[k] = cum_thresholds[k - 1] + tau[k - 1]
    category_scores = np.arange(n_categories, dtype=int)

    rows: list[list[object]] = []
    tail_index_sets = [range(n) for n in facet_level_counts[1:]]
    tail_combos = list(product(*tail_index_sets)) if tail_index_sets else [()]
    for pi, person in enumerate(persons):
        if first_facet_levels_per_person >= facet_level_counts[0]:
            first_indices = range(facet_level_counts[0])
        else:
            first_indices = [((pi + offset) % facet_level_counts[0]) for offset in range(first_facet_levels_per_person)]
        for first_idx in first_indices:
            for tail in tail_combos:
                facet_indices = (int(first_idx),) + tuple(int(x) for x in tail)
                eta = theta[pi] - sum(
                    float(effects[level_idx])
                    for effects, level_idx in zip(facet_effects, facet_indices)
                )
                if noise_sd > 0:
                    eta += float(rng.normal(0.0, noise_sd))
                log_num = category_scores.astype(float) * eta - cum_thresholds
                log_num -= float(np.max(log_num))
                probs = np.exp(log_num)
                probs = probs / probs.sum()
                score = int(rng.choice(category_scores, p=probs))
                rows.append(
                    [person]
                    + [facet_levels[j][idx] for j, idx in enumerate(facet_indices)]
                    + [score]
                )

    df = pd.DataFrame(rows, columns=["Person", *facet_names, "Score"])
    if zero_count_score is not None and not df.empty:
        mask = df["Score"].astype(int) == int(zero_count_score)
        if mask.any():
            if int(zero_count_score) <= 0:
                replacement = np.full(int(mask.sum()), 1, dtype=int)
            elif int(zero_count_score) >= n_categories - 1:
                replacement = np.full(int(mask.sum()), n_categories - 2, dtype=int)
            else:
                replacement = np.where(
                    rng.random(int(mask.sum())) < 0.5,
                    int(zero_count_score) - 1,
                    int(zero_count_score) + 1,
                )
            df.loc[mask, "Score"] = replacement.astype(int)
    if missing_rate > 0 and not df.empty:
        keep = rng.random(len(df)) >= missing_rate
        df = df.loc[keep].reset_index(drop=True)

    person_truth = pd.DataFrame({"Person": persons, "Measure": theta})
    facet_truth_parts = []
    for name, levels, effects in zip(facet_names, facet_levels, facet_effects):
        facet_truth_parts.append(pd.DataFrame({
            "Facet": name,
            "Level": levels,
            "Measure": effects,
        }))
    facet_truth = pd.concat(facet_truth_parts, ignore_index=True) if facet_truth_parts else pd.DataFrame()
    threshold_truth = pd.DataFrame({
        "Step": [f"tau{k}" for k in range(1, n_categories)],
        "Threshold": tau,
        "CumulativeThreshold": cum_thresholds[1:],
    })
    category_counts = (
        df["Score"].value_counts(dropna=False)
        .reindex(range(n_categories), fill_value=0)
        .rename_axis("Score")
        .reset_index(name="Count")
    )
    category_counts["Percent"] = (
        category_counts["Count"] / max(int(category_counts["Count"].sum()), 1)
    )
    bundle = {
        "data": df,
        "person_truth": person_truth,
        "facet_truth": facet_truth,
        "threshold_truth": threshold_truth,
        "category_counts": category_counts,
        "meta": {
            "n_person": n_person,
            "facet_names": facet_names,
            "facet_level_counts": facet_level_counts,
            "facet_sds": facet_sds,
            "first_facet_levels_per_person": first_facet_levels_per_person,
            "n_categories": n_categories,
            "theta_sd": float(theta_sd),
            "thresholds": [float(x) for x in tau],
            "step_span": float(step_span),
            "noise_sd": noise_sd,
            "n_obs": int(len(df)),
            "full_rows": full_rows,
            "missing_rate": missing_rate,
            "zero_count_score": zero_count_score,
            "seed": int(seed),
        },
    }
    sparse_audit = build_custom_simulation_sparse_design_audit(bundle)
    sparse_pair_cells = build_custom_simulation_sparse_pair_cells(bundle)
    bundle["sparse_design_audit"] = sparse_audit
    bundle["sparse_pair_cells"] = sparse_pair_cells
    return bundle


def build_custom_simulation_sparse_pair_cells(
    bundle: dict,
    *,
    min_cell_count: int = 5,
) -> pd.DataFrame:
    """Summarize observed density for every simulated facet-pair cell."""
    if not isinstance(bundle, dict):
        return pd.DataFrame()
    data = bundle.get("data")
    meta = bundle.get("meta", {})
    if not isinstance(data, pd.DataFrame) or data.empty or not isinstance(meta, dict):
        return pd.DataFrame()
    facet_names = [str(x) for x in meta.get("facet_names", []) if str(x) in data.columns]
    if len(facet_names) < 2:
        return pd.DataFrame()
    expected_counts = {
        str(name): int(count)
        for name, count in zip(meta.get("facet_names", []), meta.get("facet_level_counts", []))
    }
    rows: list[dict[str, object]] = []
    for facet_a, facet_b in combinations(facet_names, 2):
        observed = (
            data.groupby([facet_a, facet_b], dropna=False)
            .size()
            .reset_index(name="Count")
        )
        possible_cells = int(
            max(expected_counts.get(facet_a, data[facet_a].nunique(dropna=True)), 0)
            * max(expected_counts.get(facet_b, data[facet_b].nunique(dropna=True)), 0)
        )
        observed_cells = int(len(observed))
        zero_cells = max(possible_cells - observed_cells, 0)
        low_cells = int((observed["Count"] < int(min_cell_count)).sum()) if not observed.empty else 0
        min_count = int(observed["Count"].min()) if not observed.empty else 0
        median_count = float(observed["Count"].median()) if not observed.empty else 0.0
        density = observed_cells / max(possible_cells, 1)
        if zero_cells > 0 or low_cells > 0:
            status = "Review"
            action = "Inspect sparse cells before making bias/local-interaction or subgroup-comparison claims."
        else:
            status = "Ready"
            action = "Cell density meets the current simulation screening rule."
        rows.append({
            "FacetPair": f"{facet_a} x {facet_b}",
            "FacetA": facet_a,
            "FacetB": facet_b,
            "Status": status,
            "PossibleCells": possible_cells,
            "ObservedCells": observed_cells,
            "ZeroCells": zero_cells,
            "LowCountCells": low_cells,
            "MinCellCount": min_count,
            "MedianCellCount": median_count,
            "CellDensity": density,
            "ScreeningRule": f"Review if any possible cell is empty or any observed cell has < {int(min_cell_count)} observations.",
            "Action": action,
        })
    return pd.DataFrame(rows)


def build_custom_simulation_sparse_design_audit(
    bundle: dict,
    *,
    min_category_count: int = 10,
    min_level_count: int = 10,
    min_person_rows: int = 2,
    min_pair_cell_count: int = 5,
) -> pd.DataFrame:
    """Pre-fit sparse-design audit for generated synthetic MFRM data."""
    if not isinstance(bundle, dict):
        return pd.DataFrame()
    data = bundle.get("data")
    meta = bundle.get("meta", {})
    category_counts = bundle.get("category_counts")
    if not isinstance(data, pd.DataFrame) or not isinstance(meta, dict):
        return pd.DataFrame()
    facet_names = [str(x) for x in meta.get("facet_names", []) if str(x) in data.columns]
    n_obs = int(len(data))
    full_rows = int(meta.get("full_rows", n_obs) or n_obs)
    actual_missing_rate = 1.0 - (n_obs / max(full_rows, 1))
    rows: list[dict[str, object]] = []

    def add_row(
        check: str,
        status: str,
        value: object,
        threshold: str,
        evidence: str,
        action: str,
    ) -> None:
        rows.append({
            "Priority": len(rows) + 1,
            "Check": str(check),
            "Status": str(status),
            "Value": str(value),
            "Threshold": str(threshold),
            "Evidence": str(evidence),
            "Action": str(action),
            "DownloadFile": "mfrm_custom_simulation.csv; custom_simulation_sparse_design_audit.csv",
        })

    if isinstance(category_counts, pd.DataFrame) and not category_counts.empty:
        counts = pd.to_numeric(category_counts.get("Count", pd.Series(dtype=float)), errors="coerce").fillna(0)
        zero_scores = category_counts.loc[counts.eq(0), "Score"].astype(str).tolist() if "Score" in category_counts.columns else []
        sparse_scores = category_counts.loc[(counts.gt(0)) & (counts.lt(min_category_count)), "Score"].astype(str).tolist() if "Score" in category_counts.columns else []
        if zero_scores:
            status = "Hold before reporting"
            action = "Keep the explicit score range if fitting this simulation and treat unused categories as a planned stress case."
        elif sparse_scores:
            status = "Review"
            action = "Inspect category curves and category-collapse sensitivity before reporting threshold or category-functioning claims."
        else:
            status = "Ready"
            action = "Category counts meet the current screening rule."
        add_row(
            "Score category support",
            status,
            f"min={int(counts.min()) if len(counts) else 0}; zero={', '.join(zero_scores) or 'none'}; sparse={', '.join(sparse_scores) or 'none'}",
            f"Each category >= {int(min_category_count)} observations; zero-count categories are a stress case.",
            "category_counts; generated score support",
            action,
        )
    else:
        add_row(
            "Score category support",
            "Review",
            "category counts unavailable",
            f"Each category >= {int(min_category_count)} observations.",
            "category_counts missing",
            "Regenerate the simulation bundle before interpreting score-category behavior.",
        )

    missing_status = "Review" if actual_missing_rate >= 0.20 else "Ready"
    add_row(
        "Generated missingness",
        missing_status,
        f"{actual_missing_rate:.1%} removed; {n_obs:,}/{full_rows:,} rows retained",
        "Review planned missingness >= 20%.",
        f"meta.missing_rate={float(meta.get('missing_rate', 0.0) or 0.0):.1%}",
        "Use planned missingness as a sensitivity condition, not as evidence that the observed study design is adequate.",
    )

    if "Person" in data.columns and not data.empty:
        person_rows = data.groupby("Person", dropna=False).size()
        low_persons = int((person_rows < int(min_person_rows)).sum())
        add_row(
            "Person row support",
            "Review" if low_persons else "Ready",
            f"min={int(person_rows.min())}; median={float(person_rows.median()):.1f}; low_persons={low_persons}",
            f"Each generated person should have >= {int(min_person_rows)} retained observations.",
            "Person x retained row counts",
            "Increase persons, reduce missingness, or increase first-facet coverage if many persons have minimal retained data.",
        )

    expected_counts = {
        str(name): int(count)
        for name, count in zip(meta.get("facet_names", []), meta.get("facet_level_counts", []))
    }
    for facet in facet_names:
        counts = data[facet].value_counts(dropna=False)
        expected_levels = int(expected_counts.get(facet, len(counts)))
        observed_levels = int(data[facet].nunique(dropna=True))
        zero_levels = max(expected_levels - observed_levels, 0)
        sparse_levels = int((counts < int(min_level_count)).sum())
        status = "Hold before reporting" if zero_levels else "Review" if sparse_levels else "Ready"
        add_row(
            f"{facet} level support",
            status,
            f"observed={observed_levels}/{expected_levels}; zero_levels={zero_levels}; sparse_levels={sparse_levels}; min={int(counts.min()) if len(counts) else 0}",
            f"All generated levels observed; each retained level >= {int(min_level_count)} rows.",
            f"{facet} marginal counts",
            "Do not interpret facet-element measures as stable when levels are absent or retained rows are very sparse.",
        )

    pair_cells = build_custom_simulation_sparse_pair_cells(
        bundle,
        min_cell_count=min_pair_cell_count,
    )
    if isinstance(pair_cells, pd.DataFrame) and not pair_cells.empty:
        zero_pairs = int((pair_cells["ZeroCells"] > 0).sum())
        low_pairs = int((pair_cells["LowCountCells"] > 0).sum())
        worst_min = int(pair_cells["MinCellCount"].min())
        pair_status = "Review" if (zero_pairs or low_pairs) else "Ready"
        add_row(
            "Facet-pair cell density",
            pair_status,
            f"pairs={len(pair_cells)}; pairs_with_zero_cells={zero_pairs}; pairs_with_low_cells={low_pairs}; worst_min={worst_min}",
            f"No possible pair cells empty; observed pair cells >= {int(min_pair_cell_count)} observations.",
            "custom_simulation_sparse_pair_cells.csv",
            "Use this before interpreting bias/local interaction, subgroup comparisons, or sparse-cell warnings.",
        )

    out = pd.DataFrame(rows)
    if not out.empty:
        rank = {"Hold before reporting": 0, "Review": 1, "Ready": 2}
        out["_Rank"] = out["Status"].map(rank).fillna(1)
        out = out.sort_values(["_Rank", "Priority"]).drop(columns=["_Rank"]).reset_index(drop=True)
        out["Priority"] = np.arange(1, len(out) + 1, dtype=int)
    return out


def build_custom_simulation_sparse_reporting_context(
    bundle: dict | None = None,
    *,
    sparse_audit: pd.DataFrame | None = None,
    sparse_pair_cells: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """Translate custom-simulation sparse checks into manuscript-use guidance."""
    if isinstance(bundle, dict):
        if sparse_audit is None:
            sparse_audit = bundle.get("sparse_design_audit")
        if sparse_pair_cells is None:
            sparse_pair_cells = bundle.get("sparse_pair_cells")
    if not isinstance(sparse_audit, pd.DataFrame) or sparse_audit.empty:
        return pd.DataFrame()

    status_order = {"Hold before reporting": 0, "Review": 1, "Ready": 2}
    audit = sparse_audit.copy()
    audit["_StatusRank"] = audit.get("Status", pd.Series("Review", index=audit.index)).astype(str).map(status_order).fillna(1)
    worst_status = str(audit.sort_values("_StatusRank").iloc[0].get("Status", "Review"))
    if worst_status == "Hold before reporting":
        overall_report_status = "Do not report yet"
        overall_action = (
            "Use the generated data as a documented stress case or revise the simulation design "
            "before treating estimates as report-style evidence."
        )
        overall_caveat = (
            "The generated design contains at least one sparse-design condition that blocks "
            "straight report-style interpretation."
        )
        overall_do_not = "Do not present the simulation as a stable empirical scoring result without naming the sparse-design condition."
    elif worst_status == "Review":
        overall_report_status = "Needs caveat"
        overall_action = "Keep sparse-design caveats visible and inspect the detailed audit before writing Results prose."
        overall_caveat = "Some generated cells or categories need review before using the run as report-ready evidence."
        overall_do_not = "Do not make bias, local-interaction, category, or subgroup claims from sparse cells without caveats."
    else:
        overall_report_status = "Ready"
        overall_action = "Use the generated design as a rehearsal case, while still verifying fitted diagnostics."
        overall_caveat = "The sparse-design screening rules did not identify a generated-design blocker."
        overall_do_not = "Do not treat a simulation audit as validation of an external scoring program."

    pair_summary = "facet-pair table unavailable"
    if isinstance(sparse_pair_cells, pd.DataFrame) and not sparse_pair_cells.empty:
        zero_pairs = int((pd.to_numeric(sparse_pair_cells.get("ZeroCells", 0), errors="coerce").fillna(0) > 0).sum())
        low_pairs = int((pd.to_numeric(sparse_pair_cells.get("LowCountCells", 0), errors="coerce").fillna(0) > 0).sum())
        pair_summary = f"{len(sparse_pair_cells)} pair(s); zero-cell pairs={zero_pairs}; low-cell pairs={low_pairs}"

    rows: list[dict[str, object]] = [{
        "Priority": 1,
        "SimulationCheck": "Overall generated-design use",
        "AuditStatus": worst_status,
        "ReportStatus": overall_report_status,
        "APAUse": "Write as simulation/stress-test evidence only, not as a claim about an observed scoring program.",
        "EvidenceSummary": pair_summary,
        "ActionBeforeReporting": overall_action,
        "CaveatToCarry": overall_caveat,
        "DoNotClaim": overall_do_not,
        "EvidenceFiles": "custom_simulation_settings.csv; custom_simulation_sparse_design_audit.csv; custom_simulation_sparse_pair_cells.csv; mfrm_custom_simulation.csv",
        "DownloadFile": "custom_simulation_sparse_reporting_context.csv",
    }]

    for _, row in audit.drop(columns=["_StatusRank"], errors="ignore").sort_values("Priority").iterrows():
        audit_status = str(row.get("Status", "Review"))
        if audit_status == "Hold before reporting":
            report_status = "Do not report yet"
            apa_use = "Use as a documented stress condition or revise before report-style interpretation."
            caveat = "This generated check blocks uncaveated reporting."
            do_not = "Do not omit this sparse-design condition from Results or limitations."
        elif audit_status == "Review":
            report_status = "Needs caveat"
            apa_use = "Use with a visible design caveat and a linked evidence file."
            caveat = "This generated check needs review before strong claims."
            do_not = "Do not use this check to support strong stability, category, or interaction claims by itself."
        else:
            report_status = "Ready"
            apa_use = "No sparse-design caveat is required for this generated check under the current screening rule."
            caveat = "No additional caveat from this check."
            do_not = "Do not generalize simulation readiness beyond the generated design."
        rows.append({
            "Priority": len(rows) + 1,
            "SimulationCheck": row.get("Check", "Sparse-design check"),
            "AuditStatus": audit_status,
            "ReportStatus": report_status,
            "APAUse": apa_use,
            "EvidenceSummary": f"{row.get('Value', '')}; threshold: {row.get('Threshold', '')}",
            "ActionBeforeReporting": row.get("Action", "Open the sparse-design audit before reporting."),
            "CaveatToCarry": caveat,
            "DoNotClaim": do_not,
            "EvidenceFiles": row.get("Evidence", "custom_simulation_sparse_design_audit.csv"),
            "DownloadFile": row.get("DownloadFile", "custom_simulation_sparse_design_audit.csv"),
        })
    return pd.DataFrame(rows)


def build_custom_simulation_settings_table(
    bundle: dict | None = None,
    *,
    ui_meta: dict | None = None,
) -> pd.DataFrame:
    """Export the custom synthetic-data settings used for a generated run."""
    if not isinstance(bundle, dict):
        return pd.DataFrame()
    meta = bundle.get("meta", {})
    if not isinstance(meta, dict) or not meta:
        return pd.DataFrame()
    ui_meta = ui_meta if isinstance(ui_meta, dict) else {}
    threshold_truth = bundle.get("threshold_truth")
    thresholds = meta.get("thresholds", [])
    if (not thresholds) and isinstance(threshold_truth, pd.DataFrame) and "Threshold" in threshold_truth.columns:
        thresholds = pd.to_numeric(threshold_truth["Threshold"], errors="coerce").dropna().astype(float).tolist()

    facet_names = [str(x) for x in meta.get("facet_names", [])]
    facet_counts = [int(x) for x in meta.get("facet_level_counts", [])]
    facet_sds = [float(x) for x in meta.get("facet_sds", [])]

    rows: list[dict[str, object]] = []

    def add_row(section: str, setting: str, value: object, source: str, report_note: str) -> None:
        rows.append({
            "Section": str(section),
            "Setting": str(setting),
            "Value": "" if value is None else str(value),
            "Source": str(source),
            "ReportNote": str(report_note),
            "EvidenceFile": "custom_simulation_settings.csv",
        })

    preset_key = str(ui_meta.get("design_preset", "") or ui_meta.get("preset", "") or "")
    if preset_key:
        add_row(
            "Preset",
            "Simulation preset",
            preset_key,
            "sidebar session state",
            "Preset is a starting point; manuscript wording should report the realized settings below.",
        )
    add_row("Design", "Persons", meta.get("n_person"), "bundle meta", "Number of generated persons.")
    add_row("Design", "Facets", ", ".join(facet_names), "bundle meta", "Generated facet columns.")
    add_row("Design", "Facet level counts", ", ".join(f"{name}={count}" for name, count in zip(facet_names, facet_counts)), "bundle meta", "Generated levels per facet.")
    add_row("Design", "Facet SDs", ", ".join(f"{name}={sd:g}" for name, sd in zip(facet_names, facet_sds)), "bundle meta", "Standard deviations used for generated facet effects.")
    add_row("Design", "First-facet levels per person", meta.get("first_facet_levels_per_person"), "bundle meta", "Coverage of the first facet for each person.")
    add_row("Scoring", "Score categories", meta.get("n_categories"), "bundle meta", "Number of generated score categories.")
    add_row("Scoring", "Zero-count score requested", meta.get("zero_count_score"), "bundle meta", "Intentional unused category, if any.")
    add_row("Latent generation", "Person theta SD", meta.get("theta_sd"), "bundle meta", "Standard deviation used for generated person locations before centering.")
    add_row("Latent generation", "Noise SD", meta.get("noise_sd"), "bundle meta", "Optional random noise added to the generated response location.")
    add_row("Thresholds", "Threshold mode", ui_meta.get("threshold_mode", "custom/even not recorded"), "sidebar session state", "How threshold controls were set in the UI, when available.")
    add_row("Thresholds", "Step span", meta.get("step_span"), "bundle meta", "Even-threshold span used when thresholds were generated by the preset/even mode.")
    add_row("Thresholds", "Adjacent thresholds", ", ".join(f"{float(x):.6g}" for x in thresholds), "threshold truth", "Adjacent-category thresholds used by the synthetic generator.")
    add_row("Missingness", "Requested missing rate", meta.get("missing_rate"), "bundle meta", "Planned row removal rate for generated rating events.")
    add_row("Missingness", "Full rows before missingness", meta.get("full_rows"), "bundle meta", "Generated row count before planned row removal.")
    add_row("Missingness", "Retained rows", meta.get("n_obs"), "bundle meta", "Generated row count after planned row removal.")
    add_row("Reproducibility", "Seed", meta.get("seed"), "bundle meta", "Random seed for regenerating this synthetic data.")
    out = pd.DataFrame(rows)
    if not out.empty:
        out.insert(0, "Priority", np.arange(1, len(out) + 1, dtype=int))
    return out


def current_custom_simulation_sparse_export_frames() -> dict[str, pd.DataFrame]:
    """Return sparse-design export frames for the currently loaded custom simulation."""
    bundle = st.session_state.get("_custom_simulation_preview_bundle", {})
    if not isinstance(bundle, dict):
        return {}
    ui_meta = st.session_state.get("_loaded_custom_simulation_meta", {})
    settings = build_custom_simulation_settings_table(
        bundle,
        ui_meta=ui_meta if isinstance(ui_meta, dict) else None,
    )
    sparse_audit = bundle.get("sparse_design_audit")
    sparse_pair_cells = bundle.get("sparse_pair_cells")
    frames: dict[str, pd.DataFrame] = {}
    _frame_bundle.add_frames(frames, (
        ("custom_simulation_settings", settings),
        ("custom_simulation_sparse_design_audit", sparse_audit),
        ("custom_simulation_sparse_pair_cells", sparse_pair_cells),
    ))
    sparse_context = build_custom_simulation_sparse_reporting_context(
        bundle,
        sparse_audit=sparse_audit if isinstance(sparse_audit, pd.DataFrame) else None,
        sparse_pair_cells=sparse_pair_cells if isinstance(sparse_pair_cells, pd.DataFrame) else None,
    )
    _frame_bundle.add_frame(frames, "custom_simulation_sparse_reporting_context", sparse_context)
    return frames


def generate_custom_mfrm_simulation_data(
    **kwargs,
) -> pd.DataFrame:
    """Generate user-configurable synthetic long-format MFRM data."""
    return generate_custom_mfrm_simulation_bundle(**kwargs)["data"].copy()


@st.cache_data(show_spinner=False, max_entries=16)
def cached_custom_mfrm_simulation_bundle(
    n_person: int,
    facet_names_tuple: tuple[str, ...],
    facet_level_counts_tuple: tuple[int, ...],
    facet_sds_tuple: tuple[float, ...],
    first_facet_levels_per_person: int,
    n_categories: int,
    theta_sd: float,
    thresholds_tuple: tuple[float, ...],
    step_span: float,
    noise_sd: float,
    missing_rate: float,
    zero_count_score: int | None,
    seed: int,
) -> dict:
    return generate_custom_mfrm_simulation_bundle(
        n_person=n_person,
        facet_names=facet_names_tuple,
        facet_level_counts=facet_level_counts_tuple,
        facet_sds=facet_sds_tuple,
        first_facet_levels_per_person=first_facet_levels_per_person,
        n_categories=n_categories,
        theta_sd=theta_sd,
        thresholds=thresholds_tuple,
        step_span=step_span,
        noise_sd=noise_sd,
        missing_rate=missing_rate,
        zero_count_score=zero_count_score,
        seed=seed,
    )


def build_custom_simulation_score_histogram_figure(bundle: dict) -> go.Figure | None:
    counts = bundle.get("category_counts")
    if not isinstance(counts, pd.DataFrame) or counts.empty:
        return None
    fig = go.Figure(go.Bar(
        x=counts["Score"].astype(str),
        y=counts["Count"],
        marker_color="#4C78A8",
        hovertemplate="Score %{x}<br>Count %{y}<extra></extra>",
    ))
    fig.update_layout(
        title="Score Category Histogram",
        xaxis_title="Score category",
        yaxis_title="Count",
        height=320,
        margin=dict(l=40, r=20, t=50, b=40),
    )
    return fig


def build_custom_simulation_wright_preview_figure(bundle: dict) -> go.Figure | None:
    person_truth = bundle.get("person_truth")
    facet_truth = bundle.get("facet_truth")
    threshold_truth = bundle.get("threshold_truth")
    if not isinstance(person_truth, pd.DataFrame) or person_truth.empty:
        return None
    fig = go.Figure()
    fig.add_trace(go.Box(
        x=person_truth["Measure"],
        y=["Persons"] * len(person_truth),
        name="Persons",
        marker_color="#4C78A8",
        boxpoints="all",
        jitter=0.35,
        pointpos=0,
        orientation="h",
        hovertemplate="Person measure %{x:.2f}<extra></extra>",
    ))
    if isinstance(facet_truth, pd.DataFrame) and not facet_truth.empty:
        for facet, part in facet_truth.groupby("Facet", sort=False):
            fig.add_trace(go.Scatter(
                x=part["Measure"],
                y=[str(facet)] * len(part),
                mode="markers",
                name=str(facet),
                marker=dict(size=8),
                text=part["Level"],
                hovertemplate="%{text}<br>Measure %{x:.2f}<extra></extra>",
            ))
    if isinstance(threshold_truth, pd.DataFrame) and not threshold_truth.empty:
        for _, row in threshold_truth.iterrows():
            fig.add_vline(
                x=float(row["Threshold"]),
                line_dash="dot",
                line_color="#666666",
                opacity=0.45,
            )
    fig.update_layout(
        title="Wright Map Preview from Generating Values",
        xaxis_title="Logit scale",
        yaxis_title="Component",
        height=360,
        margin=dict(l=40, r=20, t=50, b=40),
        showlegend=False,
    )
    return fig


def build_custom_simulation_pathway_preview_figure(bundle: dict) -> go.Figure | None:
    data = bundle.get("data")
    meta = bundle.get("meta", {})
    if not isinstance(data, pd.DataFrame) or data.empty:
        return None
    facet_names = [c for c in meta.get("facet_names", []) if c in data.columns]
    nodes = [("Persons", int(data["Person"].nunique()))]
    nodes.extend((facet, int(data[facet].nunique())) for facet in facet_names)
    nodes.append(("Scores", int(data["Score"].nunique())))
    x = list(range(len(nodes)))
    y = [0] * len(nodes)
    labels = [name for name, _ in nodes]
    counts = [count for _, count in nodes]
    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=x,
        y=y,
        mode="lines",
        line=dict(color="#8A8A8A", width=3),
        hoverinfo="skip",
        showlegend=False,
    ))
    fig.add_trace(go.Scatter(
        x=x,
        y=y,
        mode="markers+text",
        marker=dict(
            size=[max(18, min(48, 12 + count * 2)) for count in counts],
            color="#59A14F",
            line=dict(width=1, color="#2F5D35"),
        ),
        text=[f"{label}<br>{count} levels" for label, count in nodes],
        textposition="bottom center",
        hovertemplate="%{text}<extra></extra>",
        showlegend=False,
    ))
    fig.update_layout(
        title="Pathway Preview of Generated Design",
        xaxis=dict(visible=False, range=[-0.5, len(nodes) - 0.5]),
        yaxis=dict(visible=False, range=[-1, 1]),
        height=260,
        margin=dict(l=20, r=20, t=50, b=80),
    )
    return fig


def render_custom_simulation_preview_panel() -> None:
    bundle = st.session_state.get("_custom_simulation_preview_bundle")
    if not isinstance(bundle, dict):
        return
    st.markdown(f"##### {t('data_source.sim_preview_header')}")
    st.caption(t("data_source.sim_preview_caption"))
    tab_hist, tab_wright, tab_pathway, tab_sparse = st.tabs([
        t("data_source.sim_preview_tab_histogram"),
        t("data_source.sim_preview_tab_wright"),
        t("data_source.sim_preview_tab_pathway"),
        t("data_source.sim_preview_tab_sparse"),
    ])
    with tab_hist:
        fig = build_custom_simulation_score_histogram_figure(bundle)
        if fig is not None:
            st.plotly_chart(fig, width="stretch")
    with tab_wright:
        fig = build_custom_simulation_wright_preview_figure(bundle)
        if fig is not None:
            st.plotly_chart(fig, width="stretch")
    with tab_pathway:
        fig = build_custom_simulation_pathway_preview_figure(bundle)
        if fig is not None:
            st.plotly_chart(fig, width="stretch")
    with tab_sparse:
        sparse_audit = bundle.get("sparse_design_audit", pd.DataFrame())
        sparse_pair_cells = bundle.get("sparse_pair_cells", pd.DataFrame())
        st.caption(t("data_source.sim_sparse_caption"))
        if isinstance(sparse_audit, pd.DataFrame) and not sparse_audit.empty:
            status_values = sparse_audit.get("Status", pd.Series(dtype=object)).astype(str).tolist()
            if "Hold before reporting" in status_values:
                st.warning(t("data_source.sim_sparse_hold_warning"))
            elif "Review" in status_values:
                st.info(t("data_source.sim_sparse_review_info"))
            else:
                st.success(t("data_source.sim_sparse_ready_success"))
            _render_compact_dataframe(
                sparse_audit,
                ["Priority", "Check", "Status", "Value", "Action"],
                details_label=t("data_source.sim_sparse_details_label"),
                hide_index=True,
                wrap_text=True,
            )
            st.download_button(
                t("data_source.sim_sparse_audit_download_button"),
                data=to_csv_bytes(sparse_audit),
                file_name="custom_simulation_sparse_design_audit.csv",
                mime="text/csv",
                key="custom_simulation_sparse_design_audit_download",
                use_container_width=True,
            )
        if isinstance(sparse_pair_cells, pd.DataFrame) and not sparse_pair_cells.empty:
            with st.expander(t("data_source.sim_sparse_pair_expander"), expanded=False):
                _render_compact_dataframe(
                    sparse_pair_cells,
                    ["FacetPair", "Status", "PossibleCells", "ObservedCells", "ZeroCells", "LowCountCells", "MinCellCount"],
                    details_label=t("data_source.sim_sparse_pair_details_label"),
                    hide_index=True,
                    wrap_text=True,
                )
                st.download_button(
                    t("data_source.sim_sparse_pair_download_button"),
                    data=to_csv_bytes(sparse_pair_cells),
                    file_name="custom_simulation_sparse_pair_cells.csv",
                    mime="text/csv",
                    key="custom_simulation_sparse_pair_cells_download",
                    use_container_width=True,
                )


def render_loaded_data_banner() -> None:
    """Show a one-line banner in the main area naming the loaded scenario.

    The banner is only rendered when a built-in scenario is loaded
    (marked by `_loaded_sample_scenario_key` in session state). When
    the user switches to Paste or Upload, the sidebar clears the
    marker and this helper no-ops — we do not want to imply that a
    user-provided file came from the literature.

    Design: st.info-colored callout with the scenario label and obs
    count. Scenario switching remains available from the Data source
    radio in the sidebar.
    """
    custom_meta = st.session_state.get("_loaded_custom_simulation_meta")
    if isinstance(custom_meta, dict):
        facet_bits = [
            f"{name}={count}"
            for name, count in zip(
                custom_meta.get("facet_names", []),
                custom_meta.get("facet_level_counts", []),
            )
        ]
        st.info(
            "**Generated synthetic data:** "
            f"{custom_meta.get('n_person', '?')} persons × "
            f"{custom_meta.get('first_facet_levels_per_person', '?')} levels/person for "
            f"{(custom_meta.get('facet_names') or ['first facet'])[0]} × "
            f"{', '.join(facet_bits) or 'facets'} = "
            f"**{custom_meta.get('n_obs', 0):,} observations**, "
            f"{custom_meta.get('n_categories', '?')} score categories, "
            f"seed `{custom_meta.get('seed', '?')}`."
        )
        return

    key = st.session_state.get("_loaded_sample_scenario_key")
    if not key:
        return
    scenario = SAMPLE_DATA_SCENARIOS.get(key)
    if not scenario:
        return
    dims = scenario["dimensions"]
    st.info(
        f"**Loaded sample data:** {scenario['label']} — "
        f"{dims['persons']} × {dims['raters']} × {dims['tasks']} × "
        f"{dims['criteria']} = **{scenario['n_obs']:,} observations**, "
        f"{dims['n_cat']}-point scale. "
        f"Switch scenario from the **Data source** radio in the sidebar."
    )


def render_input_overview(data: pd.DataFrame) -> None:
    """Render a compact raw-table overview before column mapping."""
    if not isinstance(data, pd.DataFrame) or data.empty:
        return
    n_rows, n_cols = data.shape
    n_cells = int(n_rows * n_cols)
    n_missing = int(data.isna().sum().sum()) if n_cells else 0
    missing_pct = (100.0 * n_missing / n_cells) if n_cells else 0.0
    preview_rows = min(20, n_rows)
    metric_cols = st.columns(4)
    metric_cols[0].metric("Rows", f"{n_rows:,}")
    metric_cols[1].metric("Columns", f"{n_cols:,}")
    metric_cols[2].metric("Missing cells", f"{missing_pct:.1f}%")
    metric_cols[3].metric("Previewed", f"{preview_rows:,}")
    if n_missing:
        st.caption(
            f"{n_missing:,} blank cell(s) are present in the raw table. "
            "After column mapping, the readiness panel and Data tab show which "
            "score rows are excluded from likelihood calculations."
        )
    else:
        st.caption("No blank cells were detected in the raw table preview.")


def _short_value_list(values: list[str] | tuple[str, ...], max_items: int = 4) -> str:
    labels = [str(v) for v in values]
    if not labels:
        return "(none selected)"
    if len(labels) <= max_items:
        return ", ".join(labels)
    return f"{', '.join(labels[:max_items])}, +{len(labels) - max_items} more"


def render_sidebar_run_setup_summary(
    data: pd.DataFrame,
    *,
    person_col: str,
    score_col: str,
    facet_cols: list[str],
    weight_col: str | None,
    model_type: str,
    est_method: str,
    analysis_depth: str,
    workflow_mode: str,
) -> None:
    """Show the current estimation setup close to the Run button."""
    st.sidebar.subheader(t("sidebar_run_setup.subheader"))
    try:
        n_rows = int(len(data))
        n_persons = int(data[person_col].nunique(dropna=True))
        n_score_missing = int(data[score_col].isna().sum())
    except Exception:  # pragma: no cover - summary must not block analysis
        n_rows = 0
        n_persons = 0
        n_score_missing = 0

    if len(facet_cols) < 2:
        st.sidebar.warning(t("sidebar_run_setup.needs_two_facets_warning"))
    else:
        st.sidebar.info(
            t(
                "sidebar_run_setup.selection_info_template",
                n_rows=f"{n_rows:,}",
                n_persons=f"{n_persons:,}",
                n_facets=len(facet_cols),
            )
        )

    with st.sidebar.expander(t("sidebar_run_setup.review_setup_expander"), expanded=False):
        weight_display = weight_col or t("sidebar_run_setup.weight_none_value")
        st.markdown(
            "\n".join([
                f"- {t('sidebar_run_setup.person_label')}: `{person_col}`",
                f"- {t('sidebar_run_setup.score_label')}: `{score_col}`",
                f"- {t('sidebar_run_setup.facets_label')}: `{_short_value_list(list(facet_cols))}`",
                f"- {t('sidebar_run_setup.weight_label')}: `{weight_display}`",
                f"- {t('sidebar_run_setup.model_method_label')}: `{model_type}` / `{est_method}`",
                f"- {t('sidebar_run_setup.workflow_depth_label')}: `{workflow_mode}` / `{analysis_depth}`",
            ])
        )
        if n_score_missing:
            st.caption(
                t(
                    "sidebar_run_setup.score_missing_caption_template",
                    n_score_missing=f"{n_score_missing:,}",
                )
            )


def guess_col(cols, patterns, fallback=0):
    """Guess the most plausible column for a given semantic role.

    Prefers an EXACT (case-insensitive) pattern match over a substring
    match. This matters for datasets that contain both "Score" and
    "Scorer": substring-only matching greedily returns "Scorer" for
    pattern "score", which caused a v0.2.12 crash when the binary
    testlet scenario hit the UI's auto-pick. Exact match first avoids
    the collision; substring match is kept as a fallback so typical
    datasets like "raw_score" still resolve.
    """
    if not cols:
        return None
    lowered = [c.lower() for c in cols]
    # Pass 1: exact match (case-insensitive)
    for pattern in patterns:
        for idx, name in enumerate(lowered):
            if pattern == name:
                return cols[idx]
    # Pass 2: substring match (legacy behavior)
    for pattern in patterns:
        for idx, name in enumerate(lowered):
            if pattern in name:
                return cols[idx]
    return cols[min(fallback, len(cols) - 1)]


# Multilingual column-name dictionaries for the smart column-role detector.
# Patterns are matched case-insensitively against the column names; both
# substring and Japanese matches are supported. The order within each role
# is the priority ranking when multiple patterns match.
_COLUMN_ROLE_PATTERNS: dict[str, tuple[str, ...]] = {
    "person": (
        # English
        "person", "examinee", "candidate", "participant", "subject",
        "respondent", "student", "user", "id_person", "person_id",
        # Japanese
        "学生", "児童", "生徒", "受験者", "受検者", "学習者", "被験者",
        "回答者", "対象者", "人物",
    ),
    "score": (
        # English
        "score", "rating", "mark", "marks", "points", "rate",
        "raw_score", "total_score",
        # Japanese
        "得点", "点数", "評価", "評定", "採点", "スコア", "評点",
    ),
    "rater": (
        # English
        "rater", "judge", "evaluator", "scorer", "observer", "marker",
        # Japanese
        "評価者", "採点者", "評定者", "審査員", "判定者", "観察者",
    ),
    "criterion": (
        # English
        "criterion", "criteria", "item", "task", "question", "rubric",
        "subscale", "dimension",
        # Japanese
        "観点", "項目", "課題", "評価項目", "問題", "ルーブリック",
        "下位尺度", "次元", "設問",
    ),
    "weight": (
        "weight", "wt", "frequency", "freq",
        "重み", "重み付け", "重み係数",
    ),
}


def _column_is_numeric(series: pd.Series, threshold: float = 0.7) -> bool:
    """Return True if at least ``threshold`` of non-blank cells parse to
    finite numbers — used by the smart column-role detector to bias
    Score detection toward numeric columns and Person / facet
    detection toward non-numeric (string-like) ones."""
    if not isinstance(series, pd.Series) or series.empty:
        return False
    non_blank = series.astype(str).str.strip().replace({"": pd.NA}).dropna()
    if non_blank.empty:
        return False
    coerced = pd.to_numeric(series, errors="coerce").dropna()
    return (len(coerced) / len(non_blank)) >= threshold


def auto_detect_column_roles(df: pd.DataFrame) -> dict:
    """Suggest column-role assignments from an uploaded DataFrame.

    Combines multilingual keyword matching (English + Japanese) with
    dtype and cardinality cues:

    * **Score** prefers numeric columns whose header matches a Score
      keyword (得点, score, rating, ...). Pure-numeric columns without
      a keyword match still qualify when the cardinality is small
      (rating scales typically have <= 10 distinct values).
    * **Person** prefers high-cardinality non-numeric columns whose
      header matches a Person keyword (学生, person, examinee, ...).
    * **Rater** prefers a non-numeric column whose header matches a
      Rater keyword (評価者, rater, judge, ...).
    * **Criterion** prefers a non-numeric column whose header matches
      a Criterion keyword (観点, criterion, item, task, ...).
    * **Weight** prefers a numeric column whose header matches a
      Weight keyword (重み, weight, ...); returns ``None`` when no
      such column exists (the typical case).

    Returns a dict with keys ``person``, ``score``, ``rater``,
    ``criterion``, ``weight``, ``suggested_facets`` (list), and
    ``confidence`` (dict role -> float in [0, 1]).
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return {
            "person": None, "score": None, "rater": None,
            "criterion": None, "weight": None,
            "suggested_facets": [], "confidence": {},
        }
    cols = list(df.columns)
    lowered = {c: str(c).lower() for c in cols}
    numeric_flag = {c: _column_is_numeric(df[c]) for c in cols}
    cardinality = {
        c: int(df[c].astype(str).str.strip().replace({"": pd.NA}).dropna().nunique())
        for c in cols
    }

    def _score(role: str, col: str) -> float:
        """Return a 0..1 confidence score for assigning ``col`` to ``role``."""
        patterns = _COLUMN_ROLE_PATTERNS.get(role, ())
        col_l = lowered[col]
        keyword_score = 0.0
        for i, p in enumerate(patterns):
            if p == col_l:
                # exact match has the highest weight; first pattern in the
                # list scores highest.
                keyword_score = max(keyword_score, 1.0 - i * 0.02)
            elif p in col_l:
                keyword_score = max(keyword_score, 0.6 - i * 0.01)
        keyword_score = max(keyword_score, 0.0)
        is_num = numeric_flag.get(col, False)
        card = cardinality.get(col, 0)
        n_rows = len(df)
        dtype_score = 0.0
        if role == "score":
            # Numeric + small cardinality (rating scale) preferred.
            if is_num:
                dtype_score = 0.4 if card <= 12 else 0.2
            else:
                dtype_score = 0.0
        elif role == "person":
            # Non-numeric + high cardinality preferred.
            if is_num:
                dtype_score = -0.2
            elif card >= max(2, n_rows // 4):
                dtype_score = 0.3
            else:
                dtype_score = 0.0
        elif role == "rater":
            if is_num:
                dtype_score = -0.1
            elif 2 <= card <= max(50, n_rows // 4):
                dtype_score = 0.2
        elif role == "criterion":
            if is_num:
                dtype_score = -0.1
            elif 2 <= card <= 50:
                dtype_score = 0.2
        elif role == "weight":
            if is_num:
                dtype_score = 0.3 if 0 < card <= 20 else 0.1
            else:
                dtype_score = -0.5
        return float(min(max(keyword_score + dtype_score, 0.0), 1.0))

    confidence: dict[str, float] = {}
    assignments: dict[str, str | None] = {}
    # Assign roles greedily by best-scoring column, with a minimum
    # confidence threshold so we don't surface noise as a "suggestion".
    used: set[str] = set()
    role_threshold = {
        "person": 0.15, "score": 0.15, "rater": 0.15,
        "criterion": 0.15, "weight": 0.25,
    }
    # Run roles in order of how distinctive their keyword sets are.
    role_order = ["score", "person", "rater", "criterion", "weight"]
    for role in role_order:
        best_col: str | None = None
        best_score = -1.0
        for col in cols:
            if col in used:
                continue
            s = _score(role, col)
            if s > best_score:
                best_score = s
                best_col = col
        if best_col is not None and best_score >= role_threshold[role]:
            assignments[role] = best_col
            confidence[role] = best_score
            used.add(best_col)
        else:
            assignments[role] = None

    # Suggested facets = non-assigned non-numeric columns plus
    # Rater / Criterion if we located them.
    suggested_facets: list[str] = []
    for role in ("rater", "criterion"):
        if assignments.get(role):
            suggested_facets.append(assignments[role])
    for col in cols:
        if col in used:
            continue
        if numeric_flag.get(col, False):
            continue
        if cardinality.get(col, 0) < 2:
            continue
        suggested_facets.append(col)

    return {
        "person": assignments["person"],
        "score": assignments["score"],
        "rater": assignments["rater"],
        "criterion": assignments["criterion"],
        "weight": assignments["weight"],
        "suggested_facets": suggested_facets,
        "confidence": confidence,
    }


def truncate_label(value, width=28):
    text = str(value)
    if len(text) <= width:
        return text
    return text[: max(0, width - 1)] + "…"


# ---------------------------------------------------------------------------
# Visualization CI level (user-configurable; default 95 %)
# ---------------------------------------------------------------------------

# Levels surfaced in the sidebar selector. 0.66 and 0.89 are conventional
# Bayesian credible levels (66 % is roughly ± 1 SD, 89 % is McElreath /
# Statistical Rethinking's default and avoids the "95 %" connotation
# of significance testing). 0.50 / 0.80 / 0.99 round out the options.
VIZ_CI_LEVEL_OPTIONS: tuple[float, ...] = (0.50, 0.66, 0.80, 0.89, 0.90, 0.95, 0.99)
VIZ_CI_LEVEL_DEFAULT: float = 0.95
VISUAL_THEME_OPTIONS: tuple[str, ...] = (
    "Manuscript white",
    "Grayscale print",
    "Colorblind-safe",
    "Presentation",
    "Dark inspection",
)
VISUAL_LABEL_POLICY_OPTIONS: tuple[str, ...] = (
    "Auto",
    "Show all",
    "Important labels",
    "Hover only",
)
PLOT_LABEL_MODE_OPTIONS: tuple[str, ...] = (
    "Auto",
    "Number",
    "Short label",
    "Full label",
    "None",
)
VISUAL_CAPTION_DETAIL_OPTIONS: tuple[str, ...] = ("Short", "Standard", "Detailed")
VISUAL_THEME_DEFAULT = "Manuscript white"
VISUAL_LABEL_POLICY_DEFAULT = "Auto"
PLOT_LABEL_MODE_DEFAULT = "Full label"
VISUAL_CAPTION_DETAIL_DEFAULT = "Standard"
VISUAL_BASE_FONT_SIZE_DEFAULT = 13
VISUAL_LABEL_MAX_CHARS_DEFAULT = 34
VISUAL_FIGURE_WIDTH_DEFAULT = PUBLICATION_FIGURE_WIDTH
VISUAL_FIGURE_MIN_HEIGHT_DEFAULT = 540


def get_viz_ci_level() -> float:
    """Return the user-selected visualization CI level (default 0.95).

    Read from ``st.session_state["viz_ci_level"]`` if set; otherwise
    fall back to ``VIZ_CI_LEVEL_DEFAULT``. Always clamped into ``(0, 1)``
    so a corrupted session value cannot crash a plot."""
    try:
        level = float(st.session_state.get("viz_ci_level", VIZ_CI_LEVEL_DEFAULT))
    except (TypeError, ValueError, AttributeError):
        level = VIZ_CI_LEVEL_DEFAULT
    if not (0.0 < level < 1.0):
        return VIZ_CI_LEVEL_DEFAULT
    return level


def _session_value(key: str, default):
    try:
        return st.session_state.get(key, default)
    except Exception:
        return default


def _clamp_int(value: object, default: int, min_value: int, max_value: int) -> int:
    try:
        out = int(value)
    except (TypeError, ValueError):
        out = default
    return int(max(min_value, min(max_value, out)))


def get_visualization_preferences() -> dict[str, object]:
    """Return user-controlled visual export preferences with safe defaults."""
    theme = str(_session_value("visual_theme", VISUAL_THEME_DEFAULT))
    if theme not in VISUAL_THEME_OPTIONS:
        theme = VISUAL_THEME_DEFAULT
    label_policy = str(_session_value("visual_label_policy", VISUAL_LABEL_POLICY_DEFAULT))
    if label_policy not in VISUAL_LABEL_POLICY_OPTIONS:
        label_policy = VISUAL_LABEL_POLICY_DEFAULT
    plot_label_mode = str(_session_value("plot_label_mode", PLOT_LABEL_MODE_DEFAULT))
    if plot_label_mode not in PLOT_LABEL_MODE_OPTIONS:
        plot_label_mode = PLOT_LABEL_MODE_DEFAULT
    caption_detail = str(_session_value("visual_caption_detail", VISUAL_CAPTION_DETAIL_DEFAULT))
    if caption_detail not in VISUAL_CAPTION_DETAIL_OPTIONS:
        caption_detail = VISUAL_CAPTION_DETAIL_DEFAULT
    return {
        "theme": theme,
        "label_policy": label_policy,
        "plot_label_mode": plot_label_mode,
        "caption_detail": caption_detail,
        "base_font_size": _clamp_int(
            _session_value("visual_base_font_size", VISUAL_BASE_FONT_SIZE_DEFAULT),
            VISUAL_BASE_FONT_SIZE_DEFAULT,
            9,
            22,
        ),
        "label_max_chars": _clamp_int(
            _session_value("visual_label_max_chars", VISUAL_LABEL_MAX_CHARS_DEFAULT),
            VISUAL_LABEL_MAX_CHARS_DEFAULT,
            8,
            96,
        ),
        "figure_width": _clamp_int(
            _session_value("visual_figure_width", VISUAL_FIGURE_WIDTH_DEFAULT),
            VISUAL_FIGURE_WIDTH_DEFAULT,
            640,
            1600,
        ),
        "figure_min_height": _clamp_int(
            _session_value("visual_figure_min_height", VISUAL_FIGURE_MIN_HEIGHT_DEFAULT),
            VISUAL_FIGURE_MIN_HEIGHT_DEFAULT,
            PUBLICATION_FIGURE_MIN_HEIGHT,
            PUBLICATION_FIGURE_MAX_HEIGHT,
        ),
        "dpi": PUBLICATION_FIGURE_DPI,
    }


