def _ci_z(level: float) -> float:
    """Return the two-sided normal z critical value for a given CI level.

    For a confidence level ``c`` in ``(0, 1)``, this returns
    ``Phi^{-1}((1 + c) / 2)``: ``z`` ≈ 1.96 for 0.95, 1.6449 for 0.90,
    1.5982 for 0.89, 0.6745 for 0.50, etc. Used to size error bars and
    forest-plot CI rules to a user-chosen level. Non-numeric / NaN /
    out-of-range inputs fall back to the 95 % critical value so a
    corrupted session value never crashes a plot."""
    try:
        lvl = float(level)
    except (TypeError, ValueError):
        return float(_norm.ppf(0.975))
    if not np.isfinite(lvl) or not (0.0 < lvl < 1.0):
        return float(_norm.ppf(0.975))
    return float(_norm.ppf((1.0 + lvl) / 2.0))


def _ci_level_pct_label(level: float) -> str:
    """Format ``level`` as a percentage label without trailing zeros.

    ``0.95 -> "95"``, ``0.66 -> "66"``, ``0.665 -> "66.5"``. Used in
    plot titles and captions to advertise the chosen CI level."""
    pct = float(level) * 100.0
    if abs(pct - round(pct)) < 1e-6:
        return str(int(round(pct)))
    return f"{pct:.1f}"


# ---- likelihoods ----
def loglik_rsm(eta, score_k, step_cum, weight=None):
    if eta.size == 0:
        return 0.0
    k_cat = len(step_cum)
    eta_mat = np.outer(eta, np.arange(k_cat))
    log_num = eta_mat - step_cum
    log_denom = logsumexp(log_num, axis=1)
    log_num_obs = log_num[np.arange(len(eta)), score_k]
    diff = log_num_obs - log_denom
    if weight is None:
        return float(np.sum(diff))
    return float(np.sum(diff * weight))


def loglik_pcm(eta, score_k, step_cum_mat, criterion_idx, weight=None):
    if eta.size == 0:
        return 0.0
    total = 0.0
    k_cat = step_cum_mat.shape[1]
    for c_idx in range(step_cum_mat.shape[0]):
        rows = np.where(criterion_idx == c_idx)[0]
        if rows.size == 0:
            continue
        eta_c = eta[rows]
        step_cum = step_cum_mat[c_idx]
        eta_mat = np.outer(eta_c, np.arange(k_cat))
        log_num = eta_mat - step_cum
        log_denom = logsumexp(log_num, axis=1)
        log_num_obs = log_num[np.arange(len(rows)), score_k[rows]]
        diff = log_num_obs - log_denom
        if weight is None:
            total += float(np.sum(diff))
        else:
            total += float(np.sum(diff * weight[rows]))
    return total


def loglik_gpcm(eta, score_k, step_cum_mat, step_idx, slopes, slope_idx, weight=None):
    if eta.size == 0:
        return 0.0
    if slope_idx is None:
        slope_idx = step_idx
    total = 0.0
    k_cat = step_cum_mat.shape[1]
    k_vals = np.arange(k_cat, dtype=float)
    slopes = np.asarray(slopes, dtype=float)
    for c_idx in range(step_cum_mat.shape[0]):
        rows = np.where(step_idx == c_idx)[0]
        if rows.size == 0:
            continue
        linear = np.outer(eta[rows], k_vals) - step_cum_mat[c_idx]
        slope_obs = slopes[slope_idx[rows]]
        log_num = slope_obs[:, None] * linear
        log_denom = logsumexp(log_num, axis=1)
        diff = log_num[np.arange(len(rows)), score_k[rows]] - log_denom
        if weight is None:
            total += float(np.sum(diff))
        else:
            total += float(np.sum(diff * weight[rows]))
    return total


def category_prob_rsm(eta, step_cum):
    if eta.size == 0:
        return np.zeros((0, len(step_cum)))
    k_cat = len(step_cum)
    eta_mat = np.outer(eta, np.arange(k_cat))
    log_num = eta_mat - step_cum
    log_denom = logsumexp(log_num, axis=1)
    return np.exp(log_num - log_denom[:, None])


def category_prob_pcm(eta, step_cum_mat, criterion_idx):
    if eta.size == 0:
        return np.zeros((0, step_cum_mat.shape[1]))
    k_cat = step_cum_mat.shape[1]
    probs = np.zeros((len(eta), k_cat))
    for c_idx in range(step_cum_mat.shape[0]):
        rows = np.where(criterion_idx == c_idx)[0]
        if rows.size == 0:
            continue
        step_cum = step_cum_mat[c_idx]
        eta_c = eta[rows]
        eta_mat = np.outer(eta_c, np.arange(k_cat))
        log_num = eta_mat - step_cum
        log_denom = logsumexp(log_num, axis=1)
        probs[rows, :] = np.exp(log_num - log_denom[:, None])
    return probs


def category_prob_gpcm(eta, step_cum_mat, step_idx, slopes, slope_idx):
    if eta.size == 0:
        return np.zeros((0, step_cum_mat.shape[1]))
    if slope_idx is None:
        slope_idx = step_idx
    k_cat = step_cum_mat.shape[1]
    k_vals = np.arange(k_cat, dtype=float)
    probs = np.zeros((len(eta), k_cat))
    slopes = np.asarray(slopes, dtype=float)
    for c_idx in range(step_cum_mat.shape[0]):
        rows = np.where(step_idx == c_idx)[0]
        if rows.size == 0:
            continue
        linear = np.outer(eta[rows], k_vals) - step_cum_mat[c_idx]
        slope_obs = slopes[slope_idx[rows]]
        log_num = slope_obs[:, None] * linear
        log_denom = logsumexp(log_num, axis=1)
        probs[rows, :] = np.exp(log_num - log_denom[:, None])
    return probs


def zstd_from_mnsq(mnsq, df, whexact=False):
    """Wilson-Hilferty (1931) standardised MnSq, engine convention.

    The engine convention guards against ``df < 1``: in that regime the
    ``1 - 2/(9 df)`` centring term becomes dominant and the resulting
    ZSTD can flip sign relative to the underlying MnSq, producing
    spurious large values. mfrmr (and FACETS) report NaN there so the
    user does not silently consume a misleading z-score. The
    FACETS-convention helper ``zstd_from_mnsq_facets`` relaxes this to
    ``df > 0`` (the Wright-Masters Welch-Satterthwaite d.f. can be
    fractional by design) and applies an explicit cap for the
    pathological cells.
    """
    if not np.isfinite(mnsq) or not np.isfinite(df) or df < 1:
        return np.nan
    if whexact:
        return (mnsq - 1) * np.sqrt(df / 2)
    return (mnsq ** (1 / 3) - (1 - 2 / (9 * df))) / np.sqrt(2 / (9 * df))


# ----------------------------------------------------------------------------
# FACETS / Wright-Masters ZSTD convention
# ----------------------------------------------------------------------------
# The engine ZSTD uses d.f. = sum(Var * w) for Infit and d.f. = sum(w) for
# Outfit, which assumes the per-observation variances are homogeneous enough
# that the residual sum of squares behaves like a chi-square with that d.f.
# FACETS / Wright-Masters (1982, Eqs. 4.20, 4.27) use a Welch-Satterthwaite
# d.f. that captures the variance heterogeneity:
#   DF_Infit_FACETS  = 2 * (sum sigma^2 w)^2 / sum w * (M4 - sigma^4)
#   DF_Outfit_FACETS = 2 * (sum w)^2 / sum w * (M4 / sigma^4 - 1)
# where M4 = E[(X - E[X])^4 | theta_i] is the fourth central moment of the
# polytomous response at observation i. Variance heterogeneity drives both
# denominators away from zero and so shrinks the d.f. below the engine
# convention; cells with extreme imbalance can produce d.f. << 1, which
# in turn produces extreme ZSTDs that FACETS caps at +/- 9 by default.
# The dispatch helper ``_apply_fit_df_method`` lets callers choose
# ``"engine"`` (default, backwards compatible), ``"facets"`` (primary
# ZSTD columns use the FACETS values), or ``"both"`` (both conventions
# carried side-by-side under *_ENGINE / *_FACETS suffix columns).

_FIT_DF_METHOD_CHOICES = ("engine", "facets", "both")


def _resolve_fit_df_method(fit_df_method) -> str:
    """Coerce ``fit_df_method`` to a known token, defaulting to ``"engine"``."""
    token = str(fit_df_method or "engine").strip().lower()
    if token in _FIT_DF_METHOD_CHOICES:
        return token
    return "engine"


def zstd_from_mnsq_facets(mnsq, df, whexact: bool = False, cap: float = 9.0):
    """FACETS-style ZSTD with explicit cap on extreme values.

    Implements the same Wilson-Hilferty cube-root transformation as
    ``zstd_from_mnsq`` but with the FACETS convention:

    * ``df > 0`` (rather than ``>= 1``) is accepted because the
      Wright-Masters Welch-Satterthwaite d.f. can be fractional;
    * the result is clamped to ``[-cap, +cap]`` (FACETS default 9.0).
    """
    if not np.isfinite(mnsq) or not np.isfinite(df) or mnsq <= 0 or df <= 0:
        return np.nan
    if whexact:
        z = (mnsq - 1) * np.sqrt(df / 2)
    else:
        z = (mnsq ** (1 / 3) - (1 - 2 / (9 * df))) / np.sqrt(2 / (9 * df))
    if cap is None or not np.isfinite(cap) or cap <= 0:
        return float(z)
    return float(np.clip(z, -float(cap), float(cap)))


def _facets_fit_df_terms(var, fourth, weight):
    """Return the Wright-Masters denominators for the FACETS d.f.

    The denominators are ``sum w * (M4 - sigma^4)`` for Infit and
    ``sum w * (M4 / sigma^4 - 1)`` for Outfit, evaluated only over
    observations with strictly positive variance and finite fourth
    moment. ``weight`` defaults to all-ones if ``None`` is passed.

    The linear-``w`` form matches the mfrmr 0.2.0 reference exactly
    and is the formula reported in the Wright & Masters (1982,
    Eq. 4.27) literature. The independence-based derivation under
    non-unit weights would substitute ``w^2`` for ``w``; for the
    typical MFRM case of unit observation weights the two forms are
    identical, and the linear-``w`` form is what FACETS / Wright-
    Masters report. The bundle's ``settings`` field names the
    formula in plain English so downstream consumers can name it
    correctly in a manuscript.
    """
    var = np.asarray(var, dtype=float)
    fourth = np.asarray(fourth, dtype=float)
    if weight is None:
        weight = np.ones_like(var)
    else:
        weight = np.asarray(weight, dtype=float)
    if weight.shape != var.shape:
        weight = np.broadcast_to(weight, var.shape).astype(float, copy=True)
    safe_var = np.where(np.isfinite(var) & (var > 1e-12), var, np.nan)
    valid = (
        np.isfinite(safe_var)
        & np.isfinite(fourth)
        & np.isfinite(weight)
        & (weight > 0)
    )
    denom_infit = float(np.nansum(weight[valid] * (fourth[valid] - safe_var[valid] ** 2)))
    denom_outfit = float(
        np.nansum(weight[valid] * (fourth[valid] / (safe_var[valid] ** 2) - 1))
    )
    return denom_infit, denom_outfit


def _facets_fit_df(sum_var_w: float, sum_w: float, denom_infit: float, denom_outfit: float):
    """Return ``(DF_Infit_FACETS, DF_Outfit_FACETS)`` from cell totals."""
    if (
        np.isfinite(denom_infit)
        and denom_infit > 1e-12
        and np.isfinite(sum_var_w)
        and sum_var_w > 0
    ):
        df_infit = 2.0 * (sum_var_w ** 2) / denom_infit
    else:
        df_infit = np.nan
    if (
        np.isfinite(denom_outfit)
        and denom_outfit > 1e-12
        and np.isfinite(sum_w)
        and sum_w > 0
    ):
        df_outfit = 2.0 * (sum_w ** 2) / denom_outfit
    else:
        df_outfit = np.nan
    return float(df_infit), float(df_outfit)


def fit_zstd_transform_label(whexact: bool = False) -> str:
    """Human-readable label for the ZSTD transform used in a report."""
    return "linear normal approximation" if whexact else "Wilson-Hilferty"


def _apply_fit_df_method(
    tbl: pd.DataFrame,
    fit_df_method: str = "engine",
    whexact: bool = False,
    facets_zstd_cap: float = 9.0,
) -> pd.DataFrame:
    """Dispatch a fit table between engine, FACETS, or both d.f. conventions.

    Expects ``tbl`` to carry ``Infit``, ``Outfit``, ``InfitZSTD``,
    ``OutfitZSTD``, ``DF_Infit``, ``DF_Outfit``, ``DF_Infit_FACETS``,
    ``DF_Outfit_FACETS``. Returns a frame whose primary columns reflect
    the requested method:

    * ``"engine"`` (default, backwards compatible): drops every FACETS
      column and the status fields, leaving the engine values as-is.
    * ``"facets"``: primary ``InfitZSTD`` / ``OutfitZSTD`` / ``DF_*``
      become the FACETS values; original engine values are preserved
      under ``*_ENGINE`` suffix columns; FACETS values also under
      ``*_FACETS`` for symmetry.
    * ``"both"``: keeps both ``*_ENGINE`` and ``*_FACETS`` suffix
      columns; primary columns continue to hold the engine values.

    Adds ``FitDfMethod``, ``FitZSTDTransform``, and ``FitZSTDCap``
    metadata columns in the non-engine modes so downstream consumers
    can read the convention off the row.
    """
    method = _resolve_fit_df_method(fit_df_method)
    required = (
        "Infit", "Outfit", "InfitZSTD", "OutfitZSTD",
        "DF_Infit", "DF_Outfit", "DF_Infit_FACETS", "DF_Outfit_FACETS",
    )
    if not all(c in tbl.columns for c in required):
        return tbl

    out = tbl.copy()
    out["DF_Infit_ENGINE"] = out["DF_Infit"]
    out["DF_Outfit_ENGINE"] = out["DF_Outfit"]
    out["InfitZSTD_ENGINE"] = out["InfitZSTD"]
    out["OutfitZSTD_ENGINE"] = out["OutfitZSTD"]
    out["InfitZSTD_FACETS"] = [
        zstd_from_mnsq_facets(m, d, whexact=whexact, cap=facets_zstd_cap)
        for m, d in zip(out["Infit"], out["DF_Infit_FACETS"])
    ]
    out["OutfitZSTD_FACETS"] = [
        zstd_from_mnsq_facets(m, d, whexact=whexact, cap=facets_zstd_cap)
        for m, d in zip(out["Outfit"], out["DF_Outfit_FACETS"])
    ]

    if method == "facets":
        out["DF_Infit"] = out["DF_Infit_FACETS"]
        out["DF_Outfit"] = out["DF_Outfit_FACETS"]
        out["InfitZSTD"] = out["InfitZSTD_FACETS"]
        out["OutfitZSTD"] = out["OutfitZSTD_FACETS"]
        out["FitDfMethod"] = "facets_wright_masters"
        out["FitDfFormula"] = "linear_w_wright_masters_eq_4_27"
    elif method == "both":
        out["FitDfMethod"] = "engine_primary_facets_available"
        out["FitDfFormula"] = "linear_w_wright_masters_eq_4_27"
    else:  # engine
        drop_cols = [
            "DF_Infit_ENGINE", "DF_Outfit_ENGINE",
            "InfitZSTD_ENGINE", "OutfitZSTD_ENGINE",
            "DF_Infit_FACETS", "DF_Outfit_FACETS",
            "InfitZSTD_FACETS", "OutfitZSTD_FACETS",
        ]
        return out.drop(columns=[c for c in drop_cols if c in out.columns])

    out["FitZSTDTransform"] = fit_zstd_transform_label(whexact)
    out["FitZSTDCap"] = (
        float(facets_zstd_cap)
        if (facets_zstd_cap is not None and np.isfinite(facets_zstd_cap) and facets_zstd_cap > 0)
        else np.nan
    )
    return out


def compute_base_eta(idx, params, config):
    eta = np.zeros_like(idx["score_k"], dtype=float)
    facet_signs = config.get("facet_signs", {})
    for facet in config["facet_names"]:
        sign = facet_signs.get(facet, -1)
        eta += sign * params["facets"][facet][idx["facets"][facet]]
    return eta


def compute_eta(idx, params, config, theta_override=None):
    theta = theta_override if theta_override is not None else params["theta"]
    eta = theta[idx["person"]] if theta.size else np.zeros_like(idx["score_k"], dtype=float)
    return eta + compute_base_eta(idx, params, config)


def mfrm_loglik_jmle(par, idx, config, sizes):
    params = expand_params(par, sizes, config)
    eta = compute_eta(idx, params, config)
    if config["model"] == "RSM":
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
        ll = loglik_rsm(eta, idx["score_k"], step_cum, weight=idx.get("weight"))
    elif config["model"] == "PCM":
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        ll = loglik_pcm(eta, idx["score_k"], step_cum_mat, idx["step_idx"], weight=idx.get("weight"))
    else:
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        ll = loglik_gpcm(
            eta,
            idx["score_k"],
            step_cum_mat,
            idx["step_idx"],
            params["slopes"],
            idx.get("slope_idx"),
            weight=idx.get("weight"),
        )
    return -ll


def mfrm_loglik_jmle_value_grad(par, idx, config, sizes):
    params = expand_params(par, sizes, config)
    eta = compute_eta(idx, params, config)
    score_k = idx["score_k"]
    weight = idx.get("weight")
    if weight is None:
        weight = np.ones_like(score_k, dtype=float)
    else:
        weight = np.asarray(weight, dtype=float)

    k_cat = int(config["n_cat"])
    k_vals = np.arange(k_cat, dtype=float)
    slope_obs = np.ones(len(eta), dtype=float)
    gpcm_linear = None

    if config["model"] == "RSM":
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
        log_num = np.outer(eta, k_vals) - step_cum
        log_denom = logsumexp(log_num, axis=1)
        ll_obs = log_num[np.arange(len(eta)), score_k] - log_denom
        probs = np.exp(log_num - log_denom[:, None])
    elif config["model"] == "PCM":
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        probs = np.zeros((len(eta), k_cat), dtype=float)
        ll_obs = np.zeros(len(eta), dtype=float)
        for c_idx in range(step_cum_mat.shape[0]):
            rows = np.where(idx["step_idx"] == c_idx)[0]
            if rows.size == 0:
                continue
            log_num = np.outer(eta[rows], k_vals) - step_cum_mat[c_idx]
            log_denom = logsumexp(log_num, axis=1)
            ll_obs[rows] = log_num[np.arange(len(rows)), score_k[rows]] - log_denom
            probs[rows, :] = np.exp(log_num - log_denom[:, None])
    else:
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        slope_idx = idx.get("slope_idx")
        if slope_idx is None:
            slope_idx = idx["step_idx"]
        slope_obs = params["slopes"][slope_idx]
        probs = np.zeros((len(eta), k_cat), dtype=float)
        ll_obs = np.zeros(len(eta), dtype=float)
        gpcm_linear = np.zeros((len(eta), k_cat), dtype=float)
        for c_idx in range(step_cum_mat.shape[0]):
            rows = np.where(idx["step_idx"] == c_idx)[0]
            if rows.size == 0:
                continue
            linear = np.outer(eta[rows], k_vals) - step_cum_mat[c_idx]
            log_num = slope_obs[rows, None] * linear
            log_denom = logsumexp(log_num, axis=1)
            ll_obs[rows] = log_num[np.arange(len(rows)), score_k[rows]] - log_denom
            probs[rows, :] = np.exp(log_num - log_denom[:, None])
            gpcm_linear[rows, :] = linear

    nll = -float(np.sum(weight * ll_obs))
    expected = probs @ k_vals
    eta_grad = -weight * slope_obs * (score_k - expected)

    grad_parts = []
    if sizes.get("theta", 0) > 0:
        theta_levels = len(config["theta_spec"]["levels"])
        theta_full_grad = np.bincount(idx["person"], weights=eta_grad, minlength=theta_levels)
        grad_parts.append(collapse_facet_gradient(theta_full_grad, config["theta_spec"]))

    facet_signs = config.get("facet_signs", {})
    for facet in config["facet_names"]:
        if sizes.get(facet, 0) == 0:
            continue
        sign = facet_signs.get(facet, -1)
        facet_levels = len(config["facet_specs"][facet]["levels"])
        facet_full_grad = np.bincount(
            idx["facets"][facet],
            weights=eta_grad * sign,
            minlength=facet_levels,
        )
        grad_parts.append(collapse_facet_gradient(facet_full_grad, config["facet_specs"][facet]))

    n_steps = max(k_cat - 1, 0)
    if n_steps > 0:
        thresholds = np.arange(n_steps)
        if config["model"] == "RSM":
            observed_gt = score_k[:, None] > thresholds[None, :]
            prob_gt = np.flip(np.cumsum(np.flip(probs[:, 1:], axis=1), axis=1), axis=1)
            step_full_grad = np.sum(weight[:, None] * (observed_gt - prob_gt), axis=0)
            grad_parts.append(collapse_centered_gradient(step_full_grad))
        elif config["model"] == "PCM":
            step_facet_n = len(config["facet_levels"][config["step_facet"]])
            step_mat_grad = np.zeros((step_facet_n, n_steps), dtype=float)
            for c_idx in range(step_facet_n):
                rows = np.where(idx["step_idx"] == c_idx)[0]
                if rows.size == 0:
                    continue
                observed_gt = score_k[rows, None] > thresholds[None, :]
                prob_gt = np.flip(np.cumsum(np.flip(probs[rows, 1:], axis=1), axis=1), axis=1)
                step_mat_grad[c_idx, :] = np.sum(weight[rows, None] * (observed_gt - prob_gt), axis=0)
            grad_parts.append(np.vstack([collapse_centered_gradient(row) for row in step_mat_grad]).reshape(-1))
        else:
            step_facet_n = len(config["facet_levels"][config["step_facet"]])
            step_mat_grad = np.zeros((step_facet_n, n_steps), dtype=float)
            for c_idx in range(step_facet_n):
                rows = np.where(idx["step_idx"] == c_idx)[0]
                if rows.size == 0:
                    continue
                observed_gt = score_k[rows, None] > thresholds[None, :]
                prob_gt = np.flip(np.cumsum(np.flip(probs[rows, 1:], axis=1), axis=1), axis=1)
                step_mat_grad[c_idx, :] = np.sum(
                    weight[rows, None] * slope_obs[rows, None] * (observed_gt - prob_gt),
                    axis=0,
                )
            grad_parts.append(np.vstack([collapse_centered_gradient(row) for row in step_mat_grad]).reshape(-1))

    if config["model"] == "GPCM" and sizes.get("log_slopes", 0) > 0:
        slope_idx = idx.get("slope_idx")
        if slope_idx is None:
            slope_idx = idx["step_idx"]
        obs_linear = gpcm_linear[np.arange(len(eta)), score_k]
        expected_linear = np.sum(probs * gpcm_linear, axis=1)
        slope_levels = len(config["facet_levels"][config["slope_facet"]])
        slope_full_grad = np.bincount(
            slope_idx,
            weights=-weight * slope_obs * (obs_linear - expected_linear),
            minlength=slope_levels,
        )
        grad_parts.append(collapse_centered_gradient(slope_full_grad))

    grad = np.concatenate([g for g in grad_parts if g.size]) if grad_parts else np.array([], dtype=float)
    if grad.size != len(par):
        raise RuntimeError(f"Internal gradient size mismatch: expected {len(par)}, got {grad.size}.")
    penalty_value, penalty_grad = facet_regularization_value_grad(par, sizes, config)
    if config.get("facet_regularization", {}).get("enabled"):
        nll += penalty_value
        grad = grad + penalty_grad
    return nll, grad


def mfrm_loglik_mml(par, idx, config, sizes, quad):
    """Marginal log-likelihood (negative) for MML — used in M-step."""
    params = expand_params(par, sizes, config)
    n = len(idx["score_k"])
    if n == 0:
        return 0.0

    base_eta = compute_base_eta(idx, params, config)
    rows_by_person = idx.get("rows_by_person")
    if rows_by_person is None:
        rows_by_person = [np.where(idx["person"] == p)[0] for p in range(config["n_person"])]

    log_w = np.log(quad["weights"])
    pop_mu = compute_population_mu(params, config)

    if config["model"] == "RSM":
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
        ll_person = []
        for j, rows in enumerate(rows_by_person):
            if len(rows) == 0:
                continue
            base = base_eta[rows]
            score_k = idx["score_k"][rows]
            w = idx.get("weight")[rows] if idx.get("weight") is not None else None
            mu_j = pop_mu[j] if j < len(pop_mu) else 0.0
            ll_nodes = [loglik_rsm(mu_j + theta + base, score_k, step_cum, weight=w) for theta in quad["nodes"]]
            ll_person.append(logsumexp(log_w + ll_nodes))
    elif config["model"] == "PCM":
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        ll_person = []
        for j, rows in enumerate(rows_by_person):
            if len(rows) == 0:
                continue
            base = base_eta[rows]
            score_k = idx["score_k"][rows]
            crit = idx["step_idx"][rows]
            w = idx.get("weight")[rows] if idx.get("weight") is not None else None
            mu_j = pop_mu[j] if j < len(pop_mu) else 0.0
            ll_nodes = [loglik_pcm(mu_j + theta + base, score_k, step_cum_mat, crit, weight=w) for theta in quad["nodes"]]
            ll_person.append(logsumexp(log_w + ll_nodes))
    else:
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        ll_person = []
        for j, rows in enumerate(rows_by_person):
            if len(rows) == 0:
                continue
            base = base_eta[rows]
            score_k = idx["score_k"][rows]
            step_idx = idx["step_idx"][rows]
            slope_idx_full = idx.get("slope_idx")
            slope_idx = slope_idx_full[rows] if slope_idx_full is not None else step_idx
            w = idx.get("weight")[rows] if idx.get("weight") is not None else None
            mu_j = pop_mu[j] if j < len(pop_mu) else 0.0
            ll_nodes = [
                loglik_gpcm(mu_j + theta + base, score_k, step_cum_mat, step_idx, params["slopes"], slope_idx, weight=w)
                for theta in quad["nodes"]
            ]
            ll_person.append(logsumexp(log_w + ll_nodes))

    return -float(np.sum(ll_person))


def mfrm_loglik_mml_value_grad(par, idx, config, sizes, quad):
    """Direct MML negative marginal log-likelihood with analytical gradient.

    The gradient uses Fisher's identity: at the current parameter vector, the
    gradient of the marginal log-likelihood equals the posterior expectation of
    the complete-data score. This reuses the EM E-step posterior weights and the
    analytical M-step gradient.
    """
    params = expand_params(par, sizes, config)
    post_weights, marginal_ll = _e_step_posteriors(idx, config, params, quad)
    _, grad = _m_step_expected_ll_value_grad(par, idx, config, sizes, quad, post_weights)
    penalty_value, _ = facet_regularization_value_grad(par, sizes, config)
    return -marginal_ll + penalty_value, grad


def mfrm_direct_mml(start, idx, config, sizes, quad, maxit=400, reltol=1e-6):
    """Direct analytical-gradient MML optimization."""
    opt = minimize(
        mfrm_loglik_mml_value_grad,
        np.array(start, dtype=float, copy=True),
        args=(idx, config, sizes, quad),
        jac=True,
        method="L-BFGS-B",
        bounds=build_optimizer_bounds(sizes, config),
        options={"maxiter": maxit, "gtol": reltol, "ftol": reltol},
    )
    opt.mml_engine = "direct"
    raw_nll = mfrm_loglik_mml(opt.x, idx, config, sizes, quad)
    penalty_value, _ = facet_regularization_value_grad(opt.x, sizes, config)
    opt.raw_fun = raw_nll
    opt.penalty_value = penalty_value
    opt.ll_trace = [-float(raw_nll)] if np.isfinite(raw_nll) else []
    opt.gradient_norm = float(np.linalg.norm(opt.jac)) if getattr(opt, "jac", None) is not None else np.nan
    return opt


def mfrm_hybrid_mml(start, idx, config, sizes, quad, maxit=400, reltol=1e-6):
    """Hybrid MML: short EM warm start followed by direct MML optimization."""
    warm_maxit = max(2, min(10, int(maxit // 4))) if maxit >= 4 else max(1, int(maxit))
    direct_maxit = max(1, int(maxit) - warm_maxit)
    warm = mfrm_em_mml(start, idx, config, sizes, quad, maxit=warm_maxit, reltol=reltol)
    opt = mfrm_direct_mml(warm.x, idx, config, sizes, quad, maxit=direct_maxit, reltol=reltol)
    opt.mml_engine = "hybrid"
    opt.em_warmup_iterations = int(getattr(warm, "nit", warm_maxit))
    opt.direct_iterations = int(getattr(opt, "nit", 0))
    opt.nit = opt.em_warmup_iterations + opt.direct_iterations
    opt.nfev = int(getattr(warm, "nfev", 0)) + int(getattr(opt, "nfev", 0))
    opt.ll_trace = list(getattr(warm, "ll_trace", [])) + list(getattr(opt, "ll_trace", []))
    return opt


def mfrm_auto_mml(start, idx, config, sizes, quad, maxit=400, reltol=1e-6):
    """Auto MML: try hybrid first, then fall back to EM if needed."""
    hybrid = mfrm_hybrid_mml(start, idx, config, sizes, quad, maxit=maxit, reltol=reltol)
    hybrid.auto_attempted = ["hybrid"]
    hybrid.auto_selected = "hybrid"
    if bool(getattr(hybrid, "success", False)) and np.isfinite(getattr(hybrid, "fun", np.nan)):
        return hybrid

    fallback = mfrm_em_mml(start, idx, config, sizes, quad, maxit=maxit, reltol=reltol)
    fallback.mml_engine = "em"
    fallback.auto_attempted = ["hybrid", "em"]
    fallback.auto_selected = "em"
    fallback.auto_fallback_reason = str(getattr(hybrid, "message", "hybrid did not converge") or "hybrid did not converge")

    if bool(getattr(fallback, "success", False)):
        return fallback
    if np.isfinite(getattr(fallback, "fun", np.nan)) and (
        not np.isfinite(getattr(hybrid, "fun", np.nan)) or fallback.fun <= hybrid.fun
    ):
        return fallback

    hybrid.auto_attempted = ["hybrid", "em"]
    hybrid.auto_selected = "hybrid"
    hybrid.auto_fallback_reason = "EM fallback did not improve convergence or likelihood."
    return hybrid


def build_convergence_summary(opt, config: dict, loglik: float, elapsed_seconds: float | None = None) -> pd.DataFrame:
    """One-row optimizer convergence table for reporting and downloads."""
    if opt is None:
        return pd.DataFrame()
    ll_trace = list(getattr(opt, "ll_trace", []) or [])
    ll_start = float(ll_trace[0]) if ll_trace and np.isfinite(ll_trace[0]) else np.nan
    ll_final = float(loglik) if np.isfinite(loglik) else np.nan
    ll_change = ll_final - ll_start if np.isfinite(ll_final) and np.isfinite(ll_start) else np.nan
    grad_norm = getattr(opt, "gradient_norm", np.nan)
    if not np.isfinite(grad_norm) and getattr(opt, "jac", None) is not None:
        try:
            grad_norm = float(np.linalg.norm(opt.jac))
        except Exception:
            grad_norm = np.nan
    rows = [{
        "Method": config.get("method"),
        "RequestedMmlEngine": config.get("mml_engine_requested"),
        "ResolvedMmlEngine": config.get("mml_engine"),
        "Optimizer": config.get("optimizer"),
        "FacetRegularization": "On" if config.get("facet_regularization_enabled") else "Off",
        "Converged": bool(getattr(opt, "success", False)),
        "Message": str(getattr(opt, "message", "")),
        "Iterations": int(getattr(opt, "nit", 0) or 0),
        "FunctionEvals": int(getattr(opt, "nfev", 0) or 0),
        "WarmupEMIterations": getattr(opt, "em_warmup_iterations", np.nan),
        "DirectIterations": getattr(opt, "direct_iterations", np.nan),
        "FinalLogLik": ll_final,
        "LogLikStart": ll_start,
        "LogLikChange": ll_change,
        "RegularizationPenalty": float(getattr(opt, "penalty_value", np.nan))
        if np.isfinite(getattr(opt, "penalty_value", np.nan)) else np.nan,
        "FinalPenalizedObjective": (
            -ll_final + float(getattr(opt, "penalty_value", 0.0))
            if np.isfinite(ll_final) and np.isfinite(getattr(opt, "penalty_value", 0.0)) else np.nan
        ),
        "GradientNorm": float(grad_norm) if np.isfinite(grad_norm) else np.nan,
        "ElapsedSeconds": float(elapsed_seconds) if elapsed_seconds is not None and np.isfinite(elapsed_seconds) else np.nan,
        "AutoAttempted": ", ".join(getattr(opt, "auto_attempted", []) or []),
        "AutoSelected": getattr(opt, "auto_selected", ""),
        "AutoFallbackReason": getattr(opt, "auto_fallback_reason", ""),
    }]
    return pd.DataFrame(rows)


def _safe_float(value, default: float = np.nan) -> float:
    """Coerce a scalar to float; return default for missing/non-finite failures."""
    try:
        out = float(value)
    except (TypeError, ValueError):
        return default
    return out if np.isfinite(out) else default


def _summary_metric(summary: pd.DataFrame | None, name: str, default: float = np.nan) -> float:
    if not isinstance(summary, pd.DataFrame) or summary.empty or name not in summary.columns:
        return default
    return _safe_float(summary.iloc[0].get(name), default=default)


def build_likelihood_information_criteria(result: dict | None) -> pd.DataFrame:
    """Single-run likelihood and information-criteria table for reporting."""
    if not isinstance(result, dict):
        return pd.DataFrame()
    summary = result.get("summary")
    if not isinstance(summary, pd.DataFrame) or summary.empty:
        return pd.DataFrame()
    row = summary.iloc[0]
    config = result.get("config", {}) if isinstance(result.get("config", {}), dict) else {}
    loglik = _summary_metric(summary, "LogLik")
    n_eff = _summary_metric(summary, "N")
    k_params = _summary_metric(summary, "KParams")
    if not np.isfinite(k_params):
        k_params = _summary_metric(summary, "Parameters")
    if not np.isfinite(k_params):
        k_params = _safe_float(config.get("parameter_count"))
    deviance = _summary_metric(summary, "Deviance")
    if not np.isfinite(deviance) and np.isfinite(loglik):
        deviance = -2.0 * loglik
    aic = _summary_metric(summary, "AIC")
    if not np.isfinite(aic) and np.isfinite(deviance) and np.isfinite(k_params):
        aic = deviance + 2.0 * k_params
    bic = _summary_metric(summary, "BIC")
    if not np.isfinite(bic) and np.isfinite(deviance) and np.isfinite(k_params) and np.isfinite(n_eff) and n_eff > 0:
        bic = deviance + np.log(n_eff) * k_params
    penalty_value = _summary_metric(summary, "RegularizationPenalty", default=0.0)
    penalized_objective = _summary_metric(summary, "PenalizedObjective")
    if not np.isfinite(penalized_objective) and np.isfinite(deviance):
        penalized_objective = -loglik + penalty_value if np.isfinite(loglik) else np.nan

    def per_obs(value: float) -> float:
        return float(value / n_eff) if np.isfinite(value) and np.isfinite(n_eff) and n_eff > 0 else np.nan

    model = str(row.get("Model", config.get("model", "")))
    method = str(row.get("Method", config.get("method", "")))
    rows = [
        {
            "Metric": "N",
            "Value": n_eff,
            "PreferredDirection": "context",
            "Formula": "effective likelihood rows or total positive weight",
            "Interpretation": "Number of observations contributing to the fitted likelihood.",
        },
        {
            "Metric": "KParams",
            "Value": k_params,
            "PreferredDirection": "context",
            "Formula": "free estimated parameters counted for AIC/BIC",
            "Interpretation": "Penalty term size; larger models are penalized more strongly.",
        },
        {
            "Metric": "LogLik",
            "Value": loglik,
            "PreferredDirection": "higher",
            "Formula": "maximized log-likelihood",
            "Interpretation": "Higher is better only under the same likelihood definition and data.",
        },
        {
            "Metric": "Deviance",
            "Value": deviance,
            "PreferredDirection": "lower",
            "Formula": "-2 * LogLik",
            "Interpretation": "Lower is better under comparable likelihoods.",
        },
        {
            "Metric": "RegularizationPenalty",
            "Value": penalty_value,
            "PreferredDirection": "context",
            "Formula": "0.5 * sum(((facet effect - mean) / SD)^2)",
            "Interpretation": "Penalty added to the optimized objective; zero for unpenalized runs.",
        },
        {
            "Metric": "PenalizedObjective",
            "Value": penalized_objective,
            "PreferredDirection": "lower",
            "Formula": "-LogLik + RegularizationPenalty",
            "Interpretation": "Objective minimized when facet regularization is active; not an ordinary log-likelihood.",
        },
        {
            "Metric": "AIC",
            "Value": aic,
            "PreferredDirection": "lower",
            "Formula": "2 * KParams - 2 * unpenalized LogLik",
            "Interpretation": "Lower AIC favors the model after a lighter complexity penalty.",
        },
        {
            "Metric": "BIC",
            "Value": bic,
            "PreferredDirection": "lower",
            "Formula": "log(N) * KParams - 2 * unpenalized LogLik",
            "Interpretation": "Lower BIC favors the model after a stronger sample-size penalty.",
        },
        {
            "Metric": "LogLikPerObs",
            "Value": per_obs(loglik),
            "PreferredDirection": "higher",
            "Formula": "LogLik / N",
            "Interpretation": "Scale-normalized likelihood index for descriptive review.",
        },
        {
            "Metric": "AICPerObs",
            "Value": per_obs(aic),
            "PreferredDirection": "lower",
            "Formula": "AIC / N",
            "Interpretation": "Scale-normalized information criterion for descriptive review.",
        },
        {
            "Metric": "BICPerObs",
            "Value": per_obs(bic),
            "PreferredDirection": "lower",
            "Formula": "BIC / N",
            "Interpretation": "Scale-normalized information criterion for descriptive review.",
        },
    ]
    out = pd.DataFrame(rows)
    out.insert(0, "Method", method)
    out.insert(0, "Model", model)
    return out


# ============================================================================
# Model-choice guidance: refit RSM / PCM / GPCM and compare
# ============================================================================
# The three rating-scale models form a nested hierarchy in the model
# specification, but inferential LR-test wording depends on the
# estimation route. With JMLE, incidental person parameters and bounded
# GPCM slopes make Wilks-style p-values exploratory rather than
# confirmatory. With comparable MML marginal likelihood fits, the
# large-sample interpretation is more defensible when constraints and
# quadrature/prior settings are aligned.
#   RSM (Andersen 1977 / Andrich 1978) is a special case of
#   PCM (Masters 1982) when per-step thresholds collapse to a common set;
#   PCM is a special case of GPCM (Muraki 1992) when all slopes equal one.
# AIC (Akaike 1974) and BIC (Schwarz 1978) compare any of the three on a
# common information scale; the LR chi-square pivotal (Wilks 1938) is
# surfaced with caveats on the nested pairs (RSM vs PCM, PCM vs GPCM,
# and RSM vs GPCM).
# The helper below refits the two non-current models on the same data
# and returns a publication-style comparison table with the per-row
# DeltaAIC / DeltaBIC, evidence ratios (Burnham & Anderson 2002), and
# a recommendation tier informed by the joint AIC/BIC ordering. Refits
# inherit ``method``, ``maxit``, ``reltol``, ``quad_points`` and the
# step / slope facet conventions from the original fit; runs with
# anchors, population formulas, or facet regularization are surfaced
# as ``available = False`` because their likelihoods are not directly
# comparable on the same scale.

_MODEL_CHOICE_CANDIDATES = ("RSM", "PCM", "GPCM")


def _select_first_polytomous_facet(res: dict) -> str | None:
    """Pick a sensible default step facet for refits.

    Returns the original step facet when present; otherwise the first
    non-Person facet with more than one level, since RSM-style fits
    routinely omit the step facet and PCM / GPCM refits need one.
    """
    config = res.get("config", {}) if isinstance(res, dict) else {}
    chosen = config.get("step_facet")
    if isinstance(chosen, str) and chosen:
        return chosen
    facet_names = list(config.get("facet_names", []))
    prep = res.get("prep", {}) if isinstance(res, dict) else {}
    levels = prep.get("levels", {}) if isinstance(prep, dict) else {}
    for facet in facet_names:
        n_levels = len(levels.get(facet, []))
        if n_levels > 1 and facet != "Person":
            return facet
    return None


def _model_choice_can_compare(res: dict) -> tuple[bool, str]:
    """Return ``(ok, reason)`` for the comparison pipeline.

    Refuses runs whose likelihood scale differs from a plain refit
    (anchored, population-regressed, regularized, weight-aware), since
    AIC / BIC must be evaluated on a common likelihood.
    """
    if not isinstance(res, dict):
        return False, "Result is not a fit dictionary."
    config = res.get("config", {}) if isinstance(res, dict) else {}
    if not isinstance(config, dict) or not config.get("model"):
        return False, "Fit configuration is missing a model name."
    prep = res.get("prep", {}) if isinstance(res, dict) else {}
    if not isinstance(prep, dict) or not isinstance(prep.get("data"), pd.DataFrame):
        return False, "Fit does not carry a raw data frame for re-fitting."
    if config.get("facet_regularization_enabled"):
        return (
            False,
            "Facet regularization is active; the penalized objective is not a "
            "comparable likelihood. Re-fit without regularization to run the "
            "model-choice comparison."
        )
    pop = config.get("population_model", {}) if isinstance(config.get("population_model", {}), dict) else {}
    if pop.get("enabled"):
        return (
            False,
            "Population / latent-regression terms are active; refits under the "
            "same prior require additional plumbing that is not yet in scope."
        )
    if config.get("anchors_active") or res.get("anchors", {}).get("active"):
        return (
            False,
            "Anchored runs use fixed parameters that may not be compatible with "
            "every candidate model; run the comparison on the unanchored data set."
        )
    n_cat = int(config.get("n_cat", 0) or 0)
    if n_cat < 2:
        return False, "Number of score categories is below 2; cannot compare."
    return True, ""


def _refit_candidate_model(
    res: dict,
    candidate: str,
    *,
    step_facet: str | None,
    slope_facet: str | None,
):
    """Refit a candidate model on the same raw data, inheriting fit knobs.

    Returns the new ``res`` dict on success, or ``None`` on failure.
    """
    config = res.get("config", {}) if isinstance(res, dict) else {}
    prep = res.get("prep", {}) if isinstance(res, dict) else {}
    data = prep.get("data")
    if not isinstance(data, pd.DataFrame) or data.empty:
        return None

    # RSM has no step facet (shared step thresholds); PCM / GPCM use the
    # chosen step facet (mirrors the original convention).
    refit_step_facet = None if candidate == "RSM" else step_facet
    refit_slope_facet = None if candidate != "GPCM" else (slope_facet or step_facet)
    weight_col = "Weight" if "Weight" in data.columns else None
    try:
        return mfrm_estimate(
            data=data,
            person_col="Person",
            facet_cols=list(config.get("facet_names", [])),
            score_col="Score",
            rating_min=prep.get("rating_min"),
            rating_max=(prep.get("rating_min", 0) + int(config.get("n_cat", 2) or 2) - 1),
            weight_col=weight_col,
            model=candidate,
            method=str(config.get("method", "JMLE")),
            step_facet=refit_step_facet,
            slope_facet=refit_slope_facet,
            noncenter_facet=str(config.get("noncenter_facet", "Person")),
            dummy_facets=list(config.get("dummy_facets", [])) or None,
            positive_facets=list(config.get("positive_facets", [])) or None,
            quad_points=int(config.get("quad_points", 15) or 15),
            maxit=int(config.get("maxit", 400) or 400),
            reltol=float(config.get("reltol", 1e-6) or 1e-6),
            mml_engine=str(config.get("mml_engine", "EM")),
        )
    except Exception:
        return None


def _model_choice_evidence_ratio(delta_ic: float) -> float:
    """Akaike / Schwarz evidence ratio ``exp(delta_ic / 2)`` for AIC or BIC.

    The reference model (lowest IC) has DeltaIC = 0 and evidence ratio 1.
    Larger ratios mean stronger evidence against the candidate.
    """
    if not np.isfinite(delta_ic) or delta_ic < 0:
        return np.nan
    try:
        return float(np.exp(delta_ic / 2.0))
    except OverflowError:
        return float("inf")


def _model_choice_information_weights(delta_ic_series: pd.Series) -> pd.Series:
    """Akaike / Schwarz / AICc weights from a DeltaIC column.

    For a set of models indexed by ``i`` with DeltaIC values d_i,
    the information weight is

        w_i = exp(-d_i / 2) / sum_j exp(-d_j / 2)

    (Burnham & Anderson, 2002, Eq. 2.8). The weights sum to 1
    across the finite-DeltaIC rows and admit a probability
    interpretation: w_i is the relative likelihood that model i is
    the Kullback-Leibler best of the candidate set. Non-finite
    DeltaIC entries map to ``NaN``.
    """
    arr = pd.to_numeric(delta_ic_series, errors="coerce").to_numpy(dtype=float)
    out = np.full_like(arr, np.nan)
    finite = np.isfinite(arr)
    if not finite.any():
        return pd.Series(out, index=delta_ic_series.index)
    # Subtract the minimum to keep exp() within range and avoid
    # underflow at the high-DeltaIC tail (DeltaIC values are already
    # non-negative when computed relative to the minimum, but defensive
    # subtraction guards against numerical drift).
    centred = arr.copy()
    centred[finite] = centred[finite] - float(np.min(centred[finite]))
    relative = np.zeros_like(arr)
    relative[finite] = np.exp(-centred[finite] / 2.0)
    total = float(np.sum(relative[finite]))
    if total <= 0 or not np.isfinite(total):
        return pd.Series(out, index=delta_ic_series.index)
    out[finite] = relative[finite] / total
    return pd.Series(out, index=delta_ic_series.index)


def _model_choice_recommend(comparison: pd.DataFrame) -> dict:
    """Return ``{"model", "tier", "rationale"}`` from the comparison table.

    Reading order: prefer the lowest BIC for evidence-weight assessment
    (Schwarz 1978 is consistent under regularity); break ties by AIC
    (Akaike 1974); when |DeltaBIC| < 2 between the top two, downgrade
    the tier to ``"weak"`` so the recommendation does not over-state.
    When the design is small (any model with ``N / K < 40``), AICc
    (Hurvich & Tsai 1989) replaces AIC for the secondary criterion
    because the small-sample correction is recommended in that regime
    (Burnham & Anderson 2002, p. 66).
    """
    if comparison is None or comparison.empty:
        return {
            "model": "",
            "tier": "not_available",
            "rationale": "Comparison table is empty.",
        }
    finite = comparison.dropna(subset=["BIC", "AIC"])
    if finite.empty:
        return {
            "model": "",
            "tier": "not_available",
            "rationale": "No model produced a finite BIC / AIC.",
        }
    # Decide whether to use AICc as the secondary criterion. The
    # AICcRecommended flag fires when any candidate has N / K < 40.
    use_aicc = bool(finite.get("AICcRecommended", pd.Series([False])).any())
    secondary_col = "AICc" if use_aicc and finite["AICc"].notna().any() else "AIC"
    delta_secondary_label = "DeltaAICc" if secondary_col == "AICc" else "DeltaAIC"

    ranked = finite.sort_values(["BIC", secondary_col], ascending=True)
    best = ranked.iloc[0]
    if len(ranked) >= 2:
        second = ranked.iloc[1]
        delta_bic = float(second["BIC"] - best["BIC"])
        delta_secondary = float(second[secondary_col] - best[secondary_col])
    else:
        delta_bic = float("inf")
        delta_secondary = float("inf")
    if delta_bic >= 10 or delta_secondary >= 10:
        tier = "strong"
    elif delta_bic >= 6 or delta_secondary >= 6:
        tier = "moderate"
    elif delta_bic >= 2 or delta_secondary >= 2:
        tier = "weak"
    else:
        tier = "tie"
    rationale_extra = (
        f" (AICc used as the secondary criterion because N / K < 40 on at "
        f"least one candidate, per Burnham & Anderson 2002, p. 66)"
        if use_aicc and secondary_col == "AICc"
        else ""
    )
    return {
        "model": str(best["Model"]),
        "tier": tier,
        "rationale": (
            f"Lowest BIC ({best['BIC']:.2f}) and {secondary_col} "
            f"({best[secondary_col]:.2f}); "
            f"gap to second-best is DeltaBIC = {delta_bic:.2f}, "
            f"{delta_secondary_label} = {delta_secondary:.2f}{rationale_extra}."
        ),
    }


def _model_choice_lr_tests(model_results: dict[str, dict]) -> pd.DataFrame:
    """Return a per-pair LR-test table for the nested comparisons.

    RSM ⊂ PCM ⊂ GPCM is the standard nesting; the chi-square pivotal
    is ``Lambda = 2 * (LL_alt - LL_null) ~ chi2_{df_alt - df_null}``
    (Wilks 1938). Only pairs where both fits succeeded contribute a
    row; the d.f. for each pair is the difference in counted free
    parameters. Returns an empty frame if no nested pair is available.
    """
    rows = []
    pairs = [("RSM", "PCM"), ("PCM", "GPCM"), ("RSM", "GPCM")]
    for null_name, alt_name in pairs:
        null = model_results.get(null_name)
        alt = model_results.get(alt_name)
        if null is None or alt is None:
            continue
        null_ll = _summary_metric(null.get("summary"), "LogLik")
        alt_ll = _summary_metric(alt.get("summary"), "LogLik")
        null_k = _summary_metric(null.get("summary"), "KParams")
        alt_k = _summary_metric(alt.get("summary"), "KParams")
        if not (np.isfinite(null_ll) and np.isfinite(alt_ll) and np.isfinite(null_k) and np.isfinite(alt_k)):
            continue
        chi_sq = 2.0 * (alt_ll - null_ll)
        df = int(round(alt_k - null_k))
        if df <= 0:
            continue
        p_val = float(chi2.sf(chi_sq, df=df)) if np.isfinite(chi_sq) and chi_sq >= 0 else np.nan
        if not np.isfinite(p_val):
            decision = "not available"
        elif p_val < 0.001:
            decision = "reject null (p < 0.001)"
        elif p_val < 0.01:
            decision = "reject null (p < 0.01)"
        elif p_val < 0.05:
            decision = "reject null (p < 0.05)"
        else:
            decision = "retain null"
        rows.append({
            "Null": null_name,
            "Alternative": alt_name,
            "ChiSq": float(chi_sq),
            "df": df,
            "p": p_val,
            "Decision": decision,
        })
    return pd.DataFrame(rows)


def compute_model_choice_comparison(res: dict) -> dict:
    """Refit RSM / PCM / GPCM on the same data and return a comparison bundle.

    The bundle keys are:

    * ``available`` (bool) — comparison is reportable
    * ``reason`` (str) — only populated when ``available`` is False
    * ``comparison`` (DataFrame) — one row per model with
      ``Model, N, KParams, LogLik, AIC, BIC, DeltaAIC, DeltaBIC,
      AICEvidenceRatio, BICEvidenceRatio, FitStatus``
    * ``lr_tests`` (DataFrame) — nested-pair likelihood-ratio tests
    * ``recommendation`` (dict) — ``model``, ``tier``, ``rationale``
    * ``caveat`` (str) — manuscript-ready caveat about scope
    * ``fit_times`` (dict) — elapsed seconds per refit

    Refits inherit ``method`` (JMLE / MML), ``maxit``, ``reltol``,
    ``quad_points``, ``step_facet``, and ``slope_facet`` from the
    original fit. Runs with anchors, population formulas, facet
    regularization, or non-positive number of score categories are
    refused with an explanatory ``reason``.
    """
    ok, reason = _model_choice_can_compare(res)
    if not ok:
        return {
            "available": False,
            "reason": reason,
            "comparison": pd.DataFrame(),
            "lr_tests": pd.DataFrame(),
            "recommendation": {"model": "", "tier": "not_available", "rationale": ""},
            "caveat": "",
            "fit_times": {},
        }

    config = res.get("config", {})
    current_model = str(config.get("model", "")).upper()
    step_facet = _select_first_polytomous_facet(res)
    slope_facet = config.get("slope_facet") or step_facet

    import time

    model_results: dict[str, dict] = {}
    fit_times: dict[str, float] = {}

    # Reuse the original fit for its own model row.
    if current_model in _MODEL_CHOICE_CANDIDATES:
        model_results[current_model] = res
        fit_times[current_model] = 0.0

    for candidate in _MODEL_CHOICE_CANDIDATES:
        if candidate in model_results:
            continue
        start = time.perf_counter()
        refit = _refit_candidate_model(
            res, candidate, step_facet=step_facet, slope_facet=slope_facet
        )
        fit_times[candidate] = float(time.perf_counter() - start)
        if refit is None:
            continue
        model_results[candidate] = refit

    rows = []
    for candidate in _MODEL_CHOICE_CANDIDATES:
        if candidate not in model_results:
            rows.append({
                "Model": candidate,
                "N": np.nan,
                "KParams": np.nan,
                "LogLik": np.nan,
                "AIC": np.nan,
                "AICc": np.nan,
                "BIC": np.nan,
                "FitStatus": "refit_failed",
            })
            continue
        cand_res = model_results[candidate]
        summary = cand_res.get("summary", pd.DataFrame())
        n_val = _summary_metric(summary, "N")
        k_val = _summary_metric(summary, "KParams")
        aic_val = _summary_metric(summary, "AIC")
        # AICc finite-sample correction (Hurvich & Tsai, 1989, Eq. 1):
        # AICc = AIC + 2 k (k + 1) / (N - k - 1). Undefined when N - k - 1
        # <= 0; recommended over AIC when N / k < ~40 (Burnham & Anderson
        # 2002, p. 66). Falls back to NaN when any of N, k, or AIC is
        # missing or when the small-sample denominator collapses.
        if (
            np.isfinite(n_val) and np.isfinite(k_val) and np.isfinite(aic_val)
            and n_val > k_val + 1
        ):
            aicc_val = float(aic_val) + 2.0 * float(k_val) * (float(k_val) + 1.0) / (
                float(n_val) - float(k_val) - 1.0
            )
        else:
            aicc_val = np.nan
        rows.append({
            "Model": candidate,
            "N": n_val,
            "KParams": k_val,
            "LogLik": _summary_metric(summary, "LogLik"),
            "AIC": aic_val,
            "AICc": aicc_val,
            "BIC": _summary_metric(summary, "BIC"),
            "FitStatus": (
                "current" if candidate == current_model else "refit_ok"
            ),
        })
    comparison = pd.DataFrame(rows)

    if comparison["AIC"].notna().any():
        min_aic = float(comparison["AIC"].min(skipna=True))
        comparison["DeltaAIC"] = comparison["AIC"] - min_aic
        comparison["AICEvidenceRatio"] = comparison["DeltaAIC"].apply(_model_choice_evidence_ratio)
        comparison["AICWeight"] = _model_choice_information_weights(comparison["DeltaAIC"])
    else:
        comparison["DeltaAIC"] = np.nan
        comparison["AICEvidenceRatio"] = np.nan
        comparison["AICWeight"] = np.nan

    if comparison["AICc"].notna().any():
        min_aicc = float(comparison["AICc"].min(skipna=True))
        comparison["DeltaAICc"] = comparison["AICc"] - min_aicc
        comparison["AICcEvidenceRatio"] = comparison["DeltaAICc"].apply(_model_choice_evidence_ratio)
        comparison["AICcWeight"] = _model_choice_information_weights(comparison["DeltaAICc"])
    else:
        comparison["DeltaAICc"] = np.nan
        comparison["AICcEvidenceRatio"] = np.nan
        comparison["AICcWeight"] = np.nan

    if comparison["BIC"].notna().any():
        min_bic = float(comparison["BIC"].min(skipna=True))
        comparison["DeltaBIC"] = comparison["BIC"] - min_bic
        comparison["BICEvidenceRatio"] = comparison["DeltaBIC"].apply(_model_choice_evidence_ratio)
        comparison["BICWeight"] = _model_choice_information_weights(comparison["DeltaBIC"])
    else:
        comparison["DeltaBIC"] = np.nan
        comparison["BICEvidenceRatio"] = np.nan
        comparison["BICWeight"] = np.nan

    # Compute n / k ratio per row for AICc applicability guidance.
    comparison["N_over_K"] = comparison["N"] / comparison["KParams"]
    comparison["AICcRecommended"] = (
        comparison["N_over_K"] < 40.0
    ).fillna(False)

    comparison = comparison[[
        "Model", "FitStatus", "N", "KParams", "N_over_K", "AICcRecommended",
        "LogLik",
        "AIC", "DeltaAIC", "AICEvidenceRatio", "AICWeight",
        "AICc", "DeltaAICc", "AICcEvidenceRatio", "AICcWeight",
        "BIC", "DeltaBIC", "BICEvidenceRatio", "BICWeight",
    ]]

    method_label = str(config.get("method", "")).upper()
    lr_tests = _model_choice_lr_tests(model_results)
    if isinstance(lr_tests, pd.DataFrame) and not lr_tests.empty:
        lr_tests["InferenceScope"] = (
            "exploratory_screening_jmle"
            if method_label == "JMLE" else
            "large_sample_mml_if_quadrature_prior_constraints_aligned"
        )
    recommendation = _model_choice_recommend(comparison)

    if method_label == "JMLE":
        lr_scope = (
            "For JMLE, LR-test p-values are exploratory screening indices because "
            "person parameters are estimated jointly and GPCM slopes may be on "
            "bounds; do not report them as confirmatory Wilks tests without "
            "bootstrap or cross-validation evidence."
        )
    else:
        lr_scope = (
            "For MML, LR-test p-values are large-sample checks only when the "
            "candidate fits use comparable marginal likelihoods with aligned "
            "quadrature, prior SD, constraints, and no active boundary solutions."
        )
    caveat = (
        "AIC, AICc, and BIC are evaluated on the same data and method; all "
        "three penalise model complexity, with BIC favouring parsimony most "
        "strongly. AICc (Hurvich & Tsai, 1989) is the finite-sample "
        "correction recommended over AIC when N / K < ~40 (Burnham & "
        "Anderson, 2002, p. 66); see the AICcRecommended flag in the "
        f"comparison table. {lr_scope} Refits inherit the original method, "
        "step facet, and slope facet; differences across runs reflect the "
        "model term itself, not the optimizer or the data."
    )

    return {
        "available": True,
        "reason": "",
        "comparison": comparison,
        "lr_tests": lr_tests,
        "recommendation": recommendation,
        "caveat": caveat,
        "fit_times": fit_times,
    }


def extract_run_likelihood_row(output: dict, *, timestamp: str = "", label: str = "") -> dict:
    """Extract one compact likelihood/information-criteria row from a run snapshot."""
    output_dict = output if isinstance(output, dict) else {}
    result = output_dict.get("result", {})
    summary = result.get("summary") if isinstance(result, dict) else None
    config = result.get("config", {}) if isinstance(result, dict) and isinstance(result.get("config", {}), dict) else {}
    row = summary.iloc[0] if isinstance(summary, pd.DataFrame) and not summary.empty else {}
    model = str(row.get("Model", output_dict.get("model_type", config.get("model", ""))) if isinstance(row, pd.Series) else output_dict.get("model_type", ""))
    method = str(row.get("Method", output_dict.get("_est_method", config.get("method", ""))) if isinstance(row, pd.Series) else output_dict.get("_est_method", ""))
    n_eff = _summary_metric(summary, "N")
    k_params = _summary_metric(summary, "KParams")
    if not np.isfinite(k_params):
        k_params = _safe_float(config.get("parameter_count"))
    loglik = _summary_metric(summary, "LogLik")
    deviance = _summary_metric(summary, "Deviance")
    if not np.isfinite(deviance) and np.isfinite(loglik):
        deviance = -2.0 * loglik
    aic = _summary_metric(summary, "AIC")
    bic = _summary_metric(summary, "BIC")
    penalty_value = _summary_metric(summary, "RegularizationPenalty", default=0.0)
    penalized_objective = _summary_metric(summary, "PenalizedObjective")
    reg_enabled = bool(config.get("facet_regularization_enabled", False)) or bool(np.isfinite(penalty_value) and penalty_value > 0)
    comparability_key = stable_json_fingerprint({
        "model": model,
        "method": method,
        "n": n_eff,
        "input": config.get("input_data_fingerprint"),
        "rating_min": config.get("rating_min"),
        "rating_max": config.get("rating_max"),
        "keep_original": config.get("keep_original"),
        "score_range_explicit": config.get("score_range_explicit"),
        "step_facet": config.get("step_facet"),
        "slope_facet": config.get("slope_facet"),
        "noncenter_facet": config.get("noncenter_facet"),
        "dummy_facets": sorted(map(str, config.get("dummy_facets", []) or [])),
        "positive_facets": sorted(map(str, config.get("positive_facets", []) or [])),
        "anchor_source": config.get("anchor_source_fingerprint"),
        "group_anchor_source": config.get("group_anchor_source_fingerprint"),
        "regularization": config.get("facet_regularization_fingerprint") if reg_enabled else "off",
    })
    return {
        "Label": label,
        "Timestamp": timestamp,
        "Model": model,
        "Method": method,
        "EstimatorLabel": str(row.get("EstimatorLabel", method) if isinstance(row, pd.Series) else method),
        "N": n_eff,
        "KParams": k_params,
        "LogLik": loglik,
        "Deviance": deviance,
        "Regularization": "On" if reg_enabled else "Off",
        "RegularizationPenalty": penalty_value,
        "PenalizedObjective": penalized_objective,
        "RegularizationFingerprint": config.get("facet_regularization_fingerprint") if reg_enabled else "off",
        "ComparabilityKey": comparability_key,
        "AIC": aic,
        "BIC": bic,
        "LogLikPerObs": loglik / n_eff if np.isfinite(loglik) and np.isfinite(n_eff) and n_eff > 0 else np.nan,
        "AICPerObs": aic / n_eff if np.isfinite(aic) and np.isfinite(n_eff) and n_eff > 0 else np.nan,
        "BICPerObs": bic / n_eff if np.isfinite(bic) and np.isfinite(n_eff) and n_eff > 0 else np.nan,
    }


def build_run_history_likelihood_table(history: list[dict]) -> pd.DataFrame:
    """Run-history table with likelihood criteria and delta AIC/BIC."""
    rows = []
    for entry in history or []:
        if not isinstance(entry, dict):
            continue
        output = entry.get("output_snapshot", {})
        if _history_entry_has_snapshot(entry):
            rows.append(extract_run_likelihood_row(
                output,
                timestamp=str(entry.get("timestamp", "")),
                label=str(entry.get("label", "")),
            ))
        else:
            rows.append({
                "Label": str(entry.get("label", "")),
                "Timestamp": str(entry.get("timestamp", "")),
                "Model": entry.get("model", ""),
                "Method": entry.get("method", ""),
                "EstimatorLabel": entry.get("method", ""),
                "N": entry.get("n_obs", np.nan),
                "KParams": entry.get("k_params", np.nan),
                "LogLik": entry.get("loglik", np.nan),
                "Deviance": entry.get("deviance", np.nan),
                "Regularization": entry.get("regularization", ""),
                "AIC": entry.get("aic", np.nan),
                "BIC": entry.get("bic", np.nan),
                "LogLikPerObs": (
                    entry.get("loglik", np.nan) / entry.get("n_obs", np.nan)
                    if pd.notna(entry.get("loglik", np.nan)) and pd.notna(entry.get("n_obs", np.nan))
                    and float(entry.get("n_obs", 0) or 0) > 0
                    else np.nan
                ),
                "AICPerObs": (
                    entry.get("aic", np.nan) / entry.get("n_obs", np.nan)
                    if pd.notna(entry.get("aic", np.nan)) and pd.notna(entry.get("n_obs", np.nan))
                    and float(entry.get("n_obs", 0) or 0) > 0
                    else np.nan
                ),
                "BICPerObs": (
                    entry.get("bic", np.nan) / entry.get("n_obs", np.nan)
                    if pd.notna(entry.get("bic", np.nan)) and pd.notna(entry.get("n_obs", np.nan))
                    and float(entry.get("n_obs", 0) or 0) > 0
                    else np.nan
                ),
                "ComparableIC": False,
            })
    out = pd.DataFrame(rows)
    if out.empty:
        return out
    numeric_cols = [
        "N", "KParams", "LogLik", "Deviance", "RegularizationPenalty",
        "PenalizedObjective", "AIC", "BIC", "LogLikPerObs", "AICPerObs", "BICPerObs",
    ]
    for col in numeric_cols:
        if col in out.columns:
            out[col] = pd.to_numeric(out[col], errors="coerce")
    for metric in ["AIC", "BIC", "Deviance"]:
        if metric in out.columns and out[metric].notna().any():
            out[f"Delta{metric}"] = out[metric] - out[metric].min(skipna=True)
    if "ComparabilityKey" in out.columns:
        keys = set(out["ComparabilityKey"].fillna("").astype(str).tolist())
        out["ComparableIC"] = len(keys) <= 1
    return out


def build_likelihood_descriptives(likelihood_rows: pd.DataFrame) -> pd.DataFrame:
    """Descriptive statistics for likelihood/info criteria across stored runs."""
    if not isinstance(likelihood_rows, pd.DataFrame) or likelihood_rows.empty:
        return pd.DataFrame()
    metric_cols = [
        "LogLik", "Deviance", "RegularizationPenalty", "PenalizedObjective",
        "AIC", "BIC", "LogLikPerObs", "AICPerObs", "BICPerObs",
    ]
    rows = []
    for metric in metric_cols:
        if metric not in likelihood_rows.columns:
            continue
        values = pd.to_numeric(likelihood_rows[metric], errors="coerce").dropna()
        if values.empty:
            continue
        rows.append({
            "Metric": metric,
            "N_Runs": int(values.size),
            "Mean": float(values.mean()),
            "SD": float(values.std(ddof=1)) if values.size >= 2 else np.nan,
            "Min": float(values.min()),
            "Median": float(values.median()),
            "Max": float(values.max()),
            "PreferredDirection": "higher" if metric.startswith("LogLik") else ("context" if "Penalty" in metric else "lower"),
        })
    return pd.DataFrame(rows)


# ── EM algorithm for MML (Bock & Aitkin, 1981) ─────────────────────
def _e_step_posteriors(idx, config, params, quad):
    """E-step: compute posterior weights for each person × quadrature node.

    Returns
    -------
    post_weights : ndarray, shape (n_persons, Q)
        Posterior probabilities  P(θ_q | x_j, δ)  for person j at node q.
    marginal_ll : float
        Current marginal log-likelihood  Σ_j log Σ_q w_q L(x_j|θ_q,δ).

    Reference: Bock, R. D. & Aitkin, M. (1981). Marginal maximum
    likelihood estimation of item parameters: Application of an EM
    algorithm.  Psychometrika, 46(4), 443–459.
    """
    base_eta = compute_base_eta(idx, params, config)
    rows_by_person = idx.get("rows_by_person")
    if rows_by_person is None:
        rows_by_person = [np.where(idx["person"] == p)[0] for p in range(config["n_person"])]

    n_persons = len(rows_by_person)
    Q = len(quad["nodes"])
    log_w = np.log(quad["weights"])                    # (Q,)
    log_lik_mat = np.zeros((n_persons, Q))             # person × node
    pop_mu = compute_population_mu(params, config)

    if config["model"] == "RSM":
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
        for j, rows in enumerate(rows_by_person):
            if len(rows) == 0:
                continue
            base = base_eta[rows]
            score_k = idx["score_k"][rows]
            w = idx.get("weight")[rows] if idx.get("weight") is not None else None
            mu_j = pop_mu[j] if j < len(pop_mu) else 0.0
            for q, theta_q in enumerate(quad["nodes"]):
                log_lik_mat[j, q] = loglik_rsm(mu_j + theta_q + base, score_k, step_cum, weight=w)
    elif config["model"] == "PCM":
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        for j, rows in enumerate(rows_by_person):
            if len(rows) == 0:
                continue
            base = base_eta[rows]
            score_k = idx["score_k"][rows]
            crit = idx["step_idx"][rows]
            w = idx.get("weight")[rows] if idx.get("weight") is not None else None
            mu_j = pop_mu[j] if j < len(pop_mu) else 0.0
            for q, theta_q in enumerate(quad["nodes"]):
                log_lik_mat[j, q] = loglik_pcm(mu_j + theta_q + base, score_k, step_cum_mat, crit, weight=w)
    else:
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        for j, rows in enumerate(rows_by_person):
            if len(rows) == 0:
                continue
            base = base_eta[rows]
            score_k = idx["score_k"][rows]
            step_idx = idx["step_idx"][rows]
            slope_idx_full = idx.get("slope_idx")
            slope_idx = slope_idx_full[rows] if slope_idx_full is not None else step_idx
            w = idx.get("weight")[rows] if idx.get("weight") is not None else None
            mu_j = pop_mu[j] if j < len(pop_mu) else 0.0
            for q, theta_q in enumerate(quad["nodes"]):
                log_lik_mat[j, q] = loglik_gpcm(
                    mu_j + theta_q + base,
                    score_k,
                    step_cum_mat,
                    step_idx,
                    params["slopes"],
                    slope_idx,
                    weight=w,
                )

    # log posterior (unnormalized) = log w_q + log L(x_j | θ_q, δ)
    log_joint = log_w[None, :] + log_lik_mat           # (n_persons, Q)
    log_marginal = logsumexp(log_joint, axis=1)        # (n_persons,)
    log_post = log_joint - log_marginal[:, None]       # normalise per person
    post_weights = np.exp(log_post)                    # (n_persons, Q)

    marginal_ll = float(np.sum(log_marginal))
    return post_weights, marginal_ll


def _m_step_expected_ll(par, idx, config, sizes, quad, post_weights):
    """M-step objective: expected complete-data log-likelihood.

    Q(δ|δ^(t)) = Σ_j Σ_q  r_jq  log L(x_j | θ_q, δ)

    where r_jq = P(θ_q | x_j, δ^(t)) from the E-step.

    This is the function minimised (negated) w.r.t. item/facet
    parameters δ in the M-step.
    """
    params = expand_params(par, sizes, config)
    base_eta = compute_base_eta(idx, params, config)

    rows_by_person = {}
    for i, p_idx in enumerate(idx["person"]):
        rows_by_person.setdefault(p_idx, []).append(i)

    Q = len(quad["nodes"])
    total = 0.0
    pop_mu = compute_population_mu(params, config)

    if config["model"] == "RSM":
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
        for j, rows in enumerate(rows_by_person.values()):
            base = base_eta[rows]
            score_k = idx["score_k"][rows]
            w = idx.get("weight")[rows] if idx.get("weight") is not None else None
            mu_j = pop_mu[j] if j < len(pop_mu) else 0.0
            for q in range(Q):
                r_jq = post_weights[j, q]
                if r_jq < 1e-15:
                    continue
                ll = loglik_rsm(mu_j + quad["nodes"][q] + base, score_k, step_cum, weight=w)
                total += r_jq * ll
    elif config["model"] == "PCM":
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        for j, rows in enumerate(rows_by_person.values()):
            base = base_eta[rows]
            score_k = idx["score_k"][rows]
            crit = idx["step_idx"][rows]
            w = idx.get("weight")[rows] if idx.get("weight") is not None else None
            mu_j = pop_mu[j] if j < len(pop_mu) else 0.0
            for q in range(Q):
                r_jq = post_weights[j, q]
                if r_jq < 1e-15:
                    continue
                ll = loglik_pcm(mu_j + quad["nodes"][q] + base, score_k, step_cum_mat, crit, weight=w)
                total += r_jq * ll
    else:
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        for j, rows in enumerate(rows_by_person.values()):
            base = base_eta[rows]
            score_k = idx["score_k"][rows]
            step_idx = idx["step_idx"][rows]
            slope_idx_full = idx.get("slope_idx")
            slope_idx = slope_idx_full[rows] if slope_idx_full is not None else step_idx
            w = idx.get("weight")[rows] if idx.get("weight") is not None else None
            mu_j = pop_mu[j] if j < len(pop_mu) else 0.0
            for q in range(Q):
                r_jq = post_weights[j, q]
                if r_jq < 1e-15:
                    continue
                ll = loglik_gpcm(
                    mu_j + quad["nodes"][q] + base,
                    score_k,
                    step_cum_mat,
                    step_idx,
                    params["slopes"],
                    slope_idx,
                    weight=w,
                )
                total += r_jq * ll

    return -total


def _m_step_expected_ll_value_grad(par, idx, config, sizes, quad, post_weights):
    params = expand_params(par, sizes, config)
    base_eta = compute_base_eta(idx, params, config)
    score_k = idx["score_k"]
    weight = idx.get("weight")
    if weight is None:
        weight = np.ones_like(score_k, dtype=float)
    else:
        weight = np.asarray(weight, dtype=float)

    k_cat = int(config["n_cat"])
    k_vals = np.arange(k_cat, dtype=float)
    n_steps = max(k_cat - 1, 0)
    thresholds = np.arange(n_steps)
    facet_signs = config.get("facet_signs", {})

    facet_full_grads = {
        facet: np.zeros(len(config["facet_specs"][facet]["levels"]), dtype=float)
        for facet in config["facet_names"]
    }
    pop = config.get("population_model", {})
    pop_X = np.asarray(pop.get("X", np.zeros((int(config.get("n_person", 0)), 0))), dtype=float)
    pop_mu = compute_population_mu(params, config)
    pop_mu_by_obs = pop_mu[idx["person"]] if pop_mu.size else np.zeros(len(score_k), dtype=float)
    pop_grad_full = np.zeros(pop_X.shape[1], dtype=float) if pop.get("enabled") and pop_X.ndim == 2 else np.array([], dtype=float)
    if config["model"] == "RSM":
        step_grad_full = np.zeros(n_steps, dtype=float)
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
    else:
        step_facet_n = len(config["facet_levels"][config["step_facet"]])
        step_grad_full = np.zeros((step_facet_n, n_steps), dtype=float)
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
    if config["model"] == "GPCM":
        slope_idx = idx.get("slope_idx")
        if slope_idx is None:
            slope_idx = idx["step_idx"]
        slope_obs = params["slopes"][slope_idx]
        slope_levels = len(config["facet_levels"][config["slope_facet"]])
        log_slope_grad_full = np.zeros(slope_levels, dtype=float)
    else:
        slope_idx = None
        slope_obs = np.ones(len(score_k), dtype=float)
        log_slope_grad_full = np.array([], dtype=float)

    nll = 0.0
    for q, theta_q in enumerate(quad["nodes"]):
        post_obs = post_weights[idx["person"], q]
        eff_weight = weight * post_obs
        eta = theta_q + pop_mu_by_obs + base_eta

        if config["model"] == "RSM":
            log_num = np.outer(eta, k_vals) - step_cum
            log_denom = logsumexp(log_num, axis=1)
            ll_obs = log_num[np.arange(len(eta)), score_k] - log_denom
            probs = np.exp(log_num - log_denom[:, None])
            nll -= float(np.sum(eff_weight * ll_obs))
            if n_steps > 0:
                observed_gt = score_k[:, None] > thresholds[None, :]
                prob_gt = np.flip(np.cumsum(np.flip(probs[:, 1:], axis=1), axis=1), axis=1)
                step_grad_full += np.sum(eff_weight[:, None] * (observed_gt - prob_gt), axis=0)
        elif config["model"] == "PCM":
            probs = np.zeros((len(eta), k_cat), dtype=float)
            ll_obs = np.zeros(len(eta), dtype=float)
            for c_idx in range(step_cum_mat.shape[0]):
                rows = np.where(idx["step_idx"] == c_idx)[0]
                if rows.size == 0:
                    continue
                log_num = np.outer(eta[rows], k_vals) - step_cum_mat[c_idx]
                log_denom = logsumexp(log_num, axis=1)
                ll_obs[rows] = log_num[np.arange(len(rows)), score_k[rows]] - log_denom
                probs[rows, :] = np.exp(log_num - log_denom[:, None])
                if n_steps > 0:
                    observed_gt = score_k[rows, None] > thresholds[None, :]
                    prob_gt = np.flip(np.cumsum(np.flip(probs[rows, 1:], axis=1), axis=1), axis=1)
                    step_grad_full[c_idx, :] += np.sum(eff_weight[rows, None] * (observed_gt - prob_gt), axis=0)
            nll -= float(np.sum(eff_weight * ll_obs))
        else:
            probs = np.zeros((len(eta), k_cat), dtype=float)
            ll_obs = np.zeros(len(eta), dtype=float)
            linear_all = np.zeros((len(eta), k_cat), dtype=float)
            for c_idx in range(step_cum_mat.shape[0]):
                rows = np.where(idx["step_idx"] == c_idx)[0]
                if rows.size == 0:
                    continue
                linear = np.outer(eta[rows], k_vals) - step_cum_mat[c_idx]
                log_num = slope_obs[rows, None] * linear
                log_denom = logsumexp(log_num, axis=1)
                ll_obs[rows] = log_num[np.arange(len(rows)), score_k[rows]] - log_denom
                probs[rows, :] = np.exp(log_num - log_denom[:, None])
                linear_all[rows, :] = linear
                if n_steps > 0:
                    observed_gt = score_k[rows, None] > thresholds[None, :]
                    prob_gt = np.flip(np.cumsum(np.flip(probs[rows, 1:], axis=1), axis=1), axis=1)
                    step_grad_full[c_idx, :] += np.sum(
                        eff_weight[rows, None] * slope_obs[rows, None] * (observed_gt - prob_gt),
                        axis=0,
                    )
            obs_linear = linear_all[np.arange(len(eta)), score_k]
            expected_linear = np.sum(probs * linear_all, axis=1)
            log_slope_grad_full += np.bincount(
                slope_idx,
                weights=-eff_weight * slope_obs * (obs_linear - expected_linear),
                minlength=slope_levels,
            )
            nll -= float(np.sum(eff_weight * ll_obs))

        expected = probs @ k_vals
        eta_grad = -eff_weight * slope_obs * (score_k - expected)
        for facet in config["facet_names"]:
            sign = facet_signs.get(facet, -1)
            facet_full_grads[facet] += np.bincount(
                idx["facets"][facet],
                weights=eta_grad * sign,
                minlength=len(config["facet_specs"][facet]["levels"]),
            )
        if pop_grad_full.size:
            person_eta_grad = np.bincount(
                idx["person"],
                weights=eta_grad,
                minlength=pop_X.shape[0],
            )
            pop_grad_full += pop_X.T @ person_eta_grad

    grad_parts = []
    if sizes.get("population", 0) > 0:
        grad_parts.append(pop_grad_full)
    for facet in config["facet_names"]:
        if sizes.get(facet, 0) > 0:
            grad_parts.append(collapse_facet_gradient(facet_full_grads[facet], config["facet_specs"][facet]))
    if n_steps > 0:
        if config["model"] == "RSM":
            grad_parts.append(collapse_centered_gradient(step_grad_full))
        else:
            grad_parts.append(np.vstack([collapse_centered_gradient(row) for row in step_grad_full]).reshape(-1))
    if config["model"] == "GPCM" and sizes.get("log_slopes", 0) > 0:
        grad_parts.append(collapse_centered_gradient(log_slope_grad_full))

    grad = np.concatenate([g for g in grad_parts if g.size]) if grad_parts else np.array([], dtype=float)
    if grad.size != len(par):
        raise RuntimeError(f"Internal MML gradient size mismatch: expected {len(par)}, got {grad.size}.")
    penalty_value, penalty_grad = facet_regularization_value_grad(par, sizes, config)
    if config.get("facet_regularization", {}).get("enabled"):
        nll += penalty_value
        grad = grad + penalty_grad
    return nll, grad


def mfrm_em_mml(start, idx, config, sizes, quad, maxit=200, reltol=1e-6):
    """EM algorithm for MML estimation of MFRM parameters.

    Implements the Bock & Aitkin (1981) EM algorithm:
      E-step — compute posterior  P(θ_q | x_j, δ^(t))  for each
               person j at each quadrature node q.
      M-step — maximise expected complete-data log-likelihood
               Q(δ | δ^(t)) = Σ_j Σ_q r_jq log L(x_j | θ_q, δ)
               w.r.t. item/facet parameters δ using analytical-gradient
               L-BFGS-B.

    Parameters
    ----------
    start : ndarray
        Initial parameter vector (facet + step parameters only; no θ).
    idx : dict
        Observation indices from build_indices().
    config : dict
        Model configuration.
    sizes : OrderedDict
        Parameter block sizes.
    quad : dict
        Gauss-Hermite quadrature nodes and weights.
    maxit : int
        Maximum number of EM iterations.
    reltol : float
        Convergence criterion on relative change in marginal LL.

    Returns
    -------
    result : dict with keys
        'x'        — final parameter vector
        'fun'      — final negative marginal log-likelihood
        'success'  — whether convergence was achieved
        'nit'      — number of EM iterations
        'nfev'     — total function evaluations across all M-steps
        'll_trace' — marginal LL at each iteration

    References
    ----------
    Bock, R. D. & Aitkin, M. (1981). Marginal maximum likelihood
        estimation of item parameters: Application of an EM algorithm.
        Psychometrika, 46(4), 443–459.
    Bock, R. D. & Mislevy, R. J. (1982). Adaptive EAP estimation of
        ability in a microcomputer environment. Applied Psychological
        Measurement, 6(4), 431–444.
    """
    par = np.array(start, dtype=float, copy=True)
    params = expand_params(par, sizes, config)

    # Optional free latent-population-SD estimation (Bock-Aitkin variance
    # M-step). Opt-in via config['estimate_population_sd']; when off, the quad
    # below stays the caller's fixed-SD object and this engine is unchanged.
    estimate_sd = bool(config.get("estimate_population_sd", False))
    if estimate_sd:
        quad = dict(quad)  # local mutable copy; never mutate the caller's quad
        n_quad_points = len(quad["nodes"])
        sd_lo, sd_hi = config.get("population_sd_bounds", (0.05, 10.0))
        sigma = float(quad.get("sd", get_population_prior_sd(config)))
        persons_with_obs = np.unique(np.asarray(idx["person"]))
        n_eff = max(int(persons_with_obs.size), 1)
        sigma_trace = [sigma]

    prev_ll = -np.inf
    converged = False
    ll_trace = []
    total_nfev = 0

    for it in range(maxit):
        # ── E-step ──────────────────────────────────────────────
        post_weights, marginal_ll = _e_step_posteriors(idx, config, params, quad)
        ll_trace.append(marginal_ll)

        # ── Convergence check (relative change in marginal LL) ─
        if it > 0:
            rel_change = abs(marginal_ll - prev_ll) / (abs(prev_ll) + 1e-10)
            if rel_change < reltol:
                converged = True
                break
        prev_ll = marginal_ll

        # ── M-step (analytical-gradient L-BFGS-B) ──────────────
        opt = minimize(
            _m_step_expected_ll_value_grad,
            par,
            args=(idx, config, sizes, quad, post_weights),
            jac=True,
            method="L-BFGS-B",
            bounds=build_optimizer_bounds(sizes, config),
            options={"maxiter": 50, "gtol": 1e-5, "ftol": 1e-7},
        )
        par = opt.x
        total_nfev += opt.nfev
        params = expand_params(par, sizes, config)

        # ── Population-variance M-step (Bock-Aitkin) ───────────
        # sigma^2 = (1/n_eff) Σ_j Σ_q post[j,q] · node_q^2, where node_q is the
        # quadrature deviation (theta_jq − mu_j). Rebuild the grid at the new
        # sigma so the next E-step integrates over N(mu_j, sigma^2). ML/EM
        # divide-by-N keeps EM monotone. Empty-person rows are excluded.
        if estimate_sd:
            nodes_sq = (quad["nodes"] ** 2)[None, :]
            sigma2_new = float(np.sum(post_weights[persons_with_obs] * nodes_sq) / n_eff)
            sigma = float(np.clip(np.sqrt(max(sigma2_new, sd_lo ** 2)), sd_lo, sd_hi))
            quad = gauss_hermite_normal(n_quad_points, sd=sigma)
            sigma_trace.append(sigma)

    # Final E-step to get the converged marginal LL
    _, final_ll = _e_step_posteriors(idx, config, params, quad)
    ll_trace.append(final_ll)

    class EMResult:
        """Mimics scipy.optimize.OptimizeResult for compatibility."""
        pass

    result = EMResult()
    result.x = par
    penalty_value, _ = facet_regularization_value_grad(par, sizes, config)
    result.raw_fun = -final_ll
    result.penalty_value = penalty_value
    result.fun = -final_ll + penalty_value
    result.success = converged
    result.nit = len(ll_trace) - 1
    result.nfev = total_nfev
    result.ll_trace = ll_trace
    result.estimated_population_sd = float(sigma) if estimate_sd else None
    result.sigma_trace = sigma_trace if estimate_sd else None
    result.final_quad_sd = float(quad.get("sd")) if estimate_sd else None
    result.message = "EM relative log-likelihood convergence reached." if converged else "EM reached max iterations before relative log-likelihood convergence."
    return result


def compute_person_eap(idx, config, params, quad):
    n = len(idx["score_k"])
    if n == 0:
        return pd.DataFrame(columns=["Person", "Estimate", "SD"])

    base_eta = compute_base_eta(idx, params, config)
    rows_by_person = idx.get("rows_by_person")
    if rows_by_person is None:
        rows_by_person = [np.where(idx["person"] == p)[0] for p in range(config["n_person"])]

    log_w = np.log(quad["weights"])
    pop_mu = compute_population_mu(params, config)
    estimates = []
    if config["model"] == "RSM":
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
        for j, rows in enumerate(rows_by_person):
            base = base_eta[rows]
            score_k = idx["score_k"][rows]
            w = idx.get("weight")[rows] if idx.get("weight") is not None else None
            mu_j = pop_mu[j] if j < len(pop_mu) else 0.0
            theta_nodes = mu_j + quad["nodes"]
            ll_nodes = np.array([loglik_rsm(theta + base, score_k, step_cum, weight=w) for theta in theta_nodes])
            log_post = log_w + ll_nodes
            log_post = log_post - logsumexp(log_post)
            post_w = np.exp(log_post)
            eap = float(np.sum(theta_nodes * post_w))
            sd = float(np.sqrt(np.sum((theta_nodes - eap) ** 2 * post_w)))
            estimates.append((eap, sd))
    elif config["model"] == "PCM":
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        for j, rows in enumerate(rows_by_person):
            base = base_eta[rows]
            score_k = idx["score_k"][rows]
            crit = idx["step_idx"][rows]
            w = idx.get("weight")[rows] if idx.get("weight") is not None else None
            mu_j = pop_mu[j] if j < len(pop_mu) else 0.0
            theta_nodes = mu_j + quad["nodes"]
            ll_nodes = np.array([loglik_pcm(theta + base, score_k, step_cum_mat, crit, weight=w) for theta in theta_nodes])
            log_post = log_w + ll_nodes
            log_post = log_post - logsumexp(log_post)
            post_w = np.exp(log_post)
            eap = float(np.sum(theta_nodes * post_w))
            sd = float(np.sqrt(np.sum((theta_nodes - eap) ** 2 * post_w)))
            estimates.append((eap, sd))
    else:
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        for j, rows in enumerate(rows_by_person):
            base = base_eta[rows]
            score_k = idx["score_k"][rows]
            step_idx = idx["step_idx"][rows]
            slope_idx_full = idx.get("slope_idx")
            slope_idx = slope_idx_full[rows] if slope_idx_full is not None else step_idx
            w = idx.get("weight")[rows] if idx.get("weight") is not None else None
            mu_j = pop_mu[j] if j < len(pop_mu) else 0.0
            theta_nodes = mu_j + quad["nodes"]
            ll_nodes = np.array([
                loglik_gpcm(theta + base, score_k, step_cum_mat, step_idx, params["slopes"], slope_idx, weight=w)
                for theta in theta_nodes
            ])
            log_post = log_w + ll_nodes
            log_post = log_post - logsumexp(log_post)
            post_w = np.exp(log_post)
            eap = float(np.sum(theta_nodes * post_w))
            sd = float(np.sqrt(np.sum((theta_nodes - eap) ** 2 * post_w)))
            estimates.append((eap, sd))

    est_mat = np.array(estimates)
    return pd.DataFrame({"Estimate": est_mat[:, 0], "SD": est_mat[:, 1]})


def _weighted_quantile_from_grid(nodes: np.ndarray, weights: np.ndarray, probs=(0.05, 0.5, 0.95)) -> list[float]:
    order = np.argsort(nodes)
    x = np.asarray(nodes, dtype=float)[order]
    w = np.asarray(weights, dtype=float)[order]
    total = float(np.sum(w))
    if total <= 0 or not np.isfinite(total):
        return [np.nan for _ in probs]
    cdf = np.cumsum(w / total)
    return [float(x[min(np.searchsorted(cdf, p, side="left"), len(x) - 1)]) for p in probs]


def compute_person_posterior_outputs(
    idx,
    config,
    params,
    quad,
    person_levels=None,
    n_plausible_values=0,
    seed=20260411,
):
    """MML person posterior summaries and optional plausible-value draws."""
    if config.get("method") != "MML":
        return {
            "available": False,
            "reason": "Posterior scoring and plausible values are defined for MML runs only.",
            "scores": pd.DataFrame(),
            "plausible_values": pd.DataFrame(),
        }

    n = len(idx["score_k"])
    n_person = int(config.get("n_person", 0))
    if n_person <= 0:
        return {
            "available": False,
            "reason": "No persons available for posterior scoring.",
            "scores": pd.DataFrame(),
            "plausible_values": pd.DataFrame(),
        }

    if person_levels is None:
        person_levels = [str(i) for i in range(n_person)]

    base_eta = compute_base_eta(idx, params, config)
    rows_by_person = idx.get("rows_by_person")
    if rows_by_person is None:
        rows_by_person = [np.where(idx["person"] == p)[0] for p in range(n_person)]

    log_w = np.log(quad["weights"])
    rng = np.random.default_rng(int(seed))
    n_pv = max(0, int(n_plausible_values or 0))
    score_rows: list[dict] = []
    pv_rows: list[dict] = []
    pop_mu = compute_population_mu(params, config)

    if config["model"] == "RSM":
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
    else:
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])

    for p_idx, rows in enumerate(rows_by_person):
        base = base_eta[rows]
        score_k = idx["score_k"][rows]
        weight = idx.get("weight")[rows] if idx.get("weight") is not None else None
        mu_j = pop_mu[p_idx] if p_idx < len(pop_mu) else 0.0
        theta_nodes = mu_j + quad["nodes"]
        if config["model"] == "RSM":
            ll_nodes = np.array([loglik_rsm(theta + base, score_k, step_cum, weight=weight) for theta in theta_nodes])
        elif config["model"] == "PCM":
            crit = idx["step_idx"][rows]
            ll_nodes = np.array([loglik_pcm(theta + base, score_k, step_cum_mat, crit, weight=weight) for theta in theta_nodes])
        else:
            step_idx = idx["step_idx"][rows]
            slope_idx_full = idx.get("slope_idx")
            slope_idx = slope_idx_full[rows] if slope_idx_full is not None else step_idx
            ll_nodes = np.array([
                loglik_gpcm(theta + base, score_k, step_cum_mat, step_idx, params["slopes"], slope_idx, weight=weight)
                for theta in theta_nodes
            ])
        log_post = log_w + ll_nodes
        log_post = log_post - logsumexp(log_post)
        post_w = np.exp(log_post)
        eap = float(np.sum(theta_nodes * post_w))
        sd = float(np.sqrt(np.sum((theta_nodes - eap) ** 2 * post_w)))
        q05, q50, q95 = _weighted_quantile_from_grid(theta_nodes, post_w, probs=(0.05, 0.5, 0.95))
        map_theta = float(theta_nodes[int(np.argmax(post_w))])
        person_id = person_levels[p_idx] if p_idx < len(person_levels) else str(p_idx)
        row_weight = float(np.sum(weight)) if weight is not None else float(len(rows))
        score_rows.append({
            "Person": person_id,
            "PosteriorMean": eap,
            "PosteriorSD": sd,
            "PosteriorMedian": q50,
            "PosteriorQ05": q05,
            "PosteriorQ95": q95,
            "PosteriorMAPGrid": map_theta,
            "PopulationMean": float(mu_j),
            "ObservedRows": int(len(rows)),
            "ObservedWeight": row_weight,
        })
        if n_pv > 0:
            draws = rng.choice(np.asarray(theta_nodes, dtype=float), size=n_pv, replace=True, p=post_w / np.sum(post_w))
            pv_rows.append({
                "Person": person_id,
                **{f"PV_{i + 1}": float(draws[i]) for i in range(n_pv)},
            })

    return {
        "available": True,
        "reason": "Posterior scores computed from the MML quadrature posterior.",
        "scores": pd.DataFrame(score_rows),
        "plausible_values": pd.DataFrame(pv_rows),
        "n_plausible_values": n_pv,
        "seed": int(seed),
        "interpretation": (
            "PosteriorMean is the EAP person score. Plausible values are random draws "
            "from each person's posterior distribution and are intended for group-level "
            "uncertainty propagation, not for ranking individual persons."
        ),
    }


def normalize_anchor_df(df):
    if df is None or df.empty:
        return pd.DataFrame()
    nm = [c.lower() for c in df.columns]
    facet_col = next((i for i, c in enumerate(nm) if c in ("facet", "facets")), None)
    level_col = next((i for i, c in enumerate(nm) if c in ("level", "element", "label")), None)
    anchor_col = next((i for i, c in enumerate(nm) if c in ("anchor", "value", "measure")), None)
    if facet_col is None or level_col is None or anchor_col is None:
        return pd.DataFrame()
    out = pd.DataFrame({
        "Facet": df.iloc[:, facet_col].astype(str),
        "Level": df.iloc[:, level_col].astype(str),
        "Anchor": pd.to_numeric(df.iloc[:, anchor_col], errors="coerce"),
    })
    return out.dropna(subset=["Facet", "Level"])


def normalize_group_anchor_df(df):
    if df is None or df.empty:
        return pd.DataFrame()
    nm = [c.lower() for c in df.columns]
    facet_col = next((i for i, c in enumerate(nm) if c in ("facet", "facets")), None)
    level_col = next((i for i, c in enumerate(nm) if c in ("level", "element", "label")), None)
    group_col = next((i for i, c in enumerate(nm) if c in ("group", "subset")), None)
    value_col = next((i for i, c in enumerate(nm) if c in ("groupvalue", "value", "anchor")), None)
    if facet_col is None or level_col is None or group_col is None or value_col is None:
        return pd.DataFrame()
    out = pd.DataFrame({
        "Facet": df.iloc[:, facet_col].astype(str),
        "Level": df.iloc[:, level_col].astype(str),
        "Group": df.iloc[:, group_col].astype(str),
        "GroupValue": pd.to_numeric(df.iloc[:, value_col], errors="coerce"),
    })
    return out.dropna(subset=["Facet", "Level", "Group"])


def audit_mfrm_anchors(
    prep,
    anchor_df=None,
    group_anchor_df=None,
    dummy_facets=None,
    min_common_anchors=2,
    min_obs_per_element=2,
    min_obs_per_category=1,
):
    """Audit anchor inputs before they are used for scale constraints."""
    all_facets = ["Person"] + prep["facet_names"]
    dummy_facets = set(dummy_facets or [])
    levels_map = {facet: set(map(str, prep["levels"].get(facet, []))) for facet in all_facets}

    data = prep.get("data", pd.DataFrame())
    if not data.empty:
        element_counts = {}
        for facet in all_facets:
            if facet in data.columns:
                element_counts[facet] = data.groupby(facet, observed=False)["Score"].size().to_dict()
            else:
                element_counts[facet] = {}
        cat_counts = data["Score"].value_counts().to_dict() if "Score" in data.columns else {}
    else:
        element_counts = {facet: {} for facet in all_facets}
        cat_counts = {}

    issues: list[dict] = []
    anchor_norm = normalize_anchor_df(anchor_df) if anchor_df is not None else pd.DataFrame()
    group_norm = normalize_group_anchor_df(group_anchor_df) if group_anchor_df is not None else pd.DataFrame()

    if anchor_df is not None and not getattr(anchor_df, "empty", True) and anchor_norm.empty:
        issues.append({
            "Severity": "error",
            "Type": "anchor_format",
            "Facet": "",
            "Level": "",
            "Message": "Anchor table could not be parsed. Required columns: Facet, Level, Anchor.",
            "Action": "Rename columns or paste a CSV with Facet,Level,Anchor.",
        })
    if group_anchor_df is not None and not getattr(group_anchor_df, "empty", True) and group_norm.empty:
        issues.append({
            "Severity": "error",
            "Type": "group_anchor_format",
            "Facet": "",
            "Level": "",
            "Message": "Group-anchor table could not be parsed. Required columns: Facet, Level, Group, GroupValue.",
            "Action": "Rename columns or paste a CSV with Facet,Level,Group,GroupValue.",
        })

    valid_anchor_rows = []
    if not anchor_norm.empty:
        dup_mask = anchor_norm.duplicated(subset=["Facet", "Level"], keep="last")
        for row in anchor_norm[dup_mask].itertuples(index=False):
            issues.append({
                "Severity": "warning",
                "Type": "duplicate_anchor",
                "Facet": row.Facet,
                "Level": row.Level,
                "Message": "Duplicate anchor row detected; the last value will be used.",
                "Action": "Keep only one anchor value per Facet x Level for reproducibility.",
            })
        anchor_work = anchor_norm.drop_duplicates(subset=["Facet", "Level"], keep="last")
        for row in anchor_work.itertuples(index=False):
            facet = str(row.Facet)
            level = str(row.Level)
            if facet not in all_facets:
                issues.append({
                    "Severity": "warning",
                    "Type": "unknown_facet",
                    "Facet": facet,
                    "Level": level,
                    "Message": "Anchor references a facet that is not in the current model; it will be ignored.",
                    "Action": "Check spelling or include that facet in the model.",
                })
                continue
            if level not in levels_map[facet]:
                issues.append({
                    "Severity": "warning",
                    "Type": "unknown_level",
                    "Facet": facet,
                    "Level": level,
                    "Message": "Anchor references a level not observed in the current data; it will be ignored.",
                    "Action": "Check spelling or use a dataset containing this level.",
                })
                continue
            if not np.isfinite(row.Anchor):
                issues.append({
                    "Severity": "warning",
                    "Type": "invalid_anchor_value",
                    "Facet": facet,
                    "Level": level,
                    "Message": "Anchor value is missing or non-finite; it will be ignored.",
                    "Action": "Provide a finite logit value.",
                })
                continue
            n_level = int(element_counts.get(facet, {}).get(level, 0))
            if n_level < int(min_obs_per_element):
                issues.append({
                    "Severity": "warning",
                    "Type": "low_anchor_observations",
                    "Facet": facet,
                    "Level": level,
                    "Message": f"Anchored level has only {n_level} observation(s).",
                    "Action": "Treat this anchor cautiously or add more linked observations.",
                })
            valid_anchor_rows.append({"Facet": facet, "Level": level, "Anchor": float(row.Anchor)})

    valid_group_rows = []
    if not group_norm.empty:
        dup_mask = group_norm.duplicated(subset=["Facet", "Level"], keep="last")
        for row in group_norm[dup_mask].itertuples(index=False):
            issues.append({
                "Severity": "warning",
                "Type": "duplicate_group_anchor",
                "Facet": row.Facet,
                "Level": row.Level,
                "Message": "Duplicate group-anchor row detected; the last value will be used.",
                "Action": "Keep only one group assignment per Facet x Level.",
            })
        group_work = group_norm.drop_duplicates(subset=["Facet", "Level"], keep="last")
        for row in group_work.itertuples(index=False):
            facet = str(row.Facet)
            level = str(row.Level)
            group = str(row.Group)
            if facet not in all_facets:
                issues.append({
                    "Severity": "warning",
                    "Type": "unknown_group_facet",
                    "Facet": facet,
                    "Level": level,
                    "Message": "Group anchor references a facet that is not in the current model; it will be ignored.",
                    "Action": "Check spelling or include that facet in the model.",
                })
                continue
            if level not in levels_map[facet]:
                issues.append({
                    "Severity": "warning",
                    "Type": "unknown_group_level",
                    "Facet": facet,
                    "Level": level,
                    "Message": "Group anchor references a level not observed in the current data; it will be ignored.",
                    "Action": "Check spelling or use a dataset containing this level.",
                })
                continue
            valid_group_rows.append({
                "Facet": facet,
                "Level": level,
                "Group": group,
                "GroupValue": float(row.GroupValue) if np.isfinite(row.GroupValue) else 0.0,
            })

    valid_anchor_df = pd.DataFrame(valid_anchor_rows, columns=["Facet", "Level", "Anchor"])
    valid_group_df = pd.DataFrame(valid_group_rows, columns=["Facet", "Level", "Group", "GroupValue"])

    summary_rows = []
    for facet in all_facets:
        n_levels = len(levels_map[facet])
        n_anch = int((valid_anchor_df["Facet"] == facet).sum()) if not valid_anchor_df.empty else 0
        n_group_levels = int((valid_group_df["Facet"] == facet).sum()) if not valid_group_df.empty else 0
        n_groups = int(valid_group_df.loc[valid_group_df["Facet"] == facet, "Group"].nunique()) if not valid_group_df.empty else 0
        anchored_total = n_anch + n_group_levels + (n_levels if facet in dummy_facets else 0)
        if facet in dummy_facets:
            status = "Dummy"
            action = "Facet fixed at 0 by dummy-facet setting."
        elif anchored_total == 0:
            status = "Unanchored"
            action = "OK for a single-run analysis; add anchors only for linking across runs."
        elif anchored_total < int(min_common_anchors):
            status = "Weak link"
            action = f"Use at least {min_common_anchors} common anchored levels when making linking claims."
            issues.append({
                "Severity": "warning",
                "Type": "few_common_anchors",
                "Facet": facet,
                "Level": "",
                "Message": f"Only {anchored_total} anchored/common level(s) available for this facet.",
                "Action": action,
            })
        else:
            status = "Linked"
            action = "Anchor count is adequate for a first linking screen; still inspect content match and fit."
        summary_rows.append({
            "Facet": facet,
            "Levels": n_levels,
            "FixedAnchors": n_anch,
            "GroupAnchoredLevels": n_group_levels,
            "Groups": n_groups,
            "DummyFacet": facet in dummy_facets,
            "Status": status,
            "Action": action,
        })

    for cat, cnt in sorted(cat_counts.items()):
        if int(cnt) < int(min_obs_per_category):
            issues.append({
                "Severity": "warning",
                "Type": "low_category_count",
                "Facet": "Score",
                "Level": str(cat),
                "Message": f"Score category {cat} has only {int(cnt)} observation(s).",
                "Action": "Threshold and anchor-based linking diagnostics may be unstable for sparse categories.",
            })

    issues_df = pd.DataFrame(issues, columns=["Severity", "Type", "Facet", "Level", "Message", "Action"])
    summary_df = pd.DataFrame(summary_rows)
    n_error = int((issues_df["Severity"] == "error").sum()) if not issues_df.empty else 0
    n_warning = int((issues_df["Severity"] == "warning").sum()) if not issues_df.empty else 0
    overall_status = "error" if n_error else ("warning" if n_warning else "ok")
    linking_review = {
        "overall_status": overall_status,
        "message": (
            "Anchor audit found error(s). Fix anchor inputs before estimating."
            if n_error else
            "Anchor audit found warning(s). Review before making linking claims."
            if n_warning else
            "Anchor audit found no obvious anchor-input issues."
        ),
        "summary": summary_df,
        "issues": issues_df,
        "valid_anchors": valid_anchor_df,
        "valid_group_anchors": valid_group_df,
        "settings": {
            "min_common_anchors": int(min_common_anchors),
            "min_obs_per_element": int(min_obs_per_element),
            "min_obs_per_category": int(min_obs_per_category),
        },
    }
    return linking_review


def prepare_constraint_specs(prep, anchor_df=None, group_anchor_df=None, noncenter_facet="Person", dummy_facets=None):
    facet_names = prep["facet_names"]
    all_facets = ["Person"] + facet_names

    anchor_df = normalize_anchor_df(anchor_df) if anchor_df is not None else pd.DataFrame()
    anchor_df = anchor_df[anchor_df["Facet"].isin(all_facets)] if not anchor_df.empty else anchor_df

    group_anchor_df = normalize_group_anchor_df(group_anchor_df) if group_anchor_df is not None else pd.DataFrame()
    group_anchor_df = group_anchor_df[group_anchor_df["Facet"].isin(all_facets)] if not group_anchor_df.empty else group_anchor_df

    dummy_facets = set(dummy_facets or [])

    anchor_map = {facet: {} for facet in all_facets}
    group_map = {facet: {} for facet in all_facets}
    group_values = {facet: {} for facet in all_facets}

    for facet in all_facets:
        levels = prep["levels"].get(facet, [])
        if facet in dummy_facets:
            anchor_map[facet] = {level: 0.0 for level in levels}
            group_map[facet] = {}
            group_values[facet] = {}
            continue
        if not anchor_df.empty:
            df = anchor_df[anchor_df["Facet"] == facet]
            if not df.empty:
                anchors = {row.Level: row.Anchor for row in df.itertuples() if row.Level in levels}
                anchor_map[facet] = anchors
        if not group_anchor_df.empty:
            df = group_anchor_df[group_anchor_df["Facet"] == facet]
            if not df.empty:
                groups = {row.Level: row.Group for row in df.itertuples() if row.Level in levels}
                group_map[facet] = groups
                group_vals = (
                    df[["Group", "GroupValue"]]
                    .dropna(subset=["Group"])
                    .drop_duplicates(subset=["Group"])
                    .assign(GroupValue=lambda x: x["GroupValue"].fillna(0))
                )
                group_values[facet] = {row.Group: row.GroupValue for row in group_vals.itertuples()}

    theta_spec = build_facet_constraint(
        levels=prep["levels"]["Person"],
        anchors=anchor_map["Person"],
        groups=group_map["Person"],
        group_values=group_values["Person"],
        centered=noncenter_facet != "Person",
    )

    facet_specs = {}
    for facet in facet_names:
        facet_specs[facet] = build_facet_constraint(
            levels=prep["levels"][facet],
            anchors=anchor_map[facet],
            groups=group_map[facet],
            group_values=group_values[facet],
            centered=noncenter_facet != facet,
        )

    anchor_summary = pd.DataFrame({
        "Facet": all_facets,
        "AnchoredLevels": [len(anchor_map[f]) for f in all_facets],
        "GroupAnchors": [len(set(group_map[f].values())) if group_map[f] else 0 for f in all_facets],
        "DummyFacet": [f in dummy_facets for f in all_facets],
    })

    return {
        "theta_spec": theta_spec,
        "facet_specs": facet_specs,
        "anchor_summary": anchor_summary,
    }


def _combined_measure_table_for_linking(result: dict) -> pd.DataFrame:
    facets = result.get("facets", {})
    frames = []
    person_tbl = facets.get("person", pd.DataFrame()) if isinstance(facets, dict) else pd.DataFrame()
    if isinstance(person_tbl, pd.DataFrame) and {"Person", "Estimate"}.issubset(person_tbl.columns):
        frames.append(pd.DataFrame({
            "Facet": "Person",
            "Level": person_tbl["Person"].astype(str),
            "Estimate": pd.to_numeric(person_tbl["Estimate"], errors="coerce"),
        }))
    other_tbl = facets.get("others", pd.DataFrame()) if isinstance(facets, dict) else pd.DataFrame()
    if isinstance(other_tbl, pd.DataFrame) and {"Facet", "Level", "Estimate"}.issubset(other_tbl.columns):
        frames.append(pd.DataFrame({
            "Facet": other_tbl["Facet"].astype(str),
            "Level": other_tbl["Level"].astype(str),
            "Estimate": pd.to_numeric(other_tbl["Estimate"], errors="coerce"),
        }))
    if not frames:
        return pd.DataFrame(columns=["Facet", "Level", "Estimate"])
    return pd.concat(frames, ignore_index=True)


def build_anchor_drift_review(result: dict, tolerance: float | None = None, warning_abs: float = 0.05) -> dict:
    """Post-fit anchor consistency screen.

    Because this app uses anchor inputs as hard constraints, this is not an
    empirical unconstrained drift estimate. It verifies that the fitted scale
    respects the supplied baseline anchors and group-anchor target means.
    """
    config = result.get("config", {})
    audit = config.get("anchor_audit", {})
    if not isinstance(audit, dict):
        return {
            "available": False,
            "reason": "No anchor audit is available.",
            "summary": pd.DataFrame(),
            "anchor_drift": pd.DataFrame(),
            "group_drift": pd.DataFrame(),
        }
    valid_anchors = audit.get("valid_anchors", pd.DataFrame())
    valid_groups = audit.get("valid_group_anchors", pd.DataFrame())
    has_anchors = isinstance(valid_anchors, pd.DataFrame) and not valid_anchors.empty
    has_groups = isinstance(valid_groups, pd.DataFrame) and not valid_groups.empty
    if not has_anchors and not has_groups:
        return {
            "available": False,
            "reason": "No fixed anchors or group anchors were supplied for this run.",
            "summary": pd.DataFrame(),
            "anchor_drift": pd.DataFrame(),
            "group_drift": pd.DataFrame(),
            "scope": "post_fit_constraint_check_only",
        }

    tol = float(tolerance) if tolerance is not None else max(1e-6, 10.0 * float(config.get("reltol") or 1e-6))
    measures = _combined_measure_table_for_linking(result)
    anchor_tbl = pd.DataFrame()
    if has_anchors:
        anchor_tbl = valid_anchors.copy()
        anchor_tbl["Facet"] = anchor_tbl["Facet"].astype(str)
        anchor_tbl["Level"] = anchor_tbl["Level"].astype(str)
        anchor_tbl["Anchor"] = pd.to_numeric(anchor_tbl["Anchor"], errors="coerce")
        anchor_tbl = anchor_tbl.merge(measures, on=["Facet", "Level"], how="left")
        anchor_tbl["Drift"] = anchor_tbl["Estimate"] - anchor_tbl["Anchor"]
        anchor_tbl["AbsDrift"] = anchor_tbl["Drift"].abs()
        anchor_tbl["Tolerance"] = tol
        anchor_tbl["Status"] = "Constraint ok"
        anchor_tbl.loc[anchor_tbl["Estimate"].isna(), "Status"] = "Missing estimate"
        anchor_tbl.loc[
            anchor_tbl["Estimate"].notna() & (anchor_tbl["AbsDrift"] > tol) & (anchor_tbl["AbsDrift"] <= float(warning_abs)),
            "Status",
        ] = "Small numerical drift"
        anchor_tbl.loc[
            anchor_tbl["Estimate"].notna() & (anchor_tbl["AbsDrift"] > float(warning_abs)),
            "Status",
        ] = "Review"
        anchor_tbl["Scope"] = "Constrained anchor consistency check"
        anchor_tbl["Action"] = np.where(
            anchor_tbl["Status"].eq("Constraint ok"),
            "No action needed; this verifies the hard anchor constraint.",
            "Check anchor spelling, duplicate inputs, and optimizer convergence before making linking claims.",
        )

    group_tbl = pd.DataFrame()
    if has_groups:
        group_rows = valid_groups.copy()
        group_rows["Facet"] = group_rows["Facet"].astype(str)
        group_rows["Level"] = group_rows["Level"].astype(str)
        group_rows["Group"] = group_rows["Group"].astype(str)
        group_rows["GroupValue"] = pd.to_numeric(group_rows["GroupValue"], errors="coerce").fillna(0.0)
        group_rows = group_rows.merge(measures, on=["Facet", "Level"], how="left")
        group_tbl = (
            group_rows.groupby(["Facet", "Group"], dropna=False)
            .agg(
                GroupValue=("GroupValue", "first"),
                Levels=("Level", "nunique"),
                EstimatedMean=("Estimate", "mean"),
                EstimatedSD=("Estimate", "std"),
                MissingEstimates=("Estimate", lambda x: int(pd.to_numeric(x, errors="coerce").isna().sum())),
            )
            .reset_index()
        )
        group_tbl["MeanDrift"] = group_tbl["EstimatedMean"] - group_tbl["GroupValue"]
        group_tbl["AbsMeanDrift"] = group_tbl["MeanDrift"].abs()
        group_tbl["Tolerance"] = tol
        group_tbl["Status"] = "Group target ok"
        group_tbl.loc[group_tbl["MissingEstimates"] > 0, "Status"] = "Missing estimate"
        group_tbl.loc[
            group_tbl["EstimatedMean"].notna() & (group_tbl["AbsMeanDrift"] > tol) & (group_tbl["AbsMeanDrift"] <= float(warning_abs)),
            "Status",
        ] = "Small numerical drift"
        group_tbl.loc[
            group_tbl["EstimatedMean"].notna() & (group_tbl["AbsMeanDrift"] > float(warning_abs)),
            "Status",
        ] = "Review"
        group_tbl["Scope"] = "Group-anchor mean consistency check"
        group_tbl["Action"] = np.where(
            group_tbl["Status"].eq("Group target ok"),
            "No action needed; the group target mean is respected.",
            "Check group-anchor values and convergence before making group-linking claims.",
        )

    max_anchor = float(pd.to_numeric(anchor_tbl.get("AbsDrift", pd.Series(dtype=float)), errors="coerce").max()) if not anchor_tbl.empty else np.nan
    max_group = float(pd.to_numeric(group_tbl.get("AbsMeanDrift", pd.Series(dtype=float)), errors="coerce").max()) if not group_tbl.empty else np.nan
    review_count = 0
    if not anchor_tbl.empty:
        review_count += int(anchor_tbl["Status"].isin(["Review", "Missing estimate"]).sum())
    if not group_tbl.empty:
        review_count += int(group_tbl["Status"].isin(["Review", "Missing estimate"]).sum())
    summary = pd.DataFrame([{
        "Available": True,
        "ExplicitAnchors": int(len(valid_anchors)) if has_anchors else 0,
        "GroupAnchorLevels": int(len(valid_groups)) if has_groups else 0,
        "MaxAbsAnchorDrift": max_anchor,
        "MaxAbsGroupMeanDrift": max_group,
        "Tolerance": tol,
        "ReviewCount": review_count,
        "Status": "Ready" if review_count == 0 else "Review",
        "Scope": "post_fit_constraint_check_only",
        "Action": (
            "Anchor constraints are internally consistent; this does not prove empirical invariance."
            if review_count == 0 else
            "Resolve anchor consistency warnings before using this run for linking."
        ),
    }])
    return {
        "available": True,
        "reason": "Anchor drift review is a post-fit constraint consistency check for the supplied anchors.",
        "summary": summary,
        "anchor_drift": anchor_tbl,
        "group_drift": group_tbl,
        "scope": "post_fit_constraint_check_only",
        "empirical_unconstrained_drift_available": False,
    }


def build_equating_chain_summary(result: dict) -> dict:
    """Single-run linking-chain summary from anchor and group-anchor inputs."""
    config = result.get("config", {})
    audit = config.get("anchor_audit", {})
    if not isinstance(audit, dict):
        return {
            "available": False,
            "reason": "No anchor audit is available.",
            "summary": pd.DataFrame(),
            "edges": pd.DataFrame(),
        }
    audit_summary = audit.get("summary", pd.DataFrame())
    if not isinstance(audit_summary, pd.DataFrame) or audit_summary.empty:
        return {
            "available": False,
            "reason": "Anchor summary is unavailable.",
            "summary": pd.DataFrame(),
            "edges": pd.DataFrame(),
        }
    min_common = int(audit.get("settings", {}).get("min_common_anchors", 2))
    rows = []
    edges = []
    for row in audit_summary.itertuples(index=False):
        facet = str(getattr(row, "Facet", ""))
        levels = int(getattr(row, "Levels", 0) or 0)
        fixed = int(getattr(row, "FixedAnchors", 0) or 0)
        group_levels = int(getattr(row, "GroupAnchoredLevels", 0) or 0)
        groups = int(getattr(row, "Groups", 0) or 0)
        dummy = bool(getattr(row, "DummyFacet", False))
        common = fixed + group_levels + (levels if dummy else 0)
        coverage = (common / levels) if levels > 0 else np.nan
        if dummy:
            link_type = "Dummy facet"
        elif fixed and group_levels:
            link_type = "Fixed + group anchors"
        elif fixed:
            link_type = "Fixed anchors"
        elif group_levels:
            link_type = "Group anchors"
        else:
            link_type = "None"
        if dummy or common >= min_common:
            strength = "Linked" if common > 0 else "Unanchored"
        elif common > 0:
            strength = "Weak link"
        else:
            strength = "Unanchored"
        action = (
            "Do not make cross-run linking claims from this facet alone; add common anchors or group anchors."
            if strength == "Unanchored" else
            f"Add at least {min_common - common} more common anchored level(s) before strong linking claims."
            if strength == "Weak link" else
            "Use with anchor drift and content-match review before reporting linked results."
        )
        rows.append({
            "Facet": facet,
            "Levels": levels,
            "LinkType": link_type,
            "CommonLinkedLevels": common,
            "FixedAnchors": fixed,
            "GroupAnchoredLevels": group_levels,
            "Groups": groups,
            "Coverage": coverage,
            "MinimumCommonAnchors": min_common,
            "Strength": strength,
            "Action": action,
        })
        if common > 0:
            edges.append({
                "From": "Current run",
                "To": f"Anchor baseline via {facet}",
                "Facet": facet,
                "LinkType": link_type,
                "CommonLinkedLevels": common,
                "Strength": strength,
                "Action": action,
            })

    summary = pd.DataFrame(rows)
    edges_df = pd.DataFrame(edges, columns=[
        "From", "To", "Facet", "LinkType", "CommonLinkedLevels", "Strength", "Action",
    ])
    available = not edges_df.empty
    return {
        "available": available,
        "reason": (
            "Single-run anchor chain summary built from fixed anchors and group anchors."
            if available else "No anchored/common levels were supplied for this run."
        ),
        "summary": summary,
        "edges": edges_df,
        "scope": "single_run_anchor_chain_summary",
        "full_multi_run_chain_available": False,
        "interpretation": (
            "This summarizes how the current run is linked to supplied anchor baselines. "
            "It is not a historical multi-run equating-chain reconstruction."
        ),
    }


def build_anchor_equating_workflow_plan(result: dict) -> pd.DataFrame:
    """Operational anchor/equating checklist for the current Streamlit run."""
    config = result.get("config", {}) if isinstance(result, dict) else {}
    audit = config.get("anchor_audit", {}) if isinstance(config, dict) else {}
    drift = result.get("anchor_drift", {}) if isinstance(result, dict) else {}
    chain = result.get("equating_chain", {}) if isinstance(result, dict) else {}
    rows: list[dict] = []

    if not isinstance(audit, dict):
        return pd.DataFrame([{
            "Step": 1,
            "Check": "Anchor inputs",
            "Status": "Missing",
            "Evidence": "Anchor audit was not recorded for this run.",
            "Action": "Run the model again with current anchor settings before making linking claims.",
        }])

    audit_status = str(audit.get("overall_status", "unknown"))
    audit_summary = audit.get("summary", pd.DataFrame())
    audit_issues = audit.get("issues", pd.DataFrame())
    n_issues = len(audit_issues) if isinstance(audit_issues, pd.DataFrame) else 0
    rows.append({
        "Step": 1,
        "Check": "Anchor input validation",
        "Status": "Ready" if audit_status == "ok" else "Review",
        "Evidence": f"{audit.get('message', 'No audit message.')} Issues: {n_issues}.",
        "Action": "Fix format, spelling, duplicate, sparse, or missing-anchor issues before claiming a linked scale.",
    })

    linked = weak = unanchored = 0
    if isinstance(audit_summary, pd.DataFrame) and not audit_summary.empty:
        chain_summary = chain.get("summary", pd.DataFrame()) if isinstance(chain, dict) else pd.DataFrame()
        if isinstance(chain_summary, pd.DataFrame) and not chain_summary.empty and "Strength" in chain_summary.columns:
            linked = int(chain_summary["Strength"].astype(str).eq("Linked").sum())
            weak = int(chain_summary["Strength"].astype(str).eq("Weak link").sum())
            unanchored = int(chain_summary["Strength"].astype(str).eq("Unanchored").sum())
    common_status = "Ready" if linked > 0 and weak == 0 else "Review" if linked or weak else "Not linked"
    rows.append({
        "Step": 2,
        "Check": "Common-anchor coverage",
        "Status": common_status,
        "Evidence": f"Linked facets: {linked}; weak links: {weak}; unanchored facets: {unanchored}.",
        "Action": "Use at least the configured minimum common anchors per linking facet and document content equivalence.",
    })

    if isinstance(drift, dict) and drift.get("available"):
        drift_summary = drift.get("summary", pd.DataFrame())
        drift_status = "Review"
        evidence = drift.get("reason", "Anchor drift review available.")
        if isinstance(drift_summary, pd.DataFrame) and not drift_summary.empty:
            drift_status = str(drift_summary.get("Status", pd.Series(["Review"])).iloc[0])
            evidence = (
                f"Max fixed-anchor drift: {drift_summary.get('MaxAbsAnchorDrift', pd.Series([np.nan])).iloc[0]}; "
                f"max group mean drift: {drift_summary.get('MaxAbsGroupMeanDrift', pd.Series([np.nan])).iloc[0]}."
            )
        rows.append({
            "Step": 3,
            "Check": "Hard-anchor consistency",
            "Status": "Ready" if drift_status == "Ready" else "Review",
            "Evidence": evidence,
            "Action": "Resolve drift or convergence warnings before reporting linked results.",
        })
    else:
        rows.append({
            "Step": 3,
            "Check": "Hard-anchor consistency",
            "Status": "Not applicable",
            "Evidence": drift.get("reason", "No fixed anchors or group anchors were supplied.") if isinstance(drift, dict) else "No drift review.",
            "Action": "For cross-run linking, supply fixed anchors or group anchors and rerun.",
        })

    chain_available = bool(isinstance(chain, dict) and chain.get("available"))
    rows.append({
        "Step": 4,
        "Check": "Equating-chain scope",
        "Status": "Ready" if chain_available else "Not linked",
        "Evidence": (
            chain.get("interpretation", chain.get("reason", "No chain summary."))
            if isinstance(chain, dict) else "No chain summary."
        ),
        "Action": "Treat this as a current-run link to supplied baselines; keep historical multi-run chain evidence separately.",
    })
    rows.append({
        "Step": 5,
        "Check": "Next-run anchor package",
        "Status": "Ready" if chain_available else "Optional",
        "Evidence": "Downloads include current estimated anchors, anchor audit tables, drift tables, and equating summary when available.",
        "Action": "Export anchors after a vetted run, version the file, and reuse unchanged labels for the next administration.",
    })
    return pd.DataFrame(rows)


def mfrm_estimate(
    data,
    person_col,
    facet_cols,
    score_col,
    rating_min=None,
    rating_max=None,
    weight_col=None,
    keep_original=False,
    model="RSM",
    method="JMLE",
    step_facet=None,
    slope_facet=None,
    person_data=None,
    person_id_col=None,
    population_formula=None,
    population_standardize_numeric=False,
    population_categorical_terms=None,
    population_numeric_terms=None,
    anchor_df=None,
    group_anchor_df=None,
    noncenter_facet="Person",
    dummy_facets=None,
    positive_facets=None,
    quad_points=15,
    population_prior_sd=1.0,
    estimate_population_sd=False,
    facet_regularization=None,
    maxit=400,
    reltol=1e-6,
    mml_engine="EM",
    anchor_policy="warn",
    min_common_anchors=2,
    min_obs_per_element=2,
    min_obs_per_category=1,
    compute_plausible_values=False,
    n_plausible_values=5,
    plausible_seed=20260411,
):
    response_data_audit = build_response_data_audit(
        data,
        person_col=person_col,
        facet_cols=list(facet_cols),
        score_col=score_col,
        weight_col=weight_col,
    )
    data_for_fit = normalize_response_input_data(
        data,
        person_col=person_col,
        facet_cols=list(facet_cols),
        score_col=score_col,
        weight_col=weight_col,
    )
    facet_regularization_rows_for_dispatch = normalize_facet_regularization_rows(facet_regularization)
    facet_regularization_requested = not facet_regularization_rows_for_dispatch.empty

    if (
        method == "JMLE"
        and SHARED_SIM_ENGINE is not None
        and not USE_EMBEDDED_ENGINE_ONLY
        and not facet_regularization_requested
    ):
        shared_result = SHARED_SIM_ENGINE.mfrm_estimate(
            data=data_for_fit,
            person_col=person_col,
            facet_cols=facet_cols,
            score_col=score_col,
            rating_min=rating_min,
            rating_max=rating_max,
            weight_col=weight_col,
            keep_original=keep_original,
            model=model,
            method=method,
            step_facet=step_facet,
            anchor_df=anchor_df,
            group_anchor_df=group_anchor_df,
            noncenter_facet=noncenter_facet,
            dummy_facets=dummy_facets,
            positive_facets=positive_facets,
            quad_points=quad_points,
            maxit=maxit,
            reltol=reltol,
            jmle_optimizer="AUTO",
        )
        if isinstance(shared_result, dict):
            shared_prep = shared_result.setdefault("prep", {})
            shared_prep["response_data_audit"] = response_data_audit
            shared_prep["row_audit"] = response_data_audit.get("rows", pd.DataFrame())
            shared_prep["excluded_rows"] = response_data_audit.get("excluded_rows", pd.DataFrame())
            shared_prep["audit_summary"] = response_data_audit.get("summary", pd.DataFrame())
        return shared_result

    prep = prepare_mfrm_data(
        data_for_fit,
        person_col=person_col,
        facet_cols=facet_cols,
        score_col=score_col,
        rating_min=rating_min,
        rating_max=rating_max,
        weight_col=weight_col,
        keep_original=keep_original,
    )
    prep["response_data_audit"] = response_data_audit
    prep["row_audit"] = response_data_audit.get("rows", pd.DataFrame())
    prep["excluded_rows"] = response_data_audit.get("excluded_rows", pd.DataFrame())
    prep["audit_summary"] = response_data_audit.get("summary", pd.DataFrame())

    model = str(model or "RSM").upper()
    if model not in {"RSM", "PCM", "GPCM"}:
        raise ValueError("Model must be one of: RSM, PCM, GPCM.")
    population_prior_sd = float(population_prior_sd if population_prior_sd is not None else 1.0)
    if not np.isfinite(population_prior_sd) or population_prior_sd <= 0:
        raise ValueError("population_prior_sd must be a positive finite value.")

    if model in {"PCM", "GPCM"}:
        if step_facet is None:
            step_facet = prep["facet_names"][0]
        if step_facet not in prep["facet_names"]:
            raise ValueError("Selected step facet is not in the facet list.")
        if model == "GPCM":
            if slope_facet is None:
                slope_facet = step_facet
            if slope_facet not in prep["facet_names"]:
                raise ValueError("Selected slope facet is not in the facet list.")
            if slope_facet != step_facet:
                raise ValueError("Bounded GPCM currently requires slope_facet == step_facet.")
        else:
            slope_facet = None
    else:
        step_facet = None
        slope_facet = None

    idx = build_indices(prep, step_facet=step_facet, slope_facet=slope_facet)

    n_person = len(prep["levels"]["Person"])
    facet_levels = {f: prep["levels"][f] for f in prep["facet_names"]}
    n_cat = prep["rating_max"] - prep["rating_min"] + 1
    if str(population_formula or "").strip() and method != "MML":
        raise ValueError("population_formula / latent regression is currently available for MML only.")
    population_model = (
        build_population_model(
            prep,
            person_data=person_data,
            person_id_col=person_id_col,
            population_formula=population_formula,
            standardize_numeric=population_standardize_numeric,
            categorical_terms=population_categorical_terms,
            numeric_terms=population_numeric_terms,
        )
        if method == "MML" else build_population_model(prep)
    )

    if noncenter_facet not in ["Person"] + prep["facet_names"]:
        noncenter_facet = "Person"

    dummy_facets = [f for f in (dummy_facets or []) if f in ["Person"] + prep["facet_names"]]

    positive_facets = set(positive_facets or [])
    facet_signs = {facet: (1 if facet in positive_facets else -1) for facet in prep["facet_names"]}
    anchor_policy = str(anchor_policy or "warn").lower()
    if anchor_policy not in {"warn", "error", "silent"}:
        anchor_policy = "warn"
    anchor_audit = audit_mfrm_anchors(
        prep,
        anchor_df=anchor_df,
        group_anchor_df=group_anchor_df,
        dummy_facets=dummy_facets,
        min_common_anchors=min_common_anchors,
        min_obs_per_element=min_obs_per_element,
        min_obs_per_category=min_obs_per_category,
    )
    if anchor_policy == "error" and anchor_audit.get("overall_status") in {"error", "warning"}:
        issues = anchor_audit.get("issues", pd.DataFrame())
        msg = "Anchor audit failed under policy='error'."
        if isinstance(issues, pd.DataFrame) and not issues.empty:
            first = issues.iloc[0]
            msg += f" First issue: {first.get('Message', '')} Action: {first.get('Action', '')}"
        raise ValueError(msg)
    anchor_df_for_fit = anchor_audit.get("valid_anchors", pd.DataFrame())
    group_anchor_df_for_fit = anchor_audit.get("valid_group_anchors", pd.DataFrame())

    config = {
        "model": model,
        "method": method,
        "app_version": APP_VERSION,
        "release_label": APP_RELEASE_LABEL,
        "runtime_scope": "standalone Python; no external MFRM engine called",
        "n_person": n_person,
        "n_cat": n_cat,
        "facet_names": prep["facet_names"],
        "facet_levels": facet_levels,
        "step_facet": step_facet,
        "slope_facet": slope_facet,
        "population_model": population_model,
    }
    config["weight_col"] = weight_col if weight_col else None
    config["keep_original"] = bool(keep_original)
    config["rating_min"] = prep["rating_min"]
    config["rating_max"] = prep["rating_max"]
    config["input_rating_min"] = rating_min
    config["input_rating_max"] = rating_max
    config["score_range_explicit"] = bool(prep.get("score_range_explicit", False))
    config["positive_facets"] = list(positive_facets)
    config["facet_signs"] = facet_signs
    config["maxit"] = maxit
    config["reltol"] = reltol
    config["quad_points"] = quad_points if method == "MML" else None
    config["population_prior_sd"] = float(population_prior_sd) if method == "MML" else None
    config["population_formula"] = population_model.get("formula", "") if method == "MML" else ""
    config["population_standardize_numeric"] = bool(population_model.get("standardize_numeric", False)) if method == "MML" else False
    config["population_categorical_terms"] = population_model.get("categorical_terms", []) if method == "MML" else []
    config["population_numeric_terms"] = population_model.get("numeric_terms", []) if method == "MML" else []
    config["population_term_types"] = population_model.get("term_types", {}) if method == "MML" else {}
    config["person_id_col"] = person_id_col if method == "MML" and population_model.get("enabled") else None
    config["anchor_policy"] = anchor_policy
    config["compute_plausible_values"] = bool(compute_plausible_values) if method == "MML" else False
    config["n_plausible_values"] = int(n_plausible_values) if method == "MML" and compute_plausible_values else 0
    config["plausible_seed"] = int(plausible_seed) if method == "MML" and compute_plausible_values else None
    if model == "GPCM":
        config["gpcm_spec"] = {
            "scope": "bounded",
            "step_facet": step_facet,
            "slope_facet": slope_facet,
            "slope_identification": "positive slopes; centered log slopes; geometric mean slope fixed to 1",
            "log_slope_bounds": [-3.0, 3.0],
        }
        config["gpcm_log_slope_bounds"] = (-3.0, 3.0)
    mml_engine_raw = str(mml_engine or "EM").strip().lower()
    config["mml_engine_requested"] = str(mml_engine) if method == "MML" else None
    if "auto" in mml_engine_raw:
        mml_engine_resolved = "auto"
    elif "hybrid" in mml_engine_raw:
        mml_engine_resolved = "hybrid"
    elif "direct" in mml_engine_raw:
        mml_engine_resolved = "direct"
    else:
        mml_engine_resolved = "em"
    # Free latent-population-SD estimation is opt-in and EM-only. Force the EM
    # engine (recording an override notice) and give EM more iterations to fit
    # the extra variance coordinate. Default (fixed SD) leaves all of this off.
    config["estimate_population_sd"] = bool(estimate_population_sd) if method == "MML" else False
    config["population_sd_bounds"] = (0.05, 10.0)
    if config["estimate_population_sd"]:
        maxit = max(int(maxit), 300)
        if mml_engine_resolved != "em":
            config["mml_engine_requested_before_sd_override"] = mml_engine_resolved
            config["population_sd_engine_notice"] = (
                "Population-SD estimation requires the EM engine; overrode "
                f"requested '{mml_engine_resolved}' to 'em'."
            )
            mml_engine_resolved = "em"
    config["mml_engine"] = mml_engine_resolved if method == "MML" else None
    if method == "JMLE":
        config["optimizer"] = "L-BFGS-B"
    elif mml_engine_resolved == "direct":
        config["optimizer"] = "Direct MML with analytical-gradient L-BFGS-B"
    elif mml_engine_resolved == "hybrid":
        config["optimizer"] = "Hybrid MML: EM warm start + analytical-gradient L-BFGS-B"
    elif mml_engine_resolved == "auto":
        config["optimizer"] = "Auto MML: hybrid first, EM fallback if needed"
    else:
        config["optimizer"] = (
            "EM with analytical-gradient M-step and free population SD"
            if config.get("estimate_population_sd")
            else "EM with analytical-gradient L-BFGS-B M-step"
        )

    constraint_specs = prepare_constraint_specs(
        prep=prep,
        anchor_df=anchor_df_for_fit,
        group_anchor_df=group_anchor_df_for_fit,
        noncenter_facet=noncenter_facet,
        dummy_facets=dummy_facets,
    )
    config["theta_spec"] = constraint_specs["theta_spec"]
    config["facet_specs"] = constraint_specs["facet_specs"]
    config["noncenter_facet"] = noncenter_facet
    config["dummy_facets"] = dummy_facets
    config["anchor_summary"] = constraint_specs["anchor_summary"]
    config["anchor_audit"] = anchor_audit

    sizes = build_param_sizes(config)
    regularization_bundle = prepare_facet_regularization(facet_regularization, config, sizes)
    config["facet_regularization"] = regularization_bundle["runtime"]
    config["facet_regularization_scope"] = regularization_bundle["scope"]
    config["facet_regularization_mode"] = regularization_bundle["mode"]
    config["facet_regularization_objective_mode"] = regularization_bundle["mode"]
    config["facet_regularization_enabled"] = bool(regularization_bundle["enabled"])
    config["facet_regularization_fingerprint"] = regularization_bundle["runtime"].get("fingerprint")

    step_init = np.linspace(-1, 1, max(n_cat - 1, 0)) if n_cat > 1 else np.array([], dtype=float)
    facet_starts = np.concatenate([np.zeros(sizes[f]) for f in config["facet_names"]]) if config["facet_names"] else np.array([], dtype=float)
    start = np.concatenate([
        np.zeros(sizes["theta"]),
        np.zeros(sizes.get("population", 0)),
        facet_starts,
        step_init if model == "RSM" else np.tile(step_init, len(facet_levels[step_facet])),
        np.zeros(sizes.get("log_slopes", 0)),
    ])

    fit_start_time = time.perf_counter()
    if method == "JMLE":
        opt = minimize(
            mfrm_loglik_jmle_value_grad,
            start,
            args=(idx, config, sizes),
            jac=True,
            method="L-BFGS-B",
            bounds=build_optimizer_bounds(sizes, config),
            options={"maxiter": maxit, "gtol": reltol, "ftol": reltol},
        )
    else:
        quad = make_mml_quadrature(config, quad_points)
        if mml_engine_resolved == "direct":
            opt = mfrm_direct_mml(start, idx, config, sizes, quad,
                                  maxit=maxit, reltol=reltol)
        elif mml_engine_resolved == "hybrid":
            opt = mfrm_hybrid_mml(start, idx, config, sizes, quad,
                                  maxit=maxit, reltol=reltol)
        elif mml_engine_resolved == "auto":
            opt = mfrm_auto_mml(start, idx, config, sizes, quad,
                                maxit=maxit, reltol=reltol)
        else:
            opt = mfrm_em_mml(start, idx, config, sizes, quad,
                              maxit=maxit, reltol=reltol)
            opt.mml_engine = "em"
        config["mml_engine"] = getattr(opt, "mml_engine", mml_engine_resolved)
        if mml_engine_resolved == "auto":
            config["mml_engine_auto_selected"] = getattr(opt, "auto_selected", config["mml_engine"])
            config["mml_engine_auto_attempted"] = getattr(opt, "auto_attempted", ["hybrid"])
            config["mml_engine_auto_fallback_reason"] = getattr(opt, "auto_fallback_reason", "")
            if config["mml_engine"] == "em":
                config["optimizer"] = "Auto MML selected EM after hybrid fallback"
            elif config["mml_engine"] == "hybrid":
                config["optimizer"] = "Auto MML selected hybrid"
        # Thread the estimated population SD back into config so the final
        # marginal-NLL, EAP, and plausible-value quadratures (all built via
        # make_mml_quadrature, which reads population_prior_sd) use the fitted
        # scale. The user's original input is preserved separately.
        if config.get("estimate_population_sd"):
            est_sd = getattr(opt, "estimated_population_sd", None)
            if est_sd is not None and np.isfinite(est_sd) and est_sd > 0:
                config["estimated_population_sd"] = float(est_sd)
                config["population_prior_sd_input"] = float(population_prior_sd)
                config["population_prior_sd"] = float(est_sd)
                config["sigma_trace"] = list(getattr(opt, "sigma_trace", []) or [])
    elapsed_seconds = time.perf_counter() - fit_start_time

    params = expand_params(opt.x, sizes, config)

    # Profile SE / CI for a freely-estimated population SD: numerically
    # differentiate the marginal log-likelihood twice wrt sigma, holding the
    # other parameters at their converged values (3 extra E-steps). This is a
    # conditional (profile) SE; it ignores curvature coupling with the item /
    # facet block and is therefore slightly optimistic.
    if config.get("estimate_population_sd") and config.get("estimated_population_sd"):
        sigma_hat = float(config["estimated_population_sd"])
        sd_lo = float(config.get("population_sd_bounds", (0.05, 10.0))[0])
        n_quad = int(quad_points or config.get("quad_points") or 15)
        h = max(1e-3, 0.01 * sigma_hat)
        se_sigma = float("nan")
        ci_lo = ci_hi = float("nan")
        if sigma_hat - h > sd_lo:
            try:
                def _mll_at_sigma(s):
                    _, ll = _e_step_posteriors(
                        idx, config, params, gauss_hermite_normal(n_quad, sd=s)
                    )
                    return float(ll)

                d2 = (
                    _mll_at_sigma(sigma_hat + h)
                    - 2.0 * _mll_at_sigma(sigma_hat)
                    + _mll_at_sigma(sigma_hat - h)
                ) / (h * h)
                obs_info = -d2
                if np.isfinite(obs_info) and obs_info > 0:
                    se_sigma = float(np.sqrt(1.0 / obs_info))
                    ci_lo = float(max(sigma_hat - 1.96 * se_sigma, sd_lo))
                    ci_hi = float(sigma_hat + 1.96 * se_sigma)
            except Exception:
                pass
        config["population_sd_se"] = se_sigma
        config["population_sd_ci"] = [ci_lo, ci_hi]
        config["population_sd_se_basis"] = (
            "Profile SE (other parameters held at converged values); slightly "
            "optimistic. NaN means sigma is at a bound or the likelihood is "
            "locally flat."
        )

    if method == "MML":
        quad = make_mml_quadrature(config, quad_points)
        person_tbl = compute_person_eap(idx, config, params, quad)
        person_tbl.insert(0, "Person", prep["levels"]["Person"])
        if population_model.get("enabled"):
            person_tbl["PopulationMean"] = compute_population_mu(params, config)
        posterior_outputs = compute_person_posterior_outputs(
            idx,
            config,
            params,
            quad,
            person_levels=prep["levels"]["Person"],
            n_plausible_values=(int(n_plausible_values) if compute_plausible_values else 0),
            seed=int(plausible_seed),
        )
    else:
        person_tbl = pd.DataFrame({
            "Person": prep["levels"]["Person"],
            "Estimate": params["theta"],
        })
        posterior_outputs = {
            "available": False,
            "reason": "Posterior scoring and plausible values are defined for MML runs only.",
            "scores": pd.DataFrame(),
            "plausible_values": pd.DataFrame(),
        }

    facet_tbls = []
    for facet in config["facet_names"]:
        facet_tbls.append(pd.DataFrame({
            "Facet": facet,
            "Level": prep["levels"][facet],
            "Estimate": params["facets"][facet],
        }))
    facet_tbl = pd.concat(facet_tbls, ignore_index=True) if facet_tbls else pd.DataFrame(columns=["Facet", "Level", "Estimate"])

    if model == "RSM":
        step_tbl = pd.DataFrame({
            "Step": [f"Step_{i+1}" for i in range(n_cat - 1)],
            "Estimate": params["steps"],
        })
    else:
        rows = []
        for sf in prep["levels"][step_facet]:
            for i in range(n_cat - 1):
                rows.append((sf, f"Step_{i+1}", params["steps_mat"][prep["levels"][step_facet].index(sf), i]))
        step_tbl = pd.DataFrame(rows, columns=["StepFacet", "Step", "Estimate"])

    if model == "GPCM":
        slope_tbl = pd.DataFrame({
            "SlopeFacet": slope_facet,
            "Level": prep["levels"][slope_facet],
            "LogEstimate": params["log_slopes"],
            "Estimate": params["slopes"],
        })
    else:
        slope_tbl = pd.DataFrame(columns=["SlopeFacet", "Level", "LogEstimate", "Estimate"])

    if method == "MML" and population_model.get("enabled") and sizes.get("population", 0) > 0:
        population_tbl = pd.DataFrame({
            "Term": population_model.get("columns", []),
            "Estimate": params["population"],
        })
        person_population_tbl = population_model.get("person_data", pd.DataFrame()).copy()
        pop_mu = compute_population_mu(params, config)
        if isinstance(person_population_tbl, pd.DataFrame) and not person_population_tbl.empty:
            person_population_tbl["PopulationMean"] = pop_mu
    else:
        population_tbl = pd.DataFrame(columns=["Term", "Estimate"])
        person_population_tbl = pd.DataFrame()
    transform_rows = []
    if method == "MML" and population_model.get("enabled"):
        for term, transform in population_model.get("numeric_transforms", {}).items():
            if isinstance(transform, dict):
                transform_rows.append({
                    "Term": term,
                    "Center": float(transform.get("center", 0.0)),
                    "Scale": float(transform.get("scale", 1.0)),
                    "Standardized": bool(transform.get("standardized", False)),
                })
    population_transform_tbl = pd.DataFrame(
        transform_rows,
        columns=["Term", "Center", "Scale", "Standardized"],
    )

    k_params = int(sum(sizes.values())) + (1 if config.get("estimate_population_sd") else 0)
    config["parameter_count"] = k_params
    if method == "MML":
        final_quad_for_ll = make_mml_quadrature(config, quad_points)
        final_raw_nll = mfrm_loglik_mml(opt.x, idx, config, sizes, final_quad_for_ll)
    else:
        final_raw_nll = mfrm_loglik_jmle(opt.x, idx, config, sizes)
    penalty_value, _ = facet_regularization_value_grad(opt.x, sizes, config)
    penalized_objective = final_raw_nll + penalty_value
    loglik = -final_raw_nll
    opt.raw_fun = final_raw_nll
    opt.penalty_value = penalty_value
    opt.penalized_objective = penalized_objective
    if not np.isfinite(getattr(opt, "gradient_norm", np.nan)):
        try:
            if method == "MML":
                final_quad = make_mml_quadrature(config, quad_points)
                _, final_grad = mfrm_loglik_mml_value_grad(opt.x, idx, config, sizes, final_quad)
            else:
                _, final_grad = mfrm_loglik_jmle_value_grad(opt.x, idx, config, sizes)
            opt.gradient_norm = float(np.linalg.norm(final_grad))
        except Exception:
            opt.gradient_norm = np.nan
    opt.elapsed_seconds = float(elapsed_seconds)
    convergence_tbl = build_convergence_summary(opt, config, loglik, elapsed_seconds)
    if "Weight" in prep["data"].columns:
        n_obs = float(prep["data"]["Weight"].sum())
    else:
        n_obs = len(prep["data"])
    aic = 2 * k_params - 2 * loglik
    bic = np.log(n_obs) * k_params - 2 * loglik if n_obs > 0 else np.nan
    deviance = -2 * loglik
    loglik_per_obs = loglik / n_obs if n_obs > 0 else np.nan
    aic_per_obs = aic / n_obs if n_obs > 0 else np.nan
    bic_per_obs = bic / n_obs if n_obs > 0 else np.nan

    n_iter = getattr(opt, "nit", opt.nfev)
    summary_tbl = pd.DataFrame({
        "Model": [model],
        "Method": [method],
        "EstimatorLabel": [f"Penalized {method}" if regularization_bundle["enabled"] else method],
        "MML Engine": [config.get("mml_engine") if method == "MML" else None],
        "PopulationPriorSD": [config.get("population_prior_sd") if method == "MML" else None],
        "FacetRegularization": ["On" if regularization_bundle["enabled"] else "Off"],
        "Optimizer": [config.get("optimizer")],
        "N": [n_obs],
        "Persons": [n_person],
        "Facets": [len(config["facet_names"])],
        "Categories": [n_cat],
        "KParams": [k_params],
        "PopulationSDMode": [
            "estimated" if config.get("estimate_population_sd")
            else ("fixed" if config.get("method") == "MML" else "n/a")
        ],
        "EstimatedPopulationSD": [config.get("estimated_population_sd")],
        "LogLik": [loglik],
        "Deviance": [deviance],
        "RegularizationPenalty": [penalty_value],
        "PenalizedObjective": [penalized_objective],
        "ObjectiveBasis": [
            "negative log-likelihood + Gaussian facet penalty"
            if regularization_bundle["enabled"] else "negative log-likelihood"
        ],
        "LogLikBasis": ["unpenalized likelihood evaluated at fitted estimates"],
        "AIC": [aic],
        "BIC": [bic],
        "LogLikPerObs": [loglik_per_obs],
        "AICPerObs": [aic_per_obs],
        "BICPerObs": [bic_per_obs],
        "Converged": [bool(opt.success)],
        "Iterations": [n_iter],
        "GradientNorm": [getattr(opt, "gradient_norm", np.nan)],
        "ElapsedSeconds": [elapsed_seconds],
    })

    result = {
        "summary": summary_tbl,
        "facets": {"person": person_tbl, "others": facet_tbl},
        "steps": step_tbl,
        "slopes": slope_tbl,
        "population": {
            "enabled": bool(population_model.get("enabled", False)),
            "formula": population_model.get("formula", ""),
            "coefficients": population_tbl,
            "person_data": person_population_tbl,
            "numeric_transforms": population_transform_tbl,
            "term_types": dict(population_model.get("term_types", {})),
            "type_summary": population_model.get(
                "type_summary",
                pd.DataFrame(columns=POPULATION_TYPE_SUMMARY_COLUMNS),
            ),
            "categorical_terms": list(population_model.get("categorical_terms", [])),
            "numeric_terms": list(population_model.get("numeric_terms", [])),
            "warnings": list(population_model.get("warnings", [])),
        },
        "config": config,
        "prep": prep,
        "opt": opt,
        "params": params,
        "convergence": convergence_tbl,
        "posterior": posterior_outputs,
        "regularization": {
            "settings": regularization_bundle["spec"],
            "audit": regularization_bundle["audit"],
            "penalty_summary": facet_regularization_penalty_summary(opt.x, sizes, config),
        },
    }
    result["likelihood_information"] = build_likelihood_information_criteria(result)
    result["anchor_drift"] = build_anchor_drift_review(result)
    result["equating_chain"] = build_equating_chain_summary(result)
    result["anchor_equating_workflow"] = build_anchor_equating_workflow_plan(result)
    config["anchor_drift_scope"] = result["anchor_drift"].get("scope")
    config["equating_chain_scope"] = result["equating_chain"].get("scope")
    return result


def compute_obs_table(res):
    prep = res["prep"]
    config = res["config"]
    idx = build_indices(prep, step_facet=config["step_facet"], slope_facet=config.get("slope_facet"))
    params = res["params"]
    theta_hat = params["theta"] if config["method"] == "JMLE" else res["facets"]["person"]["Estimate"].to_numpy()

    person_measure = theta_hat
    person_measure_by_row = person_measure[idx["person"]] if person_measure.size else np.zeros_like(idx["score_k"], dtype=float)

    eta = compute_eta(idx, params, config, theta_override=theta_hat if theta_hat.size else None)
    if config["model"] == "RSM":
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
        probs = category_prob_rsm(eta, step_cum)
    elif config["model"] == "PCM":
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        probs = category_prob_pcm(eta, step_cum_mat, idx["step_idx"])
    else:
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        probs = category_prob_gpcm(
            eta,
            step_cum_mat,
            idx["step_idx"],
            params["slopes"],
            idx.get("slope_idx"),
        )

    k_vals = np.arange(probs.shape[1])
    expected_k = probs.dot(k_vals)
    var_k = probs.dot(k_vals ** 2) - expected_k ** 2
    var_k = np.where(var_k <= 1e-10, np.nan, var_k)
    resid_k = idx["score_k"] - expected_k
    std_sq = resid_k ** 2 / var_k
    # E[(X - E[X])^4 | theta_i] for the polytomous model, in closed form:
    # M4_i = sum_k P_k * (k - E[X])^4. Used by the FACETS / Wright-Masters
    # Welch-Satterthwaite d.f. for ZSTD reporting (Wright & Masters, 1982,
    # Eqs. 4.20 and 4.27).
    diff_k = k_vals[np.newaxis, :] - expected_k[:, np.newaxis]
    fourth_central_moment = np.sum(probs * (diff_k ** 4), axis=1)

    df = prep["data"].copy()
    df["PersonMeasure"] = person_measure_by_row
    df["Observed"] = prep["rating_min"] + idx["score_k"]
    df["Expected"] = prep["rating_min"] + expected_k
    df["Var"] = var_k
    df["FourthCentralMoment"] = fourth_central_moment
    df["Residual"] = df["Observed"] - df["Expected"]
    df["StdResidual"] = df["Residual"] / np.sqrt(df["Var"])
    df["StdSq"] = std_sq

    # ---- Per-observation diagnostics for polytomous person-fit ----
    # These six columns are the inputs to the Drasgow (1985) lz statistic
    # and the Snijders (2001) lz* correction (Snijders, 2001, Eq. 16). The
    # math is summarised in the lz / lz* helpers below; the columns are
    # added here so a single pass over the per-observation
    # probability matrix produces every term they need.
    n_rows = probs.shape[0]
    score_k_int = idx["score_k"].astype(int)
    pr_observed = np.full(n_rows, np.nan)
    if n_rows > 0:
        valid_score = (score_k_int >= 0) & (score_k_int < probs.shape[1])
        rows_idx = np.where(valid_score)[0]
        pr_observed[rows_idx] = probs[rows_idx, score_k_int[rows_idx]]
    # Use clipping to avoid log(0); the clip floor mirrors the R reference
    # (.Machine$double.eps in R, np.finfo(float).eps here).
    eps = float(np.finfo(float).eps)
    log_p_mat = np.log(np.clip(probs, eps, None))
    # E[log P]_i = sum_k P_k * log P_k   (per-item negentropy; the R code
    # calls this ItemEntropy for parity with mfrmr 0.2.0, even though
    # information-theoretically it is the negative of Shannon entropy).
    item_entropy = np.sum(probs * log_p_mat, axis=1)
    # Var[log P]_i = sum_k P_k * (log P_k)^2  -  (E[log P])^2
    item_var_logp = np.sum(probs * log_p_mat ** 2, axis=1) - item_entropy ** 2
    item_var_logp = np.maximum(item_var_logp, 0.0)
    # Slope per observation (1.0 for RSM / PCM; estimated for GPCM under
    # the geometric-mean-one identification).
    if config["model"] == "GPCM":
        slope_idx_arr = idx.get("slope_idx")
        if slope_idx_arr is None:
            slope_idx_arr = idx["step_idx"]
        slope_obs = np.asarray(params["slopes"], dtype=float)[slope_idx_arr]
    else:
        slope_obs = np.ones(n_rows, dtype=float)
    # ScoreInformation_i = a^2 * Var[X|theta]   (Muraki, 1993, Eq. 16).
    score_information = (slope_obs ** 2) * var_k
    # ObservedScoreDerivative_i = d log P_i / d theta evaluated at the
    # observed category: a_i * (X_i - E[X|theta]). At the JML estimate
    # of theta_n the sum across a person's observations is zero
    # (definition of the MLE); for any individual observation it can
    # take either sign.
    observed_score_derivative = slope_obs * (idx["score_k"].astype(float) - expected_k)
    # ItemLogPScoreCov_i = Cov[log P, score]_i
    #   = a_i * Cov[log P, X | theta]_i
    #   = a_i * (E[X * log P]_i - E[X]_i * E[log P]_i)
    # where E[X * log P]_i = sum_k k * P_k * log P_k.
    item_e_k_logp = np.sum(k_vals * probs * log_p_mat, axis=1)
    item_logp_score_cov = slope_obs * (item_e_k_logp - expected_k * item_entropy)

    df["PrObserved"] = pr_observed
    df["ItemEntropy"] = item_entropy
    df["ItemVarLogP"] = item_var_logp
    df["ItemLogPScoreCov"] = item_logp_score_cov
    df["ScoreInformation"] = score_information
    df["ObservedScoreDerivative"] = observed_score_derivative
    return df


# ============================================================================
# Person-fit indices: Drasgow (1985) lz and Snijders (2001) lz*
# ============================================================================
# lz is the standardised polytomous log-likelihood (Drasgow, Levine, &
# Williams, 1985). For person n responding to items i = 1..I:
#
#     l_n        = sum_i log P_i(X_i | theta_n)
#     E[l_n]     = sum_i E[log P_i | theta_n]              (ItemEntropy)
#     Var[l_n]   = sum_i Var[log P_i | theta_n]            (ItemVarLogP)
#     lz_n       = (l_n - E[l_n]) / sqrt(Var[l_n])
#
# At the true theta_n, lz is asymptotically standard normal. When theta_n
# is replaced by its JML estimate the variance shrinks because the
# estimator was fit to the observed log-likelihood; the asymptotic null
# distribution is no longer N(0, 1) and lz over-rejects in the tails.
#
# Snijders (2001, Eq. 16) gives the leading-order correction: regress
# l_n on the score function S_n = sum_i a_i (X_i - E[X_i]), then take
# the residual variance as the new denominator. With
#     c_n           = Cov[l, S] / I(theta)            (ItemLogPScoreCov / ScoreInformation)
#     corrected_var = Var[l]    - Cov[l, S]^2 / I(theta)
# we get
#     lz*_n         = (l_n - E[l_n] - c_n * S_n) / sqrt(corrected_var)
#
# Under JML, S_n is ~zero at the per-person MLE, so the centring term
# c_n * S_n vanishes in expectation but its variance contribution is what
# restores the N(0, 1) null.
#
# For MML (EAP / MAP) estimates a Gaussian population prior N(mu, sigma^2)
# shrinks theta_n toward the mean. The prior score -(theta - mu)/sigma^2 is
# deterministic given theta, so it leaves the score variance unchanged
# (Var[S] = I) but augments the estimating-equation sensitivity to I + p,
# where p = 1/sigma^2. Sinharay (2001 -> 2016) extends Snijders to this
# Bayes-modal setting:
#     c_n           = Cov[l, S] / (I + p)
#     corrected_var = Var[l] - Cov[l, S]^2 * (I + 2p) / (I + p)^2
# which reduces EXACTLY to the JML formula at p -> 0. EAP (the posterior
# mean) is not itself an M-estimator, but it agrees with the MAP estimator
# to O(1/I), so the same correction applies to leading order. We therefore
# ship the population-prior-corrected lz* on the MML path (status
# 'computed_eap_population_corrected') and only fall back to unadjusted lz
# when the prior SD is unavailable or the method is unrecognised.
#
# References: Snijders (2001, Psychometrika 66, Eq. 16); Sinharay (2016,
# Brit. J. Math. Stat. Psychol. 69, 175-193); Magis, Raiche & Beland (2012).

_PERSON_FIT_Z_5PCT = float(_norm.ppf(0.975))
_PERSON_FIT_Z_1PCT = float(_norm.ppf(0.995))

_PERSON_FIT_OBS_REQUIRED_COLUMNS = (
    "Person",
    "PrObserved",
    "ItemEntropy",
    "ItemVarLogP",
)

_PERSON_FIT_LZ_STAR_REQUIRED_COLUMNS = (
    "ItemLogPScoreCov",
    "ScoreInformation",
)

# Statuses for which lz* was actually computed and may be reported as the
# ReportIndex: the JML conditional calibration and the MML/EAP/MAP
# population-prior-corrected extension (Sinharay, 2016).
_PERSON_FIT_LZ_STAR_COMPUTED_STATUSES = (
    "computed_jml_conditional_calibration",
    "computed_eap_population_corrected",
)


def _compute_snijders_lz_star(obs, persons, res=None):
    """Return Snijders (2001) lz* for each person.

    Parameters
    ----------
    obs : pandas.DataFrame
        Per-observation diagnostics frame as produced by ``compute_obs_table``.
        Must carry ``Person``, ``PrObserved``, ``ItemEntropy``, ``ItemVarLogP``
        plus the lz*-specific columns ``ItemLogPScoreCov`` and
        ``ScoreInformation``. ``ObservedScoreDerivative`` is also required;
        if absent, it is reconstructed from ``ScoreSlope * (Observed -
        Expected)`` when those columns exist.
    persons : sequence
        The roster of person identifiers to report on (one row per person
        in the returned frame, in the supplied order).
    res : dict | None
        The fit result dictionary; reads ``config['method']`` and, on the
        MML/EAP/MAP path, ``config['population_prior_sd']`` (the prior SD the
        estimate was shrunk toward — the freely-estimated sigma when MML
        freed it). If ``None`` or a method/SD the correction cannot cover,
        the function reports a status reason without raising — the public
        ``compute_person_fit_indices`` wrapper handles fallback to lz.

    Returns
    -------
    pandas.DataFrame
        Columns: ``Person``, ``lz_star``, ``lz_star_status``,
        ``lz_star_c``, ``lz_star_variance``. ``lz_star_status`` is one of:

        - ``"fit_required"`` — ``res`` was ``None``.
        - ``"invalid_fit"`` — ``res`` lacks a recognisable config block.
        - ``"eap_population_sd_unavailable"`` — fit is MML/EAP/MAP but the
          population SD (prior precision) needed for the correction is
          missing or non-positive.
        - ``"not_applicable_method"`` — the person-estimation method is
          neither JML nor an MML/EAP/MAP variant the correction covers.
        - ``"diagnostics_missing_snijders_terms"`` — obs lacks the lz*
          covariance / information columns.
        - ``"insufficient_information"`` — per-person numeric guard rails
          tripped (no usable rows, zero information, non-positive
          corrected variance).
        - ``"computed_jml_conditional_calibration"`` — JML value reported.
        - ``"computed_eap_population_corrected"`` — MML/EAP/MAP value
          reported, using the population-prior precision (Sinharay, 2016).
    """
    persons_arr = np.asarray([str(p) for p in persons], dtype=object)
    empty = pd.DataFrame(
        {
            "Person": persons_arr,
            "lz_star": np.full(len(persons_arr), np.nan),
            "lz_star_status": np.array(["fit_required"] * len(persons_arr), dtype=object),
            "lz_star_c": np.full(len(persons_arr), np.nan),
            "lz_star_variance": np.full(len(persons_arr), np.nan),
        }
    )
    if res is None:
        return empty

    config = res.get("config") if isinstance(res, dict) else None
    if not isinstance(config, dict):
        empty["lz_star_status"] = "invalid_fit"
        return empty

    method = str(config.get("method", "")).upper()
    if method == "JMLE":
        method = "JML"
    # Determine the person-estimator regime and the prior precision p = 1/sigma^2.
    #   JML / ML  -> no population prior (p = 0); Snijders (2001) conditional
    #               calibration, where S_n is ~0 at the per-person MLE.
    #   MML / EAP / MAP -> a Gaussian population prior shrinks the estimate, so
    #               the estimating-equation *sensitivity* becomes I + p while the
    #               score variance stays I (the prior score is deterministic).
    #               Following Sinharay (2016), c_n = Cov/(I + p) and the corrected
    #               variance is Var[l] - Cov^2 (I + 2p)/(I + p)^2. This reduces
    #               EXACTLY to the JML formula at p -> 0. EAP is handled via its
    #               leading-order equivalence to the MAP estimator (exact for MAP,
    #               accurate to O(1/I) for the EAP posterior mean).
    _EAP_METHODS = {"MML", "EAP", "MAP", "BAYES"}
    if method == "JML":
        prior_precision = 0.0
        computed_status = "computed_jml_conditional_calibration"
    elif method in _EAP_METHODS:
        # Use the SAME prior SD the EAP/MAP estimate was shrunk toward — i.e.
        # what make_mml_quadrature consumed (the freely-estimated sigma when
        # MML freed it, since the free-SD path writes it back here).
        try:
            sigma = get_population_prior_sd(config)
        except (TypeError, ValueError):
            sigma = np.nan
        if not (np.isfinite(sigma) and sigma > 0):
            # The prior SD the EAP/MAP estimate was shrunk toward is unknown
            # (or non-positive), so the population-prior correction cannot be
            # formed; the wrapper falls back to unadjusted lz.
            empty["lz_star_status"] = "eap_population_sd_unavailable"
            return empty
        prior_precision = 1.0 / (sigma * sigma)
        computed_status = "computed_eap_population_corrected"
    else:
        empty["lz_star_status"] = "not_applicable_method"
        return empty

    missing_cols = [c for c in _PERSON_FIT_LZ_STAR_REQUIRED_COLUMNS if c not in obs.columns]
    if missing_cols:
        empty["lz_star_status"] = "diagnostics_missing_snijders_terms"
        return empty

    work = obs.copy()
    work["Person"] = work["Person"].astype(str)
    work["ItemLogPScoreCov"] = pd.to_numeric(work["ItemLogPScoreCov"], errors="coerce")
    work["ScoreInformation"] = pd.to_numeric(work["ScoreInformation"], errors="coerce")
    if "ObservedScoreDerivative" in work.columns:
        work["ObservedScoreDerivative"] = pd.to_numeric(work["ObservedScoreDerivative"], errors="coerce")
    elif {"ScoreSlope", "Observed", "Expected"}.issubset(work.columns):
        work["ObservedScoreDerivative"] = (
            pd.to_numeric(work["ScoreSlope"], errors="coerce")
            * (pd.to_numeric(work["Observed"], errors="coerce")
               - pd.to_numeric(work["Expected"], errors="coerce"))
        )
    else:
        empty["lz_star_status"] = "diagnostics_missing_snijders_terms"
        return empty

    eps = float(np.finfo(float).eps)
    log_p = np.log(np.maximum(work["PrObserved"].to_numpy(dtype=float), eps))
    work["_WCentered"] = log_p - work["ItemEntropy"].to_numpy(dtype=float)

    out = empty.copy()
    out["lz_star_status"] = "insufficient_information"
    sqrt_eps = float(np.sqrt(eps))
    grouped = {str(name): grp for name, grp in work.groupby("Person", sort=False)}
    for i, person in enumerate(persons_arr):
        d = grouped.get(str(person))
        if d is None or len(d) == 0:
            continue
        w_centered = d["_WCentered"].to_numpy(dtype=float)
        item_var_logp = d["ItemVarLogP"].to_numpy(dtype=float)
        item_cov = d["ItemLogPScoreCov"].to_numpy(dtype=float)
        score_info = d["ScoreInformation"].to_numpy(dtype=float)
        score_deriv = d["ObservedScoreDerivative"].to_numpy(dtype=float)
        ok = (
            np.isfinite(w_centered)
            & np.isfinite(item_var_logp)
            & (item_var_logp >= 0)
            & np.isfinite(item_cov)
            & np.isfinite(score_info)
            & (score_info > 0)
            & np.isfinite(score_deriv)
        )
        if not np.any(ok):
            continue
        info_total = float(np.sum(score_info[ok]))
        cov_total = float(np.sum(item_cov[ok]))
        var_logp_total = float(np.sum(item_var_logp[ok]))
        if not (np.isfinite(info_total) and info_total > 0):
            continue
        if not (np.isfinite(var_logp_total) and var_logp_total > 0):
            continue
        if prior_precision == 0.0:
            # JML / ML: literal original arithmetic, kept byte-identical.
            c_n = cov_total / info_total
            corrected_var = var_logp_total - (cov_total ** 2) / info_total
        else:
            # MML / EAP / MAP: prior precision augments the sensitivity (I + p)
            # in c_n; Var[S] stays I, giving the (I + 2p)/(I + p)^2 factor.
            denom = info_total + prior_precision
            c_n = cov_total / denom
            corrected_var = var_logp_total - (cov_total ** 2) * (
                info_total + 2.0 * prior_precision
            ) / (denom ** 2)
        if not np.isfinite(corrected_var) or corrected_var <= sqrt_eps:
            out.at[i, "lz_star_c"] = c_n
            out.at[i, "lz_star_variance"] = corrected_var
            continue
        centered_loglik = float(np.sum(w_centered[ok]))
        score_sum = float(np.sum(score_deriv[ok]))
        out.at[i, "lz_star"] = (centered_loglik - c_n * score_sum) / float(np.sqrt(corrected_var))
        out.at[i, "lz_star_status"] = computed_status
        out.at[i, "lz_star_c"] = c_n
        out.at[i, "lz_star_variance"] = corrected_var
    return out


def _add_person_fit_reporting_columns(out: pd.DataFrame) -> pd.DataFrame:
    """Add the report-ready flag/caveat columns to a person-fit frame.

    The reporting layer chooses ``lz_star`` when it was successfully
    computed and falls back to unadjusted ``lz`` otherwise. The flag
    columns use the practical two-sided thresholds |z| > 1.96 (5%) and
    |z| > 2.58 (1%) on the standard normal. ``ReviewStatus`` /
    ``ReviewReason`` / ``ReportCaveat`` give a human-readable reading
    so manuscripts can quote the column directly without re-deriving
    the rule.
    """
    z5 = _PERSON_FIT_Z_5PCT
    z1 = _PERSON_FIT_Z_1PCT

    lz = pd.to_numeric(out["lz"], errors="coerce")
    lz_star = pd.to_numeric(out["lz_star"], errors="coerce")
    status = out["lz_star_status"].astype(str)

    out["lz_flag_5pct"] = lz.abs().gt(z5).fillna(False)
    out["lz_flag_1pct"] = lz.abs().gt(z1).fillna(False)
    out["lz_star_flag_5pct"] = lz_star.abs().gt(z5).fillna(False)
    out["lz_star_flag_1pct"] = lz_star.abs().gt(z1).fillna(False)

    snijders_ready = lz_star.notna() & status.isin(_PERSON_FIT_LZ_STAR_COMPUTED_STATUSES)
    lz_ready = (~snijders_ready) & lz.notna()

    out["ReportIndex"] = np.where(snijders_ready, "lz_star",
                                  np.where(lz_ready, "lz", "none"))
    report_value = np.where(snijders_ready, lz_star,
                            np.where(lz_ready, lz, np.nan))
    out["ReportValue"] = report_value
    abs_report = np.abs(report_value)
    flag_level = np.where(
        ~np.isfinite(abs_report), "not_available",
        np.where(abs_report > z1, "1pct",
                 np.where(abs_report > z5, "5pct", "none")),
    )
    out["ReportFlagLevel"] = flag_level
    out["ReportFlag"] = np.isin(flag_level, ["5pct", "1pct"])
    out["ReviewStatus"] = np.where(
        flag_level == "1pct", "review_1pct",
        np.where(flag_level == "5pct", "review_5pct",
                 np.where(flag_level == "none", "not_flagged", "not_available")),
    )

    report_index_arr = np.asarray(out["ReportIndex"])
    review_reason = np.where(
        flag_level == "1pct",
        np.array([f"{ri} exceeds |z| > 2.58." for ri in report_index_arr]),
        np.where(
            flag_level == "5pct",
            np.array([f"{ri} exceeds |z| > 1.96." for ri in report_index_arr]),
            np.where(
                flag_level == "none",
                "No report-level flag under the practical two-sided thresholds.",
                "No finite person-fit statistic is available for report-level flagging.",
            ),
        ),
    )
    out["ReviewReason"] = review_reason

    status_arr = status.to_numpy()
    jml_caveat = (
        "lz_star applies the Snijders correction conditional on fitted "
        "non-person calibration; non-person parameter uncertainty is not "
        "propagated."
    )
    eap_caveat = (
        "lz_star applies the Snijders correction extended to the MML/EAP "
        "population prior (precision 1/sigma^2; Sinharay, 2016): exact for "
        "MAP, accurate to O(1/I) for the EAP posterior mean. Non-person "
        "parameter and posterior uncertainty are not propagated."
    )
    snijders_caveat = np.where(
        status.eq("computed_eap_population_corrected").to_numpy(),
        eap_caveat,
        jml_caveat,
    )
    out["ReportCaveat"] = np.where(
        snijders_ready.to_numpy(),
        snijders_caveat,
        np.where(
            lz_ready.to_numpy(),
            np.array([
                f"lz is the uncorrected standardized log-likelihood; lz_star_status = {s}."
                for s in status_arr
            ]),
            np.array([
                f"No report index selected; lz_star_status = {s}."
                for s in status_arr
            ]),
        ),
    )
    return out


def compute_person_fit_indices(res, obs=None):
    """Return per-person Drasgow lz and Snijders lz* statistics.

    Mirrors mfrmr ``compute_person_fit_indices`` (R/api-person-fit.R) for
    the JML path, and extends it: the function consumes the per-observation
    diagnostics frame from ``compute_obs_table`` and reports the uncorrected
    lz and Snijders lz* for BOTH JML/fixed-effect estimates (conditional
    calibration) and MML/EAP/MAP estimates (the population-prior-corrected
    extension; Sinharay, 2016). lz* falls back to lz only when the prior SD
    is unavailable or the method is unrecognised.

    Returned columns
    ----------------
    Person, N, LogLik, lz, lz_star, lz_star_status, lz_star_c,
    lz_star_variance, lz_flag_5pct, lz_flag_1pct, lz_star_flag_5pct,
    lz_star_flag_1pct, ReportIndex, ReportValue, ReportFlagLevel,
    ReportFlag, ReviewStatus, ReviewReason, ReportCaveat.
    """
    if obs is None:
        obs = compute_obs_table(res)
    if obs is None or not isinstance(obs, pd.DataFrame):
        raise ValueError(
            "compute_person_fit_indices requires a per-observation "
            "diagnostics frame from compute_obs_table()."
        )

    missing_cols = [c for c in _PERSON_FIT_OBS_REQUIRED_COLUMNS if c not in obs.columns]
    if missing_cols:
        raise ValueError(
            "obs is missing required person-fit columns: "
            + ", ".join(missing_cols)
            + ". This typically means the diagnostics frame was generated by "
            "an older codepath that did not populate the per-observation "
            "probability columns; recompute via compute_obs_table()."
        )

    obs_work = obs.copy()
    obs_work["Person"] = obs_work["Person"].astype(str)
    obs_work["PrObserved"] = pd.to_numeric(obs_work["PrObserved"], errors="coerce")
    obs_work["ItemEntropy"] = pd.to_numeric(obs_work["ItemEntropy"], errors="coerce")
    obs_work["ItemVarLogP"] = pd.to_numeric(obs_work["ItemVarLogP"], errors="coerce")

    eps = float(np.finfo(float).eps)
    log_p = np.log(np.maximum(obs_work["PrObserved"].to_numpy(dtype=float), eps))
    obs_work["_LogP"] = log_p

    # Preserve the order of persons as they appear in the fit (prep
    # level order if available, otherwise first-seen order in obs).
    person_levels = None
    if isinstance(res, dict):
        prep = res.get("prep") if isinstance(res.get("prep"), dict) else None
        if prep and isinstance(prep.get("levels"), dict):
            raw_levels = prep["levels"].get("Person")
            if raw_levels is not None:
                person_levels = [str(p) for p in raw_levels]
    if person_levels is None:
        person_levels = list(dict.fromkeys(obs_work["Person"].tolist()))

    rows = []
    grouped = {str(name): grp for name, grp in obs_work.groupby("Person", sort=False)}
    for person in person_levels:
        d = grouped.get(person)
        if d is None or len(d) == 0:
            rows.append({"Person": person, "N": 0, "LogLik": np.nan, "lz": np.nan})
            continue
        log_p = d["_LogP"].to_numpy(dtype=float)
        e_logp = d["ItemEntropy"].to_numpy(dtype=float)
        var_logp = d["ItemVarLogP"].to_numpy(dtype=float)
        ok = np.isfinite(log_p) & np.isfinite(e_logp) & np.isfinite(var_logp) & (var_logp >= 0)
        if not np.any(ok):
            rows.append({"Person": person, "N": 0, "LogLik": np.nan, "lz": np.nan})
            continue
        ll = float(np.sum(log_p[ok]))
        e_ll = float(np.sum(e_logp[ok]))
        var_ll = float(np.sum(var_logp[ok]))
        lz_val = (ll - e_ll) / float(np.sqrt(var_ll)) if var_ll > 0 else np.nan
        rows.append({"Person": person, "N": int(np.sum(ok)), "LogLik": ll, "lz": lz_val})
    out = pd.DataFrame(rows, columns=["Person", "N", "LogLik", "lz"])
    out["N"] = out["N"].astype(int)

    lz_star_tbl = _compute_snijders_lz_star(obs_work, out["Person"].tolist(), res=res)
    merged = out.merge(lz_star_tbl, on="Person", how="left")
    merged["lz_star_status"] = merged["lz_star_status"].fillna("fit_required")
    out = _add_person_fit_reporting_columns(merged)

    column_order = [
        "Person", "N", "LogLik", "lz", "lz_star", "lz_star_status",
        "lz_star_c", "lz_star_variance",
        "lz_flag_5pct", "lz_flag_1pct",
        "lz_star_flag_5pct", "lz_star_flag_1pct",
        "ReportIndex", "ReportValue", "ReportFlagLevel", "ReportFlag",
        "ReviewStatus", "ReviewReason", "ReportCaveat",
    ]
    return out[column_order]


def person_fit_threshold_table() -> pd.DataFrame:
    """Two-sided z-thresholds used by the report-ready flag columns."""
    return pd.DataFrame(
        {
            "Threshold": ["5pct", "1pct"],
            "TwoSidedAlpha": [0.05, 0.01],
            "AbsZ": [_PERSON_FIT_Z_5PCT, _PERSON_FIT_Z_1PCT],
            "Rule": ["|z| > 1.96", "|z| > 2.58"],
        }
    )


def compute_prob_matrix(res):
    prep = res["prep"]
    config = res["config"]
    idx = build_indices(prep, step_facet=config["step_facet"], slope_facet=config.get("slope_facet"))
    params = res["params"]
    theta_hat = params["theta"] if config["method"] == "JMLE" else res["facets"]["person"]["Estimate"].to_numpy()
    eta = compute_eta(idx, params, config, theta_override=theta_hat if theta_hat.size else None)
    if config["model"] == "RSM":
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
        return category_prob_rsm(eta, step_cum)
    step_cum_mat = np.vstack([
        np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
    ])
    if config["model"] == "PCM":
        return category_prob_pcm(eta, step_cum_mat, idx["step_idx"])
    return category_prob_gpcm(
        eta,
        step_cum_mat,
        idx["step_idx"],
        params["slopes"],
        idx.get("slope_idx"),
    )


def compute_scorefile(res):
    obs = compute_obs_table(res)
    if obs.empty:
        return pd.DataFrame()
    probs = compute_prob_matrix(res)
    if probs is None or probs.shape[0] != len(obs):
        return obs
    cat_vals = np.arange(res["prep"]["rating_min"], res["prep"]["rating_max"] + 1)
    prob_df = pd.DataFrame(probs, columns=[f"P_{v}" for v in cat_vals])
    max_idx = np.argmax(probs, axis=1)
    max_prob = probs[np.arange(len(probs)), max_idx]
    most_likely = cat_vals[max_idx]
    base_cols = ["Person"] + res["config"]["facet_names"]
    if "Weight" in obs.columns:
        base_cols.append("Weight")
    base_cols += ["Score", "Observed", "Expected", "Residual", "StdResidual", "Var", "PersonMeasure"]
    out = pd.concat([
        obs[base_cols],
        prob_df,
    ], axis=1)
    out["MostLikely"] = most_likely
    out["MaxProb"] = max_prob
    return out


def compute_fitted_prediction_table(res):
    """Prediction table for the fitted design rows.

    Predictions are conditional on the fitted person measure (JMLE theta or MML
    EAP). They are intended for checking the fitted response pattern, not for
    forecasting entirely new persons or unseen facet designs.
    """
    scorefile = compute_scorefile(res)
    if scorefile.empty:
        return pd.DataFrame()
    probs = compute_prob_matrix(res)
    if probs is None or probs.shape[0] != len(scorefile):
        return scorefile

    out = scorefile.copy()
    probs = np.asarray(probs, dtype=float)
    probs = np.where(np.isfinite(probs) & (probs >= 0), probs, 0.0)
    row_sum = probs.sum(axis=1, keepdims=True)
    probs = np.divide(probs, row_sum, out=np.full_like(probs, 1.0 / probs.shape[1]), where=row_sum > 0)

    cat_vals = np.arange(res["prep"]["rating_min"], res["prep"]["rating_max"] + 1)
    max_idx = np.argmax(probs, axis=1)
    with np.errstate(divide="ignore", invalid="ignore"):
        entropy = -np.sum(np.where(probs > 0, probs * np.log(probs), 0.0), axis=1)
    max_entropy = float(np.log(probs.shape[1])) if probs.shape[1] > 1 else np.nan
    uncertainty = entropy / max_entropy if np.isfinite(max_entropy) and max_entropy > 0 else np.zeros_like(entropy)

    out["PredictedCategory"] = cat_vals[max_idx]
    out["PredictionConfidence"] = probs[np.arange(len(probs)), max_idx]
    out["PredictionEntropy"] = entropy
    out["PredictionUncertainty"] = uncertainty
    out["PredictionScope"] = "fitted_design_conditional_on_person_measure"

    person_tbl = res.get("facets", {}).get("person", pd.DataFrame())
    if (
        isinstance(person_tbl, pd.DataFrame)
        and "Person" in person_tbl.columns
        and "PopulationMean" in person_tbl.columns
        and "PopulationMean" not in out.columns
    ):
        pop_lookup = person_tbl[["Person", "PopulationMean"]].copy()
        pop_lookup["Person"] = pop_lookup["Person"].astype(str)
        out["Person"] = out["Person"].astype(str)
        out = out.merge(pop_lookup, on="Person", how="left")

    first_cols = ["Person"] + list(res.get("config", {}).get("facet_names", []))
    tail_cols = [c for c in out.columns if c not in first_cols]
    return out[first_cols + tail_cols]


def _normalise_probability_rows(probs: np.ndarray) -> np.ndarray:
    probs = np.asarray(probs, dtype=float)
    if probs.ndim != 2 or probs.size == 0:
        return probs
    probs = np.where(np.isfinite(probs) & (probs >= 0), probs, 0.0)
    row_sum = probs.sum(axis=1, keepdims=True)
    return np.divide(
        probs,
        row_sum,
        out=np.full_like(probs, 1.0 / probs.shape[1]),
        where=row_sum > 0,
    )


def _category_probs_from_eta_for_prediction(config, params, eta, step_idx=None, slope_idx=None):
    eta = np.asarray(eta, dtype=float)
    if config["model"] == "RSM":
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
        return category_prob_rsm(eta, step_cum)
    step_cum_mat = np.vstack([
        np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
    ])
    if step_idx is None:
        raise ValueError("step_idx is required for PCM/GPCM prediction.")
    step_idx = np.asarray(step_idx, dtype=int)
    if config["model"] == "PCM":
        return category_prob_pcm(eta, step_cum_mat, step_idx)
    return category_prob_gpcm(
        eta,
        step_cum_mat,
        step_idx,
        params["slopes"],
        np.asarray(slope_idx, dtype=int) if slope_idx is not None else step_idx,
    )


def _population_mu_for_prediction_rows(
    config,
    params,
    rows: pd.DataFrame,
    person_col="Person",
    person_data=None,
    person_id_col=None,
) -> np.ndarray:
    pop = config.get("population_model", {})
    if not pop or not pop.get("enabled"):
        return np.zeros(len(rows), dtype=float)

    beta = np.asarray(params.get("population", np.array([], dtype=float)), dtype=float)
    columns = list(pop.get("columns", []))
    if beta.size == 0 or not columns:
        return np.zeros(len(rows), dtype=float)

    source = rows.copy()
    if person_col not in source.columns:
        raise ValueError(f"Prediction data must contain person column '{person_col}'.")
    source[person_col] = source[person_col].astype(str)
    if person_col != "Person":
        source = source.rename(columns={person_col: "Person"})

    if isinstance(person_data, pd.DataFrame) and not person_data.empty:
        pdf = person_data.copy()
        if person_id_col is None:
            person_id_col = "Person" if "Person" in pdf.columns else pdf.columns[0]
        if person_id_col not in pdf.columns:
            raise ValueError(f"person_id_col '{person_id_col}' was not found in prediction person_data.")
        pdf = pdf.rename(columns={person_id_col: "Person"})
        pdf["Person"] = pdf["Person"].astype(str)
        if pdf["Person"].duplicated().any():
            examples = pdf.loc[pdf["Person"].duplicated(), "Person"].head(5).tolist()
            raise ValueError("prediction person_data contains duplicate person IDs: " + ", ".join(map(str, examples)))
        missing_terms = [t for t in pop.get("terms", []) if t not in source.columns and t in pdf.columns]
        if missing_terms:
            source = source.merge(pdf[["Person", *missing_terms]], on="Person", how="left")

    matrix_parts: list[np.ndarray] = []
    built_columns: list[str] = []
    if "Intercept" in columns:
        matrix_parts.append(np.ones((len(source), 1), dtype=float))
        built_columns.append("Intercept")

    fitted_person_data = pop.get("person_data", pd.DataFrame())
    for term in pop.get("terms", []):
        if term not in source.columns:
            raise ValueError(
                f"Prediction data for unknown persons requires population covariate '{term}'. "
                "Add it to the new design table or upload a matching person_data table."
            )
        series = source[term]
        if series.isna().any():
            missing_people = source.loc[series.isna(), "Person"].astype(str).head(10).tolist()
            raise ValueError(
                f"population covariate '{term}' is missing for prediction person(s): "
                + ", ".join(missing_people)
            )
        numeric_col = term in columns
        dummy_cols = [c for c in columns if c.startswith(f"{term}_")]
        if numeric_col:
            numeric = pd.to_numeric(series, errors="coerce")
            if numeric.isna().any():
                raise ValueError(f"population covariate '{term}' must be numeric for this fitted model.")
            values = numeric.to_numpy(dtype=float)
            transform = pop.get("numeric_transforms", {}).get(term, {})
            if isinstance(transform, dict) and transform.get("standardized"):
                center = float(transform.get("center", 0.0))
                scale = float(transform.get("scale", 1.0))
                if not np.isfinite(scale) or abs(scale) <= 1e-12:
                    scale = 1.0
                values = (values - center) / scale
            matrix_parts.append(values.reshape(-1, 1))
            built_columns.append(term)
        elif dummy_cols:
            fitted_levels = []
            if isinstance(fitted_person_data, pd.DataFrame) and term in fitted_person_data.columns:
                fitted_levels = sorted(fitted_person_data[term].dropna().astype(str).unique().tolist())
            if not fitted_levels:
                fitted_levels = ["__reference__", *[c[len(term) + 1:] for c in dummy_cols]]
            incoming = series.astype(str)
            unknown = sorted(set(incoming.unique().tolist()) - set(fitted_levels))
            if unknown:
                raise ValueError(
                    f"population covariate '{term}' contains level(s) not seen in the fitted population data: "
                    + ", ".join(unknown[:10])
                )
            mat = np.zeros((len(source), len(dummy_cols)), dtype=float)
            for j, col in enumerate(dummy_cols):
                level = col[len(term) + 1:]
                mat[:, j] = (incoming == level).astype(float)
            matrix_parts.append(mat)
            built_columns.extend(dummy_cols)

    X = np.column_stack(matrix_parts) if matrix_parts else np.zeros((len(source), 0), dtype=float)
    if built_columns != columns:
        missing = [c for c in columns if c not in built_columns]
        if missing:
            raise ValueError("Could not build prediction population columns: " + ", ".join(missing))
    if X.size and not np.all(np.isfinite(X)):
        raise ValueError("Prediction population model matrix contains non-finite values.")
    return X @ beta


def predict_mfrm_design(
    res,
    new_data: pd.DataFrame,
    person_col="Person",
    score_col=None,
    person_data=None,
    person_id_col=None,
    use_fitted_person=True,
):
    """Predict category probabilities for new or held-out design rows.

    Scope:
    - Facet levels must already exist in the fitted model.
    - Known persons can be predicted conditionally on their fitted estimate.
    - Unknown persons require MML and are predicted marginally over the population
      distribution; latent-regression covariates are used when supplied.
    """
    if new_data is None or not isinstance(new_data, pd.DataFrame) or new_data.empty:
        return {
            "available": False,
            "reason": "No new design rows were supplied.",
            "table": pd.DataFrame(),
            "issues": pd.DataFrame(),
        }

    config = res.get("config", {})
    prep = res.get("prep", {})
    params = res.get("params", {})
    facet_names = list(config.get("facet_names", []))
    required = [person_col] + facet_names
    missing_cols = [c for c in required if c not in new_data.columns]
    if missing_cols:
        raise ValueError("Prediction data is missing required column(s): " + ", ".join(missing_cols))

    df = new_data.copy()
    df[person_col] = df[person_col].astype(str)
    if person_col != "Person":
        df = df.rename(columns={person_col: "Person"})
    person_col = "Person"
    for facet in facet_names:
        df[facet] = df[facet].astype(str)

    n = len(df)
    base_eta = np.zeros(n, dtype=float)
    facet_signs = config.get("facet_signs", {})
    index_info = {"facets": {}, "step_idx": None, "slope_idx": None}
    issue_rows = []
    for facet in facet_names:
        levels = [str(x) for x in prep.get("levels", {}).get(facet, [])]
        level_map = {level: i for i, level in enumerate(levels)}
        unknown = sorted(set(df[facet].astype(str).tolist()) - set(level_map.keys()))
        if unknown:
            for value in unknown[:20]:
                issue_rows.append({
                    "Type": "unknown_facet_level",
                    "Facet": facet,
                    "Level": value,
                    "Action": "Use only facet levels present in the fitted model, or refit the model including this level.",
                })
            raise ValueError(
                f"Prediction data contains unknown {facet} level(s): "
                + ", ".join(unknown[:10])
            )
        idx = df[facet].map(level_map).to_numpy(dtype=int)
        index_info["facets"][facet] = idx
        base_eta += facet_signs.get(facet, -1) * params["facets"][facet][idx]

    if config.get("step_facet"):
        index_info["step_idx"] = index_info["facets"][config["step_facet"]]
    if config.get("slope_facet"):
        index_info["slope_idx"] = index_info["facets"][config["slope_facet"]]

    person_levels = [str(x) for x in prep.get("levels", {}).get("Person", [])]
    person_map = {level: i for i, level in enumerate(person_levels)}
    person_idx = df[person_col].map(person_map)
    known_mask = person_idx.notna().to_numpy(dtype=bool)
    conditional_mask = known_mask & bool(use_fitted_person)
    marginal_mask = ~conditional_mask

    if marginal_mask.any() and config.get("method") != "MML":
        unknown_examples = df.loc[marginal_mask, person_col].astype(str).drop_duplicates().head(10).tolist()
        raise ValueError(
            "Prediction for unknown persons requires MML so the population distribution can be used. "
            "Unknown person(s): " + ", ".join(unknown_examples)
        )

    cat_vals = np.arange(prep["rating_min"], prep["rating_max"] + 1)
    probs = np.zeros((n, len(cat_vals)), dtype=float)
    theta_used = np.full(n, np.nan, dtype=float)
    population_mean = np.full(n, np.nan, dtype=float)
    scope = np.array(["unknown"] * n, dtype=object)

    if conditional_mask.any():
        person_tbl = res.get("facets", {}).get("person", pd.DataFrame())
        if isinstance(person_tbl, pd.DataFrame) and "Person" in person_tbl.columns and "Estimate" in person_tbl.columns:
            theta_lookup = person_tbl.set_index(person_tbl["Person"].astype(str))["Estimate"].astype(float).to_dict()
            theta_known = df.loc[conditional_mask, person_col].map(theta_lookup).to_numpy(dtype=float)
        else:
            theta_arr = np.asarray(params.get("theta", np.array([], dtype=float)), dtype=float)
            theta_known = theta_arr[person_idx[conditional_mask].astype(int).to_numpy()] if theta_arr.size else np.zeros(int(conditional_mask.sum()))
        theta_used[conditional_mask] = theta_known
        eta_known = base_eta[conditional_mask] + theta_known
        step_known = index_info["step_idx"][conditional_mask] if index_info["step_idx"] is not None else None
        slope_known = index_info["slope_idx"][conditional_mask] if index_info["slope_idx"] is not None else None
        probs[conditional_mask, :] = _category_probs_from_eta_for_prediction(
            config, params, eta_known, step_idx=step_known, slope_idx=slope_known
        )
        scope[conditional_mask] = "known_person_conditional_on_fitted_measure"
        pop_mu = compute_population_mu(params, config)
        if pop_mu.size:
            population_mean[conditional_mask] = pop_mu[person_idx[conditional_mask].astype(int).to_numpy()]

    if marginal_mask.any():
        quad = make_mml_quadrature(config, int(config.get("quad_points") or 15))
        unknown_rows = df.loc[marginal_mask].copy()
        mu_unknown = _population_mu_for_prediction_rows(
            config,
            params,
            unknown_rows,
            person_col=person_col,
            person_data=person_data,
            person_id_col=person_id_col,
        )
        population_mean[marginal_mask] = mu_unknown
        prob_unknown = np.zeros((int(marginal_mask.sum()), len(cat_vals)), dtype=float)
        step_unknown = index_info["step_idx"][marginal_mask] if index_info["step_idx"] is not None else None
        slope_unknown = index_info["slope_idx"][marginal_mask] if index_info["slope_idx"] is not None else None
        for theta_node, weight in zip(quad["nodes"], quad["weights"]):
            eta_unknown = base_eta[marginal_mask] + mu_unknown + float(theta_node)
            prob_unknown += float(weight) * _category_probs_from_eta_for_prediction(
                config, params, eta_unknown, step_idx=step_unknown, slope_idx=slope_unknown
            )
        probs[marginal_mask, :] = prob_unknown
        scope[marginal_mask] = np.where(
            known_mask[marginal_mask],
            "known_person_mml_population_marginal",
            "unknown_person_mml_population_marginal",
        )

    probs = _normalise_probability_rows(probs)
    expected = probs.dot(cat_vals)
    max_idx = np.argmax(probs, axis=1)
    with np.errstate(divide="ignore", invalid="ignore"):
        entropy = -np.sum(np.where(probs > 0, probs * np.log(probs), 0.0), axis=1)
    max_entropy = float(np.log(probs.shape[1])) if probs.shape[1] > 1 else np.nan
    uncertainty = entropy / max_entropy if np.isfinite(max_entropy) and max_entropy > 0 else np.zeros_like(entropy)

    prob_df = pd.DataFrame(probs, columns=[f"P_{v}" for v in cat_vals])
    out = pd.concat([df.reset_index(drop=True), prob_df], axis=1)
    out["Expected"] = expected
    out["PredictedCategory"] = cat_vals[max_idx]
    out["PredictionConfidence"] = probs[np.arange(n), max_idx]
    out["PredictionEntropy"] = entropy
    out["PredictionUncertainty"] = uncertainty
    out["PersonStatus"] = np.where(known_mask, "Known", "Unknown")
    out["PredictionScope"] = scope
    out["ThetaUsed"] = theta_used
    out["PopulationMean"] = population_mean

    score_col_final = score_col if score_col and score_col in out.columns else ("Score" if "Score" in out.columns else None)
    if score_col_final:
        observed = pd.to_numeric(out[score_col_final], errors="coerce")
        valid_obs = observed.notna()
        if valid_obs.any():
            fractional = valid_obs & ((observed - np.round(observed)).abs() > np.sqrt(np.finfo(float).eps))
            if fractional.any():
                raise ValueError("Observed score column for held-out prediction must contain integer category codes.")
            out["Observed"] = observed
            out["Residual"] = out["Observed"] - out["Expected"]
            k_vals = cat_vals.astype(float)
            var = probs.dot(k_vals ** 2) - expected ** 2
            var = np.where(var <= 1e-10, np.nan, var)
            out["Var"] = var
            out["StdResidual"] = out["Residual"] / np.sqrt(out["Var"])

    first_cols = [c for c in ["Person", *facet_names] if c in out.columns]
    tail_cols = [c for c in out.columns if c not in first_cols]
    return {
        "available": True,
        "reason": "Prediction computed for supplied design rows.",
        "table": out[first_cols + tail_cols],
        "issues": pd.DataFrame(issue_rows),
        "interpretation": (
            "Known persons are predicted conditionally on their fitted measure. "
            "Unknown persons are supported only for MML and are predicted by integrating "
            "over the fitted population distribution; this is a population-scenario forecast, "
            "not a person-specific posterior score."
        ),
    }


def simulate_from_fitted_model(
    res,
    n_replicates=100,
    seed=20260411,
    include_row_draws=False,
    max_row_draw_rows=200000,
):
    """Simulate response data from the fitted row-level probability matrix."""
    scorefile = compute_fitted_prediction_table(res)
    if scorefile.empty:
        return {
            "available": False,
            "reason": "No fitted rows are available for simulation.",
            "summary": pd.DataFrame(),
            "category_counts": pd.DataFrame(),
            "row_draws": pd.DataFrame(),
        }

    probs = compute_prob_matrix(res)
    if probs is None or probs.shape[0] != len(scorefile):
        return {
            "available": False,
            "reason": "Prediction probabilities are unavailable for simulation.",
            "summary": pd.DataFrame(),
            "category_counts": pd.DataFrame(),
            "row_draws": pd.DataFrame(),
        }

    probs = np.asarray(probs, dtype=float)
    probs = np.where(np.isfinite(probs) & (probs >= 0), probs, 0.0)
    row_sum = probs.sum(axis=1, keepdims=True)
    probs = np.divide(probs, row_sum, out=np.full_like(probs, 1.0 / probs.shape[1]), where=row_sum > 0)
    cdf = np.cumsum(probs, axis=1)
    cdf[:, -1] = 1.0

    n_rep = max(1, int(n_replicates or 1))
    rng = np.random.default_rng(int(seed))
    cat_vals = np.arange(res["prep"]["rating_min"], res["prep"]["rating_max"] + 1)
    weights = (
        pd.to_numeric(scorefile["Weight"], errors="coerce").to_numpy(dtype=float)
        if "Weight" in scorefile.columns else np.ones(len(scorefile), dtype=float)
    )
    weights = np.where(np.isfinite(weights) & (weights > 0), weights, 0.0)
    total_weight = float(np.sum(weights))
    if total_weight <= 0:
        weights = np.ones(len(scorefile), dtype=float)
        total_weight = float(len(scorefile))

    observed = pd.to_numeric(scorefile.get("Observed", pd.Series(dtype=float)), errors="coerce").to_numpy(dtype=float)
    expected = probs.dot(cat_vals)
    observed_mean = float(np.average(observed, weights=weights)) if np.all(np.isfinite(observed)) else np.nan
    expected_mean = float(np.average(expected, weights=weights))

    summary_rows = []
    count_rows = []
    row_draw_parts = []
    store_row_draws = bool(include_row_draws) and (len(scorefile) * n_rep <= int(max_row_draw_rows))
    id_cols = ["Person"] + list(res.get("config", {}).get("facet_names", []))
    id_cols = [c for c in id_cols if c in scorefile.columns]

    for rep in range(1, n_rep + 1):
        u = rng.random(len(scorefile))
        draw_idx = np.sum(u[:, None] > cdf, axis=1)
        sim_scores = cat_vals[draw_idx]
        sim_mean = float(np.average(sim_scores, weights=weights))
        sim_var = float(np.average((sim_scores - sim_mean) ** 2, weights=weights))
        summary_rows.append({
            "Replicate": rep,
            "Rows": int(len(sim_scores)),
            "WeightedRows": total_weight,
            "MeanScore": sim_mean,
            "SDScore": float(np.sqrt(max(sim_var, 0.0))),
            "MinScore": int(np.min(sim_scores)),
            "MaxScore": int(np.max(sim_scores)),
            "ExpectedMeanFromModel": expected_mean,
            "ObservedMean": observed_mean,
            "MeanMinusObserved": sim_mean - observed_mean if np.isfinite(observed_mean) else np.nan,
        })
        for cat in cat_vals:
            mask = sim_scores == cat
            weighted_count = float(np.sum(weights[mask]))
            count_rows.append({
                "Replicate": rep,
                "Category": int(cat),
                "Count": int(np.sum(mask)),
                "Percent": float(np.mean(mask)),
                "WeightedCount": weighted_count,
                "WeightedPercent": weighted_count / total_weight if total_weight > 0 else np.nan,
            })
        if store_row_draws:
            part = scorefile[id_cols].copy()
            part["Replicate"] = rep
            part["SimulatedScore"] = sim_scores
            row_draw_parts.append(part)

    return {
        "available": True,
        "reason": "Simulated from fitted row-level category probabilities.",
        "summary": pd.DataFrame(summary_rows),
        "category_counts": pd.DataFrame(count_rows),
        "row_draws": pd.concat(row_draw_parts, ignore_index=True) if row_draw_parts else pd.DataFrame(),
        "n_replicates": n_rep,
        "seed": int(seed),
        "interpretation": (
            "These simulations hold the observed design and fitted parameters fixed. "
            "They are useful design forecasts and model checks, but they do not prove "
            "future performance and they do not include uncertainty from refitting the model."
        ),
    }


def simulate_refit_design(
    res,
    n_replicates=3,
    seed=20260411,
    missing_rate=0.0,
    refit_maxit=30,
    refit_reltol=1e-3,
    refit_method=None,
    refit_mml_engine=None,
    refit_quad_points=None,
):
    """Simulate response data, apply prospective missingness, and refit.

    This is intentionally small-scope and capped by the UI. It estimates
    operational risk (non-convergence, reliability loss) under the current
    design, not parameter-recovery truth.
    """
    prep = res.get("prep", {})
    config = res.get("config", {})
    data = prep.get("data", pd.DataFrame())
    if data.empty:
        return {
            "available": False,
            "reason": "No fitted data are available for refit simulation.",
            "summary": pd.DataFrame(),
            "category_counts": pd.DataFrame(),
        }

    probs = compute_prob_matrix(res)
    if probs is None or probs.shape[0] != len(data):
        return {
            "available": False,
            "reason": "Fitted row probabilities are unavailable for refit simulation.",
            "summary": pd.DataFrame(),
            "category_counts": pd.DataFrame(),
        }
    probs = _normalise_probability_rows(probs)
    cdf = np.cumsum(probs, axis=1)
    cdf[:, -1] = 1.0
    cat_vals = np.arange(prep["rating_min"], prep["rating_max"] + 1)
    rng = np.random.default_rng(int(seed))

    n_rep = max(1, int(n_replicates or 1))
    miss_rate = min(max(float(missing_rate or 0.0), 0.0), 0.95)
    facet_names = list(config.get("facet_names", []))
    base_cols = ["Person", *facet_names, "Score"]
    if "Weight" in data.columns:
        base_cols.append("Weight")
    base = data[base_cols].copy()
    for col in ["Person", *facet_names]:
        base[col] = base[col].astype(str)

    method = str(refit_method or config.get("method", "JMLE")).upper()
    if method not in {"JMLE", "MML"}:
        method = str(config.get("method", "JMLE")).upper()
    mml_engine = refit_mml_engine or config.get("mml_engine_requested") or config.get("mml_engine") or "EM"
    quad_points = int(refit_quad_points or config.get("quad_points") or 5)
    population_prior_sd = float(config.get("population_prior_sd") or 1.0) if method == "MML" else 1.0
    if method != "MML":
        mml_engine = "EM"

    population = res.get("population", {})
    person_data = population.get("person_data", pd.DataFrame()) if isinstance(population, dict) else pd.DataFrame()
    if isinstance(person_data, pd.DataFrame) and "PopulationMean" in person_data.columns:
        person_data = person_data.drop(columns=["PopulationMean"])
    population_formula = config.get("population_formula", "") if method == "MML" else None
    population_standardize_numeric = bool(config.get("population_standardize_numeric", False)) if method == "MML" else False
    population_categorical_terms = config.get("population_categorical_terms", []) if method == "MML" else []
    population_numeric_terms = config.get("population_numeric_terms", []) if method == "MML" else []

    anchor_audit = config.get("anchor_audit", {})
    anchor_df = anchor_audit.get("valid_anchors", pd.DataFrame()) if isinstance(anchor_audit, dict) else pd.DataFrame()
    group_anchor_df = anchor_audit.get("valid_group_anchors", pd.DataFrame()) if isinstance(anchor_audit, dict) else pd.DataFrame()
    anchor_settings = anchor_audit.get("settings", {}) if isinstance(anchor_audit, dict) else {}

    summary_rows = []
    count_rows = []
    for rep in range(1, n_rep + 1):
        u = rng.random(len(base))
        draw_idx = np.sum(u[:, None] > cdf, axis=1)
        sim_scores = cat_vals[draw_idx]
        sim_df = base.copy()
        sim_df["Score"] = sim_scores
        if miss_rate > 0:
            keep_mask = rng.random(len(sim_df)) >= miss_rate
            if keep_mask.sum() < max(2, len(facet_names) + 2):
                keep_mask[:] = True
            sim_df = sim_df.loc[keep_mask].copy()

        for cat in cat_vals:
            count_rows.append({
                "Replicate": rep,
                "Category": int(cat),
                "Count": int((sim_df["Score"] == cat).sum()),
                "Percent": float((sim_df["Score"] == cat).mean()) if len(sim_df) else np.nan,
            })

        row = {
            "Replicate": rep,
            "MissingRateTarget": miss_rate,
            "RowsBeforeMissing": int(len(base)),
            "RowsAfterMissing": int(len(sim_df)),
            "CategoriesObserved": int(sim_df["Score"].nunique()) if len(sim_df) else 0,
            "Method": method,
            "Model": config.get("model"),
            "Converged": False,
            "Iterations": np.nan,
            "GradientNorm": np.nan,
            "LogLik": np.nan,
            "PersonReliability": np.nan,
            "MinFacetReliability": np.nan,
            "ElapsedSeconds": np.nan,
            "Error": "",
        }
        try:
            refit_res = mfrm_estimate(
                sim_df,
                person_col="Person",
                facet_cols=facet_names,
                score_col="Score",
                rating_min=prep["rating_min"],
                rating_max=prep["rating_max"],
                weight_col="Weight" if "Weight" in sim_df.columns else None,
                keep_original=True,
                model=config.get("model", "RSM"),
                method=method,
                step_facet=config.get("step_facet"),
                slope_facet=config.get("slope_facet"),
                person_data=person_data if method == "MML" and isinstance(person_data, pd.DataFrame) and not person_data.empty else None,
                person_id_col="Person" if method == "MML" and isinstance(person_data, pd.DataFrame) and not person_data.empty else None,
                population_formula=population_formula,
                population_standardize_numeric=population_standardize_numeric,
                population_categorical_terms=population_categorical_terms,
                population_numeric_terms=population_numeric_terms,
                anchor_df=anchor_df,
                group_anchor_df=group_anchor_df,
                noncenter_facet=config.get("noncenter_facet", "Person"),
                dummy_facets=config.get("dummy_facets", []),
                positive_facets=config.get("positive_facets", []),
                quad_points=quad_points,
                population_prior_sd=population_prior_sd,
                maxit=int(refit_maxit),
                reltol=float(refit_reltol),
                mml_engine=mml_engine,
                anchor_policy="warn",
                min_common_anchors=int(anchor_settings.get("min_common_anchors", 2)),
                min_obs_per_element=int(anchor_settings.get("min_obs_per_element", 2)),
                min_obs_per_category=int(anchor_settings.get("min_obs_per_category", 1)),
                compute_plausible_values=False,
            )
            refit_diag = mfrm_diagnostics(refit_res, compute_pca=False, compute_marginal=False)
            fit_summary = refit_res.get("summary", pd.DataFrame())
            if isinstance(fit_summary, pd.DataFrame) and not fit_summary.empty:
                s0 = fit_summary.iloc[0]
                row["Converged"] = bool(s0.get("Converged", False))
                row["Iterations"] = int(s0.get("Iterations", 0) or 0)
                row["GradientNorm"] = float(s0.get("GradientNorm", np.nan))
                row["LogLik"] = float(s0.get("LogLik", np.nan))
                row["ElapsedSeconds"] = float(s0.get("ElapsedSeconds", np.nan))
            rel = refit_diag.get("reliability", pd.DataFrame())
            if isinstance(rel, pd.DataFrame) and not rel.empty and "Reliability" in rel.columns:
                person_rel = rel.loc[rel["Facet"].astype(str) == "Person", "Reliability"]
                if not person_rel.empty:
                    row["PersonReliability"] = float(pd.to_numeric(person_rel, errors="coerce").iloc[0])
                rel_vals = pd.to_numeric(rel["Reliability"], errors="coerce").dropna()
                if len(rel_vals):
                    row["MinFacetReliability"] = float(rel_vals.min())
        except Exception as exc:
            row["Error"] = str(exc)[:500]
        summary_rows.append(row)

    return {
        "available": True,
        "reason": "Simulated response data were optionally made missing and refit with the current standalone engine.",
        "summary": pd.DataFrame(summary_rows),
        "category_counts": pd.DataFrame(count_rows),
        "n_replicates": n_rep,
        "seed": int(seed),
        "interpretation": (
            "Refit simulation is a stress test of the current design and optimizer path. "
            "Use it to screen convergence and reliability sensitivity to missingness; "
            "do not treat a small number of replicates as a formal prospective power study."
        ),
    }


# ============================================================================
# Parameter-recovery ADEMP simulation
# ============================================================================
# Generates data from a known many-facet ground truth, refits the requested
# model on each replicate, aligns the estimated location-indeterminate
# blocks (Person, Rater, Criterion) to remove the Rasch identification
# constant, and reports bias / RMSE / MCSE / coverage95 per parameter type.
# The reporting layout follows the ADEMP simulation-study framing of
# Morris, White, and Crowther (2019): Aims, Data-generating mechanism,
# Estimands, Methods, Performance measures.

_RECOVERY_LOCATION_FACETS = ("Person", "Rater", "Criterion")


def _simulate_recovery_responses(
    *,
    theta: np.ndarray,
    rater: np.ndarray,
    criterion: np.ndarray,
    steps: np.ndarray,
    slopes: np.ndarray | None,
    model: str,
    rating_min: int,
    rng: np.random.Generator,
) -> pd.DataFrame:
    """Draw a complete design table from the requested model with known truth.

    ``steps`` is a 2-D array of cumulative step thresholds with shape
    ``(n_criterion, n_cat - 1)``; for RSM the same row is broadcast across
    criteria. ``slopes`` is required for GPCM and ignored elsewhere.
    The returned frame carries Person, Rater, Criterion, and Score columns.
    """
    n_person = theta.size
    n_rater = rater.size
    n_criterion = criterion.size
    n_cat = steps.shape[1] + 1
    cat_vals = np.arange(rating_min, rating_min + n_cat)
    rows = []
    for i in range(n_person):
        for j in range(n_rater):
            for k in range(n_criterion):
                eta = float(theta[i] - rater[j] - criterion[k])
                a = float(slopes[k]) if (slopes is not None and model == "GPCM") else 1.0
                step_row = steps[0] if model == "RSM" else steps[k]
                # Polytomous category log-numerators (Andersen 1977 / Muraki 1992):
                # log P_l prop sum_{r=0}^{l-1} a * (eta - step_r), with the l=0
                # term equal to zero.
                log_num = np.zeros(n_cat)
                cumulative = 0.0
                for l in range(1, n_cat):
                    cumulative += a * (eta - float(step_row[l - 1]))
                    log_num[l] = cumulative
                log_num -= log_num.max()
                p = np.exp(log_num)
                p = p / p.sum()
                draw = int(np.searchsorted(np.cumsum(p), rng.uniform()))
                rows.append({
                    "Person": f"P{i+1:02d}",
                    "Rater": f"R{j+1}",
                    "Criterion": f"C{k+1}",
                    "Score": int(cat_vals[draw]),
                })
    return pd.DataFrame(rows)


def _mean_align(values: np.ndarray) -> np.ndarray:
    """Subtract the finite mean so a location-block has zero overall mean."""
    arr = np.asarray(values, dtype=float)
    finite = np.isfinite(arr)
    if not finite.any():
        return arr
    return arr - float(arr[finite].mean())


def _recovery_rows_from_fit(
    res: dict,
    truth: dict,
    *,
    rep: int,
    include_person: bool,
    measures: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """Build one rep's long table of (Truth, Estimate, ErrorAligned, ...) rows.

    Location-block parameters (Person, Rater, Criterion) are mean-aligned
    within each rep so the Rasch identification constant does not appear
    as a systematic bias. The raw unaligned error is retained as
    ``ErrorRaw`` for transparency. SE-based coverage at the 95 % level
    is reported when the estimated SE is finite and positive; SE values
    are read from the optional ``measures`` table (the combined
    Facet/Level/Estimate/SE frame produced by ``mfrm_diagnostics``).
    """
    facets = res.get("facets", {}) if isinstance(res, dict) else {}
    rows = []
    z95 = float(_norm.ppf(0.975))

    # Build (Facet, Level) lookups from the optional measures table.
    se_lookup: dict[tuple[str, str], float] = {}
    uncertainty_lookup: dict[tuple[str, str], dict[str, str]] = {}
    uncertainty_cols = [
        "SE_Method", "SE_Status", "CI_Method", "CI_Status", "UncertaintyCaution",
    ]
    if isinstance(measures, pd.DataFrame) and not measures.empty and "SE" in measures.columns:
        for facet_val, level_val, se_val in zip(
            measures["Facet"].astype(str),
            measures["Level"].astype(str),
            pd.to_numeric(measures["SE"], errors="coerce"),
        ):
            try:
                se_lookup[(facet_val, level_val)] = float(se_val)
            except (TypeError, ValueError):
                continue

        if {"Facet", "Level"}.issubset(measures.columns):
            for _, measure_row in measures.iterrows():
                key = (str(measure_row.get("Facet")), str(measure_row.get("Level")))
                uncertainty_lookup[key] = {
                    col: str(measure_row.get(col, "not_reported"))
                    for col in uncertainty_cols
                }

    def _se_for(facet_name: str, level: str) -> float:
        return float(se_lookup.get((facet_name, str(level)), np.nan))

    def _uncertainty_for(facet_name: str, level: str) -> dict[str, str]:
        default = {
            "SE_Method": "not reported by diagnostics",
            "SE_Status": "not_reported",
            "CI_Method": "not reported by diagnostics",
            "CI_Status": "not_reported",
            "UncertaintyCaution": "Coverage is unavailable unless finite positive SE values are reported.",
        }
        found = uncertainty_lookup.get((facet_name, str(level)))
        if not found:
            return default
        out = default.copy()
        out.update({k: v for k, v in found.items() if v and v != "nan"})
        return out

    # --- Person rows -------------------------------------------------------
    if include_person:
        person_tbl = facets.get("person", pd.DataFrame())
        if isinstance(person_tbl, pd.DataFrame) and not person_tbl.empty:
            person_lookup = {
                str(p): float(est)
                for p, est in zip(
                    person_tbl["Person"].astype(str),
                    pd.to_numeric(person_tbl["Estimate"], errors="coerce"),
                )
            }
            truth_persons = truth.get("Person", {})
            est_arr = np.array([person_lookup.get(str(p), np.nan) for p in truth_persons], dtype=float)
            truth_arr = np.array([truth_persons[p] for p in truth_persons], dtype=float)
            est_aligned = _mean_align(est_arr)
            truth_aligned = _mean_align(truth_arr)
            for p, t_val, e_val, e_aligned, t_aligned in zip(
                truth_persons, truth_arr, est_arr, est_aligned, truth_aligned
            ):
                se = _se_for("Person", str(p))
                err_aligned = e_aligned - t_aligned
                err_raw = e_val - t_val
                uncertainty = _uncertainty_for("Person", str(p))
                covered = (
                    bool(abs(err_aligned) <= z95 * se)
                    if np.isfinite(se) and se > 0
                    else np.nan
                )
                rows.append({
                    "rep": rep,
                    "ParameterType": "Person",
                    "Facet": "Person",
                    "Level": str(p),
                    "Truth": float(t_val),
                    "Estimate": float(e_val),
                    "EstimateAligned": float(e_aligned),
                    "Truth_Aligned": float(t_aligned),
                    "ErrorRaw": float(err_raw),
                    "ErrorAligned": float(err_aligned),
                    "SE": float(se) if np.isfinite(se) else np.nan,
                    "Covered95": covered,
                    "NominalCILevel": 0.95,
                    "CoverageMethod": "mean-aligned Wald interval: abs(ErrorAligned) <= z_0.975 * SE",
                    "SE_Method": uncertainty["SE_Method"],
                    "SE_Status": uncertainty["SE_Status"],
                    "CI_Method": uncertainty["CI_Method"],
                    "CI_Status": uncertainty["CI_Status"],
                    "UncertaintyCaution": uncertainty["UncertaintyCaution"],
                    "ComparisonScale": "logit_mean_aligned",
                    "RecoveryComparable": np.isfinite(err_aligned),
                    "RecoveryBasis": "mean_alignment",
                })

    # --- Non-person facet rows --------------------------------------------
    others = facets.get("others", pd.DataFrame())
    if isinstance(others, pd.DataFrame) and not others.empty:
        for facet_name in _RECOVERY_LOCATION_FACETS[1:]:
            mask = others["Facet"].astype(str) == facet_name
            sub = others[mask]
            if sub.empty or facet_name not in truth:
                continue
            levels = sub["Level"].astype(str).tolist()
            est_arr = pd.to_numeric(sub["Estimate"], errors="coerce").to_numpy(dtype=float)
            truth_map = truth.get(facet_name, {})
            truth_arr = np.array([truth_map.get(str(l), np.nan) for l in levels], dtype=float)
            est_aligned = _mean_align(est_arr)
            truth_aligned = _mean_align(truth_arr)
            for level, t_val, e_val, e_aligned, t_aligned in zip(
                levels, truth_arr, est_arr, est_aligned, truth_aligned
            ):
                se = _se_for(facet_name, level)
                err_aligned = e_aligned - t_aligned
                err_raw = e_val - t_val
                uncertainty = _uncertainty_for(facet_name, level)
                covered = (
                    bool(abs(err_aligned) <= z95 * se)
                    if np.isfinite(se) and se > 0
                    else np.nan
                )
                rows.append({
                    "rep": rep,
                    "ParameterType": facet_name,
                    "Facet": facet_name,
                    "Level": str(level),
                    "Truth": float(t_val),
                    "Estimate": float(e_val),
                    "EstimateAligned": float(e_aligned),
                    "Truth_Aligned": float(t_aligned),
                    "ErrorRaw": float(err_raw),
                    "ErrorAligned": float(err_aligned),
                    "SE": float(se) if np.isfinite(se) else np.nan,
                    "Covered95": covered,
                    "NominalCILevel": 0.95,
                    "CoverageMethod": "mean-aligned Wald interval: abs(ErrorAligned) <= z_0.975 * SE",
                    "SE_Method": uncertainty["SE_Method"],
                    "SE_Status": uncertainty["SE_Status"],
                    "CI_Method": uncertainty["CI_Method"],
                    "CI_Status": uncertainty["CI_Status"],
                    "UncertaintyCaution": uncertainty["UncertaintyCaution"],
                    "ComparisonScale": "logit_mean_aligned",
                    "RecoveryComparable": np.isfinite(err_aligned),
                    "RecoveryBasis": "mean_alignment",
                })

    return pd.DataFrame(rows)


def _compact_value_counts(series: pd.Series | None, *, max_items: int = 4) -> str:
    """Return a compact, stable value-count summary for status columns."""
    if series is None:
        return ""
    clean = series.dropna().astype(str)
    clean = clean[clean.str.len() > 0]
    if clean.empty:
        return ""
    counts = clean.value_counts()
    pieces = [f"{idx}={int(count)}" for idx, count in counts.head(max_items).items()]
    remaining = int(counts.iloc[max_items:].sum()) if len(counts) > max_items else 0
    if remaining:
        pieces.append(f"other={remaining}")
    return "; ".join(pieces)


def _primary_status(series: pd.Series | None) -> str:
    """Return the modal status value, or not_reported when unavailable."""
    if series is None:
        return "not_reported"
    clean = series.dropna().astype(str)
    clean = clean[clean.str.len() > 0]
    if clean.empty:
        return "not_reported"
    return str(clean.value_counts().index[0])


def _coverage_diagnostic_label(
    coverage: float,
    coverage_n: int,
    *,
    nominal: float = 0.95,
) -> str:
    """Classify Monte Carlo coverage against a nominal CI level."""
    if coverage_n <= 0 or not np.isfinite(coverage):
        return "No finite positive-SE rows; coverage not evaluated."
    if coverage_n < 30:
        return "Screening only; increase replicates before treating coverage as calibration evidence."
    error = float(coverage - nominal)
    if abs(error) <= 0.05:
        return "Coverage close to nominal in this simulation condition."
    if error < -0.05:
        return "Under-coverage in this simulation condition; intervals may be too narrow."
    return "Over-coverage in this simulation condition; intervals may be conservative."


def _coverage_recommended_action(
    coverage: float,
    coverage_n: int,
    primary_se_status: str,
    *,
    nominal: float = 0.95,
) -> str:
    """Translate the coverage diagnostic into a manuscript-facing action."""
    if coverage_n <= 0 or not np.isfinite(coverage):
        return "Report that finite positive SEs were unavailable for this block; do not cite CI coverage."
    if coverage_n < 30:
        return "Increase Monte Carlo replicates and match the generator to the intended study design before citing coverage."
    error = float(coverage - nominal)
    status_note = f"SE status: {primary_se_status}."
    if abs(error) <= 0.05:
        return f"Report as a design-specific validation screen, with model/design/reps/seed and {status_note}"
    if error < -0.05:
        return f"Treat reported CIs cautiously, inspect SE method/status, and run a larger validation grid. {status_note}"
    return f"Intervals appear conservative in this condition; verify on adjacent designs before using as a general claim. {status_note}"


def _se_basis_risk(primary_se_status: str, se_status_summary: str = "") -> str:
    text = f"{primary_se_status} {se_status_summary}".lower()
    if "not_reported" in text or "not_available" in text:
        return "se_unavailable"
    if "regularized" in text:
        return "regularized_structural_covariance"
    if "ok" in text and "conditional_approximation" not in text:
        return "structural_covariance"
    if "conditional_approximation" in text or "posterior" in text:
        return "conditional_or_posterior_approximation"
    return "mixed_or_unclassified"


def _coverage_claim_status(
    coverage: float,
    coverage_n: int,
    primary_se_status: str,
    se_status_summary: str = "",
    *,
    nominal: float = 0.95,
) -> str:
    if coverage_n <= 0 or not np.isfinite(coverage):
        return "Do not claim"
    if coverage_n < 30:
        return "Screening only"
    risk = _se_basis_risk(primary_se_status, se_status_summary)
    if risk in {"se_unavailable", "mixed_or_unclassified"}:
        return "Report with caveat"
    if risk in {"regularized_structural_covariance", "conditional_or_posterior_approximation"}:
        return "Report with caveat"
    if abs(float(coverage - nominal)) > 0.05:
        return "Report with caveat"
    return "Ready"


def _recovery_summarize(rows: pd.DataFrame) -> pd.DataFrame:
    """Aggregate per-rep recovery rows into a per-parameter-type summary.

    Returns one row per ``(ParameterType, Facet, ComparisonScale)`` with
    bias, MCSE(bias), RMSE, MCSE(RMSE), MAE, correlation across rows,
    mean SE, SE availability rate, and coverage95.
    """
    if not isinstance(rows, pd.DataFrame) or rows.empty:
        return pd.DataFrame()
    summaries = []
    for (ptype, facet, scale), grp in rows.groupby(
        ["ParameterType", "Facet", "ComparisonScale"], dropna=False
    ):
        err_aligned = pd.to_numeric(grp["ErrorAligned"], errors="coerce").to_numpy()
        err_raw = pd.to_numeric(grp["ErrorRaw"], errors="coerce").to_numpy()
        truth = pd.to_numeric(grp["Truth"], errors="coerce").to_numpy()
        est_aligned = pd.to_numeric(grp["EstimateAligned"], errors="coerce").to_numpy()
        se = pd.to_numeric(grp["SE"], errors="coerce").to_numpy()
        covered = grp["Covered95"]
        ok = np.isfinite(err_aligned)
        n = int(ok.sum())
        if n == 0:
            continue
        bias = float(np.mean(err_aligned[ok]))
        mcse_bias = float(np.std(err_aligned[ok], ddof=1) / np.sqrt(n)) if n > 1 else np.nan
        rmse = float(np.sqrt(np.mean(err_aligned[ok] ** 2)))
        mcse_rmse = (
            float(np.std(err_aligned[ok] ** 2, ddof=1) / (2.0 * rmse * np.sqrt(n)))
            if n > 1 and rmse > 0
            else np.nan
        )
        mae = float(np.mean(np.abs(err_aligned[ok])))
        raw_bias = float(np.mean(err_raw[np.isfinite(err_raw)])) if np.any(np.isfinite(err_raw)) else np.nan
        raw_rmse = (
            float(np.sqrt(np.mean(err_raw[np.isfinite(err_raw)] ** 2)))
            if np.any(np.isfinite(err_raw)) else np.nan
        )
        ok_both = np.isfinite(truth) & np.isfinite(est_aligned)
        if ok_both.sum() > 1:
            corr = float(np.corrcoef(truth[ok_both], est_aligned[ok_both])[0, 1])
        else:
            corr = np.nan
        se_ok = np.isfinite(se) & (se > 0)
        mean_se = float(np.mean(se[se_ok])) if se_ok.any() else np.nan
        se_rate = float(np.mean(se_ok))
        covered_arr = covered.dropna().astype(bool).to_numpy()
        coverage_n = int(covered_arr.size)
        coverage = float(np.mean(covered_arr)) if covered_arr.size else np.nan
        nominal = 0.95
        coverage_error = float(coverage - nominal) if np.isfinite(coverage) else np.nan
        se_status_series = grp["SE_Status"] if "SE_Status" in grp.columns else None
        ci_status_series = grp["CI_Status"] if "CI_Status" in grp.columns else None
        primary_se_status = _primary_status(se_status_series)
        se_summary = _compact_value_counts(se_status_series)
        ci_summary = _compact_value_counts(ci_status_series)
        summaries.append({
            "ParameterType": ptype,
            "Facet": facet,
            "ComparisonScale": scale,
            "Rows": int(len(grp)),
            "Reps": int(grp["rep"].nunique()),
            "CoverageN": coverage_n,
            "MeanTruth": float(np.mean(truth[np.isfinite(truth)])) if np.any(np.isfinite(truth)) else np.nan,
            "MeanEstimate": float(np.mean(est_aligned[np.isfinite(est_aligned)])) if np.any(np.isfinite(est_aligned)) else np.nan,
            "Bias": bias,
            "MCSEBias": mcse_bias,
            "RMSE": rmse,
            "MCSERMSE": mcse_rmse,
            "MAE": mae,
            "RawBias": raw_bias,
            "RawRMSE": raw_rmse,
            "Correlation": corr,
            "MeanSE": mean_se,
            "SEAvailableRate": se_rate,
            "NominalCoverage": nominal,
            "Coverage95": coverage,
            "CoverageErrorFromNominal": coverage_error,
            "PrimarySEStatus": primary_se_status,
            "SEStatusSummary": se_summary,
            "CIStatusSummary": ci_summary,
            "SEBasisRisk": _se_basis_risk(primary_se_status, se_summary),
            "CoverageClaimStatus": _coverage_claim_status(
                coverage, coverage_n, primary_se_status, se_summary, nominal=nominal
            ),
            "CoverageInterpretation": _coverage_diagnostic_label(
                coverage, coverage_n, nominal=nominal
            ),
            "RecommendedAction": _coverage_recommended_action(
                coverage, coverage_n, primary_se_status, nominal=nominal
            ),
        })
    return pd.DataFrame(summaries).sort_values(
        ["ParameterType", "Facet", "ComparisonScale"]
    ).reset_index(drop=True)


def build_se_ci_coverage_report(
    recovery_bundle: dict | pd.DataFrame,
    *,
    nominal: float = 0.95,
) -> pd.DataFrame:
    """Build an explicit SE/CI coverage diagnostic table from recovery output.

    The table is intentionally separate from the ADEMP performance summary so
    manuscript exports can cite coverage only with its Monte Carlo size, SE
    status, interpretation, and recommended action.
    """
    if isinstance(recovery_bundle, pd.DataFrame):
        summary = _recovery_summarize(recovery_bundle)
    elif isinstance(recovery_bundle, dict):
        summary = recovery_bundle.get("recovery_summary", pd.DataFrame())
        if not isinstance(summary, pd.DataFrame) or summary.empty:
            recovery = recovery_bundle.get("recovery", pd.DataFrame())
            summary = _recovery_summarize(recovery) if isinstance(recovery, pd.DataFrame) else pd.DataFrame()
    else:
        summary = pd.DataFrame()
    if not isinstance(summary, pd.DataFrame) or summary.empty:
        return pd.DataFrame()

    report = summary.copy()
    if "NominalCoverage" not in report.columns:
        report["NominalCoverage"] = float(nominal)
    else:
        report["NominalCoverage"] = float(nominal)
    if "CoverageN" not in report.columns:
        report["CoverageN"] = np.nan
    coverage = pd.to_numeric(report.get("Coverage95"), errors="coerce")
    report["CoverageError"] = coverage - float(nominal)
    report["CoverageAbsError"] = report["CoverageError"].abs()
    if "PrimarySEStatus" not in report.columns:
        report["PrimarySEStatus"] = "not_reported"
    if "SEStatusSummary" not in report.columns:
        report["SEStatusSummary"] = ""
    if "CIStatusSummary" not in report.columns:
        report["CIStatusSummary"] = ""
    if "SEBasisRisk" not in report.columns:
        report["SEBasisRisk"] = [
            _se_basis_risk(status, summary)
            for status, summary in zip(
                report["PrimarySEStatus"].astype(str),
                report["SEStatusSummary"].astype(str),
            )
        ]
    if "CoverageClaimStatus" not in report.columns:
        report["CoverageClaimStatus"] = [
            _coverage_claim_status(
                cov,
                int(n) if np.isfinite(n) else 0,
                str(status),
                str(summary),
                nominal=nominal,
            )
            for cov, n, status, summary in zip(
                coverage,
                pd.to_numeric(report["CoverageN"], errors="coerce"),
                report["PrimarySEStatus"].astype(str),
                report["SEStatusSummary"].astype(str),
            )
        ]
    report["Interpretation"] = [
        _coverage_diagnostic_label(cov, int(n) if np.isfinite(n) else 0, nominal=nominal)
        for cov, n in zip(coverage, pd.to_numeric(report["CoverageN"], errors="coerce"))
    ]
    report["RecommendedAction"] = [
        _coverage_recommended_action(
            cov,
            int(n) if np.isfinite(n) else 0,
            str(status),
            nominal=nominal,
        )
        for cov, n, status in zip(
            coverage,
            pd.to_numeric(report["CoverageN"], errors="coerce"),
            report["PrimarySEStatus"].astype(str),
        )
    ]
    ordered = [
        "ParameterType", "Facet", "ComparisonScale", "Reps", "Rows",
        "CoverageN", "NominalCoverage", "Coverage95", "CoverageError",
        "CoverageAbsError", "SEAvailableRate", "MeanSE", "PrimarySEStatus",
        "SEStatusSummary", "CIStatusSummary", "SEBasisRisk", "CoverageClaimStatus",
        "Interpretation", "RecommendedAction",
    ]
    available_cols = [col for col in ordered if col in report.columns]
    rest = [col for col in report.columns if col not in available_cols]
    return report[available_cols + rest].reset_index(drop=True)


def evaluate_se_ci_coverage(**kwargs) -> dict:
    """Run parameter recovery and attach the explicit SE/CI coverage report."""
    bundle = evaluate_parameter_recovery(**kwargs)
    bundle["coverage_report"] = build_se_ci_coverage_report(bundle)
    return bundle


def evaluate_parameter_recovery(
    *,
    n_person: int = 40,
    n_rater: int = 3,
    n_criterion: int = 3,
    n_cat: int = 4,
    reps: int = 10,
    theta_sd: float = 1.0,
    rater_sd: float = 0.35,
    criterion_sd: float = 0.25,
    step_span: float = 1.4,
    model: str = "RSM",
    fit_method: str = "JMLE",
    seed: int | None = 20260601,
    maxit: int = 25,
    reltol: float = 1e-4,
    quad_points: int = 7,
    include_person: bool = True,
    slopes: np.ndarray | None = None,
    estimate_population_sd: bool = False,
) -> dict:
    """Run a parameter-recovery simulation and return an ADEMP bundle.

    The data-generating mechanism samples person measures, rater
    severities, and criterion difficulties from independent normals;
    step thresholds are equally spaced across the rating scale
    (RSM uses shared thresholds; PCM / GPCM use per-criterion
    thresholds with a small symmetric perturbation per criterion).
    Each replicate refits the requested model via ``mfrm_estimate``,
    aligns the location-indeterminate parameter blocks to the truth,
    and reports per-row error and coverage95 (when SE is finite).

    Returns
    -------
    dict
        With keys:

        * ``available`` (bool) — pipeline produced a non-empty result
        * ``reason`` (str) — populated when ``available`` is False
        * ``recovery`` (DataFrame) — long table of per-rep, per-row errors
        * ``recovery_summary`` (DataFrame) — bias / RMSE / coverage95 aggregates
        * ``coverage_report`` (DataFrame) — SE/CI coverage interpretation table
        * ``rep_overview`` (DataFrame) — per-rep convergence and timing
        * ``ademp`` (dict) — ADEMP-style narrative metadata
        * ``settings`` (dict) — generator and fit settings used
    """
    model = str(model).upper()
    if model not in {"RSM", "PCM", "GPCM"}:
        return {
            "available": False,
            "reason": f"Unsupported model {model!r}; choose RSM, PCM, or GPCM.",
            "recovery": pd.DataFrame(),
            "recovery_summary": pd.DataFrame(),
            "coverage_report": pd.DataFrame(),
            "rep_overview": pd.DataFrame(),
            "ademp": {},
            "settings": {},
        }
    fit_method = str(fit_method).upper()
    if fit_method not in {"JMLE", "MML"}:
        return {
            "available": False,
            "reason": f"Unsupported fit_method {fit_method!r}; choose JMLE or MML.",
            "recovery": pd.DataFrame(),
            "recovery_summary": pd.DataFrame(),
            "coverage_report": pd.DataFrame(),
            "rep_overview": pd.DataFrame(),
            "ademp": {},
            "settings": {},
        }
    if n_cat < 2:
        return {
            "available": False,
            "reason": "n_cat must be >= 2.",
            "recovery": pd.DataFrame(),
            "recovery_summary": pd.DataFrame(),
            "coverage_report": pd.DataFrame(),
            "rep_overview": pd.DataFrame(),
            "ademp": {},
            "settings": {},
        }
    reps = max(1, int(reps))
    rng = np.random.default_rng(int(seed) if seed is not None else None)
    seeds = rng.integers(low=1, high=2**31 - 1, size=reps).tolist()

    # Truth: identification-friendly draws (mean-zero blocks).
    theta = rng.normal(0.0, theta_sd, n_person)
    theta = theta - theta.mean()
    rater_eff = rng.normal(0.0, rater_sd, n_rater)
    rater_eff = rater_eff - rater_eff.mean()
    crit_eff = rng.normal(0.0, criterion_sd, n_criterion)
    crit_eff = crit_eff - crit_eff.mean()

    step_thresholds = np.linspace(-step_span / 2.0, step_span / 2.0, n_cat - 1)
    if model == "RSM":
        steps = np.broadcast_to(step_thresholds, (n_criterion, n_cat - 1)).copy()
    else:
        # PCM / GPCM use criterion-specific perturbed thresholds so that
        # the per-criterion structure is recoverable in principle.
        perturb = np.linspace(-0.15, 0.15, n_criterion)
        steps = np.array([step_thresholds + p for p in perturb])
    if model == "GPCM":
        if slopes is None:
            slopes = np.ones(n_criterion)
        slopes = np.asarray(slopes, dtype=float)
    else:
        slopes = None

    truth = {
        "Person": {f"P{i+1:02d}": float(theta[i]) for i in range(n_person)},
        "Rater": {f"R{j+1}": float(rater_eff[j]) for j in range(n_rater)},
        "Criterion": {f"C{k+1}": float(crit_eff[k]) for k in range(n_criterion)},
    }

    recovery_chunks: list[pd.DataFrame] = []
    rep_rows: list[dict] = []
    import time
    for rep in range(1, reps + 1):
        t0 = time.perf_counter()
        rep_rng = np.random.default_rng(seeds[rep - 1])
        sim_df = _simulate_recovery_responses(
            theta=theta, rater=rater_eff, criterion=crit_eff,
            steps=steps, slopes=slopes, model=model, rating_min=0, rng=rep_rng,
        )
        row = {
            "rep": rep,
            "Seed": int(seeds[rep - 1]),
            "Observations": int(len(sim_df)),
            "ElapsedSec": np.nan,
            "RunOK": False,
            "Converged": False,
            "RecoveryRows": 0,
            "EstimatedPopulationSD": np.nan,
            "Error": "",
        }
        try:
            fit_kwargs = dict(
                data=sim_df, person_col="Person", facet_cols=["Rater", "Criterion"],
                score_col="Score", rating_min=0, rating_max=n_cat - 1,
                model=model, method=fit_method, maxit=int(maxit), reltol=float(reltol),
            )
            if model in {"PCM", "GPCM"}:
                fit_kwargs["step_facet"] = "Criterion"
            if model == "GPCM":
                fit_kwargs["slope_facet"] = "Criterion"
            if fit_method == "MML":
                fit_kwargs["quad_points"] = int(quad_points)
                if estimate_population_sd:
                    fit_kwargs["estimate_population_sd"] = True
            refit_res = mfrm_estimate(**fit_kwargs)
        except Exception as exc:
            row["Error"] = str(exc)[:500]
            row["ElapsedSec"] = float(time.perf_counter() - t0)
            rep_rows.append(row)
            continue

        row["ElapsedSec"] = float(time.perf_counter() - t0)
        summary = refit_res.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            row["Converged"] = bool(summary.iloc[0].get("Converged", False))
        est_sd_rep = refit_res.get("config", {}).get("estimated_population_sd")
        if est_sd_rep is not None and np.isfinite(est_sd_rep):
            row["EstimatedPopulationSD"] = float(est_sd_rep)
        # Pull SEs from a lightweight diagnostics pass so coverage95 is
        # populated. PCA / marginal-fit are disabled to keep the per-rep
        # cost in the ~70 ms range; the rest of the recovery summary is
        # not sensitive to those options.
        measures_for_se: pd.DataFrame | None = None
        try:
            diag = mfrm_diagnostics(refit_res, compute_pca=False, compute_marginal=False)
            measures_for_se = diag.get("measures") if isinstance(diag, dict) else None
        except Exception:
            measures_for_se = None
        recovery_rows = _recovery_rows_from_fit(
            refit_res, truth, rep=rep, include_person=include_person,
            measures=measures_for_se,
        )
        row["RunOK"] = True
        row["RecoveryRows"] = int(len(recovery_rows))
        rep_rows.append(row)
        if not recovery_rows.empty:
            recovery_chunks.append(recovery_rows)

    recovery = (
        pd.concat(recovery_chunks, ignore_index=True)
        if recovery_chunks
        else pd.DataFrame()
    )
    rep_overview = pd.DataFrame(rep_rows)
    # Aggregate recovery metrics over converged replicates only. A replicate
    # that ran but did not converge can land far from the optimum and would
    # inflate bias / RMSE and distort coverage if folded into the summary.
    # Fall back to all completed replicates only when none converged, so the
    # summary is never silently empty.
    n_reps_total = int(len(rep_overview))
    converged_mask = (
        rep_overview["Converged"].astype(bool)
        if "Converged" in rep_overview.columns
        else pd.Series([False] * n_reps_total, dtype=bool)
    )
    n_reps_converged = int(converged_mask.sum())
    if not recovery.empty and "rep" in recovery.columns and n_reps_converged > 0:
        converged_reps = set(rep_overview.loc[converged_mask, "rep"].tolist())
        recovery_for_summary = recovery[recovery["rep"].isin(converged_reps)]
        summary_basis = "converged"
    else:
        recovery_for_summary = recovery
        summary_basis = "all_completed" if n_reps_converged == 0 else "converged"
    recovery_summary = _recovery_summarize(recovery_for_summary)
    coverage_report = build_se_ci_coverage_report({
        "recovery": recovery_for_summary,
        "recovery_summary": recovery_summary,
    })

    ademp = {
        "Aims": (
            "Assess parameter recovery of the requested many-facet model under "
            "one explicit data-generating setup, by repeated simulation and "
            "refitting (Morris, White, & Crowther, 2019)."
        ),
        "DataGenerating": (
            f"Synthetic responses simulated from {model} with {n_person} persons, "
            f"{n_rater} raters, {n_criterion} criteria, and {n_cat} score categories. "
            f"Person measures ~ N(0, {theta_sd:.2f}^2), rater severities ~ "
            f"N(0, {rater_sd:.2f}^2), criterion difficulties ~ N(0, {criterion_sd:.2f}^2); "
            f"step thresholds equally spaced over a span of {step_span:.2f} logits."
        ),
        "Estimands": (
            "Identification-anchored person measures (theta), rater severities, "
            "criterion difficulties; location blocks are mean-aligned within each "
            "replicate to remove the Rasch identification constant."
        ),
        "Methods": (
            f"Each replicate refits the {model} model under {fit_method} via "
            f"mfrm_estimate (maxit = {maxit}, reltol = {reltol:.0e}). For MML, "
            f"quad_points = {quad_points}. The location-block estimates are "
            "mean-aligned before computing per-row error and coverage95."
        ),
        "PerformanceMeasures": (
            "Bias, Monte-Carlo SE of bias, RMSE, Monte-Carlo SE of RMSE, MAE, "
            "Pearson correlation between truth and aligned estimate, mean SE, "
            "SE-availability rate, and 95 % coverage rate (truth in "
            "estimate +/- 1.96 * SE)."
        ),
        "Reference": "Morris, T. P., White, I. R., & Crowther, M. J. (2019).",
    }

    settings = {
        "model": model,
        "fit_method": fit_method,
        "n_person": int(n_person),
        "n_rater": int(n_rater),
        "n_criterion": int(n_criterion),
        "n_cat": int(n_cat),
        "reps": int(reps),
        "theta_sd": float(theta_sd),
        "rater_sd": float(rater_sd),
        "criterion_sd": float(criterion_sd),
        "step_span": float(step_span),
        "maxit": int(maxit),
        "reltol": float(reltol),
        "quad_points": int(quad_points),
        "seed": int(seed) if seed is not None else None,
        "include_person": bool(include_person),
    }

    return {
        "available": not recovery.empty,
        "reason": "" if not recovery.empty else "All recovery replications failed before producing rows.",
        "recovery": recovery,
        "recovery_summary": recovery_summary,
        "coverage_report": coverage_report,
        "rep_overview": rep_overview,
        "n_reps_total": n_reps_total,
        "n_reps_converged": n_reps_converged,
        "summary_basis": summary_basis,
        "ademp": ademp,
        "settings": settings,
    }


# ============================================================================
# ============================================================================
# Nonparametric dimensionality test (Stout 1987; Nandakumar & Yu 1996)
# ============================================================================
# Adapts Stout's (1987, Psychometrika 52) DIMTEST framework for the
# essential-unidimensionality null hypothesis to MFRM data. For each
# Person, the rater scores on a given Criterion are averaged to produce
# a Person x Criterion item-response matrix; the criteria are then
# partitioned into an Assessment subtest (AT) and a Partitioning
# subtest (PT) using PC2 loading signs from the existing residual-PCA
# pipeline (Roussos & Stout, 1996). The test statistic is the pooled
# within-stratum covariance among AT items after stratifying persons
# by their PT total score; under essential unidimensionality the
# pooled covariance is asymptotically zero, and any systematic
# departure from zero is evidence of a residual secondary dimension
# beyond what the fitted MFRM accounts for.
#
# This is the conditional-covariance core of DIMTEST. The full Stout
# (1987) procedure includes a parametric bias-correction term T_B
# that requires fitting an auxiliary unidimensional IRT model on each
# subtest; that step is documented as future work in the bundle's
# caveat field. Standard errors and p-values here are based on a
# cluster bootstrap on persons (Efron & Tibshirani, 1993, Ch. 19)
# rather than the asymptotic null distribution, which keeps the
# implementation purely nonparametric and side-steps the bias-
# correction derivation.
#
# Polytomous adaptation: Nandakumar & Yu (1996) extension applies
# because the AT covariances and the PT total score are well-defined
# for ordered polytomous data; no rescaling to 0/1 is performed.


def _dimtest_build_person_item_matrix(
    obs_df: pd.DataFrame,
    item_facet: str,
    score_col: str = "Score",
) -> pd.DataFrame:
    """Build the Person x Item score matrix by averaging across raters.

    Returns an N_persons x N_items DataFrame with the per-cell average
    score; rows are Person identifiers and columns are Item levels.
    Missing cells are returned as NaN.
    """
    if not isinstance(obs_df, pd.DataFrame) or obs_df.empty:
        return pd.DataFrame()
    if item_facet not in obs_df.columns or "Person" not in obs_df.columns:
        return pd.DataFrame()
    work = obs_df[["Person", item_facet, score_col]].copy()
    work["Person"] = work["Person"].astype(str)
    work[item_facet] = work[item_facet].astype(str)
    work[score_col] = pd.to_numeric(work[score_col], errors="coerce")
    work = work.dropna(subset=[score_col])
    if work.empty:
        return pd.DataFrame()
    return work.pivot_table(
        index="Person", columns=item_facet, values=score_col, aggfunc="mean",
    )


def _dimtest_at_pt_split_from_pca(
    pca_bundle: dict | None,
    items: list[str],
) -> tuple[list[str], list[str], str]:
    """Pick AT / PT items from the existing PCA-of-residuals PC2 loadings.

    Roussos & Stout (1996) recommend forming AT from items that load
    on the suspected secondary dimension and using the remaining items
    as the partitioning subtest. We project PC2 sign onto the supplied
    item list; positive-loading items go to AT, negative-loading items
    to PT. If the PCA bundle is unavailable or its loadings frame does
    not cover the items, we fall back to a deterministic alphabetical
    split so the test always returns a well-defined result; the
    ``split_method`` field on the returned bundle names the path.
    """
    if isinstance(pca_bundle, dict):
        loadings = pca_bundle.get("loadings")
    else:
        loadings = None
    pc2_values: dict[str, float] = {}
    if isinstance(loadings, pd.DataFrame) and "PC2" in loadings.columns:
        for item in items:
            # The PCA loadings are indexed by item label; for some
            # facets the label is exactly ``item``, for others (overall
            # PCA) it is a concatenation. Try the direct match first.
            if item in loadings.index:
                try:
                    pc2_values[item] = float(loadings.at[item, "PC2"])
                except Exception:
                    continue
    if len(pc2_values) >= len(items) and len(items) >= 4:
        at = [it for it in items if pc2_values.get(it, 0.0) >= 0]
        pt = [it for it in items if pc2_values.get(it, 0.0) < 0]
        # Both halves must contain >= 2 items for the AT covariance
        # statistic to have a finite SE.
        if len(at) >= 2 and len(pt) >= 2:
            return at, pt, "pc2_loading_sign"
    # Fallback: deterministic alphabetical split.
    sorted_items = sorted(items)
    cut = len(sorted_items) // 2
    return sorted_items[cut:], sorted_items[:cut], "alphabetical_fallback"


def _dimtest_t_l_statistic(
    matrix: pd.DataFrame,
    at_items: list[str],
    pt_items: list[str],
    n_strata: int = 5,
) -> tuple[float, int, list[int]]:
    """Compute the pooled within-stratum covariance statistic.

    Strata are equal-frequency cuts on the PT total score; for each
    stratum the AT-pair covariance is pooled into a single weighted
    average. Returns ``(T_L, n_used, stratum_sizes)``.
    """
    finite = matrix.dropna(subset=at_items + pt_items, how="any")
    n = int(len(finite))
    if n < 2 * n_strata or len(at_items) < 2:
        return float("nan"), 0, []
    pt_total = finite[pt_items].sum(axis=1)
    # Equal-frequency strata via quantile cuts; collapse adjacent ties
    # by adjusting the requested stratum count downward if needed.
    quantiles = np.linspace(0.0, 1.0, n_strata + 1)
    cuts = pt_total.quantile(quantiles).to_numpy()
    cuts = np.unique(cuts)
    if cuts.size < 3:
        return float("nan"), n, []
    bins = pd.cut(pt_total, bins=cuts, include_lowest=True, duplicates="drop")
    grouped = finite.groupby(bins, observed=False)
    t_l = 0.0
    n_total_used = 0
    sizes: list[int] = []
    at_arr_cols = at_items
    for _, sub in grouped:
        n_s = int(len(sub))
        if n_s < 2:
            continue
        sizes.append(n_s)
        n_total_used += n_s
        # Within-stratum covariance among AT items; ddof=1 sample
        # covariance, then sum over the strict upper triangle.
        sub_at = sub[at_arr_cols].to_numpy(dtype=float)
        if sub_at.shape[0] < 2:
            continue
        cov_mat = np.cov(sub_at, rowvar=False, ddof=1)
        # Sum strictly upper-triangular off-diagonal entries.
        triu = np.triu_indices_from(cov_mat, k=1)
        s_cov_sum = float(np.sum(cov_mat[triu]))
        t_l += (n_s / max(n, 1)) * s_cov_sum
    return float(t_l), n_total_used, sizes


def compute_dimtest_nonparametric(
    res: dict,
    diagnostics: dict | None = None,
    *,
    item_facet: str = "Criterion",
    at_items: list[str] | None = None,
    pt_items: list[str] | None = None,
    n_strata: int = 5,
    n_bootstrap: int = 200,
    confidence: float = 0.95,
    seed: int | None = 20260612,
) -> dict:
    """Polytomous adaptation of Stout's nonparametric DIMTEST for MFRM data.

    Tests the essential-unidimensionality null hypothesis after the
    fitted MFRM main effects are accounted for. Each Person x Item
    score is the raw rating averaged across raters; AT / PT items are
    auto-split from the existing residual-PCA PC2 loadings (Roussos &
    Stout, 1996). The test statistic is the pooled within-stratum
    covariance among AT items after stratifying persons by PT total
    score (Stout 1987 framework, Nandakumar & Yu 1996 polytomous
    extension). Standard error and p-value come from a cluster
    bootstrap on persons (Efron & Tibshirani 1993, Ch. 19).

    Returns
    -------
    dict
        With keys ``available``, ``reason``, ``T_L``, ``SE``, ``Z``,
        ``p_value``, ``ci_lower``, ``ci_upper``, ``n_persons``,
        ``n_strata``, ``at_items``, ``pt_items``, ``split_method``,
        ``method``, ``references``, ``caveat``, ``settings``.
    """
    empty = {
        "available": False, "reason": "",
        "T_L": np.nan, "SE": np.nan, "Z": np.nan, "p_value": np.nan,
        "ci_lower": np.nan, "ci_upper": np.nan,
        "n_persons": 0, "n_strata": 0,
        "at_items": [], "pt_items": [],
        "split_method": "",
        "method": "conditional_covariance_with_cluster_bootstrap_se",
        "references": (
            "Stout (1987); Nandakumar & Yu (1996); "
            "Roussos & Stout (1996); Efron & Tibshirani (1993)."
        ),
        "caveat": "",
        "settings": {},
    }
    if not isinstance(res, dict):
        empty["reason"] = "Result is not a fit dictionary."
        return empty
    prep = res.get("prep") if isinstance(res, dict) else {}
    config = res.get("config") if isinstance(res, dict) else {}
    if not isinstance(prep, dict) or not isinstance(config, dict):
        empty["reason"] = "Fit dictionary missing prep / config."
        return empty
    facet_names = list(config.get("facet_names", []))
    if item_facet not in facet_names:
        empty["reason"] = (
            f"item_facet {item_facet!r} is not a facet on this fit; choose one of "
            f"{facet_names}."
        )
        return empty

    obs_df = None
    if isinstance(diagnostics, dict):
        obs_df = diagnostics.get("obs")
    if obs_df is None:
        try:
            obs_df = compute_obs_table(res)
        except Exception:
            obs_df = None
    if not isinstance(obs_df, pd.DataFrame) or obs_df.empty:
        empty["reason"] = "Per-observation diagnostics frame is empty."
        return empty

    matrix = _dimtest_build_person_item_matrix(obs_df, item_facet)
    if matrix.empty or matrix.shape[1] < 4:
        empty["reason"] = (
            f"Need >= 4 distinct {item_facet} levels to form AT / PT subtests; "
            f"got {matrix.shape[1]}."
        )
        return empty

    items = list(matrix.columns.astype(str))

    # AT / PT subtest selection. If the caller passes a priori
    # ``at_items`` and ``pt_items``, use them verbatim (the rigorous
    # path that side-steps the selection bias in PCA-driven splits).
    # Otherwise fall back to the PCA PC2 loading-sign auto-split with
    # an explicit caveat about the inflated Type I error rate that
    # comes from picking AT / PT from the same data.
    user_specified = bool(at_items) and bool(pt_items)
    if user_specified:
        at_items = [str(x) for x in at_items if str(x) in items]
        pt_items = [str(x) for x in pt_items if str(x) in items]
        split_method = "user_specified"
    else:
        pca_bundle = None
        if isinstance(diagnostics, dict):
            pca_by_facet = diagnostics.get("pca_by_facet") or {}
            pca_bundle = (
                pca_by_facet.get(item_facet) if isinstance(pca_by_facet, dict) else None
            )
            if pca_bundle is None:
                pca_bundle = diagnostics.get("pca")
        at_items, pt_items, split_method = _dimtest_at_pt_split_from_pca(
            pca_bundle, items
        )
    if len(at_items) < 2 or len(pt_items) < 2:
        empty["reason"] = (
            "AT / PT split produced an empty subtest; need >= 2 items in each."
        )
        return empty
    if set(at_items) & set(pt_items):
        empty["reason"] = "at_items and pt_items must be disjoint."
        return empty

    matrix = matrix.dropna(subset=at_items + pt_items, how="any")
    n_persons = int(len(matrix))
    if n_persons < max(2 * int(n_strata), 10):
        empty["reason"] = (
            f"Need at least max(2 * n_strata, 10) = {max(2 * int(n_strata), 10)} "
            f"persons with complete AT + PT scores; got {n_persons}."
        )
        return empty

    t_l_observed, n_used, stratum_sizes = _dimtest_t_l_statistic(
        matrix, at_items, pt_items, n_strata=n_strata,
    )
    if not np.isfinite(t_l_observed):
        empty["reason"] = "T_L could not be computed on the observed sample."
        return empty

    # Cluster bootstrap on persons. Resample with replacement and
    # recompute T_L on each replicate.
    rng = np.random.default_rng(int(seed) if seed is not None else None)
    persons_arr = matrix.index.to_numpy()
    replicates: list[float] = []
    for _ in range(int(n_bootstrap)):
        idx = rng.choice(persons_arr.size, size=persons_arr.size, replace=True)
        # Re-label resampled persons with unique identifiers (the
        # bootstrap needs each draw to be a distinct row).
        boot = matrix.iloc[idx].copy()
        boot.index = [f"BOOT_{k:05d}" for k in range(boot.shape[0])]
        t_b, _, _ = _dimtest_t_l_statistic(
            boot, at_items, pt_items, n_strata=n_strata,
        )
        if np.isfinite(t_b):
            replicates.append(float(t_b))
    rep_arr = np.asarray(replicates, dtype=float)
    if rep_arr.size < 10:
        empty["reason"] = "Insufficient bootstrap replicates produced a finite T_L."
        return empty
    se = float(np.std(rep_arr, ddof=1))
    z_stat = float(t_l_observed / se) if (np.isfinite(se) and se > 0) else float("nan")
    p_value = float(2.0 * (1.0 - _norm.cdf(abs(z_stat)))) if np.isfinite(z_stat) else float("nan")
    alpha_lo = (1.0 - float(confidence)) / 2.0
    ci_lo = float(np.quantile(rep_arr, alpha_lo))
    ci_hi = float(np.quantile(rep_arr, 1.0 - alpha_lo))

    return {
        "available": True,
        "reason": "",
        "T_L": float(t_l_observed),
        "SE": se,
        "Z": z_stat,
        "p_value": p_value,
        "ci_lower": ci_lo,
        "ci_upper": ci_hi,
        "n_persons": n_persons,
        "n_strata_requested": int(n_strata),
        "n_strata_used": int(len(stratum_sizes)),
        "stratum_sizes": stratum_sizes,
        "at_items": at_items,
        "pt_items": pt_items,
        "split_method": split_method,
        "method": "conditional_covariance_with_cluster_bootstrap_se",
        "references": (
            "Stout (1987); Nandakumar & Yu (1996); "
            "Roussos & Stout (1996); Efron & Tibshirani (1993)."
        ),
        "caveat": (
            "T_L is the pooled within-stratum covariance among AT items "
            "after partitioning on the PT total score. Under essential "
            "unidimensionality (conditional independence of AT items "
            "given the latent trait), T_L is asymptotically zero. The "
            "standard error and p-value come from a cluster bootstrap "
            "on persons; the full Stout (1987) procedure also subtracts "
            "an analytic bias-correction term T_B that requires fitting "
            "an auxiliary unidimensional IRT model on the AT subtest, "
            "which this initial port omits in favour of the purely "
            "nonparametric bootstrap variance estimate. When AT / PT is "
            "chosen by the PC2 loading sign on the same data (the "
            "default), the test inherits a selection-bias inflation of "
            "Type I error because PC2 already maximises an "
            "approximately-orthogonal covariance direction. For a "
            "rigorous confirmatory test, pass a priori at_items and "
            "pt_items derived from substantive considerations or from "
            "a separate calibration sample (Roussos & Stout, 1996). "
            "Read the p-value alongside the existing residual PCA: "
            "agreement across the two diagnostics is the strongest "
            "signal."
        ),
        "settings": {
            "item_facet": item_facet,
            "n_strata": int(n_strata),
            "n_bootstrap": int(n_bootstrap),
            "confidence": float(confidence),
            "seed": int(seed) if seed is not None else None,
        },
    }


# ============================================================================
# Design network analysis: connectivity, articulation points, bridges
# ============================================================================
# Treats the rating design as an undirected weighted graph: nodes are
# (Facet, Level) pairs, edges connect levels that co-occur in at least
# one observed rating, edge weights are co-observation counts. Returns
# a bundle with summary metrics (components, density, mean degree),
# per-node metrics (degree, strength, betweenness, closeness,
# eigenvector centrality, cutpoint flag), per-edge metrics (weight,
# bridge flag, edge betweenness), and a per-facet aggregate. The
# resulting numbers are *design diagnostics* — they describe how
# tightly the design is linked, not the psychometric quality of any
# person or rater.
#
# References:
# - Csardi & Nepusz (2006) on the igraph library that the R reference
#   wraps; here we use networkx (Hagberg, Schult & Swart 2008) for
#   the same algorithms.
# - Newman (2010) Networks: An Introduction for the underlying
#   centrality definitions.


def _network_node_id(facet: str, level: str) -> str:
    return f"{facet}:{level}"


def compute_design_network_analysis(
    res: dict,
    *,
    min_observations: int = 1,
    include_graph: bool = False,
) -> dict:
    """Undirected weighted co-observation graph diagnostics for a fit.

    Parameters
    ----------
    res : dict
        Fit result dictionary from ``mfrm_estimate`` (uses
        ``prep['data']`` plus ``config['facet_names']``).
    min_observations : int
        Drop edges with weight strictly below this threshold.
    include_graph : bool
        Embed the underlying ``networkx.Graph`` object in the return
        bundle under the ``graph`` key. Defaults to ``False`` so the
        bundle stays cheap to serialize.

    Returns
    -------
    dict
        With keys ``available``, ``reason``, ``summary``,
        ``node_metrics``, ``edge_metrics``, ``facet_summary``,
        ``cut_nodes``, ``bridge_edges``, ``settings``, and optionally
        ``graph``.
    """
    import networkx as nx

    if not isinstance(res, dict):
        return {
            "available": False,
            "reason": "Result is not a fit dictionary.",
            "summary": pd.DataFrame(),
            "node_metrics": pd.DataFrame(),
            "edge_metrics": pd.DataFrame(),
            "facet_summary": pd.DataFrame(),
            "cut_nodes": pd.DataFrame(),
            "bridge_edges": pd.DataFrame(),
            "settings": {},
        }
    config = res.get("config", {}) if isinstance(res.get("config"), dict) else {}
    prep = res.get("prep", {}) if isinstance(res.get("prep"), dict) else {}
    data = prep.get("data")
    if not isinstance(data, pd.DataFrame) or data.empty:
        return {
            "available": False,
            "reason": "Fit does not carry a raw data frame.",
            "summary": pd.DataFrame(),
            "node_metrics": pd.DataFrame(),
            "edge_metrics": pd.DataFrame(),
            "facet_summary": pd.DataFrame(),
            "cut_nodes": pd.DataFrame(),
            "bridge_edges": pd.DataFrame(),
            "settings": {},
        }
    facet_names = ["Person"] + list(config.get("facet_names", []))
    facet_names = [f for f in facet_names if f in data.columns]
    if len(facet_names) < 2:
        return {
            "available": False,
            "reason": "Need at least two facet columns to build a network.",
            "summary": pd.DataFrame(),
            "node_metrics": pd.DataFrame(),
            "edge_metrics": pd.DataFrame(),
            "facet_summary": pd.DataFrame(),
            "cut_nodes": pd.DataFrame(),
            "bridge_edges": pd.DataFrame(),
            "settings": {},
        }

    # Build the weighted co-observation graph.
    graph = nx.Graph()
    node_facet = {}
    node_level = {}
    for facet in facet_names:
        for level in data[facet].astype(str).unique():
            node_id = _network_node_id(facet, str(level))
            graph.add_node(node_id, facet=facet, level=str(level))
            node_facet[node_id] = facet
            node_level[node_id] = str(level)

    # Edges: every observation row connects every pair of (facet, level)
    # nodes it touches. Aggregate edge weights as co-observation counts.
    import itertools
    edge_weights: dict[tuple[str, str], float] = {}
    for _, row in data.iterrows():
        ids = [_network_node_id(f, str(row[f])) for f in facet_names]
        for a, b in itertools.combinations(sorted(ids), 2):
            edge_weights[(a, b)] = edge_weights.get((a, b), 0.0) + 1.0
    for (a, b), w in edge_weights.items():
        if w < float(min_observations):
            continue
        graph.add_edge(a, b, weight=float(w), distance=1.0 / max(float(w), 1.0))

    n_nodes = int(graph.number_of_nodes())
    n_edges = int(graph.number_of_edges())
    if n_nodes == 0:
        return {
            "available": False,
            "reason": "No usable nodes in the design graph.",
            "summary": pd.DataFrame(),
            "node_metrics": pd.DataFrame(),
            "edge_metrics": pd.DataFrame(),
            "facet_summary": pd.DataFrame(),
            "cut_nodes": pd.DataFrame(),
            "bridge_edges": pd.DataFrame(),
            "settings": {},
        }

    components = [c for c in nx.connected_components(graph)]
    n_components = len(components)
    component_sizes = [len(c) for c in components]
    largest_size = max(component_sizes) if component_sizes else 0
    largest_share = largest_size / n_nodes if n_nodes else np.nan
    density = nx.density(graph)
    mean_degree = (
        float(np.mean([d for _, d in graph.degree()])) if n_nodes else np.nan
    )
    mean_strength = (
        float(np.mean([graph.degree(n, weight="weight") for n in graph.nodes()]))
        if n_nodes else np.nan
    )

    # Articulation points / bridges work on connected graphs; networkx
    # treats disconnected graphs as a forest and reports the points /
    # bridges across each component, which is what we want.
    articulation_set = set(nx.articulation_points(graph))
    bridge_set = set(map(frozenset, nx.bridges(graph)))

    # Centralities. Use the inverse-weight distance for path-based
    # measures so frequent co-observation edges are "shorter".
    try:
        betweenness = nx.betweenness_centrality(graph, weight="distance", normalized=True)
    except Exception:
        betweenness = {n: np.nan for n in graph.nodes()}
    try:
        closeness = nx.closeness_centrality(graph, distance="distance")
    except Exception:
        closeness = {n: np.nan for n in graph.nodes()}
    try:
        eigen = nx.eigenvector_centrality_numpy(graph, weight="weight")
    except Exception:
        eigen = {n: np.nan for n in graph.nodes()}

    # Diameter / mean distance: defined per component; report the
    # largest-component value for the bundle summary.
    diameter = np.nan
    mean_distance = np.nan
    if components and largest_size > 1:
        sub = graph.subgraph(max(components, key=len))
        try:
            diameter = float(nx.diameter(sub, weight="distance"))
        except Exception:
            diameter = np.nan
        try:
            mean_distance = float(nx.average_shortest_path_length(sub, weight="distance"))
        except Exception:
            mean_distance = np.nan

    summary = pd.DataFrame([{
        "Nodes": n_nodes,
        "Edges": n_edges,
        "Components": n_components,
        "LargestComponentNodes": int(largest_size),
        "LargestComponentShare": float(largest_share) if np.isfinite(largest_share) else np.nan,
        "Density": float(density),
        "MeanDegree": float(mean_degree),
        "MeanStrength": float(mean_strength),
        "ArticulationPoints": int(len(articulation_set)),
        "Bridges": int(len(bridge_set)),
        "Connected": bool(n_components == 1),
        "Diameter": float(diameter) if np.isfinite(diameter) else np.nan,
        "MeanDistance": float(mean_distance) if np.isfinite(mean_distance) else np.nan,
    }])

    node_rows = []
    for node in graph.nodes():
        node_rows.append({
            "Node": node,
            "Facet": node_facet.get(node, ""),
            "Level": node_level.get(node, ""),
            "Degree": int(graph.degree(node)),
            "Strength": float(graph.degree(node, weight="weight")),
            "Betweenness": float(betweenness.get(node, np.nan)),
            "Closeness": float(closeness.get(node, np.nan)),
            "EigenvectorCentrality": float(eigen.get(node, np.nan)),
            "IsArticulationPoint": bool(node in articulation_set),
        })
    node_metrics = pd.DataFrame(node_rows).sort_values(
        ["Facet", "Level"]
    ).reset_index(drop=True)

    edge_rows = []
    for u, v, attrs in graph.edges(data=True):
        edge_rows.append({
            "From": u,
            "To": v,
            "Weight": float(attrs.get("weight", 0.0)),
            "IsBridge": bool(frozenset((u, v)) in bridge_set),
        })
    edge_metrics = pd.DataFrame(edge_rows).sort_values(
        ["From", "To"]
    ).reset_index(drop=True)

    facet_summary_rows = []
    if not node_metrics.empty:
        for facet, sub in node_metrics.groupby("Facet"):
            facet_summary_rows.append({
                "Facet": str(facet),
                "Nodes": int(len(sub)),
                "MeanDegree": float(sub["Degree"].mean()),
                "MeanBetweenness": float(sub["Betweenness"].mean()),
                "MeanCloseness": float(sub["Closeness"].mean()),
                "ArticulationCount": int(sub["IsArticulationPoint"].sum()),
            })
    facet_summary = pd.DataFrame(facet_summary_rows)

    cut_nodes = (
        node_metrics[node_metrics["IsArticulationPoint"]].copy()
        if not node_metrics.empty else pd.DataFrame()
    )
    bridge_edges = (
        edge_metrics[edge_metrics["IsBridge"]].copy()
        if not edge_metrics.empty else pd.DataFrame()
    )

    out = {
        "available": True,
        "reason": "",
        "summary": summary,
        "node_metrics": node_metrics,
        "edge_metrics": edge_metrics,
        "facet_summary": facet_summary,
        "cut_nodes": cut_nodes,
        "bridge_edges": bridge_edges,
        "settings": {
            "min_observations": int(min_observations),
            "graph_definition": "undirected weighted co-observation graph",
            "centrality_weighting": "betweenness / closeness use inverse-weight distances; eigenvector uses raw weights",
            "facet_names": list(facet_names),
        },
    }
    if include_graph:
        out["graph"] = graph
    return out


# ============================================================================
# Rater severity network analysis (directed graph)
# ============================================================================
# For every pair of raters with overlapping scoring contexts, compute the
# mean score difference, the mean absolute difference, and the directional
# "higher count" / "higher prop" diagnostics. Build a directed graph
# whose edge weight is the proportion of disagreements where Rater A
# scored strictly higher than Rater B; an out-degree-minus-in-degree
# summary then gives a leniency rank. The math is a pure descriptive
# screen on raw ratings; it does not refit the model and does not
# attempt causal inference.


def _rater_severity_pair_metrics(
    data: pd.DataFrame,
    rater_facet: str,
    context_facets: list[str],
    score_col: str = "Score",
    score_diff_tolerance: float = 0.0,
) -> pd.DataFrame:
    """Pairwise rater severity metrics on shared scoring contexts.

    Returns one row per ordered pair (Rater1, Rater2) with:

    * ``N`` — shared scoring contexts (rows with both raters present)
    * ``MeanDiff`` — mean(R1 - R2) over shared contexts
    * ``MAD`` — mean(|R1 - R2|) over shared contexts
    * ``Rater1HigherCount`` — count where R1 > R2 + tolerance
    * ``Rater2HigherCount`` — count where R2 > R1 + tolerance
    * ``Rater1HigherProp`` — share of disagreements where R1 was higher
    * ``Rater2HigherProp`` — share of disagreements where R2 was higher
    * ``DirectionN`` — number of disagreement opportunities

    Set ``score_col`` to ``"Residual"`` (or another diagnostic column)
    to switch the metric from raw-score differences to MFRM-
    residualized differences; the same identity holds either way
    because the math depends only on the relative ordering of the
    two raters' values, not on their absolute scale.
    """
    cols_required = [rater_facet, score_col] + list(context_facets)
    missing = [c for c in cols_required if c not in data.columns]
    if missing:
        return pd.DataFrame()
    work = data[cols_required].copy()
    work[rater_facet] = work[rater_facet].astype(str)
    for c in context_facets:
        work[c] = work[c].astype(str)
    work[score_col] = pd.to_numeric(work[score_col], errors="coerce")
    work = work.dropna(subset=[score_col])
    if work.empty:
        return pd.DataFrame()
    raters = sorted(work[rater_facet].unique().tolist())
    if len(raters) < 2:
        return pd.DataFrame()

    wide = work.pivot_table(
        index=context_facets,
        columns=rater_facet,
        values=score_col,
        aggfunc="mean",
    )
    import itertools
    rows = []
    tol = float(score_diff_tolerance)
    for r1, r2 in itertools.combinations(raters, 2):
        if r1 not in wide.columns or r2 not in wide.columns:
            continue
        sub = wide[[r1, r2]].dropna()
        n = int(len(sub))
        if n == 0:
            rows.append({
                "Rater1": r1, "Rater2": r2, "N": 0,
                "MeanDiff": np.nan, "MAD": np.nan,
                "Rater1HigherCount": 0, "Rater2HigherCount": 0,
                "TieCount": 0,
                "Rater1HigherProp": np.nan, "Rater2HigherProp": np.nan,
                "Rater1HigherCondProp": np.nan, "Rater2HigherCondProp": np.nan,
                "DirectionN": 0,
            })
            continue
        s1 = sub[r1].to_numpy(dtype=float)
        s2 = sub[r2].to_numpy(dtype=float)
        diff = s1 - s2
        higher1 = int(np.sum(diff > tol))
        higher2 = int(np.sum(-diff > tol))
        direction_n = higher1 + higher2
        ties = n - direction_n
        # Two complementary probabilities. ``Rater1HigherProp`` follows
        # the mfrmr / FACETS convention (share of *all* shared contexts);
        # ``Rater1HigherCondProp`` is the conditional share given the
        # two raters disagree (preserves the +/- 1 ordering at the
        # individual edge but loses tie information).
        rows.append({
            "Rater1": r1, "Rater2": r2, "N": n,
            "MeanDiff": float(np.mean(diff)),
            "MAD": float(np.mean(np.abs(diff))),
            "Rater1HigherCount": higher1,
            "Rater2HigherCount": higher2,
            "TieCount": int(ties),
            "Rater1HigherProp": float(higher1 / n),
            "Rater2HigherProp": float(higher2 / n),
            "Rater1HigherCondProp": (
                float(higher1 / direction_n) if direction_n > 0 else np.nan
            ),
            "Rater2HigherCondProp": (
                float(higher2 / direction_n) if direction_n > 0 else np.nan
            ),
            "DirectionN": int(direction_n),
        })
    return pd.DataFrame(rows)


def compute_rater_severity_network(
    res: dict,
    *,
    rater_facet: str | None = None,
    context_facets: list[str] | None = None,
    min_pair_n: int = 1,
    score_diff_tolerance: float = 0.0,
    score_source: str = "observed",
    include_graph: bool = False,
) -> dict:
    """Directed rater severity / leniency network.

    Each rater is a node. For each pair of raters with shared scoring
    contexts (rows with both rater observations), the edge ``A -> B``
    carries weight ``Rater1HigherProp = P(A > B | A != B)``. A high
    out-degree (large total ``Rater1HigherProp``) means a rater scores
    higher than their peers more often than not — a leniency signal.
    A high in-degree means the opposite (severity signal).

    ``score_source`` chooses the comparison metric:

    * ``"observed"`` (default) — raw scores; the classic descriptive
      screen. Useful when the user wants a non-IRT view of who scores
      higher.
    * ``"residual"`` — MFRM-corrected ``(Observed - Expected)``
      residuals from ``compute_obs_table``; controls for person
      ability and criterion difficulty so the leniency rank reflects
      systematic rater bias rather than chance encounters with
      higher- or lower-ability persons. Recommended by Eckes (2011)
      for severity comparisons. Requires the residuals to be
      computable from the fit (RSM / PCM / GPCM after a successful
      run); falls back to ``"observed"`` if residuals are not
      available.

    Returns a bundle with ``available``, ``reason``, ``pair_metrics``,
    ``node_metrics`` (per-rater out-degree, in-degree, mean MAD,
    severity rank), ``edge_metrics`` (directed edge table), ``summary``
    (n_raters, n_eligible_pairs, mean MAD), ``settings``, and
    optionally ``graph`` (networkx DiGraph).
    """
    import networkx as nx

    if not isinstance(res, dict):
        return _empty_rater_severity_bundle("Result is not a fit dictionary.", rater_facet)
    config = res.get("config", {}) if isinstance(res.get("config"), dict) else {}
    prep = res.get("prep", {}) if isinstance(res.get("prep"), dict) else {}
    data = prep.get("data")
    if not isinstance(data, pd.DataFrame) or data.empty:
        return _empty_rater_severity_bundle("Fit does not carry a raw data frame.", rater_facet)

    facet_names = list(config.get("facet_names", []))
    if rater_facet is None:
        rater_facet = next((f for f in facet_names if f.lower() == "rater"), None)
        if rater_facet is None and facet_names:
            rater_facet = facet_names[0]
    if rater_facet is None or rater_facet not in data.columns:
        return _empty_rater_severity_bundle(
            f"rater_facet {rater_facet!r} is not a column on the fit data.", rater_facet,
        )
    if rater_facet == "Person":
        return _empty_rater_severity_bundle(
            "rater_facet = 'Person' is not supported; choose a non-person facet.",
            rater_facet,
        )
    if context_facets is None:
        context_facets = ["Person"] + [f for f in facet_names if f != rater_facet]
        context_facets = [c for c in context_facets if c in data.columns]
    if not context_facets:
        return _empty_rater_severity_bundle(
            "No context facets available; at least one shared context is required.",
            rater_facet,
        )

    # Optional residualized metric: replace raw Score with the
    # MFRM-corrected (Observed - Expected) residuals from
    # compute_obs_table when ``score_source = "residual"``. Falls back
    # to raw scores if the residuals cannot be computed.
    score_source = str(score_source or "observed").strip().lower()
    effective_score_col = "Score"
    residual_data = None
    if score_source == "residual":
        try:
            obs_df = compute_obs_table(res)
            if isinstance(obs_df, pd.DataFrame) and "Residual" in obs_df.columns:
                residual_data = data.copy()
                # Length parity: compute_obs_table preserves prep['data']
                # row ordering, so a positional copy of the Residual
                # column is correct.
                if len(obs_df) == len(residual_data):
                    residual_data["_ResidScore"] = pd.to_numeric(
                        obs_df["Residual"], errors="coerce"
                    ).to_numpy()
                    effective_score_col = "_ResidScore"
                else:
                    residual_data = None
        except Exception:
            residual_data = None
    work_data = residual_data if residual_data is not None else data
    if effective_score_col != "Score" and effective_score_col not in work_data.columns:
        effective_score_col = "Score"
        work_data = data

    pair_metrics = _rater_severity_pair_metrics(
        work_data, rater_facet, context_facets,
        score_col=effective_score_col,
        score_diff_tolerance=score_diff_tolerance,
    )
    if pair_metrics.empty:
        return _empty_rater_severity_bundle(
            "Fewer than two raters share scorable contexts.", rater_facet,
        )

    eligible_mask = pair_metrics["N"] >= int(min_pair_n)
    eligible = pair_metrics[eligible_mask].copy()
    if eligible.empty:
        return _empty_rater_severity_bundle(
            f"No rater pair has at least {min_pair_n} shared scoring contexts.",
            rater_facet,
        )

    # Build directed edges: for every eligible pair record both
    # directions (A -> B with Rater1HigherProp, B -> A with
    # Rater2HigherProp). Skip near-zero weights.
    edge_rows = []
    for _, row in eligible.iterrows():
        r1 = str(row["Rater1"])
        r2 = str(row["Rater2"])
        n_dir = int(row["DirectionN"])
        if n_dir == 0:
            continue
        edge_rows.append({
            "From": r1, "To": r2,
            "Weight": float(row["Rater1HigherProp"]),
            "HigherCount": int(row["Rater1HigherCount"]),
            "DirectionN": n_dir,
            "MeanDiff": float(row["MeanDiff"]),
            "MAD": float(row["MAD"]),
            "Direction": "Rater1Higher",
        })
        edge_rows.append({
            "From": r2, "To": r1,
            "Weight": float(row["Rater2HigherProp"]),
            "HigherCount": int(row["Rater2HigherCount"]),
            "DirectionN": n_dir,
            "MeanDiff": float(-row["MeanDiff"]),
            "MAD": float(row["MAD"]),
            "Direction": "Rater2Higher",
        })
    edge_metrics = pd.DataFrame(edge_rows)
    edge_metrics = edge_metrics[
        edge_metrics["Weight"].notna() & (edge_metrics["HigherCount"] > 0)
    ]

    graph = nx.DiGraph()
    raters = sorted(set(pair_metrics["Rater1"]).union(pair_metrics["Rater2"]))
    for r in raters:
        graph.add_node(str(r))
    for _, row in edge_metrics.iterrows():
        graph.add_edge(str(row["From"]), str(row["To"]),
                       weight=float(row["Weight"]),
                       higher_count=int(row["HigherCount"]),
                       direction_n=int(row["DirectionN"]),
                       mad=float(row["MAD"]))

    # Per-node metrics: total "higher than peers" mass minus total
    # "lower than peers" mass yields a leniency index. Ranks raters
    # from most lenient (rank 1) to most severe.
    node_rows = []
    for r in raters:
        out_edges = list(graph.out_edges(r, data=True))
        in_edges = list(graph.in_edges(r, data=True))
        out_mass = float(sum(d.get("weight", 0.0) for _, _, d in out_edges))
        in_mass = float(sum(d.get("weight", 0.0) for _, _, d in in_edges))
        peers_compared = int(graph.out_degree(r) + graph.in_degree(r))
        mean_mad = (
            float(np.mean([d.get("mad", np.nan) for _, _, d in out_edges]))
            if out_edges else np.nan
        )
        node_rows.append({
            "Rater": str(r),
            "OutDegree": int(graph.out_degree(r)),
            "InDegree": int(graph.in_degree(r)),
            "OutMass": out_mass,
            "InMass": in_mass,
            "LeniencyIndex": float(out_mass - in_mass),
            "MeanAbsDiffToPeers": mean_mad,
            "PeersCompared": peers_compared,
        })
    node_metrics = pd.DataFrame(node_rows)
    if not node_metrics.empty:
        node_metrics["SeverityRank"] = (
            node_metrics["LeniencyIndex"].rank(method="min", ascending=False).astype(int)
        )
        node_metrics = node_metrics.sort_values(
            "SeverityRank"
        ).reset_index(drop=True)

    summary = pd.DataFrame([{
        "RaterFacet": rater_facet,
        "NRaters": int(len(raters)),
        "NEligiblePairs": int(len(eligible)),
        "MeanPairN": float(eligible["N"].mean()) if not eligible.empty else np.nan,
        "MeanMAD": float(eligible["MAD"].mean()) if not eligible.empty else np.nan,
        "MeanAbsMeanDiff": float(np.abs(eligible["MeanDiff"]).mean()) if not eligible.empty else np.nan,
    }])

    out = {
        "available": True,
        "reason": "",
        "summary": summary,
        "pair_metrics": pair_metrics.reset_index(drop=True),
        "node_metrics": node_metrics,
        "edge_metrics": edge_metrics.reset_index(drop=True),
        "settings": {
            "rater_facet": rater_facet,
            "context_facets": list(context_facets),
            "min_pair_n": int(min_pair_n),
            "score_diff_tolerance": float(score_diff_tolerance),
            "score_source": (
                "residual" if effective_score_col == "_ResidScore" else "observed"
            ),
            "edge_definition": (
                "directed edge from rater A to rater B with weight = "
                "P(A > B | the two raters disagree on a shared context); "
                "comparisons run on " + (
                    "MFRM-corrected residuals (Observed - Expected)"
                    if effective_score_col == "_ResidScore"
                    else "raw observed scores"
                )
            ),
        },
    }
    if include_graph:
        out["graph"] = graph
    return out


def _empty_rater_severity_bundle(reason: str, rater_facet: str | None) -> dict:
    return {
        "available": False,
        "reason": reason,
        "summary": pd.DataFrame(),
        "pair_metrics": pd.DataFrame(),
        "node_metrics": pd.DataFrame(),
        "edge_metrics": pd.DataFrame(),
        "settings": {"rater_facet": rater_facet},
    }


# ============================================================================
# Rater halo network analysis (within-rater cross-criterion correlation)
# ============================================================================
# Each (Rater, Criterion) is a node. For every pair of nodes, the edge
# weight is the Spearman / Pearson correlation between their score
# vectors over shared contexts (typically Person). Halo edges connect
# two criteria scored by the same rater; non-halo edges connect
# different raters. Per-rater review flags surface whether a single
# rater's cross-criterion correlations are high enough to consider a
# halo pattern (Lai, Wolfe & Vickers, 2015; Lamprianou, 2025).


def _halo_node_score_matrix(
    data: pd.DataFrame,
    rater_facet: str,
    criterion_facet: str,
    context_facets: list[str],
    score_col: str = "Score",
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Build the (Rater, Criterion) node score matrix.

    Returns (wide, node_tbl). ``wide`` is indexed by context_facets
    rows with one column per (Rater:Criterion) node; ``node_tbl``
    carries one row per node with Rater + Criterion labels.
    """
    cols_required = [rater_facet, criterion_facet, score_col] + list(context_facets)
    missing = [c for c in cols_required if c not in data.columns]
    if missing:
        return pd.DataFrame(), pd.DataFrame()
    work = data[cols_required].copy()
    work[rater_facet] = work[rater_facet].astype(str)
    work[criterion_facet] = work[criterion_facet].astype(str)
    for c in context_facets:
        work[c] = work[c].astype(str)
    work[score_col] = pd.to_numeric(work[score_col], errors="coerce")
    work = work.dropna(subset=[score_col])
    if work.empty:
        return pd.DataFrame(), pd.DataFrame()
    work["_Node"] = work[rater_facet] + ":" + work[criterion_facet]
    wide = work.pivot_table(
        index=context_facets,
        columns="_Node",
        values=score_col,
        aggfunc="mean",
    )
    node_tbl_rows = []
    seen = set()
    for _, row in work[["_Node", rater_facet, criterion_facet]].drop_duplicates().iterrows():
        node_id = row["_Node"]
        if node_id in seen:
            continue
        seen.add(node_id)
        node_tbl_rows.append({
            "Node": str(node_id),
            "Rater": str(row[rater_facet]),
            "Criterion": str(row[criterion_facet]),
        })
    node_tbl = pd.DataFrame(node_tbl_rows)
    return wide, node_tbl


def _halo_correlation_safe(
    x: np.ndarray, y: np.ndarray, method: str = "spearman"
) -> tuple[float, float]:
    """Return (rho, p-value) for the requested correlation, NaN on failure.

    ``method`` is one of ``"spearman"`` (default, rank-based; robust to
    non-linearity in score profiles), ``"pearson"`` (linear correlation
    on raw scores; matches the L2-norm interpretation of halo), or
    ``"kendall"`` (rank-based tau; more conservative for small N and
    ties). All three flavours use ``scipy.stats``; NaN is returned on
    any failure (e.g. constant series, NaN inputs).
    """
    method = str(method or "spearman").strip().lower()
    if method not in {"spearman", "pearson", "kendall"}:
        return np.nan, np.nan
    try:
        if method == "spearman":
            from scipy.stats import spearmanr
            with np.errstate(all="ignore"):
                res = spearmanr(x, y, nan_policy="omit")
        elif method == "pearson":
            from scipy.stats import pearsonr
            with np.errstate(all="ignore"):
                res = pearsonr(x, y)
        else:  # kendall
            from scipy.stats import kendalltau
            with np.errstate(all="ignore"):
                res = kendalltau(x, y, nan_policy="omit")
        rho = float(res.statistic) if hasattr(res, "statistic") else float(res[0])
        pval = float(res.pvalue) if hasattr(res, "pvalue") else float(res[1])
        return rho, pval
    except Exception:
        return np.nan, np.nan


def _spearman_correlation_safe(x: np.ndarray, y: np.ndarray) -> tuple[float, float]:
    """Backwards-compatible alias for the Spearman-only flavour."""
    return _halo_correlation_safe(x, y, method="spearman")


def _bonferroni_adjust(pvals: np.ndarray) -> np.ndarray:
    """Bonferroni-adjust a vector of p-values (clamp at 1.0)."""
    arr = np.asarray(pvals, dtype=float)
    finite = np.isfinite(arr)
    m = int(finite.sum())
    if m == 0:
        return arr
    out = np.full_like(arr, np.nan)
    out[finite] = np.minimum(arr[finite] * m, 1.0)
    return out


def compute_rater_halo_network(
    res: dict,
    *,
    rater_facet: str | None = None,
    criterion_facet: str | None = None,
    context_facets: list[str] | None = None,
    method: str = "spearman",
    min_pair_n: int = 5,
    alpha: float = 0.05,
    min_abs_weight: float = 0.0,
    halo_weight_review: float = 0.50,
    halo_contrast_review: float = 0.10,
    positive_only: bool = True,
    include_graph: bool = False,
) -> dict:
    """Rater-by-criterion halo network screen.

    Builds an undirected weighted graph whose nodes are
    ``(Rater, Criterion)`` pairs and edge weights are Spearman
    correlations between the two nodes' score vectors over a shared
    context (default: Person). Edges connecting two criteria scored
    by the same rater are labelled ``"halo"``; edges across raters
    are labelled ``"non_halo"``. Per-rater review flags surface
    whether the within-rater cross-criterion correlations are high
    enough to consider a halo pattern (Lai, Wolfe, & Vickers, 2015;
    Lamprianou, 2025).

    The Welch test contrasting halo vs non-halo edge weights is
    descriptive only because the edge weights are clustered by
    rater and node; do not treat its p-value as inferential.
    """
    import networkx as nx

    if not isinstance(res, dict):
        return _empty_halo_bundle("Result is not a fit dictionary.")
    config = res.get("config", {}) if isinstance(res.get("config"), dict) else {}
    prep = res.get("prep", {}) if isinstance(res.get("prep"), dict) else {}
    data = prep.get("data")
    if not isinstance(data, pd.DataFrame) or data.empty:
        return _empty_halo_bundle("Fit does not carry a raw data frame.")

    facet_names = list(config.get("facet_names", []))
    if rater_facet is None:
        rater_facet = next((f for f in facet_names if f.lower() == "rater"), None)
    if criterion_facet is None:
        criterion_facet = next((f for f in facet_names if f.lower() == "criterion"), None)
    if rater_facet is None or rater_facet not in data.columns:
        return _empty_halo_bundle(
            f"rater_facet {rater_facet!r} is not a column on the fit data."
        )
    if criterion_facet is None or criterion_facet not in data.columns:
        return _empty_halo_bundle(
            f"criterion_facet {criterion_facet!r} is not a column on the fit data."
        )
    if rater_facet == criterion_facet or rater_facet == "Person" or criterion_facet == "Person":
        return _empty_halo_bundle(
            "rater_facet and criterion_facet must be distinct non-person facets."
        )
    if context_facets is None:
        context_facets = ["Person"] + [
            f for f in facet_names if f not in {rater_facet, criterion_facet}
        ]
        context_facets = [c for c in context_facets if c in data.columns]
    if not context_facets:
        return _empty_halo_bundle(
            "No context facets available; at least one shared context is required."
        )

    wide, node_tbl = _halo_node_score_matrix(
        data, rater_facet, criterion_facet, context_facets,
    )
    if node_tbl.empty or len(node_tbl) < 2:
        return _empty_halo_bundle(
            "Fewer than two rater-by-criterion nodes are available."
        )

    # Pairwise correlations across nodes.
    import itertools
    node_ids = node_tbl["Node"].astype(str).tolist()
    pair_rows = []
    for a, b in itertools.combinations(node_ids, 2):
        if a not in wide.columns or b not in wide.columns:
            continue
        sub = wide[[a, b]].dropna()
        n = int(len(sub))
        if n < int(min_pair_n):
            rho, pval = np.nan, np.nan
        else:
            rho, pval = _halo_correlation_safe(
                sub[a].to_numpy(dtype=float),
                sub[b].to_numpy(dtype=float),
                method=method,
            )
        rater_a = node_tbl.loc[node_tbl["Node"] == a, "Rater"].iloc[0]
        crit_a = node_tbl.loc[node_tbl["Node"] == a, "Criterion"].iloc[0]
        rater_b = node_tbl.loc[node_tbl["Node"] == b, "Rater"].iloc[0]
        crit_b = node_tbl.loc[node_tbl["Node"] == b, "Criterion"].iloc[0]
        edge_type = "halo" if rater_a == rater_b else "non_halo"
        pair_rows.append({
            "From": a, "To": b,
            "Rater1": rater_a, "Criterion1": crit_a,
            "Rater2": rater_b, "Criterion2": crit_b,
            "EdgeType": edge_type,
            "Estimate": float(rho) if np.isfinite(rho) else np.nan,
            "AbsEstimate": float(abs(rho)) if np.isfinite(rho) else np.nan,
            "N": n,
            "PValue": float(pval) if np.isfinite(pval) else np.nan,
        })
    pair_metrics = pd.DataFrame(pair_rows)
    if pair_metrics.empty:
        return _empty_halo_bundle("No rater-by-criterion node pairs could be estimated.")

    pair_metrics["PAdjusted"] = _bonferroni_adjust(
        pair_metrics["PValue"].to_numpy(dtype=float)
    )

    # Edge retention.
    retained_by_n = pair_metrics["N"].fillna(0).astype(int) >= int(min_pair_n)
    retained_by_p = pair_metrics["PAdjusted"].fillna(1.0) <= float(alpha)
    retained_by_weight = pair_metrics["AbsEstimate"].fillna(0.0) >= float(min_abs_weight)
    if positive_only:
        retained_by_sign = pair_metrics["Estimate"].fillna(0.0) > 0
    else:
        retained_by_sign = pair_metrics["Estimate"].notna()
    pair_metrics["RetainedEdge"] = (
        retained_by_n & retained_by_p & retained_by_weight & retained_by_sign
    )

    edge_metrics = pair_metrics[pair_metrics["RetainedEdge"]].copy()
    edge_metrics["Weight"] = edge_metrics["AbsEstimate"]
    edge_metrics["SignedWeight"] = edge_metrics["Estimate"]

    # Build the undirected graph for per-node centrality.
    graph = nx.Graph()
    for _, row in node_tbl.iterrows():
        graph.add_node(str(row["Node"]), rater=row["Rater"], criterion=row["Criterion"])
    for _, row in edge_metrics.iterrows():
        graph.add_edge(
            str(row["From"]), str(row["To"]),
            weight=float(row["Weight"]),
            edge_type=str(row["EdgeType"]),
            n=int(row["N"]),
        )

    # Per-rater halo summary. Read the retained-edge weights from
    # ``AbsEstimate`` on the pair_metrics frame (the same value as the
    # ``Weight`` column on edge_metrics, but the column lives on
    # pair_metrics for the broader retention analytics).
    raters = sorted(node_tbl["Rater"].astype(str).unique().tolist())
    halo_summary_rows = []
    for r in raters:
        rater_nodes = node_tbl[node_tbl["Rater"] == r]["Node"].astype(str).tolist()
        halo_pairs = pair_metrics[
            (pair_metrics["Rater1"] == r) & (pair_metrics["Rater2"] == r)
        ]
        non_halo_pairs = pair_metrics[
            ((pair_metrics["Rater1"] == r) ^ (pair_metrics["Rater2"] == r))
        ]
        retained_halo = halo_pairs[halo_pairs["RetainedEdge"]]
        retained_non_halo = non_halo_pairs[non_halo_pairs["RetainedEdge"]]
        halo_mean_weight = (
            float(retained_halo["AbsEstimate"].mean()) if not retained_halo.empty else np.nan
        )
        non_halo_mean_weight = (
            float(retained_non_halo["AbsEstimate"].mean())
            if not retained_non_halo.empty else np.nan
        )
        contrast = (
            halo_mean_weight - non_halo_mean_weight
            if np.isfinite(halo_mean_weight) and np.isfinite(non_halo_mean_weight)
            else np.nan
        )
        # Review status with three tiers. ``warning`` requires both a
        # high same-rater cross-criterion mean weight AND a clear
        # contrast against the non-halo edges (or, equivalently, no
        # non-halo edges retained at all — in which case the halo
        # signal dominates trivially). ``review`` is the softer tier
        # for when only one criterion is elevated. Otherwise ``ok``.
        halo_mean_high = (
            np.isfinite(halo_mean_weight)
            and halo_mean_weight >= float(halo_weight_review)
        )
        contrast_high = (
            np.isfinite(contrast)
            and contrast >= float(halo_contrast_review)
        )
        no_non_halo_for_contrast = (
            np.isfinite(halo_mean_weight)
            and not np.isfinite(non_halo_mean_weight)
            and len(retained_halo) > 0
        )
        warn = halo_mean_high and (contrast_high or no_non_halo_for_contrast)
        review_only = (halo_mean_high or contrast_high) and not warn
        if warn:
            review_status = "warning"
            if no_non_halo_for_contrast:
                review_reason = (
                    f"Same-rater cross-criterion mean correlation = "
                    f"{halo_mean_weight:.3f} (>= {halo_weight_review:.2f}); "
                    "no non-halo edges were retained at the configured "
                    "alpha / weight threshold, so the halo signal dominates."
                )
            else:
                review_reason = (
                    f"Same-rater cross-criterion mean correlation = "
                    f"{halo_mean_weight:.3f} (>= {halo_weight_review:.2f}); "
                    f"halo - non-halo contrast = {contrast:.3f} "
                    f"(>= {halo_contrast_review:.2f})."
                )
        elif review_only:
            review_status = "review"
            review_reason = (
                f"Halo mean weight = "
                f"{halo_mean_weight if np.isfinite(halo_mean_weight) else float('nan'):.3f}; "
                f"halo - non-halo contrast = "
                f"{contrast if np.isfinite(contrast) else float('nan'):.3f}. "
                "At least one screening criterion is elevated."
            )
        else:
            review_status = "ok"
            review_reason = "No screening criterion is elevated."

        halo_summary_rows.append({
            "Rater": r,
            "NHaloEdges": int(len(retained_halo)),
            "NNonHaloEdges": int(len(retained_non_halo)),
            "HaloMeanWeight": halo_mean_weight,
            "NonHaloMeanWeight": non_halo_mean_weight,
            "HaloNonHaloContrast": contrast,
            "ReviewStatus": review_status,
            "ReviewReason": review_reason,
        })
    halo_summary = pd.DataFrame(halo_summary_rows)

    # Welch t-test contrast on retained halo vs non-halo edges.
    welch_t = welch_p = np.nan
    try:
        from scipy.stats import ttest_ind
        halo_weights = edge_metrics[edge_metrics["EdgeType"] == "halo"]["Weight"].dropna()
        non_halo_weights = edge_metrics[edge_metrics["EdgeType"] == "non_halo"]["Weight"].dropna()
        if len(halo_weights) >= 2 and len(non_halo_weights) >= 2:
            result = ttest_ind(halo_weights, non_halo_weights, equal_var=False)
            welch_t = float(result.statistic)
            welch_p = float(result.pvalue)
    except Exception:
        pass

    n_halo_retained = int(
        ((edge_metrics["EdgeType"] == "halo") & edge_metrics["RetainedEdge"]).sum()
    )
    n_non_halo_retained = int(
        ((edge_metrics["EdgeType"] == "non_halo") & edge_metrics["RetainedEdge"]).sum()
    )
    summary = pd.DataFrame([{
        "Nodes": int(len(node_tbl)),
        "RetainedEdges": int(len(edge_metrics)),
        "HaloEdges": n_halo_retained,
        "NonHaloEdges": n_non_halo_retained,
        "HaloMeanWeight": (
            float(edge_metrics.loc[edge_metrics["EdgeType"] == "halo", "Weight"].mean())
            if n_halo_retained > 0 else np.nan
        ),
        "NonHaloMeanWeight": (
            float(edge_metrics.loc[edge_metrics["EdgeType"] == "non_halo", "Weight"].mean())
            if n_non_halo_retained > 0 else np.nan
        ),
        "HaloNonHaloContrast": np.nan,
        "WelchT": welch_t,
        "WelchP": welch_p,
    }])
    if np.isfinite(summary.loc[0, "HaloMeanWeight"]) and np.isfinite(summary.loc[0, "NonHaloMeanWeight"]):
        summary.loc[0, "HaloNonHaloContrast"] = (
            float(summary.loc[0, "HaloMeanWeight"]) - float(summary.loc[0, "NonHaloMeanWeight"])
        )

    out = {
        "available": True,
        "reason": "",
        "summary": summary,
        "node_metrics": node_tbl,
        "pair_metrics": pair_metrics.reset_index(drop=True),
        "edge_metrics": edge_metrics.reset_index(drop=True),
        "halo_summary_by_rater": halo_summary,
        "settings": {
            "rater_facet": rater_facet,
            "criterion_facet": criterion_facet,
            "context_facets": list(context_facets),
            "method": str(method or "spearman").lower(),
            "min_pair_n": int(min_pair_n),
            "alpha": float(alpha),
            "p_adjust": "bonferroni",
            "min_abs_weight": float(min_abs_weight),
            "halo_weight_review": float(halo_weight_review),
            "halo_contrast_review": float(halo_contrast_review),
            "positive_only": bool(positive_only),
            "node_definition": "rater-by-criterion score profile",
            "halo_edge_definition": "edge connecting two criteria scored by the same rater",
        },
        "caveats": (
            "Edge weights are clustered by rater and node; the Welch test "
            "contrasting halo vs non-halo edge weights is descriptive only. "
            "Read ReviewStatus = 'warning' as a follow-up trigger, not a "
            "causal halo diagnosis."
        ),
        "references": (
            "Lai, Wolfe, & Vickers (2015); Lamprianou (2025)."
        ),
    }
    if include_graph:
        out["graph"] = graph
    return out


def _empty_halo_bundle(reason: str) -> dict:
    return {
        "available": False,
        "reason": reason,
        "summary": pd.DataFrame(),
        "node_metrics": pd.DataFrame(),
        "pair_metrics": pd.DataFrame(),
        "edge_metrics": pd.DataFrame(),
        "halo_summary_by_rater": pd.DataFrame(),
        "settings": {},
        "caveats": "",
        "references": "",
    }


# ============================================================================
# Generalizability theory (G-study) and design-of-measurement (D-study)
# ============================================================================
# `compute_generalizability_study(res)` runs a method-of-moments ANOVA
# decomposition on the rating data and reports variance components,
# G / Phi coefficients (Cronbach, Gleser, Nanda, & Rajaratnam, 1972;
# Brennan, 2001), and a D-study forecast grid that scales G / Phi to
# planned numbers of raters and criteria. The helper does NOT refit
# the MFRM as a random-effects model; it treats the rating data as a
# crossed main-effects ANOVA. Two-way and higher person-by-facet
# interactions are folded into the residual, which is the standard
# one-observation-per-cell approximation; the bundle's `caveat`
# field documents this limitation in manuscript-ready language.

_GD_STUDY_DEFAULT_GRID = (1, 2, 3, 4, 5, 6, 8, 10)


def _is_balanced_one_obs_per_cell(
    work: pd.DataFrame,
    facets: list[str],
) -> bool:
    """Detect whether the design has exactly one observation per cell."""
    if work.empty or not facets:
        return False
    cells = work.groupby(facets, observed=False).size()
    return bool((cells == 1).all() and cells.size > 0)


def _crossed_anova_two_way_variance_components(
    work: pd.DataFrame,
    *,
    object_facet: str,
    random_facets: list[str],
    score_col: str,
    grand_mean: float,
    ss_total: float,
) -> pd.DataFrame | None:
    """Full random-effects 3-way ANOVA decomposition under one-obs-per-cell.

    For a balanced p x i x j design with one observation per cell, all
    factors random, and Person as the object of measurement, the
    method-of-moments equations from Brennan (2001, Table 3.5) yield:

      sigma2_p   = (MS_p   - MS_pi - MS_pj + MS_pij) / (n_i n_j)
      sigma2_i   = (MS_i   - MS_pi - MS_ij + MS_pij) / (n_p n_j)
      sigma2_j   = (MS_j   - MS_pj - MS_ij + MS_pij) / (n_p n_i)
      sigma2_pi  = (MS_pi  - MS_pij) / n_j
      sigma2_pj  = (MS_pj  - MS_pij) / n_i
      sigma2_ij  = (MS_ij  - MS_pij) / n_p
      sigma2_pij = MS_pij              (residual; confounded with error)

    Returns the variance-component table with seven rows (three main
    effects + three two-way interactions + residual) when applicable,
    or ``None`` when the design does not satisfy the one-observation-
    per-cell balanced assumption. Variance estimates are clamped at
    zero (Henderson III convention; Brennan 2001 p. 81).
    """
    if len(random_facets) != 2:
        return None
    p_facet = object_facet
    i_facet, j_facet = random_facets[0], random_facets[1]
    facets_3way = [p_facet, i_facet, j_facet]
    if not _is_balanced_one_obs_per_cell(work, facets_3way):
        return None

    n_p = int(work[p_facet].nunique())
    n_i = int(work[i_facet].nunique())
    n_j = int(work[j_facet].nunique())
    if min(n_p, n_i, n_j) < 2:
        return None

    def cell_mean(group_cols):
        return work.groupby(group_cols, observed=False)[score_col].mean()

    # Main-effect SS (each weighted by the cell count of the
    # marginalised facets so the formula matches the balanced ANOVA).
    means_p = cell_mean(p_facet)
    ss_p = float(n_i * n_j * np.sum((means_p.to_numpy(dtype=float) - grand_mean) ** 2))
    means_i = cell_mean(i_facet)
    ss_i = float(n_p * n_j * np.sum((means_i.to_numpy(dtype=float) - grand_mean) ** 2))
    means_j = cell_mean(j_facet)
    ss_j = float(n_p * n_i * np.sum((means_j.to_numpy(dtype=float) - grand_mean) ** 2))

    # Two-way SS: SS_pi = n_j * sum (bar_Y_pi. - bar_Y_p.. - bar_Y_.i. + bar_Y_...)^2
    means_pi = cell_mean([p_facet, i_facet]).unstack().to_numpy()
    means_pj = cell_mean([p_facet, j_facet]).unstack().to_numpy()
    means_ij = cell_mean([i_facet, j_facet]).unstack().to_numpy()
    means_p_arr = means_p.to_numpy(dtype=float).reshape(-1, 1)
    means_i_arr = means_i.to_numpy(dtype=float).reshape(-1, 1)
    means_j_arr = means_j.to_numpy(dtype=float).reshape(-1, 1)

    diff_pi = (
        means_pi - means_p_arr - means_i.to_numpy(dtype=float).reshape(1, -1) + grand_mean
    )
    ss_pi = float(n_j * np.sum(diff_pi ** 2))
    diff_pj = (
        means_pj - means_p_arr - means_j.to_numpy(dtype=float).reshape(1, -1) + grand_mean
    )
    ss_pj = float(n_i * np.sum(diff_pj ** 2))
    diff_ij = (
        means_ij - means_i_arr - means_j.to_numpy(dtype=float).reshape(1, -1) + grand_mean
    )
    ss_ij = float(n_p * np.sum(diff_ij ** 2))

    # Residual (= three-way interaction confounded with error under
    # one obs per cell) by subtraction.
    ss_residual = max(ss_total - ss_p - ss_i - ss_j - ss_pi - ss_pj - ss_ij, 0.0)

    # Degrees of freedom for each source (Brennan 2001 Table 3.5).
    df_p = n_p - 1
    df_i = n_i - 1
    df_j = n_j - 1
    df_pi = df_p * df_i
    df_pj = df_p * df_j
    df_ij = df_i * df_j
    df_residual = df_p * df_i * df_j

    def safe_div(num, den):
        return float(num / den) if (np.isfinite(num) and den > 0) else np.nan

    ms_p = safe_div(ss_p, df_p)
    ms_i = safe_div(ss_i, df_i)
    ms_j = safe_div(ss_j, df_j)
    ms_pi = safe_div(ss_pi, df_pi)
    ms_pj = safe_div(ss_pj, df_pj)
    ms_ij = safe_div(ss_ij, df_ij)
    ms_residual = safe_div(ss_residual, df_residual)

    # Method-of-moments variance estimators. Clamp at zero per
    # Henderson III convention (negative MoM estimates are a
    # finite-sample artefact; Brennan 2001 p. 81).
    sigma2_residual = max(ms_residual, 0.0)
    sigma2_pi = max((ms_pi - ms_residual) / max(n_j, 1), 0.0)
    sigma2_pj = max((ms_pj - ms_residual) / max(n_i, 1), 0.0)
    sigma2_ij = max((ms_ij - ms_residual) / max(n_p, 1), 0.0)
    sigma2_p = max(
        (ms_p - ms_pi - ms_pj + ms_residual) / max(n_i * n_j, 1), 0.0
    )
    sigma2_i = max(
        (ms_i - ms_pi - ms_ij + ms_residual) / max(n_p * n_j, 1), 0.0
    )
    sigma2_j = max(
        (ms_j - ms_pj - ms_ij + ms_residual) / max(n_p * n_i, 1), 0.0
    )

    rows = [
        {"Source": p_facet, "SumSquares": ss_p, "df": df_p,
         "MeanSquares": ms_p, "Variance": sigma2_p,
         "MeanObsPerLevel": float(n_i * n_j), "Levels": n_p,
         "Term": "main"},
        {"Source": i_facet, "SumSquares": ss_i, "df": df_i,
         "MeanSquares": ms_i, "Variance": sigma2_i,
         "MeanObsPerLevel": float(n_p * n_j), "Levels": n_i,
         "Term": "main"},
        {"Source": j_facet, "SumSquares": ss_j, "df": df_j,
         "MeanSquares": ms_j, "Variance": sigma2_j,
         "MeanObsPerLevel": float(n_p * n_i), "Levels": n_j,
         "Term": "main"},
        {"Source": f"{p_facet}:{i_facet}", "SumSquares": ss_pi, "df": df_pi,
         "MeanSquares": ms_pi, "Variance": sigma2_pi,
         "MeanObsPerLevel": float(n_j), "Levels": n_p * n_i,
         "Term": "two-way"},
        {"Source": f"{p_facet}:{j_facet}", "SumSquares": ss_pj, "df": df_pj,
         "MeanSquares": ms_pj, "Variance": sigma2_pj,
         "MeanObsPerLevel": float(n_i), "Levels": n_p * n_j,
         "Term": "two-way"},
        {"Source": f"{i_facet}:{j_facet}", "SumSquares": ss_ij, "df": df_ij,
         "MeanSquares": ms_ij, "Variance": sigma2_ij,
         "MeanObsPerLevel": float(n_p), "Levels": n_i * n_j,
         "Term": "two-way"},
        {"Source": "Residual", "SumSquares": ss_residual, "df": df_residual,
         "MeanSquares": ms_residual, "Variance": sigma2_residual,
         "MeanObsPerLevel": float("nan"),
         "Levels": None, "Term": "residual"},
    ]
    out = pd.DataFrame(rows)
    total_var = float(np.nansum(out["Variance"]))
    out["ProportionVariance"] = (
        out["Variance"] / total_var if total_var > 0 else np.nan
    )
    return out[[
        "Source", "Term", "Variance", "ProportionVariance",
        "SumSquares", "df", "MeanSquares", "MeanObsPerLevel", "Levels",
    ]]


def _crossed_anova_variance_components(
    obs_df: pd.DataFrame,
    *,
    object_facet: str,
    random_facets: list[str],
    score_col: str = "Score",
) -> pd.DataFrame:
    """Method-of-moments variance components for a crossed main-effects design.

    Returns one row per source (object_facet, each random_facet, Residual)
    with Variance, ProportionVariance, SumSquares, df, MeanSquares,
    MeanObsPerLevel. For balanced data the variance estimates match the
    classical ANOVA method-of-moments solutions; for mildly unbalanced
    data the estimates remain useful summaries even if not unbiased.

    When the design admits a full 3-way ANOVA (object + exactly two
    random facets, balanced, one observation per cell), the helper
    delegates to ``_crossed_anova_two_way_variance_components`` which
    estimates the three two-way interaction variances explicitly per
    Brennan (2001, Table 3.5). The main-effects-only path below is
    used for designs with 1 random facet, 3+ random facets, or any
    unbalanced cell structure.
    """
    needed = [object_facet] + list(random_facets) + [score_col]
    missing = [c for c in needed if c not in obs_df.columns]
    if missing:
        return pd.DataFrame()
    work = obs_df[needed].copy()
    work[score_col] = pd.to_numeric(work[score_col], errors="coerce")
    work = work.dropna(subset=[score_col])
    n_obs = int(len(work))
    if n_obs == 0:
        return pd.DataFrame()
    for col in [object_facet] + list(random_facets):
        work[col] = work[col].astype(str)

    grand_mean = float(work[score_col].mean())
    ss_total = float(((work[score_col] - grand_mean) ** 2).sum())

    # Try the full 3-way decomposition first (Brennan 2001 Table 3.5).
    # When the design admits it, this gives explicit two-way
    # interaction variances and a residual that is the three-way
    # interaction confounded with error; otherwise fall through to the
    # main-effects-only approximation below.
    two_way = _crossed_anova_two_way_variance_components(
        work,
        object_facet=object_facet,
        random_facets=list(random_facets),
        score_col=score_col,
        grand_mean=grand_mean,
        ss_total=ss_total,
    )
    if two_way is not None and not two_way.empty:
        return two_way

    rows = []
    explained_ss = 0.0
    facet_terms = [object_facet] + list(random_facets)
    for facet in facet_terms:
        grouped = work.groupby(facet, observed=False)
        means = grouped[score_col].mean()
        ns = grouped[score_col].size().astype(float)
        k = int(len(means))
        if k < 2:
            continue
        ss_facet = float(np.sum(ns.to_numpy() * (means.to_numpy() - grand_mean) ** 2))
        df_facet = k - 1
        ms_facet = ss_facet / df_facet if df_facet > 0 else np.nan
        # Harmonic-mean observations per level. Under a balanced design
        # this equals n_obs / k exactly. Under unbalanced designs it
        # gives the correct unbiased denominator for the random-effects
        # method-of-moments estimator
        # ``sigma2_facet = (MS_facet - MS_residual) / m_per_level``;
        # cf. Searle, Casella, & McCulloch (1992, Section 3.4) for the
        # Henderson III formulation. The harmonic mean prevents the
        # estimator from being biased upward when one level has many
        # observations and others have few.
        ns_arr = ns.to_numpy(dtype=float)
        ns_valid = ns_arr[ns_arr > 0]
        if ns_valid.size > 0 and np.all(ns_valid > 0):
            harmonic_mean_n = float(ns_valid.size / np.sum(1.0 / ns_valid))
        else:
            harmonic_mean_n = float(n_obs / max(k, 1))
        mean_obs_per_level = harmonic_mean_n
        explained_ss += ss_facet
        rows.append({
            "Source": facet,
            "Term": "main",
            "SumSquares": ss_facet,
            "df": df_facet,
            "MeanSquares": ms_facet,
            "MeanObsPerLevel": mean_obs_per_level,
            "Levels": k,
        })
    ss_residual = max(float(ss_total - explained_ss), 0.0)
    df_residual = max(int(n_obs - sum(int(r["Levels"]) for r in rows) + len(rows) - 1), 1)
    ms_residual = ss_residual / df_residual if df_residual > 0 else np.nan
    rows.append({
        "Source": "Residual",
        "Term": "residual",
        "SumSquares": ss_residual,
        "df": df_residual,
        "MeanSquares": ms_residual,
        "MeanObsPerLevel": float("nan"),
        "Levels": None,
    })

    out = pd.DataFrame(rows)
    sigma2_e = ms_residual if np.isfinite(ms_residual) else np.nan
    variances = []
    for _, row in out.iterrows():
        source = row["Source"]
        if source == "Residual":
            variances.append(float(sigma2_e) if np.isfinite(sigma2_e) else np.nan)
            continue
        ms = float(row["MeanSquares"])
        m_per = float(row["MeanObsPerLevel"]) if pd.notna(row["MeanObsPerLevel"]) else np.nan
        if not (np.isfinite(ms) and np.isfinite(sigma2_e) and np.isfinite(m_per) and m_per > 0):
            variances.append(np.nan)
        else:
            variances.append(max((ms - sigma2_e) / m_per, 0.0))
    out["Variance"] = variances
    total_var = float(np.nansum(out["Variance"]))
    out["ProportionVariance"] = (
        out["Variance"] / total_var if total_var > 0 else np.nan
    )
    return out[
        ["Source", "Term", "Variance", "ProportionVariance", "SumSquares", "df",
         "MeanSquares", "MeanObsPerLevel", "Levels"]
    ]


def _g_phi_from_variance_components(
    var_components: pd.DataFrame,
    *,
    object_facet: str,
    facet_observations: dict[str, int] | None = None,
) -> dict:
    """Compute G / Phi from a variance-component table.

    Two formulas are used depending on what the variance-component
    table carries:

    * **Full 3-way decomposition** (the table has explicit two-way
      interaction terms ``object:facetA``, ``object:facetB``,
      ``facetA:facetB``): the canonical Brennan (2001, Eq. 3.18)
      formulas with explicit interaction variances:

          sigma2(delta) = sigma2_pi / n_i + sigma2_pj / n_j + sigma2_pij / (n_i n_j)
          sigma2(Delta) = sigma2(delta) + sigma2_i / n_i + sigma2_j / n_j + sigma2_ij / (n_i n_j)
          G   = sigma2_p / (sigma2_p + sigma2(delta))
          Phi = sigma2_p / (sigma2_p + sigma2(Delta))

      Here ``sigma2_pij`` is the residual term (three-way interaction
      confounded with error under one observation per cell).

    * **Main-effects-only fallback**: every facet other than the
      object contributes ``sigma2_facet / n_facet`` to absolute error
      and the residual contributes ``sigma2_residual / n_total`` to
      both relative and absolute error. This path is used for 1-
      random-facet designs, 3+-random-facet designs, and any
      unbalanced cell structure. The caveat field documents that
      person-by-facet interaction variance is absorbed into the
      residual in this mode.
    """
    if not isinstance(var_components, pd.DataFrame) or var_components.empty:
        return {"G": np.nan, "Phi": np.nan, "details": {}}

    # Lookup by Source name; the table may also carry a Term column
    # ("main" / "two-way" / "residual") to flag interaction rows.
    lookup = {
        str(row["Source"]): float(row["Variance"])
        for _, row in var_components.iterrows()
    }
    sigma2_p = lookup.get(object_facet, np.nan)
    sigma2_e = lookup.get("Residual", np.nan)
    if not (np.isfinite(sigma2_p) and np.isfinite(sigma2_e) and sigma2_p > 0):
        return {"G": np.nan, "Phi": np.nan, "details": {"sigma2_p": sigma2_p, "sigma2_e": sigma2_e}}

    facet_obs = facet_observations or {}
    has_term = "Term" in var_components.columns
    two_way_rows = (
        var_components[var_components["Term"] == "two-way"]
        if has_term else pd.DataFrame()
    )
    using_interactions = not two_way_rows.empty

    if using_interactions:
        # Full 3-way decomposition. Identify the two random facets
        # from the two-way Source labels that involve the object_facet.
        random_facets: list[str] = []
        for src in two_way_rows["Source"]:
            parts = [p for p in str(src).split(":") if p != object_facet]
            for p in parts:
                if p not in random_facets:
                    random_facets.append(p)
        n_a = max(int(facet_obs.get(random_facets[0], 1)), 1) if random_facets else 1
        n_b = max(int(facet_obs.get(random_facets[1], 1)), 1) if len(random_facets) > 1 else 1

        def lookup_two_way(facets: tuple[str, str]) -> float:
            for src, var in lookup.items():
                parts = set(str(src).split(":"))
                if parts == set(facets):
                    return float(var)
            return 0.0

        i_facet = random_facets[0] if random_facets else None
        j_facet = random_facets[1] if len(random_facets) > 1 else None
        sigma2_pi = lookup_two_way((object_facet, i_facet)) if i_facet else 0.0
        sigma2_pj = lookup_two_way((object_facet, j_facet)) if j_facet else 0.0
        sigma2_ij = lookup_two_way((i_facet, j_facet)) if i_facet and j_facet else 0.0
        sigma2_i = lookup.get(i_facet, 0.0) if i_facet else 0.0
        sigma2_j = lookup.get(j_facet, 0.0) if j_facet else 0.0

        # Brennan (2001) Eq. 3.18 / 3.19.
        sigma2_delta = (
            sigma2_pi / n_a + sigma2_pj / n_b + sigma2_e / (n_a * n_b)
        )
        sigma2_big_delta = (
            sigma2_delta
            + sigma2_i / n_a + sigma2_j / n_b + sigma2_ij / (n_a * n_b)
        )
        g_coef = sigma2_p / (sigma2_p + sigma2_delta)
        phi_coef = sigma2_p / (sigma2_p + sigma2_big_delta)
        return {
            "G": float(g_coef),
            "Phi": float(phi_coef),
            "details": {
                "sigma2_object": sigma2_p,
                "sigma2_residual": sigma2_e,
                "sigma2_relative_error": sigma2_delta,
                "sigma2_absolute_error": sigma2_big_delta,
                "facet_observations": dict(facet_obs),
                "decomposition": "full_3way_brennan_eq_3_18",
                "random_facets": list(random_facets),
            },
        }

    # Main-effects-only fallback.
    sigma2_main_per_obs = 0.0
    for source, variance in lookup.items():
        if source in {object_facet, "Residual"} or not np.isfinite(variance):
            continue
        n_per = facet_obs.get(source, 1)
        sigma2_main_per_obs += variance / max(int(n_per), 1)

    # Total number of conditions-of-measurement observations per object.
    n_total = max(int(np.prod([max(facet_obs.get(s, 1), 1)
                              for s in lookup
                              if s not in {object_facet, "Residual"}])), 1)
    relative_err = sigma2_e / n_total
    g_coef = sigma2_p / (sigma2_p + relative_err)
    phi_coef = sigma2_p / (sigma2_p + sigma2_main_per_obs + relative_err)
    return {
        "G": float(g_coef),
        "Phi": float(phi_coef),
        "details": {
            "sigma2_object": sigma2_p,
            "sigma2_residual": sigma2_e,
            "sigma2_main_per_obs": sigma2_main_per_obs,
            "n_total": n_total,
            "facet_observations": dict(facet_obs),
            "decomposition": "main_effects_only_approximation",
        },
    }


def _build_d_study_grid(
    var_components: pd.DataFrame,
    *,
    object_facet: str,
    random_facets: list[str],
    facet_grids: dict[str, tuple[int, ...]],
) -> pd.DataFrame:
    """Forecast G / Phi over the cartesian product of facet sample sizes."""
    if not isinstance(var_components, pd.DataFrame) or var_components.empty:
        return pd.DataFrame()
    if not random_facets:
        return pd.DataFrame()
    grids = [facet_grids.get(f, _GD_STUDY_DEFAULT_GRID) for f in random_facets]
    rows = []
    import itertools
    for combo in itertools.product(*grids):
        facet_obs = {f: int(n) for f, n in zip(random_facets, combo)}
        gp = _g_phi_from_variance_components(
            var_components, object_facet=object_facet, facet_observations=facet_obs,
        )
        row = {f: int(n) for f, n in zip(random_facets, combo)}
        row["G"] = float(gp["G"]) if np.isfinite(gp.get("G", np.nan)) else np.nan
        row["Phi"] = float(gp["Phi"]) if np.isfinite(gp.get("Phi", np.nan)) else np.nan
        rows.append(row)
    return pd.DataFrame(rows)


def _bootstrap_g_phi_ci(
    data: pd.DataFrame,
    *,
    object_facet: str,
    random_facets: list[str],
    score_col: str,
    facet_observations: dict[str, int],
    n_bootstrap: int = 200,
    confidence: float = 0.95,
    seed: int | None = 20260601,
    extra_designs: list[dict[str, int]] | None = None,
) -> dict:
    """Cluster bootstrap CI for G and Phi coefficients.

    Resamples persons (the object of measurement) with replacement,
    recomputes the variance-component decomposition on each
    bootstrap sample, and reports the percentile-based CI for G and
    Phi at the observed design. Person-level cluster resampling is
    the standard nonparametric bootstrap for G-theory (Efron &
    Tibshirani, 1993, Ch. 19) and respects the within-person
    correlation structure that drives both relative and absolute
    error.

    When ``extra_designs`` is supplied, the same B variance-component
    replicates are evaluated at every additional ``facet_observations``
    dictionary in the list, and per-design replicate arrays are
    returned under ``extra_design_replicates``. This is how the
    D-study CI bands are computed: a single resample loop is shared
    across the observed design and every grid point.

    Returns
    -------
    dict
        With keys ``available``, ``reason``, ``G_lower``, ``G_upper``,
        ``Phi_lower``, ``Phi_upper``, ``G_replicates``,
        ``Phi_replicates``, ``confidence``, ``n_bootstrap``,
        ``n_success``, and optionally ``extra_design_replicates``
        (list of dicts, one per ``extra_designs`` entry, each with
        ``design`` plus the replicate arrays / CI bounds).
    """
    if not isinstance(data, pd.DataFrame) or data.empty:
        return {
            "available": False, "reason": "Empty data frame.",
            "G_lower": np.nan, "G_upper": np.nan,
            "Phi_lower": np.nan, "Phi_upper": np.nan,
            "G_replicates": np.array([]), "Phi_replicates": np.array([]),
            "confidence": float(confidence),
            "n_bootstrap": int(n_bootstrap), "n_success": 0,
            "extra_design_replicates": [],
        }
    n_bootstrap = max(int(n_bootstrap), 1)
    confidence = float(min(max(confidence, 0.0), 1.0))
    alpha_low = (1.0 - confidence) / 2.0
    alpha_high = 1.0 - alpha_low

    rng = np.random.default_rng(int(seed) if seed is not None else None)
    persons = data[object_facet].astype(str).unique()
    n_persons = int(persons.size)
    if n_persons < 2:
        return {
            "available": False, "reason": "Need >= 2 persons to bootstrap.",
            "G_lower": np.nan, "G_upper": np.nan,
            "Phi_lower": np.nan, "Phi_upper": np.nan,
            "G_replicates": np.array([]), "Phi_replicates": np.array([]),
            "confidence": confidence,
            "n_bootstrap": n_bootstrap, "n_success": 0,
            "extra_design_replicates": [],
        }

    # Pre-index rows by person for fast resampling.
    rows_by_person = {
        str(p): data[data[object_facet].astype(str) == str(p)]
        for p in persons
    }
    g_replicates: list[float] = []
    phi_replicates: list[float] = []
    extra_designs = list(extra_designs or [])
    extra_g_lists: list[list[float]] = [[] for _ in extra_designs]
    extra_phi_lists: list[list[float]] = [[] for _ in extra_designs]
    for _ in range(n_bootstrap):
        sample_persons = rng.choice(persons, size=n_persons, replace=True)
        # Re-label resampled persons with unique identifiers so the
        # ANOVA treats each draw as a distinct level (necessary because
        # a single original person can appear multiple times under
        # cluster resampling and ANOVA needs each cluster as a
        # different unit of measurement).
        parts = []
        for k, p in enumerate(sample_persons):
            sub = rows_by_person[str(p)].copy()
            sub[object_facet] = f"BOOT_{k:04d}_{p}"
            parts.append(sub)
        boot_df = pd.concat(parts, ignore_index=True)
        try:
            var_components = _crossed_anova_variance_components(
                boot_df,
                object_facet=object_facet,
                random_facets=random_facets,
                score_col=score_col,
            )
            if var_components.empty:
                continue
            coef = _g_phi_from_variance_components(
                var_components,
                object_facet=object_facet,
                facet_observations=facet_observations,
            )
            g_val = float(coef.get("G", np.nan))
            phi_val = float(coef.get("Phi", np.nan))
            if np.isfinite(g_val):
                g_replicates.append(g_val)
            if np.isfinite(phi_val):
                phi_replicates.append(phi_val)
            # Evaluate at every extra design with the same variance
            # components; this is the heart of the D-study CI bands.
            for k, design in enumerate(extra_designs):
                coef_k = _g_phi_from_variance_components(
                    var_components,
                    object_facet=object_facet,
                    facet_observations=design,
                )
                g_k = float(coef_k.get("G", np.nan))
                phi_k = float(coef_k.get("Phi", np.nan))
                if np.isfinite(g_k):
                    extra_g_lists[k].append(g_k)
                if np.isfinite(phi_k):
                    extra_phi_lists[k].append(phi_k)
        except Exception:
            continue

    g_arr = np.asarray(g_replicates, dtype=float)
    phi_arr = np.asarray(phi_replicates, dtype=float)
    def _percentile_ci(arr: np.ndarray):
        if arr.size < 2:
            return (np.nan, np.nan)
        return (
            float(np.quantile(arr, alpha_low)),
            float(np.quantile(arr, alpha_high)),
        )
    g_lo, g_hi = _percentile_ci(g_arr)
    phi_lo, phi_hi = _percentile_ci(phi_arr)

    extra_results = []
    for design, g_list, phi_list in zip(extra_designs, extra_g_lists, extra_phi_lists):
        g_a = np.asarray(g_list, dtype=float)
        phi_a = np.asarray(phi_list, dtype=float)
        gl, gh = _percentile_ci(g_a)
        pl, ph = _percentile_ci(phi_a)
        extra_results.append({
            "design": dict(design),
            "G_lower": gl, "G_upper": gh,
            "Phi_lower": pl, "Phi_upper": ph,
            "n_success": int(g_a.size),
        })

    return {
        "available": bool(g_arr.size >= 2 or phi_arr.size >= 2),
        "reason": (
            "" if (g_arr.size >= 2 or phi_arr.size >= 2)
            else "Insufficient bootstrap replicates produced finite coefficients."
        ),
        "G_lower": g_lo, "G_upper": g_hi,
        "Phi_lower": phi_lo, "Phi_upper": phi_hi,
        "G_replicates": g_arr, "Phi_replicates": phi_arr,
        "confidence": confidence,
        "n_bootstrap": n_bootstrap,
        "n_success": int(g_arr.size),
        "method": "cluster_bootstrap_on_persons",
        "extra_design_replicates": extra_results,
    }


def compute_generalizability_study(
    res: dict,
    *,
    object_facet: str = "Person",
    random_facets: list[str] | None = None,
    n_max_per_facet: int = 10,
    score_col: str = "Score",
    bootstrap_ci: bool = False,
    n_bootstrap: int = 200,
    bootstrap_confidence: float = 0.95,
    bootstrap_seed: int | None = 20260601,
) -> dict:
    """Run a G-study + D-study on the rating data backing a fit.

    Parameters
    ----------
    res : dict
        Result dictionary from ``mfrm_estimate`` (uses ``prep['data']``).
    object_facet : str
        Object of measurement (default ``"Person"``).
    random_facets : list[str] | None
        Random conditions of measurement. Defaults to every non-object
        facet in the fit configuration.
    n_max_per_facet : int
        Upper bound on the D-study sample-size grid for each facet
        (default 10). The grid is ``(1, 2, 3, 4, 5, 6, 8, 10)`` truncated
        to ``n_max_per_facet``.
    score_col : str
        Name of the score column (default ``"Score"``).

    Returns
    -------
    dict
        Bundle with keys:

        * ``available`` (bool) — pipeline produced a usable result
        * ``reason`` (str) — populated when ``available`` is False
        * ``variance_components`` (DataFrame) — Source / Variance /
          ProportionVariance / SumSquares / df / MeanSquares
        * ``observed_coefficients`` (dict) — ``G``, ``Phi`` at the
          observed average number of observations per facet level
        * ``d_study`` (DataFrame) — forecast G / Phi over a grid of
          planned ``(n_facet1, n_facet2, ...)`` combinations
        * ``design`` (dict) — object_facet, random_facets, observed_n,
          grand_mean, n_observations
        * ``caveat`` (str) — manuscript-ready scope statement
        * ``reference`` (str) — APA citation hint

    The math contract follows Cronbach et al. (1972) and Brennan (2001):
    sigma2_object / (sigma2_object + sigma2_residual / n_obs) for G,
    plus facet main-effect contributions for Phi.
    """
    if not isinstance(res, dict):
        return {
            "available": False,
            "reason": "Result is not a fit dictionary.",
            "variance_components": pd.DataFrame(),
            "observed_coefficients": {"G": np.nan, "Phi": np.nan},
            "d_study": pd.DataFrame(),
            "design": {},
            "caveat": "",
            "reference": "",
        }
    config = res.get("config", {}) if isinstance(res, dict) else {}
    prep = res.get("prep", {}) if isinstance(res, dict) else {}
    data = prep.get("data") if isinstance(prep, dict) else None
    if not isinstance(data, pd.DataFrame) or data.empty:
        return {
            "available": False,
            "reason": "Fit does not carry a raw data frame for G-study.",
            "variance_components": pd.DataFrame(),
            "observed_coefficients": {"G": np.nan, "Phi": np.nan},
            "d_study": pd.DataFrame(),
            "design": {},
            "caveat": "",
            "reference": "",
        }
    facet_names = list(config.get("facet_names", []))
    if random_facets is None:
        random_facets = [f for f in facet_names if f != object_facet]
    if not random_facets:
        return {
            "available": False,
            "reason": "At least one non-object random facet is required for a G-study.",
            "variance_components": pd.DataFrame(),
            "observed_coefficients": {"G": np.nan, "Phi": np.nan},
            "d_study": pd.DataFrame(),
            "design": {},
            "caveat": "",
            "reference": "",
        }

    var_components = _crossed_anova_variance_components(
        data,
        object_facet=object_facet,
        random_facets=random_facets,
        score_col=score_col,
    )
    if var_components.empty:
        return {
            "available": False,
            "reason": "Variance-component decomposition produced no usable rows.",
            "variance_components": pd.DataFrame(),
            "observed_coefficients": {"G": np.nan, "Phi": np.nan},
            "d_study": pd.DataFrame(),
            "design": {},
            "caveat": "",
            "reference": "",
        }

    # Observed facet sample sizes: number of distinct levels per facet
    # (one observation per cell of the cross is assumed by the
    # one-observation-per-cell approximation).
    observed_n = {f: int(data[f].astype(str).nunique()) for f in random_facets}
    observed_coefficients = _g_phi_from_variance_components(
        var_components,
        object_facet=object_facet,
        facet_observations=observed_n,
    )

    # D-study grid: cap at min(observed * 2, n_max_per_facet).
    facet_grids = {}
    for facet in random_facets:
        upper = max(observed_n.get(facet, 1) * 2, 4)
        upper = min(upper, int(n_max_per_facet))
        facet_grids[facet] = tuple(g for g in _GD_STUDY_DEFAULT_GRID if g <= upper)
        if not facet_grids[facet]:
            facet_grids[facet] = (1, observed_n.get(facet, 1))
    d_study = _build_d_study_grid(
        var_components,
        object_facet=object_facet,
        random_facets=random_facets,
        facet_grids=facet_grids,
    )

    design = {
        "object_facet": object_facet,
        "random_facets": list(random_facets),
        "observed_n": observed_n,
        "n_observations": int(len(data)),
        "grand_mean": float(pd.to_numeric(data[score_col], errors="coerce").mean()),
    }
    # Caveat depends on which decomposition path the helper took. For
    # the canonical balanced 3-way design with one observation per
    # cell the bundle reports explicit two-way interaction variances
    # (Brennan 2001 Table 3.5); otherwise it falls back to the main-
    # effects-only approximation.
    using_full = (
        observed_coefficients.get("details", {}).get("decomposition")
        == "full_3way_brennan_eq_3_18"
    )
    if using_full:
        caveat = (
            "Full random-effects 3-way ANOVA decomposition (Brennan, "
            "2001, Table 3.5) on the balanced one-observation-per-cell "
            "design. The variance-components table carries the three "
            "main effects, the three two-way interactions, and a "
            "Residual term that is the three-way interaction confounded "
            "with error (the standard one-observation-per-cell "
            "confounding). G is appropriate for relative decisions "
            "(rank ordering); Phi for absolute decisions (cut-score "
            "classification). Reporting bands follow Brennan (2001): "
            "G / Phi >= 0.8 for high-stakes decisions, >= 0.7 for "
            "routine reporting."
        )
    else:
        caveat = (
            "Main-effects-only crossed ANOVA decomposition (used when "
            "the design has only one random facet, three or more "
            "random facets, or an unbalanced cell structure). All "
            "two-way and higher person-by-facet interactions are "
            "folded into the Residual term, which can bias G downward "
            "when person x facet interactions are substantively large. "
            "For the canonical balanced p x i x j design with one "
            "observation per cell the bundle uses the full 3-way "
            "decomposition (Brennan 2001 Table 3.5) automatically. "
            "G is appropriate for relative decisions (rank ordering); "
            "Phi for absolute decisions (cut-score classification). "
            "Reporting bands follow Brennan (2001): G / Phi >= 0.8 "
            "for high-stakes decisions, >= 0.7 for routine reporting."
        )
    reference = (
        "Cronbach, Gleser, Nanda, & Rajaratnam (1972); Brennan (2001). "
        "Bootstrap CI: Efron & Tibshirani (1993, Ch. 19)."
    )

    bootstrap = {
        "available": False, "reason": "Bootstrap CI was not requested.",
        "G_lower": np.nan, "G_upper": np.nan,
        "Phi_lower": np.nan, "Phi_upper": np.nan,
        "confidence": float(bootstrap_confidence),
        "n_bootstrap": int(n_bootstrap),
        "n_success": 0,
        "extra_design_replicates": [],
    }
    if bootstrap_ci:
        # Build the list of extra designs to evaluate per replicate.
        # Each d_study row contributes a facet_observations dict; the
        # bootstrap loop computes the variance components ONCE per
        # replicate and reuses them across all grid points, so the
        # marginal cost of the D-study CI bands is small (one G/Phi
        # closed-form evaluation per replicate per grid point).
        extra_designs: list[dict[str, int]] = []
        if isinstance(d_study, pd.DataFrame) and not d_study.empty:
            for _, row in d_study.iterrows():
                design_dict: dict[str, int] = {}
                for facet in random_facets:
                    if facet in row.index and pd.notna(row[facet]):
                        design_dict[facet] = int(row[facet])
                if design_dict:
                    extra_designs.append(design_dict)
        bootstrap = _bootstrap_g_phi_ci(
            data,
            object_facet=object_facet,
            random_facets=list(random_facets),
            score_col=score_col,
            facet_observations=observed_n,
            n_bootstrap=int(n_bootstrap),
            confidence=float(bootstrap_confidence),
            seed=bootstrap_seed,
            extra_designs=extra_designs,
        )
        # Merge per-design CIs into d_study DataFrame.
        if (
            isinstance(d_study, pd.DataFrame)
            and not d_study.empty
            and bootstrap.get("available")
        ):
            extra_replicates = bootstrap.get("extra_design_replicates", [])
            # Match by (n_facet1, n_facet2, ...) tuple.
            ci_rows: dict[tuple, dict] = {}
            for entry in extra_replicates:
                key = tuple(int(entry["design"].get(f, 0)) for f in random_facets)
                ci_rows[key] = entry
            g_lows, g_highs, phi_lows, phi_highs = [], [], [], []
            for _, row in d_study.iterrows():
                key = tuple(int(row[f]) if f in row.index else 0 for f in random_facets)
                entry = ci_rows.get(key)
                if entry is None:
                    g_lows.append(np.nan)
                    g_highs.append(np.nan)
                    phi_lows.append(np.nan)
                    phi_highs.append(np.nan)
                else:
                    g_lows.append(float(entry["G_lower"]))
                    g_highs.append(float(entry["G_upper"]))
                    phi_lows.append(float(entry["Phi_lower"]))
                    phi_highs.append(float(entry["Phi_upper"]))
            d_study = d_study.copy()
            d_study["G_lower"] = g_lows
            d_study["G_upper"] = g_highs
            d_study["Phi_lower"] = phi_lows
            d_study["Phi_upper"] = phi_highs

    return {
        "available": True,
        "reason": "",
        "variance_components": var_components,
        "observed_coefficients": observed_coefficients,
        "d_study": d_study,
        "design": design,
        "caveat": caveat,
        "reference": reference,
        "bootstrap_ci": bootstrap,
    }


def _spearman_brown_forecast(reliability, multiplier):
    rel = float(reliability) if pd.notna(reliability) else np.nan
    mult = float(multiplier)
    if not np.isfinite(rel) or rel < 0 or not np.isfinite(mult) or mult <= 0:
        return np.nan
    rel = min(max(rel, 0.0), 0.999999)
    return float((mult * rel) / (1.0 + (mult - 1.0) * rel))


def _design_recommendation(facet, reliability, min_obs, cv_obs, high_bias=False):
    name = str(facet)
    lower = name.lower()
    rel = float(reliability) if pd.notna(reliability) else np.nan
    min_obs_val = float(min_obs) if pd.notna(min_obs) else np.nan
    cv_val = float(cv_obs) if pd.notna(cv_obs) else np.nan

    reasons = []
    actions = []
    if np.isfinite(rel) and rel < 0.70:
        reasons.append("low reliability")
        if lower == "person":
            actions.append("add independent ratings per person and keep common raters/tasks across groups")
        else:
            actions.append(f"add observations per {name} level before interpreting fine-grained differences")
    elif np.isfinite(rel) and rel >= 0.90 and lower != "person":
        reasons.append("large systematic facet differences")
        if any(token in lower for token in ["rater", "judge", "evaluator"]):
            actions.append("review rater calibration and consider anchoring or reporting severity differences")
        else:
            actions.append(f"report {name} differences explicitly; they are not negligible design noise")

    if np.isfinite(min_obs_val) and min_obs_val < 3:
        reasons.append("very sparse element")
        actions.append(f"collect at least 3 observations for the sparsest {name} level when feasible")
    if np.isfinite(cv_val) and cv_val > 1.0:
        reasons.append("unbalanced observations")
        actions.append(f"rebalance the design so {name} levels have less uneven observation counts")
    if bool(high_bias):
        reasons.append("bias/interaction signal")
        actions.append("inspect the Bias/Interaction tab before final reporting")

    if not actions:
        return "OK", "No immediate design change is suggested by this screen."
    status = "Review" if ("low reliability" in reasons or "very sparse element" in reasons or high_bias) else "Caution"
    return status, "; ".join(dict.fromkeys(actions))


def evaluate_design_from_fitted(res, diagnostics=None, forecast_multipliers=(1.5, 2.0, 3.0)):
    """Summarize design strength and simple reliability forecasts."""
    diagnostics = diagnostics or {}
    prep = res.get("prep", {})
    data = prep.get("data", pd.DataFrame())
    config = res.get("config", {})
    facets = ["Person"] + list(config.get("facet_names", []))
    facets = [f for f in facets if isinstance(data, pd.DataFrame) and f in data.columns]
    if data.empty or not facets:
        return {
            "available": False,
            "reason": "No fitted design data are available.",
            "overview": pd.DataFrame(),
            "facet_counts": pd.DataFrame(),
            "sample_size_adequacy": pd.DataFrame(),
            "sample_size_summary": pd.DataFrame(),
            "nesting_audit": pd.DataFrame(),
            "design_effect": pd.DataFrame(),
            "summary": pd.DataFrame(),
            "forecast": pd.DataFrame(),
        }

    rel_tbl = diagnostics.get("reliability", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()
    if not isinstance(rel_tbl, pd.DataFrame) or rel_tbl.empty:
        measures = diagnostics.get("measures", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()
        rel_tbl = calc_reliability(measures) if isinstance(measures, pd.DataFrame) else pd.DataFrame()

    count_rows = []
    summary_rows = []
    dummy_facets = config.get("dummy_facets", []) or []
    for facet in facets:
        counts = data.groupby(facet, observed=False).size().astype(float)
        levels = int(len(counts))
        mean_obs = float(counts.mean()) if levels else np.nan
        sd_obs = float(counts.std(ddof=1)) if levels > 1 else 0.0
        cv_obs = float(sd_obs / mean_obs) if np.isfinite(mean_obs) and mean_obs > 0 else np.nan
        for level, n_obs in counts.items():
            count_rows.append({"Facet": facet, "Level": str(level), "ObservedRows": int(n_obs)})

        rel_row = rel_tbl[rel_tbl["Facet"].astype(str) == str(facet)] if isinstance(rel_tbl, pd.DataFrame) and "Facet" in rel_tbl.columns else pd.DataFrame()
        reliability = float(rel_row["Reliability"].iloc[0]) if not rel_row.empty and "Reliability" in rel_row else np.nan
        separation = float(rel_row["Separation"].iloc[0]) if not rel_row.empty and "Separation" in rel_row else np.nan
        rmse = float(rel_row["RMSE"].iloc[0]) if not rel_row.empty and "RMSE" in rel_row else np.nan
        bias_tbl = diagnostics.get("bias", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()
        high_bias = False
        if isinstance(bias_tbl, pd.DataFrame) and not bias_tbl.empty and "Facet" in bias_tbl.columns:
            facet_bias = bias_tbl[bias_tbl["Facet"].astype(str) == str(facet)]
            bias_col = "Bias Size" if "Bias Size" in facet_bias.columns else None
            if bias_col:
                vals = pd.to_numeric(facet_bias[bias_col], errors="coerce").abs().dropna()
                high_bias = bool(len(vals) and float(vals.max()) >= 0.50)

        status, action = _design_recommendation(
            facet,
            reliability,
            float(counts.min()) if levels else np.nan,
            cv_obs,
            high_bias=high_bias,
        )
        summary_rows.append({
            "Facet": facet,
            "Levels": levels,
            "ObservedRows": int(counts.sum()) if levels else 0,
            "MeanRowsPerLevel": mean_obs,
            "MinRowsPerLevel": float(counts.min()) if levels else np.nan,
            "MaxRowsPerLevel": float(counts.max()) if levels else np.nan,
            "CVRowsPerLevel": cv_obs,
            "Reliability": reliability,
            "Separation": separation,
            "RMSE": rmse,
            "Status": status,
            "RecommendedAction": action,
        })

    n_possible = 1
    for facet in facets:
        n_possible *= max(int(data[facet].nunique(dropna=True)), 1)
    observed_cells = int(data[facets].drop_duplicates().shape[0])
    overview = pd.DataFrame([{
        "ObservedRows": int(len(data)),
        "DesignFacets": ", ".join(facets),
        "ObservedUniqueDesignCells": observed_cells,
        "FullyCrossedDesignCells": int(n_possible),
        "ObservedCellDensity": observed_cells / n_possible if n_possible else np.nan,
        "Interpretation": (
            "Density is relative to a fully crossed design. Sparse density can be intentional, "
            "but interpretation needs common links across persons and facet elements."
        ),
    }])

    forecast_rows = []
    for row in summary_rows:
        for mult in forecast_multipliers:
            forecast_rows.append({
                "Facet": row["Facet"],
                "Multiplier": float(mult),
                "CurrentReliability": row["Reliability"],
                "ForecastReliability": _spearman_brown_forecast(row["Reliability"], mult),
                "Assumption": "Spearman-Brown style forecast; assumes added ratings behave like current ratings.",
            })

    sample_audit = build_facet_sample_size_audit(
        data,
        facets,
        weight_col="Weight",
        dummy_facets=dummy_facets,
    )
    sample_summary = summarize_facet_sample_size_audit(sample_audit)
    nesting_audit = build_facet_nesting_audit(data, facets, weight_col="Weight")
    design_effect = compute_intraclass_design_effect(data, facets, score_col="Score")

    return {
        "available": True,
        "reason": "Design evaluation from fitted reliability and observed design balance.",
        "overview": overview,
        "facet_counts": pd.DataFrame(count_rows),
        "sample_size_adequacy": sample_audit,
        "sample_size_summary": sample_summary,
        "nesting_audit": nesting_audit,
        "design_effect": design_effect,
        "summary": pd.DataFrame(summary_rows),
        "forecast": pd.DataFrame(forecast_rows),
        "interpretation": (
            "Treat this as a planning screen. It flags sparse or unbalanced facets and gives "
            "rough reliability forecasts; it is not a replacement for a prospective simulation study."
        ),
    }


def compute_residual_file(res):
    obs = compute_obs_table(res)
    if obs.empty:
        return pd.DataFrame()
    cols = ["Person", *res["config"]["facet_names"]]
    if "Weight" in obs.columns:
        cols.append("Weight")
    cols += ["Score", "Observed", "Expected", "Residual", "StdResidual", "Var", "StdSq", "PersonMeasure"]
    return obs[cols]


def get_weights(df):
    if "Weight" in df.columns:
        w = df["Weight"].to_numpy(dtype=float)
        w = np.where(np.isfinite(w) & (w > 0), w, 0.0)
        return w
    return np.ones(len(df), dtype=float)


def calc_overall_fit(
    obs_df,
    whexact: bool = False,
    fit_df_method: str = "engine",
    facets_zstd_cap: float = 9.0,
):
    """Overall Infit / Outfit mean-square with optional FACETS d.f.

    The primary ``InfitZSTD`` / ``OutfitZSTD`` columns use the engine
    d.f. convention by default (``sum(Var * w)`` for Infit, ``sum(w)``
    for Outfit). Pass ``fit_df_method="facets"`` to swap them for the
    Wright-Masters Welch-Satterthwaite d.f., or ``"both"`` to keep
    side-by-side ``*_ENGINE`` / ``*_FACETS`` suffix columns. The
    ``facets_zstd_cap`` argument (default 9.0) bounds the FACETS ZSTD
    on extreme cells to match the FACETS software convention.
    """
    w = get_weights(obs_df)
    var = pd.to_numeric(obs_df["Var"], errors="coerce").to_numpy(dtype=float)
    fourth = (
        pd.to_numeric(obs_df.get("FourthCentralMoment"), errors="coerce").to_numpy(dtype=float)
        if "FourthCentralMoment" in obs_df.columns
        else np.full(len(obs_df), np.nan)
    )
    infit = np.nansum(obs_df["StdSq"] * obs_df["Var"] * w) / np.nansum(obs_df["Var"] * w)
    outfit = np.nansum(obs_df["StdSq"] * w) / np.nansum(w)
    df_infit = float(np.nansum(obs_df["Var"] * w))
    df_outfit = float(np.nansum(w))
    denom_infit, denom_outfit = _facets_fit_df_terms(var, fourth, w)
    df_infit_facets, df_outfit_facets = _facets_fit_df(df_infit, df_outfit, denom_infit, denom_outfit)
    tbl = pd.DataFrame({
        "Infit": [infit],
        "Outfit": [outfit],
        "InfitZSTD": [zstd_from_mnsq(infit, df_infit, whexact=whexact)],
        "OutfitZSTD": [zstd_from_mnsq(outfit, df_outfit, whexact=whexact)],
        "DF_Infit": [df_infit],
        "DF_Outfit": [df_outfit],
        "DF_Infit_FACETS": [df_infit_facets],
        "DF_Outfit_FACETS": [df_outfit_facets],
    })
    return _apply_fit_df_method(
        tbl,
        fit_df_method=fit_df_method,
        whexact=whexact,
        facets_zstd_cap=facets_zstd_cap,
    )


def calc_facet_fit(
    obs_df,
    facet_cols,
    whexact: bool = False,
    fit_df_method: str = "engine",
    facets_zstd_cap: float = 9.0,
):
    """Per-facet/-level Infit / Outfit mean-square with optional FACETS d.f."""
    rows = []
    has_fourth = "FourthCentralMoment" in obs_df.columns
    for facet in facet_cols:
        grp = obs_df.groupby(facet, observed=False)
        for level, df in grp:
            w = get_weights(df)
            infit = np.nansum(df["StdSq"] * df["Var"] * w) / np.nansum(df["Var"] * w)
            outfit = np.nansum(df["StdSq"] * w) / np.nansum(w)
            df_infit = float(np.nansum(df["Var"] * w))
            df_outfit = float(np.nansum(w))
            var = pd.to_numeric(df["Var"], errors="coerce").to_numpy(dtype=float)
            fourth = (
                pd.to_numeric(df["FourthCentralMoment"], errors="coerce").to_numpy(dtype=float)
                if has_fourth
                else np.full(len(df), np.nan)
            )
            denom_infit, denom_outfit = _facets_fit_df_terms(var, fourth, w)
            df_infit_facets, df_outfit_facets = _facets_fit_df(
                df_infit, df_outfit, denom_infit, denom_outfit
            )
            rows.append({
                "Facet": facet,
                "Level": level,
                "N": np.nansum(w),
                "Infit": infit,
                "Outfit": outfit,
                "InfitZSTD": zstd_from_mnsq(infit, df_infit, whexact=whexact),
                "OutfitZSTD": zstd_from_mnsq(outfit, df_outfit, whexact=whexact),
                "DF_Infit": df_infit,
                "DF_Outfit": df_outfit,
                "DF_Infit_FACETS": df_infit_facets,
                "DF_Outfit_FACETS": df_outfit_facets,
            })
    return _apply_fit_df_method(
        pd.DataFrame(rows),
        fit_df_method=fit_df_method,
        whexact=whexact,
        facets_zstd_cap=facets_zstd_cap,
    )


def calc_facet_se(obs_df, facet_cols):
    rows = []
    for facet in facet_cols:
        grp = obs_df.groupby(facet, observed=False)
        for level, df in grp:
            w = get_weights(df)
            info = np.nansum(df["Var"] * w)
            se = 1 / np.sqrt(info) if info > 0 else np.nan
            rows.append({
                "Facet": facet,
                "Level": level,
                "N": np.nansum(w),
                "SE": se,
            })
    return pd.DataFrame(rows)


def calc_bias_facet(obs_df, facet_cols):
    rows = []
    for facet in facet_cols:
        grp = obs_df.groupby(facet, observed=False)
        for level, df in grp:
            w = get_weights(df)
            n = np.nansum(w)
            observed_avg = weighted_mean(df["Observed"].to_numpy(), w)
            expected_avg = weighted_mean(df["Expected"].to_numpy(), w)
            mean_resid = weighted_mean(df["Residual"].to_numpy(), w)
            mean_std_resid = weighted_mean(df["StdResidual"].to_numpy(), w)
            mean_abs_std = weighted_mean(np.abs(df["StdResidual"]).to_numpy(), w)
            chi_sq = np.nansum((df["StdResidual"] ** 2) * w)
            se_resid = np.sqrt(np.nansum(df["Var"] * w)) / n if n > 0 else np.nan
            se_std = 1 / np.sqrt(n) if n > 0 else np.nan
            df_chi = n - 1 if n > 1 else np.nan
            t_resid = mean_resid / se_resid if np.isfinite(se_resid) and se_resid > 0 else np.nan
            t_std = mean_std_resid / se_std if np.isfinite(se_std) and se_std > 0 else np.nan
            p_resid = 2 * t_dist.cdf(-abs(t_resid), df=df_chi) if np.isfinite(df_chi) and np.isfinite(t_resid) else np.nan
            p_std = 2 * t_dist.cdf(-abs(t_std), df=df_chi) if np.isfinite(df_chi) and np.isfinite(t_std) else np.nan
            chi_p = 1 - chi2.cdf(chi_sq, df=df_chi) if np.isfinite(chi_sq) and np.isfinite(df_chi) and df_chi > 0 else np.nan

            rows.append({
                "Facet": facet,
                "Level": level,
                "N": n,
                "ObservedAverage": observed_avg,
                "ExpectedAverage": expected_avg,
                "Bias": mean_resid,
                "MeanResidual": mean_resid,
                "MeanStdResidual": mean_std_resid,
                "MeanAbsStdResidual": mean_abs_std,
                "ChiSq": chi_sq,
                "ChiDf": df_chi,
                "ChiP": chi_p,
                "SE_Residual": se_resid,
                "t_Residual": t_resid,
                "p_Residual": p_resid,
                "SE_StdResidual": se_std,
                "t_StdResidual": t_std,
                "p_StdResidual": p_std,
                "DF": df_chi,
            })
    return pd.DataFrame(rows)


def calc_bias_interactions(obs_df, facet_cols, pairs=None, top_n=20):
    if len(facet_cols) < 2:
        return pd.DataFrame()
    if pairs is None:
        combos = []
        for i in range(len(facet_cols)):
            for j in range(i + 1, len(facet_cols)):
                combos.append((facet_cols[i], facet_cols[j]))
    elif len(pairs) == 0:
        return pd.DataFrame()
    else:
        combos = pairs

    rows = []
    for pair1, pair2 in combos:
        grp = obs_df.groupby([pair1, pair2], observed=False)
        for (lvl1, lvl2), df in grp:
            w = get_weights(df)
            n = np.nansum(w)
            observed_avg = weighted_mean(df["Observed"].to_numpy(), w)
            expected_avg = weighted_mean(df["Expected"].to_numpy(), w)
            mean_resid = weighted_mean(df["Residual"].to_numpy(), w)
            mean_std_resid = weighted_mean(df["StdResidual"].to_numpy(), w)
            mean_abs_std = weighted_mean(np.abs(df["StdResidual"]).to_numpy(), w)
            chi_sq = np.nansum((df["StdResidual"] ** 2) * w)
            se_resid = np.sqrt(np.nansum(df["Var"] * w)) / n if n > 0 else np.nan
            se_std = 1 / np.sqrt(n) if n > 0 else np.nan
            df_chi = n - 1 if n > 1 else np.nan
            t_resid = mean_resid / se_resid if np.isfinite(se_resid) and se_resid > 0 else np.nan
            t_std = mean_std_resid / se_std if np.isfinite(se_std) and se_std > 0 else np.nan
            p_resid = 2 * t_dist.cdf(-abs(t_resid), df=df_chi) if np.isfinite(df_chi) and np.isfinite(t_resid) else np.nan
            p_std = 2 * t_dist.cdf(-abs(t_std), df=df_chi) if np.isfinite(df_chi) and np.isfinite(t_std) else np.nan
            chi_p = 1 - chi2.cdf(chi_sq, df=df_chi) if np.isfinite(chi_sq) and np.isfinite(df_chi) and df_chi > 0 else np.nan

            rows.append({
                "Pair": f"{pair1} x {pair2}",
                "Level": f"{lvl1} | {lvl2}",
                "N": n,
                "ObservedAverage": observed_avg,
                "ExpectedAverage": expected_avg,
                "Bias": mean_resid,
                "MeanResidual": mean_resid,
                "MeanStdResidual": mean_std_resid,
                "MeanAbsStdResidual": mean_abs_std,
                "ChiSq": chi_sq,
                "ChiDf": df_chi,
                "ChiP": chi_p,
                "SE_Residual": se_resid,
                "t_Residual": t_resid,
                "p_Residual": p_resid,
                "SE_StdResidual": se_std,
                "t_StdResidual": t_std,
                "p_StdResidual": p_std,
                "DF": df_chi,
            })

    out = pd.DataFrame(rows)
    if out.empty:
        return out
    out["AbsStd"] = out["MeanStdResidual"].abs()
    out = out.sort_values("AbsStd", ascending=False).drop(columns=["AbsStd"]).head(top_n)
    return out


def weighted_mean(x, w):
    ok = np.isfinite(x) & np.isfinite(w) & (w > 0)
    if not np.any(ok):
        return np.nan
    w_sum = np.sum(w[ok])
    if w_sum <= 0:
        return np.nan
    return float(np.sum(x[ok] * w[ok]) / w_sum)


FACET_SAMPLE_ADEQUACY_THRESHOLDS = OrderedDict([
    ("sparse", 10.0),
    ("marginal", 30.0),
    ("standard", 50.0),
])


def _facet_sample_category(n_effective: float) -> str:
    n = float(n_effective) if pd.notna(n_effective) else np.nan
    if not np.isfinite(n):
        return "unknown"
    if n < FACET_SAMPLE_ADEQUACY_THRESHOLDS["sparse"]:
        return "sparse"
    if n < FACET_SAMPLE_ADEQUACY_THRESHOLDS["marginal"]:
        return "marginal"
    if n < FACET_SAMPLE_ADEQUACY_THRESHOLDS["standard"]:
        return "standard"
    return "strong"


def _facet_sample_action(category: str, facet: str, *, is_dummy: bool = False) -> str:
    if is_dummy:
        return "Structural/dummy facet fixed at zero; do not interpret level differences."
    if category == "sparse":
        return f"Collect more observations or merge/review sparse {facet} levels before interpreting fine differences."
    if category == "marginal":
        return f"Interpret {facet} level estimates with caution and report the small-N limitation."
    if category == "standard":
        return f"{facet} level counts are adequate for routine review; still inspect SE and fit."
    if category == "strong":
        return f"{facet} level counts are strong for this descriptive screen."
    return f"{facet} sample adequacy could not be classified."


def build_facet_sample_size_audit(
    data: pd.DataFrame,
    facets: list[str],
    *,
    weight_col: str = "Weight",
    dummy_facets: Iterable[str] | None = None,
) -> pd.DataFrame:
    """Per-facet level sample adequacy using likelihood-included rows."""
    if not isinstance(data, pd.DataFrame) or data.empty or not facets:
        return pd.DataFrame()
    dummy_set = {str(v) for v in (dummy_facets or [])}
    rows: list[dict[str, object]] = []
    has_weight = weight_col in data.columns
    weights = pd.to_numeric(data.get(weight_col, pd.Series(1.0, index=data.index)), errors="coerce")
    weights = weights.where(np.isfinite(weights) & (weights > 0), 0.0)
    for facet in facets:
        if facet not in data.columns:
            continue
        tmp = pd.DataFrame({
            "Level": data[facet].astype(str),
            "Weight": weights.to_numpy(dtype=float) if has_weight else np.ones(len(data), dtype=float),
        })
        grouped = tmp.groupby("Level", observed=False).agg(
            RawRows=("Level", "size"),
            EffectiveWeight=("Weight", "sum"),
        ).reset_index()
        for row in grouped.itertuples(index=False):
            eff = float(getattr(row, "EffectiveWeight", np.nan))
            category = _facet_sample_category(eff)
            is_dummy = str(facet) in dummy_set
            rows.append({
                "Facet": str(facet),
                "Level": str(row.Level),
                "RawRows": int(getattr(row, "RawRows", 0)),
                "EffectiveWeight": eff,
                "SampleCategory": "structural" if is_dummy else category,
                "ThresholdRule": "sparse <10; marginal <30; standard <50; strong >=50",
                "DummyFacet": bool(is_dummy),
                "RecommendedAction": _facet_sample_action(category, str(facet), is_dummy=is_dummy),
            })
    out = pd.DataFrame(rows)
    if out.empty:
        return out
    order = {"structural": -1, "sparse": 0, "marginal": 1, "standard": 2, "strong": 3, "unknown": 4}
    out["_order"] = out["SampleCategory"].map(order).fillna(5)
    out = out.sort_values(["_order", "Facet", "EffectiveWeight", "Level"]).drop(columns=["_order"])
    return out.reset_index(drop=True)


def summarize_facet_sample_size_audit(audit: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(audit, pd.DataFrame) or audit.empty:
        return pd.DataFrame()
    rows = []
    for facet, df in audit.groupby("Facet", observed=False):
        categories = df["SampleCategory"].astype(str)
        non_struct = df.loc[categories != "structural"]
        source = non_struct if not non_struct.empty else df
        rows.append({
            "Facet": str(facet),
            "Levels": int(len(df)),
            "SparseLevels": int((categories == "sparse").sum()),
            "MarginalLevels": int((categories == "marginal").sum()),
            "StandardLevels": int((categories == "standard").sum()),
            "StrongLevels": int((categories == "strong").sum()),
            "WorstCategory": str(source["SampleCategory"].iloc[0]) if not source.empty else "unknown",
            "MinEffectiveWeight": float(pd.to_numeric(source["EffectiveWeight"], errors="coerce").min()) if not source.empty else np.nan,
            "RecommendedAction": (
                "Review sparse levels before publication."
                if int((categories == "sparse").sum()) else
                "Report marginal levels with caution."
                if int((categories == "marginal").sum()) else
                "No small-sample level flagged by this screen."
            ),
        })
    return pd.DataFrame(rows)


def _weighted_entropy(values: pd.Series, weights: pd.Series | None = None) -> float:
    if values is None:
        return 0.0
    if weights is None:
        weights = pd.Series(1.0, index=values.index)
    frame = pd.DataFrame({"Value": values.astype(str), "Weight": pd.to_numeric(weights, errors="coerce")})
    frame["Weight"] = frame["Weight"].where(np.isfinite(frame["Weight"]) & (frame["Weight"] > 0), 0.0)
    counts = frame.groupby("Value", observed=False)["Weight"].sum().to_numpy(dtype=float)
    total = float(np.nansum(counts))
    if total <= 0:
        return 0.0
    p = counts[counts > 0] / total
    return float(-np.sum(p * np.log(p)))


def build_facet_nesting_audit(
    data: pd.DataFrame,
    facets: list[str],
    *,
    weight_col: str = "Weight",
) -> pd.DataFrame:
    """Ordered conditional-entropy nesting/crossing screen for facets."""
    if not isinstance(data, pd.DataFrame) or data.empty:
        return pd.DataFrame()
    available = [str(f) for f in facets if str(f) in data.columns]
    if len(available) < 2:
        return pd.DataFrame()
    w = pd.to_numeric(data.get(weight_col, pd.Series(1.0, index=data.index)), errors="coerce")
    w = w.where(np.isfinite(w) & (w > 0), 0.0)
    rows: list[dict[str, object]] = []
    for facet_a in available:
        for facet_b in available:
            if facet_a == facet_b:
                continue
            frame = pd.DataFrame({
                "A": data[facet_a].astype(str),
                "B": data[facet_b].astype(str),
                "Weight": w,
            })
            total_w = float(frame["Weight"].sum())
            h_b = _weighted_entropy(frame["B"], frame["Weight"])
            h_cond = 0.0
            unique_b_per_a = []
            dominance = []
            for _, sub in frame.groupby("A", observed=False):
                sub_w = float(sub["Weight"].sum())
                if sub_w <= 0 or total_w <= 0:
                    continue
                h_cond += (sub_w / total_w) * _weighted_entropy(sub["B"], sub["Weight"])
                counts = sub.groupby("B", observed=False)["Weight"].sum()
                unique_b_per_a.append(int((counts > 0).sum()))
                dominance.append(float(counts.max() / counts.sum()) if counts.sum() > 0 else np.nan)
            index = 1.0 - (h_cond / h_b) if h_b > 0 else np.nan
            if np.isfinite(index) and index >= 0.999:
                classification = "Fully nested / deterministic"
            elif np.isfinite(index) and index >= 0.95:
                classification = "Near-perfectly nested"
            elif np.isfinite(index) and index >= 0.50:
                classification = "Partially nested"
            elif np.isfinite(index):
                classification = "Crossed"
            else:
                classification = "Degenerate"
            rows.append({
                "FacetA": facet_a,
                "FacetB": facet_b,
                "Interpretation": f"{facet_b} predictable from {facet_a}",
                "NestingIndex": index,
                "EntropyB": h_b,
                "ConditionalEntropyBGivenA": h_cond,
                "MedianUniqueBPerA": float(np.nanmedian(unique_b_per_a)) if unique_b_per_a else np.nan,
                "MaxUniqueBPerA": int(np.nanmax(unique_b_per_a)) if unique_b_per_a else 0,
                "MeanDominanceShare": float(np.nanmean(dominance)) if dominance else np.nan,
                "Classification": classification,
            })
    out = pd.DataFrame(rows)
    if out.empty:
        return out
    return out.sort_values(["NestingIndex", "FacetA", "FacetB"], ascending=[False, True, True]).reset_index(drop=True)


def compute_intraclass_design_effect(
    data: pd.DataFrame,
    facets: list[str],
    *,
    score_col: str = "Score",
) -> pd.DataFrame:
    """ANOVA-style cluster ICC and design effect by facet."""
    if not isinstance(data, pd.DataFrame) or data.empty or score_col not in data.columns:
        return pd.DataFrame()
    score = pd.to_numeric(data[score_col], errors="coerce")
    rows: list[dict[str, object]] = []
    for facet in facets:
        if facet not in data.columns:
            continue
        frame = pd.DataFrame({"Level": data[facet].astype(str), "Score": score}).dropna(subset=["Score"])
        if frame.empty:
            continue
        grouped = frame.groupby("Level", observed=False)["Score"]
        means = grouped.mean()
        ns = grouped.size().astype(float)
        k = int(len(ns))
        n = float(ns.sum())
        if k < 2 or n <= k:
            icc = np.nan
            ms_between = np.nan
            ms_within = np.nan
            n_bar = np.nan
        else:
            grand = float(frame["Score"].mean())
            ss_between = float(np.sum(ns * (means - grand) ** 2))
            ss_within = float(grouped.apply(lambda s: np.sum((s - s.mean()) ** 2)).sum())
            ms_between = ss_between / (k - 1)
            ms_within = ss_within / (n - k)
            n_bar = (n - float(np.sum(ns ** 2)) / n) / (k - 1) if k > 1 and n > 0 else np.nan
            denom = ms_between + (n_bar - 1.0) * ms_within
            icc = (ms_between - ms_within) / denom if np.isfinite(denom) and denom > 0 else np.nan
        icc_for_deff = max(float(icc), 0.0) if np.isfinite(icc) else np.nan
        mean_cluster = float(ns.mean()) if k else np.nan
        deff = 1.0 + (mean_cluster - 1.0) * icc_for_deff if np.isfinite(icc_for_deff) and np.isfinite(mean_cluster) else np.nan
        eff_n = n / deff if np.isfinite(deff) and deff > 0 else np.nan
        rows.append({
            "Facet": str(facet),
            "Levels": k,
            "Rows": int(n),
            "MeanClusterSize": mean_cluster,
            "IntraclassCorrelationClusterICC": icc,
            "DesignEffect": deff,
            "EffectiveN": eff_n,
            "MSBetween": ms_between,
            "MSWithin": ms_within,
            "Method": "one-way ANOVA descriptive screen on observed scores",
            "Caution": "Cluster ICC here is not an item-characteristic curve and not a random-effects MFRM estimate.",
        })
    return pd.DataFrame(rows)


def compute_empirical_bayes_shrinkage(
    measures: pd.DataFrame,
    *,
    min_levels: int = 3,
    shrink_person: bool = False,
    facet_prior_sd: float | None = None,
) -> dict:
    """Post-hoc James-Stein / empirical-Bayes shrinkage for facet measures."""
    empty = {
        "available": False,
        "reason": "Measure table is unavailable.",
        "measures": pd.DataFrame(),
        "report": pd.DataFrame(),
    }
    required = {"Facet", "Level", "Estimate", "SE"}
    if not isinstance(measures, pd.DataFrame) or measures.empty or not required.issubset(measures.columns):
        return empty
    rows: list[pd.DataFrame] = []
    report_rows: list[dict[str, object]] = []
    for facet, df in measures.groupby("Facet", observed=False):
        if str(facet) == "Person" and not shrink_person:
            continue
        sub = df.copy()
        sub["Estimate"] = pd.to_numeric(sub["Estimate"], errors="coerce")
        sub["SE"] = pd.to_numeric(sub["SE"], errors="coerce")
        valid = sub["Estimate"].notna() & sub["SE"].notna() & np.isfinite(sub["SE"]) & (sub["SE"] > 0)
        k_valid = int(valid.sum())
        sub["ShrinkageTau2"] = np.nan
        sub["ShrinkageFactor"] = 0.0
        sub["ShrunkEstimate"] = sub["Estimate"]
        sub["ShrunkSE"] = sub["SE"]
        sub["ShrinkageStatus"] = "not enough valid levels" if k_valid < int(min_levels) else "not shrunk"
        if k_valid >= int(min_levels):
            est = sub.loc[valid, "Estimate"].to_numpy(dtype=float)
            se = sub.loc[valid, "SE"].to_numpy(dtype=float)
            if facet_prior_sd is not None and np.isfinite(float(facet_prior_sd)) and float(facet_prior_sd) > 0:
                tau2 = float(facet_prior_sd) ** 2
                tau_source = "user-specified prior SD"
            else:
                tau2 = max(0.0, float(np.mean(est ** 2) - np.mean(se ** 2)))
                tau_source = "method-of-moments EB"
            denom = tau2 + se ** 2
            b = np.where(denom > 0, se ** 2 / denom, 1.0)
            b = np.clip(b, 0.0, 1.0)
            shrunk = (1.0 - b) * est
            shrunk_se = np.sqrt(np.maximum((1.0 - b) * se ** 2, 0.0))
            sub.loc[valid, "ShrinkageTau2"] = tau2
            sub.loc[valid, "ShrinkageFactor"] = b
            sub.loc[valid, "ShrunkEstimate"] = shrunk
            sub.loc[valid, "ShrunkSE"] = shrunk_se
            sub.loc[valid, "ShrinkageStatus"] = "shrunk"
            report_rows.append({
                "Facet": str(facet),
                "ValidLevels": k_valid,
                "Tau2": tau2,
                "TauSource": tau_source,
                "MeanShrinkageFactor": float(np.mean(b)),
                "MaxShrinkageFactor": float(np.max(b)),
                "EffectiveDF": float(np.sum(1.0 - b)),
                "Caution": (
                    "Posterior SE treats tau2 as known; raw estimates remain the primary fitted estimates. "
                    "This is post-hoc shrinkage, not a random-effects model."
                ),
            })
        else:
            report_rows.append({
                "Facet": str(facet),
                "ValidLevels": k_valid,
                "Tau2": np.nan,
                "TauSource": "not estimated",
                "MeanShrinkageFactor": np.nan,
                "MaxShrinkageFactor": np.nan,
                "EffectiveDF": np.nan,
                "Caution": f"At least {int(min_levels)} valid levels with positive SE are required.",
            })
        rows.append(sub)
    if not rows:
        return {
            "available": False,
            "reason": "No non-person facet measures with usable SE were available.",
            "measures": pd.DataFrame(),
            "report": pd.DataFrame(report_rows),
        }
    out = pd.concat(rows, ignore_index=True)
    out["ShrinkageDelta"] = pd.to_numeric(out["ShrunkEstimate"], errors="coerce") - pd.to_numeric(out["Estimate"], errors="coerce")
    return {
        "available": True,
        "reason": "Post-hoc empirical-Bayes shrinkage computed for non-person facet measures.",
        "measures": out,
        "report": pd.DataFrame(report_rows),
    }



def format_fixed_width_table(
    df,
    columns,
    formats=None,
    right_align=None,
    max_col_width=16,
    min_col_width=6,
):
    if df is None or df.empty:
        return "No data"
    formats = formats or {}
    if right_align is None:
        right_align = {
            col for col in columns
            if col in df.columns and pd.api.types.is_numeric_dtype(df[col])
        }

    def fmt_val(col, val):
        if pd.isna(val):
            return ""
        fmt = formats.get(col)
        if callable(fmt):
            return fmt(val)
        if isinstance(fmt, str):
            try:
                return fmt.format(val)
            except Exception:
                return str(val)
        return str(val)

    str_cols = {}
    widths = {}
    for col in columns:
        if col not in df.columns:
            str_cols[col] = [""] * len(df)
            widths[col] = max(len(col), min_col_width)
            continue
        vals = [fmt_val(col, v) for v in df[col].tolist()]
        str_cols[col] = vals
        max_len = max([len(col)] + [len(v) for v in vals])
        widths[col] = max(min_col_width, min(max_len, max_col_width))

    def pad(col, text):
        text = text[: widths[col]]
        if col in right_align:
            return text.rjust(widths[col])
        return text.ljust(widths[col])

    header = " ".join([pad(col, col) for col in columns])
    lines = [header]
    for i in range(len(df)):
        row = " ".join([pad(col, str_cols[col][i]) for col in columns])
        lines.append(row)
    return "\n".join(lines)




def get_extreme_levels(obs_df, facet_names, rating_min, rating_max):
    extreme_levels = {}
    for facet in facet_names:
        if facet not in obs_df.columns:
            extreme_levels[facet] = set()
            continue
        stat = (
            obs_df.groupby(facet, observed=False)["Observed"]
            .agg(MinScore="min", MaxScore="max")
            .reset_index()
        )
        extreme = stat[
            ((stat["MinScore"] == rating_min) & (stat["MaxScore"] == rating_min))
            | ((stat["MinScore"] == rating_max) & (stat["MaxScore"] == rating_max))
        ]
        extreme_levels[facet] = set(extreme[facet].astype(str).tolist())
    return extreme_levels


# =============================================================================
# Conditional profile-likelihood inference for an additive bias shift
# -----------------------------------------------------------------------------
# Mathematical contract
#   * Under the regularity conditions for maximum likelihood, the likelihood-
#     ratio statistic ``Lambda = 2 * (ell(b_hat) - ell(b))`` follows a
#     chi-square distribution with one degree of freedom in the limit
#     (Wilks 1938). Inverting that pivotal yields a confidence set
#         { b : 2 * (ell(b_hat) - ell(b)) <= chi^2_{1, 1-alpha} }
#     which is the standard profile-likelihood confidence interval (Cox 1975).
#   * For the additive bias shift b in this code path the profile is taken
#     by holding theta, step thresholds, slopes, and other facet measures
#     fixed at their fit-time values; the remaining one-parameter profile is
#     a scalar in b, so the chi-square pivotal has one degree of freedom.
#   * The endpoints of the confidence interval are roots of
#         f(b) = 2 * (NLL(b) - NLL(b_hat)) - chi^2_{1, 1-alpha} = 0
#     on the negative and positive sides of b_hat, found numerically via
#     bracketed Brent root-finding. When f never crosses zero within
#     ``[-max_abs, max_abs]`` the search returns the boundary with status
#     ``"limited by search range"`` so the caller can communicate that the
#     CI is wider than the bias-search bracket rather than reporting a
#     spurious finite endpoint.
# =============================================================================


def _safe_nll_value(nll, b):
    """Robust wrapper for evaluating a negative log-likelihood closure.

    Catches arbitrary exceptions (degenerate observation slices, log of
    zero from probabilities that collapse, etc.) and returns ``nan`` so
    the profile-likelihood search and the LR statistic can degrade
    gracefully instead of propagating a hard error from a single cell.
    """
    try:
        val = float(nll(b))
    except Exception:
        return float("nan")
    return val if np.isfinite(val) else float("nan")


def _profile_bias_ci(nll, estimate, nll_min, max_abs, level=0.95):
    """Profile-likelihood confidence interval for an additive scalar bias.

    Parameters
    ----------
    nll : callable
        Negative log-likelihood as a function of the bias scalar.
    estimate : float
        The MLE ``b_hat`` for the bias parameter.
    nll_min : float
        ``nll(estimate)`` at the MLE. Pre-evaluated so the helper does
        not duplicate the cost of the optimisation.
    max_abs : float
        Half-width of the search bracket. The CI is computed inside
        ``[-max_abs, max_abs]``.
    level : float, default 0.95
        Nominal CI coverage. Maps to the chi-square cutoff
        ``chi2.ppf(level, df=1)``.

    Returns
    -------
    dict with keys ``lower``, ``upper``, ``level``, ``status``. ``status``
    is one of ``"ok"`` (both endpoints found via interior roots),
    ``"limited by search range"`` (one or both endpoints hit the
    ``max_abs`` boundary because the likelihood never fell far enough
    inside the bracket), or ``"not available"`` (the search did not
    return a finite endpoint).
    """
    if not np.isfinite(estimate) or not np.isfinite(nll_min) or not np.isfinite(max_abs) or max_abs <= 0:
        return {"lower": float("nan"), "upper": float("nan"), "level": float(level), "status": "not available"}
    if not (0.0 < level < 1.0):
        return {"lower": float("nan"), "upper": float("nan"), "level": float(level), "status": "not available"}
    cutoff = float(chi2.ppf(level, df=1))

    def target(b):
        val = _safe_nll_value(nll, b)
        if not np.isfinite(val):
            return float("nan")
        return 2.0 * (val - nll_min) - cutoff

    def root_side(bound):
        if abs(bound - estimate) <= np.sqrt(np.finfo(float).eps):
            return {"value": float(bound), "status": "limited by search range"}
        t_bound = target(bound)
        if not np.isfinite(t_bound):
            return {"value": float("nan"), "status": "not available"}
        if t_bound <= 0:
            # The likelihood never drops by the cutoff inside the bracket,
            # so the CI extends to or beyond ``bound``. Report the bound
            # so the caller can flag the truncation in the status field.
            return {"value": float(bound), "status": "limited by search range"}
        lo = min(bound, estimate)
        hi = max(bound, estimate)
        try:
            sol = root_scalar(target, bracket=(lo, hi), method="brentq", xtol=1e-8)
        except Exception:
            return {"value": float("nan"), "status": "not available"}
        if not getattr(sol, "converged", False) or not np.isfinite(sol.root):
            return {"value": float("nan"), "status": "not available"}
        return {"value": float(sol.root), "status": "ok"}

    lower = root_side(-abs(float(max_abs)))
    upper = root_side(abs(float(max_abs)))
    statuses: list[str] = []
    for s in (lower["status"], upper["status"]):
        if s not in statuses:
            statuses.append(s)
    if statuses == ["ok"]:
        status = "ok"
    else:
        status = "; ".join(statuses)
    return {
        "lower": lower["value"],
        "upper": upper["value"],
        "level": float(level),
        "status": status,
    }


def estimate_bias_interaction(
    res,
    diagnostics,
    facet_a,
    facet_b,
    max_abs=10.0,
    omit_extreme=True,
    max_iter=4,
    tol=1e-3,
):
    # Returns either:
    #   - a full results dict (table, summary, chi-sq, ...) on success
    #   - a dict with a single "_skip_reason" key explaining why
    #     the computation was not possible. This lets the UI surface
    #     the cause instead of showing "not computed" silently.
    if res is None or diagnostics is None:
        return {"_skip_reason": "estimation result or diagnostics missing"}
    obs_df = diagnostics.get("obs")
    if obs_df is None or obs_df.empty:
        return {"_skip_reason": "observation table is empty (no usable rows for bias analysis)"}
    if facet_a == facet_b:
        return {
            "_skip_reason": (
                f"bias analysis requires two distinct facets, not `{facet_a}` × `{facet_a}`"
            )
        }

    facet_names = ["Person"] + res["config"]["facet_names"]
    if facet_a not in facet_names or facet_b not in facet_names:
        missing = [f for f in (facet_a, facet_b) if f not in facet_names]
        return {
            "_skip_reason": (
                f"facet(s) {missing} not in estimated facets {facet_names} "
                "(did you rename a column after running the estimation?)"
            )
        }

    prep = res["prep"]
    config = res["config"]
    params = res["params"]
    idx = build_indices(prep, step_facet=config["step_facet"], slope_facet=config.get("slope_facet"))
    theta_hat = params["theta"] if config["method"] == "JMLE" else res["facets"]["person"]["Estimate"].to_numpy()
    eta_base = compute_eta(idx, params, config, theta_override=theta_hat if theta_hat.size else None)
    score_k = idx["score_k"]
    weight = idx.get("weight")
    step_idx = idx.get("step_idx")
    slope_idx = idx.get("slope_idx")

    if config["model"] == "RSM":
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
        step_cum_mat = None
    else:
        step_cum = None
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])

    if omit_extreme:
        extreme_levels = get_extreme_levels(
            obs_df,
            [facet_a, facet_b],
            prep["rating_min"],
            prep["rating_max"],
        )
    else:
        extreme_levels = {facet_a: set(), facet_b: set()}

    measures = diagnostics.get("measures", pd.DataFrame())
    meas_map = {}
    se_map = {}
    if not measures.empty:
        for row in measures.itertuples():
            meas_map[(row.Facet, str(row.Level))] = float(row.Estimate)
            se_map[(row.Facet, str(row.Level))] = float(row.SE) if pd.notna(row.SE) else np.nan

    level_map = {facet: list(map(str, prep["levels"][facet])) for facet in facet_names if facet in prep["levels"]}
    group_indices = obs_df.groupby([facet_a, facet_b], observed=False).indices
    groups = []
    for (lvl_a, lvl_b), idx_rows in group_indices.items():
        lvl_a_str = str(lvl_a)
        lvl_b_str = str(lvl_b)
        if omit_extreme:
            if lvl_a_str in extreme_levels.get(facet_a, set()) or lvl_b_str in extreme_levels.get(facet_b, set()):
                continue
        idx_rows = np.asarray(idx_rows, dtype=int)
        if idx_rows.size == 0:
            continue
        groups.append({
            "key": (lvl_a_str, lvl_b_str),
            "idx": idx_rows,
        })

    def _slice_cell(idx_rows):
        """Slice the captured per-observation arrays to a single bias cell."""
        eta_sub = eta_base[idx_rows]
        score_k_sub = score_k[idx_rows]
        weight_sub = weight[idx_rows] if weight is not None else None
        step_idx_sub = step_idx[idx_rows] if step_idx is not None else None
        slope_idx_sub = slope_idx[idx_rows] if slope_idx is not None else step_idx_sub
        return eta_sub, score_k_sub, weight_sub, step_idx_sub, slope_idx_sub

    def _make_nll(eta_sub, score_k_sub, weight_sub, step_idx_sub, slope_idx_sub):
        """Per-cell negative log-likelihood closure for an additive bias shift.

        The closure holds the conditional profile fixed: theta, step
        thresholds, slopes, and the other facet estimates enter through
        their fit-time values inside ``eta_sub`` and the captured step
        and slope structures, and only the additive scalar ``b`` varies.
        The same closure is consumed by ``minimize_scalar`` (to find the
        bias MLE), by the LR test (to evaluate the null and the maximised
        log-likelihood), and by the profile-likelihood CI (to invert the
        chi-square pivotal).
        """
        if config["model"] == "RSM":
            def nll(b):
                return -loglik_rsm(eta_sub + b, score_k_sub, step_cum, weight=weight_sub)
        elif config["model"] == "PCM":
            def nll(b):
                return -loglik_pcm(eta_sub + b, score_k_sub, step_cum_mat, step_idx_sub, weight=weight_sub)
        else:  # GPCM
            def nll(b):
                return -loglik_gpcm(
                    eta_sub + b,
                    score_k_sub,
                    step_cum_mat,
                    step_idx_sub,
                    params["slopes"],
                    slope_idx_sub,
                    weight=weight_sub,
                )
        return nll

    def estimate_bias_for_group(idx_rows):
        nll = _make_nll(*_slice_cell(idx_rows))
        try:
            opt = minimize_scalar(nll, bounds=(-max_abs, max_abs), method="bounded")
            if opt.success:
                return float(opt.x)
        except Exception:
            return np.nan
        return np.nan

    def iteration_metrics(bias_map):
        max_resid = 0.0
        max_resid_pct = np.nan
        max_categories = np.nan
        for g in groups:
            idx_rows = g["idx"]
            bias = bias_map.get(g["key"], 0.0)
            eta_sub = eta_base[idx_rows] + (bias if np.isfinite(bias) else 0.0)
            score_k_sub = score_k[idx_rows]
            step_idx_sub = step_idx[idx_rows] if step_idx is not None else None
            slope_idx_sub = slope_idx[idx_rows] if slope_idx is not None else step_idx_sub
            if config["model"] == "RSM":
                probs = category_prob_rsm(eta_sub, step_cum)
            elif config["model"] == "PCM":
                probs = category_prob_pcm(eta_sub, step_cum_mat, step_idx_sub)
            else:
                probs = category_prob_gpcm(
                    eta_sub,
                    step_cum_mat,
                    step_idx_sub,
                    params["slopes"],
                    slope_idx_sub,
                )
            k_vals = np.arange(probs.shape[1])
            expected_k = probs.dot(k_vals)
            expected_score = prep["rating_min"] + expected_k
            obs_score = obs_df.iloc[idx_rows]["Observed"].to_numpy(dtype=float)
            if "Weight" in obs_df.columns:
                w = obs_df.iloc[idx_rows]["Weight"].to_numpy(dtype=float)
                obs_score = obs_score * w
                expected_score = expected_score * w
            resid = obs_score - expected_score
            if resid.size:
                obs_sum = float(np.nansum(obs_score))
                exp_sum = float(np.nansum(expected_score))
                resid_sum = obs_sum - exp_sum
                if abs(resid_sum) >= abs(max_resid):
                    max_resid = resid_sum
                    max_resid_pct = (resid_sum / exp_sum * 100) if exp_sum != 0 else np.nan
                    max_categories = np.nan

        return {
            "max_resid": max_resid,
            "max_resid_pct": max_resid_pct,
            "max_resid_categories": max_categories,
        }

    bias_map = {g["key"]: 0.0 for g in groups}
    iter_rows = []
    for it in range(1, max_iter + 1):
        max_change_abs = 0.0
        max_change_signed = 0.0
        changes = []
        for g in groups:
            key = g["key"]
            bias_hat = estimate_bias_for_group(g["idx"])
            prev = bias_map.get(key, 0.0)
            if np.isfinite(bias_hat) and np.isfinite(prev):
                delta = bias_hat - prev
                if abs(delta) >= max_change_abs:
                    max_change_abs = abs(delta)
                    max_change_signed = delta
                changes.append(abs(delta))
            else:
                changes.append(np.nan)
            bias_map[key] = bias_hat
        resid_info = iteration_metrics(bias_map)
        iter_rows.append({
            "Iteration": it,
            "MaxScoreResidual": resid_info["max_resid"],
            "MaxScoreResidualPct": resid_info["max_resid_pct"],
            "MaxScoreResidualCategories": resid_info["max_resid_categories"],
            "MaxLogitChange": max_change_signed,
            "BiasCells": int(np.sum(np.array(changes, dtype=float) > tol)),
        })
        if max_change_abs < tol:
            break

    rows = []
    seq = 1
    for g in groups:
        lvl_a_str, lvl_b_str = g["key"]
        idx_rows = g["idx"]
        bias_hat = bias_map.get(g["key"], np.nan)
        eta_sub, score_k_sub, weight_sub, step_idx_sub, slope_idx_sub = _slice_cell(idx_rows)

        if config["model"] == "RSM":
            probs = category_prob_rsm(eta_sub + (bias_hat if np.isfinite(bias_hat) else 0.0), step_cum)
        elif config["model"] == "PCM":
            probs = category_prob_pcm(eta_sub + (bias_hat if np.isfinite(bias_hat) else 0.0), step_cum_mat, step_idx_sub)
        else:
            probs = category_prob_gpcm(
                eta_sub + (bias_hat if np.isfinite(bias_hat) else 0.0),
                step_cum_mat,
                step_idx_sub,
                params["slopes"],
                slope_idx_sub,
            )

        k_vals = np.arange(probs.shape[1])
        expected_k = probs.dot(k_vals)
        var_k = probs.dot(k_vals ** 2) - expected_k ** 2
        var_k = np.where(var_k <= 1e-10, np.nan, var_k)
        resid_k = score_k_sub - expected_k
        std_sq = resid_k ** 2 / var_k

        w = weight_sub if weight_sub is not None else np.ones(len(idx_rows))

        # Slope-aware Fisher information for the additive bias shift ``b``.
        # Under GPCM, d log L / d b = sum_i a_i * (X_i - E[X_i | eta_i + b]),
        # so the conditional information for b is
        #     I(b) = sum_i a_i^2 * Var[X_i | eta_i + b] * w_i.
        # The slope^2 factor reduces to 1 for RSM/PCM (a_i = 1), so those
        # branches keep the historical sum(var_k * w) form unchanged.
        # Reference: Muraki (1993) AppliedPsychMeasurement 17(4) Eqs. 7, 16.
        if (
            config["model"] == "GPCM"
            and slope_idx_sub is not None
            and params.get("slopes") is not None
            and len(params["slopes"]) > 0
        ):
            slope_obs_sub = np.asarray(params["slopes"], dtype=float)[slope_idx_sub]
            info_var = np.where(
                np.isfinite(slope_obs_sub) & (slope_obs_sub > 0),
                (slope_obs_sub ** 2) * var_k,
                np.nan,
            )
        else:
            info_var = var_k
        info = np.nansum(info_var * w)
        se = 1 / np.sqrt(info) if np.isfinite(info) and info > 0 else np.nan
        infit = np.nansum(std_sq * var_k * w) / np.nansum(var_k * w) if np.nansum(var_k * w) > 0 else np.nan
        outfit = np.nansum(std_sq * w) / np.nansum(w) if np.nansum(w) > 0 else np.nan

        # Likelihood-ratio test and profile-likelihood confidence interval
        # for the additive bias shift. Only computed for GPCM fits, because
        # the slope-aware information identity above is the part that
        # justifies treating the LR statistic as chi-square with 1 d.f. for
        # this code path. RSM and PCM fits stay in the t-based screening
        # tier already reported by the existing ``t`` / ``d.f.`` / ``Prob.``
        # columns; their LR / profile columns are returned as ``nan`` with
        # an explanatory ``Likelihood Basis`` string so downstream consumers
        # can render an honest "not applicable" cell instead of a silent
        # zero.
        lr_chisq = np.nan
        lr_df = np.nan
        lr_prob = np.nan
        profile_ci = {"lower": np.nan, "upper": np.nan, "level": 0.95, "status": "not available"}
        likelihood_basis = (
            f"not applicable (model is {config['model']}; profile-"
            f"likelihood inference is reported under GPCM only)"
        )
        if config["model"] == "GPCM" and np.isfinite(bias_hat):
            nll_sub = _make_nll(eta_sub, score_k_sub, weight_sub, step_idx_sub, slope_idx_sub)
            nll_hat = _safe_nll_value(nll_sub, bias_hat)
            nll_null = _safe_nll_value(nll_sub, 0.0)
            if np.isfinite(nll_hat) and np.isfinite(nll_null):
                lr_chisq = max(0.0, 2.0 * (nll_null - nll_hat))
                lr_df = 1
                lr_prob = float(chi2.sf(lr_chisq, df=lr_df))
                profile_ci = _profile_bias_ci(nll_sub, bias_hat, nll_hat, max_abs, level=0.95)
                likelihood_basis = (
                    "conditional profile likelihood for one additive GPCM "
                    "bias shift; theta, steps, slopes, and other facet "
                    "estimates held fixed"
                )

        obs_slice = obs_df.iloc[idx_rows]
        w_obs = obs_slice["Weight"].to_numpy(dtype=float) if "Weight" in obs_slice.columns else np.ones(len(obs_slice))
        obs_score = float(np.nansum(obs_slice["Observed"].to_numpy(dtype=float) * w_obs))
        exp_score = float(np.nansum(obs_slice["Expected"].to_numpy(dtype=float) * w_obs))
        obs_count = float(np.nansum(w_obs))
        obs_exp_avg = (obs_score - exp_score) / obs_count if obs_count > 0 else np.nan

        n_obs = int(len(obs_slice))
        df_t = max(n_obs - 1, 0)
        t_val = bias_hat / se if np.isfinite(bias_hat) and np.isfinite(se) and se > 0 else np.nan
        p_val = 2 * t_dist.cdf(-abs(t_val), df=df_t) if np.isfinite(t_val) and df_t > 0 else np.nan

        rows.append({
            "Sq": seq,
            "Observd Score": obs_score,
            "Expctd Score": exp_score,
            "Observd Count": obs_count,
            "Obs-Exp Average": obs_exp_avg,
            "Bias Size": bias_hat,
            "S.E.": se,
            "t": t_val,
            "d.f.": df_t,
            "Prob.": p_val,
            "LR ChiSq": lr_chisq,
            "LR d.f.": lr_df,
            "LR Prob.": lr_prob,
            "Profile CI Lower": profile_ci["lower"],
            "Profile CI Upper": profile_ci["upper"],
            "Profile CI Level": profile_ci["level"],
            "Profile CI Status": profile_ci["status"],
            "Likelihood Basis": likelihood_basis,
            "SE Basis": (
                "conditional information for one additive bias shift at fitted "
                "theta, facet, step, and slope values; main-effect uncertainty "
                "is not propagated"
            ),
            "Multiplicity Basis": (
                "cellwise screening statistics; use DFF table Holm/BH p-values, "
                "sparse-cell flags, and substantive design review before claims"
            ),
            "InferenceTier": "screening",
            "Infit": infit,
            "Outfit": outfit,
            "ObsN": n_obs,
            "FacetA": facet_a,
            "FacetA_Level": lvl_a_str,
            "FacetA_Index": level_map.get(facet_a, []).index(lvl_a_str) + 1 if lvl_a_str in level_map.get(facet_a, []) else np.nan,
            "FacetA_Measure": meas_map.get((facet_a, lvl_a_str), np.nan),
            "FacetA_SE": se_map.get((facet_a, lvl_a_str), np.nan),
            "FacetB": facet_b,
            "FacetB_Level": lvl_b_str,
            "FacetB_Index": level_map.get(facet_b, []).index(lvl_b_str) + 1 if lvl_b_str in level_map.get(facet_b, []) else np.nan,
            "FacetB_Measure": meas_map.get((facet_b, lvl_b_str), np.nan),
            "FacetB_SE": se_map.get((facet_b, lvl_b_str), np.nan),
        })
        seq += 1

    bias_tbl = pd.DataFrame(rows)
    if bias_tbl.empty:
        return {
            "_skip_reason": (
                f"no valid `{facet_a}` × `{facet_b}` cells after filtering "
                "(all-extreme levels were removed and no valid observations remain)"
            )
        }

    numeric_cols = ["Observd Score", "Expctd Score", "Observd Count", "Obs-Exp Average", "Bias Size", "S.E."]
    mean_row = bias_tbl[numeric_cols].mean(numeric_only=True)
    sd_pop_row = bias_tbl[numeric_cols].std(ddof=0, numeric_only=True)
    sd_sample_row = bias_tbl[numeric_cols].std(ddof=1, numeric_only=True)
    summary_tbl = pd.DataFrame(
        [mean_row, sd_pop_row, sd_sample_row],
        index=["Mean (Count: {})".format(len(bias_tbl)), "S.D. (Population)", "S.D. (Sample)"],
    ).reset_index().rename(columns={"index": "Statistic"})

    se_bias = bias_tbl["S.E."].to_numpy()
    bias_vals = bias_tbl["Bias Size"].to_numpy()
    w_chi = np.where(np.isfinite(se_bias) & (se_bias > 0), 1 / (se_bias ** 2), np.nan)
    ok = np.isfinite(w_chi) & np.isfinite(bias_vals)
    fixed_chi = (
        np.sum(w_chi[ok] * bias_vals[ok] ** 2) - (np.sum(w_chi[ok] * bias_vals[ok]) ** 2) / np.sum(w_chi[ok])
        if np.sum(ok) >= 2
        else np.nan
    )
    fixed_df = max(len(bias_tbl) - 1, 0)
    fixed_prob = 1 - chi2.cdf(fixed_chi, df=fixed_df) if np.isfinite(fixed_chi) and fixed_df > 0 else np.nan
    chi_tbl = pd.DataFrame({
        "FixedChiSq": [fixed_chi],
        "FixedDF": [fixed_df],
        "FixedProb": [fixed_prob],
    })

    return {
        "facet_a": facet_a,
        "facet_b": facet_b,
        "table": bias_tbl,
        "summary": summary_tbl,
        "chi_sq": chi_tbl,
        "iteration": pd.DataFrame(iter_rows),
    }


def calc_bias_pairwise(bias_tbl, target_facet, context_facet):
    if bias_tbl is None or bias_tbl.empty:
        return pd.DataFrame()

    use_a = bias_tbl["FacetA"].iloc[0] == target_facet
    use_b = bias_tbl["FacetB"].iloc[0] == target_facet
    if not (use_a or use_b):
        return pd.DataFrame()

    if use_a:
        target_prefix = "FacetA"
        context_prefix = "FacetB"
    else:
        target_prefix = "FacetB"
        context_prefix = "FacetA"

    sub = bias_tbl.copy()
    sub = sub[sub[f"{context_prefix}"].isin([context_facet])]
    if sub.empty:
        sub = bias_tbl.copy()

    rows = []
    for tgt_level, group_df in sub.groupby(f"{target_prefix}_Level"):
        contexts = group_df[f"{context_prefix}_Level"].unique().tolist()
        if len(contexts) < 2:
            continue
        ctx_pairs = list(combinations(contexts, 2))
        for c1, c2 in ctx_pairs:
            r1 = group_df[group_df[f"{context_prefix}_Level"] == c1].iloc[0]
            r2 = group_df[group_df[f"{context_prefix}_Level"] == c2].iloc[0]

            tgt_measure = float(r1[f"{target_prefix}_Measure"]) if np.isfinite(r1[f"{target_prefix}_Measure"]) else np.nan
            tgt_se = float(r1[f"{target_prefix}_SE"]) if np.isfinite(r1[f"{target_prefix}_SE"]) else np.nan
            tgt_index = r1.get(f"{target_prefix}_Index", np.nan)

            bias1 = float(r1["Bias Size"]) if np.isfinite(r1["Bias Size"]) else np.nan
            bias2 = float(r2["Bias Size"]) if np.isfinite(r2["Bias Size"]) else np.nan
            bias_se1 = float(r1["S.E."]) if np.isfinite(r1["S.E."]) else np.nan
            bias_se2 = float(r2["S.E."]) if np.isfinite(r2["S.E."]) else np.nan

            local1 = tgt_measure + bias1 if np.isfinite(tgt_measure) and np.isfinite(bias1) else np.nan
            local2 = tgt_measure + bias2 if np.isfinite(tgt_measure) and np.isfinite(bias2) else np.nan
            se1 = np.sqrt(tgt_se ** 2 + bias_se1 ** 2) if np.isfinite(tgt_se) and np.isfinite(bias_se1) else np.nan
            se2 = np.sqrt(tgt_se ** 2 + bias_se2 ** 2) if np.isfinite(tgt_se) and np.isfinite(bias_se2) else np.nan

            contrast = local1 - local2 if np.isfinite(local1) and np.isfinite(local2) else np.nan
            se_contrast = np.sqrt(se1 ** 2 + se2 ** 2) if np.isfinite(se1) and np.isfinite(se2) else np.nan
            t_val = contrast / se_contrast if np.isfinite(contrast) and np.isfinite(se_contrast) and se_contrast > 0 else np.nan

            n1 = int(r1["ObsN"]) if np.isfinite(r1["ObsN"]) else 0
            n2 = int(r2["ObsN"]) if np.isfinite(r2["ObsN"]) else 0
            df_num = (se1 ** 2 + se2 ** 2) ** 2
            df_den = 0.0
            if n1 > 1 and np.isfinite(se1):
                df_den += (se1 ** 4) / (n1 - 1)
            if n2 > 1 and np.isfinite(se2):
                df_den += (se2 ** 4) / (n2 - 1)
            df_t_val = df_num / df_den if df_den > 0 else np.nan
            p_val = 2 * t_dist.cdf(-abs(t_val), df=df_t_val) if np.isfinite(t_val) and np.isfinite(df_t_val) and df_t_val > 0 else np.nan

            rows.append({
                "Target": tgt_level,
                "Target N": tgt_index,
                "Target Measure": tgt_measure,
                "Target S.E.": tgt_se,
                "Context1": c1,
                "Context1 N": r1.get(f"{context_prefix}_Index", np.nan),
                "Local Measure1": local1,
                "SE1": se1,
                "Obs-Exp Avg1": float(r1["Obs-Exp Average"]),
                "Count1": float(r1["Observd Count"]),
                "Context2": c2,
                "Context2 N": r2.get(f"{context_prefix}_Index", np.nan),
                "Local Measure2": local2,
                "SE2": se2,
                "Obs-Exp Avg2": float(r2["Obs-Exp Average"]),
                "Count2": float(r2["Observd Count"]),
                "Contrast": contrast,
                "SE": se_contrast,
                "t": t_val,
                "d.f.": df_t_val,
                "Prob.": p_val,
            })

    return pd.DataFrame(rows)


def adjust_p_values(p_values, method: str = "holm") -> np.ndarray:
    """Multiplicity adjustment for bias/DFF screening without extra dependencies."""
    p = np.asarray(p_values, dtype=float)
    out = np.full(p.shape, np.nan, dtype=float)
    ok = np.isfinite(p)
    if not np.any(ok):
        return out
    vals = np.clip(p[ok], 0.0, 1.0)
    order = np.argsort(vals)
    sorted_p = vals[order]
    m = len(sorted_p)
    method_l = str(method).lower()
    if method_l in {"bh", "fdr", "benjamini-hochberg", "benjamini_hochberg"}:
        ranks = np.arange(1, m + 1, dtype=float)
        adjusted_sorted = sorted_p * m / ranks
        adjusted_sorted = np.minimum.accumulate(adjusted_sorted[::-1])[::-1]
    elif method_l in {"holm", "holm-bonferroni", "holm_bonferroni"}:
        adjusted_sorted = sorted_p * (m - np.arange(m, dtype=float))
        adjusted_sorted = np.maximum.accumulate(adjusted_sorted)
    else:
        adjusted_sorted = sorted_p
    adjusted_sorted = np.clip(adjusted_sorted, 0.0, 1.0)
    adjusted = np.empty(m, dtype=float)
    adjusted[order] = adjusted_sorted
    out[np.where(ok)[0]] = adjusted
    return out


def build_dff_bias_screening_table(
    bias_results: dict | pd.DataFrame | None,
    *,
    alpha: float = 0.05,
    min_n: int = 5,
    practical_logit: float = 0.50,
) -> pd.DataFrame:
    """Create a DFF/bias screening table with multiplicity and sparse-cell flags."""
    if isinstance(bias_results, pd.DataFrame):
        tbl = bias_results.copy()
    elif isinstance(bias_results, dict):
        tbl = bias_results.get("table", pd.DataFrame()).copy()
    else:
        tbl = pd.DataFrame()
    if tbl.empty or "Bias Size" not in tbl.columns:
        return pd.DataFrame(columns=[
            "FacetPair", "FacetA", "FacetA_Level", "FacetB", "FacetB_Level",
            "ObsN", "BiasSize", "SE", "t", "p", "p_holm", "p_bh",
            "AbsBias", "Direction", "SparseCell", "EvidenceLevel", "Flag",
            "ClaimStatus", "LRChiSq", "LRProb", "ProfileCILower",
            "ProfileCIUpper", "ProfileCIStatus", "LikelihoodBasis",
            "SEBasis", "InferenceTier", "MultiplicityBasis",
            "MultiplicityFamily", "ReportingCaution",
            "Interpretation", "NextAction",
        ])
    tbl = tbl.reset_index(drop=True)

    def col_series(name: str, default=np.nan) -> pd.Series:
        if name in tbl.columns:
            return tbl[name]
        return pd.Series([default] * len(tbl))

    p_vals = pd.to_numeric(col_series("Prob."), errors="coerce").to_numpy(dtype=float)
    bias_vals = pd.to_numeric(col_series("Bias Size"), errors="coerce")
    se_vals = pd.to_numeric(col_series("S.E."), errors="coerce")
    t_vals = pd.to_numeric(col_series("t"), errors="coerce")
    obs_source = tbl["ObsN"] if "ObsN" in tbl.columns else col_series("Observd Count")
    obs_n = pd.to_numeric(obs_source, errors="coerce")
    out = pd.DataFrame({
        "FacetPair": col_series("FacetA", "FacetA").astype(str)
        + " x "
        + col_series("FacetB", "FacetB").astype(str),
        "FacetA": col_series("FacetA", "").astype(str),
        "FacetA_Level": col_series("FacetA_Level", "").astype(str),
        "FacetB": col_series("FacetB", "").astype(str),
        "FacetB_Level": col_series("FacetB_Level", "").astype(str),
        "ObsN": obs_n,
        "BiasSize": bias_vals,
        "SE": se_vals,
        "t": t_vals,
        "p": p_vals,
        "p_holm": adjust_p_values(p_vals, "holm"),
        "p_bh": adjust_p_values(p_vals, "bh"),
    })
    out["AbsBias"] = out["BiasSize"].abs()
    out["Direction"] = np.select(
        [out["BiasSize"] > 0, out["BiasSize"] < 0],
        ["Observed higher than expected", "Observed lower than expected"],
        default="No signed departure",
    )

    sparse = pd.to_numeric(out["ObsN"], errors="coerce").fillna(0) < int(min_n)
    stat_holm = pd.to_numeric(out["p_holm"], errors="coerce") < float(alpha)
    stat_bh_t = (
        (pd.to_numeric(out["p_bh"], errors="coerce") < float(alpha))
        & (pd.to_numeric(out["t"], errors="coerce").abs() >= 2.0)
    )
    practical = pd.to_numeric(out["AbsBias"], errors="coerce") >= float(practical_logit)
    out["SparseCell"] = sparse.astype(bool)
    levels = np.select(
        [
            sparse,
            stat_holm & practical,
            stat_holm | stat_bh_t,
            practical,
        ],
        [
            "Sparse cell",
            "Strong review",
            "Statistical review",
            "Practical review",
        ],
        default="No flag",
    )
    out["EvidenceLevel"] = levels
    out["Flag"] = out["EvidenceLevel"].ne("No flag")
    out["ClaimStatus"] = np.select(
        [
            out["EvidenceLevel"].eq("Sparse cell"),
            out["Flag"].astype(bool),
        ],
        [
            "Do not claim from this cell alone",
            "Report with caveat",
        ],
        default="No computed local-bias flag",
    )
    out["LRChiSq"] = pd.to_numeric(col_series("LR ChiSq"), errors="coerce")
    out["LRProb"] = pd.to_numeric(col_series("LR Prob."), errors="coerce")
    out["ProfileCILower"] = pd.to_numeric(col_series("Profile CI Lower"), errors="coerce")
    out["ProfileCIUpper"] = pd.to_numeric(col_series("Profile CI Upper"), errors="coerce")
    out["ProfileCIStatus"] = col_series("Profile CI Status", "").astype(str)
    out["LikelihoodBasis"] = col_series("Likelihood Basis", "").astype(str)
    out["SEBasis"] = col_series("SE Basis", "").astype(str)
    out["InferenceTier"] = col_series("InferenceTier", "").astype(str)
    out["MultiplicityBasis"] = col_series("Multiplicity Basis", "").astype(str)
    out["MultiplicityFamily"] = (
        out["FacetPair"].astype(str)
        + f" cell screen; alpha={float(alpha):.3g}, min_n={int(min_n)}, "
        + f"practical_logit={float(practical_logit):.3g}"
    )
    out["ReportingCaution"] = np.select(
        [
            out["EvidenceLevel"].eq("Sparse cell"),
            out["Flag"].astype(bool),
        ],
        [
            "Sparse cells are design evidence, not stable bias estimates.",
            "Treat as a conditional screening flag; corroborate with design, fit, and substantive evidence.",
        ],
        default=(
            "No flag under this conditional screen; this is not evidence that "
            "bias is absent outside the tested cell family."
        ),
    )
    out["Interpretation"] = np.select(
        [
            out["EvidenceLevel"].eq("Sparse cell"),
            out["EvidenceLevel"].eq("Strong review"),
            out["EvidenceLevel"].eq("Statistical review"),
            out["EvidenceLevel"].eq("Practical review"),
        ],
        [
            "Too few observations for a stable DFF/bias claim.",
            "Cell is statistically flagged after Holm correction and practically large.",
            "Cell is statistically flagged after multiplicity screening.",
            "Cell is practically large but not multiplicity-adjusted significant.",
        ],
        default="No clear DFF/bias signal under the current screening thresholds.",
    )
    out["NextAction"] = np.select(
        [
            out["EvidenceLevel"].eq("Sparse cell"),
            out["EvidenceLevel"].eq("Strong review"),
            out["EvidenceLevel"].eq("Statistical review"),
            out["EvidenceLevel"].eq("Practical review"),
        ],
        [
            "Add observations or combine substantively defensible levels before interpreting.",
            "Review scoring rubrics, rater notes, content match, and rerun sensitivity checks.",
            "Inspect heatmap pattern and corroborate with fit, residual, and substantive evidence.",
            "Decide whether this logit departure is substantively meaningful for the use case.",
        ],
        default="No special action beyond routine review.",
    )
    return out.sort_values(["Flag", "AbsBias"], ascending=[False, False]).reset_index(drop=True)


def summarize_dff_bias_screening(dff_tbl: pd.DataFrame) -> pd.DataFrame:
    """Compact counts for the DFF/bias screening panel and exports."""
    if dff_tbl is None or dff_tbl.empty:
        return pd.DataFrame(columns=["Metric", "Value", "Interpretation"])
    levels = dff_tbl["EvidenceLevel"].astype(str) if "EvidenceLevel" in dff_tbl.columns else pd.Series(dtype=str)
    abs_bias = pd.to_numeric(dff_tbl.get("AbsBias", pd.Series(dtype=float)), errors="coerce")
    p_holm = pd.to_numeric(dff_tbl.get("p_holm", pd.Series(dtype=float)), errors="coerce")
    p_bh = pd.to_numeric(dff_tbl.get("p_bh", pd.Series(dtype=float)), errors="coerce")
    profile_status = dff_tbl["ProfileCIStatus"].astype(str) if "ProfileCIStatus" in dff_tbl.columns else pd.Series(dtype=str)
    flagged = dff_tbl[dff_tbl.get("Flag", pd.Series([False] * len(dff_tbl))).astype(bool)]
    strongest = "none"
    if len(flagged) and "FacetA_Level" in flagged.columns and "FacetB_Level" in flagged.columns:
        row = flagged.iloc[0]
        strongest = (
            f"{row.get('FacetA', 'FacetA')}={row.get('FacetA_Level', '')} x "
            f"{row.get('FacetB', 'FacetB')}={row.get('FacetB_Level', '')}"
        )
    return pd.DataFrame([
        {"Metric": "Cells screened", "Value": int(len(dff_tbl)), "Interpretation": "Facet-level combinations in this pair."},
        {"Metric": "Flagged cells", "Value": int(len(flagged)), "Interpretation": "Sparse, statistical, or practical review prompts."},
        {"Metric": "Strong review", "Value": int((levels == "Strong review").sum()), "Interpretation": "Holm-adjusted and practically large cells."},
        {"Metric": "Holm p < .05", "Value": int((p_holm < 0.05).sum()), "Interpretation": "Familywise-error adjusted statistical flags."},
        {"Metric": "BH q < .05", "Value": int((p_bh < 0.05).sum()), "Interpretation": "False-discovery-rate adjusted statistical flags."},
        {"Metric": "Sparse cells", "Value": int((levels == "Sparse cell").sum()), "Interpretation": "Cells below the minimum observation threshold."},
        {"Metric": "Max |bias|", "Value": float(abs_bias.max()) if len(abs_bias.dropna()) else np.nan, "Interpretation": "Largest absolute logit departure."},
        {"Metric": "Profile CI ok", "Value": int((profile_status == "ok").sum()), "Interpretation": "GPCM cells with finite conditional profile-likelihood intervals."},
        {"Metric": "Inference tier", "Value": "conditional screening", "Interpretation": "Other fitted parameters are held fixed; global uncertainty is not propagated."},
        {"Metric": "Strongest flagged cell", "Value": strongest, "Interpretation": "First flagged row after sorting by |bias|."},
    ])


def _iter_bias_result_bundles(
    bias_results: dict | pd.DataFrame | None,
) -> list[tuple[str, dict]]:
    """Normalize selected-pair and all-pair bias containers."""
    if isinstance(bias_results, pd.DataFrame):
        return [("Bias table", {"table": bias_results})]
    if not isinstance(bias_results, dict) or not bias_results:
        return []
    if any(k in bias_results for k in ("table", "bias_tbl", "_skip_reason")):
        label = "Bias table"
        facet_a = bias_results.get("facet_a")
        facet_b = bias_results.get("facet_b")
        if facet_a or facet_b:
            label = f"{facet_a or 'FacetA'} x {facet_b or 'FacetB'}"
        return [(label, bias_results)]
    out: list[tuple[str, dict]] = []
    for pair_label, bundle in bias_results.items():
        if isinstance(bundle, pd.DataFrame):
            out.append((str(pair_label), {"table": bundle}))
        elif isinstance(bundle, dict):
            out.append((str(pair_label), bundle))
    return out


def _common_scale_bias_status(result: dict | None, diagnostics: dict | None) -> tuple[str, int | None]:
    """Evaluate whether the observed design is connected for bias claims."""
    if not isinstance(diagnostics, dict):
        return "Not evaluated: diagnostics are unavailable.", None
    obs = diagnostics.get("obs", pd.DataFrame())
    if not isinstance(obs, pd.DataFrame) or obs.empty:
        return "Not evaluated: observation-level diagnostics are unavailable.", None
    config = result.get("config", {}) if isinstance(result, dict) else {}
    configured = list(config.get("facet_names", []) or [])
    facet_cols = ["Person"] + configured if "Person" in obs.columns else configured
    facet_cols = [c for c in facet_cols if c in obs.columns]
    if len(facet_cols) < 2:
        return "Not evaluated: fewer than two observed facet columns are available.", None
    try:
        subsets = calc_subsets(obs, facet_cols)
        summary = subsets.get("summary", pd.DataFrame()) if isinstance(subsets, dict) else pd.DataFrame()
    except Exception as exc:
        return f"Not evaluated: connectedness check failed ({exc}).", None
    if not isinstance(summary, pd.DataFrame) or summary.empty:
        return "Not evaluated: connectedness summary is empty.", None
    n_subsets = int(summary["Subset"].nunique()) if "Subset" in summary.columns else int(len(summary))
    if n_subsets > 1:
        return (
            f"Review: observed design has {n_subsets} disconnected subset(s); "
            "bias cells across subsets are not on one common scale.",
            n_subsets,
        )
    return (
        "Ready: observed design is connected for the fitted Person + facet graph.",
        1,
    )


def build_bias_inference_audit(
    bias_results: dict | pd.DataFrame | None,
    result: dict | None = None,
    diagnostics: dict | None = None,
    *,
    alpha: float = 0.05,
    min_n: int = 5,
    practical_logit: float = 0.50,
) -> pd.DataFrame:
    """Pair-level guardrails for conditional bias / local-interaction claims."""
    columns = [
        "FacetPair", "Status", "ClaimStatus", "CellsScreened", "FlaggedCells",
        "StrongReviewCells", "SparseCells", "HolmSignificantCells",
        "BHSignificantCells", "PracticalCells", "MaxAbsBias",
        "CommonScaleSubsets", "CommonScaleStatus", "InferenceScope",
        "MultiplicityScope", "ProfileCIStatusSummary", "InferenceTierSummary",
        "EvidenceSummary", "RecommendedAction",
    ]
    bundles = _iter_bias_result_bundles(bias_results)
    if not bundles:
        return pd.DataFrame(columns=columns)

    common_status, common_subsets = _common_scale_bias_status(result, diagnostics)
    disconnected = str(common_status).startswith("Review:")
    rows: list[dict[str, object]] = []
    inference_scope = (
        "Conditional screening: fitted theta, facet, step, slope, and other "
        "main-effect values are held fixed; global model uncertainty is not propagated."
    )
    multiplicity_scope = (
        "Holm and BH adjustments are computed within each exported facet-pair "
        "cell family; flags are review prompts, not confirmatory proof."
    )
    for pair_label, bundle in bundles:
        if isinstance(bundle, dict) and "_skip_reason" in bundle and "table" not in bundle:
            reason = str(bundle.get("_skip_reason", "Bias screen was skipped."))
            rows.append({
                "FacetPair": pair_label,
                "Status": "Missing",
                "ClaimStatus": "Do not claim",
                "CellsScreened": 0,
                "FlaggedCells": 0,
                "StrongReviewCells": 0,
                "SparseCells": 0,
                "HolmSignificantCells": 0,
                "BHSignificantCells": 0,
                "PracticalCells": 0,
                "MaxAbsBias": np.nan,
                "CommonScaleSubsets": common_subsets,
                "CommonScaleStatus": common_status,
                "InferenceScope": inference_scope,
                "MultiplicityScope": multiplicity_scope,
                "ProfileCIStatusSummary": "",
                "InferenceTierSummary": "",
                "EvidenceSummary": reason,
                "RecommendedAction": "Run a selected-pair or all-pair bias screen before writing no-bias claims.",
            })
            continue

        dff_tbl = build_dff_bias_screening_table(
            bundle,
            alpha=alpha,
            min_n=min_n,
            practical_logit=practical_logit,
        )
        if dff_tbl.empty:
            rows.append({
                "FacetPair": pair_label,
                "Status": "Missing",
                "ClaimStatus": "Do not claim",
                "CellsScreened": 0,
                "FlaggedCells": 0,
                "StrongReviewCells": 0,
                "SparseCells": 0,
                "HolmSignificantCells": 0,
                "BHSignificantCells": 0,
                "PracticalCells": 0,
                "MaxAbsBias": np.nan,
                "CommonScaleSubsets": common_subsets,
                "CommonScaleStatus": common_status,
                "InferenceScope": inference_scope,
                "MultiplicityScope": multiplicity_scope,
                "ProfileCIStatusSummary": "",
                "InferenceTierSummary": "",
                "EvidenceSummary": "No interpretable bias cells were exported.",
                "RecommendedAction": "Check sparse/extreme data and rerun the bias screen if local interaction is a reporting target.",
            })
            continue

        levels = dff_tbl["EvidenceLevel"].astype(str) if "EvidenceLevel" in dff_tbl.columns else pd.Series(dtype=str)
        flags = dff_tbl["Flag"].astype(bool) if "Flag" in dff_tbl.columns else pd.Series([False] * len(dff_tbl))
        p_holm = pd.to_numeric(dff_tbl.get("p_holm", pd.Series(dtype=float)), errors="coerce")
        p_bh = pd.to_numeric(dff_tbl.get("p_bh", pd.Series(dtype=float)), errors="coerce")
        abs_bias = pd.to_numeric(dff_tbl.get("AbsBias", pd.Series(dtype=float)), errors="coerce")
        profile_status = (
            dff_tbl["ProfileCIStatus"].astype(str)
            if "ProfileCIStatus" in dff_tbl.columns else pd.Series(dtype=str)
        )
        tiers = (
            dff_tbl["InferenceTier"].astype(str)
            if "InferenceTier" in dff_tbl.columns else pd.Series(dtype=str)
        )
        flagged_n = int(flags.sum())
        strong_n = int((levels == "Strong review").sum())
        sparse_n = int((levels == "Sparse cell").sum())
        holm_n = int((p_holm < float(alpha)).sum())
        bh_n = int((p_bh < float(alpha)).sum())
        practical_n = int((abs_bias >= float(practical_logit)).sum())
        max_abs = float(abs_bias.max()) if len(abs_bias.dropna()) else np.nan
        profile_summary = (
            dict(profile_status[profile_status.ne("")].value_counts())
            if len(profile_status) else {}
        )
        tier_summary = dict(tiers[tiers.ne("")].value_counts()) if len(tiers) else {}

        if disconnected or sparse_n or flagged_n:
            status = "Review"
            claim_status = "Report with caveat"
        else:
            status = "Ready"
            claim_status = "Ready"

        if disconnected:
            action = "Resolve linking/connectivity or restrict bias wording to each connected subset."
        elif sparse_n:
            action = "Treat sparse cells as design prompts; add observations or combine defensible levels before strong claims."
        elif strong_n:
            action = "Review scoring rubrics, rater notes, content match, fit, and sensitivity before reporting the flagged cells."
        elif flagged_n:
            action = "Use flagged cells as conditional screening evidence and corroborate with substantive design review."
        else:
            action = "Report only that no cell was flagged in the computed conditional screen; avoid broad no-bias claims."

        rows.append({
            "FacetPair": pair_label,
            "Status": status,
            "ClaimStatus": claim_status,
            "CellsScreened": int(len(dff_tbl)),
            "FlaggedCells": flagged_n,
            "StrongReviewCells": strong_n,
            "SparseCells": sparse_n,
            "HolmSignificantCells": holm_n,
            "BHSignificantCells": bh_n,
            "PracticalCells": practical_n,
            "MaxAbsBias": max_abs,
            "CommonScaleSubsets": common_subsets,
            "CommonScaleStatus": common_status,
            "InferenceScope": inference_scope,
            "MultiplicityScope": multiplicity_scope,
            "ProfileCIStatusSummary": profile_summary,
            "InferenceTierSummary": tier_summary,
            "EvidenceSummary": (
                f"{flagged_n} flagged of {len(dff_tbl)} screened cell(s); "
                f"{strong_n} strong-review, {sparse_n} sparse, "
                f"{holm_n} Holm-significant, {bh_n} BH-significant."
            ),
            "RecommendedAction": action,
        })
    return pd.DataFrame(rows, columns=columns)


# ============================================================================
# Classical polytomous DIF (Differential Item Functioning) — screening
# ============================================================================
# Observed-score DIF for an EXTERNAL person group (e.g. L1, gender) — a
# complement to the model-based facet bias/interaction screen above. Two
# standard polytomous methods on the rater-averaged person x item scores:
#   * polytomous Mantel (1963) chi-square + ETS standardized mean difference;
#   * Zumbo (1999) ordinal (cumulative-logit) logistic-regression DIF, fit by
#     maximum likelihood with scipy (no statsmodels), giving nested uniform /
#     non-uniform / total likelihood-ratio tests and a Nagelkerke Delta-R^2.
# This is SCREENING evidence, not a fairness / invariance / operational claim.

_DIF_SMD_B = 0.17   # ETS standardized-SMD A/B boundary
_DIF_SMD_C = 0.25   # ETS standardized-SMD B/C boundary
_DIF_R2_B = 0.035   # Jodoin-Gierl Nagelkerke Delta-R^2 A/B boundary
_DIF_R2_C = 0.070   # Jodoin-Gierl Nagelkerke Delta-R^2 B/C boundary
_DIF_SIBTEST_B = 0.059   # Roussos-Stout SIBTEST beta (unit-metric) A/B boundary
_DIF_SIBTEST_C = 0.088   # Roussos-Stout SIBTEST beta (unit-metric) B/C boundary


def _dif_smd_class(smd_std) -> str:
    a = abs(float(smd_std)) if smd_std is not None and np.isfinite(smd_std) else np.nan
    if not np.isfinite(a):
        return "n/a"
    if a < _DIF_SMD_B:
        return "negligible (A)"
    if a < _DIF_SMD_C:
        return "moderate (B)"
    return "large (C)"


def _dif_r2_class(dr2) -> str:
    v = float(dr2) if dr2 is not None and np.isfinite(dr2) else np.nan
    if not np.isfinite(v):
        return "n/a"
    if v < _DIF_R2_B:
        return "negligible (A)"
    if v < _DIF_R2_C:
        return "moderate (B)"
    return "large (C)"


def _sibtest_eff_class(beta, score_range) -> str:
    # ETS/Roussos-Stout beta bands are defined on a 0-1 (proportion) metric;
    # divide the polytomous beta by the score range so the band is invariant to
    # the item's number of categories.
    rw = float(score_range) if score_range else 1.0
    b = abs(float(beta)) / rw if (beta is not None and np.isfinite(beta) and rw > 0) else np.nan
    if not np.isfinite(b):
        return "n/a"
    if b < _DIF_SIBTEST_B:
        return "negligible (A)"
    if b < _DIF_SIBTEST_C:
        return "moderate (B)"
    return "large (C)"


def _dif_strata(matching, n_strata: int) -> np.ndarray:
    """Stratify the matching score: integer-rounded levels if few, else quantile bins."""
    m = np.asarray(matching, dtype=float)
    rounded = np.round(m)
    distinct = np.unique(rounded[np.isfinite(rounded)])
    if distinct.size <= max(int(n_strata), 8):
        return rounded
    try:
        return pd.qcut(m, int(n_strata), labels=False, duplicates="drop").to_numpy(dtype=float)
    except Exception:
        return rounded


def _mantel_polytomous(y, focal_mask, strata, min_stratum_n: int = 2):
    """Polytomous Mantel (1963) chi-square + ETS standardized mean difference.

    Operates on ordered (here continuous rater-mean) item scores directly.
    Returns (chi2, p, smd, smd_std, smd_class, direction, n_strata_used).
    """
    y = np.asarray(y, dtype=float)
    focal = np.asarray(focal_mask, dtype=bool)
    strata = np.asarray(strata)
    num = den = smd_num = smd_den = 0.0
    n_used = 0
    for s in pd.unique(strata):
        if not (np.isscalar(s) and np.isfinite(s)):
            continue
        idx = (strata == s) & np.isfinite(y)
        n_k = int(idx.sum())
        if n_k <= 1:
            continue
        f_k = idx & focal
        n_fk = int(f_k.sum())
        n_rk = n_k - n_fk
        if n_fk == 0 or n_rk == 0 or n_k < int(min_stratum_n):
            continue
        s_k = float(y[idx].sum())
        s2_k = float((y[idx] ** 2).sum())
        F_k = float(y[f_k].sum())
        e_fk = n_fk * s_k / n_k
        var_fk = (n_fk * n_rk) * (n_k * s2_k - s_k ** 2) / (n_k ** 2 * (n_k - 1))
        num += (F_k - e_fk)
        den += var_fk
        smd_num += n_k * (F_k / n_fk - (s_k - F_k) / n_rk)
        smd_den += n_k
        n_used += 1
    if n_used == 0 or den <= 0:
        return (np.nan, np.nan, np.nan, np.nan, "n/a", "n/a", n_used)
    chi2_stat = (num ** 2) / den
    p = float(chi2.sf(chi2_stat, 1))
    smd = smd_num / smd_den if smd_den > 0 else np.nan
    y_ok = y[np.isfinite(y)]
    sd_y = float(np.std(y_ok, ddof=1)) if y_ok.size > 1 else np.nan
    smd_std = smd / sd_y if (np.isfinite(smd) and np.isfinite(sd_y) and sd_y > 0) else np.nan
    direction = (
        "favors focal" if (np.isfinite(smd) and smd > 0)
        else "favors reference" if (np.isfinite(smd) and smd < 0)
        else "no signed difference"
    )
    return (float(chi2_stat), p, float(smd) if np.isfinite(smd) else np.nan,
            float(smd_std) if np.isfinite(smd_std) else np.nan,
            _dif_smd_class(smd_std), direction, n_used)


def _poly_sibtest(y, M, g, strata, *, score_range, min_stratum_n: int = 2):
    """Polytomous uniform SIBTEST (Shealy-Stout 1993; Chang-Mazzeo-Roussos 1996).

    Regression-corrected DIF on ordered (rater-mean) item scores y, continuous
    matching M, focal mask g (1=focal, 0=reference), and the same strata MH uses.
    Each group's mean studied score is projected to the stratum's common matching
    location (the Shealy-Stout correction). No rounding of y is needed. Returns
    (beta, se, z, p, eff_class, direction); beta is reference-minus-focal so a
    positive value (like the Mantel direction) favors the reference group. v1 is
    uniform SIBTEST; non-uniform DIF is covered by the ordinal-logistic test.
    """
    y = np.asarray(y, dtype=float)
    M = np.asarray(M, dtype=float)
    focal = np.asarray(g, dtype=float) >= 0.5
    strata = np.asarray(strata)
    fin = np.isfinite(y) & np.isfinite(M)
    used = []
    n_total = 0
    for s in pd.unique(strata):
        if not (np.isscalar(s) and np.isfinite(s)):
            continue
        idx = (strata == s) & fin
        n_k = int(idx.sum())
        if n_k < int(min_stratum_n):
            continue
        f_k = idx & focal
        r_k = idx & (~focal)
        n_fk = int(f_k.sum())
        n_rk = int(r_k.sum())
        if n_fk == 0 or n_rk == 0:
            continue
        yf, yr = y[f_k], y[r_k]
        mf, mr = M[f_k], M[r_k]
        mbar_f, mbar_r = float(mf.mean()), float(mr.mean())
        mbar_k = float(M[idx].mean())
        ybar_f, ybar_r = float(yf.mean()), float(yr.mean())
        sxx = float(((mf - mbar_f) ** 2).sum() + ((mr - mbar_r) ** 2).sum())
        sxy = float(((mf - mbar_f) * (yf - ybar_f)).sum() + ((mr - mbar_r) * (yr - ybar_r)).sum())
        b_k = (sxy / sxx) if sxx > 1e-12 else 0.0
        ystar_f = ybar_f + b_k * (mbar_k - mbar_f)
        ystar_r = ybar_r + b_k * (mbar_k - mbar_r)
        d_k = ystar_r - ystar_f
        s2_f = float(yf.var(ddof=1)) if n_fk > 1 else 0.0
        s2_r = float(yr.var(ddof=1)) if n_rk > 1 else 0.0
        used.append((n_k, d_k, s2_f / n_fk + s2_r / n_rk))
        n_total += n_k
    if not used or n_total == 0:
        return (np.nan, np.nan, np.nan, np.nan, "n/a", "n/a")
    beta = sum((n_k / n_total) * d_k for n_k, d_k, _ in used)
    var_acc = sum((n_k / n_total) ** 2 * var_dk for n_k, _, var_dk in used)
    beta = float(beta)
    se = float(np.sqrt(var_acc)) if var_acc > 0 else np.nan
    z = beta / se if (np.isfinite(se) and se > 0) else np.nan
    p = float(2.0 * _norm.sf(abs(z))) if np.isfinite(z) else np.nan
    direction = ("favors reference" if beta > 0 else "favors focal" if beta < 0 else "no signed difference")
    return (beta, se, z, p, _sibtest_eff_class(beta, score_range), direction)


def _po_cutpoints(p):
    """Map free params (len C-1) to strictly increasing cutpoints."""
    alpha = np.empty_like(np.asarray(p, dtype=float))
    alpha[0] = p[0]
    if alpha.size > 1:
        alpha[1:] = p[0] + np.cumsum(np.exp(p[1:]))
    return alpha


def _po_nll(theta, M, g, ycat, n_cat, include_match, include_group, include_interaction):
    from scipy.special import expit
    n_cut = n_cat - 1
    alpha = _po_cutpoints(theta[:n_cut])
    pos = n_cut
    beta = theta[pos] if include_match else 0.0
    pos += 1 if include_match else 0
    gamma = theta[pos] if include_group else 0.0
    pos += 1 if include_group else 0
    delta = theta[pos] if include_interaction else 0.0
    eta = beta * M + gamma * g + delta * M * g
    N = ycat.size
    cdf = np.empty((N, n_cat + 1))
    cdf[:, 0] = 0.0
    cdf[:, n_cat] = 1.0
    for c in range(1, n_cat):
        cdf[:, c] = expit(alpha[c - 1] - eta)
    probs = cdf[np.arange(N), ycat + 1] - cdf[np.arange(N), ycat]
    probs = np.clip(probs, 1e-12, 1.0)
    return -float(np.sum(np.log(probs)))


def _fit_proportional_odds(M, g, ycat, n_cat, include_match, include_group, include_interaction):
    """ML fit of a proportional-odds model with scipy. Returns (ll, n_params, status)."""
    n_cut = n_cat - 1
    if n_cut < 1:
        return (np.nan, 0, "degenerate")
    counts = np.bincount(ycat, minlength=n_cat).astype(float)
    props = np.clip(counts / max(counts.sum(), 1.0), 1e-3, 1.0)
    cum = np.clip(np.cumsum(props)[:-1], 1e-3, 1 - 1e-3)
    alpha0 = np.log(cum / (1 - cum))
    p0 = np.empty(n_cut)
    p0[0] = alpha0[0]
    if n_cut > 1:
        p0[1:] = np.log(np.clip(np.diff(alpha0), 1e-2, None))
    x0 = list(p0)
    if include_match:
        x0.append(0.5)
    if include_group:
        x0.append(0.0)
    if include_interaction:
        x0.append(0.0)
    x0 = np.asarray(x0, dtype=float)
    args = (M, g, ycat, n_cat, include_match, include_group, include_interaction)
    try:
        opt = minimize(_po_nll, x0, args=args, method="BFGS", options={"maxiter": 200, "gtol": 1e-5})
        if not opt.success or not np.isfinite(opt.fun):
            opt = minimize(_po_nll, x0, args=args, method="Nelder-Mead",
                           options={"maxiter": 3000, "xatol": 1e-4, "fatol": 1e-4})
        ll = -float(opt.fun)
        extra = np.asarray(opt.x[n_cut:], dtype=float)
        if not np.isfinite(ll) or (extra.size and np.max(np.abs(extra)) > 50.0):
            return (np.nan, x0.size, "separation")
        return (ll, x0.size, "ok")
    except Exception:
        return (np.nan, x0.size, "error")


def _ordinal_logistic_dif(M, g, ycat, n_cat):
    """Zumbo ordinal-logistic DIF: nested LR tests (uniform/non-uniform/total) + Nagelkerke Delta-R^2."""
    out = {"uniform_p": np.nan, "nonuniform_p": np.nan, "total_p": np.nan,
           "dr2_nag": np.nan, "dr2_mcf": np.nan, "r2_class": "n/a", "status": "ok"}
    M = np.asarray(M, dtype=float)
    g = np.asarray(g, dtype=float)
    ycat = np.asarray(ycat, dtype=int)
    N = ycat.size
    if N < (n_cat + 4) or np.unique(ycat).size < 2:
        out["status"] = "insufficient"
        return out
    msd = float(np.std(M))
    Mz = (M - float(np.mean(M))) / msd if msd > 0 else (M - float(np.mean(M)))
    ll_int, _, s_int = _fit_proportional_odds(Mz, g, ycat, n_cat, False, False, False)
    ll0, _, s0 = _fit_proportional_odds(Mz, g, ycat, n_cat, True, False, False)
    ll1, _, s1 = _fit_proportional_odds(Mz, g, ycat, n_cat, True, True, False)
    ll2, _, s2 = _fit_proportional_odds(Mz, g, ycat, n_cat, True, True, True)
    if not all(s == "ok" for s in (s0, s1, s2)) or not all(np.isfinite(x) for x in (ll0, ll1, ll2)):
        out["status"] = next((s for s in (s2, s1, s0) if s != "ok"), "nonconvergence")
        return out
    out["uniform_p"] = float(chi2.sf(max(2.0 * (ll1 - ll0), 0.0), 1))
    out["nonuniform_p"] = float(chi2.sf(max(2.0 * (ll2 - ll1), 0.0), 1))
    out["total_p"] = float(chi2.sf(max(2.0 * (ll2 - ll0), 0.0), 2))
    if np.isfinite(ll_int) and ll_int < 0:
        denom = 1.0 - np.exp(ll_int * 2.0 / N)

        def _nag(ll_m):
            cox = 1.0 - np.exp((ll_int - ll_m) * 2.0 / N)
            return cox / denom if denom > 0 else np.nan

        r2_0, r2_2 = _nag(ll0), _nag(ll2)
        if np.isfinite(r2_0) and np.isfinite(r2_2):
            out["dr2_nag"] = float(r2_2 - r2_0)
            out["r2_class"] = _dif_r2_class(out["dr2_nag"])
        out["dr2_mcf"] = float((1.0 - ll2 / ll_int) - (1.0 - ll0 / ll_int))
    return out


def build_dif_screening_table(raw, *, alpha: float = 0.05, min_group_n: int = 10,
                              practical_smd: float = 0.17, delta_r2_b: float = 0.035) -> pd.DataFrame:
    """Add multiplicity (Holm/BH) and evidence-level flags to raw per-item DIF rows."""
    cols = ["Item", "GroupContrast", "FocalLevel", "RefLevel", "N_focal", "N_ref", "ObsN",
            "NStrataUsed", "MH_ChiSq", "MH_p", "SMD", "SMD_std", "SMD_class",
            "Logit_Uniform_p", "Logit_NonUniform_p", "Logit_Total_p",
            "DeltaR2_Nagelkerke", "DeltaR2_McFadden", "R2_class", "LogisticStatus",
            "SIBTEST_Beta", "SIBTEST_SE", "SIBTEST_Z", "SIBTEST_p", "SIBTEST_class",
            "SIBTEST_Direction", "SIBTEST_Agreement",
            "PrimaryP", "p_holm", "p_bh", "EvidenceLevel", "Flag", "Direction",
            "ClaimStatus", "ReportingCaution", "MultiplicityFamily", "NextAction"]
    if not isinstance(raw, pd.DataFrame) or raw.empty:
        return pd.DataFrame(columns=cols)
    out = raw.copy().reset_index(drop=True)
    logit_ok = out.get("LogisticStatus", pd.Series(["not_fitted"] * len(out))).astype(str).eq("ok").to_numpy()
    primary = np.where(logit_ok,
                       pd.to_numeric(out.get("Logit_Total_p"), errors="coerce").to_numpy(dtype=float),
                       pd.to_numeric(out.get("MH_p"), errors="coerce").to_numpy(dtype=float))
    out["PrimaryP"] = primary
    out["p_holm"] = adjust_p_values(primary, "holm")
    out["p_bh"] = adjust_p_values(primary, "bh")
    n_focal = pd.to_numeric(out["N_focal"], errors="coerce").fillna(0)
    n_ref = pd.to_numeric(out["N_ref"], errors="coerce").fillna(0)
    n_strata = pd.to_numeric(out["NStrataUsed"], errors="coerce").fillna(0)
    sparse = (n_focal < int(min_group_n)) | (n_ref < int(min_group_n)) | (n_strata == 0)
    stat_holm = pd.to_numeric(out["p_holm"], errors="coerce") < float(alpha)
    stat_bh = pd.to_numeric(out["p_bh"], errors="coerce") < float(alpha)
    smd_std_abs = pd.to_numeric(out["SMD_std"], errors="coerce").abs()
    dr2 = pd.to_numeric(out["DeltaR2_Nagelkerke"], errors="coerce")
    sib_practical = out.get("SIBTEST_class", pd.Series(["n/a"] * len(out))).astype(str).isin(["moderate (B)", "large (C)"])
    practical = ((smd_std_abs >= float(practical_smd)) | (dr2 >= float(delta_r2_b)) | sib_practical).fillna(False)
    # SIBTEST corroboration: does the regression-corrected estimator agree on the
    # direction of the difference with the Mantel SMD?
    sib_dir = out.get("SIBTEST_Direction", pd.Series(["n/a"] * len(out))).astype(str)
    mh_dir = out.get("Direction", pd.Series(["n/a"] * len(out))).astype(str)
    out["SIBTEST_Agreement"] = np.select(
        [sib_dir.isin(["n/a", "no signed difference"]) | mh_dir.isin(["n/a", "no signed difference"]),
         sib_dir == mh_dir],
        ["n/a", "agrees"],
        default="disagrees")
    out["EvidenceLevel"] = np.select(
        [sparse, stat_holm & practical, stat_holm | stat_bh, practical],
        ["Sparse data", "Strong review", "Statistical review", "Effect-size note"],
        default="No flag")
    # A DIF flag requires statistical significance AFTER multiplicity control, so
    # the false-positive rate stays near alpha. A large effect size that is not
    # significant is surfaced as an "Effect-size note" (visible, but not a flag);
    # sparse cells are a data-quality note, not a DIF flag.
    out["Flag"] = out["EvidenceLevel"].isin(["Strong review", "Statistical review"])
    out["ClaimStatus"] = np.select(
        [out["EvidenceLevel"].eq("Sparse data"),
         out["Flag"].astype(bool),
         out["EvidenceLevel"].eq("Effect-size note")],
        ["Do not claim from this item alone",
         "Report with caveat",
         "Effect-size note only; not statistically flagged"],
        default="No computed DIF flag")
    out["ReportingCaution"] = np.select(
        [out["EvidenceLevel"].eq("Sparse data"),
         out["Flag"].astype(bool),
         out["EvidenceLevel"].eq("Effect-size note")],
        ["Too few persons per group for a stable DIF estimate.",
         "Screening evidence only — corroborate with content review, fit, and rater-allocation before any fairness or item-removal claim.",
         "Effect size reaches the practical band but is not significant after multiplicity control; treat as a watch item, not a flag."],
        default="No flag under this screen; not evidence that DIF is absent outside the tested items.")
    out["NextAction"] = np.select(
        [out["EvidenceLevel"].eq("Sparse data"),
         out["EvidenceLevel"].eq("Strong review"),
         out["EvidenceLevel"].eq("Statistical review"),
         out["EvidenceLevel"].eq("Effect-size note")],
        ["Collect more responses per group before interpreting.",
         "Review item content/translation and scoring for the flagged group; corroborate before any action.",
         "Inspect the item and corroborate with content and fit evidence.",
         "Watch the item; the effect size is notable but not statistically reliable here."],
        default="No special action beyond routine review.")
    out["MultiplicityFamily"] = (out["GroupContrast"].astype(str)
                                 + f"; alpha={float(alpha):.3g}, min_group_n={int(min_group_n)}")
    for c in cols:
        if c not in out.columns:
            out[c] = np.nan
    return out[cols].sort_values(["Flag", "PrimaryP"], ascending=[False, True]).reset_index(drop=True)


def summarize_dif_screening(table) -> pd.DataFrame:
    """One-row-per-metric summary of a DIF screening table."""
    cols = ["Metric", "Value"]
    if not isinstance(table, pd.DataFrame) or table.empty:
        return pd.DataFrame(columns=cols)
    flag = table["Flag"].astype(bool)
    ev = table["EvidenceLevel"].astype(str)
    smd_abs = pd.to_numeric(table["SMD_std"], errors="coerce").abs()
    dr2 = pd.to_numeric(table["DeltaR2_Nagelkerke"], errors="coerce")
    rows = [
        ("Items x contrasts screened", int(len(table))),
        ("Flagged", int(flag.sum())),
        ("Strong review", int(ev.eq("Strong review").sum())),
        ("Statistical review", int(ev.eq("Statistical review").sum())),
        ("Sparse data", int(ev.eq("Sparse data").sum())),
        ("Holm-significant", int((pd.to_numeric(table["p_holm"], errors="coerce") < 0.05).sum())),
        ("BH-significant", int((pd.to_numeric(table["p_bh"], errors="coerce") < 0.05).sum())),
        ("Logistic failures", int(table["LogisticStatus"].astype(str).ne("ok").sum())),
        ("Max |SMD_std|", float(smd_abs.max()) if smd_abs.notna().any() else np.nan),
        ("Max Delta-R^2", float(dr2.max()) if dr2.notna().any() else np.nan),
        ("Max |SIBTEST_Beta|", float(pd.to_numeric(table.get("SIBTEST_Beta"), errors="coerce").abs().max())
         if "SIBTEST_Beta" in table.columns and pd.to_numeric(table.get("SIBTEST_Beta"), errors="coerce").notna().any() else np.nan),
        ("SIBTEST agrees with MH", int(table.get("SIBTEST_Agreement", pd.Series(dtype=str)).astype(str).eq("agrees").sum())),
    ]
    return pd.DataFrame(rows, columns=cols)


def build_dif_inference_audit(table, settings=None) -> pd.DataFrame:
    """Per-contrast claim-safety audit for the DIF screen (mirrors the bias audit)."""
    cols = ["GroupContrast", "Status", "ClaimStatus", "ItemsScreened", "FlaggedItems",
            "StrongReviewItems", "SparseItems", "HolmSignificant", "BHSignificant",
            "InferenceScope", "MultiplicityScope", "EvidenceSummary", "RecommendedAction"]
    if not isinstance(table, pd.DataFrame) or table.empty:
        return pd.DataFrame(columns=cols)
    rows = []
    for contrast, grp in table.groupby("GroupContrast"):
        flag = grp["Flag"].astype(bool)
        ev = grp["EvidenceLevel"].astype(str)
        flagged = int(flag.sum())
        strong = int(ev.eq("Strong review").sum())
        sparse = int(ev.eq("Sparse data").sum())
        holm = int((pd.to_numeric(grp["p_holm"], errors="coerce") < 0.05).sum())
        bh = int((pd.to_numeric(grp["p_bh"], errors="coerce") < 0.05).sum())
        claim = "Do not claim" if (flagged and strong) else ("Report with caveat" if flagged else "Ready")
        action = ("Corroborate flagged items with content and fit evidence before any fairness claim."
                  if flagged else "No flag; do not extend a no-DIF claim beyond the screened items.")
        rows.append({
            "GroupContrast": str(contrast),
            "Status": "Review" if flagged else "Ready",
            "ClaimStatus": claim,
            "ItemsScreened": int(len(grp)), "FlaggedItems": flagged,
            "StrongReviewItems": strong, "SparseItems": sparse,
            "HolmSignificant": holm, "BHSignificant": bh,
            "InferenceScope": "Screening on rater-mean aggregates; rater severity averaged out, group allocation assumed balanced; global model uncertainty not propagated.",
            "MultiplicityScope": "Holm and BH adjustments computed within this contrast's item family; flags are review prompts, not confirmatory proof.",
            "EvidenceSummary": f"{flagged} flagged of {len(grp)}; {strong} strong-review, {sparse} sparse, {holm} Holm-significant, {bh} BH-significant.",
            "RecommendedAction": action,
        })
    return pd.DataFrame(rows, columns=cols)


def analyze_classical_dif(prep_or_data, item_facet, group_labels, *, matching="rest",
                          contrast="pairwise", reference_group=None, n_strata=10,
                          alpha=0.05, practical_smd=0.17, delta_r2_b=0.035,
                          min_group_n=10, min_stratum_n=2, fit_logistic=True,
                          purify=True, max_purify_iter=3) -> dict:
    """Classical polytomous DIF screening for an external person group.

    Returns {"table", "summary", "audit", "settings", "caveats"} or
    {"_skip_reason": "..."} when the input cannot support a screen.
    """
    if isinstance(prep_or_data, dict):
        data = prep_or_data.get("data")
        rating_min = int(prep_or_data.get("rating_min", 0) or 0)
        rating_max = int(prep_or_data.get("rating_max", 0) or 0)
    else:
        data = prep_or_data
        sc = pd.to_numeric(data["Score"], errors="coerce") if isinstance(data, pd.DataFrame) and "Score" in data.columns else pd.Series(dtype=float)
        rating_min = int(np.nanmin(sc)) if sc.notna().any() else 0
        rating_max = int(np.nanmax(sc)) if sc.notna().any() else 0
    if not isinstance(data, pd.DataFrame) or data.empty:
        return {"_skip_reason": "No response data available for DIF."}
    if item_facet not in data.columns:
        return {"_skip_reason": f"Item facet '{item_facet}' is not in the data."}
    n_cat = rating_max - rating_min + 1
    if n_cat < 2:
        return {"_skip_reason": "Need at least 2 score categories for DIF."}

    df = data[["Person", item_facet, "Score"]].copy()
    df["Score"] = pd.to_numeric(df["Score"], errors="coerce")
    df["Weight"] = pd.to_numeric(data["Weight"], errors="coerce").fillna(1.0) if "Weight" in data.columns else 1.0
    df = df.dropna(subset=["Score"])
    # Weighted rater-mean per person x item, vectorized (avoids a groupby.apply
    # over grouping columns and works across pandas versions).
    df["_ScoreW"] = df["Score"] * df["Weight"]
    gsum = df.groupby(["Person", item_facet], observed=True).agg(
        _sw=("_ScoreW", "sum"), _w=("Weight", "sum"), _n=("Score", "size"))
    rater_aggregated = bool((gsum["_n"] > 1).any())
    agg = gsum["_sw"] / gsum["_w"].replace(0, np.nan)
    wide = agg.unstack(item_facet)
    items = [str(c) for c in wide.columns]
    if len(items) < 2:
        return {"_skip_reason": "Need at least 2 items for DIF matching."}

    grp_series = pd.Series(group_labels)
    grp_series.index = grp_series.index.astype(str)
    wide.index = wide.index.astype(str)
    g_aligned = grp_series.reindex(wide.index)
    valid = g_aligned.notna()
    n_dropped_group = int((~valid).sum())
    wide = wide.loc[valid]
    g_aligned = g_aligned.loc[valid].astype(str)
    group_counts = g_aligned.value_counts()
    if group_counts.size < 2:
        return {"_skip_reason": "Need at least 2 groups for DIF (only one group label found)."}
    eligible = [gn for gn, cnt in group_counts.items() if cnt >= int(min_group_n)]
    if len(eligible) < 2:
        return {"_skip_reason": f"Need at least 2 groups each with >= {min_group_n} persons."}

    ref = str(reference_group) if (reference_group is not None and str(reference_group) in eligible) else str(group_counts.index[0])
    if str(contrast) == "rest":
        contrasts = [(gn, "rest") for gn in eligible]
    else:
        contrasts = [(gn, ref) for gn in eligible if gn != ref]

    g_arr = g_aligned.to_numpy()
    item_scores = wide.to_numpy(dtype=float)
    item_index = {it: j for j, it in enumerate(items)}
    def _matching_for_item(j_item, anchor_cols):
        # Sum of anchor item scores (matching criterion), minus the studied item
        # itself when using rest-score and it is an anchor (purification: DIF
        # items are dropped from the anchor pool so they do not contaminate the
        # matching variable for the remaining items).
        if anchor_cols:
            anchor_sum = np.nansum(item_scores[:, anchor_cols], axis=1)
        else:
            anchor_sum = np.zeros(item_scores.shape[0])
        if matching == "rest" and j_item in anchor_cols:
            return anchor_sum - np.nan_to_num(item_scores[:, j_item], nan=0.0)
        return anchor_sum

    def _compute_rows(exclude_set):
        anchor_cols = [item_index[it] for it in items if it not in exclude_set]
        rows = []
        for focal, ref_label in contrasts:
            is_focal = (g_arr == focal)
            is_ref = (g_arr != focal) if ref_label == "rest" else (g_arr == ref_label)
            for it in items:
                j = item_index[it]
                y = item_scores[:, j]
                fin = np.isfinite(y)
                foc_sel = is_focal & fin
                ref_sel = is_ref & fin & (~is_focal)
                sel = foc_sel | ref_sel
                n_focal_i = int(foc_sel.sum())
                n_ref_i = int(ref_sel.sum())
                row = {
                    "Item": it, "GroupContrast": f"{focal} vs {ref_label}",
                    "FocalLevel": focal, "RefLevel": ref_label,
                    "N_focal": n_focal_i, "N_ref": n_ref_i, "ObsN": int(sel.sum()),
                    "NStrataUsed": 0, "MH_ChiSq": np.nan, "MH_p": np.nan,
                    "SMD": np.nan, "SMD_std": np.nan, "SMD_class": "n/a",
                    "Logit_Uniform_p": np.nan, "Logit_NonUniform_p": np.nan,
                    "Logit_Total_p": np.nan, "DeltaR2_Nagelkerke": np.nan,
                    "DeltaR2_McFadden": np.nan, "R2_class": "n/a",
                    "LogisticStatus": "not_fitted", "Direction": "n/a",
                    "SIBTEST_Beta": np.nan, "SIBTEST_SE": np.nan, "SIBTEST_Z": np.nan,
                    "SIBTEST_p": np.nan, "SIBTEST_class": "n/a", "SIBTEST_Direction": "n/a",
                }
                if n_focal_i < int(min_group_n) or n_ref_i < int(min_group_n):
                    rows.append(row)
                    continue
                M = _matching_for_item(j, anchor_cols)
                yk = y[sel]
                Mk = M[sel]
                gk = is_focal[sel].astype(float)
                strata = _dif_strata(Mk, n_strata)
                chi2v, pv, smd, smd_std, smd_cls, direction, n_used = _mantel_polytomous(
                    yk, gk.astype(bool), strata, min_stratum_n)
                row.update({"MH_ChiSq": chi2v, "MH_p": pv, "SMD": smd, "SMD_std": smd_std,
                            "SMD_class": smd_cls, "Direction": direction, "NStrataUsed": n_used})
                sb, sb_se, sb_z, sb_p, sb_cls, sb_dir = _poly_sibtest(
                    yk, Mk, gk, strata, score_range=(rating_max - rating_min), min_stratum_n=min_stratum_n)
                row.update({"SIBTEST_Beta": sb, "SIBTEST_SE": sb_se, "SIBTEST_Z": sb_z,
                            "SIBTEST_p": sb_p, "SIBTEST_class": sb_cls, "SIBTEST_Direction": sb_dir})
                if fit_logistic:
                    ycat = np.clip(np.round(yk).astype(int) - rating_min, 0, n_cat - 1)
                    log = _ordinal_logistic_dif(Mk, gk, ycat, n_cat)
                    row.update({"Logit_Uniform_p": log["uniform_p"],
                                "Logit_NonUniform_p": log["nonuniform_p"],
                                "Logit_Total_p": log["total_p"],
                                "DeltaR2_Nagelkerke": log["dr2_nag"],
                                "DeltaR2_McFadden": log["dr2_mcf"],
                                "R2_class": log["r2_class"],
                                "LogisticStatus": log["status"]})
                rows.append(row)
        return pd.DataFrame(rows)

    # Iterative purification (Holland & Thayer): items strongly flagged in one
    # pass are removed from the matching anchor for the next pass, so a strong-DIF
    # item does not induce spurious DIF on the others through the matching score.
    exclude_set: set = set()
    table = build_dif_screening_table(_compute_rows(exclude_set), alpha=alpha, min_group_n=min_group_n,
                                      practical_smd=practical_smd, delta_r2_b=delta_r2_b)
    n_iter = int(max_purify_iter) if purify else 1
    for _ in range(max(n_iter - 1, 0)):
        new_strong = set(table.loc[table["EvidenceLevel"].eq("Strong review"), "Item"].astype(str))
        if new_strong == exclude_set or (len(items) - len(new_strong)) < 2:
            break
        exclude_set = new_strong
        table = build_dif_screening_table(_compute_rows(exclude_set), alpha=alpha, min_group_n=min_group_n,
                                          practical_smd=practical_smd, delta_r2_b=delta_r2_b)
    purified_items = sorted(exclude_set)

    summary = summarize_dif_screening(table)
    settings = {"item_facet": str(item_facet), "matching": str(matching), "contrast": str(contrast),
                "reference_group": ref, "n_strata": int(n_strata), "alpha": float(alpha),
                "practical_smd": float(practical_smd), "delta_r2_b": float(delta_r2_b),
                "min_group_n": int(min_group_n), "fit_logistic": bool(fit_logistic),
                "purify": bool(purify), "purified_items": purified_items,
                "groups": [str(x) for x in group_counts.index.tolist()], "n_items": len(items)}
    caveats = []
    if rater_aggregated:
        caveats.append("Item scores are rater-mean aggregates per person x item; rater severity is averaged out (not modeled), and rater allocation is assumed balanced across groups.")
    if fit_logistic:
        caveats.append("The ordinal-logistic response rounds the rater-mean to the nearest category; borderline persons are assigned to the nearest integer.")
    if purify and purified_items:
        caveats.append("Purified matching: " + ", ".join(purified_items) + " were removed from the matching anchor after being strongly flagged, so they do not contaminate the other items' matching score.")
    if n_dropped_group:
        caveats.append(f"{n_dropped_group} person(s) dropped for a missing group label.")
    audit = build_dif_inference_audit(table, settings)
    frame = wide.reset_index()
    if "Person" not in frame.columns:
        frame = frame.rename(columns={frame.columns[0]: "Person"})
    frame.insert(1, "group", g_aligned.to_numpy())
    return {"table": table, "summary": summary, "audit": audit,
            "settings": settings, "caveats": caveats,
            "analysis_frame": {"frame": frame, "rating_min": int(rating_min), "rating_max": int(rating_max)}}


_DIF_R_CROSSCHECK_SCRIPT = r'''# run_difR_crosscheck.R
# External cross-check of the MFRM app's classical DIF screen, using the R
# packages difR and lordif on the EXACT analysis frame the app screened.
# This is a reproducibility artifact: exact numbers will differ from the app
# (see README_difR_crosscheck.md) — directional and A/B/C agreement is the bar.
#   install.packages(c("difR", "lordif"))
suppressMessages({library(difR); library(lordif)})

frame    <- read.csv("dif_analysis_frame.csv",    stringsAsFactors = FALSE, check.names = FALSE)
settings <- read.csv("dif_analysis_settings.csv", stringsAsFactors = FALSE)

reference <- as.character(settings$reference_group)
item_cols <- setdiff(colnames(frame), c("Person", "group"))
Data  <- as.matrix(frame[, item_cols, drop = FALSE])   # rater-mean (float) item scores
group <- as.character(frame$group)

cat("Reference group:", reference, " items:", paste(item_cols, collapse=", "), "\n\n")

# 1. Generalized Mantel-Haenszel (polytomous MH) -- vs the app's _mantel_polytomous
gmh <- tryCatch(difGMH(Data = Data, group = group, focal.name = reference,
                       alpha = settings$alpha), error = function(e) {message(e); NULL})
if (!is.null(gmh)) print(gmh)

# 2. SIBTEST (uniform) -- vs the app's _poly_sibtest
sib <- tryCatch(difSIBTEST(Data = Data, group = group, focal.name = reference,
                           type = "udif", alpha = settings$alpha), error = function(e) {message(e); NULL})
if (!is.null(sib)) print(sib)

# 3. Ordinal logistic DIF via lordif (cumulative-logit GRM) -- vs the app's
#    _ordinal_logistic_dif. lordif needs integer scores, so round (as the app
#    does for its ordinal-logistic model).
resp <- as.data.frame(round(Data))
grp_bin <- as.integer(group != reference)              # focal = not reference
lo <- tryCatch(lordif(resp.data = resp, group = grp_bin, criterion = "Chisqr",
                      alpha = settings$alpha, model = "GRM"),
               error = function(e) {message("lordif: ", conditionMessage(e)); NULL})
if (!is.null(lo)) print(lo$stats)

# 4. difR generalized logistic (ordinal-logistic alternative, no lordif needed)
glog <- tryCatch(difGenLogistic(Data = round(Data), group = group, focal.name = reference,
                                type = "udif", alpha = settings$alpha), error = function(e) {message(e); NULL})
if (!is.null(glog)) print(glog)

# 5. Side-by-side with the app's own result table
app_res <- tryCatch(read.csv("dif_app_results.csv"), error = function(e) NULL)
if (!is.null(app_res)) {
  cat("\n--- App result (compare flags / direction / effect class per item) ---\n")
  keep <- intersect(c("Item","GroupContrast","MH_p","SMD_class","SIBTEST_Beta","SIBTEST_p",
                      "Logit_Total_p","EvidenceLevel","Flag","Direction"), colnames(app_res))
  print(app_res[, keep])
}
'''

_DIF_R_CROSSCHECK_README = '''# difR / lordif cross-check of the MFRM classical DIF screen

This bundle lets you reproduce the app's classical DIF screen in R (difR /
lordif) for external validation. **Exact numeric parity is NOT expected** — the
bar is directional and A/B/C-classification agreement, not matching p-values.

## Files
- `dif_analysis_frame.csv` — the exact person x item frame the app screened:
  one row per person, `Person`, `group`, and one column per item holding the
  **rater-mean** score (float).
- `dif_analysis_settings.csv` — reference group, matching, strata, alpha,
  min_group_n, purified items, score range.
- `dif_app_results.csv` — the app's own per-item DIF table for side-by-side.
- `run_difR_crosscheck.R` — runs `difR::difGMH`, `difR::difSIBTEST`,
  `lordif::lordif`, and `difR::difGenLogistic`.

## Run
```
install.packages(c("difR", "lordif"))
Rscript run_difR_crosscheck.R
```

## Why the numbers differ (expected sources)
1. **Rater-mean aggregation.** The app screens rater-mean per person x item
   scores; difR/lordif expect one score per cell. The CSV ships the app's exact
   rater means, so MH/SIBTEST see identical inputs — but lordif / difGenLogistic
   need integers and the script `round()`s them (as the app does only for its
   ordinal-logistic model). App-MH/SIBTEST vs difR should be close; lordif vs
   the app's logistic differs by that rounding.
2. **Matching & rest-score.** The app defaults to rest-score matching with
   iterative purification; difGMH/difSIBTEST default to total score with their
   own purification loop. The anchor item set will not match item-for-item.
3. **Stratification.** The app bins the matching score (integer levels if few,
   else quantiles); difR uses score-level matching, so chi-squares differ in
   magnitude.
4. **Variance / correction details.** The app's polytomous SIBTEST variance uses
   empirical within-stratum group variances; difR uses the Shealy-Stout form.
   Point estimates of beta agree closely; SE/Z can differ in the second decimal.
5. **Group coding.** difR codes the focal group via `focal.name`; here
   `focal.name = reference_group` and a positive SIBTEST beta favors the
   reference group (the same sign convention as the app's Direction column).

## What to compare
Per item: (a) the same items flagged at alpha, (b) the same Direction
(favors focal / reference), (c) the same A/B/C effect band. A row-by-row
p-value diff is the wrong test; a flag/direction agreement table is the right
one. Disagreement on a borderline item is expected; disagreement on a strongly
flagged item warrants inspecting the matching / stratification choices.
'''


def build_dif_validation_bundle(res: dict) -> dict:
    """Build a difR/lordif R cross-check bundle from an analyze_classical_dif result.

    Returns {filename: bytes-or-text} for cached_mixed_asset_zip. Reproducibility
    artifact only — difR / lordif are NOT app dependencies.
    """
    if not isinstance(res, dict):
        return {}
    af = res.get("analysis_frame")
    settings = res.get("settings", {})
    table = res.get("table", pd.DataFrame())
    out: dict = {}
    if isinstance(af, dict) and isinstance(af.get("frame"), pd.DataFrame):
        out["dif_analysis_frame.csv"] = to_csv_bytes(af["frame"])
    settings_row = {
        "reference_group": settings.get("reference_group", ""),
        "matching": settings.get("matching", "rest"),
        "n_strata": settings.get("n_strata", 10),
        "alpha": settings.get("alpha", 0.05),
        "min_group_n": settings.get("min_group_n", 10),
        "purify_flag": str(bool(settings.get("purify", True))).upper(),
        "purified_items": ";".join(settings.get("purified_items", []) or []),
        "rating_min": af.get("rating_min", 0) if isinstance(af, dict) else 0,
        "rating_max": af.get("rating_max", 0) if isinstance(af, dict) else 0,
    }
    out["dif_analysis_settings.csv"] = to_csv_bytes(pd.DataFrame([settings_row]))
    if isinstance(table, pd.DataFrame) and not table.empty:
        out["dif_app_results.csv"] = to_csv_bytes(table)
    out["run_difR_crosscheck.R"] = _DIF_R_CROSSCHECK_SCRIPT
    out["README_difR_crosscheck.md"] = _DIF_R_CROSSCHECK_README
    return out


_CROSS_ENGINE_R_SCRIPT = r'''# run_tam_mirt_crosscheck.R
# Cross-engine validation of the MFRM app's MML/GPCM main estimates, using the R
# packages TAM, sirt, and mirt on the EXACT data the app fitted. This is a
# reproducibility artifact: exact numbers WILL differ (see README) — rank-order
# and directional agreement is the bar, not matching logits.
#   install.packages(c("TAM", "sirt", "mirt"))
suppressMessages({library(TAM); library(sirt)})

dat      <- read.csv("data.csv",     stringsAsFactors = FALSE, check.names = FALSE)
settings <- read.csv("settings.csv", stringsAsFactors = FALSE)

model      <- as.character(settings$model[1])      # RSM / PCM / GPCM
method     <- as.character(settings$method[1])     # MML / JMLE
item_facet <- as.character(settings$step_facet[1])
facet_all  <- strsplit(as.character(settings$facet_names[1]), ";")[[1]]
if (is.na(item_facet) || item_facet == "") item_facet <- tail(facet_all, 1)  # RSM: last facet as item
other_facets <- setdiff(facet_all, item_facet)
cat("Model:", model, " method:", method, " item facet:", item_facet,
    " other facets:", paste(other_facets, collapse = ", "), "\n\n")

# --- Reshape long -> wide on the item facet (TAM facets format) -------------
#   Each row = (Person + other-facet) combination; columns = item-facet levels;
#   pid = Person; facets = the other facets per row. ADAPT to your design.
id_cols <- c("Person", other_facets)
wide <- reshape(dat[, c(id_cols, item_facet, "Score")],
                idvar = id_cols, timevar = item_facet, direction = "wide")
item_cols <- grep("^Score\\.", colnames(wide), value = TRUE)
resp   <- wide[, item_cols, drop = FALSE]
colnames(resp) <- sub("^Score\\.", "", item_cols)
pid    <- wide$Person
facets <- wide[, other_facets, drop = FALSE]

# --- 1. TAM many-facet Rasch (tam.mml.mfr) ---------------------------------
formA <- as.formula(paste("~ item +", paste(other_facets, collapse = " + "), "+ item:step"))
tam_mod <- tryCatch(
  TAM::tam.mml.mfr(resp = resp, facets = facets, formulaA = formA, pid = pid),
  error = function(e) { message("TAM: ", conditionMessage(e)); NULL })
if (!is.null(tam_mod)) {
  cat("\n--- TAM facet/item parameters (xsi) ---\n"); print(tam_mod$xsi)
  cat("\n--- TAM person EAP/WLE (head) ---\n"); print(head(TAM::tam.wle(tam_mod)))
}

# --- 2. sirt rater-facet model (rm.facets) — closest to a rater-mediated MFRM
if (length(other_facets) >= 1) {
  rater <- as.factor(facets[[other_facets[1]]])     # ADAPT: which facet is the rater
  rm_mod <- tryCatch(sirt::rm.facets(dat = resp, pid = pid, rater = rater),
                     error = function(e) { message("sirt rm.facets: ", conditionMessage(e)); NULL })
  if (!is.null(rm_mod)) { cat("\n--- sirt rm.facets item/rater parameters ---\n"); print(rm_mod$item) }
}

# --- 3. mirt item-level (collapse raters: mean score per person x item) -----
dat$.item <- dat[[item_facet]]
agg <- aggregate(Score ~ Person + .item, data = dat, FUN = mean)
colnames(agg)[colnames(agg) == ".item"] <- "item"
mwide <- reshape(agg, idvar = "Person", timevar = "item", direction = "wide")
mresp <- round(mwide[, grep("^Score", colnames(mwide)), drop = FALSE])
itemtype <- if (model == "GPCM") "gpcm" else "Rasch"   # GPCM ~ gpcm; RSM/PCM ~ Rasch-family
m_mod <- tryCatch(mirt::mirt(mresp, 1, itemtype = itemtype, verbose = FALSE),
                  error = function(e) { message("mirt: ", conditionMessage(e)); NULL })
if (!is.null(m_mod)) { cat("\n--- mirt item coefficients ---\n"); print(mirt::coef(m_mod, simplify = TRUE)$items) }

# --- 4. side-by-side with the app's own estimates ---------------------------
for (f in c("app_facets.csv", "app_person.csv", "app_steps.csv", "app_slopes.csv")) {
  if (file.exists(f)) { cat("\n---", f, "(head) ---\n"); print(head(read.csv(f))) }
}
cat("\nCompare RANK ORDER and DIRECTION, not exact logits (see README_cross_engine.md).\n")
'''

_CROSS_ENGINE_README = '''# Cross-engine validation of the MFRM app's main estimates (TAM / sirt / mirt)

This bundle lets you refit the app's MML/GPCM analysis in R (TAM, sirt, mirt) and
cross-check the estimates. **Exact numerical equality is NOT claimed** (the app
runs standalone Python; it never calls these packages at runtime). The bar is
rank-order, sign, and effect-ordering agreement — not matching logits or
log-likelihoods.

## Files
- `data.csv` — the exact long response frame the app fitted: `Person`, each facet,
  `Score`, `Weight`.
- `settings.csv` — the fitted model: model (RSM/PCM/GPCM), method (MML/JMLE),
  step/slope facet, facet names, identification (noncenter facet), population SD
  setting, quadrature points, score range.
- `app_person.csv` / `app_facets.csv` / `app_steps.csv` / `app_slopes.csv` — the
  app's own person, facet, step, and (GPCM) slope estimates for side-by-side.
- `run_tam_mirt_crosscheck.R` — refits with `TAM::tam.mml.mfr`, `sirt::rm.facets`,
  and `mirt`, then prints estimates for comparison. It is a **template** —
  adapt the facets design (`formulaA`, which facet is the rater) to your study.

## Run
```
install.packages(c("TAM", "sirt", "mirt"))
Rscript run_tam_mirt_crosscheck.R
```

## Why the numbers differ (expected sources)
1. **Population variance.** The app's MML fixes the person SD by default, or
   estimates it (the opt-in free-SD mode — see `estimate_population_sd` /
   `estimated_population_sd` in settings.csv). TAM estimates the latent variance
   by default. Person measures are on different metric scales unless the variance
   handling is aligned; compare rank order, not raw logits.
2. **Identification / centering.** The app uses sum-to-zero centering on the
   facets (non-centered facet recorded in settings); TAM/sirt use their own
   defaults (often a fixed first level). Expect a constant shift / rotation, not
   item-for-item equality.
3. **GPCM slopes.** The app uses a bounded GPCM slope facet with a geometric-mean
   slope identification; mirt's `gpcm` is item-level with free slopes. Treat mirt
   as item-level corroboration, not a facet-level match.
4. **Rater mediation.** sirt's `rm.facets` is the closest analog (a rater-facet
   model). mirt is item-level, so the R script collapses raters to a mean score
   per person x item and rounds — that aggregation/rounding alone shifts results.
5. **Estimator / quadrature.** MML EM vs the package optimizer, quadrature point
   counts, and scoring conventions differ.

## What to compare
Per facet/item: (a) the same sign and ordering of difficulties/severities,
(b) rank correlation of person measures > ~0.95, (c) the same fit outliers.
A logit-by-logit diff is the wrong test; report a cross-check only when the
model, constraints, quadrature, and scoring conventions are aligned (see the
app's "Cross-package equivalence" boundary). Disagreement beyond ~0.05 logits or
a rank correlation below ~0.95 warrants inspecting the identification and
variance-handling alignment first.
'''


def build_cross_engine_validation_bundle(result: dict) -> dict:
    """Build a TAM/sirt/mirt R cross-engine validation bundle from a fitted result.

    Ships the exact data, the fitted settings, and the app's own estimates so the
    researcher can refit in R and cross-check. Reproducibility artifact only —
    TAM/sirt/mirt are NOT app dependencies; exact numerical parity is not claimed.
    Returns {filename: bytes-or-text} for cached_mixed_asset_zip, or {} when there
    is no usable fitted result.
    """
    if not isinstance(result, dict):
        return {}
    prep = result.get("prep", {})
    config = result.get("config", {})
    data = prep.get("data") if isinstance(prep, dict) else None
    if not isinstance(data, pd.DataFrame) or data.empty:
        return {}
    facet_names = [str(f) for f in (config.get("facet_names") or [])]
    keep_cols = (["Person"]
                 + [c for c in facet_names if c in data.columns]
                 + [c for c in ("Score", "Weight") if c in data.columns])
    out: dict = {"data.csv": to_csv_bytes(data[keep_cols].copy())}
    settings_row = {
        "model": config.get("model"),
        "method": config.get("method"),
        "step_facet": config.get("step_facet"),
        "slope_facet": config.get("slope_facet"),
        "facet_names": ";".join(facet_names),
        "noncenter_facet": config.get("noncenter_facet"),
        "dummy_facets": ";".join(str(x) for x in (config.get("dummy_facets") or [])),
        "population_prior_sd": config.get("population_prior_sd"),
        "estimate_population_sd": bool(config.get("estimate_population_sd")),
        "estimated_population_sd": config.get("estimated_population_sd"),
        "quad_points": config.get("quad_points"),
        "rating_min": prep.get("rating_min") if isinstance(prep, dict) else None,
        "rating_max": prep.get("rating_max") if isinstance(prep, dict) else None,
    }
    out["settings.csv"] = to_csv_bytes(pd.DataFrame([settings_row]))
    facets = result.get("facets", {})
    if isinstance(facets, dict):
        for fname, key in (("person", "app_person.csv"), ("others", "app_facets.csv")):
            tbl = facets.get(fname)
            if isinstance(tbl, pd.DataFrame) and not tbl.empty:
                out[key] = to_csv_bytes(tbl)
    for rkey, fname in (("steps", "app_steps.csv"), ("slopes", "app_slopes.csv")):
        tbl = result.get(rkey)
        if isinstance(tbl, pd.DataFrame) and not tbl.empty:
            out[fname] = to_csv_bytes(tbl)
    out["run_tam_mirt_crosscheck.R"] = _CROSS_ENGINE_R_SCRIPT
    out["README_cross_engine.md"] = _CROSS_ENGINE_README
    return out


def safe_cor(x, y, w=None):
    ok = np.isfinite(x) & np.isfinite(y)
    if w is None:
        if not np.any(ok):
            return np.nan
        x = x[ok]
        y = y[ok]
        if len(np.unique(x)) < 2 or len(np.unique(y)) < 2:
            return np.nan
        return float(np.corrcoef(x, y)[0, 1])

    ok = ok & np.isfinite(w) & (w > 0)
    if not np.any(ok):
        return np.nan
    x = x[ok]
    y = y[ok]
    w = w[ok]
    w_sum = np.sum(w)
    if w_sum <= 0:
        return np.nan
    mx = np.sum(w * x) / w_sum
    my = np.sum(w * y) / w_sum
    vx = np.sum(w * (x - mx) ** 2) / w_sum
    vy = np.sum(w * (y - my) ** 2) / w_sum
    if vx <= 0 or vy <= 0:
        return np.nan
    cov = np.sum(w * (x - mx) * (y - my)) / w_sum
    return float(cov / np.sqrt(vx * vy))


def weighted_mean_safe(x, w):
    ok = np.isfinite(x) & np.isfinite(w)
    if not np.any(ok):
        return np.nan
    return float(np.sum(x[ok] * w[ok]) / np.sum(w[ok]))


def calc_interrater_agreement(obs_df, facet_cols, rater_facet, res=None):
    if obs_df is None or obs_df.empty:
        return {"summary": pd.DataFrame(), "pairs": pd.DataFrame()}
    if rater_facet is None or rater_facet not in facet_cols:
        return {"summary": pd.DataFrame(), "pairs": pd.DataFrame()}
    context_cols = [c for c in facet_cols if c != rater_facet]
    if len(context_cols) == 0:
        return {"summary": pd.DataFrame(), "pairs": pd.DataFrame()}

    df = obs_df.copy()
    df["_context"] = df[context_cols].astype(str).agg("|".join, axis=1)
    base_cols = ["_context", rater_facet, "Observed"]
    if "Weight" in df.columns:
        base_cols.append("Weight")
    df = df[base_cols].copy()
    if "Weight" in df.columns:
        df["_weighted_observed"] = df["Observed"].astype(float) * df["Weight"].astype(float)
        # observed=True: skip empty Cartesian combinations. Required
        # for sparse designs (e.g., peer-rating where 118 of 120
        # raters never see each examinee). Previously `observed=False`
        # materialised the full 120×N_context cross and pandas raised
        # a length-mismatch on the post-agg insert.
        df_obs = (
            df.groupby(["_context", rater_facet], observed=True, as_index=False)
            .agg(WeightedObserved=("_weighted_observed", "sum"), Weight=("Weight", "sum"))
        )
        df_obs["Score"] = np.where(
            df_obs["Weight"].to_numpy(dtype=float) > 0,
            df_obs["WeightedObserved"].to_numpy(dtype=float) / df_obs["Weight"].to_numpy(dtype=float),
            np.nan,
        )
        df_obs = df_obs[["_context", rater_facet, "Score"]]
    else:
        df_obs = df.groupby(["_context", rater_facet], observed=True, as_index=False).agg(Score=("Observed", "mean"))
    if df_obs.empty:
        return {"summary": pd.DataFrame(), "pairs": pd.DataFrame()}

    prob_map = {}
    if res is not None:
        probs = compute_prob_matrix(res)
        if probs is not None and probs.shape[0] == len(obs_df):
            prob_cols = [f"_p{i}" for i in range(probs.shape[1])]
            df_probs = df[["_context", rater_facet]].copy()
            for i, col in enumerate(prob_cols):
                df_probs[col] = probs[:, i]
            if "Weight" in df.columns:
                df_probs["Weight"] = df["Weight"].to_numpy()
            for (ctx, r), g in df_probs.groupby(["_context", rater_facet], observed=False):
                if "Weight" in g.columns:
                    w = g["Weight"].to_numpy(dtype=float)
                    ok = np.isfinite(w) & (w > 0)
                    if not np.any(ok):
                        avg = np.full(len(prob_cols), np.nan)
                    else:
                        avg = np.average(g.loc[ok, prob_cols].to_numpy(), axis=0, weights=w[ok])
                else:
                    avg = np.nanmean(g[prob_cols].to_numpy(), axis=0)
                prob_map[(ctx, r)] = avg

    wide = df_obs.pivot(index="_context", columns=rater_facet, values="Score")
    if wide is None or wide.empty:
        return {"summary": pd.DataFrame(), "pairs": pd.DataFrame()}

    rater_cols = [c for c in wide.columns if c != "_context"]
    if len(rater_cols) < 2:
        return {"summary": pd.DataFrame(), "pairs": pd.DataFrame()}

    pairs = []
    for i in range(len(rater_cols)):
        for j in range(i + 1, len(rater_cols)):
            pairs.append((rater_cols[i], rater_cols[j]))

    pair_rows = []
    total_pairs = 0
    total_exact = 0
    total_expected = 0.0
    expected_available = False
    for r1, r2 in pairs:
        sub = wide[[r1, r2]].dropna()
        n_ok = int(len(sub))
        if n_ok == 0:
            pair_rows.append({
                "Element1": r1,
                "Element2": r2,
                "N": 0,
                "Exact": np.nan,
                "ExpectedExact": np.nan,
                "Adjacent": np.nan,
                "MeanDiff": np.nan,
                "MAD": np.nan,
                "Corr": np.nan,
            })
            continue

        v1 = sub[r1].to_numpy()
        v2 = sub[r2].to_numpy()
        diff = v1 - v2
        exact_count = int(np.sum(np.isclose(diff, 0)))

        exp_vals = []
        if prob_map:
            for ctx in sub.index:
                p1 = prob_map.get((ctx, r1))
                p2 = prob_map.get((ctx, r2))
                if p1 is None or p2 is None:
                    continue
                if np.any(np.isnan(p1)) or np.any(np.isnan(p2)):
                    continue
                exp_vals.append(float(np.sum(p1 * p2)))
        exp_mean = float(np.mean(exp_vals)) if exp_vals else np.nan
        exp_sum = float(np.sum(exp_vals)) if exp_vals else 0.0
        if exp_vals:
            expected_available = True

        pair_rows.append({
            "Element1": r1,
            "Element2": r2,
            "N": n_ok,
            "Exact": float(exact_count / n_ok),
            "ExpectedExact": exp_mean,
            "Adjacent": float(np.mean(np.abs(diff) <= 1)),
            "MeanDiff": float(np.mean(diff)),
            "MAD": float(np.mean(np.abs(diff))),
            "Corr": safe_cor(v1, v2),
        })

        total_pairs += n_ok
        total_exact += exact_count
        total_expected += exp_sum

    pair_tbl = pd.DataFrame(pair_rows)
    contexts_with_pairs = int(np.sum(np.sum(np.isfinite(wide.to_numpy()), axis=1) >= 2))

    if not expected_available:
        total_expected = np.nan
    summary_tbl = pd.DataFrame({
        "RaterFacet": [rater_facet],
        "Elements": [len(rater_cols)],
        "Pairs": [len(pair_tbl)],
        "Contexts": [contexts_with_pairs],
        "TotalPairs": [total_pairs],
        "ExactAgreements": [total_exact],
        "ExpectedAgreements": [total_expected if total_pairs > 0 else np.nan],
        "ExactAgreement": [total_exact / total_pairs if total_pairs > 0 else np.nan],
        "ExpectedExactAgreement": [total_expected / total_pairs if total_pairs > 0 else np.nan],
        "AdjacentAgreement": [weighted_mean_safe(pair_tbl["Adjacent"].to_numpy(), pair_tbl["N"].to_numpy()) if not pair_tbl.empty else np.nan],
        "MeanAbsDiff": [weighted_mean_safe(pair_tbl["MAD"].to_numpy(), pair_tbl["N"].to_numpy()) if not pair_tbl.empty else np.nan],
        "MeanCorr": [weighted_mean_safe(pair_tbl["Corr"].to_numpy(), pair_tbl["N"].to_numpy()) if not pair_tbl.empty else np.nan],
    })

    return {"summary": summary_tbl, "pairs": pair_tbl}


KRIPPENDORFF_ALPHA_METRICS: tuple[str, ...] = ("ordinal", "nominal", "interval")


def _agreement_score_wide(
    obs_df: pd.DataFrame,
    facet_cols: list[str],
    target_facet: str,
) -> tuple[pd.DataFrame, dict[str, object]]:
    """Return unit-by-element score matrix for agreement-style diagnostics."""
    meta: dict[str, object] = {
        "TargetFacet": target_facet,
        "ContextColumns": "",
        "Aggregation": "mean",
        "RowsUsed": 0,
    }
    if obs_df is None or obs_df.empty or target_facet not in obs_df.columns:
        return pd.DataFrame(), meta
    available_facets = [c for c in facet_cols if c in obs_df.columns]
    context_cols = [c for c in available_facets if c != target_facet]
    if not context_cols:
        return pd.DataFrame(), meta

    df = obs_df.copy()
    if "Observed" not in df.columns:
        return pd.DataFrame(), meta
    df["_context"] = df[context_cols].astype(str).agg("|".join, axis=1)
    df["_score_for_agreement"] = pd.to_numeric(df["Observed"], errors="coerce")
    base_cols = ["_context", target_facet, "_score_for_agreement"]
    if "Weight" in df.columns:
        base_cols.append("Weight")
    df = df[base_cols].dropna(subset=["_score_for_agreement", target_facet]).copy()
    if df.empty:
        return pd.DataFrame(), meta

    if "Weight" in df.columns:
        df["Weight"] = pd.to_numeric(df["Weight"], errors="coerce")
        df = df.dropna(subset=["Weight"])
        df = df[df["Weight"] > 0].copy()
        if df.empty:
            return pd.DataFrame(), meta
        df["_weighted_score_for_agreement"] = df["_score_for_agreement"] * df["Weight"]
        df_obs = (
            df.groupby(["_context", target_facet], observed=True, as_index=False)
            .agg(WeightedObserved=("_weighted_score_for_agreement", "sum"), Weight=("Weight", "sum"))
        )
        df_obs["Score"] = np.where(
            df_obs["Weight"].to_numpy(dtype=float) > 0,
            df_obs["WeightedObserved"].to_numpy(dtype=float) / df_obs["Weight"].to_numpy(dtype=float),
            np.nan,
        )
        meta["Aggregation"] = "weighted_mean"
    else:
        df_obs = (
            df.groupby(["_context", target_facet], observed=True, as_index=False)
            .agg(Score=("_score_for_agreement", "mean"))
        )
        meta["Aggregation"] = "mean"

    wide = df_obs.pivot(index="_context", columns=target_facet, values="Score")
    wide = wide.apply(pd.to_numeric, errors="coerce")
    meta["ContextColumns"] = "; ".join(context_cols)
    meta["RowsUsed"] = int(len(df))
    return wide, meta


def _krippendorff_alpha_status(alpha_value: float) -> tuple[str, str]:
    if not np.isfinite(alpha_value):
        return (
            "Unavailable",
            "Alpha could not be estimated from the shared contexts in this run.",
        )
    if alpha_value >= 0.80:
        return (
            "Ready",
            "High agreement for this selected facet under the chosen distance metric.",
        )
    if alpha_value >= 0.67:
        return (
            "Caution",
            "Moderate agreement; usable for some summaries, but inspect pairwise patterns and MFRM fit.",
        )
    return (
        "Review",
        "Low agreement; inspect scoring design, facet fit, category functioning, and possible rater or task drift.",
    )


def _krippendorff_ordinal_distance_matrix(values: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    categories, counts = np.unique(values, return_counts=True)
    order = np.argsort(categories)
    categories = categories[order]
    counts = counts[order].astype(float)
    n_cat = len(categories)
    dist = np.zeros((n_cat, n_cat), dtype=float)
    if n_cat <= 1:
        return categories, dist
    for i in range(n_cat):
        for j in range(i + 1, n_cat):
            span = float(np.sum(counts[i:j + 1]) - 0.5 * (counts[i] + counts[j]))
            dist[i, j] = span ** 2
            dist[j, i] = dist[i, j]
    return categories, dist


def calc_krippendorff_alpha(
    obs_df: pd.DataFrame,
    facet_cols: list[str],
    target_facet: str,
    *,
    metric: str = "ordinal",
) -> dict[str, pd.DataFrame]:
    """Compute an experimental Krippendorff alpha table for one selected facet."""
    metric = str(metric or "ordinal").lower()
    if metric not in KRIPPENDORFF_ALPHA_METRICS:
        metric = "ordinal"
    wide, meta = _agreement_score_wide(obs_df, facet_cols, target_facet)
    empty_summary = pd.DataFrame(columns=[
        "Facet", "DistanceMetric", "KrippendorffAlpha", "Status", "PlainLanguage",
        "Units", "Elements", "PairableUnits", "RatingsUsed", "MissingCells",
        "UnitsWithSingleRating", "ObservedDisagreement", "ExpectedDisagreement", "ContextColumns",
        "Aggregation", "Caveat",
    ])
    if wide.empty or wide.shape[1] < 2:
        return {"summary": empty_summary, "coverage": pd.DataFrame()}

    pairable_values: list[float] = []
    observed_num = 0.0
    pairable_units = 0
    units_with_single_rating = 0

    for _, row in wide.iterrows():
        vals = pd.to_numeric(row, errors="coerce").dropna().to_numpy(dtype=float)
        m = len(vals)
        if m < 2:
            if m == 1:
                units_with_single_rating += 1
            continue
        pairable_units += 1
        pairable_values.extend(float(v) for v in vals)
        if metric == "nominal":
            diff = vals[:, None] != vals[None, :]
            observed_num += float(diff.sum()) / float(m - 1)
        elif metric == "interval":
            delta = (vals[:, None] - vals[None, :]) ** 2
            observed_num += float(delta.sum()) / float(m - 1)
        else:
            # Ordinal distances are data-dependent, so compute after the
            # pairable marginal categories are known. Store raw values here.
            continue

    values = np.asarray(pairable_values, dtype=float)
    ratings_used = int(len(values))
    units = int(wide.shape[0])
    elements = int(wide.shape[1])
    missing_cells = int(wide.isna().sum().sum())
    caveat = (
        "Experimental agreement screen. It complements MFRM fit/reliability; "
        "it does not replace model-based severity, bias, or category diagnostics."
    )
    if ratings_used < 2 or pairable_units < 1:
        status, plain = _krippendorff_alpha_status(np.nan)
        summary = pd.DataFrame([{
            "Facet": target_facet,
            "DistanceMetric": metric,
            "KrippendorffAlpha": np.nan,
            "Status": status,
            "PlainLanguage": plain,
            "Units": units,
            "Elements": elements,
            "PairableUnits": pairable_units,
            "UnitsWithSingleRating": units_with_single_rating,
            "RatingsUsed": ratings_used,
            "MissingCells": missing_cells,
            "ObservedDisagreement": np.nan,
            "ExpectedDisagreement": np.nan,
            "ContextColumns": meta.get("ContextColumns", ""),
            "Aggregation": meta.get("Aggregation", "mean"),
            "Caveat": caveat,
        }])
        return {"summary": summary, "coverage": pd.DataFrame()}

    if metric == "ordinal":
        categories, dist = _krippendorff_ordinal_distance_matrix(values)
        cat_index = {float(cat): idx for idx, cat in enumerate(categories)}
        observed_num = 0.0
        for _, row in wide.iterrows():
            vals = pd.to_numeric(row, errors="coerce").dropna().to_numpy(dtype=float)
            m = len(vals)
            if m < 2:
                continue
            idx = [cat_index[float(v)] for v in vals]
            observed_num += float(dist[np.ix_(idx, idx)].sum()) / float(m - 1)
        counts = np.array([np.sum(values == cat) for cat in categories], dtype=float)
        expected_num = float((counts[:, None] * counts[None, :] * dist).sum())
    elif metric == "nominal":
        _, counts = np.unique(values, return_counts=True)
        counts = counts.astype(float)
        expected_num = float(values.size ** 2 - np.sum(counts ** 2))
    else:
        mean_value = float(np.mean(values))
        expected_num = float(2.0 * values.size * np.sum((values - mean_value) ** 2))

    observed_disagreement = float(observed_num / ratings_used) if ratings_used else np.nan
    expected_disagreement = (
        float(expected_num / (ratings_used * (ratings_used - 1)))
        if ratings_used > 1 else np.nan
    )
    alpha_value = (
        float(1.0 - observed_disagreement / expected_disagreement)
        if np.isfinite(observed_disagreement)
        and np.isfinite(expected_disagreement)
        and expected_disagreement > 0
        else np.nan
    )
    status, plain = _krippendorff_alpha_status(alpha_value)

    coverage_rows = []
    for col in wide.columns:
        vals = pd.to_numeric(wide[col], errors="coerce").dropna()
        coverage_rows.append({
            "Facet": target_facet,
            "Element": col,
            "Ratings": int(len(vals)),
            "MeanScore": float(vals.mean()) if len(vals) else np.nan,
            "MissingUnits": int(wide[col].isna().sum()),
        })

    summary = pd.DataFrame([{
        "Facet": target_facet,
        "DistanceMetric": metric,
        "KrippendorffAlpha": alpha_value,
        "Status": status,
        "PlainLanguage": plain,
        "Units": units,
        "Elements": elements,
        "PairableUnits": pairable_units,
        "UnitsWithSingleRating": units_with_single_rating,
        "RatingsUsed": ratings_used,
        "MissingCells": missing_cells,
        "ObservedDisagreement": observed_disagreement,
        "ExpectedDisagreement": expected_disagreement,
        "ContextColumns": meta.get("ContextColumns", ""),
        "Aggregation": meta.get("Aggregation", "mean"),
        "Caveat": caveat,
    }])
    return {"summary": summary, "coverage": pd.DataFrame(coverage_rows)}


def calc_krippendorff_alpha_by_facet(
    obs_df: pd.DataFrame,
    facet_cols: list[str],
    *,
    metrics: tuple[str, ...] = KRIPPENDORFF_ALPHA_METRICS,
) -> pd.DataFrame:
    """Compute experimental Krippendorff alpha summaries for each non-person facet."""
    rows: list[pd.DataFrame] = []
    target_facets = [facet for facet in facet_cols if facet != "Person"]
    for facet in target_facets:
        for metric in metrics:
            result = calc_krippendorff_alpha(obs_df, facet_cols, facet, metric=metric)
            summary = result.get("summary", pd.DataFrame())
            if isinstance(summary, pd.DataFrame) and not summary.empty:
                rows.append(summary)
    if not rows:
        return pd.DataFrame()
    return pd.concat(rows, ignore_index=True)


QC_DECISION_STATUS_ORDER: dict[str, int] = {
    "Ready": 0,
    "OK": 0,
    "Caution": 1,
    "Missing evidence": 2,
    "Missing": 2,
    "Unavailable": 2,
    "Review": 3,
    "Review before reporting": 3,
    "Do not claim yet": 4,
}


def _qc_status_rank(status: object) -> int:
    text = str(status or "").strip()
    if text in QC_DECISION_STATUS_ORDER:
        return QC_DECISION_STATUS_ORDER[text]
    low = text.lower()
    if "do not" in low:
        return 4
    if "review" in low:
        return 3
    if "missing" in low or "unavailable" in low:
        return 2
    if "caution" in low:
        return 1
    return 0


def _qc_worst_status(statuses: Iterable[object]) -> str:
    normalized = [str(s or "Ready") for s in statuses]
    if not normalized:
        return "Missing evidence"
    return max(normalized, key=_qc_status_rank)


def _format_qc_pct(value: object) -> str:
    val = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
    if np.isfinite(val):
        return f"{float(val) * 100:.1f}%"
    return "not available"


def _format_qc_number(value: object, digits: int = 3) -> str:
    val = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
    if np.isfinite(val):
        return f"{float(val):.{digits}f}"
    return "not available"


def _qc_report_blocking(status: object) -> str:
    rank = _qc_status_rank(status)
    if rank >= 2:
        return "Yes"
    if rank == 1:
        return "Caveat"
    return "No"


def _qc_priority_from_status(status: object) -> str:
    rank = _qc_status_rank(status)
    if rank >= 3:
        return "High"
    if rank == 2:
        return "Medium"
    if rank == 1:
        return "Low"
    return "Routine"


def _result_facet_names(result: dict, diagnostics: dict | None = None, facet_cols: list[str] | None = None) -> list[str]:
    candidates: list[object] = []
    if facet_cols:
        candidates.extend(facet_cols)
    if isinstance(result, dict):
        candidates.extend(result.get("config", {}).get("facet_names", []) or [])
    obs_df = diagnostics.get("obs") if isinstance(diagnostics, dict) else pd.DataFrame()
    if isinstance(obs_df, pd.DataFrame) and not obs_df.empty:
        candidates.extend([c for c in obs_df.columns if c not in {"Observed", "Score", "Weight"}])
    out: list[str] = []
    for value in candidates:
        name = str(value)
        if not name or name == "Person" or name in out:
            continue
        out.append(name)
    return out


def _infer_facet_by_role(
    result: dict,
    diagnostics: dict,
    facet_cols: list[str] | None,
    role: str,
) -> str | None:
    facets = _result_facet_names(result, diagnostics, facet_cols)
    if not facets:
        return None
    role = str(role or "").lower()
    patterns = list(_COLUMN_ROLE_PATTERNS.get(role, ()))
    if role == "criterion":
        patterns.extend(["domain", "trait", "scale", "aspect", "基準"])
    if role == "rater":
        patterns.extend(["reader", "assessor"])
    lowered = {facet: str(facet).lower() for facet in facets}
    for pattern in patterns:
        p = str(pattern).lower()
        for facet, low in lowered.items():
            if low == p:
                return facet
    for pattern in patterns:
        p = str(pattern).lower()
        for facet, low in lowered.items():
            if p and p in low:
                return facet
    return facets[0]


def _agreement_summary_for_facet(result: dict, diagnostics: dict, facet_cols: list[str], target_facet: str | None) -> pd.DataFrame:
    obs_df = diagnostics.get("obs", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()
    if not isinstance(obs_df, pd.DataFrame) or obs_df.empty or not target_facet:
        return pd.DataFrame()
    all_facet_cols = ["Person"] + [facet for facet in facet_cols if facet != "Person"]
    try:
        agreement = calc_interrater_agreement(obs_df, all_facet_cols, target_facet, res=result)
    except Exception:
        return pd.DataFrame()
    summary = agreement.get("summary", pd.DataFrame()) if isinstance(agreement, dict) else pd.DataFrame()
    return summary if isinstance(summary, pd.DataFrame) else pd.DataFrame()


def _ordinal_alpha_summary_for_facet(result: dict, diagnostics: dict, facet_cols: list[str], target_facet: str | None) -> pd.DataFrame:
    if not target_facet:
        return pd.DataFrame()
    alpha_tbl = diagnostics.get("krippendorff_alpha", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()
    if isinstance(alpha_tbl, pd.DataFrame) and not alpha_tbl.empty:
        sub = alpha_tbl.loc[
            (alpha_tbl.get("Facet", pd.Series(dtype=object)).astype(str) == str(target_facet))
            & (alpha_tbl.get("DistanceMetric", pd.Series(dtype=object)).astype(str).str.lower() == "ordinal")
        ].copy()
        if not sub.empty:
            return sub.head(1)
    obs_df = diagnostics.get("obs", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()
    if not isinstance(obs_df, pd.DataFrame) or obs_df.empty:
        return pd.DataFrame()
    try:
        out = calc_krippendorff_alpha(obs_df, ["Person"] + [f for f in facet_cols if f != "Person"], target_facet, metric="ordinal")
    except Exception:
        return pd.DataFrame()
    summary = out.get("summary", pd.DataFrame()) if isinstance(out, dict) else pd.DataFrame()
    return summary if isinstance(summary, pd.DataFrame) else pd.DataFrame()


def _facet_fit_review_summary(diagnostics: dict, target_facet: str | None) -> tuple[str, str, str]:
    if not target_facet or not isinstance(diagnostics, dict):
        return "Missing evidence", "rater facet not identified", "Confirm the rater facet before interpreting rater fit."
    fit_tbl = diagnostics.get("fit", pd.DataFrame())
    if not isinstance(fit_tbl, pd.DataFrame) or fit_tbl.empty:
        fit_tbl = diagnostics.get("measures", pd.DataFrame())
    if not isinstance(fit_tbl, pd.DataFrame) or fit_tbl.empty:
        return "Missing evidence", "fit table unavailable", "Run element fit diagnostics before final scoring-quality claims."
    if "Facet" in fit_tbl.columns:
        sub = fit_tbl.loc[fit_tbl["Facet"].astype(str) == str(target_facet)].copy()
    else:
        sub = fit_tbl.copy()
    if sub.empty:
        return "Missing evidence", f"no fit rows for {target_facet}", "Check whether the selected facet is represented in the fit table."

    flags = pd.Series(False, index=sub.index)
    evidence: list[str] = []
    for col in ("Infit", "Outfit"):
        if col in sub.columns:
            vals = pd.to_numeric(sub[col], errors="coerce")
            bad = vals.notna() & ((vals < 0.5) | (vals > 1.5))
            flags = flags | bad
            if bool(bad.any()):
                evidence.append(f"{col} outside 0.5-1.5 for {int(bad.sum())} element(s)")
    for col in ("InfitZSTD", "OutfitZSTD", "InfitZStd", "OutfitZStd"):
        if col in sub.columns:
            vals = pd.to_numeric(sub[col], errors="coerce")
            bad = vals.abs() >= 2.0
            flags = flags | bad.fillna(False)
            if bool(bad.any()):
                evidence.append(f"|{col}| >= 2 for {int(bad.sum())} element(s)")
    flagged_levels = "none"
    if bool(flags.any()):
        level_col = "Level" if "Level" in sub.columns else sub.columns[0]
        flagged_levels = _compact_value_list(sub.loc[flags, level_col].tolist(), max_items=8)
        return (
            "Review",
            f"{'; '.join(evidence)}; flagged elements: {flagged_levels}",
            "Use this to target rater training or moderation, then rerun the model after documented remediation.",
        )
    return (
        "Ready",
        f"{len(sub)} {target_facet} element(s) checked; no Infit/Outfit or ZSTD review flags under conservative bands",
        "Report rater fit together with agreement evidence; keep the fit bands visible for auditability.",
    )


def _scoring_decision_rule(area: object) -> str:
    rules = {
        "Overall scoring consistency": "Worst status across agreement, alpha, rater fit, and category-functioning rows.",
        "Exact/adjacent agreement": "Ready if exact agreement >= 70% and adjacent agreement >= 85%; Caution if adjacent agreement >= 75%; Review otherwise.",
        "Krippendorff alpha": "Ready if ordinal alpha >= .80; Caution if .67 <= alpha < .80; Review if alpha < .67; Missing evidence if not estimable.",
        "Rater fit/severity": "Ready when no selected-facet elements are outside Infit/Outfit 0.5-1.5 and no |ZSTD| >= 2 flags are present.",
        "Rubric/category functioning": "Uses the integrated rating-scale decision table: category counts, average measures, thresholds, curves, and fit.",
        "Category collapse readiness": "Review means adjacent-category sensitivity analysis is justified only if rubric logic also supports it.",
    }
    return rules.get(str(area), "Conservative evidence rule; inspect the listed evidence file before reporting.")


def _scoring_plain_language(area: object, status: object) -> str:
    area = str(area)
    status = str(status)
    if area == "Overall scoring consistency":
        if _qc_status_rank(status) <= 1:
            return "The scoring-quality claim can be drafted, with caveats matched to the evidence rows."
        return "The report should pause here until the blocking evidence rows are resolved or explicitly caveated."
    if area == "Exact/adjacent agreement":
        return "This is the easiest agreement evidence for scoring managers to audit."
    if area == "Krippendorff alpha":
        return "This summarizes shared-context agreement across raters/elements, but it is not MFRM reliability."
    if area == "Rater fit/severity":
        return "This is the FACETS-familiar check for whether rater behavior is model-consistent."
    if area == "Rubric/category functioning":
        return "This checks whether the score categories can support the intended rubric interpretation."
    if area == "Category collapse readiness":
        return "This keeps recoding as a documented sensitivity analysis rather than a hidden repair."
    return "Use this row to decide whether the related manuscript claim is ready."


def _scoring_next_checkpoint(area: object, status: object) -> str:
    area = str(area)
    status = str(status)
    if _qc_status_rank(status) <= 1:
        if area == "Overall scoring consistency":
            return "Copy only claims whose supporting rows are Ready or Caution."
        return "Archive the evidence file and keep the safe wording visible in the manuscript notes."
    if area == "Exact/adjacent agreement":
        return "Open agreement_pairs.csv, identify the worst pair(s), and check whether the disagreement is localized."
    if area == "Krippendorff alpha":
        return "Check pairable-unit coverage and compare ordinal alpha with exact/adjacent agreement."
    if area == "Rater fit/severity":
        return "Inspect flagged rater rows, conduct training/moderation if needed, and rerun diagnostics."
    if area == "Rubric/category functioning":
        return "Open rating-scale decision support and category curves before revising rubric wording."
    if area == "Category collapse readiness":
        return "Plan original-vs-collapsed sensitivity runs only for adjacent categories with substantive justification."
    return "Resolve this evidence row before final manuscript wording."


def _scoring_facets_crosswalk(area: object) -> str:
    crosswalk = {
        "Overall scoring consistency": "FACETS-style synthesis of agreement, fit, and category evidence.",
        "Exact/adjacent agreement": "FACETS Table 8-style agreement screen.",
        "Krippendorff alpha": "Agreement supplement to Table 8; not a FACETS replacement statistic.",
        "Rater fit/severity": "FACETS measurement report: rater measures, Infit/Outfit, ZSTD.",
        "Rubric/category functioning": "FACETS Categories/Steps: category counts, averages, thresholds, and curves.",
        "Category collapse readiness": "FACETS-style recoding review after category/step evidence.",
    }
    return crosswalk.get(str(area), "FACETS-style diagnostic evidence.")


def _scoring_primary_audience(area: object) -> str:
    audiences = {
        "Overall scoring consistency": "Paper author; scoring manager",
        "Exact/adjacent agreement": "Scoring manager; non-specialist reviewer",
        "Krippendorff alpha": "Paper author; measurement practitioner",
        "Rater fit/severity": "Measurement practitioner; scoring manager",
        "Rubric/category functioning": "Rubric owner; measurement practitioner",
        "Category collapse readiness": "Rubric owner; paper author",
    }
    return audiences.get(str(area), "Paper author")


def _refine_scoring_decision_table(table: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(table, pd.DataFrame) or table.empty:
        return pd.DataFrame()
    out = table.copy()
    out["SeverityRank"] = out["Status"].apply(_qc_status_rank)
    out["ReportBlocking"] = out["Status"].apply(_qc_report_blocking)
    out["Priority"] = out["Status"].apply(_qc_priority_from_status)
    out["DecisionRule"] = out["DecisionArea"].apply(_scoring_decision_rule)
    out["PlainLanguageSummary"] = [
        _scoring_plain_language(area, status)
        for area, status in zip(out["DecisionArea"], out["Status"])
    ]
    out["NextCheckpoint"] = [
        _scoring_next_checkpoint(area, status)
        for area, status in zip(out["DecisionArea"], out["Status"])
    ]
    out["FACETSCrosswalk"] = out["DecisionArea"].apply(_scoring_facets_crosswalk)
    out["PrimaryAudience"] = out["DecisionArea"].apply(_scoring_primary_audience)
    preferred = [
        "DecisionArea", "Status", "ReportBlocking", "Priority", "SeverityRank",
        "PlainLanguageSummary", "PrimaryEvidence", "DecisionRule", "Interpretation",
        "RecommendedAction", "NextCheckpoint", "APAReporting", "FACETSCrosswalk",
        "PrimaryAudience", "EvidenceFile", "DoNotClaim",
    ]
    return out.loc[:, [col for col in preferred if col in out.columns]]


def build_krippendorff_alpha_interpretation(
    result: dict,
    diagnostics: dict,
    facet_cols: list[str] | None = None,
) -> pd.DataFrame:
    """Add reporting guidance to the experimental Krippendorff alpha table."""
    facets = _result_facet_names(result, diagnostics, facet_cols)
    alpha_tbl = diagnostics.get("krippendorff_alpha", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()
    if (not isinstance(alpha_tbl, pd.DataFrame) or alpha_tbl.empty) and isinstance(diagnostics, dict):
        obs_df = diagnostics.get("obs", pd.DataFrame())
        if isinstance(obs_df, pd.DataFrame) and not obs_df.empty and facets:
            alpha_tbl = calc_krippendorff_alpha_by_facet(obs_df, ["Person"] + facets)
    if not isinstance(alpha_tbl, pd.DataFrame) or alpha_tbl.empty:
        return pd.DataFrame([{
            "Facet": "",
            "DistanceMetric": "ordinal",
            "KrippendorffAlpha": np.nan,
            "Status": "Missing evidence",
            "PlainLanguage": "Krippendorff alpha was not available from the current shared-context design.",
            "RecommendedAction": "Confirm that at least two elements score the same persons/items/criteria before using alpha.",
            "ReportWording": "Krippendorff's alpha was not estimated because the shared-context requirement was not met.",
            "DoNotClaim": "Do not report alpha or general inter-element consistency without shared-context evidence.",
            "EvidenceFile": "krippendorff_alpha_experimental.csv",
        }])

    rows = []
    for _, row in alpha_tbl.iterrows():
        status = str(row.get("Status", "Missing evidence"))
        alpha = pd.to_numeric(pd.Series([row.get("KrippendorffAlpha")]), errors="coerce").iloc[0]
        metric = str(row.get("DistanceMetric", "ordinal"))
        facet = str(row.get("Facet", ""))
        if status == "Ready":
            action = "Use as supporting agreement evidence; still report MFRM rater fit and category diagnostics."
            wording = f"For {facet}, Krippendorff's alpha ({metric}) was {_format_qc_number(alpha)}, indicating high shared-context agreement."
            do_not = "Do not present alpha as a replacement for MFRM reliability, severity, bias, or category diagnostics."
        elif status == "Caution":
            action = "Inspect pairwise agreement, rater fit, and category functioning before making strong scoring-quality claims."
            wording = f"For {facet}, Krippendorff's alpha ({metric}) was {_format_qc_number(alpha)}, suggesting moderate agreement that should be interpreted with other diagnostics."
            do_not = "Do not claim uniformly high agreement from alpha alone."
        elif status == "Review":
            action = "Prioritize scoring-design review, rater training, rubric clarification, or category sensitivity analysis before final reporting."
            wording = f"For {facet}, Krippendorff's alpha ({metric}) was {_format_qc_number(alpha)}, indicating that agreement evidence requires review."
            do_not = "Do not claim acceptable agreement until the source of disagreement is investigated and rerun evidence is documented."
        else:
            action = "Confirm shared scoring contexts and rerun the agreement panel."
            wording = f"For {facet}, Krippendorff's alpha ({metric}) was not available."
            do_not = "Do not report alpha when the design does not provide pairable shared contexts."
        rows.append({
            "Facet": facet,
            "DistanceMetric": metric,
            "KrippendorffAlpha": alpha,
            "Status": status,
            "PlainLanguage": str(row.get("PlainLanguage", "")),
            "RecommendedAction": action,
            "ReportWording": wording,
            "DoNotClaim": do_not,
            "EvidenceFile": "krippendorff_alpha_experimental.csv",
        })
    return pd.DataFrame(rows)


def build_scoring_consistency_decision(
    result: dict,
    diagnostics: dict,
    facet_cols: list[str] | None = None,
    *,
    rater_facet: str | None = None,
    criterion_facet: str | None = None,
) -> pd.DataFrame:
    """Create a conservative QC decision table for scoring consistency."""
    facets = _result_facet_names(result, diagnostics, facet_cols)
    rater_facet = rater_facet or _infer_facet_by_role(result, diagnostics, facets, "rater")
    criterion_facet = criterion_facet or _infer_facet_by_role(result, diagnostics, facets, "criterion")
    rows: list[dict[str, str]] = []

    agreement_summary = _agreement_summary_for_facet(result, diagnostics, facets, rater_facet)
    if isinstance(agreement_summary, pd.DataFrame) and not agreement_summary.empty:
        row = agreement_summary.iloc[0]
        exact = pd.to_numeric(pd.Series([row.get("ExactAgreement")]), errors="coerce").iloc[0]
        adjacent = pd.to_numeric(pd.Series([row.get("AdjacentAgreement")]), errors="coerce").iloc[0]
        contexts = row.get("Contexts", "not available")
        if np.isfinite(exact) and np.isfinite(adjacent):
            status = "Ready" if exact >= 0.70 and adjacent >= 0.85 else ("Caution" if adjacent >= 0.75 else "Review")
            evidence = f"exact = {_format_qc_pct(exact)}; adjacent = {_format_qc_pct(adjacent)}; shared contexts = {contexts}"
        else:
            status = "Missing evidence"
            evidence = f"exact/adjacent agreement unavailable; shared contexts = {contexts}"
    else:
        status = "Missing evidence"
        evidence = f"agreement summary unavailable for {rater_facet or 'selected facet'}"
    rows.append({
        "DecisionArea": "Exact/adjacent agreement",
        "Status": status,
        "PrimaryEvidence": evidence,
        "Interpretation": "Shared-context agreement is the most intuitive check for scoring consistency.",
        "RecommendedAction": (
            "Use as report-ready supporting evidence."
            if status == "Ready" else
            "Inspect pairwise rows and scoring design before making strong agreement claims."
        ),
        "APAReporting": (
            "Report exact and adjacent agreement percentages for the rater facet."
            if status != "Missing evidence" else
            "State that exact/adjacent agreement was not estimable from the current shared-context design."
        ),
        "EvidenceFile": "agreement_summary.csv; agreement_pairs.csv",
        "DoNotClaim": "Do not infer agreement for raters who did not score common persons/items/criteria.",
    })

    alpha_summary = _ordinal_alpha_summary_for_facet(result, diagnostics, facets, rater_facet)
    if isinstance(alpha_summary, pd.DataFrame) and not alpha_summary.empty:
        alpha_row = alpha_summary.iloc[0]
        alpha_status = str(alpha_row.get("Status", "Missing evidence"))
        alpha_value = alpha_row.get("KrippendorffAlpha", np.nan)
        alpha_evidence = (
            f"ordinal alpha = {_format_qc_number(alpha_value)}; pairable units = "
            f"{alpha_row.get('PairableUnits', 'not available')}; elements = {alpha_row.get('Elements', 'not available')}"
        )
        alpha_action = str(alpha_row.get("PlainLanguage", "Read with pairwise agreement and MFRM diagnostics."))
    else:
        alpha_status = "Missing evidence"
        alpha_evidence = "ordinal Krippendorff alpha unavailable"
        alpha_action = "Confirm at least two raters scored the same shared contexts."
    rows.append({
        "DecisionArea": "Krippendorff alpha",
        "Status": alpha_status if alpha_status in {"Ready", "Caution", "Review"} else "Missing evidence",
        "PrimaryEvidence": alpha_evidence,
        "Interpretation": "Alpha summarizes agreement across all pairable scoring contexts while respecting ordered categories.",
        "RecommendedAction": alpha_action,
        "APAReporting": "Report ordinal alpha as an agreement check, not as MFRM reliability.",
        "EvidenceFile": "krippendorff_alpha_experimental.csv; krippendorff_alpha_interpretation.csv",
        "DoNotClaim": "Do not use alpha alone to identify a specific problematic rater or rubric category.",
    })

    fit_status, fit_evidence, fit_action = _facet_fit_review_summary(diagnostics, rater_facet)
    rows.append({
        "DecisionArea": "Rater fit/severity",
        "Status": fit_status,
        "PrimaryEvidence": fit_evidence,
        "Interpretation": "MFRM fit and severity locate whether scoring behavior is model-consistent after accounting for other facets.",
        "RecommendedAction": fit_action,
        "APAReporting": "Report rater fit/severity evidence together with agreement so FACETS users can audit the scoring-quality claim.",
        "EvidenceFile": "fit_statistics.csv; measures.csv",
        "DoNotClaim": "Do not treat high agreement as sufficient when rater fit or severity evidence is flagged.",
    })

    try:
        category_decisions = rating_scale_decision_support_table(result, diagnostics)
    except Exception:
        category_decisions = pd.DataFrame()
    if isinstance(category_decisions, pd.DataFrame) and not category_decisions.empty:
        category_overall = category_decisions.iloc[0]
        cat_status_raw = str(category_overall.get(
            "DecisionStatus",
            category_overall.get("Decision", category_overall.get("Status", "Missing evidence")),
        ))
        cat_status = "Review" if "Do not" in cat_status_raw or "Review" in cat_status_raw else ("Missing evidence" if "Missing" in cat_status_raw else "Ready")
        cat_evidence = str(category_overall.get(
            "PrimaryEvidence",
            category_overall.get("Evidence", category_overall.get("TriggerEvidence", "")),
        ))
        cat_action = str(category_overall.get(
            "RecommendedAction",
            category_overall.get("Action", ""),
        ))
    else:
        cat_status = "Missing evidence"
        cat_evidence = "rating-scale decision support unavailable"
        cat_action = "Run category counts, threshold order, and category curve diagnostics."
    rows.append({
        "DecisionArea": "Rubric/category functioning",
        "Status": cat_status,
        "PrimaryEvidence": cat_evidence,
        "Interpretation": "Scoring consistency is only useful if the rubric categories themselves function as ordered, distinct score levels.",
        "RecommendedAction": cat_action,
        "APAReporting": "Report category support, threshold order, and curve evidence before claiming that the rubric categories function distinctly.",
        "EvidenceFile": "rating_scale_decision_support.csv; category_evidence.csv",
        "DoNotClaim": "Do not report category distinctness or collapse categories from one diagnostic alone.",
    })

    collapse_status = "Review" if cat_status == "Review" else ("Missing evidence" if cat_status == "Missing evidence" else "Ready")
    rows.append({
        "DecisionArea": "Category collapse readiness",
        "Status": collapse_status,
        "PrimaryEvidence": (
            "category diagnostics flagged review evidence"
            if collapse_status == "Review" else
            "category-collapse evidence incomplete"
            if collapse_status == "Missing evidence" else
            "no integrated category-collapse trigger in the current diagnostics"
        ),
        "Interpretation": "Category collapse should be treated as a planned sensitivity analysis, not an automatic repair.",
        "RecommendedAction": (
            "Compare original scoring against substantively justified adjacent-category recodes and rerun all diagnostics."
            if collapse_status == "Review" else
            "Retain original categories unless theory or response-process evidence justifies a sensitivity run."
        ),
        "APAReporting": "If recoding is evaluated, describe it as sensitivity analysis and report why the final scoring rule was selected.",
        "EvidenceFile": "rating_scale_recode_candidates.csv; rating_scale_decision_support.csv",
        "DoNotClaim": "Do not collapse categories solely to improve fit or agreement statistics.",
    })

    overall_status = _qc_worst_status([row["Status"] for row in rows])
    overall_action = (
        "Proceed with report-ready scoring-quality language while retaining diagnostic caveats."
        if overall_status == "Ready" else
        "Resolve review/missing evidence rows before making strong claims about scoring quality."
    )
    overall = {
        "DecisionArea": "Overall scoring consistency",
        "Status": overall_status,
        "PrimaryEvidence": (
            f"rater facet = {rater_facet or 'not identified'}; criterion facet = {criterion_facet or 'not identified'}; "
            f"worst evidence status = {overall_status}"
        ),
        "Interpretation": "This row integrates agreement, MFRM rater evidence, and category-functioning evidence for scoring-quality decisions.",
        "RecommendedAction": overall_action,
        "APAReporting": "Use the APA draft only after matching each claim to the evidence files listed in this table.",
        "EvidenceFile": "scoring_consistency_decision.csv",
        "DoNotClaim": "Do not state that scoring is publication-ready if any key evidence row is Review or Missing evidence.",
    }
    decision_table = pd.concat([pd.DataFrame([overall]), pd.DataFrame(rows)], ignore_index=True)
    return _refine_scoring_decision_table(decision_table)


def build_quality_control_recommendations(
    result: dict,
    diagnostics: dict,
    facet_cols: list[str] | None = None,
    *,
    rater_facet: str | None = None,
    criterion_facet: str | None = None,
) -> pd.DataFrame:
    """Turn scoring-consistency evidence into action-oriented QC recommendations."""
    decision = build_scoring_consistency_decision(
        result,
        diagnostics,
        facet_cols,
        rater_facet=rater_facet,
        criterion_facet=criterion_facet,
    )
    if decision.empty:
        return pd.DataFrame()

    def _area_status(area: str) -> str:
        sub = decision.loc[decision["DecisionArea"] == area, "Status"]
        return str(sub.iloc[0]) if not sub.empty else "Missing evidence"

    def _area_evidence(area: str) -> str:
        sub = decision.loc[decision["DecisionArea"] == area, "PrimaryEvidence"]
        return str(sub.iloc[0]) if not sub.empty else "not available"

    agreement_status = _qc_worst_status([_area_status("Exact/adjacent agreement"), _area_status("Krippendorff alpha")])
    rater_status = _area_status("Rater fit/severity")
    category_status = _area_status("Rubric/category functioning")
    collapse_status = _area_status("Category collapse readiness")
    overall_status = _area_status("Overall scoring consistency")

    rows = [
        {
            "QCDecision": "Rater training",
            "Recommendation": "Prioritize" if _qc_status_rank(_qc_worst_status([agreement_status, rater_status])) >= 3 else "Monitor",
            "Priority": "High" if _qc_status_rank(_qc_worst_status([agreement_status, rater_status])) >= 3 else "Routine",
            "TriggerEvidence": f"agreement: {_area_evidence('Exact/adjacent agreement')}; alpha: {_area_evidence('Krippendorff alpha')}; fit: {_area_evidence('Rater fit/severity')}",
            "Action": (
                "Review anchor papers, conduct adjudication/moderation, document training changes, and rerun agreement plus MFRM fit."
                if _qc_status_rank(_qc_worst_status([agreement_status, rater_status])) >= 3 else
                "Keep standard calibration records and monitor pairwise agreement in future scoring cycles."
            ),
            "ReportableWording": "Rater training was evaluated using agreement and MFRM rater diagnostics.",
            "DoNotClaim": "Do not attribute disagreement to rater behavior without checking rubric/category evidence.",
            "EvidenceFile": "scoring_consistency_decision.csv; agreement_pairs.csv; fit_statistics.csv",
        },
        {
            "QCDecision": "Rubric revision",
            "Recommendation": "Prioritize" if _qc_status_rank(category_status) >= 3 else "Monitor",
            "Priority": "High" if _qc_status_rank(category_status) >= 3 else "Routine",
            "TriggerEvidence": _area_evidence("Rubric/category functioning"),
            "Action": (
                "Inspect category labels, descriptors, anchor examples, and response-process notes before altering the scoring rule."
                if _qc_status_rank(category_status) >= 3 else
                "Retain rubric wording while keeping category evidence in the audit trail."
            ),
            "ReportableWording": "Rubric/category functioning was reviewed with category support, thresholds, and category-curve evidence.",
            "DoNotClaim": "Do not revise the rubric only because one statistic was unfavorable.",
            "EvidenceFile": "rating_scale_decision_support.csv; category_evidence.csv",
        },
        {
            "QCDecision": "Category collapse",
            "Recommendation": "Sensitivity analysis" if _qc_status_rank(collapse_status) >= 3 else "Not indicated",
            "Priority": "Medium" if _qc_status_rank(collapse_status) >= 3 else "Routine",
            "TriggerEvidence": _area_evidence("Category collapse readiness"),
            "Action": (
                "Fit original and adjacent-category recode candidates, compare diagnostics, then justify the final scoring rule substantively."
                if _qc_status_rank(collapse_status) >= 3 else
                "Use the original category structure as the primary analysis unless planned rubric evidence suggests otherwise."
            ),
            "ReportableWording": "Category collapse, if used, should be reported as a sensitivity comparison with retained original-scale evidence.",
            "DoNotClaim": "Do not present collapsed categories as an automatic correction.",
            "EvidenceFile": "rating_scale_recode_candidates.csv; rating_scale_decision_support.csv",
        },
        {
            "QCDecision": "Agreement claim",
            "Recommendation": "Report with caveat" if _qc_status_rank(overall_status) <= 1 else "Withhold strong claim",
            "Priority": "Manuscript" if _qc_status_rank(overall_status) <= 1 else "High",
            "TriggerEvidence": _area_evidence("Overall scoring consistency"),
            "Action": (
                "Use exact/adjacent agreement, ordinal alpha, rater fit, and category diagnostics in one paragraph."
                if _qc_status_rank(overall_status) <= 1 else
                "First resolve rows marked Review or Missing evidence; then regenerate the APA draft."
            ),
            "ReportableWording": "Scoring consistency was interpreted as a converging evidence claim, not a single-index claim.",
            "DoNotClaim": "Do not say the scoring system is reliable solely from exact agreement or alpha.",
            "EvidenceFile": "apa_scoring_quality_draft.md; scoring_consistency_decision.csv",
        },
    ]
    out = pd.DataFrame(rows)
    linked_area = {
        "Rater training": "Rater fit/severity",
        "Rubric revision": "Rubric/category functioning",
        "Category collapse": "Category collapse readiness",
        "Agreement claim": "Overall scoring consistency",
    }
    owner = {
        "Rater training": "Scoring manager",
        "Rubric revision": "Rubric owner",
        "Category collapse": "Measurement practitioner; paper author",
        "Agreement claim": "Paper author",
    }
    completion = {
        "Rater training": "Training/moderation decision is documented and agreement plus rater-fit evidence has been rerun or explicitly caveated.",
        "Rubric revision": "Rubric wording, anchor examples, and category evidence are aligned before final scoring claims.",
        "Category collapse": "Original and candidate recode runs are compared, or a written decision explains why no recode is used.",
        "Agreement claim": "Every manuscript sentence is linked to an evidence file and no Review/Missing row is ignored.",
    }
    risk = {
        "Rater training": "Unresolved rater evidence can make score decisions appear more stable than the scoring process supports.",
        "Rubric revision": "Weak category evidence can make rubric interpretations overstate what the score scale distinguishes.",
        "Category collapse": "Unplanned recoding can look like data-driven score repair and weaken reproducibility.",
        "Agreement claim": "A single-index claim can overstate reliability and confuse agreement with MFRM measurement evidence.",
    }
    stop_rule = {
        "Rater training": "Stop when flagged rater evidence is resolved, documented, or transparently reported as a limitation.",
        "Rubric revision": "Stop when category-functioning evidence and rubric language point to the same interpretation.",
        "Category collapse": "Stop when the original scoring rule is retained or the selected recode has both statistical and rubric justification.",
        "Agreement claim": "Stop when the APA draft contains only claims supported by the exported tables.",
    }
    out["LinkedDecisionArea"] = out["QCDecision"].map(linked_area).fillna("")
    out["OwnerRole"] = out["QCDecision"].map(owner).fillna("Paper author")
    out["CompletionCriterion"] = out["QCDecision"].map(completion).fillna("Decision is documented and evidence files are archived.")
    out["RiskIfSkipped"] = out["QCDecision"].map(risk).fillna("The report may overstate the available evidence.")
    out["WhenToStop"] = out["QCDecision"].map(stop_rule).fillna("Stop when the claim has explicit evidence support.")
    preferred = [
        "QCDecision", "Recommendation", "Priority", "OwnerRole", "LinkedDecisionArea",
        "TriggerEvidence", "Action", "CompletionCriterion", "WhenToStop",
        "ReportableWording", "RiskIfSkipped", "DoNotClaim", "EvidenceFile",
    ]
    return out.loc[:, [col for col in preferred if col in out.columns]]


def build_quality_control_todo_checklist(
    result: dict,
    diagnostics: dict,
    facet_cols: list[str] | None = None,
    *,
    rater_facet: str | None = None,
    criterion_facet: str | None = None,
) -> pd.DataFrame:
    """Build a checkbox-ready QC checklist for non-specialist workflows."""
    decision = build_scoring_consistency_decision(
        result,
        diagnostics,
        facet_cols,
        rater_facet=rater_facet,
        criterion_facet=criterion_facet,
    )
    qc = build_quality_control_recommendations(
        result,
        diagnostics,
        facet_cols,
        rater_facet=rater_facet,
        criterion_facet=criterion_facet,
    )
    if decision.empty and qc.empty:
        return pd.DataFrame()

    def _decision_status(area: str) -> str:
        sub = decision.loc[decision["DecisionArea"] == area] if not decision.empty else pd.DataFrame()
        return str(sub.iloc[0].get("Status", "Missing evidence")) if not sub.empty else "Missing evidence"

    def _decision_evidence(area: str) -> str:
        sub = decision.loc[decision["DecisionArea"] == area] if not decision.empty else pd.DataFrame()
        return str(sub.iloc[0].get("PrimaryEvidence", "not available")) if not sub.empty else "not available"

    def _qc_row(name: str) -> pd.Series:
        sub = qc.loc[qc["QCDecision"] == name] if not qc.empty else pd.DataFrame()
        return sub.iloc[0] if not sub.empty else pd.Series(dtype=object)

    todo_specs = [
        (
            1,
            "Confirm shared-context design",
            "Overall scoring consistency",
            "Paper author",
            "Open the data audit and confirm that at least two raters/elements score common persons/items/criteria.",
            "Agreement metrics are interpretable because shared contexts are present.",
            "Prevents treating disconnected ratings as agreement evidence.",
            "agreement_summary.csv; response_data_audit_summary.csv",
            "Agreement claim",
        ),
        (
            2,
            "Inspect agreement and alpha together",
            "Krippendorff alpha",
            "Measurement practitioner",
            "Read exact/adjacent agreement, pairwise rows, ordinal alpha, and alpha coverage before summarizing agreement.",
            "Worst pair(s), pairable units, and alpha status are documented.",
            "Prevents one-index agreement claims.",
            "agreement_pairs.csv; krippendorff_alpha_interpretation.csv",
            "Agreement claim",
        ),
        (
            3,
            "Decide whether rater training is needed",
            "Rater fit/severity",
            "Scoring manager",
            str(_qc_row("Rater training").get("Action", "Review rater evidence and document the training decision.")),
            str(_qc_row("Rater training").get("CompletionCriterion", "Rater-training decision is documented.")),
            str(_qc_row("Rater training").get("RiskIfSkipped", "Rater evidence may remain unresolved.")),
            "fit_statistics.csv; measures.csv; agreement_pairs.csv",
            "Rater training",
        ),
        (
            4,
            "Decide whether rubric revision is needed",
            "Rubric/category functioning",
            "Rubric owner",
            str(_qc_row("Rubric revision").get("Action", "Review category evidence and rubric wording.")),
            str(_qc_row("Rubric revision").get("CompletionCriterion", "Rubric decision is documented.")),
            str(_qc_row("Rubric revision").get("RiskIfSkipped", "Rubric interpretation may overstate category evidence.")),
            "rating_scale_decision_support.csv; category_evidence.csv",
            "Rubric revision",
        ),
        (
            5,
            "Decide whether category collapse sensitivity is needed",
            "Category collapse readiness",
            "Measurement practitioner",
            str(_qc_row("Category collapse").get("Action", "Plan or reject adjacent-category sensitivity analysis with justification.")),
            str(_qc_row("Category collapse").get("CompletionCriterion", "Category-collapse decision is documented.")),
            str(_qc_row("Category collapse").get("RiskIfSkipped", "Recoding may appear data-driven or unjustified.")),
            "rating_scale_recode_candidates.csv; rating_scale_decision_support.csv",
            "Category collapse",
        ),
        (
            6,
            "Finalize APA scoring-quality wording",
            "Overall scoring consistency",
            "Paper author",
            str(_qc_row("Agreement claim").get("Action", "Regenerate the APA draft and link every claim to evidence files.")),
            str(_qc_row("Agreement claim").get("CompletionCriterion", "APA wording is evidence-linked and caveated.")),
            str(_qc_row("Agreement claim").get("RiskIfSkipped", "The manuscript may overclaim scoring quality.")),
            "apa_scoring_quality_draft.md; scoring_consistency_decision.csv",
            "Agreement claim",
        ),
    ]

    rows = []
    for order, item, area, owner, action, completion, why, evidence_file, qc_decision in todo_specs:
        status = _decision_status(area)
        rows.append({
            "Done": False,
            "Step": order,
            "ToDoItem": item,
            "BlockingForReport": _qc_report_blocking(status) == "Yes",
            "NeedsCaveat": _qc_report_blocking(status) == "Caveat",
            "Priority": _qc_priority_from_status(status),
            "StatusSource": status,
            "OwnerRole": owner,
            "WhyItMatters": why,
            "Action": action,
            "CompletionCriterion": completion,
            "EvidenceToOpen": evidence_file,
            "ClaimUnlocked": qc_decision,
            "LinkedDecisionArea": area,
            "EvidenceSnapshot": _decision_evidence(area),
            "FACETSCrosswalk": _scoring_facets_crosswalk(area),
        })
    return pd.DataFrame(rows)


def build_scoring_quality_first_read_summary(
    result: dict,
    diagnostics: dict,
    facet_cols: list[str] | None = None,
    *,
    rater_facet: str | None = None,
    criterion_facet: str | None = None,
) -> pd.DataFrame:
    """Return a one-row plain-language summary for the scoring-quality gate."""
    decision = build_scoring_consistency_decision(
        result,
        diagnostics,
        facet_cols,
        rater_facet=rater_facet,
        criterion_facet=criterion_facet,
    )
    todo = build_quality_control_todo_checklist(
        result,
        diagnostics,
        facet_cols,
        rater_facet=rater_facet,
        criterion_facet=criterion_facet,
    )
    if decision.empty and todo.empty:
        return pd.DataFrame()

    overall = decision.loc[decision["DecisionArea"] == "Overall scoring consistency"] if not decision.empty else pd.DataFrame()
    overall_row = overall.iloc[0] if not overall.empty else pd.Series(dtype=object)
    overall_status = str(overall_row.get("Status", "Missing evidence"))
    blocker_count = int(todo.get("BlockingForReport", pd.Series(dtype=bool)).fillna(False).astype(bool).sum()) if not todo.empty else 0
    caveat_count = int(todo.get("NeedsCaveat", pd.Series(dtype=bool)).fillna(False).astype(bool).sum()) if not todo.empty else 0

    if blocker_count > 0:
        readiness = "Do not report yet"
        can_use_draft = "No"
        safe_claim = "Use the APA draft only as an internal planning note until blocking QC items are resolved."
    elif caveat_count > 0 or _qc_status_rank(overall_status) == 1:
        readiness = "Report with caveats"
        can_use_draft = "Yes, after caveats are added"
        safe_claim = "Report scoring quality as converging evidence with explicit caveats."
    else:
        readiness = "Report-ready"
        can_use_draft = "Yes"
        safe_claim = "Draft the scoring-quality paragraph and link each claim to its evidence file."

    next_rows = pd.DataFrame()
    if not todo.empty:
        blockers = todo.loc[todo.get("BlockingForReport", pd.Series(False, index=todo.index)).fillna(False).astype(bool)]
        caveats = todo.loc[todo.get("NeedsCaveat", pd.Series(False, index=todo.index)).fillna(False).astype(bool)]
        if not blockers.empty:
            next_rows = blockers
        elif not caveats.empty:
            next_rows = caveats
        else:
            next_rows = todo.sort_values("Step").head(1)
    next_row = next_rows.sort_values("Step").iloc[0] if not next_rows.empty else pd.Series(dtype=object)

    return pd.DataFrame([{
        "ReadinessLabel": readiness,
        "OverallStatus": overall_status,
        "CanUseApaDraft": can_use_draft,
        "BlockingItems": blocker_count,
        "CaveatItems": caveat_count,
        "NextAction": str(next_row.get("Action", overall_row.get("NextCheckpoint", "Review the scoring consistency decision table."))),
        "NextOwner": str(next_row.get("OwnerRole", overall_row.get("PrimaryAudience", "Paper author"))),
        "WhyThisMatters": str(next_row.get("WhyItMatters", overall_row.get("PlainLanguageSummary", "Keeps the scoring-quality claim tied to evidence."))),
        "FirstEvidenceToOpen": str(next_row.get("EvidenceToOpen", overall_row.get("EvidenceFile", "scoring_consistency_decision.csv"))),
        "SafeClaim": safe_claim,
        "DoNotClaim": str(overall_row.get("DoNotClaim", "Do not state that scoring is report-ready before QC evidence supports it.")),
        "EvidenceFile": "scoring_quality_first_read_summary.csv; quality_control_todo_checklist.csv",
    }])


def scoring_quality_term_guide() -> pd.DataFrame:
    """Short QC-specific term guide for the agreement and scoring-quality panel."""
    rows = [
        {
            "Term": "Exact agreement",
            "PlainMeaning": "How often two elements gave the same score in the same shared context.",
            "WhyItMatters": "It is the easiest agreement number for scoring managers and reviewers to audit.",
            "LookAt": "agreement_summary.csv; agreement_pairs.csv",
            "DoNotConfuseWith": "MFRM reliability or rater severity.",
        },
        {
            "Term": "Adjacent agreement",
            "PlainMeaning": "How often scores were the same or only one category apart.",
            "WhyItMatters": "A one-category difference may be tolerable in some rubrics, but it still needs documentation.",
            "LookAt": "agreement_summary.csv; agreement_pairs.csv",
            "DoNotConfuseWith": "A guarantee that scoring is accurate.",
        },
        {
            "Term": "Krippendorff alpha",
            "PlainMeaning": "A shared-context agreement index that can account for ordered rating categories.",
            "WhyItMatters": "It summarizes agreement beyond one rater pair, but it does not explain why disagreement happened.",
            "LookAt": "krippendorff_alpha_interpretation.csv",
            "DoNotConfuseWith": "FACETS reliability, separation, severity, or bias diagnostics.",
        },
        {
            "Term": "Rater fit/severity",
            "PlainMeaning": "MFRM evidence about whether rater behavior is model-consistent and how severe or lenient raters are.",
            "WhyItMatters": "High agreement is not enough if rater fit or severity evidence is flagged.",
            "LookAt": "fit_statistics.csv; measures.csv",
            "DoNotConfuseWith": "A personal evaluation of a rater.",
        },
        {
            "Term": "Infit/Outfit",
            "PlainMeaning": "Mean-square fit statistics that flag unexpected or overly predictable scoring patterns.",
            "WhyItMatters": "They help locate scoring patterns that need moderation, training, or closer review.",
            "LookAt": "fit_statistics.csv",
            "DoNotConfuseWith": "Agreement percentages.",
        },
        {
            "Term": "ZSTD",
            "PlainMeaning": "A standardized fit signal; large absolute values are review flags, especially with fit mean-squares.",
            "WhyItMatters": "It helps prioritize which fit rows need attention, but large samples can make it sensitive.",
            "LookAt": "fit_statistics.csv",
            "DoNotConfuseWith": "A standalone removal rule.",
        },
        {
            "Term": "Category collapse",
            "PlainMeaning": "Combining adjacent score categories and rerunning the analysis as a sensitivity check.",
            "WhyItMatters": "It can be justified when categories do not function distinctly, but only with rubric logic.",
            "LookAt": "rating_scale_recode_candidates.csv; rating_scale_decision_support.csv",
            "DoNotConfuseWith": "An automatic way to improve model fit.",
        },
        {
            "Term": "Report blocking",
            "PlainMeaning": "A QC item that should be resolved before strong manuscript claims are made.",
            "WhyItMatters": "It prevents report-ready language from getting ahead of the evidence.",
            "LookAt": "quality_control_todo_checklist.csv",
            "DoNotConfuseWith": "A permanent failure of the scoring design.",
        },
        {
            "Term": "Needs caveat",
            "PlainMeaning": "A claim may be reported, but the limitation must be stated clearly.",
            "WhyItMatters": "It lets users report conservatively without hiding uncertainty.",
            "LookAt": "scoring_consistency_decision.csv; apa_scoring_quality_draft.md",
            "DoNotConfuseWith": "Full report readiness.",
        },
    ]
    return pd.DataFrame(rows)


def generate_apa_scoring_quality_draft(
    result: dict,
    diagnostics: dict,
    decision_table: pd.DataFrame | None = None,
    qc_table: pd.DataFrame | None = None,
) -> str:
    """Generate conservative APA-style manuscript text for scoring quality."""
    if decision_table is None or not isinstance(decision_table, pd.DataFrame) or decision_table.empty:
        decision_table = build_scoring_consistency_decision(result, diagnostics)
    if qc_table is None or not isinstance(qc_table, pd.DataFrame) or qc_table.empty:
        qc_table = build_quality_control_recommendations(result, diagnostics)

    config = result.get("config", {}) if isinstance(result, dict) else {}
    prep = result.get("prep", {}) if isinstance(result, dict) else {}
    obs_df = diagnostics.get("obs", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()
    model_name = str(config.get("model", "MFRM"))
    method_name = str(config.get("method", "estimation"))
    facet_names = [str(f) for f in config.get("facet_names", []) or []]
    n_obs = prep.get("n_obs")
    if n_obs is None and isinstance(obs_df, pd.DataFrame):
        n_obs = len(obs_df)
    n_person = prep.get("n_person")
    if n_person is None and isinstance(obs_df, pd.DataFrame) and "Person" in obs_df.columns:
        n_person = obs_df["Person"].nunique(dropna=True)
    context_text = (
        f"The analysis used a {model_name} many-facet Rasch specification estimated with {method_name}. "
        f"The scoring file included {n_obs if n_obs is not None else '[N]'} observations"
        + (f" from {n_person} persons" if n_person is not None else "")
        + (f" across the facets {', '.join(facet_names)}." if facet_names else ".")
    )

    def _decision(area: str, col: str, default: str = "not available") -> str:
        if not isinstance(decision_table, pd.DataFrame) or decision_table.empty:
            return default
        sub = decision_table.loc[decision_table["DecisionArea"] == area]
        if sub.empty or col not in sub.columns:
            return default
        return str(sub.iloc[0].get(col, default))

    overall_status = _decision("Overall scoring consistency", "Status", "Missing evidence")
    exact_evidence = _decision("Exact/adjacent agreement", "PrimaryEvidence")
    alpha_evidence = _decision("Krippendorff alpha", "PrimaryEvidence")
    rater_evidence = _decision("Rater fit/severity", "PrimaryEvidence")
    category_evidence = _decision("Rubric/category functioning", "PrimaryEvidence")
    collapse_action = _decision("Category collapse readiness", "RecommendedAction")
    qc_priorities = "not available"
    if isinstance(qc_table, pd.DataFrame) and not qc_table.empty and {"QCDecision", "Recommendation"}.issubset(qc_table.columns):
        qc_priorities = "; ".join(
            f"{row.get('QCDecision')}: {row.get('Recommendation')}"
            for _, row in qc_table.iterrows()
        )
    todo_table = build_quality_control_todo_checklist(result, diagnostics)
    first_read = build_scoring_quality_first_read_summary(result, diagnostics)
    blocking_count = 0
    caveat_count = 0
    if isinstance(todo_table, pd.DataFrame) and not todo_table.empty:
        blocking_count = int(todo_table.get("BlockingForReport", pd.Series(dtype=bool)).fillna(False).astype(bool).sum())
        caveat_count = int(todo_table.get("NeedsCaveat", pd.Series(dtype=bool)).fillna(False).astype(bool).sum())
    first_read_text = "First-read summary was not available."
    if isinstance(first_read, pd.DataFrame) and not first_read.empty:
        row = first_read.iloc[0]
        first_read_text = (
            f"First-read summary: {row.get('ReadinessLabel', 'not available')}. "
            f"Next action: {row.get('NextAction', 'not available')} "
            f"Responsible role: {row.get('NextOwner', 'not available')}. "
            f"First evidence file to open: {row.get('FirstEvidenceToOpen', 'not available')}."
        )

    caveat = (
        "The following text is a draft. Replace bracketed study details, verify numerical values against the exported tables, "
        "and align the wording with the journal's reporting requirements."
    )
    strength = (
        "supported publication-oriented interpretation"
        if _qc_status_rank(overall_status) <= 1 else
        "preliminary interpretation requiring follow-up before strong claims"
    )
    return "\n\n".join([
        "# APA Scoring Quality Draft",
        caveat,
        context_text,
        (
            f"Quality-control gate: {blocking_count} checklist item(s) were blocking final report-ready claims, "
            f"and {caveat_count} item(s) required explicit caveats. Treat this gate as a manuscript-preparation aid, "
            "not as a substitute for substantive scoring review."
        ),
        first_read_text,
        (
            f"Scoring quality was evaluated as a converging-evidence claim across shared-context agreement, "
            f"Krippendorff's alpha, many-facet Rasch rater diagnostics, and rating-scale/category functioning. "
            f"The integrated decision status was **{overall_status}**, indicating a {strength}."
        ),
        (
            f"For inter-element agreement, the primary shared-context evidence was: {exact_evidence}. "
            f"Krippendorff's alpha was used as an additional agreement check for ordered score categories: {alpha_evidence}. "
            "These agreement indices were interpreted as descriptive scoring-consistency evidence and were not treated as replacements "
            "for MFRM reliability, severity, fit, or bias diagnostics."
        ),
        (
            f"Rater evidence was reviewed using MFRM fit/severity diagnostics: {rater_evidence}. "
            "When rater evidence was flagged, the recommended interpretation was to use the result for rater training or moderation "
            "rather than to remove or relabel raters without documented scoring-process evidence."
        ),
        (
            f"Rubric and rating-category functioning were reviewed before making scoring-quality claims: {category_evidence}. "
            f"For category collapse decisions, the planned action was: {collapse_action} "
            "Category collapse should therefore be reported only as a substantively justified sensitivity analysis, not as an automatic statistical repair."
        ),
        (
            f"Quality-control priorities generated from the app were: {qc_priorities}. "
            "In the manuscript, each claim should be matched to the exported evidence files rather than reported from a single statistic."
        ),
        (
            "Suggested method citations for this scoring-quality paragraph: agreement and alpha "
            "(Krippendorff, 2004; Hayes & Krippendorff, 2007), rater-effect interpretation "
            "(Engelhard, 1994; Myford & Wolfe, 2003; Myford & Wolfe, 2004), and rating-scale/category review "
            "(Linacre, 2002b; Wind, 2023). Confirm the final reference list against `method_reference_audit.csv` "
            "and `help_reference_coverage.csv` before submission."
        ),
        (
            "For readers familiar with FACETS, the agreement evidence corresponds to a Table 8-style shared-context screen; "
            "rater evidence corresponds to rater measure/fit output; and rating-scale evidence corresponds to Categories/Steps "
            "counts, average measures, thresholds, and category curves."
        ),
        (
            "**Do not overclaim:** Do not state that scoring was fully reliable, that all categories functioned distinctly, "
            "or that category collapse was warranted unless the corresponding rows in `scoring_consistency_decision.csv` and "
            "`quality_control_todo_checklist.csv` support that statement."
        ),
    ])


def calc_ptmea(obs_df, facet_cols):
    facet_cols = [f for f in facet_cols if f != "Person"]
    rows = []
    for facet in facet_cols:
        grp = obs_df.groupby(facet, observed=False)
        for level, df in grp:
            w = get_weights(df)
            rows.append({
                "Facet": facet,
                "Level": level,
                "PTMEA": safe_cor(df["Observed"].to_numpy(), df["PersonMeasure"].to_numpy(), w=w),
                "N": np.nansum(w),
            })
    return pd.DataFrame(rows)


def calc_subsets(obs_df, facet_cols):
    if obs_df is None or obs_df.empty or not facet_cols:
        return {"summary": pd.DataFrame(), "nodes": pd.DataFrame()}

    df = obs_df[facet_cols].dropna()
    if df.empty:
        return {"summary": pd.DataFrame(), "nodes": pd.DataFrame()}

    nodes = []
    for facet in facet_cols:
        nodes.extend([f"{facet}:{val}" for val in df[facet].astype(str).unique()])
    nodes = list(dict.fromkeys(nodes))
    if not nodes:
        return {"summary": pd.DataFrame(), "nodes": pd.DataFrame()}

    parent = {node: node for node in nodes}

    def find_root(x):
        px = parent.get(x)
        if px is None:
            return None
        if px != x:
            parent[x] = find_root(px)
        return parent[x]

    def union_nodes(a, b):
        ra = find_root(a)
        rb = find_root(b)
        if ra is None or rb is None or ra == rb:
            return
        parent[rb] = ra

    for _, row in df.iterrows():
        row_nodes = [f"{facet}:{row[facet]}" for facet in facet_cols if pd.notna(row[facet])]
        if len(row_nodes) < 2:
            continue
        base = row_nodes[0]
        for node in row_nodes[1:]:
            union_nodes(base, node)

    comp_ids = {node: find_root(node) for node in nodes}
    comp_levels = list(dict.fromkeys(comp_ids.values()))
    comp_index = {comp: idx + 1 for idx, comp in enumerate(comp_levels)}

    node_tbl = pd.DataFrame({
        "Node": nodes,
        "Component": [comp_ids[n] for n in nodes],
        "Subset": [comp_index[comp_ids[n]] for n in nodes],
        "Facet": [n.split(":", 1)[0] for n in nodes],
        "Level": [n.split(":", 1)[1] for n in nodes],
    })

    facet_counts = (
        node_tbl.groupby(["Subset", "Facet"])["Level"]
        .nunique()
        .reset_index()
        .pivot(index="Subset", columns="Facet", values="Level")
        .fillna(0)
        .reset_index()
    )

    first_facet = facet_cols[0]
    row_subset = df[first_facet].astype(str).apply(lambda v: comp_index[find_root(f"{first_facet}:{v}")])
    obs_counts = row_subset.value_counts().rename_axis("Subset").reset_index(name="Observations")

    summary_tbl = facet_counts.merge(obs_counts, on="Subset", how="left")
    summary_tbl["Observations"] = summary_tbl["Observations"].fillna(0).astype(int)
    summary_tbl = summary_tbl.sort_values("Observations", ascending=False)

    return {"summary": summary_tbl, "nodes": node_tbl}


# =============================================================================
# Slope-aware GPCM kernel for fair-average evaluation
# -----------------------------------------------------------------------------
# References
#   Muraki, E. (1992). A Generalized Partial Credit Model: Application of an
#     EM Algorithm. Applied Psychological Measurement, 16(2), 159-176.
#     Equations 2-3 and 10 define the category-probability kernel
#         P_k(eta; a, sc) = exp(a*(k*eta - sc_k)) / sum_r exp(a*(r*eta - sc_r))
#     where sc_k is the cumulative threshold and a is the discrimination (slope).
#   Muraki, E. (1993). Information Functions of the Generalized Partial Credit
#     Model. Applied Psychological Measurement, 17(4), 351-363. Equations 7
#     and 16 give E[X|eta] = sum_k k*P_k and the analytic relation
#         d E[X|eta] / d eta = a * Var[X|eta].
#   Linacre, J. M. FACETS Manual, section "Fair Average". Defines Fair-M and
#     Fair-Z averages by substituting other-facet measures with their
#     facet-level mean (Fair-M) or with zero (Fair-Z) and recomputing the
#     expected score under the resulting eta.
# Identification: log-slopes are constrained to sum to zero so the
# discrimination geometric mean is exactly one. Rows whose facet is not the
# slope facet therefore receive slope = 1 (the neutral slope under that
# identification), which makes the GPCM kernel reduce exactly to the PCM
# Linacre fair-average for those rows.
# =============================================================================


def expected_score_from_eta(eta, step_cum, rating_min, slope=1.0):
    """Expected score under the slope-aware GPCM / PCM / RSM kernel.

    At ``slope == 1`` the body reduces byte-for-byte to the PCM/RSM Linacre
    expected score; for ``slope > 0`` it implements the GPCM kernel of
    Muraki (1992, Eqs. 2-3, 10) in log-space via ``logsumexp`` for numerical
    stability. A non-finite or non-positive slope returns ``np.nan`` rather
    than silently falling back to slope = 1, so a degenerate fit cannot
    masquerade as a successful one.
    """

    if not np.isfinite(eta) or step_cum is None or len(step_cum) == 0:
        return np.nan
    step_cum = np.asarray(step_cum, dtype=float)
    if step_cum.ndim != 1:
        return np.nan
    if not np.isfinite(slope) or slope <= 0:
        return np.nan
    slope = float(slope)
    k_vals = np.arange(len(step_cum), dtype=float)
    log_num = slope * (eta * k_vals - step_cum)
    if not np.all(np.isfinite(log_num)):
        return np.nan
    log_denom = logsumexp(log_num)
    probs = np.exp(log_num - log_denom)
    return float(rating_min + np.sum(probs * k_vals))


def estimate_eta_from_target(target, step_cum, rating_min, rating_max, slope=1.0):
    if not np.isfinite(target) or step_cum is None or len(step_cum) == 0:
        return np.nan
    if target <= rating_min:
        return -np.inf
    if target >= rating_max:
        return np.inf

    def f(eta):
        return expected_score_from_eta(eta, step_cum, rating_min, slope=slope) - target

    low, high = -10.0, 10.0
    f_low = f(low)
    f_high = f(high)
    if not np.isfinite(f_low) or not np.isfinite(f_high) or f_low * f_high > 0:
        low, high = -20.0, 20.0
        f_low = f(low)
        f_high = f(high)
        if not np.isfinite(f_low) or not np.isfinite(f_high) or f_low * f_high > 0:
            return np.nan

    try:
        root = root_scalar(f, bracket=(low, high), method="brentq")
        return float(root.root) if root.converged else np.nan
    except Exception:
        return np.nan


def facet_anchor_status(facet, levels, config, extreme_levels=None):
    spec = config["theta_spec"] if facet == "Person" else config["facet_specs"].get(facet)
    if spec is None:
        return [""] * len(levels)
    anchors = spec.get("anchors")
    groups = spec.get("groups")
    status = []
    for lvl in levels:
        idx = spec["levels"].index(str(lvl)) if str(lvl) in spec["levels"] else None
        if idx is not None and anchors is not None and np.isfinite(anchors[idx]):
            status.append("A")
        elif idx is not None and groups is not None:
            grp_val = groups[idx]
            if grp_val not in (None, "", np.nan):
                if extreme_levels is not None and str(lvl) in extreme_levels:
                    status.append("X")
                else:
                    status.append("G")
            else:
                status.append("")
        else:
            status.append("")
    return status


def calc_facets_report_tbls(
    res,
    diagnostics,
    totalscore=True,
    umean=0,
    uscale=1,
    udecimals=2,
    omit_unobserved=False,
    xtreme=0,
):
    if res is None or diagnostics is None:
        return {}
    obs_df = diagnostics.get("obs")
    measures = diagnostics.get("measures")
    if obs_df is None or obs_df.empty or measures is None or measures.empty:
        return {}

    prep = res["prep"]
    config = res["config"]
    rating_min = prep["rating_min"]
    rating_max = prep["rating_max"]
    params = res["params"]

    theta_hat = params["theta"] if config["method"] == "JMLE" else res["facets"]["person"]["Estimate"].to_numpy()
    theta_mean = float(np.mean(theta_hat)) if len(theta_hat) > 0 else 0.0
    facet_means = {f: float(np.nanmean(params["facets"][f])) for f in config["facet_names"]}
    facet_signs = config.get("facet_signs", {f: -1 for f in config["facet_names"]})

    if config["model"] == "RSM":
        step_cum_common = np.concatenate([[0.0], np.cumsum(params["steps"])])
        step_cum_mean = step_cum_common
        slope_by_step_level = np.array([], dtype=float)
    else:
        step_mat = params["steps_mat"]
        if step_mat is None or len(step_mat) == 0:
            step_cum_common = np.array([])
            step_cum_mean = np.array([])
        else:
            step_mean = np.nanmean(step_mat, axis=0)
            step_cum_common = np.vstack([
                np.concatenate([[0.0], np.cumsum(row)]) for row in step_mat
            ])
            step_cum_mean = np.concatenate([[0.0], np.cumsum(step_mean)])
        if config["model"] == "GPCM":
            slope_by_step_level = np.asarray(params.get("slopes", []), dtype=float)
        else:
            slope_by_step_level = np.array([], dtype=float)

    facet_names = ["Person"] + config["facet_names"]
    facet_levels_all = {
        facet: (prep["levels"]["Person"] if facet == "Person" else prep["levels"][facet])
        for facet in facet_names
    }

    extreme_levels = {}
    for facet in facet_names:
        if facet not in obs_df.columns:
            extreme_levels[facet] = []
            continue
        stat = (
            obs_df.groupby(facet, observed=False)["Observed"]
            .agg(MinScore="min", MaxScore="max")
            .reset_index()
        )
        extreme = stat[
            ((stat["MinScore"] == rating_min) & (stat["MaxScore"] == rating_min))
            | ((stat["MinScore"] == rating_max) & (stat["MaxScore"] == rating_max))
        ]
        extreme_levels[facet] = extreme[facet].astype(str).tolist()

    extreme_flags = {}
    for facet in facet_names:
        if facet in obs_df.columns:
            extreme_flags[facet] = obs_df[facet].astype(str).isin(extreme_levels[facet])
    if extreme_flags:
        extreme_flag_df = pd.DataFrame(extreme_flags)
        extreme_count = extreme_flag_df.sum(axis=1)
    else:
        extreme_count = pd.Series(0, index=obs_df.index, dtype=int)

    out = {}
    for facet in facet_names:
        if facet not in obs_df.columns:
            continue
        status_tbl = (
            obs_df.groupby(facet, observed=False)["Observed"]
            .agg(MinScore="min", MaxScore="max", TotalCountAll="size")
            .reset_index()
        )
        if totalscore:
            score_source = obs_df
        else:
            flag = extreme_flags.get(facet)
            if flag is None:
                flag = pd.Series(False, index=obs_df.index)
            active_mask = (extreme_count == 0) | ((extreme_count == 1) & flag)
            score_source = obs_df.loc[active_mask]
        score_rows = []
        for level_val, df_lvl in score_source.groupby(facet, observed=False):
            total_score = float(df_lvl["Observed"].sum())
            total_count = float(len(df_lvl))
            if "Weight" in df_lvl.columns:
                weightd_count = float(df_lvl["Weight"].sum())
                weightd_score = float((df_lvl["Observed"] * df_lvl["Weight"]).sum())
            else:
                weightd_count = total_count
                weightd_score = total_score
            observed_avg = weightd_score / weightd_count if weightd_count > 0 else np.nan
            score_rows.append({
                facet: level_val,
                "TotalScore": total_score,
                "TotalCount": total_count,
                "WeightdScore": weightd_score,
                "WeightdCount": weightd_count,
                "ObservedAverage": observed_avg,
            })
        score_tbl = pd.DataFrame(
            score_rows,
            columns=[facet, "TotalScore", "TotalCount", "WeightdScore", "WeightdCount", "ObservedAverage"],
        )
        level_tbl = pd.DataFrame({"Level": list(map(str, facet_levels_all[facet]))})

        score_tbl[facet] = score_tbl[facet].astype(str)
        status_tbl[facet] = status_tbl[facet].astype(str)

        tbl = level_tbl.merge(score_tbl, left_on="Level", right_on=facet, how="left")
        tbl = tbl.merge(status_tbl, left_on="Level", right_on=facet, how="left", suffixes=("", "_all"))
        tbl = tbl.drop(columns=[c for c in [facet, f"{facet}_all"] if c in tbl.columns])

        tbl["TotalScore"] = tbl["TotalScore"].fillna(0)
        tbl["TotalCount"] = tbl["TotalCount"].fillna(0)
        if "WeightdScore" in tbl.columns:
            tbl["WeightdScore"] = tbl["WeightdScore"].fillna(0)
        if "WeightdCount" in tbl.columns:
            tbl["WeightdCount"] = tbl["WeightdCount"].fillna(0)
        if "WeightdCount" in tbl.columns:
            tbl["ObservedAverage"] = tbl.apply(
                lambda r: np.nan if r["WeightdCount"] == 0 else r["ObservedAverage"], axis=1
            )
        else:
            tbl["ObservedAverage"] = tbl.apply(
                lambda r: np.nan if r["TotalCount"] == 0 else r["ObservedAverage"], axis=1
            )

        meas_tbl = measures[measures["Facet"] == facet].copy()
        if not meas_tbl.empty:
            meas_tbl["Level"] = meas_tbl["Level"].astype(str)
            tbl = tbl.merge(
                meas_tbl[
                    ["Level", "Estimate", "SE", "Infit", "Outfit", "InfitZSTD", "OutfitZSTD", "PTMEA"]
                ],
                on="Level",
                how="left",
            )

        tbl["Anchor"] = facet_anchor_status(
            facet,
            tbl["Level"].tolist(),
            config,
            extreme_levels=extreme_levels.get(facet),
        )
        tbl["Status"] = ""
        tbl.loc[tbl["TotalCountAll"].fillna(0) == 0, "Status"] = "No data"
        tbl.loc[
            (tbl["Status"] == "")
            & (tbl["MinScore"] == rating_min)
            & (tbl["MaxScore"] == rating_min),
            "Status",
        ] = "Minimum"
        tbl.loc[
            (tbl["Status"] == "")
            & (tbl["MinScore"] == rating_max)
            & (tbl["MaxScore"] == rating_max),
            "Status",
        ] = "Maximum"
        tbl.loc[(tbl["Status"] == "") & (tbl["TotalCountAll"] == 1), "Status"] = "One datum"

        sign = facet_signs.get(facet, -1)
        if facet == "Person":
            other_sum = float(np.sum([facet_signs[k] * v for k, v in facet_means.items()]))
            eta_m = tbl["Estimate"] + other_sum
            eta_z = tbl["Estimate"]
        else:
            other_sum = float(np.sum([
                facet_signs[k] * v for k, v in facet_means.items() if k != facet
            ]))
            eta_m = theta_mean + other_sum + sign * tbl["Estimate"]
            eta_z = sign * tbl["Estimate"]

        # Build per-row step-cumulative thresholds and per-row slopes for the
        # slope-aware GPCM Linacre fair-average. The contract here matches the
        # mfrmr R reference implementation:
        #   * Step facet's own rows use that level's own cumulative thresholds.
        #   * Slope facet's own rows use that level's own discrimination.
        #   * Any other facet row uses (a) the column-mean cumulative
        #     thresholds and (b) slope = 1, which is the discrimination
        #     geometric mean under the sum-to-zero log-slope identification.
        # The "slope = 1" choice (rather than the arithmetic mean of the
        # estimated slopes) makes the GPCM fair-average reduce exactly to the
        # PCM Linacre construction on non-slope-facet rows, restoring continuity
        # with the simpler models.
        slope_list = [1.0 for _ in range(len(tbl))]
        if config["model"] in {"PCM", "GPCM"} and config.get("step_facet"):
            step_levels = prep["levels"][config["step_facet"]]
            if facet == config["step_facet"] and len(step_levels) > 0 and len(step_cum_common) > 0:
                step_cum_list = []
                slope_list = []
                for lvl in tbl["Level"].tolist():
                    idx = step_levels.index(lvl) if lvl in step_levels else None
                    if idx is not None and idx < len(step_cum_common):
                        step_cum_list.append(step_cum_common[idx])
                        if (
                            config["model"] == "GPCM"
                            and idx < len(slope_by_step_level)
                            and np.isfinite(slope_by_step_level[idx])
                            and slope_by_step_level[idx] > 0
                        ):
                            slope_list.append(float(slope_by_step_level[idx]))
                        else:
                            slope_list.append(1.0)
                    else:
                        step_cum_list.append(step_cum_mean)
                        slope_list.append(1.0)
            else:
                step_cum_list = [step_cum_mean for _ in range(len(tbl))]
                slope_list = [1.0 for _ in range(len(tbl))]
        else:
            step_cum_list = [step_cum_common for _ in range(len(tbl))]

        tbl["FairM"] = [
            expected_score_from_eta(e, step, rating_min, slope=slope)
            for e, step, slope in zip(eta_m, step_cum_list, slope_list)
        ]
        tbl["FairZ"] = [
            expected_score_from_eta(e, step, rating_min, slope=slope)
            for e, step, slope in zip(eta_z, step_cum_list, slope_list)
        ]

        xtreme_target = np.where(
            tbl["Status"] == "Minimum",
            rating_min + xtreme,
            np.where(tbl["Status"] == "Maximum", rating_max - xtreme, np.nan),
        )
        xtreme_eta = [
            estimate_eta_from_target(t, step, rating_min, rating_max, slope=slope) if xtreme > 0 else np.nan
            for t, step, slope in zip(xtreme_target, step_cum_list, slope_list)
        ]

        measure_logit = tbl["Estimate"].copy()
        xtreme_mask = np.isfinite(xtreme_eta)
        if np.any(xtreme_mask):
            if facet == "Person":
                measure_logit = np.where(xtreme_mask, np.array(xtreme_eta) - other_sum, measure_logit)
            else:
                measure_logit = np.where(
                    xtreme_mask,
                    (np.array(xtreme_eta) - theta_mean - other_sum) / sign,
                    measure_logit,
                )

        scale_factor = uscale if np.isfinite(uscale) else 1
        scale_origin = umean if np.isfinite(umean) else 0

        tbl["Measure"] = np.where(np.isfinite(measure_logit), measure_logit * scale_factor + scale_origin, np.nan)
        tbl["ModelSE"] = np.where(np.isfinite(tbl["SE"]), np.abs(scale_factor) * tbl["SE"], np.nan)
        tbl["RealSE"] = np.where(
            np.isfinite(tbl["SE"]) & np.isfinite(tbl["Infit"]),
            np.abs(scale_factor) * tbl["SE"] * np.sqrt(np.maximum(tbl["Infit"], 1)),
            np.nan,
        )

        extreme_mask = tbl["Status"].isin(["Minimum", "Maximum"])
        tbl.loc[extreme_mask, ["Infit", "Outfit", "InfitZSTD", "OutfitZSTD"]] = np.nan
        if facet == "Person":
            tbl["PTMEA"] = np.nan

        tbl = tbl.rename(columns={
            "Infit": "InfitMnSq",
            "InfitZSTD": "InfitZStd",
            "Outfit": "OutfitMnSq",
            "OutfitZSTD": "OutfitZStd",
            "PTMEA": "PtMeaCorr",
        })

        tbl = tbl[[
            "TotalScore",
            "TotalCount",
            "WeightdScore",
            "WeightdCount",
            "ObservedAverage",
            "FairM",
            "FairZ",
            "Measure",
            "ModelSE",
            "RealSE",
            "InfitMnSq",
            "InfitZStd",
            "OutfitMnSq",
            "OutfitZStd",
            "PtMeaCorr",
            "Anchor",
            "Status",
            "Level",
            "TotalCountAll",
        ]]

        if omit_unobserved:
            tbl = tbl[tbl["TotalCountAll"] > 0]

        tbl = tbl.drop(columns=["TotalCountAll"]).sort_values(["Measure", "TotalCount"], ascending=[False, False])
        out[facet] = tbl

    return out


# =============================================================================
# MML observed information and structural delta-method SE for the fair-average
# -----------------------------------------------------------------------------
# Mathematical contract
#   * The MML observed information is the Hessian of the negative marginal
#     log-likelihood at the MLE. We compute it as the numerical Jacobian of
#     the analytical gradient returned by ``mfrm_loglik_mml_value_grad``,
#     which costs O(P) gradient evaluations rather than O(P^2) function
#     evaluations (P is the number of free parameters).
#   * The parameter covariance ``Cov(par_hat) = I_obs^{-1}`` is obtained via
#     eigendecomposition with regularization: any eigenvalue at or below
#     ``max|lambda| * sqrt(eps)`` is floored, and the ``regularized`` flag is
#     set so downstream consumers can label the resulting SE as
#     regularization-aware.
#   * For a fair-average scalar function ``g(par_hat)`` the structural
#     delta-method standard error is ``sqrt(grad^T Cov grad)`` where ``grad``
#     is the finite-difference gradient of ``g`` with respect to the
#     optimization parameter vector. Person rows are returned as status
#     ``"not available"`` because the EAP person estimates are not part of
#     the marginal-likelihood Hessian.
# References
#   Muraki (1992) Eqs. 2-3, 10; Muraki (1993) Eqs. 7, 16; Linacre, FACETS
#   Manual section "Fair Average"; Cox (1975) on profile-likelihood-based
#   inference; standard delta-method treatment in any large-sample text.
# =============================================================================


def _invert_information_matrix(info):
    """Invert a symmetric observed-information matrix with eigenvalue regularization.

    Returns a tuple ``(cov, regularized, rank)`` where ``cov`` is the
    inverse (or ``None`` if inversion failed), ``regularized`` is ``True``
    when any eigenvalue was at or below the tolerance and had to be floored,
    and ``rank`` is the count of eigenvalues strictly above the tolerance.
    The tolerance follows ``np.linalg.matrix_rank``: ``max|lambda| * sqrt(eps)``.
    """
    if info is None:
        return None, False, 0
    info = np.asarray(info, dtype=float)
    if info.size == 0 or info.ndim != 2 or info.shape[0] != info.shape[1]:
        return None, False, 0
    if not np.all(np.isfinite(info)):
        return None, False, 0
    info_sym = (info + info.T) / 2.0
    try:
        eigvals, eigvecs = np.linalg.eigh(info_sym)
    except np.linalg.LinAlgError:
        return None, False, 0
    if eigvals.size == 0:
        return None, False, 0
    max_val = float(np.max(np.abs(eigvals)))
    eps = float(np.finfo(float).eps)
    tol = max_val * np.sqrt(eps) if max_val > 0 else np.sqrt(eps)
    rank = int(np.sum(eigvals > tol))
    regularized = bool(np.any(eigvals <= tol))
    safe_eigvals = np.maximum(eigvals, tol)
    cov = eigvecs @ np.diag(1.0 / safe_eigvals) @ eigvecs.T
    cov = (cov + cov.T) / 2.0
    return cov, regularized, rank


def _information_matrix_spectrum(info) -> dict[str, object]:
    """Numerical spectrum diagnostics for an observed-information matrix."""
    out = {
        "HessianFinite": False,
        "ParamCount": 0,
        "Rank": 0,
        "RankDeficiency": np.nan,
        "MinEigenvalue": np.nan,
        "MaxEigenvalue": np.nan,
        "MinPositiveEigenvalue": np.nan,
        "EigFloorTolerance": np.nan,
        "RegularizedEigenvalues": np.nan,
        "ConditionNumber": np.nan,
    }
    if info is None:
        return out
    arr = np.asarray(info, dtype=float)
    if arr.size == 0 or arr.ndim != 2 or arr.shape[0] != arr.shape[1]:
        return out
    out["ParamCount"] = int(arr.shape[0])
    if not np.all(np.isfinite(arr)):
        return out
    info_sym = (arr + arr.T) / 2.0
    try:
        eigvals = np.linalg.eigvalsh(info_sym)
    except np.linalg.LinAlgError:
        return out
    if eigvals.size == 0:
        return out
    max_abs = float(np.max(np.abs(eigvals)))
    eps = float(np.finfo(float).eps)
    tol = max_abs * np.sqrt(eps) if max_abs > 0 else np.sqrt(eps)
    positive = eigvals[eigvals > tol]
    rank = int(positive.size)
    min_positive = float(np.min(positive)) if positive.size else np.nan
    max_positive = float(np.max(positive)) if positive.size else np.nan
    condition = (
        float(max_positive / min_positive)
        if np.isfinite(max_positive) and np.isfinite(min_positive) and min_positive > 0
        else np.inf
    )
    out.update({
        "HessianFinite": True,
        "Rank": rank,
        "RankDeficiency": int(arr.shape[0] - rank),
        "MinEigenvalue": float(np.min(eigvals)),
        "MaxEigenvalue": float(np.max(eigvals)),
        "MinPositiveEigenvalue": min_positive,
        "EigFloorTolerance": float(tol),
        "RegularizedEigenvalues": int(np.sum(eigvals <= tol)),
        "ConditionNumber": condition,
    })
    return out


def build_mml_covariance_audit(covariance: dict | None, result: dict | None = None) -> pd.DataFrame:
    """Machine-readable audit for MML observed-information covariance quality."""
    cov_info = covariance if isinstance(covariance, dict) else {}
    config = (result or {}).get("config", {}) if isinstance(result, dict) else {}
    par = _get_opt_par(result or {}) if isinstance(result, dict) else None
    hessian = cov_info.get("hessian")
    spectrum = _information_matrix_spectrum(hessian)
    param_count = int(spectrum.get("ParamCount") or 0)
    if param_count == 0 and par is not None:
        param_count = int(np.asarray(par).size)
    status = str(cov_info.get("status", "not_available"))
    detail = str(cov_info.get("detail", "MML covariance audit was not available."))
    cov = cov_info.get("cov")
    cov_arr = np.asarray(cov, dtype=float) if cov is not None else np.asarray([])
    cov_finite = bool(cov_arr.size and cov_arr.ndim == 2 and np.all(np.isfinite(cov_arr)))
    cov_diag = np.diag(cov_arr) if cov_finite and cov_arr.shape[0] == cov_arr.shape[1] else np.asarray([])
    condition = float(spectrum.get("ConditionNumber", np.nan))
    rank_def = spectrum.get("RankDeficiency", np.nan)
    regularized_eigs = spectrum.get("RegularizedEigenvalues", np.nan)

    if status == "ok":
        claim_status = "Ready"
        interpretation = "Observed-information covariance was inverted without eigenvalue regularization."
        action = "Report SE/CI status and retain the covariance audit with the analysis archive."
    elif status == "regularized":
        claim_status = "Report with caveat"
        interpretation = "Observed-information covariance required eigenvalue regularization; SEs are regularization-aware large-sample approximations."
        action = "Report the regularized status, condition number, and sensitivity caveat before treating SE/CI as calibration evidence."
    elif status == "skipped_large_parameter_count":
        claim_status = "Report with caveat"
        interpretation = "Routine observed-information covariance was skipped by the parameter-count gate."
        action = "Use conditional SEs for screening, or rerun a smaller/targeted validation if structural SEs are required."
    elif status == "not_applicable":
        claim_status = "Not applicable"
        interpretation = "Observed-information covariance is only defined for the current MML path."
        action = "Use the method-specific SE/CI status columns instead of claiming structural MML covariance."
    else:
        claim_status = "Do not claim"
        interpretation = "Observed-information covariance was unavailable or failed diagnostics."
        action = "Do not claim structural covariance-based SE/CI; report fallback SE_Status and investigate the covariance failure."

    if np.isfinite(condition) and condition > 1e8 and claim_status == "Ready":
        claim_status = "Report with caveat"
        interpretation += " The Hessian condition number is high."
        action = "Report the high condition number and consider a sensitivity check or simpler parameterization."
    if np.isfinite(rank_def) and float(rank_def) > 0 and claim_status == "Ready":
        claim_status = "Report with caveat"

    row = {
        "Area": "MML observed-information covariance",
        "Status": status,
        "ClaimStatus": claim_status,
        "Method": "numerical Jacobian of analytical MML gradient; eigendecomposition inverse",
        "Model": str(config.get("model", "")),
        "FitMethod": str(config.get("method", "")),
        "ParamCount": param_count,
        "AutoParamLimit": int(MML_COVARIANCE_AUTO_MAX_PARAMS),
        "Rank": int(cov_info.get("rank", spectrum.get("Rank", 0)) or 0),
        "RankDeficiency": rank_def,
        "HessianFinite": bool(spectrum.get("HessianFinite", False)),
        "MinEigenvalue": spectrum.get("MinEigenvalue", np.nan),
        "MaxEigenvalue": spectrum.get("MaxEigenvalue", np.nan),
        "MinPositiveEigenvalue": spectrum.get("MinPositiveEigenvalue", np.nan),
        "EigFloorTolerance": spectrum.get("EigFloorTolerance", np.nan),
        "RegularizedEigenvalues": regularized_eigs,
        "ConditionNumber": condition,
        "Regularized": bool(cov_info.get("regularized", False)),
        "CovarianceFinite": cov_finite,
        "CovarianceMinDiagonal": float(np.nanmin(cov_diag)) if cov_diag.size else np.nan,
        "CovarianceMaxDiagonal": float(np.nanmax(cov_diag)) if cov_diag.size else np.nan,
        "Detail": detail,
        "Interpretation": interpretation,
        "RecommendedAction": action,
    }
    return pd.DataFrame([row])


def _compute_mml_observed_information(par, idx, config, sizes, quad, rel_step=1e-5):
    """Observed information of the MML negative marginal log-likelihood.

    Computed as the numerical Jacobian of the analytical gradient
    returned by ``mfrm_loglik_mml_value_grad`` via central differences at
    relative step size ``rel_step``. Symmetrised before return; downstream
    inversion is responsible for regularising near-singular spectra.
    """
    par = np.asarray(par, dtype=float)
    P = par.size
    if P == 0:
        return np.zeros((0, 0), dtype=float)
    H = np.zeros((P, P), dtype=float)
    for j in range(P):
        h = rel_step * max(1.0, abs(float(par[j])))
        par_p = par.copy()
        par_m = par.copy()
        par_p[j] += h
        par_m[j] -= h
        _, grad_p = mfrm_loglik_mml_value_grad(par_p, idx, config, sizes, quad)
        _, grad_m = mfrm_loglik_mml_value_grad(par_m, idx, config, sizes, quad)
        H[:, j] = (np.asarray(grad_p, dtype=float) - np.asarray(grad_m, dtype=float)) / (2.0 * h)
    return (H + H.T) / 2.0


def _build_param_slices(sizes):
    """Return a dict mapping each parameter section name to its slice into ``par``."""
    out = {}
    cursor = 0
    for name, count in sizes.items():
        out[name] = slice(cursor, cursor + int(count))
        cursor += int(count)
    return out


def _get_opt_par(res):
    """Robustly extract the optimisation parameter vector from a fit result."""
    opt = res.get("opt") if isinstance(res, dict) else None
    if opt is None:
        return None
    if hasattr(opt, "x"):
        return np.asarray(getattr(opt, "x"), dtype=float)
    if isinstance(opt, dict):
        for key in ("x", "par"):
            if key in opt:
                return np.asarray(opt[key], dtype=float)
    return None


def compute_mml_parameter_covariance(res, rel_step=1e-5):
    """Compute the MML observed-information covariance for an MML fit.

    Returns a dict with the keys ``cov`` (P x P ndarray or ``None``),
    ``hessian`` (P x P ndarray or ``None``), ``sizes`` (the OrderedDict from
    ``build_param_sizes``), ``param_slices`` (section-name -> slice),
    ``status`` (``"ok" | "regularized" | "not_applicable" | "fallback"``),
    ``detail`` (human-readable description), ``regularized`` (bool),
    ``rank`` (int), and a one-row ``audit`` table with Hessian spectrum
    and covariance quality diagnostics.
    """
    config = (res or {}).get("config", {}) or {}
    try:
        sizes = build_param_sizes(config) if config.get("facet_names") else OrderedDict()
    except Exception:
        sizes = OrderedDict()
    param_slices = _build_param_slices(sizes)

    def envelope(status, detail, cov=None, hessian=None, regularized=False, rank=0):
        out = {
            "cov": cov,
            "hessian": hessian,
            "sizes": sizes,
            "param_slices": param_slices,
            "status": status,
            "detail": detail,
            "regularized": regularized,
            "rank": rank,
        }
        out["audit"] = build_mml_covariance_audit(out, res)
        return out

    if config.get("method") != "MML":
        return envelope(
            "not_applicable",
            "MML observed-information covariance is only computed for MML fits.",
        )

    par = _get_opt_par(res)
    if par is None or par.size == 0:
        return envelope(
            "fallback",
            "Optimised parameter vector was not available; observed-information covariance was not computed.",
        )

    try:
        idx = build_indices(
            res["prep"],
            step_facet=config.get("step_facet"),
            slope_facet=config.get("slope_facet"),
        )
    except Exception as exc:
        return envelope(
            "fallback",
            f"Could not rebuild observation indices for covariance: {exc!s}",
        )

    quad_points = int(config.get("quad_points") or 15)
    try:
        quad = gauss_hermite_normal(max(1, quad_points), sd=get_population_prior_sd(config))
    except Exception as exc:
        return envelope(
            "fallback",
            f"Could not build Gauss-Hermite quadrature for covariance: {exc!s}",
        )

    try:
        hess = _compute_mml_observed_information(par, idx, config, sizes, quad, rel_step=rel_step)
    except Exception as exc:
        return envelope(
            "fallback",
            f"Observed-information Hessian computation raised: {exc!s}",
        )

    if not np.all(np.isfinite(hess)):
        return envelope(
            "fallback",
            "Observed-information matrix contained non-finite entries; covariance was not computed.",
            hessian=hess,
        )

    cov, regularized, rank = _invert_information_matrix(hess)
    if cov is None:
        return envelope(
            "fallback",
            "Observed-information matrix could not be inverted; covariance was not computed.",
            hessian=hess,
        )

    if regularized:
        detail = (
            "MML parameter covariance from observed information; a near-singular "
            "Hessian was regularized during inversion."
        )
        status = "regularized"
    else:
        detail = "MML parameter covariance from observed information."
        status = "ok"

    return envelope(status, detail, cov=cov, hessian=hess, regularized=regularized, rank=rank)


def _finite_difference_gradient(fn, par, rel_step=1e-5):
    """Central-difference gradient of a scalar ``fn(par)``.

    Falls back to one-sided differences if the symmetric perturbation
    returns a non-finite value at either end (e.g. the per-row fair-average
    crosses a rating bound). Returns NaN for entries that cannot be
    estimated at all.
    """
    par = np.asarray(par, dtype=float)
    P = par.size
    if P == 0:
        return np.zeros(0, dtype=float)
    grad = np.full(P, np.nan, dtype=float)
    try:
        base_val = float(fn(par))
    except Exception:
        base_val = float("nan")
    for j in range(P):
        h = rel_step * max(1.0, abs(float(par[j])))
        par_p = par.copy()
        par_m = par.copy()
        par_p[j] += h
        par_m[j] -= h
        try:
            f_p = float(fn(par_p))
        except Exception:
            f_p = float("nan")
        try:
            f_m = float(fn(par_m))
        except Exception:
            f_m = float("nan")
        if np.isfinite(f_p) and np.isfinite(f_m):
            grad[j] = (f_p - f_m) / (2.0 * h)
        elif np.isfinite(f_p) and np.isfinite(base_val):
            grad[j] = (f_p - base_val) / h
        elif np.isfinite(f_m) and np.isfinite(base_val):
            grad[j] = (base_val - f_m) / h
    return grad


def _compute_fair_average_value_from_par(res, par, facet, level, metric="FairM"):
    """Scalar fair-average value as a function of the optimisation parameter vector.

    This is the function ``g(par)`` that the structural delta method
    differentiates. For Person rows the function returns ``np.nan`` because
    MML person estimates are not part of ``par`` and therefore the
    structural Hessian cannot describe their uncertainty. For all other
    rows the function rebuilds the slope-aware Linacre fair-average from
    ``par`` using the same conventions as ``calc_facets_report_tbls``:
    slope-facet rows use that level's own discrimination and own step
    thresholds; non slope-facet rows use slope = 1 (the geometric-mean
    discrimination under the sum-to-zero log-slope identification) and the
    column-mean cumulative step thresholds.
    """
    if res is None:
        return float("nan")
    config = res.get("config", {}) if isinstance(res, dict) else {}
    if config.get("model") != "GPCM":
        return float("nan")
    prep = res.get("prep", {}) if isinstance(res, dict) else {}
    facet = str(facet)
    level = str(level)
    facet_names = list(config.get("facet_names", []))
    if facet == "Person" or facet not in facet_names:
        return float("nan")

    try:
        sizes = build_param_sizes(config)
        params = expand_params(np.asarray(par, dtype=float), sizes, config)
    except Exception:
        return float("nan")

    facet_levels = [str(x) for x in (prep.get("levels", {}).get(facet) or [])]
    if level not in facet_levels:
        return float("nan")
    facet_idx = facet_levels.index(level)

    person_frame = res.get("facets", {}).get("person") if isinstance(res.get("facets"), dict) else None
    theta_mean = 0.0
    if person_frame is not None:
        try:
            est_vals = np.asarray(person_frame["Estimate"].to_numpy(), dtype=float)
            if est_vals.size:
                m = float(np.nanmean(est_vals))
                if np.isfinite(m):
                    theta_mean = m
        except Exception:
            theta_mean = 0.0

    facet_means = {}
    for f in facet_names:
        vals = np.asarray(params["facets"].get(f, np.array([])), dtype=float)
        m = float(np.nanmean(vals)) if vals.size else 0.0
        facet_means[f] = m if np.isfinite(m) else 0.0

    facet_signs = config.get("facet_signs", {f: -1 for f in facet_names})
    sign = float(facet_signs.get(facet, -1))
    if not np.isfinite(sign):
        sign = -1.0

    facet_values = np.asarray(params["facets"].get(facet, np.array([])), dtype=float)
    if facet_idx >= facet_values.size:
        return float("nan")
    estimate = float(facet_values[facet_idx])
    if not np.isfinite(estimate):
        return float("nan")

    other_sum = 0.0
    for f, mean_f in facet_means.items():
        if f == facet:
            continue
        s = float(facet_signs.get(f, -1))
        if not np.isfinite(s):
            s = -1.0
        other_sum += s * mean_f

    if metric == "FairM":
        eta = theta_mean + other_sum + sign * estimate
    elif metric == "FairZ":
        eta = sign * estimate
    else:
        return float("nan")
    if not np.isfinite(eta):
        return float("nan")

    step_mat = params.get("steps_mat")
    if step_mat is None or np.asarray(step_mat).size == 0:
        return float("nan")
    step_mat = np.asarray(step_mat, dtype=float)
    step_profile = np.nanmean(step_mat, axis=0)
    step_facet = config.get("step_facet")
    if step_facet and facet == step_facet:
        step_levels = [str(x) for x in (prep.get("levels", {}).get(step_facet) or [])]
        if level in step_levels:
            step_row_idx = step_levels.index(level)
            if 0 <= step_row_idx < step_mat.shape[0]:
                step_profile = step_mat[step_row_idx]
    if not np.all(np.isfinite(step_profile)):
        return float("nan")

    step_cum = np.concatenate([[0.0], np.cumsum(step_profile)])

    slope = 1.0
    slope_facet = config.get("slope_facet") or step_facet
    slopes = np.asarray(params.get("slopes", np.array([])), dtype=float)
    if slope_facet and facet == slope_facet and slopes.size:
        slope_levels = [str(x) for x in (prep.get("levels", {}).get(slope_facet) or [])]
        if level in slope_levels:
            slope_row_idx = slope_levels.index(level)
            if 0 <= slope_row_idx < slopes.size:
                candidate = float(slopes[slope_row_idx])
                if np.isfinite(candidate) and candidate > 0:
                    slope = candidate

    return expected_score_from_eta(eta, step_cum, prep.get("rating_min", 0), slope=slope)


def add_gpcm_fair_average_delta_se(raw_tbls, res, covariance=None, ci_level=0.95):
    """Annotate fair-average tables with the structural delta-method SE / CI.

    Non-Person rows under a GPCM MML fit receive a standard error
    ``SE = sqrt(grad^T Cov grad)`` where ``Cov`` is the MML observed-
    information covariance and ``grad`` is the finite-difference gradient
    of the fair-average scalar function with respect to the optimisation
    parameter vector. Person rows return ``status = "not available"``
    because EAP person estimates are not part of the marginal-likelihood
    Hessian. Rows from non-GPCM fits return ``status = "not_applicable"``.
    """
    if not raw_tbls:
        return raw_tbls
    config = (res or {}).get("config", {}) or {}
    model = config.get("model")
    ci_level = float(ci_level) if np.isfinite(ci_level) else 0.95
    if not 0.0 < ci_level < 1.0:
        ci_level = 0.95

    def annotate_unavailable(tbl, status, detail):
        if tbl is None:
            return tbl
        new_tbl = tbl.copy()
        for prefix in ("FairM", "FairZ"):
            new_tbl[f"{prefix}SE"] = np.nan
            new_tbl[f"{prefix}_CI_Lower"] = np.nan
            new_tbl[f"{prefix}_CI_Upper"] = np.nan
            new_tbl[f"{prefix}_CI_Level"] = ci_level
            new_tbl[f"{prefix}_SE_Method"] = "not available"
            new_tbl[f"{prefix}_SE_Status"] = status
            new_tbl[f"{prefix}_SE_Detail"] = detail
        return new_tbl

    if model != "GPCM":
        return {
            facet: annotate_unavailable(
                tbl,
                "not_applicable",
                f"Structural delta-method fair-average SE is implemented for GPCM only; this fit is {model}.",
            )
            for facet, tbl in raw_tbls.items()
        }

    if covariance is None:
        covariance = compute_mml_parameter_covariance(res)

    if covariance.get("status") not in {"ok", "regularized"} or covariance.get("cov") is None:
        return {
            facet: annotate_unavailable(tbl, covariance.get("status", "fallback"), covariance.get("detail", ""))
            for facet, tbl in raw_tbls.items()
        }

    par = _get_opt_par(res)
    cov = np.asarray(covariance["cov"], dtype=float)
    if par is None or par.size != cov.shape[0]:
        return {
            facet: annotate_unavailable(
                tbl,
                "fallback",
                "Parameter vector length does not match the observed-information covariance shape.",
            )
            for facet, tbl in raw_tbls.items()
        }

    from scipy.stats import norm  # local import keeps module-level import surface stable
    z = float(norm.ppf((1.0 + ci_level) / 2.0))
    rating_min = res.get("prep", {}).get("rating_min", -np.inf)
    rating_max = res.get("prep", {}).get("rating_max", np.inf)

    se_method_main = (
        "Structural delta method (MML observed information; regularized Hessian)"
        if covariance.get("regularized")
        else "Structural delta method (MML observed information)"
    )
    se_detail_main = (
        "Propagates the structural covariance of facet, step, and slope "
        "parameters; MML person EAP estimates are conditioned on rather "
        "than included in the Hessian."
    )

    def compute_one(facet, level, estimate, metric):
        if not np.isfinite(estimate):
            return {
                "se": np.nan,
                "lower": np.nan,
                "upper": np.nan,
                "status": "not available",
                "detail": "Fair-average estimate is not finite.",
            }
        if facet == "Person":
            return {
                "se": np.nan,
                "lower": np.nan,
                "upper": np.nan,
                "status": "not available",
                "detail": (
                    "Person rows are not assigned structural fair-average SEs because "
                    "MML EAP person estimates are not part of the structural Hessian."
                ),
            }
        fn = lambda p: _compute_fair_average_value_from_par(res, p, facet, level, metric=metric)
        grad = _finite_difference_gradient(fn, par)
        if grad.size != cov.shape[0] or not np.any(np.isfinite(grad)):
            return {
                "se": np.nan,
                "lower": np.nan,
                "upper": np.nan,
                "status": "not available",
                "detail": "Finite-difference gradient was not available.",
            }
        grad = np.where(np.isfinite(grad), grad, 0.0)
        var = float(grad @ cov @ grad)
        if -1e-10 < var < 0:
            var = 0.0
        if not np.isfinite(var) or var < 0:
            return {
                "se": np.nan,
                "lower": np.nan,
                "upper": np.nan,
                "status": "not available",
                "detail": "Delta-method variance was not non-negative.",
            }
        se = float(np.sqrt(var))
        lower = estimate - z * se
        upper = estimate + z * se
        if np.isfinite(rating_min):
            lower = max(lower, rating_min)
        if np.isfinite(rating_max):
            upper = min(upper, rating_max)
        return {
            "se": se,
            "lower": lower,
            "upper": upper,
            "status": covariance.get("status", "ok"),
            "detail": se_detail_main,
        }

    out = {}
    for facet, tbl in raw_tbls.items():
        if tbl is None or len(tbl) == 0:
            out[facet] = tbl
            continue
        new_tbl = tbl.copy()
        for prefix in ("FairM", "FairZ"):
            if prefix not in new_tbl.columns:
                continue
            results = []
            for i in range(len(new_tbl)):
                estimate = float(new_tbl.iloc[i][prefix])
                level = str(new_tbl.iloc[i]["Level"]) if "Level" in new_tbl.columns else ""
                results.append(compute_one(facet, level, estimate, prefix))
            new_tbl[f"{prefix}SE"] = [r["se"] for r in results]
            new_tbl[f"{prefix}_CI_Lower"] = [r["lower"] for r in results]
            new_tbl[f"{prefix}_CI_Upper"] = [r["upper"] for r in results]
            new_tbl[f"{prefix}_CI_Level"] = ci_level
            new_tbl[f"{prefix}_SE_Method"] = se_method_main
            new_tbl[f"{prefix}_SE_Status"] = [r["status"] for r in results]
            new_tbl[f"{prefix}_SE_Detail"] = [r["detail"] for r in results]
        out[facet] = new_tbl
    return out


def fair_average_table(res, diagnostics, fair_se=False, ci_level=0.95, **kwargs):
    """Public wrapper: compute FACETS-style fair-average tables with optional
    structural delta-method SE / CI columns for GPCM MML fits.

    With ``fair_se=False`` (the default) the return value is identical to
    ``calc_facets_report_tbls``. With ``fair_se=True`` each table gains
    ``Fair{M,Z}SE``, ``Fair{M,Z}_CI_Lower``, ``Fair{M,Z}_CI_Upper``,
    ``Fair{M,Z}_CI_Level``, ``Fair{M,Z}_SE_Method``,
    ``Fair{M,Z}_SE_Status``, and ``Fair{M,Z}_SE_Detail`` columns. Person
    rows are always marked ``status = "not available"`` because MML EAPs
    are not part of the structural Hessian; non-GPCM fits are marked
    ``status = "not_applicable"``.
    """
    raw_tbls = calc_facets_report_tbls(res, diagnostics, **kwargs)
    if not fair_se:
        return raw_tbls
    return add_gpcm_fair_average_delta_se(raw_tbls, res, ci_level=ci_level)


def _mml_covariance_for_diagnostics(res, max_params=MML_COVARIANCE_AUTO_MAX_PARAMS):
    """Observed-information covariance with an automatic size gate for diagnostics.

    ``compute_mml_parameter_covariance`` remains the exact public helper. This
    wrapper is used during normal diagnostics so large MML runs do not silently
    become much slower; when skipped, downstream tables keep conditional SEs and
    carry an explicit ``skipped_large_parameter_count`` status.
    """
    config = (res or {}).get("config", {}) or {}
    try:
        sizes = build_param_sizes(config) if config.get("facet_names") else OrderedDict()
    except Exception:
        sizes = OrderedDict()
    param_slices = _build_param_slices(sizes)

    def envelope(status, detail):
        out = {
            "cov": None,
            "hessian": None,
            "sizes": sizes,
            "param_slices": param_slices,
            "status": status,
            "detail": detail,
            "regularized": False,
            "rank": 0,
        }
        out["audit"] = build_mml_covariance_audit(out, res)
        return out

    if config.get("method") != "MML":
        return envelope(
            "not_applicable",
            "MML observed-information covariance is only computed for MML fits.",
        )
    par = _get_opt_par(res)
    if par is not None and max_params is not None and int(par.size) > int(max_params):
        return envelope(
            "skipped_large_parameter_count",
            (
                f"MML observed-information covariance was skipped for routine "
                f"diagnostics because the parameter vector has {int(par.size)} "
                f"parameters (auto limit {int(max_params)}). The measure table "
                "keeps conditional information SEs; run a smaller or targeted "
                "external validation when structural SEs are required."
            ),
        )
    return compute_mml_parameter_covariance(res)


def _compute_measure_value_from_par(res, par, facet, level):
    """Return a non-person facet measure as a scalar function of ``par``."""
    config = (res or {}).get("config", {}) or {}
    if config.get("method") != "MML" or str(facet) == "Person":
        return float("nan")
    prep = (res or {}).get("prep", {}) or {}
    facet = str(facet)
    level = str(level)
    if facet not in list(config.get("facet_names", [])):
        return float("nan")
    try:
        sizes = build_param_sizes(config)
        params = expand_params(np.asarray(par, dtype=float), sizes, config)
    except Exception:
        return float("nan")
    levels = [str(x) for x in (prep.get("levels", {}).get(facet) or [])]
    if level not in levels:
        return float("nan")
    idx = levels.index(level)
    values = np.asarray(params.get("facets", {}).get(facet, np.array([])), dtype=float)
    if idx >= values.size:
        return float("nan")
    value = float(values[idx])
    return value if np.isfinite(value) else float("nan")


def compute_mml_structural_measure_se_table(res, covariance=None, ci_level=0.95):
    """Delta-method SEs for MML non-person facet estimates.

    Person EAP estimates are posterior summaries and are intentionally excluded:
    they are not coordinates of the marginal-likelihood parameter vector. The
    returned table is keyed by ``Facet`` / ``Level`` and is merged into the main
    measure table by ``annotate_measure_uncertainty`` when finite SEs are
    available.
    """
    config = (res or {}).get("config", {}) or {}
    if config.get("method") != "MML":
        return pd.DataFrame()
    if covariance is None:
        covariance = _mml_covariance_for_diagnostics(res)
    prep = (res or {}).get("prep", {}) or {}
    par = _get_opt_par(res)
    status = str((covariance or {}).get("status", "fallback"))
    detail = str((covariance or {}).get("detail", "MML covariance unavailable."))
    cov = (covariance or {}).get("cov")
    rows: list[dict[str, object]] = []
    z = float(_norm.ppf((1.0 + float(ci_level)) / 2.0)) if 0.0 < float(ci_level) < 1.0 else 1.959963984540054

    for facet in list(config.get("facet_names", [])):
        levels = [str(x) for x in (prep.get("levels", {}).get(facet) or [])]
        for level in levels:
            row = {
                "Facet": str(facet),
                "Level": str(level),
                "StructuralSE": np.nan,
                "StructuralCI_Lower": np.nan,
                "StructuralCI_Upper": np.nan,
                "StructuralCI_Level": float(ci_level),
                "StructuralSE_Status": status,
                "StructuralSE_Method": "MML observed-information delta method",
                "StructuralSE_Detail": detail,
            }
            if status in {"ok", "regularized"} and cov is not None and par is not None:
                cov_arr = np.asarray(cov, dtype=float)
                if cov_arr.ndim == 2 and cov_arr.shape[0] == cov_arr.shape[1] == par.size:
                    fn = lambda p, f=facet, lv=level: _compute_measure_value_from_par(res, p, f, lv)
                    grad = _finite_difference_gradient(fn, par)
                    if grad.size == cov_arr.shape[0] and np.any(np.isfinite(grad)):
                        grad = np.where(np.isfinite(grad), grad, 0.0)
                        var = float(grad @ cov_arr @ grad)
                        if -1e-10 < var < 0:
                            var = 0.0
                        estimate = _compute_measure_value_from_par(res, par, facet, level)
                        if np.isfinite(var) and var >= 0 and np.isfinite(estimate):
                            se = float(np.sqrt(var))
                            row.update({
                                "StructuralSE": se,
                                "StructuralCI_Lower": estimate - z * se,
                                "StructuralCI_Upper": estimate + z * se,
                                "StructuralSE_Status": status,
                                "StructuralSE_Detail": detail,
                            })
                        else:
                            row["StructuralSE_Status"] = "not_available"
                            row["StructuralSE_Detail"] = "Delta-method variance was not finite and non-negative."
                    else:
                        row["StructuralSE_Status"] = "not_available"
                        row["StructuralSE_Detail"] = "Finite-difference gradient was not available."
            rows.append(row)
    return pd.DataFrame(rows)


def _compute_step_value_from_par(res, par, step_facet_level, step_index):
    """Return a reported step / threshold estimate as a scalar function of ``par``.

    Mirrors :func:`_compute_measure_value_from_par` for the rating-scale step
    thresholds. The reported step is the centred value (``center_sum_zero``)
    that the fit surfaces, so differentiating it through ``par`` carries the
    sum-to-zero identification automatically -- no explicit Jacobian is needed.
    """
    config = (res or {}).get("config", {}) or {}
    if config.get("method") != "MML":
        return float("nan")
    n_cat = int(config.get("n_cat", 0) or 0)
    n_steps = max(n_cat - 1, 0)
    step_index = int(step_index)
    if step_index < 0 or step_index >= n_steps:
        return float("nan")
    try:
        sizes = build_param_sizes(config)
        params = expand_params(np.asarray(par, dtype=float), sizes, config)
    except Exception:
        return float("nan")
    if config.get("model") == "RSM":
        steps = np.asarray(params.get("steps"), dtype=float)
        if steps.ndim != 1 or step_index >= steps.size:
            return float("nan")
        value = float(steps[step_index])
    else:
        prep = (res or {}).get("prep", {}) or {}
        step_facet = config.get("step_facet")
        levels = [str(x) for x in (prep.get("levels", {}).get(step_facet) or [])]
        sf = str(step_facet_level)
        steps_mat = params.get("steps_mat")
        if sf not in levels or steps_mat is None:
            return float("nan")
        steps_mat = np.asarray(steps_mat, dtype=float)
        level_idx = levels.index(sf)
        if steps_mat.ndim != 2 or level_idx >= steps_mat.shape[0] or step_index >= steps_mat.shape[1]:
            return float("nan")
        value = float(steps_mat[level_idx, step_index])
    return value if np.isfinite(value) else float("nan")


def compute_mml_step_se_table(res, covariance=None, ci_level=0.95):
    """Delta-method SEs for MML rating-scale step / threshold estimates.

    Uses the same MML observed-information delta method as
    :func:`compute_mml_structural_measure_se_table`, applied to the step
    thresholds. Returns a table keyed by ``Step`` (RSM) or ``StepFacet`` /
    ``Step`` (PCM / GPCM) so it can be merged onto the fitted steps table.
    Empty for non-MML fits; SE columns are ``NaN`` with a status when the
    marginal-likelihood covariance is unavailable.
    """
    config = (res or {}).get("config", {}) or {}
    if config.get("method") != "MML":
        return pd.DataFrame()
    n_cat = int(config.get("n_cat", 0) or 0)
    n_steps = max(n_cat - 1, 0)
    if n_steps <= 0:
        return pd.DataFrame()
    model = config.get("model")
    prep = (res or {}).get("prep", {}) or {}
    if covariance is None:
        covariance = _mml_covariance_for_diagnostics(res)
    par = _get_opt_par(res)
    status = str((covariance or {}).get("status", "fallback"))
    detail = str((covariance or {}).get("detail", "MML covariance unavailable."))
    cov = (covariance or {}).get("cov")
    z = float(_norm.ppf((1.0 + float(ci_level)) / 2.0)) if 0.0 < float(ci_level) < 1.0 else 1.959963984540054

    targets: list[tuple[object, int, dict[str, object]]] = []
    if model == "RSM":
        for i in range(n_steps):
            targets.append((None, i, {"Step": f"Step_{i + 1}"}))
    else:
        step_facet = config.get("step_facet")
        for sf in [str(x) for x in (prep.get("levels", {}).get(step_facet) or [])]:
            for i in range(n_steps):
                targets.append((sf, i, {"StepFacet": sf, "Step": f"Step_{i + 1}"}))

    cov_arr = np.asarray(cov, dtype=float) if cov is not None else None
    par_arr = np.asarray(par, dtype=float) if par is not None else None
    usable = (
        status in {"ok", "regularized"}
        and cov_arr is not None
        and par_arr is not None
        and cov_arr.ndim == 2
        and cov_arr.shape[0] == cov_arr.shape[1] == par_arr.size
    )

    rows: list[dict[str, object]] = []
    for sf, i, key in targets:
        row = dict(key)
        row.update({
            "SE": np.nan,
            "CI_Lower": np.nan,
            "CI_Upper": np.nan,
            "CI_Level": float(ci_level),
            "SE_Method": "MML observed-information delta method",
            "SE_Status": status,
            "SE_Detail": detail,
        })
        if usable:
            fn = lambda p, _sf=sf, _i=i: _compute_step_value_from_par(res, p, _sf, _i)
            grad = _finite_difference_gradient(fn, par_arr)
            if grad.size == cov_arr.shape[0] and np.any(np.isfinite(grad)):
                grad = np.where(np.isfinite(grad), grad, 0.0)
                var = float(grad @ cov_arr @ grad)
                if -1e-10 < var < 0:
                    var = 0.0
                estimate = _compute_step_value_from_par(res, par_arr, sf, i)
                if np.isfinite(var) and var >= 0 and np.isfinite(estimate):
                    se = float(np.sqrt(var))
                    row.update({
                        "SE": se,
                        "CI_Lower": estimate - z * se,
                        "CI_Upper": estimate + z * se,
                    })
                else:
                    row["SE_Status"] = "not_available"
                    row["SE_Detail"] = "Delta-method variance was not finite and non-negative."
            else:
                row["SE_Status"] = "not_available"
                row["SE_Detail"] = "Finite-difference gradient was not available."
        rows.append(row)
    return pd.DataFrame(rows)


def annotate_measure_uncertainty(measures, res, obs_df=None, *, ci_level=0.95):
    """Attach SE/CI provenance columns to the measure table."""
    if not isinstance(measures, pd.DataFrame) or measures.empty:
        return measures, {
            "covariance": {"status": "not_available", "detail": "Measure table is empty."},
            "structural_se": pd.DataFrame(),
            "summary": pd.DataFrame(),
        }
    out = measures.copy()
    config = (res or {}).get("config", {}) or {}
    method = str(config.get("method", ""))
    z = float(_norm.ppf((1.0 + float(ci_level)) / 2.0)) if 0.0 < float(ci_level) < 1.0 else 1.959963984540054

    out["SE_Method"] = "conditional information approximation: 1/sqrt(sum Var*w), other fitted parameters held fixed"
    out["SE_Status"] = "conditional_approximation"
    out["SE_Detail"] = "Does not propagate uncertainty from other estimated person, facet, step, slope, or anchor parameters."
    out["CI_Level"] = float(ci_level)
    out["CI_Method"] = "Wald normal CI from the reported SE"
    out["CI_Status"] = "conditional_approximation"
    out["UncertaintyCaution"] = "Use for screening unless the method/status column says structural covariance was used."

    if method == "MML" and "Facet" in out.columns:
        person_mask = out["Facet"].astype(str) == "Person"
        out.loc[person_mask, "SE_Method"] = "MML EAP posterior SD from quadrature"
        out.loc[person_mask, "SE_Status"] = "posterior_eap_sd"
        out.loc[person_mask, "SE_Detail"] = (
            "Person SE is the posterior SD of the EAP score, not a structural "
            "marginal-likelihood SE."
        )
        out.loc[person_mask, "CI_Status"] = "posterior_interval_approximation"
        out.loc[person_mask, "UncertaintyCaution"] = (
            "Person interval uses EAP posterior SD; do not treat it as a "
            "fixed-effect ML parameter CI."
        )

        covariance = _mml_covariance_for_diagnostics(res)
        structural = compute_mml_structural_measure_se_table(
            res,
            covariance=covariance,
            ci_level=ci_level,
        )
        if isinstance(structural, pd.DataFrame) and not structural.empty:
            out = out.merge(structural, on=["Facet", "Level"], how="left")
            structural_ok = (
                out.get("StructuralSE").notna()
                & out.get("StructuralSE_Status").astype(str).isin({"ok", "regularized"})
            )
            out.loc[structural_ok, "SE"] = out.loc[structural_ok, "StructuralSE"]
            out.loc[structural_ok, "CI_Lower"] = out.loc[structural_ok, "StructuralCI_Lower"]
            out.loc[structural_ok, "CI_Upper"] = out.loc[structural_ok, "StructuralCI_Upper"]
            out.loc[structural_ok, "SE_Method"] = out.loc[structural_ok, "StructuralSE_Method"]
            out.loc[structural_ok, "SE_Status"] = out.loc[structural_ok, "StructuralSE_Status"]
            out.loc[structural_ok, "SE_Detail"] = out.loc[structural_ok, "StructuralSE_Detail"]
            out.loc[structural_ok, "CI_Method"] = "Wald normal CI using MML observed-information delta-method SE"
            out.loc[structural_ok, "CI_Status"] = out.loc[structural_ok, "StructuralSE_Status"]
            out.loc[structural_ok, "UncertaintyCaution"] = (
                "Non-person MML facet interval propagates structural covariance "
                "for fitted model parameters; it remains a large-sample Wald CI."
            )
            helper_cols = [
                "StructuralSE", "StructuralCI_Lower", "StructuralCI_Upper",
                "StructuralCI_Level", "StructuralSE_Status",
                "StructuralSE_Method", "StructuralSE_Detail",
            ]
            out = out.drop(columns=[c for c in helper_cols if c in out.columns])
    else:
        covariance = {"status": "not_applicable", "detail": "MML covariance is not applicable to this run."}
        structural = pd.DataFrame()

    covariance_audit = (
        covariance.get("audit")
        if isinstance(covariance, dict) and isinstance(covariance.get("audit"), pd.DataFrame)
        else build_mml_covariance_audit(covariance, res)
    )
    if isinstance(covariance_audit, pd.DataFrame) and not covariance_audit.empty:
        ca = covariance_audit.iloc[0]
        out["SE_CovarianceStatus"] = str(ca.get("Status", "not_available"))
        out["SE_CovarianceClaimStatus"] = str(ca.get("ClaimStatus", "Do not claim"))
        out["SE_CovarianceConditionNumber"] = ca.get("ConditionNumber", np.nan)
        out["SE_CovarianceRank"] = ca.get("Rank", np.nan)
        out["SE_CovarianceRankDeficiency"] = ca.get("RankDeficiency", np.nan)
        out["SE_CovarianceRegularizedEigenvalues"] = ca.get("RegularizedEigenvalues", np.nan)
        out["SE_CovarianceDetail"] = str(ca.get("Detail", ""))
    else:
        out["SE_CovarianceStatus"] = "not_available"
        out["SE_CovarianceClaimStatus"] = "Do not claim"
        out["SE_CovarianceConditionNumber"] = np.nan
        out["SE_CovarianceRank"] = np.nan
        out["SE_CovarianceRankDeficiency"] = np.nan
        out["SE_CovarianceRegularizedEigenvalues"] = np.nan
        out["SE_CovarianceDetail"] = ""

    est = pd.to_numeric(out.get("Estimate", pd.Series(dtype=float)), errors="coerce")
    se = pd.to_numeric(out.get("SE", pd.Series(dtype=float)), errors="coerce")
    needs_ci = out["CI_Lower"].isna() | out["CI_Upper"].isna() if {"CI_Lower", "CI_Upper"}.issubset(out.columns) else pd.Series(True, index=out.index)
    out.loc[needs_ci, "CI_Lower"] = est.loc[needs_ci] - z * se.loc[needs_ci]
    out.loc[needs_ci, "CI_Upper"] = est.loc[needs_ci] + z * se.loc[needs_ci]

    summary_rows = []
    if "SE_Status" in out.columns:
        for status, sub in out.groupby("SE_Status", dropna=False, observed=False):
            summary_rows.append({
                "Area": "Measure SE/CI",
                "Status": str(status),
                "Rows": int(len(sub)),
                "Method": "; ".join(sorted(set(sub["SE_Method"].astype(str))))[:500],
                "Caution": "; ".join(sorted(set(sub["UncertaintyCaution"].astype(str))))[:500],
            })
    if method == "MML":
        summary_rows.append({
            "Area": "MML observed-information covariance",
            "Status": str(covariance.get("status", "unknown")),
            "Rows": int(len(out)),
            "Method": "numerical Jacobian of analytical MML gradient; eigendecomposition inverse",
            "Caution": str(covariance.get("detail", "")),
            "ClaimStatus": (
                str(covariance_audit.iloc[0].get("ClaimStatus", "Do not claim"))
                if isinstance(covariance_audit, pd.DataFrame) and not covariance_audit.empty
                else "Do not claim"
            ),
            "ConditionNumber": (
                covariance_audit.iloc[0].get("ConditionNumber", np.nan)
                if isinstance(covariance_audit, pd.DataFrame) and not covariance_audit.empty
                else np.nan
            ),
        })
    return out, {
        "covariance": covariance,
        "covariance_audit": covariance_audit,
        "structural_se": structural,
        "summary": pd.DataFrame(summary_rows),
    }


# Display ordering for the FACETS-style tables tab. Keeps each fair-average
# value adjacent to its standard error, confidence-interval bounds, and
# status flag for quick visual scanning. Lower-priority columns (S.E.
# method label, longer-form detail strings, the CI level itself) move to
# the right edge of the table so the centre stays focused on measurement
# values that drive interpretation.
_FACETS_TABLE_DISPLAY_ORDER = (
    "TotalScore", "TotalCount", "WeightdScore", "WeightdCount", "ObservedAverage",
    "FairM", "FairMSE", "FairM_CI_Lower", "FairM_CI_Upper", "FairM_SE_Status",
    "FairZ", "FairZSE", "FairZ_CI_Lower", "FairZ_CI_Upper", "FairZ_SE_Status",
    "Measure", "ModelSE", "RealSE",
    "InfitMnSq", "InfitZStd", "OutfitMnSq", "OutfitZStd",
    "PtMeaCorr", "Anchor", "Status", "Level",
    "FairM_CI_Level", "FairM_SE_Method", "FairM_SE_Detail",
    "FairZ_CI_Level", "FairZ_SE_Method", "FairZ_SE_Detail",
)


def _reorder_facets_table_columns(tbl):
    """Reorder a fair-average facet table so SE / CI / status columns sit
    adjacent to their parent metric.

    The function is a no-op for ``None`` or empty tables. Columns that are
    not in the display order template are preserved at the right edge in
    their original relative order, so downstream consumers (CSV exports,
    custom forks adding new columns) are not broken by this reorder.
    """
    if tbl is None or len(tbl) == 0:
        return tbl
    cols = list(tbl.columns)
    ordered = [c for c in _FACETS_TABLE_DISPLAY_ORDER if c in cols]
    extras = [c for c in cols if c not in ordered]
    return tbl[ordered + extras]


def _facets_fair_se_cache_key(res, ci_level):
    """Stable session-state key for the SE-annotated facet tables.

    Keyed on a content hash of the optimised parameter vector and the CI
    level so a re-run with the same fit and the same CI choice reuses the
    cached annotation, but a fresh fit (different ``opt.x``) triggers a
    fresh Hessian / delta-method evaluation.
    """
    par = _get_opt_par(res)
    if par is None:
        return None
    try:
        par_hash = hash(par.tobytes())
    except Exception:
        return None
    try:
        ci = float(ci_level)
    except Exception:
        ci = 0.95
    return ("_fair_se_facets_tables_cache", par_hash, ci)


def calc_reliability(measure_df):
    """Compute Separation / Reliability / Strata for each facet.

    Adds a ``ReliabilityNote`` column that diagnoses *why* Separation or
    Reliability is NaN for a given facet, so the Measures tab can show a
    concrete reason (e.g., "all levels have identical measures") instead
    of a bare NaN cell that users interpret as a bug.
    """
    rows = []
    if measure_df.empty:
        return pd.DataFrame()
    for facet, df in measure_df.groupby("Facet"):
        # `ddof=1` on a single-element slice (common with singleton
        # Scorer facets in binary testlet data) raises a
        # RuntimeWarning from numpy. Cleanly return NaN instead of
        # dumping the warning into the Streamlit log.
        finite_est = df["Estimate"].dropna()
        mv = float(np.nanvar(finite_est, ddof=1)) if len(finite_est) >= 2 else np.nan
        ev = np.nanmean(df["SE"] ** 2)
        rmse = np.sqrt(ev) if np.isfinite(ev) else np.nan
        eap_basis = (
            "SE_Status" in df.columns
            and df["SE_Status"].astype(str).eq("posterior_eap_sd").any()
        )
        note = ""
        if np.isfinite(mv) and np.isfinite(ev) and mv > 0 and ev > 0:
            if eap_basis:
                # EAP measures (e.g. MML person rows): use the IRT empirical
                # reliability Var(EAP) / (Var(EAP) + mean posterior SD^2). The
                # posterior SD already carries shrinkage, so the JMLE-style
                # (ObsVar - ErrVar) / ObsVar form understates person reliability
                # and is not FACETS-comparable.
                reliability = mv / (mv + ev)
                separation = np.sqrt(mv / ev)
                strata = (4 * separation + 1) / 3
            else:
                tv = max(mv - ev, 0.0)
                separation = np.sqrt(tv / ev) if tv > 0 else 0.0
                reliability = tv / mv if mv > 0 else np.nan
                strata = (4 * separation + 1) / 3
                if tv == 0:
                    note = "measurement variance ≤ error variance; separation = 0"
        else:
            separation = np.nan
            reliability = np.nan
            strata = np.nan
            # Diagnose the exact NaN cause so the UI can surface it to the user
            if len(df) < 2:
                note = f"only {len(df)} level — need ≥2 for separation"
            elif not np.isfinite(mv) or mv == 0:
                note = "all levels have identical (or NaN) measures"
            elif not np.isfinite(ev) or ev == 0:
                note = "standard errors are zero or NaN (check fit statistics)"
            else:
                note = "variance components are invalid (mv or ev non-finite)"
        se_status_counts = ""
        if "SE_Status" in df.columns:
            counts = df["SE_Status"].astype(str).value_counts().to_dict()
            se_status_counts = "; ".join(f"{k}={v}" for k, v in sorted(counts.items()))
            if note:
                note = f"{note}; SE status: {se_status_counts}"
            else:
                note = f"SE status: {se_status_counts}"
        if eap_basis:
            reliability_basis = (
                "Empirical reliability for EAP measures: Var(EAP) / (Var(EAP) + mean "
                "posterior SD^2). Posterior SDs already include shrinkage, so this is "
                "not directly comparable to a JMLE-style separation reliability."
            )
        else:
            reliability_basis = (
                "Reliability is computed from observed estimate variance minus mean squared SE. "
                "Its evidential strength follows the SE_Status values for this facet."
            )
        rows.append({
            "Facet": facet,
            "Levels": len(df),
            "SD": np.sqrt(mv) if np.isfinite(mv) else np.nan,
            "RMSE": rmse,
            "Separation": separation,
            "Strata": strata,
            "Reliability": reliability,
            "MeanInfit": np.nanmean(df["Infit"]),
            "MeanOutfit": np.nanmean(df["Outfit"]),
            "ReliabilityNote": note,
            "SE_StatusSummary": se_status_counts,
            "ReliabilityBasis": reliability_basis,
        })
    return pd.DataFrame(rows)


def compute_marginal_fit_diagnostics(
    res,
    include_pairwise=False,
    max_pair_cells=400,
    min_expected=1e-8,
):
    """MML-only marginal observed-vs-expected category diagnostics.

    This integrates category probabilities over the population quadrature
    distribution, conditional on the observed design rows. It is a marginal
    distribution screen, not a posterior/person-residual diagnostic.
    """
    config = res.get("config", {})
    if config.get("method") != "MML":
        return {
            "available": False,
            "reason": "Strict marginal diagnostics are currently defined for MML runs only.",
            "summary": pd.DataFrame(),
            "counts": pd.DataFrame(),
            "pairwise": {"available": False, "reason": "MML run required.", "summary": pd.DataFrame(), "counts": pd.DataFrame()},
        }

    prep = res.get("prep", {})
    params = res.get("params", {})
    if not prep or not params:
        return {
            "available": False,
            "reason": "Fitted data or parameters are unavailable.",
            "summary": pd.DataFrame(),
            "counts": pd.DataFrame(),
            "pairwise": {"available": False, "reason": "Fitted data or parameters are unavailable.", "summary": pd.DataFrame(), "counts": pd.DataFrame()},
        }

    idx = build_indices(prep, step_facet=config.get("step_facet"), slope_facet=config.get("slope_facet"))
    n = len(idx["score_k"])
    n_cat = int(config.get("n_cat", prep["rating_max"] - prep["rating_min"] + 1))
    if n == 0 or n_cat < 2:
        return {
            "available": False,
            "reason": "Not enough observations or score categories for marginal diagnostics.",
            "summary": pd.DataFrame(),
            "counts": pd.DataFrame(),
            "pairwise": {"available": False, "reason": "Not enough data.", "summary": pd.DataFrame(), "counts": pd.DataFrame()},
        }

    quad_points = int(config.get("quad_points") or 15)
    quad = make_mml_quadrature(config, quad_points)
    base_eta = compute_base_eta(idx, params, config)
    pop_mu = compute_population_mu(params, config)
    pop_mu_by_obs = pop_mu[idx["person"]] if pop_mu.size else np.zeros(n, dtype=float)
    k_vals = np.arange(n_cat)
    marginal_probs = np.zeros((n, n_cat), dtype=float)

    if config.get("model") == "RSM":
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
        for theta_q, w_q in zip(quad["nodes"], quad["weights"]):
            eta = theta_q + pop_mu_by_obs + base_eta
            log_num = np.outer(eta, k_vals) - step_cum
            log_denom = logsumexp(log_num, axis=1, keepdims=True)
            marginal_probs += float(w_q) * np.exp(log_num - log_denom)
    elif config.get("model") == "PCM":
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        step_idx = idx["step_idx"]
        for theta_q, w_q in zip(quad["nodes"], quad["weights"]):
            eta = theta_q + pop_mu_by_obs + base_eta
            for c_idx in range(step_cum_mat.shape[0]):
                rows = np.where(step_idx == c_idx)[0]
                if rows.size == 0:
                    continue
                log_num = np.outer(eta[rows], k_vals) - step_cum_mat[c_idx]
                log_denom = logsumexp(log_num, axis=1, keepdims=True)
                marginal_probs[rows, :] += float(w_q) * np.exp(log_num - log_denom)
    else:
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        for theta_q, w_q in zip(quad["nodes"], quad["weights"]):
            eta = theta_q + pop_mu_by_obs + base_eta
            marginal_probs += float(w_q) * category_prob_gpcm(
                eta,
                step_cum_mat,
                idx["step_idx"],
                params["slopes"],
                idx.get("slope_idx"),
            )

    row_weight = idx.get("weight")
    if row_weight is None:
        row_weight = np.ones(n, dtype=float)
    else:
        row_weight = np.asarray(row_weight, dtype=float)

    obs_k = np.asarray(idx["score_k"], dtype=int)
    rating_min = int(prep["rating_min"])
    facet_names = list(config.get("facet_names", []))
    data = prep.get("data", pd.DataFrame())

    def aggregate(assignments: pd.DataFrame, scope: str, label_cols: list[str]):
        count_rows = []
        summary_rows = []
        if assignments.empty:
            return pd.DataFrame(), pd.DataFrame()
        grouped = assignments.groupby(label_cols, dropna=False, observed=False, sort=False) if label_cols else [((), assignments)]
        for key, sub in grouped:
            row_idx = sub["_row"].to_numpy(dtype=int)
            if row_idx.size == 0:
                continue
            key_tuple = key if isinstance(key, tuple) else (key,)
            label = {col: key_tuple[i] if i < len(key_tuple) else "" for i, col in enumerate(label_cols)}
            chi_sq = 0.0
            df_eff = 0
            total_obs = 0.0
            total_exp = 0.0
            for k in range(n_cat):
                obs = float(np.sum(row_weight[row_idx] * (obs_k[row_idx] == k)))
                exp = float(np.sum(row_weight[row_idx] * marginal_probs[row_idx, k]))
                resid = obs - exp
                std = resid / np.sqrt(exp) if exp > min_expected else np.nan
                contrib = (resid * resid / exp) if exp > min_expected else np.nan
                if np.isfinite(contrib):
                    chi_sq += contrib
                    df_eff += 1
                total_obs += obs
                total_exp += exp
                count_rows.append({
                    "Scope": scope,
                    **label,
                    "Category": rating_min + k,
                    "Observed": obs,
                    "Expected": exp,
                    "Residual": resid,
                    "StdResidual": std,
                    "ChiSquareContribution": contrib,
                })
            df = max(df_eff - 1, 0)
            p_val = float(chi2.sf(chi_sq, df)) if df > 0 and np.isfinite(chi_sq) else np.nan
            summary_rows.append({
                "Scope": scope,
                **label,
                "Rows": int(row_idx.size),
                "ObservedTotal": total_obs,
                "ExpectedTotal": total_exp,
                "ChiSquare": chi_sq,
                "df": df,
                "p": p_val,
                "MaxAbsStdResidual": float(np.nanmax(np.abs([r["StdResidual"] for r in count_rows[-n_cat:]]))),
                "Status": "Review" if (np.isfinite(p_val) and p_val < 0.01) or (np.nanmax(np.abs([r["StdResidual"] for r in count_rows[-n_cat:]])) >= 3) else "OK",
            })
        return pd.DataFrame(summary_rows), pd.DataFrame(count_rows)

    row_base = pd.DataFrame({"_row": np.arange(n, dtype=int)})
    overall_summary, overall_counts = aggregate(row_base, "Overall", [])

    summary_parts = [overall_summary]
    count_parts = [overall_counts]
    for facet in facet_names:
        assignments = pd.DataFrame({
            "_row": np.arange(n, dtype=int),
            "Facet": facet,
            "Level": data[facet].astype(str).to_numpy() if facet in data.columns else idx["facets"][facet].astype(str),
        })
        s_tbl, c_tbl = aggregate(assignments, f"Facet:{facet}", ["Facet", "Level"])
        summary_parts.append(s_tbl)
        count_parts.append(c_tbl)

    pair_summary = pd.DataFrame()
    pair_counts = pd.DataFrame()
    pair_reason = "Pairwise marginal diagnostics were not requested."
    pair_available = False
    if include_pairwise and len(facet_names) >= 2:
        pair_summary_parts = []
        pair_count_parts = []
        n_cells = 0
        for fa, fb in combinations(facet_names, 2):
            if fa not in data.columns or fb not in data.columns:
                continue
            n_cells += int(data[[fa, fb]].drop_duplicates().shape[0]) * n_cat
            if n_cells > int(max_pair_cells):
                pair_reason = (
                    f"Pairwise marginal diagnostics skipped after exceeding {max_pair_cells} expected cells. "
                    "Increase the Custom limit only when you need a final, slower screening run."
                )
                break
            assignments = pd.DataFrame({
                "_row": np.arange(n, dtype=int),
                "FacetA": fa,
                "LevelA": data[fa].astype(str).to_numpy(),
                "FacetB": fb,
                "LevelB": data[fb].astype(str).to_numpy(),
            })
            s_tbl, c_tbl = aggregate(assignments, f"Pair:{fa} x {fb}", ["FacetA", "LevelA", "FacetB", "LevelB"])
            pair_summary_parts.append(s_tbl)
            pair_count_parts.append(c_tbl)
        if pair_summary_parts:
            pair_summary = pd.concat(pair_summary_parts, ignore_index=True)
            pair_counts = pd.concat(pair_count_parts, ignore_index=True)
            pair_available = True
            pair_reason = "Pairwise marginal diagnostics computed."

    summary = pd.concat([p for p in summary_parts if isinstance(p, pd.DataFrame) and not p.empty], ignore_index=True)
    counts = pd.concat([p for p in count_parts if isinstance(p, pd.DataFrame) and not p.empty], ignore_index=True)
    n_review = int((summary.get("Status", pd.Series(dtype=str)) == "Review").sum()) if not summary.empty else 0

    return {
        "available": True,
        "reason": "Marginal diagnostics computed for an MML run.",
        "summary": summary,
        "counts": counts,
        "n_review": n_review,
        "quad_points": quad_points,
        "interpretation": (
            "Review rows with small p-values or |StdResidual| >= 3. "
            "This is a marginal distribution screen; interpret together with residual fit, category functioning, and design review."
        ),
        "pairwise": {
            "available": pair_available,
            "reason": pair_reason,
            "summary": pair_summary,
            "counts": pair_counts,
            "max_pair_cells": int(max_pair_cells),
        },
    }



def ensure_positive_definite(mat, eps=1e-6):
    mat = np.array(mat, dtype=float, copy=True)
    mat = (mat + mat.T) / 2
    eigvals = np.linalg.eigvalsh(mat)
    min_eig = np.min(eigvals)
    if min_eig < eps:
        mat += np.eye(mat.shape[0]) * (eps - min_eig)
    return mat


def _pca_core_from_residual_matrix(residual_matrix: pd.DataFrame | None) -> dict | None:
    """Compute the correlation PCA core without recursive stability checks."""
    if residual_matrix is None or residual_matrix.shape[0] < 2 or residual_matrix.shape[1] < 2:
        return None
    residual_matrix_clean = residual_matrix.dropna(axis=1, how="all")
    if residual_matrix_clean.shape[1] < 2:
        return None
    cor_df = residual_matrix_clean.corr(min_periods=2)
    cor_df = cor_df.fillna(0)
    cor_arr = cor_df.to_numpy(copy=True)
    np.fill_diagonal(cor_arr, 1)

    cor_pd = ensure_positive_definite(cor_arr)
    cor_pd_df = pd.DataFrame(cor_pd, index=cor_df.index, columns=cor_df.columns)

    eigvals, eigvecs = np.linalg.eigh(cor_pd)
    order = np.argsort(eigvals)[::-1]
    eigvals = eigvals[order]
    eigvecs = eigvecs[:, order]

    total = np.sum(eigvals)
    var_pct = (eigvals / total * 100) if total > 0 else np.zeros_like(eigvals)
    loadings = eigvecs * np.sqrt(np.maximum(eigvals, 0))
    loadings_df = pd.DataFrame(
        loadings,
        index=cor_pd_df.index,
        columns=[f"PC{i+1}" for i in range(loadings.shape[1])],
    )
    return {
        "eigenvalues": eigvals,
        "variance_pct": var_pct,
        "loadings": loadings_df,
        "cor_matrix": cor_pd_df,
        "residual_matrix_clean": residual_matrix_clean,
    }


def _abs_loading_correlation(reference: pd.Series, candidate: pd.Series) -> float:
    joined = pd.concat([reference, candidate], axis=1, join="inner").dropna()
    if joined.shape[0] < 2:
        return np.nan
    x = pd.to_numeric(joined.iloc[:, 0], errors="coerce")
    y = pd.to_numeric(joined.iloc[:, 1], errors="coerce")
    ok = x.notna() & y.notna()
    if int(ok.sum()) < 2:
        return np.nan
    x_arr = x[ok].to_numpy(dtype=float)
    y_arr = y[ok].to_numpy(dtype=float)
    if np.nanstd(x_arr) <= 0 or np.nanstd(y_arr) <= 0:
        return np.nan
    return float(abs(np.corrcoef(x_arr, y_arr)[0, 1]))


def _pca_leave_one_column_stability(
    residual_matrix_clean: pd.DataFrame,
    full_eigenvalues: np.ndarray,
    full_loadings: pd.DataFrame,
) -> dict[str, object]:
    if (
        residual_matrix_clean is None
        or residual_matrix_clean.shape[1] < 3
        or full_eigenvalues is None
        or len(full_eigenvalues) == 0
        or not isinstance(full_loadings, pd.DataFrame)
        or "PC1" not in full_loadings.columns
    ):
        return {
            "LOOColumnsEvaluated": 0,
            "LOOEV1Min": np.nan,
            "LOOEV1Max": np.nan,
            "LOOEV1MaxAbsDelta": np.nan,
            "LOOEV1ShareMin": np.nan,
            "LOOEV1ShareMax": np.nan,
            "LOOEV1ShareMaxAbsDelta": np.nan,
            "LOOPC1MedianAbsLoadingCorrelation": np.nan,
            "LOOPC1MinAbsLoadingCorrelation": np.nan,
        }
    columns = list(residual_matrix_clean.columns)
    if len(columns) > PCA_STABILITY_LOO_MAX_COLUMNS:
        columns = columns[:PCA_STABILITY_LOO_MAX_COLUMNS]
    ev1_values: list[float] = []
    ev1_shares: list[float] = []
    loading_corrs: list[float] = []
    full_ev1 = float(full_eigenvalues[0])
    full_ev1_share = float(full_ev1 / residual_matrix_clean.shape[1]) if residual_matrix_clean.shape[1] else np.nan
    for col in columns:
        reduced = residual_matrix_clean.drop(columns=[col], errors="ignore")
        core = _pca_core_from_residual_matrix(reduced)
        if not core:
            continue
        eig = np.asarray(core.get("eigenvalues", []), dtype=float)
        load = core.get("loadings")
        if eig.size:
            ev1_values.append(float(eig[0]))
            ev1_shares.append(float(eig[0] / reduced.shape[1]) if reduced.shape[1] else np.nan)
        if isinstance(load, pd.DataFrame) and "PC1" in load.columns:
            corr = _abs_loading_correlation(full_loadings["PC1"].drop(index=[col], errors="ignore"), load["PC1"])
            if np.isfinite(corr):
                loading_corrs.append(float(corr))
    ev_arr = np.asarray(ev1_values, dtype=float)
    share_arr = np.asarray(ev1_shares, dtype=float)
    corr_arr = np.asarray(loading_corrs, dtype=float)
    return {
        "LOOColumnsEvaluated": int(len(ev_arr)),
        "LOOEV1Min": float(np.nanmin(ev_arr)) if ev_arr.size else np.nan,
        "LOOEV1Max": float(np.nanmax(ev_arr)) if ev_arr.size else np.nan,
        "LOOEV1MaxAbsDelta": float(np.nanmax(np.abs(ev_arr - full_ev1))) if ev_arr.size else np.nan,
        "LOOEV1ShareMin": float(np.nanmin(share_arr)) if share_arr.size else np.nan,
        "LOOEV1ShareMax": float(np.nanmax(share_arr)) if share_arr.size else np.nan,
        "LOOEV1ShareMaxAbsDelta": float(np.nanmax(np.abs(share_arr - full_ev1_share))) if share_arr.size and np.isfinite(full_ev1_share) else np.nan,
        "LOOPC1MedianAbsLoadingCorrelation": float(np.nanmedian(corr_arr)) if corr_arr.size else np.nan,
        "LOOPC1MinAbsLoadingCorrelation": float(np.nanmin(corr_arr)) if corr_arr.size else np.nan,
    }


def _pca_row_bootstrap_stability(
    residual_matrix_clean: pd.DataFrame,
    full_eigenvalues: np.ndarray,
    full_loadings: pd.DataFrame,
) -> dict[str, object]:
    if (
        residual_matrix_clean is None
        or residual_matrix_clean.shape[0] < 4
        or residual_matrix_clean.shape[1] < 2
        or full_eigenvalues is None
        or len(full_eigenvalues) == 0
        or not isinstance(full_loadings, pd.DataFrame)
        or "PC1" not in full_loadings.columns
    ):
        return {
            "BootstrapReplicates": 0,
            "BootstrapEV1Mean": np.nan,
            "BootstrapEV1SD": np.nan,
            "BootstrapEV1CV": np.nan,
            "BootstrapEV1P05": np.nan,
            "BootstrapEV1P95": np.nan,
            "BootstrapPC1MedianAbsLoadingCorrelation": np.nan,
            "BootstrapPC1MinAbsLoadingCorrelation": np.nan,
            "BootstrapEV1ThresholdCrossing": False,
        }
    work = residual_matrix_clean
    if work.shape[1] > PCA_STABILITY_BOOTSTRAP_MAX_COLUMNS:
        work = work.iloc[:, :PCA_STABILITY_BOOTSTRAP_MAX_COLUMNS]
    full_pc1 = full_loadings["PC1"].reindex(work.columns)
    rng = np.random.default_rng(PCA_STABILITY_BOOTSTRAP_SEED)
    ev1_values: list[float] = []
    loading_corrs: list[float] = []
    n_rows = int(work.shape[0])
    for _ in range(PCA_STABILITY_BOOTSTRAP_REPS):
        idx = rng.integers(0, n_rows, size=n_rows)
        boot = work.iloc[idx].reset_index(drop=True)
        core = _pca_core_from_residual_matrix(boot)
        if not core:
            continue
        eig = np.asarray(core.get("eigenvalues", []), dtype=float)
        load = core.get("loadings")
        if eig.size:
            ev1_values.append(float(eig[0]))
        if isinstance(load, pd.DataFrame) and "PC1" in load.columns:
            corr = _abs_loading_correlation(full_pc1, load["PC1"])
            if np.isfinite(corr):
                loading_corrs.append(float(corr))
    ev_arr = np.asarray(ev1_values, dtype=float)
    corr_arr = np.asarray(loading_corrs, dtype=float)
    ev_mean = float(np.nanmean(ev_arr)) if ev_arr.size else np.nan
    ev_sd = float(np.nanstd(ev_arr, ddof=1)) if ev_arr.size > 1 else np.nan
    ev_cv = float(ev_sd / ev_mean) if np.isfinite(ev_sd) and np.isfinite(ev_mean) and ev_mean > 0 else np.nan
    ev_p05 = float(np.nanpercentile(ev_arr, 5)) if ev_arr.size else np.nan
    ev_p95 = float(np.nanpercentile(ev_arr, 95)) if ev_arr.size else np.nan
    full_ev1 = float(full_eigenvalues[0])
    threshold_cross = False
    for threshold in (FINAL_PCA_EIGENVALUE_READY, FINAL_PCA_EIGENVALUE_REVIEW):
        if np.isfinite(ev_p05) and np.isfinite(ev_p95) and ev_p05 < threshold <= ev_p95:
            threshold_cross = True
        if np.isfinite(full_ev1) and full_ev1 < threshold <= ev_p95:
            threshold_cross = True
        if np.isfinite(full_ev1) and full_ev1 >= threshold and ev_p05 < threshold:
            threshold_cross = True
    return {
        "BootstrapReplicates": int(len(ev_arr)),
        "BootstrapEV1Mean": ev_mean,
        "BootstrapEV1SD": ev_sd,
        "BootstrapEV1CV": ev_cv,
        "BootstrapEV1P05": ev_p05,
        "BootstrapEV1P95": ev_p95,
        "BootstrapPC1MedianAbsLoadingCorrelation": float(np.nanmedian(corr_arr)) if corr_arr.size else np.nan,
        "BootstrapPC1MinAbsLoadingCorrelation": float(np.nanmin(corr_arr)) if corr_arr.size else np.nan,
        "BootstrapEV1ThresholdCrossing": bool(threshold_cross),
    }


def compute_pca_bundle(residual_matrix_wide):
    if residual_matrix_wide is None:
        return None
    if residual_matrix_wide.shape[0] < 2 or residual_matrix_wide.shape[1] < 2:
        return None

    residual_matrix_clean = residual_matrix_wide.dropna(axis=1, how="all")
    if residual_matrix_clean.shape[1] < 2:
        return None

    valid_mask = residual_matrix_clean.notna().astype(int)
    pairwise_n = valid_mask.T.dot(valid_mask)
    if pairwise_n.shape[0] > 1:
        off_diag = pairwise_n.to_numpy(dtype=float)
        off_diag = off_diag[~np.eye(off_diag.shape[0], dtype=bool)]
        min_pairwise_n = float(np.nanmin(off_diag)) if off_diag.size else np.nan
        median_pairwise_n = float(np.nanmedian(off_diag)) if off_diag.size else np.nan
    else:
        min_pairwise_n = np.nan
        median_pairwise_n = np.nan
    missing_share = float(residual_matrix_clean.isna().to_numpy().mean())
    n_persons, n_columns = residual_matrix_clean.shape
    stability_flags = []
    if n_persons < PCA_STABILITY_MIN_PERSONS:
        stability_flags.append(f"fewer than {PCA_STABILITY_MIN_PERSONS} persons")
    if n_columns < PCA_STABILITY_MIN_COLUMNS:
        stability_flags.append(f"fewer than {PCA_STABILITY_MIN_COLUMNS} residual columns")
    if missing_share > PCA_STABILITY_MAX_MISSING_SHARE:
        stability_flags.append(f"{missing_share:.0%} matrix missingness")
    if np.isfinite(min_pairwise_n) and min_pairwise_n < PCA_STABILITY_MIN_PAIRWISE_N:
        stability_flags.append(f"minimum pairwise overlap {min_pairwise_n:.0f}")

    core = _pca_core_from_residual_matrix(residual_matrix_clean)
    if core is None:
        return None
    eigvals = np.asarray(core["eigenvalues"], dtype=float)
    var_pct = np.asarray(core["variance_pct"], dtype=float)
    loadings_df = core["loadings"]
    cor_pd_df = core["cor_matrix"]

    loo = _pca_leave_one_column_stability(residual_matrix_clean, eigvals, loadings_df)
    boot = _pca_row_bootstrap_stability(residual_matrix_clean, eigvals, loadings_df)
    sensitivity_flags: list[str] = []
    loo_delta = float(loo.get("LOOEV1MaxAbsDelta", np.nan))
    loo_share_delta = float(loo.get("LOOEV1ShareMaxAbsDelta", np.nan))
    loo_corr = float(loo.get("LOOPC1MinAbsLoadingCorrelation", np.nan))
    boot_cv = float(boot.get("BootstrapEV1CV", np.nan))
    boot_corr = float(boot.get("BootstrapPC1MinAbsLoadingCorrelation", np.nan))
    if np.isfinite(loo_share_delta) and loo_share_delta > PCA_STABILITY_MAX_LOO_EV1_SHARE_DELTA:
        sensitivity_flags.append(f"leave-one-column EV1 share shift {loo_share_delta:.2f}")
    if np.isfinite(loo_corr) and loo_corr < PCA_STABILITY_MIN_LOADING_CORR:
        sensitivity_flags.append(f"leave-one-column loading correlation {loo_corr:.2f}")
    if np.isfinite(boot_cv) and boot_cv > PCA_STABILITY_MAX_BOOTSTRAP_EV1_CV:
        sensitivity_flags.append(f"bootstrap EV1 CV {boot_cv:.2f}")
    if np.isfinite(boot_corr) and boot_corr < PCA_STABILITY_MIN_LOADING_CORR:
        sensitivity_flags.append(f"bootstrap loading correlation {boot_corr:.2f}")
    if bool(boot.get("BootstrapEV1ThresholdCrossing", False)):
        sensitivity_flags.append("bootstrap EV1 interval crosses an interpretation threshold")
    stability_flags.extend(sensitivity_flags)
    stability_status = "Review" if stability_flags else "Stable screen"
    stability_caution = (
        "Residual PCA may be unstable because " + "; ".join(stability_flags) + ". "
        "Use loadings as exploratory prompts and corroborate with fit, content, and marginal diagnostics."
        if stability_flags else
        "Residual matrix has adequate basic overlap for a screening PCA; still interpret as a diagnostic, not proof."
    )
    stability_row = {
        "PCAStabilityStatus": stability_status,
        "Persons": int(n_persons),
        "ResidualColumns": int(n_columns),
        "MissingShare": missing_share,
        "MinPairwiseOverlap": min_pairwise_n,
        "MedianPairwiseOverlap": median_pairwise_n,
        "FullEV1": float(eigvals[0]) if eigvals.size else np.nan,
        "FullEV2": float(eigvals[1]) if eigvals.size > 1 else np.nan,
        "FullPC1VariancePct": float(var_pct[0]) if var_pct.size else np.nan,
        "SensitivityFlagSummary": "; ".join(sensitivity_flags) if sensitivity_flags else "none",
        "Rule": (
            f"Review if persons < {PCA_STABILITY_MIN_PERSONS}, columns < "
            f"{PCA_STABILITY_MIN_COLUMNS}, missing share > "
            f"{PCA_STABILITY_MAX_MISSING_SHARE:.0%}, or min pairwise overlap < "
            f"{PCA_STABILITY_MIN_PAIRWISE_N}; also review if leave-one-column "
            f"EV1 share shift > {PCA_STABILITY_MAX_LOO_EV1_SHARE_DELTA:.0%}, bootstrap EV1 CV > "
            f"{PCA_STABILITY_MAX_BOOTSTRAP_EV1_CV:.0%}, loading correlation < "
            f"{PCA_STABILITY_MIN_LOADING_CORR}, or bootstrap EV1 crosses EV=2/3 thresholds."
        ),
        "Caution": stability_caution,
    }
    stability_row.update(loo)
    stability_row.update(boot)
    stability_table = pd.DataFrame([stability_row])

    return {
        "eigenvalues": eigvals,
        "variance_pct": var_pct,
        "loadings": loadings_df,
        "cor_matrix": cor_pd_df,
        "residual_matrix": residual_matrix_wide,
        "stability": stability_table.iloc[0].to_dict(),
        "stability_table": stability_table,
    }


def compute_pca_overall(obs_df, facet_names):
    if obs_df is None or obs_df.empty or not facet_names:
        return None
    df_aug = obs_df.copy()
    df_aug["Person"] = df_aug["Person"].astype(str)
    df_aug["item_combination"] = df_aug[facet_names].astype(str).agg("_".join, axis=1)
    residual_matrix_prep = (
        df_aug.groupby(["Person", "item_combination"])["StdResidual"]
        .mean()
        .reset_index()
    )
    residual_matrix_wide = residual_matrix_prep.pivot(
        index="Person", columns="item_combination", values="StdResidual"
    )
    return compute_pca_bundle(residual_matrix_wide)


def compute_pca_by_facet(obs_df, facet_names):
    out = {}
    if obs_df is None or obs_df.empty:
        return out
    for facet in facet_names:
        df = obs_df.copy()
        df["Person"] = df["Person"].astype(str)
        df["Level"] = df[facet].astype(str)
        residual_matrix_prep = (
            df.groupby(["Person", "Level"])["StdResidual"]
            .mean()
            .reset_index()
        )
        residual_matrix_wide = residual_matrix_prep.pivot(
            index="Person", columns="Level", values="StdResidual"
        )
        out[facet] = compute_pca_bundle(residual_matrix_wide)
    return out


def collect_pca_stability_tables(diagnostics: dict | None) -> pd.DataFrame:
    """Collect overall and per-facet PCA stability audits into one export table."""
    rows: list[pd.DataFrame] = []
    if not isinstance(diagnostics, dict):
        return pd.DataFrame()
    pca = diagnostics.get("pca")
    if isinstance(pca, dict):
        stability = pca.get("stability_table")
        if isinstance(stability, pd.DataFrame) and not stability.empty:
            df = stability.copy()
            df.insert(0, "Scope", "overall")
            df.insert(1, "Facet", "")
            rows.append(df)
    pca_by_facet = diagnostics.get("pca_by_facet")
    if isinstance(pca_by_facet, dict):
        for facet, bundle in pca_by_facet.items():
            if not isinstance(bundle, dict):
                continue
            stability = bundle.get("stability_table")
            if isinstance(stability, pd.DataFrame) and not stability.empty:
                df = stability.copy()
                df.insert(0, "Scope", "facet")
                df.insert(1, "Facet", str(facet))
                rows.append(df)
    if not rows:
        return pd.DataFrame()
    return pd.concat(rows, ignore_index=True, sort=False)


def diagnose_pca_skip_reason(obs_df, facet_names, *, mode="overall", facet=None):
    """Return a human-readable reason why residual PCA could not be computed.

    Called by ``mfrm_diagnostics`` whenever ``compute_pca_overall`` /
    ``compute_pca_by_facet`` returns None. The Dimensionality tab now
    surfaces this reason instead of the silent "PCA of residuals is
    not available for this estimation" message.

    Parameters
    ----------
    obs_df : pd.DataFrame | None
        Observation table from ``compute_obs_table(res)``.
    facet_names : list[str] | None
        Facet names from ``res["config"]["facet_names"]``.
    mode : {"overall", "facet"}
        "overall" concatenates all facets into ``item_combination``;
        "facet" keys the residual matrix by a single facet level.
    facet : str | None
        Required when ``mode="facet"``.

    Returns
    -------
    dict
        A reason payload of the form ``{"key": str, "kwargs": dict}``
        suitable for ``_render_reason``. The payload is locale-agnostic
        and re-translates on every Streamlit rerun, so the Dimensionality
        tab matches the active sidebar language even when the user
        toggles language *after* the run. Callers must treat the value
        as opaque and never match it against fixed English literals.
    """
    if obs_df is None:
        return _make_reason("dimensionality.skip_reason_obs_none")
    if not isinstance(obs_df, pd.DataFrame):
        return _make_reason(
            "dimensionality.skip_reason_obs_type_template",
            type_name=type(obs_df).__name__,
        )
    if obs_df.empty:
        return _make_reason("dimensionality.skip_reason_obs_empty")
    if mode == "overall" and not facet_names:
        return _make_reason("dimensionality.skip_reason_no_facets")
    if mode == "facet":
        if not facet:
            return _make_reason("dimensionality.skip_reason_facet_not_provided")
        if facet not in obs_df.columns:
            return _make_reason(
                "dimensionality.skip_reason_facet_not_in_obs_template",
                facet=facet,
            )
    if "Person" not in obs_df.columns:
        return _make_reason("dimensionality.skip_reason_person_missing")
    if "StdResidual" not in obs_df.columns:
        return _make_reason("dimensionality.skip_reason_stdresidual_missing")

    try:
        df_aug = obs_df.copy()
        df_aug["Person"] = df_aug["Person"].astype(str)
        if mode == "overall":
            df_aug["_col_key"] = df_aug[facet_names].astype(str).agg("_".join, axis=1)
        else:
            df_aug["_col_key"] = df_aug[facet].astype(str)
        residual_matrix_prep = (
            df_aug.groupby(["Person", "_col_key"])["StdResidual"].mean().reset_index()
        )
        residual_matrix_wide = residual_matrix_prep.pivot(
            index="Person", columns="_col_key", values="StdResidual"
        )
    except Exception as exc:  # pragma: no cover - defensive
        return _make_reason(
            "dimensionality.skip_reason_construction_error_template",
            error_type=type(exc).__name__,
            error=str(exc),
        )

    n_persons, n_cols = residual_matrix_wide.shape
    if n_persons < 2:
        return _make_reason(
            "dimensionality.skip_reason_too_few_persons_template",
            n_persons=n_persons,
        )
    if n_cols < 2:
        # ``key_label`` itself is a translatable fragment, so we record the
        # mode discriminator and the facet kwarg and let _render_reason
        # resolve the final concatenation at display time.
        if mode == "overall":
            return _make_reason(
                "dimensionality.skip_reason_too_few_cols_template",
                n_cols=n_cols,
                key_label=_LazyKeyLabel(mode="overall"),
            )
        return _make_reason(
            "dimensionality.skip_reason_too_few_cols_template",
            n_cols=n_cols,
            key_label=_LazyKeyLabel(mode="facet", facet=facet),
        )
    clean = residual_matrix_wide.dropna(axis=1, how="all")
    if clean.shape[1] < 2:
        return _make_reason(
            "dimensionality.skip_reason_after_dropna_template",
            n_remaining=clean.shape[1],
        )

    nan_share = float(residual_matrix_wide.isna().to_numpy().mean())
    if nan_share > 0.95:
        return _make_reason(
            "dimensionality.skip_reason_too_sparse_template",
            nan_pct=f"{nan_share:.0%}",
        )

    return _make_reason("dimensionality.skip_reason_unknown")


def calc_expected_category_counts(res):
    if res is None:
        return pd.DataFrame()
    prep = res["prep"]
    config = res["config"]
    idx = build_indices(prep, step_facet=config["step_facet"], slope_facet=config.get("slope_facet"))
    params = res["params"]
    theta_hat = params["theta"] if config["method"] == "JMLE" else res["facets"]["person"]["Estimate"].to_numpy()
    eta = compute_eta(idx, params, config, theta_override=theta_hat if theta_hat.size else None)
    if config["model"] == "RSM":
        step_cum = np.concatenate([[0.0], np.cumsum(params["steps"])])
        probs = category_prob_rsm(eta, step_cum)
    elif config["model"] == "PCM":
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        probs = category_prob_pcm(eta, step_cum_mat, idx["step_idx"])
    else:
        step_cum_mat = np.vstack([
            np.concatenate([[0.0], np.cumsum(row)]) for row in params["steps_mat"]
        ])
        probs = category_prob_gpcm(
            eta,
            step_cum_mat,
            idx["step_idx"],
            params["slopes"],
            idx.get("slope_idx"),
        )
    if probs.size == 0:
        return pd.DataFrame()
    w = idx.get("weight")
    if w is None:
        exp_counts = np.nansum(probs, axis=0)
    else:
        exp_counts = np.nansum(probs * w[:, None], axis=0)
    total_exp = np.nansum(exp_counts)
    cat_vals = np.arange(prep["rating_min"], prep["rating_max"] + 1)
    return pd.DataFrame({
        "Category": cat_vals,
        "ExpectedCount": exp_counts,
        "ExpectedPercent": (100 * exp_counts / total_exp) if total_exp > 0 else np.nan,
    })


def calc_category_stats(obs_df, res=None, whexact=False):
    if obs_df.empty:
        return pd.DataFrame()
    total_n = np.nansum(get_weights(obs_df))
    rows = []
    for category, df_cat in obs_df.groupby("Observed"):
        w = get_weights(df_cat)
        count = np.nansum(w)
        var_w = np.nansum(df_cat["Var"] * w)
        infit = np.nansum(df_cat["StdSq"] * df_cat["Var"] * w) / var_w if var_w > 0 else np.nan
        outfit = np.nansum(df_cat["StdSq"] * w) / count if count > 0 else np.nan
        rows.append({
            "Category": category,
            "Count": count,
            "AvgPersonMeasure": weighted_mean(df_cat["PersonMeasure"].to_numpy(), w),
            "ExpectedAverage": weighted_mean(df_cat["Expected"].to_numpy(), w),
            "Infit": infit,
            "Outfit": outfit,
            "MeanResidual": weighted_mean(df_cat["Residual"].to_numpy(), w),
            "DF_Infit": var_w,
            "DF_Outfit": count,
        })
    summary = pd.DataFrame(rows)

    all_categories = (
        np.arange(res["prep"]["rating_min"], res["prep"]["rating_max"] + 1)
        if res is not None
        else np.sort(obs_df["Observed"].unique())
    )
    cat_tbl = pd.DataFrame({"Category": all_categories}).merge(summary, on="Category", how="left")
    cat_tbl["Count"] = cat_tbl["Count"].fillna(0)
    cat_tbl["Percent"] = np.where(total_n > 0, 100 * cat_tbl["Count"] / total_n, np.nan)
    cat_tbl["InfitZSTD"] = [
        zstd_from_mnsq(m, d, whexact=whexact) for m, d in zip(cat_tbl["Infit"], cat_tbl["DF_Infit"])
    ]
    cat_tbl["OutfitZSTD"] = [
        zstd_from_mnsq(m, d, whexact=whexact) for m, d in zip(cat_tbl["Outfit"], cat_tbl["DF_Outfit"])
    ]

    exp_tbl = calc_expected_category_counts(res) if res is not None else pd.DataFrame()
    if not exp_tbl.empty:
        cat_tbl = cat_tbl.merge(exp_tbl, on="Category", how="left")
        cat_tbl["DiffCount"] = cat_tbl["Count"] - cat_tbl["ExpectedCount"]
        cat_tbl["DiffPercent"] = cat_tbl["Percent"] - cat_tbl["ExpectedPercent"]

    cat_tbl["LowCount"] = cat_tbl["Count"] < 10
    cat_tbl["InfitFlag"] = cat_tbl["Infit"].apply(
        lambda v: np.nan if pd.isna(v) else (v < 0.5 or v > 1.5)
    )
    cat_tbl["OutfitFlag"] = cat_tbl["Outfit"].apply(
        lambda v: np.nan if pd.isna(v) else (v < 0.5 or v > 1.5)
    )
    cat_tbl["ZSTDFlag"] = (
        (cat_tbl["InfitZSTD"].abs() >= 2) | (cat_tbl["OutfitZSTD"].abs() >= 2)
    )
    return cat_tbl.sort_values("Category")


def calc_step_order(step_tbl):
    if step_tbl is None or step_tbl.empty:
        return pd.DataFrame()
    step_tbl = step_tbl.copy()
    step_tbl["StepIndex"] = step_tbl["Step"].str.extract(r"(\d+)").astype(float)
    if "StepFacet" not in step_tbl.columns:
        step_tbl["StepFacet"] = "Common"
    step_tbl = step_tbl.sort_values(["StepFacet", "StepIndex"])
    step_tbl["Spacing"] = step_tbl.groupby("StepFacet")["Estimate"].diff()
    step_tbl["Ordered"] = step_tbl["Spacing"].apply(lambda x: np.nan if pd.isna(x) else x > 0)
    return step_tbl


def category_warnings_text(cat_tbl, step_tbl=None):
    if cat_tbl is None or cat_tbl.empty:
        return "No category diagnostics available."
    msgs = []
    unused = cat_tbl[cat_tbl["Count"] == 0]
    if not unused.empty:
        msgs.append("Unused categories: " + ", ".join(map(str, unused["Category"].tolist())))
    low_counts = cat_tbl[cat_tbl["Count"] < 10]
    if not low_counts.empty:
        msgs.append("Low category counts (<10): " + ", ".join(map(str, low_counts["Category"].tolist())))
    if "DiffPercent" in cat_tbl.columns:
        diff_bad = cat_tbl[cat_tbl["DiffPercent"].abs() >= 5]
        if not diff_bad.empty:
            msgs.append("Observed vs expected % differs by >= 5: " + ", ".join(map(str, diff_bad["Category"].tolist())))
    if "InfitZSTD" in cat_tbl.columns and "OutfitZSTD" in cat_tbl.columns:
        zstd_bad = cat_tbl[(cat_tbl["InfitZSTD"].abs() >= 2) | (cat_tbl["OutfitZSTD"].abs() >= 2)]
        if not zstd_bad.empty:
            msgs.append("Category |ZSTD| >= 2: " + ", ".join(map(str, zstd_bad["Category"].tolist())))
    avg_tbl = cat_tbl.dropna(subset=["AvgPersonMeasure"]).sort_values("Category")
    if len(avg_tbl) >= 3 and not avg_tbl["AvgPersonMeasure"].is_monotonic_increasing:
        msgs.append("Category averages are not monotonic (Avg Measure by category).")
    if step_tbl is not None and not step_tbl.empty:
        disordered = step_tbl[step_tbl["Ordered"] == False]
        if not disordered.empty:
            labels = disordered.apply(lambda r: f"{r['StepFacet']}:{r['Step']}", axis=1).tolist()
            msgs.append("Disordered thresholds detected: " + ", ".join(labels))
    return "No major category warnings detected." if not msgs else "\n".join(msgs)


def to_float(value):
    try:
        return float(value)
    except (TypeError, ValueError):
        return np.nan


def fmt_count(value):
    val = to_float(value)
    if not np.isfinite(val):
        return "NA"
    if abs(val - round(val)) < 1e-6:
        return str(int(round(val)))
    return f"{val:.0f}"


def fmt_num(value, decimals=2):
    val = to_float(value)
    if not np.isfinite(val):
        return "NA"
    return f"{val:.{decimals}f}"


def fmt_pvalue(value):
    val = to_float(value)
    if not np.isfinite(val):
        return "NA"
    if val < 0.001:
        return "< .001"
    return f"= {val:.3f}"


def describe_series(series):
    if series is None:
        return None
    arr = pd.to_numeric(series, errors="coerce").dropna().to_numpy(dtype=float)
    if arr.size == 0:
        return None
    return {
        "min": float(np.nanmin(arr)),
        "max": float(np.nanmax(arr)),
        "mean": float(np.nanmean(arr)),
        "sd": float(np.nanstd(arr, ddof=1)) if arr.size > 1 else np.nan,
    }













def mfrm_diagnostics(
    res,
    interaction_pairs=None,
    top_n_interactions=20,
    whexact=False,
    compute_pca=True,
    compute_marginal=False,
    marginal_pairwise=False,
    marginal_max_pair_cells=400,
    compute_eb_shrinkage=False,
    fit_df_method: str = "engine",
    facets_zstd_cap: float = 9.0,
):
    fit_df_method = _resolve_fit_df_method(fit_df_method)
    obs_df = compute_obs_table(res)
    facet_cols = ["Person"] + res["config"]["facet_names"]
    overall_fit = calc_overall_fit(
        obs_df,
        whexact=whexact,
        fit_df_method=fit_df_method,
        facets_zstd_cap=facets_zstd_cap,
    )
    fit_tbl = calc_facet_fit(
        obs_df,
        facet_cols,
        whexact=whexact,
        fit_df_method=fit_df_method,
        facets_zstd_cap=facets_zstd_cap,
    )
    se_tbl = calc_facet_se(obs_df, facet_cols)
    bias_tbl = calc_bias_facet(obs_df, facet_cols)
    interaction_tbl = calc_bias_interactions(obs_df, facet_cols, pairs=interaction_pairs, top_n=top_n_interactions)
    ptmea_tbl = calc_ptmea(obs_df, facet_cols)

    person_tbl = res["facets"]["person"].copy()
    person_tbl["Facet"] = "Person"
    person_tbl["Level"] = person_tbl["Person"].astype(str)
    person_tbl["SE"] = person_tbl["SD"] if "SD" in person_tbl.columns else np.nan

    facet_tbl = res["facets"]["others"].copy()
    facet_tbl["Level"] = facet_tbl["Level"].astype(str)
    facet_tbl["SE"] = np.nan

    measures = pd.concat([
        person_tbl[["Facet", "Level", "Estimate", "SE"]],
        facet_tbl[["Facet", "Level", "Estimate", "SE"]],
    ], ignore_index=True)

    measures = measures.merge(se_tbl, on=["Facet", "Level"], how="left", suffixes=("", "_calc"))
    measures["SE"] = measures["SE"].fillna(measures["SE_calc"])
    measures = measures.drop(columns=["SE_calc"])
    if "N" in measures.columns:
        measures = measures.rename(columns={"N": "N_SE"})
    fit_tbl = fit_tbl.rename(columns={"N": "N_Fit"}) if "N" in fit_tbl.columns else fit_tbl
    bias_tbl = bias_tbl.rename(columns={"N": "N_Bias"}) if "N" in bias_tbl.columns else bias_tbl
    ptmea_tbl = ptmea_tbl.rename(columns={"N": "N_PTMEA"}) if "N" in ptmea_tbl.columns else ptmea_tbl
    measures = measures.merge(fit_tbl, on=["Facet", "Level"], how="left")
    measures = measures.merge(bias_tbl, on=["Facet", "Level"], how="left")
    measures = measures.merge(ptmea_tbl, on=["Facet", "Level"], how="left")
    ci_z = float(_norm.ppf(0.975))
    measures["CI_Lower"] = measures["Estimate"] - ci_z * measures["SE"]
    measures["CI_Upper"] = measures["Estimate"] + ci_z * measures["SE"]
    measures, uncertainty_bundle = annotate_measure_uncertainty(
        measures,
        res,
        obs_df=obs_df,
        ci_level=0.95,
    )

    # Attach MML observed-information delta-method SEs / CIs to the fitted step
    # thresholds, reusing the covariance already computed for the facet
    # measures. MML only; a no-op for JMLE fits and when the steps table
    # already carries an SE column.
    try:
        steps_tbl = res.get("steps") if isinstance(res, dict) else None
        if (
            isinstance(steps_tbl, pd.DataFrame)
            and not steps_tbl.empty
            and "Estimate" in steps_tbl.columns
            and "SE" not in steps_tbl.columns
        ):
            step_se_tbl = compute_mml_step_se_table(
                res,
                covariance=uncertainty_bundle.get("covariance") if isinstance(uncertainty_bundle, dict) else None,
                ci_level=0.95,
            )
            if isinstance(step_se_tbl, pd.DataFrame) and not step_se_tbl.empty:
                key_cols = [c for c in ("StepFacet", "Step") if c in steps_tbl.columns and c in step_se_tbl.columns]
                if key_cols:
                    res["steps"] = steps_tbl.merge(step_se_tbl, on=key_cols, how="left")
    except Exception:
        pass

    reliability_tbl = calc_reliability(measures)
    krippendorff_alpha_tbl = calc_krippendorff_alpha_by_facet(
        obs_df,
        ["Person"] + list(res["config"]["facet_names"]),
    )

    # PCA of standardised residuals
    facet_names = res["config"]["facet_names"]
    pca_overall = None
    pca_by_facet = {}
    pca_reason: dict | None = None
    # Reason payloads are stored as dicts ({"key": ..., "kwargs": ...}) so
    # the Dimensionality tab can re-translate them on every rerun even
    # when the user toggles the sidebar language after the run completes.
    pca_by_facet_reasons: dict[str, dict] = {}
    if compute_pca:
        try:
            pca_overall = compute_pca_overall(obs_df, facet_names)
            if pca_overall is None:
                pca_reason = diagnose_pca_skip_reason(obs_df, facet_names, mode="overall")
        except Exception as exc:
            pca_overall = None
            pca_reason = _make_reason(
                "dimensionality.exception_overall_template",
                error_type=type(exc).__name__,
                error=str(exc),
            )
        try:
            pca_by_facet = compute_pca_by_facet(obs_df, facet_names)
            # Record a per-facet skip reason so each Dimensionality sub-tab
            # can show *why* its panel is empty even when overall PCA succeeded.
            for facet in facet_names or []:
                bundle = pca_by_facet.get(facet) if isinstance(pca_by_facet, dict) else None
                if bundle is None:
                    pca_by_facet_reasons[facet] = diagnose_pca_skip_reason(
                        obs_df, facet_names, mode="facet", facet=facet,
                    )
        except Exception as exc:
            pca_by_facet = {}
            pca_by_facet_reasons = {
                facet: _make_reason(
                    "dimensionality.exception_facet_template",
                    error_type=type(exc).__name__,
                    error=str(exc),
                )
                for facet in (facet_names or [])
            }
    else:
        pca_reason = _make_reason("dimensionality.disabled_by_depth_setting")

    marginal_fit = {
        "available": False,
        "reason": "Strict marginal diagnostics were skipped for this run.",
        "summary": pd.DataFrame(),
        "counts": pd.DataFrame(),
        "pairwise": {"available": False, "reason": "Strict marginal diagnostics were skipped.", "summary": pd.DataFrame(), "counts": pd.DataFrame()},
    }
    if compute_marginal:
        try:
            marginal_fit = compute_marginal_fit_diagnostics(
                res,
                include_pairwise=bool(marginal_pairwise),
                max_pair_cells=int(marginal_max_pair_cells),
            )
        except Exception as marg_exc:
            marginal_fit = {
                "available": False,
                "reason": f"Strict marginal diagnostics failed: {marg_exc}",
                "summary": pd.DataFrame(),
                "counts": pd.DataFrame(),
                "pairwise": {"available": False, "reason": f"Strict marginal diagnostics failed: {marg_exc}", "summary": pd.DataFrame(), "counts": pd.DataFrame()},
            }

    if compute_eb_shrinkage:
        shrinkage = compute_empirical_bayes_shrinkage(measures)
    else:
        shrinkage = {
            "available": False,
            "reason": "Empirical-Bayes shrinkage was not requested for this run.",
            "measures": pd.DataFrame(),
            "report": pd.DataFrame(),
        }

    return {
        "obs": obs_df,
        "overall_fit": overall_fit,
        "measures": measures,
        "fit": fit_tbl,
        "reliability": reliability_tbl,
        "krippendorff_alpha": krippendorff_alpha_tbl,
        "bias": bias_tbl,
        "interactions": interaction_tbl,
        "pca": pca_overall,
        "pca_by_facet": pca_by_facet,
        "pca_reason": pca_reason,
        "pca_by_facet_reasons": pca_by_facet_reasons,
        "pca_enabled": bool(compute_pca),
        "marginal_fit": marginal_fit,
        "marginal_fit_enabled": bool(compute_marginal),
        "eb_shrinkage": shrinkage,
        "eb_shrinkage_enabled": bool(compute_eb_shrinkage),
        "uncertainty": uncertainty_bundle,
        "fit_df_method": fit_df_method,
        "fit_zstd_transform": fit_zstd_transform_label(whexact),
        "facets_zstd_cap": (
            float(facets_zstd_cap)
            if (facets_zstd_cap is not None and np.isfinite(facets_zstd_cap) and facets_zstd_cap > 0)
            else None
        ),
    }


