def _bundled_asset_path(relative_path: str) -> Path:
    """Resolve a bundled static asset under the app directory."""
    root = Path(__file__).resolve().parent / "anchor_templates_and_guideline"
    path = (root / relative_path).resolve()
    try:
        path.relative_to(root.resolve())
    except ValueError as exc:
        raise ValueError(f"Asset path escapes the bundled asset directory: {relative_path}") from exc
    return path


def _bundled_asset_stamp(relative_path: str) -> tuple[str, int, int]:
    path = _bundled_asset_path(relative_path)
    stat = path.stat()
    return relative_path, int(stat.st_size), int(stat.st_mtime_ns)


@st.cache_data(show_spinner=False, max_entries=8)
def cached_bundled_asset_bytes(relative_path: str, asset_stamp: tuple[str, int, int]) -> bytes:
    """Cache static bundled template/guideline bytes; never used for uploaded data."""
    _ = asset_stamp
    return _bundled_asset_path(relative_path).read_bytes()


def get_bundled_asset_bytes(relative_path: str) -> bytes:
    return cached_bundled_asset_bytes(relative_path, _bundled_asset_stamp(relative_path))


def get_bundled_asset_text(relative_path: str) -> str:
    return get_bundled_asset_bytes(relative_path).decode("utf-8")


@lru_cache(maxsize=1)
def get_runtime_build_id() -> str:
    for env_key in APP_BUILD_ENV_KEYS:
        env_value = os.environ.get(env_key, "").strip()
        if re.fullmatch(r"[0-9a-fA-F]{7,40}", env_value):
            return env_value[:7].lower()

    try:
        completed = subprocess.run(
            ["git", "rev-parse", "--short=7", "HEAD"],
            cwd=Path(__file__).resolve().parent,
            check=True,
            capture_output=True,
            text=True,
            timeout=2,
        )
    except Exception:
        return "unknown"

    build_id = completed.stdout.strip()
    if re.fullmatch(r"[0-9a-fA-F]{7,40}", build_id):
        return build_id[:7].lower()
    return "unknown"


def render_app_scope_badges(where: str = "main") -> None:
    build_id = get_runtime_build_id()
    text = (
        f"{APP_RELEASE_LABEL} {APP_VERSION} | standalone Python runtime | "
        f"source commit: {build_id} | "
        "no mfrmr/rpy2/Rscript/FACETS/TAM/sirt/mirt engine call"
    )
    if where == "sidebar":
        st.sidebar.caption(text)
    else:
        st.caption(text)
        with st.expander("Public beta boundaries", expanded=False):
            st.caption(
                "These boundaries are part of the app's public-beta claim. "
                "They prevent over-claiming cross-package equivalence or confirmatory statistical evidence."
            )
            st.dataframe(public_beta_limitations_table(), width="stretch", hide_index=True)


def render_data_privacy_notice(where: str = "main") -> None:
    if where == "sidebar":
        st.sidebar.warning(DATA_PRIVACY_NOTICE)
    else:
        st.warning(DATA_PRIVACY_NOTICE)


def build_data_source_options() -> list[dict]:
    """Flat data-source radio options: samples, simulation, paste, upload.

    Scenario labels stay in their data-driven form (English, sourced from
    ``SAMPLE_DATA_SCENARIOS``) — translating them would require localizing
    the scenario registry itself, which is deferred. The non-scenario
    options resolve through ``t()`` so the radio matches the active
    sidebar locale.
    """
    options: list[dict] = []
    for key, meta in SAMPLE_DATA_SCENARIOS.items():
        options.append({
            "label": meta["label"],
            "kind": "scenario",
            "scenario_key": key,
        })
    options.append({"label": t("data_source.option_simulate"), "kind": "simulate", "scenario_key": None})
    options.append({"label": t("data_source.option_paste"), "kind": "paste", "scenario_key": None})
    options.append({"label": t("data_source.option_upload"), "kind": "upload", "scenario_key": None})
    return options


def render_custom_simulation_source() -> pd.DataFrame:
    """Render sidebar controls for a user-configurable synthetic dataset."""
    st.sidebar.info(t("data_source.sim_info"))
    st.sidebar.caption(t("data_source.sim_method_caption"))
    selected_design_preset = str(st.sidebar.selectbox(
        t("data_source.sim_design_preset_label"),
        options=list(CUSTOM_SIMULATION_DESIGN_PRESET_KEYS),
        index=0,
        format_func=lambda key: t(f"data_source.sim_design_preset_{key}"),
        key="sim_design_preset",
        help=t("data_source.sim_design_preset_help"),
    ))
    st.sidebar.caption(t(f"data_source.sim_design_preset_{selected_design_preset}_caption"))
    if st.sidebar.button(
        t("data_source.sim_design_preset_apply_button"),
        key="sim_design_preset_apply",
        use_container_width=True,
    ):
        preset = get_custom_simulation_design_preset_settings(selected_design_preset)
        st.session_state["sim_n_person"] = int(preset["n_person"])
        st.session_state["sim_n_facets"] = int(preset["n_facets"])
        st.session_state["sim_n_categories"] = int(preset["n_categories"])
        st.session_state["sim_theta_sd"] = float(preset["theta_sd"])
        st.session_state["sim_noise_sd"] = float(preset["noise_sd"])
        st.session_state["sim_missing_rate"] = float(preset["missing_rate"])
        st.session_state["sim_threshold_mode"] = "even"
        st.session_state["sim_step_span"] = float(preset["step_span"])
        facet_names = list(preset["facet_names"])
        facet_level_counts = [int(x) for x in preset["facet_level_counts"]]
        facet_sds = [float(x) for x in preset["facet_sds"]]
        for idx, facet in enumerate(facet_names):
            st.session_state[f"sim_facet_name_{idx}"] = str(facet)
        for idx, level_count in enumerate(facet_level_counts):
            st.session_state[f"sim_facet_levels_{idx}"] = int(level_count)
        for idx, facet_sd in enumerate(facet_sds):
            st.session_state[f"sim_facet_sd_{idx}"] = float(facet_sd)
        first_level_count = int(facet_level_counts[0])
        st.session_state[f"sim_first_facet_levels_per_person_{first_level_count}"] = int(
            preset["first_facet_levels_per_person"]
        )
        zero_count_score = preset["zero_count_score"]
        st.session_state["sim_zero_count_enabled"] = zero_count_score is not None
        if zero_count_score is not None:
            st.session_state[f"sim_zero_count_score_{int(preset['n_categories'])}"] = int(zero_count_score)
        for cache_key in (
            "_loaded_custom_simulation_meta",
            "_custom_simulation_preview_bundle",
            "_custom_simulation_facet_names",
            "_custom_simulation_score_support",
        ):
            st.session_state.pop(cache_key, None)
        st.sidebar.info(t("data_source.sim_design_preset_applied_template", preset=t(f"data_source.sim_design_preset_{selected_design_preset}")))
        st.rerun()

    with st.sidebar.expander(t("data_source.sim_design_expander"), expanded=True):
        n_person = int(st.number_input(
            t("data_source.sim_n_person_label"),
            min_value=10, max_value=200, value=50, step=5,
            key="sim_n_person",
            help=t("data_source.sim_n_person_help"),
        ))
        n_facets = int(st.number_input(
            t("data_source.sim_n_facets_label"),
            min_value=2, max_value=6, value=3, step=1,
            key="sim_n_facets",
            help=t("data_source.sim_n_facets_help"),
        ))
        n_categories = int(st.number_input(
            t("data_source.sim_n_categories_label"),
            min_value=2, max_value=7, value=5, step=1,
            key="sim_n_categories",
            help=t("data_source.sim_n_categories_help"),
        ))
        zero_count_enabled = st.checkbox(
            t("data_source.sim_zero_count_enabled_label"),
            value=False,
            key="sim_zero_count_enabled",
            help=t("data_source.sim_zero_count_enabled_help"),
        )
        zero_count_score: int | None = None
        if zero_count_enabled:
            zero_count_score = int(st.selectbox(
                t("data_source.sim_zero_count_score_label"),
                options=list(range(n_categories)),
                index=min(3, n_categories - 1),
                key=f"sim_zero_count_score_{n_categories}",
                help=t("data_source.sim_zero_count_score_help"),
            ))
            st.caption(t("data_source.sim_zero_count_caption"))

        default_names = default_custom_simulation_facet_names(n_facets)
        facet_names_raw: list[str] = []
        facet_level_counts: list[int] = []
        st.markdown(f"**{t('data_source.sim_facets_expander')}**")
        for idx in range(n_facets):
            col_name, col_levels = st.columns([1.2, 0.8])
            with col_name:
                facet_names_raw.append(st.text_input(
                    t("data_source.sim_facet_name_label_template", index=idx + 1),
                    value=default_names[idx],
                    key=f"sim_facet_name_{idx}",
                ))
            with col_levels:
                default_count = [4, 2, 4, 2, 2, 2][idx] if idx < 6 else 2
                facet_level_counts.append(int(st.number_input(
                    t("data_source.sim_facet_levels_label_template", index=idx + 1),
                    min_value=2,
                    max_value=12,
                    value=default_count,
                    step=1,
                    key=f"sim_facet_levels_{idx}",
                )))
        facet_names = sanitize_custom_simulation_facet_names(facet_names_raw)
        first_facet_levels_per_person = int(st.number_input(
            t("data_source.sim_first_facet_levels_per_person_label_template", facet=facet_names[0]),
            min_value=1,
            max_value=facet_level_counts[0],
            value=min(2, facet_level_counts[0]),
            step=1,
            key=f"sim_first_facet_levels_per_person_{facet_level_counts[0]}",
            help=t("data_source.sim_first_facet_levels_per_person_help"),
        ))

    with st.sidebar.expander(t("data_source.sim_parameters_expander"), expanded=False):
        theta_sd = float(st.number_input(
            t("data_source.sim_theta_sd_label"),
            min_value=0.0, max_value=3.0, value=1.0, step=0.1,
            format="%.2f", key="sim_theta_sd",
        ))
        facet_sds: list[float] = []
        for idx, facet in enumerate(facet_names):
            default_sd = [0.35, 0.25, 0.25, 0.20, 0.20, 0.20][idx] if idx < 6 else 0.20
            facet_sds.append(float(st.number_input(
                t("data_source.sim_facet_sd_label_template", facet=facet),
                min_value=0.0, max_value=2.0, value=default_sd, step=0.05,
                format="%.2f", key=f"sim_facet_sd_{idx}",
            )))
        noise_sd = float(st.number_input(
            t("data_source.sim_noise_sd_label"),
            min_value=0.0, max_value=2.0, value=0.0, step=0.05,
            format="%.2f", key="sim_noise_sd",
            help=t("data_source.sim_noise_sd_help"),
        ))
        missing_rate = float(st.slider(
            t("data_source.sim_missing_rate_label"),
            min_value=0.0, max_value=0.50, value=0.0, step=0.01,
            key="sim_missing_rate",
            help=t("data_source.sim_missing_rate_help"),
        ))

    step_span = 2.0
    thresholds = default_custom_simulation_thresholds(n_categories, step_span=step_span)
    with st.sidebar.expander(t("data_source.sim_thresholds_expander"), expanded=False):
        threshold_mode = st.radio(
            t("data_source.sim_threshold_mode_label"),
            options=["even", "custom"],
            format_func=lambda v: (
                t("data_source.sim_threshold_mode_even")
                if v == "even"
                else t("data_source.sim_threshold_mode_custom")
            ),
            horizontal=True,
            key="sim_threshold_mode",
        )
        if threshold_mode == "custom":
            default_text = ", ".join(f"{x:.2f}" for x in thresholds)
            threshold_text = st.text_input(
                t("data_source.sim_threshold_text_label"),
                value=default_text,
                key=f"sim_threshold_text_{n_categories}",
                help=t("data_source.sim_threshold_text_help"),
            )
            try:
                thresholds = parse_custom_simulation_thresholds(
                    threshold_text, n_categories,
                )
            except ValueError as exc:
                st.sidebar.error(t("data_source.sim_threshold_error_template", error=str(exc)))
                st.session_state.pop("_loaded_custom_simulation_meta", None)
                st.session_state.pop("_custom_simulation_preview_bundle", None)
                st.session_state.pop("_custom_simulation_facet_names", None)
                return pd.DataFrame()
        else:
            step_span = float(st.slider(
                t("data_source.sim_step_span_label"),
                min_value=0.5, max_value=4.0, value=2.0, step=0.1,
                key="sim_step_span",
                help=t("data_source.sim_step_span_help"),
            ))
            thresholds = default_custom_simulation_thresholds(
                n_categories, step_span=step_span,
            )
            st.caption(t(
                "data_source.sim_threshold_preview_template",
                thresholds=", ".join(f"{x:.2f}" for x in thresholds),
            ))
        if thresholds.size > 1 and np.any(np.diff(thresholds) <= 0):
            st.warning(t("data_source.sim_threshold_order_warning"))

    seed = int(st.sidebar.number_input(
        t("data_source.sim_seed_label"),
        min_value=1, max_value=2_147_483_647, value=20260515, step=1,
        key="sim_seed",
        help=t("data_source.sim_seed_help"),
    ))

    expected_rows = int(n_person * first_facet_levels_per_person * np.prod(facet_level_counts[1:], dtype=np.int64))
    expected_after_missing = int(round(expected_rows * (1.0 - missing_rate)))
    st.sidebar.caption(t(
        "data_source.sim_expected_rows_template",
        n_rows=f"{expected_after_missing:,}",
        full_rows=f"{expected_rows:,}",
    ))
    if expected_rows > 100_000:
        st.sidebar.error(t("data_source.sim_size_error"))
        st.session_state.pop("_loaded_custom_simulation_meta", None)
        st.session_state.pop("_custom_simulation_preview_bundle", None)
        st.session_state.pop("_custom_simulation_facet_names", None)
        return pd.DataFrame()
    if expected_rows >= 50_000:
        st.sidebar.warning(t("data_source.sim_size_warning"))

    sim_bundle = cached_custom_mfrm_simulation_bundle(
        n_person,
        tuple(facet_names),
        tuple(int(x) for x in facet_level_counts),
        tuple(float(x) for x in facet_sds),
        first_facet_levels_per_person,
        n_categories,
        theta_sd,
        tuple(float(x) for x in thresholds),
        step_span,
        noise_sd,
        missing_rate,
        zero_count_score,
        seed,
    )
    sim_df = sim_bundle["data"].copy()
    st.sidebar.download_button(
        t("data_source.sim_download_button"),
        data=to_csv_bytes(sim_df),
        file_name="mfrm_custom_simulation.csv",
        mime="text/csv",
        key="custom_simulation_download",
        help=t("data_source.sim_download_help"),
        use_container_width=True,
    )
    st.session_state.pop("_loaded_sample_scenario_key", None)
    st.session_state["_custom_simulation_preview_bundle"] = sim_bundle
    st.session_state["_custom_simulation_facet_names"] = facet_names
    st.session_state["_custom_simulation_score_support"] = {
        "rating_min": 0,
        "rating_max": n_categories - 1,
        "zero_count_score": zero_count_score,
    }
    st.session_state["_loaded_custom_simulation_meta"] = {
        "design_preset": selected_design_preset,
        "n_person": n_person,
        "n_facets": n_facets,
        "facet_names": facet_names,
        "facet_level_counts": facet_level_counts,
        "facet_sds": facet_sds,
        "first_facet_levels_per_person": first_facet_levels_per_person,
        "n_categories": n_categories,
        "theta_sd": theta_sd,
        "threshold_mode": threshold_mode,
        "thresholds": [float(x) for x in thresholds],
        "step_span": step_span,
        "noise_sd": noise_sd,
        "missing_rate": missing_rate,
        "n_obs": int(len(sim_df)),
        "zero_count_score": zero_count_score,
        "seed": seed,
    }
    return sim_df


def read_input_data(core: dict) -> pd.DataFrame:
    # v0.2.8-beta: Flat single-radio data-source picker. Previously the
    # user faced a two-step flow (Sample data radio → Sample scenario
    # selectbox) where the scenario switch was easy to miss. Now all
    # sample scenarios are first-class options alongside Paste and
    # Upload, so the scenario switcher is impossible to overlook.
    st.sidebar.markdown(f"### {t('data_source.header')}")

    # Build the option list: scenarios first (in registry order), then
    # simulation / paste / upload. Each entry records its kind so we can
    # dispatch without string-matching the label.
    _options = build_data_source_options()
    _option_labels = [opt["label"] for opt in _options]

    # Default to the writing-essay scenario so existing onboarding
    # tours and screenshots still match without user action.
    default_idx = 0
    for i, opt in enumerate(_options):
        if opt.get("scenario_key") == DEFAULT_SAMPLE_SCENARIO_KEY:
            default_idx = i
            break

    _n_scenarios = len(SAMPLE_DATA_SCENARIOS)
    chosen_label = st.sidebar.radio(
        t("data_source.radio_prompt_template", n_scenarios=_n_scenarios),
        options=_option_labels,
        index=default_idx,
        key="data_source_flat",
    )
    chosen = _options[_option_labels.index(chosen_label)]

    if chosen["kind"] == "scenario":
        scenario_key = chosen["scenario_key"]
        scenario = SAMPLE_DATA_SCENARIOS[scenario_key]
        dims = scenario["dimensions"]

        # Inline info card (always visible — no expander gate). Users
        # immediately see what they just selected: dimensions, obs
        # count, and one-line diagnostic hint. Full description +
        # references move to a secondary expander below.
        st.sidebar.info(t(
            "data_source.scenario_info_template",
            label=scenario["label"],
            persons=dims["persons"],
            raters=dims["raters"],
            tasks=dims["tasks"],
            criteria=dims["criteria"],
            n_obs=f"{scenario['n_obs']:,}",
            n_cat=dims["n_cat"],
            short=scenario["short"],
        ))

        # Full description + APA references in a collapsed expander
        # so the info card stays compact. Opening this gives users
        # everything they need to cite the scenario in a manuscript.
        with st.sidebar.expander(t("data_source.full_description_expander")):
            st.markdown(scenario["description"])
            citations = scenario.get("citations", [])
            if citations:
                st.markdown(t("data_source.parameter_values_grounded_label"))
                keys_seen: set[str] = set()
                for cite in citations:
                    key = _CITATION_TO_KEY.get(cite)
                    if key and key in _APA_REFERENCE_LIBRARY:
                        keys_seen.add(key)
                if keys_seen:
                    for entry in sorted(
                        _APA_REFERENCE_LIBRARY[k] for k in keys_seen
                    ):
                        st.markdown(f"- {entry}")
                else:
                    st.caption(t("data_source.references_pending_caption"))

        sample_df = cached_sample_mfrm_data_by_key(
            scenario_key, seed=20240101,
        ).copy()
        st.sidebar.download_button(
            t("data_source.download_scenario_button"),
            data=sample_df.to_csv(index=False).encode("utf-8"),
            file_name=f"mfrm_sample_{scenario_key}.csv",
            mime="text/csv",
            key="sample_data_download",
            help=t("data_source.download_scenario_help"),
            use_container_width=True,
        )
        # Remember which scenario is loaded so the main area can
        # surface a matching banner above the results tabs.
        st.session_state["_loaded_sample_scenario_key"] = scenario_key
        st.session_state.pop("_loaded_custom_simulation_meta", None)
        st.session_state.pop("_custom_simulation_preview_bundle", None)
        st.session_state.pop("_custom_simulation_facet_names", None)
        st.session_state.pop("_custom_simulation_score_support", None)
        return sample_df

    if chosen["kind"] == "simulate":
        return render_custom_simulation_source()

    # Non-scenario paths clear the loaded-scenario marker so the
    # main-area banner does not lie about the data source.
    st.session_state.pop("_loaded_sample_scenario_key", None)
    st.session_state.pop("_loaded_custom_simulation_meta", None)
    st.session_state.pop("_custom_simulation_preview_bundle", None)
    st.session_state.pop("_custom_simulation_facet_names", None)
    st.session_state.pop("_custom_simulation_score_support", None)

    if chosen["kind"] == "paste":
        render_data_privacy_notice(where="sidebar")
        paste_delimiter = st.sidebar.selectbox(
            t("data_source.delimiter_label"),
            list(TABLE_DELIMITER_OPTIONS.keys()),
            index=0,
            key="paste_data_delimiter",
            help=t("data_source.paste_delimiter_help"),
        )
        text_value = st.sidebar.text_area(
            t("data_source.paste_textarea_label"),
            height=180,
            placeholder=TEACHER_PASTE_EXAMPLE_CSV,
            help=t("data_source.paste_textarea_help"),
        )
        with st.sidebar.expander(
            t("data_source.teacher_paste_guide_expander"),
            expanded=not bool(text_value.strip()),
        ):
            st.markdown(t("data_source.teacher_paste_guide_body"))
            st.code(TEACHER_PASTE_EXAMPLE_CSV, language="csv")
            st.download_button(
                t("data_source.download_teacher_template_button"),
                data=TEACHER_PASTE_EXAMPLE_CSV.encode("utf-8"),
                file_name="mfrm_teacher_paste_template.csv",
                mime="text/csv",
                key="teacher_paste_template_download",
                use_container_width=True,
            )
        if not text_value.strip():
            return pd.DataFrame()
        try:
            parsed = core["read_flexible_table"](text_value, None, header=True, delimiter=paste_delimiter)
        except Exception as exc:
            st.sidebar.error(t("data_source.paste_parse_error"))
            with st.sidebar.expander(t("data_source.technical_parse_details_expander"), expanded=False):
                render_exception_details(exc)
            return pd.DataFrame()
        if parsed.shape[1] < 2:
            st.sidebar.warning(t("data_source.single_column_warning_paste"))
        else:
            preview_cols = ", ".join(map(str, parsed.columns[:5]))
            st.sidebar.caption(t(
                "data_source.detected_columns_caption_template",
                n_cols=parsed.shape[1],
                preview_cols=preview_cols,
                ellipsis="..." if parsed.shape[1] > 5 else "",
            ))
        return maybe_apply_wide_to_long_sidebar(parsed, key_prefix="paste")

    render_data_privacy_notice(where="sidebar")
    upload_delimiter = st.sidebar.selectbox(
        t("data_source.delimiter_label"),
        list(TABLE_DELIMITER_OPTIONS.keys()),
        index=0,
        key="upload_data_delimiter",
        help=t("data_source.upload_delimiter_help"),
    )
    upload = st.sidebar.file_uploader(
        t("data_source.upload_file_label"),
        type=TABLE_FILE_UPLOAD_TYPES,
        help=t("data_source.upload_file_help_template", file_label=TABLE_FILE_UPLOAD_LABEL),
    )
    if upload is None:
        return pd.DataFrame()
    # Preflight: warn before parsing if the file is so large that it may
    # OOM the Streamlit Cloud instance. 50 MB is the soft warning; 100 MB
    # is a hard stop in the Streamlit UI.
    upload_size_mb = 0.0
    try:
        upload_size_mb = float(getattr(upload, "size", 0) or 0) / (1024 * 1024)
    except (TypeError, ValueError):
        upload_size_mb = 0.0
    if upload_size_mb >= TABLE_FILE_HARD_LIMIT_MB:
        st.sidebar.error(t(
            "data_source.upload_size_blocked_template",
            size_mb=f"{upload_size_mb:.0f}",
            limit_mb=TABLE_FILE_HARD_LIMIT_MB,
        ))
        return pd.DataFrame()
    elif upload_size_mb >= TABLE_FILE_SOFT_WARNING_MB:
        st.sidebar.warning(t(
            "data_source.upload_size_warning_template",
            size_mb=f"{upload_size_mb:.0f}",
        ))
    try:
        parsed = core["read_flexible_table"]("", upload, header=True, delimiter=upload_delimiter)
    except Exception as exc:
        st.sidebar.error(t("data_source.upload_parse_error"))
        with st.sidebar.expander(t("data_source.technical_parse_details_expander"), expanded=False):
            render_exception_details(exc)
        return pd.DataFrame()
    if parsed.shape[1] < 2:
        st.sidebar.warning(t("data_source.single_column_warning_upload"))
    else:
        preview_cols = ", ".join(map(str, parsed.columns[:5]))
        st.sidebar.caption(t(
            "data_source.detected_columns_caption_template",
            n_cols=parsed.shape[1],
            preview_cols=preview_cols,
            ellipsis="..." if parsed.shape[1] > 5 else "",
        ))

    return maybe_apply_wide_to_long_sidebar(parsed, key_prefix="upload")


