# ---------------------------------------------------------------------------
# Top-level warnings (above tabs)
# ---------------------------------------------------------------------------

def _show_top_level_warnings(
    result: dict,
    diagnostics: dict,
    data: pd.DataFrame,
    person_col: str,
    facet_cols: list[str],
    score_col: str,
    core: dict | None,
) -> None:
    """Show critical warnings above the tabs so they are always visible."""
    alerts: list[tuple[str, str]] = []  # (level, message)

    # 1. Convergence
    opt = result.get("opt", None)
    converged = getattr(opt, "success", None) if opt is not None else None
    if converged is not None and not converged:
        opt_msg = getattr(opt, "message", "unknown reason")
        alerts.append((
            "error",
            f"**Estimation did not converge** ({opt_msg}). "
            "Results may be unreliable. Consider increasing `maxit` or relaxing `reltol`."
        ))

    # 2. Disconnected subsets
    calc_subsets_fn = core.get("calc_subsets") if core else None
    if calc_subsets_fn and diagnostics.get("obs") is not None:
        try:
            config_facet_names = result.get("config", {}).get("facet_names", facet_cols)
            subsets = calc_subsets_fn(diagnostics["obs"], ["Person"] + list(config_facet_names))
            if subsets and not subsets.get("summary", pd.DataFrame()).empty:
                n_sub = len(subsets["summary"])
                if n_sub >= 2:
                    alerts.append((
                        "warning",
                        f"**{n_sub} disconnected subsets** detected. "
                        "Estimates across subsets are not on a common scale."
                    ))
        except Exception as conn_exc:
            alerts.append(("warning", f"Connectivity analysis failed: {conn_exc}"))

    # 3. Global fit — observation-level residuals
    obs_df = diagnostics.get("obs", pd.DataFrame())
    if not obs_df.empty and "StdResidual" in obs_df.columns:
        std_res = pd.to_numeric(obs_df["StdResidual"], errors="coerce").dropna()
        if len(std_res) > 0:
            pct_ge2 = float((std_res.abs() >= 2).mean() * 100)
            if pct_ge2 > FINAL_RESIDUAL_PCT_GE2_READY:
                severity = "well above" if pct_ge2 > FINAL_RESIDUAL_PCT_GE2_REVIEW else "above"
                alerts.append((
                    "warning",
                    f"**{pct_ge2:.1f}%** of observations have |z| >= 2 "
                    f"({severity} the {FINAL_RESIDUAL_PCT_GE2_READY:.0f}% final-report readiness benchmark). "
                    "Inspect Fit Details and Bias/Interaction before final reporting."
                ))

    # 4. High missing rate
    n_missing = data[score_col].isna().sum()
    pct_missing = 100 * n_missing / len(data) if len(data) > 0 else 0
    if pct_missing > 20:
        alerts.append((
            "warning",
            f"**High missing rate**: {pct_missing:.1f}% of observations have missing scores."
        ))

    # 5. Anchor / linking audit
    anchor_audit = result.get("config", {}).get("anchor_audit", {})
    if isinstance(anchor_audit, dict) and anchor_audit.get("overall_status") in {"error", "warning"}:
        issues = anchor_audit.get("issues", pd.DataFrame())
        n_issues = len(issues) if isinstance(issues, pd.DataFrame) else 0
        alerts.append((
            "warning" if anchor_audit.get("overall_status") == "warning" else "error",
            f"**Anchor audit**: {n_issues} issue(s) found. "
            "Open the Data tab's Anchor/linking audit before making linking claims."
        ))

    # 6. Strict marginal diagnostics
    marginal_fit = diagnostics.get("marginal_fit", {})
    if isinstance(marginal_fit, dict) and marginal_fit.get("available"):
        n_review = int(marginal_fit.get("n_review", 0) or 0)
        if n_review > 0:
            alerts.append((
                "warning",
                f"**Strict marginal diagnostics**: {n_review} row(s) flagged for review. "
                "Open Fit Details > Strict marginal diagnostics before final reporting."
            ))

    # Display
    if not alerts:
        st.success(
            f"Estimation completed successfully for {len(data):,} observations, "
            f"{data[person_col].nunique():,} persons, and {len(facet_cols)} facets."
        )
    else:
        has_error = any(level == "error" for level, _ in alerts)
        if has_error:
            st.error("Estimation completed with critical issues:")
        else:
            st.warning("Estimation completed with warnings:")
        for level, msg in alerts:
            if level == "error":
                st.error(msg)
            else:
                st.warning(msg)


def build_first_read_guide_rows(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> list[dict[str, str]]:
    """Build the guided first-read checklist rows."""
    rows: list[dict[str, str]] = []

    opt = result.get("opt")
    converged = bool(getattr(opt, "success", False))
    opt_msg = str(getattr(opt, "message", "") or "")
    rows.append({
        "Check": "1. Convergence",
        "Status": "OK" if converged else "Do not interpret yet",
        "What it means": (
            "Optimizer reached its stopping rule."
            if converged else
            f"Optimizer did not converge. {opt_msg[:120]}"
        ),
        "Next action": (
            "Continue to reliability and fit."
            if converged else
            "Increase maxit, relax reltol slightly, simplify the model, or inspect sparse/extreme data."
        ),
    })

    config = result.get("config", {})
    if config.get("model") == "GPCM":
        slope_tbl = result.get("slopes", pd.DataFrame())
        slope_vals = (
            pd.to_numeric(slope_tbl.get("Estimate", pd.Series(dtype=float)), errors="coerce").dropna()
            if isinstance(slope_tbl, pd.DataFrame) else pd.Series(dtype=float)
        )
        if len(slope_vals):
            ratio = float(slope_vals.max() / slope_vals.min()) if slope_vals.min() > 0 else np.nan
            status = "OK" if np.isfinite(ratio) and ratio <= 3.0 else "Review"
            rows.append({
                "Check": "1b. GPCM slope spread",
                "Status": status,
                "What it means": (
                    f"Slope range is {slope_vals.min():.2f} to {slope_vals.max():.2f}; "
                    "geometric mean is fixed to 1."
                ),
                "Next action": (
                    "Interpret slopes as exploratory discrimination differences, not ordinary Rasch severities."
                    if status == "OK" else
                    "Open Categories/Steps and confirm that sparse categories are not driving extreme slopes."
                ),
            })
        else:
            rows.append({
                "Check": "1b. GPCM slope spread",
                "Status": "Review",
                "What it means": "GPCM was selected but slope estimates are unavailable.",
                "Next action": "Re-run estimation or switch to PCM/RSM if slope parameters are not part of the analysis question.",
            })

    obs_df = diagnostics.get("obs", pd.DataFrame())
    if isinstance(obs_df, pd.DataFrame) and not obs_df.empty and "StdResidual" in obs_df.columns:
        z = pd.to_numeric(obs_df["StdResidual"], errors="coerce").dropna()
        pct_ge2 = float((z.abs() >= 2).mean() * 100) if len(z) else np.nan
        status = (
            "OK" if np.isfinite(pct_ge2) and pct_ge2 <= FINAL_RESIDUAL_PCT_GE2_READY
            else "Review" if np.isfinite(pct_ge2) and pct_ge2 <= FINAL_RESIDUAL_PCT_GE2_REVIEW
            else "Caution"
        )
        rows.append({
            "Check": "2. Global residual fit",
            "Status": status,
            "What it means": f"{pct_ge2:.1f}% of observations have |z| >= 2." if np.isfinite(pct_ge2) else "Residual summary unavailable.",
            "Next action": (
                "Move to element fit and bias checks."
                if status == "OK" else
                "Inspect Fit Details and Bias/Interaction before reporting; final-report Ready requires about 5% or fewer."
            ),
        })

    rel_df = diagnostics.get("reliability", pd.DataFrame())
    if (
        isinstance(rel_df, pd.DataFrame)
        and not rel_df.empty
        and {"Facet", "Reliability"}.issubset(rel_df.columns)
    ):
        rel_work = rel_df.copy()
        rel_work["Reliability"] = pd.to_numeric(rel_work["Reliability"], errors="coerce")
        person_rel = rel_work.loc[
            rel_work["Facet"].astype(str).str.strip().str.lower() == "person",
            "Reliability",
        ].dropna()
        if len(person_rel):
            rel_value = float(person_rel.iloc[0])
            status = (
                "OK" if rel_value >= FINAL_PERSON_RELIABILITY_READY
                else "Review" if rel_value >= FINAL_PERSON_RELIABILITY_REVIEW
                else "Caution"
            )
            meaning = f"Person reliability is {rel_value:.2f}; this supports or limits learner ordering claims."
            next_action = (
                "Use person ordering claims with the facet tables and fit checks."
                if status == "OK" else
                "Avoid strong learner-ranking claims; inspect person spread, task coverage, and score range."
            )
        else:
            nonperson_vals = rel_work["Reliability"].dropna()
            status = "Review"
            meaning = (
                "Person reliability is unavailable. Non-person facet reliability is not automatically better when high; "
                "for raters, low reliability can indicate desirable interchangeability."
            )
            next_action = (
                "Interpret reliability facet-by-facet: person reliability for learner ordering, "
                "rater reliability for interchangeability, task/criterion reliability for design spread."
                if len(nonperson_vals) else
                "Reliability values are unavailable; inspect estimation and data coverage first."
            )
        rows.append({
            "Check": "3. Reliability / separation",
            "Status": status,
            "What it means": meaning,
            "Next action": next_action,
        })

    pca_enabled = bool(diagnostics.get("pca_enabled", diagnostics.get("pca") is not None))
    pca = diagnostics.get("pca")
    if not pca_enabled:
        rows.append({
            "Check": "4. Dimensionality",
            "Status": "Skipped",
            "What it means": "Residual PCA was turned off for this run.",
            "Next action": "Enable residual PCA for final reporting or if fit looks suspicious.",
        })
    elif isinstance(pca, dict) and pca.get("eigenvalues") is not None:
        ev = np.asarray(pca.get("eigenvalues"), dtype=float)
        ev1 = float(ev[0]) if ev.size else np.nan
        stability_tbl = pca.get("stability_table")
        stability_status = ""
        stability_flags = ""
        if isinstance(stability_tbl, pd.DataFrame) and not stability_tbl.empty:
            stability_status = str(stability_tbl.iloc[0].get("PCAStabilityStatus", ""))
            stability_flags = str(stability_tbl.iloc[0].get("SensitivityFlagSummary", ""))
        status = (
            "OK" if np.isfinite(ev1) and ev1 < FINAL_PCA_EIGENVALUE_READY and stability_status != "Review"
            else "Review" if np.isfinite(ev1) and ev1 < FINAL_PCA_EIGENVALUE_REVIEW
            else "Caution"
        )
        meaning = f"First residual PCA eigenvalue is {ev1:.2f}."
        if stability_status:
            meaning += f" Stability audit: {stability_status}."
        if stability_flags and stability_flags != "none":
            meaning += f" Sensitivity flags: {stability_flags}."
        rows.append({
            "Check": "4. Dimensionality",
            "Status": status,
            "What it means": meaning,
            "Next action": (
                "Unidimensionality screen is stable enough for scoped reporting."
                if status == "OK" else
                "Open the Dimensionality tab and inspect residual PCA stability, loadings, and content."
            ),
        })

    all_bias = all_bias_results or {}
    if not all_bias:
        rows.append({
            "Check": "5. Bias interactions",
            "Status": "Skipped",
            "What it means": "No bias/interaction table was computed for this run.",
            "Next action": "Use Selected pair for a targeted check or Full publication for all-pair screening.",
        })
    else:
        bias_audit = build_bias_inference_audit(all_bias, result, diagnostics)
        n_total = int(pd.to_numeric(bias_audit.get("CellsScreened", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
        n_flagged = int(pd.to_numeric(bias_audit.get("FlaggedCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
        n_strong = int(pd.to_numeric(bias_audit.get("StrongReviewCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
        n_sparse = int(pd.to_numeric(bias_audit.get("SparseCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
        has_disconnected = (
            isinstance(bias_audit, pd.DataFrame)
            and "CommonScaleStatus" in bias_audit.columns
            and bias_audit["CommonScaleStatus"].astype(str).str.startswith("Review:").any()
        )
        if n_total == 0:
            status = "Review"
        elif n_flagged == 0 and n_sparse == 0 and not has_disconnected:
            status = "OK"
        elif n_strong or has_disconnected:
            status = "Caution"
        else:
            status = "Review"
        rows.append({
            "Check": "5. Bias interactions",
            "Status": status,
            "What it means": (
                f"{n_flagged} of {n_total} screened local interactions are DFF/bias review flags; "
                f"{n_strong} strong-review and {n_sparse} sparse cell(s)."
            ),
            "Next action": (
                "No computed local-bias flag in the conditional screen; keep claims limited to screened pairs."
                if status == "OK" else
                "Open Bias/Interaction and use the bias inference audit; interpret flags with multiplicity, sparsity, and connectedness."
            ),
        })

    anchor_audit = result.get("config", {}).get("anchor_audit", {})
    if isinstance(anchor_audit, dict):
        issues = anchor_audit.get("issues", pd.DataFrame())
        n_issues = len(issues) if isinstance(issues, pd.DataFrame) else 0
        overall = anchor_audit.get("overall_status", "ok")
        rows.append({
            "Check": "6. Anchor / linking audit",
            "Status": "OK" if overall == "ok" else ("Caution" if overall == "error" else "Review"),
            "What it means": (
                "No obvious anchor-input issues were found."
                if overall == "ok" else
                f"{n_issues} anchor/linking issue(s) were found."
            ),
            "Next action": (
                "Proceed if this is a single-run analysis; use anchors only when linking across runs."
                if overall == "ok" else
                "Open Data > Anchor/linking audit and fix or justify each issue before making linking claims."
            ),
        })

    marginal_fit = diagnostics.get("marginal_fit", {})
    if isinstance(marginal_fit, dict):
        if marginal_fit.get("available"):
            n_review = int(marginal_fit.get("n_review", 0) or 0)
            rows.append({
                "Check": "7. Strict marginal fit",
                "Status": "OK" if n_review == 0 else "Review",
                "What it means": f"{n_review} marginal distribution row(s) were flagged.",
                "Next action": (
                    "Use this as corroborating evidence with residual fit and category checks."
                    if n_review == 0 else
                    "Open Fit Details and inspect which facet/category marginal distributions differ from expectation."
                ),
            })
        elif diagnostics.get("marginal_fit_enabled"):
            rows.append({
                "Check": "7. Strict marginal fit",
                "Status": "Skipped",
                "What it means": marginal_fit.get("reason", "Marginal diagnostics were unavailable."),
                "Next action": "Use MML and enable strict marginal diagnostics for this screen.",
            })

    return rows


def first_read_guide_should_expand(rows: list[dict[str, str]]) -> bool:
    """Open the first-read guide automatically for blocking or caution states."""
    return any(str(row.get("Status", "")) in {"Do not interpret yet", "Caution"} for row in rows)


def _first_read_tab_hint(check: str) -> str:
    check_text = str(check)
    if "Convergence" in check_text:
        return "Report"
    if "GPCM" in check_text or "slope" in check_text:
        return "Categories/Steps"
    if "Global residual" in check_text or "Strict marginal" in check_text:
        return "Fit Details"
    if "Reliability" in check_text:
        return "Report"
    if "Dimensionality" in check_text:
        return "Dimensionality"
    if "Bias" in check_text:
        return "Bias/Interaction"
    if "Anchor" in check_text:
        return "Data"
    return "Report"


def _show_first_read_guide(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    rows: list[dict[str, str]] | None = None,
) -> None:
    """Render the first-read checklist with a single prioritized next stop."""
    guide_rows = rows if rows is not None else build_first_read_guide_rows(
        result, diagnostics, all_bias_results
    )
    guide_df = pd.DataFrame(guide_rows)
    if guide_df.empty:
        st.info("No first-read checks were generated for this run.")
        return

    priority_order = ["Do not interpret yet", "Caution", "Review", "Skipped"]
    priority_row = None
    for status in priority_order:
        hits = guide_df.loc[guide_df["Status"].astype(str) == status]
        if not hits.empty:
            priority_row = hits.iloc[0]
            break

    if priority_row is None:
        st.success("First read: no high-priority interpretation blockers were detected.")
    else:
        check = str(priority_row.get("Check", "Review result"))
        status = str(priority_row.get("Status", "Review"))
        tab_hint = _first_read_tab_hint(check)
        action = str(priority_row.get("Next action", "Review the flagged row before reporting."))
        if status in {"Do not interpret yet", "Caution"}:
            st.warning(f"Start with {tab_hint}: {check} is marked '{status}'. {action}")
        else:
            st.info(f"Suggested next stop: {tab_hint}. {check} is marked '{status}'. {action}")

    st.caption(
        "Read results in this order. Stop early if a row says 'Do not interpret yet' "
        "or 'Caution' and resolve that issue before writing final conclusions."
    )
    st.dataframe(guide_df, width="stretch", hide_index=True)


GUIDED_STATUS_PRIORITY = {
    "Do not interpret yet": 0,
    "Caution": 1,
    "Review": 2,
    "Skipped": 3,
    "OK": 4,
}


GUIDED_AREA_I18N_KEYS = {
    "Estimation": "guided.area_estimation",
    "Rating scale": "guided.area_rating_scale",
    "Fit": "guided.area_fit",
    "Measures": "guided.area_measures",
    "Assumptions": "guided.area_assumptions",
    "Bias / interaction": "guided.area_bias_interaction",
    "Data / linking": "guided.area_data_linking",
    "Reporting": "guided.area_reporting",
}


GUIDED_STATUS_I18N_KEYS = {
    "Do not interpret yet": "guided.status_do_not_interpret",
    "Caution": "guided.status_caution",
    "Review": "guided.status_review",
    "Skipped": "guided.status_skipped",
    "OK": "guided.status_ok",
}


def _guided_area_for_check(check: str) -> str:
    """Map a first-read check to a task area for the guided result view."""
    check_text = str(check)
    if "Convergence" in check_text:
        return "Estimation"
    if "GPCM" in check_text or "slope" in check_text:
        return "Rating scale"
    if "Global residual" in check_text or "Strict marginal" in check_text:
        return "Fit"
    if "Reliability" in check_text:
        return "Measures"
    if "Dimensionality" in check_text:
        return "Assumptions"
    if "Bias" in check_text:
        return "Bias / interaction"
    if "Anchor" in check_text:
        return "Data / linking"
    return "Reporting"


def _guided_area_label(area: str) -> str:
    return t(GUIDED_AREA_I18N_KEYS.get(str(area), "guided.area_reporting"), default=str(area))


def _guided_status_label(status: str) -> str:
    return t(GUIDED_STATUS_I18N_KEYS.get(str(status), "guided.status_review"), default=str(status))


def _guided_detail_location_label(location: str) -> str:
    key = "guided.detail_location_" + (
        str(location)
        .strip()
        .lower()
        .replace("/", "_")
        .replace("-", "_")
        .replace(" ", "_")
    )
    return t(key, default=str(location))


def build_guided_action_plan(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> pd.DataFrame:
    """Return the Essential-view action plan while preserving the detailed checks."""
    rows = build_first_read_guide_rows(result, diagnostics, all_bias_results)
    out: list[dict[str, object]] = []
    for source_order, row in enumerate(rows, start=1):
        check = str(row.get("Check", "Review result"))
        status = str(row.get("Status", "Review"))
        out.append({
            "Priority": GUIDED_STATUS_PRIORITY.get(status, 9),
            "SourceOrder": source_order,
            "Area": _guided_area_for_check(check),
            "Check": check,
            "Status": status,
            "WhatItSays": str(row.get("What it means", "")),
            "NextAction": str(row.get("Next action", "")),
            "DetailLocation": _first_read_tab_hint(check),
        })
    columns = [
        "Priority",
        "SourceOrder",
        "Area",
        "Check",
        "Status",
        "WhatItSays",
        "NextAction",
        "DetailLocation",
    ]
    if not out:
        return pd.DataFrame(columns=columns)
    plan = pd.DataFrame(out, columns=columns)
    plan = plan.sort_values(["Priority", "SourceOrder"], kind="stable").reset_index(drop=True)
    plan["Priority"] = [f"P{i}" for i in range(1, len(plan) + 1)]
    return plan


def guided_action_plan_display_frame(plan: pd.DataFrame, *, include_detail: bool = False) -> pd.DataFrame:
    """Build a display-only action-plan table with localized labels."""
    base_columns = [
        t("guided.col_priority"),
        t("guided.col_area"),
        t("guided.col_status"),
        t("guided.col_check"),
        t("guided.col_next_action"),
        t("guided.col_detail_location"),
    ]
    detail_columns = [
        t("guided.col_what_it_says"),
        t("guided.col_source_order"),
        t("guided.col_raw_status"),
    ]
    columns = base_columns + (detail_columns if include_detail else [])
    if not isinstance(plan, pd.DataFrame) or plan.empty:
        return pd.DataFrame(columns=columns)
    display = pd.DataFrame({
        t("guided.col_priority"): plan.get("Priority", pd.Series(dtype=str)).astype(str),
        t("guided.col_area"): plan.get("Area", pd.Series(dtype=str)).map(_guided_area_label),
        t("guided.col_status"): plan.get("Status", pd.Series(dtype=str)).map(_guided_status_label),
        t("guided.col_check"): plan.get("Check", pd.Series(dtype=str)).astype(str),
        t("guided.col_next_action"): plan.get("NextAction", pd.Series(dtype=str)).astype(str),
        t("guided.col_detail_location"): plan.get("DetailLocation", pd.Series(dtype=str)).map(_guided_detail_location_label),
    })
    if include_detail:
        display[t("guided.col_what_it_says")] = plan.get("WhatItSays", pd.Series(dtype=str)).astype(str)
        display[t("guided.col_source_order")] = plan.get("SourceOrder", pd.Series(dtype=str)).astype(str)
        display[t("guided.col_raw_status")] = plan.get("Status", pd.Series(dtype=str)).astype(str)
    return display


