GUIDED_GOAL_STEP_OPEN = {
    "check_readiness": ["First Read", "Report & Export", "Diagnostics"],
    "inspect_measures": ["Results", "Results", "Results / FACETS-style tables"],
    "diagnose_problem": ["First Read", "Diagnostics", "Report & Export"],
    "prepare_report": ["First Read", "Report & Export", "Report & Export"],
    "export_share": ["Report & Export", "Report & Export / Downloads", "Report & Export / Downloads"],
    "learn_terms": ["Learn", "Learn", "First Read"],
}


GUIDED_GOAL_IDS = tuple(GUIDED_GOAL_STEP_OPEN.keys())


GUIDED_GOAL_REVIEW_STATUSES = {
    "Caution",
    "Review",
    "Skipped",
}


GUIDED_FOCUS_CLAIM_CAVEAT_AREAS = {
    "Fit",
    "Assumptions",
    "Bias / interaction",
}


GUIDED_FOCUS_HARD_STOP_AREAS = {
    "Estimation",
    "Data / linking",
}


GUIDED_GOALS_THAT_CAN_CONTINUE_WITH_CAVEATS = {
    "inspect_measures",
    "export_share",
    "learn_terms",
}


GUIDED_GOAL_AREA_PRIORITY = {
    "check_readiness": (
        "Estimation",
        "Data / linking",
        "Fit",
        "Rating scale",
        "Assumptions",
        "Bias / interaction",
        "Reporting",
        "Measures",
    ),
    "inspect_measures": (
        "Measures",
        "Rating scale",
        "Fit",
    ),
    "diagnose_problem": (
        "Fit",
        "Assumptions",
        "Rating scale",
        "Bias / interaction",
        "Data / linking",
    ),
    "prepare_report": (
        "Reporting",
        "Fit",
        "Assumptions",
        "Bias / interaction",
        "Data / linking",
    ),
    "export_share": (
        "Reporting",
        "Data / linking",
        "Measures",
    ),
    "learn_terms": (
        "Rating scale",
        "Fit",
        "Assumptions",
        "Measures",
        "Bias / interaction",
    ),
}


def _safe_guided_goal_id(goal_id: str) -> str:
    safe_goal = str(goal_id)
    return safe_goal if safe_goal in GUIDED_GOAL_IDS else "check_readiness"


def guided_goal_decision_brief_table(goal_id: str) -> pd.DataFrame:
    """Return the one-row decision brief for a selected goal."""
    safe_goal = _safe_guided_goal_id(goal_id)
    return pd.DataFrame([{
        t("guided.goal_brief_col_prompt"): t(f"guided.goal_brief_{safe_goal}_prompt"),
        t("guided.goal_brief_col_decide"): t(f"guided.goal_brief_{safe_goal}_decide"),
        t("guided.goal_brief_col_do_not_decide"): t(f"guided.goal_brief_{safe_goal}_do_not_decide"),
        t("guided.goal_brief_col_output"): t(f"guided.goal_brief_{safe_goal}_output"),
        t("guided.goal_brief_col_caveat"): t(f"guided.goal_brief_{safe_goal}_caveat"),
    }])


def guided_goal_evidence_checklist(goal_id: str) -> pd.DataFrame:
    """Return goal-specific evidence checks that support the selected decision."""
    safe_goal = _safe_guided_goal_id(goal_id)
    rows: list[dict[str, str]] = []
    for row_number in range(1, 4):
        rows.append({
            t("guided.goal_evidence_col_evidence"): t(f"guided.goal_evidence_{safe_goal}_{row_number}_evidence"),
            t("guided.goal_evidence_col_reason"): t(f"guided.goal_evidence_{safe_goal}_{row_number}_reason"),
            t("guided.goal_evidence_col_caveat"): t(f"guided.goal_evidence_{safe_goal}_{row_number}_caveat"),
        })
    return pd.DataFrame(rows)


def guided_goal_detail_locator_table(goal_id: str) -> pd.DataFrame:
    """Return exact places to inspect for the selected goal."""
    safe_goal = _safe_guided_goal_id(goal_id)
    columns = [
        t("guided.goal_locator_col_open"),
        t("guided.goal_locator_col_place"),
        t("guided.goal_locator_col_check"),
        t("guided.goal_locator_col_use"),
    ]
    rows: list[dict[str, str]] = []
    for row_number in range(1, 4):
        rows.append({
            columns[0]: t(f"guided.goal_locator_{safe_goal}_{row_number}_open"),
            columns[1]: t(f"guided.goal_locator_{safe_goal}_{row_number}_place"),
            columns[2]: t(f"guided.goal_locator_{safe_goal}_{row_number}_check"),
            columns[3]: t(f"guided.goal_locator_{safe_goal}_{row_number}_use"),
        })
    return pd.DataFrame(rows, columns=columns)


def guided_goal_step_table(goal_id: str) -> pd.DataFrame:
    """Return the three-step reading route for a selected goal."""
    safe_goal = _safe_guided_goal_id(goal_id)
    rows: list[dict[str, object]] = []
    for step_number, open_label in enumerate(GUIDED_GOAL_STEP_OPEN[safe_goal], start=1):
        rows.append({
            t("guided.goal_step_col_step"): step_number,
            t("guided.goal_step_col_open"): open_label,
            t("guided.goal_step_col_action"): t(f"guided.goal_step_{safe_goal}_{step_number}_action"),
            t("guided.goal_step_col_done"): t(f"guided.goal_step_{safe_goal}_{step_number}_done"),
        })
    return pd.DataFrame(rows)


def _guided_goal_route_row(goal_id: str) -> pd.Series:
    """Return the localized route row for a goal, falling back to readiness."""
    safe_goal = _safe_guided_goal_id(goal_id)
    routes = guided_goal_route_table()
    return routes.loc[routes["GoalId"].eq(safe_goal)].iloc[0]


def _guided_focus_class(row: pd.Series) -> str:
    """Classify a First Read row by how it should affect goal routing."""
    status = str(row.get("Status", "Review"))
    area = str(row.get("Area", "Reporting"))
    if status == "OK":
        return "ok"
    if status == "Do not interpret yet":
        return "hard_stop"
    if status == "Caution" and area in GUIDED_FOCUS_HARD_STOP_AREAS:
        return "hard_stop"
    if area in GUIDED_FOCUS_CLAIM_CAVEAT_AREAS:
        return "claim_caveat"
    return "goal_review"


def _guided_focus_rows_by_class(action_plan: pd.DataFrame, focus_class: str) -> pd.DataFrame:
    """Return action-plan rows matching a focus class while preserving priority order."""
    if not isinstance(action_plan, pd.DataFrame) or action_plan.empty:
        return pd.DataFrame()
    rows = [
        row
        for _, row in action_plan.iterrows()
        if _guided_focus_class(row) == focus_class
    ]
    return pd.DataFrame(rows).reset_index(drop=True) if rows else pd.DataFrame()


def _prefer_goal_relevant_focus_row(goal_id: str, rows: pd.DataFrame) -> pd.Series | None:
    """Prefer a focus row whose topic is closest to the selected goal."""
    if not isinstance(rows, pd.DataFrame) or rows.empty:
        return None
    if "Area" not in rows.columns:
        return rows.iloc[0]
    safe_goal = _safe_guided_goal_id(goal_id)
    for area in GUIDED_GOAL_AREA_PRIORITY.get(safe_goal, ()):
        hits = rows.loc[rows["Area"].astype(str).eq(area)]
        if not hits.empty:
            return hits.iloc[0]
    return rows.iloc[0]


def _guided_goal_focus_selection(
    goal_id: str,
    action_plan: pd.DataFrame,
) -> tuple[pd.Series | None, str]:
    """Return the run-specific focus row and the reason it was selected."""
    if not isinstance(action_plan, pd.DataFrame) or action_plan.empty:
        return None, "clean"
    if "Status" not in action_plan.columns:
        return action_plan.iloc[0], "flagged"
    hard_flags = _guided_focus_rows_by_class(action_plan, "hard_stop")
    if not hard_flags.empty:
        return hard_flags.iloc[0], "hard"
    review_flags = action_plan.loc[
        action_plan["Status"].astype(str).isin(GUIDED_GOAL_REVIEW_STATUSES)
    ]
    if review_flags.empty:
        return None, "clean"
    focus_row = _prefer_goal_relevant_focus_row(goal_id, review_flags)
    if focus_row is None:
        return None, "clean"
    if str(focus_row.get("Area", "")) in GUIDED_GOAL_AREA_PRIORITY.get(_safe_guided_goal_id(goal_id), ()):
        return focus_row, "goal_relevant"
    return focus_row, "flagged"


def _guided_goal_row_from_route(goal_id: str, route: pd.Series) -> dict[str, str]:
    """Return a row that lets the selected non-reporting goal proceed."""
    safe_goal = _safe_guided_goal_id(goal_id)
    return {
        t("guided.goal_focus_col_focus"): (
            f"{t('guided.goal_focus_selected_goal_prefix')}: "
            f"{route[t('guided.goal_col_goal')]}"
        ),
        t("guided.goal_focus_col_why"): t("guided.goal_focus_can_continue_why"),
        t("guided.goal_focus_col_open"): str(route[t("guided.goal_col_start")]),
        t("guided.goal_focus_col_action"): str(route[t("guided.goal_col_next")]),
    }


def _guided_focus_label(row: pd.Series) -> str:
    """Build the compact label for a First Read focus row."""
    raw_status = str(row.get("Status", "Review"))
    raw_area = str(row.get("Area", "Reporting"))
    priority = str(row.get("Priority", "")).strip()
    check = str(row.get("Check", "")).strip()
    focus_label = " / ".join(
        part for part in [
            _guided_status_label(raw_status),
            _guided_area_label(raw_area),
            check,
        ]
        if part
    )
    if priority:
        focus_label = f"{priority}: {focus_label}"
    return focus_label


def _guided_focus_table_row(row: pd.Series, reason_key: str) -> dict[str, str]:
    """Return one display row for a First Read focus item."""
    what_it_says = str(row.get("WhatItSays", "")).strip()
    why = t(reason_key)
    if what_it_says:
        why = f"{why} {what_it_says}"
    return {
        t("guided.goal_focus_col_focus"): _guided_focus_label(row),
        t("guided.goal_focus_col_why"): why,
        t("guided.goal_focus_col_open"): _guided_detail_location_label(
            str(row.get("DetailLocation", ""))
        ),
        t("guided.goal_focus_col_action"): str(row.get("NextAction", "")).strip(),
    }


def _guided_claim_caveat_table_row(row: pd.Series) -> dict[str, str]:
    """Return a display row for a caveat that should travel with claims."""
    display = _guided_focus_table_row(row, "guided.goal_focus_claim_caveat_why")
    focus_col = t("guided.goal_focus_col_focus")
    display[focus_col] = f"{t('guided.goal_focus_claim_caveat_prefix')}: {display[focus_col]}"
    return display


def guided_goal_current_focus_table(goal_id: str, action_plan: pd.DataFrame | None) -> pd.DataFrame:
    """Return a one-row guide that combines the selected goal with this run."""
    safe_goal = _safe_guided_goal_id(goal_id)
    route = _guided_goal_route_row(safe_goal)
    col_focus = t("guided.goal_focus_col_focus")
    col_why = t("guided.goal_focus_col_why")
    col_open = t("guided.goal_focus_col_open")
    col_action = t("guided.goal_focus_col_action")

    columns = [col_focus, col_why, col_open, col_action]
    if not isinstance(action_plan, pd.DataFrame) or action_plan.empty:
        return pd.DataFrame([{
            col_focus: t("guided.goal_focus_unavailable_focus"),
            col_why: t("guided.goal_focus_unavailable_why"),
            col_open: route[t("guided.goal_col_start")],
            col_action: route[t("guided.goal_col_next")],
        }], columns=columns)

    hard_flags = _guided_focus_rows_by_class(action_plan, "hard_stop")
    if not hard_flags.empty:
        return pd.DataFrame([
            _guided_focus_table_row(hard_flags.iloc[0], "guided.goal_focus_hard_flagged_why")
        ], columns=columns)

    claim_caveats = _guided_focus_rows_by_class(action_plan, "claim_caveat")
    goal_reviews = _guided_focus_rows_by_class(action_plan, "goal_review")
    if safe_goal in GUIDED_GOALS_THAT_CAN_CONTINUE_WITH_CAVEATS and not claim_caveats.empty:
        rows: list[dict[str, str]] = []
        goal_row = _prefer_goal_relevant_focus_row(safe_goal, goal_reviews)
        if goal_row is not None:
            rows.append(_guided_focus_table_row(goal_row, "guided.goal_focus_goal_relevant_why"))
        else:
            rows.append(_guided_goal_row_from_route(safe_goal, route))
        caveat_row = _prefer_goal_relevant_focus_row(safe_goal, claim_caveats)
        if caveat_row is not None:
            rows.append(_guided_claim_caveat_table_row(caveat_row))
        return pd.DataFrame(rows, columns=columns)

    focus_row, selection_reason = _guided_goal_focus_selection(safe_goal, action_plan)
    if focus_row is None:
        return pd.DataFrame([{
            col_focus: t("guided.goal_focus_clean_focus"),
            col_why: t(f"guided.goal_focus_{safe_goal}_clean_why"),
            col_open: route[t("guided.goal_col_start")],
            col_action: route[t("guided.goal_col_next")],
        }], columns=columns)

    reason_key = {
        "hard": "guided.goal_focus_hard_flagged_why",
        "goal_relevant": "guided.goal_focus_goal_relevant_why",
    }.get(selection_reason, "guided.goal_focus_flagged_why")
    if _guided_focus_class(focus_row) == "claim_caveat":
        reason_key = "guided.goal_focus_claim_caveat_why"
    return pd.DataFrame([
        _guided_focus_table_row(focus_row, reason_key)
    ], columns=columns)


def guided_next_click_summary_table(goal_id: str, action_plan: pd.DataFrame | None) -> pd.DataFrame:
    """Return the single next click implied by the selected goal and run status."""
    safe_goal = _safe_guided_goal_id(goal_id)
    focus = guided_goal_current_focus_table(safe_goal, action_plan)
    col_focus = t("guided.goal_focus_col_focus")
    col_open = t("guided.goal_focus_col_open")
    col_action = t("guided.goal_focus_col_action")
    columns = [
        t("guided.next_click_col_next"),
        t("guided.next_click_col_open"),
        t("guided.next_click_col_do"),
        t("guided.next_click_col_keep_visible"),
    ]
    if focus.empty:
        return pd.DataFrame([{
            columns[0]: t("guided.next_click_run_first"),
            columns[1]: t("guided.tab_start"),
            columns[2]: t("guided.goal_focus_unavailable_why"),
            columns[3]: t("guided.next_click_keep_run_first"),
        }], columns=columns)

    first = focus.iloc[0]
    open_value = str(first.get(col_open, ""))
    action_value = str(first.get(col_action, ""))
    hard_flags = _guided_focus_rows_by_class(action_plan, "hard_stop")
    claim_caveats = _guided_focus_rows_by_class(action_plan, "claim_caveat")
    if not isinstance(action_plan, pd.DataFrame) or action_plan.empty:
        label = t("guided.next_click_run_first")
        open_value = t("guided.tab_start")
        action_value = t("guided.goal_focus_unavailable_why")
        keep_visible = t("guided.next_click_keep_run_first")
    elif not hard_flags.empty:
        label = t("guided.next_click_hard_stop")
        keep_visible = t("guided.next_click_keep_hard_stop")
    elif len(focus) > 1:
        label = t("guided.next_click_selected_goal")
        keep_visible = f"{t('guided.next_click_keep_prefix')}: {focus.iloc[1][col_focus]}"
    elif not claim_caveats.empty:
        label = t("guided.next_click_claim_caveat")
        keep_visible = t("guided.next_click_keep_claim_caveat")
    elif str(first[col_focus]) == t("guided.goal_focus_clean_focus"):
        label = t("guided.next_click_goal_route")
        keep_visible = t("guided.next_click_keep_evidence")
    else:
        label = t("guided.next_click_review")
        keep_visible = t("guided.next_click_keep_evidence")

    return pd.DataFrame([{
        columns[0]: label,
        columns[1]: open_value,
        columns[2]: action_value,
        columns[3]: keep_visible,
    }], columns=columns)


def guided_goal_guardrail_summary_table(goal_id: str, action_plan: pd.DataFrame | None) -> pd.DataFrame:
    """Return the compact interpretation guardrail for the selected goal."""
    safe_goal = _safe_guided_goal_id(goal_id)
    brief = guided_goal_decision_brief_table(safe_goal).iloc[0]
    next_click = guided_next_click_summary_table(safe_goal, action_plan).iloc[0]
    return pd.DataFrame([{
        t("guided.goal_guardrail_col_do_not_decide"): str(
            brief[t("guided.goal_brief_col_do_not_decide")]
        ),
        t("guided.goal_guardrail_col_keep_visible"): str(
            next_click[t("guided.next_click_col_keep_visible")]
        ),
        t("guided.goal_guardrail_col_expected_output"): str(
            brief[t("guided.goal_brief_col_output")]
        ),
    }])


def guided_section_id_for_target(target: object) -> str:
    """Map a visible target label to the Essential section id."""
    text = str(target or "").strip()
    if not text:
        return "start"
    direct_labels = {
        t("guided.tab_start"): "start",
        t("guided.tab_first_read"): "first_read",
        t("guided.tab_results"): "results",
        t("guided.tab_diagnostics"): "diagnostics",
        t("guided.tab_figures"): "figures",
        t("guided.tab_report_export"): "report_export",
        t("guided.tab_learn"): "learn",
    }
    for label, section_id in direct_labels.items():
        if str(label) and str(label) in text:
            return section_id
    lowered = text.lower()
    keyword_map = {
        "first_read": ("first read", "first-read", "first_read", "初期確認", "最初に確認"),
        "results": ("results", "measure", "facets-style", "結果", "測定値"),
        "diagnostics": ("diagnostic", "fit", "dimensionality", "categories", "bias", "診断", "適合", "次元", "カテゴリ", "バイアス"),
        "figures": ("figures", "figure", "wright", "yardstick", "visual", "図", "視覚"),
        "report_export": ("report", "export", "download", "publication", "readiness", "レポート", "出力", "ダウンロード", "準備"),
        "learn": ("learn", "help", "glossary", "guide", "学ぶ", "ヘルプ", "用語", "ガイド"),
        "start": ("start", "sample", "data", "run", "開始", "サンプル", "データ", "実行"),
    }
    for section_id, keywords in keyword_map.items():
        if any(keyword in lowered for keyword in keywords):
            return section_id
    return "start"


def guided_action_hub_cards(goal_id: str, action_plan: pd.DataFrame | None) -> pd.DataFrame:
    """Return a compact action hub with one primary action and detail links."""
    safe_goal = _safe_guided_goal_id(goal_id)
    next_click = guided_next_click_summary_table(safe_goal, action_plan)
    locator = guided_goal_detail_locator_table(safe_goal)
    guardrail = guided_goal_guardrail_summary_table(safe_goal, action_plan)
    route = _guided_goal_route_row(safe_goal)

    next_row = next_click.iloc[0] if isinstance(next_click, pd.DataFrame) and not next_click.empty else pd.Series(dtype=object)
    locator_row = locator.iloc[0] if isinstance(locator, pd.DataFrame) and not locator.empty else pd.Series(dtype=object)
    guardrail_row = guardrail.iloc[0] if isinstance(guardrail, pd.DataFrame) and not guardrail.empty else pd.Series(dtype=object)

    next_open = str(next_row.get(t("guided.next_click_col_open"), route[t("guided.goal_col_start")]))
    detail_open = str(locator_row.get(t("guided.goal_locator_col_open"), route[t("guided.goal_col_start")]))
    detail_place = str(locator_row.get(t("guided.goal_locator_col_place"), route[t("guided.goal_col_detail")]))
    report_open = t("guided.tab_report_export")

    columns = [
        "ActionId",
        t("guided.action_hub_col_role"),
        t("guided.action_hub_col_open"),
        t("guided.action_hub_col_action"),
        t("guided.action_hub_col_detail"),
        "SectionId",
        t("guided.action_hub_col_button"),
    ]
    rows = [
        {
            "ActionId": "primary",
            columns[1]: t("guided.action_hub_primary_role"),
            columns[2]: next_open,
            columns[3]: str(next_row.get(t("guided.next_click_col_do"), route[t("guided.goal_col_next")])),
            columns[4]: str(next_row.get(t("guided.next_click_col_keep_visible"), t("guided.next_click_keep_evidence"))),
            "SectionId": guided_section_id_for_target(next_open),
            columns[6]: t("guided.action_hub_primary_button"),
        },
        {
            "ActionId": "detail",
            columns[1]: t("guided.action_hub_detail_role"),
            columns[2]: detail_open,
            columns[3]: str(locator_row.get(t("guided.goal_locator_col_check"), "")),
            columns[4]: detail_place,
            "SectionId": guided_section_id_for_target(f"{detail_open} {detail_place}"),
            columns[6]: t("guided.action_hub_detail_button"),
        },
        {
            "ActionId": "boundary",
            columns[1]: t("guided.action_hub_boundary_role"),
            columns[2]: report_open,
            columns[3]: str(guardrail_row.get(t("guided.goal_guardrail_col_do_not_decide"), "")),
            columns[4]: str(guardrail_row.get(t("guided.goal_guardrail_col_expected_output"), "")),
            "SectionId": "report_export",
            columns[6]: t("guided.action_hub_boundary_button"),
        },
    ]
    return pd.DataFrame(rows, columns=columns)


def guided_progress_checklist(goal_id: str, action_plan: pd.DataFrame | None) -> pd.DataFrame:
    """Return a checkbox-ready guided progress checklist for the selected goal."""
    safe_goal = _safe_guided_goal_id(goal_id)
    route = _guided_goal_route_row(safe_goal)
    focus = guided_goal_current_focus_table(safe_goal, action_plan)
    next_click = guided_next_click_summary_table(safe_goal, action_plan)
    locator = guided_goal_detail_locator_table(safe_goal)

    has_plan = isinstance(action_plan, pd.DataFrame) and not action_plan.empty
    hard_flags = _guided_focus_rows_by_class(action_plan, "hard_stop")
    claim_caveats = _guided_focus_rows_by_class(action_plan, "claim_caveat")
    if isinstance(action_plan, pd.DataFrame) and not action_plan.empty and "Status" in action_plan.columns:
        review_flags = action_plan.loc[
            action_plan["Status"].astype(str).isin(GUIDED_GOAL_REVIEW_STATUSES)
        ]
    else:
        review_flags = pd.DataFrame()
    unresolved_flags = bool(not hard_flags.empty or not review_flags.empty)

    focus_row = focus.iloc[0] if isinstance(focus, pd.DataFrame) and not focus.empty else pd.Series(dtype=object)
    next_row = next_click.iloc[0] if isinstance(next_click, pd.DataFrame) and not next_click.empty else pd.Series(dtype=object)
    locator_row = locator.iloc[0] if isinstance(locator, pd.DataFrame) and not locator.empty else pd.Series(dtype=object)
    route_start = str(route[t("guided.goal_col_start")])
    route_next = str(route[t("guided.goal_col_next")])
    locator_open = str(locator_row.get(t("guided.goal_locator_col_open"), route_start))
    locator_place = str(locator_row.get(t("guided.goal_locator_col_place"), route_start))
    locator_check = str(locator_row.get(t("guided.goal_locator_col_check"), ""))
    locator_use = str(locator_row.get(t("guided.goal_locator_col_use"), ""))

    columns = [
        t("guided.progress_col_done"),
        t("guided.progress_col_checkpoint"),
        t("guided.progress_col_state"),
        t("guided.progress_col_open"),
        t("guided.progress_col_action"),
        t("guided.progress_col_completion"),
        t("guided.progress_col_boundary"),
    ]
    rows: list[dict[str, object]] = []

    def add_row(
        *,
        done: bool,
        checkpoint_key: str,
        state: str,
        open_value: str,
        action: str,
        completion_key: str,
        boundary_key: str,
    ) -> None:
        rows.append({
            columns[0]: bool(done),
            columns[1]: t(f"guided.progress_{checkpoint_key}_checkpoint"),
            columns[2]: state,
            columns[3]: open_value,
            columns[4]: action,
            columns[5]: t(f"guided.progress_{completion_key}_completion"),
            columns[6]: t(f"guided.progress_{boundary_key}_boundary"),
        })

    add_row(
        done=has_plan,
        checkpoint_key="run",
        state=t("guided.progress_state_ready") if has_plan else t("guided.progress_state_blocked"),
        open_value=t("guided.tab_start"),
        action=t("guided.next_click_run_first") if not has_plan else t("guided.progress_run_action_ready"),
        completion_key="run",
        boundary_key="run",
    )
    add_row(
        done=True,
        checkpoint_key="goal",
        state=t("guided.progress_state_available"),
        open_value=route_start,
        action=route_next,
        completion_key="goal",
        boundary_key="goal",
    )
    add_row(
        done=has_plan and not unresolved_flags,
        checkpoint_key="focus",
        state=(
            t("guided.progress_state_blocked")
            if not hard_flags.empty else
            t("guided.progress_state_review")
            if unresolved_flags else
            t("guided.progress_state_ready")
        ),
        open_value=str(focus_row.get(t("guided.goal_focus_col_open"), route_start)),
        action=str(focus_row.get(t("guided.goal_focus_col_action"), route_next)),
        completion_key="focus",
        boundary_key="focus",
    )
    add_row(
        done=False,
        checkpoint_key="evidence",
        state=t("guided.progress_state_user_check"),
        open_value=f"{locator_open}: {locator_place}",
        action=" ".join(part for part in [locator_check, locator_use] if part).strip(),
        completion_key="evidence",
        boundary_key="evidence",
    )
    claim_ready = bool(
        has_plan
        and hard_flags.empty
        and claim_caveats.empty
        and review_flags.empty
    )
    add_row(
        done=claim_ready,
        checkpoint_key="claim",
        state=t("guided.progress_state_ready") if claim_ready else t("guided.progress_state_review"),
        open_value=str(next_row.get(t("guided.next_click_col_open"), t("guided.tab_report_export"))),
        action=str(next_row.get(t("guided.next_click_col_keep_visible"), t("guided.next_click_keep_evidence"))),
        completion_key="claim",
        boundary_key="claim",
    )
    add_row(
        done=False,
        checkpoint_key="archive",
        state=t("guided.progress_state_user_check"),
        open_value=t("guided.tab_report_export"),
        action=t("guided.progress_archive_action"),
        completion_key="archive",
        boundary_key="archive",
    )
    return pd.DataFrame(rows, columns=columns)


def _render_guided_goal_router(
    *,
    action_plan: pd.DataFrame | None = None,
    key_suffix: str = "main",
) -> None:
    """Render a goal selector that routes to the appropriate guided section."""
    routes = guided_goal_route_table()
    if routes.empty:
        return
    st.subheader(t("guided.goal_router_subheader"))
    st.caption(t("guided.goal_router_caption"))
    goal_col = t("guided.goal_col_goal")
    selected_goal = st.selectbox(
        t("guided.goal_select_label"),
        options=routes["GoalId"].tolist(),
        index=0,
        format_func=lambda goal_id: str(
            routes.loc[routes["GoalId"].eq(goal_id), goal_col].iloc[0]
        ),
        key=f"guided_goal_route_{key_suffix}",
        help=t("guided.goal_select_help"),
    )
    selected = routes.loc[routes["GoalId"].eq(selected_goal)].iloc[0]
    with st.container(border=True):
        st.markdown(
            f"**{t('guided.goal_card_start')}**: {selected[t('guided.goal_col_start')]}  \n"
            f"**{t('guided.goal_card_next')}**: {selected[t('guided.goal_col_next')]}  \n"
            f"**{t('guided.goal_card_detail')}**: {selected[t('guided.goal_col_detail')]}"
        )
        st.caption(str(selected[t("guided.goal_col_when")]))
    st.markdown(f"**{t('guided.goal_focus_heading')}**")
    st.caption(t("guided.goal_focus_caption"))
    st.dataframe(
        guided_goal_current_focus_table(str(selected_goal), action_plan),
        width="stretch",
        hide_index=True,
    )
    st.markdown(f"**{t('guided.next_click_heading')}**")
    st.caption(t("guided.next_click_caption"))
    st.dataframe(
        guided_next_click_summary_table(str(selected_goal), action_plan),
        width="stretch",
        hide_index=True,
    )
    action_hub = guided_action_hub_cards(str(selected_goal), action_plan)
    if isinstance(action_hub, pd.DataFrame) and not action_hub.empty:
        st.markdown(f"**{t('guided.action_hub_heading')}**")
        st.caption(t("guided.action_hub_caption"))
        role_col = t("guided.action_hub_col_role")
        open_col = t("guided.action_hub_col_open")
        action_col = t("guided.action_hub_col_action")
        detail_col = t("guided.action_hub_col_detail")
        button_col = t("guided.action_hub_col_button")
        card_cols = st.columns(len(action_hub))
        for idx, (_, hub_row) in enumerate(action_hub.iterrows()):
            with card_cols[idx]:
                with st.container(border=True):
                    st.markdown(f"**{hub_row.get(role_col, '')}**")
                    st.caption(str(hub_row.get(open_col, "")))
                    st.write(str(hub_row.get(action_col, "")))
                    detail_text = str(hub_row.get(detail_col, "")).strip()
                    if detail_text:
                        st.caption(detail_text)
                    if st.button(
                        str(hub_row.get(button_col, t("guided.action_hub_primary_button"))),
                        key=f"guided_action_hub_{key_suffix}_{hub_row.get('ActionId', idx)}",
                        use_container_width=True,
                    ):
                        st.session_state["guided_essential_section"] = str(hub_row.get("SectionId", "start"))
                        st.rerun()
        with st.expander(t("guided.action_hub_detail_expander"), expanded=False):
            st.dataframe(
                action_hub.drop(columns=["ActionId", "SectionId"], errors="ignore"),
                width="stretch",
                hide_index=True,
            )
    progress_table = guided_progress_checklist(str(selected_goal), action_plan)
    if isinstance(progress_table, pd.DataFrame) and not progress_table.empty:
        st.markdown(f"**{t('guided.progress_heading')}**")
        done_col = t("guided.progress_col_done")
        done_count = int(progress_table[done_col].fillna(False).astype(bool).sum()) if done_col in progress_table.columns else 0
        total_count = int(len(progress_table))
        st.caption(t("guided.progress_caption", done=done_count, total=total_count))
        try:
            st.progress(done_count / max(total_count, 1))
        except Exception:
            pass
        disabled_cols = [col for col in progress_table.columns if col != done_col]
        try:
            st.data_editor(
                progress_table,
                width="stretch",
                hide_index=True,
                disabled=disabled_cols,
                column_config={
                    done_col: st.column_config.CheckboxColumn(
                        done_col,
                        help=t("guided.progress_done_help"),
                    ),
                },
                key=f"guided_progress_checklist_{key_suffix}",
            )
        except Exception:
            st.dataframe(progress_table, width="stretch", hide_index=True)
        st.download_button(
            t("guided.progress_download_button"),
            data=to_csv_bytes(progress_table),
            file_name="mfrm_guided_progress_checklist.csv",
            mime="text/csv",
            key=f"dl_guided_progress_checklist_{key_suffix}",
        )
    st.markdown(f"**{t('guided.goal_locator_heading')}**")
    st.caption(t("guided.goal_locator_caption"))
    st.dataframe(guided_goal_detail_locator_table(str(selected_goal)), width="stretch", hide_index=True)
    st.markdown(f"**{t('guided.goal_guardrail_heading')}**")
    st.caption(t("guided.goal_guardrail_caption"))
    st.dataframe(
        guided_goal_guardrail_summary_table(str(selected_goal), action_plan),
        width="stretch",
        hide_index=True,
    )
    with st.expander(t("guided.goal_supporting_detail_expander"), expanded=False):
        st.caption(t("guided.goal_supporting_detail_caption"))
        st.markdown(f"**{t('guided.goal_brief_heading')}**")
        st.dataframe(guided_goal_decision_brief_table(str(selected_goal)), width="stretch", hide_index=True)
        st.markdown(f"**{t('guided.goal_evidence_heading')}**")
        st.dataframe(guided_goal_evidence_checklist(str(selected_goal)), width="stretch", hide_index=True)
        st.markdown(f"**{t('guided.goal_steps_heading')}**")
        st.dataframe(guided_goal_step_table(str(selected_goal)), width="stretch", hide_index=True)
        st.markdown(f"**{t('guided.goal_all_routes_expander')}**")
        st.dataframe(routes.drop(columns=["GoalId"]), width="stretch", hide_index=True)


def _render_guided_start_section(
    core: dict,
    data: pd.DataFrame,
    result: dict,
    diagnostics: dict,
    est_facet_cols: list[str],
    person_col: str,
    score_col: str,
) -> None:
    st.subheader(t("guided.start_subheader"))
    st.caption(t("guided.start_caption"))
    with st.expander(t("guided.first_run_route_expander"), expanded=True):
        st.caption(t("guided.first_run_route_caption"))
        st.dataframe(guided_first_run_route_table(), width="stretch", hide_index=True)
    obs_n = len(data) if isinstance(data, pd.DataFrame) else 0
    person_n = data[person_col].nunique() if isinstance(data, pd.DataFrame) and person_col in data else 0
    facet_n = len(est_facet_cols or [])
    score_n = (
        pd.to_numeric(data[score_col], errors="coerce").dropna().nunique()
        if isinstance(data, pd.DataFrame) and score_col in data else 0
    )
    metric_cols = st.columns(4)
    metric_cols[0].metric(t("guided.metric_observations"), f"{obs_n:,}")
    metric_cols[1].metric(t("guided.metric_persons"), f"{person_n:,}")
    metric_cols[2].metric(t("guided.metric_facets"), f"{facet_n:,}")
    metric_cols[3].metric(t("guided.metric_score_categories"), f"{int(score_n):,}")

    with st.expander(t("guided.data_quality_expander"), expanded=True):
        try:
            _draw_data_coverage_heatmap(data, est_facet_cols, person_col)
            _draw_category_usage_bar(data, score_col, est_facet_cols)
        except Exception:  # pragma: no cover - diagnostic helpers must not break guided view
            pass
        prep = result.get("prep", {}) if isinstance(result, dict) else {}
        render_response_data_audit_panel(
            prep.get("response_data_audit"),
            expanded=False,
            context="guided_run",
        )
        _show_data_tab_checks(data, score_col)

        score_messages = prep.get("score_messages", [])
        score_map = prep.get("score_map", pd.DataFrame())
        for msg in score_messages:
            st.warning(msg)
        if isinstance(score_map, pd.DataFrame) and not score_map.empty:
            with st.expander(t("data_quality.score_map_expander"), expanded=bool(score_messages)):
                st.dataframe(score_map, width="stretch")

        anchor_audit = result.get("config", {}).get("anchor_audit", {}) if isinstance(result, dict) else {}
        if isinstance(anchor_audit, dict):
            status = anchor_audit.get("overall_status", "ok")
            message = anchor_audit.get("message", t("data_quality.anchor_default_message"))
            if status == "error":
                st.error(message)
            elif status == "warning":
                st.warning(message)
            else:
                st.success(message)
            audit_summary = anchor_audit.get("summary", pd.DataFrame())
            audit_issues = anchor_audit.get("issues", pd.DataFrame())
            with st.expander(t("data_quality.anchor_summary_expander"), expanded=status != "ok"):
                if isinstance(audit_summary, pd.DataFrame) and not audit_summary.empty:
                    st.dataframe(audit_summary, width="stretch")
                else:
                    st.info(t("data_quality.anchor_no_summary_info"))
            if isinstance(audit_issues, pd.DataFrame) and not audit_issues.empty:
                with st.expander(t("data_quality.anchor_issues_expander"), expanded=True):
                    st.dataframe(audit_issues, width="stretch")

        calc_subsets_fn = core.get("calc_subsets") if isinstance(core, dict) else None
        if calc_subsets_fn and diagnostics.get("obs") is not None:
            try:
                config_facet_names = result.get("config", {}).get("facet_names", est_facet_cols)
                subsets = calc_subsets_fn(diagnostics["obs"], ["Person"] + list(config_facet_names))
                summary_df = subsets.get("summary", pd.DataFrame()) if subsets else pd.DataFrame()
                if not summary_df.empty and len(summary_df) >= 2:
                    st.warning(t("data_quality.subsets_warning_template", n=len(summary_df)))
                    with st.expander(t("data_quality.subset_details_expander")):
                        st.dataframe(summary_df, width="stretch")
                        nodes_df = subsets.get("nodes", pd.DataFrame()) if subsets else pd.DataFrame()
                        if not nodes_df.empty:
                            st.dataframe(nodes_df, width="stretch")
                elif not summary_df.empty:
                    st.success(t("data_quality.subsets_connected_success"))
            except Exception as conn_exc:
                st.info(t("data_quality.connectivity_failed_info_template", error=str(conn_exc)))

    with st.expander(t("guided.input_preview_expander"), expanded=False):
        st.dataframe(data.head(100), width="stretch")

    _render_guided_detail_navigator()


def _render_guided_results_section(result: dict, diagnostics: dict, report_tables: dict) -> None:
    st.subheader(t("guided.results_subheader"))
    st.caption(t("guided.results_caption"))
    st.markdown(f"**{t('guided.measures_reading_heading')}**")
    st.caption(t("guided.measures_reading_caption"))
    render_guided_measures_reading_guide_tables()
    show_convergence_section(result)

    person_df = result.get("facets", {}).get("person", pd.DataFrame())
    with st.expander(t("guided.person_measures_expander"), expanded=True):
        st.caption(t("result_tabs.persons_caption"))
        if isinstance(person_df, pd.DataFrame) and not person_df.empty:
            st.dataframe(person_df, width="stretch")
        else:
            st.info(t("sidebar_perf.no_person_measures_info_template", run_button=t("sidebar_perf.run_button")))
        show_person_fit_section(result, diagnostics)
        show_posterior_scoring_section(result)

    with st.expander(t("guided.facet_measures_expander"), expanded=False):
        others_df = result.get("facets", {}).get("others", pd.DataFrame())
        if isinstance(others_df, pd.DataFrame) and not others_df.empty:
            st.dataframe(others_df, width="stretch")
        else:
            st.info(t("result_tabs.facets_no_data_info"))

    with st.expander(t("guided.steps_expander"), expanded=False):
        steps_df = result.get("steps", pd.DataFrame())
        if isinstance(steps_df, pd.DataFrame) and not steps_df.empty:
            st.dataframe(steps_df, width="stretch")
        else:
            st.info(t("result_tabs.steps_no_data_info"))
        slopes_df = result.get("slopes", pd.DataFrame())
        if isinstance(slopes_df, pd.DataFrame) and not slopes_df.empty:
            st.subheader(t("result_tabs.slopes_subheader"))
            st.caption(t("result_tabs.slopes_caption"))
            st.dataframe(slopes_df, width="stretch")

    with st.expander(t("guided.combined_measures_expander"), expanded=True):
        measures_df = diagnostics.get("measures", pd.DataFrame())
        if isinstance(measures_df, pd.DataFrame) and not measures_df.empty:
            measures_display = measures_df.copy()
            if "CI_Lower" not in measures_display.columns and "SE" in measures_display.columns:
                se = pd.to_numeric(measures_display["SE"], errors="coerce")
                est = pd.to_numeric(measures_display["Estimate"], errors="coerce")
                measures_display.insert(
                    measures_display.columns.get_loc("SE") + 1,
                    "CI_Lower", (est - 1.96 * se).round(3),
                )
                measures_display.insert(
                    measures_display.columns.get_loc("CI_Lower") + 1,
                    "CI_Upper", (est + 1.96 * se).round(3),
                )
            measures_display = reorder_measure_columns(measures_display)
            measures_display = format_measure_table(measures_display)
            st.dataframe(style_fit_columns(measures_display), width="stretch")
            if "CI_Lower" in measures_display.columns:
                st.caption(t("result_tabs.combined_ci_caption"))
            render_eb_shrinkage_section(result, diagnostics, expanded=False)
        else:
            st.info(t("sidebar_perf.no_combined_measures_info_template", run_button=t("sidebar_perf.run_button")))

    with st.expander(t("guided.facets_tables_expander"), expanded=False):
        if not report_tables:
            st.info("No FACETS-style report tables were generated.")
        else:
            _n_facets = len(report_tables)
            _n_elements = sum(len(tbl) for tbl in report_tables.values())
            st.info(f"{_n_facets} facet table(s), {_n_elements} total elements.")
            for facet, tbl in report_tables.items():
                st.markdown(f"**{facet}**")
                st.dataframe(tbl, width="stretch")


def _render_guided_diagnostics_section(
    core: dict,
    result: dict,
    diagnostics: dict,
    est_facet_cols: list[str],
    bias_results: dict | None,
    all_bias_results: dict | None,
    *,
    result_compute_pca: bool,
    result_render_plots: bool,
) -> None:
    st.subheader(t("guided.diagnostics_subheader"))
    st.caption(t("guided.diagnostics_caption"))
    selected_diagnostic = st.segmented_control(
        t("guided.diagnostics_select_label"),
        options=list(GUIDED_DIAGNOSTIC_PANEL_IDS),
        default="fit_details",
        format_func=_guided_diagnostic_panel_label,
        key="guided_diagnostics_panel",
        help=t("guided.diagnostics_select_help"),
        width="stretch",
    )
    selected_diagnostic = selected_diagnostic or "fit_details"
    st.caption(t("guided.diagnostics_select_caption"))

    if selected_diagnostic == "fit_details":
        show_fit_details_section(diagnostics, result=result, all_bias_results=all_bias_results or {})
    elif selected_diagnostic == "dimensionality":
        if result_compute_pca:
            dim_core = dict(core) if isinstance(core, dict) else {}
            dim_core["result"] = result
            show_dimensionality_section(diagnostics, est_facet_cols, core=dim_core)
        else:
            st.info(t("result_tabs.dimensionality_skipped_info"))
    elif selected_diagnostic == "wright_map":
        if result_render_plots:
            show_wright_map_section(result, diagnostics)
        else:
            st.info(t("result_tabs.wright_map_skipped_info"))
    elif selected_diagnostic == "visuals":
        if result_render_plots:
            force_full_visuals = st.checkbox(
                t("guided.show_full_visuals"),
                value=False,
                key="guided_show_full_visuals",
                help=t("guided.show_full_visuals_help"),
            )
            show_visuals_section(result, diagnostics, force_full=force_full_visuals)
        else:
            st.info(t("guided.plots_skipped_info"))
    elif selected_diagnostic == "bias_interaction":
        show_bias_section(
            bias_results,
            core,
            all_bias_results=all_bias_results or {},
            result=result,
            diagnostics=diagnostics,
        )
    elif selected_diagnostic == "categories_steps":
        show_categories_section(result, diagnostics, core)
    elif selected_diagnostic == "agreement":
        show_agreement_section(result, diagnostics, est_facet_cols, core)
    elif selected_diagnostic == "facet_dashboard":
        show_facet_dashboard(result, diagnostics, est_facet_cols, all_bias_results=all_bias_results or {})
    elif selected_diagnostic == "prediction_simulation":
        show_prediction_simulation_section(result, diagnostics, core=core)
    else:
        show_fit_details_section(diagnostics, result=result, all_bias_results=all_bias_results or {})


def _render_guided_figures_section(
    result: dict,
    diagnostics: dict,
    *,
    result_render_plots: bool,
    result_generate_figures: bool,
) -> None:
    """Render figure-viewing surfaces as their own Essential section."""
    st.subheader(t("guided.figures_subheader"))
    st.caption(t("guided.figures_caption"))
    with st.container(border=True):
        st.markdown(t("guided.figures_location_markdown"))

    if not result_render_plots:
        st.info(t("guided.figures_plots_skipped_info"))
        return

    selected_figure_panel = st.segmented_control(
        t("guided.figures_panel_select_label"),
        options=list(GUIDED_FIGURE_PANEL_IDS),
        default="wright_map",
        format_func=_guided_figure_panel_label,
        key="guided_figures_panel",
        help=t("guided.figures_panel_select_help"),
        width="stretch",
    )
    selected_figure_panel = selected_figure_panel or "wright_map"
    st.caption(t("guided.figures_panel_select_caption"))

    if selected_figure_panel == "wright_map":
        show_wright_map_section(result, diagnostics)
    elif selected_figure_panel == "visuals":
        force_full_visuals = st.checkbox(
            t("guided.show_full_visuals"),
            value=False,
            key="guided_figures_show_full_visuals",
            help=t("guided.show_full_visuals_help"),
        )
        show_visuals_section(result, diagnostics, force_full=force_full_visuals)
    elif selected_figure_panel == "export_status":
        if result_generate_figures:
            st.success(t("guided.figures_export_ready_info"))
        else:
            st.info(t("downloads.figures_skipped_info"))
        st.markdown(t("guided.figures_export_hint_markdown"))
        visual_guardrails = visual_claim_guardrail_table()
        if isinstance(visual_guardrails, pd.DataFrame) and not visual_guardrails.empty:
            _render_compact_dataframe(
                visual_guardrails,
                ["Visualization", "SafeReportWording", "DoNotWrite", "RequiredEvidence"],
                details_label=t("guided.figures_guardrails_details_label"),
                hide_index=True,
                wrap_text=True,
            )
    else:
        show_wright_map_section(result, diagnostics)


def _render_guided_report_export_section(
    result: dict,
    diagnostics: dict,
    report_tables: dict,
    scorefile: pd.DataFrame,
    residuals: pd.DataFrame,
    bias_results: dict | None,
    all_bias_results: dict | None,
    *,
    generate_figures: bool,
) -> None:
    st.subheader(t("guided.report_export_subheader"))
    st.caption(t("guided.report_export_caption"))
    report_ready_summary = build_report_ready_summary_panel(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
    )
    st.markdown(f"**{t('guided.report_ready_summary_heading')}**")
    st.caption(t("guided.report_ready_summary_caption"))
    if isinstance(report_ready_summary, pd.DataFrame) and not report_ready_summary.empty:
        _render_compact_dataframe(
            report_ready_summary,
            [
                "Priority",
                "ReportArea",
                "ReportStatus",
                "PrimaryUsers",
                "UseNow",
                "OpenFirst",
                "ActionBeforeWriting",
            ],
            details_label=t("guided.report_ready_summary_details_label"),
            hide_index=True,
            wrap_text=True,
        )
        st.download_button(
            t("guided.report_ready_summary_download"),
            data=to_csv_bytes(report_ready_summary),
            file_name="report_ready_summary_panel.csv",
            mime="text/csv",
            key="dl_guided_report_ready_summary_panel",
            use_container_width=True,
        )
    else:
        st.info(t("guided.report_ready_summary_empty"))
    decision_brief = generate_report_ready_decision_brief(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
    )
    custom_simulation_frames = current_custom_simulation_sparse_export_frames()
    simulation_sparse_context = custom_simulation_frames.get(
        "custom_simulation_sparse_reporting_context",
        pd.DataFrame(),
    )
    simulation_settings = custom_simulation_frames.get("custom_simulation_settings", pd.DataFrame())
    apa_results_draft = generate_report_ready_apa_results_draft(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
        simulation_sparse_context=simulation_sparse_context,
        simulation_settings=simulation_settings,
    )
    role_action_memos = build_role_based_action_memos(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
    )
    role_action_memos_md = generate_role_based_action_memos_markdown(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
    )
    role_action_checklist = build_role_based_action_checklist(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
    )
    reanalysis_checklist = build_report_ready_reanalysis_checklist(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
        report_ready_summary=report_ready_summary,
        role_action_checklist=role_action_checklist,
        simulation_settings=simulation_settings,
        simulation_sparse_context=simulation_sparse_context,
    )
    reanalysis_checklist_md = generate_report_ready_reanalysis_checklist_markdown(reanalysis_checklist)
    role_action_checklist_state_key = "guided_role_based_action_checklist_done"
    if isinstance(role_action_checklist, pd.DataFrame) and not role_action_checklist.empty:
        role_action_checklist_run_key = dataframe_fingerprint(
            role_action_checklist.drop(columns=["Done"], errors="ignore"),
            length=16,
        )
        role_action_checklist_state_key = (
            f"guided_role_based_action_checklist_done_{role_action_checklist_run_key}"
        )
        role_action_checklist = apply_role_based_action_checklist_done_state(
            role_action_checklist,
            st.session_state.get(role_action_checklist_state_key, {}),
        )
    role_action_checklist_md = generate_role_based_action_checklist_markdown(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
        checklist=role_action_checklist,
    )
    st.markdown(f"**{t('guided.report_ready_brief_heading')}**")
    st.caption(t("guided.report_ready_brief_caption"))
    brief_col, apa_col = st.columns(2)
    with brief_col:
        with st.expander(t("guided.report_ready_brief_expander"), expanded=False):
            st.code(decision_brief, language="markdown")
        st.download_button(
            t("guided.report_ready_brief_download"),
            data=decision_brief.encode("utf-8"),
            file_name="report_ready_decision_brief.md",
            mime="text/markdown",
            key="dl_guided_report_ready_decision_brief_md",
            use_container_width=True,
        )
    with apa_col:
        with st.expander(t("guided.apa_results_draft_expander"), expanded=False):
            st.code(apa_results_draft, language="markdown")
        st.download_button(
            t("guided.apa_results_draft_download"),
            data=apa_results_draft.encode("utf-8"),
            file_name="apa_results_paragraph_draft.md",
            mime="text/markdown",
            key="dl_guided_apa_results_paragraph_draft_md",
            use_container_width=True,
        )
    st.markdown(f"**{t('guided.role_action_memos_heading')}**")
    st.caption(t("guided.role_action_memos_caption"))
    if isinstance(role_action_memos, pd.DataFrame) and not role_action_memos.empty:
        _render_compact_dataframe(
            role_action_memos,
            ["Role", "Priority", "DecisionFocus", "ReportStatus", "ImmediateAction", "EvidenceToOpen"],
            details_label=t("guided.role_action_memos_details_label"),
            hide_index=True,
            wrap_text=True,
        )
        memo_col, memo_md_col = st.columns(2)
        with memo_col:
            st.download_button(
                t("guided.role_action_memos_download_csv"),
                data=to_csv_bytes(role_action_memos),
                file_name="role_based_action_memos.csv",
                mime="text/csv",
                key="dl_guided_role_based_action_memos_csv",
                use_container_width=True,
            )
        with memo_md_col:
            with st.expander(t("guided.role_action_memos_expander"), expanded=False):
                st.code(role_action_memos_md, language="markdown")
            st.download_button(
                t("guided.role_action_memos_download_md"),
                data=role_action_memos_md.encode("utf-8"),
                file_name="role_based_action_memos.md",
                mime="text/markdown",
                key="dl_guided_role_based_action_memos_md",
                use_container_width=True,
            )
    else:
        st.info(t("guided.role_action_memos_empty"))
    st.markdown(f"**{t('guided.role_checklist_heading')}**")
    st.caption(t("guided.role_checklist_caption"))
    if isinstance(role_action_checklist, pd.DataFrame) and not role_action_checklist.empty:
        checklist_progress = role_based_action_checklist_progress_summary(role_action_checklist)
        total_items = int(len(role_action_checklist))
        done_items = int(role_action_checklist["Done"].fillna(False).astype(bool).sum())
        remaining_items = int(total_items - done_items)
        remaining_blockers = int(
            role_action_checklist.loc[~role_action_checklist["Done"].fillna(False).astype(bool)]
            .get("BlockingForFinalOutput", pd.Series(dtype=bool))
            .fillna(False)
            .astype(bool)
            .sum()
        )
        remaining_caveats = int(
            role_action_checklist.loc[~role_action_checklist["Done"].fillna(False).astype(bool)]
            .get("NeedsCaveat", pd.Series(dtype=bool))
            .fillna(False)
            .astype(bool)
            .sum()
        )
        st.caption(
            t(
                "guided.role_checklist_progress_template",
                done=done_items,
                total=total_items,
                remaining=remaining_items,
                blockers=remaining_blockers,
                caveats=remaining_caveats,
            )
        )
        try:
            st.progress(done_items / max(total_items, 1))
        except Exception:
            pass
        if isinstance(checklist_progress, pd.DataFrame) and not checklist_progress.empty:
            _render_compact_dataframe(
                checklist_progress,
                [
                    "Role",
                    "DoneItems",
                    "TotalItems",
                    "RemainingBlockingItems",
                    "RemainingCaveatItems",
                    "State",
                    "NextAction",
                ],
                details_label=t("guided.role_checklist_summary_details_label"),
                hide_index=True,
                wrap_text=True,
            )
        roles = role_action_checklist["Role"].astype(str).drop_duplicates().tolist()
        selected_role = st.selectbox(
            t("guided.role_checklist_role_select_label"),
            [t("guided.role_checklist_all_roles"), *roles],
            key="guided_role_action_checklist_role",
        )
        show_open_only = st.checkbox(
            t("guided.role_checklist_open_only_label"),
            value=False,
            key="guided_role_action_checklist_open_only",
            help=t("guided.role_checklist_open_only_help"),
        )
        checklist_display = role_action_checklist
        if selected_role != t("guided.role_checklist_all_roles"):
            checklist_display = role_action_checklist.loc[
                role_action_checklist["Role"].astype(str).eq(str(selected_role))
            ].copy()
        if show_open_only:
            checklist_display = checklist_display.loc[
                ~checklist_display["Done"].fillna(False).astype(bool)
            ].copy()
        if checklist_display.empty:
            st.info(t("guided.role_checklist_filter_empty"))
        else:
            edited_checklist = st.data_editor(
                checklist_display,
                column_config={
                    "Done": st.column_config.CheckboxColumn(
                        t("guided.role_checklist_done_col"),
                        help=t("guided.role_checklist_done_help"),
                    ),
                    "ChecklistId": None,
                },
                disabled=[col for col in checklist_display.columns if col != "Done"],
                width="stretch",
                hide_index=True,
                key="guided_role_based_action_checklist_editor",
            )
            if isinstance(edited_checklist, pd.DataFrame) and "Done" in edited_checklist.columns:
                if "ChecklistId" not in edited_checklist.columns and "ChecklistId" in checklist_display.columns:
                    edited_checklist = edited_checklist.copy()
                    edited_checklist["ChecklistId"] = [
                        checklist_display.loc[idx, "ChecklistId"] if idx in checklist_display.index else ""
                        for idx in edited_checklist.index
                    ]
                updated_done_state = dict(st.session_state.get(role_action_checklist_state_key, {}))
                for _, edited_row in edited_checklist.iterrows():
                    updated_done_state[str(edited_row.get("ChecklistId", ""))] = bool(
                        edited_row.get("Done", False)
                    )
                if updated_done_state != st.session_state.get(role_action_checklist_state_key, {}):
                    st.session_state[role_action_checklist_state_key] = updated_done_state
                    role_action_checklist = apply_role_based_action_checklist_done_state(
                        role_action_checklist,
                        updated_done_state,
                    )
                    role_action_checklist_md = generate_role_based_action_checklist_markdown(
                        result,
                        diagnostics,
                        all_bias_results=all_bias_results or {},
                        bias_results=bias_results,
                        checklist=role_action_checklist,
                    )
        check_col, check_md_col = st.columns(2)
        with check_col:
            st.download_button(
                t("guided.role_checklist_download_csv"),
                data=to_csv_bytes(role_action_checklist),
                file_name="role_based_action_checklist.csv",
                mime="text/csv",
                key="dl_guided_role_based_action_checklist_csv",
                use_container_width=True,
            )
        with check_md_col:
            with st.expander(t("guided.role_checklist_expander"), expanded=False):
                st.code(role_action_checklist_md, language="markdown")
            st.download_button(
                t("guided.role_checklist_download_md"),
                data=role_action_checklist_md.encode("utf-8"),
                file_name="role_based_action_checklist.md",
                mime="text/markdown",
                key="dl_guided_role_based_action_checklist_md",
                use_container_width=True,
            )
    else:
        st.info(t("guided.role_checklist_empty"))
    st.markdown("**Report-ready simulation / reanalysis checklist**")
    st.caption(
        "A shared checklist for generated data, reruns, sensitivity checks, and final report exports."
    )
    if isinstance(reanalysis_checklist, pd.DataFrame) and not reanalysis_checklist.empty:
        _render_compact_dataframe(
            reanalysis_checklist,
            ["Priority", "Phase", "Audience", "ReportStatus", "Task", "Action", "EvidenceToOpen"],
            details_label="Show full simulation / reanalysis checklist",
            hide_index=True,
            wrap_text=True,
        )
        re_col, re_md_col = st.columns(2)
        with re_col:
            st.download_button(
                "Download simulation / reanalysis checklist (CSV)",
                data=to_csv_bytes(reanalysis_checklist),
                file_name="report_ready_reanalysis_checklist.csv",
                mime="text/csv",
                key="dl_guided_report_ready_reanalysis_checklist_csv",
                use_container_width=True,
            )
        with re_md_col:
            with st.expander("View simulation / reanalysis checklist"):
                st.code(reanalysis_checklist_md, language="markdown")
            st.download_button(
                "Download simulation / reanalysis checklist (Markdown)",
                data=reanalysis_checklist_md.encode("utf-8"),
                file_name="report_ready_reanalysis_checklist.md",
                mime="text/markdown",
                key="dl_guided_report_ready_reanalysis_checklist_md",
                use_container_width=True,
            )
    else:
        st.info("No simulation / reanalysis checklist rows were generated for this run.")
    guided_final_report_readiness = build_final_report_readiness(
        result,
        diagnostics,
        all_bias_results or {},
    )
    guided_submission_action_plan = build_submission_action_plan(
        result,
        diagnostics,
        all_bias_results or {},
    )
    critical_final_review = build_critical_final_review_panel(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
        role_action_checklist=role_action_checklist,
        report_ready_summary=report_ready_summary,
        final_report_readiness=guided_final_report_readiness,
        submission_action_plan=guided_submission_action_plan,
    )
    critical_final_review_md = generate_critical_final_review_markdown(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
        role_action_checklist=role_action_checklist,
        critical_final_review=critical_final_review,
        report_ready_summary=report_ready_summary,
        final_report_readiness=guided_final_report_readiness,
        submission_action_plan=guided_submission_action_plan,
    )
    st.markdown(f"**{t('guided.critical_review_heading')}**")
    st.caption(t("guided.critical_review_caption"))
    if isinstance(critical_final_review, pd.DataFrame) and not critical_final_review.empty:
        stop_count = int(
            critical_final_review.get("StopBeforeFinalOutput", pd.Series(dtype=bool))
            .fillna(False)
            .astype(bool)
            .sum()
        )
        caveat_count = int(
            critical_final_review.get("NeedsCaveat", pd.Series(dtype=bool))
            .fillna(False)
            .astype(bool)
            .sum()
        )
        status_text = t(
            "guided.critical_review_status_template",
            stop=stop_count,
            caveat=caveat_count,
        )
        if stop_count:
            st.warning(status_text)
        else:
            st.info(status_text)
        _render_compact_dataframe(
            critical_final_review,
            [
                "Priority",
                "Lens",
                "Decision",
                "StopBeforeFinalOutput",
                "NeedsCaveat",
                "ActionBeforeContinuing",
                "EvidenceToOpen",
            ],
            details_label=t("guided.critical_review_details_label"),
            hide_index=True,
            wrap_text=True,
        )
        critical_col, critical_md_col = st.columns(2)
        with critical_col:
            st.download_button(
                t("guided.critical_review_download_csv"),
                data=to_csv_bytes(critical_final_review),
                file_name="critical_final_review_panel.csv",
                mime="text/csv",
                key="dl_guided_critical_final_review_panel_csv",
                use_container_width=True,
            )
        with critical_md_col:
            with st.expander(t("guided.critical_review_expander"), expanded=False):
                st.code(critical_final_review_md, language="markdown")
            st.download_button(
                t("guided.critical_review_download_md"),
                data=critical_final_review_md.encode("utf-8"),
                file_name="critical_final_review.md",
                mime="text/markdown",
                key="dl_guided_critical_final_review_md",
                use_container_width=True,
            )
    else:
        st.info(t("guided.critical_review_empty"))
    status_rationale = build_status_rationale_drilldown(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
        role_action_checklist=role_action_checklist,
        critical_final_review=critical_final_review,
        report_ready_summary=report_ready_summary,
        final_report_readiness=guided_final_report_readiness,
        submission_action_plan=guided_submission_action_plan,
    )
    guided_claim_guide = build_manuscript_claim_guide(
        result,
        diagnostics,
        all_bias_results or {},
    )
    reading_path = build_result_reading_path(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
        report_ready_summary=report_ready_summary,
        final_report_readiness=guided_final_report_readiness,
        manuscript_claim_guide=guided_claim_guide,
    )
    guided_qc_recommendations = build_quality_control_recommendations(result, diagnostics)
    guided_category_action_center = category_collapse_action_center_table(result, diagnostics)
    operational_board = build_operational_decision_board(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
        quality_control_recommendations=guided_qc_recommendations,
        category_action_center=guided_category_action_center,
        critical_final_review=critical_final_review,
        report_ready_summary=report_ready_summary,
        final_report_readiness=guided_final_report_readiness,
        submission_action_plan=guided_submission_action_plan,
    )
    reporting_bridge = build_reporting_action_bridge(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
        role_action_checklist=role_action_checklist,
        report_ready_summary=report_ready_summary,
        final_report_readiness=guided_final_report_readiness,
        manuscript_claim_guide=guided_claim_guide,
        critical_final_review=critical_final_review,
        status_rationale=status_rationale,
        result_reading_path=reading_path,
        operational_decision_board=operational_board,
        quality_control_recommendations=guided_qc_recommendations,
        category_action_center=guided_category_action_center,
        submission_action_plan=guided_submission_action_plan,
    )
    reporting_bridge_md = generate_reporting_action_bridge_markdown(
        result,
        diagnostics,
        all_bias_results=all_bias_results or {},
        bias_results=bias_results,
        bridge=reporting_bridge,
    )
    st.markdown(f"**{t('guided.audience_boards_heading')}**")
    st.caption(t("guided.audience_boards_caption"))
    rationale_tab, reading_tab, operation_tab = st.tabs([
        t("guided.audience_status_tab"),
        t("guided.audience_reading_tab"),
        t("guided.audience_operation_tab"),
    ])
    with rationale_tab:
        if isinstance(status_rationale, pd.DataFrame) and not status_rationale.empty:
            _render_compact_dataframe(
                status_rationale,
                ["Priority", "StatusSource", "CurrentStatus", "Decision", "DecisionLogic", "MinimumEvidenceNeeded"],
                details_label=t("guided.audience_status_details_label"),
                hide_index=True,
                wrap_text=True,
            )
