def _render_guided_essential_tabs(
    core: dict,
    data: pd.DataFrame,
    result: dict,
    diagnostics: dict,
    report_tables: dict,
    scorefile: pd.DataFrame,
    residuals: pd.DataFrame,
    est_facet_cols: list[str],
    person_col: str,
    score_col: str,
    bias_results: dict | None,
    all_bias_results: dict | None,
    *,
    result_compute_pca: bool,
    result_render_plots: bool,
    result_generate_figures: bool,
) -> None:
    """Render the selected Essential section without drawing every heavy panel."""
    selected_section = st.segmented_control(
        t("guided.section_select_label"),
        options=list(GUIDED_SECTION_IDS),
        default="start",
        format_func=_guided_section_label,
        key="guided_essential_section",
        help=t("guided.section_select_help"),
        width="stretch",
    )
    selected_section = selected_section or "start"
    st.caption(t("guided.section_select_caption"))
    render_guided_section_reading_order(selected_section)

    if selected_section == "start":
        _render_guided_start_section(
            core,
            data,
            result,
            diagnostics,
            est_facet_cols,
            person_col,
            score_col,
        )
    elif selected_section == "first_read":
        st.subheader(t("guided.first_read_subheader"))
        st.caption(t("guided.first_read_caption"))
        _render_guided_action_plan(
            result,
            diagnostics,
            all_bias_results,
            expanded_details=True,
            key_suffix="first_read",
        )
    elif selected_section == "results":
        _render_guided_results_section(result, diagnostics, report_tables)
    elif selected_section == "diagnostics":
        _render_guided_diagnostics_section(
            core,
            result,
            diagnostics,
            est_facet_cols,
            bias_results,
            all_bias_results,
            result_compute_pca=result_compute_pca,
            result_render_plots=result_render_plots,
        )
    elif selected_section == "figures":
        _render_guided_figures_section(
            result,
            diagnostics,
            result_render_plots=result_render_plots,
            result_generate_figures=result_generate_figures,
        )
    elif selected_section == "report_export":
        _render_guided_report_export_section(
            result,
            diagnostics,
            report_tables,
            scorefile,
            residuals,
            bias_results,
            all_bias_results,
            generate_figures=result_generate_figures,
        )
    elif selected_section == "learn":
        _render_guided_learn_section()


def _show_data_tab_checks(data: pd.DataFrame, score_col: str) -> None:
    """Show data-specific checks (score range, missing rate) in the Data tab."""
    scores = pd.to_numeric(data[score_col], errors="coerce").dropna()
    if len(scores) > 0:
        n_cats = int(scores.nunique())
        if n_cats < 2:
            st.warning(
                f"**Only {n_cats} distinct score value(s)** found. "
                "At least 2 categories are required for estimation."
            )
    n_missing = data[score_col].isna().sum()
    pct_missing = 100 * n_missing / len(data) if len(data) > 0 else 0
    if pct_missing > 5:
        st.info(
            f"**Missing scores**: {n_missing:,} of {len(data):,} observations "
            f"({pct_missing:.1f}%) have missing scores."
        )
    n_obs = len(data)
    n_unique_scores = int(scores.nunique()) if len(scores) > 0 else 0
    st.caption(
        f"{n_obs:,} observations, {n_unique_scores} score categories "
        f"({int(scores.min())}–{int(scores.max())})"
        if len(scores) > 0 else f"{n_obs:,} observations"
    )


def render_response_data_audit_panel(
    audit_bundle: dict | None,
    *,
    expanded: bool = False,
    context: str = "pre",
) -> None:
    """Render the row-level audit that links user input to likelihood rows."""
    if not isinstance(audit_bundle, dict):
        return
    summary = audit_bundle.get("summary", pd.DataFrame())
    rows = audit_bundle.get("rows", pd.DataFrame())
    excluded_rows = audit_bundle.get("excluded_rows", pd.DataFrame())
    if not isinstance(rows, pd.DataFrame) or rows.empty:
        return
    if not isinstance(summary, pd.DataFrame):
        summary = pd.DataFrame()
    if not isinstance(excluded_rows, pd.DataFrame):
        excluded_rows = pd.DataFrame()

    included = int(rows["IncludedInLikelihood"].sum()) if "IncludedInLikelihood" in rows.columns else 0
    excluded = int((~rows["IncludedInLikelihood"]).sum()) if "IncludedInLikelihood" in rows.columns else 0
    errors = int((rows["LikelihoodAction"].astype(str) == "error_before_fit").sum()) if "LikelihoodAction" in rows.columns else 0
    total = len(rows)

    st.subheader(t("response_audit.subheader"))
    st.caption(t("response_audit.caption"))
    m1, m2, m3 = st.columns(3)
    m1.metric(t("response_audit.metric_input_rows"), f"{total:,}")
    m2.metric(t("response_audit.metric_likelihood_rows"), f"{included:,}")
    m3.metric(t("response_audit.metric_excluded_rows"), f"{excluded:,}")

    if errors:
        st.error(t("response_audit.fractional_error_template", n=f"{errors:,}"))
    elif excluded:
        st.warning(t("response_audit.excluded_warning_template", n=f"{excluded:,}"))
    else:
        st.success(t("response_audit.all_usable_success"))

    expander_label = (
        t("response_audit.expander_pre")
        if context == "pre" else
        t("response_audit.expander_post")
    )
    with st.expander(expander_label, expanded=expanded or bool(excluded or errors)):
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.markdown(t("response_audit.summary_markdown"))
            st.dataframe(summary, width="stretch", hide_index=True)
        if not excluded_rows.empty:
            st.markdown(t("response_audit.excluded_markdown"))
            st.dataframe(excluded_rows.head(500), width="stretch", hide_index=True)
            if len(excluded_rows) > 500:
                st.caption(t("response_audit.first_500_caption_template", n=f"{len(excluded_rows):,}"))
        else:
            st.caption(t("response_audit.no_excluded_caption"))
        st.download_button(
            t("response_audit.download_full_button"),
            data=to_csv_bytes(rows),
            file_name="mfrm_response_data_row_audit.csv",
            mime="text/csv",
            key=f"response_data_row_audit_{context}",
            use_container_width=True,
        )
        if not excluded_rows.empty:
            st.download_button(
                t("response_audit.download_excluded_button"),
                data=to_csv_bytes(excluded_rows),
                file_name="mfrm_response_data_excluded_rows.csv",
                mime="text/csv",
                key=f"response_data_excluded_rows_{context}",
                use_container_width=True,
            )


def _fit_summary_callout(measures_df: pd.DataFrame, facet_filter: str | None = None) -> None:
    """Result-aware success/warning/error callout summarising fit."""
    if measures_df.empty or "Infit" not in measures_df.columns:
        return
    if facet_filter is None or "Facet" not in measures_df.columns:
        df = measures_df
    else:
        df = measures_df[measures_df["Facet"] == facet_filter]
    infit = pd.to_numeric(df["Infit"], errors="coerce")
    outfit = pd.to_numeric(df["Outfit"], errors="coerce") if "Outfit" in df.columns else pd.Series(dtype=float)
    n_total = len(df)
    if n_total == 0:
        return
    misfit_mask = (infit > 1.5) | (infit < 0.5)
    if len(outfit) > 0:
        misfit_mask = misfit_mask | (outfit > 2.0)
    n_misfit = int(misfit_mask.sum())
    pct = 100 * n_misfit / n_total
    label = f" ({facet_filter})" if facet_filter else ""
    pct_int = f"{pct:.0f}"
    if n_misfit == 0:
        st.success(t("fit_details.summary_all_acceptable_template", n_total=n_total, label=label))
    elif pct <= 10:
        st.info(t("fit_details.summary_within_typical_template", n_misfit=n_misfit, n_total=n_total, label=label))
    elif pct <= 25:
        st.warning(t("fit_details.summary_review_warning_template", n_misfit=n_misfit, n_total=n_total, label=label, pct=pct_int))
    else:
        st.error(t("fit_details.summary_widespread_error_template", n_misfit=n_misfit, n_total=n_total, label=label, pct=pct_int))


# ---------------------------------------------------------------------------
# Dimensionality / PCA interpretation
# ---------------------------------------------------------------------------

def show_dimensionality_section(diagnostics: dict, facet_cols: list[str], core: dict | None = None) -> None:
    """Render PCA / dimensionality analysis with scree plot and interpretation."""
    pca = diagnostics.get("pca")
    if pca is None:
        reason = _render_reason(
            diagnostics.get("pca_reason"),
            default=t("dimensionality.reason_unknown_fallback"),
        )
        st.warning(t("dimensionality.warning_pca_failed_template", reason=reason))
        return

    st.markdown(t("dimensionality.interpretation_main"))

    # Determine default tab -- prefer first rater facet if available.
    # ``tab_keys`` are stable identifiers used for routing (the "overall"
    # key drives the mode='overall' branch). ``tab_display`` are the
    # translated labels shown in the Streamlit tab strip; the two arrays
    # stay aligned by index so tab_keys[i] always describes tab_display[i].
    rater_facets = [f for f in facet_cols if "rater" in f.lower() or "judge" in f.lower()]
    tab_keys = ["overall"] + facet_cols
    tab_display = [t("dimensionality.tab_label_overall")] + facet_cols
    default_idx = (tab_keys.index(rater_facets[0]) if rater_facets else 0)

    # Build tab list, put default first by reordering both arrays in lockstep.
    if default_idx > 0:
        order = [default_idx] + [i for i in range(len(tab_keys)) if i != default_idx]
    else:
        order = list(range(len(tab_keys)))
    reordered_keys = [tab_keys[i] for i in order]
    reordered_display = [tab_display[i] for i in order]
    dim_tabs = st.tabs(reordered_display)

    for i, key in enumerate(reordered_keys):
        with dim_tabs[i]:
            if key == "overall":
                _show_pca_panel(pca, mode="overall", core=core, diagnostics=diagnostics, facet_cols=facet_cols)
            else:
                _show_pca_panel(pca, mode="facet", facet_name=key, core=core, diagnostics=diagnostics, facet_cols=facet_cols)

    # Nonparametric DIMTEST (Stout 1987; Nandakumar & Yu 1996),
    # complementary to the residual PCA above.
    result = (core or {}).get("result") if isinstance(core, dict) else None
    render_dimtest_panel(result, diagnostics, facet_cols)


def render_dimtest_panel(
    result: dict | None,
    diagnostics: dict | None,
    facet_cols: list[str] | None = None,
) -> None:
    """Render the nonparametric DIMTEST panel.

    Sits below the residual-PCA tabs as a complementary nonparametric
    check on essential unidimensionality. Runs on demand because the
    cluster bootstrap can be slow on large designs.
    """
    if result is None or not isinstance(facet_cols, list) or not facet_cols:
        return
    st.subheader(t("dimensionality.dimtest_subheader"))
    st.caption(t("dimensionality.dimtest_caption"))

    # Pick a default item facet: prefer "Criterion" if present, else
    # the first non-rater-like facet.
    item_facet_default = next(
        (f for f in facet_cols if f.lower() == "criterion"),
        next((f for f in facet_cols if "rater" not in f.lower() and "judge" not in f.lower()),
             facet_cols[0]),
    )
    item_facet = st.selectbox(
        t("dimensionality.dimtest_item_facet_label"),
        options=facet_cols,
        index=facet_cols.index(item_facet_default),
        key=f"dimtest_item_facet::{id(result)}",
    )

    # Build the candidate items list (so the user can pick a-priori
    # AT / PT). Read from the prep['levels'][item_facet].
    prep = result.get("prep", {}) if isinstance(result, dict) else {}
    levels = prep.get("levels", {}) if isinstance(prep, dict) else {}
    items = [str(x) for x in levels.get(item_facet, [])]
    if len(items) < 4:
        st.info(
            t(
                "dimensionality.dimtest_too_few_items_template",
                item_facet=item_facet, n=len(items),
            )
        )
        return

    use_auto = st.checkbox(
        t("dimensionality.dimtest_use_auto_split"),
        value=True, key=f"dimtest_use_auto::{id(result)}",
    )
    at_items: list[str] = []
    pt_items: list[str] = []
    if not use_auto:
        cols = st.columns(2)
        with cols[0]:
            at_items = st.multiselect(
                t("dimensionality.dimtest_at_label"),
                options=items, default=items[: max(2, len(items) // 2)],
                key=f"dimtest_at::{id(result)}",
            )
        with cols[1]:
            pt_items = st.multiselect(
                t("dimensionality.dimtest_pt_label"),
                options=[x for x in items if x not in at_items],
                default=[x for x in items if x not in at_items],
                key=f"dimtest_pt::{id(result)}",
            )

    nb_col, conf_col = st.columns(2)
    with nb_col:
        n_bootstrap = int(
            st.number_input(
                t("dimensionality.dimtest_n_bootstrap"),
                min_value=50, max_value=2000, value=200, step=50,
                key=f"dimtest_n_boot::{id(result)}",
            )
        )
    with conf_col:
        confidence = float(
            st.selectbox(
                t("dimensionality.dimtest_confidence"),
                options=list(VIZ_CI_LEVEL_OPTIONS),
                index=VIZ_CI_LEVEL_OPTIONS.index(0.95)
                    if 0.95 in VIZ_CI_LEVEL_OPTIONS else 5,
                key=f"dimtest_conf::{id(result)}",
                format_func=lambda v: f"{_ci_level_pct_label(v)} %",
            )
        )

    cache_key = "|".join([
        str(item_facet), str(use_auto),
        ",".join(at_items), ",".join(pt_items),
        str(n_bootstrap), str(confidence),
    ])
    state_key = f"dimtest_bundle::{id(result)}::{cache_key}"
    bundle = st.session_state.get(state_key)
    if bundle is None:
        if st.button(
            t("dimensionality.dimtest_run_button"),
            help=t("dimensionality.dimtest_run_help"),
            key=f"dimtest_run::{id(result)}::{cache_key}",
        ):
            with st.spinner(t("dimensionality.dimtest_running_spinner")):
                bundle = compute_dimtest_nonparametric(
                    result, diagnostics,
                    item_facet=item_facet,
                    at_items=at_items if not use_auto else None,
                    pt_items=pt_items if not use_auto else None,
                    n_bootstrap=n_bootstrap,
                    confidence=confidence,
                )
            st.session_state[state_key] = bundle
        else:
            return

    if not bundle.get("available"):
        st.info(
            t(
                "dimensionality.dimtest_unavailable_template",
                reason=str(bundle.get("reason", "")),
            )
        )
        return

    z_val = float(bundle.get("Z", float("nan")))
    p_val = float(bundle.get("p_value", float("nan")))
    t_l = float(bundle.get("T_L", float("nan")))
    cols = st.columns(4)
    cols[0].metric(t("dimensionality.dimtest_metric_T_L"), f"{t_l:.4f}")
    cols[1].metric(t("dimensionality.dimtest_metric_Z"), f"{z_val:.3f}")
    cols[2].metric(t("dimensionality.dimtest_metric_p"), f"{p_val:.4f}")
    cols[3].metric(
        t("dimensionality.dimtest_metric_n_persons"),
        f"{int(bundle.get('n_persons', 0)):,}",
    )

    st.caption(
        t(
            "dimensionality.dimtest_summary_caption_template",
            at=", ".join(bundle.get("at_items", [])),
            pt=", ".join(bundle.get("pt_items", [])),
            split=str(bundle.get("split_method", "")),
            confidence=int(round(float(bundle.get("settings", {}).get("confidence", 0.95)) * 100)),
            ci_low=f"{float(bundle.get('ci_lower', float('nan'))):.4f}",
            ci_high=f"{float(bundle.get('ci_upper', float('nan'))):.4f}",
        )
    )

    if p_val < 0.05:
        st.warning(t("dimensionality.dimtest_reject_warning"))
    else:
        st.success(t("dimensionality.dimtest_retain_success"))

    caveat = bundle.get("caveat", "")
    if caveat:
        st.caption(t("dimensionality.dimtest_caveat_label") + ": " + str(caveat))


def _show_pca_panel(
    pca: dict,
    mode: str = "overall",
    facet_name: str | None = None,
    core: dict | None = None,
    diagnostics: dict | None = None,
    facet_cols: list[str] | None = None,
) -> None:
    """Render a single PCA panel (overall or per-facet) with scree plot and assessment."""


    # --- Use cached PCA first, then fall back to direct computation ---
    eigenvalues = None
    var_pct = None
    loadings = None
    stability_table = pd.DataFrame()

    # Prefer pre-computed PCA from mfrm_diagnostics so Streamlit reruns do not
    # recompute expensive decompositions just to redraw the page.
    if mode == "overall" and isinstance(pca, dict):
        eigenvalues = pca.get("eigenvalues")
        var_pct = pca.get("variance_pct")
        loadings = pca.get("loadings")
        stability_table = pca.get("stability_table", pd.DataFrame())
    elif mode == "facet" and diagnostics and facet_name:
        facet_pca = (diagnostics.get("pca_by_facet") or {}).get(facet_name)
        if isinstance(facet_pca, dict):
            eigenvalues = facet_pca.get("eigenvalues")
            var_pct = facet_pca.get("variance_pct")
            loadings = facet_pca.get("loadings")
            stability_table = facet_pca.get("stability_table", pd.DataFrame())

    if core and diagnostics:
        obs = diagnostics.get("obs")
        config_facet_names = facet_cols or []
        if eigenvalues is None and mode == "overall" and core.get("compute_pca_overall") and obs is not None:
            try:
                pca_bundle = core["compute_pca_overall"](obs, config_facet_names)
                if pca_bundle:
                    eigenvalues = pca_bundle.get("eigenvalues")
                    var_pct = pca_bundle.get("variance_pct")
                    loadings = pca_bundle.get("loadings")
                    stability_table = pca_bundle.get("stability_table", pd.DataFrame())
            except Exception as pca_exc:
                st.caption(t("dimensionality.computation_failed_caption_template", error=str(pca_exc)))
        elif eigenvalues is None and mode == "facet" and core.get("compute_pca_by_facet") and obs is not None and facet_name:
            try:
                pca_bundles = core["compute_pca_by_facet"](obs, [facet_name])
                pca_bundle = pca_bundles.get(facet_name) if pca_bundles else None
                if pca_bundle:
                    eigenvalues = pca_bundle.get("eigenvalues")
                    var_pct = pca_bundle.get("variance_pct")
                    loadings = pca_bundle.get("loadings")
                    stability_table = pca_bundle.get("stability_table", pd.DataFrame())
            except Exception as pca_exc:
                st.caption(t("dimensionality.computation_failed_caption_template", error=str(pca_exc)))

    # --- Fall back to pca dict from diagnostics ---
    tbl = None
    # Plotly chart titles stay in English regardless of locale (per i18n
    # policy: figures may be exported to publications). The Streamlit
    # text label uses the translated form.
    if mode == "overall":
        label_plot = "Overall standardized residuals"
        label_ui = t("dimensionality.label_overall")
    else:
        label_plot = f"Residuals for facet: {facet_name}"
        label_ui = t("dimensionality.label_facet_template", facet_name=facet_name)

    if tbl is None or (hasattr(tbl, "__len__") and len(tbl) == 0):
        if eigenvalues is None:
            # Surface the per-facet skip reason recorded in mfrm_diagnostics.
            # The payload is stored as a dict by ``_make_reason`` so we
            # resolve it here in the active locale via ``_render_reason``.
            reason_payload = None
            if mode == "facet" and facet_name and isinstance(diagnostics, dict):
                reason_map = diagnostics.get("pca_by_facet_reasons") or {}
                reason_payload = reason_map.get(facet_name)
            elif mode == "overall" and isinstance(diagnostics, dict):
                reason_payload = diagnostics.get("pca_reason")
            reason = _render_reason(reason_payload)
            if reason:
                st.warning(t("dimensionality.warning_label_reason_template", label=label_ui, reason=reason))
            else:
                st.caption(t("dimensionality.no_results_caption_template", label=label_ui))
            return

    st.markdown(f"**{label_ui}**")
    if tbl is not None and not (hasattr(tbl, "empty") and tbl.empty):
        st.dataframe(tbl, width="stretch")

    # --- Extract eigenvalues from table if not from core ---
    if eigenvalues is None and tbl is not None:
        eigen_col = None
        for candidate in ("Eigenvalue", "eigenvalue", "EV"):
            if candidate in tbl.columns:
                eigen_col = candidate
                break
        if eigen_col is None:
            return
        eigenvalues = pd.to_numeric(tbl[eigen_col], errors="coerce").dropna().values
        # Try variance column
        for vc in ("Variance_Pct", "Variance%", "variance_pct", "Proportion"):
            if vc in tbl.columns:
                var_pct = pd.to_numeric(tbl[vc], errors="coerce").dropna().values
                break

    if eigenvalues is None or len(eigenvalues) < 2:
        st.caption(t("dimensionality.insufficient_caption"))
        return

    # --- Scree plot ---
    header_cols = st.columns([5, 1])
    with header_cols[0]:
        st.markdown(f"##### {t('dimensionality.scree_plot_header')}")
    with header_cols[1]:
        render_help_popover("scree")
    max_components = min(20, len(eigenvalues))
    components = list(range(1, max_components + 1))
    ev_plot = eigenvalues[:max_components]

    fig = go.Figure()
    fig.add_trace(go.Scatter(x=components, y=list(ev_plot), mode="lines+markers",
                             marker=dict(size=7, color="#1b9e77"),
                             line=dict(width=2, color="#1b9e77"), name="Eigenvalue"))
    # Three reference lines matching the interpretation thresholds cited in
    # the chart guide and narrative — EV=1 (expected random), EV=2 (caution),
    # EV=3 (strong secondary residual signal; Linacre 2024). Previously only EV=1
    # and EV=2 were drawn, making the "EV > 3 flags a residual contrast"
    # guidance invisible on the plot itself.
    fig.add_hline(y=3.0, line_dash="dash", line_color="#c0392b", line_width=1,
                  annotation_text="Strong residual signal (EV=3.0)",
                  annotation_position="top right")
    fig.add_hline(y=2.0, line_dash="dash", line_color="#d95f02", line_width=1,
                  annotation_text="Caution (EV=2.0)", annotation_position="top right")
    fig.add_hline(y=1.0, line_dash="dot", line_color="#666666", line_width=1,
                  annotation_text="Expected (EV=1.0)", annotation_position="bottom right")
    fig.update_layout(xaxis_title="Component", yaxis_title="Eigenvalue",
                      title=f"Scree Plot — {label_plot}", yaxis_rangemode="tozero",
                      xaxis=dict(dtick=1), height=350, template="plotly_white")
    st.plotly_chart(fig, width="stretch")
    render_chart_guide("scree")

    # --- Eigenvalue table ---
    n_show = min(10, len(eigenvalues))
    eigen_df_data: dict[str, list] = {
        "Component": [f"PC{i}" for i in range(1, n_show + 1)],
        "Eigenvalue": list(eigenvalues[:n_show]),
    }
    if var_pct is not None and len(var_pct) >= n_show:
        eigen_df_data["Variance %"] = list(var_pct[:n_show])
        eigen_df_data["Cumulative %"] = list(np.cumsum(var_pct[:n_show]))
    eigen_df = pd.DataFrame(eigen_df_data)
    st.subheader(t("dimensionality.eigenvalues_subheader"))
    st.dataframe(eigen_df.round(3), width="stretch")

    if isinstance(stability_table, pd.DataFrame) and not stability_table.empty:
        stability_status = str(stability_table.iloc[0].get("PCAStabilityStatus", "Review"))
        stability_caution = str(stability_table.iloc[0].get("Caution", "Review PCA stability before using loadings."))
        if stability_status == "Stable screen":
            st.success(f"PCA stability audit: {stability_status}.")
        else:
            st.warning(f"PCA stability audit: {stability_status}.")
        with st.expander("PCA stability audit", expanded=stability_status != "Stable screen"):
            st.caption(stability_caution)
            display_cols = [
                "PCAStabilityStatus", "Persons", "ResidualColumns", "MissingShare",
                "MinPairwiseOverlap", "MedianPairwiseOverlap", "FullEV1", "FullEV2",
                "FullPC1VariancePct", "LOOColumnsEvaluated", "LOOEV1MaxAbsDelta",
                "LOOEV1ShareMaxAbsDelta",
                "LOOPC1MedianAbsLoadingCorrelation", "LOOPC1MinAbsLoadingCorrelation",
                "BootstrapReplicates", "BootstrapEV1CV", "BootstrapEV1P05",
                "BootstrapEV1P95", "BootstrapPC1MedianAbsLoadingCorrelation",
                "BootstrapPC1MinAbsLoadingCorrelation", "BootstrapEV1ThresholdCrossing",
                "SensitivityFlagSummary", "Rule", "Caution",
            ]
            st.dataframe(stability_table[[c for c in display_cols if c in stability_table.columns]], width="stretch", hide_index=True)
            dl_label = re.sub(r"[^A-Za-z0-9]+", "_", label_plot).strip("_").lower() or "pca"
            st.download_button(
                "Download PCA stability audit CSV",
                data=to_csv_bytes(stability_table),
                file_name=f"mfrm_pca_stability_audit_{dl_label}.csv",
                mime="text/csv",
                key=f"dl_pca_stability_{mode}_{dl_label}",
            )

    # --- PC1 loadings bar chart ---
    if loadings is not None and hasattr(loadings, "columns") and "PC1" in loadings.columns:
        top_loadings = loadings["PC1"].abs().sort_values(ascending=False).head(20).index
        loadings_plot = loadings.loc[top_loadings, "PC1"].sort_values()

        colors = ["#d95f02" if v > 0 else "#1b9e77" for v in loadings_plot.values]
        loading_labels = [str(idx) for idx in loadings_plot.index]
        fig2 = go.Figure(go.Bar(
            x=loadings_plot.values,
            y=loading_labels,
            orientation="h", marker_color=colors,
            customdata=np.array(loading_labels, dtype=object),
            hovertemplate="%{customdata}<br>PC1 loading=%{x:.3f}<extra></extra>",
        ))
        fig2.add_vline(x=0, line_color="gray", line_width=1)
        fig2.update_layout(xaxis_title="PC1 Loading", title="PC1 Loadings (top 20)",
                           height=max(300, len(loadings_plot) * 22), template="plotly_white",
                           yaxis=dict(autorange="reversed"),
                           margin=_readable_plot_margins(y_labels=loading_labels, base_left=130))
        fig2.update_yaxes(
            tickmode="array",
            tickvals=loading_labels,
            ticktext=_compact_label_list(loading_labels, max_chars=42),
            automargin=True,
        )
        st.plotly_chart(fig2, width="stretch")

    # --- Residual dimensionality screening summary ---
    ev1 = float(eigenvalues[0])
    ev2 = float(eigenvalues[1]) if len(eigenvalues) > 1 else np.nan
    eig_ratio = ev1 / ev2 if np.isfinite(ev2) and ev2 > 0 else np.nan
    eig_above_1 = int(np.sum(eigenvalues > 1))
    pc1_var = float(var_pct[0]) if var_pct is not None and len(var_pct) > 0 else np.nan

    # Note: var_pct is % of residual variance.  In a typical Rasch analysis the
    # model explains 50-70% of total variance, so 10% of residual ≈ 3-5% of total.
    # The Smith (2002) criterion of <5% total roughly maps to ~10-15% of residual.
    assessment = t("dimensionality.assessment_acceptable")
    if ev1 >= 3.0:
        assessment = t("dimensionality.assessment_potential_multi_strong")
    elif ev1 >= 2.0:
        assessment = t("dimensionality.assessment_minor_secondary")
    elif np.isfinite(pc1_var) and pc1_var > 15:
        assessment = t("dimensionality.assessment_potential_multi_var")
    elif np.isfinite(eig_ratio) and eig_ratio < 3:
        assessment = t("dimensionality.assessment_potential_multi_ratio")

    # DataFrame column names ("Metric", "Value") and the row labels
    # ("1st eigenvalue", etc.) stay in English so CSV/Excel exports keep
    # consistent column naming across locales.
    assess_df = pd.DataFrame({
        "Metric": [
            "1st eigenvalue",
            "PC1 variance",
            "Eigenvalue ratio (PC1/PC2)",
            "Eigenvalues > 1",
            "Assessment",
        ],
        "Value": [
            f"{ev1:.2f}",
            f"{pc1_var:.1f}%" if np.isfinite(pc1_var) else "N/A",
            f"{eig_ratio:.2f}" if np.isfinite(eig_ratio) else "N/A",
            str(eig_above_1),
            assessment,
        ],
    })
    st.subheader(t("dimensionality.assessment_subheader"))
    st.dataframe(assess_df, width="stretch")

    # --- Interpretation badge ---
    ev1_fmt = f"{ev1:.2f}"
    if ev1 < 1.5:
        st.success(t("dimensionality.badge_good_template", ev1=ev1_fmt))
    elif ev1 < FINAL_PCA_EIGENVALUE_READY:
        st.info(t("dimensionality.badge_acceptable_template", ev1=ev1_fmt))
    elif ev1 < FINAL_PCA_EIGENVALUE_REVIEW:
        st.warning(t("dimensionality.badge_warning_template", ev1=ev1_fmt))
    else:
        st.error(t("dimensionality.badge_error_template", ev1=ev1_fmt))


# ---------------------------------------------------------------------------
# Wright Map + Yardstick
# ---------------------------------------------------------------------------

def _minimum_within_facet_logit_gap(facet_est: pd.DataFrame) -> float:
    """Smallest within-facet vertical gap, used to avoid label collisions."""
    if (
        not isinstance(facet_est, pd.DataFrame)
        or facet_est.empty
        or "Facet" not in facet_est.columns
        or "Estimate" not in facet_est.columns
    ):
        return float("inf")
    gaps: list[float] = []
    for _, sub in facet_est.groupby("Facet", dropna=False):
        vals = pd.to_numeric(sub["Estimate"], errors="coerce").dropna().sort_values().to_numpy()
        if len(vals) >= 2:
            gaps.extend(float(v) for v in np.diff(vals) if np.isfinite(v))
    return min(gaps) if gaps else float("inf")


def show_wright_map_section(result: dict, diagnostics: dict) -> None:
    """Render both the classic Wright Map and the FACETS-style yardstick."""
    header_cols = st.columns([5, 1])
    with header_cols[0]:
        st.markdown(f"##### {t('visuals.wright_map_header')}")
    with header_cols[1]:
        render_help_popover("wright_map")
    st.caption(t("visuals.wright_map_caption"))

    facets = result.get("facets", {})
    person_tbl = facets.get("person", pd.DataFrame())
    facet_tbl = facets.get("others", pd.DataFrame())
    step_tbl = result.get("steps", pd.DataFrame())

    # Result-aware targeting check
    _p_est = pd.to_numeric(person_tbl.get("Estimate", pd.Series(dtype=float)), errors="coerce").dropna()
    _f_est = pd.to_numeric(facet_tbl.get("Estimate", pd.Series(dtype=float)), errors="coerce").dropna()
    if len(_p_est) > 0 and len(_f_est) > 0:
        overlap = min(float(_p_est.max()), float(_f_est.max())) - max(float(_p_est.min()), float(_f_est.min()))
        if overlap > 0:
            st.success(t(
                "visuals.targeting_overlap_success_template",
                overlap=f"{overlap:.2f}",
            ))
        else:
            st.warning(t(
                "visuals.targeting_overlap_warning_template",
                gap=f"{-overlap:.2f}",
            ))

    # Tabs are accessed by index (wm_tabs[0]/[1]) below, so the labels can be
    # safely translated without breaking routing.
    wm_tabs = st.tabs([
        t("visuals.tab_label_wright_map"),
        t("visuals.tab_label_yardstick"),
    ])

    with wm_tabs[0]:
        _draw_wright_map_plotly(person_tbl, facet_tbl, step_tbl)

    with wm_tabs[1]:
        prep = result.get("prep", {}) if isinstance(result, dict) else {}
        rating_min = prep.get("rating_min")
        _draw_yardstick(person_tbl, facet_tbl, step_tbl, rating_min=rating_min)






def _draw_yardstick(
    person_tbl: pd.DataFrame,
    facet_tbl: pd.DataFrame,
    step_tbl: pd.DataFrame,
    *,
    rating_min: int | float | None = None,
) -> None:
    """FACETS Table 6.0 style yardstick: vertical logit ruler with facet columns."""


    st.markdown(t("visuals.yardstick_intro_markdown"))

    person_est = pd.to_numeric(person_tbl.get("Estimate", pd.Series(dtype=float)), errors="coerce").dropna()
    if person_est.empty:
        st.caption(t("visuals.no_finite_person_estimates"))
        return

    facet_est = facet_tbl.copy() if facet_tbl is not None else pd.DataFrame()
    if "Estimate" in facet_est.columns:
        facet_est["Estimate"] = pd.to_numeric(facet_est["Estimate"], errors="coerce")
        facet_est = facet_est.dropna(subset=["Estimate"])

    facet_names = list(facet_est["Facet"].unique()) if "Facet" in facet_est.columns else []
    if len(facet_names) < 1:
        st.caption(t("visuals.not_enough_facets_yardstick"))
        return
    max_elements_per_facet = int(facet_est.groupby("Facet").size().max()) if "Facet" in facet_est.columns and not facet_est.empty else 0
    label_max = (
        int(facet_est.get("Level", pd.Series(dtype=str)).astype(str).str.len().max())
        if "Level" in facet_est.columns and not facet_est.empty else 0
    )
    min_label_gap = _minimum_within_facet_logit_gap(facet_est)
    tight_labels = min_label_gap < 0.30
    crowded = max_elements_per_facet > 18 or len(facet_names) > 7 or label_max > 28
    show_direct_labels = True
    if crowded or tight_labels:
        st.caption(t("visuals.dense_yardstick_caption"))

    fig = _make_yardstick_figure(
        person_tbl,
        facet_est,
        step_tbl,
        show_direct_labels=show_direct_labels,
        rating_min=rating_min,
    )
    if fig is None:
        st.caption(t("visuals.not_enough_facets_yardstick"))
        return
    st.plotly_chart(fig, width="stretch")
    yardstick_map = make_yardstick_export_table(
        person_tbl,
        facet_est,
        step_tbl,
        rating_min=rating_min,
    )
    if not yardstick_map.empty:
        script_assets = yardstick_reproducibility_scripts()
        bundle_assets: dict[str, bytes | str] = {
            "mfrm_yardstick_map.csv": yardstick_map.to_csv(index=False),
            **script_assets,
        }
        with st.expander("Download / reproduce this FACETS-style yardstick", expanded=False):
            st.caption(
                "The CSV contains the exact logit positions and display labels used by the figure. "
                "Threshold rows also include line positions for the short boundary segments. "
                "The R script uses ggplot2::geom_text() and geom_segment(); Python and Julia templates are included for cross-language reproduction."
            )
            st.dataframe(
                yardstick_map.loc[:, [
                    c for c in [
                        "Role", "Facet", "DisplayLabel", "Estimate", "PlotY",
                        "TextLane", "LineXStart", "LineXEnd", "PlotColumn"
                    ] if c in yardstick_map.columns
                ]],
                width="stretch",
                hide_index=True,
            )
            ycol1, ycol2 = st.columns(2)
            with ycol1:
                st.download_button(
                    "Download yardstick map CSV",
                    data=to_csv_bytes(yardstick_map),
                    file_name="mfrm_yardstick_map.csv",
                    mime="text/csv",
                    key="dl_yardstick_map_csv",
                )
            with ycol2:
                st.download_button(
                    "Download yardstick reproduction bundle",
                    data=cached_mixed_asset_zip(bundle_assets, bytes_mapping_fingerprint(bundle_assets)),
                    file_name="MFRM_FACETS_Yardstick_Reproduction.zip",
                    mime="application/zip",
                    key="dl_yardstick_reproduction_zip",
                )
    render_chart_guide("facets_yardstick")


def _yardstick_step_boundary(label: object, *, rating_min: int | float | None = None) -> tuple[str, float | None, float | None]:
    """Return a FACETS-style threshold label such as 0|1 or 4|5."""
    raw = str(label or "").strip()
    match = re.fullmatch(r"(?i)\s*step[\s_-]*(\d+)\s*", raw)
    if not match:
        return raw, None, None
    step_index = int(match.group(1))
    try:
        base = int(float(rating_min)) if rating_min is not None and np.isfinite(float(rating_min)) else 1
    except Exception:
        base = 1
    lower = base + step_index - 1
    upper = lower + 1
    return f"{lower}|{upper}", float(lower), float(upper)


def _yardstick_threshold_frame(
    step_tbl: pd.DataFrame | None,
    *,
    rating_min: int | float | None = None,
) -> pd.DataFrame:
    """Normalize step/threshold estimates for the FACETS-style yardstick column."""
    if not isinstance(step_tbl, pd.DataFrame) or step_tbl.empty or "Estimate" not in step_tbl.columns:
        return pd.DataFrame(columns=["Label", "RawLabel", "DisplayLabel", "Estimate"])
    out = step_tbl.copy()
    out["Estimate"] = pd.to_numeric(out["Estimate"], errors="coerce")
    out = out.dropna(subset=["Estimate"])
    if out.empty:
        return pd.DataFrame(columns=["Label", "RawLabel", "DisplayLabel", "Estimate"])
    if "Step" in out.columns:
        labels = out["Step"].astype(str)
    elif "Category" in out.columns:
        labels = out["Category"].astype(str)
    else:
        labels = pd.Series([f"Step_{idx + 1}" for idx in range(len(out))], index=out.index)
    boundary = [
        _yardstick_step_boundary(label, rating_min=rating_min)
        for label in labels.tolist()
    ]
    display_labels = [item[0] for item in boundary]
    boundary_lower = [item[1] for item in boundary]
    boundary_upper = [item[2] for item in boundary]
    step_facet = (
        out["StepFacet"].astype(str).to_numpy()
        if "StepFacet" in out.columns else np.repeat("Common", len(out))
    )
    return pd.DataFrame({
        "Label": display_labels,
        "RawLabel": labels.to_numpy(),
        "DisplayLabel": display_labels,
        "StepFacet": step_facet,
        "BoundaryLower": boundary_lower,
        "BoundaryUpper": boundary_upper,
        "Estimate": out["Estimate"].to_numpy(dtype=float),
    })


def _yardstick_label_x_positions(
    estimates: pd.Series | list[float] | np.ndarray,
    *,
    base: float = 0.12,
    lane_width: float = 0.14,
    min_gap: float = 0.30,
    max_lanes: int = 5,
) -> list[float]:
    """Horizontally stagger close labels while preserving their logit y-position."""
    x_positions, _, _ = _yardstick_label_layout(
        estimates,
        base=base,
        lane_width=lane_width,
        min_gap=min_gap,
        max_lanes=max_lanes,
    )
    return x_positions


def _yardstick_label_layout(
    estimates: pd.Series | list[float] | np.ndarray,
    *,
    base: float = 0.12,
    lane_width: float = 0.14,
    min_gap: float = 0.30,
    max_lanes: int = 5,
    min_y_gap: float = 0.16,
) -> tuple[list[float], list[float], list[int]]:
    """Return deterministic text lanes for dense FACETS-style yardstick labels.

    The exported ``Estimate`` remains the exact logit value. ``PlotY`` is a
    small display dodge used only when labels are too close to read.
    """
    vals = pd.to_numeric(pd.Series(estimates), errors="coerce")
    if vals.empty:
        return [], [], []
    vals = vals.reset_index(drop=True)
    positions = [base] * len(vals)
    y_positions = [
        float(value) if pd.notna(value) and np.isfinite(float(value)) else np.nan
        for value in vals
    ]
    lanes = [0] * len(vals)
    finite = vals.dropna().sort_values()
    clusters: list[list[int]] = []
    current: list[int] = []
    last_val: float | None = None
    for idx, val in finite.items():
        val_f = float(val)
        if last_val is None or abs(val_f - last_val) < min_gap:
            current.append(int(idx))
        else:
            if current:
                clusters.append(current)
            current = [int(idx)]
        last_val = val_f
    if current:
        clusters.append(current)
    for cluster in clusters:
        if len(cluster) <= 1:
            continue
        cluster_sorted = sorted(cluster, key=lambda idx: float(vals.iloc[idx]))
        lane_count = max(1, min(int(max_lanes), len(cluster_sorted)))
        raw_values = [float(vals.iloc[idx]) for idx in cluster_sorted]
        actual_span = max(raw_values) - min(raw_values) if raw_values else 0.0
        required_span = float(min_y_gap) * (len(cluster_sorted) - 1)
        if actual_span < required_span:
            center = float(np.mean(raw_values))
            display_values = [
                center + (rank - (len(cluster_sorted) - 1) / 2.0) * float(min_y_gap)
                for rank in range(len(cluster_sorted))
            ]
        else:
            display_values = raw_values
        for lane_idx, original_idx in enumerate(cluster_sorted):
            lane = lane_idx % lane_count
            positions[original_idx] = base + lane * lane_width
            y_positions[original_idx] = display_values[lane_idx]
            lanes[original_idx] = lane
    return positions, y_positions, lanes


def make_yardstick_export_table(
    person_tbl: pd.DataFrame,
    facet_tbl: pd.DataFrame,
    step_tbl: pd.DataFrame | None = None,
    *,
    rating_min: int | float | None = None,
    plot_label_mode: str | None = None,
) -> pd.DataFrame:
    """Create the portable data contract behind the FACETS-style yardstick."""
    rows: list[dict[str, object]] = []

    if isinstance(person_tbl, pd.DataFrame) and "Estimate" in person_tbl.columns:
        person_est = pd.to_numeric(person_tbl["Estimate"], errors="coerce")
        label_col = "Person" if "Person" in person_tbl.columns else None
        for idx, estimate in person_est.dropna().items():
            raw_label = str(person_tbl.loc[idx, label_col]) if label_col else ""
            rows.append({
                "Role": "Person",
                "Facet": "Person",
                "RawLabel": raw_label,
                "DisplayLabel": raw_label,
                "Estimate": float(estimate),
                "PlotY": float(estimate),
                "TextLane": 0,
                "LineXStart": np.nan,
                "LineXEnd": np.nan,
                "PlotColumn": "Measr / Persons",
                "PlotKind": "histogram_source",
                "BoundaryLower": np.nan,
                "BoundaryUpper": np.nan,
            })

    facet_est = facet_tbl.copy() if isinstance(facet_tbl, pd.DataFrame) else pd.DataFrame()
    if not facet_est.empty and {"Facet", "Estimate"}.issubset(facet_est.columns):
        facet_est["Estimate"] = pd.to_numeric(facet_est["Estimate"], errors="coerce")
        facet_est = facet_est.dropna(subset=["Estimate"])
        for _, row in facet_est.iterrows():
            facet = str(row.get("Facet", "Facet"))
            raw_label = str(row.get("Level", row.get("Element", "")))
            rows.append({
                "Role": "FacetElement",
                "Facet": facet,
                "RawLabel": raw_label,
                "DisplayLabel": _compact_label(raw_label, 28),
                "Estimate": float(row["Estimate"]),
                "PlotY": float(row["Estimate"]),
                "TextLane": 0,
                "LineXStart": np.nan,
                "LineXEnd": np.nan,
                "PlotColumn": facet,
                "PlotKind": "direct_text",
                "BoundaryLower": np.nan,
                "BoundaryUpper": np.nan,
            })

    threshold_frame = _yardstick_threshold_frame(step_tbl, rating_min=rating_min)
    if not threshold_frame.empty:
        for _, row in threshold_frame.iterrows():
            step_facet = str(row.get("StepFacet", "Common"))
            display = str(row.get("DisplayLabel", row.get("Label", "")))
            if step_facet and step_facet != "Common":
                display = f"{step_facet}: {display}"
            rows.append({
                "Role": "Threshold",
                "Facet": step_facet,
                "RawLabel": str(row.get("RawLabel", row.get("Label", ""))),
                "DisplayLabel": _compact_label(display, 28),
                "Estimate": float(row["Estimate"]),
                "PlotY": float(row["Estimate"]),
                "TextLane": 0,
                "LineXStart": 0.08,
                "LineXEnd": 0.20,
                "PlotColumn": "Thresholds",
                "PlotKind": "direct_text",
                "BoundaryLower": row.get("BoundaryLower", np.nan),
                "BoundaryUpper": row.get("BoundaryUpper", np.nan),
            })

    if not rows:
        return pd.DataFrame(columns=[
            "Role", "Facet", "RawLabel", "DisplayLabel", "Estimate", "PlotY", "TextLane",
            "LineXStart", "LineXEnd", "PlotColumn", "PlotKind", "BoundaryLower", "BoundaryUpper",
            "PlotLabelID", "PlotLabelShort", "PlotLabelFull", "PlotLabelMode", "PlotLabelGroup",
        ])
    out = pd.DataFrame(rows)
    out["Estimate"] = pd.to_numeric(out["Estimate"], errors="coerce")
    out["PlotY"] = pd.to_numeric(out.get("PlotY", out["Estimate"]), errors="coerce")
    out["TextLane"] = pd.to_numeric(out.get("TextLane", 0), errors="coerce").fillna(0).astype(int)
    out["LineXStart"] = pd.to_numeric(out.get("LineXStart", np.nan), errors="coerce")
    out["LineXEnd"] = pd.to_numeric(out.get("LineXEnd", np.nan), errors="coerce")
    for _, idx in out[out["PlotKind"] == "direct_text"].groupby("PlotColumn").groups.items():
        idx_list = list(idx)
        _, plot_y, lanes = _yardstick_label_layout(
            out.loc[idx_list, "Estimate"].reset_index(drop=True),
            base=0.12,
            lane_width=0.14,
            min_gap=0.30,
            max_lanes=5,
        )
        out.loc[idx_list, "PlotY"] = plot_y
        out.loc[idx_list, "TextLane"] = lanes
    out = build_plot_label_lookup(
        out,
        label_mode=plot_label_mode,
        max_chars=int(get_visualization_preferences().get("label_max_chars", VISUAL_LABEL_MAX_CHARS_DEFAULT)),
    )
    return out.sort_values(["Role", "PlotColumn", "Estimate", "DisplayLabel"]).reset_index(drop=True)


def _make_yardstick_figure(
    person_tbl: pd.DataFrame,
    facet_tbl: pd.DataFrame,
    step_tbl: pd.DataFrame | None = None,
    *,
    show_direct_labels: bool = True,
    rating_min: int | float | None = None,
    plot_label_mode: str | None = None,
):
    """Build a FACETS-like text-first yardstick figure.

    This intentionally differs from the general Wright Map: the primary marks
    are text labels placed on a vertical ruler, matching the way FACETS users
    read Table 6.0-style maps. Points are used only when direct labels are
    disabled for dense designs.
    """
    person_est = pd.to_numeric(
        person_tbl.get("Estimate", pd.Series(dtype=float)), errors="coerce"
    ).dropna() if isinstance(person_tbl, pd.DataFrame) else pd.Series(dtype=float)
    if person_est.empty:
        return None

    facet_est = facet_tbl.copy() if isinstance(facet_tbl, pd.DataFrame) else pd.DataFrame()
    if "Estimate" in facet_est.columns:
        facet_est["Estimate"] = pd.to_numeric(facet_est["Estimate"], errors="coerce")
        facet_est = facet_est.dropna(subset=["Estimate"])
    facet_names = list(facet_est["Facet"].unique()) if "Facet" in facet_est.columns and not facet_est.empty else []
    if not facet_names:
        return None
    max_elements_per_facet = int(facet_est.groupby("Facet").size().max()) if facet_names else 0
    threshold_frame = _yardstick_threshold_frame(step_tbl, rating_min=rating_min)
    include_thresholds = not threshold_frame.empty
    yardstick_map = make_yardstick_export_table(
        person_tbl,
        facet_est,
        step_tbl,
        rating_min=rating_min,
        plot_label_mode=plot_label_mode,
    )

    y_all = list(person_est)
    if not facet_est.empty:
        y_all.extend(facet_est["Estimate"].tolist())
    if include_thresholds:
        y_all.extend(threshold_frame["Estimate"].tolist())
    margin = 0.5
    y_lo, y_hi = min(y_all) - margin, max(y_all) + margin

    col_titles = ["Measr / Persons"] + [str(name) for name in facet_names]
    if include_thresholds:
        col_titles.append("Thresholds")
    n_cols = len(col_titles)
    col_widths = [0.22] + [0.18] * len(facet_names) + ([0.16] if include_thresholds else [])
    total_width = sum(col_widths)
    col_widths = [value / total_width for value in col_widths]
    fig = make_subplots(
        rows=1,
        cols=n_cols,
        shared_yaxes=True,
        subplot_titles=col_titles,
        column_widths=col_widths,
        horizontal_spacing=0.015,
    )
    tick_values = list(range(int(np.floor(y_lo)), int(np.ceil(y_hi)) + 1))
    text_font_size = 10
    if max_elements_per_facet > 35:
        text_font_size = 8
    elif max_elements_per_facet > 18:
        text_font_size = 9

    def _add_yardstick_ruler(col_idx: int) -> None:
        fig.add_trace(
            go.Scatter(
                x=[0.06, 0.06],
                y=[y_lo, y_hi],
                mode="lines",
                line=dict(color="#111827", width=1.0),
                hoverinfo="skip",
                showlegend=False,
            ),
            row=1,
            col=col_idx,
        )
        if tick_values:
            tick_x: list[float | None] = []
            tick_y: list[float | None] = []
            for tick in tick_values:
                tick_x.extend([0.02, 0.10, None])
                tick_y.extend([float(tick), float(tick), None])
            fig.add_trace(
                go.Scatter(
                    x=tick_x,
                    y=tick_y,
                    mode="lines",
                    line=dict(color="#111827", width=0.7),
                    hoverinfo="skip",
                    showlegend=False,
                ),
                row=1,
                col=col_idx,
            )

    # Column 1: Person histogram (horizontal)
    bins_arr = np.linspace(y_lo, y_hi, max(15, int(len(person_est) ** 0.5)))
    counts, bin_edges = np.histogram(person_est, bins=bins_arr)
    bin_centers = 0.5 * (bin_edges[:-1] + bin_edges[1:])
    fig.add_trace(go.Bar(y=bin_centers, x=counts, orientation="h",
                         marker_color="#b0b0b0", showlegend=False,
                         hovertemplate="n=%{customdata}<br>Logit=%{y:.2f}",
                         customdata=counts), row=1, col=1)
    fig.update_xaxes(title_text="n", autorange="reversed", row=1, col=1)
    fig.update_yaxes(title_text="Logit scale", range=[y_lo, y_hi], dtick=1, row=1, col=1)

    # Facet columns
    for i, fname in enumerate(facet_names):
        col_idx = i + 2
        sub_map = yardstick_map[
            (yardstick_map["Role"] == "FacetElement")
            & (yardstick_map["Facet"].astype(str) == str(fname))
        ].copy() if not yardstick_map.empty else pd.DataFrame()
        _add_yardstick_ruler(col_idx)
        if not sub_map.empty:
            full_labels = sub_map["PlotLabelFull"].astype(str).tolist()
            display_labels = sub_map["DisplayLabel"].astype(str).tolist()
            text_x = (0.14 + pd.to_numeric(sub_map["TextLane"], errors="coerce").fillna(0).astype(float) * 0.14).tolist()
            text_y = pd.to_numeric(sub_map["PlotY"], errors="coerce").tolist()
            visible_text = show_direct_labels and any(label.strip() for label in display_labels)
            fig.add_trace(go.Scatter(
                x=text_x, y=text_y,
                mode="text" if visible_text else "markers",
                marker=dict(size=8, color="#111827", symbol="line-ns"),
                text=display_labels if visible_text else None,
                textposition="middle right", textfont=dict(size=text_font_size, color="#111827"),
                cliponaxis=False,
                showlegend=False,
                customdata=np.column_stack([
                    full_labels,
                    np.repeat(fname, len(sub_map)),
                    pd.to_numeric(sub_map["Estimate"], errors="coerce").to_numpy(dtype=float),
                    sub_map["PlotLabelID"].astype(str).to_numpy(),
                ]),
                hovertemplate="%{customdata[1]} %{customdata[3]}: %{customdata[0]}<br>Logit=%{customdata[2]:.2f}<extra></extra>",
            ), row=1, col=col_idx)
        fig.update_xaxes(range=[0, 1], showticklabels=False, showline=True, linecolor="#d1d5db", mirror=True, row=1, col=col_idx)
        fig.update_yaxes(range=[y_lo, y_hi], dtick=1, showgrid=True, gridcolor="#ececec", zeroline=True, zerolinecolor="#666666", row=1, col=col_idx)

    if include_thresholds:
        col_idx = n_cols
        _add_yardstick_ruler(col_idx)
        threshold_map = yardstick_map[yardstick_map["Role"] == "Threshold"].copy()
        threshold_labels = threshold_map["DisplayLabel"].astype(str).tolist() if not threshold_map.empty else []
        threshold_full_labels = threshold_map["PlotLabelFull"].astype(str).tolist() if not threshold_map.empty else []
        threshold_ids = threshold_map["PlotLabelID"].astype(str).tolist() if not threshold_map.empty else []
        threshold_x = (0.24 + pd.to_numeric(threshold_map["TextLane"], errors="coerce").fillna(0).astype(float) * 0.14).tolist() if not threshold_map.empty else []
        threshold_y = pd.to_numeric(threshold_map["PlotY"], errors="coerce").tolist() if not threshold_map.empty else []
        line_x: list[float | None] = []
        line_y: list[float | None] = []
        line_custom: list[list[object] | None] = []
        for label, label_id, estimate in zip(threshold_full_labels, threshold_ids, threshold_map["Estimate"].tolist() if not threshold_map.empty else []):
            line_x.extend([0.08, 0.20, None])
            line_y.extend([float(estimate), float(estimate), None])
            line_custom.extend([[label, label_id, float(estimate)], [label, label_id, float(estimate)], [None, None, np.nan]])
        fig.add_trace(
            go.Scatter(
                x=line_x,
                y=line_y,
                mode="lines",
                line=dict(color="#8c4a14", width=1.4),
                name="Threshold boundary lines",
                customdata=line_custom,
                hovertemplate="Threshold %{customdata[1]}: %{customdata[0]}<br>Exact logit=%{customdata[2]:.2f}<extra></extra>",
                showlegend=False,
            ),
            row=1,
            col=col_idx,
        )
        visible_threshold_text = show_direct_labels and any(label.strip() for label in threshold_labels)
        fig.add_trace(
            go.Scatter(
                x=threshold_x,
                y=threshold_y,
                mode="text" if visible_threshold_text else "markers",
                marker=dict(size=8, color="#d95f02", symbol="line-ew"),
                text=threshold_labels if visible_threshold_text else None,
                textposition="middle right",
                textfont=dict(size=text_font_size, color="#6b2d00"),
                cliponaxis=False,
                customdata=np.column_stack([
                    threshold_full_labels,
                    np.repeat("Threshold", len(threshold_map)),
                    pd.to_numeric(threshold_map["Estimate"], errors="coerce").to_numpy(dtype=float) if not threshold_map.empty else np.array([], dtype=float),
                    np.array(threshold_ids, dtype=object),
                ]),
                hovertemplate="%{customdata[1]} %{customdata[3]}: %{customdata[0]}<br>Logit=%{customdata[2]:.2f}<extra></extra>",
                showlegend=False,
            ),
            row=1,
            col=col_idx,
        )
        fig.update_xaxes(range=[0, 1], showticklabels=False, showline=True, linecolor="#d1d5db", mirror=True, row=1, col=col_idx)
        fig.update_yaxes(range=[y_lo, y_hi], dtick=1, showgrid=True, gridcolor="#ececec", row=1, col=col_idx)

    fig.update_layout(
        title="Yardstick (FACETS-style text map)",
        height=max(620, 30 * max(max_elements_per_facet, len(threshold_frame)) + 240 if show_direct_labels else 620),
        template="plotly_white",
        showlegend=False,
        margin=dict(l=90, r=50, t=90, b=80),
        hovermode="closest",
        font=dict(size=12),
        plot_bgcolor="white",
    )
    return fig


