def resolve_analysis_depth_settings(
    analysis_depth: str,
    est_method: str,
    custom: dict | None = None,
) -> dict:
    """Resolve performance preset settings used by the sidebar and self-tests."""
    is_mml = est_method == "MML"
    if analysis_depth == "Fast preview":
        settings = {
            "compute_residual_pca": False,
            "compute_strict_marginal": False,
            "strict_marginal_pairwise": False,
            "strict_marginal_max_pair_cells": 400,
            "compute_plausible_values": False,
            "n_plausible_values": 0,
            "plausible_seed": 20260411,
            "bias_mode": "Skip",
            "render_interactive_plots": False,
            "generate_figure_exports": False,
            "compute_eb_shrinkage": False,
        }
    elif analysis_depth == "Full publication":
        settings = {
            "compute_residual_pca": True,
            "compute_strict_marginal": is_mml,
            "strict_marginal_pairwise": is_mml,
            "strict_marginal_max_pair_cells": 800,
            "compute_plausible_values": is_mml,
            "n_plausible_values": 10 if is_mml else 0,
            "plausible_seed": 20260411,
            "bias_mode": "All facet pairs",
            "render_interactive_plots": True,
            "generate_figure_exports": True,
            "compute_eb_shrinkage": True,
        }
    elif analysis_depth == "Custom":
        settings = {
            "compute_residual_pca": True,
            "compute_strict_marginal": is_mml,
            "strict_marginal_pairwise": False,
            "strict_marginal_max_pair_cells": 400,
            "compute_plausible_values": is_mml,
            "n_plausible_values": 5 if is_mml else 0,
            "plausible_seed": 20260411,
            "bias_mode": "Selected pair",
            "render_interactive_plots": True,
            "generate_figure_exports": False,
            "compute_eb_shrinkage": True,
        }
        if custom:
            settings.update(custom)
    else:
        settings = {
            "compute_residual_pca": True,
            "compute_strict_marginal": False,
            "strict_marginal_pairwise": False,
            "strict_marginal_max_pair_cells": 400,
            "compute_plausible_values": False,
            "n_plausible_values": 0,
            "plausible_seed": 20260411,
            "bias_mode": "Selected pair",
            "render_interactive_plots": True,
            "generate_figure_exports": False,
            "compute_eb_shrinkage": False,
        }

    settings["compute_residual_pca"] = bool(settings.get("compute_residual_pca", True))
    settings["compute_strict_marginal"] = bool(settings.get("compute_strict_marginal", False))
    settings["strict_marginal_pairwise"] = bool(settings.get("strict_marginal_pairwise", False))
    settings["strict_marginal_max_pair_cells"] = int(settings.get("strict_marginal_max_pair_cells", 400))
    settings["compute_plausible_values"] = bool(settings.get("compute_plausible_values", False))
    settings["n_plausible_values"] = int(settings.get("n_plausible_values", 0) or 0)
    settings["plausible_seed"] = int(settings.get("plausible_seed", 20260411) or 20260411)
    settings["bias_mode"] = str(settings.get("bias_mode", "Selected pair"))
    settings["render_interactive_plots"] = bool(settings.get("render_interactive_plots", True))
    settings["generate_figure_exports"] = bool(settings.get("generate_figure_exports", False))
    settings["compute_eb_shrinkage"] = bool(settings.get("compute_eb_shrinkage", False))

    if not is_mml:
        settings["compute_strict_marginal"] = False
        settings["strict_marginal_pairwise"] = False
        settings["compute_plausible_values"] = False
        settings["n_plausible_values"] = 0
    if not settings["compute_strict_marginal"]:
        settings["strict_marginal_pairwise"] = False
    if not settings["compute_plausible_values"]:
        settings["n_plausible_values"] = 0
    return settings


def analysis_depth_sidebar_summary(settings: dict) -> str:
    """Compact read-only summary of what the selected performance preset runs."""
    enabled: list[str] = []
    skipped: list[str] = []
    feature_map = [
        ("compute_residual_pca", "residual PCA"),
        ("compute_strict_marginal", "strict marginal"),
        ("strict_marginal_pairwise", "pairwise marginal"),
        ("compute_plausible_values", "plausible values"),
        ("compute_eb_shrinkage", "EB shrinkage advisory"),
        ("render_interactive_plots", "interactive plots"),
        ("generate_figure_exports", "figure export bundle"),
    ]
    for key, label in feature_map:
        (enabled if bool(settings.get(key)) else skipped).append(label)
    bias_mode = str(settings.get("bias_mode", "Skip"))
    if bias_mode != "Skip":
        enabled.append(f"bias scan: {bias_mode}")
    else:
        skipped.append("bias scan")
    return (
        f"Runs: {', '.join(enabled) if enabled else 'core estimation only'}. "
        f"Skips: {', '.join(skipped) if skipped else 'none'}."
    )


def _allow_large_hosted_run_override() -> bool:
    return _preflight.allow_large_hosted_run_override()


def build_estimation_resource_preflight(
    *,
    data: pd.DataFrame,
    person_col: str,
    score_col: str,
    facet_cols: list[str],
    model_type: str,
    est_method: str,
    maxit: int,
    quad_points: int,
    bias_mode: str,
    bias_pairs_available: list[tuple[str, str]],
    selected_bias_pair: tuple[str, str] | None,
    compute_strict_marginal: bool,
    strict_marginal_pairwise: bool,
    strict_marginal_max_pair_cells: int,
    generate_figure_exports: bool,
) -> dict:
    """Compatibility wrapper for hosted-runtime resource preflight."""
    return _preflight.build_estimation_resource_preflight(
        data=data,
        person_col=person_col,
        score_col=score_col,
        facet_cols=facet_cols,
        model_type=model_type,
        est_method=est_method,
        maxit=maxit,
        quad_points=quad_points,
        bias_mode=bias_mode,
        bias_pairs_available=bias_pairs_available,
        selected_bias_pair=selected_bias_pair,
        compute_strict_marginal=compute_strict_marginal,
        strict_marginal_pairwise=strict_marginal_pairwise,
        strict_marginal_max_pair_cells=strict_marginal_max_pair_cells,
        generate_figure_exports=generate_figure_exports,
        hosted_max_obs=ESTIMATION_HOSTED_MAX_OBS,
        hosted_max_parameters=ESTIMATION_HOSTED_MAX_PARAMETERS,
        hosted_max_mml_evals=ESTIMATION_HOSTED_MAX_MML_EVALS,
        hosted_max_bias_cells=ESTIMATION_HOSTED_MAX_BIAS_CELLS,
    )


def estimation_resource_preflight_status(preflight: dict) -> str:
    return _preflight.estimation_resource_preflight_status(preflight)


def should_render_estimation_resource_preflight(preflight: dict) -> bool:
    """Avoid alert fatigue: only surface resource budget details when action is needed."""
    return _preflight.should_render_estimation_resource_preflight(preflight)


def render_estimation_resource_preflight(preflight: dict) -> None:
    rows = preflight.get("rows", []) if isinstance(preflight, dict) else []
    if not rows:
        return
    frame = pd.DataFrame(rows)
    status = estimation_resource_preflight_status(preflight)
    if status == "OK":
        st.caption(t("resource_preflight.ok_caption"))
        return
    if status == "Block":
        st.error(
            t("resource_preflight.blocked_error")
        )
    else:
        st.warning(
            t("resource_preflight.review_warning")
        )
    with st.expander(t("resource_preflight.details_expander"), expanded=(status == "Block")):
        st.dataframe(frame, width="stretch", hide_index=True)


_RUN_HISTORY_KEY = "_facets_mode_run_history"
# Full restorable snapshots are opt-in because they duplicate row-level
# outputs and can retain identifiable learner/rater data in session memory.
_RUN_HISTORY_STORE_SNAPSHOTS_KEY = "_run_history_store_full_snapshots"
# Keep compact run metadata for the last few analyses. When users opt into
# full snapshots, the same cap also bounds the duplicated result bundles.
_RUN_HISTORY_MAX = 5

# Config-import whitelist (v0.2.6-beta extraction): sidebar-replayable
# keys that a `mfrm_config.json` import panel shows back to the user.
# Extracted to a module-level constant so `_self_test_config_json_import_whitelist`
# can pin the key set and catch accidental drift (adding/removing a
# setting here without updating the exporter or docs).
_CONFIG_JSON_IMPORT_WHITELIST: frozenset[str] = frozenset({
    "model_type", "method", "analysis_depth", "workflow_mode",
    "bias_mode", "selected_bias_pair",
    "render_interactive_plots", "generate_figure_exports",
    "rating_min", "rating_max", "keep_original",
    "noncenter_facet", "dummy_facets", "positive_facets",
    "maxit", "reltol", "anchor_policy",
    "population_enabled", "population_formula",
    "facet_regularization_ui_mode", "facet_regularization_specs",
    "compute_residual_pca", "compute_strict_marginal",
    "compute_plausible_values", "n_plausible_values",
    "visualization_preferences",
})


def _run_history_extract_summary(output: dict) -> tuple[bool, int, str, str]:
    """Pull Converged / Iterations / Model / Method from the output's summary row."""
    result = output.get("result", {}) if isinstance(output, dict) else {}
    summary = result.get("summary") if isinstance(result, dict) else None
    converged = False
    iters = 0
    model = str(output.get("model_type") or "?") if isinstance(output, dict) else "?"
    method = ""
    if isinstance(summary, pd.DataFrame) and not summary.empty:
        row = summary.iloc[0]
        converged = bool(row.get("Converged", False))
        try:
            iters = int(row.get("Iterations", 0))
        except (TypeError, ValueError):
            iters = 0
        if "Method" in summary.columns:
            method = str(row.get("Method", ""))
        if "Model" in summary.columns and (not model or model == "?"):
            model = str(row.get("Model", model))
    if not method and isinstance(output, dict):
        method = str(output.get("_est_method", ""))
    return converged, iters, model, method


def _history_entry_has_snapshot(entry: dict) -> bool:
    return bool(isinstance(entry, dict) and isinstance(entry.get("output_snapshot"), dict) and entry.get("output_snapshot"))


def record_run_in_history(*, output: dict, elapsed_sec: float) -> dict:
    """Push a compact metadata entry for this run onto the session history stack.

    Keeps at most _RUN_HISTORY_MAX entries, dropping oldest first. Full
    result snapshots are stored only when the user opts in, because those
    snapshots duplicate row-level outputs and identifiers in Streamlit
    session state. Returns the entry just recorded.
    """
    import copy as _copy
    import datetime as _dt

    converged, iters, model, method = _run_history_extract_summary(output)
    facet_cols = output.get("facet_cols", []) if isinstance(output, dict) else []
    n_facets = len(facet_cols) if isinstance(facet_cols, (list, tuple)) else 0
    prep = (output.get("result", {}) or {}).get("prep", {}) if isinstance(output, dict) else {}
    try:
        n_obs = int(prep.get("n_obs", 0))
    except (TypeError, ValueError):
        n_obs = 0
    try:
        n_persons = int(prep.get("n_person", 0))
    except (TypeError, ValueError):
        n_persons = 0
    like_row = extract_run_likelihood_row(output)
    result_cfg = (output.get("result", {}) or {}).get("config", {}) if isinstance(output, dict) else {}
    reg_label = "On" if isinstance(result_cfg, dict) and result_cfg.get("facet_regularization_enabled") else "Off"
    store_snapshot = bool(st.session_state.get(_RUN_HISTORY_STORE_SNAPSHOTS_KEY, False))

    entry = {
        "run_id": f"run-{_dt.datetime.now().strftime('%Y%m%d-%H%M%S-%f')}",
        "timestamp": _dt.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "model": model,
        "method": method,
        "n_obs": n_obs,
        "n_persons": n_persons,
        "n_facets": n_facets,
        "converged": converged,
        "iterations": iters,
        "elapsed_sec": float(elapsed_sec or 0.0),
        "regularization": reg_label,
        "loglik": like_row.get("LogLik", np.nan),
        "deviance": like_row.get("Deviance", np.nan),
        "aic": like_row.get("AIC", np.nan),
        "bic": like_row.get("BIC", np.nan),
        "k_params": like_row.get("KParams", np.nan),
        "snapshot_available": bool(store_snapshot and isinstance(output, dict)),
        "output_snapshot": _copy.deepcopy(output) if store_snapshot and isinstance(output, dict) else {},
    }
    history = list(st.session_state.get(_RUN_HISTORY_KEY, []))
    history.append(entry)
    if len(history) > _RUN_HISTORY_MAX:
        history = history[-_RUN_HISTORY_MAX:]
    st.session_state[_RUN_HISTORY_KEY] = history
    return entry


def get_run_history() -> list[dict]:
    """Return the current run history list (may be empty)."""
    return list(st.session_state.get(_RUN_HISTORY_KEY, []))


def restore_run_from_history(run_id: str) -> bool:
    """Restore a past run's output snapshot into the live facets_mode_output."""
    import copy as _copy
    for entry in get_run_history():
        if entry.get("run_id") == run_id and _history_entry_has_snapshot(entry):
            st.session_state["facets_mode_output"] = _copy.deepcopy(entry["output_snapshot"])
            st.session_state["_facets_mode_restored_snapshot"] = {
                "run_id": entry.get("run_id"),
                "timestamp": entry.get("timestamp"),
                "model": entry.get("model"),
                "method": entry.get("method"),
            }
            return True
    return False


def clear_run_history() -> None:
    """Wipe all recorded runs."""
    if _RUN_HISTORY_KEY in st.session_state:
        del st.session_state[_RUN_HISTORY_KEY]


def render_run_history_panel() -> None:
    """Collapsible panel showing recent runs with Restore buttons."""
    history = get_run_history()
    if not history:
        return

    with st.expander(
        f"Run history ({len(history)} run{'s' if len(history) > 1 else ''})",
        expanded=False,
    ):
        st.caption(
            "Recent analyses in this session. By default this stores compact metadata only "
            "to avoid duplicating private row-level outputs in memory."
        )
        st.checkbox(
            "Store restorable full snapshots for future runs",
            value=bool(st.session_state.get(_RUN_HISTORY_STORE_SNAPSHOTS_KEY, False)),
            key=_RUN_HISTORY_STORE_SNAPSHOTS_KEY,
            help=(
                "Opt in only for local, controlled sessions. Full snapshots enable Restore "
                "and Compare, but duplicate result tables and identifiers in Streamlit session state."
            ),
        )
        # Compact table view (newest first)
        display_rows = []
        for h in reversed(history):
            display_rows.append({
                "timestamp": h["timestamp"],
                "model": h["model"],
                "method": h["method"],
                "n_obs": h["n_obs"],
                "n_persons": h["n_persons"],
                "n_facets": h["n_facets"],
                "converged": h["converged"],
                "iterations": h["iterations"],
                "regularization": h.get("regularization", "Off"),
                "LogLik": h.get("loglik", np.nan),
                "AIC": h.get("aic", np.nan),
                "BIC": h.get("bic", np.nan),
                "restorable": _history_entry_has_snapshot(h),
                "elapsed_sec": round(h["elapsed_sec"], 2),
            })
        compact_history = pd.DataFrame(display_rows)
        if not compact_history.empty:
            for col in ["LogLik", "AIC", "BIC"]:
                if col in compact_history.columns:
                    compact_history[col] = pd.to_numeric(compact_history[col], errors="coerce").round(3)
        st.dataframe(compact_history, width="stretch", hide_index=True)

        likelihood_history = build_run_history_likelihood_table(history)
        if isinstance(likelihood_history, pd.DataFrame) and not likelihood_history.empty:
            with st.expander("Maximized likelihood / information criteria across run history", expanded=False):
                st.caption(
                    "Use these descriptively unless runs share the same response rows, score map, "
                    "missing-data rule, likelihood definition, and identification constraints. "
                    "AIC/BIC are lower-is-better; LogLik is higher-is-better."
                )
                display_cols = [
                    c for c in [
                        "Timestamp", "Model", "Method", "N", "KParams",
                        "Regularization", "LogLik", "Deviance", "RegularizationPenalty",
                        "PenalizedObjective", "AIC", "BIC",
                        "DeltaAIC", "DeltaBIC", "DeltaDeviance",
                        "LogLikPerObs", "AICPerObs", "BICPerObs", "ComparableIC",
                    ] if c in likelihood_history.columns
                ]
                st.dataframe(likelihood_history[display_cols].round(4), width="stretch", hide_index=True)
                desc = build_likelihood_descriptives(likelihood_history)
                if isinstance(desc, pd.DataFrame) and not desc.empty:
                    st.markdown("**Descriptive statistics across stored runs**")
                    st.dataframe(desc.round(4), width="stretch", hide_index=True)
                st.download_button(
                    "Download run-history likelihood criteria (CSV)",
                    data=to_csv_bytes(likelihood_history),
                    file_name="mfrm_run_history_likelihood_criteria.csv",
                    mime="text/csv",
                    key="dl_run_history_likelihood_criteria",
                )

        # Per-entry Restore buttons
        for entry in reversed(history):
            cols = st.columns([5, 1])
            has_snapshot = _history_entry_has_snapshot(entry)
            label = (
                f"**{entry['timestamp']}** — {entry['model']} / {entry['method']} — "
                f"{'converged' if entry['converged'] else 'not converged'}"
                f" — {entry['elapsed_sec']:.1f}s"
                f"{'' if has_snapshot else ' — metadata only'}"
            )
            cols[0].markdown(label)
            if cols[1].button(
                "Restore",
                key=f"restore_{entry['run_id']}",
                use_container_width=True,
                disabled=not has_snapshot,
                help=(
                    "Load this run's results into the current view."
                    if has_snapshot else
                    "This entry has compact metadata only. Enable full snapshots before a future run to restore it."
                ),
            ):
                if restore_run_from_history(entry["run_id"]):
                    st.success(f"Restored run from {entry['timestamp']}")
                    st.rerun()

        st.markdown("---")
        # Two-step confirmation for Clear history — a single stray click
        # used to wipe all snapshots permanently with no recovery path.
        if st.session_state.get("_run_history_clear_confirm", False):
            st.warning(
                f"Delete all **{len(history)}** snapshots? "
                "This cannot be undone."
            )
            confirm_cols = st.columns([1, 1, 3])
            if confirm_cols[0].button(
                "Yes, delete all",
                key="run_history_clear_yes",
                type="primary",
                use_container_width=True,
            ):
                clear_run_history()
                st.session_state["_run_history_clear_confirm"] = False
                st.rerun()
            if confirm_cols[1].button(
                "Cancel",
                key="run_history_clear_no",
                use_container_width=True,
            ):
                st.session_state["_run_history_clear_confirm"] = False
                st.rerun()
        else:
            if st.button(
                "Clear history",
                key="run_history_clear",
                help="Remove all stored snapshots. Requires confirmation.",
            ):
                st.session_state["_run_history_clear_confirm"] = True
                st.rerun()


def _comparison_extract_label(snapshot: dict) -> str:
    """Build a short 'MODEL / METHOD' label from a run snapshot."""
    model = str(snapshot.get("model_type", "") or "")
    method = str(snapshot.get("_est_method", "") or "")
    summary = (snapshot.get("result") or {}).get("summary")
    if isinstance(summary, pd.DataFrame) and not summary.empty:
        row = summary.iloc[0]
        if "Model" in summary.columns and not model:
            model = str(row.get("Model", model))
        if "Method" in summary.columns and not method:
            method = str(row.get("Method", method))
    return f"{model or '?'} / {method or '?'}"


def _comparison_extract_conv(snapshot: dict) -> tuple[bool, int]:
    summary = (snapshot.get("result") or {}).get("summary")
    if isinstance(summary, pd.DataFrame) and not summary.empty:
        row = summary.iloc[0]
        try:
            iters = int(row.get("Iterations", 0))
        except (TypeError, ValueError):
            iters = 0
        return bool(row.get("Converged", False)), iters
    return False, 0


def _comparison_measures_diff(snap_a: dict, snap_b: dict) -> dict | None:
    """Merge the two runs' measures on (Facet, Level) and compute corr + RMSE."""
    da = (snap_a.get("diagnostics") or {}).get("measures")
    db = (snap_b.get("diagnostics") or {}).get("measures")
    if not isinstance(da, pd.DataFrame) or not isinstance(db, pd.DataFrame):
        return None
    if da.empty or db.empty:
        return None
    req = {"Facet", "Level", "Estimate"}
    if not req.issubset(da.columns) or not req.issubset(db.columns):
        return None
    left = da[["Facet", "Level", "Estimate"]].rename(columns={"Estimate": "Estimate_A"})
    right = db[["Facet", "Level", "Estimate"]].rename(columns={"Estimate": "Estimate_B"})
    merged = left.merge(right, on=["Facet", "Level"], how="inner")
    if merged.empty:
        return {"merged": merged, "correlation": float("nan"), "rmse": float("nan"), "n_overlap": 0}
    ea = pd.to_numeric(merged["Estimate_A"], errors="coerce")
    eb = pd.to_numeric(merged["Estimate_B"], errors="coerce")
    valid = ea.notna() & eb.notna()
    n_valid = int(valid.sum())
    corr = float(np.corrcoef(ea[valid], eb[valid])[0, 1]) if n_valid >= 2 else float("nan")
    rmse = float(np.sqrt(np.mean((ea[valid] - eb[valid]) ** 2))) if n_valid else float("nan")
    merged["diff"] = eb - ea
    return {"merged": merged, "correlation": corr, "rmse": rmse, "n_overlap": n_valid}


def _comparison_reliability_diff(snap_a: dict, snap_b: dict) -> pd.DataFrame | None:
    ra = (snap_a.get("diagnostics") or {}).get("reliability")
    rb = (snap_b.get("diagnostics") or {}).get("reliability")
    if not isinstance(ra, pd.DataFrame) or not isinstance(rb, pd.DataFrame):
        return None
    if ra.empty or rb.empty or "Facet" not in ra.columns or "Facet" not in rb.columns:
        return None
    keep = ["Facet", "Separation", "Reliability", "Strata"]
    la = ra[[c for c in keep if c in ra.columns]].rename(columns={
        "Separation": "Separation_A", "Reliability": "Reliability_A", "Strata": "Strata_A",
    })
    lb = rb[[c for c in keep if c in rb.columns]].rename(columns={
        "Separation": "Separation_B", "Reliability": "Reliability_B", "Strata": "Strata_B",
    })
    return la.merge(lb, on="Facet", how="outer")


def _comparison_data_alignment(snap_a: dict, snap_b: dict) -> tuple[bool, list[str]]:
    """Flag whether two run snapshots are a like-for-like comparison.

    Element measures and likelihood / information-criteria values are only
    comparable when both runs scored the same response rows with the same
    column mapping. Returns ``(aligned, reasons)`` where ``reasons`` lists the
    differing inputs that make a raw agreement number misleading.
    """
    def _get(key):
        a = snap_a.get(key) if isinstance(snap_a, dict) else None
        b = snap_b.get(key) if isinstance(snap_b, dict) else None
        return a, b

    reasons: list[str] = []
    fa, fb = _get("_input_data_fingerprint")
    if fa is not None and fb is not None and fa != fb:
        reasons.append("different input data")
    pa, pb = _get("person_col")
    if pa != pb:
        reasons.append("different person column")
    sa, sb = _get("score_col")
    if sa != sb:
        reasons.append("different score column")
    ca, cb = _get("facet_cols")
    if sorted(map(str, ca or [])) != sorted(map(str, cb or [])):
        reasons.append("different facet set")
    aa, ab = _get("_anchor_source_fingerprint")
    if aa is not None and ab is not None and aa != ab:
        reasons.append("different anchor inputs")
    return (len(reasons) == 0, reasons)


def render_comparison_panel(snap_a: dict, snap_b: dict) -> None:
    """Render a side-by-side comparison between two run snapshots."""
    label_a = _comparison_extract_label(snap_a)
    label_b = _comparison_extract_label(snap_b)
    conv_a, iters_a = _comparison_extract_conv(snap_a)
    conv_b, iters_b = _comparison_extract_conv(snap_b)

    with st.container(border=True):
        st.markdown(f"### Comparison: `{label_a}` vs `{label_b}`")

        data_aligned, mismatch_reasons = _comparison_data_alignment(snap_a, snap_b)
        if not data_aligned:
            st.warning(
                "These runs are not a like-for-like comparison ("
                + ", ".join(mismatch_reasons)
                + "). The element-measure and likelihood / information-criteria "
                "differences below partly reflect those input differences, not just "
                "the estimation settings — read them as descriptive, not as a "
                "method-agreement check."
            )

        cols = st.columns(2)
        cols[0].metric(
            "Convergence",
            "both" if conv_a and conv_b else
            ("A only" if conv_a else ("B only" if conv_b else "neither")),
        )
        cols[1].metric(
            "Iterations",
            f"{iters_a} vs {iters_b}",
            delta=iters_b - iters_a,
            delta_color="inverse",
        )

        likelihood_cmp = build_run_history_likelihood_table([
            {"timestamp": "Run A", "output_snapshot": snap_a},
            {"timestamp": "Run B", "output_snapshot": snap_b},
        ])
        if isinstance(likelihood_cmp, pd.DataFrame) and not likelihood_cmp.empty:
            metric_cols = [
                c for c in [
                        "Timestamp", "Model", "Method", "N", "KParams",
                        "Regularization", "LogLik", "Deviance", "RegularizationPenalty",
                        "PenalizedObjective", "AIC", "BIC",
                        "DeltaAIC", "DeltaBIC", "DeltaDeviance",
                        "LogLikPerObs", "AICPerObs", "BICPerObs", "ComparableIC",
                    ] if c in likelihood_cmp.columns
                ]
            if any(pd.to_numeric(likelihood_cmp.get(c, pd.Series(dtype=float)), errors="coerce").notna().any()
                   for c in ["LogLik", "AIC", "BIC"]):
                st.markdown("#### Maximized likelihood / information criteria")
                st.caption(
                    "Compare AIC/BIC/LRT-style likelihood quantities only when both runs use the same "
                    "response rows, score map, missing-data rule, likelihood definition, constraints, "
                    "and regularization settings."
                )
                st.dataframe(likelihood_cmp[metric_cols].round(4), width="stretch", hide_index=True)

        measures = _comparison_measures_diff(snap_a, snap_b)
        if measures is not None:
            st.markdown("#### Element-level measure agreement")
            if measures["n_overlap"] == 0:
                st.info(
                    "No overlapping (Facet, Level) elements between the two runs — "
                    "measures cannot be compared."
                )
            else:
                mcols = st.columns(3)
                mcols[0].metric("Overlap (elements)", measures["n_overlap"])
                mcols[1].metric(
                    "Pearson r",
                    f"{measures['correlation']:.4f}" if pd.notna(measures["correlation"]) else "n/a",
                )
                mcols[2].metric(
                    "RMSE",
                    f"{measures['rmse']:.3f}" if pd.notna(measures["rmse"]) else "n/a",
                )
                # Scatter (45° reference)
                try:
                    fig = go.Figure()
                    for facet, grp in measures["merged"].groupby("Facet"):
                        fig.add_trace(go.Scatter(
                            x=grp["Estimate_A"], y=grp["Estimate_B"],
                            mode="markers", name=str(facet),
                            text=grp["Level"], hovertemplate="<b>%{text}</b><br>A=%{x:.3f}<br>B=%{y:.3f}<extra></extra>",
                        ))
                    est_min = float(min(measures["merged"]["Estimate_A"].min(),
                                        measures["merged"]["Estimate_B"].min()))
                    est_max = float(max(measures["merged"]["Estimate_A"].max(),
                                        measures["merged"]["Estimate_B"].max()))
                    fig.add_shape(type="line", x0=est_min, y0=est_min, x1=est_max, y1=est_max,
                                  line=dict(color="gray", dash="dash", width=1))
                    fig.update_layout(
                        xaxis_title=f"Estimate — {label_a}",
                        yaxis_title=f"Estimate — {label_b}",
                        title="Element measures (dashed line = perfect agreement)",
                        height=420, template="plotly_white",
                    )
                    st.plotly_chart(fig, width="stretch")
                except Exception:
                    st.dataframe(measures["merged"].head(20), width="stretch", hide_index=True)

                with st.expander("Top 10 elements by |diff|", expanded=False):
                    sorted_diff = measures["merged"].reindex(
                        measures["merged"]["diff"].abs().sort_values(ascending=False).index
                    ).head(10)
                    st.dataframe(sorted_diff, width="stretch", hide_index=True)

                # Interpretation
                corr = measures["correlation"]
                if pd.notna(corr):
                    if not data_aligned:
                        st.caption(
                            f"Observed Pearson r = {corr:.3f}. Because the two runs differ in "
                            "input data or column mapping, this is not a method-agreement "
                            "statistic — interpret it only alongside the mismatch warning above."
                        )
                    elif corr >= 0.98:
                        st.success(f"Near-perfect agreement (r = {corr:.3f}). Methods produce effectively identical measures.")
                    elif corr >= 0.90:
                        st.info(f"Strong agreement (r = {corr:.3f}). Differences are minor; either method is defensible.")
                    elif corr >= 0.70:
                        st.warning(f"Moderate agreement (r = {corr:.3f}). Inspect the scatter for outlier elements.")
                    else:
                        st.error(f"Weak agreement (r = {corr:.3f}). Methods disagree substantially; check assumptions.")

        reliability = _comparison_reliability_diff(snap_a, snap_b)
        if reliability is not None:
            st.markdown(f"#### {t('report_tables.comparison_reliability_separation_header')}")
            st.dataframe(reliability.round(3), width="stretch", hide_index=True)


def render_comparison_selector() -> None:
    """Expander that lets the user pick two runs from history and compare."""
    history = [h for h in get_run_history() if _history_entry_has_snapshot(h)]
    if len(history) < 2:
        return
    with st.expander("Compare two runs", expanded=False):
        st.caption(
            "Pick two analyses from your run history to view a side-by-side "
            "comparison of convergence, element measures, and reliability."
        )
        labels = [
            f"{h['timestamp']} — {h['model']}/{h['method']}"
            + (" — converged" if h["converged"] else " — not converged")
            + f" ({h['iterations']} iter, {h['elapsed_sec']:.1f}s)"
            for h in history
        ]
        cols = st.columns([5, 5, 2])
        idx_a = cols[0].selectbox(
            "Run A",
            options=list(range(len(labels))),
            format_func=lambda i: labels[i],
            index=max(0, len(labels) - 2),
            key="compare_run_a",
        )
        idx_b = cols[1].selectbox(
            "Run B",
            options=list(range(len(labels))),
            format_func=lambda i: labels[i],
            index=len(labels) - 1,
            key="compare_run_b",
        )
        do_compare = cols[2].button(
            "Compare",
            key="compare_trigger",
            use_container_width=True,
            type="primary",
        )
        if do_compare:
            if idx_a == idx_b:
                st.info("Pick two different runs to compare.")
                return
            render_comparison_panel(
                history[idx_a]["output_snapshot"],
                history[idx_b]["output_snapshot"],
            )


# Readiness status prefixes avoid colour-only signalling and keep the UI
# legible in plain-text exports, screenshots, and assistive technologies.
_READINESS_PREFIX: dict[str, str] = {"ok": "[OK] ", "warning": "[CAUTION] ", "issue": "[ISSUE] "}
_READINESS_ICON: dict[str, str] = {"ok": "🟢", "warning": "🟡", "issue": "🔴"}
_READINESS_TEXT_LABEL: dict[str, str] = {"ok": "OK", "warning": "CAUTION", "issue": "ISSUE"}


def _readiness_severity_max(*severities: str) -> str:
    """Combine severities: issue > warning > ok."""
    order = {"ok": 0, "warning": 1, "issue": 2}
    reverse = {v: k for k, v in order.items()}
    return reverse[max(order.get(s, 0) for s in severities)]


def build_readiness_report(
    *,
    data: pd.DataFrame,
    person_col: str,
    score_col: str,
    facet_cols: list[str],
    weight_col: str | None = None,
) -> dict:
    """Build a pre-estimation readiness report from the uploaded data.

    Returns a dict with:
        overall     -- "ok" | "warning" | "issue"
        checks      -- list of {"name", "severity", "headline", "detail"}
        n_issues, n_warnings

    Each check diagnoses one dimension (n_obs, n_persons, score column,
    facet cardinality, facet coverage, column role overlap). The UI
    renders this as a readiness status banner with an expandable detail panel.
    """
    if data is None or (hasattr(data, "empty") and data.empty):
        return {
            "overall": "issue",
            "checks": [{
                "name": "data", "severity": "issue",
                "headline": "No data uploaded",
                "detail": f"Upload {TABLE_FILE_UPLOAD_LABEL}, paste spreadsheet text, or load sample data to run MFRM.",
            }],
            "n_issues": 1, "n_warnings": 0,
        }

    facet_cols = list(facet_cols)
    checks: list[dict] = []

    # Column role overlap check
    seen: dict[str, list[str]] = {}
    for role, col in [("Person", person_col), ("Score", score_col)] + [
        (f"Facet[{i}]", f) for i, f in enumerate(facet_cols)
    ]:
        seen.setdefault(col, []).append(role)
    conflicts = {col: roles for col, roles in seen.items() if len(roles) > 1}
    if conflicts:
        first_col, first_roles = next(iter(conflicts.items()))
        checks.append({
            "name": "column_overlap", "severity": "issue",
            "headline": f"Column `{first_col}` assigned to multiple roles",
            "detail": f"Roles: {', '.join(first_roles)}. Each column must serve exactly one role.",
        })

    # N observations
    n = len(data)
    if n >= 300:
        checks.append({
            "name": "n_observations", "severity": "ok",
            "headline": f"{n:,} observations",
            "detail": "Good sample size for reliable MFRM estimation.",
        })
    elif n >= 100:
        checks.append({
            "name": "n_observations", "severity": "warning",
            "headline": f"{n:,} observations (low)",
            "detail": "MFRM needs ≥100 observations for usable estimates; ≥300 recommended.",
        })
    else:
        checks.append({
            "name": "n_observations", "severity": "issue",
            "headline": f"{n:,} observations (too few)",
            "detail": "Need at least ~30 observations to estimate measures; 100+ preferred.",
        })

    # N persons
    if person_col not in data.columns:
        checks.append({
            "name": "n_persons", "severity": "issue",
            "headline": "Person column missing",
            "detail": f"Column `{person_col}` not found in the data.",
        })
    else:
        np_count = data[person_col].nunique()
        if np_count >= 30:
            checks.append({
                "name": "n_persons", "severity": "ok",
                "headline": f"{np_count} unique persons",
                "detail": "Sufficient person sample for ability estimation.",
            })
        elif np_count >= 10:
            checks.append({
                "name": "n_persons", "severity": "warning",
                "headline": f"{np_count} unique persons (low)",
                "detail": "Person reliability will be weak with <30 persons.",
            })
        else:
            checks.append({
                "name": "n_persons", "severity": "issue",
                "headline": f"{np_count} unique persons (too few)",
                "detail": "Need ≥10 persons; person measures are unstable with fewer.",
            })

    # Score column
    if score_col not in data.columns:
        checks.append({
            "name": "score", "severity": "issue",
            "headline": "Score column missing",
            "detail": f"Column `{score_col}` not found in the data.",
        })
    else:
        scores = pd.to_numeric(data[score_col], errors="coerce")
        n_numeric = int(scores.notna().sum())
        n_total = len(scores)
        if n_numeric == 0:
            checks.append({
                "name": "score", "severity": "issue",
                "headline": "Score column has no numeric values",
                "detail": "All values in the Score column are non-numeric. Check for text labels.",
            })
        else:
            missing_pct = (1 - n_numeric / max(n_total, 1)) * 100
            unique = scores.dropna().unique()
            n_unique = len(unique)
            if missing_pct > 50:
                checks.append({
                    "name": "score", "severity": "issue",
                    "headline": f"Score column is {missing_pct:.0f}% missing",
                    "detail": "Over half of score values are missing or non-numeric.",
                })
            elif n_unique < 2:
                checks.append({
                    "name": "score", "severity": "issue",
                    "headline": f"Score has only {n_unique} unique value",
                    "detail": "MFRM needs at least 2 rating categories.",
                })
            elif n_unique > 15:
                checks.append({
                    "name": "score", "severity": "warning",
                    "headline": f"Score has {n_unique} unique values",
                    "detail": "Typical rating scales have 2–7. Consider whether this is continuous.",
                })
            elif missing_pct > 20:
                checks.append({
                    "name": "score", "severity": "warning",
                    "headline": f"Score is {missing_pct:.0f}% missing",
                    "detail": f"Missing rate is {missing_pct:.0f}% — expect reduced effective sample size.",
                })
            else:
                checks.append({
                    "name": "score", "severity": "ok",
                    "headline": f"Score: {n_unique} categories, {missing_pct:.0f}% missing",
                    "detail": f"Looks well-formed.",
                })

    try:
        audit = build_response_data_audit(
            data,
            person_col=person_col,
            facet_cols=facet_cols,
            score_col=score_col,
            weight_col=weight_col,
        )
        audit_rows = audit.get("rows", pd.DataFrame())
        if isinstance(audit_rows, pd.DataFrame) and not audit_rows.empty:
            included = int(audit_rows.get("IncludedInLikelihood", pd.Series(dtype=bool)).sum())
            excluded = int((~audit_rows.get("IncludedInLikelihood", pd.Series(dtype=bool))).sum())
            errors = int((audit_rows.get("LikelihoodAction", pd.Series(dtype=str)) == "error_before_fit").sum())
            pct_excluded = 100.0 * excluded / max(len(audit_rows), 1)
            if included == 0:
                checks.append({
                    "name": "likelihood_rows", "severity": "issue",
                    "headline": "No rows can enter the likelihood",
                    "detail": "Every input row is missing a required role, has an unusable score, or has non-positive weight.",
                })
            elif errors > 0:
                checks.append({
                    "name": "likelihood_rows", "severity": "issue",
                    "headline": f"{errors:,} row(s) have fractional score values",
                    "detail": "The run stops until fractional scores are recoded to ordered integer categories.",
                })
            elif excluded > 0:
                checks.append({
                    "name": "likelihood_rows", "severity": "warning",
                    "headline": f"{excluded:,} row(s) excluded before likelihood ({pct_excluded:.1f}%)",
                    "detail": (
                        f"{included:,} row(s) will be used. Open the response-data audit to see the exact "
                        "input row numbers and exclusion reasons."
                    ),
                })
            else:
                checks.append({
                    "name": "likelihood_rows", "severity": "ok",
                    "headline": "All rows enter the likelihood",
                    "detail": "No missing selected cells, unusable scores, or non-positive weights were detected.",
                })
    except Exception:  # pragma: no cover - readiness should stay non-blocking
        pass

    # Facet count
    if len(facet_cols) < 2:
        checks.append({
            "name": "n_facets", "severity": "issue",
            "headline": f"{len(facet_cols)} facet(s) selected",
            "detail": "MFRM needs at least 2 facets (e.g., Rater + Task).",
        })
    else:
        checks.append({
            "name": "n_facets", "severity": "ok",
            "headline": f"{len(facet_cols)} facets selected",
            "detail": f"Facets: {', '.join(facet_cols)}",
        })

    # Per-facet level count
    for facet in facet_cols:
        if facet not in data.columns:
            checks.append({
                "name": f"facet:{facet}", "severity": "issue",
                "headline": f"`{facet}` column missing",
                "detail": f"Column `{facet}` not found in the data.",
            })
            continue
        levels = data[facet].nunique()
        if levels < 2:
            # v0.2.14-beta: downgraded from issue → warning. MFRM
            # centers a singleton facet to 0 without error; no
            # severity/difficulty is estimable but the fit itself
            # proceeds. A hard block was overkill for legitimate
            # single-scorer / single-form designs (e.g., binary
            # reading testlets).
            checks.append({
                "name": f"facet:{facet}", "severity": "warning",
                "headline": f"`{facet}` has only {levels} level",
                "detail": (
                    "Singleton facets contribute no estimable "
                    "severity/difficulty — MFRM centers them to 0. "
                    "Remove from facet selection if the column is "
                    "not informative for your research question."
                ),
            })
        elif levels > 100:
            checks.append({
                "name": f"facet:{facet}", "severity": "warning",
                "headline": f"`{facet}` has {levels} levels",
                "detail": (
                    f"High-cardinality facets ({levels}+ levels) slow estimation and "
                    "produce noisy measures. Consider grouping levels."
                ),
            })
        else:
            checks.append({
                "name": f"facet:{facet}", "severity": "ok",
                "headline": f"`{facet}`: {levels} levels",
                "detail": f"OK",
            })

    # Per-person coverage (each person should see ≥2 distinct facet-level combos)
    try:
        if person_col in data.columns and facet_cols and all(f in data.columns for f in facet_cols):
            grouped = data.groupby(person_col)[facet_cols].nunique()
            per_person_combos = grouped.prod(axis=1) if len(facet_cols) > 1 else grouped.iloc[:, 0]
            single_obs_persons = int((per_person_combos <= 1).sum())
            total_persons = int(len(grouped))
            if single_obs_persons == 0:
                checks.append({
                    "name": "coverage", "severity": "ok",
                    "headline": "Every person has ≥2 observations",
                    "detail": "Good coverage across facet levels.",
                })
            else:
                frac = single_obs_persons / max(total_persons, 1)
                if frac > 0.5:
                    checks.append({
                        "name": "coverage", "severity": "issue",
                        "headline": f"{single_obs_persons}/{total_persons} persons have only 1 observation",
                        "detail": (
                            f"{frac:.0%} of persons never see multiple facet-level combinations; "
                            "person measures cannot be estimated precisely."
                        ),
                    })
                else:
                    checks.append({
                        "name": "coverage", "severity": "warning",
                        "headline": f"{single_obs_persons}/{total_persons} persons have only 1 observation",
                        "detail": f"{frac:.0%} of persons have limited coverage — their measures will be imprecise.",
                    })
    except Exception:  # pragma: no cover - defensive
        pass

    # v0.2.9-beta: ingestion-time outlier detection. Appends check
    # entries for zero-variance persons/elements, extreme-frequency
    # outliers, negative scores, and ceiling/floor saturation. All
    # findings piggy-back on the same readiness UI.
    try:
        outlier_checks = detect_data_outliers(
            data, person_col=person_col, score_col=score_col,
            facet_cols=facet_cols,
        )
        checks.extend(outlier_checks)
    except Exception:  # pragma: no cover - outlier detection must not break readiness
        pass

    overall = "ok"
    for c in checks:
        overall = _readiness_severity_max(overall, c["severity"])

    return {
        "overall": overall,
        "checks": checks,
        "n_issues": sum(1 for c in checks if c["severity"] == "issue"),
        "n_warnings": sum(1 for c in checks if c["severity"] == "warning"),
    }


def _input_readiness_priority_check(report: dict) -> dict:
    """Return the highest-priority pre-run readiness check."""
    checks = report.get("checks", []) if isinstance(report, dict) else []
    if not isinstance(checks, list) or not checks:
        return {}
    for severity in ("issue", "warning"):
        for check in checks:
            if isinstance(check, dict) and str(check.get("severity")) == severity:
                return check
    for check in checks:
        if isinstance(check, dict):
            return check
    return {}


def _input_readiness_action_key(check_name: str, severity: str) -> str:
    """Map a readiness check to the localized next action users should take."""
    name = str(check_name or "")
    if severity == "ok":
        return "ready_to_run"
    if name == "data":
        return "load_data"
    if name == "column_overlap":
        return "fix_column_overlap"
    if name == "n_facets":
        return "select_two_facets"
    if name == "n_persons":
        return "fix_person_column"
    if name == "score":
        return "fix_score_column"
    if name == "likelihood_rows":
        return "inspect_likelihood_rows"
    if name == "n_observations":
        return "review_sample_size"
    if name == "coverage":
        return "review_coverage"
    if name.startswith("facet:"):
        return "review_facet_column"
    if name.startswith(("zero_variance", "scores_", "ceiling_", "floor_", "person_")):
        return "review_score_patterns"
    return "review_flagged_check"


def _input_readiness_open_key(action_key: str) -> str:
    """Map the readiness action to the UI surface where the user should look."""
    return {
        "ready_to_run": "run_button",
        "load_data": "data_source",
        "fix_column_overlap": "column_mapping",
        "select_two_facets": "column_mapping",
        "fix_person_column": "column_mapping",
        "fix_score_column": "column_mapping",
        "inspect_likelihood_rows": "response_audit",
        "review_sample_size": "data_source",
        "review_coverage": "data_shape",
        "review_facet_column": "column_mapping",
        "review_score_patterns": "readiness_detail",
        "review_flagged_check": "readiness_detail",
    }.get(action_key, "readiness_detail")


def _input_readiness_guidance_key(check_name: str) -> str:
    """Map a readiness check to stable explanation keys for the detail table."""
    name = str(check_name or "")
    if name in {
        "data",
        "column_overlap",
        "n_observations",
        "n_persons",
        "score",
        "likelihood_rows",
        "n_facets",
        "coverage",
    }:
        return name
    if name.startswith("facet:"):
        return "facet"
    if name == "scores_negative":
        return "score_negative"
    if name.startswith("scores_"):
        return "score_range"
    if name == "zero_variance_persons":
        return "zero_variance_persons"
    if name.startswith("zero_variance_"):
        return "zero_variance_facet"
    if name.startswith("person_"):
        return "person_frequency"
    if name in {"ceiling_saturation", "floor_saturation"}:
        return "score_saturation"
    return "flagged_check"


def build_input_readiness_next_action_table(report: dict) -> pd.DataFrame:
    """Return a one-row pre-run readiness summary from a readiness report."""
    overall = str(report.get("overall", "ok")) if isinstance(report, dict) else "ok"
    priority = _input_readiness_priority_check(report)
    severity = str(priority.get("severity", overall) or overall)
    check_name = str(priority.get("name", "") or "")
    action_key = _input_readiness_action_key(check_name, severity)
    open_key = _input_readiness_open_key(action_key)
    reason = str(priority.get("headline", "") or "").strip()
    if not reason:
        reason = t(f"input_readiness.reason_{severity}", default=t("input_readiness.reason_ok"))

    columns = [
        t("input_readiness.col_status"),
        t("input_readiness.col_next_action"),
        t("input_readiness.col_open"),
        t("input_readiness.col_reason"),
    ]
    return pd.DataFrame([{
        columns[0]: t(f"input_readiness.status_{severity}", default=severity),
        columns[1]: t(f"input_readiness.action_{action_key}"),
        columns[2]: t(f"input_readiness.open_{open_key}"),
        columns[3]: reason,
    }], columns=columns)


def build_input_readiness_detail_table(checks: list[dict]) -> pd.DataFrame:
    """Return all pre-run readiness checks in a guided, severity-first table."""
    columns = [
        t("input_readiness.col_status"),
        t("input_readiness.col_check"),
        t("input_readiness.col_meaning"),
        t("input_readiness.col_impact"),
        t("input_readiness.col_next_action"),
        t("input_readiness.col_open"),
        t("input_readiness.col_technical_detail"),
    ]
    if not isinstance(checks, list) or not checks:
        return pd.DataFrame(columns=columns)

    severity_order = {"issue": 0, "warning": 1, "ok": 2}
    ordered_checks = sorted(
        enumerate(checks),
        key=lambda item: (
            severity_order.get(str(item[1].get("severity", "ok")), 3),
            item[0],
        ),
    )
    rows: list[dict] = []
    for _, check in ordered_checks:
        if not isinstance(check, dict):
            continue
        severity = str(check.get("severity", "ok") or "ok")
        check_name = str(check.get("name", "") or "")
        action_key = _input_readiness_action_key(check_name, severity)
        open_key = _input_readiness_open_key(action_key)
        guidance_key = _input_readiness_guidance_key(check_name)
        icon = _READINESS_ICON.get(severity, "⚪")
        text = _READINESS_TEXT_LABEL.get(severity, severity.upper())
        rows.append({
            columns[0]: f"{icon} [{text}] {t(f'input_readiness.status_{severity}', default=severity)}",
            columns[1]: str(check.get("headline", "") or check_name or "-"),
            columns[2]: t(f"input_readiness.guidance_{guidance_key}_meaning"),
            columns[3]: t(f"input_readiness.guidance_{guidance_key}_impact"),
            columns[4]: t(f"input_readiness.action_{action_key}"),
            columns[5]: t(f"input_readiness.open_{open_key}"),
            columns[6]: str(check.get("detail", "") or "-"),
        })
    return pd.DataFrame(rows, columns=columns)


def detect_data_outliers(
    data: pd.DataFrame,
    *,
    person_col: str,
    score_col: str,
    facet_cols: list[str],
    rating_min: int | float | None = None,
    rating_max: int | float | None = None,
) -> list[dict]:
    """Screen uploaded data for common ingestion-time anomalies.

    Returns a list of readiness-check dicts ({"name", "severity",
    "headline", "detail"}) so the caller can fold them into the
    readiness report. Each check is defensive — if the
    relevant columns are missing or the data is too small to compute a
    meaningful fence, the check is simply skipped.

    Anomaly types detected:
      1. **Out-of-range scores** (only when `rating_min`/`rating_max`
         are provided explicitly). Flags ratings that fall outside
         the declared scale.
      2. **Negative scores**. Rating scales are conventionally
         non-negative; negatives usually indicate an encoding error.
      3. **Zero-variance persons**. Persons whose Score column is
         constant cannot contribute to ability estimation.
      4. **Zero-variance facet elements**. Raters / items / tasks
         whose Score is constant cannot be calibrated. This catches
         classic "agreeing" or "central-tendency" raters with zero
         spread.
      5. **Extreme-frequency persons** (Tukey fence with k=3). Users
         with far more or far fewer observations than the cohort
         median — often a cleaning / duplication artefact.
      6. **Ceiling / floor saturation**. Over 90 % of observations at
         the scale extremes suggests scale misspecification or
         response-set behaviour.
    """
    findings: list[dict] = []

    if data is None or not hasattr(data, "columns"):
        return findings
    cols = set(data.columns)

    # Precompute numeric scores once; all score-based checks use this.
    scores_num: pd.Series | None = None
    if score_col in cols:
        scores_num = pd.to_numeric(data[score_col], errors="coerce")

    # 1. Out-of-range scores (needs an explicit rating scale)
    if scores_num is not None and rating_min is not None:
        below = int((scores_num < rating_min).sum())
        if below > 0:
            findings.append({
                "name": "scores_below_range",
                "severity": "warning" if below < 10 else "issue",
                "headline": f"{below} score(s) below rating_min ({rating_min})",
                "detail": "Verify the intended scale; out-of-range scores will be recoded.",
            })
    if scores_num is not None and rating_max is not None:
        above = int((scores_num > rating_max).sum())
        if above > 0:
            findings.append({
                "name": "scores_above_range",
                "severity": "warning" if above < 10 else "issue",
                "headline": f"{above} score(s) above rating_max ({rating_max})",
                "detail": "Verify the intended scale; out-of-range scores will be recoded.",
            })

    # 2. Negative scores (most rating scales are 0-based or 1-based)
    if scores_num is not None:
        n_negative = int((scores_num < 0).sum())
        if n_negative > 0:
            findings.append({
                "name": "scores_negative",
                "severity": "warning",
                "headline": f"{n_negative} negative score value(s)",
                "detail": "Rating scales are typically non-negative — check for encoding errors.",
            })

    # 3. Zero-variance persons
    if scores_num is not None and person_col in cols:
        per_person = pd.Series(scores_num.values).groupby(data[person_col].values).std()
        # `std` returns NaN for singleton groups — exclude them from
        # "zero variance" because one observation cannot have zero
        # variance in a meaningful sense.
        zero_var_ids = per_person[(per_person == 0) & per_person.notna()].index.tolist()
        if zero_var_ids:
            n_zero = len(zero_var_ids)
            examples = ", ".join(str(x) for x in zero_var_ids[:3])
            suffix = f", … ({n_zero} total)" if n_zero > 3 else ""
            findings.append({
                "name": "zero_variance_persons",
                "severity": "warning" if n_zero <= 5 else "issue",
                "headline": f"{n_zero} person(s) with zero score variance",
                "detail": (
                    f"All responses identical for: {examples}{suffix}. "
                    "Their person measures cannot be estimated precisely."
                ),
            })

    # 4. Zero-variance facet elements
    for facet in facet_cols:
        if scores_num is not None and facet in cols:
            per_elem = pd.Series(scores_num.values).groupby(data[facet].values).std()
            zero_var_ids = per_elem[(per_elem == 0) & per_elem.notna()].index.tolist()
            if zero_var_ids:
                n_zero = len(zero_var_ids)
                examples = ", ".join(str(x) for x in zero_var_ids[:3])
                suffix = f", … ({n_zero} total)" if n_zero > 3 else ""
                findings.append({
                    "name": f"zero_variance_{facet}",
                    "severity": "warning" if n_zero <= 3 else "issue",
                    "headline": f"{n_zero} `{facet}` element(s) with zero score variance",
                    "detail": (
                        f"Constant responses from: {examples}{suffix}. "
                        "Cannot calibrate these element measures."
                    ),
                })

    # 5. Extreme-frequency persons (Tukey fence, k=3)
    if person_col in cols:
        counts = data[person_col].value_counts()
        if len(counts) >= 10:
            q1 = float(counts.quantile(0.25))
            q3 = float(counts.quantile(0.75))
            iqr = q3 - q1
            if iqr > 0:
                upper = q3 + 3 * iqr
                lower = max(1.0, q1 - 3 * iqr)
                highs = counts[counts > upper]
                lows = counts[counts < lower]
                if len(highs) > 0:
                    findings.append({
                        "name": "person_over_observed",
                        "severity": "warning",
                        "headline": f"{len(highs)} person(s) over-observed",
                        "detail": (
                            f"Highest observation count = {int(counts.max())} "
                            f"(cohort median = {int(counts.median())}). "
                            "Check for duplicated rows or inconsistent sampling."
                        ),
                    })
                if len(lows) > 0:
                    findings.append({
                        "name": "person_under_observed",
                        "severity": "warning",
                        "headline": f"{len(lows)} person(s) under-observed",
                        "detail": (
                            f"Lowest observation count = {int(counts.min())} "
                            f"(cohort median = {int(counts.median())}). "
                            "Their measures will have wide SE."
                        ),
                    })

    # 6. Ceiling / floor saturation
    if scores_num is not None:
        valid = scores_num.dropna()
        if len(valid) >= 50:
            s_min = float(valid.min())
            s_max = float(valid.max())
            if s_max > s_min:
                frac_floor = float((valid == s_min).mean())
                frac_ceiling = float((valid == s_max).mean())
                if frac_ceiling > 0.9:
                    findings.append({
                        "name": "ceiling_saturation",
                        "severity": "warning",
                        "headline": f"{frac_ceiling:.0%} of scores at the ceiling ({s_max:g})",
                        "detail": "Targeting is poor — most ratings are at the top of the scale.",
                    })
                elif frac_floor > 0.9:
                    findings.append({
                        "name": "floor_saturation",
                        "severity": "warning",
                        "headline": f"{frac_floor:.0%} of scores at the floor ({s_min:g})",
                        "detail": "Targeting is poor — most ratings are at the bottom of the scale.",
                    })

    return findings


def render_readiness_panel(report: dict) -> None:
    """Streamlit panel showing the readiness status + details.

    Each severity state uses a textual prefix so users can distinguish
    status without relying on hue alone.
    """
    overall = report.get("overall", "ok")
    checks = report.get("checks", [])
    icon = _READINESS_ICON.get(overall, "⚪")
    text = _READINESS_TEXT_LABEL.get(overall, overall.upper())

    if overall == "ok":
        st.success(
            t(
                "input_readiness.panel_ok_template",
                icon=icon,
                status=text,
                n_checks=len(checks),
            )
        )
        st.caption(t("input_readiness.next_action_caption"))
        st.dataframe(build_input_readiness_next_action_table(report), width="stretch", hide_index=True)
        with st.expander(t("input_readiness.detail_expander_ok"), expanded=False):
            _render_readiness_checklist(checks)
        return

    if overall == "warning":
        n_w = report.get("n_warnings", 0)
        st.warning(
            t(
                "input_readiness.panel_warning_template",
                icon=icon,
                status=text,
                n_warnings=n_w,
            )
        )
        st.caption(t("input_readiness.next_action_caption"))
        st.dataframe(build_input_readiness_next_action_table(report), width="stretch", hide_index=True)
        with st.expander(t("input_readiness.detail_expander_action_needed"), expanded=True):
            _render_readiness_checklist(checks)
        return

    # issue
    st.error(
        t(
            "input_readiness.panel_issue_template",
            icon=icon,
            status=text,
            n_issues=report.get("n_issues", 0),
        )
    )
    st.caption(t("input_readiness.next_action_caption"))
    st.dataframe(build_input_readiness_next_action_table(report), width="stretch", hide_index=True)
    with st.expander(t("input_readiness.detail_expander_action_needed"), expanded=True):
        _render_readiness_checklist(checks)


def _render_readiness_checklist(checks: list[dict]) -> None:
    st.caption(t("input_readiness.detail_caption"))
    detail_table = build_input_readiness_detail_table(checks)
    if detail_table.empty:
        st.caption(t("input_readiness.detail_empty"))
        return
    st.dataframe(detail_table, width="stretch", hide_index=True)


