def _citation_present_in_text(text: str, citation: str) -> bool:
    """Return True when ``text`` cites ``citation``.

    Accepts both exact one-citation tokens such as ``(Linacre, 1989)`` and
    multi-source parentheticals such as ``(Rasch, 1980; Linacre, 1989)``.
    """
    if citation in text:
        return True
    label = str(citation).strip()
    if not (label.startswith("(") and label.endswith(")")):
        return False
    inner = label[1:-1].strip()
    for match in re.finditer(r"\(([^)]*)\)", str(text)):
        parts = [part.strip() for part in match.group(1).split(";")]
        if inner in parts:
            return True
    return False


def collect_cited_references(text: str) -> list[str]:
    """Return the APA 7 entries for every `(Author, Year)` citation in `text`.

    Scans the narrative for citations that match a known library key,
    deduplicates by key, and returns an alphabetised list of ready-to-
    render APA entries. Unknown citations are silently ignored — callers
    should add them to `_APA_REFERENCE_LIBRARY` if they want them surfaced.
    """
    keys_seen: set[str] = set()
    for citation, key in _CITATION_TO_KEY.items():
        if _citation_present_in_text(text, citation) and key in _APA_REFERENCE_LIBRARY:
            keys_seen.add(key)
    entries = [_APA_REFERENCE_LIBRARY[k] for k in keys_seen]
    return sorted(entries)


_MONOCHROME_PALETTE = (
    "#1a1a1a",  # near-black
    "#5c5c5c",  # dark grey
    "#8c8c8c",  # mid grey
    "#bdbdbd",  # light grey
    "#d9d9d9",  # very light grey
    "#000000",  # pure black
    "#404040",  # charcoal
    "#737373",  # warm grey
)

_MONOCHROME_DASH_PATTERNS = (
    "solid",
    "dash",
    "dot",
    "dashdot",
    "longdash",
    "longdashdot",
)


def get_monochrome_palette(n: int | None = None) -> list[str]:
    """Return a grayscale-only color palette suitable for print-friendly
    APA figures.

    When ``n`` is supplied the palette is cycled / truncated to that
    length. The palette is anchored at near-black and walks down to
    very-light-grey in eight steps; print reproduction at 300 DPI keeps
    every step distinct.
    """
    base = list(_MONOCHROME_PALETTE)
    if n is None:
        return base
    n = max(int(n), 0)
    if n <= len(base):
        return base[:n]
    repeats = (n + len(base) - 1) // len(base)
    return (base * repeats)[:n]


def get_monochrome_dash_patterns(n: int | None = None) -> list[str]:
    """Return Plotly dash patterns for line plots under the monochrome
    preset. Pairs with ``get_monochrome_palette`` so distinct lines can
    be told apart by both line style and shade."""
    base = list(_MONOCHROME_DASH_PATTERNS)
    if n is None:
        return base
    n = max(int(n), 0)
    if n <= len(base):
        return base[:n]
    repeats = (n + len(base) - 1) // len(base)
    return (base * repeats)[:n]


def _format_apa_cell(value, digits: int = 3, *, is_bool: bool = False) -> str:
    """Format a single cell value for an APA-style report table.

    ``is_bool`` forces Yes/No rendering for columns whose dtype is
    boolean even after pandas upcasts the row Series to an object dtype.
    """
    if value is None:
        return ""
    if isinstance(value, float) and not np.isfinite(value):
        return ""
    if is_bool:
        try:
            return "Yes" if bool(value) else "No"
        except Exception:
            return ""
    if isinstance(value, (np.bool_, bool)):
        return "Yes" if bool(value) else "No"
    if isinstance(value, (np.floating,)):
        value = float(value)
    if isinstance(value, float):
        return f"{value:.{int(digits)}f}"
    if isinstance(value, (np.integer, int)):
        return f"{int(value)}"
    return str(value)


def _apa_column_is_bool(df: pd.DataFrame, col: str) -> bool:
    """Detect whether a column should render as Yes/No.

    Inspects the column's dtype and, when ambiguous (e.g. object dtype
    holding Python bools), checks the first non-null value.
    """
    dtype = df[col].dtype
    if dtype == bool or dtype == np.bool_:
        return True
    if str(dtype) == "boolean":  # pandas nullable boolean
        return True
    if dtype == object:
        non_null = df[col].dropna()
        if not non_null.empty:
            first = non_null.iloc[0]
            return isinstance(first, (bool, np.bool_))
    return False


def apa_table_to_markdown(
    df: pd.DataFrame,
    *,
    caption: str | None = None,
    note: str | None = None,
    digits: int = 3,
    table_number: int | None = None,
) -> str:
    """Render a DataFrame as an APA 7 Markdown table.

    APA 7 places the table number on its own line, the caption in italics
    immediately below, the table grid in the middle, and a ``Note.``
    block at the bottom for definitions / measurement-scale callouts.
    The Markdown output uses GitHub-flavoured pipe tables so it pastes
    cleanly into Quarto / RMarkdown / GitHub READMEs / manuscripts that
    accept Markdown source.
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return ""
    columns = list(df.columns)
    bool_cols = {c: _apa_column_is_bool(df, c) for c in columns}
    header = "| " + " | ".join(str(c) for c in columns) + " |"
    sep = "| " + " | ".join("---" for _ in columns) + " |"
    body_lines = []
    for _, row in df.iterrows():
        cells = [
            _format_apa_cell(row[c], digits=digits, is_bool=bool_cols[c])
            for c in columns
        ]
        body_lines.append("| " + " | ".join(cells) + " |")
    parts: list[str] = []
    if table_number is not None:
        parts.append(f"**Table {int(table_number)}**")
    if caption:
        parts.append(f"*{caption}*")
    parts.append(header)
    parts.append(sep)
    parts.extend(body_lines)
    if note:
        parts.append("")
        parts.append(f"*Note.* {note}")
    return "\n".join(parts)


def _escape_html(value: str) -> str:
    return (
        str(value)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


def apa_table_to_html(
    df: pd.DataFrame,
    *,
    caption: str | None = None,
    note: str | None = None,
    digits: int = 3,
    table_number: int | None = None,
) -> str:
    """Render a DataFrame as an APA 7 HTML table.

    The structure follows APA 7 placement: a ``<div class="apa-table">``
    wrapper with the table number on its own line, the caption in
    italics, a borderless ``<table>`` grid (top, header, bottom rules),
    and a ``Note.`` paragraph below. Inline CSS keeps the output
    self-contained so it can be pasted into Word, a manuscript HTML
    template, or a Quarto / RMarkdown HTML chunk.
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return ""
    columns = list(df.columns)
    bool_cols = {c: _apa_column_is_bool(df, c) for c in columns}
    header_row = "".join(
        f"<th style=\"border-bottom: 1px solid #000; padding: 4px 8px; text-align: left;\">"
        f"{_escape_html(c)}</th>"
        for c in columns
    )
    body_rows = []
    for _, row in df.iterrows():
        cells = "".join(
            f"<td style=\"padding: 4px 8px;\">"
            f"{_escape_html(_format_apa_cell(row[c], digits=digits, is_bool=bool_cols[c]))}</td>"
            for c in columns
        )
        body_rows.append(f"<tr>{cells}</tr>")
    parts = [
        "<div class=\"apa-table\" style=\"font-family: serif; margin: 1em 0;\">"
    ]
    if table_number is not None:
        parts.append(
            f"<div style=\"font-weight: bold; margin-bottom: 0.2em;\">"
            f"Table {int(table_number)}</div>"
        )
    if caption:
        parts.append(
            f"<div style=\"font-style: italic; margin-bottom: 0.5em;\">"
            f"{_escape_html(caption)}</div>"
        )
    parts.append(
        "<table style=\"border-collapse: collapse; border-top: 2px solid #000; "
        "border-bottom: 2px solid #000; width: 100%;\">"
    )
    parts.append(f"<thead><tr>{header_row}</tr></thead>")
    parts.append("<tbody>" + "".join(body_rows) + "</tbody>")
    parts.append("</table>")
    if note:
        parts.append(
            "<div style=\"margin-top: 0.5em; font-size: 0.95em;\">"
            f"<em>Note.</em> {_escape_html(note)}</div>"
        )
    parts.append("</div>")
    return "\n".join(parts)


def build_apa_reference_list(text: str, *, always_include: list[str] | None = None) -> list[str]:
    """Build the APA reference list for a publication document.

    - `text`: the narrative body (Methods + Results) that was just rendered;
      every `(Author, Year)` token present in it is included.
    - `always_include`: reference keys that must appear regardless of
      whether they were cited (used for core MFRM references).
    """
    keys_seen: set[str] = set()
    for citation, key in _CITATION_TO_KEY.items():
        if _citation_present_in_text(text, citation) and key in _APA_REFERENCE_LIBRARY:
            keys_seen.add(key)
    for key in always_include or []:
        if key in _APA_REFERENCE_LIBRARY:
            keys_seen.add(key)
    return sorted(_APA_REFERENCE_LIBRARY[k] for k in keys_seen)


def _reference_keys_from_citation_labels(labels: Iterable[str]) -> list[str]:
    """Resolve ``Author, Year`` labels used by the APA report to library keys."""
    keys_seen: set[str] = set()
    for label in labels:
        token = str(label).strip()
        if not token:
            continue
        citation = token if token.startswith("(") and token.endswith(")") else f"({token})"
        key = _CITATION_TO_KEY.get(citation)
        if key in _APA_REFERENCE_LIBRARY:
            keys_seen.add(str(key))
    return sorted(keys_seen)


def _cited_reference_keys(text: str, *, always_include: list[str] | None = None) -> list[str]:
    """Return the reference keys cited in ``text`` (plus any
    ``always_include`` overrides), in alphabetical order. Shared by the
    BibTeX / RIS bundle exporters so the three formats (APA / BibTeX /
    RIS) always include the same set of references for a given run."""
    keys_seen: set[str] = set()
    for citation, key in _CITATION_TO_KEY.items():
        if _citation_present_in_text(text, citation) and key in _APA_REFERENCE_LIBRARY:
            keys_seen.add(key)
    for key in always_include or []:
        if key in _APA_REFERENCE_LIBRARY:
            keys_seen.add(key)
    return sorted(keys_seen)


# ---------------------------------------------------------------------------
# BibTeX / RIS conversion for the APA reference library
# ---------------------------------------------------------------------------
#
# Academic users of the Streamlit app frequently maintain bibliographies in
# BibTeX (LaTeX, Zotero) or RIS (EndNote). The APA prose entries already
# stored in ``_APA_REFERENCE_LIBRARY`` are the source of truth; the helpers
# below parse each prose entry on the fly into a structured record, then
# serialise it to either format. Entries the parser cannot confidently
# classify fall back to ``@misc`` (BibTeX) or ``TY  - GEN`` (RIS) with the
# raw APA string in the ``note``/``N1`` field, so users still get a usable
# reference even for unusual formats (RMT short notes, edited proceedings).

# Matches an APA initial token: a single uppercase letter followed by ``.``,
# optionally followed by one or more `` X.`` or ``-X.`` sequences. Covers
# ``T.`` / ``E. R.`` / ``A. A.`` / ``K.-Y.``.
_APA_AUTHOR_INITIAL_RE = re.compile(r"^[A-Z]\.(?:[\s-][A-Z]\.)*$")


def _apa_authors_to_bibtex(authors_apa: str) -> str:
    """Convert an APA author list to a BibTeX ``and``-separated string.

    APA: ``"Lai, E. R., Wolfe, E. W., & Vickers, D."``
    BibTeX: ``"Lai, E. R. and Wolfe, E. W. and Vickers, D."``

    Preserves suffixes (``Jr.``) and editor markers (``(Ed.)``) verbatim so
    Zotero / BibDesk display the entry correctly even when our parsing is
    approximate."""
    raw = authors_apa.strip()
    if not raw:
        return ""
    # Pull the last author off the ``" & "`` separator if present; that
    # handles all 2+-author cases. Single-author entries pass through.
    if " & " in raw:
        before_and, last_author = raw.rsplit(" & ", 1)
    else:
        before_and, last_author = raw, ""
    # In ``before_and`` the authors are listed as ``Lastname1, Initials1, Lastname2, Initials2``.
    # Pair them up greedily. The trailing chunk often carries the dangling
    # ``,`` that precedes the ``" & "`` separator (e.g. ``"Eckes, T.,"``)
    # — strip it so the initials regex still matches ``"T."``.
    chunks = [c.strip().rstrip(",") for c in before_and.split(", ") if c.strip()]
    paired: list[str] = []
    i = 0
    while i < len(chunks):
        if i + 1 < len(chunks) and _APA_AUTHOR_INITIAL_RE.match(chunks[i + 1]):
            paired.append(f"{chunks[i]}, {chunks[i + 1]}")
            i += 2
        else:
            # No initials follow — likely a suffix like ``Jr.`` that
            # belongs to the previous author. Glue it on.
            if paired and chunks[i] in {"Jr.", "Sr.", "II", "III"}:
                paired[-1] = f"{paired[-1]}, {chunks[i]}"
            else:
                paired.append(chunks[i])
            i += 1
    if last_author:
        paired.append(last_author.strip())
    return " and ".join(paired)


def _split_apa_after_year(apa: str) -> tuple[str, str, str] | None:
    """Split ``apa`` at the first ``(YYYY)`` token and return
    ``(authors, year, rest)`` or ``None`` if no year is present. The
    trailing period after the last initial (``"... J. M."``) is
    preserved so the author-pairing regex can recognise the initials."""
    year_match = re.search(r"\(((?:18|19|20)\d{2}[a-z]?)\)", apa)
    if not year_match:
        return None
    year = year_match.group(1)
    authors = apa[: year_match.start()].rstrip()
    rest = apa[year_match.end():].lstrip(". ").strip()
    return authors, year, rest


def _extract_doi(rest: str) -> tuple[str, str]:
    """Return ``(doi, rest_without_doi)``. Handles trailing punctuation."""
    doi_match = re.search(r"https?://(?:dx\.)?doi\.org/(\S+?)\s*\.?\s*$", rest)
    if not doi_match:
        return "", rest
    doi = doi_match.group(1).rstrip(".")
    rest = rest[: doi_match.start()].rstrip().rstrip(".")
    return doi, rest


def _strip_trailing_period(title: str) -> str:
    """Strip a trailing period from a title — BibTeX convention is to omit
    the sentence-ending period because the bibliography style adds it.
    A trailing ``?`` or ``!`` is meaningful punctuation and is kept."""
    return title.strip().rstrip(".").strip()


def _parse_apa_entry(key: str, apa: str) -> dict:
    """Parse one APA prose entry into a structured BibTeX-ready record.

    Returns a dict with keys ``type`` (``"article"`` / ``"book"`` /
    ``"incollection"`` / ``"misc"``), ``key``, ``author``, ``year``,
    ``title``, ``doi``, and type-specific fields (``journal`` /
    ``publisher`` / ``booktitle`` / ``editor`` / ``volume`` / ``number``
    / ``pages`` / ``edition``). ``"misc"`` types carry the original APA
    prose in ``note`` so the user retains the raw reference even when
    structure cannot be inferred."""
    split = _split_apa_after_year(apa)
    if split is None:
        return {"type": "misc", "key": key, "note": apa.strip()}
    authors, year, rest = split
    doi, rest = _extract_doi(rest)

    # Journal article: ``Title. Journal Name, V(N), pages``. The title can
    # end with ``.``, ``?``, or ``!`` — capture the terminator inside the
    # group so the question mark survives into the BibTeX output.
    article_match = re.match(
        r"^(?P<title>.+?[.?!])\s+(?P<journal>[^,]+),\s*(?P<volume>\d+)"
        r"(?:\((?P<number>[^)]+)\))?,\s*(?P<pages>[\dA-Za-z–\-]+(?:[–\-][\dA-Za-z]+)?)\.?\s*$",
        rest,
    )
    if article_match:
        return {
            "type": "article",
            "key": key,
            "author": authors,
            "year": year,
            "title": _strip_trailing_period(article_match.group("title")),
            "journal": article_match.group("journal").strip(),
            "volume": article_match.group("volume"),
            "number": (article_match.group("number") or "").strip(),
            "pages": article_match.group("pages").replace("–", "--"),
            "doi": doi,
        }

    # Book chapter / proceedings: ``Title. In E. Editor (Ed.), Booktitle (pp. xx-yy). Publisher``
    # Publisher is optional — some proceedings entries end at the page range.
    chapter_match = re.match(
        r"^(?P<title>.+?[.?!])\s+In\s+(?P<editor>.+?)\s*\((?:Ed|Eds)\.\),\s+"
        r"(?P<booktitle>.+?)\s+\(pp\.\s*(?P<pages>[\d–\-]+)\)"
        r"(?:\.\s+(?P<publisher>.+?))?\.?\s*$",
        rest,
    )
    if chapter_match:
        return {
            "type": "incollection",
            "key": key,
            "author": authors,
            "year": year,
            "title": _strip_trailing_period(chapter_match.group("title")),
            "editor": chapter_match.group("editor").strip(),
            "booktitle": chapter_match.group("booktitle").strip(),
            "pages": chapter_match.group("pages").replace("–", "--"),
            "publisher": (chapter_match.group("publisher") or "").strip(),
            "doi": doi,
        }

    # Book: ``Title. Publisher`` or ``Title (2nd ed.). Publisher``. Publisher
    # may itself contain periods (``Winsteps.com``, ``Cambridge U.K.``), so we
    # allow any chars in the trailing publisher.
    book_match = re.match(r"^(?P<title>.+?[.?!])\s+(?P<publisher>.+?)\.?\s*$", rest)
    if book_match:
        title = _strip_trailing_period(book_match.group("title"))
        publisher = book_match.group("publisher").strip()
        edition_match = re.search(r"\s*\((\d+(?:st|nd|rd|th)\s*ed\.?)\)\s*$", title)
        edition = ""
        if edition_match:
            edition = edition_match.group(1)
            title = title[: edition_match.start()].rstrip()
        return {
            "type": "book",
            "key": key,
            "author": authors,
            "year": year,
            "title": title,
            "publisher": publisher,
            "edition": edition,
            "doi": doi,
        }

    return {"type": "misc", "key": key, "note": apa.strip()}


def _format_bibtex_entry(record: dict) -> str:
    """Serialise a parsed reference record as a BibTeX entry."""
    rtype = record.get("type", "misc")
    key = record.get("key", "unknown")
    if rtype == "misc":
        # Fall back to ``@misc`` and stash the raw APA in ``note`` so the
        # user still gets a usable citation in their bibliography.
        return (
            f"@misc{{{key},\n"
            f"  note = {{{record.get('note', '')}}}\n"
            f"}}"
        )
    fields: list[tuple[str, str]] = []
    author = _apa_authors_to_bibtex(record.get("author", ""))
    if author:
        fields.append(("author", author))
    if rtype == "incollection" and record.get("editor"):
        fields.append(("editor", _apa_authors_to_bibtex(record["editor"])))
    if record.get("title"):
        fields.append(("title", record["title"]))
    if rtype == "article" and record.get("journal"):
        fields.append(("journal", record["journal"]))
    if rtype == "incollection" and record.get("booktitle"):
        fields.append(("booktitle", record["booktitle"]))
    if record.get("year"):
        fields.append(("year", record["year"]))
    if record.get("volume"):
        fields.append(("volume", record["volume"]))
    if record.get("number"):
        fields.append(("number", record["number"]))
    if record.get("pages"):
        fields.append(("pages", record["pages"]))
    if record.get("publisher"):
        fields.append(("publisher", record["publisher"]))
    if record.get("edition"):
        fields.append(("edition", record["edition"]))
    if record.get("doi"):
        fields.append(("doi", record["doi"]))
    body = ",\n".join(f"  {name} = {{{value}}}" for name, value in fields)
    return f"@{rtype}{{{key},\n{body}\n}}"


def apa_entry_to_bibtex(key: str, apa: str) -> str:
    """Convert one ``_APA_REFERENCE_LIBRARY`` entry to a BibTeX string.

    Public wrapper around ``_parse_apa_entry`` + ``_format_bibtex_entry``
    used by ``build_bibtex_from_cited`` and the BibTeX download button."""
    return _format_bibtex_entry(_parse_apa_entry(key, apa))


_RIS_TYPE_BY_BIB = {
    "article": "JOUR",
    "book": "BOOK",
    "incollection": "CHAP",
    "misc": "GEN",
}


def _format_ris_entry(record: dict) -> str:
    """Serialise a parsed reference record as an RIS record."""
    rtype = record.get("type", "misc")
    ris_type = _RIS_TYPE_BY_BIB.get(rtype, "GEN")
    lines: list[str] = [f"TY  - {ris_type}"]
    if rtype == "misc":
        lines.append(f"N1  - {record.get('note', '')}")
        lines.append("ER  - ")
        return "\n".join(lines)
    raw_author = record.get("author", "")
    # RIS expects one ``AU  -`` line per author in ``Lastname, Initials`` form,
    # which is exactly the APA pairing produced by ``_apa_authors_to_bibtex``.
    if raw_author:
        for au in _apa_authors_to_bibtex(raw_author).split(" and "):
            lines.append(f"AU  - {au}")
    if rtype == "incollection" and record.get("editor"):
        for ed in _apa_authors_to_bibtex(record["editor"]).split(" and "):
            lines.append(f"A2  - {ed}")
    if record.get("year"):
        lines.append(f"PY  - {record['year']}")
    if record.get("title"):
        lines.append(f"TI  - {record['title']}")
    if rtype == "article" and record.get("journal"):
        lines.append(f"JO  - {record['journal']}")
    if rtype == "incollection" and record.get("booktitle"):
        lines.append(f"T2  - {record['booktitle']}")
    if record.get("volume"):
        lines.append(f"VL  - {record['volume']}")
    if record.get("number"):
        lines.append(f"IS  - {record['number']}")
    if record.get("pages"):
        pages = record["pages"]
        if "--" in pages:
            sp, ep = pages.split("--", 1)
            lines.append(f"SP  - {sp}")
            lines.append(f"EP  - {ep}")
        else:
            lines.append(f"SP  - {pages}")
    if record.get("publisher"):
        lines.append(f"PB  - {record['publisher']}")
    if record.get("edition"):
        lines.append(f"ET  - {record['edition']}")
    if record.get("doi"):
        lines.append(f"DO  - {record['doi']}")
    lines.append("ER  - ")
    return "\n".join(lines)


def apa_entry_to_ris(key: str, apa: str) -> str:
    """Convert one ``_APA_REFERENCE_LIBRARY`` entry to an RIS record."""
    return _format_ris_entry(_parse_apa_entry(key, apa))


def build_bibtex_from_cited(
    text: str,
    *,
    always_include: list[str] | None = None,
) -> str:
    """Build a ``.bib`` file from references cited in ``text``.

    Mirrors ``build_apa_reference_list`` so the BibTeX bundle always
    matches the APA bundle for a given run. Returns the file contents
    as a UTF-8 string with blank lines between entries."""
    keys = _cited_reference_keys(text, always_include=always_include)
    if not keys:
        return ""
    entries = [apa_entry_to_bibtex(k, _APA_REFERENCE_LIBRARY[k]) for k in keys]
    header = (
        "% BibTeX export of references cited in this MFRM analysis.\n"
        f"% Generated by {APP_VERSION} ({APP_RELEASE_LABEL}).\n"
        "% Review each entry before submission — parsing of APA prose is heuristic.\n\n"
    )
    return header + "\n\n".join(entries) + "\n"


def build_ris_from_cited(
    text: str,
    *,
    always_include: list[str] | None = None,
) -> str:
    """Build an RIS file from references cited in ``text``.

    Companion to ``build_bibtex_from_cited`` for EndNote / Mendeley
    users. Returns the file contents as a UTF-8 string."""
    keys = _cited_reference_keys(text, always_include=always_include)
    if not keys:
        return ""
    return "\n\n".join(
        apa_entry_to_ris(k, _APA_REFERENCE_LIBRARY[k]) for k in keys
    ) + "\n"


# ---------------------------------------------------------------------------
# Word (.docx) publication document builder
# ---------------------------------------------------------------------------
# Produces a single manuscript-ready Word file containing:
#   - Title + auto-generated abstract
#   - Methods (from generate_method_appendix_text)
#   - Manuscript template (from generate_manuscript_reporting_template)
#   - Embedded figures (Wright map, pathway, scree, category curves)
#   - Embedded core tables (measures, reliability, fit summary)
#   - APA 7 reference list (via build_apa_reference_list)
#
# python-docx is lazy-imported so the app still boots if the package
# is missing (e.g. mid-deploy); the Report tab surfaces an install hint
# instead of crashing.

_PUBLICATION_DOCUMENT_CORE_REFS: list[str] = [
    "Rasch_1980",           # Rasch model foundation
    "Andrich_1978",         # RSM
    "Masters_1982",         # PCM
    "Linacre_1989",         # Many-facet Rasch measurement
    "Linacre_2024",         # Fit interpretation
    "Myford_Wolfe_2003",    # Rater effects I
    "Myford_Wolfe_2004",    # Rater effects II
    "Smith_2002",           # PCA of residuals
    "Wright_Masters_1982",  # Rating scale analysis
]


# ---------------------------------------------------------------------------
# matplotlib fallback for publication figures (v0.2.10-beta)
#
# Problem: kaleido 1.x requires a Chrome / Chromium binary to render
# Plotly figures to PNG. Streamlit Community Cloud does not ship
# Chrome, so `fig_to_png_bytes()` silently returns None there and the
# Publication Document PDF ends up with no plots. Matplotlib is a
# pure-Python rendering path with no browser dependency, so we use it
# as a guaranteed fallback. When Chrome IS available the Plotly path
# is preferred because the interactive-styled Plotly figure is what
# users see on screen.
#
# Each helper below renders one publication figure from the raw data
# in the result / diagnostics dicts (not from the Plotly figure
# object) so it works even when the Plotly build fails.
# ---------------------------------------------------------------------------


def _mpl_safe_import():
    """Import matplotlib.pyplot with the Agg backend. Returns (plt, None) or (None, error_str)."""
    try:
        import matplotlib
        matplotlib.use("Agg", force=False)
        import matplotlib.pyplot as plt
        return plt, None
    except ImportError as exc:
        return None, f"matplotlib not available: {exc}"


def _mpl_fig_to_png_bytes(fig, dpi: int = PUBLICATION_FIGURE_DPI) -> bytes | None:
    """Serialise a matplotlib Figure to PNG bytes and close it."""
    try:
        import io as _io
        buf = _io.BytesIO()
        fig.savefig(buf, format="png", dpi=dpi, bbox_inches="tight")
        return buf.getvalue()
    except Exception:
        return None
    finally:
        try:
            import matplotlib.pyplot as plt
            plt.close(fig)
        except Exception:
            pass


def _mpl_wright_map_png(result: dict, diagnostics: dict) -> bytes | None:
    """Matplotlib Wright map: person abilities (left) vs. facet elements (right)."""
    plt, err = _mpl_safe_import()
    if plt is None:
        return None
    try:
        # Person ability distribution
        facets = result.get("facets", {}) if isinstance(result, dict) else {}
        person_df = facets.get("person") if isinstance(facets, dict) else None
        measures = diagnostics.get("measures") if isinstance(diagnostics, dict) else None
        if not isinstance(person_df, pd.DataFrame) or person_df.empty:
            return None

        person_est = pd.to_numeric(person_df.get("Estimate"), errors="coerce").dropna()
        if person_est.empty:
            return None

        fig, (ax_l, ax_r) = plt.subplots(
            1, 2, figsize=(10, 6), sharey=True,
            gridspec_kw={"width_ratios": [1, 1.4], "wspace": 0.08},
        )
        # Persons — horizontal histogram
        ax_l.hist(
            person_est.values, bins=20, orientation="horizontal",
            color="#0d7a5a", edgecolor="white", alpha=0.85,
        )
        ax_l.set_title("Persons", fontsize=11)
        ax_l.set_xlabel("Count")
        ax_l.invert_xaxis()
        ax_l.grid(axis="y", alpha=0.25)
        ax_l.axhline(0, color="#666666", linewidth=0.7)

        # Facet elements — scatter with labels
        if isinstance(measures, pd.DataFrame) and not measures.empty:
            facet_col = "Facet" if "Facet" in measures.columns else None
            if facet_col is not None:
                colors = plt.cm.tab10.colors
                facet_names = list(measures[facet_col].astype(str).unique())
                offsets = {name: i for i, name in enumerate(facet_names)}
                for name in facet_names:
                    sub = measures[measures[facet_col].astype(str) == name]
                    y = pd.to_numeric(sub.get("Estimate"), errors="coerce")
                    x = [offsets[name]] * len(sub)
                    color = colors[offsets[name] % len(colors)]
                    ax_r.scatter(x, y, color=color, s=35, alpha=0.8, label=name)
                ax_r.set_xticks(list(offsets.values()))
                ax_r.set_xticklabels(list(offsets.keys()), rotation=25, ha="right")
        ax_r.set_title("Facet elements", fontsize=11)
        ax_r.set_ylabel("Logit measure")
        ax_r.axhline(0, color="#666666", linewidth=0.7)
        ax_r.grid(axis="y", alpha=0.25)

        fig.suptitle("Wright map (person–element targeting)", fontsize=13, y=1.02)
        return _mpl_fig_to_png_bytes(fig)
    except Exception:
        return None


def _mpl_fit_scatter_png(diagnostics: dict) -> bytes | None:
    """Matplotlib fit scatter: Infit (x) vs Outfit (y) with acceptable-zone bands."""
    plt, err = _mpl_safe_import()
    if plt is None:
        return None
    try:
        measures = diagnostics.get("measures") if isinstance(diagnostics, dict) else None
        if not isinstance(measures, pd.DataFrame) or measures.empty:
            return None
        infit = pd.to_numeric(measures.get("Infit"), errors="coerce")
        outfit = pd.to_numeric(measures.get("Outfit"), errors="coerce")
        mask = infit.notna() & outfit.notna()
        if int(mask.sum()) < 2:
            return None
        infit = infit[mask]
        outfit = outfit[mask]

        fig, ax = plt.subplots(figsize=(7.5, 6))
        # Acceptable zone shading (0.5–1.5 on both axes)
        ax.axhspan(0.5, 1.5, facecolor="#b2dfb8", alpha=0.25, zorder=0)
        ax.axvspan(0.5, 1.5, facecolor="#b2dfb8", alpha=0.25, zorder=0)
        # Reference lines at 1.0 (expected value)
        ax.axhline(1.0, color="#444444", linewidth=0.8, linestyle="--", zorder=1)
        ax.axvline(1.0, color="#444444", linewidth=0.8, linestyle="--", zorder=1)
        # Scatter
        facet_col = "Facet" if "Facet" in measures.columns else None
        if facet_col is not None:
            facets = measures.loc[mask, facet_col].astype(str)
            colors = plt.cm.tab10.colors
            for i, name in enumerate(facets.unique()):
                sel = facets == name
                ax.scatter(
                    infit[sel], outfit[sel],
                    color=colors[i % len(colors)], label=name,
                    alpha=0.8, s=40, edgecolor="white", linewidth=0.5,
                )
            ax.legend(loc="best", fontsize=9, framealpha=0.9)
        else:
            ax.scatter(infit, outfit, color="#0d7a5a", alpha=0.8, s=40)

        ax.set_xlabel("Infit mean-square", fontsize=12)
        ax.set_ylabel("Outfit mean-square", fontsize=12)
        ax.set_title("Fit scatter (Infit vs Outfit)", fontsize=13)
        ax.grid(alpha=0.3)
        ax.set_xlim(max(0, min(infit.min(), 0.4)), max(infit.max() * 1.05, 2.0))
        ax.set_ylim(max(0, min(outfit.min(), 0.4)), max(outfit.max() * 1.05, 2.0))
        return _mpl_fig_to_png_bytes(fig)
    except Exception:
        return None


def _mpl_category_probability_png(result: dict) -> bytes | None:
    """Matplotlib category probability curves across the latent scale."""
    plt, err = _mpl_safe_import()
    if plt is None:
        return None
    try:
        # `build_category_probability_curve_data` is the public helper
        # that returns {"available": bool, "probability": DataFrame, ...}
        builder = globals().get("build_category_probability_curve_data")
        if not callable(builder):
            return None
        curve = builder(result)
        if not isinstance(curve, dict) or not curve.get("available"):
            return None
        prob = curve.get("probability")
        if not isinstance(prob, pd.DataFrame) or prob.empty or "Theta" not in prob.columns:
            return None

        theta = pd.to_numeric(prob["Theta"], errors="coerce").values
        category_cols = [c for c in prob.columns if c not in ("Theta", "Expected")]
        if not category_cols:
            return None

        fig, ax = plt.subplots(figsize=(8, 5.5))
        colors = plt.cm.viridis(np.linspace(0, 0.9, len(category_cols)))
        for i, cname in enumerate(category_cols):
            y = pd.to_numeric(prob[cname], errors="coerce").values
            ax.plot(theta, y, color=colors[i], linewidth=2, label=str(cname))
        ax.set_xlabel("Latent measure θ (logits)", fontsize=12)
        ax.set_ylabel("P(category)", fontsize=12)
        ax.set_title("Category probability curves", fontsize=13)
        ax.grid(alpha=0.3)
        ax.set_ylim(-0.02, 1.02)
        ax.legend(title="Category", loc="best", fontsize=9, framealpha=0.9)
        return _mpl_fig_to_png_bytes(fig)
    except Exception:
        return None


def _mpl_facet_distribution_png(diagnostics: dict) -> bytes | None:
    """Matplotlib box plot of measures within each facet."""
    plt, err = _mpl_safe_import()
    if plt is None:
        return None
    try:
        measures = diagnostics.get("measures") if isinstance(diagnostics, dict) else None
        if not isinstance(measures, pd.DataFrame) or measures.empty:
            return None
        if "Facet" not in measures.columns or "Estimate" not in measures.columns:
            return None

        pdf = measures.copy()
        pdf["Estimate"] = pd.to_numeric(pdf["Estimate"], errors="coerce")
        pdf = pdf.dropna(subset=["Estimate"])
        if pdf.empty:
            return None

        facet_groups: list[tuple[str, np.ndarray]] = []
        for name in pdf["Facet"].astype(str).unique():
            vals = pdf.loc[pdf["Facet"].astype(str) == name, "Estimate"].values
            if len(vals) >= 1:
                facet_groups.append((name, vals))
        if not facet_groups:
            return None

        fig, ax = plt.subplots(figsize=(8, 5.5))
        labels = [g[0] for g in facet_groups]
        values = [g[1] for g in facet_groups]
        # `tick_labels` replaced the deprecated `labels` kwarg in
        # matplotlib 3.9; fall back to the old name when older versions
        # are installed so we stay compatible with the pinned floor.
        try:
            bp = ax.boxplot(
                values, tick_labels=labels, patch_artist=True, widths=0.55,
                medianprops={"color": "#222222", "linewidth": 1.5},
            )
        except TypeError:
            bp = ax.boxplot(
                values, labels=labels, patch_artist=True, widths=0.55,
                medianprops={"color": "#222222", "linewidth": 1.5},
            )
        colors = plt.cm.tab10.colors
        for i, patch in enumerate(bp["boxes"]):
            patch.set_facecolor(colors[i % len(colors)])
            patch.set_alpha(0.55)
        # Overlay strip-plot of raw values
        for i, (_, vals) in enumerate(facet_groups, start=1):
            jitter = (np.random.default_rng(42 + i).normal(0, 0.05, size=len(vals)))
            ax.scatter(np.full_like(vals, i, dtype=float) + jitter, vals,
                       color="#222222", alpha=0.55, s=12, zorder=3)

        ax.set_ylabel("Logit measure", fontsize=12)
        ax.set_title("Facet element distribution", fontsize=13)
        ax.grid(axis="y", alpha=0.3)
        ax.axhline(0, color="#666666", linewidth=0.7, linestyle="--")
        fig.autofmt_xdate(rotation=20)
        return _mpl_fig_to_png_bytes(fig)
    except Exception:
        return None


def _plotly_or_matplotlib_png(
    plotly_fig,
    matplotlib_fallback,
) -> bytes | None:
    """Try Plotly (kaleido → Chrome) first; fall back to matplotlib.

    The Plotly path produces PNGs styled identically to the on-screen
    figure, so it is preferred when Chrome is available. On Streamlit
    Community Cloud Chrome is typically absent and `fig_to_png_bytes`
    returns None — we then call the matplotlib fallback, which needs
    nothing beyond the raw data and always succeeds.
    """
    if plotly_fig is not None:
        png = fig_to_png_bytes(plotly_fig)
        if png:
            return png
    # matplotlib_fallback is a zero-arg callable that produces bytes
    try:
        return matplotlib_fallback()
    except Exception:
        return None


def _publication_figure_payloads(
    result: dict, diagnostics: dict,
) -> list[tuple[str, str, bytes]]:
    """Render the core publication figures as PNG bytes for Word/PDF embedding.

    Returns a list of (figure_id, caption, png_bytes). Prefers the
    Plotly export (kaleido + Chrome) for parity with the on-screen
    visuals, but falls back to matplotlib when Chrome is unavailable
    — so PDFs / Word docs always have their core figures embedded,
    even on Streamlit Community Cloud.
    """
    out: list[tuple[str, str, bytes]] = []

    # Wright map
    try:
        wright_fig = None
        try:
            facets = result.get("facets", {}) if isinstance(result, dict) else {}
            person_tbl = facets.get("person", pd.DataFrame()) if isinstance(facets, dict) else pd.DataFrame()
            facet_tbl = facets.get("others", pd.DataFrame()) if isinstance(facets, dict) else pd.DataFrame()
            step_tbl = result.get("steps", pd.DataFrame()) if isinstance(result, dict) else pd.DataFrame()
            wright_fig = _make_wright_map_export_figure(person_tbl, facet_tbl, step_tbl)
        except Exception:
            pass
        png = _plotly_or_matplotlib_png(
            wright_fig,
            lambda: _mpl_wright_map_png(result, diagnostics),
        )
        if png:
            out.append((
                "wright_map",
                "Wright map aligning person abilities and facet element measures on a common logit scale.",
                png,
            ))
    except Exception:  # pragma: no cover - figure helpers may refuse some inputs
        pass

    # Fit scatter (Infit vs Outfit)
    try:
        fit_fig = None
        measures = diagnostics.get("measures")
        if isinstance(measures, pd.DataFrame) and not measures.empty:
            try:
                fit_fig = _make_fit_scatter_export_figure(measures)
            except Exception:
                pass
        png = _plotly_or_matplotlib_png(
            fit_fig,
            lambda: _mpl_fit_scatter_png(diagnostics),
        )
        if png:
            out.append((
                "fit_scatter",
                "Infit vs Outfit mean-square statistics across facet elements (1.0 = expected).",
                png,
            ))
    except Exception:
        pass

    # Category probability curves
    try:
        first_plotly = None
        first_name = ""
        try:
            curve = build_category_probability_curve_data(result)
            avg_fig, level_fig = _make_category_probability_curve_figures(curve)
            first_plotly = avg_fig or level_fig
            meta = curve.get("metadata", {}) if isinstance(curve, dict) else {}
            first_name = str(meta.get("Scope", "Average")) if isinstance(meta, dict) else "Average"
        except Exception:
            first_plotly = None
            first_name = ""
        png = _plotly_or_matplotlib_png(
            first_plotly,
            lambda: _mpl_category_probability_png(result),
        )
        if png:
            label = first_name or "Average"
            out.append((
                f"category_curves_{label}",
                f"Category probability curves — {label}.",
                png,
            ))
    except Exception:
        pass

    # Facet distribution
    try:
        fd_fig = None
        try:
            fd_fig = _make_facet_distribution_export_figure(diagnostics.get("measures", pd.DataFrame()))
        except Exception:
            pass
        png = _plotly_or_matplotlib_png(
            fd_fig,
            lambda: _mpl_facet_distribution_png(diagnostics),
        )
        if png:
            out.append((
                "facet_distribution",
                "Facet distribution of element measures.",
                png,
            ))
    except Exception:
        pass

    return out


def _add_markdown_to_docx(document, markdown_text: str) -> None:
    """Render a minimal subset of markdown (headings, paragraphs, bullets,
    horizontal rules) into a python-docx Document. Anything we don't
    recognise falls through as a plain paragraph."""
    if not markdown_text:
        return
    lines = markdown_text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        if not stripped:
            i += 1
            continue
        if stripped.startswith("### "):
            document.add_heading(stripped[4:].strip(), level=3)
        elif stripped.startswith("## "):
            document.add_heading(stripped[3:].strip(), level=2)
        elif stripped.startswith("# "):
            document.add_heading(stripped[2:].strip(), level=1)
        elif stripped.startswith(("- ", "* ")):
            document.add_paragraph(stripped[2:].strip(), style="List Bullet")
        elif stripped == "---":
            document.add_paragraph("").add_run()  # blank spacer
        elif stripped.startswith("|") and "|" in stripped[1:]:
            # Minimal markdown table support: collect contiguous | rows
            table_rows = []
            while i < len(lines) and lines[i].strip().startswith("|"):
                row = [c.strip() for c in lines[i].strip().strip("|").split("|")]
                table_rows.append(row)
                i += 1
            # Drop markdown alignment row (---|---)
            table_rows = [r for r in table_rows if not all(set(c) <= set("-: ") for c in r)]
            if table_rows:
                cols = max(len(r) for r in table_rows)
                tbl = document.add_table(rows=len(table_rows), cols=cols)
                tbl.style = "Light Grid Accent 1"
                for r_idx, row in enumerate(table_rows):
                    for c_idx in range(cols):
                        tbl.cell(r_idx, c_idx).text = row[c_idx] if c_idx < len(row) else ""
            continue  # i already advanced past the table
        else:
            document.add_paragraph(stripped)
        i += 1


def _bias_table_for_publication(
    all_bias_results: dict | None,
    model: str | None,
) -> "pd.DataFrame | None":
    """Build a publication-ready bias / interaction table.

    Concatenates every facet pair in ``all_bias_results`` into one
    DataFrame. For GPCM fits the slope-aware Fisher information SE, the
    likelihood-ratio test, and the profile-likelihood CI columns are
    appended after the base bias / t / Prob. block; for RSM and PCM
    fits only the t-based screening columns are included because the
    chi-square pivotal pertains only to the slope-aware GPCM kernel
    (Wilks, 1938; Cox, 1975).
    """
    if not all_bias_results:
        return None
    parts: list[pd.DataFrame] = []
    for pair_key, bias_results in all_bias_results.items():
        if not isinstance(bias_results, dict) or "table" not in bias_results:
            continue
        tbl = bias_results["table"]
        if not isinstance(tbl, pd.DataFrame) or tbl.empty:
            continue
        rows = tbl.copy()
        rows.insert(0, "Pair", str(pair_key))
        parts.append(rows)
    if not parts:
        return None
    out = pd.concat(parts, ignore_index=True)
    base_cols = [
        "Pair", "FacetA_Level", "FacetB_Level",
        "Bias Size", "S.E.", "t", "d.f.", "Prob.",
    ]
    gpcm_cols = [
        "LR ChiSq", "LR Prob.",
        "Profile CI Lower", "Profile CI Upper", "Profile CI Status",
    ]
    cols = list(base_cols)
    if (model or "").upper() == "GPCM" and "LR ChiSq" in out.columns and pd.to_numeric(
        out["LR ChiSq"], errors="coerce"
    ).notna().any():
        cols.extend(gpcm_cols)
    cols = [c for c in cols if c in out.columns]
    return out[cols].copy()


def _bias_table_caption(model: str | None, table_idx: int) -> str:
    """Caption for the publication bias / interaction table.

    The GPCM caption cites Muraki (1993) for the slope-aware Fisher
    information identity, Wilks (1938) for the chi-square pivotal that
    underwrites the likelihood-ratio test, and Cox (1975) for the
    profile-likelihood confidence interval. The RSM / PCM caption stays
    in the original t-based screening framing (Myford & Wolfe, 2003).
    """
    if (model or "").upper() == "GPCM":
        return (
            f"Table {table_idx}. Bias / interaction analysis with slope-aware "
            "GPCM inference. Bias Size is the additive bias shift in logits; "
            "S.E. is the conditional Fisher information standard error "
            "sum_i a_i^2 * Var[X_i | eta_i + b_hat] * w_i (Muraki, 1993); "
            "LR ChiSq is the likelihood-ratio test of bias = 0 with one "
            "degree of freedom (Wilks, 1938); Profile CI is the 95% profile-"
            "likelihood confidence interval (Cox, 1975) holding theta, step "
            "thresholds, slopes, and other facet estimates fixed. These are "
            "screening inferences, not full joint-uncertainty intervals."
        )
    return (
        f"Table {table_idx}. Bias / interaction analysis. Bias Size is the "
        "additive bias shift in logits; S.E. is the conditional information "
        "standard error; t and Prob. are the t-test of bias = 0 (Myford & "
        "Wolfe, 2003). These cellwise statistics are screening prompts and "
        "do not propagate uncertainty from the rest of the fitted model."
    )


def _add_dataframe_to_docx(document, df: "pd.DataFrame", caption: str | None = None) -> None:
    """Render a pandas DataFrame as a Word table (with optional caption above)."""
    if not isinstance(df, pd.DataFrame) or df.empty:
        return
    if caption:
        p = document.add_paragraph()
        run = p.add_run(caption)
        run.italic = True
    # Cap very wide / long tables so the Word file stays reasonable
    display = df.copy()
    n_cols_full, n_rows_full = len(display.columns), len(display)
    if len(display.columns) > 12:
        display = display.iloc[:, :12]
    if len(display) > 60:
        display = display.head(60)
    tbl = document.add_table(rows=len(display) + 1, cols=len(display.columns))
    tbl.style = "Light Grid Accent 1"
    for j, col in enumerate(display.columns):
        tbl.cell(0, j).text = str(col)
    for i_row, (_, row) in enumerate(display.iterrows(), start=1):
        for j, col in enumerate(display.columns):
            value = row[col]
            if isinstance(value, float):
                tbl.cell(i_row, j).text = f"{value:.3f}"
            else:
                tbl.cell(i_row, j).text = str(value)
    if len(display.columns) < n_cols_full or len(display) < n_rows_full:
        note_p = document.add_paragraph()
        note_p.add_run(
            f"Table truncated to the first {len(display)} of {n_rows_full} rows "
            f"and {len(display.columns)} of {n_cols_full} columns; the full table "
            "is in the Downloads bundle."
        ).italic = True


def build_publication_word_bytes(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> bytes:
    """Build a manuscript-ready Word (.docx) document as bytes.

    Raises RuntimeError if python-docx is unavailable (callers should catch
    and show an install hint). Figure / table embeds that fail are silently
    skipped so the document always assembles.
    """
    try:
        from docx import Document
        from docx.shared import Inches
    except ImportError as exc:
        raise RuntimeError(
            "python-docx is not installed. Add `python-docx>=1.0` to "
            "requirements.txt and reinstall."
        ) from exc
    import io as _io

    document = Document()
    config = result.get("config", {}) if isinstance(result, dict) else {}
    prep = result.get("prep", {}) if isinstance(result, dict) else {}

    # --- Title + auto-abstract ---
    model_name = str(config.get("model", "MFRM"))
    method_name = str(config.get("method", "estimation"))
    n_obs = prep.get("n_obs", "?")
    n_person = prep.get("n_person", "?")
    facet_names = config.get("facet_names", [])

    document.add_heading("Many-Facet Rasch Measurement analysis", level=0)
    abstract = document.add_paragraph()
    abstract.add_run("Abstract. ").bold = True
    abstract.add_run(
        f"This document reports a {model_name} analysis estimated via {method_name} "
        f"on {n_obs} observations from {n_person} persons across "
        f"{len(facet_names)} facets ({', '.join(map(str, facet_names)) or 'none'}). "
        "The sections below follow the APA 7 reporting layout: exhaustive Methods, "
        "Results with embedded figures and tables, and a references list. "
        "All content is auto-generated from the current analysis configuration; "
        "edit freely for your manuscript."
    )

    # --- Methods (reuse existing narrative generator) ---
    methods_text = ""
    try:
        methods_text = generate_method_appendix_text(result, diagnostics, all_bias_results)
    except Exception:
        methods_text = "# Methods\n\n(Method appendix could not be generated for this run.)"
    _add_markdown_to_docx(document, methods_text)

    # --- Manuscript template (Methods + Results narrative) ---
    document.add_page_break()
    manuscript_text = ""
    try:
        manuscript_text = generate_manuscript_reporting_template(result, diagnostics, all_bias_results)
    except Exception:
        manuscript_text = "# Results\n\n(Manuscript template could not be generated for this run.)"
    _add_markdown_to_docx(document, manuscript_text)

    # --- Core results tables ---
    document.add_heading("Results tables", level=1)
    table_idx = 1
    measures = diagnostics.get("measures") if isinstance(diagnostics, dict) else None
    if isinstance(measures, pd.DataFrame) and not measures.empty:
        _add_dataframe_to_docx(
            document, measures.round(3),
            caption=f"Table {table_idx}. Element measures, standard errors, and fit statistics.",
        )
        table_idx += 1
    reliability = diagnostics.get("reliability") if isinstance(diagnostics, dict) else None
    if isinstance(reliability, pd.DataFrame) and not reliability.empty:
        _add_dataframe_to_docx(
            document, reliability.round(3),
            caption=f"Table {table_idx}. Reliability and separation by facet.",
        )
        table_idx += 1
    bias_publication_tbl = _bias_table_for_publication(all_bias_results, config.get("model"))
    if bias_publication_tbl is not None and not bias_publication_tbl.empty:
        _add_dataframe_to_docx(
            document, bias_publication_tbl.round(3),
            caption=_bias_table_caption(config.get("model"), table_idx),
        )
        table_idx += 1

    # --- Embedded figures ---
    figures = _publication_figure_payloads(result, diagnostics)
    if figures:
        document.add_heading("Figures", level=1)
        for idx, (fig_id, caption, png) in enumerate(figures, start=1):
            buf = _io.BytesIO(png)
            try:
                document.add_picture(buf, width=Inches(6))
            except Exception as exc:
                note = document.add_paragraph()
                note.add_run(
                    f"Figure {idx}. {caption} — could not be embedded "
                    f"({type(exc).__name__}); regenerate it from the Visuals tab."
                ).italic = True
                continue
            p = document.add_paragraph()
            p.add_run(f"Figure {idx}. {caption}").italic = True

    # --- References ---
    document.add_page_break()
    document.add_heading("References", level=1)
    narrative_for_refs = (methods_text or "") + "\n" + (manuscript_text or "")
    refs = build_apa_reference_list(
        narrative_for_refs,
        always_include=_PUBLICATION_DOCUMENT_CORE_REFS,
    )
    if refs:
        for ref in refs:
            p = document.add_paragraph(ref)
            p.paragraph_format.first_line_indent = Inches(-0.5)
            p.paragraph_format.left_indent = Inches(0.5)
    else:
        document.add_paragraph("(No references cited in the current narrative.)")

    out = _io.BytesIO()
    document.save(out)
    return out.getvalue()


# ---------------------------------------------------------------------------
# PDF publication document builder (reportlab)
# ---------------------------------------------------------------------------
# Same content as the Word builder, rendered as a flowable PDF via
# reportlab's platypus stack. Per the earlier decision the PDF excludes
# the reproducibility code appendix that the Word version carries —
# users who need the code path should use the Word export (or the
# Downloads tab zip).

def _pdf_markdown_to_flowables(markdown_text: str, styles):
    """Convert a minimal subset of markdown into reportlab flowables.

    Handles headings (`#`, `##`, `###`), paragraphs, bullet lists,
    horizontal rules. Markdown tables are rendered as a monospaced
    block for readability (full table styling is reserved for core
    result tables passed via _pdf_dataframe_flowable).
    """
    from reportlab.platypus import Paragraph, Spacer
    flowables = []
    if not markdown_text:
        return flowables
    lines = markdown_text.splitlines()
    for raw in lines:
        line = raw.rstrip()
        if not line.strip():
            flowables.append(Spacer(1, 6))
            continue
        if line.startswith("### "):
            flowables.append(Paragraph(line[4:].strip(), styles["Heading3"]))
        elif line.startswith("## "):
            flowables.append(Paragraph(line[3:].strip(), styles["Heading2"]))
        elif line.startswith("# "):
            flowables.append(Paragraph(line[2:].strip(), styles["Heading1"]))
        elif line.startswith(("- ", "* ")):
            flowables.append(Paragraph(f"• {line[2:].strip()}", styles["BodyText"]))
        elif line.strip() == "---":
            flowables.append(Spacer(1, 10))
        elif line.startswith("|"):
            # Monospaced fallback for markdown tables
            flowables.append(Paragraph(f"<font face='Courier'>{line}</font>", styles["BodyText"]))
        else:
            # Reportlab uses simple HTML-ish markup for inline formatting;
            # escape existing <> so the markdown source doesn't break the parser.
            safe = line.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            flowables.append(Paragraph(safe, styles["BodyText"]))
    return flowables


def _pdf_dataframe_flowable(df: "pd.DataFrame", caption: str | None = None):
    """Render a DataFrame as a reportlab Table flowable."""
    from reportlab.platypus import Paragraph, Spacer, Table, TableStyle
    from reportlab.lib import colors
    from reportlab.lib.styles import getSampleStyleSheet

    if not isinstance(df, pd.DataFrame) or df.empty:
        return []
    styles = getSampleStyleSheet()
    display = df.copy()
    n_cols_full, n_rows_full = len(display.columns), len(display)
    if len(display.columns) > 10:
        display = display.iloc[:, :10]
    if len(display) > 50:
        display = display.head(50)
    # Round floats for compactness
    for col in display.columns:
        if pd.api.types.is_float_dtype(display[col]):
            display[col] = display[col].round(3)

    rows = [list(display.columns)]
    for _, row in display.iterrows():
        rows.append([str(v) for v in row.tolist()])
    tbl = Table(rows, repeatRows=1)
    tbl.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#D9E1F2")),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.black),
        ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
        ("FONTSIZE", (0, 0), (-1, -1), 8),
        ("GRID", (0, 0), (-1, -1), 0.25, colors.grey),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
    ]))
    out = []
    if caption:
        out.append(Paragraph(f"<i>{caption}</i>", styles["BodyText"]))
        out.append(Spacer(1, 4))
    out.append(tbl)
    out.append(Spacer(1, 10))
    if len(display.columns) < n_cols_full or len(display) < n_rows_full:
        out.append(Paragraph(
            f"<i>Table truncated to the first {len(display)} of {n_rows_full} rows "
            f"and {len(display.columns)} of {n_cols_full} columns; the full table is "
            f"in the Downloads bundle.</i>",
            styles["BodyText"],
        ))
        out.append(Spacer(1, 6))
    return out


def build_publication_pdf_bytes(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> bytes:
    """Build a manuscript-ready PDF document as bytes.

    Raises RuntimeError if reportlab is unavailable. Figure embeds that fail
    leave a visible note (rather than being silently dropped), and oversized
    tables are capped with a truncation note, so the document always assembles.
    """
    try:
        from reportlab.lib.pagesizes import LETTER
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.units import inch
        from reportlab.platypus import (
            Image,
            PageBreak,
            Paragraph,
            SimpleDocTemplate,
            Spacer,
        )
    except ImportError as exc:
        raise RuntimeError(
            "reportlab is not installed. Add `reportlab>=4.0` to "
            "requirements.txt and reinstall."
        ) from exc
    import io as _io

    config = result.get("config", {}) if isinstance(result, dict) else {}
    prep = result.get("prep", {}) if isinstance(result, dict) else {}

    model_name = str(config.get("model", "MFRM"))
    method_name = str(config.get("method", "estimation"))
    n_obs = prep.get("n_obs", "?")
    n_person = prep.get("n_person", "?")
    facet_names = config.get("facet_names", [])

    buf = _io.BytesIO()
    doc = SimpleDocTemplate(
        buf, pagesize=LETTER,
        topMargin=0.75 * inch, bottomMargin=0.75 * inch,
        leftMargin=0.85 * inch, rightMargin=0.85 * inch,
        title="MFRM publication document",
    )
    styles = getSampleStyleSheet()
    # Custom title style
    styles.add(ParagraphStyle(
        name="DocTitle",
        parent=styles["Title"],
        fontSize=18,
        spaceAfter=12,
    ))

    story: list = []

    # --- Title ---
    story.append(Paragraph("Many-Facet Rasch Measurement analysis", styles["DocTitle"]))
    story.append(Spacer(1, 6))

    # --- Abstract ---
    abstract_text = (
        f"<b>Abstract.</b> This document reports a {model_name} analysis "
        f"estimated via {method_name} on {n_obs} observations from "
        f"{n_person} persons across {len(facet_names)} facets "
        f"({', '.join(map(str, facet_names)) or 'none'}). "
        "Sections below follow the APA 7 reporting layout: exhaustive "
        "Methods, Results with embedded figures and tables, and a "
        "references list. All content is auto-generated from the current "
        "analysis configuration; edit freely for your manuscript."
    )
    story.append(Paragraph(abstract_text, styles["BodyText"]))
    story.append(Spacer(1, 12))

    # --- Methods ---
    methods_text = ""
    try:
        methods_text = generate_method_appendix_text(result, diagnostics, all_bias_results)
    except Exception:
        methods_text = "# Methods\n\n(Method appendix could not be generated for this run.)"
    story.extend(_pdf_markdown_to_flowables(methods_text, styles))

    # --- Manuscript template ---
    story.append(PageBreak())
    manuscript_text = ""
    try:
        manuscript_text = generate_manuscript_reporting_template(result, diagnostics, all_bias_results)
    except Exception:
        manuscript_text = "# Results\n\n(Manuscript template could not be generated for this run.)"
    story.extend(_pdf_markdown_to_flowables(manuscript_text, styles))

    # --- Results tables ---
    story.append(Paragraph("Results tables", styles["Heading1"]))
    table_idx = 1
    measures = diagnostics.get("measures") if isinstance(diagnostics, dict) else None
    if isinstance(measures, pd.DataFrame) and not measures.empty:
        story.extend(_pdf_dataframe_flowable(
            measures,
            caption=f"Table {table_idx}. Element measures, standard errors, and fit statistics.",
        ))
        table_idx += 1
    reliability = diagnostics.get("reliability") if isinstance(diagnostics, dict) else None
    if isinstance(reliability, pd.DataFrame) and not reliability.empty:
        story.extend(_pdf_dataframe_flowable(
            reliability,
            caption=f"Table {table_idx}. Reliability and separation by facet.",
        ))
        table_idx += 1
    bias_publication_tbl = _bias_table_for_publication(all_bias_results, config.get("model"))
    if bias_publication_tbl is not None and not bias_publication_tbl.empty:
        story.extend(_pdf_dataframe_flowable(
            bias_publication_tbl,
            caption=_bias_table_caption(config.get("model"), table_idx),
        ))
        table_idx += 1

    # --- Figures ---
    figures = _publication_figure_payloads(result, diagnostics)
    if figures:
        story.append(PageBreak())
        story.append(Paragraph("Figures", styles["Heading1"]))
        for idx, (fig_id, caption, png) in enumerate(figures, start=1):
            try:
                img_buf = _io.BytesIO(png)
                story.append(Image(img_buf, width=6.0 * inch, height=4.0 * inch, kind="proportional"))
            except Exception as exc:
                story.append(Paragraph(
                    f"<i>Figure {idx}. {caption} — could not be embedded "
                    f"({type(exc).__name__}); regenerate it from the Visuals tab.</i>",
                    styles["BodyText"],
                ))
                continue
            story.append(Paragraph(f"<i>Figure {idx}. {caption}</i>", styles["BodyText"]))
            story.append(Spacer(1, 10))

    # --- References ---
    story.append(PageBreak())
    story.append(Paragraph("References", styles["Heading1"]))
    narrative_for_refs = (methods_text or "") + "\n" + (manuscript_text or "")
    refs = build_apa_reference_list(
        narrative_for_refs,
        always_include=_PUBLICATION_DOCUMENT_CORE_REFS,
    )
    if refs:
        # Hanging-indent style (APA 7)
        ref_style = ParagraphStyle(
            name="APARef",
            parent=styles["BodyText"],
            firstLineIndent=-18,
            leftIndent=18,
            spaceAfter=6,
        )
        for ref in refs:
            safe = ref.replace("&", "&amp;")
            story.append(Paragraph(safe, ref_style))
    else:
        story.append(Paragraph("(No references cited in the current narrative.)", styles["BodyText"]))

    doc.build(story)
    return buf.getvalue()


# ---------------------------------------------------------------------------
# HTML publication document builder (stdlib only)
# ---------------------------------------------------------------------------

def _html_escape(text: str) -> str:
    return (
        text.replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
    )


def _markdown_to_html(markdown_text: str) -> str:
    """Minimal markdown → HTML converter used by the HTML publication
    document. Handles headings, paragraphs, bullet lists, horizontal
    rules, and markdown tables (pipe-delimited)."""
    if not markdown_text:
        return ""
    lines = markdown_text.splitlines()
    out: list[str] = []
    i = 0
    in_list = False
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        if not stripped:
            if in_list:
                out.append("</ul>")
                in_list = False
            i += 1
            continue
        if stripped == "---":
            if in_list:
                out.append("</ul>")
                in_list = False
            out.append("<hr/>")
            i += 1
            continue
        if stripped.startswith("### "):
            if in_list:
                out.append("</ul>")
                in_list = False
            out.append(f"<h3>{_html_escape(stripped[4:].strip())}</h3>")
        elif stripped.startswith("## "):
            if in_list:
                out.append("</ul>")
                in_list = False
            out.append(f"<h2>{_html_escape(stripped[3:].strip())}</h2>")
        elif stripped.startswith("# "):
            if in_list:
                out.append("</ul>")
                in_list = False
            out.append(f"<h1>{_html_escape(stripped[2:].strip())}</h1>")
        elif stripped.startswith(("- ", "* ")):
            if not in_list:
                out.append("<ul>")
                in_list = True
            out.append(f"<li>{_html_escape(stripped[2:].strip())}</li>")
        elif stripped.startswith("|"):
            if in_list:
                out.append("</ul>")
                in_list = False
            rows: list[list[str]] = []
            while i < len(lines) and lines[i].strip().startswith("|"):
                cells = [c.strip() for c in lines[i].strip().strip("|").split("|")]
                rows.append(cells)
                i += 1
            rows = [r for r in rows if not all(set(c) <= set("-: ") for c in r)]
            if rows:
                out.append("<table>")
                for r_idx, row in enumerate(rows):
                    tag = "th" if r_idx == 0 else "td"
                    out.append("<tr>" + "".join(f"<{tag}>{_html_escape(c)}</{tag}>" for c in row) + "</tr>")
                out.append("</table>")
            continue
        else:
            if in_list:
                out.append("</ul>")
                in_list = False
            out.append(f"<p>{_html_escape(stripped)}</p>")
        i += 1
    if in_list:
        out.append("</ul>")
    return "\n".join(out)


_PUBLICATION_HTML_STYLE = """
<style>
  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
         max-width: 820px; margin: 2em auto; padding: 0 1em; line-height: 1.55; color: #222; }
  h1 { font-size: 1.9em; border-bottom: 2px solid #1b9e77; padding-bottom: 0.25em; }
  h2 { font-size: 1.4em; color: #1b9e77; margin-top: 1.8em; }
  h3 { font-size: 1.15em; color: #555; }
  table { border-collapse: collapse; margin: 1em 0; font-size: 0.92em; }
  th, td { border: 1px solid #bbb; padding: 4px 8px; text-align: left; }
  th { background: #e9eef5; }
  hr { border: none; border-top: 1px solid #ccc; margin: 1.5em 0; }
  .abstract { background: #f5f7fa; padding: 0.8em 1em; border-left: 4px solid #1b9e77; margin: 1em 0; }
  .figure-caption { font-style: italic; font-size: 0.9em; color: #555; margin: 0.3em 0 1.5em 0; }
  .ref { text-indent: -1.5em; padding-left: 1.5em; margin-bottom: 0.4em; }
</style>
"""


def build_publication_html_bytes(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> bytes:
    """Build a manuscript-ready HTML document as UTF-8 bytes (no JS, no external assets)."""
    config = result.get("config", {}) if isinstance(result, dict) else {}
    prep = result.get("prep", {}) if isinstance(result, dict) else {}
    model_name = str(config.get("model", "MFRM"))
    method_name = str(config.get("method", "estimation"))
    n_obs = prep.get("n_obs", "?")
    n_person = prep.get("n_person", "?")
    facet_names = config.get("facet_names", [])

    try:
        methods_text = generate_method_appendix_text(result, diagnostics, all_bias_results)
    except Exception:
        methods_text = "# Methods\n\n(Method appendix could not be generated for this run.)"
    try:
        manuscript_text = generate_manuscript_reporting_template(result, diagnostics, all_bias_results)
    except Exception:
        manuscript_text = "# Results\n\n(Manuscript template could not be generated for this run.)"

    narrative_for_refs = (methods_text or "") + "\n" + (manuscript_text or "")
    refs = build_apa_reference_list(
        narrative_for_refs, always_include=_PUBLICATION_DOCUMENT_CORE_REFS,
    )

    # Tables rendered as HTML via pandas (escape-safe)
    measures = diagnostics.get("measures") if isinstance(diagnostics, dict) else None
    reliability = diagnostics.get("reliability") if isinstance(diagnostics, dict) else None
    table_idx = 1
    measures_html = ""
    if isinstance(measures, pd.DataFrame) and not measures.empty:
        measures_html = (
            f"<h2>Table {table_idx}. Element measures, standard errors, and fit statistics</h2>\n"
            + measures.round(3).to_html(index=False, border=0)
        )
        table_idx += 1
    reliability_html = ""
    if isinstance(reliability, pd.DataFrame) and not reliability.empty:
        reliability_html = (
            f"<h2>Table {table_idx}. Reliability and separation by facet</h2>\n"
            + reliability.round(3).to_html(index=False, border=0)
        )
        table_idx += 1
    bias_publication_tbl = _bias_table_for_publication(all_bias_results, config.get("model"))
    bias_html = ""
    if bias_publication_tbl is not None and not bias_publication_tbl.empty:
        bias_caption = _bias_table_caption(config.get("model"), table_idx)
        bias_html = (
            f"<h2>{_html_escape(bias_caption)}</h2>\n"
            + bias_publication_tbl.round(3).to_html(index=False, border=0)
        )
        table_idx += 1

    # Embed figures as base64 PNG so the HTML stays self-contained
    import base64
    figures = _publication_figure_payloads(result, diagnostics)
    figures_html = ""
    if figures:
        figures_html = "<h2>Figures</h2>\n"
        for idx, (fig_id, caption, png) in enumerate(figures, start=1):
            b64 = base64.b64encode(png).decode("ascii")
            figures_html += (
                f'<figure><img src="data:image/png;base64,{b64}" '
                f'alt="{_html_escape(caption)}" style="max-width:100%;"/>'
                f'<figcaption class="figure-caption">Figure {idx}. {_html_escape(caption)}</figcaption></figure>\n'
            )

    refs_html = ""
    if refs:
        refs_html = "<h2>References</h2>\n" + "\n".join(
            f'<p class="ref">{_html_escape(r)}</p>' for r in refs
        )

    body = f"""
<h1>Many-Facet Rasch Measurement analysis</h1>
<div class="abstract">
  <strong>Abstract.</strong> This document reports a {_html_escape(model_name)} analysis
  estimated via {_html_escape(method_name)} on {n_obs} observations from {n_person}
  persons across {len(facet_names)} facets
  ({_html_escape(', '.join(map(str, facet_names)) or 'none')}).
  The sections below follow the APA 7 reporting layout: exhaustive Methods,
  Results with embedded figures and tables, and a references list.
  All content is auto-generated from the current analysis configuration;
  edit freely for your manuscript.
</div>
{_markdown_to_html(methods_text)}
<hr/>
{_markdown_to_html(manuscript_text)}
{measures_html}
{reliability_html}
{bias_html}
{figures_html}
{refs_html}
"""
    html = (
        "<!DOCTYPE html>\n<html lang='en'><head><meta charset='utf-8'/>"
        "<title>MFRM publication document</title>"
        + _PUBLICATION_HTML_STYLE
        + "</head><body>\n" + body + "\n</body></html>"
    )
    return html.encode("utf-8")


# ---------------------------------------------------------------------------
# Report-tab section: Publication Document (Word / PDF / HTML)
# ---------------------------------------------------------------------------

def _render_publication_document_section(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> None:
    """Render the download buttons for the Word / PDF / HTML publication docs."""
    st.subheader("Publication Document")
    st.caption(
        "Download a manuscript-ready document combining the auto-generated "
        "abstract, an exhaustive Methods section, results tables, embedded "
        "figures, and an APA 7 reference list. Choose the format that fits "
        "your workflow: Word for further editing, PDF for sharing, HTML for web."
    )

    # v0.2.10-beta: one-click downloads for all three formats. Each
    # format is built lazily on first entry to this tab and cached in
    # session_state keyed by a fingerprint of the current run; subsequent
    # sidebar reruns reuse the cached bytes so only genuinely new runs
    # trigger a rebuild. The PDF button is promoted to `type="primary"`
    # because the user explicitly asked for the PDF to be the easy path.

    # Fingerprint the current run so cache invalidates only when the
    # underlying results actually change, not on every sidebar rerun.
    try:
        _run_fp = stable_json_fingerprint({
            "config": result.get("config", {}),
            "prep": result.get("prep", {}),
            "summary_len": len(result.get("summary", pd.DataFrame())),
            "measures_len": len(diagnostics.get("measures", pd.DataFrame())),
        })
    except Exception:
        _run_fp = f"no_fp_{id(result)}"

    def _cached_build(
        label: str, kind: str, builder, allow_runtime_error: bool = True,
    ) -> tuple[bytes | None, str | None]:
        """Build document bytes or pull them from session_state cache."""
        cache_key = f"_publication_doc_{kind}_bytes"
        fp_key = f"_publication_doc_{kind}_fp"
        if (
            cache_key in st.session_state
            and st.session_state.get(fp_key) == _run_fp
        ):
            return st.session_state[cache_key], None
        try:
            with st.spinner(f"Building {label}…"):
                data = builder(result, diagnostics, all_bias_results)
            st.session_state[cache_key] = data
            st.session_state[fp_key] = _run_fp
            return data, None
        except RuntimeError as exc:
            if allow_runtime_error:
                return None, f"{label} export unavailable: {exc}"
            raise
        except Exception as exc:  # pragma: no cover
            return None, f"{label} build failed: {exc}"

    col_w, col_p, col_h = st.columns(3)

    with col_w:
        word_bytes, word_err = _cached_build(
            "Word", "word", build_publication_word_bytes,
        )
        if word_bytes is not None:
            st.download_button(
                "Download Word (.docx)",
                data=word_bytes,
                file_name="mfrm_publication_document.docx",
                mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                key="publication_doc_word_dl",
                use_container_width=True,
                help="Editable manuscript with tables + embedded figures.",
            )
        elif word_err:
            st.caption(str(word_err))

    with col_p:
        pdf_bytes, pdf_err = _cached_build(
            "PDF", "pdf", build_publication_pdf_bytes,
        )
        if pdf_bytes is not None:
            st.download_button(
                "Download PDF (with plots)",
                data=pdf_bytes,
                file_name="mfrm_publication_document.pdf",
                mime="application/pdf",
                key="publication_doc_pdf_dl",
                use_container_width=True,
                type="primary",
                help=(
                    "Letter-size PDF with Methods, tables, embedded figures "
                    "(Wright map, Fit scatter, Category probability, Facet "
                    "distribution), and APA 7 references."
                ),
            )
        elif pdf_err:
            st.caption(str(pdf_err))

    with col_h:
        html_bytes, html_err = _cached_build(
            "HTML", "html", build_publication_html_bytes,
        )
        if html_bytes is not None:
            st.download_button(
                "Download HTML",
                data=html_bytes,
                file_name="mfrm_publication_document.html",
                mime="text/html",
                key="publication_doc_html_dl",
                use_container_width=True,
                help="Self-contained HTML page (no external assets).",
            )
        elif html_err:
            st.caption(str(html_err))

    st.caption(
        "All three formats share the same narrative source — content "
        "is identical. Word = editable, PDF = print-ready (with embedded "
        "plots), HTML = self-contained and works offline."
    )


