def _status_from_bool(ok: bool, *, missing: bool = False) -> str:
    if missing:
        return "Missing"
    return "Ready" if ok else "Review"


def _readiness_row(check, status, evidence, action, required=True):
    return {
        "Check": check,
        "Status": status,
        "Evidence": evidence,
        "ActionBeforeFinalReport": action,
        "Required": "Yes" if required else "No",
    }


MML_PRIOR_SENSITIVITY_DEFAULT_MULTIPLIERS = (0.5, 0.75, 1.0, 1.25, 1.5, 2.0)
MML_PRIOR_SENSITIVITY_STABILITY_RULES = {
    "max_abs_measure_shift": 0.25,
    "measure_rmse": 0.10,
    "rank_correlation": 0.98,
    "population_coefficient_shift": 0.10,
}


def build_mml_prior_sensitivity_plan(
    result: dict,
    multipliers=MML_PRIOR_SENSITIVITY_DEFAULT_MULTIPLIERS,
) -> pd.DataFrame:
    """Recommended fixed-prior-SD sensitivity reruns for MML reports."""
    config = (result or {}).get("config", {}) or {}
    if config.get("method") != "MML":
        return pd.DataFrame()
    try:
        base_sd = float(config.get("population_prior_sd") or 1.0)
    except Exception:
        base_sd = 1.0
    if not np.isfinite(base_sd) or base_sd <= 0:
        base_sd = 1.0
    pop = config.get("population_model", {})
    latent_regression = bool(isinstance(pop, dict) and pop.get("enabled"))
    rows = []
    seen: set[float] = set()
    for mult in multipliers:
        try:
            sd = float(base_sd) * float(mult)
        except Exception:
            continue
        if not np.isfinite(sd) or sd <= 0:
            continue
        sd_key = round(sd, 8)
        if sd_key in seen:
            continue
        seen.add(sd_key)
        rows.append({
            "PopulationPriorSD": sd,
            "Multiplier": float(mult),
            "Role": "current fitted value" if abs(float(mult) - 1.0) < 1e-12 else "sensitivity rerun",
            "RunStatus": "Already fit" if abs(float(mult) - 1.0) < 1e-12 else "Not run",
            "RequiredBeforeClaim": (
                "Yes for population-scale or latent-regression claims"
                if latent_regression else
                "Recommended for final MML claims"
            ),
            "PrimaryComparisons": (
                "Compare log-likelihood/AIC/BIC, person EAP shifts, non-person "
                "facet shifts, rank correlations, strict marginal diagnostics, "
                "and latent-regression coefficients when present."
            ),
            "DecisionRule": (
                "Review if max |measure shift| > "
                f"{MML_PRIOR_SENSITIVITY_STABILITY_RULES['max_abs_measure_shift']:.2f} logits, "
                "measure RMSE > "
                f"{MML_PRIOR_SENSITIVITY_STABILITY_RULES['measure_rmse']:.2f}, "
                "rank correlation < "
                f"{MML_PRIOR_SENSITIVITY_STABILITY_RULES['rank_correlation']:.2f}, "
                "or population coefficient shift > "
                f"{MML_PRIOR_SENSITIVITY_STABILITY_RULES['population_coefficient_shift']:.2f}."
            ),
            "Purpose": (
                "Check whether facet ordering, person EAP distribution, "
                "latent-regression coefficients, and marginal diagnostics are "
                "stable to the fixed population prior SD."
            ),
            "Boundary": (
                "This app fixes population_prior_sd during MML quadrature; the "
                "latent variance is not estimated as a free model parameter."
            ),
        })
    return pd.DataFrame(rows)


def _mml_prior_sensitivity_measure_long(result: dict) -> pd.DataFrame:
    """Return Person + non-person estimates in one comparable long table."""
    if not isinstance(result, dict):
        return pd.DataFrame()
    frames: list[pd.DataFrame] = []
    person = result.get("facets", {}).get("person", pd.DataFrame())
    if isinstance(person, pd.DataFrame) and not person.empty and {"Person", "Estimate"}.issubset(person.columns):
        frames.append(pd.DataFrame({
            "Facet": "Person",
            "Level": person["Person"].astype(str),
            "Estimate": pd.to_numeric(person["Estimate"], errors="coerce"),
        }))
    others = result.get("facets", {}).get("others", pd.DataFrame())
    if isinstance(others, pd.DataFrame) and not others.empty and {"Facet", "Level", "Estimate"}.issubset(others.columns):
        frames.append(pd.DataFrame({
            "Facet": others["Facet"].astype(str),
            "Level": others["Level"].astype(str),
            "Estimate": pd.to_numeric(others["Estimate"], errors="coerce"),
        }))
    if not frames:
        return pd.DataFrame(columns=["Facet", "Level", "Estimate"])
    out = pd.concat(frames, ignore_index=True)
    return out.dropna(subset=["Estimate"]).reset_index(drop=True)


def _mml_prior_sensitivity_population_long(result: dict) -> pd.DataFrame:
    pop = (result or {}).get("population", {}) if isinstance(result, dict) else {}
    coef = pop.get("coefficients", pd.DataFrame()) if isinstance(pop, dict) else pd.DataFrame()
    if not isinstance(coef, pd.DataFrame) or coef.empty or not {"Term", "Estimate"}.issubset(coef.columns):
        return pd.DataFrame(columns=["Term", "Estimate"])
    return pd.DataFrame({
        "Term": coef["Term"].astype(str),
        "Estimate": pd.to_numeric(coef["Estimate"], errors="coerce"),
    }).dropna(subset=["Estimate"]).reset_index(drop=True)


def _mml_prior_sensitivity_summary_row(
    run: dict | None,
    *,
    population_prior_sd: float,
    base_sd: float,
    source: str,
    run_ok: bool,
    error: str = "",
) -> dict:
    summary = run.get("summary", pd.DataFrame()) if isinstance(run, dict) else pd.DataFrame()
    srow = summary.iloc[0] if isinstance(summary, pd.DataFrame) and not summary.empty else {}
    measures = _mml_prior_sensitivity_measure_long(run or {})
    persons = measures[measures["Facet"] == "Person"] if not measures.empty else pd.DataFrame()
    non_person = measures[measures["Facet"] != "Person"] if not measures.empty else pd.DataFrame()
    pop = _mml_prior_sensitivity_population_long(run or {})
    opt = run.get("opt") if isinstance(run, dict) else None
    converged = bool(getattr(opt, "success", False))
    if isinstance(srow, pd.Series) and "Converged" in srow.index:
        converged = bool(srow.get("Converged"))
    return {
        "PopulationPriorSD": float(population_prior_sd),
        "BasePopulationPriorSD": float(base_sd),
        "Multiplier": float(population_prior_sd / base_sd) if base_sd > 0 else np.nan,
        "Role": "current fitted value" if abs(float(population_prior_sd) - float(base_sd)) < 1e-10 else "sensitivity rerun",
        "Source": source,
        "RunOK": bool(run_ok),
        "Converged": converged if run_ok else False,
        "LogLik": float(srow.get("LogLik", np.nan)) if isinstance(srow, pd.Series) else np.nan,
        "AIC": float(srow.get("AIC", np.nan)) if isinstance(srow, pd.Series) else np.nan,
        "BIC": float(srow.get("BIC", np.nan)) if isinstance(srow, pd.Series) else np.nan,
        "KParams": int(srow.get("KParams", 0)) if isinstance(srow, pd.Series) and pd.notna(srow.get("KParams", np.nan)) else 0,
        "N": float(srow.get("N", np.nan)) if isinstance(srow, pd.Series) else np.nan,
        "Iterations": int(srow.get("Iterations", 0)) if isinstance(srow, pd.Series) and pd.notna(srow.get("Iterations", np.nan)) else 0,
        "GradientNorm": float(srow.get("GradientNorm", np.nan)) if isinstance(srow, pd.Series) else np.nan,
        "ElapsedSeconds": float(srow.get("ElapsedSeconds", np.nan)) if isinstance(srow, pd.Series) else np.nan,
        "PersonEstimateMean": float(persons["Estimate"].mean()) if not persons.empty else np.nan,
        "PersonEstimateSD": float(persons["Estimate"].std(ddof=1)) if len(persons) > 1 else np.nan,
        "NonPersonEstimateMean": float(non_person["Estimate"].mean()) if not non_person.empty else np.nan,
        "NonPersonEstimateSD": float(non_person["Estimate"].std(ddof=1)) if len(non_person) > 1 else np.nan,
        "PopulationCoefficientMaxAbs": float(pop["Estimate"].abs().max()) if not pop.empty else np.nan,
        "Error": str(error)[:500],
    }


def _mml_prior_sensitivity_measure_deltas(
    base_result: dict,
    run: dict,
    *,
    population_prior_sd: float,
    base_sd: float,
) -> pd.DataFrame:
    base = _mml_prior_sensitivity_measure_long(base_result)
    other = _mml_prior_sensitivity_measure_long(run)
    if base.empty or other.empty:
        return pd.DataFrame()
    merged = base.merge(
        other,
        on=["Facet", "Level"],
        how="inner",
        suffixes=("_Base", "_Sensitivity"),
    )
    if merged.empty:
        return pd.DataFrame()
    merged["Difference"] = merged["Estimate_Sensitivity"] - merged["Estimate_Base"]
    rows = []
    for facet, sub in merged.groupby("Facet", dropna=False, observed=False):
        diff = pd.to_numeric(sub["Difference"], errors="coerce")
        base_est = pd.to_numeric(sub["Estimate_Base"], errors="coerce")
        sens_est = pd.to_numeric(sub["Estimate_Sensitivity"], errors="coerce")
        ok = np.isfinite(diff) & np.isfinite(base_est) & np.isfinite(sens_est)
        if not ok.any():
            continue
        corr = float(np.corrcoef(base_est[ok], sens_est[ok])[0, 1]) if int(ok.sum()) > 1 else np.nan
        rank_corr = (
            float(base_est[ok].rank(method="average").corr(sens_est[ok].rank(method="average")))
            if int(ok.sum()) > 1 else np.nan
        )
        rows.append({
            "PopulationPriorSD": float(population_prior_sd),
            "BasePopulationPriorSD": float(base_sd),
            "Multiplier": float(population_prior_sd / base_sd) if base_sd > 0 else np.nan,
            "Facet": str(facet),
            "MatchedLevels": int(ok.sum()),
            "MeanDifference": float(diff[ok].mean()),
            "MedianDifference": float(diff[ok].median()),
            "MaxAbsDifference": float(diff[ok].abs().max()),
            "RMSE": float(np.sqrt(np.mean(np.square(diff[ok])))),
            "Correlation": corr,
            "RankCorrelation": rank_corr,
            "Status": (
                "Review"
                if (
                    float(diff[ok].abs().max()) > MML_PRIOR_SENSITIVITY_STABILITY_RULES["max_abs_measure_shift"]
                    or float(np.sqrt(np.mean(np.square(diff[ok])))) > MML_PRIOR_SENSITIVITY_STABILITY_RULES["measure_rmse"]
                    or (np.isfinite(rank_corr) and rank_corr < MML_PRIOR_SENSITIVITY_STABILITY_RULES["rank_correlation"])
                )
                else "Stable screen"
            ),
        })
    return pd.DataFrame(rows)


def _mml_prior_sensitivity_population_deltas(
    base_result: dict,
    run: dict,
    *,
    population_prior_sd: float,
    base_sd: float,
) -> pd.DataFrame:
    base = _mml_prior_sensitivity_population_long(base_result)
    other = _mml_prior_sensitivity_population_long(run)
    if base.empty or other.empty:
        return pd.DataFrame()
    merged = base.merge(other, on="Term", how="inner", suffixes=("_Base", "_Sensitivity"))
    if merged.empty:
        return pd.DataFrame()
    merged["PopulationPriorSD"] = float(population_prior_sd)
    merged["BasePopulationPriorSD"] = float(base_sd)
    merged["Multiplier"] = float(population_prior_sd / base_sd) if base_sd > 0 else np.nan
    merged["Difference"] = merged["Estimate_Sensitivity"] - merged["Estimate_Base"]
    merged["AbsDifference"] = merged["Difference"].abs()
    merged["Status"] = np.where(
        merged["AbsDifference"] > MML_PRIOR_SENSITIVITY_STABILITY_RULES["population_coefficient_shift"],
        "Review",
        "Stable screen",
    )
    return merged[[
        "PopulationPriorSD", "BasePopulationPriorSD", "Multiplier", "Term",
        "Estimate_Base", "Estimate_Sensitivity", "Difference", "AbsDifference", "Status",
    ]]


def build_mml_prior_sensitivity_report(
    summary: pd.DataFrame,
    measure_deltas: pd.DataFrame,
    population_deltas: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """One-row interpretation layer for fixed-prior-SD sensitivity output."""
    if not isinstance(summary, pd.DataFrame) or summary.empty:
        return pd.DataFrame()
    ok_summary = summary[summary.get("RunOK", pd.Series(False, index=summary.index)).astype(bool)]
    failed = int(len(summary) - len(ok_summary))
    non_base = ok_summary[ok_summary.get("Role", pd.Series("", index=ok_summary.index)).astype(str) != "current fitted value"]
    if len(ok_summary) < 2 or non_base.empty:
        status = "Review"
        evidence = "Fewer than two successful prior-SD conditions were available."
    else:
        max_abs = (
            float(pd.to_numeric(measure_deltas.get("MaxAbsDifference"), errors="coerce").max())
            if isinstance(measure_deltas, pd.DataFrame) and not measure_deltas.empty else np.nan
        )
        max_rmse = (
            float(pd.to_numeric(measure_deltas.get("RMSE"), errors="coerce").max())
            if isinstance(measure_deltas, pd.DataFrame) and not measure_deltas.empty else np.nan
        )
        min_rank = (
            float(pd.to_numeric(measure_deltas.get("RankCorrelation"), errors="coerce").min())
            if isinstance(measure_deltas, pd.DataFrame) and not measure_deltas.empty else np.nan
        )
        max_pop = (
            float(pd.to_numeric(population_deltas.get("AbsDifference"), errors="coerce").max())
            if isinstance(population_deltas, pd.DataFrame) and not population_deltas.empty else np.nan
        )
        review = failed > 0
        review = review or (np.isfinite(max_abs) and max_abs > MML_PRIOR_SENSITIVITY_STABILITY_RULES["max_abs_measure_shift"])
        review = review or (np.isfinite(max_rmse) and max_rmse > MML_PRIOR_SENSITIVITY_STABILITY_RULES["measure_rmse"])
        review = review or (np.isfinite(min_rank) and min_rank < MML_PRIOR_SENSITIVITY_STABILITY_RULES["rank_correlation"])
        review = review or (np.isfinite(max_pop) and max_pop > MML_PRIOR_SENSITIVITY_STABILITY_RULES["population_coefficient_shift"])
        status = "Review" if review else "Stable screen"
        evidence = (
            f"{len(ok_summary)} successful condition(s), {failed} failed; "
            f"max |measure shift|={max_abs:.3g}; max RMSE={max_rmse:.3g}; "
            f"min rank correlation={min_rank:.3g}; max population-coefficient shift={max_pop:.3g}."
        )
    interpretation = (
        "This is a fixed-population-prior-SD sensitivity screen for the current "
        "MML parameterization. It does not estimate the latent variance; it asks "
        "whether conclusions are stable when the user-set prior SD is varied."
    )
    action = (
        "If Status is Review, report the sensitivity range and avoid population-scale "
        "or latent-regression claims until a larger grid or external MML/Bayesian "
        "check supports the conclusion."
        if status == "Review" else
        "Report the tested prior-SD values, comparison metrics, and the fixed-variance boundary."
    )
    return pd.DataFrame([{
        "Area": "MML fixed population prior SD sensitivity",
        "Status": status,
        "Evidence": evidence,
        "Interpretation": interpretation,
        "RecommendedAction": action,
        "DecisionRule": (
            "Review thresholds: max |measure shift| > "
            f"{MML_PRIOR_SENSITIVITY_STABILITY_RULES['max_abs_measure_shift']:.2f}, "
            "measure RMSE > "
            f"{MML_PRIOR_SENSITIVITY_STABILITY_RULES['measure_rmse']:.2f}, "
            "rank correlation < "
            f"{MML_PRIOR_SENSITIVITY_STABILITY_RULES['rank_correlation']:.2f}, "
            "or population coefficient shift > "
            f"{MML_PRIOR_SENSITIVITY_STABILITY_RULES['population_coefficient_shift']:.2f}."
        ),
    }])


def evaluate_mml_prior_sd_sensitivity(
    result: dict,
    *,
    prior_sds: Iterable[float] | None = None,
    multipliers=MML_PRIOR_SENSITIVITY_DEFAULT_MULTIPLIERS,
    max_values: int | None = None,
    maxit: int | None = None,
    reltol: float | None = None,
    mml_engine: str | None = None,
    quad_points: int | None = None,
) -> dict:
    """Refit an MML run across fixed population-prior SD values.

    The current fitted result is reused for the base SD. Other SD values are
    refit on the normalized response table stored in ``result["prep"]["data"]``.
    """
    config = (result or {}).get("config", {}) if isinstance(result, dict) else {}
    if config.get("method") != "MML":
        return {
            "available": False,
            "reason": "MML prior-SD sensitivity is only available for MML runs.",
            "summary": pd.DataFrame(),
            "measure_deltas": pd.DataFrame(),
            "population_deltas": pd.DataFrame(),
            "report": pd.DataFrame(),
            "plan": pd.DataFrame(),
        }
    prep = result.get("prep", {}) if isinstance(result, dict) else {}
    data = prep.get("data", pd.DataFrame()) if isinstance(prep, dict) else pd.DataFrame()
    facet_names = list(config.get("facet_names", []))
    if not isinstance(data, pd.DataFrame) or data.empty or not facet_names:
        return {
            "available": False,
            "reason": "The fitted result does not carry a reusable normalized response table.",
            "summary": pd.DataFrame(),
            "measure_deltas": pd.DataFrame(),
            "population_deltas": pd.DataFrame(),
            "report": pd.DataFrame(),
            "plan": build_mml_prior_sensitivity_plan(result, multipliers=multipliers),
        }
    try:
        base_sd = float(config.get("population_prior_sd") or 1.0)
    except Exception:
        base_sd = 1.0
    if not np.isfinite(base_sd) or base_sd <= 0:
        base_sd = 1.0
    if prior_sds is None:
        plan = build_mml_prior_sensitivity_plan(result, multipliers=multipliers)
        candidate_sds = pd.to_numeric(plan.get("PopulationPriorSD"), errors="coerce").dropna().tolist()
    else:
        candidate_sds = []
        for val in prior_sds:
            try:
                candidate_sds.append(float(val))
            except Exception:
                continue
        plan = build_mml_prior_sensitivity_plan(
            result,
            multipliers=[sd / base_sd for sd in candidate_sds if base_sd > 0],
        )
    candidate_sds.append(base_sd)
    cleaned: list[float] = []
    for sd in candidate_sds:
        if np.isfinite(sd) and sd > 0 and not any(abs(sd - prev) < 1e-10 for prev in cleaned):
            cleaned.append(float(sd))
    cleaned = sorted(cleaned)
    if max_values is not None and len(cleaned) > int(max_values):
        keep = {base_sd}
        for sd in sorted(cleaned, key=lambda x: abs(x - base_sd)):
            keep.add(sd)
            if len(keep) >= int(max_values):
                break
        cleaned = sorted(keep)

    anchor_audit = config.get("anchor_audit", {}) if isinstance(config.get("anchor_audit"), dict) else {}
    population_model = config.get("population_model", {}) if isinstance(config.get("population_model"), dict) else {}
    regularization = result.get("regularization", {}) if isinstance(result, dict) else {}
    facet_regularization = regularization.get("settings") if isinstance(regularization, dict) else None
    fit_kwargs_base = dict(
        data=data.copy(),
        person_col="Person",
        facet_cols=facet_names,
        score_col="Score",
        rating_min=config.get("rating_min"),
        rating_max=config.get("rating_max"),
        weight_col="Weight" if "Weight" in data.columns else None,
        keep_original=True,
        model=config.get("model", "RSM"),
        method="MML",
        step_facet=config.get("step_facet"),
        slope_facet=config.get("slope_facet"),
        person_data=population_model.get("person_data") if population_model.get("enabled") else None,
        person_id_col="Person" if population_model.get("enabled") else None,
        population_formula=config.get("population_formula", ""),
        population_standardize_numeric=bool(config.get("population_standardize_numeric", False)),
        population_categorical_terms=config.get("population_categorical_terms", []),
        population_numeric_terms=config.get("population_numeric_terms", []),
        anchor_df=anchor_audit.get("valid_anchors", pd.DataFrame()),
        group_anchor_df=anchor_audit.get("valid_group_anchors", pd.DataFrame()),
        noncenter_facet=config.get("noncenter_facet", "Person"),
        dummy_facets=config.get("dummy_facets", []),
        positive_facets=config.get("positive_facets", []),
        quad_points=int(quad_points or config.get("quad_points") or 7),
        facet_regularization=facet_regularization,
        maxit=int(maxit or config.get("maxit") or 100),
        reltol=float(reltol or config.get("reltol") or 1e-5),
        mml_engine=mml_engine or config.get("mml_engine_requested") or config.get("mml_engine") or "EM",
        anchor_policy=config.get("anchor_policy", "warn"),
        compute_plausible_values=False,
    )

    runs: dict[float, dict] = {}
    summary_rows: list[dict] = []
    delta_frames: list[pd.DataFrame] = []
    pop_delta_frames: list[pd.DataFrame] = []
    for sd in cleaned:
        if abs(sd - base_sd) < 1e-10:
            run = result
            source = "current_result"
            run_ok = True
            err = ""
        else:
            source = "refit"
            try:
                run = mfrm_estimate(**{**fit_kwargs_base, "population_prior_sd": float(sd)})
                run_ok = True
                err = ""
            except Exception as exc:
                run = None
                run_ok = False
                err = f"{type(exc).__name__}: {exc}"
        if run_ok and isinstance(run, dict):
            runs[sd] = run
            deltas = _mml_prior_sensitivity_measure_deltas(
                result, run, population_prior_sd=sd, base_sd=base_sd
            )
            if not deltas.empty:
                delta_frames.append(deltas)
            pop_deltas = _mml_prior_sensitivity_population_deltas(
                result, run, population_prior_sd=sd, base_sd=base_sd
            )
            if not pop_deltas.empty:
                pop_delta_frames.append(pop_deltas)
        summary_rows.append(_mml_prior_sensitivity_summary_row(
            run,
            population_prior_sd=sd,
            base_sd=base_sd,
            source=source,
            run_ok=run_ok,
            error=err,
        ))

    summary = pd.DataFrame(summary_rows)
    measure_deltas = pd.concat(delta_frames, ignore_index=True) if delta_frames else pd.DataFrame()
    population_deltas = pd.concat(pop_delta_frames, ignore_index=True) if pop_delta_frames else pd.DataFrame()
    report = build_mml_prior_sensitivity_report(summary, measure_deltas, population_deltas)
    return {
        "available": bool(len(runs) >= 1 and not summary.empty),
        "reason": "MML fixed-prior-SD sensitivity refits completed.",
        "summary": summary,
        "measure_deltas": measure_deltas,
        "population_deltas": population_deltas,
        "report": report,
        "plan": plan,
        "settings": {
            "base_population_prior_sd": base_sd,
            "tested_population_prior_sds": cleaned,
            "maxit": fit_kwargs_base["maxit"],
            "reltol": fit_kwargs_base["reltol"],
            "quad_points": fit_kwargs_base["quad_points"],
            "mml_engine": fit_kwargs_base["mml_engine"],
        },
    }


def build_statistical_assumption_audit(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> pd.DataFrame:
    """Machine-readable audit of the main statistical caveats for export."""
    rows: list[dict[str, object]] = []
    config = (result or {}).get("config", {}) or {}
    uncertainty = diagnostics.get("uncertainty", {}) if isinstance(diagnostics, dict) else {}
    unc_summary = uncertainty.get("summary", pd.DataFrame()) if isinstance(uncertainty, dict) else pd.DataFrame()
    if isinstance(unc_summary, pd.DataFrame) and not unc_summary.empty:
        for _, row in unc_summary.iterrows():
            area = row.get("Area", "Measure SE/CI")
            condition = row.get("ConditionNumber", np.nan)
            claim = row.get("ClaimStatus", "")
            evidence = f"{row.get('Rows', 0)} row(s): {row.get('Method', '')}"
            if str(area) == "MML observed-information covariance":
                if np.isfinite(pd.to_numeric(pd.Series([condition]), errors="coerce").iloc[0]):
                    evidence += f"; condition number={float(condition):.3g}"
                if str(claim):
                    evidence += f"; claim status={claim}"
            rows.append({
                "Area": area,
                "Status": row.get("Status", "unknown"),
                "Evidence": evidence,
                "Implication": row.get("Caution", ""),
                "RecommendedAction": (
                    "Report covariance audit condition number, rank, regularization, and fallback status with MML structural SE/CI."
                    if str(area) == "MML observed-information covariance"
                    else "Report SE_Method, SE_Status, CI_Method, and CI_Status with exported measures."
                ),
            })
    if config.get("method") == "MML":
        prior_sd = config.get("population_prior_sd", "unknown")
        plan = build_mml_prior_sensitivity_plan(result)
        rows.append({
            "Area": "MML fixed population prior SD",
            "Status": "Review",
            "Evidence": f"population_prior_sd = {prior_sd}; {len(plan)} sensitivity value(s) listed.",
            "Implication": (
                "The person population variance is fixed by the user setting, "
                "so MML estimates are conditional on that scale choice."
            ),
            "RecommendedAction": (
                "Use evaluate_mml_prior_sd_sensitivity() / the Fit Details "
                "prior-SD sensitivity screen, or state why the fixed SD is "
                "part of the design."
            ),
        })
    rel = diagnostics.get("reliability", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()
    if isinstance(rel, pd.DataFrame) and not rel.empty and "SE_StatusSummary" in rel.columns:
        rows.append({
            "Area": "Reliability / separation uncertainty",
            "Status": "Review" if rel["SE_StatusSummary"].astype(str).str.contains("conditional_approximation|posterior", regex=True).any() else "Ready",
            "Evidence": "; ".join(
                f"{r.get('Facet')}: {r.get('SE_StatusSummary')}" for _, r in rel.iterrows()
            )[:800],
            "Implication": "Reliability and separation inherit the SE basis used for each facet.",
            "RecommendedAction": "Do not compare reliability values across facets without noting their SE basis.",
        })
    pca = diagnostics.get("pca") if isinstance(diagnostics, dict) else None
    if isinstance(pca, dict):
        stability_tbl = pca.get("stability_table")
        if isinstance(stability_tbl, pd.DataFrame) and not stability_tbl.empty:
            s = stability_tbl.iloc[0]
            rows.append({
                "Area": "Residual PCA stability",
                "Status": s.get("PCAStabilityStatus", "Review"),
                "Evidence": (
                    f"persons={s.get('Persons')}; residual columns={s.get('ResidualColumns')}; "
                    f"missing share={float(s.get('MissingShare', np.nan)):.1%}; "
                    f"min pairwise overlap={s.get('MinPairwiseOverlap')}; "
                    f"LOO EV1 max shift={s.get('LOOEV1MaxAbsDelta', 'n/a')}; "
                    f"bootstrap EV1 CV={s.get('BootstrapEV1CV', 'n/a')}; "
                    f"sensitivity flags={s.get('SensitivityFlagSummary', 'n/a')}"
                ),
                "Implication": s.get("Caution", ""),
                "RecommendedAction": "Use pca_stability_audit.csv before dimensionality claims; treat loadings as exploratory prompts when status is Review.",
            })
    all_bias = all_bias_results or {}
    if all_bias:
        bias_audit = build_bias_inference_audit(all_bias, result, diagnostics)
        if isinstance(bias_audit, pd.DataFrame) and not bias_audit.empty:
            flagged = int(pd.to_numeric(bias_audit.get("FlaggedCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum())
            sparse = int(pd.to_numeric(bias_audit.get("SparseCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum())
            strong = int(pd.to_numeric(bias_audit.get("StrongReviewCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum())
            cells = int(pd.to_numeric(bias_audit.get("CellsScreened", pd.Series(dtype=float)), errors="coerce").fillna(0).sum())
            statuses = dict(bias_audit.get("Status", pd.Series(dtype=str)).astype(str).value_counts())
            common_status = "; ".join(
                dict.fromkeys(bias_audit.get("CommonScaleStatus", pd.Series(dtype=str)).astype(str).tolist())
            )[:500]
            status = "Ready" if cells and statuses == {"Ready": len(bias_audit)} else "Review"
            action = (
                "Report only the computed conditional screen and keep no-bias wording limited to screened cells."
                if status == "Ready" else
                "Use bias_inference_audit plus DFF tables; resolve sparse cells, disconnected subsets, and flagged cells before strong bias claims."
            )
        else:
            flagged = sparse = strong = cells = 0
            statuses = {}
            common_status = "Bias audit unavailable."
            status = "Review"
            action = "Rerun or inspect bias screen outputs before making local-interaction claims."
        rows.append({
            "Area": "Bias / local interaction inference",
            "Status": status,
            "Evidence": (
                f"{len(all_bias)} facet pair bundle(s); {cells} cell(s); "
                f"{flagged} flagged, {strong} strong-review, {sparse} sparse; "
                f"pair status={statuses}; common-scale={common_status}"
            ),
            "Implication": (
                "Bias cells are conditional screening results; GPCM profile CIs "
                "hold other fitted parameters fixed and do not propagate global "
                "model uncertainty."
            ),
            "RecommendedAction": action,
        })
    return pd.DataFrame(rows)


def build_final_report_readiness(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> pd.DataFrame:
    """Final-report readiness table generated from current outputs."""
    rows: list[dict[str, str]] = []
    config = result.get("config", {})
    prep = result.get("prep", {})

    opt = result.get("opt")
    converged = bool(getattr(opt, "success", False))
    rows.append(_readiness_row(
        "Convergence",
        _status_from_bool(converged),
        str(getattr(opt, "message", "not available")),
        "Do not write final interpretations until the optimizer converges." if not converged else "No action needed.",
    ))

    obs_df = diagnostics.get("obs", pd.DataFrame())
    if isinstance(obs_df, pd.DataFrame) and not obs_df.empty and "StdResidual" in obs_df.columns:
        z = pd.to_numeric(obs_df["StdResidual"], errors="coerce").dropna()
        pct_ge2 = float((z.abs() >= 2).mean() * 100) if len(z) else np.nan
        fit_ok = np.isfinite(pct_ge2) and pct_ge2 <= FINAL_RESIDUAL_PCT_GE2_READY
        rows.append(_readiness_row(
            "Global residual fit",
            _status_from_bool(fit_ok, missing=not np.isfinite(pct_ge2)),
            f"{pct_ge2:.1f}% of observations have |z| >= 2." if np.isfinite(pct_ge2) else "Residual summary unavailable.",
            "Inspect Fit Details and Bias/Interaction before reporting." if not fit_ok else "No action needed.",
        ))
    else:
        rows.append(_readiness_row(
            "Global residual fit",
            "Missing",
            "Observation-level residuals are unavailable.",
            "Re-run diagnostics before final reporting.",
        ))

    rating_dashboard = rating_scale_functioning_dashboard(result, diagnostics)
    if isinstance(rating_dashboard, pd.DataFrame) and not rating_dashboard.empty:
        overall_row = rating_dashboard.loc[
            rating_dashboard["Check"].astype(str) == "Overall rating-scale decision"
        ]
        status = str(overall_row["Status"].iloc[0]) if not overall_row.empty else "Review"
        review_rows = rating_dashboard.loc[rating_dashboard["Status"].astype(str) == "Review"]
        review_checks = _compact_value_list(review_rows["Check"].tolist()) if not review_rows.empty else "none"
        evidence = (
            str(overall_row["Evidence"].iloc[0]) if not overall_row.empty else
            "rating-scale dashboard generated"
        )
        if review_checks != "none":
            evidence = f"{evidence}; review checks: {review_checks}"
        rows.append(_readiness_row(
            "Category functioning",
            status,
            evidence,
            (
                "Open Categories/Steps and Visuals; consider collapsing sparse or non-distinct adjacent categories."
                if status != "OK" else
                "No action needed."
            ),
        ))
    else:
        rows.append(_readiness_row(
            "Category functioning",
            "Missing",
            "Rating-scale dashboard unavailable.",
            "Open Categories/Steps and confirm category diagnostics before final reporting.",
        ))

    rel_df = diagnostics.get("reliability", pd.DataFrame())
    if isinstance(rel_df, pd.DataFrame) and not rel_df.empty and "Reliability" in rel_df.columns:
        person_rel = rel_df[rel_df["Facet"].astype(str) == "Person"] if "Facet" in rel_df.columns else pd.DataFrame()
        if not person_rel.empty:
            rel_val = pd.to_numeric(person_rel["Reliability"], errors="coerce").iloc[0]
            rel_ok = bool(np.isfinite(rel_val) and rel_val >= FINAL_PERSON_RELIABILITY_READY)
            evidence = f"Person reliability = {rel_val:.3f}" if np.isfinite(rel_val) else "Person reliability unavailable."
            action = (
                "Use Design Evaluation to decide whether more ratings or linking observations are needed."
                if not rel_ok else "No action needed."
            )
        else:
            rel_vals = pd.to_numeric(rel_df["Reliability"], errors="coerce").dropna()
            rel_ok = False
            evidence = (
                "Person reliability unavailable; non-person reliability must be interpreted facet-by-facet "
                "(low rater reliability can be desirable)."
                if len(rel_vals) else "Reliability values unavailable."
            )
            action = (
                "Do not use a lowest-facet reliability rule. Interpret person, rater, task, and criterion reliability separately."
            )
        rows.append(_readiness_row(
            "Reliability / separation",
            _status_from_bool(rel_ok),
            evidence,
            action,
        ))
    else:
        rows.append(_readiness_row(
            "Reliability / separation",
            "Missing",
            "Reliability table unavailable.",
            "Re-run diagnostics before final reporting.",
        ))

    pca_enabled = bool(diagnostics.get("pca_enabled", False))
    pca = diagnostics.get("pca")
    if pca_enabled and isinstance(pca, dict) and pca.get("eigenvalues") is not None:
        ev = np.asarray(pca.get("eigenvalues"), dtype=float)
        ev1 = float(ev[0]) if ev.size else np.nan
        stability_status = ""
        stability_caution = ""
        stability_flags = ""
        boot_cv = np.nan
        loo_delta = np.nan
        loo_share_delta = np.nan
        stability_tbl = pca.get("stability_table")
        if isinstance(stability_tbl, pd.DataFrame) and not stability_tbl.empty:
            stability_status = str(stability_tbl.iloc[0].get("PCAStabilityStatus", ""))
            stability_caution = str(stability_tbl.iloc[0].get("Caution", ""))
            stability_flags = str(stability_tbl.iloc[0].get("SensitivityFlagSummary", ""))
            boot_cv = pd.to_numeric(pd.Series([stability_tbl.iloc[0].get("BootstrapEV1CV", np.nan)]), errors="coerce").iloc[0]
            loo_delta = pd.to_numeric(pd.Series([stability_tbl.iloc[0].get("LOOEV1MaxAbsDelta", np.nan)]), errors="coerce").iloc[0]
            loo_share_delta = pd.to_numeric(pd.Series([stability_tbl.iloc[0].get("LOOEV1ShareMaxAbsDelta", np.nan)]), errors="coerce").iloc[0]
        pca_stable = stability_status != "Review"
        pca_ok = bool(np.isfinite(ev1) and ev1 < FINAL_PCA_EIGENVALUE_READY and pca_stable)
        evidence = f"first residual PCA eigenvalue = {ev1:.2f}" if np.isfinite(ev1) else "PCA result unavailable."
        if stability_status:
            evidence += f"; stability = {stability_status}"
        if stability_flags and stability_flags != "none":
            evidence += f"; sensitivity flags = {stability_flags}"
        if np.isfinite(boot_cv):
            evidence += f"; bootstrap EV1 CV = {float(boot_cv):.2f}"
        if np.isfinite(loo_delta):
            evidence += f"; LOO EV1 max shift = {float(loo_delta):.2f}"
        if np.isfinite(loo_share_delta):
            evidence += f"; LOO EV1 share max shift = {float(loo_share_delta):.2f}"
        rows.append(_readiness_row(
            "Dimensionality screen",
            _status_from_bool(pca_ok, missing=not np.isfinite(ev1)),
            evidence,
            (
                f"Inspect Dimensionality tab; {stability_caution}"
                if not pca_ok else "No action needed."
            ),
        ))
    else:
        # Surface the concrete skip reason (set by mfrm_diagnostics via
        # diagnose_pca_skip_reason) so the readiness row and exported CSV
        # tell users WHY PCA is missing — small data, single
        # item-combination, >95% NaN, disabled by Analysis depth, etc. —
        # instead of the previous generic "skipped or unavailable".
        pca_skip_reason = ""
        if isinstance(diagnostics, dict):
            # ``pca_reason`` is now a localizable payload (see _make_reason);
            # resolve it to display text in the active locale before embedding
            # in readiness CSV output.
            pca_skip_reason = _render_reason(diagnostics.get("pca_reason"))
        evidence = "Residual PCA was skipped or unavailable."
        if pca_skip_reason:
            evidence = f"Residual PCA was skipped or unavailable. Reason: {pca_skip_reason}"
        rows.append(_readiness_row(
            "Dimensionality screen",
            "Review",
            evidence,
            "Enable residual PCA for final reports unless the analysis is explicitly exploratory.",
        ))

    person_tbl = result.get("facets", {}).get("person", pd.DataFrame())
    facet_tbl = result.get("facets", {}).get("others", pd.DataFrame())
    p_est = pd.to_numeric(person_tbl.get("Estimate", pd.Series(dtype=float)), errors="coerce").dropna() if isinstance(person_tbl, pd.DataFrame) else pd.Series(dtype=float)
    f_est = pd.to_numeric(facet_tbl.get("Estimate", pd.Series(dtype=float)), errors="coerce").dropna() if isinstance(facet_tbl, pd.DataFrame) else pd.Series(dtype=float)
    if len(p_est) and len(f_est):
        overlap = min(float(p_est.max()), float(f_est.max())) - max(float(p_est.min()), float(f_est.min()))
        target_ok = bool(overlap > 0)
        rows.append(_readiness_row(
            "Wright Map targeting",
            _status_from_bool(target_ok),
            f"person/facet distribution overlap = {overlap:.2f} logits",
            "Open Wright Map; check for ceiling/floor effects and weak targeting." if not target_ok else "No action needed.",
        ))
    else:
        rows.append(_readiness_row(
            "Wright Map targeting",
            "Missing",
            "Finite person/facet estimates unavailable.",
            "Re-run estimation or inspect extreme data.",
        ))

    all_bias = all_bias_results or {}
    if all_bias:
        bias_audit = build_bias_inference_audit(all_bias, result, diagnostics)
        n_total = int(pd.to_numeric(bias_audit.get("CellsScreened", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
        n_flagged = int(pd.to_numeric(bias_audit.get("FlaggedCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
        n_strong = int(pd.to_numeric(bias_audit.get("StrongReviewCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
        n_sparse = int(pd.to_numeric(bias_audit.get("SparseCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
        has_ready_only = (
            isinstance(bias_audit, pd.DataFrame)
            and not bias_audit.empty
            and bias_audit["Status"].astype(str).eq("Ready").all()
        )
        rows.append(_readiness_row(
            "Bias / local interaction",
            "Ready" if has_ready_only else "Review",
            (
                f"{n_flagged} of {n_total} screened interactions are DFF/bias review flags; "
                f"{n_strong} strong-review and {n_sparse} sparse cell(s)."
            ),
            (
                "Report the conditional screen scope and keep no-bias wording limited to screened cells."
                if has_ready_only else
                "Substantively review flagged or sparse cells; consider multiplicity, connectedness, and design balance."
            ),
            required=False,
        ))
    else:
        rows.append(_readiness_row(
            "Bias / local interaction",
            "Review",
            "No bias/interaction scan was computed.",
            "Use Selected pair or Full publication before making no-bias claims.",
            required=False,
        ))

    anchor_audit = config.get("anchor_audit", {})
    if isinstance(anchor_audit, dict):
        status = anchor_audit.get("overall_status", "ok")
        issue_tbl = anchor_audit.get("issues", pd.DataFrame())
        n_issues = len(issue_tbl) if isinstance(issue_tbl, pd.DataFrame) else 0
        rows.append(_readiness_row(
            "Anchor / linking audit",
            "Ready" if status == "ok" else "Review",
            anchor_audit.get("message", f"{n_issues} issue(s)."),
            "Fix or explicitly justify anchor/linking issues before linking across runs." if status != "ok" else "No action needed for a single-run report.",
            required=False,
        ))
    drift = result.get("anchor_drift", {})
    if isinstance(drift, dict) and drift.get("available"):
        drift_summary = drift.get("summary", pd.DataFrame())
        if isinstance(drift_summary, pd.DataFrame) and not drift_summary.empty:
            d0 = drift_summary.iloc[0]
            status = "Ready" if str(d0.get("Status", "")) == "Ready" else "Review"
            rows.append(_readiness_row(
                "Anchor drift / constraint consistency",
                status,
                f"max fixed-anchor drift = {float(d0.get('MaxAbsAnchorDrift', np.nan)):.3g}; "
                f"max group-mean drift = {float(d0.get('MaxAbsGroupMeanDrift', np.nan)):.3g}",
                d0.get("Action", "Review anchor drift table before linking."),
                required=False,
            ))
    chain = result.get("equating_chain", {})
    if isinstance(chain, dict) and chain.get("available"):
        edges = chain.get("edges", pd.DataFrame())
        n_edges = len(edges) if isinstance(edges, pd.DataFrame) else 0
        weak = int((edges["Strength"].astype(str) == "Weak link").sum()) if isinstance(edges, pd.DataFrame) and "Strength" in edges.columns else 0
        rows.append(_readiness_row(
            "Equating-chain summary",
            "Ready" if weak == 0 else "Review",
            f"{n_edges} anchor-chain edge(s); {weak} weak link(s).",
            "Review weak links before cross-run linking claims." if weak else "Use with anchor drift and content-match review.",
            required=False,
        ))

    marginal = diagnostics.get("marginal_fit", {})
    if isinstance(marginal, dict) and marginal.get("available"):
        n_review = int(marginal.get("n_review", 0) or 0)
        rows.append(_readiness_row(
            "Strict marginal diagnostics",
            "Ready" if n_review == 0 else "Review",
            f"{n_review} marginal row(s) flagged.",
            "Inspect strict marginal summaries before final MML reporting." if n_review else "No action needed.",
            required=config.get("method") == "MML",
        ))
    elif config.get("method") == "MML":
        rows.append(_readiness_row(
            "Strict marginal diagnostics",
            "Review",
            marginal.get("reason", "Strict marginal diagnostics were skipped."),
            "Enable strict marginal diagnostics for final MML reports when feasible.",
            required=False,
        ))

    if config.get("method") == "MML":
        prior_plan = build_mml_prior_sensitivity_plan(result)
        rows.append(_readiness_row(
            "MML fixed population prior SD",
            "Review",
            (
                f"population_prior_sd = {config.get('population_prior_sd', 'unknown')}; "
                f"{len(prior_plan)} recommended sensitivity value(s)."
            ),
            (
                "Report that latent variance is fixed by the app setting, and "
                "run or justify prior-SD sensitivity before population-scale or "
                "latent-regression claims."
            ),
            required=False,
        ))

    readiness = pd.DataFrame(rows)
    status_order = {"Not ready": 0, "Review": 1, "Missing": 2, "Ready": 3}
    if "Status" in readiness.columns:
        readiness["_sort"] = readiness["Status"].map(status_order).fillna(2)
        readiness = readiness.sort_values(["_sort", "Check"]).drop(columns=["_sort"]).reset_index(drop=True)
    return readiness


def build_manuscript_claim_guide(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> pd.DataFrame:
    """Result-aware guardrails for manuscript claims."""
    config = result.get("config", {})
    prep = result.get("prep", {})
    opt = result.get("opt")
    converged = bool(getattr(opt, "success", False))
    model = str(config.get("model", "unknown"))
    method = str(config.get("method", "unknown"))
    facet_names = ", ".join(map(str, config.get("facet_names", []))) or "not recorded"
    n_obs = prep.get("n_obs", "unknown")
    n_person = prep.get("n_person", "unknown")
    rating_min = prep.get("rating_min", "?")
    rating_max = prep.get("rating_max", "?")
    all_bias = all_bias_results or {}
    readiness = build_final_report_readiness(result, diagnostics, all_bias)

    def readiness_status(check: str, default: str = "Missing") -> str:
        if not isinstance(readiness, pd.DataFrame) or readiness.empty or "Check" not in readiness.columns:
            return default
        hit = readiness.loc[readiness["Check"].astype(str) == check, "Status"]
        return str(hit.iloc[0]) if not hit.empty else default

    def readiness_evidence(check: str, default: str = "No result-specific evidence recorded.") -> str:
        if not isinstance(readiness, pd.DataFrame) or readiness.empty or "Check" not in readiness.columns:
            return default
        hit = readiness.loc[readiness["Check"].astype(str) == check, "Evidence"]
        return str(hit.iloc[0]) if not hit.empty else default

    def claim_status(readiness_value: str, *, skipped_is_do_not_claim: bool = False) -> str:
        if readiness_value == "Ready":
            return "Ready"
        if readiness_value in {"Review", "Missing"}:
            return "Do not claim" if skipped_is_do_not_claim and readiness_value == "Missing" else "Report with caveat"
        return "Report with caveat"

    def combined_claim_status(*readiness_values: str) -> str:
        if readiness_values and all(value == "Ready" for value in readiness_values):
            return "Ready"
        if any(value in {"Review", "Missing"} for value in readiness_values):
            return "Report with caveat"
        return "Report with caveat"

    bias_audit = build_bias_inference_audit(all_bias, result, diagnostics) if all_bias else pd.DataFrame()
    n_total = int(pd.to_numeric(bias_audit.get("CellsScreened", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
    n_flagged = int(pd.to_numeric(bias_audit.get("FlaggedCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
    n_strong = int(pd.to_numeric(bias_audit.get("StrongReviewCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
    n_sparse = int(pd.to_numeric(bias_audit.get("SparseCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
    n_holm = int(pd.to_numeric(bias_audit.get("HolmSignificantCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
    bias_statuses = (
        dict(bias_audit.get("Status", pd.Series(dtype=str)).astype(str).value_counts())
        if isinstance(bias_audit, pd.DataFrame) and not bias_audit.empty else {}
    )
    if not all_bias:
        bias_claim_status = "Do not claim"
        bias_safe = "No bias/interaction screen was run for this result."
        bias_action = "Run a selected pair or full publication bias screen before writing no-bias claims."
    elif isinstance(bias_audit, pd.DataFrame) and not bias_audit.empty and bias_audit["Status"].astype(str).eq("Ready").all():
        bias_claim_status = "Ready"
        bias_safe = (
            "For the computed facet-pair screen, no cell was flagged by the conditional DFF/bias "
            "rules with Holm/BH multiplicity review."
        )
        bias_action = "Report the facet pairs and thresholds that were screened; keep the claim limited to those pairs and cells."
    else:
        bias_claim_status = "Report with caveat"
        bias_safe = (
            f"{n_flagged} of {n_total} screened local interactions were flagged by the "
            "conditional DFF/bias rules and need substantive review."
        )
        bias_action = "Report flagged pairs as review evidence; consider sparse cells, multiplicity, connectedness, and rubric content."

    rating_decision = rating_scale_decision_support_table(result, diagnostics)
    rating_decision_row = pd.DataFrame()
    if isinstance(rating_decision, pd.DataFrame) and not rating_decision.empty:
        rating_decision_row = rating_decision.loc[
            rating_decision["DecisionArea"].astype(str) == "Overall reportability"
        ]
        if rating_decision_row.empty:
            rating_decision_row = rating_decision.head(1)
    rating_decision_status = (
        str(rating_decision_row["DecisionStatus"].iloc[0])
        if not rating_decision_row.empty and "DecisionStatus" in rating_decision_row.columns else
        "Missing evidence"
    )
    rating_claim_status = (
        "Ready" if rating_decision_status == "Ready" else
        "Do not claim" if rating_decision_status in {"Do not claim yet", "Missing evidence"} else
        "Report with caveat"
    )
    rating_safe_wording = (
        str(rating_decision_row["SafeReportWording"].iloc[0])
        if not rating_decision_row.empty and "SafeReportWording" in rating_decision_row.columns else
        "Report category counts, average-measure ordering, threshold ordering, and category-curve peak/dominance evidence."
    )
    rating_do_not_claim = (
        str(rating_decision_row["DoNotClaim"].iloc[0])
        if not rating_decision_row.empty and "DoNotClaim" in rating_decision_row.columns else
        "Do not state that all categories function distinctly if any category row is sparse, thresholds are disordered, or a category curve lacks a dominance region."
    )
    rating_next_action = (
        str(rating_decision_row["RecommendedAction"].iloc[0])
        if not rating_decision_row.empty and "RecommendedAction" in rating_decision_row.columns else
        "Use Categories/Steps and category probability curves before deciding whether to collapse categories."
    )
    rating_evidence = readiness_evidence("Category functioning")
    if not rating_decision_row.empty and "PrimaryEvidence" in rating_decision_row.columns:
        rating_evidence = f"{rating_evidence} Decision support: {rating_decision_row['PrimaryEvidence'].iloc[0]}".strip()

    rows = [
        {
            "ManuscriptArea": "Model and software scope",
            "ClaimStatus": "Ready",
            "SafeManuscriptWording": (
                f"A many-facet Rasch model was fitted with the standalone Python app "
                f"using {model} and {method}; facets were {facet_names}."
            ),
            "EvidenceToReport": (
                f"{n_obs} observations, {n_person} persons, score range {rating_min}-{rating_max}; "
                f"app version {config.get('app_version', APP_VERSION)}."
            ),
            "DoNotClaim": "Do not describe the run as FACETS/TAM/sirt/mirt/mfrmr output or as exact cross-package parity.",
            "NextAction": "Report the app version, model, estimation method, facets, and runtime boundary.",
        },
        {
            "ManuscriptArea": "Convergence and final interpretability",
            "ClaimStatus": "Ready" if converged else "Do not claim",
            "SafeManuscriptWording": (
                "The optimizer reported convergence, so substantive diagnostics can be read."
                if converged else
                "The optimizer did not report convergence; final parameter interpretation should be withheld."
            ),
            "EvidenceToReport": str(getattr(opt, "message", "not available")),
            "DoNotClaim": "Do not interpret person ability, rater severity, or task difficulty as final if convergence failed.",
            "NextAction": (
                "Continue through category, fit, reliability, and dimensionality diagnostics."
                if converged else
                "Increase iterations, simplify the model, inspect sparse/extreme data, or adjust category structure."
            ),
        },
        {
            "ManuscriptArea": "MML population scale",
            "ClaimStatus": (
                "Report with caveat" if method == "MML" else "Ready"
            ),
            "SafeManuscriptWording": (
                (
                    f"The MML run estimated the person population SD at {config.get('estimated_population_sd', 'not recorded')}; "
                    "population-scale conclusions reflect the freely estimated metric (report the SD with its profile SE/CI)."
                    if config.get("estimate_population_sd") else
                    f"The MML run used a fixed population prior SD of {config.get('population_prior_sd', 'not recorded')}; "
                    "population-scale conclusions are conditional on that setting."
                )
                if method == "MML" else
                "No MML population prior SD was used because this run was not MML."
            ),
            "EvidenceToReport": readiness_evidence("MML fixed population prior SD", "Not an MML run."),
            "DoNotClaim": (
                "Do not state that the latent variance was estimated by the app or that the result is identical to TAM/ConQuest variance handling."
            ),
            "NextAction": (
                "Run or justify prior-SD sensitivity before latent-regression or population-scale claims."
                if method == "MML" else
                "No action for non-MML reports."
            ),
        },
        {
            "ManuscriptArea": "Rating-scale functioning",
            "ClaimStatus": rating_claim_status,
            "SafeManuscriptWording": rating_safe_wording,
            "EvidenceToReport": rating_evidence,
            "DoNotClaim": rating_do_not_claim,
            "NextAction": rating_next_action,
        },
        {
            "ManuscriptArea": "Reliability and separation",
            "ClaimStatus": claim_status(readiness_status("Reliability / separation")),
            "SafeManuscriptWording": (
                "Report person reliability/separation when person ordering is a study goal; interpret rater reliability differently from person reliability."
            ),
            "EvidenceToReport": readiness_evidence("Reliability / separation"),
            "DoNotClaim": "Do not treat high rater reliability as automatically desirable; it can mean raters differ in severity.",
            "NextAction": "Use the facet reliability table and design evaluation before making precision or design adequacy claims.",
        },
        {
            "ManuscriptArea": "Fit and dimensionality",
            "ClaimStatus": combined_claim_status(
                readiness_status("Global residual fit"),
                readiness_status("Dimensionality screen"),
            ),
            "SafeManuscriptWording": (
                "Report residual fit together with residual PCA and local-dependence screens; describe them as residual-structure evidence, not proof of unidimensionality."
            ),
            "EvidenceToReport": (
                f"{readiness_evidence('Global residual fit')} "
                f"{readiness_evidence('Dimensionality screen')}"
            ).strip(),
            "DoNotClaim": "Do not claim that unidimensionality was established from fit statistics alone, or if residual PCA was skipped or flagged.",
            "NextAction": "Open Fit Details and Dimensionality; discuss any review flags before final conclusions.",
        },
        {
            "ManuscriptArea": "Wright map targeting and measure interpretation",
            "ClaimStatus": claim_status(readiness_status("Wright Map targeting")),
            "SafeManuscriptWording": (
                "Report the Wright map as evidence of targeting and relative ordering on the current connected scale."
            ),
            "EvidenceToReport": readiness_evidence("Wright Map targeting"),
            "DoNotClaim": "Do not generalize beyond the observed connected design or ignore ceiling/floor targeting problems.",
            "NextAction": "Use the Wright Map tab to check overlap, gaps, and extreme clustering before interpreting rank order.",
        },
        {
            "ManuscriptArea": "Bias / local interaction",
            "ClaimStatus": bias_claim_status,
            "SafeManuscriptWording": bias_safe,
            "EvidenceToReport": (
                f"{len(all_bias)} facet-pair bundle(s); {n_flagged} of {n_total} screened local interactions flagged; "
                f"{n_strong} strong-review, {n_sparse} sparse, {n_holm} Holm-significant; pair status={bias_statuses}."
            ),
            "DoNotClaim": (
                "Do not claim that bias is absent outside the facet pairs and cells that were actually screened, "
                "or that conditional bias CIs propagate global model uncertainty."
            ),
            "NextAction": bias_action,
        },
        {
            "ManuscriptArea": "Anchoring and linking",
            "ClaimStatus": claim_status(readiness_status("Anchor / linking audit"), skipped_is_do_not_claim=False),
            "SafeManuscriptWording": (
                "For a single unanchored run, interpret measures within the current analysis; for linking, report anchor audit evidence."
            ),
            "EvidenceToReport": readiness_evidence("Anchor / linking audit"),
            "DoNotClaim": "Do not compare administrations, cohorts, or forms on a common scale without anchor/linking evidence.",
            "NextAction": "Use anchor audit, drift, and equating-chain outputs before making cross-run linking claims.",
        },
        {
            "ManuscriptArea": "Prediction, plausible values, and simulation",
            "ClaimStatus": "Report with caveat",
            "SafeManuscriptWording": (
                "Use prediction, plausible values, and simulation outputs as model-based sensitivity or design-support evidence."
            ),
            "EvidenceToReport": (
                f"MML method: {config.get('method') == 'MML'}; plausible values requested: "
                f"{bool(config.get('compute_plausible_values', False))}; "
                f"draws: {int(config.get('n_plausible_values') or 0)}."
            ),
            "DoNotClaim": "Do not present model-based simulations as a prospective validation study or causal evidence.",
            "NextAction": "State assumptions, seeds/replicates, and whether unknown persons were handled through the MML population distribution.",
        },
        {
            "ManuscriptArea": "External package comparison",
            "ClaimStatus": "Boundary",
            "SafeManuscriptWording": (
                "External TAM/sirt/mirt/mfrmr checks may be cited only as optional validation evidence when the exact artifact set is archived."
            ),
            "EvidenceToReport": "See validation/README.md and validation/R_CROSSCHECK_STATUS.md when external checks are used.",
            "DoNotClaim": "Do not force or display R-vs-Python numerical equality claims unless the fixture, parameterization map, and tolerance report justify them.",
            "NextAction": "Keep the main manuscript focused on the Python app outputs unless the study explicitly includes cross-package validation.",
        },
        {
            "ManuscriptArea": "Bayesian / Uto-family extension",
            "ClaimStatus": "Boundary",
            "SafeManuscriptWording": (
                "Uto-family Bayesian MFRM references can motivate an extension analysis when a separate Stan model, priors, data map, diagnostics, and sensitivity checks are archived."
            ),
            "EvidenceToReport": "See bayesian_mfrm_stan_refinement_plan.csv, stan_reproducibility_archive_contract.csv, stan_posterior_reproducibility_route.csv, mfrm_stan_data_manifest.csv, mfrm_stan_data_dictionary.csv, mfrm_stan_prior_guidance.csv, mfrm_stan_prior_sensitivity_grid.csv, stan_posterior_handoff_checklist.csv, stan_run_manifest_template.csv, method_reference_audit.csv, and the exported Stan runner templates.",
            "DoNotClaim": (
                "Do not state that generalized Bayesian MFRM, multidimensional rubric traits, or rater severity drift were fitted unless the corresponding Stan scaffold was run and validated."
            ),
            "NextAction": "Use the Uto-family Stan scaffold as a separate reproducibility artifact; archive JSON data, priors, sampler settings, posterior diagnostics, and sensitivity variants.",
        },
    ]
    return pd.DataFrame(rows)


def build_publication_gate_summary(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> pd.DataFrame:
    """Manuscript-level gate that keeps APA text aligned with diagnostics."""
    readiness = build_final_report_readiness(result, diagnostics, all_bias_results or {})
    guide = build_manuscript_claim_guide(result, diagnostics, all_bias_results or {})
    rows: list[dict[str, str]] = []
    blocking_areas = {"Convergence and final interpretability"}
    optional_claim_areas = {"Prediction, plausible values, and simulation"}

    def add_row(area: str, status: str, evidence: str, action: str) -> None:
        rows.append({
            "GateArea": str(area),
            "GateStatus": str(status),
            "Evidence": str(evidence),
            "ManuscriptAction": str(action),
        })

    if isinstance(readiness, pd.DataFrame) and not readiness.empty:
        for _, row in readiness.iterrows():
            status = str(row.get("Status", ""))
            required = str(row.get("Required", "No")) == "Yes"
            check = str(row.get("Check", "Readiness check"))
            evidence = str(row.get("Evidence", ""))
            action = str(row.get("ActionBeforeFinalReport", "Review before reporting."))
            if required and status == "Not ready":
                add_row(check, "Not ready", evidence, action)
            elif required and status in {"Review", "Missing"}:
                add_row(check, "Report with caveat", evidence, action)
            elif (not required) and status in {"Review", "Missing", "Not ready"}:
                add_row(check, "Boundary", evidence, action)

    if isinstance(guide, pd.DataFrame) and not guide.empty:
        for _, row in guide.iterrows():
            area = str(row.get("ManuscriptArea", "Manuscript area"))
            status = str(row.get("ClaimStatus", ""))
            evidence = str(row.get("EvidenceToReport", ""))
            action = str(row.get("NextAction", "Review before reporting."))
            do_not = str(row.get("DoNotClaim", ""))
            if area in blocking_areas and status == "Do not claim":
                add_row(area, "Not ready", evidence, action)
            elif area in optional_claim_areas and status == "Report with caveat":
                add_row(area, "Boundary", evidence, action)
            elif status == "Report with caveat":
                add_row(area, "Report with caveat", evidence, action)
            elif status == "Do not claim":
                add_row(area, "Boundary", do_not or evidence, action)
            elif status == "Boundary":
                add_row(area, "Boundary", do_not or evidence, action)

    detail = pd.DataFrame(rows).drop_duplicates() if rows else pd.DataFrame(
        columns=["GateArea", "GateStatus", "Evidence", "ManuscriptAction"]
    )
    n_blockers = int((detail["GateStatus"] == "Not ready").sum()) if not detail.empty else 0
    n_caveats = int((detail["GateStatus"] == "Report with caveat").sum()) if not detail.empty else 0
    n_boundaries = int((detail["GateStatus"] == "Boundary").sum()) if not detail.empty else 0
    if n_blockers:
        overall_status = "Not ready"
        overall_action = "Do not copy final APA conclusions until blocker rows are resolved."
    elif n_caveats:
        overall_status = "Report with caveat"
        overall_action = "Report results only with the listed caveats and avoid over-claiming."
    else:
        overall_status = "Ready"
        overall_action = "APA text can be used as a draft after study-specific editing."
    overall = pd.DataFrame([{
        "GateArea": "Overall manuscript gate",
        "GateStatus": overall_status,
        "Evidence": (
            f"{n_blockers} blocker(s), {n_caveats} caveat row(s), "
            f"{n_boundaries} boundary row(s)."
        ),
        "ManuscriptAction": overall_action,
    }])
    if detail.empty:
        return overall
    status_order = {"Not ready": 0, "Report with caveat": 1, "Boundary": 2, "Ready": 3}
    detail["_sort"] = detail["GateStatus"].map(status_order).fillna(3)
    detail = detail.sort_values(["_sort", "GateArea"]).drop(columns=["_sort"]).reset_index(drop=True)
    return pd.concat([overall, detail], ignore_index=True)


REPORT_READY_SUMMARY_STATUS_ORDER: dict[str, int] = {
    "Do not report yet": 0,
    "Needs rerun": 1,
    "Needs caveat": 2,
    "Ready": 3,
}


def _report_ready_summary_status(status: object) -> str:
    """Map detailed gate/QC statuses into a four-state report decision."""
    text = str(status or "").strip()
    low = text.lower()
    if not text:
        return "Needs caveat"
    if text in {"Ready", "OK", "Keep original scale", "Report-ready"}:
        return "Ready"
    if text in {"Not ready", "Do not claim", "Do not report yet"}:
        return "Do not report yet"
    if text in {"Missing", "Missing evidence", "Unavailable"}:
        return "Needs rerun"
    if "do not copy" in low or "do not claim" in low or "not ready" in low:
        return "Do not report yet"
    if "missing" in low or "unavailable" in low:
        return "Needs rerun"
    if any(token in low for token in ("caveat", "boundary", "review", "caution", "sensitivity")):
        return "Needs caveat"
    return "Ready"


def _worst_report_ready_summary_status(statuses: Iterable[object]) -> str:
    normalized = [_report_ready_summary_status(status) for status in statuses]
    if not normalized:
        return "Needs caveat"
    return min(
        normalized,
        key=lambda status: REPORT_READY_SUMMARY_STATUS_ORDER.get(status, 2),
    )


def _report_ready_summary_counts(frame: pd.DataFrame, column: str) -> str:
    if not isinstance(frame, pd.DataFrame) or frame.empty or column not in frame.columns:
        return "no rows"
    counts = frame[column].astype(str).value_counts(dropna=False).to_dict()
    return "; ".join(f"{key}: {int(value)}" for key, value in sorted(counts.items()))


def _report_ready_use_now(status: object) -> str:
    status = _report_ready_summary_status(status)
    if status == "Ready":
        return "Use as draft reporting evidence after study-specific editing."
    if status == "Needs caveat":
        return "Use only bounded claims; keep caveats visible in Results, notes, or limitations."
    if status == "Needs rerun":
        return "Use for troubleshooting and planning; regenerate report text after the missing evidence is computed."
    return "Use only as an internal diagnostic record; do not write final conclusions from this run."


def build_report_ready_summary_panel(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
) -> pd.DataFrame:
    """One-screen report-writing decision panel for the current run.

    The panel compresses readiness, publication-gate, APA sentence,
    claim-evidence, scoring-quality, and category-collapse outputs into
    action rows. It is intentionally conservative and points back to the
    detailed evidence files instead of replacing them.
    """
    if not isinstance(result, dict):
        return pd.DataFrame()
    diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
    all_bias = all_bias_results or {}
    if not all_bias and isinstance(bias_results, dict) and bias_results:
        pair_label = f"{bias_results.get('facet_a', 'A')} x {bias_results.get('facet_b', 'B')}"
        all_bias = {pair_label: bias_results}

    readiness = _safe_guided_evidence_frame(build_final_report_readiness, result, diagnostics, all_bias)
    gate = _safe_guided_evidence_frame(build_publication_gate_summary, result, diagnostics, all_bias)
    claim_matrix = _safe_guided_evidence_frame(build_claim_to_evidence_matrix, result, diagnostics, all_bias)
    apa_audit = _safe_guided_evidence_frame(
        build_apa_report_sentence_audit,
        result,
        diagnostics,
        all_bias_results=all_bias,
    )
    scoring_first = _safe_guided_evidence_frame(build_scoring_quality_first_read_summary, result, diagnostics)
    scoring_decision = _safe_guided_evidence_frame(build_scoring_consistency_decision, result, diagnostics)
    category_action = _safe_guided_evidence_frame(category_collapse_action_center_table, result, diagnostics)

    rows: list[dict[str, object]] = []

    def add_row(
        priority: int,
        area: str,
        status: object,
        users: str,
        open_first: str,
        evidence_files: str,
        action: str,
        safe_wording: str,
        do_not_write: str,
        details: str,
    ) -> None:
        report_status = _report_ready_summary_status(status)
        rows.append({
            "_Sort": REPORT_READY_SUMMARY_STATUS_ORDER.get(report_status, 2) * 100 + int(priority),
            "Priority": int(priority),
            "ReportArea": str(area),
            "ReportStatus": report_status,
            "PrimaryUsers": str(users),
            "UseNow": _report_ready_use_now(report_status),
            "OpenFirst": str(open_first),
            "EvidenceFiles": str(evidence_files),
            "ActionBeforeWriting": str(action),
            "SafeWording": str(safe_wording),
            "DoNotWrite": str(do_not_write),
            "Details": str(details),
        })

    overall_gate = _table_row_by_value(gate, "GateArea", "Overall manuscript gate")
    gate_status = _handoff_text(
        overall_gate.get("GateStatus") if overall_gate is not None else "",
        "Needs caveat",
    )
    required_statuses: list[object] = []
    if isinstance(readiness, pd.DataFrame) and not readiness.empty and {"Required", "Status"}.issubset(readiness.columns):
        required_rows = readiness.loc[readiness["Required"].astype(str).eq("Yes")]
        required_statuses = required_rows["Status"].astype(str).tolist()
    overall_status = _worst_report_ready_summary_status([gate_status, *required_statuses])
    add_row(
        1,
        "Overall manuscript conclusion",
        overall_status,
        "Paper author; measurement practitioner; scoring manager",
        "Report -> APA Report; Report -> Readiness",
        "publication_gate_summary.csv; final_report_readiness.csv; submission_action_plan.csv",
        _handoff_text(
            overall_gate.get("ManuscriptAction") if overall_gate is not None else "",
            "Review the publication gate and readiness rows before using generated report text.",
        ),
        (
            "The fitted MFRM results were interpreted within the stated diagnostics, caveats, and study design."
            if overall_status == "Ready" else
            "The fitted MFRM results were interpreted only within the evidence-supported and caveated scope."
        ),
        "Do not turn generated text into final conclusions when blocker, missing, or caveat rows remain unresolved.",
        _handoff_text(
            overall_gate.get("Evidence") if overall_gate is not None else "",
            f"required readiness statuses: {_report_ready_summary_counts(readiness, 'Status')}",
        ),
    )

    apa_status = (
        _worst_report_ready_summary_status(apa_audit["CopyDecision"].tolist())
        if isinstance(apa_audit, pd.DataFrame) and not apa_audit.empty and "CopyDecision" in apa_audit.columns
        else "Needs rerun"
    )
    add_row(
        2,
        "APA sentence draft",
        apa_status,
        "Paper author",
        "Report -> APA Report",
        "apa_report_sentence_audit.csv; claim_to_evidence_matrix.csv; method_reference_audit.csv",
        "Filter generated sentences by CopyDecision; edit every sentence for study design, rubric labels, and citations.",
        "Use generated APA text as a draft only when each sentence has an evidence row and any caveat remains visible.",
        "Do not copy a generated sentence whose CopyDecision blocks or caveats it without revising the claim.",
        (
            f"{len(apa_audit)} sentence row(s); "
            f"copy decisions: {_report_ready_summary_counts(apa_audit, 'CopyDecision')}"
            if isinstance(apa_audit, pd.DataFrame) and not apa_audit.empty else
            "APA sentence audit was not generated."
        ),
    )

    claim_statuses: list[object] = []
    if isinstance(claim_matrix, pd.DataFrame) and not claim_matrix.empty:
        for col in ("ClaimStatus", "GateStatus"):
            if col in claim_matrix.columns:
                claim_statuses.extend(claim_matrix[col].astype(str).tolist())
    claim_panel_status = _worst_report_ready_summary_status(claim_statuses) if claim_statuses else "Needs rerun"
    add_row(
        3,
        "Claim boundary and evidence",
        claim_panel_status,
        "Paper author; reviewer response lead",
        "Report -> Claim Guide; Downloads -> Data Tables",
        "claim_to_evidence_matrix.csv; manuscript_claim_guide.csv; publication_gate_summary.csv",
        "Match each planned manuscript claim to a table, figure, diagnostic row, caveat, and archive file.",
        "State claims only for the computed facet structure, screened pairs, and diagnostics that were actually produced.",
        "Do not make broad validity, fairness, category, or equivalence claims without a traceable evidence row.",
        (
            f"{len(claim_matrix)} claim area(s); "
            f"ClaimStatus: {_report_ready_summary_counts(claim_matrix, 'ClaimStatus')}; "
            f"GateStatus: {_report_ready_summary_counts(claim_matrix, 'GateStatus')}"
            if isinstance(claim_matrix, pd.DataFrame) and not claim_matrix.empty else
            "Claim-to-evidence matrix was not generated."
        ),
    )

    if isinstance(scoring_first, pd.DataFrame) and not scoring_first.empty:
        sf = scoring_first.iloc[0]
        scoring_status = str(sf.get("ReadinessLabel", "Needs caveat"))
        scoring_action = str(sf.get("NextAction", "Review scoring consistency decision rows."))
        scoring_safe = str(sf.get("SafeClaim", "Report scoring quality as converging evidence with caveats."))
        scoring_do_not = str(sf.get("DoNotClaim", "Do not state that scoring is report-ready before QC evidence supports it."))
        scoring_details = (
            f"overall status: {sf.get('OverallStatus', 'not available')}; "
            f"blocking items: {sf.get('BlockingItems', 'not available')}; "
            f"caveat items: {sf.get('CaveatItems', 'not available')}"
        )
    else:
        scoring_status = (
            _worst_report_ready_summary_status(scoring_decision["Status"].tolist())
            if isinstance(scoring_decision, pd.DataFrame) and not scoring_decision.empty and "Status" in scoring_decision.columns
            else "Needs rerun"
        )
        scoring_action = "Open scoring consistency and QC checklist rows before writing scoring-quality claims."
        scoring_safe = "Report scoring quality only as converging evidence from agreement, alpha, rater fit, and category diagnostics."
        scoring_do_not = "Do not state that scoring quality is established from one agreement or fit statistic alone."
        scoring_details = _report_ready_summary_counts(scoring_decision, "Status")
    add_row(
        4,
        "Scoring quality and QC decision",
        scoring_status,
        "Scoring manager; paper author; measurement practitioner",
        "Agreement / QC; Report -> APA Report",
        "scoring_quality_first_read_summary.csv; scoring_consistency_decision.csv; quality_control_todo_checklist.csv",
        scoring_action,
        scoring_safe,
        scoring_do_not,
        scoring_details,
    )

    if isinstance(category_action, pd.DataFrame) and not category_action.empty:
        cat = category_action.iloc[0]
        cat_status = str(cat.get("Status", "Needs caveat"))
        cat_action = str(cat.get("RecommendedAction", "Review category-collapse action center rows."))
        cat_safe = str(cat.get("ReportReadyWording", "Report category functioning only with the available evidence."))
        cat_do_not = str(cat.get("DoNotClaim", "Do not collapse categories solely from one diagnostic."))
        cat_details = str(cat.get("EvidenceSummary", _report_ready_summary_counts(category_action, "Status")))
    else:
        cat_status = "Needs rerun"
        cat_action = "Run or inspect category counts, threshold order, and category-curve diagnostics."
        cat_safe = "Report only the category-functioning evidence that was computed."
        cat_do_not = "Do not claim category distinctness or collapse readiness without category diagnostics."
        cat_details = "Category-collapse action center was not generated."
    add_row(
        5,
        "Rubric categories and collapse sensitivity",
        cat_status,
        "Rubric owner; scoring manager; paper author",
        "Categories / Steps; Visuals -> category curves",
        "category_collapse_action_center.csv; rating_scale_decision_support.csv; rating_scale_recode_candidates.csv",
        cat_action,
        cat_safe,
        cat_do_not,
        cat_details,
    )

    if not rows:
        return pd.DataFrame()
    out = pd.DataFrame(rows)
    out = out.sort_values(["_Sort", "Priority", "ReportArea"]).drop(columns=["_Sort"]).reset_index(drop=True)
    out["Priority"] = np.arange(1, len(out) + 1, dtype=int)
    return out


def _report_ready_summary_overall_status(panel: pd.DataFrame) -> str:
    if not isinstance(panel, pd.DataFrame) or panel.empty or "ReportStatus" not in panel.columns:
        return "Needs caveat"
    return _worst_report_ready_summary_status(panel["ReportStatus"].astype(str).tolist())


def _unique_evidence_files_from_text(values: Iterable[object]) -> list[str]:
    files: list[str] = []
    seen: set[str] = set()
    for value in values:
        for part in re.split(r"[;,|]", str(value or "")):
            clean = part.strip()
            if not clean or "." not in clean:
                continue
            if clean not in seen:
                seen.add(clean)
                files.append(clean)
    return files


def _markdown_bullets(values: Iterable[object], *, default: str = "- Not available.") -> str:
    clean = [str(value).strip() for value in values if str(value).strip()]
    if not clean:
        return default
    return "\n".join(f"- {value}" for value in clean)


def generate_report_ready_decision_brief(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
) -> str:
    """Generate a short decision memo from the report-ready summary panel."""
    panel = build_report_ready_summary_panel(
        result,
        diagnostics,
        all_bias_results=all_bias_results,
        bias_results=bias_results,
    )
    if not isinstance(panel, pd.DataFrame) or panel.empty:
        return "\n".join([
            "# Report-Ready Decision Brief",
            "",
            "No report-ready summary rows were generated for this run.",
            "Regenerate the run or inspect exported diagnostics before writing conclusions.",
            "",
        ])

    overall_status = _report_ready_summary_overall_status(panel)
    status_counts = panel["ReportStatus"].astype(str).value_counts().to_dict()
    status_summary = "; ".join(
        f"{status}: {int(status_counts.get(status, 0))}"
        for status in REPORT_READY_SUMMARY_STATUS_ORDER
        if int(status_counts.get(status, 0))
    ) or "no status rows"
    config = result.get("config", {}) if isinstance(result, dict) else {}
    prep = result.get("prep", {}) if isinstance(result, dict) else {}
    facet_names = ", ".join(map(str, config.get("facet_names", []) or [])) if isinstance(config, dict) else ""

    def row_lines(statuses: set[str], template: str) -> list[str]:
        rows = panel.loc[panel["ReportStatus"].astype(str).isin(statuses)]
        out: list[str] = []
        for _, row in rows.iterrows():
            out.append(template.format(
                area=row.get("ReportArea", "Report area"),
                status=row.get("ReportStatus", "Needs caveat"),
                users=row.get("PrimaryUsers", "Paper author"),
                use_now=row.get("UseNow", ""),
                open_first=row.get("OpenFirst", ""),
                action=row.get("ActionBeforeWriting", ""),
                safe=row.get("SafeWording", ""),
                do_not=row.get("DoNotWrite", ""),
            ))
        return out

    writeable_rows = row_lines(
        {"Ready", "Needs caveat"},
        "**{area}** ({status}; {users}): {use_now} Open first: {open_first}.",
    )
    hold_rows = row_lines(
        {"Needs rerun", "Do not report yet"},
        "**{area}** ({status}): {action} Open first: {open_first}.",
    )
    safe_wording = row_lines(
        {"Ready", "Needs caveat"},
        "**{area}**: {safe}",
    )
    do_not = [
        f"**{row.get('ReportArea', 'Report area')}**: {row.get('DoNotWrite', '')}"
        for _, row in panel.iterrows()
        if str(row.get("DoNotWrite", "")).strip()
    ]
    evidence_files = _unique_evidence_files_from_text(panel.get("EvidenceFiles", pd.Series(dtype=object)).tolist())

    lines = [
        "# Report-Ready Decision Brief",
        "",
        "## Overall Decision",
        "",
        f"- Overall status: **{overall_status}**.",
        f"- Status counts: {status_summary}.",
        f"- Model/method: {config.get('model', 'unknown') if isinstance(config, dict) else 'unknown'} / {config.get('method', 'unknown') if isinstance(config, dict) else 'unknown'}.",
        f"- Observations/persons: {prep.get('n_obs', 'unknown') if isinstance(prep, dict) else 'unknown'} observations; {prep.get('n_person', 'unknown') if isinstance(prep, dict) else 'unknown'} persons.",
        f"- Facets: {facet_names or 'not recorded'}.",
        "",
        "## Can Be Used Now",
        "",
        _markdown_bullets(writeable_rows, default="- No row is ready for manuscript wording without follow-up."),
        "",
        "## Resolve Before Final Wording",
        "",
        _markdown_bullets(hold_rows, default="- No blocking or rerun row was generated."),
        "",
        "## Conservative Wording To Carry Forward",
        "",
        _markdown_bullets(safe_wording, default="- No conservative wording row was generated."),
        "",
        "## Do Not Write",
        "",
        _markdown_bullets(do_not, default="- No do-not-write boundary was generated."),
        "",
        "## Evidence Files To Keep With The Draft",
        "",
        _markdown_bullets(evidence_files, default="- report_ready_summary_panel.csv"),
        "",
        "## Use Note",
        "",
        "This brief is a manuscript and decision-support aid. It does not replace study-specific interpretation, rubric documentation, privacy review, or journal reporting requirements.",
        "",
    ]
    return "\n".join(lines)


def _apa_results_copy_allowed(copy_decision: object) -> bool:
    text = str(copy_decision or "").strip().lower()
    return bool(text) and not text.startswith("do not copy")


def _apa_critical_review_lines(
    critical_review: pd.DataFrame,
    *,
    stop_only: bool,
) -> list[str]:
    """Convert critical-review rows into APA draft guardrail bullets."""
    if not isinstance(critical_review, pd.DataFrame) or critical_review.empty:
        return []
    work = critical_review.copy()
    if stop_only:
        flag = work.get("StopBeforeFinalOutput", pd.Series(False, index=work.index))
        work = work.loc[flag.fillna(False).astype(bool)].copy()
    else:
        stop_flag = work.get("StopBeforeFinalOutput", pd.Series(False, index=work.index))
        caveat_flag = work.get("NeedsCaveat", pd.Series(False, index=work.index))
        work = work.loc[(~stop_flag.fillna(False).astype(bool)) & caveat_flag.fillna(False).astype(bool)].copy()
    if work.empty:
        return []
    lines: list[str] = []
    for _, row in work.sort_values("Priority").iterrows():
        lines.append(
            f"**{row.get('Lens', 'Critical review')}**: {row.get('Decision', 'Review')}. "
            f"Action: {row.get('ActionBeforeContinuing', 'open the listed evidence')}. "
            f"Evidence: {row.get('EvidenceToOpen', 'critical_final_review_panel.csv')}. "
            f"Do not claim: {row.get('DoNotClaim', 'keep claims within the available evidence')}."
        )
    return lines


def build_apa_bridge_revision_plan(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
    critical_review: pd.DataFrame | None = None,
    reporting_action_bridge: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """Build APA-specific revision instructions from bridge and critical-review rows."""
    all_bias = all_bias_results or {}
    if not all_bias and isinstance(bias_results, dict) and bias_results:
        all_bias = {f"{bias_results.get('facet_a', 'A')} x {bias_results.get('facet_b', 'B')}": bias_results}
    rows: list[dict[str, object]] = []

    def add_row(
        *,
        placement: str,
        track: str,
        status: object,
        blocks_final_copy: bool,
        revision: str,
        required_check: str,
        caveat: str,
        stop_rule: str,
        evidence: str,
        download_file: str,
    ) -> None:
        rows.append({
            "Priority": len(rows) + 1,
            "APAPlacement": str(placement),
            "SourceTrack": str(track),
            "CurrentStatus": _report_ready_summary_status(status),
            "BlocksFinalCopy": bool(blocks_final_copy),
            "RevisionInstruction": str(revision),
            "RequiredCheck": str(required_check),
            "CaveatToCarry": str(caveat),
            "StopRule": str(stop_rule),
            "EvidenceFiles": str(evidence),
            "DownloadFile": str(download_file),
        })

    if isinstance(reporting_action_bridge, pd.DataFrame) and not reporting_action_bridge.empty:
        track = reporting_action_bridge.get(
            "BridgeTrack",
            pd.Series("", index=reporting_action_bridge.index, dtype=object),
        ).astype(str)
        bridge_rows = reporting_action_bridge.loc[
            track.str.contains("APA|Claim-to-evidence|Guided result-reading", case=False, regex=True, na=False)
        ].copy()
        for _, row in bridge_rows.sort_values("Priority").iterrows():
            status = _report_ready_summary_status(row.get("CurrentStatus", "Needs caveat"))
            add_row(
                placement=(
                    "Before paragraph"
                    if str(row.get("BridgeTrack", "")).startswith("APA")
                    else "After paragraph"
                ),
                track=row.get("BridgeTrack", "Reporting action bridge"),
                status=status,
                blocks_final_copy=status in {"Do not report yet", "Needs rerun"},
                revision=row.get("DraftOrDecisionMove", "Keep the bridge instruction visible while editing the APA draft."),
                required_check=row.get("RequiredCheck", "Open the listed evidence files before copying generated wording."),
                caveat=row.get("CaveatToCarry", "Keep caveats visible in the Results text."),
                stop_rule=row.get("StopRule", "Do not treat the draft as final until this bridge row is resolved."),
                evidence=row.get("EvidenceFiles", "reporting_action_bridge.csv; apa_report_sentence_audit.csv"),
                download_file=row.get("DownloadFile", "reporting_action_bridge.csv; apa_results_paragraph_draft.md"),
            )

    if not rows:
        if not isinstance(critical_review, pd.DataFrame) or critical_review.empty:
            critical_review = build_critical_final_review_panel(
                result,
                diagnostics,
                all_bias_results=all_bias,
                bias_results=bias_results,
            )
        if isinstance(critical_review, pd.DataFrame) and not critical_review.empty:
            lens = critical_review.get(
                "Lens",
                pd.Series("", index=critical_review.index, dtype=object),
            ).astype(str)
            critical_rows = critical_review.loc[
                lens.str.contains("APA|Claim|Manuscript", case=False, regex=True, na=False)
            ].copy()
            for _, row in critical_rows.sort_values("Priority").iterrows():
                stop = bool(row.get("StopBeforeFinalOutput", False))
                add_row(
                    placement="Before paragraph" if "APA" in str(row.get("Lens", "")) else "After paragraph",
                    track=row.get("Lens", "Critical final review"),
                    status=row.get("CurrentStatus", "Needs caveat"),
                    blocks_final_copy=stop,
                    revision=(
                        "Use this Results paragraph as an editing worksheet only until this blocker is resolved."
                        if stop else
                        "Use the Results paragraph only with this caveat visible during editing."
                    ),
                    required_check=row.get("EvidenceToOpen", "critical_final_review_panel.csv"),
                    caveat=row.get("DoNotClaim", "Keep claims within the computed evidence."),
                    stop_rule=row.get("ActionBeforeContinuing", "Open the critical final review before copying generated wording."),
                    evidence=row.get("EvidenceToOpen", "critical_final_review_panel.csv"),
                    download_file="critical_final_review_panel.csv; reporting_action_bridge.csv; apa_results_paragraph_draft.md",
                )

    if not rows:
        add_row(
            placement="Before paragraph",
            track="APA draft guardrail",
            status="Needs caveat",
            blocks_final_copy=False,
            revision="Use generated APA text as an editable draft, not as final Results wording.",
            required_check="Open the APA sentence audit and report-ready summary before copying.",
            caveat="Carry any caveat listed in the sentence audit or report-ready summary.",
            stop_rule="Do not treat missing bridge rows as evidence that no review is needed.",
            evidence="apa_report_sentence_audit.csv; report_ready_summary_panel.csv; reporting_action_bridge.csv",
            download_file="apa_results_paragraph_draft.md; reporting_action_bridge.csv",
        )

    return pd.DataFrame(rows).reset_index(drop=True)


def _apa_bridge_revision_lines(plan: pd.DataFrame, *, blockers_only: bool = False) -> list[str]:
    if not isinstance(plan, pd.DataFrame) or plan.empty:
        return []
    work = plan.copy()
    if blockers_only and "BlocksFinalCopy" in work.columns:
        work = work.loc[work["BlocksFinalCopy"].fillna(False).astype(bool)].copy()
    if work.empty:
        return []
    lines: list[str] = []
    for _, row in work.sort_values("Priority").iterrows():
        lines.append(
            f"**{row.get('SourceTrack', 'Bridge row')}** ({row.get('CurrentStatus', 'Needs caveat')}): "
            f"{row.get('RevisionInstruction', 'review before copying')}. "
            f"Check: {row.get('RequiredCheck', 'open the listed evidence')}. "
            f"Caveat: {row.get('CaveatToCarry', 'keep caveats visible')}. "
            f"Evidence: {row.get('EvidenceFiles', 'reporting_action_bridge.csv')}."
        )
    return lines


def _simulation_sparse_context_lines(context: pd.DataFrame, *, blockers_only: bool = False) -> list[str]:
    if not isinstance(context, pd.DataFrame) or context.empty:
        return []
    work = context.copy()
    if blockers_only and "ReportStatus" in work.columns:
        work = work.loc[work["ReportStatus"].astype(str).isin(["Do not report yet", "Needs rerun"])].copy()
    if work.empty:
        return []
    lines: list[str] = []
    for _, row in work.sort_values("Priority").iterrows():
        lines.append(
            f"**{row.get('SimulationCheck', 'Simulation design')}** ({row.get('ReportStatus', 'Needs caveat')}): "
            f"{row.get('ActionBeforeReporting', 'review the sparse-design audit')}. "
            f"Caveat: {row.get('CaveatToCarry', 'keep simulation design caveats visible')}. "
            f"Evidence: {row.get('EvidenceFiles', 'custom_simulation_sparse_design_audit.csv')}."
        )
    return lines


def _simulation_settings_lines(settings: pd.DataFrame) -> list[str]:
    if not isinstance(settings, pd.DataFrame) or settings.empty:
        return []
    wanted = {
        "Simulation preset",
        "Persons",
        "Facets",
        "Facet level counts",
        "First-facet levels per person",
        "Score categories",
        "Requested missing rate",
        "Adjacent thresholds",
        "Seed",
    }
    work = settings.loc[settings["Setting"].astype(str).isin(wanted)].copy() if "Setting" in settings.columns else settings.copy()
    if work.empty:
        return []
    lines: list[str] = []
    for _, row in work.sort_values("Priority" if "Priority" in work.columns else "Setting").iterrows():
        lines.append(
            f"**{row.get('Setting', 'Simulation setting')}**: {row.get('Value', '')}. "
            f"Note: {row.get('ReportNote', 'Archive this setting with generated-data results')}."
        )
    return lines


def generate_report_ready_apa_results_draft(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
    critical_review: pd.DataFrame | None = None,
    reporting_action_bridge: pd.DataFrame | None = None,
    apa_bridge_revision_plan: pd.DataFrame | None = None,
    simulation_sparse_context: pd.DataFrame | None = None,
    simulation_settings: pd.DataFrame | None = None,
) -> str:
    """Compose an APA-style Results draft from allowed sentence-audit rows."""
    all_bias = all_bias_results or {}
    if not all_bias and isinstance(bias_results, dict) and bias_results:
        all_bias = {f"{bias_results.get('facet_a', 'A')} x {bias_results.get('facet_b', 'B')}": bias_results}
    panel = build_report_ready_summary_panel(
        result,
        diagnostics,
        all_bias_results=all_bias,
        bias_results=bias_results,
    )
    apa_audit = build_apa_report_sentence_audit(
        result,
        diagnostics,
        bias_results=bias_results,
        all_bias_results=all_bias,
    )
    overall_status = _report_ready_summary_overall_status(panel)
    if not isinstance(critical_review, pd.DataFrame) or critical_review.empty:
        critical_review = build_critical_final_review_panel(
            result,
            diagnostics,
            all_bias_results=all_bias,
            bias_results=bias_results,
        )
    final_blocker_lines = _apa_critical_review_lines(critical_review, stop_only=True)
    critical_caveat_lines = _apa_critical_review_lines(critical_review, stop_only=False)
    if not isinstance(apa_bridge_revision_plan, pd.DataFrame) or apa_bridge_revision_plan.empty:
        apa_bridge_revision_plan = build_apa_bridge_revision_plan(
            result,
            diagnostics,
            all_bias_results=all_bias,
            bias_results=bias_results,
            critical_review=critical_review,
            reporting_action_bridge=reporting_action_bridge,
        )
    bridge_blocker_lines = _apa_bridge_revision_lines(apa_bridge_revision_plan, blockers_only=True)
    bridge_revision_lines = _apa_bridge_revision_lines(apa_bridge_revision_plan, blockers_only=False)
    simulation_blocker_lines = _simulation_sparse_context_lines(simulation_sparse_context, blockers_only=True)
    simulation_context_lines = _simulation_sparse_context_lines(simulation_sparse_context, blockers_only=False)
    simulation_setting_lines = _simulation_settings_lines(simulation_settings)
    if not isinstance(apa_audit, pd.DataFrame) or apa_audit.empty:
        return "\n".join([
            "# APA Results Paragraph Draft",
            "",
            f"Overall report-ready status: **{overall_status}**.",
            "",
            "## Final-Output Blockers",
            "",
            _markdown_bullets(final_blocker_lines, default="- No critical final-review row currently stops final output."),
            "",
            "## Bridge-Constrained Use Conditions",
            "",
            _markdown_bullets(bridge_revision_lines, default="- Open `reporting_action_bridge.csv` before treating generated wording as final."),
            "",
            "## Simulation Design Use Conditions",
            "",
            _markdown_bullets(simulation_context_lines, default="- No custom-simulation sparse-design context was attached to this draft."),
            "",
            "## Simulation Settings To Archive",
            "",
            _markdown_bullets(simulation_setting_lines, default="- No custom-simulation settings table was attached to this draft."),
            "",
            "No APA sentence audit rows were generated. Regenerate diagnostics before drafting Results prose.",
            "",
            "Evidence file to open first: `critical_final_review_panel.csv`; `reporting_action_bridge.csv`; `custom_simulation_settings.csv` and `custom_simulation_sparse_reporting_context.csv` if generated data were used.",
            "",
        ])

    copy_allowed = apa_audit["CopyDecision"].apply(_apa_results_copy_allowed) if "CopyDecision" in apa_audit.columns else pd.Series(False, index=apa_audit.index)
    is_results = apa_audit["APASection"].astype(str).eq("Results") if "APASection" in apa_audit.columns else pd.Series(False, index=apa_audit.index)
    allowed_results = apa_audit.loc[copy_allowed & is_results].copy()
    blocked_results = apa_audit.loc[(~copy_allowed) & is_results].copy()
    allowed_copy_decision = allowed_results.get(
        "CopyDecision",
        pd.Series("", index=allowed_results.index, dtype=object),
    ).astype(str)
    allowed_claim_status = allowed_results.get(
        "ClaimStatus",
        pd.Series("", index=allowed_results.index, dtype=object),
    ).astype(str)
    allowed_gate_status = allowed_results.get(
        "GateStatus",
        pd.Series("", index=allowed_results.index, dtype=object),
    ).astype(str)
    caveated_results = allowed_results.loc[
        allowed_copy_decision.str.contains("caveat", case=False, na=False)
        | allowed_claim_status.isin(["Report with caveat", "Review", "Boundary"])
        | allowed_gate_status.isin(["Report with caveat", "Boundary"])
    ].copy()

    draft_sentences = allowed_results.get("DraftSentence", pd.Series(dtype=object)).astype(str).str.strip().tolist()
    draft_paragraph = " ".join(sentence for sentence in draft_sentences if sentence)
    if not draft_paragraph:
        draft_paragraph = "No Results sentence is currently copyable from the APA sentence audit."
    elif simulation_blocker_lines:
        draft_paragraph = (
            "Simulation design worksheet only; do not paste as final Results text until generated-design stop rules are resolved or explicitly documented as stress-test conditions. "
            f"{draft_paragraph}"
        )
    elif bridge_blocker_lines:
        draft_paragraph = (
            "Editing worksheet only; do not paste as final Results text until the bridge stop rules are resolved. "
            f"{draft_paragraph}"
        )
    elif simulation_context_lines or bridge_revision_lines:
        draft_paragraph = (
            "Caveat-carrying draft; keep the bridge and simulation design conditions visible while editing. "
            f"{draft_paragraph}"
        )

    caveat_lines = []
    for _, row in caveated_results.iterrows():
        caveat_lines.append(
            f"{row.get('SentenceRole', 'Results sentence')}: keep caveat visible; "
            f"evidence files: {row.get('EvidenceFiles', 'not recorded')}; "
            f"boundary: {row.get('DoNotClaim', 'keep within computed evidence')}."
        )
    blocked_lines = []
    for _, row in blocked_results.iterrows():
        blocked_lines.append(
            f"{row.get('SentenceRole', 'Results sentence')}: {row.get('CopyDecision', 'Do not copy')}; "
            f"needed evidence: {row.get('BeforeSubmissionCheck', 'review evidence first')}."
        )
    evidence_files = _unique_evidence_files_from_text(
        allowed_results.get("EvidenceFiles", pd.Series(dtype=object)).tolist()
        + panel.get("EvidenceFiles", pd.Series(dtype=object)).tolist()
        + ["critical_final_review_panel.csv"]
    )
    simulation_evidence_files = _unique_evidence_files_from_text(
        simulation_sparse_context.get("EvidenceFiles", pd.Series(dtype=object)).tolist()
        if isinstance(simulation_sparse_context, pd.DataFrame) and not simulation_sparse_context.empty
        else []
    )
    simulation_settings_files = ["custom_simulation_settings.csv"] if simulation_setting_lines else []

    lines = [
        "# APA Results Paragraph Draft",
        "",
        f"Overall report-ready status: **{overall_status}**.",
        "",
        "## Final-Output Blockers",
        "",
        _markdown_bullets(final_blocker_lines, default="- No critical final-review row currently stops final output."),
        "",
        "## Critical Review Caveats",
        "",
        _markdown_bullets(critical_caveat_lines, default="- No additional critical-review caveat row was generated."),
        "",
        "## Bridge-Constrained Use Conditions",
        "",
        _markdown_bullets(bridge_revision_lines, default="- Open `reporting_action_bridge.csv` before treating generated wording as final."),
        "",
        "## Simulation Design Use Conditions",
        "",
        _markdown_bullets(simulation_context_lines, default="- No custom-simulation sparse-design context was attached to this draft."),
        "",
        "## Simulation Settings To Archive",
        "",
        _markdown_bullets(simulation_setting_lines, default="- No custom-simulation settings table was attached to this draft."),
        "",
        "## Draft Paragraph",
        "",
        draft_paragraph,
        "",
        "## Bridge Revision Plan",
        "",
        _markdown_bullets(bridge_revision_lines, default="- No bridge revision row was generated."),
        "",
        "## Caveats To Keep Visible",
        "",
        _markdown_bullets(caveat_lines, default="- No caveated Results sentence was selected."),
        "",
        "## Do Not Use Yet",
        "",
        _markdown_bullets(blocked_lines, default="- No blocked Results sentence was selected."),
        "",
        "## Evidence Files",
        "",
        _markdown_bullets(evidence_files + simulation_evidence_files + simulation_settings_files + ["reporting_action_bridge.csv"], default="- apa_report_sentence_audit.csv"),
        "",
        "## Editing Note",
        "",
        "Treat this paragraph as a draft. Verify numbers against exported tables, add study-specific labels, and preserve any caveat required by the sentence audit or report-ready summary.",
        "",
    ]
    return "\n".join(lines)


def _role_memo_row_by_area(panel: pd.DataFrame, area: str) -> pd.Series | None:
    if not isinstance(panel, pd.DataFrame) or panel.empty or "ReportArea" not in panel.columns:
        return None
    hit = panel.loc[panel["ReportArea"].astype(str) == str(area)]
    return hit.iloc[0] if not hit.empty else None


def _role_memo_qc_row(qc: pd.DataFrame, decision: str) -> pd.Series:
    if isinstance(qc, pd.DataFrame) and not qc.empty and "QCDecision" in qc.columns:
        hit = qc.loc[qc["QCDecision"].astype(str) == str(decision)]
        if not hit.empty:
            return hit.iloc[0]
    return pd.Series(dtype=object)


def _role_memo_decision_status(decision: pd.DataFrame, areas: Iterable[str]) -> str:
    if not isinstance(decision, pd.DataFrame) or decision.empty or "DecisionArea" not in decision.columns:
        return "Needs rerun"
    statuses = []
    for area in areas:
        hit = decision.loc[decision["DecisionArea"].astype(str) == str(area)]
        if not hit.empty and "Status" in hit.columns:
            statuses.append(str(hit.iloc[0].get("Status", "Review")))
    return _worst_report_ready_summary_status(statuses) if statuses else "Needs rerun"


def _role_memo_readiness_status(readiness: pd.DataFrame, checks: Iterable[str]) -> str:
    if not isinstance(readiness, pd.DataFrame) or readiness.empty or "Check" not in readiness.columns:
        return "Needs rerun"
    statuses = []
    for check in checks:
        hit = readiness.loc[readiness["Check"].astype(str) == str(check)]
        if not hit.empty and "Status" in hit.columns:
            statuses.append(str(hit.iloc[0].get("Status", "Review")))
    return _worst_report_ready_summary_status(statuses) if statuses else "Needs caveat"


def build_role_based_action_memos(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
) -> pd.DataFrame:
    """Build role-specific action rows from report, QC, and diagnostic evidence."""
    if not isinstance(result, dict):
        return pd.DataFrame()
    diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
    all_bias = all_bias_results or {}
    if not all_bias and isinstance(bias_results, dict) and bias_results:
        all_bias = {f"{bias_results.get('facet_a', 'A')} x {bias_results.get('facet_b', 'B')}": bias_results}

    panel = build_report_ready_summary_panel(
        result,
        diagnostics,
        all_bias_results=all_bias,
        bias_results=bias_results,
    )
    readiness = _safe_guided_evidence_frame(build_final_report_readiness, result, diagnostics, all_bias)
    claim_matrix = _safe_guided_evidence_frame(build_claim_to_evidence_matrix, result, diagnostics, all_bias)
    apa_audit = _safe_guided_evidence_frame(
        build_apa_report_sentence_audit,
        result,
        diagnostics,
        bias_results=bias_results,
        all_bias_results=all_bias,
    )
    scoring_decision = _safe_guided_evidence_frame(build_scoring_consistency_decision, result, diagnostics)
    qc_recommendations = _safe_guided_evidence_frame(build_quality_control_recommendations, result, diagnostics)
    category_action = _safe_guided_evidence_frame(category_collapse_action_center_table, result, diagnostics)
    bias_audit = _safe_guided_evidence_frame(build_bias_inference_audit, all_bias, result, diagnostics) if all_bias else pd.DataFrame()

    overall = _role_memo_row_by_area(panel, "Overall manuscript conclusion")
    apa = _role_memo_row_by_area(panel, "APA sentence draft")
    claim = _role_memo_row_by_area(panel, "Claim boundary and evidence")
    scoring = _role_memo_row_by_area(panel, "Scoring quality and QC decision")
    category = _role_memo_row_by_area(panel, "Rubric categories and collapse sensitivity")
    role_order = {
        "Paper author": 1,
        "Scoring manager": 2,
        "Measurement practitioner": 3,
    }
    rows: list[dict[str, object]] = []

    def panel_value(row: pd.Series | None, column: str, default: str = "") -> str:
        if row is None or row.empty:
            return default
        return _handoff_text(row.get(column), default)

    def add_row(
        *,
        role: str,
        priority: int,
        focus: str,
        status: object,
        why: str,
        action: str,
        evidence: str,
        safe: str,
        do_not: str,
        question: str,
        app_location: str,
        download_file: str,
        details: str,
    ) -> None:
        rows.append({
            "_RoleOrder": role_order.get(role, 99),
            "Role": role,
            "Priority": int(priority),
            "DecisionFocus": focus,
            "ReportStatus": _report_ready_summary_status(status),
            "DecisionQuestion": question,
            "WhyThisMatters": why,
            "ImmediateAction": action,
            "EvidenceToOpen": evidence,
            "SafeOutput": safe,
            "DoNotDo": do_not,
            "AppLocation": app_location,
            "DownloadFile": download_file,
            "Details": details,
        })

    add_row(
        role="Paper author",
        priority=1,
        focus="Results wording",
        status=_worst_report_ready_summary_status([
            panel_value(overall, "ReportStatus", "Needs caveat"),
            panel_value(apa, "ReportStatus", "Needs caveat"),
        ]),
        why="This controls which generated Results sentences can move into the manuscript.",
        action="Open the APA Results paragraph draft, then verify each sentence against the sentence audit before copying.",
        evidence="apa_results_paragraph_draft.md; apa_report_sentence_audit.csv; report_ready_summary_panel.csv",
        safe=panel_value(apa, "SafeWording", "Use generated APA text only as an editable draft with evidence-linked caveats."),
        do_not=panel_value(apa, "DoNotWrite", "Do not copy blocked or unsupported generated APA sentences."),
        question="Which Results sentences can be used now, and which need caveats or rerun evidence?",
        app_location="Report -> APA Report; Report & Export -> Decision brief",
        download_file="apa_results_paragraph_draft.md; apa_report_sentence_audit.csv",
        details=(
            f"APA sentence rows: {len(apa_audit) if isinstance(apa_audit, pd.DataFrame) else 0}; "
            f"copy decisions: {_report_ready_summary_counts(apa_audit, 'CopyDecision')}"
        ),
    )

    add_row(
        role="Paper author",
        priority=2,
        focus="Claim boundary and reviewer evidence",
        status=panel_value(claim, "ReportStatus", "Needs caveat"),
        why="This keeps each manuscript claim tied to tables, figures, diagnostics, caveats, and reviewer questions.",
        action="Use the claim-to-evidence matrix before writing Discussion, limitations, or reviewer-response text.",
        evidence="claim_to_evidence_matrix.csv; manuscript_claim_guide.csv; publication_gate_summary.csv",
        safe=panel_value(claim, "SafeWording", "Keep claims inside the computed facet structure and diagnostic scope."),
        do_not=panel_value(claim, "DoNotWrite", "Do not make broad validity, fairness, or equivalence claims without traceable evidence."),
        question="What evidence file supports each manuscript claim?",
        app_location="Report -> Claim Guide; Downloads -> Data Tables",
        download_file="claim_to_evidence_matrix.csv; manuscript_claim_guide.csv",
        details=(
            f"claim areas: {len(claim_matrix) if isinstance(claim_matrix, pd.DataFrame) else 0}; "
            f"claim statuses: {_report_ready_summary_counts(claim_matrix, 'ClaimStatus')}"
        ),
    )

    rater_training = _role_memo_qc_row(qc_recommendations, "Rater training")
    add_row(
        role="Scoring manager",
        priority=1,
        focus="Rater training decision",
        status=_role_memo_decision_status(scoring_decision, ["Exact/adjacent agreement", "Krippendorff alpha", "Rater fit/severity"]),
        why="Rater training decisions should combine agreement, alpha, rater fit, and severity evidence rather than one statistic.",
        action=_handoff_text(rater_training.get("Action"), "Review agreement, alpha, rater fit, and severity evidence; document the training decision."),
        evidence="quality_control_todo_checklist.csv; scoring_consistency_decision.csv; agreement_pairs.csv; fit_statistics.csv",
        safe=_handoff_text(rater_training.get("ReportableWording"), "Rater training was evaluated using agreement and MFRM rater diagnostics."),
        do_not=_handoff_text(rater_training.get("DoNotClaim"), "Do not attribute disagreement to rater behavior without checking rubric/category evidence."),
        question="Should scoring operations prioritize rater training, moderation, or routine monitoring?",
        app_location="Agreement / QC; Fit Details; Measures",
        download_file="quality_control_todo_checklist.csv; scoring_consistency_decision.csv",
        details=_handoff_text(rater_training.get("TriggerEvidence"), panel_value(scoring, "Details", "QC evidence not available.")),
    )

    rubric_revision = _role_memo_qc_row(qc_recommendations, "Rubric revision")
    add_row(
        role="Scoring manager",
        priority=2,
        focus="Rubric revision decision",
        status=_role_memo_decision_status(scoring_decision, ["Rubric/category functioning"]),
        why="Rubric wording and category evidence must point to the same interpretation before operational changes are made.",
        action=_handoff_text(rubric_revision.get("Action"), "Review category evidence and rubric descriptors before changing scoring guidance."),
        evidence="rating_scale_decision_support.csv; rating_scale_category_evidence.csv; category_probability_curves.csv",
        safe=_handoff_text(rubric_revision.get("ReportableWording"), "Rubric/category functioning was reviewed with category support and curve evidence."),
        do_not=_handoff_text(rubric_revision.get("DoNotClaim"), "Do not revise the rubric only because one statistic was unfavorable."),
        question="Does the evidence point to rubric clarification, or only to cautious reporting?",
        app_location="Categories / Steps; Visuals -> category curves",
        download_file="rating_scale_decision_support.csv; rating_scale_category_evidence.csv",
        details=_handoff_text(rubric_revision.get("TriggerEvidence"), panel_value(category, "Details", "Category evidence not available.")),
    )

    collapse = _role_memo_qc_row(qc_recommendations, "Category collapse")
    add_row(
        role="Scoring manager",
        priority=3,
        focus="Category collapse sensitivity",
        status=panel_value(category, "ReportStatus", "Needs caveat"),
        why="Category collapse should be a planned sensitivity comparison, not an automatic repair.",
        action=_handoff_text(collapse.get("Action"), panel_value(category, "ActionBeforeWriting", "Open category-collapse action rows before deciding on recoding.")),
        evidence="category_collapse_action_center.csv; rating_scale_recode_candidates.csv; rating_scale_decision_support.csv",
        safe=panel_value(category, "SafeWording", "Report category collapse only as a sensitivity comparison with rubric justification."),
        do_not=panel_value(category, "DoNotWrite", "Do not collapse categories solely because one diagnostic is flagged."),
        question="Should the original scoring be retained, or should a justified adjacent-category sensitivity run be added?",
        app_location="Categories / Steps; Report -> Readiness",
        download_file="category_collapse_action_center.csv; rating_scale_recode_candidates.csv",
        details=(
            _handoff_text(collapse.get("TriggerEvidence"), "")
            or (str(category_action.iloc[0].get("EvidenceSummary", "")) if isinstance(category_action, pd.DataFrame) and not category_action.empty else "")
            or panel_value(category, "Details", "Category-collapse evidence not available.")
        ),
    )

    add_row(
        role="Measurement practitioner",
        priority=1,
        focus="Model fit and dimensionality",
        status=_role_memo_readiness_status(readiness, ["Convergence", "Global residual fit", "Dimensionality screen", "Reliability / separation"]),
        why="Fit, dimensionality, and reliability determine how far substantive interpretation can go.",
        action="Review convergence, residual fit, PCA/stability, reliability, and fit rows before approving report wording.",
        evidence="final_report_readiness.csv; fit_statistics.csv; residuals.csv; pca_stability_audit.csv; reliability.csv",
        safe="Describe fit and dimensionality as screened diagnostics, with any instability or missing evidence stated explicitly.",
        do_not="Do not treat convergence, global fit, reliability, or residual PCA as a single standalone proof of model adequacy.",
        question="Do the diagnostics support the planned interpretation, or should the claim be narrowed?",
        app_location="Fit Details; Dimensionality; Reliability",
        download_file="final_report_readiness.csv; pca_stability_audit.csv; reliability.csv",
        details=_report_ready_summary_counts(readiness, "Status"),
    )

    add_row(
        role="Measurement practitioner",
        priority=2,
        focus="Bias/local interaction scope",
        status=(
            _worst_report_ready_summary_status(bias_audit["Status"].tolist())
            if isinstance(bias_audit, pd.DataFrame) and not bias_audit.empty and "Status" in bias_audit.columns
            else "Needs caveat"
        ),
        why="Bias/local interaction claims are conditional screens and must remain within computed pairs and cells.",
        action="Check screened facet pairs, sparse cells, multiplicity adjustments, common-scale status, and flagged-cell substance.",
        evidence="bias_inference_audit.csv; bias_*.csv; dff_bias_*.csv; claim_to_evidence_matrix.csv",
        safe="Report only the computed conditional bias/local interaction screen and its caveats.",
        do_not="Do not claim absence of bias outside the screened facet pairs, cells, and connected design.",
        question="Which pairs and cells were actually screened, and which flags require substantive review?",
        app_location="Bias / Interaction; Downloads -> Data Tables",
        download_file="bias_inference_audit.csv; dff_bias_*.csv",
        details=(
            f"bias pair outputs: {len(all_bias)}; "
            f"bias audit statuses: {_report_ready_summary_counts(bias_audit, 'Status') if isinstance(bias_audit, pd.DataFrame) else 'no audit'}"
        ),
    )

    add_row(
        role="Measurement practitioner",
        priority=3,
        focus="Reproducibility and archive route",
        status=panel_value(overall, "ReportStatus", "Needs caveat"),
        why="Reviewers and collaborators need exact settings, method references, evidence files, and privacy boundaries.",
        action="Archive the decision brief, role memos, config, method appendix, claim matrix, scripts, and export privacy manifest together.",
        evidence="role_based_action_memos.csv; report_ready_decision_brief.md; method_reference_audit.csv; mfrm_config.json; export_privacy_manifest.csv",
        safe="Describe the app output as a standalone Python run with archived settings and evidence files.",
        do_not="Do not claim cross-package equivalence, calibration evidence, or prospective validation without separate archived validation artifacts.",
        question="Can another reviewer trace the claim, setting, script, and evidence file without reopening the app?",
        app_location="Downloads -> Scripts & Config; Manuscript Binder",
        download_file="role_based_action_memos.md; MFRM_OSF_Package.zip; mfrm_config.json",
        details=panel_value(overall, "Details", "Overall report-ready evidence not available."),
    )

    out = pd.DataFrame(rows)
    if out.empty:
        return out
    out = out.sort_values(["_RoleOrder", "Priority", "DecisionFocus"]).drop(columns=["_RoleOrder"]).reset_index(drop=True)
    return out


def generate_role_based_action_memos_markdown(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
) -> str:
    """Render role-specific action memo rows as a compact Markdown handoff."""
    memos = build_role_based_action_memos(
        result,
        diagnostics,
        all_bias_results=all_bias_results,
        bias_results=bias_results,
    )
    if not isinstance(memos, pd.DataFrame) or memos.empty:
        return "\n".join([
            "# Role-Based Action Memos",
            "",
            "No role-based action memo rows were generated for this run.",
            "",
        ])
    panel = build_report_ready_summary_panel(
        result,
        diagnostics,
        all_bias_results=all_bias_results,
        bias_results=bias_results,
    )
    overall_status = _report_ready_summary_overall_status(panel)
    lines = [
        "# Role-Based Action Memos",
        "",
        f"Overall report-ready status: **{overall_status}**.",
        "",
        "Use the section for your role first, then open the shared evidence files listed in each row.",
        "",
    ]
    for role in ["Paper author", "Scoring manager", "Measurement practitioner"]:
        role_rows = memos.loc[memos["Role"].astype(str) == role].sort_values("Priority")
        if role_rows.empty:
            continue
        lines.extend([f"## {role}", ""])
        for _, row in role_rows.iterrows():
            lines.extend([
                f"### P{row.get('Priority')} - {row.get('DecisionFocus')} ({row.get('ReportStatus')})",
                "",
                f"- Decision question: {row.get('DecisionQuestion')}",
                f"- Immediate action: {row.get('ImmediateAction')}",
                f"- Evidence to open: {row.get('EvidenceToOpen')}",
                f"- Safe output: {row.get('SafeOutput')}",
                f"- Do not do: {row.get('DoNotDo')}",
                f"- App location: {row.get('AppLocation')}",
                f"- Download file: {row.get('DownloadFile')}",
                "",
            ])
    lines.extend([
        "## Shared Evidence",
        "",
        "- `report_ready_summary_panel.csv`",
        "- `report_ready_decision_brief.md`",
        "- `apa_results_paragraph_draft.md`",
        "- `claim_to_evidence_matrix.csv`",
        "- `quality_control_todo_checklist.csv`",
        "- `method_reference_audit.csv`",
        "",
    ])
    return "\n".join(lines)


def _role_checklist_completion_criterion(status: object, role: object) -> str:
    report_status = _report_ready_summary_status(status)
    role_text = str(role or "")
    if report_status == "Ready":
        return "Evidence files were opened, the action was documented, and the safe output was used only within the stated scope."
    if report_status == "Needs caveat":
        return "The caveat was added to the manuscript, scoring decision note, or diagnostic memo before the output was used."
    if report_status == "Needs rerun":
        return "The missing evidence was regenerated, or the report explicitly states that the claim was not made from this run."
    if role_text == "Scoring manager":
        return "The operational decision is held until blocker evidence is resolved or documented as a limitation."
    return "Final wording or decision use is held until blocker evidence is resolved."


def _role_checklist_output_artifact(role: object) -> str:
    role_text = str(role or "")
    if role_text == "Paper author":
        return "APA Results draft; manuscript claim notes; reviewer-response plan"
    if role_text == "Scoring manager":
        return "Rater-training log; rubric-decision note; category-sensitivity decision"
    if role_text == "Measurement practitioner":
        return "Diagnostic review note; reproducibility archive; sensitivity-analysis plan"
    return "Project decision log"


ROLE_BASED_ACTION_CHECKLIST_ROLES = ("Paper author", "Scoring manager", "Measurement practitioner")


def _role_action_checklist_item_id(row: dict[str, object] | pd.Series) -> str:
    """Stable row key used to preserve Done state across Streamlit reruns."""
    get_value = row.get if hasattr(row, "get") else lambda key, default=None: default
    return stable_json_fingerprint(
        {
            "role": str(get_value("Role", "")),
            "step": str(get_value("Step", "")),
            "todo": str(get_value("ToDoItem", "")),
            "status": str(get_value("ReportStatus", "")),
            "evidence": str(get_value("EvidenceToOpen", "")),
        },
        length=12,
    )


def build_role_based_action_checklist(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
) -> pd.DataFrame:
    """Convert role-based memos into checkbox-ready action rows."""
    memos = build_role_based_action_memos(
        result,
        diagnostics,
        all_bias_results=all_bias_results,
        bias_results=bias_results,
    )
    if not isinstance(memos, pd.DataFrame) or memos.empty:
        return pd.DataFrame()
    rows: list[dict[str, object]] = []
    for _, row in memos.iterrows():
        status = _report_ready_summary_status(row.get("ReportStatus"))
        role = str(row.get("Role", ""))
        decision_focus = str(row.get("DecisionFocus", "Decision focus"))
        decision_question = str(row.get("DecisionQuestion", ""))
        item = {
            "Done": False,
            "ChecklistId": "",
            "Role": role,
            "Step": int(row.get("Priority", len(rows) + 1)),
            "ToDoItem": f"{decision_focus}: {decision_question}".strip(": "),
            "ReportStatus": status,
            "BlockingForFinalOutput": status in {"Do not report yet", "Needs rerun"},
            "NeedsCaveat": status == "Needs caveat",
            "Action": str(row.get("ImmediateAction", "")),
            "EvidenceToOpen": str(row.get("EvidenceToOpen", "")),
            "CompletionCriterion": _role_checklist_completion_criterion(status, role),
            "OutputArtifact": _role_checklist_output_artifact(role),
            "SafeOutput": str(row.get("SafeOutput", "")),
            "DoNotDo": str(row.get("DoNotDo", "")),
            "AppLocation": str(row.get("AppLocation", "")),
            "DownloadFile": str(row.get("DownloadFile", "")),
            "Details": str(row.get("Details", "")),
        }
        item["ChecklistId"] = _role_action_checklist_item_id(item)
        rows.append(item)
    out = pd.DataFrame(rows)
    role_order = {"Paper author": 1, "Scoring manager": 2, "Measurement practitioner": 3}
    status_order = {status: rank for rank, status in enumerate(REPORT_READY_SUMMARY_STATUS_ORDER)}
    out["_RoleOrder"] = out["Role"].map(role_order).fillna(99)
    out["_StatusOrder"] = out["ReportStatus"].map(status_order).fillna(2)
    out = out.sort_values(["_RoleOrder", "_StatusOrder", "Step", "ToDoItem"])
    return out.drop(columns=["_RoleOrder", "_StatusOrder"]).reset_index(drop=True)


def apply_role_based_action_checklist_done_state(
    checklist: pd.DataFrame,
    done_state: dict[str, bool] | None = None,
) -> pd.DataFrame:
    """Apply persisted Done values to a role-based checklist copy."""
    if not isinstance(checklist, pd.DataFrame) or checklist.empty:
        return pd.DataFrame()
    out = checklist.copy()
    if "ChecklistId" not in out.columns:
        out["ChecklistId"] = out.apply(_role_action_checklist_item_id, axis=1)
    if "Done" not in out.columns:
        out["Done"] = False
    state = {str(key): bool(value) for key, value in (done_state or {}).items()}
    out["Done"] = [
        bool(state.get(str(row.get("ChecklistId", "")), row.get("Done", False)))
        for _, row in out.iterrows()
    ]
    return out


def role_based_action_checklist_progress_summary(checklist: pd.DataFrame) -> pd.DataFrame:
    """Summarize completed and remaining role-specific review tasks."""
    if not isinstance(checklist, pd.DataFrame) or checklist.empty:
        return pd.DataFrame()
    work = apply_role_based_action_checklist_done_state(checklist)
    roles = list(ROLE_BASED_ACTION_CHECKLIST_ROLES)
    extra_roles = [
        role for role in work.get("Role", pd.Series(dtype=str)).astype(str).drop_duplicates().tolist()
        if role not in roles
    ]
    rows: list[dict[str, object]] = []
    for role in [*roles, *extra_roles]:
        role_rows = work.loc[work["Role"].astype(str).eq(role)].copy()
        if role_rows.empty:
            continue
        done = role_rows["Done"].fillna(False).astype(bool)
        remaining_rows = role_rows.loc[~done].copy()
        remaining_blockers = int(
            remaining_rows.get("BlockingForFinalOutput", pd.Series(False, index=remaining_rows.index))
            .fillna(False)
            .astype(bool)
            .sum()
        )
        remaining_caveats = int(
            remaining_rows.get("NeedsCaveat", pd.Series(False, index=remaining_rows.index))
            .fillna(False)
            .astype(bool)
            .sum()
        )
        next_action = ""
        next_evidence = ""
        if not remaining_rows.empty:
            status_order = {status: rank for rank, status in enumerate(REPORT_READY_SUMMARY_STATUS_ORDER)}
            remaining_rows["_StatusOrder"] = remaining_rows["ReportStatus"].map(status_order).fillna(2)
            remaining_rows = remaining_rows.sort_values(["_StatusOrder", "Step", "ToDoItem"])
            next_row = remaining_rows.iloc[0]
            next_action = str(next_row.get("Action", ""))
            next_evidence = str(next_row.get("EvidenceToOpen", ""))
        if remaining_rows.empty:
            state = "Complete"
        elif remaining_blockers:
            state = "Blocking evidence remains"
        elif remaining_caveats:
            state = "Caveat review remains"
        else:
            state = "Open review tasks remain"
        rows.append({
            "Role": role,
            "DoneItems": int(done.sum()),
            "TotalItems": int(len(role_rows)),
            "RemainingItems": int((~done).sum()),
            "RemainingBlockingItems": remaining_blockers,
            "RemainingCaveatItems": remaining_caveats,
            "CompletionPercent": round(100.0 * float(done.sum()) / max(float(len(role_rows)), 1.0), 1),
            "State": state,
            "NextAction": next_action,
            "NextEvidenceToOpen": next_evidence,
        })
    return pd.DataFrame(rows)


def generate_role_based_action_checklist_markdown(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
    checklist: pd.DataFrame | None = None,
) -> str:
    """Render the role checklist as Markdown with checkbox syntax."""
    if checklist is None:
        checklist = build_role_based_action_checklist(
            result,
            diagnostics,
            all_bias_results=all_bias_results,
            bias_results=bias_results,
        )
    else:
        checklist = apply_role_based_action_checklist_done_state(checklist)
    if not isinstance(checklist, pd.DataFrame) or checklist.empty:
        return "\n".join([
            "# Role-Based Action Checklist",
            "",
            "No role-based checklist rows were generated for this run.",
            "",
        ])
    lines = [
        "# Role-Based Action Checklist",
        "",
        "Use this checklist after reading `report_ready_decision_brief.md`. Keep completed rows with the manuscript or scoring decision archive.",
        "",
    ]
    progress = role_based_action_checklist_progress_summary(checklist)
    if isinstance(progress, pd.DataFrame) and not progress.empty:
        total_done = int(progress["DoneItems"].sum())
        total_items = int(progress["TotalItems"].sum())
        remaining_blockers = int(progress["RemainingBlockingItems"].sum())
        remaining_caveats = int(progress["RemainingCaveatItems"].sum())
        lines.extend([
            "## Progress Snapshot",
            "",
            f"- Completed items: {total_done}/{total_items}",
            f"- Remaining blocking items: {remaining_blockers}",
            f"- Remaining caveat items: {remaining_caveats}",
            "",
        ])
    role_sequence = [*ROLE_BASED_ACTION_CHECKLIST_ROLES]
    role_sequence.extend(
        role for role in checklist["Role"].astype(str).drop_duplicates().tolist()
        if role not in role_sequence
    )
    for role in role_sequence:
        role_rows = checklist.loc[checklist["Role"].astype(str) == role].sort_values("Step")
        if role_rows.empty:
            continue
        lines.extend([f"## {role}", ""])
        for _, row in role_rows.iterrows():
            checkmark = "x" if bool(row.get("Done", False)) else " "
            lines.extend([
                f"- [{checkmark}] P{row.get('Step')} - {row.get('ToDoItem')} ({row.get('ReportStatus')})",
                f"  - Action: {row.get('Action')}",
                f"  - Evidence: {row.get('EvidenceToOpen')}",
                f"  - Done when: {row.get('CompletionCriterion')}",
                f"  - Do not do: {row.get('DoNotDo')}",
                "",
            ])
    lines.extend([
        "## Export Files",
        "",
        "- `role_based_action_checklist.csv`",
        "- `role_based_action_memos.csv`",
        "- `report_ready_summary_panel.csv`",
        "",
    ])
    return "\n".join(lines)


def _reanalysis_checklist_item_id(row: dict[str, object] | pd.Series) -> str:
    get_value = row.get if hasattr(row, "get") else lambda key, default=None: default
    return stable_json_fingerprint(
        {
            "phase": str(get_value("Phase", "")),
            "task": str(get_value("Task", "")),
            "audience": str(get_value("Audience", "")),
            "evidence": str(get_value("EvidenceToOpen", "")),
        },
        length=12,
    )


def _reanalysis_completion_criterion(status: object, phase: object) -> str:
    report_status = _report_ready_summary_status(status)
    phase_text = str(phase or "")
    if report_status == "Ready":
        return "Evidence was opened, settings were archived, and the output was used only within the listed scope."
    if report_status == "Needs caveat":
        return "The caveat was carried into the manuscript, scoring note, simulation note, or reanalysis log."
    if report_status == "Needs rerun":
        return "The missing analysis was rerun, or the claim was removed from report-ready wording."
    if "Simulation" in phase_text:
        return "Generated-design blockers were resolved or explicitly documented as stress-test conditions."
    return "Report-ready use is held until blocker evidence is resolved."


def build_report_ready_reanalysis_checklist(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
    report_ready_summary: pd.DataFrame | None = None,
    role_action_checklist: pd.DataFrame | None = None,
    quality_control_todo: pd.DataFrame | None = None,
    category_action_center: pd.DataFrame | None = None,
    simulation_settings: pd.DataFrame | None = None,
    simulation_sparse_context: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """Checkbox-ready checklist for report-ready simulation or reanalysis use."""
    if not isinstance(result, dict):
        return pd.DataFrame()
    diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
    all_bias = all_bias_results or {}
    if not all_bias and isinstance(bias_results, dict) and bias_results:
        all_bias = {f"{bias_results.get('facet_a', 'A')} x {bias_results.get('facet_b', 'B')}": bias_results}
    if not isinstance(report_ready_summary, pd.DataFrame) or report_ready_summary.empty:
        report_ready_summary = build_report_ready_summary_panel(
            result,
            diagnostics,
            all_bias_results=all_bias,
            bias_results=bias_results,
        )
    if not isinstance(role_action_checklist, pd.DataFrame) or role_action_checklist.empty:
        role_action_checklist = build_role_based_action_checklist(
            result,
            diagnostics,
            all_bias_results=all_bias,
            bias_results=bias_results,
        )
    if not isinstance(quality_control_todo, pd.DataFrame) or quality_control_todo.empty:
        try:
            quality_control_todo = build_quality_control_todo_checklist(result, diagnostics)
        except Exception:
            quality_control_todo = pd.DataFrame()
    if not isinstance(category_action_center, pd.DataFrame) or category_action_center.empty:
        try:
            category_action_center = category_collapse_action_center_table(result, diagnostics)
        except Exception:
            category_action_center = pd.DataFrame()

    def panel_status(area: str, default: str = "Needs caveat") -> str:
        if isinstance(report_ready_summary, pd.DataFrame) and not report_ready_summary.empty and "ReportArea" in report_ready_summary.columns:
            hit = report_ready_summary.loc[report_ready_summary["ReportArea"].astype(str).eq(area)]
            if not hit.empty:
                return _report_ready_summary_status(hit.iloc[0].get("ReportStatus", default))
        return _report_ready_summary_status(default)

    def panel_value(area: str, column: str, default: str = "") -> str:
        if isinstance(report_ready_summary, pd.DataFrame) and not report_ready_summary.empty and {"ReportArea", column}.issubset(report_ready_summary.columns):
            hit = report_ready_summary.loc[report_ready_summary["ReportArea"].astype(str).eq(area)]
            if not hit.empty:
                return str(hit.iloc[0].get(column, default))
        return str(default)

    role_blockers = 0
    role_caveats = 0
    if isinstance(role_action_checklist, pd.DataFrame) and not role_action_checklist.empty:
        open_rows = role_action_checklist.loc[
            ~role_action_checklist.get("Done", pd.Series(False, index=role_action_checklist.index)).fillna(False).astype(bool)
        ]
        role_blockers = int(open_rows.get("BlockingForFinalOutput", pd.Series(False, index=open_rows.index)).fillna(False).astype(bool).sum())
        role_caveats = int(open_rows.get("NeedsCaveat", pd.Series(False, index=open_rows.index)).fillna(False).astype(bool).sum())

    qc_blockers = 0
    qc_caveats = 0
    if isinstance(quality_control_todo, pd.DataFrame) and not quality_control_todo.empty:
        status_text = quality_control_todo.astype(str).agg(" ".join, axis=1)
        qc_blockers = int(status_text.str.contains("Do not|Stop|Hold|block", case=False, regex=True, na=False).sum())
        qc_caveats = int(status_text.str.contains("Review|Caveat|training|rubric|category", case=False, regex=True, na=False).sum())

    category_status = "Needs caveat"
    if isinstance(category_action_center, pd.DataFrame) and not category_action_center.empty:
        category_status = _worst_report_ready_summary_status(
            category_action_center.get("Status", pd.Series("Needs caveat", index=category_action_center.index)).astype(str).tolist()
        )

    sim_status = None
    if isinstance(simulation_sparse_context, pd.DataFrame) and not simulation_sparse_context.empty:
        sim_status = _worst_report_ready_summary_status(
            simulation_sparse_context.get("ReportStatus", pd.Series("Needs caveat", index=simulation_sparse_context.index)).astype(str).tolist()
        )

    has_simulation_settings = isinstance(simulation_settings, pd.DataFrame) and not simulation_settings.empty
    rows: list[dict[str, object]] = []

    def add_row(
        *,
        phase: str,
        audience: str,
        task: str,
        status: str,
        action: str,
        evidence: str,
        output: str,
        caveat: str,
        do_not: str,
        app_location: str,
        details: str = "",
    ) -> None:
        report_status = _report_ready_summary_status(status)
        row = {
            "Done": False,
            "ChecklistId": "",
            "Priority": len(rows) + 1,
            "Phase": str(phase),
            "Audience": str(audience),
            "Task": str(task),
            "ReportStatus": report_status,
            "BlocksReportReady": report_status in {"Do not report yet", "Needs rerun"},
            "NeedsCaveat": report_status == "Needs caveat",
            "Action": str(action),
            "EvidenceToOpen": str(evidence),
            "CompletionCriterion": _reanalysis_completion_criterion(report_status, phase),
            "OutputArtifact": str(output),
            "CaveatToCarry": str(caveat),
            "DoNotDo": str(do_not),
            "AppLocation": str(app_location),
            "DownloadFile": str(evidence),
            "Details": str(details),
        }
        row["ChecklistId"] = _reanalysis_checklist_item_id(row)
        rows.append(row)

    overall_status = panel_status("Overall manuscript conclusion")
    add_row(
        phase="Study result handoff",
        audience="Paper author; measurement practitioner; scoring manager",
        task="Confirm whether this run is ready for manuscript or operational use.",
        status=overall_status,
        action=panel_value("Overall manuscript conclusion", "ActionBeforeWriting", "Open the report-ready summary and publication gate before using generated wording."),
        evidence="report_ready_summary_panel.csv; publication_gate_summary.csv; final_report_readiness.csv",
        output="Report-ready decision note",
        caveat=panel_value("Overall manuscript conclusion", "SafeWording", "Keep claims within computed evidence."),
        do_not=panel_value("Overall manuscript conclusion", "DoNotWrite", "Do not turn generated wording into final conclusions while blockers remain."),
        app_location="Guided Report -> Report-ready summary; Downloads -> Scripts & Config",
        details=f"open role checklist blockers={role_blockers}; open role caveats={role_caveats}",
    )
    add_row(
        phase="Reanalysis reproducibility",
        audience="Measurement practitioner; paper author",
        task="Archive the exact data tables, config, method appendix, and manuscript binder before rerunning or sharing.",
        status="Needs caveat",
        action="Download the table bundle, config JSON, method appendix, and manuscript binder; record whether public or private export mode was used.",
        evidence="MFRM_Tables.zip; mfrm_config.json; mfrm_method_appendix.md; MFRM_Manuscript_Binder.zip; export_privacy_manifest.csv",
        output="Reanalysis archive log",
        caveat="Public export mode reduces sharing risk but is not formal de-identification.",
        do_not="Do not compare reruns, external packages, or reviewer responses without archiving settings and exported evidence.",
        app_location="Downloads -> Data Tables; Downloads -> Scripts & Config",
    )
    add_row(
        phase="Model diagnostic rerun",
        audience="Measurement practitioner",
        task="Check whether required diagnostics were computed before repeating or extending the analysis.",
        status=panel_status("Claim boundary and evidence"),
        action=panel_value("Claim boundary and evidence", "ActionBeforeWriting", "Open claim-to-evidence rows and final-readiness rows before rerun decisions."),
        evidence="claim_to_evidence_matrix.csv; final_report_readiness.csv; status_rationale_drilldown.csv",
        output="Diagnostic rerun plan",
        caveat="Reruns should preserve row inclusion, score map, model, method, and facet mapping unless the change is documented.",
        do_not="Do not interpret changed estimates across reruns without documenting what changed.",
        app_location="Report -> Claim Guide; Downloads -> Data Tables",
    )
    add_row(
        phase="Scoring quality control",
        audience="Scoring manager",
        task="Decide whether rater training, rubric revision, or category-collapse review is needed before the next scoring cycle.",
        status=panel_status("Scoring quality and QC decision"),
        action=panel_value("Scoring quality and QC decision", "ActionBeforeWriting", "Open scoring QC and checklist rows before acting."),
        evidence="scoring_quality_first_read_summary.csv; scoring_consistency_decision.csv; quality_control_todo_checklist.csv",
        output="Rater training or scoring QC memo",
        caveat="Treat QC outputs as structured review evidence, not automatic personnel or rubric decisions.",
        do_not="Do not make rater-training or rubric decisions from one fit, alpha, or agreement statistic alone.",
        app_location="Agreement / QC; Report -> APA Report",
        details=f"qc_blockers={qc_blockers}; qc_review_rows={qc_caveats}",
    )
    add_row(
        phase="Rubric/category sensitivity",
        audience="Scoring manager; test developer",
        task="Check whether category-collapse or rubric revision is only exploratory or ready for a documented sensitivity decision.",
        status=category_status,
        action="Open category-collapse action rows, rating-scale decision support, and recode candidates before revising scoring categories.",
        evidence="category_collapse_action_center.csv; rating_scale_decision_support.csv; rating_scale_recode_candidates.csv",
        output="Rubric/category sensitivity note",
        caveat="Category changes need statistical evidence and substantive rubric justification.",
        do_not="Do not collapse categories solely because it improves one diagnostic or makes output simpler.",
        app_location="Categories / Steps; Downloads -> Data Tables",
    )
    add_row(
        phase="APA/manuscript wording",
        audience="Paper author",
        task="Confirm generated APA wording carries every caveat, blocker, and evidence file needed for the claim.",
        status=panel_status("APA sentence draft"),
        action=panel_value("APA sentence draft", "ActionBeforeWriting", "Filter generated sentences by CopyDecision and revise every caveated sentence."),
        evidence="apa_results_paragraph_draft.md; apa_report_sentence_audit.csv; reporting_action_bridge.csv",
        output="APA Results paragraph revision note",
        caveat="Generated prose is an editing scaffold; numbers and claims still need study-specific checking.",
        do_not="Do not copy blocked or caveated sentences without revision.",
        app_location="Report -> APA Report; Guided Report -> Report export",
    )
    if has_simulation_settings:
        add_row(
            phase="Simulation settings archive",
            audience="Paper author; measurement practitioner",
            task="Confirm the generated-data preset, seed, thresholds, missingness, and facet design are archived.",
            status="Ready",
            action="Open custom_simulation_settings.csv and confirm it matches the generated data used in the analysis.",
            evidence="custom_simulation_settings.csv; mfrm_custom_simulation.csv",
            output="Simulation settings note",
            caveat="Settings document the synthetic design; they do not validate an observed scoring program.",
            do_not="Do not cite generated results without the seed and settings that reproduce them.",
            app_location="Data source -> Generate synthetic data; Downloads -> Data Tables",
        )
    if sim_status is not None:
        add_row(
            phase="Simulation design reportability",
            audience="Paper author; measurement practitioner; test developer",
            task="Decide whether generated sparse-design conditions are stress-test features or reportability blockers.",
            status=sim_status,
            action="Open sparse-design context, design audit, and facet-pair cell table before interpreting simulated estimates.",
            evidence="custom_simulation_sparse_reporting_context.csv; custom_simulation_sparse_design_audit.csv; custom_simulation_sparse_pair_cells.csv",
            output="Simulation/stress-test interpretation note",
            caveat="Sparse generated designs can be useful stress tests but must be named before report-style interpretation.",
            do_not="Do not present a sparse simulation as stable empirical evidence without documenting the sparse condition.",
            app_location="Data source preview -> Sparse design; Report -> APA Report",
        )

    out = pd.DataFrame(rows)
    if out.empty:
        return out
    status_order = {"Do not report yet": 0, "Needs rerun": 1, "Needs caveat": 2, "Ready": 3}
    out["_StatusOrder"] = out["ReportStatus"].map(status_order).fillna(2)
    out = out.sort_values(["_StatusOrder", "Priority"]).drop(columns=["_StatusOrder"]).reset_index(drop=True)
    out["Priority"] = np.arange(1, len(out) + 1, dtype=int)
    return out


def generate_report_ready_reanalysis_checklist_markdown(checklist: pd.DataFrame) -> str:
    """Render the report-ready simulation/reanalysis checklist as Markdown."""
    if not isinstance(checklist, pd.DataFrame) or checklist.empty:
        return "\n".join([
            "# Report-Ready Simulation / Reanalysis Checklist",
            "",
            "No checklist rows were generated for this run.",
            "",
        ])
    lines = [
        "# Report-Ready Simulation / Reanalysis Checklist",
        "",
        "Use this checklist before treating generated data, reruns, sensitivity checks, or final exports as report-ready evidence.",
        "",
    ]
    for _, row in checklist.sort_values("Priority").iterrows():
        checkmark = "x" if bool(row.get("Done", False)) else " "
        lines.extend([
            f"- [{checkmark}] P{row.get('Priority')} - {row.get('Phase')}: {row.get('Task')} ({row.get('ReportStatus')})",
            f"  - Audience: {row.get('Audience')}",
            f"  - Action: {row.get('Action')}",
            f"  - Evidence: {row.get('EvidenceToOpen')}",
            f"  - Done when: {row.get('CompletionCriterion')}",
            f"  - Do not do: {row.get('DoNotDo')}",
            "",
        ])
    lines.extend([
        "## Export Files",
        "",
        "- `report_ready_reanalysis_checklist.csv`",
        "- `report_ready_reanalysis_checklist.md`",
        "",
    ])
    return "\n".join(lines)


def _critical_review_decision(status: object) -> str:
    report_status = _report_ready_summary_status(status)
    if report_status in {"Do not report yet", "Needs rerun"}:
        return "Stop before final output"
    if report_status == "Needs caveat":
        return "Proceed only with caveat"
    return "Ready for draft use"


def _critical_review_row_from_report_area(panel: pd.DataFrame, area: str) -> pd.Series:
    row = _table_row_by_value(panel, "ReportArea", area)
    return row if row is not None else pd.Series(dtype=object)


def build_critical_final_review_panel(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
    role_action_checklist: pd.DataFrame | None = None,
    report_ready_summary: pd.DataFrame | None = None,
    final_report_readiness: pd.DataFrame | None = None,
    submission_action_plan: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """Cross-lens critical review gate before manuscript or decision use."""
    if not isinstance(result, dict):
        return pd.DataFrame()
    diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
    all_bias = all_bias_results or {}
    if not all_bias and isinstance(bias_results, dict) and bias_results:
        all_bias = {f"{bias_results.get('facet_a', 'A')} x {bias_results.get('facet_b', 'B')}": bias_results}

    if isinstance(report_ready_summary, pd.DataFrame) and not report_ready_summary.empty:
        report_panel = report_ready_summary.copy()
    else:
        report_panel = build_report_ready_summary_panel(
            result,
            diagnostics,
            all_bias_results=all_bias,
            bias_results=bias_results,
        )
    if role_action_checklist is None:
        role_action_checklist = build_role_based_action_checklist(
            result,
            diagnostics,
            all_bias_results=all_bias,
            bias_results=bias_results,
        )
    role_action_checklist = apply_role_based_action_checklist_done_state(role_action_checklist)
    role_progress = role_based_action_checklist_progress_summary(role_action_checklist)
    if isinstance(submission_action_plan, pd.DataFrame) and not submission_action_plan.empty:
        action_plan = submission_action_plan.copy()
    else:
        action_plan = build_submission_action_plan(result, diagnostics, all_bias)
    if isinstance(final_report_readiness, pd.DataFrame) and not final_report_readiness.empty:
        readiness = final_report_readiness.copy()
    else:
        readiness = build_final_report_readiness(result, diagnostics, all_bias)

    rows: list[dict[str, object]] = []

    def checklist_counts(role: str) -> tuple[int, int, int]:
        if not isinstance(role_progress, pd.DataFrame) or role_progress.empty:
            return 0, 0, 0
        hit = role_progress.loc[role_progress["Role"].astype(str).eq(role)]
        if hit.empty:
            return 0, 0, 0
        row = hit.iloc[0]
        return (
            int(row.get("RemainingItems", 0) or 0),
            int(row.get("RemainingBlockingItems", 0) or 0),
            int(row.get("RemainingCaveatItems", 0) or 0),
        )

    def add_row(
        lens: str,
        source_area: str,
        status: object,
        owner: str,
        question: str,
        risk: str,
        action: str,
        evidence: str,
        do_not: str,
        safe_output: str,
        *,
        unresolved_workflow_items: int = 0,
        unresolved_workflow_blockers: int = 0,
        unresolved_workflow_caveats: int = 0,
    ) -> None:
        report_status = _report_ready_summary_status(status)
        evidence_blocks = report_status in {"Do not report yet", "Needs rerun"}
        caveat_needed = report_status == "Needs caveat" or unresolved_workflow_caveats > 0
        stop = bool(evidence_blocks or unresolved_workflow_blockers > 0)
        rows.append({
            "Priority": 0,
            "Lens": str(lens),
            "OwnerRole": str(owner),
            "CriticalQuestion": str(question),
            "CurrentStatus": report_status,
            "Decision": _critical_review_decision(report_status),
            "StopBeforeFinalOutput": stop,
            "EvidenceBlocksDirectClaim": evidence_blocks,
            "UnresolvedWorkflowItems": int(unresolved_workflow_items),
            "UnresolvedWorkflowBlockers": int(unresolved_workflow_blockers),
            "NeedsCaveat": bool(caveat_needed),
            "WhatCouldGoWrong": str(risk),
            "ActionBeforeContinuing": str(action),
            "EvidenceToOpen": str(evidence),
            "DoNotClaim": str(do_not),
            "SafeNextOutput": str(safe_output),
            "SourceArea": str(source_area),
            "DownloadFile": str(evidence),
        })

    if not isinstance(report_panel, pd.DataFrame) or report_panel.empty:
        add_row(
            "Run availability",
            "Report-ready summary",
            "Needs rerun",
            "Paper author; measurement practitioner",
            "Is there enough generated evidence to write or decide from this run?",
            "The app could not assemble the report-ready panel, so downstream claims lack a common gate.",
            "Regenerate the run and open the readiness, claim, and APA audit tables before writing.",
            "report_ready_summary_panel.csv; publication_gate_summary.csv; final_report_readiness.csv",
            "Do not write final conclusions when the report-ready panel is unavailable.",
            "Internal troubleshooting note only.",
        )
        out = pd.DataFrame(rows)
        out["Priority"] = np.arange(1, len(out) + 1, dtype=int)
        return out

    overall = _critical_review_row_from_report_area(report_panel, "Overall manuscript conclusion")
    paper_remaining, paper_blockers, paper_caveats = checklist_counts("Paper author")
    add_row(
        "Manuscript conclusion",
        "Overall manuscript conclusion",
        overall.get("ReportStatus", "Needs caveat"),
        "Paper author",
        "Can the Results and Discussion conclusions be treated as final?",
        "Generated prose may outrun the publication gate, especially when a blocker or caveat remains.",
        overall.get("ActionBeforeWriting", "Open the publication gate and readiness rows before using final wording."),
        overall.get("EvidenceFiles", "publication_gate_summary.csv; final_report_readiness.csv"),
        overall.get("DoNotWrite", "Do not turn generated text into final conclusions while blocker or caveat rows remain."),
        overall.get("SafeWording", "Use only bounded wording supported by the current run."),
        unresolved_workflow_items=paper_remaining,
        unresolved_workflow_blockers=paper_blockers,
        unresolved_workflow_caveats=paper_caveats,
    )

    apa = _critical_review_row_from_report_area(report_panel, "APA sentence draft")
    add_row(
        "APA wording",
        "APA sentence draft",
        apa.get("ReportStatus", "Needs caveat"),
        "Paper author",
        "Which generated sentences can be copied only after editing?",
        "A polished sentence can hide a caveat, unsupported claim, or missing evidence row.",
        apa.get("ActionBeforeWriting", "Use the APA sentence audit before copying generated sentences."),
        apa.get("EvidenceFiles", "apa_report_sentence_audit.csv; method_reference_audit.csv"),
        apa.get("DoNotWrite", "Do not copy blocked or caveated sentences without revision."),
        apa.get("SafeWording", "Use generated APA text as evidence-linked draft wording."),
        unresolved_workflow_items=paper_remaining,
        unresolved_workflow_blockers=paper_blockers,
        unresolved_workflow_caveats=paper_caveats,
    )

    claim = _critical_review_row_from_report_area(report_panel, "Claim boundary and evidence")
    add_row(
        "Claim scope",
        "Claim boundary and evidence",
        claim.get("ReportStatus", "Needs caveat"),
        "Paper author; reviewer response lead",
        "Are each Results claim, limitation, and reviewer answer tied to actual evidence?",
        "Broad claims about validity, fairness, no bias, category functioning, or equivalence may exceed computed evidence.",
        claim.get("ActionBeforeWriting", "Map every planned claim to claim-to-evidence rows."),
        claim.get("EvidenceFiles", "claim_to_evidence_matrix.csv; manuscript_claim_guide.csv"),
        claim.get("DoNotWrite", "Do not make claims that lack a traceable evidence row."),
        claim.get("SafeWording", "State claims only for the fitted design and diagnostics actually produced."),
        unresolved_workflow_items=paper_remaining,
        unresolved_workflow_blockers=paper_blockers,
        unresolved_workflow_caveats=paper_caveats,
    )

    scoring = _critical_review_row_from_report_area(report_panel, "Scoring quality and QC decision")
    scoring_remaining, scoring_blockers, scoring_caveats = checklist_counts("Scoring manager")
    add_row(
        "Scoring operations",
        "Scoring quality and QC decision",
        scoring.get("ReportStatus", "Needs caveat"),
        "Scoring manager",
        "Can rater training, rubric revision, or category-collapse decisions be made from the current evidence?",
        "Agreement, alpha, fit, and category evidence can be over-read as a personnel judgement or automatic rubric rule.",
        scoring.get("ActionBeforeWriting", "Open scoring consistency and QC checklist rows before operational decisions."),
        scoring.get("EvidenceFiles", "scoring_consistency_decision.csv; quality_control_todo_checklist.csv"),
        scoring.get("DoNotWrite", "Do not diagnose raters, revise rubrics, or collapse categories from one statistic alone."),
        scoring.get("SafeWording", "Use scoring QC as a structured review prompt, not an automatic action."),
        unresolved_workflow_items=scoring_remaining,
        unresolved_workflow_blockers=scoring_blockers,
        unresolved_workflow_caveats=scoring_caveats,
    )

    category = _critical_review_row_from_report_area(report_panel, "Rubric categories and collapse sensitivity")
    add_row(
        "Rubric/category decision",
        "Rubric categories and collapse sensitivity",
        category.get("ReportStatus", "Needs caveat"),
        "Scoring manager; rubric owner",
        "Does the evidence justify keeping, revising, or collapsing rating categories?",
        "Category collapse can appear statistically convenient while weakening the rubric construct.",
        category.get("ActionBeforeWriting", "Review counts, thresholds, category curves, and sensitivity candidates."),
        category.get("EvidenceFiles", "category_collapse_action_center.csv; rating_scale_decision_support.csv"),
        category.get("DoNotWrite", "Do not collapse categories solely to improve fit or agreement statistics."),
        category.get("SafeWording", "Treat category decisions as sensitivity work requiring substantive rubric justification."),
        unresolved_workflow_items=scoring_remaining,
        unresolved_workflow_blockers=scoring_blockers,
        unresolved_workflow_caveats=scoring_caveats,
    )

    practitioner_remaining, practitioner_blockers, practitioner_caveats = checklist_counts("Measurement practitioner")
    readiness_statuses: list[str] = []
    if isinstance(readiness, pd.DataFrame) and not readiness.empty and {"Required", "Status"}.issubset(readiness.columns):
        required = readiness.loc[readiness["Required"].astype(str).eq("Yes")]
        readiness_statuses = required["Status"].astype(str).tolist()
    diagnostic_status = _worst_report_ready_summary_status(readiness_statuses) if readiness_statuses else "Needs caveat"
    add_row(
        "Measurement diagnostics",
        "Final-report readiness",
        diagnostic_status,
        "Measurement practitioner",
        "Do fit, dimensionality, reliability, targeting, linking, and bias screens support the intended interpretation?",
        "A single good-looking table or figure can hide a skipped diagnostic, weak connectedness, or unsupported linking claim.",
        "Open final_report_readiness and submission_action_plan; resolve required rows before final interpretation.",
        "final_report_readiness.csv; submission_action_plan.csv; case_interpretation_guidance.csv",
        "Do not describe the model as broadly valid, unidimensional, unbiased, or linked without the corresponding diagnostic evidence.",
        "Use diagnostics as converging evidence with explicit boundaries and limitations.",
        unresolved_workflow_items=practitioner_remaining,
        unresolved_workflow_blockers=practitioner_blockers,
        unresolved_workflow_caveats=practitioner_caveats,
    )

    action_statuses = (
        action_plan["Status"].astype(str).tolist()
        if isinstance(action_plan, pd.DataFrame) and not action_plan.empty and "Status" in action_plan.columns
        else []
    )
    action_report_status = _worst_report_ready_summary_status(action_statuses) if action_statuses else "Needs caveat"
    add_row(
        "Reproducibility and archive",
        "Submission action plan",
        action_report_status,
        "Paper author; measurement practitioner",
        "Could another reviewer reconstruct the evidence behind each claim?",
        "Without config, method appendix, table bundle, and action plan, a claim may be impossible to audit.",
        "Archive the table bundle, config JSON, method appendix, manuscript binder, and any external validation artifacts used.",
        "MFRM_Tables.zip; mfrm_config.json; mfrm_method_appendix.md; MFRM_Manuscript_Binder.zip",
        "Do not cite numerical equivalence, posterior extensions, or external package checks unless their artifacts are archived.",
        "Use the exported archive as a reproducibility record, not as proof of cross-package parity.",
    )

    add_row(
        "Sharing and privacy",
        "Export/share preflight",
        "Needs caveat",
        "Paper author; project lead",
        "Which files can leave the controlled research workspace?",
        "Direct exports may include row-level or person-level information; public bundle mode is not formal de-identification.",
        "Choose public/private export mode intentionally and review each shared file before distribution.",
        "export_privacy_manifest.csv; MFRM_OSF_Package.zip; MFRM_Manuscript_Binder.zip",
        "Do not share private row-level exports, IDs, scripts, or fingerprints without an approved sharing plan.",
        "Share only the minimum bundle needed for the audience, with privacy limits documented.",
    )

    out = pd.DataFrame(rows)
    if out.empty:
        return out
    decision_order = {
        "Stop before final output": 0,
        "Proceed only with caveat": 1,
        "Ready for draft use": 2,
    }
    out["_DecisionOrder"] = out["Decision"].map(decision_order).fillna(1)
    out["_StopOrder"] = (~out["StopBeforeFinalOutput"].astype(bool)).astype(int)
    out = out.sort_values(["_StopOrder", "_DecisionOrder", "Lens"]).drop(columns=["_DecisionOrder", "_StopOrder"])
    out["Priority"] = np.arange(1, len(out) + 1, dtype=int)
    return out.reset_index(drop=True)


def generate_critical_final_review_markdown(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
    role_action_checklist: pd.DataFrame | None = None,
    critical_final_review: pd.DataFrame | None = None,
    report_ready_summary: pd.DataFrame | None = None,
    final_report_readiness: pd.DataFrame | None = None,
    submission_action_plan: pd.DataFrame | None = None,
) -> str:
    """Render the cross-lens critical review gate as Markdown."""
    if isinstance(critical_final_review, pd.DataFrame) and not critical_final_review.empty:
        panel = critical_final_review.copy()
    else:
        panel = build_critical_final_review_panel(
            result,
            diagnostics,
            all_bias_results=all_bias_results,
            bias_results=bias_results,
            role_action_checklist=role_action_checklist,
            report_ready_summary=report_ready_summary,
            final_report_readiness=final_report_readiness,
            submission_action_plan=submission_action_plan,
        )
    if not isinstance(panel, pd.DataFrame) or panel.empty:
        return "\n".join([
            "# Critical Final Review",
            "",
            "No critical review rows were generated for this run.",
            "",
        ])
    stop_count = int(panel["StopBeforeFinalOutput"].fillna(False).astype(bool).sum())
    evidence_block_count = int(panel["EvidenceBlocksDirectClaim"].fillna(False).astype(bool).sum())
    caveat_count = int(panel["NeedsCaveat"].fillna(False).astype(bool).sum())
    lines = [
        "# Critical Final Review",
        "",
        "Use this after the report-ready decision brief and before copying final manuscript or decision wording.",
        "",
        "## Snapshot",
        "",
        f"- Stop-before-final-output rows: {stop_count}",
        f"- Evidence blocks direct claims: {evidence_block_count}",
        f"- Caveat-needed rows: {caveat_count}",
        "",
    ]
    for _, row in panel.iterrows():
        stop_text = "yes" if bool(row.get("StopBeforeFinalOutput", False)) else "no"
        caveat_text = "yes" if bool(row.get("NeedsCaveat", False)) else "no"
        lines.extend([
            f"## P{row.get('Priority')} - {row.get('Lens')}",
            "",
            f"- Owner: {row.get('OwnerRole')}",
            f"- Critical question: {row.get('CriticalQuestion')}",
            f"- Decision: {row.get('Decision')} ({row.get('CurrentStatus')})",
            f"- Stop before final output: {stop_text}",
            f"- Needs caveat: {caveat_text}",
            f"- What could go wrong: {row.get('WhatCouldGoWrong')}",
            f"- Action before continuing: {row.get('ActionBeforeContinuing')}",
            f"- Evidence to open: {row.get('EvidenceToOpen')}",
            f"- Do not claim: {row.get('DoNotClaim')}",
            f"- Safe next output: {row.get('SafeNextOutput')}",
            "",
        ])
    lines.extend([
        "## Export Files",
        "",
        "- `critical_final_review_panel.csv`",
        "- `critical_final_review.md`",
        "- `report_ready_summary_panel.csv`",
        "- `role_based_action_checklist.csv`",
        "",
    ])
    return "\n".join(lines)


def build_status_rationale_drilldown(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
    role_action_checklist: pd.DataFrame | None = None,
    critical_final_review: pd.DataFrame | None = None,
    report_ready_summary: pd.DataFrame | None = None,
    final_report_readiness: pd.DataFrame | None = None,
    submission_action_plan: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """Explain why each high-level reporting status was assigned."""
    if isinstance(critical_final_review, pd.DataFrame) and not critical_final_review.empty:
        critical = critical_final_review.copy()
    else:
        critical = build_critical_final_review_panel(
            result,
            diagnostics,
            all_bias_results=all_bias_results,
            bias_results=bias_results,
            role_action_checklist=role_action_checklist,
            report_ready_summary=report_ready_summary,
            final_report_readiness=final_report_readiness,
            submission_action_plan=submission_action_plan,
        )
    if not isinstance(critical, pd.DataFrame) or critical.empty:
        return pd.DataFrame()

    rows: list[dict[str, object]] = []
    for _, row in critical.iterrows():
        stop = bool(row.get("StopBeforeFinalOutput", False))
        evidence_blocks = bool(row.get("EvidenceBlocksDirectClaim", False))
        needs_caveat = bool(row.get("NeedsCaveat", False))
        unresolved_blockers = int(row.get("UnresolvedWorkflowBlockers", 0) or 0)
        unresolved_items = int(row.get("UnresolvedWorkflowItems", 0) or 0)
        if evidence_blocks:
            minimum = "Regenerate or resolve the listed evidence before making a direct claim."
        elif stop:
            minimum = "Complete or document the blocking workflow items before final wording."
        elif needs_caveat:
            minimum = "Carry the caveat into the Results, limitations, scoring note, or decision memo."
        else:
            minimum = "Archive the evidence file and keep the claim within the listed scope."
        rows.append({
            "Priority": int(row.get("Priority", len(rows) + 1)),
            "Audience": "Psychometric reviewer",
            "StatusSource": str(row.get("Lens", "Critical review")),
            "CurrentStatus": str(row.get("CurrentStatus", "Needs caveat")),
            "Decision": str(row.get("Decision", "Proceed only with caveat")),
            "DecisionLogic": (
                f"stop_before_final_output={stop}; evidence_blocks_direct_claim={evidence_blocks}; "
                f"needs_caveat={needs_caveat}; unresolved_workflow_blockers={unresolved_blockers}; "
                f"unresolved_workflow_items={unresolved_items}."
            ),
            "TriggerDiagnostics": str(row.get("EvidenceToOpen", "")),
            "MinimumEvidenceNeeded": minimum,
            "WhatCouldGoWrong": str(row.get("WhatCouldGoWrong", "")),
            "ClaimBoundary": str(row.get("DoNotClaim", "")),
            "NextInspection": str(row.get("ActionBeforeContinuing", "")),
            "SafeUse": str(row.get("SafeNextOutput", "")),
            "DownloadFile": str(row.get("DownloadFile", row.get("EvidenceToOpen", ""))),
        })
    out = pd.DataFrame(rows)
    if not out.empty:
        out = out.sort_values(["Priority", "StatusSource"]).reset_index(drop=True)
    return out


def _reading_path_status_from_readiness(readiness: pd.DataFrame, checks: Iterable[str]) -> tuple[str, str, str]:
    statuses: list[str] = []
    evidence: list[str] = []
    actions: list[str] = []
    if isinstance(readiness, pd.DataFrame) and not readiness.empty and "Check" in readiness.columns:
        for check in checks:
            hit = readiness.loc[readiness["Check"].astype(str).eq(str(check))]
            if hit.empty:
                continue
            row = hit.iloc[0]
            statuses.append(str(row.get("Status", "")))
            evidence.append(str(row.get("Evidence", "")))
            actions.append(str(row.get("ActionBeforeFinalReport", "")))
    status = _worst_report_ready_summary_status(statuses) if statuses else "Needs caveat"
    return status, " ".join(part for part in evidence if part), " ".join(part for part in actions if part)


def build_result_reading_path(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
    report_ready_summary: pd.DataFrame | None = None,
    final_report_readiness: pd.DataFrame | None = None,
    manuscript_claim_guide: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """Order the main outputs for a graduate researcher learning the MFRM workflow."""
    if isinstance(report_ready_summary, pd.DataFrame) and not report_ready_summary.empty:
        report_panel = report_ready_summary.copy()
    else:
        report_panel = build_report_ready_summary_panel(
            result,
            diagnostics,
            all_bias_results=all_bias_results,
            bias_results=bias_results,
        )
    if isinstance(final_report_readiness, pd.DataFrame) and not final_report_readiness.empty:
        readiness = final_report_readiness.copy()
    else:
        readiness = build_final_report_readiness(result, diagnostics, all_bias_results or {})
    if isinstance(manuscript_claim_guide, pd.DataFrame) and not manuscript_claim_guide.empty:
        claim_guide = manuscript_claim_guide.copy()
    else:
        claim_guide = build_manuscript_claim_guide(result, diagnostics, all_bias_results or {})

    def panel_row(area: str) -> pd.Series:
        row = _table_row_by_value(report_panel, "ReportArea", area)
        return row if row is not None else pd.Series(dtype=object)

    def add_row(
        rows: list[dict[str, object]],
        goal: str,
        question: str,
        status: object,
        open_first: str,
        evidence_file: str,
        how_to_read: str,
        can_write: str,
        avoid: str,
        next_move: str,
    ) -> None:
        rows.append({
            "Step": len(rows) + 1,
            "Audience": "Graduate researcher learning MFRM",
            "ReadingGoal": str(goal),
            "GuidingQuestion": str(question),
            "CurrentStatus": _report_ready_summary_status(status),
            "OpenFirst": str(open_first),
            "EvidenceFile": str(evidence_file),
            "HowToRead": str(how_to_read),
            "WhatCanBeWritten": str(can_write),
            "DoNotWriteYet": str(avoid),
            "NextMove": str(next_move),
        })

    rows: list[dict[str, object]] = []
    overall = panel_row("Overall manuscript conclusion")
    add_row(
        rows,
        "Start with the run gate",
        "Can this run support any final Results wording?",
        overall.get("ReportStatus", "Needs caveat"),
        overall.get("OpenFirst", "Report -> APA Report; Report -> Readiness"),
        overall.get("EvidenceFiles", "publication_gate_summary.csv; final_report_readiness.csv"),
        "Read the gate before individual estimates; it tells you whether the rest is draft evidence, caveated evidence, or troubleshooting evidence.",
        overall.get("SafeWording", "Use only bounded wording supported by the current run."),
        overall.get("DoNotWrite", "Do not treat generated text as final before the gate is checked."),
        overall.get("ActionBeforeWriting", "Open the publication gate and readiness rows."),
    )

    category = panel_row("Rubric categories and collapse sensitivity")
    add_row(
        rows,
        "Read the score scale",
        "Do the observed categories support the intended rubric interpretation?",
        category.get("ReportStatus", "Needs caveat"),
        category.get("OpenFirst", "Categories / Steps; Visuals -> category curves"),
        category.get("EvidenceFiles", "category_collapse_action_center.csv; rating_scale_decision_support.csv"),
        "Read counts, threshold order, and category curves before interpreting measures or category-collapse suggestions.",
        category.get("SafeWording", "Report only the category-functioning evidence that was computed."),
        category.get("DoNotWrite", "Do not collapse categories solely because one diagnostic is flagged."),
        category.get("ActionBeforeWriting", "Review category diagnostics and sensitivity candidates."),
    )

    scoring = panel_row("Scoring quality and QC decision")
    add_row(
        rows,
        "Read scoring consistency",
        "Do agreement, alpha, rater fit, and category evidence point to the same scoring-quality story?",
        scoring.get("ReportStatus", "Needs caveat"),
        scoring.get("OpenFirst", "Agreement / QC; Report -> APA Report"),
        scoring.get("EvidenceFiles", "scoring_consistency_decision.csv; quality_control_todo_checklist.csv"),
        "Read agreement and MFRM rater evidence together; one statistic is not the whole scoring-quality argument.",
        scoring.get("SafeWording", "Use scoring QC as converging evidence with clear boundaries."),
        scoring.get("DoNotWrite", "Do not claim scoring quality from one agreement or fit statistic alone."),
        scoring.get("ActionBeforeWriting", "Open scoring consistency and QC checklist rows."),
    )

    fit_status, fit_evidence, fit_action = _reading_path_status_from_readiness(
        readiness,
        ["Global residual fit", "Dimensionality screen", "Wright Map targeting"],
    )
    add_row(
        rows,
        "Read model diagnostics",
        "Do fit, dimensionality, and targeting support the intended interpretation?",
        fit_status,
        "Fit Details; Dimensionality; Wright Map",
        "fit_statistics.csv; residuals.csv; pca_stability_audit.csv; final_report_readiness.csv",
        "Read residual fit, PCA, and targeting as converging diagnostics, not as a single pass/fail score.",
        "Describe fit and targeting only within the diagnostics that were computed.",
        "Do not state that unidimensionality, targeting, or validity was established from fit alone.",
        fit_action or "Open Fit Details, Dimensionality, and Wright Map before drafting fit claims.",
    )

    bias_row = _table_row_by_value(claim_guide, "ManuscriptArea", "Bias / local interaction")
    bias_status = bias_row.get("ClaimStatus", "Needs caveat") if bias_row is not None else "Needs caveat"
    add_row(
        rows,
        "Read bias and local interaction",
        "Were the intended facet pairs and cells screened, and what is outside the screen?",
        bias_status,
        "Bias/Interaction; Claim Guide",
        "bias_inference_audit.csv; claim_to_evidence_matrix.csv; manuscript_claim_guide.csv",
        "Read the screened pairs, sparse cells, and flagged interactions before making fairness or no-bias claims.",
        bias_row.get("SafeManuscriptWording", "Limit bias statements to the screened facet pairs and cells.") if bias_row is not None else "Limit bias statements to the screened facet pairs and cells.",
        bias_row.get("DoNotClaim", "Do not make no-bias claims outside screened evidence.") if bias_row is not None else "Do not make no-bias claims outside screened evidence.",
        bias_row.get("NextAction", "Open bias and claim evidence files.") if bias_row is not None else "Open bias and claim evidence files.",
    )

    apa = panel_row("APA sentence draft")
    claim = panel_row("Claim boundary and evidence")
    add_row(
        rows,
        "Draft only after evidence mapping",
        "Which sentences can be copied as drafts, and which claims must wait?",
        _worst_report_ready_summary_status([apa.get("ReportStatus", "Needs caveat"), claim.get("ReportStatus", "Needs caveat")]),
        "Report -> APA Report; Claim Guide",
        "apa_results_paragraph_draft.md; apa_report_sentence_audit.csv; critical_final_review_panel.csv",
        "Read Final-Output Blockers before the draft paragraph; then match each sentence to evidence and caveats.",
        "Use generated APA text as evidence-linked draft wording.",
        "Do not copy polished text that hides a blocker, caveat, or missing evidence row.",
        "Edit the draft after opening the critical final review and APA sentence audit.",
    )

    add_row(
        rows,
        "Archive before sharing",
        "Can a reader reconstruct why each claim was allowed, caveated, or withheld?",
        "Needs caveat",
        "Downloads -> Scripts & Config; Manuscript Binder",
        "MFRM_Tables.zip; mfrm_config.json; MFRM_Manuscript_Binder.zip; export_privacy_manifest.csv",
        "Keep tables, config, method appendix, and privacy manifest together with the manuscript draft.",
        "Use the archive as a reproducibility record for the current run.",
        "Do not share row-level or person-level material without an approved sharing plan.",
        "Download the intended public or private bundle before manuscript circulation.",
    )
    return pd.DataFrame(rows)


def build_operational_decision_board(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
    quality_control_recommendations: pd.DataFrame | None = None,
    category_action_center: pd.DataFrame | None = None,
    critical_final_review: pd.DataFrame | None = None,
    report_ready_summary: pd.DataFrame | None = None,
    final_report_readiness: pd.DataFrame | None = None,
    submission_action_plan: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """Translate scoring and category evidence into test-development actions."""
    if isinstance(quality_control_recommendations, pd.DataFrame) and not quality_control_recommendations.empty:
        qc = quality_control_recommendations.copy()
    else:
        qc = build_quality_control_recommendations(result, diagnostics)
    if isinstance(category_action_center, pd.DataFrame) and not category_action_center.empty:
        category = category_action_center.copy()
    else:
        category = category_collapse_action_center_table(result, diagnostics)
    if isinstance(critical_final_review, pd.DataFrame) and not critical_final_review.empty:
        critical = critical_final_review.copy()
    else:
        critical = build_critical_final_review_panel(
            result,
            diagnostics,
            all_bias_results=all_bias_results,
            bias_results=bias_results,
            report_ready_summary=report_ready_summary,
            final_report_readiness=final_report_readiness,
            submission_action_plan=submission_action_plan,
        )
    rows: list[dict[str, object]] = []

    def add_decision(
        decision: str,
        signal: str,
        evidence: str,
        action: str,
        risk: str,
        owner: str,
        before_next: str,
        do_not: str,
    ) -> None:
        rows.append({
            "Priority": 0,
            "Audience": "Test developer",
            "Decision": str(decision),
            "OwnerRole": str(owner),
            "CurrentSignal": str(signal),
            "EvidenceToOpen": str(evidence),
            "RecommendedAction": str(action),
            "RiskIfIgnored": str(risk),
            "BeforeNextAdministration": str(before_next),
            "DoNotDo": str(do_not),
        })

    if isinstance(qc, pd.DataFrame) and not qc.empty:
        for _, row in qc.iterrows():
            add_decision(
                row.get("QCDecision", "Scoring quality decision"),
                f"{row.get('Recommendation', 'Review')} / {row.get('Priority', 'Routine')}",
                row.get("EvidenceFile", row.get("TriggerEvidence", "")),
                row.get("Action", "Review scoring evidence and document the decision."),
                row.get("RiskIfSkipped", "The scoring-quality claim may outrun the evidence."),
                row.get("OwnerRole", "Scoring manager"),
                row.get("CompletionCriterion", "Document the decision and archive the evidence."),
                row.get("DoNotClaim", "Do not make operational changes from one statistic alone."),
            )

    if isinstance(category, pd.DataFrame) and not category.empty:
        cat = category.iloc[0]
        add_decision(
            "Rating-category policy",
            cat.get("Status", "Review"),
            "category_collapse_action_center.csv; rating_scale_decision_support.csv; rating_scale_recode_candidates.csv",
            cat.get("RecommendedAction", "Review category evidence before deciding on category policy."),
            cat.get("DoNotClaim", "Category policy can be distorted by automatic collapse decisions."),
            "Rubric owner; scoring manager",
            "Choose to retain the original categories or document a sensitivity plan with substantive rubric justification.",
            "Do not collapse categories solely to improve fit, alpha, or visual smoothness.",
        )

    if isinstance(critical, pd.DataFrame) and not critical.empty:
        stop_rows = critical.loc[critical["StopBeforeFinalOutput"].fillna(False).astype(bool)]
        if not stop_rows.empty:
            first_stop = stop_rows.sort_values("Priority").iloc[0]
            add_decision(
                "Hold final operational decision",
                first_stop.get("Decision", "Stop before final output"),
                first_stop.get("EvidenceToOpen", "critical_final_review_panel.csv"),
                first_stop.get("ActionBeforeContinuing", "Resolve the critical final-review blocker before operational use."),
                first_stop.get("WhatCouldGoWrong", "Operational decisions may outrun the evidence."),
                first_stop.get("OwnerRole", "Project lead"),
                "Document whether the issue was resolved, caveated, or carried into the next administration plan.",
                first_stop.get("DoNotClaim", "Do not treat the current run as operationally final while a blocker remains."),
            )

    if not rows:
        add_decision(
            "Operational review",
            "No scoring or category decision row was generated",
            "scoring_consistency_decision.csv; critical_final_review_panel.csv",
            "Regenerate diagnostics or open the report-ready summary before operational use.",
            "A missing operational board can hide skipped scoring and category checks.",
            "Project lead",
            "Confirm scoring, rubric, category, and sharing decisions before the next administration.",
            "Do not use an absent decision board as evidence that no action is needed.",
        )

    out = pd.DataFrame(rows)
    priority_order = {"High": 0, "Medium": 1, "Manuscript": 1, "Routine": 2}
    out["_PriorityRank"] = out["CurrentSignal"].astype(str).map(
        lambda text: min([rank for label, rank in priority_order.items() if label in text] or [2])
    )
    out = out.sort_values(["_PriorityRank", "Decision"]).drop(columns=["_PriorityRank"]).reset_index(drop=True)
    out["Priority"] = np.arange(1, len(out) + 1, dtype=int)
    return out


def _first_text_match_row(frame: pd.DataFrame, column: str, pattern: str) -> pd.Series:
    """Return the first row whose text column contains the requested pattern."""
    if not isinstance(frame, pd.DataFrame) or frame.empty or column not in frame.columns:
        return pd.Series(dtype=object)
    hit = frame.loc[frame[column].astype(str).str.contains(pattern, case=False, regex=True, na=False)]
    return hit.iloc[0] if not hit.empty else pd.Series(dtype=object)


def build_reporting_action_bridge(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
    role_action_checklist: pd.DataFrame | None = None,
    report_ready_summary: pd.DataFrame | None = None,
    final_report_readiness: pd.DataFrame | None = None,
    manuscript_claim_guide: pd.DataFrame | None = None,
    critical_final_review: pd.DataFrame | None = None,
    status_rationale: pd.DataFrame | None = None,
    result_reading_path: pd.DataFrame | None = None,
    operational_decision_board: pd.DataFrame | None = None,
    quality_control_recommendations: pd.DataFrame | None = None,
    category_action_center: pd.DataFrame | None = None,
    submission_action_plan: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """Bridge review boards to APA wording and operational action artifacts."""
    if not isinstance(result, dict):
        return pd.DataFrame()
    diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
    all_bias = all_bias_results or {}
    if not all_bias and isinstance(bias_results, dict) and bias_results:
        all_bias = {f"{bias_results.get('facet_a', 'A')} x {bias_results.get('facet_b', 'B')}": bias_results}

    if not isinstance(report_ready_summary, pd.DataFrame) or report_ready_summary.empty:
        report_ready_summary = build_report_ready_summary_panel(
            result,
            diagnostics,
            all_bias_results=all_bias,
            bias_results=bias_results,
        )
    if not isinstance(final_report_readiness, pd.DataFrame) or final_report_readiness.empty:
        final_report_readiness = build_final_report_readiness(result, diagnostics, all_bias)
    if not isinstance(submission_action_plan, pd.DataFrame) or submission_action_plan.empty:
        submission_action_plan = build_submission_action_plan(result, diagnostics, all_bias)
    if not isinstance(manuscript_claim_guide, pd.DataFrame) or manuscript_claim_guide.empty:
        manuscript_claim_guide = build_manuscript_claim_guide(result, diagnostics, all_bias)
    if not isinstance(critical_final_review, pd.DataFrame) or critical_final_review.empty:
        critical_final_review = build_critical_final_review_panel(
            result,
            diagnostics,
            all_bias_results=all_bias,
            bias_results=bias_results,
            role_action_checklist=role_action_checklist,
            report_ready_summary=report_ready_summary,
            final_report_readiness=final_report_readiness,
            submission_action_plan=submission_action_plan,
        )
    if not isinstance(status_rationale, pd.DataFrame) or status_rationale.empty:
        status_rationale = build_status_rationale_drilldown(
            result,
            diagnostics,
            all_bias_results=all_bias,
            bias_results=bias_results,
            role_action_checklist=role_action_checklist,
            critical_final_review=critical_final_review,
            report_ready_summary=report_ready_summary,
            final_report_readiness=final_report_readiness,
            submission_action_plan=submission_action_plan,
        )
    if not isinstance(result_reading_path, pd.DataFrame) or result_reading_path.empty:
        result_reading_path = build_result_reading_path(
            result,
            diagnostics,
            all_bias_results=all_bias,
            bias_results=bias_results,
            report_ready_summary=report_ready_summary,
            final_report_readiness=final_report_readiness,
            manuscript_claim_guide=manuscript_claim_guide,
        )
    if not isinstance(quality_control_recommendations, pd.DataFrame) or quality_control_recommendations.empty:
        quality_control_recommendations = build_quality_control_recommendations(result, diagnostics)
    if not isinstance(category_action_center, pd.DataFrame) or category_action_center.empty:
        category_action_center = category_collapse_action_center_table(result, diagnostics)
    if not isinstance(operational_decision_board, pd.DataFrame) or operational_decision_board.empty:
        operational_decision_board = build_operational_decision_board(
            result,
            diagnostics,
            all_bias_results=all_bias,
            bias_results=bias_results,
            quality_control_recommendations=quality_control_recommendations,
            category_action_center=category_action_center,
            critical_final_review=critical_final_review,
            report_ready_summary=report_ready_summary,
            final_report_readiness=final_report_readiness,
            submission_action_plan=submission_action_plan,
        )

    def critical_row(pattern: str) -> pd.Series:
        return _first_text_match_row(critical_final_review, "Lens", pattern)

    def operation_row(pattern: str) -> pd.Series:
        return _first_text_match_row(operational_decision_board, "Decision", pattern)

    def reading_row(pattern: str) -> pd.Series:
        return _first_text_match_row(result_reading_path, "ReadingGoal", pattern)

    def status_from_rows(rows: Iterable[pd.Series], fallback: object = "Needs caveat") -> str:
        statuses = [
            str(row.get("CurrentStatus", row.get("ReportStatus", row.get("Status", ""))))
            for row in rows
            if isinstance(row, pd.Series) and not row.empty
        ]
        return _worst_report_ready_summary_status(statuses) if statuses else _report_ready_summary_status(fallback)

    def yes_no(value: object) -> str:
        return "Yes" if bool(value) else "No"

    rows: list[dict[str, object]] = []

    def add_row(
        *,
        track: str,
        audience: str,
        source_board: str,
        source_status: object,
        output: str,
        move: str,
        check: str,
        caveat: str,
        stop: str,
        evidence: str,
        app_location: str,
        download_file: str,
    ) -> None:
        rows.append({
            "Priority": len(rows) + 1,
            "BridgeTrack": str(track),
            "PrimaryAudience": str(audience),
            "SourceBoard": str(source_board),
            "CurrentStatus": _report_ready_summary_status(source_status),
            "OutputToProduce": str(output),
            "DraftOrDecisionMove": str(move),
            "RequiredCheck": str(check),
            "CaveatToCarry": str(caveat),
            "StopRule": str(stop),
            "EvidenceFiles": str(evidence),
            "AppLocation": str(app_location),
            "DownloadFile": str(download_file),
        })

    apa_row = critical_row("APA")
    claim_row = critical_row("Claim")
    manuscript_row = critical_row("Manuscript")
    scoring_row = critical_row("Scoring")
    category_row = critical_row("Rubric|category")
    diagnostic_row = critical_row("Measurement")
    archive_row = critical_row("Reproducibility")
    reading_draft = reading_row("Draft")
    reading_bias = reading_row("bias|local")
    rater_training = operation_row("Rater training")
    rubric_revision = operation_row("Rubric revision")
    category_policy = operation_row("Category|Rating-category")

    add_row(
        track="APA final wording gate",
        audience="Paper author; psychometric reviewer",
        source_board="Critical final review; APA sentence audit",
        source_status=status_from_rows([apa_row, manuscript_row]),
        output="Revised APA Results paragraph",
        move="Use the APA paragraph draft only after the final-output blockers and caveat rows have been resolved or carried into the text.",
        check=(
            f"APA stop={yes_no(apa_row.get('StopBeforeFinalOutput', False))}; "
            f"manuscript stop={yes_no(manuscript_row.get('StopBeforeFinalOutput', False))}; "
            "each copied sentence must match the sentence audit."
        ),
        caveat=str(apa_row.get("DoNotClaim", "Carry every caveat listed in the APA sentence audit and critical review.")),
        stop=str(apa_row.get("ActionBeforeContinuing", "Do not treat APA wording as final until the critical review has been opened.")),
        evidence="apa_results_paragraph_draft.md; apa_report_sentence_audit.csv; critical_final_review_panel.csv; reporting_action_bridge.csv",
        app_location="Report -> APA Report; Report & Export -> Critical final review",
        download_file="apa_results_paragraph_draft.md; apa_report_sentence_audit.csv; reporting_action_bridge.csv",
    )

    add_row(
        track="Claim-to-evidence revision",
        audience="Paper author; psychometric reviewer",
        source_board="Status rationale; manuscript claim guide",
        source_status=status_from_rows([claim_row, reading_draft]),
        output="Evidence-linked Results, limitations, and reviewer-response notes",
        move="Map every planned claim to a table, figure, diagnostic, caveat, and reviewer-facing boundary before writing final prose.",
        check=str(reading_draft.get("NextMove", "Open the claim guide and critical review before drafting claim language.")),
        caveat=str(claim_row.get("DoNotClaim", "Do not write claims that exceed the computed facet structure or diagnostics.")),
        stop=str(claim_row.get("ActionBeforeContinuing", "Hold broad claims until evidence rows are available.")),
        evidence="claim_to_evidence_matrix.csv; manuscript_claim_guide.csv; status_rationale_drilldown.csv; result_reading_path.csv",
        app_location="Report -> Claim Guide; Downloads -> Data Tables",
        download_file="claim_to_evidence_matrix.csv; manuscript_claim_guide.csv; status_rationale_drilldown.csv",
    )

    add_row(
        track="Guided result-reading notes",
        audience="Graduate researcher using MFRM",
        source_board="Result reading path",
        source_status=status_from_rows([reading_draft, reading_bias]),
        output="Ordered analysis notes before manuscript or operational use",
        move="Read the run gate, scale/category evidence, scoring consistency, model diagnostics, and bias/local interaction rows before drafting conclusions.",
        check="Each note should name the opened file, the supported claim, and one boundary that remains.",
        caveat=str(reading_bias.get("DoNotWriteYet", "Do not make no-bias or broad validity claims outside screened evidence.")),
        stop=str(reading_draft.get("NextMove", "Open the critical final review and APA sentence audit before copying generated wording.")),
        evidence="result_reading_path.csv; critical_final_review_panel.csv; bias_inference_audit.csv; final_report_readiness.csv",
        app_location="Report & Export -> Audience-specific review boards; Bias / Interaction; Fit Details",
        download_file="result_reading_path.csv; critical_final_review_panel.csv",
    )

    add_row(
        track="Rater training action memo",
        audience="Scoring manager; test developer",
        source_board="Operational decision board; QC recommendations",
        source_status=rater_training.get("CurrentSignal", scoring_row.get("CurrentStatus", "Needs caveat")),
        output="Rater training or moderation note",
        move=str(rater_training.get("RecommendedAction", "Review agreement, alpha, rater fit, and severity evidence before deciding on rater training.")),
        check=str(rater_training.get("BeforeNextAdministration", "Document the training decision and archive scoring-quality evidence before the next administration.")),
        caveat=str(rater_training.get("DoNotDo", "Do not diagnose rater performance from one statistic alone.")),
        stop=str(scoring_row.get("ActionBeforeContinuing", "Hold operational conclusions if scoring evidence is blocked.")),
        evidence="operational_decision_board.csv; quality_control_recommendations.csv; scoring_consistency_decision.csv; quality_control_todo_checklist.csv",
        app_location="Agreement / QC; Fit Details; Report & Export -> Decision board",
        download_file="operational_decision_board.csv; quality_control_recommendations.csv",
    )

    add_row(
        track="Rubric revision action memo",
        audience="Scoring manager; test developer",
        source_board="Operational decision board; category evidence",
        source_status=rubric_revision.get("CurrentSignal", category_row.get("CurrentStatus", "Needs caveat")),
        output="Rubric revision or clarification note",
        move=str(rubric_revision.get("RecommendedAction", "Review rubric descriptors with category evidence before revising scoring guidance.")),
        check="Use observed category support, threshold/curve evidence, scoring consistency, and substantive rubric rationale together.",
        caveat=str(rubric_revision.get("DoNotDo", "Do not revise rubric wording solely because one model diagnostic is unfavorable.")),
        stop=str(category_row.get("ActionBeforeContinuing", "Do not finalize rubric decisions before category evidence has been opened.")),
        evidence="operational_decision_board.csv; rating_scale_decision_support.csv; rating_scale_category_evidence.csv; category_probability_curves.csv",
        app_location="Categories / Steps; Visuals -> category curves",
        download_file="operational_decision_board.csv; rating_scale_decision_support.csv",
    )

    add_row(
        track="Category collapse sensitivity memo",
        audience="Scoring manager; test developer; psychometric reviewer",
        source_board="Operational decision board; category-collapse action center",
        source_status=category_policy.get("CurrentSignal", category_row.get("CurrentStatus", "Needs caveat")),
        output="Category-retain/collapse sensitivity decision",
        move=str(category_policy.get("RecommendedAction", "Treat category collapse as a documented sensitivity comparison with rubric justification.")),
        check=str(category_policy.get("BeforeNextAdministration", "Choose to retain the original categories or document a sensitivity plan before the next administration.")),
        caveat=str(category_policy.get("DoNotDo", "Do not collapse categories solely to improve fit, alpha, or visual smoothness.")),
        stop=str(category_row.get("ActionBeforeContinuing", "Hold category-policy conclusions until counts, thresholds, curves, and sensitivity candidates are reviewed.")),
        evidence="category_collapse_action_center.csv; rating_scale_recode_candidates.csv; rating_scale_decision_support.csv; operational_decision_board.csv",
        app_location="Categories / Steps; Downloads -> Scripts & Config",
        download_file="category_collapse_action_center.csv; rating_scale_recode_candidates.csv; reporting_action_bridge.csv",
    )

    add_row(
        track="Archive and handoff check",
        audience="Paper author; measurement practitioner; test developer",
        source_board="Critical final review; submission action plan",
        source_status=status_from_rows([diagnostic_row, archive_row]),
        output="Manuscript binder and operational decision log",
        move="Archive the evidence files, method notes, config, privacy manifest, and action bridge before circulating final wording or operational decisions.",
        check="A reviewer or project lead should be able to trace each claim or action to an exported evidence file.",
        caveat=str(diagnostic_row.get("DoNotClaim", "Do not claim broad model adequacy, fairness, or reproducibility beyond archived evidence.")),
        stop=str(archive_row.get("ActionBeforeContinuing", "Do not share final bundles until privacy and archive choices have been documented.")),
        evidence="MFRM_Manuscript_Binder.zip; MFRM_OSF_Package.zip; reporting_action_bridge.csv; export_privacy_manifest.csv",
        app_location="Downloads -> Scripts & Config; Manuscript Binder",
        download_file="MFRM_Manuscript_Binder.zip; reporting_action_bridge.csv; reporting_action_bridge.md",
    )

    out = pd.DataFrame(rows)
    return out.reset_index(drop=True)


def generate_reporting_action_bridge_markdown(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    bias_results: dict | None = None,
    bridge: pd.DataFrame | None = None,
    role_action_checklist: pd.DataFrame | None = None,
    report_ready_summary: pd.DataFrame | None = None,
    final_report_readiness: pd.DataFrame | None = None,
    manuscript_claim_guide: pd.DataFrame | None = None,
    critical_final_review: pd.DataFrame | None = None,
    status_rationale: pd.DataFrame | None = None,
    result_reading_path: pd.DataFrame | None = None,
    operational_decision_board: pd.DataFrame | None = None,
    quality_control_recommendations: pd.DataFrame | None = None,
    category_action_center: pd.DataFrame | None = None,
    submission_action_plan: pd.DataFrame | None = None,
) -> str:
    """Render the action bridge as a Markdown handoff."""
    if not isinstance(bridge, pd.DataFrame) or bridge.empty:
        bridge = build_reporting_action_bridge(
            result,
            diagnostics,
            all_bias_results=all_bias_results,
            bias_results=bias_results,
            role_action_checklist=role_action_checklist,
            report_ready_summary=report_ready_summary,
            final_report_readiness=final_report_readiness,
            manuscript_claim_guide=manuscript_claim_guide,
            critical_final_review=critical_final_review,
            status_rationale=status_rationale,
            result_reading_path=result_reading_path,
            operational_decision_board=operational_decision_board,
            quality_control_recommendations=quality_control_recommendations,
            category_action_center=category_action_center,
            submission_action_plan=submission_action_plan,
        )
    if not isinstance(bridge, pd.DataFrame) or bridge.empty:
        return "\n".join([
            "# Reporting Action Bridge",
            "",
            "No reporting-action bridge rows were generated for this run.",
            "",
        ])

    status_counts = bridge["CurrentStatus"].astype(str).value_counts().to_dict()
    status_summary = "; ".join(
        f"{status}: {int(status_counts.get(status, 0))}"
        for status in REPORT_READY_SUMMARY_STATUS_ORDER
        if int(status_counts.get(status, 0))
    ) or "no status rows"
    lines = [
        "# Reporting Action Bridge",
        "",
        "Use this after the audience-specific review boards. It translates the same evidence into APA wording, reviewer-facing claims, scoring actions, rubric decisions, category-collapse sensitivity notes, and archive steps.",
        "",
        f"Status summary: {status_summary}.",
        "",
    ]
    for _, row in bridge.sort_values("Priority").iterrows():
        lines.extend([
            f"## P{row.get('Priority')} - {row.get('BridgeTrack')} ({row.get('CurrentStatus')})",
            "",
            f"- Primary audience: {row.get('PrimaryAudience')}",
            f"- Source board: {row.get('SourceBoard')}",
            f"- Output to produce: {row.get('OutputToProduce')}",
            f"- Draft or decision move: {row.get('DraftOrDecisionMove')}",
            f"- Required check: {row.get('RequiredCheck')}",
            f"- Caveat to carry: {row.get('CaveatToCarry')}",
            f"- Stop rule: {row.get('StopRule')}",
            f"- Evidence files: {row.get('EvidenceFiles')}",
            f"- App location: {row.get('AppLocation')}",
            f"- Download file: {row.get('DownloadFile')}",
            "",
        ])
    lines.extend([
        "## Export Files",
        "",
        "- `reporting_action_bridge.csv`",
        "- `reporting_action_bridge.md`",
        "- `apa_results_paragraph_draft.md`",
        "- `operational_decision_board.csv`",
        "- `critical_final_review_panel.csv`",
        "",
    ])
    return "\n".join(lines)


def build_weighting_policy_audit(result: dict) -> pd.DataFrame:
    """Summarize how row weights affected the fitted likelihood inputs."""
    prep = result.get("prep", {}) if isinstance(result, dict) else {}
    row_audit = prep.get("row_audit", pd.DataFrame())
    data = prep.get("data", pd.DataFrame())
    weight_col = prep.get("weight_col", "Weight")
    rows: list[dict[str, object]] = []
    if isinstance(row_audit, pd.DataFrame) and not row_audit.empty:
        included = row_audit.get("IncludedInLikelihood", pd.Series(False, index=row_audit.index)).astype(bool)
        weight_numeric = pd.to_numeric(row_audit.get("WeightNumeric", pd.Series(np.nan, index=row_audit.index)), errors="coerce")
        rows.append({
            "Area": "Input rows",
            "RawRows": int(len(row_audit)),
            "IncludedRows": int(included.sum()),
            "ExcludedRows": int((~included).sum()),
            "IncludedEffectiveWeight": float(weight_numeric.where(included & np.isfinite(weight_numeric) & (weight_numeric > 0), 0.0).sum()),
            "MissingOrNonNumericWeightRows": int(row_audit.get("WeightMissingOrNonNumeric", pd.Series(False, index=row_audit.index)).astype(bool).sum()) if "WeightMissingOrNonNumeric" in row_audit else 0,
            "NonPositiveWeightRows": int(row_audit.get("WeightNonPositive", pd.Series(False, index=row_audit.index)).astype(bool).sum()) if "WeightNonPositive" in row_audit else 0,
            "WeightColumn": weight_col,
            "Policy": "Rows with missing, non-finite, or non-positive weights are excluded from estimation.",
        })
    elif isinstance(data, pd.DataFrame) and not data.empty:
        weights = pd.to_numeric(data.get("Weight", pd.Series(1.0, index=data.index)), errors="coerce")
        rows.append({
            "Area": "Likelihood rows",
            "RawRows": int(len(data)),
            "IncludedRows": int(len(data)),
            "ExcludedRows": 0,
            "IncludedEffectiveWeight": float(weights.where(np.isfinite(weights) & (weights > 0), 0.0).sum()),
            "MissingOrNonNumericWeightRows": 0,
            "NonPositiveWeightRows": 0,
            "WeightColumn": "Weight" if "Weight" in data.columns else "implicit unit weights",
            "Policy": "Positive likelihood weights are used in estimation, fit, bias, and SE calculations.",
        })
    out = pd.DataFrame(rows)
    if not out.empty:
        out["AffectedOutputs"] = "likelihood, element SE, fit statistics, bias screens, design effective N"
    return out


def build_misfit_casebook(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    top_n: int = 30,
) -> pd.DataFrame:
    """Combine fit/bias/marginal/PCA evidence into a review casebook."""
    if not (isinstance(result, dict) and result) and not (isinstance(diagnostics, dict) and diagnostics) and not all_bias_results:
        return pd.DataFrame()
    rows: list[dict[str, object]] = []

    def add_case(source, priority, facet, level, evidence, suggested, where):
        rows.append({
            "Priority": int(priority),
            "Source": str(source),
            "Facet": str(facet) if facet is not None else "",
            "Level": str(level) if level is not None else "",
            "Evidence": str(evidence),
            "SuggestedReview": str(suggested),
            "WhereToInspect": str(where),
            "ReportCaution": "Treat this as a review prompt; do not delete or explain away data automatically.",
        })

    fit = diagnostics.get("fit", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()
    if isinstance(fit, pd.DataFrame) and not fit.empty:
        f = fit.copy()
        infit = pd.to_numeric(f.get("Infit", pd.Series(np.nan, index=f.index)), errors="coerce")
        outfit = pd.to_numeric(f.get("Outfit", pd.Series(np.nan, index=f.index)), errors="coerce")
        iz = pd.to_numeric(f.get("InfitZSTD", pd.Series(np.nan, index=f.index)), errors="coerce").abs()
        oz = pd.to_numeric(f.get("OutfitZSTD", pd.Series(np.nan, index=f.index)), errors="coerce").abs()
        f["_score"] = np.nanmax(np.column_stack([iz.fillna(0), oz.fillna(0)]), axis=1)
        f["_mn_flag"] = (infit > 1.5) | (outfit > 1.5) | (infit < 0.5) | (outfit < 0.5)
        f = f[(f["_score"] >= 2.0) | f["_mn_flag"]].sort_values("_score", ascending=False).head(top_n)
        for _, row in f.iterrows():
            add_case(
                "Fit",
                1 if float(row.get("_score", 0.0)) >= 3.0 else 2,
                row.get("Facet", ""),
                row.get("Level", ""),
                f"Infit={row.get('Infit', np.nan):.3g}; Outfit={row.get('Outfit', np.nan):.3g}; max |ZSTD|={row.get('_score', np.nan):.3g}",
                "Inspect response patterns before interpreting this element or using it in high-stakes claims.",
                "Fit Details",
            )

    all_bias = all_bias_results or {}
    for pair_key, bundle in all_bias.items():
        tbl = bundle.get("table") if isinstance(bundle, dict) else None
        if not isinstance(tbl, pd.DataFrame) or tbl.empty:
            continue
        b = tbl.copy()
        t_vals = pd.to_numeric(b.get("t", pd.Series(np.nan, index=b.index)), errors="coerce")
        b["_abs_t"] = t_vals.abs()
        b = b[b["_abs_t"] >= 2.0].sort_values("_abs_t", ascending=False).head(max(3, top_n // max(1, len(all_bias))))
        for _, row in b.iterrows():
            bias_value = row.get("Bias Size", row.get("Bias_Size", row.get("Bias", np.nan)))
            add_case(
                "Bias/interaction",
                2,
                str(pair_key),
                row.get("Level", ""),
                f"|t|={row.get('_abs_t', np.nan):.3g}; bias={bias_value}",
                "Review local interaction substantively and consider multiplicity before reporting DIF/DFF-style claims.",
                "Bias/Interaction",
            )

    marginal = diagnostics.get("marginal_fit", {}) if isinstance(diagnostics, dict) else {}
    if isinstance(marginal, dict) and marginal.get("available"):
        summary = marginal.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            m = summary.copy()
            m["MaxAbsStdResidual"] = pd.to_numeric(m.get("MaxAbsStdResidual", pd.Series(np.nan, index=m.index)), errors="coerce")
            m = m[m["MaxAbsStdResidual"] >= 3.0].sort_values("MaxAbsStdResidual", ascending=False).head(10)
            for _, row in m.iterrows():
                label = _marginal_scope_label(row)
                add_case(
                    "Strict marginal",
                    2,
                    row.get("Facet", row.get("Scope", "")),
                    label,
                    f"Max |standardized observed-expected residual|={row.get('MaxAbsStdResidual', np.nan):.3g}",
                    "Use with residual, category, and design screens before claiming model-data reproduction.",
                    "Fit Details -> Strict marginal diagnostics",
                )

    pca_reason_payload = diagnostics.get("pca_reason") if isinstance(diagnostics, dict) else None
    pca_reason_text = _render_reason(pca_reason_payload)
    if pca_reason_text:
        add_case(
            "Dimensionality",
            3,
            "Residual PCA",
            "",
            pca_reason_text,
            "Enable or justify residual PCA before making residual-dimensionality claims.",
            "Dimensionality",
        )

    anchor = result.get("config", {}).get("anchor_audit", {}) if isinstance(result, dict) else {}
    if isinstance(anchor, dict) and anchor.get("overall_status") in {"warning", "error"}:
        add_case(
            "Anchor/linking",
            1 if anchor.get("overall_status") == "error" else 2,
            "Anchor audit",
            "",
            anchor.get("message", "Anchor audit flagged issues."),
            "Resolve anchor issues before linked-scale claims.",
            "Data -> Anchor/linking audit",
        )

    out = pd.DataFrame(rows)
    if out.empty:
        return pd.DataFrame([{
            "Priority": 9,
            "Source": "Casebook",
            "Facet": "",
            "Level": "",
            "Evidence": "No priority misfit cases were detected under the current thresholds.",
            "SuggestedReview": "Still review residual, fit, bias, marginal, and design diagnostics before treating this as perfect fit.",
            "WhereToInspect": "Fit Details; Bias/Interaction; Data",
            "ReportCaution": "Absence of flags is not proof of perfect fit.",
        }])
    return out.sort_values(["Priority", "Source", "Facet", "Level"]).head(int(top_n)).reset_index(drop=True)


def build_case_interpretation_guidance(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> pd.DataFrame:
    """Case-specific interpretation prompts for common interpretation pitfalls."""
    config = result.get("config", {})
    prep = result.get("prep", {})
    readiness = build_final_report_readiness(result, diagnostics, all_bias_results or {})
    gate = build_publication_gate_summary(result, diagnostics, all_bias_results or {})
    rows: list[dict[str, object]] = []

    def readiness_row(check: str) -> pd.Series:
        if isinstance(readiness, pd.DataFrame) and not readiness.empty and "Check" in readiness.columns:
            hit = readiness.loc[readiness["Check"].astype(str) == check]
            if not hit.empty:
                return hit.iloc[0]
        return pd.Series(dtype=object)

    def add_case(
        priority: int,
        case: str,
        status: str,
        evidence: str,
        interpretation: str,
        guardrail: str,
        action: str,
        where: str,
        avoid_wording: str,
        safer_wording: str,
    ) -> None:
        rows.append({
            "Priority": int(priority),
            "Case": str(case),
            "Status": str(status),
            "Evidence": str(evidence),
            "InterpretationNote": str(interpretation),
            "ManuscriptGuardrail": str(guardrail),
            "NextAction": str(action),
            "WhereToInspect": str(where),
            "AvoidWording": str(avoid_wording),
            "SaferWording": str(safer_wording),
        })

    overall_gate = pd.Series(dtype=object)
    if isinstance(gate, pd.DataFrame) and not gate.empty and "GateArea" in gate.columns:
        hit = gate.loc[gate["GateArea"].astype(str) == "Overall manuscript gate"]
        if not hit.empty:
            overall_gate = hit.iloc[0]
    if not overall_gate.empty:
        gate_status = str(overall_gate.get("GateStatus", "Ready"))
        add_case(
            1,
            "Overall manuscript gate",
            gate_status,
            str(overall_gate.get("Evidence", "")),
            "This is the first stop before copying APA-style text into a paper.",
            "Do not turn draft APA text into a final conclusion when the gate is caveated or blocked.",
            str(overall_gate.get("ManuscriptAction", "Review gate details.")),
            "Report -> Reports -> APA Report / publication_gate_summary.csv",
            "The model results conclusively support the study conclusions.",
            f"The MFRM output was interpreted with the publication gate status of {gate_status}, and final claims were limited to supported diagnostics.",
        )

    unused_raw = prep.get("unused_score_categories", [])
    if isinstance(unused_raw, (list, tuple, set, np.ndarray, pd.Series)):
        unused_categories = list(unused_raw)
    elif unused_raw is None or str(unused_raw) == "":
        unused_categories = []
    else:
        unused_categories = [unused_raw]
    cat_ready = readiness_row("Category functioning")
    cat_status = str(cat_ready.get("Status", "Missing")) if not cat_ready.empty else "Missing"
    cat_evidence = str(cat_ready.get("Evidence", "Category diagnostics unavailable.")) if not cat_ready.empty else "Category diagnostics unavailable."
    if unused_categories or cat_status != "Ready":
        score_range = f"{prep.get('rating_min', '?')} to {prep.get('rating_max', '?')}"
        unused_label = ", ".join(map(str, unused_categories)) if unused_categories else "none"
        add_case(
            2,
            "Sparse or unused rating categories",
            "Report with caveat" if cat_status != "Ready" or unused_categories else "Ready",
            f"score range {score_range}; unused categories: {unused_label}; {cat_evidence}",
            "The app can retain zero-count categories, but unused or sparse categories are weak evidence for threshold interpretation.",
            "Do not claim that every rating category functioned distinctly unless counts, average measures, and thresholds support it.",
            "Inspect category counts and threshold order; collapse adjacent categories only with substantive rubric justification.",
            "Categories/Steps; category_probability_curves.csv",
            "All rating categories functioned as intended.",
            "The rating scale was interpreted with caution because sparse or unused categories weaken threshold and category-functioning evidence.",
        )

    pca_ready = readiness_row("Dimensionality screen")
    pca_status = str(pca_ready.get("Status", "Missing")) if not pca_ready.empty else "Missing"
    if pca_status != "Ready":
        add_case(
            3,
            "Dimensionality caveat",
            "Report with caveat",
            str(pca_ready.get("Evidence", "Residual PCA was skipped or unavailable.")),
            "Residual structure may contain a secondary dimension, or PCA was not computed.",
            "Do not claim that unidimensionality was established from global residual fit alone.",
            "Open Dimensionality and either report the PCA caveat or enable PCA for final reporting.",
            "Dimensionality; publication_gate_summary.csv",
            "Unidimensionality was established.",
            "Global fit was interpreted together with the residual dimensionality screen; unidimensionality claims were limited by the PCA status.",
        )

    all_bias = all_bias_results or {}
    bias_audit = build_bias_inference_audit(all_bias, result, diagnostics) if all_bias else pd.DataFrame()
    n_flagged = int(pd.to_numeric(bias_audit.get("FlaggedCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
    n_total = int(pd.to_numeric(bias_audit.get("CellsScreened", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
    n_sparse = int(pd.to_numeric(bias_audit.get("SparseCells", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if isinstance(bias_audit, pd.DataFrame) else 0
    if not all_bias or n_flagged or n_sparse:
        add_case(
            4,
            "Bias/local interaction screen",
            "Boundary" if not all_bias else "Report with caveat",
            (
                "No bias/interaction screen was computed."
                if not all_bias else
                f"{n_flagged} of {n_total} screened local interactions were DFF/bias flags; {n_sparse} sparse cell(s)."
            ),
            "Bias output is a screening prompt, not automatic proof of bias or proof of no bias.",
            "Do not make no-bias claims outside the facet pairs and cells that were actually screened.",
            "For final reporting, run the intended selected pair or full publication screen and review flagged cells substantively.",
            "Bias/Interaction; manuscript_claim_guide.csv",
            "There was no rater bias.",
            "The bias/local interaction screen was treated as a diagnostic screen, and no-bias claims were limited to the facet pairs and cells actually examined.",
        )

    if str(config.get("method", "")).upper() == "MML":
        marginal = diagnostics.get("marginal_fit", {})
        available = isinstance(marginal, dict) and bool(marginal.get("available", False))
        n_review = int(marginal.get("n_review", 0) or 0) if isinstance(marginal, dict) else 0
        if (not available) or n_review:
            add_case(
                5,
                "MML strict marginal diagnostics",
                "Report with caveat" if available else "Boundary",
                (
                    f"{n_review} marginal row(s) flagged."
                    if available else
                    (marginal.get("reason", "Strict marginal diagnostics were skipped.") if isinstance(marginal, dict) else "Strict marginal diagnostics were skipped.")
                ),
                "MML posterior and marginal checks need their own diagnostic review for final manuscripts.",
                "Do not describe an MML run as fully screened if strict marginal diagnostics were skipped or flagged.",
                "Enable strict marginal diagnostics when feasible and include flagged marginal rows in the limitation language.",
                "Fit Details / Downloads -> marginal_fit_summary.csv",
                "The MML model fully reproduced the observed marginal distributions.",
                "The MML fit was interpreted together with the strict marginal diagnostic status, and any skipped or flagged marginal rows were reported as limitations.",
            )

    rel_df = diagnostics.get("reliability", pd.DataFrame())
    if isinstance(rel_df, pd.DataFrame) and not rel_df.empty and {"Facet", "Reliability"}.issubset(rel_df.columns):
        human_facet_mask = rel_df["Facet"].astype(str).str.lower().str.contains("rater|judge|evaluator|reader", regex=True)
        human_rel = rel_df[human_facet_mask].copy()
        if not human_rel.empty:
            rel_vals = pd.to_numeric(human_rel["Reliability"], errors="coerce").dropna()
            if len(rel_vals) and float(rel_vals.max()) >= FINAL_PERSON_RELIABILITY_READY:
                add_case(
                    6,
                    "High human-rater facet reliability",
                    "Report with caveat",
                    f"highest human-rater facet reliability = {float(rel_vals.max()):.3f}",
                    "High rater reliability usually means raters differ in severity; it is not automatically desirable agreement.",
                    "Do not write that high rater reliability proves raters were interchangeable.",
                    "Report rater severity spread and consider rater training/calibration if the study requires interchangeability.",
                    "Report -> Tables; Wright Map; Measures",
                    "High rater reliability shows that raters agreed well.",
                    "High rater facet reliability was interpreted as evidence of severity differentiation, not automatic rater agreement.",
                )

    anchor_ready = readiness_row("Anchor / linking audit")
    anchor_status = str(anchor_ready.get("Status", "Missing")) if not anchor_ready.empty else "Missing"
    if anchor_status != "Ready":
        add_case(
            7,
            "Anchor/linking claims",
            "Boundary",
            str(anchor_ready.get("Evidence", "Anchor/linking audit was not ready.")),
            "Single-run measures can be interpreted within the current connected design; cross-run claims require more evidence.",
            "Do not compare cohorts, forms, administrations, or studies on a common scale without anchor/linking evidence.",
            "Use anchor audit, drift, and equating-chain outputs before writing cross-run comparison claims.",
            "Data -> Anchor/linking audit; Report -> Tables & checks -> Facet Equivalence",
            "These measures can be compared directly with another administration or form.",
            "Measures were interpreted within the current connected run unless anchor/linking evidence supported cross-run comparison.",
        )

    if not rows:
        add_case(
            99,
            "No common interpretation pitfall flagged",
            "Ready",
            "No case-specific caution was generated.",
            "The main automated checks did not identify common reporting traps.",
            "Still edit all generated text for study design, rubric content, and local reporting standards.",
            "Proceed through the Manuscript Template and Reporting Checklist before submission.",
            "Report -> Manuscript Template / Reporting Checklist",
            "The generated text can be submitted without revision.",
            "The generated text was used as a draft and edited for study design, rubric content, and reporting standards.",
        )

    out = pd.DataFrame(rows)
    status_order = {"Not ready": 0, "Report with caveat": 1, "Boundary": 2, "Ready": 3}
    if "Status" in out.columns:
        out["_sort"] = out["Status"].map(status_order).fillna(4)
        out = out.sort_values(["Priority", "_sort", "Case"]).drop(columns=["_sort"]).reset_index(drop=True)
    return out


def build_submission_action_plan(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> pd.DataFrame:
    """One-screen priority list for manuscript-ready reporting decisions."""
    all_bias = all_bias_results or {}
    gate = build_publication_gate_summary(result, diagnostics, all_bias)
    case_guidance = build_case_interpretation_guidance(result, diagnostics, all_bias)
    guide = build_manuscript_claim_guide(result, diagnostics, all_bias)
    readiness = build_final_report_readiness(result, diagnostics, all_bias)
    rows: list[dict[str, object]] = []

    def status_rank(status: str) -> int:
        return {
            "Not ready": 0,
            "Do not claim": 0,
            "Report with caveat": 1,
            "Review": 1,
            "Missing": 1,
            "Boundary": 2,
            "Ready": 3,
        }.get(str(status), 2)

    def before_copying(status: str) -> str:
        status = str(status)
        if status in {"Not ready", "Do not claim"}:
            return "Resolve this before copying final APA-style conclusions."
        if status in {"Report with caveat", "Review", "Missing"}:
            return "Use caveat language and keep the claim narrower than the draft wording."
        if status == "Boundary":
            return "Do not expand this beyond the computed design and diagnostics."
        return "Use as draft wording after study-specific editing."

    def add_action(
        rank: int,
        source: str,
        topic: str,
        status: str,
        evidence: str,
        action: str,
        where: str,
        avoid: str = "",
        safer: str = "",
    ) -> None:
        rows.append({
            "_Rank": int(rank),
            "Priority": 0,
            "Source": str(source),
            "Topic": str(topic),
            "Status": str(status),
            "Evidence": str(evidence),
            "ImmediateAction": str(action),
            "BeforeCopying": before_copying(status),
            "AvoidWording": str(avoid),
            "SaferWording": str(safer),
            "WhereToInspect": str(where),
        })

    if isinstance(gate, pd.DataFrame) and not gate.empty:
        for i, row in gate.iterrows():
            status = str(row.get("GateStatus", "Review"))
            area = str(row.get("GateArea", "Publication gate"))
            if area == "Overall manuscript gate" or status != "Ready":
                add_action(
                    status_rank(status) * 1000 + i,
                    "Publication gate",
                    area,
                    status,
                    row.get("Evidence", ""),
                    row.get("ManuscriptAction", "Review gate details before reporting."),
                    "Report -> Reports -> APA Report / publication_gate_summary.csv",
                )

    if isinstance(case_guidance, pd.DataFrame) and not case_guidance.empty:
        for i, row in case_guidance.iterrows():
            status = str(row.get("Status", "Review"))
            if status != "Ready":
                add_action(
                    status_rank(status) * 1000 + 100 + int(row.get("Priority", i + 1)),
                    "Case interpretation guide",
                    row.get("Case", "Case-specific guidance"),
                    status,
                    row.get("Evidence", ""),
                    row.get("NextAction", "Review case-specific guidance."),
                    row.get("WhereToInspect", "Report"),
                    row.get("AvoidWording", ""),
                    row.get("SaferWording", ""),
                )

    if isinstance(guide, pd.DataFrame) and not guide.empty:
        for i, row in guide.iterrows():
            status = str(row.get("ClaimStatus", "Review"))
            if status != "Ready":
                add_action(
                    status_rank(status) * 1000 + 200 + i,
                    "Manuscript claim guide",
                    row.get("ManuscriptArea", "Manuscript claim"),
                    status,
                    row.get("EvidenceToReport", ""),
                    row.get("NextAction", "Review claim guide before reporting."),
                    "Report -> Manuscript Claim Guide / manuscript_claim_guide.csv",
                    row.get("DoNotClaim", ""),
                    row.get("SafeManuscriptWording", ""),
                )

    if isinstance(readiness, pd.DataFrame) and not readiness.empty:
        for i, row in readiness.iterrows():
            status = str(row.get("Status", "Review"))
            required = str(row.get("Required", "No")) == "Yes"
            if required and status != "Ready":
                add_action(
                    status_rank(status) * 1000 + 300 + i,
                    "Final-report readiness",
                    row.get("Check", "Readiness check"),
                    status,
                    row.get("Evidence", ""),
                    row.get("ActionBeforeFinalReport", "Review readiness row before reporting."),
                    "Report -> Tables & checks -> Reporting Checklist / final_report_readiness.csv",
                )

    if not rows:
        add_action(
            999,
            "Submission action plan",
            "No blocking or caveated reporting item",
            "Ready",
            "No required blocker, caveat, or boundary row was generated.",
            "Proceed to study-specific editing and reviewer preflight checks.",
            "Report -> Manuscript Template / Reporting Checklist",
            "The generated report can be submitted without revision.",
            "The generated report was adapted to the study design, rubric, and local reporting standards.",
        )

    out = pd.DataFrame(rows)
    out = out.sort_values(["_Rank", "Source", "Topic"]).reset_index(drop=True)
    out = out.drop_duplicates(subset=["Source", "Topic", "Status"], keep="first").reset_index(drop=True)
    out["Priority"] = np.arange(1, len(out) + 1, dtype=int)
    return out.drop(columns=["_Rank"])


def _status_rank_for_handoff(status: object) -> int:
    return {
        "Not ready": 0,
        "Do not claim": 0,
        "Report with caveat": 1,
        "Review": 1,
        "Missing": 1,
        "Boundary": 2,
        "Ready": 3,
    }.get(str(status), 2)


def _overall_manuscript_gate_status(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> tuple[str, str]:
    gate = build_publication_gate_summary(result, diagnostics, all_bias_results or {})
    if not isinstance(gate, pd.DataFrame) or gate.empty:
        return "Review", "Publication gate summary was not available."
    if {"GateArea", "GateStatus"}.issubset(gate.columns):
        overall = gate.loc[gate["GateArea"].astype(str) == "Overall manuscript gate"]
        if not overall.empty:
            row = overall.iloc[0]
            return str(row.get("GateStatus", "Review")), str(row.get("Evidence", "Review gate evidence."))
    if "GateStatus" in gate.columns:
        statuses = gate["GateStatus"].astype(str).tolist()
        status = min(statuses, key=_status_rank_for_handoff) if statuses else "Review"
        return status, "Overall status inferred from component publication-gate rows."
    return "Review", "Publication gate summary did not expose a status column."


def _handoff_text(value: object, default: str = "") -> str:
    if value is None:
        return default
    try:
        if pd.isna(value):
            return default
    except Exception:
        pass
    text = str(value).strip()
    return text if text else default


def _table_row_by_value(df: pd.DataFrame, key_col: str, key_value: str) -> pd.Series | None:
    if not isinstance(df, pd.DataFrame) or df.empty or key_col not in df.columns:
        return None
    hit = df.loc[df[key_col].astype(str) == str(key_value)]
    return hit.iloc[0] if not hit.empty else None


def build_claim_to_evidence_matrix(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> pd.DataFrame:
    """Map manuscript claims to the concrete app evidence that supports them."""
    all_bias = all_bias_results or {}
    guide = build_manuscript_claim_guide(result, diagnostics, all_bias)
    gate = build_publication_gate_summary(result, diagnostics, all_bias)
    readiness = build_final_report_readiness(result, diagnostics, all_bias)
    action_plan = build_submission_action_plan(result, diagnostics, all_bias)
    current_method_refs = build_current_run_method_reference_audit(result, diagnostics, all_bias)
    evidence_map: dict[str, dict[str, object]] = {
        "Model and software scope": {
            "ManuscriptSection": "Methods",
            "PrimaryTables": "summary.csv; method_reference_audit.csv; mfrm_config.json; method_appendix.md",
            "PrimaryFigures": "",
            "ReadinessChecks": "Convergence",
            "AppLocation": "Report -> Exports; Downloads -> Scripts & Config",
            "ReviewerQuestion": "What software, model, estimation method, score support, and runtime boundary produced the results?",
            "ArchiveFiles": "mfrm_config.json; mfrm_method_appendix.md; mfrm_app_engine_runner.py; requirements.txt",
        },
        "Convergence and final interpretability": {
            "ManuscriptSection": "Methods; Results",
            "PrimaryTables": "convergence.csv; publication_gate_summary.csv; final_report_readiness.csv",
            "PrimaryFigures": "",
            "ReadinessChecks": "Convergence",
            "AppLocation": "Report -> Tables & checks; Downloads -> Data Tables",
            "ReviewerQuestion": "Did the estimation converge strongly enough to interpret the fitted measures?",
            "ArchiveFiles": "MFRM_Tables.zip; MFRM_Report.xlsx",
        },
        "Rating-scale functioning": {
            "ManuscriptSection": "Results",
            "PrimaryTables": "score_map.csv; steps.csv; category_diagnostics.csv; category_probability_curves.csv; visual_claim_guardrails.csv",
            "PrimaryFigures": "category_probability_curves_average; expected_score_curve_average",
            "ReadinessChecks": "Category functioning",
            "AppLocation": "Results -> Categories/Steps; Downloads -> Figures",
            "ReviewerQuestion": "Do observed category counts, average measures, and thresholds support the rating-scale interpretation?",
            "ArchiveFiles": "MFRM_Tables.zip; MFRM_Publication_Figures.zip; visual_claim_guardrails.csv",
        },
        "Reliability and separation": {
            "ManuscriptSection": "Results",
            "PrimaryTables": "reliability.csv; design_evaluation.csv; facet_sample_size_adequacy.csv",
            "PrimaryFigures": "wright_map; facet_distribution",
            "ReadinessChecks": "Reliability / separation",
            "AppLocation": "Results -> Reliability; Design evaluation; Downloads -> Data Tables",
            "ReviewerQuestion": "Which facet's ordering is reliable, and is that reliability substantively desirable?",
            "ArchiveFiles": "MFRM_Tables.zip; MFRM_Publication_Figures.zip",
        },
        "Fit and dimensionality": {
            "ManuscriptSection": "Results; Limitations",
            "PrimaryTables": "fit_statistics.csv; residuals.csv; pca_eigenvalues.csv; pca_stability_audit.csv; method_reference_audit.csv; final_report_readiness.csv",
            "PrimaryFigures": "fit_scatter; strict_marginal_summary; strict_marginal_heatmap",
            "ReadinessChecks": "Global residual fit; Dimensionality screen; Strict marginal diagnostics",
            "AppLocation": "Fit Details; Dimensionality; Downloads -> Data Tables/Figures",
            "ReviewerQuestion": "Do fit and residual structure support the dimensional interpretation being claimed?",
            "ArchiveFiles": "MFRM_Tables.zip; MFRM_Publication_Figures.zip",
        },
        "Wright map targeting and measure interpretation": {
            "ManuscriptSection": "Results",
            "PrimaryTables": "measures.csv; person_measures.csv; facet_element_measures.csv; steps.csv; visual_claim_guardrails.csv",
            "PrimaryFigures": "wright_map",
            "ReadinessChecks": "Wright Map targeting",
            "AppLocation": "Visuals -> Wright Map; Downloads -> Figures",
            "ReviewerQuestion": "How well do person locations and facet/rubric locations overlap on the current scale?",
            "ArchiveFiles": "MFRM_Tables.zip; MFRM_Publication_Figures.zip; visual_claim_guardrails.csv",
        },
        "Bias / local interaction": {
            "ManuscriptSection": "Results; Limitations",
            "PrimaryTables": "bias_*.csv; dff_bias_*.csv; bias_inference_audit.csv; method_reference_audit.csv; submission_action_plan.csv",
            "PrimaryFigures": "",
            "ReadinessChecks": "Bias / local interaction",
            "AppLocation": "Bias / local interaction; Downloads -> Data Tables",
            "ReviewerQuestion": "Which facet pairs and cells were screened, and are flagged cells sparse, multiplicity-adjusted, or substantively meaningful?",
            "ArchiveFiles": "MFRM_Tables.zip; claim_to_evidence_matrix.csv",
        },
        "Anchoring and linking": {
            "ManuscriptSection": "Methods; Results; Limitations",
            "PrimaryTables": "anchor_audit_summary.csv; anchor_drift_summary.csv; equating_chain_summary.csv; anchors.csv",
            "PrimaryFigures": "",
            "ReadinessChecks": "Anchor / linking audit; Anchor drift; Equating-chain summary",
            "AppLocation": "Data -> Anchor/linking audit; Downloads -> Data Tables",
            "ReviewerQuestion": "Is there enough anchor/linking evidence to compare forms, cohorts, administrations, or studies?",
            "ArchiveFiles": "anchors.csv; MFRM_Tables.zip; mfrm_config.json",
        },
        "Prediction, plausible values, and simulation": {
            "ManuscriptSection": "Supplement; Limitations",
            "PrimaryTables": "fitted_predictions.csv; posterior_scores.csv; plausible_values.csv; refit_simulation_summary.csv",
            "PrimaryFigures": "",
            "ReadinessChecks": "Strict marginal diagnostics",
            "AppLocation": "Prediction/Simulation panels; Downloads -> Data Tables",
            "ReviewerQuestion": "Are model-based predictions or simulations described as sensitivity/planning evidence rather than validation or causal evidence?",
            "ArchiveFiles": "MFRM_Tables.zip; mfrm_config.json; mfrm_app_engine_runner.py",
        },
        "External package comparison": {
            "ManuscriptSection": "Supplement; Validation appendix",
            "PrimaryTables": "external_simulation_reference_inventory.csv; external_simulation_template_inventory.csv; method_reference_audit.csv; mfrmr_020_migration_coverage.csv",
            "PrimaryFigures": "",
            "ReadinessChecks": "",
            "AppLocation": "Downloads -> Scripts & Config; validation artifacts",
            "ReviewerQuestion": "If cross-package equality is claimed, where is the exact fixture, parameterization map, tolerance report, and output artifact?",
            "ArchiveFiles": "MFRM_External_Simulation_Validation_Templates.zip; archived external validation outputs",
        },
        "Bayesian / Uto-family extension": {
            "ManuscriptSection": "Methods; Supplement; Limitations",
            "PrimaryTables": "bayesian_mfrm_stan_refinement_plan.csv; reproducibility_script_matrix.csv; stan_reproducibility_archive_contract.csv; stan_posterior_reproducibility_route.csv; mfrm_stan_data_manifest.csv; mfrm_stan_data_dictionary.csv; mfrm_stan_prior_guidance.csv; mfrm_stan_prior_sensitivity_grid.csv; mfrm_uto_bayesian_mfrm_design_audit.csv; mfrm_uto_bayesian_mfrm_claim_wording.csv; stan_posterior_handoff_checklist.csv; stan_run_manifest_template.csv; method_reference_audit.csv",
            "PrimaryFigures": "posterior viewer exports when available",
            "ReadinessChecks": "",
            "AppLocation": "Report -> Exports -> Stan Code; Downloads -> Scripts & Config; Posterior Viewer",
            "ReviewerQuestion": "Was the Uto-family Bayesian MFRM scaffold actually run, with priors, data JSON, sampler diagnostics, and sensitivity variants archived?",
            "ArchiveFiles": "mfrm_uto_bayesian_mfrm.stan; mfrm_stan_data.json; mfrm_stan_prior_guidance.csv; mfrm_stan_prior_sensitivity_grid.csv; stan_run_manifest.json; stan_run_manifest.csv; posterior_manifest_check.csv; mfrm_uto_bayesian_mfrm_data_template.json; mfrm_uto_bayesian_mfrm_design_audit.csv; mfrm_uto_bayesian_mfrm_claim_wording.csv; MFRM_Bayesian_Stan_Runners.zip; CmdStan CSV chains; posterior diagnostics",
        },
    }

    rows: list[dict[str, object]] = []
    if not isinstance(guide, pd.DataFrame) or guide.empty:
        return pd.DataFrame()
    for idx, row in guide.iterrows():
        area = _handoff_text(row.get("ManuscriptArea"), "Manuscript claim")
        meta = evidence_map.get(area, {
            "ManuscriptSection": "Results",
            "PrimaryTables": "MFRM_Tables.zip",
            "PrimaryFigures": "",
            "ReadinessChecks": "",
            "AppLocation": "Downloads",
            "ReviewerQuestion": "Which app output supports this claim?",
            "ArchiveFiles": "MFRM_OSF_Package.zip",
        })
        gate_row = _table_row_by_value(gate, "GateArea", area)
        action_row = _table_row_by_value(action_plan, "Topic", area)
        check_names = [
            part.strip()
            for part in _handoff_text(meta.get("ReadinessChecks")).split(";")
            if part.strip()
        ]
        check_bits = []
        evidence_bits = []
        for check in check_names:
            readiness_row = _table_row_by_value(readiness, "Check", check)
            if readiness_row is None:
                continue
            status = _handoff_text(readiness_row.get("Status"), "Review")
            evidence = _handoff_text(readiness_row.get("Evidence"), "No evidence recorded.")
            check_bits.append(f"{check}: {status}")
            evidence_bits.append(f"{check}: {evidence}")
        ref_summary = _method_reference_summary_for_manuscript_area(area, current_method_refs)
        rows.append({
            "Priority": int(idx) + 1,
            "ManuscriptArea": area,
            "ManuscriptSection": _handoff_text(meta.get("ManuscriptSection"), "Results"),
            "PrimaryClaim": _handoff_text(row.get("SafeManuscriptWording"), "Review manuscript wording."),
            "ClaimStatus": _handoff_text(row.get("ClaimStatus"), "Review"),
            "GateStatus": _handoff_text(gate_row.get("GateStatus") if gate_row is not None else "", "Ready"),
            "EvidenceToReport": _handoff_text(row.get("EvidenceToReport"), "No evidence recorded."),
            "PrimaryTables": _handoff_text(meta.get("PrimaryTables"), "MFRM_Tables.zip"),
            "PrimaryFigures": _handoff_text(meta.get("PrimaryFigures"), ""),
            "ReadinessChecks": "; ".join(check_bits) if check_bits else _handoff_text(meta.get("ReadinessChecks"), "No dedicated readiness row."),
            "ReadinessEvidence": " | ".join(evidence_bits) if evidence_bits else "Use claim-guide and publication-gate evidence.",
            "CaveatOrBoundary": _handoff_text(row.get("DoNotClaim"), "Keep claim within the computed evidence."),
            "NextAction": _handoff_text(
                action_row.get("ImmediateAction") if action_row is not None else row.get("NextAction"),
                "Review before manuscript use.",
            ),
            "ReferenceAuditAreas": _handoff_text(ref_summary.get("ReferenceAuditAreas"), ""),
            "SuggestedCitations": _handoff_text(ref_summary.get("SuggestedCitations"), ""),
            "CitationBoundary": _handoff_text(ref_summary.get("CitationBoundary"), ""),
            "CitationEvidenceFile": _handoff_text(ref_summary.get("CitationEvidenceFile"), "method_reference_audit.csv"),
            "ReviewerQuestion": _handoff_text(meta.get("ReviewerQuestion"), "Which output supports this claim?"),
            "ArchiveFiles": _handoff_text(meta.get("ArchiveFiles"), "MFRM_OSF_Package.zip"),
            "AppLocation": _handoff_text(meta.get("AppLocation"), "Downloads"),
        })
    out = pd.DataFrame(rows)
    status_order = {"Do not claim": 0, "Report with caveat": 1, "Review": 1, "Boundary": 2, "Ready": 3}
    if "ClaimStatus" in out.columns:
        out["_sort"] = out["ClaimStatus"].map(status_order).fillna(2)
        out = out.sort_values(["_sort", "Priority"]).drop(columns=["_sort"]).reset_index(drop=True)
        out["Priority"] = np.arange(1, len(out) + 1, dtype=int)
    return out


def build_apa_report_sentence_audit(
    result: dict,
    diagnostics: dict,
    bias_results: dict | None = None,
    all_bias_results: dict | None = None,
) -> pd.DataFrame:
    """Sentence-level evidence map for generated APA report prose.

    This table is intentionally conservative: it links report-ready sentence
    drafts to app evidence, method references, and claim boundaries so authors
    can copy only the statements that remain supported after study-specific
    editing.
    """
    if not isinstance(result, dict):
        return pd.DataFrame()
    config = result.get("config", {}) if isinstance(result.get("config", {}), dict) else {}
    prep = result.get("prep", {}) if isinstance(result.get("prep", {}), dict) else {}
    diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
    if (
        not config
        and not prep
        and not any(_nonempty_run_artifact(value) for value in diagnostics.values())
    ):
        return pd.DataFrame()
    all_bias = all_bias_results or {}
    if not all_bias and bias_results:
        all_bias = {f"{bias_results.get('facet_a', 'A')} x {bias_results.get('facet_b', 'B')}": bias_results}

    try:
        claim_evidence = build_claim_to_evidence_matrix(result, diagnostics, all_bias)
    except Exception:
        claim_evidence = pd.DataFrame()
    current_refs = build_current_run_method_reference_audit(result, diagnostics, all_bias)
    method = str(config.get("method", "unknown"))
    model = str(config.get("model", "unknown"))
    rows: list[dict[str, object]] = []

    def claim_row(area: str) -> pd.Series | None:
        return _table_row_by_value(claim_evidence, "ManuscriptArea", area)

    def claim_value(area: str, column: str, default: str = "") -> str:
        row = claim_row(area)
        if row is None:
            return default
        return _handoff_text(row.get(column), default)

    def copy_decision(area: str) -> str:
        claim_status = claim_value(area, "ClaimStatus", "Review")
        gate_status = claim_value(area, "GateStatus", "Ready")
        if claim_status == "Do not claim" or gate_status == "Not ready":
            return "Do not copy without revision and additional evidence."
        if claim_status in {"Report with caveat", "Review", "Boundary"} or gate_status == "Report with caveat":
            return "Copy only with the stated caveat and supporting table."
        return "Copy after study-specific editing and reference-list review."

    def linked_evidence(area: str) -> str:
        bits = [
            claim_value(area, "PrimaryTables", ""),
            claim_value(area, "PrimaryFigures", ""),
        ]
        return "; ".join(bit for bit in bits if bit)

    def add_row(
        section: str,
        role: str,
        area: str,
        draft_sentence: str,
        output_evidence: str,
        before_submission: str,
    ) -> None:
        ref_summary = _method_reference_summary_for_manuscript_area(area, current_refs)
        rows.append({
            "SentenceOrder": len(rows) + 1,
            "APASection": section,
            "SentenceRole": role,
            "LinkedManuscriptArea": area,
            "DraftSentence": draft_sentence,
            "ClaimStatus": claim_value(area, "ClaimStatus", "Review"),
            "GateStatus": claim_value(area, "GateStatus", "Ready"),
            "EvidenceFiles": linked_evidence(area),
            "OutputEvidence": output_evidence,
            "SuggestedCitations": _handoff_text(
                claim_value(area, "SuggestedCitations", ""),
                ref_summary.get("SuggestedCitations", ""),
            ),
            "CitationBoundary": _handoff_text(
                claim_value(area, "CitationBoundary", ""),
                ref_summary.get("CitationBoundary", ""),
            ),
            "DoNotClaim": claim_value(area, "CaveatOrBoundary", "Keep the sentence within the computed evidence."),
            "BeforeSubmissionCheck": before_submission,
            "CopyDecision": copy_decision(area),
            "CitationEvidenceFile": _handoff_text(
                claim_value(area, "CitationEvidenceFile", ""),
                ref_summary.get("CitationEvidenceFile", "method_reference_audit.csv"),
            ),
        })

    n_obs = prep.get("n_obs", "unknown")
    n_person = prep.get("n_person", "unknown")
    facet_names = config.get("facet_names", []) or []
    facet_label = ", ".join(map(str, facet_names)) if facet_names else "not recorded"
    rating_min = prep.get("rating_min", "?")
    rating_max = prep.get("rating_max", "?")
    n_cat = config.get("n_cat", "unknown")
    add_row(
        "Method",
        "Model, sample, and runtime scope",
        "Model and software scope",
        (
            f"A many-facet Rasch-family model ({model}) was estimated using {method} "
            f"with {n_obs} observations from {n_person} persons."
        ),
        f"facets={facet_label}; score support={rating_min} to {rating_max}; categories={n_cat}",
        "Verify the app version, runtime boundary, model, facets, and score support against the exported config.",
    )
    if facet_names:
        add_row(
            "Method",
            "Facet specification",
            "Model and software scope",
            f"The modeled facets were {facet_label}.",
            f"facet_names={facet_label}",
            "Confirm that each facet is substantively meaningful and present in the analysis design.",
        )
    add_row(
        "Method",
        "Estimation and uncertainty basis",
        "MML population scale" if method.upper() == "MML" else "Model and software scope",
        (
            "Reported intervals are conditional approximations and should be read with the exported SE/CI basis metadata."
            if method.upper() != "MML" else
            f"The MML run estimated the person population SD at {config.get('estimated_population_sd', 'not recorded')}; "
            "population-scale and EAP claims reflect the freely estimated metric."
            if config.get("estimate_population_sd") else
            f"The MML run used a fixed population prior SD of {config.get('population_prior_sd', 'not recorded')}; "
            "population-scale and EAP claims are conditional on that setting."
        ),
        "measures.csv SE_Method/SE_Status; statistical_uncertainty_summary.csv; mml_covariance_audit.csv when available",
        "Do not describe conditional or observed-information intervals as fully unconditional uncertainty.",
    )
    if model == "RSM":
        add_row(
            "Method",
            "Rating-scale model citation",
            "Rating-scale functioning",
            "The rating-scale formulation follows the ordered-category RSM specification.",
            "model=RSM; steps/category diagnostics available after estimation",
            "Use this sentence only when the fitted model is RSM and category diagnostics are reported separately.",
        )
    elif model == "PCM":
        add_row(
            "Method",
            "Partial-credit model citation",
            "Rating-scale functioning",
            "The partial-credit formulation allows category thresholds to vary by step structure.",
            "model=PCM; step estimates exported when available",
            "Use this sentence only when the fitted model is PCM.",
        )
    elif model == "GPCM":
        add_row(
            "Method",
            "Generalized partial-credit model citation",
            "Rating-scale functioning",
            "The generalized partial-credit specification is reported with bounded positive slope constraints.",
            f"model=GPCM; step_facet={config.get('step_facet')}; slope_facet={config.get('slope_facet')}",
            "Report the slope constraint and avoid treating slopes as Rasch severity parameters.",
        )

    opt = result.get("opt")
    add_row(
        "Results",
        "Convergence",
        "Convergence and final interpretability",
        (
            "The optimizer reported convergence, so fitted measures can be interpreted with the remaining diagnostics."
            if bool(getattr(opt, "success", False)) else
            "The optimizer did not report convergence; fitted measures should not be treated as final."
        ),
        str(getattr(opt, "message", "optimizer message not available")),
        "Resolve non-convergence before copying substantive measure interpretations.",
    )

    obs = diagnostics.get("obs", pd.DataFrame())
    if isinstance(obs, pd.DataFrame) and "StdResidual" in obs.columns:
        std_res = pd.to_numeric(obs["StdResidual"], errors="coerce").dropna()
        if len(std_res):
            pct_ge2 = float((std_res.abs() >= 2).mean() * 100)
            add_row(
                "Results",
                "Global residual fit",
                "Fit and dimensionality",
                f"Global residual fit showed {pct_ge2:.1f}% of standardized residuals exceeding |2|.",
                f"N residuals={len(std_res)}; % |StdResidual| >= 2 = {pct_ge2:.1f}",
                "Read this with residual PCA/stability evidence before making dimensionality claims.",
            )

    rel = diagnostics.get("reliability", pd.DataFrame())
    if isinstance(rel, pd.DataFrame) and not rel.empty:
        facets = ", ".join(rel.get("Facet", pd.Series(dtype=str)).astype(str).tolist())
        add_row(
            "Results",
            "Reliability and separation",
            "Reliability and separation",
            "Facet reliability and separation were summarized to evaluate distinguishability on the fitted scale.",
            f"reliability rows={len(rel)}; facets={facets}",
            "Interpret rater/facet reliability differently from person reliability; high rater separation may indicate severity differences.",
        )

    measures = diagnostics.get("measures", pd.DataFrame())
    if isinstance(measures, pd.DataFrame) and "Infit" in measures.columns:
        infit = pd.to_numeric(measures["Infit"], errors="coerce").dropna()
        if len(infit):
            n_misfit = int(((infit > 1.5) | (infit < 0.5)).sum())
            add_row(
                "Results",
                "Element fit",
                "Fit and dimensionality",
                f"{n_misfit} of {len(infit)} elements showed Infit MnSq outside the 0.5-1.5 screening range.",
                f"fit rows={len(infit)}; outside screening range={n_misfit}",
                "Treat fit flags as diagnostic prompts; removal or invalidity claims require substantive review.",
            )

    steps = result.get("steps", pd.DataFrame())
    if isinstance(steps, pd.DataFrame) and not steps.empty:
        rating_dashboard = rating_scale_functioning_dashboard(result, diagnostics)
        dashboard_evidence = (
            f"rating-scale dashboard rows={len(rating_dashboard)}"
            if isinstance(rating_dashboard, pd.DataFrame) and not rating_dashboard.empty
            else f"step rows={len(steps)}"
        )
        add_row(
            "Results",
            "Rating-scale functioning",
            "Rating-scale functioning",
            "Rating-scale functioning was evaluated from category counts, average measures, threshold/step ordering, and category-curve peak/dominance diagnostics.",
            dashboard_evidence,
            "Do not claim distinct functioning for sparse, disordered, or curve-dominated categories without addressing the diagnostic rows.",
        )

    pca_available = any(
        _nonempty_run_artifact(diagnostics.get(key))
        for key in ["pca", "pca_enabled", "pca_eigenvalues", "pca_loadings", "pca_stability", "pca_stability_audit"]
    )
    if pca_available:
        add_row(
            "Results",
            "Residual PCA dimensionality screen",
            "Fit and dimensionality",
            "Residual PCA was treated as an exploratory dimensionality screen rather than proof of unidimensionality.",
            "pca_eigenvalues.csv and pca_stability_audit.csv when available",
            "Require stability and substantive construct review before turning PCA evidence into a dimensionality conclusion.",
        )

    if all_bias:
        bias_audit = build_bias_inference_audit(all_bias, result, diagnostics)
        n_pairs = len(bias_audit) if isinstance(bias_audit, pd.DataFrame) else len(all_bias)
        flagged = 0
        if isinstance(bias_audit, pd.DataFrame) and "FlaggedCells" in bias_audit.columns:
            flagged = int(pd.to_numeric(bias_audit["FlaggedCells"], errors="coerce").fillna(0).sum())
        add_row(
            "Results",
            "Bias/local interaction screen",
            "Bias / local interaction",
            "Bias/local interaction results were reported as conditional screening evidence within the computed facet-pair family.",
            f"facet-pair bundles={n_pairs}; flagged cells={flagged}",
            "Limit no-bias wording to screened pairs and cells; do not generalize to sparse, untested, or disconnected cells.",
        )

    posterior = result.get("posterior", {}) if isinstance(result.get("posterior", {}), dict) else {}
    simulation_available = (
        bool(config.get("compute_plausible_values", False))
        or _nonempty_run_artifact(result.get("fitted_predictions"))
        or _nonempty_run_artifact(result.get("refit_simulation"))
        or _nonempty_run_artifact(result.get("simulation"))
        or _nonempty_run_artifact(diagnostics.get("design_evaluation"))
        or _nonempty_run_artifact(posterior.get("plausible_values", pd.DataFrame()))
    )
    if simulation_available:
        add_row(
            "Supplement",
            "Prediction, plausible values, or simulation",
            "Prediction, plausible values, and simulation",
            "Prediction, plausible values, and simulation outputs were treated as model-based sensitivity or planning evidence.",
            f"plausible values requested={bool(config.get('compute_plausible_values', False))}; draws={int(config.get('n_plausible_values') or 0)}",
            "Do not present model-based simulation as prospective validation or causal evidence.",
        )

    out = pd.DataFrame(rows)
    if not out.empty:
        out["SentenceOrder"] = np.arange(1, len(out) + 1, dtype=int)
    return out


def build_manuscript_handoff_checklist(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    public_export_mode: bool = True,
) -> pd.DataFrame:
    """Ordered handoff checklist for moving final app outputs into a manuscript."""
    all_bias = all_bias_results or {}
    gate_status, gate_evidence = _overall_manuscript_gate_status(result, diagnostics, all_bias)
    action_plan = build_submission_action_plan(result, diagnostics, all_bias)
    statuses = (
        action_plan["Status"].astype(str).tolist()
        if isinstance(action_plan, pd.DataFrame) and "Status" in action_plan.columns else []
    )
    blocking_count = sum(status in {"Not ready", "Do not claim"} for status in statuses)
    caveat_count = sum(status in {"Report with caveat", "Review", "Missing"} for status in statuses)
    boundary_count = sum(status == "Boundary" for status in statuses)
    action_status = (
        "Not ready" if blocking_count
        else "Review" if caveat_count
        else "Boundary" if boundary_count
        else "Ready"
    )
    privacy_status = "Ready" if public_export_mode else "Review"
    privacy_action = (
        "Keep public export mode enabled for files that may leave the controlled research workspace."
        if public_export_mode else
        "Complete/private export is selected; share only inside an approved confidential workflow."
    )
    config = result.get("config", {}) if isinstance(result, dict) else {}
    prep = result.get("prep", {}) if isinstance(result, dict) else {}
    opt = result.get("opt") if isinstance(result, dict) else None
    n_obs = prep.get("n_obs", "unknown") if isinstance(prep, dict) else "unknown"
    n_person = prep.get("n_person", "unknown") if isinstance(prep, dict) else "unknown"
    model = config.get("model", "unknown") if isinstance(config, dict) else "unknown"
    method = config.get("method", "unknown") if isinstance(config, dict) else "unknown"
    converged = bool(getattr(opt, "success", False))

    rows = [
        {
            "Step": 1,
            "Phase": "Pre-download review",
            "Status": gate_status,
            "Task": "Confirm the overall manuscript gate before treating conclusions as final.",
            "AppLocation": "Report -> Reports / Downloads -> Data Tables",
            "DownloadFile": "publication_gate_summary.csv",
            "Action": "Use final wording only when the gate is Ready; otherwise follow the gate action.",
            "WhyItMatters": gate_evidence,
        },
        {
            "Step": 2,
            "Phase": "Pre-download review",
            "Status": gate_status,
            "Task": "Open the report-ready decision brief and summary panel before drafting Results text.",
            "AppLocation": "Report -> APA Report / Downloads -> Scripts & Config",
            "DownloadFile": "report_ready_decision_brief.md; report_ready_summary_panel.csv; role_based_action_memos.md; role_based_action_checklist.csv; critical_final_review_panel.csv; critical_final_review.md; status_rationale_drilldown.csv; result_reading_path.csv; operational_decision_board.csv; reporting_action_bridge.csv; reporting_action_bridge.md; apa_results_paragraph_draft.md",
            "Action": "Use the brief, role memos, role checklist, critical final review, audience-specific boards, and reporting action bridge to decide what can be written now, what needs caveats, and what must wait for rerun evidence.",
            "WhyItMatters": "This keeps APA wording, scoring QC, rubric decisions, category decisions, and claim evidence aligned before manuscript drafting.",
        },
        {
            "Step": 3,
            "Phase": "Pre-download review",
            "Status": action_status,
            "Task": "Resolve prioritized blockers, caveats, boundaries, and wording repairs.",
            "AppLocation": "Report -> Reports / Downloads -> Data Tables",
            "DownloadFile": "submission_action_plan.csv",
            "Action": (
                f"Review {blocking_count} blocker(s), {caveat_count} caveat/review row(s), "
                f"and {boundary_count} boundary row(s) before manuscript use."
            ),
            "WhyItMatters": "This prevents generated text from outrunning the computed evidence.",
        },
        {
            "Step": 4,
            "Phase": "Privacy and sharing",
            "Status": privacy_status,
            "Task": "Choose the export privacy mode intentionally.",
            "AppLocation": "Downloads -> Data Tables",
            "DownloadFile": "export_privacy_manifest.csv",
            "Action": privacy_action,
            "WhyItMatters": "Public mode removes likely row-level or person-level tables, but it is not a formal de-identification guarantee.",
        },
        {
            "Step": 5,
            "Phase": "Core result archive",
            "Status": "Ready",
            "Task": "Download the complete table bundle for analysis records.",
            "AppLocation": "Downloads -> Data Tables",
            "DownloadFile": "MFRM_Tables.zip; MFRM_Report.xlsx; MFRM_Report.html",
            "Action": "Archive the exact exported bundle with the manuscript draft.",
            "WhyItMatters": f"This preserves the fitted {model}/{method} run with {n_obs} observations and {n_person} persons.",
        },
        {
            "Step": 6,
            "Phase": "Manuscript draft",
            "Status": gate_status,
            "Task": "Export the publication document and use it as a drafted report, not final prose.",
            "AppLocation": "Report -> Exports -> Publication Document",
            "DownloadFile": "Publication Document (.docx/.pdf/.html)",
            "Action": "Edit all generated text for the study design, rubric, research questions, and journal style.",
            "WhyItMatters": "The app can assemble evidence, but the paper still needs study-specific framing and scholarly judgment.",
        },
        {
            "Step": 7,
            "Phase": "Claim wording",
            "Status": action_status,
            "Task": "Match every Results and Discussion claim to evidence, caveats, and safer wording.",
            "AppLocation": "Report -> Tables & checks / Downloads -> Data Tables",
            "DownloadFile": "claim_to_evidence_matrix.csv; method_reference_audit.csv; manuscript_claim_guide.csv; case_interpretation_guidance.csv",
            "Action": "Use the evidence and reference matrices as the bridge from manuscript claims to exported tables, figures, citations, and reviewer questions.",
            "WhyItMatters": "This keeps reliability, fit, dimensionality, bias, linking, and citation language tied to the evidence actually computed.",
        },
        {
            "Step": 8,
            "Phase": "Methods and reproducibility",
            "Status": "Ready" if converged else "Review",
            "Task": "Save the method appendix, manuscript template, config JSON, and reproduction scripts.",
            "AppLocation": "Downloads -> Scripts & Config",
            "DownloadFile": "mfrm_method_appendix.md; mfrm_manuscript_template.md; mfrm_config.json; mfrm_app_engine_runner.py; requirements.txt",
            "Action": "Use the appendix for methods details and the app-engine runner for exact current-path reproduction.",
            "WhyItMatters": f"Convergence is {'recorded as successful' if converged else 'not recorded as successful'}; reproducibility files document the analysis path.",
        },
        {
            "Step": 9,
            "Phase": "Figures",
            "Status": "Ready",
            "Task": "Download figure assets and inspect readability before placing them in the paper.",
            "AppLocation": "Downloads -> Figures",
            "DownloadFile": "MFRM_Publication_Figures.zip; figure_manifest.csv",
            "Action": "Prefer publication-styled PNG when available; keep HTML files for interactive inspection.",
            "WhyItMatters": "The figure manifest records manuscript use and cautions for each exported figure.",
        },
        {
            "Step": 10,
            "Phase": "External validation",
            "Status": "Boundary",
            "Task": "Separate optional external package validation from the main app findings.",
            "AppLocation": "Downloads -> Scripts & Config",
            "DownloadFile": "MFRM_External_Simulation_Validation_Templates.zip",
            "Action": "Run external validation only as a separate archived artifact when the paper needs that claim.",
            "WhyItMatters": "Do not claim equality with FACETS, TAM, sirt, mirt, or mfrmr without a specific validation artifact.",
        },
        {
            "Step": 11,
            "Phase": "Final archive",
            "Status": "Ready",
            "Task": "Package final evidence for coauthors, reviewers, or OSF-style archiving.",
            "AppLocation": "Downloads -> Scripts & Config",
            "DownloadFile": "MFRM_OSF_Package.zip; mfrm_manuscript_handoff.md",
            "Action": "Archive the OSF package, this handoff, and the exact manuscript version that used the outputs.",
            "WhyItMatters": "A complete archive makes later revisions traceable without reopening the app session.",
        },
    ]
    return pd.DataFrame(rows)


def generate_manuscript_handoff_markdown(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
    *,
    public_export_mode: bool = True,
) -> str:
    """Markdown guide for downloading final results and converting them into a paper."""
    all_bias = all_bias_results or {}
    config = result.get("config", {}) if isinstance(result, dict) else {}
    prep = result.get("prep", {}) if isinstance(result, dict) else {}
    opt = result.get("opt") if isinstance(result, dict) else None
    gate_status, gate_evidence = _overall_manuscript_gate_status(result, diagnostics, all_bias)
    action_plan = build_submission_action_plan(result, diagnostics, all_bias)
    checklist = build_manuscript_handoff_checklist(
        result,
        diagnostics,
        all_bias,
        public_export_mode=public_export_mode,
    )

    top_actions: list[str] = []
    if isinstance(action_plan, pd.DataFrame) and not action_plan.empty:
        plan = action_plan.copy()
        if "Status" in plan.columns:
            plan["_rank"] = plan["Status"].map(_status_rank_for_handoff).fillna(2)
            plan = plan.sort_values(["_rank", "Priority"]).drop(columns=["_rank"])
        for _, row in plan.head(5).iterrows():
            top_actions.append(
                f"- P{row.get('Priority', '?')} - {row.get('Status', 'Review')} - "
                f"{row.get('Topic', 'Reporting item')}: {row.get('ImmediateAction', 'Review before manuscript use.')}"
            )
    if not top_actions:
        top_actions.append("- No prioritized action rows were generated; still perform study-specific editing before submission.")

    open_order = [
        f"{int(row.Step)}. `{row.DownloadFile}` - {row.Task}"
        for row in checklist.itertuples(index=False)
    ]
    facet_names = ", ".join(map(str, config.get("facet_names", []))) if isinstance(config, dict) else ""
    lines = [
        "# MFRM Final Results and Manuscript Handoff",
        "",
        "Use this handoff after the model has been fitted and before copying app-generated text into a manuscript.",
        "",
        "## Analysis Snapshot",
        "",
        f"- App version: {config.get('app_version', APP_VERSION) if isinstance(config, dict) else APP_VERSION}.",
        f"- Model and method: {config.get('model', 'unknown') if isinstance(config, dict) else 'unknown'} / {config.get('method', 'unknown') if isinstance(config, dict) else 'unknown'}.",
        f"- Observations and persons: {prep.get('n_obs', 'unknown') if isinstance(prep, dict) else 'unknown'} observations; {prep.get('n_person', 'unknown') if isinstance(prep, dict) else 'unknown'} persons.",
        f"- Facets: {facet_names or 'not recorded'}.",
        f"- Converged: {bool(getattr(opt, 'success', False))}. Optimizer message: {getattr(opt, 'message', 'not available')}.",
        f"- Overall manuscript gate: {gate_status}. Evidence: {gate_evidence}",
        f"- Export privacy mode: {'public/anonymized bundle mode' if public_export_mode else 'complete/private bundle mode'}.",
        "",
        "## Open In This Order",
        "",
        *open_order,
        "",
        "## Download Package",
        "",
        "- Decision brief and role memos: Report -> APA Report or Downloads -> Scripts & Config; download `report_ready_decision_brief.md`, `report_ready_summary_panel.csv`, `role_based_action_memos.md`, `role_based_action_memos.csv`, `role_based_action_checklist.csv`, `critical_final_review_panel.csv`, `critical_final_review.md`, `status_rationale_drilldown.csv`, `result_reading_path.csv`, `operational_decision_board.csv`, `reporting_action_bridge.csv`, `reporting_action_bridge.md`, and `apa_results_paragraph_draft.md` before writing Results prose.",
        "- Publication Document: Report -> Exports -> Publication Document; download Word, PDF, or HTML for a draft report.",
        "- Tables: Downloads -> Data Tables; download `MFRM_Tables.zip`, `MFRM_Report.xlsx`, and `MFRM_Report.html`.",
        "- Figures: Downloads -> Figures; download `MFRM_Publication_Figures.zip` and `figure_manifest.csv`.",
        "- Claim evidence: Downloads -> Data Tables or Scripts & Config; download `claim_to_evidence_matrix.csv`, `apa_report_sentence_audit.csv`, and `method_reference_audit.csv` before drafting Results and Discussion claims.",
        "- Methods and scripts: Downloads -> Scripts & Config; download `mfrm_config.json`, `mfrm_method_appendix.md`, `mfrm_manuscript_template.md`, `mfrm_app_engine_runner.py`, and `requirements.txt`.",
        "- Archive package: Downloads -> Scripts & Config; download `MFRM_OSF_Package.zip` using the intended privacy mode.",
        "",
        "## Before Manuscript Submission",
        "",
        "- Resolve every `Not ready` or `Do not claim` item before final conclusions.",
        "- Use caveat language for `Report with caveat`, `Review`, or `Missing` items.",
        "- Keep `Boundary` items inside the computed design and diagnostics.",
        "- Confirm that each table and figure cited in the manuscript has a matching exported file.",
        "- Record whether public or private export mode was used for any shared archive.",
        "",
        "## Priority Actions",
        "",
        *top_actions,
        "",
        "## Privacy And Archiving Note",
        "",
        "Public export mode removes likely row-level or person-level tables from the standard bundle and writes `export_privacy_manifest.csv`. It is not a formal de-identification guarantee. For confidential studies, review institutional policy before sharing any exported data, report, figure, or reproduction script.",
        "",
        "Archive the final manuscript version together with `MFRM_OSF_Package.zip`, this handoff, and any external validation artifacts used to support cross-package or cross-run claims.",
    ]
    return "\n".join(lines) + "\n"


def generate_manuscript_binder_readme(
    *,
    public_export_mode: bool = True,
    included_files: Iterable[str] | None = None,
) -> str:
    files = list(included_files or [])
    file_lines = [f"- `{name}`" for name in sorted(files)] or ["- No files were added."]
    lines = [
        "# MFRM Manuscript Binder",
        "",
        "This bundle is a curated writing and review packet. It is smaller than the full OSF package and is intended for manuscript drafting, coauthor review, and reviewer-response planning.",
        "",
        f"- Export privacy mode at creation: {'public/anonymized bundle mode' if public_export_mode else 'complete/private bundle mode'}.",
        "- Public mode is not a formal de-identification guarantee; review shared files before distribution.",
        "",
        "## Suggested Use",
        "",
        "1. Open `manuscript_handoff.md` first.",
        "2. Open `report_ready_decision_brief.md` and `report_ready_summary_panel.csv` before writing Results text.",
        "3. Open `critical_final_review.md` or `critical_final_review_panel.csv` before treating any generated wording as final.",
        "4. Use `status_rationale_drilldown.csv`, `result_reading_path.csv`, and `operational_decision_board.csv` to translate the same evidence for psychometric review, MFRM reading, and test-development decisions.",
        "5. Use `reporting_action_bridge.md` or `reporting_action_bridge.csv` to turn review rows into APA wording, scoring-action, rubric-decision, category-sensitivity, and archive tasks.",
        "6. Open `role_based_action_memos.md` or `role_based_action_memos.csv` and start with the section for your role.",
        "7. Use `role_based_action_checklist.md` or `role_based_action_checklist.csv` to track which review tasks are complete.",
        "8. Use `report_ready_reanalysis_checklist.md` or `report_ready_reanalysis_checklist.csv` before treating generated data, reruns, sensitivity checks, or final exports as report-ready evidence.",
        "9. Use `apa_results_paragraph_draft.md` only with the caveats and blocked-sentence list it carries.",
        "10. Use `claim_to_evidence_matrix.csv` to map each manuscript claim to tables, figures, diagnostics, caveats, and reviewer questions.",
        "11. Use `apa_report_sentence_audit.csv` to check each generated APA sentence against evidence files, citations, and wording boundaries.",
        "12. Use `visual_claim_guardrails.csv` before copying interpretation from Wright Maps, yardsticks, thresholds, or category curves.",
        "13. If generated custom simulation data were used, open `custom_simulation_settings.csv`, `custom_simulation_sparse_reporting_context.csv`, `custom_simulation_sparse_design_audit.csv`, and `custom_simulation_sparse_pair_cells.csv` before treating the APA draft as report-ready.",
        "14. Use `method_reference_audit.csv` to check which methodological references support each analysis surface.",
        "15. If Stan posterior results are used, open `stan_posterior_reproducibility_handoff.md` and `stan_reproducibility_archive_contract.csv` before citing posterior intervals.",
        "16. Use `submission_action_plan.csv` to resolve blockers and caveats before copying generated prose.",
        "17. Use `method_appendix.md` and `manuscript_template.md` as draft scaffolds, not final manuscript text.",
        "18. Keep the full `MFRM_OSF_Package.zip` or table bundle with this binder when archiving.",
        "",
        "## Included Files",
        "",
        *file_lines,
    ]
    return "\n".join(lines) + "\n"


def build_manuscript_binder_assets(
    frames: dict[str, pd.DataFrame],
    text_assets: dict[str, str] | None = None,
    *,
    figure_manifest: pd.DataFrame | None = None,
    visual_evidence_map: pd.DataFrame | None = None,
    public_export_mode: bool = True,
) -> dict[str, bytes | str]:
    """Create a curated manuscript-writing bundle from current export assets."""
    assets: dict[str, bytes | str] = {}
    assets["visualization_settings.json"] = _visualization_preferences_json()
    assets["visualization_settings.csv"] = to_csv_bytes(build_visualization_preferences_table())
    for name, text in (text_assets or {}).items():
        if name in {
            "manuscript_handoff.md",
            "report_ready_decision_brief.md",
            "apa_results_paragraph_draft.md",
            "role_based_action_memos.md",
            "role_based_action_checklist.md",
            "report_ready_reanalysis_checklist.md",
            "critical_final_review.md",
            "reporting_action_bridge.md",
            "method_appendix.md",
            "manuscript_template.md",
            "local_batch_workflow.md",
            "mfrm_config.json",
            "README_bayesian_mfrm_stan_runners.md",
            "stan_posterior_reproducibility_handoff.md",
        }:
            assets[str(name)] = str(text)
    selected_frames = [
        "report_ready_summary_panel",
        "role_based_action_memos",
        "role_based_action_checklist",
        "report_ready_reanalysis_checklist",
        "critical_final_review_panel",
        "status_rationale_drilldown",
        "result_reading_path",
        "operational_decision_board",
        "reporting_action_bridge",
        "manuscript_handoff_checklist",
        "claim_to_evidence_matrix",
        "apa_report_sentence_audit",
        "method_reference_audit",
        "publication_gate_summary",
        "submission_action_plan",
        "case_interpretation_guidance",
        "final_report_readiness",
        "manuscript_claim_guide",
        "visual_interpretation_checklist",
        "visual_claim_guardrails",
        "visual_method_evidence",
        "custom_simulation_settings",
        "custom_simulation_sparse_reporting_context",
        "custom_simulation_sparse_design_audit",
        "custom_simulation_sparse_pair_cells",
        "export_privacy_manifest",
        "summary",
        "convergence",
        "reliability",
        "fit_statistics",
        "category_probability_curves",
        "bayesian_mfrm_stan_refinement_plan",
        "stan_reproducibility_archive_contract",
        "stan_posterior_reproducibility_route",
        "stan_posterior_handoff_checklist",
        "stan_run_manifest_template",
        "mfrm_stan_prior_guidance",
        "mfrm_stan_prior_sensitivity_grid",
    ]
    for frame_name in selected_frames:
        frame = (frames or {}).get(frame_name)
        if isinstance(frame, pd.DataFrame) and not frame.empty:
            assets[f"{frame_name}.csv"] = to_csv_bytes(frame)
    if isinstance(figure_manifest, pd.DataFrame) and not figure_manifest.empty:
        assets["figure_manifest.csv"] = to_csv_bytes(figure_manifest)
    if isinstance(visual_evidence_map, pd.DataFrame) and not visual_evidence_map.empty:
        assets["visual_evidence_map.csv"] = to_csv_bytes(visual_evidence_map)
        visual_qa = build_visual_qa_preflight(figure_manifest, visual_evidence_map)
        if isinstance(visual_qa, pd.DataFrame) and not visual_qa.empty:
            assets["visual_qa_preflight.csv"] = to_csv_bytes(visual_qa)
    readme = generate_manuscript_binder_readme(
        public_export_mode=public_export_mode,
        included_files=assets.keys(),
    )
    return {"README_first.md": readme, **assets}


def generate_manuscript_reporting_template(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> str:
    """Result-aware manuscript skeleton for guided reporting."""
    config = result.get("config", {})
    prep = result.get("prep", {})
    opt = result.get("opt")
    all_bias = all_bias_results or {}
    guide = build_manuscript_claim_guide(result, diagnostics, all_bias)
    readiness = build_final_report_readiness(result, diagnostics, all_bias)
    case_guidance = build_case_interpretation_guidance(result, diagnostics, all_bias)

    def guide_value(area: str, column: str, default: str = "No result-specific guidance recorded.") -> str:
        if not isinstance(guide, pd.DataFrame) or guide.empty:
            return default
        if "ManuscriptArea" not in guide.columns or column not in guide.columns:
            return default
        hit = guide.loc[guide["ManuscriptArea"].astype(str) == area, column]
        return str(hit.iloc[0]) if not hit.empty else default

    def readiness_value(check: str, column: str, default: str = "No result-specific evidence recorded.") -> str:
        if not isinstance(readiness, pd.DataFrame) or readiness.empty:
            return default
        if "Check" not in readiness.columns or column not in readiness.columns:
            return default
        hit = readiness.loc[readiness["Check"].astype(str) == check, column]
        return str(hit.iloc[0]) if not hit.empty else default

    def status(area: str) -> str:
        return guide_value(area, "ClaimStatus", "Missing")

    def wording(area: str) -> str:
        return guide_value(area, "SafeManuscriptWording")

    def evidence(area: str) -> str:
        return guide_value(area, "EvidenceToReport")

    def action(area: str) -> str:
        return guide_value(area, "NextAction")

    def do_not(area: str) -> str:
        return guide_value(area, "DoNotClaim")

    def fmt_list(values: Iterable[object], default: str = "not recorded") -> str:
        clean = [str(v) for v in values if str(v)]
        return ", ".join(clean) if clean else default

    facet_names = fmt_list(config.get("facet_names", []) or [], "not recorded")
    model = str(config.get("model", "unknown"))
    method = str(config.get("method", "unknown"))
    rating_min = prep.get("rating_min", "?")
    rating_max = prep.get("rating_max", "?")
    n_obs = prep.get("n_obs", "unknown")
    n_person = prep.get("n_person", "unknown")
    n_cat = config.get("n_cat", "unknown")
    try:
        n_cat_int = int(n_cat)
    except Exception:
        n_cat_int = None
    cat_label = "category" if n_cat_int == 1 else "categories"
    raw_unused_categories = prep.get("unused_score_categories", [])
    if isinstance(raw_unused_categories, (list, tuple, set, np.ndarray, pd.Series)):
        unused_categories = list(raw_unused_categories)
    elif raw_unused_categories is None or str(raw_unused_categories) == "":
        unused_categories = []
    else:
        unused_categories = [raw_unused_categories]
    unused_label = (
        "none"
        if not unused_categories else
        ", ".join(map(str, unused_categories))
    )
    score_support = (
        f"{rating_min} to {rating_max}; {n_cat} {cat_label}; "
        f"unused categories retained: {unused_label}"
    )
    if bool(prep.get("score_range_explicit", False)):
        score_support += "; explicit score range was supplied"

    pca_status = readiness_value("Dimensionality screen", "Status", "Review")
    bias_status = status("Bias / local interaction")
    anchor_status = status("Anchoring and linking")
    uncertainty = diagnostics.get("uncertainty", {}) if isinstance(diagnostics, dict) else {}
    unc_summary = uncertainty.get("summary", pd.DataFrame()) if isinstance(uncertainty, dict) else pd.DataFrame()
    if isinstance(unc_summary, pd.DataFrame) and not unc_summary.empty:
        uncertainty_status = "; ".join(
            f"{row.get('Status')}: {row.get('Rows')} row(s)" for _, row in unc_summary.iterrows()
            if str(row.get("Area", "")).startswith("Measure")
        ) or "not summarized"
    else:
        uncertainty_status = "not summarized"
    caution_rows = []
    if isinstance(guide, pd.DataFrame) and not guide.empty:
        for _, row in guide.iterrows():
            row_status = str(row.get("ClaimStatus", ""))
            if row_status in {"Report with caveat", "Do not claim", "Boundary"}:
                caution_rows.append(
                    f"- **{row.get('ManuscriptArea', 'Unknown area')}** ({row_status}): "
                    f"{row.get('DoNotClaim', 'No boundary recorded')} "
                    f"Next action: {row.get('NextAction', 'No action recorded')}"
                )
    if not caution_rows:
        caution_rows.append("- No caution rows were generated by the claim guide. Still review all diagnostics before submission.")
    wording_rows: list[str] = []
    if isinstance(case_guidance, pd.DataFrame) and not case_guidance.empty:
        case_flags = case_guidance.loc[
            case_guidance["Status"].astype(str) != "Ready"
        ] if "Status" in case_guidance.columns else case_guidance
        for _, row in case_flags.iterrows():
            wording_rows.extend([
                f"- **{row.get('Case', 'Unknown case')}** ({row.get('Status', 'Review')}):",
                f"  - Avoid: {row.get('AvoidWording', 'No avoid wording recorded.')}",
                f"  - Safer: {row.get('SaferWording', 'No safer wording recorded.')}",
                f"  - Evidence: {row.get('Evidence', 'No evidence recorded.')}",
                f"  - Next action: {row.get('NextAction', 'No action recorded.')}",
            ])
    if not wording_rows:
        wording_rows.append("- No case-specific wording repair was generated. Still edit the template for the study context before submission.")
    method_reference_rows = _method_reference_claim_boundary_lines(result, diagnostics, all_bias)

    suggested_results = [
        "Rating-scale functioning",
        "MML population scale",
        "Reliability and separation",
        "Fit and dimensionality",
        "Wright map targeting and measure interpretation",
        "Bias / local interaction",
        "Anchoring and linking",
        "Prediction, plausible values, and simulation",
    ]
    result_blocks: list[str] = []
    for area in suggested_results:
        result_blocks.extend([
            f"### {area}",
            "",
            f"- Claim status: {status(area)}.",
            f"- Evidence to report: {evidence(area)}",
            f"- Draft wording: {wording(area)}",
            f"- Guardrail: {do_not(area)}",
            f"- Before submission: {action(area)}",
            "",
        ])

    converged = bool(getattr(opt, "success", False))
    lines = [
        "# MFRM Manuscript Reporting Template",
        "",
        "Use this as a draft scaffold, not as final prose. Replace bracketed text with study-specific content, and resolve every `Do not claim` row before submission.",
        "",
        "## Study-Specific Placeholders",
        "",
        "- Construct or rubric: [write construct/rubric name].",
        "- Research question: [write research question].",
        "- Sample and setting: [write participants, raters, tasks, and context].",
        "- Rating rubric: [write score categories and anchor descriptions].",
        "- Missing-data rule: [write how missing or omitted ratings were handled].",
        "",
        "## Methods Draft",
        "",
        (
            f"We analyzed [construct/rubric] ratings with a many-facet Rasch model in the standalone "
            f"Python MFRM Streamlit app (version {config.get('app_version', APP_VERSION)}). "
            f"The fitted model was {model} using {method}. The analysis included {n_obs} observations "
            f"from {n_person} persons, facets ({facet_names}), and score support {score_support}."
        ),
        "",
        (
            "The app did not call `mfrmr`, `rpy2`, `Rscript`, FACETS, TAM, sirt, or mirt at runtime. "
            "External package equality should not be reported unless a separate validation artifact is archived."
        ),
        "",
        "Report estimation settings here: optimizer/engine, maximum iterations, convergence tolerance, quadrature points for MML, latent-regression formula if used, anchor policy if used, and whether optional PCA, strict marginal diagnostics, bias screening, plausible values, prediction, simulation, or design evaluation were enabled.",
        "",
        "## Method References And Claim Boundaries",
        "",
        "Use this section to keep method citations aligned with the analyses actually computed in this run. The downloadable `method_reference_audit.csv` is the canonical table; these bullets are a run-specific subset for drafting.",
        "",
        *method_reference_rows,
        "",
        "## Results Draft",
        "",
        f"Convergence status: {'converged' if converged else 'not converged'}. Optimizer message: {getattr(opt, 'message', 'not available')}.",
        "",
        *result_blocks,
        "## Tables And Figures To Include",
        "",
        "- Table 1: analysis design, facets, observations, score range, retained zero-count categories, and missing-data handling.",
        "- Table 2: person and facet measures with standard errors and fit statistics.",
        "- Table 3: category counts, average measures, and step/threshold ordering.",
        "- Table 4: reliability/separation and final-report readiness or manuscript claim guide summary.",
        "- Figure 1: Wright map for targeting and scale overlap.",
        "- Figure 2: category probability and expected-score curves for PCM/GPCM rating-scale interpretation.",
        "- Figure 3: residual, PCA, marginal, or bias plots only when the corresponding option was computed and labels remain readable.",
        "- Do not include an R-vs-Python comparison table unless the paper is explicitly a validation study.",
        "",
        "## Limitations Draft",
        "",
        "- This report is based on a standalone Python implementation and should be cited as such.",
        f"- Measure SE/CI basis: {uncertainty_status}. Report SE_Method and SE_Status from the exported measure table.",
        f"- MML population scale status: {status('MML population scale')}. Do not imply that the latent variance was freely estimated by this app.",
        f"- Residual PCA status: {pca_status}. Do not claim unidimensionality if this remains Review or Missing.",
        f"- Bias/local interaction status: {bias_status}. Limit no-bias statements to screened facet pairs and cells.",
        f"- Anchor/linking status: {anchor_status}. Do not compare administrations, forms, cohorts, or studies on a common scale without anchor/linking evidence.",
        "- Prediction, plausible-value, simulation, and design-evaluation outputs are model-based sensitivity or planning tools, not causal or prospective validation evidence.",
        "- Fingerprints support reproducibility checks, but they are not encryption and are not a privacy guarantee.",
        "",
        "## Claims Requiring Caution",
        "",
        *caution_rows,
        "",
        "## Result-Specific Wording Repairs",
        "",
        *wording_rows,
        "",
        "## Reviewer Preflight Checklist",
        "",
        "- The optimizer converged or non-convergence is explicitly handled.",
        "- Sparse or zero-count categories are reported and category collapse decisions are justified.",
        "- Reliability/separation claims match the facet being interpreted.",
        "- Fit, dimensionality, and bias/local-interaction language matches the computed diagnostics.",
        "- Each method citation and statistical claim has a matching row in `method_reference_audit.csv` or `claim_to_evidence_matrix.csv`.",
        "- Figures use readable labels; dense labels are shortened or inspected via interactive hover/downloads.",
        "- Cross-run linking claims are supported by anchor audit, drift, and chain evidence.",
        "- The data privacy warning is followed before sharing any real dataset or report bundle.",
    ]
    return "\n".join(lines) + "\n"


def generate_method_appendix_text(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> str:
    """Compact method appendix for reproducible reporting."""
    config = result.get("config", {})
    prep = result.get("prep", {})
    opt = result.get("opt")
    lines = [
        "# MFRM Method Appendix",
        "",
        "## Analysis Scope",
        "",
        "- Software: standalone Python Streamlit app; no `mfrmr`, `rpy2`, `Rscript`, or external MFRM engine is called.",
        f"- Release label: {config.get('release_label', APP_RELEASE_LABEL)}; app version: {config.get('app_version', APP_VERSION)}.",
        "- Validation stance: functional parity target; exact numerical equality with FACETS/TAM/sirt/mirt/mfrmr is not claimed unless a specific external cross-check is reported.",
        f"- Run fingerprint: {config.get('run_fingerprint', config.get('analysis_config_fingerprint', 'not recorded'))}.",
        f"- Model: {config.get('model', 'unknown')}.",
        f"- Estimation method: {config.get('method', 'unknown')}.",
        f"- Optimizer / engine: {config.get('optimizer', config.get('mml_engine', 'unknown'))}.",
        "- Method reference audit: `method_reference_audit.csv` maps model, estimation, fit, dimensionality, bias, simulation, and external-validation claims to APA-library references confirmed from the Zotero/BibTeX audit.",
        f"- Observations: {prep.get('n_obs', 'unknown')}; persons: {prep.get('n_person', 'unknown')}; categories: {config.get('n_cat', 'unknown')} ({prep.get('rating_min', '?')} to {prep.get('rating_max', '?')}).",
        f"- Facets: {', '.join(map(str, config.get('facet_names', []))) or 'none recorded'}.",
        "",
        "## Score Support",
        "",
        f"- Keep original category values: {bool(prep.get('keep_original', False))}.",
        f"- Explicit score range supplied: {bool(prep.get('score_range_explicit', False))}.",
        f"- Retained zero-count categories: {prep.get('unused_score_categories', [])}.",
    ]
    if config.get("model") == "GPCM":
        lines.extend([
            "",
            "## GPCM Scope",
            "",
            f"- Bounded GPCM path: `slope_facet = step_facet = {config.get('step_facet')}`.",
            "- Slope parameters are positive and identified by fixing the geometric mean slope to 1.",
            "- Slopes describe category-transition steepness and should not be interpreted as Rasch severity parameters.",
        ])
    pop = config.get("population_model", {})
    if isinstance(pop, dict) and pop.get("enabled"):
        type_summary = pop.get("type_summary", pd.DataFrame())
        if isinstance(type_summary, pd.DataFrame) and not type_summary.empty and "ReviewFlag" in type_summary.columns:
            review_terms = type_summary.loc[
                type_summary["ReviewFlag"].astype(bool), "Term"
            ].astype(str).tolist()
        else:
            review_terms = []
        lines.extend([
            "",
            "## Latent Regression / Population Model",
            "",
            f"- `population_formula`: `{config.get('population_formula', '')}`.",
            "- MML quadrature is shifted by the fitted person-level population mean X beta.",
            f"- Numeric covariates standardized before fitting: {bool(pop.get('standardize_numeric', False))}.",
            f"- Covariate type overrides: categorical={pop.get('categorical_terms', [])}; numeric={pop.get('numeric_terms', [])}.",
            f"- Covariate type review flags: {review_terms or 'none'}.",
            (
                f"- Estimated population SD: {float(config.get('estimated_population_sd') or 0.0):.3f} (free, EM); EM starting value {float(config.get('population_prior_sd_input') or 1.0):.3f}."
                if config.get("estimate_population_sd") else
                f"- Fixed population prior SD: {float(config.get('population_prior_sd') or 1.0):.3f}; the variance is not estimated."
            ),
        ])
    if config.get("method") == "MML":
        prior_plan = build_mml_prior_sensitivity_plan(result)
        covariance = diagnostics.get("uncertainty", {}).get("covariance", {}) if isinstance(diagnostics.get("uncertainty", {}), dict) else {}
        lines.extend([
            "",
            "## MML Diagnostics",
            "",
            f"- Requested MML engine: {config.get('mml_engine_requested', config.get('ui_mml_engine', 'unknown'))}.",
            f"- Resolved MML engine: {config.get('mml_engine', 'unknown')}.",
            f"- Quadrature points: {config.get('quad_points', 'unknown')}.",
            f"- Population prior SD: {config.get('population_prior_sd', 'unknown')}.",
            (
                f"- Population prior SD treatment: freely estimated by EM (profile SE {config.get('population_sd_se', 'not computed')}); EM starting value {config.get('population_prior_sd_input', 'unknown')}."
                if config.get("estimate_population_sd") else
                "- Population prior SD treatment: fixed user-set scale; the latent variance is not estimated as a free parameter."
            ),
            f"- Recommended prior-SD sensitivity values: {prior_plan['PopulationPriorSD'].round(4).tolist() if isinstance(prior_plan, pd.DataFrame) and not prior_plan.empty else 'not generated'}.",
            f"- MML structural covariance status for measure SEs: {covariance.get('status', 'not recorded')}; {covariance.get('detail', '')}",
            f"- Posterior scoring available: {result.get('posterior', {}).get('available') if isinstance(result.get('posterior'), dict) else False}.",
            f"- Plausible values requested: {bool(config.get('compute_plausible_values', False))}; draws: {int(config.get('n_plausible_values') or 0)}.",
            f"- Strict marginal diagnostics enabled: {bool(diagnostics.get('marginal_fit_enabled', False))}.",
        ])
    regularization = result.get("regularization", {})
    reg_penalty = regularization.get("penalty_summary", pd.DataFrame()) if isinstance(regularization, dict) else pd.DataFrame()
    reg_audit = regularization.get("audit", pd.DataFrame()) if isinstance(regularization, dict) else pd.DataFrame()
    if bool(config.get("facet_regularization_enabled", False)) or (
        isinstance(reg_audit, pd.DataFrame) and not reg_audit.empty
    ):
        applied_levels = 0
        if isinstance(reg_penalty, pd.DataFrame) and not reg_penalty.empty and "PenalizedLevels" in reg_penalty.columns:
            total_row = reg_penalty.loc[reg_penalty["Facet"].astype(str) == "TOTAL"]
            source = total_row if not total_row.empty else reg_penalty
            applied_levels = int(pd.to_numeric(source["PenalizedLevels"], errors="coerce").fillna(0).max())
        lines.extend([
            "",
            "## Facet Regularization",
            "",
            f"- Enabled: {bool(config.get('facet_regularization_enabled', False))}.",
            f"- UI mode: {config.get('facet_regularization_ui_mode', 'not recorded')}.",
            f"- Objective mode: {config.get('facet_regularization_objective_mode', config.get('facet_regularization_mode', 'not recorded'))}.",
            f"- Scope: {config.get('facet_regularization_scope', 'not recorded')}.",
            f"- Penalized free facet levels: {applied_levels}.",
            f"- Penalty value at estimates: {float(getattr(opt, 'penalty_value', np.nan)) if opt is not None and np.isfinite(getattr(opt, 'penalty_value', np.nan)) else 'not recorded'}.",
            "- Interpretation: this is penalized fixed-effect estimation for selected non-person facet main effects; it is not a random-effects model and not full Bayesian posterior sampling.",
            "- Likelihood note: reported LogLik, deviance, AIC, and BIC use the unpenalized likelihood evaluated at the fitted estimates; PenalizedObjective is shown separately.",
        ])
    shrinkage = diagnostics.get("eb_shrinkage", {}) if isinstance(diagnostics, dict) else {}
    if bool(diagnostics.get("eb_shrinkage_enabled", False)) or (
        isinstance(shrinkage, dict) and shrinkage.get("available")
    ):
        report = shrinkage.get("report", pd.DataFrame()) if isinstance(shrinkage, dict) else pd.DataFrame()
        mean_shrink = np.nan
        if isinstance(report, pd.DataFrame) and not report.empty and "MeanShrinkageFactor" in report.columns:
            vals = pd.to_numeric(report["MeanShrinkageFactor"], errors="coerce").dropna()
            if len(vals):
                mean_shrink = float(vals.mean())
        lines.extend([
            "",
            "## Empirical-Bayes Facet Shrinkage Advisory",
            "",
            f"- Enabled: {bool(diagnostics.get('eb_shrinkage_enabled', False))}.",
            f"- Available: {bool(isinstance(shrinkage, dict) and shrinkage.get('available', False))}.",
            f"- Mean shrinkage factor across reported facets: {mean_shrink:.3f}" if np.isfinite(mean_shrink) else "- Mean shrinkage factor: not available.",
            "- Interpretation: shrinkage estimates are post-hoc reporting diagnostics for non-person facet measures; raw fitted estimates, fit statistics, LogLik, AIC, and BIC are unchanged.",
            "- Mathematical note: posterior SE treats the empirical prior variance as known, so small-facet uncertainty can be understated.",
        ])
    script_support = build_script_support_status(result)
    lines.extend([
        "",
        "## Reproducibility Scripts",
        "",
        "- Python app-engine runner: exact current app path.",
        f"- Portable self-contained JMLE/R available for this run: {bool(script_support.get('portable_available', False))}.",
    ])
    if script_support.get("portable_blockers"):
        lines.append(
            "- Portable script blocker(s): "
            + ", ".join(map(str, script_support.get("portable_blockers", [])))
            + ". Use the app-engine runner instead."
        )
    anchor = config.get("anchor_audit", {})
    if isinstance(anchor, dict):
        lines.extend([
            "",
            "## Anchor / Linking Review",
            "",
            f"- Anchor audit status: {anchor.get('overall_status', 'unknown')}.",
            f"- Anchor audit message: {anchor.get('message', 'not available')}",
        ])
        drift = result.get("anchor_drift", {})
        if isinstance(drift, dict) and drift.get("available"):
            lines.append("- Anchor drift scope: post-fit hard-constraint consistency check; empirical unconstrained drift is not estimated.")
        chain = result.get("equating_chain", {})
        if isinstance(chain, dict) and chain.get("available"):
            edges = chain.get("edges", pd.DataFrame())
            n_edges = len(edges) if isinstance(edges, pd.DataFrame) else 0
            lines.append(f"- Equating-chain summary: {n_edges} current-run anchor-chain edge(s); full historical multi-run chain reconstruction is not included.")
        workflow_plan = result.get("anchor_equating_workflow", pd.DataFrame())
        if isinstance(workflow_plan, pd.DataFrame) and not workflow_plan.empty:
            review_steps = int(workflow_plan["Status"].astype(str).isin(["Review", "Missing"]).sum())
            lines.append(f"- Anchor/equating workflow checklist rows: {len(workflow_plan)}; review/missing rows: {review_steps}.")
    all_bias = all_bias_results or {}
    dff_tables = []
    for bundle in all_bias.values():
        dff_tbl = build_dff_bias_screening_table(bundle)
        if isinstance(dff_tbl, pd.DataFrame) and not dff_tbl.empty:
            dff_tables.append(dff_tbl)
    dff_flag_count = int(sum(tbl["Flag"].astype(bool).sum() for tbl in dff_tables)) if dff_tables else 0
    lines.extend([
        "",
        "## Optional Screens",
        "",
        f"- Residual PCA enabled: {bool(diagnostics.get('pca_enabled', False))}.",
        f"- Bias/interaction pair outputs: {len(all_bias)}.",
        f"- DFF/bias screening flags: {dff_flag_count}. Holm and BH adjusted p-values plus sparse-cell and practical-logit flags are review prompts, not proof of bias.",
        f"- EB shrinkage advisory enabled: {bool(diagnostics.get('eb_shrinkage_enabled', False))}.",
        "- Prediction scope: fitted design rows plus supplied new/held-out rows. For supplied rows, known persons use fitted measures; unknown persons require MML and are integrated over the fitted population distribution.",
        "- Simulation scope: optional fixed-parameter row-probability simulation; not a full refit simulation.",
        "- Refit simulation scope: optional small replicate stress test with random row-level missingness and model refitting; not a formal power study.",
        "- Design evaluation scope: observed design balance and reliability forecast; not a prospective guarantee.",
        "",
        "## Convergence",
        "",
        f"- Converged: {bool(getattr(opt, 'success', False))}.",
        f"- Message: {getattr(opt, 'message', 'not available')}.",
        f"- Gradient norm: {getattr(opt, 'gradient_norm', 'not available')}.",
    ])
    return "\n".join(lines) + "\n"


def _render_final_readiness_section(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> None:
    st.subheader("Final Report Readiness")
    st.caption(
        "A compact gate check before writing final conclusions. "
        "`Review` does not always mean the model is unusable, but it must be inspected or justified."
    )
    report_ready_summary = build_report_ready_summary_panel(result, diagnostics, all_bias_results)
    if isinstance(report_ready_summary, pd.DataFrame) and not report_ready_summary.empty:
        st.markdown(f"**{t('guided.report_ready_summary_heading')}**")
        st.caption(t("guided.report_ready_summary_caption"))
        _render_compact_dataframe(
            report_ready_summary,
            [
                "Priority",
                "ReportArea",
                "ReportStatus",
                "PrimaryUsers",
                "UseNow",
                "OpenFirst",
                "ActionBeforeWriting",
            ],
            details_label=t("guided.report_ready_summary_details_label"),
            hide_index=True,
            wrap_text=True,
        )
        st.download_button(
            t("guided.report_ready_summary_download"),
            data=to_csv_bytes(report_ready_summary),
            file_name="report_ready_summary_panel.csv",
            mime="text/csv",
            key="dl_final_report_ready_summary_panel",
        )
    readiness = build_final_report_readiness(result, diagnostics, all_bias_results)
    if readiness.empty:
        st.info("No readiness checks were generated.")
        return
    status_counts = readiness["Status"].value_counts().to_dict()
    cols = st.columns(3)
    cols[0].metric("Ready", int(status_counts.get("Ready", 0)))
    cols[1].metric("Review", int(status_counts.get("Review", 0)))
    cols[2].metric("Missing", int(status_counts.get("Missing", 0)))
    if int(status_counts.get("Review", 0)) or int(status_counts.get("Missing", 0)):
        st.warning("Resolve or explicitly justify rows marked Review/Missing before final reporting.")
    else:
        st.success("No required readiness issues were detected.")
    st.dataframe(readiness, width="stretch", hide_index=True)
    st.download_button(
        "Download readiness checklist (CSV)",
        data=to_csv_bytes(readiness),
        file_name="mfrm_final_report_readiness.csv",
        mime="text/csv",
        key="dl_final_readiness_report_tab",
    )


