def _render_manuscript_claim_guide_section(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> None:
    st.subheader("Submission Action Plan")
    st.caption(
        "A prioritized first-read list for manuscript blockers, caveats, boundaries, "
        "and wording repairs."
    )
    action_plan = build_submission_action_plan(result, diagnostics, all_bias_results)
    if isinstance(action_plan, pd.DataFrame) and not action_plan.empty:
        action_counts = action_plan["Status"].value_counts().to_dict() if "Status" in action_plan.columns else {}
        action_cols = st.columns(4)
        action_cols[0].metric("Not ready / Do not claim", int(action_counts.get("Not ready", 0)) + int(action_counts.get("Do not claim", 0)))
        action_cols[1].metric("Caveat / Review", int(action_counts.get("Report with caveat", 0)) + int(action_counts.get("Review", 0)) + int(action_counts.get("Missing", 0)))
        action_cols[2].metric("Boundary", int(action_counts.get("Boundary", 0)))
        action_cols[3].metric("Ready", int(action_counts.get("Ready", 0)))
        if int(action_counts.get("Not ready", 0)) or int(action_counts.get("Do not claim", 0)):
            st.error("Resolve the highest-priority blocker rows before writing final conclusions.")
        elif int(action_counts.get("Report with caveat", 0)) or int(action_counts.get("Review", 0)) or int(action_counts.get("Missing", 0)):
            st.warning("Use caveat language for the rows marked Caveat, Review, or Missing.")
        _render_compact_dataframe(
            action_plan,
            ["Priority", "Status", "Topic", "ImmediateAction"],
            details_label="Show full submission action plan",
            hide_index=True,
            wrap_text=True,
        )
        st.download_button(
            "Download submission action plan (CSV)",
            data=to_csv_bytes(action_plan),
            file_name="mfrm_submission_action_plan.csv",
            mime="text/csv",
            key="dl_submission_action_plan_report_tab",
        )

    st.subheader("Manuscript Claim Guide")
    st.caption(
        "A guided bridge from diagnostics to publishable claims. "
        "Use this before copying APA text into a manuscript."
    )
    guide = build_manuscript_claim_guide(result, diagnostics, all_bias_results)
    if guide.empty:
        st.info("No manuscript claim guidance was generated.")
        return
    status_counts = guide["ClaimStatus"].value_counts().to_dict()
    cols = st.columns(4)
    cols[0].metric("Ready", int(status_counts.get("Ready", 0)))
    cols[1].metric("Report with caveat", int(status_counts.get("Report with caveat", 0)))
    cols[2].metric("Do not claim", int(status_counts.get("Do not claim", 0)))
    cols[3].metric("Boundary", int(status_counts.get("Boundary", 0)))
    if int(status_counts.get("Do not claim", 0)):
        st.warning("Do not make rows marked 'Do not claim' until the listed action is complete.")
    _render_compact_dataframe(
        guide,
        ["ManuscriptArea", "ClaimStatus", "NextAction"],
        details_label="Show full manuscript claim guide",
        hide_index=True,
        wrap_text=True,
    )
    st.download_button(
        "Download manuscript claim guide (CSV)",
        data=to_csv_bytes(guide),
        file_name="mfrm_manuscript_claim_guide.csv",
        mime="text/csv",
        key="dl_manuscript_claim_guide_report_tab",
    )
    case_guide = build_case_interpretation_guidance(result, diagnostics, all_bias_results)
    if isinstance(case_guide, pd.DataFrame) and not case_guide.empty:
        st.subheader("Case-Specific Interpretation Guide")
        st.caption(
            "Common interpretation traps detected from this run. "
            "Use this as a first-pass editing checklist for manuscript wording."
        )
        case_counts = case_guide["Status"].value_counts().to_dict() if "Status" in case_guide.columns else {}
        case_cols = st.columns(4)
        case_cols[0].metric("Not ready", int(case_counts.get("Not ready", 0)))
        case_cols[1].metric("Caveat", int(case_counts.get("Report with caveat", 0)))
        case_cols[2].metric("Boundary", int(case_counts.get("Boundary", 0)))
        case_cols[3].metric("Ready", int(case_counts.get("Ready", 0)))
        _render_compact_dataframe(
            case_guide,
            ["Priority", "Case", "Status", "NextAction"],
            details_label="Show full case interpretation guide",
            hide_index=True,
            wrap_text=True,
        )
        wording_cols = ["Case", "Status", "AvoidWording", "SaferWording", "NextAction"]
        if set(wording_cols).issubset(case_guide.columns):
            wording_rows = case_guide.loc[
                case_guide["Status"].astype(str) != "Ready", wording_cols
            ]
            if not wording_rows.empty:
                with st.expander("Copy-edit wording repairs", expanded=True):
                    _render_compact_dataframe(
                        wording_rows,
                        ["Case", "Status", "AvoidWording", "SaferWording"],
                        details_label="Show full wording-repair table",
                        hide_index=True,
                        wrap_text=True,
                    )
        st.download_button(
            "Download case-specific interpretation guide (CSV)",
            data=to_csv_bytes(case_guide),
            file_name="mfrm_case_interpretation_guidance.csv",
            mime="text/csv",
            key="dl_case_interpretation_guidance_report_tab",
        )
    method_refs = build_method_reference_audit()
    if isinstance(method_refs, pd.DataFrame) and not method_refs.empty:
        st.subheader("Method Reference Audit")
        st.caption(
            "A Zotero/BibTeX-informed map from app methodology surfaces to "
            "APA-library references, manuscript use, and claim boundaries."
        )
        _render_compact_dataframe(
            method_refs,
            ["MethodArea", "ReferenceCoverageStatus", "ManuscriptUse"],
            details_label="Show full method reference audit",
            hide_index=True,
            wrap_text=True,
        )
        st.download_button(
            "Download method reference audit (CSV)",
            data=to_csv_bytes(method_refs),
            file_name="mfrm_method_reference_audit.csv",
            mime="text/csv",
            key="dl_method_reference_audit_report_tab",
        )
    help_refs = build_help_reference_coverage()
    if isinstance(help_refs, pd.DataFrame) and not help_refs.empty:
        st.subheader("Help Reference Coverage")
        st.caption(
            "A first-read evidence map for Help, Agreement, and category-collapse claims, "
            "including Zotero gaps that should be cleaned before manuscript submission."
        )
        _render_compact_dataframe(
            help_refs,
            ["HelpArea", "ReferenceCoverageStatus", "SafeClaim"],
            details_label="Show full help reference coverage",
            hide_index=True,
            wrap_text=True,
        )
        st.download_button(
            "Download help reference coverage (CSV)",
            data=to_csv_bytes(help_refs),
            file_name="mfrm_help_reference_coverage.csv",
            mime="text/csv",
            key="dl_help_reference_coverage_report_tab",
        )
    apa_sentence_audit = build_apa_report_sentence_audit(result, diagnostics, all_bias_results=all_bias_results)
    if isinstance(apa_sentence_audit, pd.DataFrame) and not apa_sentence_audit.empty:
        st.subheader("APA Sentence Evidence Audit")
        st.caption(
            "Sentence-level map from generated APA report prose to evidence files, "
            "suggested citations, and claim boundaries."
        )
        _render_compact_dataframe(
            apa_sentence_audit,
            ["SentenceOrder", "APASection", "SentenceRole", "LinkedManuscriptArea", "CopyDecision"],
            details_label="Show full APA sentence evidence audit",
            hide_index=True,
            wrap_text=True,
        )
        st.download_button(
            "Download APA sentence evidence audit (CSV)",
            data=to_csv_bytes(apa_sentence_audit),
            file_name="apa_report_sentence_audit.csv",
            mime="text/csv",
            key="dl_apa_sentence_audit_report_tab",
        )


def _render_manuscript_template_section(
    result: dict,
    diagnostics: dict,
    all_bias_results: dict | None = None,
) -> None:
    st.subheader("Manuscript Template")
    st.caption(
        "A result-aware Markdown scaffold for Methods, Results, figures, limitations, "
        "and reviewer preflight checks. Edit it for your study before submission."
    )
    template = generate_manuscript_reporting_template(result, diagnostics, all_bias_results)
    guide = build_manuscript_claim_guide(result, diagnostics, all_bias_results)
    caution_count = 0
    if isinstance(guide, pd.DataFrame) and not guide.empty and "ClaimStatus" in guide.columns:
        caution_count = int(guide["ClaimStatus"].astype(str).isin(["Do not claim", "Report with caveat"]).sum())
