def _collect_apa_exportable_tables(
    result: dict, diagnostics: dict
) -> dict[str, pd.DataFrame]:
    """Gather DataFrame tables from a fit + diagnostics bundle for APA export.

    Returns an insertion-ordered dict from human-readable label to the
    backing DataFrame. Only non-empty DataFrames are included; this is
    the same list of tables the existing publication-doc pipeline
    typically emits.
    """
    candidates: dict[str, pd.DataFrame] = {}
    if isinstance(result, dict):
        summary = result.get("summary")
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            candidates["Estimation summary"] = summary
        lik_info = result.get("likelihood_information")
        if isinstance(lik_info, pd.DataFrame) and not lik_info.empty:
            candidates["Likelihood / information criteria"] = lik_info
        facets = result.get("facets", {}) if isinstance(result.get("facets"), dict) else {}
        person_tbl = facets.get("person")
        if isinstance(person_tbl, pd.DataFrame) and not person_tbl.empty:
            candidates["Person measures"] = person_tbl
        others_tbl = facets.get("others")
        if isinstance(others_tbl, pd.DataFrame) and not others_tbl.empty:
            candidates["Facet element measures"] = others_tbl
        steps_tbl = result.get("steps")
        if isinstance(steps_tbl, pd.DataFrame) and not steps_tbl.empty:
            candidates["Step thresholds"] = steps_tbl
    if isinstance(diagnostics, dict):
        for key, label in [
            ("overall_fit", "Overall fit"),
            ("fit", "Per-facet fit"),
            ("measures", "Combined measures and fit"),
            ("reliability", "Reliability / separation"),
            ("bias", "Per-facet bias screen"),
            ("interactions", "Bias interaction screen"),
        ]:
            tbl = diagnostics.get(key)
            if isinstance(tbl, pd.DataFrame) and not tbl.empty:
                candidates[label] = tbl
    return candidates


def render_apa_presets_section(result: dict, diagnostics: dict) -> None:
    """Render the APA-preset export panel.

    Lets the user pick any of the available report tables, configure
    the caption / note / float digits / table number, and download the
    snippet as Markdown or HTML. Also previews the monochrome palette
    + dash patterns so figure exports can adopt the print-friendly
    preset on demand.
    """
    st.subheader(t("report_tables.apa_presets_subheader"))
    st.caption(t("report_tables.apa_presets_caption"))

    tables = _collect_apa_exportable_tables(result, diagnostics)
    if not tables:
        st.info(t("report_tables.apa_presets_no_tables_info"))
    else:
        labels = list(tables.keys())
        picker_col, format_col, digits_col, number_col = st.columns([3, 2, 1, 1])
        with picker_col:
            chosen_label = st.selectbox(
                t("report_tables.apa_presets_table_picker_label"),
                options=labels,
                key="apa_presets_table_picker",
            )
        with format_col:
            chosen_format = st.radio(
                t("report_tables.apa_presets_format_label"),
                options=["markdown", "html"],
                format_func=lambda v: (
                    t("report_tables.apa_presets_format_markdown")
                    if v == "markdown"
                    else t("report_tables.apa_presets_format_html")
                ),
                key="apa_presets_format",
                horizontal=True,
            )
        with digits_col:
            digits = int(
                st.number_input(
                    t("report_tables.apa_presets_digits_label"),
                    min_value=0, max_value=8, value=3, step=1,
                    key="apa_presets_digits",
                )
            )
        with number_col:
            tbl_num_raw = st.number_input(
                t("report_tables.apa_presets_table_number_label"),
                min_value=0, max_value=99, value=0, step=1,
                key="apa_presets_table_number",
            )
            table_number = int(tbl_num_raw) if int(tbl_num_raw) > 0 else None

        caption = st.text_input(
            t("report_tables.apa_presets_caption_label"),
            value=chosen_label,
            key="apa_presets_caption",
        ).strip() or None
        note = st.text_area(
            t("report_tables.apa_presets_note_label"),
            value="",
            height=80,
            key="apa_presets_note",
        ).strip() or None

        df = tables[chosen_label]
        if chosen_format == "markdown":
            snippet = apa_table_to_markdown(
                df, caption=caption, note=note,
                digits=digits, table_number=table_number,
            )
            st.markdown("**" + t("report_tables.apa_presets_preview_label") + "**")
            st.markdown(
                "```markdown\n" + snippet + "\n```"
                if snippet else "_(empty)_"
            )
            st.caption(t("report_tables.apa_presets_copy_caption"))
            if snippet:
                st.download_button(
                    t("report_tables.apa_presets_download_markdown_button"),
                    data=snippet.encode("utf-8"),
                    file_name="mfrm_apa_table.md",
                    mime="text/markdown",
                    key="apa_presets_md_download",
                )
        else:
            snippet = apa_table_to_html(
                df, caption=caption, note=note,
                digits=digits, table_number=table_number,
            )
            st.markdown("**" + t("report_tables.apa_presets_preview_label") + "**")
            if snippet:
                # Render the HTML snippet (a) literally as code and
                # (b) as actual styled HTML so users can sanity-check
                # the rendered output before pasting into a manuscript.
                with st.expander("HTML source", expanded=False):
                    st.code(snippet, language="html")
                st.markdown(snippet, unsafe_allow_html=True)
            else:
                st.write("_(empty)_")
            st.caption(t("report_tables.apa_presets_copy_caption"))
            if snippet:
                st.download_button(
                    t("report_tables.apa_presets_download_html_button"),
                    data=snippet.encode("utf-8"),
                    file_name="mfrm_apa_table.html",
                    mime="text/html",
                    key="apa_presets_html_download",
                )

    st.markdown(
        "**" + t("report_tables.apa_presets_monochrome_preview_subheader") + "**"
    )
    st.caption(t("report_tables.apa_presets_monochrome_caption"))
    palette = get_monochrome_palette()
    dashes = get_monochrome_dash_patterns()
    swatches = "".join(
        f"<span style=\"display:inline-block; width:36px; height:24px; "
        f"background:{color}; border:1px solid #888; margin-right:6px; "
        f"vertical-align:middle;\" title=\"{color}\"></span>"
        for color in palette
    )
    st.markdown(swatches, unsafe_allow_html=True)
    st.caption(
        " | ".join(
            f"`{c}`" for c in palette
        )
    )
    st.caption("Dash patterns: " + " · ".join(dashes))


def render_g_d_study_section(result: dict) -> None:
    """Render the generalizability theory + D-study panel.

    The math layer is fast (a few ANOVA reductions on the rating
    data plus a Cartesian-product grid), so the panel runs every
    page load without a Run-on-demand button. The bootstrap CI for
    G / Phi is gated behind a toggle because it pays the cost of
    re-decomposing the data across the resampled persons.
    """
    if not isinstance(result, dict):
        return
    st.subheader(t("report_tables.g_d_study_subheader"))
    st.caption(t("report_tables.g_d_study_caption"))

    # Bootstrap CI toggle. Keeps the initial render light; users who
    # want inferential bands click the checkbox and the bundle is
    # recomputed with bootstrap_ci=True (cached in session state).
    bootstrap_key = f"g_d_study_bootstrap_ci::{id(result)}"
    bootstrap_n_key = f"g_d_study_bootstrap_n::{id(result)}"
    bootstrap_conf_key = f"g_d_study_bootstrap_conf::{id(result)}"
    with st.expander(
        t("report_tables.g_d_study_bootstrap_expander"), expanded=False
    ):
        do_bootstrap = st.checkbox(
            t("report_tables.g_d_study_bootstrap_enable"),
            value=False, key=bootstrap_key,
        )
        bootstrap_n = int(
            st.number_input(
                t("report_tables.g_d_study_bootstrap_n"),
                min_value=50, max_value=2000, value=200, step=50,
                key=bootstrap_n_key,
            )
        )
        bootstrap_conf = float(
            st.selectbox(
                t("report_tables.g_d_study_bootstrap_conf"),
                options=list(VIZ_CI_LEVEL_OPTIONS),
                index=VIZ_CI_LEVEL_OPTIONS.index(0.95)
                    if 0.95 in VIZ_CI_LEVEL_OPTIONS else 5,
                key=bootstrap_conf_key,
                format_func=lambda v: f"{_ci_level_pct_label(v)} %",
            )
        )

    if do_bootstrap:
        with st.spinner(t("report_tables.g_d_study_bootstrap_running")):
            bundle = compute_generalizability_study(
                result,
                bootstrap_ci=True,
                n_bootstrap=bootstrap_n,
                bootstrap_confidence=bootstrap_conf,
            )
    else:
        bundle = compute_generalizability_study(result)
    if not bundle.get("available"):
        st.info(
            t(
                "report_tables.g_d_study_unavailable_template",
                reason=str(bundle.get("reason", "")),
            )
        )
        return

    var_components: pd.DataFrame = bundle["variance_components"]
    coef: dict = bundle["observed_coefficients"]
    d_study: pd.DataFrame = bundle["d_study"]
    design: dict = bundle["design"]

    if isinstance(var_components, pd.DataFrame) and not var_components.empty:
        display = var_components.copy()
        for col in ["Variance", "ProportionVariance", "SumSquares",
                    "MeanSquares", "MeanObsPerLevel"]:
            if col in display.columns:
                display[col] = pd.to_numeric(display[col], errors="coerce").round(4)
        st.caption(t("report_tables.g_d_study_variance_table_caption"))
        st.dataframe(display, width="stretch", hide_index=True)

    st.markdown("**" + t("report_tables.g_d_study_coefficients_subheader") + "**")
    cols = st.columns(2)
    cols[0].metric(
        t("report_tables.g_d_study_g_label"),
        f"{float(coef.get('G', float('nan'))):.3f}",
    )
    cols[1].metric(
        t("report_tables.g_d_study_phi_label"),
        f"{float(coef.get('Phi', float('nan'))):.3f}",
    )
    st.caption(
        t(
            "report_tables.g_d_study_design_template",
            object=str(design.get("object_facet", "")),
            facets=", ".join(str(x) for x in design.get("random_facets", [])),
            n_obs=f"{int(design.get('n_observations', 0)):,}",
        )
    )

    bootstrap = bundle.get("bootstrap_ci", {})
    if isinstance(bootstrap, dict) and bootstrap.get("available"):
        st.caption(
            t(
                "report_tables.g_d_study_bootstrap_ci_template",
                confidence=int(round(float(bootstrap.get("confidence", 0.95)) * 100)),
                n_success=int(bootstrap.get("n_success", 0)),
                g_lower=f"{float(bootstrap.get('G_lower', float('nan'))):.3f}",
                g_upper=f"{float(bootstrap.get('G_upper', float('nan'))):.3f}",
                phi_lower=f"{float(bootstrap.get('Phi_lower', float('nan'))):.3f}",
                phi_upper=f"{float(bootstrap.get('Phi_upper', float('nan'))):.3f}",
            )
        )

    if isinstance(d_study, pd.DataFrame) and not d_study.empty:
        st.markdown("**" + t("report_tables.g_d_study_d_study_subheader") + "**")
        st.caption(t("report_tables.g_d_study_d_study_caption"))
        display_d = d_study.copy()
        for col in ["G", "Phi", "G_lower", "G_upper", "Phi_lower", "Phi_upper"]:
            if col in display_d.columns:
                display_d[col] = pd.to_numeric(display_d[col], errors="coerce").round(4)
        has_ci_columns = all(
            col in display_d.columns
            for col in ["G_lower", "G_upper", "Phi_lower", "Phi_upper"]
        )
        if has_ci_columns:
            st.caption(t("report_tables.g_d_study_d_study_ci_band_caption"))
        st.dataframe(display_d, width="stretch", hide_index=True)

    caveat = bundle.get("caveat", "")
    if caveat:
        st.caption(
            t("report_tables.g_d_study_caveat_label") + ": " + str(caveat)
        )

    download_frames = []
    if isinstance(var_components, pd.DataFrame) and not var_components.empty:
        vc_dl = var_components.copy()
        vc_dl["_section"] = "variance_components"
        download_frames.append(vc_dl)
    if isinstance(d_study, pd.DataFrame) and not d_study.empty:
        d_dl = d_study.copy()
        d_dl["_section"] = "d_study"
        download_frames.append(d_dl)
    if download_frames:
        combined = pd.concat(download_frames, ignore_index=True)
        st.download_button(
            t("report_tables.g_d_study_download_button"),
            data=to_csv_bytes(combined),
            file_name="mfrm_g_d_study.csv",
            mime="text/csv",
            key=f"g_d_study_download::{id(result)}",
        )


_PARAMETER_RECOVERY_MODELS = ("RSM", "PCM", "GPCM")
_PARAMETER_RECOVERY_METHODS = ("JMLE", "MML")


def render_parameter_recovery_simulation() -> None:
    """Render the ADEMP parameter-recovery panel.

    The simulation is self-contained (it does not refit the user's
    data) — it samples a known many-facet truth, refits the requested
    model on each replicate, and reports bias / RMSE / coverage95.
    The widget caches the bundle in ``st.session_state`` keyed on the
    chosen settings so flipping language / re-rendering does not
    re-run the simulation.
    """
    st.subheader(t("report_tables.parameter_recovery_subheader"))
    st.caption(t("report_tables.parameter_recovery_caption"))

    settings_cols = st.columns(4)
    with settings_cols[0]:
        model = st.selectbox(
            t("report_tables.parameter_recovery_model_label"),
            options=list(_PARAMETER_RECOVERY_MODELS),
            index=0,
            key="param_recovery_model",
        )
    with settings_cols[1]:
        method = st.selectbox(
            t("report_tables.parameter_recovery_method_label"),
            options=list(_PARAMETER_RECOVERY_METHODS),
            index=0,
            key="param_recovery_method",
        )
    with settings_cols[2]:
        reps = int(
            st.number_input(
                t("report_tables.parameter_recovery_reps_label"),
                min_value=2, max_value=200, value=10, step=1,
                key="param_recovery_reps",
            )
        )
    with settings_cols[3]:
        seed = int(
            st.number_input(
                t("report_tables.parameter_recovery_seed_label"),
                min_value=1, max_value=2**31 - 1, value=20260601, step=1,
                key="param_recovery_seed",
            )
        )

    design_cols = st.columns(4)
    with design_cols[0]:
        n_person = int(
            st.number_input(
                t("report_tables.parameter_recovery_n_person_label"),
                min_value=5, max_value=500, value=30, step=5,
                key="param_recovery_n_person",
            )
        )
    with design_cols[1]:
        n_rater = int(
            st.number_input(
                t("report_tables.parameter_recovery_n_rater_label"),
                min_value=1, max_value=20, value=3, step=1,
                key="param_recovery_n_rater",
            )
        )
    with design_cols[2]:
        n_criterion = int(
            st.number_input(
                t("report_tables.parameter_recovery_n_criterion_label"),
                min_value=1, max_value=20, value=3, step=1,
                key="param_recovery_n_criterion",
            )
        )
    with design_cols[3]:
        n_cat = int(
            st.number_input(
                t("report_tables.parameter_recovery_n_cat_label"),
                min_value=2, max_value=10, value=4, step=1,
                key="param_recovery_n_cat",
            )
        )

    cache_key = "|".join([
        str(model), str(method), str(reps), str(seed),
        str(n_person), str(n_rater), str(n_criterion), str(n_cat),
    ])
    state_key = f"parameter_recovery_bundle::{cache_key}"

    if st.button(
        t("report_tables.parameter_recovery_run_button"),
        help=t("report_tables.parameter_recovery_run_help"),
        key=f"param_recovery_run::{cache_key}",
    ):
        with st.spinner(t("report_tables.parameter_recovery_running_spinner")):
            bundle = evaluate_parameter_recovery(
                model=model, fit_method=method, reps=reps,
                n_person=n_person, n_rater=n_rater, n_criterion=n_criterion,
                n_cat=n_cat, seed=seed,
            )
        st.session_state[state_key] = bundle

    bundle = st.session_state.get(state_key)
    if not bundle:
        return
    if not bundle.get("available"):
        st.info(
            t(
                "report_tables.parameter_recovery_unavailable_template",
                reason=str(bundle.get("reason", "")),
            )
        )
        return

    n_reps_total = int(bundle.get("n_reps_total", 0) or 0)
    n_reps_converged = int(bundle.get("n_reps_converged", 0) or 0)
    if n_reps_total:
        if bundle.get("summary_basis") == "all_completed":
            st.warning(
                t("report_tables.parameter_recovery_no_convergence_note", n_total=n_reps_total)
            )
        else:
            st.caption(
                t(
                    "report_tables.parameter_recovery_convergence_note",
                    n_converged=n_reps_converged,
                    n_total=n_reps_total,
                )
            )

    summary: pd.DataFrame = bundle["recovery_summary"]
    if isinstance(summary, pd.DataFrame) and not summary.empty:
        display = summary.copy()
        for col in [
            "Bias", "MCSEBias", "RMSE", "MCSERMSE", "MAE",
            "RawBias", "RawRMSE", "Correlation",
            "MeanSE", "SEAvailableRate", "Coverage95",
            "NominalCoverage", "CoverageErrorFromNominal",
            "MeanTruth", "MeanEstimate",
        ]:
            if col in display.columns:
                display[col] = pd.to_numeric(display[col], errors="coerce").round(4)
        st.caption(t("report_tables.parameter_recovery_summary_caption"))
        st.dataframe(display, width="stretch", hide_index=True)

    coverage_report: pd.DataFrame = bundle.get("coverage_report", pd.DataFrame())
    if not isinstance(coverage_report, pd.DataFrame) or coverage_report.empty:
        coverage_report = build_se_ci_coverage_report(bundle)
    if isinstance(coverage_report, pd.DataFrame) and not coverage_report.empty:
        coverage_display = coverage_report.copy()
        for col in [
            "NominalCoverage", "Coverage95", "CoverageError", "CoverageAbsError",
            "SEAvailableRate", "MeanSE",
        ]:
            if col in coverage_display.columns:
                coverage_display[col] = pd.to_numeric(
                    coverage_display[col], errors="coerce"
                ).round(4)
        st.caption(t("report_tables.parameter_recovery_coverage_caption"))
        _render_compact_dataframe(
            coverage_display,
            [
                "ParameterType", "Facet", "CoverageN", "NominalCoverage",
                "Coverage95", "CoverageError", "PrimarySEStatus",
                "SEBasisRisk", "CoverageClaimStatus",
                "Interpretation", "RecommendedAction",
            ],
            details_label=t("report_tables.parameter_recovery_coverage_details"),
            hide_index=True,
            wrap_text=True,
        )

    rep_overview: pd.DataFrame = bundle["rep_overview"]
    with st.expander(
        t("report_tables.parameter_recovery_rep_overview_expander"), expanded=False
    ):
        if isinstance(rep_overview, pd.DataFrame) and not rep_overview.empty:
            st.dataframe(rep_overview, width="stretch", hide_index=True)

    ademp = bundle.get("ademp", {})
    with st.expander(
        t("report_tables.parameter_recovery_ademp_expander"), expanded=False
    ):
        for key in ("Aims", "DataGenerating", "Estimands", "Methods",
                    "PerformanceMeasures", "Reference"):
            if key in ademp and ademp[key]:
                st.markdown(f"**{key}.** {ademp[key]}")

    # Build a single CSV with both summary and long table for download.
    recovery: pd.DataFrame = bundle.get("recovery", pd.DataFrame())
    download_frames = []
    if isinstance(summary, pd.DataFrame) and not summary.empty:
        s_dl = summary.copy()
        s_dl["_section"] = "recovery_summary"
        download_frames.append(s_dl)
    if isinstance(coverage_report, pd.DataFrame) and not coverage_report.empty:
        c_dl = coverage_report.copy()
        c_dl["_section"] = "se_ci_coverage_report"
        download_frames.append(c_dl)
    if isinstance(recovery, pd.DataFrame) and not recovery.empty:
        r_dl = recovery.copy()
        r_dl["_section"] = "recovery_long_table"
        download_frames.append(r_dl)
    if download_frames:
        combined = pd.concat(download_frames, ignore_index=True)
        st.download_button(
            t("report_tables.parameter_recovery_download_button"),
            data=to_csv_bytes(combined),
            file_name="mfrm_parameter_recovery.csv",
            mime="text/csv",
            key=f"param_recovery_download::{cache_key}",
        )
    if isinstance(coverage_report, pd.DataFrame) and not coverage_report.empty:
        st.download_button(
            t("report_tables.parameter_recovery_coverage_download_button"),
            data=to_csv_bytes(coverage_report),
            file_name="mfrm_se_ci_coverage_report.csv",
            mime="text/csv",
            key=f"param_recovery_coverage_download::{cache_key}",
        )


# ---------------------------------------------------------------------------
# Report sub-tab: Tables & Figures
# ---------------------------------------------------------------------------

def _render_report_tables(result: dict, diagnostics: dict) -> None:
    """Estimation summary tables for the Report tab."""
    st.subheader(t("report_tables.estimation_summary_subheader"))
    summary_df = result.get("summary", pd.DataFrame())
    if isinstance(summary_df, pd.DataFrame) and not summary_df.empty:
        st.dataframe(summary_df, width="stretch")
    else:
        st.info(t("report_tables.no_estimation_summary"))

    likelihood_info = result.get("likelihood_information", pd.DataFrame())
    if not isinstance(likelihood_info, pd.DataFrame) or likelihood_info.empty:
        likelihood_info = build_likelihood_information_criteria(result)
    if isinstance(likelihood_info, pd.DataFrame) and not likelihood_info.empty:
        st.subheader(t("report_tables.likelihood_info_subheader"))
        st.caption(t("report_tables.likelihood_info_caption"))
        st.dataframe(likelihood_info.round(4), width="stretch", hide_index=True)

    render_model_choice_guidance(result)
    render_g_d_study_section(result)
    render_design_network_section(result)
    render_rater_severity_section(result)
    render_rater_halo_section(result)
    render_parameter_recovery_simulation()
    render_apa_presets_section(result, diagnostics)

    regularization = result.get("regularization", {})
    if isinstance(regularization, dict):
        reg_penalty = regularization.get("penalty_summary", pd.DataFrame())
        reg_audit = regularization.get("audit", pd.DataFrame())
        if isinstance(reg_penalty, pd.DataFrame) and not reg_penalty.empty:
            active = bool(result.get("config", {}).get("facet_regularization_enabled", False))
            st.subheader(t("report_tables.facet_regularization_subheader"))
            if active:
                st.warning(t("report_tables.facet_regularization_warning_active"))
            else:
                st.caption(t("report_tables.facet_regularization_off_caption"))
            st.dataframe(reg_penalty.round(4), width="stretch", hide_index=True)
            if isinstance(reg_audit, pd.DataFrame) and not reg_audit.empty:
                with st.expander(t("report_tables.facet_regularization_audit_expander"), expanded=False):
                    st.dataframe(reg_audit, width="stretch", hide_index=True)

    shrinkage = diagnostics.get("eb_shrinkage", {}) if isinstance(diagnostics, dict) else {}
    if isinstance(shrinkage, dict) and diagnostics.get("eb_shrinkage_enabled", False):
        st.subheader(t("report_tables.eb_shrinkage_subheader"))
        report = shrinkage.get("report", pd.DataFrame())
        if shrinkage.get("available") and isinstance(report, pd.DataFrame) and not report.empty:
            st.caption(t("report_tables.eb_shrinkage_caption"))
            st.dataframe(report.round(4), width="stretch", hide_index=True)
        else:
            # ``shrinkage["reason"]`` is upstream-supplied dynamic text (locale-
            # neutral). Fall back to the translated default when absent.
            reason = shrinkage.get("reason") or t("report_tables.eb_shrinkage_unavailable")
            st.info(reason)

    weight_audit = build_weighting_policy_audit(result)
    if isinstance(weight_audit, pd.DataFrame) and not weight_audit.empty:
        st.subheader(t("report_tables.weighting_policy_audit_subheader"))
        st.caption(t("report_tables.weighting_policy_audit_caption"))
        st.dataframe(weight_audit, width="stretch", hide_index=True)

    show_convergence_section(result)

    st.subheader(t("report_tables.overall_fit_subheader"))
    overall_fit_df = diagnostics.get("overall_fit", pd.DataFrame())
    if isinstance(overall_fit_df, pd.DataFrame) and not overall_fit_df.empty:
        st.dataframe(overall_fit_df, width="stretch")
    else:
        st.info(t("report_tables.no_overall_fit"))

    # Observation-level standardized residual check (Eckes, 2005)
    obs_df = diagnostics.get("obs", pd.DataFrame())
    if not obs_df.empty and "StdResidual" in obs_df.columns:
        std_res = pd.to_numeric(obs_df["StdResidual"], errors="coerce").dropna()
        if len(std_res) > 0:
            abs_res = std_res.abs()
            pct_ge2 = float((abs_res >= 2).mean() * 100)
            pct_ge3 = float((abs_res >= 3).mean() * 100)
            n_total = len(std_res)
            fit_lines = [
                t(
                    "report_tables.fit_obs_z2_template",
                    n_z2=int((abs_res >= 2).sum()),
                    n_total=n_total,
                    pct_ge2=f"{pct_ge2:.1f}",
                ),
                t(
                    "report_tables.fit_obs_z3_template",
                    n_z3=int((abs_res >= 3).sum()),
                    n_total=n_total,
                    pct_ge3=f"{pct_ge3:.1f}",
                ),
            ]
            st.markdown(t("report_tables.global_fit_header"))
            st.markdown("\n".join(fit_lines))
            if pct_ge2 > FINAL_RESIDUAL_PCT_GE2_REVIEW:
                st.warning(t(
                    "report_tables.fit_warning_template",
                    pct_ge2=f"{pct_ge2:.1f}",
                    threshold=f"{FINAL_RESIDUAL_PCT_GE2_READY:.0f}",
                ))
            elif pct_ge2 > FINAL_RESIDUAL_PCT_GE2_READY:
                st.info(t(
                    "report_tables.fit_info_template",
                    pct_ge2=f"{pct_ge2:.1f}",
                    threshold=f"{FINAL_RESIDUAL_PCT_GE2_READY:.0f}",
                ))

    st.subheader(t("report_tables.reliability_subheader"))
    rel_df = diagnostics.get("reliability", pd.DataFrame())
    if isinstance(rel_df, pd.DataFrame) and not rel_df.empty:
        st.dataframe(rel_df, width="stretch")
    else:
        st.info(t("report_tables.no_reliability"))

    # Measurement report by facet
    measures = diagnostics.get("measures", pd.DataFrame())
    if not measures.empty and "Facet" in measures.columns:
        st.subheader(t("report_tables.measurement_report_subheader"))
        report_rows = []
        for facet_name, grp in measures.groupby("Facet"):
            estimates = pd.to_numeric(grp.get("Estimate", pd.Series(dtype=float)), errors="coerce").dropna()
            se_vals = pd.to_numeric(grp.get("SE", pd.Series(dtype=float)), errors="coerce").dropna()
            if len(estimates) < 2:
                continue
            adj_sd = float(np.std(estimates, ddof=1))
            rmse = float(np.sqrt(np.mean(se_vals ** 2))) if len(se_vals) > 0 else np.nan
            true_sd = np.sqrt(max(adj_sd ** 2 - rmse ** 2, 0)) if np.isfinite(rmse) else np.nan
            separation = true_sd / rmse if np.isfinite(rmse) and rmse > 0 else np.nan
            reliability = separation ** 2 / (1 + separation ** 2) if np.isfinite(separation) else np.nan
            strata = (4 * separation + 1) / 3 if np.isfinite(separation) else np.nan
            infit = pd.to_numeric(grp.get("Infit", pd.Series(dtype=float)), errors="coerce").dropna()
            outfit = pd.to_numeric(grp.get("Outfit", pd.Series(dtype=float)), errors="coerce").dropna()
            n_misfit = 0
            if len(infit) > 0:
                n_misfit = int(((infit > 1.5) | (infit < 0.5)).sum())
            if len(outfit) > 0:
                n_misfit = max(n_misfit, int(((outfit > 1.5) | (outfit < 0.5)).sum()))
            n_total = len(estimates)
            report_rows.append({
                "Facet": facet_name,
                "N": n_total,
                "Mean Measure": f"{float(estimates.mean()):.2f}",
                "Obs. SD": f"{adj_sd:.2f}",
                "RMSE": f"{rmse:.2f}" if np.isfinite(rmse) else "—",
                "True SD": f"{true_sd:.2f}" if np.isfinite(true_sd) else "—",
                "Separation (G)": f"{separation:.2f}" if np.isfinite(separation) else "—",
                "Strata (H)": f"{strata:.1f}" if np.isfinite(strata) else "—",
                "Reliability": f"{reliability:.3f}" if np.isfinite(reliability) else "—",
                "Misfit": f"{n_misfit}/{n_total} ({100*n_misfit/n_total:.0f}%)" if n_total > 0 else "—",
            })
        if report_rows:
            report_df = pd.DataFrame(report_rows)
            st.dataframe(report_df, width="stretch")
            st.caption(t("report_tables.measurement_report_caption"))

    # Measures with 95% CI
    if not measures.empty and "Estimate" in measures.columns and "SE" in measures.columns:
        st.subheader(t("report_tables.element_measures_ci_subheader"))
        ci_df = measures.copy()
        est = pd.to_numeric(ci_df["Estimate"], errors="coerce")
        se = pd.to_numeric(ci_df["SE"], errors="coerce")
        if "CI_Lower" not in ci_df.columns:
            ci_df["CI_Lower"] = (est - 1.96 * se).round(3)
            ci_df["CI_Upper"] = (est + 1.96 * se).round(3)
        show_cols = [c for c in ["Facet", "Element", "Level", "Estimate", "SE",
                                  "CI_Lower", "CI_Upper", "Infit", "Outfit"] if c in ci_df.columns]
        st.dataframe(ci_df[show_cols], width="stretch")
        st.caption(t("report_tables.element_measures_ci_caption"))


def _render_apa_report(
    result: dict,
    diagnostics: dict,
    bias_results: dict | None = None,
    all_bias_results: dict | None = None,
) -> None:
    """Generate publication-quality APA-style report text with interpretation guidance."""
    st.subheader("APA-Style Report Text")
    st.caption(
        "Auto-generated from estimation output. Copy the text below into your "
        "manuscript Method and Results sections. Review and adapt before submission."
    )

    # --- Reading guide ---
    with st.expander("How to read this report", expanded=False):
        st.markdown(
            """
This tab generates draft text for the **Method** and **Results** sections
of a research paper that uses MFRM.

#### What each section covers

| Section | Purpose | What to look for |
|---------|---------|-----------------|
| **Method** | Describes *what* you did | Model type, sample size, software — readers need this to evaluate your study |
| **Global fit** | Does the model fit the data? | % of residuals > |2| should be near 5%. Much higher = poor fit |
| **Reliability & Separation** | Can the model distinguish between elements? | Higher is better for persons; for raters, *low* reliability means raters agree (good!) |
| **Misfit** | Are there problematic elements? | Infit 0.5–1.5 is acceptable. Outside = erratic (>1.5) or too predictable (<0.5) |
| **Rating scale** | Is the rubric working? | Ordered thresholds = good. Disordered = categories are confusing raters |
| **Bias** | Are there systematic interactions? | Use the DFF/bias audit: sparse cells, Holm/BH multiplicity checks, and conditional inference scope determine what can be claimed |

#### Key terms explained

- **Separation (*G*)**: How many distinct levels the model can identify within a facet. *G* > 2.0 is good for persons; *G* < 1.0 for raters means they are similar (desirable).
- **Reliability**: Proportion of observed variance that is "true" variance (not measurement error). Ranges from 0 to 1.
- **Strata (*H*)**: Number of statistically distinct groups. *H* = (4*G* + 1) / 3. For persons, *H* ≥ 3 means at least 3 ability levels.
- **Infit MnSq**: Mean-square fit statistic weighted by information. 1.0 = perfect fit. Values far from 1.0 indicate misfit.
- **Outfit MnSq**: Unweighted mean-square — sensitive to outliers. A single unexpected response can inflate Outfit.
- **Bias / local interaction**: A conditional screening check for whether a specific element pairing (e.g., Rater R1 on Task T3) deviates from the model prediction. Interpret with sparse-cell flags, Holm/BH multiplicity checks, common-scale evidence, and the exported inference audit.
- **Logit**: The unit of measurement in Rasch models. One logit difference ≈ the effect of one additional correct response.
- **95% CI**: Confidence interval. If two elements' CIs do not overlap, they are significantly different at *p* < .05.

#### How to use the generated text

1. **Copy** the text from the "Copy-ready plain text" expander below.
2. **Paste** into your manuscript's Method and Results sections.
3. **Review and edit**: The text is a starting draft — adapt it to your specific study context, add your research questions, and connect findings to your hypotheses.
4. **Add references**: The cited references are listed in the "References" expander below. Add them to your reference list.
"""
        )

    config = result.get("config", {})
    prep = result.get("prep", {})
    facet_names = config.get("facet_names", [])
    measures = diagnostics.get("measures", pd.DataFrame())
    gate_summary = build_publication_gate_summary(result, diagnostics, all_bias_results)
    case_guidance = build_case_interpretation_guidance(result, diagnostics, all_bias_results)
    action_plan = build_submission_action_plan(result, diagnostics, all_bias_results)
    current_bias_results = all_bias_results or {}
    if not current_bias_results and bias_results:
        current_bias_results = {
            f"{bias_results.get('facet_a', 'A')} x {bias_results.get('facet_b', 'B')}": bias_results
        }
    current_method_refs = build_current_run_method_reference_audit(
        result,
        diagnostics,
        current_bias_results,
    )
    apa_sentence_audit = build_apa_report_sentence_audit(
        result,
        diagnostics,
        bias_results=bias_results,
        all_bias_results=current_bias_results,
    )
    decision_brief = generate_report_ready_decision_brief(
        result,
        diagnostics,
        all_bias_results=current_bias_results,
        bias_results=bias_results,
    )
    custom_simulation_frames = current_custom_simulation_sparse_export_frames()
    simulation_sparse_context = custom_simulation_frames.get(
        "custom_simulation_sparse_reporting_context",
        pd.DataFrame(),
    )
    simulation_settings = custom_simulation_frames.get("custom_simulation_settings", pd.DataFrame())
    apa_results_draft = generate_report_ready_apa_results_draft(
        result,
        diagnostics,
        all_bias_results=current_bias_results,
        bias_results=bias_results,
        simulation_sparse_context=simulation_sparse_context,
        simulation_settings=simulation_settings,
    )
    role_action_memos = build_role_based_action_memos(
        result,
        diagnostics,
        all_bias_results=current_bias_results,
        bias_results=bias_results,
    )
    role_action_memos_md = generate_role_based_action_memos_markdown(
        result,
        diagnostics,
        all_bias_results=current_bias_results,
        bias_results=bias_results,
    )
    role_action_checklist = build_role_based_action_checklist(
        result,
        diagnostics,
        all_bias_results=current_bias_results,
        bias_results=bias_results,
    )
    role_action_checklist_md = generate_role_based_action_checklist_markdown(
        result,
        diagnostics,
        all_bias_results=current_bias_results,
        bias_results=bias_results,
    )
    critical_final_review = build_critical_final_review_panel(
        result,
        diagnostics,
        all_bias_results=current_bias_results,
        bias_results=bias_results,
        role_action_checklist=role_action_checklist,
    )
    critical_final_review_md = generate_critical_final_review_markdown(
        result,
        diagnostics,
        all_bias_results=current_bias_results,
        bias_results=bias_results,
        role_action_checklist=role_action_checklist,
        critical_final_review=critical_final_review,
    )
    reporting_action_bridge = build_reporting_action_bridge(
        result,
        diagnostics,
        all_bias_results=current_bias_results,
        bias_results=bias_results,
        role_action_checklist=role_action_checklist,
        critical_final_review=critical_final_review,
        submission_action_plan=action_plan,
    )
    reporting_action_bridge_md = generate_reporting_action_bridge_markdown(
        result,
        diagnostics,
        all_bias_results=current_bias_results,
        bias_results=bias_results,
        bridge=reporting_action_bridge,
        role_action_checklist=role_action_checklist,
        critical_final_review=critical_final_review,
        submission_action_plan=action_plan,
    )
    with st.expander("Report-ready decision brief", expanded=False):
        st.code(decision_brief, language="markdown")
    st.download_button(
        "Download report-ready decision brief (Markdown)",
        data=decision_brief.encode("utf-8"),
        file_name="report_ready_decision_brief.md",
        mime="text/markdown",
        key="dl_apa_report_ready_decision_brief_md",
    )
    with st.expander("APA Results paragraph draft", expanded=True):
        st.code(apa_results_draft, language="markdown")
    st.download_button(
        "Download APA Results paragraph draft (Markdown)",
        data=apa_results_draft.encode("utf-8"),
        file_name="apa_results_paragraph_draft.md",
        mime="text/markdown",
        key="dl_apa_results_paragraph_draft_md",
    )
    if isinstance(role_action_memos, pd.DataFrame) and not role_action_memos.empty:
        with st.expander("Role-based action memos", expanded=False):
            _render_compact_dataframe(
                role_action_memos,
                ["Role", "Priority", "DecisionFocus", "ReportStatus", "ImmediateAction", "EvidenceToOpen"],
                details_label="Show full role-based action memos",
                hide_index=True,
                wrap_text=True,
            )
            st.code(role_action_memos_md, language="markdown")
        st.download_button(
            "Download role-based action memos (Markdown)",
            data=role_action_memos_md.encode("utf-8"),
            file_name="role_based_action_memos.md",
            mime="text/markdown",
            key="dl_apa_role_based_action_memos_md",
        )
    if isinstance(role_action_checklist, pd.DataFrame) and not role_action_checklist.empty:
        with st.expander("Role-based action checklist", expanded=False):
            st.dataframe(role_action_checklist, width="stretch", hide_index=True)
            st.code(role_action_checklist_md, language="markdown")
        st.download_button(
            "Download role-based action checklist (CSV)",
            data=to_csv_bytes(role_action_checklist),
            file_name="role_based_action_checklist.csv",
            mime="text/csv",
            key="dl_apa_role_based_action_checklist_csv",
        )
    if isinstance(critical_final_review, pd.DataFrame) and not critical_final_review.empty:
        with st.expander("Critical final review", expanded=False):
            _render_compact_dataframe(
                critical_final_review,
                ["Priority", "Lens", "Decision", "StopBeforeFinalOutput", "NeedsCaveat", "ActionBeforeContinuing"],
                details_label="Show full critical final review",
                hide_index=True,
                wrap_text=True,
            )
            st.code(critical_final_review_md, language="markdown")
        crit_col, crit_md_col = st.columns(2)
        with crit_col:
            st.download_button(
                "Download critical final review (CSV)",
                data=to_csv_bytes(critical_final_review),
                file_name="critical_final_review_panel.csv",
                mime="text/csv",
                key="dl_apa_critical_final_review_panel_csv",
            )
        with crit_md_col:
            st.download_button(
                "Download critical final review (Markdown)",
                data=critical_final_review_md.encode("utf-8"),
                file_name="critical_final_review.md",
                mime="text/markdown",
                key="dl_apa_critical_final_review_md",
            )
    if isinstance(reporting_action_bridge, pd.DataFrame) and not reporting_action_bridge.empty:
        with st.expander("Reporting action bridge", expanded=False):
            _render_compact_dataframe(
                reporting_action_bridge,
                ["Priority", "BridgeTrack", "PrimaryAudience", "CurrentStatus", "OutputToProduce", "DraftOrDecisionMove"],
                details_label="Show full reporting action bridge",
                hide_index=True,
                wrap_text=True,
            )
            st.code(reporting_action_bridge_md, language="markdown")
        bridge_col, bridge_md_col = st.columns(2)
        with bridge_col:
            st.download_button(
                "Download reporting action bridge (CSV)",
                data=to_csv_bytes(reporting_action_bridge),
                file_name="reporting_action_bridge.csv",
                mime="text/csv",
                key="dl_apa_reporting_action_bridge_csv",
            )
        with bridge_md_col:
            st.download_button(
                "Download reporting action bridge (Markdown)",
                data=reporting_action_bridge_md.encode("utf-8"),
                file_name="reporting_action_bridge.md",
                mime="text/markdown",
                key="dl_apa_reporting_action_bridge_md",
            )
    if isinstance(simulation_sparse_context, pd.DataFrame) and not simulation_sparse_context.empty:
        with st.expander("Simulation sparse-design context", expanded=False):
            _render_compact_dataframe(
                simulation_sparse_context,
                ["Priority", "SimulationCheck", "ReportStatus", "ActionBeforeReporting", "CaveatToCarry"],
                details_label="Show full simulation sparse-design context",
                hide_index=True,
                wrap_text=True,
            )
        st.download_button(
            "Download simulation sparse-design context (CSV)",
            data=to_csv_bytes(simulation_sparse_context),
            file_name="custom_simulation_sparse_reporting_context.csv",
            mime="text/csv",
            key="dl_apa_custom_simulation_sparse_reporting_context_csv",
        )
    if isinstance(simulation_settings, pd.DataFrame) and not simulation_settings.empty:
        with st.expander("Simulation settings", expanded=False):
            _render_compact_dataframe(
                simulation_settings,
                ["Priority", "Section", "Setting", "Value", "ReportNote"],
                details_label="Show full simulation settings",
                hide_index=True,
                wrap_text=True,
            )
        st.download_button(
            "Download simulation settings (CSV)",
            data=to_csv_bytes(simulation_settings),
            file_name="custom_simulation_settings.csv",
            mime="text/csv",
            key="dl_apa_custom_simulation_settings_csv",
        )
    overall_gate = pd.Series(dtype=object)
    if isinstance(gate_summary, pd.DataFrame) and not gate_summary.empty:
        overall_hit = gate_summary.loc[
            gate_summary["GateArea"].astype(str) == "Overall manuscript gate"
        ]
        if not overall_hit.empty:
            overall_gate = overall_hit.iloc[0]
            gate_status = str(overall_gate.get("GateStatus", ""))
            gate_text = (
                f"**Manuscript gate: {gate_status}.** "
                f"{overall_gate.get('Evidence', '')} "
                f"{overall_gate.get('ManuscriptAction', '')}"
            )
            if gate_status == "Not ready":
                st.error(gate_text)
            elif gate_status == "Report with caveat":
                st.warning(gate_text)
            else:
                st.success(gate_text)
            with st.expander("View manuscript gate details", expanded=False):
                st.dataframe(gate_summary, width="stretch", hide_index=True)
    if isinstance(action_plan, pd.DataFrame) and not action_plan.empty:
        top_actions = action_plan.head(8)
        with st.expander("First actions before final reporting", expanded=True):
            st.caption(
                "Read these rows before copying APA-style text. They combine the gate, "
                "claim guide, readiness checks, and wording repairs."
            )
            _render_compact_dataframe(
                top_actions,
                ["Priority", "Status", "Topic", "ImmediateAction"],
                details_label="Show full first-action table",
                hide_index=True,
                wrap_text=True,
            )
    if isinstance(case_guidance, pd.DataFrame) and not case_guidance.empty:
        wording_cols = ["Case", "Status", "AvoidWording", "SaferWording", "NextAction"]
        if set(wording_cols).issubset(case_guidance.columns):
            copy_flags = case_guidance.loc[
                case_guidance["Status"].astype(str) != "Ready", wording_cols
            ]
            if not copy_flags.empty:
                st.warning(
                    "Before copying APA text, review these result-specific wording repairs."
                )
                with st.expander("Case-specific wording repairs for this report", expanded=True):
                    _render_compact_dataframe(
                        copy_flags,
                        ["Case", "Status", "AvoidWording", "SaferWording"],
                        details_label="Show full wording-repair table",
                        hide_index=True,
                        wrap_text=True,
                    )

    if isinstance(current_method_refs, pd.DataFrame) and not current_method_refs.empty:
        with st.expander("Method references and claim boundaries for this report", expanded=False):
            st.caption(
                "Run-specific subset of `method_reference_audit.csv`. These rows support "
                "method description and claim boundaries; they do not by themselves validate the dataset."
            )
            _render_compact_dataframe(
                current_method_refs,
                ["MethodArea", "CitationTokens", "ManuscriptUse", "ClaimBoundary", "TriggerEvidence"],
                details_label="Show full current-run reference audit",
                hide_index=True,
                wrap_text=True,
            )

    method_parts: list[str] = []
    results_parts: list[str] = []
    refs_used: set[str] = set()

    # --- Method section ---
    n_obs = prep.get("n_obs", "?")
    n_person = prep.get("n_person", "?")
    n_cat = config.get("n_cat", "?")
    model = config.get("model", "RSM")
    method = config.get("method", "JMLE")
    rating_min = prep.get("rating_min", "?")
    rating_max = prep.get("rating_max", "?")

    if isinstance(n_obs, int) and isinstance(n_person, int):
        method_parts.append(
            f"A *Many-Facet Rasch Model* (MFRM; {model}) was estimated "
            f"using {method} with *N* = {n_obs:,} observations from {n_person:,} persons, "
            "following Rasch-family and many-facet measurement conventions "
            "(Rasch, 1980; Linacre, 1989)."
        )
    else:
        method_parts.append(
            f"A *Many-Facet Rasch Model* (MFRM; {model}) was estimated "
            f"using {method} with *N* = {n_obs} observations from {n_person} persons, "
            "following Rasch-family and many-facet measurement conventions "
            "(Rasch, 1980; Linacre, 1989)."
        )
    refs_used.update(["Rasch, 1980", "Linacre, 1989"])

    # Facet counts
    facet_desc_parts = []
    for fn in facet_names:
        if not measures.empty and "Facet" in measures.columns:
            n_levels = len(measures[measures["Facet"] == fn])
            facet_desc_parts.append(f"{n_levels} {fn.lower()}s")
        else:
            facet_desc_parts.append(fn)
    if facet_desc_parts:
        method_parts.append(f"Facets modeled: {', '.join(facet_desc_parts)}.")

    if method == "JMLE":
        optimizer_desc = (
            "custom Python software with analytical-gradient quasi-Newton optimization"
        )
    else:
        optimizer_desc = (
            "custom Python software using an EM algorithm with quasi-Newton M-step updates"
        )

    method_parts.append(
        f"The rating scale had {n_cat} categories ({rating_min}–{rating_max}). "
        f"Estimation was performed using {optimizer_desc}. "
        "Reported 95% intervals use conditional approximate SEs "
        "(Estimate ± 1.96 × SE); they do not propagate all non-person parameter "
        "covariances or person-estimation uncertainty."
    )
    if model == "RSM":
        method_parts.append("The rating-scale formulation follows the ordered-category RSM specification (Andrich, 1978).")
        refs_used.add("Andrich, 1978")
    elif model == "PCM":
        method_parts.append("The partial-credit formulation allows category thresholds to vary by step structure (Masters, 1982).")
        refs_used.add("Masters, 1982")
    elif model == "GPCM":
        method_parts.append("The generalized partial-credit specification is reported with its bounded slope constraints (Masters, 1982; Muraki, 1992).")
        refs_used.update(["Masters, 1982", "Muraki, 1992"])
    if method == "MML":
        method_parts.append(
            "The MML/EAP path was treated as marginal EM estimation with posterior "
            "scoring and observed-information caveats (Bock & Aitkin, 1981; "
            "Bock & Mislevy, 1982; Louis, 1982)."
        )
        refs_used.update(["Bock & Aitkin, 1981", "Bock & Mislevy, 1982", "Louis, 1982"])
    if model == "GPCM":
        slope_tbl = result.get("slopes", pd.DataFrame())
        if isinstance(slope_tbl, pd.DataFrame) and not slope_tbl.empty:
            slopes = pd.to_numeric(slope_tbl.get("Estimate", pd.Series(dtype=float)), errors="coerce").dropna()
            if len(slopes):
                method_parts.append(
                    "The GPCM specification used the bounded slope structure "
                    f"`slope_facet = step_facet = {config.get('step_facet')}`. "
                    "Slope parameters were constrained positive and identified by fixing "
                    "the geometric mean slope to 1. "
                    f"Estimated slopes ranged from {slopes.min():.2f} to {slopes.max():.2f}."
                )
            else:
                method_parts.append(
                    "The GPCM specification used the bounded slope structure "
                    f"`slope_facet = step_facet = {config.get('step_facet')}`; slope estimates were not available for summarization."
                )
        refs_used.update(["Masters, 1982", "Muraki, 1992"])

    # --- Global fit ---
    obs_df = diagnostics.get("obs", pd.DataFrame())
    if not obs_df.empty and "StdResidual" in obs_df.columns:
        std_res = pd.to_numeric(obs_df["StdResidual"], errors="coerce").dropna()
        if len(std_res) > 0:
            abs_res = std_res.abs()
            n_total = len(std_res)
            pct_ge2 = float((abs_res >= 2).mean() * 100)
            pct_ge3 = float((abs_res >= 3).mean() * 100)
            fit_label = (
                "satisfactory"
                if pct_ge2 <= FINAL_RESIDUAL_PCT_GE2_READY
                else "marginally acceptable"
                if pct_ge2 <= FINAL_RESIDUAL_PCT_GE2_REVIEW
                else "poor"
            )
            results_parts.append(
                f"Global model fit was {fit_label}, with {pct_ge2:.1f}% of "
                f"standardized residuals exceeding |2| (expected ≈ 5%; Eckes, 2005) "
                f"and {pct_ge3:.1f}% exceeding |3| (expected ≈ 1%)."
            )
            refs_used.add("Eckes, 2005")

    # --- Reliability & separation with 95% CI ---
    rel_df = diagnostics.get("reliability", pd.DataFrame())
    if not rel_df.empty:
        rel_sentences = []
        for _, row in rel_df.iterrows():
            facet = row.get("Facet", "")
            rel_val = row.get("Reliability", row.get("reliability", np.nan))
            sep_val = row.get("Separation", row.get("separation", np.nan))
            try:
                rel_val = float(rel_val)
                sep_val = float(sep_val)
            except (TypeError, ValueError):
                continue
            if not np.isfinite(rel_val):
                continue
            strata = (4 * sep_val + 1) / 3 if np.isfinite(sep_val) else np.nan
            if rel_val >= 0.90:
                interp = "excellent differentiation"
            elif rel_val >= FINAL_PERSON_RELIABILITY_READY:
                interp = "good differentiation"
            elif rel_val >= FINAL_PERSON_RELIABILITY_REVIEW:
                interp = "moderate differentiation"
            else:
                interp = "poor differentiation; differences mainly due to measurement error"
            strata_str = f", *H* = {strata:.1f}" if np.isfinite(strata) else ""
            # Add measure range with 95% CI for this facet
            ci_note = ""
            if not measures.empty and "Facet" in measures.columns:
                fmeas = measures[measures["Facet"] == facet]
                est = pd.to_numeric(fmeas.get("Estimate", pd.Series(dtype=float)), errors="coerce").dropna()
                se = pd.to_numeric(fmeas.get("SE", pd.Series(dtype=float)), errors="coerce").dropna()
                if len(est) > 0 and len(se) > 0:
                    ci_note = (
                        f"; measures ranged from {est.min():.2f} to {est.max():.2f} logits, "
                        f"mean SE = {se.mean():.3f}"
                    )
            rel_sentences.append(
                f"{facet} separation *G* = {sep_val:.2f} "
                f"(reliability = {rel_val:.3f}{strata_str}; {interp}{ci_note})"
            )
        if rel_sentences:
            results_parts.append(
                "; ".join(rel_sentences) + " (Wright & Masters, 1982)."
            )
            refs_used.add("Wright & Masters, 1982")

    # --- Misfit summary ---
    if not measures.empty and "Infit" in measures.columns:
        infit = pd.to_numeric(measures["Infit"], errors="coerce").dropna()
        outfit = pd.to_numeric(measures.get("Outfit", pd.Series(dtype=float)), errors="coerce").dropna()
        n_elements = len(infit)
        n_infit_misfit = int(((infit > 1.5) | (infit < 0.5)).sum())
        n_outfit_misfit = int((outfit > 2.0).sum()) if len(outfit) > 0 else 0
        if n_elements > 0:
            results_parts.append(
                f"{n_infit_misfit} of {n_elements} elements ({100*n_infit_misfit/n_elements:.0f}%) "
                f"showed Infit *MnSq* outside the 0.5–1.5 range (Wright & Linacre, 1994)"
                + (f", and {n_outfit_misfit} showed Outfit *MnSq* > 2.0" if n_outfit_misfit > 0 else "")
                + "."
            )
            refs_used.add("Wright & Linacre, 1994")

    # --- Rating scale analysis (Linacre's 5 criteria) ---
    steps_df = result.get("steps", pd.DataFrame())
    if isinstance(steps_df, pd.DataFrame) and not steps_df.empty:
        step_vals = pd.to_numeric(
            steps_df.get("Estimate", pd.Series(dtype=float)), errors="coerce"
        ).dropna()
        if len(step_vals) >= 2:
            diffs = step_vals.diff().dropna()
            ordered = bool((diffs > 0).all())
            sorted_diffs = step_vals.sort_values().diff().dropna()
            min_gap = float(sorted_diffs.min()) if len(sorted_diffs) > 0 else 0
            max_gap = float(sorted_diffs.max()) if len(sorted_diffs) > 0 else 0
            linacre_met = 0
            linacre_total = 0
            linacre_details: list[str] = []
            obs_df_cat = diagnostics.get("obs", pd.DataFrame())
            if not obs_df_cat.empty and "Score" in obs_df_cat.columns:
                cat_counts = obs_df_cat["Score"].value_counts()
                min_count = int(cat_counts.min()) if len(cat_counts) > 0 else 0
                linacre_total += 1
                if min_count >= 10:
                    linacre_met += 1
                else:
                    linacre_details.append(f"minimum category count = {min_count} (criterion: ≥ 10)")
            if not obs_df_cat.empty and "Score" in obs_df_cat.columns:
                cat_pcts = obs_df_cat["Score"].value_counts(normalize=True) * 100
                min_pct = float(cat_pcts.min()) if len(cat_pcts) > 0 else 0
                linacre_total += 1
                if min_pct >= 1.0:
                    linacre_met += 1
                else:
                    linacre_details.append(f"minimum category usage = {min_pct:.1f}% (criterion: ≥ 1%)")
            linacre_total += 1
            if len(sorted_diffs) > 0:
                if bool((sorted_diffs.abs() >= 1.0).all() and (sorted_diffs.abs() <= 5.0).all()):
                    linacre_met += 1
                else:
                    linacre_details.append(f"step advance range {min_gap:.2f}–{max_gap:.2f} logits (criterion: 1.0–5.0)")
            linacre_total += 1
            if ordered:
                linacre_met += 1
            else:
                linacre_details.append("thresholds disordered")
            if linacre_total > 0:
                rating_text = (
                    f"Rating scale analysis showed {linacre_met} of {linacre_total} "
                    f"evaluated Linacre criteria met (Linacre, 2004). "
                )
                if ordered:
                    rating_text += f"Thresholds were ordered with step advances of {min_gap:.2f}–{max_gap:.2f} logits"
                else:
                    rating_text += "Thresholds were disordered"
                if linacre_details:
                    rating_text += f"; issues: {'; '.join(linacre_details)}"
                rating_text += "."
                decision_support = rating_scale_decision_support_table(result, diagnostics)
                if isinstance(decision_support, pd.DataFrame) and not decision_support.empty:
                    overall_decision = decision_support.loc[
                        decision_support["DecisionArea"].astype(str) == "Overall reportability"
                    ]
                    if not overall_decision.empty:
                        decision_status = str(overall_decision["DecisionStatus"].iloc[0])
                        safe_wording = str(overall_decision["SafeReportWording"].iloc[0]).rstrip(".")
                        rating_text += (
                            f" Integrated decision support status: {decision_status}; "
                            f"{safe_wording}."
                        )
                results_parts.append(rating_text)
            refs_used.add("Linacre, 2004")

    # --- Bias/Interaction — ALL pairs ---
    all_bias = current_bias_results
    bias_audit = build_bias_inference_audit(all_bias, result, diagnostics) if all_bias else pd.DataFrame()
    if isinstance(bias_audit, pd.DataFrame) and not bias_audit.empty:
        for _, audit_row in bias_audit.iterrows():
            n_pairs = int(audit_row.get("CellsScreened", 0) or 0)
            if n_pairs <= 0:
                continue
            n_flagged = int(audit_row.get("FlaggedCells", 0) or 0)
            n_strong = int(audit_row.get("StrongReviewCells", 0) or 0)
            n_sparse = int(audit_row.get("SparseCells", 0) or 0)
            pair_label = str(audit_row.get("FacetPair", "selected facet pair")).replace(" x ", " × ")
            results_parts.append(
                f"Bias analysis of the {pair_label} interaction was treated as a "
                f"conditional screening analysis: {n_flagged} of {n_pairs} cells were "
                f"DFF/bias review flags ({n_strong} strong-review; {n_sparse} sparse), "
                "with Holm/BH multiplicity checks applied within the exported cell family "
                "(Yen, 1984; Christensen, Makransky & Horton, 2017; Myford & Wolfe, 2003; "
                "Myford & Wolfe, 2004)."
            )
            refs_used.update([
                "Yen, 1984",
                "Christensen, Makransky & Horton, 2017",
                "Myford & Wolfe, 2003",
                "Myford & Wolfe, 2004",
            ])

    # --- Build final text ---
    method_text = "**Method.**  " + "  ".join(method_parts)
    results_text = "**Results.**  " + "  ".join(results_parts) if results_parts else ""
    full_text = method_text + "\n\n" + results_text

    st.markdown(full_text)
    if isinstance(apa_sentence_audit, pd.DataFrame) and not apa_sentence_audit.empty:
        with st.expander("Sentence-level evidence audit for the APA text", expanded=False):
            st.caption(
                "Use this table before copying generated prose. Each row links a report sentence "
                "to evidence files, suggested citations, and wording boundaries."
            )
            _render_compact_dataframe(
                apa_sentence_audit,
                ["SentenceOrder", "APASection", "SentenceRole", "LinkedManuscriptArea", "CopyDecision"],
                details_label="Show full APA sentence evidence audit",
                hide_index=True,
                wrap_text=True,
            )
            st.download_button(
                "Download APA sentence evidence audit (CSV)",
                data=to_csv_bytes(apa_sentence_audit),
                file_name="apa_report_sentence_audit.csv",
                mime="text/csv",
                key=f"dl_apa_sentence_audit_apa_tab::{id(result)}",
            )

    # --- Inline interpretation guidance (below the APA text) ---
    st.markdown("---")
    st.markdown("#### Interpretation Guide")
    st.caption(
        "The callouts below summarize the key findings from the report above "
        "and help you decide whether action is needed."
    )

    # Global fit interpretation
    obs_df_interp = diagnostics.get("obs", pd.DataFrame())
    if not obs_df_interp.empty and "StdResidual" in obs_df_interp.columns:
        std_res_interp = pd.to_numeric(obs_df_interp["StdResidual"], errors="coerce").dropna()
        if len(std_res_interp) > 0:
            pct2 = float((std_res_interp.abs() >= 2).mean() * 100)
            if pct2 <= FINAL_RESIDUAL_PCT_GE2_READY:
                st.success(
                    f"**Global fit: Good** — {pct2:.1f}% of residuals exceed |2| "
                    f"(final-report benchmark <= {FINAL_RESIDUAL_PCT_GE2_READY:.0f}%). "
                    "The model fits the data adequately."
                )
            elif pct2 <= FINAL_RESIDUAL_PCT_GE2_REVIEW:
                st.warning(
                    f"**Global fit: Marginal** — {pct2:.1f}% of residuals exceed |2| "
                    f"(final-report benchmark <= {FINAL_RESIDUAL_PCT_GE2_READY:.0f}%). "
                    "Consider checking for misfitting elements in the Fit Details tab."
                )
            else:
                st.error(
                    f"**Global fit: Poor** — {pct2:.1f}% of residuals exceed |2| "
                    f"(final-report benchmark <= {FINAL_RESIDUAL_PCT_GE2_READY:.0f}%). "
                    "The model does not fit well. Consider: (a) collapsing rating categories, "
                    "(b) removing misfitting elements, or (c) using PCM instead of RSM."
                )

    # Reliability interpretation per facet
    rel_df_interp = diagnostics.get("reliability", pd.DataFrame())
    if not rel_df_interp.empty:
        for _, row in rel_df_interp.iterrows():
            facet = row.get("Facet", "")
            rel_val = float(row.get("Reliability", row.get("reliability", np.nan)))
            sep_val = float(row.get("Separation", row.get("separation", np.nan)))
            if not np.isfinite(rel_val):
                continue
            # Different interpretation for persons vs. raters/other facets
            is_person = (facet.lower() == "person")
            if is_person:
                if rel_val >= FINAL_PERSON_RELIABILITY_READY:
                    st.success(
                        f"**{facet} reliability: {rel_val:.3f} (Good)** — "
                        f"The model reliably distinguishes {facet.lower()} ability levels "
                        f"(Separation *G* = {sep_val:.2f})."
                    )
                elif rel_val >= FINAL_PERSON_RELIABILITY_REVIEW:
                    st.info(
                        f"**{facet} reliability: {rel_val:.3f} (Moderate)** — "
                        "Person differentiation is moderate. Consider increasing "
                        "the number of tasks or raters to improve precision."
                    )
                else:
                    st.warning(
                        f"**{facet} reliability: {rel_val:.3f} (Low)** — "
                        "The model cannot reliably distinguish between persons. "
                        "Add more observations per person (more raters, tasks, or criteria)."
                    )
            else:
                # For non-person facets, low reliability can be desirable (rater interchangeability)
                if rel_val >= FINAL_PERSON_RELIABILITY_READY:
                    st.info(
                        f"**{facet} reliability: {rel_val:.3f} (High differentiation)** — "
                        f"{facet} elements differ significantly in severity "
                        f"(Separation *G* = {sep_val:.2f}). "
                        "If these are raters, this means raters are *not* interchangeable — "
                        "consider rater training or calibration."
                    )
                elif rel_val >= FINAL_PERSON_RELIABILITY_REVIEW:
                    st.info(
                        f"**{facet} reliability: {rel_val:.3f} (Moderate)** — "
                        f"Some {facet.lower()} elements differ moderately. Review the "
                        "Wright Map to see the spread of measures."
                    )
                else:
                    st.success(
                        f"**{facet} reliability: {rel_val:.3f} (Low = elements are similar)** — "
                        f"{facet} elements have similar severity. "
                        "If these are raters, this is the ideal outcome — raters are interchangeable."
                    )

    # Misfit interpretation
    if not measures.empty and "Infit" in measures.columns:
        infit_interp = pd.to_numeric(measures["Infit"], errors="coerce").dropna()
        n_elements_interp = len(infit_interp)
        n_misfit_interp = int(((infit_interp > 1.5) | (infit_interp < 0.5)).sum())
        if n_elements_interp > 0:
            pct_misfit = 100 * n_misfit_interp / n_elements_interp
            if n_misfit_interp == 0:
                st.success(
                    "**Element fit: All acceptable** — No elements outside the 0.5–1.5 Infit range."
                )
            elif pct_misfit <= 15:
                misfit_elements = measures[
                    (infit_interp > 1.5) | (infit_interp < 0.5)
                ]
                names = ", ".join(
                    misfit_elements["Level"].astype(str).tolist()[:5]
                ) if "Level" in misfit_elements.columns else f"{n_misfit_interp} elements"
                st.warning(
                    f"**Element fit: {n_misfit_interp} misfitting ({pct_misfit:.0f}%)** — "
                    f"Flagged: {names}. "
                    "Check the Fit Details tab for details. Consider whether these elements "
                    "should be removed, retrained (if raters), or revised (if tasks)."
                )
            else:
                st.error(
                    f"**Element fit: {n_misfit_interp} misfitting ({pct_misfit:.0f}%)** — "
                    "A large proportion of elements show misfit. This suggests the model "
                    "may not be appropriate for this data. Consider simplifying the model, "
                    "collapsing categories, or checking for data quality issues."
                )

    # Rating scale interpretation
    steps_df_interp = result.get("steps", pd.DataFrame())
    if isinstance(steps_df_interp, pd.DataFrame) and not steps_df_interp.empty:
        sv = pd.to_numeric(
            steps_df_interp.get("Estimate", pd.Series(dtype=float)), errors="coerce"
        ).dropna()
        if len(sv) >= 2:
            diffs_interp = sv.diff().dropna()
            ordered_interp = bool((diffs_interp > 0).all())
            if ordered_interp:
                st.success(
                    "**Rating scale: Thresholds ordered** — The rubric categories function "
                    "as intended. Each category represents a progressively higher level."
                )
            else:
                disordered_pairs = []
                for i, d in enumerate(diffs_interp):
                    if d <= 0:
                        disordered_pairs.append(f"step {i+1}→{i+2}")
                st.error(
                    f"**Rating scale: Thresholds disordered** at {', '.join(disordered_pairs)}. "
                    "This means some adjacent categories are not being used as distinct levels. "
                    "**Action:** Consider collapsing the affected categories (e.g., merge categories "
                    "2 and 3 into a single 'moderate' category) and re-run the estimation."
                )

    # Bias interpretation
    all_bias_interp = current_bias_results
    bias_audit_interp = build_bias_inference_audit(all_bias_interp, result, diagnostics) if all_bias_interp else pd.DataFrame()
    any_bias = False
    if isinstance(bias_audit_interp, pd.DataFrame) and not bias_audit_interp.empty:
        for _, audit_row in bias_audit_interp.iterrows():
            ns = int(audit_row.get("FlaggedCells", 0) or 0)
            np_ = int(audit_row.get("CellsScreened", 0) or 0)
            sparse = int(audit_row.get("SparseCells", 0) or 0)
            strong = int(audit_row.get("StrongReviewCells", 0) or 0)
            pair_key = str(audit_row.get("FacetPair", "Bias"))
            if np_ > 0 and (ns > 0 or sparse > 0):
                any_bias = True
                st.warning(
                    f"**Bias: {pair_key}** — {ns} of {np_} cells are DFF/bias review flags "
                    f"({strong} strong-review; {sparse} sparse). "
                    "Treat this as conditional screening evidence and review the Bias/Interaction audit."
                )
    if all_bias_interp and not any_bias:
        st.success(
            "**Bias: No DFF/bias review flags in the computed screen** — "
            "Keep the claim limited to the facet pairs and cells that were actually tested, "
            "and report the conditional screening scope."
        )

    # --- Overall decision summary ---
    st.markdown("---")
    st.markdown("#### Summary Decision")

    issues: list[str] = []
    if not obs_df_interp.empty and "StdResidual" in obs_df_interp.columns:
        sr = pd.to_numeric(obs_df_interp["StdResidual"], errors="coerce").dropna()
        if len(sr) > 0 and float((sr.abs() >= 2).mean() * 100) > FINAL_RESIDUAL_PCT_GE2_REVIEW:
            issues.append("poor global fit")
    if not rel_df_interp.empty:
        for _, rr in rel_df_interp.iterrows():
            if rr.get("Facet", "").lower() == "person":
                rv = float(rr.get("Reliability", rr.get("reliability", 0)))
                if rv < FINAL_PERSON_RELIABILITY_REVIEW:
                    issues.append("low person reliability")
    if not measures.empty and "Infit" in measures.columns:
        inf = pd.to_numeric(measures["Infit"], errors="coerce").dropna()
        if len(inf) > 0 and ((inf > 1.5) | (inf < 0.5)).mean() > 0.25:
            issues.append("widespread element misfit")
    if isinstance(steps_df_interp, pd.DataFrame) and not steps_df_interp.empty:
        sv2 = pd.to_numeric(
            steps_df_interp.get("Estimate", pd.Series(dtype=float)), errors="coerce"
        ).dropna()
        if len(sv2) >= 2 and not bool((sv2.diff().dropna() > 0).all()):
            issues.append("disordered rating scale thresholds")
    gate_status = str(overall_gate.get("GateStatus", "Ready")) if not overall_gate.empty else "Ready"
    gate_evidence = str(overall_gate.get("Evidence", "")) if not overall_gate.empty else ""
    gate_action = str(overall_gate.get("ManuscriptAction", "")) if not overall_gate.empty else ""
    if gate_status == "Not ready":
        st.error(
            f"**Overall: Not ready for final APA conclusions.** {gate_evidence} "
            f"{gate_action} Use the Claim Guide and Readiness tabs before copying text."
        )
    elif gate_status == "Report with caveat":
        caveat_rows = gate_summary[
            (gate_summary["GateStatus"].astype(str) == "Report with caveat")
            & (gate_summary["GateArea"].astype(str) != "Overall manuscript gate")
        ] if isinstance(gate_summary, pd.DataFrame) and not gate_summary.empty else pd.DataFrame()
        caveat_labels = (
            ", ".join(caveat_rows["GateArea"].astype(str).head(4).tolist())
            if not caveat_rows.empty and "GateArea" in caveat_rows.columns else
            ", ".join(issues)
        )
        st.warning(
            f"**Overall: Report with caveat.** {gate_evidence} "
            f"Primary caveat(s): {caveat_labels or 'see gate details'}. "
            f"{gate_action} The APA text is a draft, not a final conclusion."
        )
    elif issues:
        st.warning(
            f"**Overall: Some issues to address — {', '.join(issues)}.** "
            "The results may be usable, but check the detailed diagnostics before finalizing your manuscript."
        )
    else:
        st.success(
            "**Overall: Ready for draft reporting.** "
            "No required gate issue was detected. Copy the APA text only after adapting it "
            "to the study context and checking the Manuscript Template."
        )

    st.markdown("---")

    # Copy-ready plain text (without markdown italics)
    plain_text = full_text.replace("*", "")
    with st.expander("Copy-ready plain text"):
        st.code(plain_text, language=None)
        st.caption(
            "Copy the text above into your manuscript. Remove or modify sections "
            "as needed for your specific study. The text uses APA 7th edition formatting."
        )

    # Auto-generated references: narrative citations plus current-run method
    # audit rows that may be used in the manuscript template and claim matrix.
    current_method_reference_keys = _reference_keys_from_method_reference_frame(current_method_refs)
    reference_keys_used = sorted(
        set(_reference_keys_from_citation_labels(refs_used)).union(current_method_reference_keys)
    )
    if reference_keys_used:
        with st.expander("References cited in the report"):
            st.caption(
                "Add these references to your manuscript's reference list when you use "
                "the generated APA text, method-reference audit, or claim matrix. "
                "Review the list against the final manuscript before submission."
            )
            for key in reference_keys_used:
                st.markdown(f"- {_APA_REFERENCE_LIBRARY[key]}")

    # Bibliography downloads — convert the citations found in the
    # generated narrative into BibTeX (Zotero / LaTeX) and RIS
    # (EndNote / Mendeley). Use the full APA library as the citation
    # source (build_bibtex_from_cited matches on `_CITATION_TO_KEY`)
    # so authors get well-formed entries even for references that
    # the abbreviated ``_REFERENCES`` block above does not cover.
    _bibtex_text = build_bibtex_from_cited(full_text, always_include=reference_keys_used)
    _ris_text = build_ris_from_cited(full_text, always_include=reference_keys_used)
    if _bibtex_text or _ris_text:
        with st.expander(t("apa_report.bibliography_downloads_expander")):
            st.caption(t("apa_report.bibliography_downloads_caption"))
            _bib_col, _ris_col = st.columns(2)
            if _bibtex_text:
                _bib_col.download_button(
                    label=t("apa_report.bibtex_download_label"),
                    data=_bibtex_text.encode("utf-8"),
                    file_name="mfrm_references.bib",
                    mime="application/x-bibtex",
                    help=t("apa_report.bibtex_download_help"),
                    key=f"apa_bibtex_download::{id(result)}",
                )
            if _ris_text:
                _ris_col.download_button(
                    label=t("apa_report.ris_download_label"),
                    data=_ris_text.encode("utf-8"),
                    file_name="mfrm_references.ris",
                    mime="application/x-research-info-systems",
                    help=t("apa_report.ris_download_help"),
                    key=f"apa_ris_download::{id(result)}",
                )
            st.caption(t("apa_report.bibliography_review_caveat"))


# ---------------------------------------------------------------------------
# Report sub-tab: Reporting Checklist (auto-filled)
# ---------------------------------------------------------------------------

def _render_reporting_checklist(
    result: dict, diagnostics: dict, all_bias_results: dict | None = None,
) -> None:
    """Auto-filled MFRM reporting checklist based on actual results."""
    st.subheader("MFRM Reporting Checklist")
    st.caption(
        "Based on Eckes (2005), Koizumi et al. (2019), Myford & Wolfe (2003, 2004). "
        "Items are auto-checked when the corresponding data is available."
    )

    config = result.get("config", {})
    prep = result.get("prep", {})
    measures = diagnostics.get("measures", pd.DataFrame())
    obs_df = diagnostics.get("obs", pd.DataFrame())
    rel_df = diagnostics.get("reliability", pd.DataFrame())
    steps_df = result.get("steps", pd.DataFrame())
    slopes_df = result.get("slopes", pd.DataFrame())
    all_bias = all_bias_results or {}

    def _check(condition: bool, text: str) -> str:
        return f"- [x] {text}" if condition else f"- [ ] {text}"

    lines: list[str] = []

    # 1. Method
    lines.append("#### 1. Method Section")
    model = config.get("model", "?")
    method = config.get("method", "?")
    optimizer = config.get("optimizer", "L-BFGS-B")
    lines.append(_check(model != "?", f"**Model specification**: {model}, {method}, {optimizer}"))
    n_obs = prep.get("n_obs", 0)
    n_person = prep.get("n_person", 0)
    lines.append(_check(
        isinstance(n_obs, int) and n_obs > 0,
        f"**Data description**: {n_obs:,} observations, {n_person:,} persons, "
        f"{config.get('n_cat', '?')} categories ({prep.get('rating_min', '?')}–{prep.get('rating_max', '?')})"
    ))
    opt_obj = result.get("opt", None)
    conv_ok = getattr(opt_obj, "success", False) if opt_obj is not None else False
    conv_msg = getattr(opt_obj, "message", "?") if opt_obj is not None else "not available"
    lines.append(_check(conv_ok, f"**Convergence**: {conv_msg}"))
    lines.append(_check(
        diagnostics.get("obs") is not None,
        "**Connectivity**: data connectivity assessed"
    ))

    # 2. Global fit
    lines.append("\n#### 2. Global Fit")
    has_resid = not obs_df.empty and "StdResidual" in obs_df.columns
    lines.append(_check(has_resid, "**Standardized residuals**: % with |z| ≥ 2 and |z| ≥ 3"))
    # PCA availability: True iff mfrm_diagnostics produced the pca bundle
    # for this run. Previously hardcoded to False, so the checklist cell
    # was always rendered unchecked even when PCA was computed.
    has_pca = isinstance(diagnostics.get("pca"), dict) and bool(diagnostics["pca"])
    lines.append(_check(has_pca, "**PCA of residuals**: 1st eigenvalue and % variance (see Dimensionality tab)"))

    # 3. Facet-level
    lines.append("\n#### 3. Facet-Level Statistics")
    has_rel = isinstance(rel_df, pd.DataFrame) and not rel_df.empty
    lines.append(_check(has_rel, "**Separation (G), Strata (H), Reliability (R)** per facet"))
    lines.append(_check(has_rel, "**Fixed chi-square** test (see Report → Tables & checks → Tables)"))
    lines.append(_check(has_rel, "**RMSE and True SD** per facet"))

    # 4. Element-level
    lines.append("\n#### 4. Element-Level Statistics")
    has_meas = not measures.empty and "Estimate" in measures.columns
    has_ci = has_meas and "SE" in measures.columns
    lines.append(_check(has_meas, "**Measure** (logits) with **SE** for each element"))
    lines.append(_check(
        has_ci,
        "**Conditional approximate 95% interval** for each element (Estimate ± 1.96 × SE)"
    ))
    has_fit = has_meas and "Infit" in measures.columns
    lines.append(_check(has_fit, "**Infit and Outfit MnSq** with control limits (0.5–1.5)"))
    lines.append(_check(has_fit, "**Count and percentage** of misfitting elements"))

    # 5. Rating scale
    lines.append("\n#### 5. Rating Scale Diagnostics")
    has_steps = isinstance(steps_df, pd.DataFrame) and not steps_df.empty
    lines.append(_check(has_resid, "**Category counts** and percentages"))
    # Average-measure-per-category is computed whenever observation table
    # and Score column are present. Previously hardcoded False.
    has_obs_for_categories = has_resid and "Score" in obs_df.columns
    lines.append(_check(has_obs_for_categories, "**Average measures** per category (see Categories/Steps tab)"))
    lines.append(_check(has_steps, "**Rasch-Andrich thresholds** — ordering and distances"))
    lines.append(_check(True, "**Category probability curves** (see Visuals tab)"))
    if model == "GPCM":
        has_slopes = isinstance(slopes_df, pd.DataFrame) and not slopes_df.empty
        lines.append(_check(has_slopes, "**GPCM slopes** — report range and state geometric mean slope is fixed to 1"))
        lines.append(_check(True, "**GPCM scope statement** — bounded model with slope_facet = step_facet; do not interpret slopes as severity"))

    # 6. Bias
    lines.append("\n#### 6. Bias/Interaction Analysis")
    has_bias = bool(all_bias)
    n_bias_pairs = len(all_bias)
    lines.append(_check(has_bias, f"**Facet pairs tested**: {n_bias_pairs} pair(s)"))
    lines.append(_check(has_bias, "**Significant interactions** count with Bonferroni correction"))

    # 7. Visual
    lines.append("\n#### 7. Visual Displays")
    lines.append(_check(True, "**Wright Map** (see Wright Map tab)"))
    lines.append(_check(True, "**Fit scatter, probability curves** (see Visuals tab)"))

    st.markdown("\n".join(lines))

    # Key references
    with st.expander("Key References"):
        st.markdown("""
- Eckes, T. (2005). Examining rater effects in TestDaF writing and speaking performance assessments. *Language Assessment Quarterly, 2*, 197–221.
- Koizumi, R., In'nami, Y., Asano, K., & Agawa, T. (2019). Validity argument for CEFR-J A1 spoken interaction tasks. *Papers in Language Testing and Assessment, 8*(2), 1–33.
- Linacre, J. M. (1989). *Many-facet Rasch measurement*. MESA Press.
- Linacre, J. M. (2004). Optimizing rating scale category effectiveness. In E. V. Smith & R. M. Smith (Eds.), *Introduction to Rasch measurement* (pp. 258–278). JAM Press.
- Myford, C. M., & Wolfe, E. W. (2003). Detecting and measuring rater effects using MFRM: Part I. *Journal of Applied Measurement, 4*, 386–422.
- Myford, C. M., & Wolfe, E. W. (2004). Detecting and measuring rater effects using MFRM: Part II. *Journal of Applied Measurement, 5*, 189–227.
- Wright, B. D., & Linacre, J. M. (1994). Reasonable mean-square fit values. *Rasch Measurement Transactions, 8*, 370.
- Wright, B. D., & Masters, G. N. (1982). *Rating scale analysis*. MESA Press.
""")


# ---------------------------------------------------------------------------
# Report sub-tab: Facet Equivalence Analysis
# ---------------------------------------------------------------------------

def _render_facet_equivalence(result: dict, diagnostics: dict) -> None:
    """Facet equivalence testing: TOST, BIC Bayes Factor, ROPE, forest plot."""
    st.subheader("Facet Equivalence Analysis")
    st.caption(
        "Tests whether elements within a facet have statistically equivalent measures. "
        "Combines frequentist (TOST), Bayesian (BIC Bayes Factor), and ROPE approaches. "
        "For full Bayesian posterior inference, use the Stan Code tab."
    )

    measures = diagnostics.get("measures", pd.DataFrame())
    if measures.empty or "Facet" not in measures.columns:
        st.info("No measures available. Run estimation first.")
        return

    facet_names = result.get("config", {}).get("facet_names", [])
    if not facet_names:
        st.info("No facets available.")
        return

    col_a, col_b = st.columns(2)
    with col_a:
        eq_facet = st.selectbox(
            "Facet to test", list(facet_names), index=0, key="eq_facet",
            help="Select the facet to test for equivalence. For example, choose 'Rater' "
                 "to test whether all raters have statistically equivalent severity.",
        )
    with col_b:
        eq_bound = st.number_input(
            "Equivalence bound (logits)", value=0.5, min_value=0.1, max_value=2.0,
            step=0.1, key="eq_bound",
            help="SESOI: smallest meaningful difference. 0.5 logits is a common threshold.",
        )

    elements = measures[measures["Facet"] == eq_facet].copy()
    if len(elements) < 2:
        st.info(f"Need ≥ 2 elements for '{eq_facet}'. Found {len(elements)}.")
        return

    for col in ["Estimate", "SE"]:
        elements[col] = pd.to_numeric(elements[col], errors="coerce")
    elements = elements.dropna(subset=["Estimate", "SE"])
    est = elements["Estimate"].values
    se = elements["SE"].values
    n_elem = len(est)
    elem_labels = elements["Element"].values if "Element" in elements.columns else elements["Level"].values if "Level" in elements.columns else np.arange(n_elem)

    # Weighted grand mean
    w = 1.0 / (se ** 2)
    grand_mean = float(np.average(est, weights=w))

    # --- 1. Fixed chi-square (Rasch separation test) ---
    st.markdown("---")
    st.markdown("**1. Fixed Chi-Square Test** (Linacre, 2024)")
    chi2_val = float(np.sum(w * (est - grand_mean) ** 2))
    df_chi = n_elem - 1
    p_chi = float(1 - chi2.cdf(chi2_val, df_chi))
    sep_sd = float(np.std(est, ddof=1))
    rmse = float(np.sqrt(np.mean(se ** 2)))
    true_sd = np.sqrt(max(sep_sd ** 2 - rmse ** 2, 0))
    separation = true_sd / rmse if rmse > 0 else 0
    reliability = separation ** 2 / (1 + separation ** 2)

    c1, c2, c3, c4 = st.columns(4)
    c1.metric("χ²", f"{chi2_val:.2f}")
    c2.metric("df", df_chi)
    c3.metric("p", f"{p_chi:.4f}")
    c4.metric("Separation", f"{separation:.2f}")

    if p_chi >= 0.05:
        st.success(
            f"Fixed chi-square is non-significant (p = {p_chi:.3f}). "
            "Cannot reject hypothesis that all elements have equal measures. "
            "Note: non-significance does not prove equivalence."
        )
    else:
        st.warning(
            f"Fixed chi-square is significant (p = {p_chi:.4f}). "
            "Elements are measurably different."
        )

    # --- 2. TOST Equivalence Test (Lakens, 2017) ---
    st.markdown("---")
    st.markdown("**2. TOST Equivalence Test** (Lakens, 2017)")
    st.caption(f"Equivalence bound: ±{eq_bound:.1f} logits. Uses 90% CI (two one-sided α = .05).")

    tost_rows = []
    for (i, row_a), (j, row_b) in combinations(enumerate(est), 2):
        diff = float(est[i] - est[j])
        se_diff = float(np.sqrt(se[i]**2 + se[j]**2))
        if se_diff == 0:
            continue
        z_lower = (diff - (-eq_bound)) / se_diff
        z_upper = (diff - eq_bound) / se_diff
        p_lower = float(_norm.sf(z_lower))
        p_upper = float(_norm.cdf(z_upper))
        p_tost = max(p_lower, p_upper)
        equivalent = p_tost < 0.05
        tost_rows.append({
            "Element A": elem_labels[i],
            "Element B": elem_labels[j],
            "Diff (logits)": round(diff, 3),
            "SE_diff": round(se_diff, 3),
            "p_TOST": round(p_tost, 4),
            "Equivalent": equivalent,
        })

    if tost_rows:
        tost_df = pd.DataFrame(tost_rows)
        n_equiv = int(tost_df["Equivalent"].sum())
        n_total = len(tost_df)
        if n_equiv == n_total:
            st.success(f"All {n_total} pairwise comparisons are equivalent (p_TOST < .05).")
        elif n_equiv > n_total / 2:
            st.info(f"{n_equiv} of {n_total} pairs equivalent, {n_total - n_equiv} non-equivalent.")
        else:
            st.warning(f"Only {n_equiv} of {n_total} pairs equivalent.")
        with st.expander("TOST pairwise details"):
            st.dataframe(tost_df, width="stretch")

    # --- 3. BIC-Based Bayes Factor (Wagenmakers, 2007) ---
    st.markdown("---")
    st.markdown("**3. BIC-Based Bayes Factor** (Wagenmakers, 2007)")

    n_obs = result.get("prep", {}).get("n_obs", 1000)
    bic_diff = chi2_val - df_chi * np.log(n_obs)
    bf01 = float(np.exp(bic_diff / 2))
    # Clamp for display
    bf01_display = min(bf01, 1e6)

    if bf01 > 100:
        bf_label = "Extreme evidence for equivalence"
    elif bf01 > 30:
        bf_label = "Very strong evidence for equivalence"
    elif bf01 > 10:
        bf_label = "Strong evidence for equivalence"
    elif bf01 > 3:
        bf_label = "Moderate evidence for equivalence"
    elif bf01 > 1:
        bf_label = "Anecdotal evidence for equivalence"
    elif bf01 > 1/3:
        bf_label = "Anecdotal evidence against equivalence"
    elif bf01 > 1/10:
        bf_label = "Moderate evidence against equivalence"
    else:
        bf_label = "Strong evidence against equivalence"

    bc1, bc2 = st.columns(2)
    bc1.metric("BF₀₁", f"{bf01_display:.2f}")
    bc2.metric("Interpretation", bf_label)
    st.caption(
        "BF₀₁ > 1 supports H₀ (equivalence); BF₀₁ < 1 supports H₁ (difference). "
        "Jeffreys (1961) scale: 1–3 anecdotal, 3–10 moderate, 10–30 strong, >30 very strong."
    )

    # --- 4. ROPE Analysis (Kruschke, 2018) ---
    st.markdown("---")
    st.markdown("**4. ROPE Analysis** (Kruschke, 2018)")
    st.caption(
        f"Region of Practical Equivalence: [{-eq_bound:.1f}, {eq_bound:.1f}] logits "
        "around the weighted grand mean. Shows the proportion of each element's "
        "approximate posterior (normal) falling within the ROPE."
    )

    rope_rows = []
    for i in range(n_elem):
        deviation = float(est[i] - grand_mean)
        p_in_rope = float(
            _norm.cdf(eq_bound, loc=deviation, scale=se[i])
            - _norm.cdf(-eq_bound, loc=deviation, scale=se[i])
        )
        rope_rows.append({
            "Element": elem_labels[i],
            "Measure": round(est[i], 3),
            "Deviation": round(deviation, 3),
            "SE": round(se[i], 3),
            "% in ROPE": round(p_in_rope * 100, 1),
        })
    rope_df = pd.DataFrame(rope_rows)
    mean_rope = float(rope_df["% in ROPE"].mean())

    if mean_rope >= 95:
        st.success(f"Mean ROPE probability = {mean_rope:.1f}% — strong evidence for practical equivalence.")
    elif mean_rope >= 80:
        st.info(f"Mean ROPE probability = {mean_rope:.1f}% — moderate evidence for practical equivalence.")
    else:
        st.warning(f"Mean ROPE probability = {mean_rope:.1f}% — limited evidence for practical equivalence.")
    st.dataframe(rope_df, width="stretch")

    # --- 5. Forest Plot with ROPE overlay ---
    st.markdown("---")
    st.markdown("**5. Forest Plot — Measures with 95% CI and ROPE**")

    ci_lower = est - 1.96 * se
    ci_upper = est + 1.96 * se

    fig = go.Figure()
    # ROPE band
    fig.add_vrect(x0=grand_mean - eq_bound, x1=grand_mean + eq_bound,
                  fillcolor="green", opacity=0.12, line_width=0,
                  annotation_text=f"ROPE ±{eq_bound}", annotation_position="top left")
    fig.add_vline(x=grand_mean, line_dash="dash", line_color="gray", line_width=1,
                  annotation_text=f"Grand mean = {grand_mean:.2f}")

    labels_str = [str(lbl) for lbl in elem_labels]
    for i in range(n_elem):
        in_rope_l = ci_lower[i] >= grand_mean - eq_bound
        in_rope_u = ci_upper[i] <= grand_mean + eq_bound
        if in_rope_l and in_rope_u:
            color = "#2ecc71"
        elif ci_lower[i] > grand_mean + eq_bound or ci_upper[i] < grand_mean - eq_bound:
            color = "#e74c3c"
        else:
            color = "#f39c12"
        fig.add_trace(go.Scatter(
            x=[est[i]], y=[labels_str[i]], mode="markers",
            marker=dict(size=8, color=color), showlegend=False,
            error_x=dict(type="data", symmetric=False,
                         array=[ci_upper[i] - est[i]], arrayminus=[est[i] - ci_lower[i]],
                         color=color, thickness=2),
            hovertemplate=f"{labels_str[i]}: {est[i]:.2f} [{ci_lower[i]:.2f}, {ci_upper[i]:.2f}]<extra></extra>",
        ))

    fig.update_layout(
        xaxis_title="Measure (logits)",
        title=f"{eq_facet} — Element Measures with 95% CI and ROPE",
        yaxis=dict(autorange="reversed", categoryorder="array", categoryarray=labels_str),
        height=max(300, n_elem * 30), template="plotly_white",
    )
    st.plotly_chart(fig, width="stretch")
    _offer_fig_download(fig, "facet_equivalence_forest", "Download Forest Plot (PNG 300 DPI)")

    # --- 6. Convergent interpretation ---
    st.markdown("---")
    st.markdown("**Convergent Interpretation**")
    evidence_for = 0
    evidence_against = 0
    if p_chi >= 0.05:
        evidence_for += 1
    else:
        evidence_against += 1
    if tost_rows:
        if n_equiv == n_total:
            evidence_for += 1
        elif n_equiv < n_total / 2:
            evidence_against += 1
    if bf01 > 3:
        evidence_for += 1
    elif bf01 < 1/3:
        evidence_against += 1
    if mean_rope >= 90:
        evidence_for += 1
    elif mean_rope < 50:
        evidence_against += 1

    if evidence_for >= 3:
        st.success(
            f"Convergent evidence supports practical equivalence of {eq_facet} elements "
            f"(Fixed χ² p = {p_chi:.3f}, BF₀₁ = {bf01_display:.2f}, "
            f"mean ROPE = {mean_rope:.1f}%)."
        )
    elif evidence_against >= 3:
        st.error(
            f"Convergent evidence against equivalence of {eq_facet} elements. "
            "Elements are measurably and practically different."
        )
    else:
        st.info(
            f"Mixed evidence regarding {eq_facet} equivalence "
            f"(Fixed χ² p = {p_chi:.3f}, BF₀₁ = {bf01_display:.2f}, "
            f"mean ROPE = {mean_rope:.1f}%). "
            "Consider full Bayesian analysis (Stan Code tab) for definitive inference."
        )


