def rating_scale_category_evidence_table(result: dict, diagnostics: dict) -> pd.DataFrame:
    """Merge observed category evidence with FACETS-style curve diagnostics."""
    obs_df = diagnostics.get("obs", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()
    if not isinstance(obs_df, pd.DataFrame) or obs_df.empty:
        return pd.DataFrame()
    try:
        cat_tbl = calc_category_stats(obs_df, result)
    except Exception:
        try:
            cat_tbl = calc_category_stats(obs_df, None)
        except Exception:
            return pd.DataFrame()
    if not isinstance(cat_tbl, pd.DataFrame) or cat_tbl.empty:
        return pd.DataFrame()
    out = cat_tbl.copy()
    out["CategoryValue"] = pd.to_numeric(out.get("Category"), errors="coerce")

    curve_diag = category_curve_diagnostic_scope_table(result)
    if isinstance(curve_diag, pd.DataFrame) and not curve_diag.empty:
        avg_curve = curve_diag[curve_diag.get("IsAverage", pd.Series(dtype=bool)) == True].copy()
        if avg_curve.empty:
            avg_curve = curve_diag.copy()
        avg_curve["CategoryValue"] = pd.to_numeric(avg_curve["CategoryValue"], errors="coerce")
        keep_cols = [
            "CategoryValue",
            "PeakTheta",
            "PeakProbability",
            "IsEverMostProbable",
            "DominantThetaMin",
            "DominantThetaMax",
            "DominantWidth",
            "ReviewFlag",
        ]
        avg_curve = avg_curve.loc[:, [col for col in keep_cols if col in avg_curve.columns]]
        avg_curve = avg_curve.drop_duplicates(subset=["CategoryValue"], keep="first")
        out = out.merge(avg_curve, on="CategoryValue", how="left", suffixes=("", "_Curve"))
        rename = {
            "PeakTheta": "CurvePeakTheta",
            "PeakProbability": "CurvePeakProbability",
            "IsEverMostProbable": "CurveEverMostProbable",
            "DominantThetaMin": "CurveDominantThetaMin",
            "DominantThetaMax": "CurveDominantThetaMax",
            "DominantWidth": "CurveDominantWidth",
            "ReviewFlag": "CurveReviewFlag",
        }
        out = out.rename(columns={old: new for old, new in rename.items() if old in out.columns})

    statuses: list[str] = []
    summaries: list[str] = []
    for _, row in out.iterrows():
        signals: list[str] = []
        count = pd.to_numeric(pd.Series([row.get("Count")]), errors="coerce").iloc[0]
        if np.isfinite(count):
            if count == 0:
                signals.append("unused observed category")
            elif count < 10:
                signals.append("count below 10")
        if bool(row.get("InfitFlag")) if pd.notna(row.get("InfitFlag")) else False:
            signals.append("category Infit outside 0.5-1.5")
        if bool(row.get("OutfitFlag")) if pd.notna(row.get("OutfitFlag")) else False:
            signals.append("category Outfit outside 0.5-1.5")
        if bool(row.get("ZSTDFlag")) if pd.notna(row.get("ZSTDFlag")) else False:
            signals.append("category |ZSTD| >= 2")
        ever = row.get("CurveEverMostProbable")
        if pd.notna(ever) and not bool(ever):
            signals.append("no modeled dominance region")
        peak = pd.to_numeric(pd.Series([row.get("CurvePeakProbability")]), errors="coerce").iloc[0]
        if np.isfinite(peak) and peak < 0.35:
            signals.append("weak category-curve peak")
        statuses.append("Review" if signals else "OK")
        summaries.append("; ".join(signals) if signals else "Counts, fit, and averaged curve evidence do not flag this category.")
    out["CategoryEvidenceStatus"] = statuses
    out["EvidenceSummary"] = summaries

    preferred = [
        "Category",
        "CategoryEvidenceStatus",
        "EvidenceSummary",
        "Count",
        "Percent",
        "AvgPersonMeasure",
        "ExpectedAverage",
        "Infit",
        "Outfit",
        "InfitZSTD",
        "OutfitZSTD",
        "CurvePeakTheta",
        "CurvePeakProbability",
        "CurveEverMostProbable",
        "CurveDominantThetaMin",
        "CurveDominantThetaMax",
        "CurveDominantWidth",
        "CurveReviewFlag",
    ]
    return out.loc[:, [col for col in preferred if col in out.columns]]


def rating_scale_functioning_dashboard(result: dict, diagnostics: dict) -> pd.DataFrame:
    """Integrate category counts, thresholds, and curves into one review table."""
    rows: list[dict[str, str]] = []
    obs_df = diagnostics.get("obs", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()
    cat_tbl = pd.DataFrame()
    cat_error = ""
    if isinstance(obs_df, pd.DataFrame) and not obs_df.empty:
        try:
            cat_tbl = calc_category_stats(obs_df, result)
        except Exception as exc:
            cat_error = str(exc)
            try:
                cat_tbl = calc_category_stats(obs_df, None)
                cat_error = ""
            except Exception:
                pass

    if isinstance(cat_tbl, pd.DataFrame) and not cat_tbl.empty:
        counts = pd.to_numeric(cat_tbl.get("Count", pd.Series(dtype=float)), errors="coerce")
        min_count = float(counts.min()) if counts.notna().any() else np.nan
        unused = cat_tbl.loc[counts.fillna(0) == 0, "Category"] if "Category" in cat_tbl.columns else pd.Series(dtype=object)
        low = cat_tbl.loc[(counts < 10) & (counts > 0), "Category"] if "Category" in cat_tbl.columns else pd.Series(dtype=object)
        review = bool((counts < 10).fillna(False).any())
        rows.append(_rating_scale_dashboard_row(
            "Observed category support",
            _rating_scale_status_from_flags(review=review),
            (
                f"minimum count = {min_count:.0f}; "
                f"unused = {_compact_value_list(unused)}; low nonzero count = {_compact_value_list(low)}"
                if np.isfinite(min_count) else
                "category counts unavailable"
            ),
            "Sparse or unused categories are weak evidence for stable thresholds and distinct category functioning.",
            "Inspect raw category use; collapse only with rubric justification and rerun the model.",
            "Categories/Steps: category diagnostics",
        ))

        avg_tbl = cat_tbl.dropna(subset=["AvgPersonMeasure"]).sort_values("Category") if "AvgPersonMeasure" in cat_tbl.columns else pd.DataFrame()
        if len(avg_tbl) >= 2:
            avg_ok = bool(avg_tbl["AvgPersonMeasure"].is_monotonic_increasing)
            rows.append(_rating_scale_dashboard_row(
                "Average measures by category",
                _rating_scale_status_from_flags(review=not avg_ok),
                "average person measures increase with category" if avg_ok else "average person measures are not monotonic",
                "Non-monotonic average measures mean observed categories do not follow the intended ordinal ordering.",
                "Review the adjacent categories where ordering fails before reporting the rating scale as ordered.",
                "Categories/Steps: average person measures",
            ))
        else:
            rows.append(_rating_scale_dashboard_row(
                "Average measures by category",
                "Missing",
                "fewer than two non-missing average-measure rows",
                "Average-measure ordering cannot be checked from the current diagnostic table.",
                "Confirm category support and rerun diagnostics if this was unexpected.",
                "Categories/Steps: average person measures",
            ))

        if "DiffPercent" in cat_tbl.columns:
            diff = pd.to_numeric(cat_tbl["DiffPercent"], errors="coerce")
            diff_bad = cat_tbl.loc[diff.abs() >= 5, "Category"] if "Category" in cat_tbl.columns else pd.Series(dtype=object)
            rows.append(_rating_scale_dashboard_row(
                "Observed vs expected category use",
                _rating_scale_status_from_flags(review=not diff_bad.empty),
                f"categories with absolute observed-expected difference >= 5 percentage points: {_compact_value_list(diff_bad)}",
                "Large marginal differences are corroborating evidence, not an automatic recoding rule.",
                "Read with residual fit and category curves before changing category labels.",
                "Categories/Steps: expected category counts",
            ))

        fit_flags = pd.Series(False, index=cat_tbl.index)
        for flag_col in ("InfitFlag", "OutfitFlag", "ZSTDFlag"):
            if flag_col in cat_tbl.columns:
                fit_flags = fit_flags | cat_tbl[flag_col].fillna(False).astype(bool)
        fit_bad = cat_tbl.loc[fit_flags, "Category"] if "Category" in cat_tbl.columns else pd.Series(dtype=object)
        rows.append(_rating_scale_dashboard_row(
            "Category fit residuals",
            _rating_scale_status_from_flags(review=not fit_bad.empty),
            f"categories with category-level fit flags: {_compact_value_list(fit_bad)}",
            "Category fit flags show noisy or overly predictable response patterns within a score category.",
            "Inspect category rows and response patterns; do not collapse categories from fit alone.",
            "Categories/Steps: Infit, Outfit, ZSTD",
        ))
    else:
        rows.append(_rating_scale_dashboard_row(
            "Observed category support",
            "Missing",
            f"category table unavailable. {cat_error}".strip(),
            "The rating-scale evidence chain cannot be completed without category diagnostics.",
            "Rerun diagnostics and confirm the response-data audit.",
            "Categories/Steps: category diagnostics",
        ))

    step_order = pd.DataFrame()
    try:
        step_order = calc_step_order(result.get("steps", pd.DataFrame()))
    except Exception:
        step_order = pd.DataFrame()
    if isinstance(step_order, pd.DataFrame) and not step_order.empty:
        ordered_col = step_order.get("Ordered", pd.Series(dtype=object))
        disordered = step_order.loc[ordered_col == False]
        spacing = pd.to_numeric(step_order.get("Spacing", pd.Series(dtype=float)), errors="coerce").dropna()
        spacing_text = (
            f"spacing range = {float(spacing.min()):.2f} to {float(spacing.max()):.2f} logits"
            if not spacing.empty else
            "single threshold or no adjacent spacing"
        )
        disordered_labels = (
            disordered.apply(lambda r: f"{r.get('StepFacet', 'Common')}:{r.get('Step', '')}", axis=1)
            if not disordered.empty else []
        )
        rows.append(_rating_scale_dashboard_row(
            "Threshold / step ordering",
            _rating_scale_status_from_flags(review=not disordered.empty),
            f"{spacing_text}; disordered = {_compact_value_list(disordered_labels)}",
            "Disordered thresholds weaken claims that adjacent categories are functioning as separate ordered levels.",
            "Use the FACETS-style threshold lines and Categories/Steps order table before collapsing categories.",
            "Categories/Steps: step order; Visuals: threshold lines",
        ))
    else:
        rows.append(_rating_scale_dashboard_row(
            "Threshold / step ordering",
            "Missing",
            "step threshold table unavailable",
            "Threshold order cannot be checked without fitted step parameters.",
            "Confirm model estimation and step-facet settings.",
            "Categories/Steps: step order",
        ))

    curve_diag = category_curve_diagnostic_scope_table(result)
    if isinstance(curve_diag, pd.DataFrame) and not curve_diag.empty:
        review_flags = curve_diag["ReviewFlag"].astype(str).str.startswith("Review") if "ReviewFlag" in curve_diag.columns else pd.Series(False, index=curve_diag.index)
        no_dom = curve_diag.loc[curve_diag.get("IsEverMostProbable", pd.Series(dtype=bool)) == False]
        weak = curve_diag.loc[review_flags]
        no_dom_labels = (
            no_dom["CurveLabel"].astype(str) + " / " + no_dom["Category"].astype(str)
            if not no_dom.empty and {"CurveLabel", "Category"}.issubset(no_dom.columns) else []
        )
        weak_labels = (
            weak["CurveLabel"].astype(str) + " / " + weak["Category"].astype(str)
            if not weak.empty and {"CurveLabel", "Category"}.issubset(weak.columns) else []
        )
        rows.append(_rating_scale_dashboard_row(
            "Category characteristic curves",
            _rating_scale_status_from_flags(review=not no_dom.empty or not weak.empty),
            (
                f"scopes scanned = {curve_diag['CurveLabel'].nunique() if 'CurveLabel' in curve_diag.columns else 1}; "
                f"no dominance = {_compact_value_list(no_dom_labels)}; weak peaks = {_compact_value_list(weak_labels)}"
            ),
            "A category without a modeled dominance region should not be reported as clearly distinct without corroborating evidence.",
            "Compare curve flags with counts, average measures, and threshold order before recommending recoding.",
            "Visuals: Category Probability Curves",
        ))
    else:
        rows.append(_rating_scale_dashboard_row(
            "Category characteristic curves",
            "Missing",
            "category characteristic curve diagnostics unavailable",
            "Curve-based peak/dominance evidence is absent from the current run.",
            "Open Visuals or verify that fitted thresholds are available.",
            "Visuals: Category Probability Curves",
        ))

    slopes = result.get("slopes", pd.DataFrame()) if isinstance(result, dict) else pd.DataFrame()
    if isinstance(slopes, pd.DataFrame) and not slopes.empty and "Slope" in slopes.columns:
        slope_vals = pd.to_numeric(slopes["Slope"], errors="coerce").dropna()
        if len(slope_vals):
            min_slope = float(slope_vals.min())
            max_slope = float(slope_vals.max())
            ratio = max_slope / min_slope if min_slope > 0 else np.inf
            review = bool(min_slope < 0.25 or max_slope > 4.0 or ratio > 4.0)
            rows.append(_rating_scale_dashboard_row(
                "GPCM slope spread",
                _rating_scale_status_from_flags(review=review),
                f"slope range = {min_slope:.3f} to {max_slope:.3f}; max/min ratio = {ratio:.2f}",
                "Slope changes curve steepness and local information; it is not ordinary facet severity.",
                "Report slope differences separately from measure differences and check level-specific curves.",
                "Categories/Steps: slopes; Visuals: level-specific curves",
            ))

    out = pd.DataFrame(rows)
    if out.empty:
        return out
    review_count = int((out["Status"] == "Review").sum())
    missing_count = int((out["Status"] == "Missing").sum())
    overall_status = "Review" if review_count else ("Missing" if missing_count == len(out) else "OK")
    overall = _rating_scale_dashboard_row(
        "Overall rating-scale decision",
        overall_status,
        f"{review_count} review row(s); {missing_count} missing row(s); {len(out)} evidence row(s)",
        "This is a triage summary. It preserves details but does not replace substantive rubric review.",
        (
            "Resolve review rows before claiming that all categories function distinctly."
            if review_count else
            "Report the supporting evidence and keep the diagnostic thresholds visible."
        ),
        "Integrated dashboard",
    )
    return pd.concat([pd.DataFrame([overall]), out], ignore_index=True)


def rating_scale_decision_support_table(result: dict, diagnostics: dict) -> pd.DataFrame:
    """Translate rating-scale diagnostics into conservative reporting decisions."""
    dashboard = rating_scale_functioning_dashboard(result, diagnostics)
    if not isinstance(dashboard, pd.DataFrame) or dashboard.empty:
        return pd.DataFrame([_rating_scale_decision_row(
            "Overall reportability",
            "Missing evidence",
            "not available",
            "Rating-scale dashboard could not be generated.",
            "Rerun diagnostics and confirm that observed responses, fitted thresholds, and curve data are available.",
            "Do not compare recoding candidates until the original rating-scale diagnostics are available.",
            "Rating-scale functioning was not evaluated in this run.",
            "Do not claim that the rating scale functions as intended without category, threshold, and curve evidence.",
        )])

    category_evidence = rating_scale_category_evidence_table(result, diagnostics)
    review_rows = dashboard.loc[dashboard["Status"].astype(str) == "Review"].copy()
    missing_rows = dashboard.loc[dashboard["Status"].astype(str) == "Missing"].copy()
    review_checks = _compact_value_list(review_rows["Check"].tolist()) if not review_rows.empty else "none"
    missing_checks = _compact_value_list(missing_rows["Check"].tolist()) if not missing_rows.empty else "none"

    affected_categories = "none"
    category_summaries = "none"
    if isinstance(category_evidence, pd.DataFrame) and not category_evidence.empty:
        cat_review = category_evidence.loc[
            category_evidence["CategoryEvidenceStatus"].astype(str) == "Review"
        ].copy()
        if not cat_review.empty:
            affected_categories = _compact_value_list(cat_review.get("Category", pd.Series(dtype=object)).tolist())
            category_summaries = _compact_value_list(cat_review.get("EvidenceSummary", pd.Series(dtype=object)).tolist(), max_items=5)

    step_order = pd.DataFrame()
    try:
        step_order = calc_step_order(result.get("steps", pd.DataFrame()))
    except Exception:
        step_order = pd.DataFrame()
    disordered_labels = "none"
    if isinstance(step_order, pd.DataFrame) and not step_order.empty:
        disordered = step_order.loc[step_order.get("Ordered", pd.Series(dtype=object)) == False]
        if not disordered.empty:
            labels = disordered.apply(lambda r: f"{r.get('StepFacet', 'Common')}:{r.get('Step', '')}", axis=1)
            disordered_labels = _compact_value_list(labels.tolist())

    curve_diag = category_curve_diagnostic_scope_table(result)
    curve_labels = "none"
    if isinstance(curve_diag, pd.DataFrame) and not curve_diag.empty:
        review_flags = (
            curve_diag["ReviewFlag"].astype(str).str.startswith("Review")
            if "ReviewFlag" in curve_diag.columns else
            pd.Series(False, index=curve_diag.index)
        )
        curve_review = curve_diag.loc[
            review_flags | (curve_diag.get("IsEverMostProbable", pd.Series(dtype=bool)) == False)
        ]
        if not curve_review.empty and {"CurveLabel", "Category"}.issubset(curve_review.columns):
            curve_labels = _compact_value_list(
                (curve_review["CurveLabel"].astype(str) + " / " + curve_review["Category"].astype(str)).tolist(),
                max_items=10,
            )

    has_review = not review_rows.empty
    has_missing = not missing_rows.empty
    overall_status = "Do not claim yet" if has_review else ("Missing evidence" if has_missing else "Ready")
    safe_overall = (
        "The rating-scale diagnostics flagged review evidence; report the affected categories and withhold any claim that all categories function distinctly."
        if has_review else
        "Some rating-scale diagnostics were missing; report only the evidence that is available."
        if has_missing else
        "The rating-scale dashboard did not flag category counts, threshold order, category curves, fit, or slope evidence."
    )
    rerun_review = (
        "Fit the original scoring and each substantively justified adjacent-category recode; compare convergence, global fit, reliability, "
        "category dashboard, threshold order, category curves, and key facet measures before choosing a scoring rule."
    )
    rows = [
        _rating_scale_decision_row(
            "Overall reportability",
            overall_status,
            affected_categories,
            f"review checks: {review_checks}; missing checks: {missing_checks}; category issues: {category_summaries}",
            (
                "Resolve review rows before making final rating-scale claims."
                if has_review else
                "Document missing evidence before final reporting."
                if has_missing else
                "Report the dashboard evidence and keep thresholds and category curves visible."
            ),
            rerun_review if has_review else "No recoding comparison is indicated by the current dashboard.",
            safe_overall,
            "Do not state that all categories function distinctly unless counts, average measures, thresholds, and category curves support that claim.",
        )
    ]

    rows.append(_rating_scale_decision_row(
        "Potential recoding scope",
        "Review before reporting" if affected_categories != "none" or disordered_labels != "none" or curve_labels != "none" else "Ready",
        affected_categories,
        f"category evidence: {category_summaries}; disordered thresholds: {disordered_labels}; curve flags: {curve_labels}",
        (
            "Treat adjacent collapse as a candidate sensitivity analysis only when it is defensible from the rubric and response process."
            if affected_categories != "none" or disordered_labels != "none" or curve_labels != "none" else
            "No category collapse candidate is suggested by the current integrated diagnostics."
        ),
        rerun_review if affected_categories != "none" or disordered_labels != "none" or curve_labels != "none" else "Keep the original scoring as the primary run unless theory suggests a planned sensitivity analysis.",
        (
            "A recoded scale, if evaluated, was treated as a sensitivity comparison rather than an automatic correction."
            if affected_categories != "none" or disordered_labels != "none" or curve_labels != "none" else
            "The original category structure was retained because no integrated diagnostic row required recoding review."
        ),
        "Do not collapse categories solely because one diagnostic is flagged; require rubric logic plus better reproduced diagnostics.",
    ))

    rows.append(_rating_scale_decision_row(
        "Threshold and step-order claim",
        "Review before reporting" if disordered_labels != "none" else ("Missing evidence" if "Threshold / step ordering" in missing_checks else "Ready"),
        disordered_labels,
        f"step order review labels: {disordered_labels}",
        (
            "Use the step-order table and FACETS-style threshold lines to identify the affected boundary before reporting ordered thresholds."
            if disordered_labels != "none" else
            "Report threshold order together with step spacing and the plotted threshold lines."
        ),
        rerun_review if disordered_labels != "none" else "No step-order driven recoding comparison is indicated.",
        (
            "Threshold ordering was not fully supported for the affected boundaries."
            if disordered_labels != "none" else
            "Thresholds were checked in the fitted step-order table and visualized as step boundary lines."
        ),
        "Do not state that thresholds advance in the intended order when any fitted step boundary is disordered or unavailable.",
    ))

    rows.append(_rating_scale_decision_row(
        "Category-curve distinctness claim",
        "Review before reporting" if curve_labels != "none" else ("Missing evidence" if "Category characteristic curves" in missing_checks else "Ready"),
        curve_labels,
        f"category-curve review labels: {curve_labels}",
        (
            "Inspect the category probability curves for peak height and dominance region, then cross-check the same category in counts and fit."
            if curve_labels != "none" else
            "Report curve peak and dominance evidence as a visual diagnostic, not as standalone proof."
        ),
        rerun_review if curve_labels != "none" else "No curve-driven recoding comparison is indicated.",
        (
            "Distinct category functioning was not established for every category-curve scope."
            if curve_labels != "none" else
            "Each available category-curve diagnostic had a modeled dominance region and no weak-peak review flag."
        ),
        "Do not claim that a category is distinct when its curve never dominates or has a weak peak without corroborating evidence.",
    ))

    return pd.DataFrame(rows)


def _rating_scale_category_values(result: dict, category_evidence: pd.DataFrame | None = None) -> list[float]:
    prep = result.get("prep", {}) if isinstance(result, dict) else {}
    config = result.get("config", {}) if isinstance(result, dict) else {}
    rating_min = pd.to_numeric(pd.Series([prep.get("rating_min")]), errors="coerce").iloc[0]
    rating_max = pd.to_numeric(pd.Series([prep.get("rating_max")]), errors="coerce").iloc[0]
    if not np.isfinite(rating_max):
        n_cat = pd.to_numeric(pd.Series([config.get("n_cat")]), errors="coerce").iloc[0]
        if np.isfinite(rating_min) and np.isfinite(n_cat):
            rating_max = rating_min + int(n_cat) - 1
    if np.isfinite(rating_min) and np.isfinite(rating_max) and rating_max >= rating_min:
        return [float(v) for v in np.arange(int(rating_min), int(rating_max) + 1)]
    if isinstance(category_evidence, pd.DataFrame) and not category_evidence.empty and "Category" in category_evidence.columns:
        vals = pd.to_numeric(category_evidence["Category"], errors="coerce").dropna().unique()
        return sorted(float(v) for v in vals)
    return []


def _format_rating_category_value(value: object) -> str:
    val = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
    if np.isfinite(val):
        return str(int(val)) if float(val).is_integer() else f"{float(val):.3g}"
    return str(value)


def _rating_scale_recode_mapping(
    categories: list[float],
    lower: float | None = None,
    upper: float | None = None,
) -> list[tuple[float, float]]:
    if not categories:
        return []
    if lower is None or upper is None:
        return [(cat, cat) for cat in categories]
    try:
        upper_index = categories.index(upper)
    except ValueError:
        return []
    mapping: list[tuple[float, float]] = []
    for idx, cat in enumerate(categories):
        if cat == upper:
            new_cat = lower
        elif idx > upper_index:
            new_cat = categories[idx - 1]
        else:
            new_cat = cat
        mapping.append((cat, new_cat))
    return mapping


def _rating_scale_recode_map_text(categories: list[float], lower: float | None = None, upper: float | None = None) -> str:
    mapping = _rating_scale_recode_mapping(categories, lower, upper)
    if not mapping:
        return "not available"
    return "; ".join(
        f"{_format_rating_category_value(old)} -> {_format_rating_category_value(new)}"
        for old, new in mapping
    )


def _rating_scale_pair_key(lower: float, upper: float) -> str:
    return f"{_format_rating_category_value(lower)}|{_format_rating_category_value(upper)}"


def rating_scale_recode_candidate_table(result: dict, diagnostics: dict) -> pd.DataFrame:
    """Build adjacent-category recoding candidates for sensitivity comparisons."""
    category_evidence = rating_scale_category_evidence_table(result, diagnostics)
    categories = _rating_scale_category_values(result, category_evidence)
    comparison_metrics = (
        "convergence, log likelihood/AIC when comparable, global residual fit, person reliability, "
        "category dashboard, threshold order, category curves, and key facet-measure shifts"
    )
    if len(categories) < 2:
        return pd.DataFrame([{
            "CandidateID": "BASE",
            "AnalysisRole": "Original scoring baseline",
            "AdjacentBoundary": "not available",
            "CollapsedOriginalCategories": "none",
            "OriginalToCandidateScoreMap": _rating_scale_recode_map_text(categories),
            "Priority": "Missing evidence",
            "TriggerEvidence": "Fewer than two rating categories were available for adjacent-category planning.",
            "RequiredSubstantiveJustification": "Confirm the score scale and category diagnostics before considering recoding.",
            "RerunComparisonPlan": "Do not run recoding comparisons until the original scale is identified.",
            "ReportingBoundary": "Do not report category-collapse sensitivity analysis without a valid original scoring baseline.",
        }])

    category_issue_map: dict[float, list[str]] = {}
    if isinstance(category_evidence, pd.DataFrame) and not category_evidence.empty:
        for _, row in category_evidence.iterrows():
            status = str(row.get("CategoryEvidenceStatus", ""))
            cat = pd.to_numeric(pd.Series([row.get("Category")]), errors="coerce").iloc[0]
            if status == "Review" and np.isfinite(cat):
                category_issue_map.setdefault(float(cat), []).append(str(row.get("EvidenceSummary", "category review flag")))

    curve_issue_map: dict[float, list[str]] = {}
    curve_diag = category_curve_diagnostic_scope_table(result)
    if isinstance(curve_diag, pd.DataFrame) and not curve_diag.empty:
        review_flags = (
            curve_diag["ReviewFlag"].astype(str).str.startswith("Review")
            if "ReviewFlag" in curve_diag.columns else
            pd.Series(False, index=curve_diag.index)
        )
        curve_review = curve_diag.loc[
            review_flags | (curve_diag.get("IsEverMostProbable", pd.Series(dtype=bool)) == False)
        ]
        for _, row in curve_review.iterrows():
            cat = pd.to_numeric(pd.Series([row.get("CategoryValue", row.get("Category"))]), errors="coerce").iloc[0]
            if not np.isfinite(cat):
                continue
            label = str(row.get("CurveLabel", "category curve"))
            flag = str(row.get("ReviewFlag", "curve review flag"))
            curve_issue_map.setdefault(float(cat), []).append(f"{label}: {flag}")

    boundary_issue_map: dict[str, list[str]] = {}
    try:
        step_order = calc_step_order(result.get("steps", pd.DataFrame()))
    except Exception:
        step_order = pd.DataFrame()
    rating_min = categories[0]
    if isinstance(step_order, pd.DataFrame) and not step_order.empty:
        disordered = step_order.loc[step_order.get("Ordered", pd.Series(dtype=object)) == False]
        for _, row in disordered.iterrows():
            step_index = pd.to_numeric(pd.Series([row.get("StepIndex")]), errors="coerce").iloc[0]
            if not np.isfinite(step_index):
                continue
            lower = float(rating_min + int(step_index) - 1)
            upper = float(lower + 1)
            key = _rating_scale_pair_key(lower, upper)
            if lower in categories and upper in categories:
                boundary_issue_map.setdefault(key, []).append(
                    f"{row.get('StepFacet', 'Common')}:{row.get('Step', '')} disordered"
                )

    candidate_pairs: set[tuple[float, float]] = set()
    for idx in range(len(categories) - 1):
        lower = categories[idx]
        upper = categories[idx + 1]
        key = _rating_scale_pair_key(lower, upper)
        if lower in category_issue_map or upper in category_issue_map or lower in curve_issue_map or upper in curve_issue_map or key in boundary_issue_map:
            candidate_pairs.add((lower, upper))

    rows: list[dict[str, str]] = [{
        "CandidateID": "BASE",
        "AnalysisRole": "Original scoring baseline",
        "AdjacentBoundary": "none",
        "CollapsedOriginalCategories": "none",
        "OriginalToCandidateScoreMap": _rating_scale_recode_map_text(categories),
        "Priority": "Required baseline",
        "TriggerEvidence": "Keep this run as the primary reference for every recoding sensitivity comparison.",
        "RequiredSubstantiveJustification": "The original rubric and score labels remain the default unless diagnostics and substantive review justify a candidate recode.",
        "RerunComparisonPlan": f"Compare every candidate against this baseline using {comparison_metrics}.",
        "ReportingBoundary": "Do not replace the original scoring rule without documenting why the candidate improves reproducibility and interpretability.",
    }]

    if not candidate_pairs:
        rows.append({
            "CandidateID": "NO_CANDIDATE",
            "AnalysisRole": "No recoding candidate suggested",
            "AdjacentBoundary": "none",
            "CollapsedOriginalCategories": "none",
            "OriginalToCandidateScoreMap": _rating_scale_recode_map_text(categories),
            "Priority": "No dashboard trigger",
            "TriggerEvidence": "Integrated category, threshold, and curve diagnostics did not identify an adjacent-category recoding candidate.",
            "RequiredSubstantiveJustification": "Do not recode only to simplify the scale; preserve the original scoring unless the rubric or response process requires a planned sensitivity run.",
            "RerunComparisonPlan": "No recoding comparison is indicated by the current diagnostic evidence.",
            "ReportingBoundary": "Report the original category diagnostics and retain the original scoring.",
        })
        return pd.DataFrame(rows)

    for idx, (lower, upper) in enumerate(sorted(candidate_pairs), start=1):
        key = _rating_scale_pair_key(lower, upper)
        trigger_parts: list[str] = []
        for cat in (lower, upper):
            if cat in category_issue_map:
                trigger_parts.append(f"category {_format_rating_category_value(cat)}: {_compact_value_list(category_issue_map[cat], max_items=3)}")
            if cat in curve_issue_map:
                trigger_parts.append(f"curve {_format_rating_category_value(cat)}: {_compact_value_list(curve_issue_map[cat], max_items=3)}")
        if key in boundary_issue_map:
            trigger_parts.append(f"boundary {key}: {_compact_value_list(boundary_issue_map[key], max_items=3)}")
        trigger_text = "; ".join(trigger_parts) if trigger_parts else "adjacent category review"
        score = 0
        score += 3 if key in boundary_issue_map else 0
        score += sum(1 for cat in (lower, upper) if cat in category_issue_map)
        score += sum(1 for cat in (lower, upper) if cat in curve_issue_map)
        priority = "High" if score >= 4 else ("Medium" if score >= 2 else "Low")
        rows.append({
            "CandidateID": f"C{idx:02d}",
            "AnalysisRole": "Sensitivity comparison candidate",
            "AdjacentBoundary": key,
            "CollapsedOriginalCategories": f"{_format_rating_category_value(lower)} + {_format_rating_category_value(upper)}",
            "OriginalToCandidateScoreMap": _rating_scale_recode_map_text(categories, lower, upper),
            "Priority": priority,
            "TriggerEvidence": trigger_text,
            "RequiredSubstantiveJustification": (
                "Document why these adjacent rubric levels are not empirically or substantively separable; "
                "do not use the candidate if the two score labels represent distinct construct evidence."
            ),
            "RerunComparisonPlan": (
                "Create a recoded score column from the map, keep all persons/facets/rows/settings unchanged, "
                f"refit the model, and compare {comparison_metrics}."
            ),
            "ReportingBoundary": (
                "Report as a sensitivity analysis unless the recoded model is substantively justified and "
                "diagnostically stronger without distorting key facet measures."
            ),
        })
    return pd.DataFrame(rows)


def category_collapse_action_center_table(result: dict, diagnostics: dict) -> pd.DataFrame:
    """First-read action plan for category-collapse sensitivity decisions."""
    candidates = rating_scale_recode_candidate_table(result, diagnostics)
    decision_support = rating_scale_decision_support_table(result, diagnostics)
    dashboard = rating_scale_functioning_dashboard(result, diagnostics)
    category_evidence = rating_scale_category_evidence_table(result, diagnostics)

    def _decision_value(area: str, col: str, default: str = "not available") -> str:
        if not isinstance(decision_support, pd.DataFrame) or decision_support.empty:
            return default
        if "DecisionArea" not in decision_support.columns:
            return default
        hit = decision_support.loc[decision_support["DecisionArea"].astype(str) == area]
        if hit.empty or col not in hit.columns:
            return default
        return str(hit.iloc[0].get(col, default))

    review_checks = "none"
    missing_checks = "none"
    if isinstance(dashboard, pd.DataFrame) and not dashboard.empty and {"Status", "Check"}.issubset(dashboard.columns):
        review_checks = _compact_value_list(
            dashboard.loc[dashboard["Status"].astype(str) == "Review", "Check"].tolist()
        )
        missing_checks = _compact_value_list(
            dashboard.loc[dashboard["Status"].astype(str) == "Missing", "Check"].tolist()
        )

    candidate_rows = pd.DataFrame()
    no_candidate = False
    if isinstance(candidates, pd.DataFrame) and not candidates.empty:
        candidate_rows = candidates.loc[
            candidates.get("AnalysisRole", pd.Series(dtype=object)).astype(str) == "Sensitivity comparison candidate"
        ].copy()
        no_candidate = bool(
            candidates.get("CandidateID", pd.Series(dtype=object)).astype(str).eq("NO_CANDIDATE").any()
        )

    affected_categories = _decision_value("Potential recoding scope", "AffectedCategories", "not available")
    overall_status = _decision_value("Overall reportability", "DecisionStatus", "Missing evidence")
    candidate_count = int(len(candidate_rows)) if isinstance(candidate_rows, pd.DataFrame) else 0
    high_count = 0
    if candidate_count and "Priority" in candidate_rows.columns:
        high_count = int(candidate_rows["Priority"].astype(str).eq("High").sum())
    can_report_original = candidate_count == 0 and overall_status == "Ready"

    if candidate_count:
        first_read_status = "Run sensitivity before strong claims"
        first_read_decision = "Candidate recoding requires follow-up"
        first_action = "Review the candidate rows, confirm rubric logic, then refit only defensible adjacent-category maps."
        safe_wording = (
            "Rating-scale diagnostics identified adjacent-category recoding candidates; any collapse was treated as "
            "a sensitivity analysis rather than an automatic correction."
        )
    elif no_candidate and can_report_original:
        first_read_status = "Keep original scale"
        first_read_decision = "No collapse sensitivity indicated"
        first_action = "Retain the original scoring and report the dashboard evidence with ordinary category-functioning caveats."
        safe_wording = (
            "The original category structure was retained because the integrated diagnostics did not identify an "
            "adjacent-category collapse candidate."
        )
    else:
        first_read_status = "Review evidence before reporting"
        first_read_decision = "Collapse decision not ready"
        first_action = "Open the dashboard and category evidence tables before deciding whether any recoding comparison is needed."
        safe_wording = "Rating-scale functioning was reviewed, but category-collapse readiness was not established from the available evidence."

    rows: list[dict[str, object]] = []

    def add_row(
        *,
        step: int,
        area: str,
        candidate_id: str,
        status: str,
        priority: str,
        question: str,
        evidence: str,
        summary: str,
        action: str,
        criterion: str,
        wording: str,
        do_not_claim: str,
        crosswalk: str,
    ) -> None:
        rows.append({
            "Done": False,
            "ActionStep": step,
            "ActionArea": area,
            "CandidateID": candidate_id,
            "Status": status,
            "Priority": priority,
            "PrimaryQuestion": question,
            "EvidenceToOpen": evidence,
            "EvidenceSummary": summary,
            "RecommendedAction": action,
            "CompletionCriterion": criterion,
            "ReportReadyWording": wording,
            "DoNotClaim": do_not_claim,
            "SuggestedCitations": "(Linacre, 2002b; Wind, 2023)",
            "FACETSCrosswalk": crosswalk,
        })

    add_row(
        step=1,
        area="First-read category-collapse gate",
        candidate_id="ALL",
        status=first_read_status,
        priority="High" if candidate_count or overall_status == "Do not claim yet" else "Normal",
        question="Can the original rating categories be reported as functioning distinctly?",
        evidence="rating_scale_functioning_dashboard.csv; rating_scale_decision_support.csv; rating_scale_category_evidence.csv",
        summary=(
            f"overall status: {overall_status}; review checks: {review_checks}; "
            f"missing checks: {missing_checks}; candidate count: {candidate_count}; high-priority candidates: {high_count}"
        ),
        action=first_action,
        criterion=(
            "A report-ready category claim is allowed only when review rows are resolved or explicitly caveated, "
            "and any recoding candidate has a documented baseline comparison."
        ),
        wording=safe_wording,
        do_not_claim="Do not state that category collapse is warranted before the recoded model has been refit and compared with the original scoring.",
        crosswalk="FACETS Categories/Steps; Table 6 threshold map; category probability curves",
    )

    add_row(
        step=2,
        area="Original scoring baseline",
        candidate_id="BASE",
        status="Required baseline",
        priority="High",
        question="What is the primary scoring rule before sensitivity comparisons?",
        evidence="rating_scale_recode_candidates.csv; rating_scale_recode_map_long.csv",
        summary="The original score scale is the reference run for every candidate comparison.",
        action="Archive the original run tables before creating any recoded score column.",
        criterion="Original scoring output is retained and can be compared against every candidate refit.",
        wording="The original scoring rule was retained as the baseline for category-collapse sensitivity checks.",
        do_not_claim="Do not overwrite the original score column or treat a recoded scale as primary without an archived baseline.",
        crosswalk="FACETS original scorefile and Categories/Steps output",
    )

    if candidate_count:
        for idx, (_, cand) in enumerate(candidate_rows.iterrows(), start=3):
            candidate_id = str(cand.get("CandidateID", f"C{idx - 2:02d}"))
            priority = str(cand.get("Priority", "Medium"))
            collapsed = str(cand.get("CollapsedOriginalCategories", "adjacent categories"))
            add_row(
                step=idx,
                area=f"Candidate {candidate_id}: collapse {collapsed}",
                candidate_id=candidate_id,
                status="Sensitivity run needed",
                priority=priority,
                question="Do these adjacent rubric levels represent empirically and substantively separable performance?",
                evidence="rating_scale_recode_candidates.csv; rating_scale_recode_map_long.csv; category_diagnostics.csv; steps.csv",
                summary=str(cand.get("TriggerEvidence", "adjacent category review")),
                action=(
                    "Create the candidate score column, refit the same model/design, and compare convergence, "
                    "fit, reliability, threshold order, category curves, and key facet-measure shifts."
                ),
                criterion=(
                    "Candidate is reported only if rubric documentation supports the collapse and the refit improves "
                    "or clarifies diagnostics without distorting substantively important measures."
                ),
                wording=(
                    f"If evaluated, adjacent categories {collapsed} were collapsed only for a sensitivity comparison; "
                    "the original scoring remained the reference analysis."
                ),
                do_not_claim="Do not present this candidate as a correction from trigger evidence alone.",
                crosswalk="FACETS recoded scorefile rerun; Categories/Steps comparison",
            )
    else:
        add_row(
            step=3,
            area="Candidate sensitivity queue",
            candidate_id="NO_CANDIDATE",
            status="No candidate queued" if no_candidate else "Missing candidate evidence",
            priority="Normal" if no_candidate else "Review",
            question="Is an adjacent-category recode queued for refitting?",
            evidence="rating_scale_recode_candidates.csv",
            summary=(
                "No adjacent-category recoding candidate was suggested by the integrated diagnostics."
                if no_candidate else
                "Candidate evidence was unavailable or could not be generated."
            ),
            action=(
                "Keep the original scoring unless the rubric or response process motivates a planned sensitivity run."
                if no_candidate else
                "Review score support, category diagnostics, and step thresholds before planning recodes."
            ),
            criterion="No recoding comparison is needed unless a substantive rubric review raises a planned candidate.",
            wording=(
                "No adjacent-category collapse sensitivity run was indicated by the current integrated diagnostics."
                if no_candidate else
                "Category-collapse sensitivity evidence was not available from this run."
            ),
            do_not_claim="Do not simplify categories only to reduce the number of score levels.",
            crosswalk="FACETS Categories/Steps",
        )

    unresolved = "none"
    if isinstance(category_evidence, pd.DataFrame) and not category_evidence.empty:
        unresolved = _compact_value_list(
            category_evidence.loc[
                category_evidence["CategoryEvidenceStatus"].astype(str) == "Review",
                "Category",
            ].tolist()
        )
    add_row(
        step=100,
        area="Manuscript wording boundary",
        candidate_id="ALL",
        status="Caveat required" if candidate_count or unresolved != "none" else "Ready",
        priority="High" if candidate_count else "Normal",
        question="What can be written in APA-style reporting?",
        evidence="category_collapse_action_center.csv; apa_category_collapse_sensitivity_draft.md; help_reference_coverage.csv",
        summary=f"affected categories: {affected_categories}; unresolved category rows: {unresolved}",
        action="Use conservative wording and cite the category-functioning references only for the method, not as proof of this dataset.",
        criterion="Every category-collapse statement names the evidence files and avoids treating recoding as automatic.",
        wording=(
            "Category-collapse decisions were treated as sensitivity checks and interpreted with category counts, "
            "average measures, thresholds, curves, fit, and rubric meaning."
        ),
        do_not_claim="Do not claim the original or collapsed scale is valid from category diagnostics alone.",
        crosswalk="FACETS report narrative plus Categories/Steps appendix",
    )

    return pd.DataFrame(rows)


def generate_category_collapse_sensitivity_draft(
    result: dict,
    diagnostics: dict,
    action_center: pd.DataFrame | None = None,
) -> str:
    """Generate conservative manuscript-ready text for category-collapse review."""
    if action_center is None or not isinstance(action_center, pd.DataFrame) or action_center.empty:
        action_center = category_collapse_action_center_table(result, diagnostics)
    candidates = rating_scale_recode_candidate_table(result, diagnostics)
    candidate_rows = pd.DataFrame()
    if isinstance(candidates, pd.DataFrame) and not candidates.empty:
        candidate_rows = candidates.loc[
            candidates.get("AnalysisRole", pd.Series(dtype=object)).astype(str) == "Sensitivity comparison candidate"
        ].copy()
    candidate_count = int(len(candidate_rows)) if isinstance(candidate_rows, pd.DataFrame) else 0
    if candidate_count:
        candidate_text = "; ".join(
            f"{row.get('CandidateID')}: {row.get('CollapsedOriginalCategories')} ({row.get('Priority')})"
            for _, row in candidate_rows.iterrows()
        )
        status_text = (
            f"The app identified {candidate_count} adjacent-category recoding candidate(s): {candidate_text}. "
            "These candidates should be refit as sensitivity analyses only after rubric and response-process review."
        )
    else:
        status_text = (
            "The integrated diagnostics did not queue an adjacent-category recoding candidate, or candidate evidence "
            "was unavailable. The original scoring rule should remain the default unless substantive rubric review "
            "motivates a planned sensitivity analysis."
        )

    first_row = action_center.iloc[0] if isinstance(action_center, pd.DataFrame) and not action_center.empty else pd.Series(dtype=object)
    boundary_row = (
        action_center.loc[action_center["ActionArea"].astype(str) == "Manuscript wording boundary"].iloc[0]
        if isinstance(action_center, pd.DataFrame)
        and not action_center.empty
        and "ActionArea" in action_center.columns
        and action_center["ActionArea"].astype(str).eq("Manuscript wording boundary").any()
        else pd.Series(dtype=object)
    )
    return "\n\n".join([
        "# APA Category-Collapse Sensitivity Draft",
        (
            "This draft is conservative. Replace bracketed study details, verify values against exported tables, "
            "and do not describe a recoded scale as final unless the recoded model was actually fitted and compared."
        ),
        (
            f"First-read decision: {first_row.get('Status', 'not available')}. "
            f"Recommended next action: {first_row.get('RecommendedAction', 'not available')}"
        ),
        status_text,
        (
            "Rating-category functioning was interpreted as converging evidence across observed category counts, "
            "average measures, threshold order, category characteristic curves, category-level fit, and rubric meaning "
            "(Linacre, 2002b; Wind, 2023). These diagnostics were used to decide whether category-collapse sensitivity "
            "analyses were needed; they were not treated as automatic recoding rules."
        ),
        (
            f"Report-ready wording boundary: {boundary_row.get('ReportReadyWording', 'Use caveated wording tied to exported evidence files.')} "
            f"Do not overclaim: {boundary_row.get('DoNotClaim', 'Do not claim category collapse from one diagnostic alone.')}"
        ),
        (
            "For readers familiar with FACETS, use this paragraph alongside the Categories/Steps output, the step-order table, "
            "and any recoded-score refit tables. Archive `category_collapse_action_center.csv`, "
            "`rating_scale_recode_candidates.csv`, `rating_scale_recode_map_long.csv`, and the original run tables."
        ),
    ])


def rating_scale_recode_map_long_table(result: dict, diagnostics: dict) -> pd.DataFrame:
    """Return long-form score maps for each rating-scale recode candidate."""
    candidates = rating_scale_recode_candidate_table(result, diagnostics)
    category_evidence = rating_scale_category_evidence_table(result, diagnostics)
    categories = _rating_scale_category_values(result, category_evidence)
    if not isinstance(candidates, pd.DataFrame) or candidates.empty or not categories:
        return pd.DataFrame()
    rows: list[dict[str, object]] = []
    for _, cand in candidates.iterrows():
        candidate_id = str(cand.get("CandidateID", ""))
        if candidate_id == "NO_CANDIDATE" or not candidate_id:
            continue
        lower = upper = None
        boundary = str(cand.get("AdjacentBoundary", ""))
        if candidate_id != "BASE" and "|" in boundary:
            left, right = boundary.split("|", 1)
            lower_val = pd.to_numeric(pd.Series([left]), errors="coerce").iloc[0]
            upper_val = pd.to_numeric(pd.Series([right]), errors="coerce").iloc[0]
            if np.isfinite(lower_val) and np.isfinite(upper_val):
                lower, upper = float(lower_val), float(upper_val)
        mapping = _rating_scale_recode_mapping(categories, lower, upper)
        if not mapping:
            continue
        map_payload = [
            {
                "OriginalScore": _format_rating_category_value(old),
                "CandidateScore": _format_rating_category_value(new),
            }
            for old, new in mapping
        ]
        fingerprint = stable_json_fingerprint({
            "CandidateID": candidate_id,
            "AdjacentBoundary": boundary,
            "Mapping": map_payload,
        })
        candidate_col = "Score_original" if candidate_id == "BASE" else f"Score_recode_{candidate_id}"
        for old, new in mapping:
            rows.append({
                "CandidateID": candidate_id,
                "AnalysisRole": str(cand.get("AnalysisRole", "")),
                "Priority": str(cand.get("Priority", "")),
                "AdjacentBoundary": boundary,
                "CandidateScoreColumn": candidate_col,
                "OriginalScore": old,
                "CandidateScore": new,
                "CandidateFingerprint": fingerprint,
                "TriggerEvidence": str(cand.get("TriggerEvidence", "")),
                "ReportingBoundary": str(cand.get("ReportingBoundary", "")),
            })
    return pd.DataFrame(rows)


def rating_scale_recode_script_assets(result: dict, diagnostics: dict) -> dict[str, str]:
    """Return Python/R/Julia scripts for applying recode candidate score maps."""
    candidates = rating_scale_recode_candidate_table(result, diagnostics)
    map_long = rating_scale_recode_map_long_table(result, diagnostics)
    config = result.get("config", {}) if isinstance(result, dict) else {}
    prep = result.get("prep", {}) if isinstance(result, dict) else {}
    default_score_col = str(config.get("score_col") or prep.get("score_col") or "Score")
    candidate_count = (
        int(candidates["AnalysisRole"].astype(str).eq("Sensitivity comparison candidate").sum())
        if isinstance(candidates, pd.DataFrame) and not candidates.empty and "AnalysisRole" in candidates.columns else
        0
    )
    readme = f"""# Rating-Scale Recode Candidate Scripts

These files reproduce the score-column transformations implied by the
rating-scale recode candidate table. They do not refit the MFRM by themselves.
Use the generated recoded CSV as input for the Python app-engine runner, R
script, Julia script, or Stan data builder.

Files:
- `mfrm_rating_scale_recode_candidates.csv`: candidate-level decision table.
- `mfrm_rating_scale_recode_map_long.csv`: long score map used by all scripts.
- `apply_rating_scale_recodes.py`: Python/pandas implementation.
- `apply_rating_scale_recodes.R`: base R implementation.
- `apply_rating_scale_recodes.jl`: Julia CSV/DataFrames implementation.

Default score column: `{default_score_col}`
Candidate sensitivity runs listed: {candidate_count}

Important boundaries:
- The original score column is never overwritten.
- `Score_original` is copied from the original score column.
- Candidate columns are named `Score_recode_C01`, `Score_recode_C02`, and so on.
- A candidate is a sensitivity-analysis input, not an automatic scoring rule.
- After creating recoded columns, refit the model separately and compare
  convergence, fit, reliability, threshold order, category curves, and key
  facet-measure shifts against the `BASE` run.

Example:

```bash
MFRM_INPUT_CSV=your_long_data.csv \\
MFRM_SCORE_COL={default_score_col} \\
MFRM_RECODE_MAP_CSV=mfrm_rating_scale_recode_map_long.csv \\
python apply_rating_scale_recodes.py
```
"""

    python_script = r'''#!/usr/bin/env python3
"""Apply MFRM rating-scale recode candidate maps without overwriting scores."""

from __future__ import annotations

import os
from pathlib import Path

import pandas as pd


INPUT_CSV = Path(os.environ.get("MFRM_INPUT_CSV", "input_long.csv")).expanduser()
OUTPUT_CSV = Path(os.environ.get("MFRM_OUTPUT_CSV", "mfrm_recode_candidates_long.csv")).expanduser()
MAP_CSV = Path(os.environ.get("MFRM_RECODE_MAP_CSV", "mfrm_rating_scale_recode_map_long.csv")).expanduser()
SCORE_COL = os.environ.get("MFRM_SCORE_COL", "Score")


def _as_score_column(values: pd.Series) -> pd.Series:
    clean = pd.to_numeric(values, errors="coerce")
    non_missing = clean.dropna()
    if len(non_missing) and (non_missing - non_missing.round()).abs().max() < 1e-9:
        return clean.round().astype("Int64")
    return clean


def main() -> int:
    if not INPUT_CSV.exists():
        raise FileNotFoundError(f"Input CSV not found: {INPUT_CSV}")
    if not MAP_CSV.exists():
        raise FileNotFoundError(f"Recode map CSV not found: {MAP_CSV}")
    data = pd.read_csv(INPUT_CSV)
    recode_map = pd.read_csv(MAP_CSV)
    if SCORE_COL not in data.columns:
        raise KeyError(f"Score column '{SCORE_COL}' was not found in {INPUT_CSV}")
    required = {"CandidateID", "CandidateScoreColumn", "OriginalScore", "CandidateScore", "CandidateFingerprint"}
    missing = sorted(required.difference(recode_map.columns))
    if missing:
        raise KeyError(f"Recode map is missing required columns: {missing}")

    out = data.copy()
    out["Score_original"] = out[SCORE_COL]
    score_numeric = pd.to_numeric(out[SCORE_COL], errors="coerce")
    if score_numeric.isna().any() and out[SCORE_COL].notna().any():
        bad = out.loc[score_numeric.isna() & out[SCORE_COL].notna(), SCORE_COL].head(10).tolist()
        raise ValueError(f"Score column contains non-numeric values, examples: {bad}")

    status_rows = []
    candidate_ids = [
        cid for cid in recode_map["CandidateID"].astype(str).drop_duplicates().tolist()
        if cid not in {"BASE", "NO_CANDIDATE"}
    ]
    for candidate_id in candidate_ids:
        sub = recode_map.loc[recode_map["CandidateID"].astype(str) == candidate_id].copy()
        candidate_col = str(sub["CandidateScoreColumn"].iloc[0])
        mapping = {
            float(row.OriginalScore): float(row.CandidateScore)
            for row in sub.itertuples(index=False)
        }
        mapped = score_numeric.map(mapping)
        unmapped = sorted(score_numeric.loc[score_numeric.notna() & mapped.isna()].drop_duplicates().tolist())
        if unmapped:
            raise ValueError(f"{candidate_id} does not map observed score value(s): {unmapped}")
        out[candidate_col] = _as_score_column(mapped)
        status_rows.append({
            "CandidateID": candidate_id,
            "CandidateScoreColumn": candidate_col,
            "CandidateFingerprint": str(sub["CandidateFingerprint"].iloc[0]),
            "RowsWritten": len(out),
            "SourceScoreColumn": SCORE_COL,
            "OutputCSV": str(OUTPUT_CSV),
            "Status": "applied",
        })

    OUTPUT_CSV.parent.mkdir(parents=True, exist_ok=True)
    out.to_csv(OUTPUT_CSV, index=False)
    pd.DataFrame(status_rows or [{
        "CandidateID": "none",
        "CandidateScoreColumn": "",
        "CandidateFingerprint": "",
        "RowsWritten": len(out),
        "SourceScoreColumn": SCORE_COL,
        "OutputCSV": str(OUTPUT_CSV),
        "Status": "no sensitivity candidate; wrote Score_original only",
    }]).to_csv(OUTPUT_CSV.with_name("mfrm_recode_application_manifest.csv"), index=False)
    print(f"Wrote {OUTPUT_CSV}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
'''

    r_script = r'''#!/usr/bin/env Rscript
# Apply MFRM rating-scale recode candidate maps without overwriting scores.

input_csv <- Sys.getenv("MFRM_INPUT_CSV", "input_long.csv")
output_csv <- Sys.getenv("MFRM_OUTPUT_CSV", "mfrm_recode_candidates_long.csv")
map_csv <- Sys.getenv("MFRM_RECODE_MAP_CSV", "mfrm_rating_scale_recode_map_long.csv")
score_col <- Sys.getenv("MFRM_SCORE_COL", "Score")

if (!file.exists(input_csv)) stop(paste("Input CSV not found:", input_csv))
if (!file.exists(map_csv)) stop(paste("Recode map CSV not found:", map_csv))

dat <- read.csv(input_csv, stringsAsFactors = FALSE, check.names = FALSE)
recode_map <- read.csv(map_csv, stringsAsFactors = FALSE, check.names = FALSE)
if (!(score_col %in% names(dat))) stop(paste("Score column not found:", score_col))
required <- c("CandidateID", "CandidateScoreColumn", "OriginalScore", "CandidateScore", "CandidateFingerprint")
missing <- setdiff(required, names(recode_map))
if (length(missing) > 0) stop(paste("Recode map missing columns:", paste(missing, collapse = ", ")))

dat[["Score_original"]] <- dat[[score_col]]
score_numeric <- suppressWarnings(as.numeric(dat[[score_col]]))
if (any(is.na(score_numeric) & !is.na(dat[[score_col]]))) {
  stop("Score column contains non-numeric values.")
}

candidate_ids <- unique(as.character(recode_map$CandidateID))
candidate_ids <- candidate_ids[!(candidate_ids %in% c("BASE", "NO_CANDIDATE"))]
status <- data.frame()

for (candidate_id in candidate_ids) {
  sub <- recode_map[as.character(recode_map$CandidateID) == candidate_id, , drop = FALSE]
  candidate_col <- as.character(sub$CandidateScoreColumn[1])
  mapping <- setNames(as.numeric(sub$CandidateScore), as.character(as.numeric(sub$OriginalScore)))
  mapped <- mapping[as.character(score_numeric)]
  bad <- unique(score_numeric[!is.na(score_numeric) & is.na(mapped)])
  if (length(bad) > 0) {
    stop(paste(candidate_id, "does not map observed score value(s):", paste(bad, collapse = ", ")))
  }
  dat[[candidate_col]] <- as.numeric(mapped)
  if (all(is.na(dat[[candidate_col]]) | abs(dat[[candidate_col]] - round(dat[[candidate_col]])) < 1e-9)) {
    dat[[candidate_col]] <- as.integer(round(dat[[candidate_col]]))
  }
  status <- rbind(status, data.frame(
    CandidateID = candidate_id,
    CandidateScoreColumn = candidate_col,
    CandidateFingerprint = as.character(sub$CandidateFingerprint[1]),
    RowsWritten = nrow(dat),
    SourceScoreColumn = score_col,
    OutputCSV = output_csv,
    Status = "applied",
    stringsAsFactors = FALSE
  ))
}

if (nrow(status) == 0) {
  status <- data.frame(
    CandidateID = "none",
    CandidateScoreColumn = "",
    CandidateFingerprint = "",
    RowsWritten = nrow(dat),
    SourceScoreColumn = score_col,
    OutputCSV = output_csv,
    Status = "no sensitivity candidate; wrote Score_original only",
    stringsAsFactors = FALSE
  )
}

write.csv(dat, output_csv, row.names = FALSE, na = "")
write.csv(status, file.path(dirname(output_csv), "mfrm_recode_application_manifest.csv"), row.names = FALSE)
cat("Wrote", output_csv, "\n")
'''

    julia_script = r'''#!/usr/bin/env julia
# Apply MFRM rating-scale recode candidate maps without overwriting scores.

using CSV
using DataFrames

input_csv = get(ENV, "MFRM_INPUT_CSV", "input_long.csv")
output_csv = get(ENV, "MFRM_OUTPUT_CSV", "mfrm_recode_candidates_long.csv")
map_csv = get(ENV, "MFRM_RECODE_MAP_CSV", "mfrm_rating_scale_recode_map_long.csv")
score_col = Symbol(get(ENV, "MFRM_SCORE_COL", "Score"))

isfile(input_csv) || error("Input CSV not found: $(input_csv)")
isfile(map_csv) || error("Recode map CSV not found: $(map_csv)")

dat = CSV.read(input_csv, DataFrame)
recode_map = CSV.read(map_csv, DataFrame)
String(score_col) in names(dat) || error("Score column not found: $(String(score_col))")

required = ["CandidateID", "CandidateScoreColumn", "OriginalScore", "CandidateScore", "CandidateFingerprint"]
missing_cols = [col for col in required if !(col in names(recode_map))]
isempty(missing_cols) || error("Recode map missing columns: $(join(missing_cols, \", \"))")

dat[!, :Score_original] = dat[!, score_col]
score_numeric = Vector{Union{Missing, Float64}}(undef, nrow(dat))
for i in 1:nrow(dat)
    raw = dat[i, score_col]
    if ismissing(raw) || raw === nothing || string(raw) == ""
        score_numeric[i] = missing
    else
        parsed = tryparse(Float64, string(raw))
        isnothing(parsed) && error("Score column contains non-numeric value: $(raw)")
        score_numeric[i] = parsed
    end
end

candidate_ids = unique(string.(recode_map.CandidateID))
candidate_ids = [cid for cid in candidate_ids if !(cid in ["BASE", "NO_CANDIDATE"])]
status = DataFrame(
    CandidateID = String[],
    CandidateScoreColumn = String[],
    CandidateFingerprint = String[],
    RowsWritten = Int[],
    SourceScoreColumn = String[],
    OutputCSV = String[],
    Status = String[],
)

for candidate_id in candidate_ids
    sub = recode_map[string.(recode_map.CandidateID) .== candidate_id, :]
    candidate_col = Symbol(string(sub.CandidateScoreColumn[1]))
    mapping = Dict(Float64(row.OriginalScore) => Float64(row.CandidateScore) for row in eachrow(sub))
    mapped = Vector{Union{Missing, Float64}}(missing, nrow(dat))
    bad = Float64[]
    for i in 1:nrow(dat)
        if ismissing(score_numeric[i])
            mapped[i] = missing
        elseif haskey(mapping, score_numeric[i])
            mapped[i] = mapping[score_numeric[i]]
        else
            push!(bad, score_numeric[i])
        end
    end
    isempty(bad) || error("$(candidate_id) does not map observed score value(s): $(join(unique(bad), \", \"))")
    dat[!, candidate_col] = mapped
    push!(status, (
        candidate_id,
        String(candidate_col),
        string(sub.CandidateFingerprint[1]),
        nrow(dat),
        String(score_col),
        output_csv,
        "applied",
    ))
end

if nrow(status) == 0
    push!(status, ("none", "", "", nrow(dat), String(score_col), output_csv, "no sensitivity candidate; wrote Score_original only"))
end

mkpath(dirname(output_csv) == "" ? "." : dirname(output_csv))
CSV.write(output_csv, dat)
CSV.write(joinpath(dirname(output_csv) == "" ? "." : dirname(output_csv), "mfrm_recode_application_manifest.csv"), status)
println("Wrote $(output_csv)")
'''

    return {
        "README_rating_scale_recode_scripts.md": readme,
        "mfrm_rating_scale_recode_candidates.csv": candidates.to_csv(index=False) if isinstance(candidates, pd.DataFrame) else "",
        "mfrm_rating_scale_recode_map_long.csv": map_long.to_csv(index=False) if isinstance(map_long, pd.DataFrame) else "",
        "apply_rating_scale_recodes.py": python_script,
        "apply_rating_scale_recodes.R": r_script,
        "apply_rating_scale_recodes.jl": julia_script,
    }


def category_probability_curve_export_table(result: dict) -> pd.DataFrame:
    """Long-form category curve data for all available curve scopes."""
    options = category_probability_curve_options(result)
    frames = []
    for row in options.itertuples(index=False):
        try:
            is_average = bool(getattr(row, "IsAverage"))
            level_idx = None if is_average else int(getattr(row, "LevelIndex"))
            curve = build_category_probability_curve_data(result, step_level_index=level_idx)
            frame = _category_curve_export_frame(curve, label=getattr(row, "Label"))
            if not frame.empty:
                frames.append(frame)
        except Exception:
            continue
    return pd.concat(frames, ignore_index=True) if frames else pd.DataFrame()


def build_information_curve_data(result: dict, step_level_index: int | None = None) -> dict:
    """Build score-information / conditional-SE curves from category probabilities."""
    curve = build_category_probability_curve_data(result, step_level_index=step_level_index)
    if not isinstance(curve, dict) or not curve.get("available"):
        return {"available": False, "reason": curve.get("reason", "Category curve unavailable.") if isinstance(curve, dict) else "Category curve unavailable."}
    prob = curve.get("probability", pd.DataFrame())
    meta = curve.get("metadata", {})
    if not isinstance(prob, pd.DataFrame) or prob.empty or not isinstance(meta, dict):
        return {"available": False, "reason": "Probability curve is empty."}
    slope = float(meta.get("Slope", 1.0) or 1.0)
    rows = []
    for theta, df in prob.groupby("Theta", observed=False):
        cats = pd.to_numeric(df["CategoryValue"], errors="coerce").to_numpy(dtype=float)
        p = pd.to_numeric(df["Probability"], errors="coerce").to_numpy(dtype=float)
        ok = np.isfinite(cats) & np.isfinite(p)
        if not np.any(ok):
            continue
        cats = cats[ok]
        p = p[ok]
        total = float(np.sum(p))
        if total <= 0:
            continue
        p = p / total
        expected = float(np.sum(p * cats))
        variance = float(np.sum(p * (cats - expected) ** 2))
        information = float((slope ** 2) * variance)
        rows.append({
            "Theta": float(theta),
            "ExpectedScore": expected,
            "ScoreVariance": variance,
            "Information": information,
            "ConditionalSE": 1.0 / np.sqrt(information) if information > 0 else np.nan,
        })
    info = pd.DataFrame(rows)
    if info.empty:
        return {"available": False, "reason": "Information curve could not be computed."}
    info["Scope"] = str(meta.get("Scope", "curve"))
    info["Model"] = str(meta.get("Model", "Model"))
    info["Slope"] = slope
    max_idx = int(info["Information"].idxmax()) if info["Information"].notna().any() else None
    summary = pd.DataFrame([{
        "Scope": str(meta.get("Scope", "curve")),
        "Model": str(meta.get("Model", "Model")),
        "MaxInformation": float(info.loc[max_idx, "Information"]) if max_idx is not None else np.nan,
        "ThetaAtMaxInformation": float(info.loc[max_idx, "Theta"]) if max_idx is not None else np.nan,
        "MinConditionalSE": float(info["ConditionalSE"].min()) if info["ConditionalSE"].notna().any() else np.nan,
        "Interpretation": "Higher information means better local precision; this is a model-based targeting screen.",
    }])
    return {"available": True, "curve": info, "summary": summary, "metadata": meta}


def build_category_information_curve_data(
    result: dict, step_level_index: int | None = None
) -> dict:
    """Per-category contribution to the information curve.

    For each ``theta`` on the curve grid this helper returns the
    contribution of every response category ``k`` to the total Fisher
    information:

        I_k(theta) = a^2 * P_k(theta) * (k - E[X | theta])^2

    where ``a`` is the discrimination (``1`` for RSM and PCM,
    estimated for GPCM under the geometric-mean-one identification),
    ``P_k(theta)`` is the category response probability, and
    ``E[X | theta] = sum_k k * P_k(theta)``. The category-specific
    contributions sum to the total

        sum_k I_k(theta) = a^2 * Var[X | theta] = I(theta)

    so the curves render as a decomposition of the existing
    information-curve total. Reference: Muraki (1993), Applied
    Psychological Measurement 17(4), Eqs. 7, 16.

    The function reuses ``build_category_probability_curve_data`` so
    the slope and step thresholds are read off the fitted model in
    exactly the way the existing total-information curve does;
    callers who pass the same ``step_level_index`` get the matching
    breakdown.
    """
    curve = build_category_probability_curve_data(
        result, step_level_index=step_level_index
    )
    if not isinstance(curve, dict) or not curve.get("available"):
        reason = (
            curve.get("reason", "Category curve unavailable.")
            if isinstance(curve, dict)
            else "Category curve unavailable."
        )
        return {"available": False, "reason": reason}
    prob = curve.get("probability", pd.DataFrame())
    meta = curve.get("metadata", {})
    if (
        not isinstance(prob, pd.DataFrame)
        or prob.empty
        or not isinstance(meta, dict)
    ):
        return {"available": False, "reason": "Probability curve is empty."}
    slope = float(meta.get("Slope", 1.0) or 1.0)
    rows = []
    for theta, df in prob.groupby("Theta", observed=False):
        cats = pd.to_numeric(df["CategoryValue"], errors="coerce").to_numpy(dtype=float)
        p = pd.to_numeric(df["Probability"], errors="coerce").to_numpy(dtype=float)
        ok = np.isfinite(cats) & np.isfinite(p)
        if not np.any(ok):
            continue
        cats = cats[ok]
        p = p[ok]
        total = float(np.sum(p))
        if total <= 0:
            continue
        p = p / total
        expected = float(np.sum(p * cats))
        # I_k(theta) = a^2 * P_k(theta) * (k - E[X|theta])^2
        contribution = (slope ** 2) * p * (cats - expected) ** 2
        total_info = float(np.sum(contribution))
        for k, prob_k, contrib_k in zip(cats, p, contribution):
            rows.append(
                {
                    "Theta": float(theta),
                    "CategoryValue": float(k),
                    "Probability": float(prob_k),
                    "ExpectedScore": expected,
                    "CategoryInformation": float(contrib_k),
                    "TotalInformation": total_info,
                }
            )
    info = pd.DataFrame(rows)
    if info.empty:
        return {
            "available": False,
            "reason": "Category-specific information curve could not be computed.",
        }
    info["Scope"] = str(meta.get("Scope", "curve"))
    info["Model"] = str(meta.get("Model", "Model"))
    info["Slope"] = slope

    # Per-category summary: peak information, theta at peak, share of total
    # information integrated over the curve grid.
    summary_rows = []
    grouped = info.groupby("CategoryValue", observed=False)
    for k, sub in grouped:
        contrib = pd.to_numeric(sub["CategoryInformation"], errors="coerce")
        thetas = pd.to_numeric(sub["Theta"], errors="coerce")
        peak_idx = int(contrib.idxmax()) if contrib.notna().any() else None
        summary_rows.append(
            {
                "CategoryValue": float(k),
                "MaxCategoryInformation": (
                    float(contrib.loc[peak_idx])
                    if peak_idx is not None
                    else float("nan")
                ),
                "ThetaAtMaxCategoryInformation": (
                    float(thetas.loc[peak_idx])
                    if peak_idx is not None
                    else float("nan")
                ),
                "IntegratedCategoryInformation": float(
                    np.trapezoid(contrib.to_numpy(dtype=float), thetas.to_numpy(dtype=float))
                )
                if contrib.notna().any()
                else float("nan"),
            }
        )
    summary = pd.DataFrame(summary_rows)
    if not summary.empty:
        integrated_total = float(summary["IntegratedCategoryInformation"].sum())
        if integrated_total > 0:
            summary["IntegratedShare"] = (
                summary["IntegratedCategoryInformation"] / integrated_total
            )
        else:
            summary["IntegratedShare"] = float("nan")
        summary["Scope"] = str(meta.get("Scope", "curve"))
        summary["Model"] = str(meta.get("Model", "Model"))

    return {
        "available": True,
        "curve": info,
        "summary": summary,
        "metadata": meta,
    }


def information_curve_export_table(result: dict) -> pd.DataFrame:
    options = category_probability_curve_options(result)
    frames = []
    for row in options.itertuples(index=False):
        try:
            is_average = bool(getattr(row, "IsAverage"))
            level_idx = None if is_average else int(getattr(row, "LevelIndex"))
            bundle = build_information_curve_data(result, step_level_index=level_idx)
            frame = bundle.get("curve", pd.DataFrame()) if isinstance(bundle, dict) else pd.DataFrame()
            if isinstance(frame, pd.DataFrame) and not frame.empty:
                frame = frame.copy()
                frame["CurveLabel"] = str(getattr(row, "Label"))
                frames.append(frame)
        except Exception:
            continue
    return pd.concat(frames, ignore_index=True) if frames else pd.DataFrame()


def _make_information_curve_figure(bundle: dict) -> go.Figure | None:
    if not isinstance(bundle, dict) or not bundle.get("available"):
        return None
    curve = bundle.get("curve", pd.DataFrame())
    if not isinstance(curve, pd.DataFrame) or curve.empty:
        return None
    scope = str(curve["Scope"].iloc[0]) if "Scope" in curve.columns else "curve"
    fig = make_subplots(specs=[[{"secondary_y": True}]])
    fig.add_trace(
        go.Scatter(
            x=curve["Theta"],
            y=curve["Information"],
            mode="lines",
            name="Information",
            line=dict(color="#1b9e77", width=2),
            hovertemplate="Theta=%{x:.2f}<br>Information=%{y:.3f}<extra></extra>",
        ),
        secondary_y=False,
    )
    fig.add_trace(
        go.Scatter(
            x=curve["Theta"],
            y=curve["ConditionalSE"],
            mode="lines",
            name="Conditional SE",
            line=dict(color="#d95f02", width=2, dash="dot"),
            hovertemplate="Theta=%{x:.2f}<br>Conditional SE=%{y:.3f}<extra></extra>",
        ),
        secondary_y=True,
    )
    fig.update_layout(
        title=f"Information / targeting curve ({scope})",
        xaxis_title="Person Measure - Item Measure (logits)",
        hovermode="x unified",
        height=420,
        template="plotly_white",
    )
    fig.update_yaxes(title_text="Information", secondary_y=False)
    fig.update_yaxes(title_text="Conditional SE", secondary_y=True)
    return fig


# Colour-blind-safe palette for the per-category decomposition.
# Picked from Wong (2011) Nature Methods "Color blindness", which is the
# de-facto reference for qualitative palettes that remain distinguishable
# under deuteranopia / protanopia / tritanopia. The first eight entries
# cover the common K ≤ 8 rating-scale lengths; longer scales cycle.
_CATEGORY_INFORMATION_PALETTE: tuple[str, ...] = (
    "#000000",  # Black
    "#E69F00",  # Orange
    "#56B4E9",  # Sky blue
    "#009E73",  # Bluish green
    "#F0E442",  # Yellow
    "#0072B2",  # Blue
    "#D55E00",  # Vermillion
    "#CC79A7",  # Reddish purple
)


def _make_category_information_curve_figure(bundle: dict) -> "go.Figure | None":
    """Per-category contribution curves alongside the total information.

    Returns a plotly figure where each category ``k`` is rendered as one
    line in a Wong (2011) colour-blind-safe palette, with the total
    information curve overlaid as a thicker dashed line so the
    decomposition-equals-total identity is visible at a glance.
    """
    if not isinstance(bundle, dict) or not bundle.get("available"):
        return None
    curve = bundle.get("curve", pd.DataFrame())
    if not isinstance(curve, pd.DataFrame) or curve.empty:
        return None
    scope = str(curve["Scope"].iloc[0]) if "Scope" in curve.columns else "curve"
    fig = go.Figure()
    categories = sorted(curve["CategoryValue"].unique().tolist())
    for idx, k in enumerate(categories):
        sub = curve[curve["CategoryValue"] == k].sort_values("Theta")
        colour = _CATEGORY_INFORMATION_PALETTE[idx % len(_CATEGORY_INFORMATION_PALETTE)]
        fig.add_trace(
            go.Scatter(
                x=sub["Theta"],
                y=sub["CategoryInformation"],
                mode="lines",
                name=f"Category {int(k)}",
                line=dict(color=colour, width=2),
                hovertemplate=(
                    "Theta=%{x:.2f}<br>"
                    f"Category {int(k)} information=%{{y:.3f}}<extra></extra>"
                ),
            )
        )
    # Overlay the total information curve so the decomposition is
    # visibly the sum of the parts.
    by_theta = curve.groupby("Theta", observed=False)["CategoryInformation"].sum()
    fig.add_trace(
        go.Scatter(
            x=by_theta.index,
            y=by_theta.values,
            mode="lines",
            name="Total information",
            line=dict(color="#333333", width=3, dash="dash"),
            hovertemplate="Theta=%{x:.2f}<br>Total information=%{y:.3f}<extra></extra>",
        )
    )
    fig.update_layout(
        title=f"Category-specific information ({scope})",
        xaxis_title="Person Measure - Item Measure (logits)",
        yaxis_title="Information",
        hovermode="x unified",
        height=420,
        template="plotly_white",
    )
    return fig


def _make_category_probability_curve_figures(curve: dict) -> tuple[go.Figure | None, go.Figure | None]:
    if not isinstance(curve, dict) or not curve.get("available"):
        return None, None
    prob_long = curve.get("probability", pd.DataFrame())
    expected_df = curve.get("expected", pd.DataFrame())
    thresholds = _category_curve_threshold_frame(curve)
    meta = curve.get("metadata", {})
    if not isinstance(prob_long, pd.DataFrame) or prob_long.empty or not isinstance(meta, dict):
        return None, None

    rating_min = int(prob_long["CategoryValue"].min()) if "CategoryValue" in prob_long.columns else 0
    rating_max = int(prob_long["CategoryValue"].max()) if "CategoryValue" in prob_long.columns else rating_min
    theta_lo = float(meta.get("ThetaMin", -4.0))
    theta_hi = float(meta.get("ThetaMax", 4.0))
    model = str(meta.get("Model", "Model"))
    scope = str(meta.get("Scope", "curve"))

    colors = px.colors.qualitative.Set2
    fig = go.Figure()
    threshold_est = pd.to_numeric(thresholds.get("Estimate", pd.Series(dtype=float)), errors="coerce").dropna()
    if not threshold_est.empty:
        line_x: list[float | None] = []
        line_y: list[float | None] = []
        line_custom: list[list[object]] = []
        threshold_labels = thresholds.loc[threshold_est.index, "DisplayLabel"].astype(str).tolist() if "DisplayLabel" in thresholds.columns else ["" for _ in threshold_est]
        for tau, label in zip(threshold_est.tolist(), threshold_labels):
            line_x.extend([float(tau), float(tau), None])
            line_y.extend([0.0, 1.0, None])
            line_custom.extend([[label, float(tau)], [label, float(tau)], [None, np.nan]])
        fig.add_trace(go.Scatter(
            x=line_x,
            y=line_y,
            mode="lines",
            name="Step threshold lines",
            line=dict(color="#555555", width=1, dash="dot"),
            customdata=line_custom,
            hovertemplate="Step threshold %{customdata[0]}<br>Logit=%{customdata[1]:.2f}<extra></extra>",
            showlegend=False,
        ))
        for tau, label in zip(threshold_est.tolist(), threshold_labels):
            fig.add_annotation(
                x=float(tau),
                y=1.03,
                xref="x",
                yref="paper",
                text=str(label),
                showarrow=False,
                font=dict(size=10, color="#555555"),
                bgcolor="rgba(255,255,255,0.78)",
                bordercolor="rgba(85,85,85,0.35)",
                borderwidth=0.5,
            )
    for idx, (category, group) in enumerate(prob_long.groupby("Category", sort=False)):
        fig.add_trace(go.Scatter(
            x=group["Theta"], y=group["Probability"], mode="lines",
            name=str(category),
            line=dict(color=colors[idx % len(colors)], width=2),
            hovertemplate=f"{category}<br>Theta=%{{x:.2f}}<br>Probability=%{{y:.3f}}<extra></extra>",
        ))
    diagnostic = category_probability_curve_diagnostic_table(curve)
    if isinstance(diagnostic, pd.DataFrame) and not diagnostic.empty:
        for idx, row in diagnostic.iterrows():
            peak_theta = pd.to_numeric(pd.Series([row.get("PeakTheta")]), errors="coerce").iloc[0]
            peak_prob = pd.to_numeric(pd.Series([row.get("PeakProbability")]), errors="coerce").iloc[0]
            if not (np.isfinite(float(peak_theta)) and np.isfinite(float(peak_prob))):
                continue
            label = str(row.get("Category", "Category"))
            fig.add_trace(go.Scatter(
                x=[float(peak_theta)],
                y=[float(peak_prob)],
                mode="markers+text",
                marker=dict(size=6, color=colors[idx % len(colors)], line=dict(color="#333333", width=0.5)),
                text=[label.replace("Cat ", "")],
                textposition="top center" if idx % 2 == 0 else "bottom center",
                textfont=dict(size=10, color="#333333"),
                name=f"{label} peak",
                hovertemplate=f"{label} peak<br>Theta=%{{x:.2f}}<br>Probability=%{{y:.3f}}<extra></extra>",
                showlegend=False,
            ))
    fig.update_layout(
        xaxis_title="Person Measure - Item Measure (logits)",
        yaxis_title="Probability",
        title=f"FACETS-style Category Characteristic Curves ({model}: {scope})",
        yaxis=dict(range=[0, 1]), xaxis=dict(range=[theta_lo, theta_hi]),
        hovermode="x unified", height=470, template="plotly_white",
        legend_title_text="Category",
    )

    fig_expected = None
    if isinstance(expected_df, pd.DataFrame) and not expected_df.empty:
        fig_expected = go.Figure()
        fig_expected.add_trace(go.Scatter(
            x=expected_df["Theta"], y=expected_df["ExpectedScore"], mode="lines",
            line=dict(color="#1b9e77", width=2), name="Expected Score",
        ))
        if not threshold_est.empty:
            line_x = []
            line_y = []
            for tau in threshold_est.tolist():
                line_x.extend([float(tau), float(tau), None])
                line_y.extend([rating_min, rating_max, None])
            fig_expected.add_trace(go.Scatter(
                x=line_x,
                y=line_y,
                mode="lines",
                name="Step threshold lines",
                line=dict(color="#555555", width=1, dash="dot"),
                hoverinfo="skip",
                showlegend=False,
            ))
            threshold_labels = thresholds.loc[threshold_est.index, "DisplayLabel"].astype(str).tolist() if "DisplayLabel" in thresholds.columns else ["" for _ in threshold_est]
            for tau, label in zip(threshold_est.tolist(), threshold_labels):
                fig_expected.add_annotation(
                    x=float(tau),
                    y=1.03,
                    xref="x",
                    yref="paper",
                    text=str(label),
                    showarrow=False,
                    font=dict(size=10, color="#555555"),
                    bgcolor="rgba(255,255,255,0.78)",
                    bordercolor="rgba(85,85,85,0.35)",
                    borderwidth=0.5,
                )
        fig_expected.update_layout(
            xaxis_title="Person Measure - Item Measure (logits)",
            yaxis_title="Expected Score",
            title=f"Expected Score with Step Boundaries ({scope})",
            yaxis=dict(range=[rating_min, rating_max]),
            hovermode="x unified", height=350, template="plotly_white",
        )
    return fig, fig_expected


def _draw_category_probability_curves_plotly(result: dict) -> None:
    """Interactive Plotly category probability curves."""
    header_cols = st.columns([5, 1])
    with header_cols[0]:
        st.subheader("Category Probability Curves")
    with header_cols[1]:
        render_help_popover("category_probability")
    st.caption(
        "These curves show the probability of responding in each category as a "
        "function of the latent measure (theta). Hover to read exact P(k) at any theta. "
        "The FACETS-style overlay labels the category peaks and draws vertical step "
        "threshold lines such as 0|1 or 4|5. For PCM/GPCM, inspect both the averaged "
        "curve and each step-facet level."
    )

    config = result.get("config", {})
    model = config.get("model", "RSM")
    options = category_probability_curve_options(result)
    selected_level_index: int | None = None
    if model in {"PCM", "GPCM"} and not options.empty and len(options) > 1:
        selected_option = st.selectbox(
            "Curve scope",
            options["OptionIndex"].astype(int).tolist(),
            format_func=lambda idx: str(options.loc[options["OptionIndex"] == idx, "Label"].iloc[0]),
            key=f"category_curve_scope_{model}_{config.get('step_facet')}",
            help=(
                "Average gives a compact overview. Level-specific curves use the thresholds "
                "and, for GPCM, the slope for the selected step-facet level."
            ),
        )
        selected_row = options.loc[options["OptionIndex"] == selected_option].iloc[0]
        if not bool(selected_row["IsAverage"]):
            selected_level_index = int(selected_row["LevelIndex"])
    curve = build_category_probability_curve_data(result, step_level_index=selected_level_index)
    if not curve.get("available"):
        st.info(curve.get("reason", "Step parameters not available."))
        return

    meta = curve["metadata"]

    if model in {"PCM", "GPCM"}:
        slope_note = f" Slope used for this curve: {float(meta['Slope']):.3f}." if model == "GPCM" else ""
        st.info(
            f"Curve scope: **{meta['Scope']}**.{slope_note} "
            "Use level-specific curves when category functioning may differ across tasks, raters, or criteria."
        )

    with st.expander("How to read category curves", expanded=False):
        st.markdown(
            """
- Each colored line is the model-predicted probability of a rating category.
- FACETS-style threshold lines mark adjacent category boundaries such as 0|1 or 4|5.
- Direct peak labels identify where each category is most likely.
- A well-functioning category usually has a visible peak where it is more probable than neighboring categories.
- If a category never becomes most probable, inspect sparse counts and threshold ordering before reporting the scale as fully ordered.
- For PCM/GPCM, the averaged curve can hide level-specific disorder. Use the scope selector to inspect each step-facet level.
- For GPCM, the slope changes steepness, not severity. Read slope differences separately from ordinary Rasch measures.
"""
        )

    fig, fig_expected = _make_category_probability_curve_figures(curve)
    scope_key = re.sub(r"[^A-Za-z0-9]+", "_", str(meta.get("Scope", "curve"))).strip("_")[:80] or "curve"
    if fig is not None:
        st.plotly_chart(fig, width="stretch")
        render_chart_guide("category_probability")
        _offer_fig_download(fig, f"category_probability_curve_{model}_{scope_key}", "Download displayed category curve (PNG 300 DPI)")
    if fig_expected is not None:
        st.plotly_chart(fig_expected, width="stretch")
        _offer_fig_download(fig_expected, f"expected_score_curve_{model}_{scope_key}", "Download displayed expected score curve (PNG 300 DPI)")

    curve_diagnostic = category_probability_curve_diagnostic_table(curve)
    if isinstance(curve_diagnostic, pd.DataFrame) and not curve_diagnostic.empty:
        with st.expander("FACETS-style category curve diagnostics", expanded=False):
            st.caption(
                "Use this table to check whether every category has a modeled peak and a theta region "
                "where it is the most probable category. A missing dominance region should be read "
                "with category counts, average measures, and threshold order before collapsing categories."
            )
            display_cols = [
                col for col in [
                    "Category", "CategoryValue", "PeakTheta", "PeakProbability",
                    "IsEverMostProbable", "DominantThetaMin", "DominantThetaMax",
                    "DominantWidth", "ReviewFlag"
                ] if col in curve_diagnostic.columns
            ]
            st.dataframe(curve_diagnostic.loc[:, display_cols], width="stretch", hide_index=True)
            st.download_button(
                "Download category curve diagnostics (CSV)",
                data=to_csv_bytes(curve_diagnostic),
                file_name="mfrm_category_curve_facets_diagnostics.csv",
                mime="text/csv",
                key=f"dl_category_curve_diagnostics_{model}_{meta['Scope']}",
            )

    curve_export = _category_curve_export_frame(curve)
    st.download_button(
        "Download displayed category curve data (CSV)",
        data=to_csv_bytes(curve_export),
        file_name="mfrm_category_probability_curve.csv",
        mime="text/csv",
        key=f"dl_category_probability_curve_{model}_{meta['Scope']}",
    )


def _draw_information_curves_plotly(result: dict) -> None:
    st.subheader("Information / Targeting Curves")
    st.caption(
        "Model-based local precision across the latent scale. This is different from "
        "intraclass correlation (cluster ICC) in the design audit."
    )
    config = result.get("config", {})
    model = config.get("model", "RSM")
    options = category_probability_curve_options(result)
    selected_level_index: int | None = None
    if model in {"PCM", "GPCM"} and not options.empty and len(options) > 1:
        selected_option = st.selectbox(
            "Information curve scope",
            options["OptionIndex"].astype(int).tolist(),
            format_func=lambda idx: str(options.loc[options["OptionIndex"] == idx, "Label"].iloc[0]),
            key=f"information_curve_scope_{model}_{config.get('step_facet')}",
            help="Average is compact; level-specific curves show precision for individual step-facet levels.",
        )
        selected_row = options.loc[options["OptionIndex"] == selected_option].iloc[0]
        if not bool(selected_row["IsAverage"]):
            selected_level_index = int(selected_row["LevelIndex"])
    bundle = build_information_curve_data(result, step_level_index=selected_level_index)
    if not bundle.get("available"):
        st.info(bundle.get("reason", "Information curve is unavailable."))
        return
    summary = bundle.get("summary", pd.DataFrame())
    if isinstance(summary, pd.DataFrame) and not summary.empty:
        st.dataframe(summary, width="stretch", hide_index=True)
    fig = _make_information_curve_figure(bundle)
    if fig is not None:
        st.plotly_chart(fig, width="stretch")
        scope = bundle.get("metadata", {}).get("Scope", "curve") if isinstance(bundle.get("metadata"), dict) else "curve"
        scope_key = re.sub(r"[^A-Za-z0-9]+", "_", str(scope)).strip("_")[:80] or "curve"
        _offer_fig_download(fig, f"information_curve_{model}_{scope_key}", "Download information curve (PNG 300 DPI)")
    curve = bundle.get("curve", pd.DataFrame())
    if isinstance(curve, pd.DataFrame) and not curve.empty:
        st.download_button(
            "Download displayed information curve data (CSV)",
            data=to_csv_bytes(curve),
            file_name="mfrm_information_curve.csv",
            mime="text/csv",
            key=f"dl_information_curve_{model}",
        )

    # Category-specific decomposition of the information curve. Optional
    # because the total curve is the primary diagnostic; the breakdown
    # answers a different question (which response category contributes
    # how much information at each theta) and is most useful when a
    # rubric has many categories that are not uniformly informative.
    # Hidden behind an expander so the default render stays compact.
    with st.expander(t("visuals_top.category_info_expander"), expanded=False):
        st.caption(t("visuals_top.category_info_caption"))
        cat_bundle = build_category_information_curve_data(
            result, step_level_index=selected_level_index
        )
        if not cat_bundle.get("available"):
            st.info(
                cat_bundle.get(
                    "reason", "Category-specific decomposition unavailable."
                )
            )
        else:
            cat_summary = cat_bundle.get("summary", pd.DataFrame())
            if isinstance(cat_summary, pd.DataFrame) and not cat_summary.empty:
                st.dataframe(
                    cat_summary.round(3), width="stretch", hide_index=True
                )
            cat_fig = _make_category_information_curve_figure(cat_bundle)
            if cat_fig is not None:
                st.plotly_chart(cat_fig, width="stretch")
                cat_scope = (
                    cat_bundle.get("metadata", {}).get("Scope", "curve")
                    if isinstance(cat_bundle.get("metadata"), dict)
                    else "curve"
                )
                cat_scope_key = re.sub(
                    r"[^A-Za-z0-9]+", "_", str(cat_scope)
                ).strip("_")[:80] or "curve"
                _offer_fig_download(
                    cat_fig,
                    f"category_information_curve_{model}_{cat_scope_key}",
                    "Download category information curve (PNG 300 DPI)",
                )
            cat_curve = cat_bundle.get("curve", pd.DataFrame())
            if isinstance(cat_curve, pd.DataFrame) and not cat_curve.empty:
                st.download_button(
                    "Download category information curve data (CSV)",
                    data=to_csv_bytes(cat_curve),
                    file_name="mfrm_category_information_curve.csv",
                    mime="text/csv",
                    key=f"dl_category_information_curve_{model}",
                )


def _draw_data_coverage_heatmap(
    data: "pd.DataFrame",
    facet_cols: list,
    person_col: str,
) -> None:
    """Heatmap of person × (first-facet concat) coverage — where observations exist.

    Shows which cells of the design have any observation (blue) vs which
    are missing (white). Large white blocks flag disconnected subsets or
    heavily sparse designs. Capped at the first facet × 80 persons so
    the Data tab stays readable on Community Cloud.
    """
    if (
        not isinstance(data, pd.DataFrame)
        or data.empty
        or person_col not in data.columns
        or not facet_cols
    ):
        return
    missing_cols = [f for f in facet_cols if f not in data.columns]
    if missing_cols:
        return

    header_cols = st.columns([5, 1])
    with header_cols[0]:
        st.markdown("##### Observation coverage heatmap")
    with header_cols[1]:
        render_help_popover("coverage_heatmap")
    st.caption(
        "Blue cells = at least one observation; white = no observation. "
        "Large white blocks flag sparse or disconnected designs. Cap: "
        "first facet × up to 80 persons."
    )
    try:
        facet = facet_cols[0]
        # Cap to 80 persons so the heatmap stays legible
        persons = data[person_col].astype(str).unique().tolist()
        persons = persons[: min(80, len(persons))]
        levels = sorted(data[facet].dropna().astype(str).unique().tolist())
        if not persons or not levels:
            st.info("Not enough levels in the first facet to build a coverage heatmap.")
            return
        # Count of observations per (person, level) cell
        slim = data[data[person_col].astype(str).isin(persons)][[person_col, facet]].copy()
        slim[person_col] = slim[person_col].astype(str)
        slim[facet] = slim[facet].astype(str)
        counts = slim.groupby([person_col, facet]).size().unstack(fill_value=0)
        counts = counts.reindex(index=persons, columns=levels, fill_value=0)
        # Boolean heatmap (has observation / not)
        z = (counts.to_numpy() > 0).astype(int)
        total_cells = z.size
        missing_cells = int((z == 0).sum())
        missing_pct = 100.0 * missing_cells / total_cells if total_cells else 0.0

        fig = go.Figure(data=go.Heatmap(
            z=z,
            x=levels,
            y=persons,
            colorscale=[[0, "#ffffff"], [1, "#0d7a5a"]],
            showscale=False,
            hovertemplate=(
                f"{facet}=%{{x}}<br>{person_col}=%{{y}}<br>"
                "Observed=%{z}<extra></extra>"
            ),
        ))
        fig.update_layout(
            title=(
                f"Coverage of `{person_col}` × `{facet}` "
                f"({missing_pct:.0f}% cells empty in the displayed slice)"
            ),
            xaxis_title=facet,
            yaxis_title=person_col,
            template="plotly_white",
            height=max(280, 14 * len(persons)),
        )
        st.plotly_chart(fig, width="stretch")
        if missing_pct > 40:
            st.warning(
                f"{missing_pct:.0f}% of the displayed `{person_col}` × `{facet}` "
                "cells have no observation. Review connectivity and consider "
                "anchoring or redesign before drawing cross-group conclusions."
            )
    except Exception as exc:  # pragma: no cover - defensive
        st.caption(f"Coverage heatmap could not be built: {type(exc).__name__}: {exc}")


def _draw_category_usage_bar(
    data: "pd.DataFrame",
    score_col: str,
    facet_cols: list,
) -> None:
    """Bar chart of observed score-category frequencies, optionally stacked by facet level.

    Answers "is every rating category actually used?" at a glance.
    Low or zero counts for a category usually signal disordered
    thresholds downstream (Linacre 2004), so catching the issue early
    in the Data tab saves users from chasing category-probability
    oddities later.
    """
    if (
        not isinstance(data, pd.DataFrame)
        or data.empty
        or score_col not in data.columns
    ):
        return
    scores = pd.to_numeric(data[score_col], errors="coerce").dropna()
    if scores.empty:
        return

    header_cols = st.columns([5, 1])
    with header_cols[0]:
        st.markdown("##### Category usage")
    with header_cols[1]:
        render_help_popover("category_usage")
    st.caption(
        "Raw observed frequency of each score category. Low or zero "
        "counts suggest the category is under-used and may collapse into "
        "a neighbouring one (disordered thresholds; Linacre 2004)."
    )
    try:
        facet_options = ["(none — overall)"] + list(facet_cols)
        split_by = st.selectbox(
            "Split categories by facet",
            options=facet_options,
            index=0,
            key="category_usage_split_by",
            help="Stack category counts by a facet's levels to see where under-used categories concentrate.",
        )
        if split_by == "(none — overall)" or split_by not in data.columns:
            counts = scores.value_counts().sort_index()
            fig = go.Figure(go.Bar(
                x=[str(int(c)) if float(c).is_integer() else str(c) for c in counts.index],
                y=counts.values,
                marker_color="#0d7a5a",
                hovertemplate="Category %{x}<br>Count=%{y}<extra></extra>",
            ))
            fig.update_layout(
                title="Overall category usage",
                xaxis_title="Score category",
                yaxis_title="Observed count",
                template="plotly_white", height=360,
            )
        else:
            slim = data[[score_col, split_by]].copy()
            slim[score_col] = pd.to_numeric(slim[score_col], errors="coerce")
            slim = slim.dropna(subset=[score_col])
            slim[split_by] = slim[split_by].astype(str)
            piv = slim.groupby([score_col, split_by]).size().unstack(fill_value=0)
            piv = piv.sort_index()
            fig = go.Figure()
            for level in piv.columns:
                fig.add_trace(go.Bar(
                    name=str(level),
                    x=[str(int(c)) if float(c).is_integer() else str(c) for c in piv.index],
                    y=piv[level].values,
                    hovertemplate=f"<b>{level}</b><br>Category %{{x}}<br>Count=%{{y}}<extra></extra>",
                ))
            fig.update_layout(
                title=f"Category usage stacked by {split_by}",
                xaxis_title="Score category",
                yaxis_title="Observed count",
                barmode="stack",
                template="plotly_white", height=360,
            )
        st.plotly_chart(fig, width="stretch")

        # Highlight categories with suspicious low counts
        overall = scores.value_counts().sort_index()
        total = int(overall.sum())
        low = overall[overall < max(5, int(0.01 * total))]
        if not low.empty:
            st.warning(
                f"**Low-use categories**: {dict(low)} — each with < 1% of the total "
                f"{total:,} observations. Review threshold ordering in the Categories/Steps tab."
            )
    except Exception as exc:  # pragma: no cover - defensive
        st.caption(f"Category usage chart could not be built: {type(exc).__name__}: {exc}")


def _make_eb_shrinkage_figure(shrinkage: dict) -> go.Figure | None:
    measures = shrinkage.get("measures", pd.DataFrame()) if isinstance(shrinkage, dict) else pd.DataFrame()
    if not isinstance(measures, pd.DataFrame) or measures.empty:
        return None
    required = {"Facet", "Level", "Estimate", "ShrunkEstimate", "SE", "ShrunkSE"}
    if not required.issubset(measures.columns):
        return None
    # Error bars sized to the user-selected visualization CI level so the
    # forest scales with the sidebar control rather than a hardcoded 95 %.
    viz_level = get_viz_ci_level()
    viz_z = _ci_z(viz_level)
    viz_pct = _ci_level_pct_label(viz_level)
    plot_df = measures.copy()
    for col in ["Estimate", "ShrunkEstimate", "SE", "ShrunkSE", "ShrinkageFactor"]:
        if col in plot_df.columns:
            plot_df[col] = pd.to_numeric(plot_df[col], errors="coerce")
    plot_df = plot_df.dropna(subset=["Estimate", "ShrunkEstimate"])
    plot_df = plot_df.sort_values(["Facet", "ShrinkageFactor", "Level"], ascending=[True, False, True]).head(80)
    if plot_df.empty:
        return None
    plot_df["_Label"] = plot_df["Facet"].astype(str) + ": " + plot_df["Level"].astype(str)
    y = plot_df["_Label"].tolist()
    fig = go.Figure()
    for _, row in plot_df.iterrows():
        fig.add_trace(go.Scatter(
            x=[row["Estimate"], row["ShrunkEstimate"]],
            y=[row["_Label"], row["_Label"]],
            mode="lines",
            line=dict(color="#9e9e9e", width=1),
            showlegend=False,
            hoverinfo="skip",
        ))
    fig.add_trace(go.Scatter(
        x=plot_df["Estimate"],
        y=plot_df["_Label"],
        mode="markers",
        name=f"Raw estimate ± {viz_pct} % CI",
        marker=dict(color="#7570b3", size=8),
        error_x=dict(
            type="data",
            array=viz_z * plot_df["SE"],
            visible=bool(plot_df["SE"].notna().any()),
            thickness=0.8,
        ),
        customdata=np.column_stack([plot_df["Facet"], plot_df["Level"], plot_df.get("ShrinkageFactor", pd.Series(np.nan, index=plot_df.index))]),
        hovertemplate="%{customdata[0]}: %{customdata[1]}<br>Raw=%{x:.3f}<br>Shrinkage=%{customdata[2]:.3f}<extra></extra>",
    ))
    fig.add_trace(go.Scatter(
        x=plot_df["ShrunkEstimate"],
        y=plot_df["_Label"],
        mode="markers",
        name=f"Shrunk estimate ± {viz_pct} % CI",
        marker=dict(color="#1b9e77", size=8, symbol="diamond"),
        error_x=dict(
            type="data",
            array=viz_z * plot_df["ShrunkSE"],
            visible=bool(plot_df["ShrunkSE"].notna().any()),
            thickness=0.8,
        ),
        hovertemplate="%{y}<br>Shrunk=%{x:.3f}<extra></extra>",
    ))
    fig.add_vline(x=0, line_dash="dot", line_color="#666666", line_width=0.7)
    fig.update_layout(
        title=f"Post-hoc empirical-Bayes shrinkage of facet estimates (± {viz_pct} % CI)",
        xaxis_title="Measure (logits)",
        yaxis=dict(autorange="reversed"),
        height=max(420, 24 * len(plot_df) + 120),
        template="plotly_white",
        margin=_readable_plot_margins(y_labels=y, base_left=140),
    )
    fig.update_yaxes(tickmode="array", tickvals=y, ticktext=_compact_label_list(y, max_chars=46), automargin=True)
    return fig


def render_eb_shrinkage_section(result: dict, diagnostics: dict, *, expanded: bool = False) -> None:
    shrinkage = diagnostics.get("eb_shrinkage", {}) if isinstance(diagnostics, dict) else {}
    enabled = bool(diagnostics.get("eb_shrinkage_enabled", False)) if isinstance(diagnostics, dict) else False
    if not enabled and not (isinstance(shrinkage, dict) and shrinkage.get("available")):
        return
    st.subheader("Empirical-Bayes facet shrinkage advisory")
    st.caption(
        "Post-hoc shrinkage for non-person facet estimates. Raw estimates, SE, fit, "
        "LogLik, AIC, and BIC are unchanged."
    )
    if result.get("config", {}).get("facet_regularization_enabled"):
        st.warning(
            "This run also used MAP-style facet regularization during estimation. "
            "Treat EB shrinkage as an additional reporting sensitivity check, not a second fitted model."
        )
    if not isinstance(shrinkage, dict) or not shrinkage.get("available"):
        st.info(shrinkage.get("reason", "EB shrinkage was not available for this run.") if isinstance(shrinkage, dict) else "EB shrinkage was not available.")
        return
    report = shrinkage.get("report", pd.DataFrame())
    measures = shrinkage.get("measures", pd.DataFrame())
    with st.expander("Shrinkage report", expanded=expanded):
        if isinstance(report, pd.DataFrame) and not report.empty:
            st.dataframe(report.round(4), width="stretch", hide_index=True)
        if isinstance(measures, pd.DataFrame) and not measures.empty:
            st.dataframe(format_measure_table(reorder_measure_columns(measures)).head(500), width="stretch")
            if len(measures) > 500:
                st.caption(f"Showing first 500 of {len(measures):,} shrinkage rows. Use Downloads for the full table.")
    fig = _make_eb_shrinkage_figure(shrinkage)
    if fig is not None:
        st.plotly_chart(fig, width="stretch")
        _offer_fig_download(fig, "eb_shrinkage_forest", "Download EB shrinkage figure (PNG 300 DPI)")


def _draw_measures_forest_plotly(diagnostics: dict) -> None:
    """Forest plot: element measures with two confidence-interval bands.

    A frequentist analogue of the Bayesian forest plot in Posterior Viewer —
    shows each facet element's point estimate, a thick inner CI band at
    50 % (≈ ±0.67·SE) for at-a-glance ordering, and a thin outer CI band
    at the user-selected visualization CI level (default 95 %; configure
    via the sidebar ``Visualization CI level`` selector). Useful for
    publication: one figure communicates precision and ordering at once."""
    outer_level = get_viz_ci_level()
    outer_z = _ci_z(outer_level)
    outer_pct = _ci_level_pct_label(outer_level)
    header_cols = st.columns([5, 1])
    with header_cols[0]:
        st.subheader(
            f"Forest plot of element measures (± 50 % / {outer_pct} % CI)"
        )
    with header_cols[1]:
        render_help_popover("forest_measures")
    st.caption(
        f"Each row is one facet element. Thick bar = 50 % CI (≈ ± 0.67 · SE); "
        f"thin bar = {outer_pct} % CI (± {outer_z:.3f} · SE). Dot = point "
        f"estimate (logits). Useful for communicating ordering + precision "
        f"in a single figure."
    )

    measures = diagnostics.get("measures", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()
    if not isinstance(measures, pd.DataFrame) or measures.empty:
        st.info(
            t(
                "sidebar_perf.no_measure_table_info_template",
                run_button=t("sidebar_perf.run_button"),
            )
        )
        return
    if not {"Facet", "Level", "Estimate", "SE"}.issubset(measures.columns):
        st.info("Measure table is missing Facet / Level / Estimate / SE columns.")
        return

    facet_options = sorted(measures["Facet"].dropna().unique().astype(str).tolist())
    if not facet_options:
        st.info("No facet-level rows found.")
        return
    # Default to the first non-Person facet if available so item / rater
    # distinctions are foregrounded; Person can still be picked explicitly.
    default_idx = 0
    for i, f in enumerate(facet_options):
        if f != "Person":
            default_idx = i
            break
    picked = st.selectbox(
        "Facet to plot",
        options=facet_options,
        index=default_idx,
        key="forest_plot_facet",
        help="Pick one facet — persons can be hundreds of rows, so per-facet plots stay readable.",
    )
    sub = measures[measures["Facet"].astype(str) == picked].copy()
    sub["Estimate"] = pd.to_numeric(sub["Estimate"], errors="coerce")
    sub["SE"] = pd.to_numeric(sub["SE"], errors="coerce")
    sub = sub.dropna(subset=["Estimate", "SE"])
    if sub.empty:
        st.info(f"No valid Estimate/SE rows for facet `{picked}`.")
        return

    # v0.2.11-beta bug fix: when a facet has fewer than 5 rows the
    # widget hit `value < min_value` and raised
    # `StreamlitValueBelowMinError`. Small facets need no truncation
    # — skip the widget entirely and plot every row.
    n_rows_available = len(sub)
    if n_rows_available <= 5:
        max_rows = n_rows_available
    else:
        # Cap the ceiling at a sensible upper bound but guarantee it
        # is strictly greater than `min_value=5` so Streamlit accepts
        # the numeric range.
        max_rows_ceiling = min(500, max(6, n_rows_available))
        default_value = max(5, min(40, n_rows_available))
        max_rows = int(st.number_input(
            "Show top N elements (sorted by Estimate)",
            min_value=5,
            max_value=max_rows_ceiling,
            value=default_value,
            step=5,
            help="Large facets are truncated for readability; full data is in the Measures tab.",
        ))
    sub = sub.sort_values("Estimate", ascending=True).tail(int(max_rows))
    labels = sub["Level"].astype(str).tolist()
    est = sub["Estimate"].to_numpy()
    se = sub["SE"].to_numpy()
    ci50_lo = est - 0.67 * se
    ci50_hi = est + 0.67 * se
    ci95_lo = est - outer_z * se
    ci95_hi = est + outer_z * se

    fig = go.Figure()
    for i, lbl in enumerate(labels):
        fig.add_trace(go.Scatter(
            x=[ci95_lo[i], ci95_hi[i]], y=[lbl, lbl],
            mode="lines", line=dict(width=1, color="#9aa0a6"),
            showlegend=False, hoverinfo="skip",
        ))
    for i, lbl in enumerate(labels):
        fig.add_trace(go.Scatter(
            x=[ci50_lo[i], ci50_hi[i]], y=[lbl, lbl],
            mode="lines", line=dict(width=5, color="#0d7a5a"),
            showlegend=False, hoverinfo="skip",
        ))
    fig.add_trace(go.Scatter(
        x=list(est), y=labels, mode="markers",
        marker=dict(size=8, color="#c24e00"),
        name="Estimate",
        hovertemplate=(
            "<b>%{y}</b><br>Estimate=%{x:.3f}<extra></extra>"
        ),
    ))
    fig.add_vline(x=0, line_dash="dot", line_color="#666666", line_width=1)
    fig.update_layout(
        title=f"Forest plot — {picked}",
        xaxis_title="Measure (logits)",
        yaxis_title=picked,
        template="plotly_white",
        height=max(260, 24 * len(labels)),
    )
    st.plotly_chart(fig, width="stretch")
    st.caption(
        f"Interpretation tip: elements with non-overlapping {outer_pct} % CIs "
        f"differ at the matching level; overlapping 50 % CIs is weak evidence "
        f"at best."
    )


def _draw_residual_qq_plotly(diagnostics: dict) -> None:
    """Q-Q plot of standardized residuals against a standard normal.

    Classical residual diagnostic: if the Rasch model fits, standardised
    residuals should be approximately N(0, 1). Deviations in the tails
    indicate misfit concentrated on extreme persons / items.
    """
    header_cols = st.columns([5, 1])
    with header_cols[0]:
        st.subheader("Q-Q plot of standardized residuals")
    with header_cols[1]:
        render_help_popover("qq_residuals")
    st.caption(
        "Standardized residuals on the y-axis against theoretical N(0, 1) "
        "quantiles on the x-axis. Under a well-fitting Rasch model, points "
        "lie on the 45° reference line. Heavy tails → extreme-score misfit; "
        "S-shape → possible residual structure."
    )

    obs_df = diagnostics.get("obs") if isinstance(diagnostics, dict) else None
    if not isinstance(obs_df, pd.DataFrame) or obs_df.empty:
        st.info("No observation table with standardized residuals is available.")
        return
    if "StdResidual" not in obs_df.columns:
        st.info("StdResidual column missing from the observation table.")
        return
    residuals = pd.to_numeric(obs_df["StdResidual"], errors="coerce").dropna().to_numpy()
    if residuals.size < 20:
        st.info(
            f"Only {residuals.size} standardized residuals found; Q-Q plot "
            "needs ≥20 observations to be interpretable."
        )
        return

    try:
        from scipy.stats import probplot
        osm, osr = probplot(residuals, dist="norm", fit=False)
        theoretical = osm
        sample = osr
    except Exception as exc:
        st.warning(f"Could not build Q-Q plot ({type(exc).__name__}: {exc}).")
        return

    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=theoretical, y=sample, mode="markers",
        marker=dict(size=5, color="#0d7a5a", opacity=0.6),
        name="Residuals",
        hovertemplate="Theoretical=%{x:.2f}<br>Sample=%{y:.2f}<extra></extra>",
    ))
    lo = float(min(theoretical.min(), sample.min()))
    hi = float(max(theoretical.max(), sample.max()))
    fig.add_shape(
        type="line", x0=lo, y0=lo, x1=hi, y1=hi,
        line=dict(color="#666666", dash="dash", width=1),
    )
    fig.update_layout(
        title="Q-Q plot — standardized residuals vs N(0, 1)",
        xaxis_title="Theoretical quantiles (N(0, 1))",
        yaxis_title="Sample quantiles (standardized residual)",
        template="plotly_white", height=450,
    )
    st.plotly_chart(fig, width="stretch")
    st.caption(
        f"Sample size = {residuals.size:,}. "
        f"Observed mean = {residuals.mean():.3f}, SD = {residuals.std(ddof=1):.3f} "
        "(target ≈ 0, 1 under a fitting Rasch model)."
    )


def _draw_measure_ecdf_plotly(result: dict, diagnostics: dict) -> None:
    """Empirical CDF of person and facet-element measures on the logit scale.

    Complements the Wright Map histogram by showing cumulative coverage —
    useful for identifying scale gaps where no element sits, or person
    concentrations that Wright Map's binned histogram hides.
    """
    header_cols = st.columns([5, 1])
    with header_cols[0]:
        st.subheader("Empirical cumulative distribution of measures")
    with header_cols[1]:
        render_help_popover("ecdf_measures")
    st.caption(
        "Cumulative share of persons / facet elements at each logit value. "
        "Flat segments are scale gaps (no measures in that range); steep "
        "segments are clusters. Easier than the Wright Map for spotting "
        "holes in measurement coverage."
    )

    def _collect(df: pd.DataFrame, label: str, estimate_col: str = "Estimate") -> pd.DataFrame:
        if not isinstance(df, pd.DataFrame) or df.empty or estimate_col not in df.columns:
            return pd.DataFrame()
        values = pd.to_numeric(df[estimate_col], errors="coerce").dropna().to_numpy()
        if values.size == 0:
            return pd.DataFrame()
        xs = np.sort(values)
        ys = np.arange(1, xs.size + 1) / xs.size
        return pd.DataFrame({"logit": xs, "cumulative_share": ys, "group": label})

    person_df = (result.get("facets", {}) or {}).get("person", pd.DataFrame()) if isinstance(result, dict) else pd.DataFrame()
    measures = diagnostics.get("measures", pd.DataFrame()) if isinstance(diagnostics, dict) else pd.DataFrame()

    frames = [_collect(person_df, "Persons")]
    if isinstance(measures, pd.DataFrame) and not measures.empty and "Facet" in measures.columns:
        for facet_name, sub in measures.groupby("Facet"):
            if str(facet_name).lower() == "person":
                continue
            frames.append(_collect(sub, str(facet_name)))
    frames = [f for f in frames if not f.empty]
    if not frames:
        st.info("No measure data available for the ECDF plot yet.")
        return
    ecdf = pd.concat(frames, ignore_index=True)

    fig = go.Figure()
    for grp_name, grp_df in ecdf.groupby("group"):
        fig.add_trace(go.Scatter(
            x=grp_df["logit"], y=grp_df["cumulative_share"],
            mode="lines", name=str(grp_name),
            hovertemplate="<b>%{fullData.name}</b><br>Logit=%{x:.3f}<br>Share=%{y:.2%}<extra></extra>",
        ))
    fig.add_vline(x=0, line_dash="dot", line_color="#666666", line_width=1,
                  annotation_text="Origin", annotation_position="top right")
    fig.update_layout(
        title="Empirical CDF — persons and facet elements",
        xaxis_title="Logit",
        yaxis_title="Cumulative share",
        template="plotly_white", height=460,
        yaxis=dict(range=[0, 1]),
    )
    st.plotly_chart(fig, width="stretch")
    st.caption(
        "Note: long flat stretches indicate logit ranges with no element — "
        "targets for adding items or tasks. Steep jumps mean measurement "
        "density where further discrimination is already precise."
    )


def _draw_pathway_map_plotly(diagnostics: dict) -> None:
    """Interactive Plotly pathway map: Measure vs Infit ZSTD."""
    header_cols = st.columns([5, 1])
    with header_cols[0]:
        st.subheader("Pathway Map")
    with header_cols[1]:
        render_help_popover("pathway_map")
    st.caption(
        "Each point represents a facet element. Hover to identify elements. "
        "Elements beyond ±2 approximate ZSTD warrant investigation."
    )

    with st.expander("How to read the Pathway Map", expanded=False):
        st.markdown(
            """
The Pathway Map plots each facet element's **measure** (Y-axis, in logits) against its
**Infit ZSTD** (X-axis).

**Reading the plot:**
- **Y-axis (Measure)**: The estimated severity/difficulty of each element.
  Higher values = more severe raters or harder items.
- **X-axis (Infit ZSTD)**: How much the element's response pattern deviates from model
  expectations. This is an app-side Wilson-Hilferty approximation; FACETS uses
  specialized degrees-of-freedom handling, so exact FACETS parity is not guaranteed.
  A z-score where 0 means perfect fit.
- **Green zone (|ZSTD| < 2)**: Elements in this zone fit the model well. Their response
  patterns are consistent with the Rasch model expectations.
- **Red dashed lines (±2 ZSTD)**: Elements beyond these lines show statistically
  significant misfit. Investigate their response patterns.

**What to look for:**
- *Elements far to the right (ZSTD > +2)*: Noisy — responses are more variable than expected.
  The rater may be inconsistent, or the item may be ambiguous.
- *Elements far to the left (ZSTD < −2)*: Over-fit — responses are too predictable.
  Possible response dependencies or restricted range.
- *Clusters of misfitting elements at similar measures*: May indicate a systematic issue
  at that difficulty level (e.g., a problematic rubric criterion).
- *Isolated outliers*: Often driven by a few unexpected responses (check Outfit too).
"""
        )

    measures = diagnostics.get("measures", pd.DataFrame())
    if measures.empty or "Estimate" not in measures.columns:
        st.info("Measures not available for pathway map.")
        return

    zstd_col = "InfitZSTD" if "InfitZSTD" in measures.columns else None
    if zstd_col is None:
        st.info("Infit ZSTD not available.")
        return

    pdf = measures.copy()
    pdf["Estimate"] = pd.to_numeric(pdf["Estimate"], errors="coerce")
    pdf[zstd_col] = pd.to_numeric(pdf[zstd_col], errors="coerce")
    pdf = pdf.dropna(subset=["Estimate", zstd_col])

    color_col = "Facet" if "Facet" in pdf.columns else None
    hover_data = ["Level"] if "Level" in pdf.columns else None

    fig = px.scatter(
        pdf, x=zstd_col, y="Estimate", color=color_col,
        hover_data=hover_data, opacity=0.7,
        color_discrete_sequence=px.colors.qualitative.Set2,
    )
    fig.add_vrect(x0=-2, x1=2, fillcolor="green", opacity=0.06, line_width=0)
    fig.add_vline(x=2, line_dash="dash", line_color="red", line_width=0.7)
    fig.add_vline(x=-2, line_dash="dash", line_color="red", line_width=0.7)
    fig.add_vline(x=0, line_dash="dot", line_color="gray", line_width=0.5)
    fig.update_layout(
        xaxis_title="Approx. Infit ZSTD", yaxis_title="Measure (logits)",
        title="Pathway Map: Measure vs approximate Infit ZSTD", height=500,
    )
    st.plotly_chart(fig, width="stretch")
    render_chart_guide("pathway_map")


