def _draw_bias_heatmap(tbl: pd.DataFrame, facet_a: str, facet_b: str) -> None:
    """Interactive Plotly heatmap of bias size or t-values (FacetA × FacetB)."""
    if "FacetA_Level" not in tbl.columns or "FacetB_Level" not in tbl.columns:
        return
    header_cols = st.columns([5, 1])
    with header_cols[0]:
        st.markdown(t("bias_interaction.heatmap_header_template", facet_a=facet_a, facet_b=facet_b))
    with header_cols[1]:
        render_help_popover("bias_heatmap")
    # Internal IDs (English) drive routing; format_func provides display labels.
    _heatmap_metric_options = ["Bias Size (logits)", "t-value"]
    _heatmap_metric_displays = {
        "Bias Size (logits)": t("bias_interaction.heatmap_metric_bias_size_display"),
        "t-value": t("bias_interaction.heatmap_metric_t_value_display"),
    }
    metric = st.radio(
        t("bias_interaction.heatmap_metric_label"),
        _heatmap_metric_options,
        horizontal=True,
        key="bias_heatmap_metric",
        format_func=lambda v: _heatmap_metric_displays.get(v, v),
        help=t("bias_interaction.heatmap_metric_help"),
    )
    if "t-value" in metric:
        st.caption(t("bias_interaction.heatmap_t_value_caption"))
    val_col = "Bias Size" if "Bias" in metric else "t"
    if val_col not in tbl.columns:
        return

    pivot = tbl.pivot_table(
        index="FacetA_Level", columns="FacetB_Level", values=val_col, aggfunc="first",
    )
    if pivot.empty or not np.any(np.isfinite(pivot.values)):
        st.info(t("bias_interaction.heatmap_no_finite_info"))
        return
    safe_pair_key = re.sub(r"[^A-Za-z0-9]+", "_", f"{facet_a}_{facet_b}")
    # v0.2.11-beta bug fix: on narrow/short pivots, `max_axis_default`
    # could exceed the slider's `max_value` (or equal its `min_value`,
    # making the slider degenerate). Clamp all three relative to the
    # actual pivot size so Streamlit always receives a valid range.
    axis_extent = max(1, int(max(pivot.shape)))
    if axis_extent <= 8:
        # Too few labels to need a trimming widget at all.
        max_axis = axis_extent
    else:
        slider_max_val = max(9, min(80, axis_extent))
        slider_default = max(8, min(35, axis_extent))
        slider_default = min(slider_default, slider_max_val)
        max_axis = st.slider(
            t("bias_interaction.heatmap_max_labels_label"),
            min_value=8,
            max_value=slider_max_val,
            value=slider_default,
            step=1,
            key=f"bias_heatmap_max_axis_{safe_pair_key}",
            help=t("bias_interaction.heatmap_max_labels_help"),
        )
    auto_rows, auto_cols, auto_filtered = _select_heatmap_labels(pivot, max_rows=max_axis, max_cols=max_axis)
    show_all = st.checkbox(
        t("bias_interaction.heatmap_show_all_label"),
        value=not auto_filtered,
        key=f"bias_heatmap_show_all_{safe_pair_key}",
        help=t("bias_interaction.heatmap_show_all_help"),
    )
    if not show_all and auto_filtered:
        original_shape = pivot.shape
        pivot = pivot.loc[auto_rows, auto_cols]
        st.caption(
            t(
                "bias_interaction.heatmap_compact_caption_template",
                rows=pivot.shape[0],
                total_rows=original_shape[0],
                cols=pivot.shape[1],
                total_cols=original_shape[1],
            )
        )
    # Build custom hover text
    hover_pivot = tbl.pivot_table(
        index="FacetA_Level", columns="FacetB_Level",
        values=["Bias Size", "t", "Prob.", "Observd Count"],
        aggfunc="first",
    )
    hover_text = []
    for i, row_lbl in enumerate(pivot.index):
        row_texts = []
        for j, col_lbl in enumerate(pivot.columns):
            parts = [f"{facet_a}: {row_lbl}", f"{facet_b}: {col_lbl}"]
            for c in ["Bias Size", "t", "Prob.", "Observd Count"]:
                if c in hover_pivot.columns.get_level_values(0):
                    v = hover_pivot.loc[row_lbl, (c, col_lbl)]
                    if pd.notna(v):
                        parts.append(f"{c}: {v:.3f}" if isinstance(v, float) else f"{c}: {v}")
            row_texts.append("<br>".join(parts))
        hover_text.append(row_texts)

    # Significance annotations
    t_pivot = tbl.pivot_table(
        index="FacetA_Level", columns="FacetB_Level", values="t", aggfunc="first",
    )
    star_text = np.full(pivot.shape, "", dtype=object)
    show_star_text = pivot.size <= 900
    for i, row_lbl in enumerate(pivot.index):
        for j, col_lbl in enumerate(pivot.columns):
            t_val = t_pivot.loc[row_lbl, col_lbl] if (row_lbl in t_pivot.index and col_lbl in t_pivot.columns) else np.nan
            if show_star_text and pd.notna(t_val) and abs(t_val) >= 2:
                star_text[i, j] = "*"

    zmax = float(np.nanmax(np.abs(pivot.values))) if np.any(np.isfinite(pivot.values)) else 1.0
    x_labels_full = [str(c) for c in pivot.columns]
    y_labels_full = [str(r) for r in pivot.index]
    fig = go.Figure(data=go.Heatmap(
        z=pivot.values,
        x=x_labels_full,
        y=y_labels_full,
        text=star_text if show_star_text else None,
        customdata=hover_text,
        hovertemplate="%{customdata}<extra></extra>",
        colorscale="RdBu_r",
        zmid=0,
        zmin=-zmax,
        zmax=zmax,
        colorbar=dict(title=val_col),
    ))
    if show_star_text:
        fig.update_traces(texttemplate="%{text}", textfont=dict(size=14, color="black"))
    fig.update_layout(
        xaxis_title=facet_b,
        yaxis_title=facet_a,
        title=f"{metric} — {facet_a} × {facet_b}",
        yaxis=dict(autorange="reversed"),
        height=max(340, min(900, 28 * len(pivot.index) + 150)),
        margin=_readable_plot_margins(
            y_labels=y_labels_full,
            x_labels=x_labels_full,
            base_left=120,
            base_bottom=100,
        ),
        template="plotly_white",
    )
    fig.update_xaxes(
        tickmode="array",
        tickvals=x_labels_full,
        ticktext=_compact_label_list(x_labels_full, max_chars=24),
        tickangle=-45 if len(pivot.columns) > 8 else 0,
        automargin=True,
        tickfont=dict(size=9 if len(pivot.columns) > 20 else 10),
    )
    fig.update_yaxes(
        tickmode="array",
        tickvals=y_labels_full,
        ticktext=_compact_label_list(y_labels_full, max_chars=34),
        automargin=True,
        tickfont=dict(size=9 if len(pivot.index) > 25 else 10),
    )
    st.plotly_chart(fig, width="stretch")
    if show_star_text:
        st.caption(t("bias_interaction.heatmap_significance_caption"))
    else:
        st.caption(t("bias_interaction.heatmap_dense_caption"))


def classical_dif_help_table() -> pd.DataFrame:
    """How to read the classical DIF screening table."""
    columns = [
        t("help.classical_dif_col_signal"),
        t("help.classical_dif_col_answers"),
        t("help.classical_dif_col_trigger"),
        t("help.classical_dif_col_action"),
    ]
    rows = []
    for rid in ("mh", "logistic", "sibtest", "effect", "purify"):
        rows.append({
            columns[0]: t(f"help.classical_dif_{rid}_signal"),
            columns[1]: t(f"help.classical_dif_{rid}_answers"),
            columns[2]: t(f"help.classical_dif_{rid}_trigger"),
            columns[3]: t(f"help.classical_dif_{rid}_action"),
        })
    return pd.DataFrame(rows, columns=columns)


def show_classical_dif_section(result: dict | None, core: dict) -> None:
    """Classical polytomous DIF (Differential Item Functioning) screening.

    Observed-score DIF for an external person group (e.g. L1, gender) — distinct
    from the model-based facet bias/interaction screen. Screening evidence only.
    """
    st.subheader(t("dif_screening.heading"))
    st.caption(t("dif_screening.intro_caption"))
    st.caption(t("dif_screening.boundary_caption"))

    prep = result.get("prep") if isinstance(result, dict) else None
    if not isinstance(prep, dict) or not isinstance(prep.get("data"), pd.DataFrame) or prep["data"].empty:
        st.info(t("dif_screening.no_data_info"))
        return
    config = result.get("config", {}) if isinstance(result, dict) else {}
    facet_names = [str(f) for f in (config.get("facet_names") or prep.get("facet_names") or [])]
    if not facet_names:
        st.info(t("dif_screening.no_facets_info"))
        return

    fit_pd = pd.DataFrame()
    pop = result.get("population", {}) if isinstance(result, dict) else {}
    if isinstance(pop, dict):
        fit_pd = pop.get("person_data", pd.DataFrame())

    with st.expander(t("dif_screening.group_expander"), expanded=True):
        st.caption(t("dif_screening.group_caption"))
        uploaded = st.file_uploader(
            t("dif_screening.group_upload_label"), type=["csv", "xlsx"], key="dif_group_upload")
        person_data = pd.DataFrame()
        if uploaded is not None:
            try:
                person_data = (pd.read_excel(uploaded) if str(uploaded.name).endswith("xlsx")
                               else pd.read_csv(uploaded))
            except Exception as exc:
                st.error(t("dif_screening.group_upload_error_template", error=str(exc)))
        elif isinstance(fit_pd, pd.DataFrame) and fit_pd.shape[1] > 1:
            person_data = fit_pd.copy()
            st.caption(t("dif_screening.group_reuse_caption"))
        person_data.columns = [str(c) for c in person_data.columns]
        if person_data.empty or "Person" not in person_data.columns:
            st.info(t("dif_screening.group_need_info"))
            return
        candidate_cols = [c for c in person_data.columns if c != "Person"]
        if not candidate_cols:
            st.info(t("dif_screening.group_need_info"))
            return
        group_col = st.selectbox(t("dif_screening.group_col_label"), candidate_cols, key="dif_group_col")
        item_facet = st.selectbox(
            t("dif_screening.item_facet_label"), facet_names, index=len(facet_names) - 1,
            key="dif_item_facet", help=t("dif_screening.item_facet_help"))

    with st.expander(t("dif_screening.settings_expander"), expanded=False):
        c1, c2, c3 = st.columns(3)
        matching = c1.selectbox(t("dif_screening.matching_label"), ["rest", "total"], index=0, key="dif_matching")
        alpha = float(c2.number_input(t("dif_screening.alpha_label"), 0.001, 0.5, 0.05, 0.005, format="%.3f", key="dif_alpha"))
        min_group_n = int(c3.number_input(t("dif_screening.min_n_label"), 5, 500, 30, 5, key="dif_min_n"))
        c4, c5 = st.columns(2)
        practical_smd = float(c4.number_input(t("dif_screening.practical_label"), 0.0, 2.0, 0.17, 0.01, format="%.2f", key="dif_practical"))
        purify = bool(c5.checkbox(t("dif_screening.purify_label"), value=True, key="dif_purify", help=t("dif_screening.purify_help")))

    if not st.button(t("dif_screening.run_button"), key="dif_run", type="primary"):
        st.caption(t("dif_screening.run_hint"))
        return

    group_labels = pd.Series(person_data.set_index("Person")[group_col].astype(str).to_dict())
    with st.spinner(t("dif_screening.running_spinner")):
        res = analyze_classical_dif(prep, item_facet, group_labels, matching=matching,
                                    alpha=alpha, min_group_n=min_group_n,
                                    practical_smd=practical_smd, purify=purify)
    if "_skip_reason" in res:
        st.warning(res["_skip_reason"])
        return

    for cav in res.get("caveats", []):
        st.caption("⚠ " + str(cav))

    summary = res.get("summary")
    if isinstance(summary, pd.DataFrame) and not summary.empty:
        sv = dict(zip(summary["Metric"], summary["Value"]))
        m = st.columns(4)
        m[0].metric(t("dif_screening.metric_screened"), int(sv.get("Items x contrasts screened", 0)))
        m[1].metric(t("dif_screening.metric_flagged"), int(sv.get("Flagged", 0)))
        m[2].metric(t("dif_screening.metric_strong"), int(sv.get("Strong review", 0)))
        max_smd = sv.get("Max |SMD_std|", float("nan"))
        m[3].metric(t("dif_screening.metric_max_smd"), f"{float(max_smd):.2f}" if np.isfinite(max_smd) else "n/a")

    render_help_popover("classical_dif")
    table = res.get("table", pd.DataFrame())
    flagged = table[table["Flag"].astype(bool)] if "Flag" in table.columns else pd.DataFrame()
    with st.expander(t("dif_screening.flagged_expander"), expanded=not flagged.empty):
        if flagged.empty:
            st.success(t("dif_screening.no_flags_success"))
        else:
            st.dataframe(flagged, width="stretch", hide_index=True)
    st.dataframe(table, width="stretch", hide_index=True)
    st.download_button(t("dif_screening.download_button"), data=to_csv_bytes(table),
                       file_name="mfrm_classical_dif_screening.csv", mime="text/csv", key="dl_dif_screen")
    audit = res.get("audit")
    if isinstance(audit, pd.DataFrame) and not audit.empty:
        with st.expander(t("dif_screening.audit_expander"), expanded=False):
            st.dataframe(audit, width="stretch", hide_index=True)
            st.download_button(t("dif_screening.audit_download"), data=to_csv_bytes(audit),
                               file_name="mfrm_classical_dif_audit.csv", mime="text/csv", key="dl_dif_audit")
    with st.expander(t("dif_screening.interpret_expander"), expanded=False):
        st.dataframe(classical_dif_help_table(), width="stretch", hide_index=True)
    with st.expander(t("dif_screening.crosscheck_expander"), expanded=False):
        st.caption(t("dif_screening.crosscheck_caption"))
        bundle = build_dif_validation_bundle(res)
        xc_key = f"dif_xc_{len(table)}_{res.get('settings', {}).get('reference_group', '')}_{'-'.join(res.get('settings', {}).get('purified_items', []) or [])}"
        st.download_button(
            t("dif_screening.crosscheck_download"),
            data=cached_mixed_asset_zip(bundle, xc_key),
            file_name="mfrm_difR_crosscheck_bundle.zip",
            mime="application/zip", key="dl_dif_crosscheck")


def show_bias_section(
    bias_results: dict | None,
    core: dict,
    all_bias_results: dict[str, dict] | None = None,
    result: dict | None = None,
    diagnostics: dict | None = None,
) -> None:
    """Render Bias/Interaction analysis (FACETS Table 7 style)."""
    st.subheader(t("bias_interaction.heading"))
    st.caption(t("bias_interaction.intro_caption"))

    # Let user choose which pair to view
    all_bias = all_bias_results or {}
    if not all_bias and bias_results:
        pair_key = f"{bias_results.get('facet_a', 'A')} x {bias_results.get('facet_b', 'B')}"
        all_bias = {pair_key: bias_results}

    if not all_bias:
        st.info(t("bias_interaction.no_results_info"))
        return

    pair_keys = list(all_bias.keys())
    selected_pair = st.selectbox(
        t("bias_interaction.facet_pair_label"), pair_keys, index=0, key="bias_pair_selector",
        help=t("bias_interaction.facet_pair_help"),
    )
    bias_results = all_bias[selected_pair]
    # If estimate_bias_interaction returned a skip-reason instead of results,
    # surface it here instead of crashing on the missing "table" key.
    if isinstance(bias_results, dict) and "_skip_reason" in bias_results and "table" not in bias_results:
        st.warning(
            t(
                "bias_interaction.skip_reason_warning_template",
                pair=selected_pair,
                reason=bias_results["_skip_reason"],
            )
        )
        return
    tbl = bias_results["table"].copy()

    st.caption(
        "Bias estimates are conditional screening statistics. Use the DFF table "
        "and inference audit below for multiplicity, sparse-cell, and common-scale caveats."
    )

    facet_a = bias_results.get("facet_a", selected_pair.split(" x ")[0])
    facet_b = bias_results.get("facet_b", selected_pair.split(" x ")[-1])
    safe_pair_key = re.sub(r"[^A-Za-z0-9]+", "_", selected_pair).strip("_").lower() or "selected_pair"

    st.subheader(t("bias_interaction.dff_subheader"))
    st.caption(t("bias_interaction.dff_caption"))
    with st.expander(t("bias_interaction.dff_settings_expander"), expanded=False):
        cols = st.columns(3)
        with cols[0]:
            dff_alpha = float(st.number_input(
                t("bias_interaction.dff_alpha_label"),
                min_value=0.001,
                max_value=0.500,
                value=0.050,
                step=0.005,
                format="%.3f",
                key=f"dff_alpha_{safe_pair_key}",
                help=t("bias_interaction.dff_alpha_help"),
            ))
        with cols[1]:
            dff_practical = float(st.number_input(
                t("bias_interaction.dff_practical_label"),
                min_value=0.00,
                max_value=5.00,
                value=0.50,
                step=0.05,
                format="%.2f",
                key=f"dff_practical_{safe_pair_key}",
                help=t("bias_interaction.dff_practical_help"),
            ))
        with cols[2]:
            dff_min_n = int(st.number_input(
                t("bias_interaction.dff_min_n_label"),
                min_value=1,
                max_value=100,
                value=5,
                step=1,
                key=f"dff_min_n_{safe_pair_key}",
                help=t("bias_interaction.dff_min_n_help"),
            ))
        st.caption(t("bias_interaction.dff_defaults_caption"))
    dff_tbl = build_dff_bias_screening_table(
        bias_results,
        alpha=dff_alpha,
        min_n=dff_min_n,
        practical_logit=dff_practical,
    )
    dff_summary = summarize_dff_bias_screening(dff_tbl)
    selected_bias_audit = build_bias_inference_audit(
        {selected_pair: bias_results},
        result,
        diagnostics,
        alpha=dff_alpha,
        min_n=dff_min_n,
        practical_logit=dff_practical,
    )
    if dff_tbl.empty:
        st.info(t("bias_interaction.dff_no_table_info"))
    else:
        summary_values = dict(zip(dff_summary["Metric"], dff_summary["Value"])) if not dff_summary.empty else {}
        metric_cols = st.columns(4)
        metric_cols[0].metric(t("bias_interaction.dff_metric_cells"), int(summary_values.get("Cells screened", len(dff_tbl))))
        metric_cols[1].metric(t("bias_interaction.dff_metric_flagged"), int(summary_values.get("Flagged cells", 0)))
        metric_cols[2].metric(t("bias_interaction.dff_metric_strong"), int(summary_values.get("Strong review", 0)))
        max_abs_bias = summary_values.get("Max |bias|", np.nan)
        metric_cols[3].metric(t("bias_interaction.dff_metric_max_abs_bias"), f"{float(max_abs_bias):.2f}" if np.isfinite(max_abs_bias) else "n/a")
        dff_summary_display = dff_summary.copy()
        if "Value" in dff_summary_display.columns:
            dff_summary_display["Value"] = dff_summary_display["Value"].map(
                lambda value: "" if pd.isna(value) else str(value)
            )
        st.dataframe(dff_summary_display, width="stretch", hide_index=True)
        if isinstance(selected_bias_audit, pd.DataFrame) and not selected_bias_audit.empty:
            audit_status = str(selected_bias_audit.iloc[0].get("Status", "Review"))
            audit_claim = str(selected_bias_audit.iloc[0].get("ClaimStatus", "Report with caveat"))
            if audit_status == "Ready":
                st.success(f"Bias inference audit: {audit_claim}.")
            else:
                st.warning(f"Bias inference audit: {audit_claim}.")
            with st.expander("Bias inference audit", expanded=audit_status != "Ready"):
                st.dataframe(selected_bias_audit, width="stretch", hide_index=True)
                st.download_button(
                    "Download bias inference audit CSV",
                    data=to_csv_bytes(selected_bias_audit),
                    file_name=f"mfrm_bias_inference_audit_{safe_pair_key}.csv",
                    mime="text/csv",
                    key=f"dl_bias_inference_audit_{safe_pair_key}",
                )
        flagged_dff = dff_tbl[dff_tbl["Flag"].astype(bool)] if "Flag" in dff_tbl.columns else pd.DataFrame()
        with st.expander(t("bias_interaction.dff_flagged_expander"), expanded=not flagged_dff.empty):
            if flagged_dff.empty:
                st.success(t("bias_interaction.dff_no_flags_success"))
            else:
                show_cols = [
                    "FacetA", "FacetA_Level", "FacetB", "FacetB_Level", "ObsN",
                    "BiasSize", "SE", "t", "p", "p_holm", "p_bh",
                    "EvidenceLevel", "ClaimStatus", "ProfileCIStatus",
                    "Direction", "ReportingCaution", "NextAction",
                ]
                st.dataframe(flagged_dff[[c for c in show_cols if c in flagged_dff.columns]], width="stretch")
        st.download_button(
            t("bias_interaction.dff_download_button"),
            data=to_csv_bytes(dff_tbl),
            file_name="mfrm_dff_bias_screening.csv",
            mime="text/csv",
            key=f"dl_dff_bias_screening_{safe_pair_key}",
        )

    # Add standardized effect size (Cohen's d ≈ Bias / pooled SD of measures)
    if "Bias Size" in tbl.columns:
        bias_vals = pd.to_numeric(tbl["Bias Size"], errors="coerce").dropna()
        if len(bias_vals) > 1:
            pooled_sd = float(bias_vals.std())
            if pooled_sd > 0:
                tbl["Effect (d)"] = (
                    pd.to_numeric(tbl["Bias Size"], errors="coerce") / pooled_sd
                ).round(2)

    # Display columns with friendly names. Under GPCM the LR / profile-CI
    # columns carry the inferential content that the t-based screening
    # columns can only approximate, so we slot them in right after the
    # t-based block. RSM / PCM fits leave these columns NaN; rather than
    # display empty cells we drop them from the visible dataframe when no
    # row carries a finite ``LR ChiSq``.
    gpcm_inference_active = (
        "LR ChiSq" in tbl.columns
        and pd.to_numeric(tbl["LR ChiSq"], errors="coerce").notna().any()
    )
    display_cols = [
        "Sq", "Observd Score", "Expctd Score", "Observd Count",
        "Obs-Exp Average", "Bias Size", "Effect (d)", "S.E.", "t", "d.f.", "Prob.",
    ]
    if gpcm_inference_active:
        display_cols += [
            "LR ChiSq", "LR Prob.",
            "Profile CI Lower", "Profile CI Upper", "Profile CI Status",
        ]
    display_cols += [
        "Infit", "Outfit",
        "FacetA_Index", "FacetA_Level", "FacetA_Measure",
        "FacetB_Index", "FacetB_Level", "FacetB_Measure",
    ]
    display_cols = [c for c in display_cols if c in tbl.columns]
    tbl_display = tbl[display_cols].rename(columns={
        "S.E.": "Model S.E.",
        "Infit": "Infit MnSq",
        "Outfit": "Outfit MnSq",
        "FacetA_Index": f"{facet_a} N",
        "FacetA_Level": facet_a,
        "FacetA_Measure": f"{facet_a} measr",
        "FacetB_Index": f"{facet_b} N",
        "FacetB_Level": facet_b,
        "FacetB_Measure": f"{facet_b} measr",
    })
    st.dataframe(tbl_display, width="stretch")
    if gpcm_inference_active:
        st.caption(t("bias_interaction.gpcm_inference_caption"))
    elif "LR ChiSq" in tbl.columns:
        # The LR / profile columns exist in the raw table (so they appear in
        # the CSV download for completeness) but are uniformly NaN under
        # RSM / PCM; tell the reader why instead of leaving an unexplained
        # gap between the dataframe and the heatmap below.
        st.caption(t("bias_interaction.gpcm_inference_unavailable_caption"))

    # Interactive bias heatmap (Plotly)
    st.subheader(t("bias_interaction.heatmap_subheader"))
    st.caption(t("bias_interaction.heatmap_caption"))
    _draw_bias_heatmap(tbl, facet_a, facet_b)

    # Iteration convergence report
    iter_tbl = bias_results.get("iteration")
    if iter_tbl is not None and not iter_tbl.empty:
        st.subheader(t("bias_interaction.iteration_subheader"))
        iter_display = iter_tbl.copy()
        iter_display["Iteration"] = iter_display["Iteration"].apply(
            lambda v: f"BIAS {int(v)}" if pd.notna(v) else v
        )
        st.dataframe(iter_display.rename(columns={
            "MaxScoreResidual": "Max. Score Residual",
            "MaxScoreResidualPct": "%",
            "MaxLogitChange": "Max. Logit Change",
            "BiasCells": "Cells",
        }), width="stretch")

    # Summary statistics
    st.subheader(t("bias_interaction.summary_subheader"))
    summary = bias_results.get("summary")
    if summary is not None and not summary.empty:
        st.dataframe(summary, width="stretch")

    # Bias size distribution
    bias_vals = tbl["Bias Size"].dropna()
    if len(bias_vals) >= 3:
        mean_b = float(bias_vals.mean())
        sd_b = float(bias_vals.std())
        fig_bias = make_subplots(rows=1, cols=2, subplot_titles=["Bias Size Distribution", "Bias Significance (t) Distribution"])
        fig_bias.add_trace(go.Histogram(
            x=bias_vals, nbinsx=min(20, len(bias_vals)), marker_color="#1b9e77", showlegend=False,
        ), row=1, col=1)
        fig_bias.add_vline(x=mean_b, line_color="black", line_width=1, row=1, col=1,
                           annotation_text=f"Mean={mean_b:.2f}")
        for mult in [1, 2]:
            fig_bias.add_vline(x=mean_b + mult * sd_b, line_dash="dash", line_color="gray", line_width=0.7, row=1, col=1)
            fig_bias.add_vline(x=mean_b - mult * sd_b, line_dash="dash", line_color="gray", line_width=0.7, row=1, col=1)
        fig_bias.update_xaxes(title_text="Bias Size (logits)", row=1, col=1)
        fig_bias.update_yaxes(title_text="Count", row=1, col=1)

        t_vals = tbl["t"].dropna()
        if len(t_vals) >= 3:
            fig_bias.add_trace(go.Histogram(
                x=t_vals, nbinsx=min(20, len(t_vals)), marker_color="#d95f02", showlegend=False,
            ), row=1, col=2)
            fig_bias.add_vline(x=0, line_color="black", line_width=1, row=1, col=2)
            fig_bias.add_vline(x=2, line_dash="dash", line_color="red", line_width=0.7, row=1, col=2)
            fig_bias.add_vline(x=-2, line_dash="dash", line_color="red", line_width=0.7, row=1, col=2)
            fig_bias.update_xaxes(title_text="t-value", row=1, col=2)
            fig_bias.update_yaxes(title_text="Count", row=1, col=2)

        fig_bias.update_layout(height=380, template="plotly_white")
        st.plotly_chart(fig_bias, width="stretch")
        _offer_fig_download(fig_bias, "bias_distribution", "Download Bias Distribution (PNG 300 DPI)")

    # Fixed chi-square test
    chi_sq = bias_results.get("chi_sq")
    if chi_sq is not None and not chi_sq.empty:
        st.subheader(t("bias_interaction.chi_sq_subheader"))
        st.dataframe(chi_sq, width="stretch")
        chi_val = chi_sq["FixedChiSq"].iloc[0]
        chi_df = chi_sq["FixedDF"].iloc[0]
        chi_p = chi_sq["FixedProb"].iloc[0]
        if np.isfinite(chi_p):
            tmpl_kwargs = dict(
                chi_val=f"{chi_val:.2f}",
                chi_df=int(chi_df),
                chi_p=f"{chi_p:.4f}",
            )
            if chi_p < 0.01:
                st.warning(t("bias_interaction.chi_sq_warning_template", **tmpl_kwargs))
            else:
                st.success(t("bias_interaction.chi_sq_success_template", **tmpl_kwargs))

    # Pairwise bias report
    calc_bias_pairwise_fn = core.get("calc_bias_pairwise")
    if calc_bias_pairwise_fn:
        st.subheader(t("bias_interaction.pairwise_subheader"))
        target_facet = st.selectbox(
            t("bias_interaction.pairwise_target_label"),
            [facet_a, facet_b], index=0, key="bias_target_facet",
            help=t("bias_interaction.pairwise_target_help"),
        )
        context_facet = facet_b if target_facet == facet_a else facet_a
        pairwise_tbl = calc_bias_pairwise_fn(bias_results["table"], target_facet, context_facet)
        if pairwise_tbl.empty:
            st.info(t("bias_interaction.pairwise_no_results_info"))
        else:
            st.dataframe(pairwise_tbl, width="stretch")

    # Download
    st.download_button(
        t("bias_interaction.download_button"),
        data=to_csv_bytes(tbl),
        file_name="mfrm_bias_table.csv",
        mime="text/csv",
    )


# ---------------------------------------------------------------------------
# Categories/Steps tab
# ---------------------------------------------------------------------------

def show_categories_section(result: dict, diagnostics: dict, core: dict) -> None:
    """Render category diagnostics and step ordering checks."""
    st.subheader(t("categories_steps.category_diagnostics_subheader"))
    st.caption(t("categories_steps.category_diagnostics_caption"))

    calc_cat_fn = core.get("calc_category_stats")
    calc_step_fn = core.get("calc_step_order")
    cat_warn_fn = core.get("category_warnings_text")
    obs_df = diagnostics.get("obs")

    dashboard = rating_scale_functioning_dashboard(result, diagnostics)
    if isinstance(dashboard, pd.DataFrame) and not dashboard.empty:
        st.markdown("##### Rating-scale functioning dashboard")
        st.caption(
            "Integrated FACETS-style evidence: category counts, average measures, "
            "threshold order, category characteristic curves, residual fit, and GPCM slopes when present."
        )
        st.dataframe(dashboard, width="stretch", hide_index=True)
        st.download_button(
            "Download rating-scale functioning dashboard (CSV)",
            data=to_csv_bytes(dashboard),
            file_name="mfrm_rating_scale_functioning_dashboard.csv",
            mime="text/csv",
            key="dl_rating_scale_functioning_dashboard",
        )

        decision_support = rating_scale_decision_support_table(result, diagnostics)
        if isinstance(decision_support, pd.DataFrame) and not decision_support.empty:
            st.markdown("##### Rating-scale decision support")
            st.caption(
                "Conservative reporting guidance derived from the dashboard. This is not an automatic "
                "category-collapse rule; recoding still requires rubric justification and rerun comparison."
            )
            st.dataframe(decision_support, width="stretch", hide_index=True)
            st.download_button(
                "Download rating-scale decision support (CSV)",
                data=to_csv_bytes(decision_support),
                file_name="mfrm_rating_scale_decision_support.csv",
                mime="text/csv",
                key="dl_rating_scale_decision_support",
            )

        action_center = category_collapse_action_center_table(result, diagnostics)
        if isinstance(action_center, pd.DataFrame) and not action_center.empty:
            st.markdown("##### Category-collapse action center")
            st.caption(
                "Step-by-step review checklist for category-collapse sensitivity work. "
                "Only the Done checkbox is editable; evidence and reporting boundaries stay fixed."
            )
            disabled_cols = [col for col in action_center.columns if col != "Done"]
            try:
                st.data_editor(
                    action_center,
                    width="stretch",
                    hide_index=True,
                    disabled=disabled_cols,
                    column_config={
                        "Done": st.column_config.CheckboxColumn(
                            "Done",
                            help="Tick after the evidence has been checked and the completion criterion has been met.",
                        ),
                    },
                    key="category_collapse_action_center_editor",
                )
            except Exception:
                st.dataframe(action_center, width="stretch", hide_index=True)
            st.download_button(
                "Download category-collapse action center (CSV)",
                data=to_csv_bytes(action_center),
                file_name="mfrm_category_collapse_action_center.csv",
                mime="text/csv",
                key="dl_category_collapse_action_center",
            )

            category_collapse_draft = generate_category_collapse_sensitivity_draft(
                result,
                diagnostics,
                action_center,
            )
            with st.expander("APA category-collapse sensitivity draft", expanded=False):
                st.markdown(category_collapse_draft)
            st.download_button(
                "Download APA category-collapse sensitivity draft (Markdown)",
                data=category_collapse_draft.encode("utf-8"),
                file_name="apa_category_collapse_sensitivity_draft.md",
                mime="text/markdown",
                key="dl_apa_category_collapse_sensitivity_draft",
            )

        recode_candidates = rating_scale_recode_candidate_table(result, diagnostics)
        if isinstance(recode_candidates, pd.DataFrame) and not recode_candidates.empty:
            st.markdown("##### Adjacent-category recoding candidates")
            st.caption(
                "Sensitivity-analysis planning table. The original scoring baseline is retained, and each "
                "candidate must be refitted before any reporting decision is changed."
            )
            st.dataframe(recode_candidates, width="stretch", hide_index=True)
            st.download_button(
                "Download adjacent-category recoding candidates (CSV)",
                data=to_csv_bytes(recode_candidates),
                file_name="mfrm_rating_scale_recode_candidates.csv",
                mime="text/csv",
                key="dl_rating_scale_recode_candidates",
            )
            recode_assets = rating_scale_recode_script_assets(result, diagnostics)
            st.download_button(
                "Download recode scripts (Python/R/Julia ZIP)",
                data=cached_mixed_asset_zip(recode_assets, bytes_mapping_fingerprint(recode_assets)),
                file_name="MFRM_Rating_Scale_Recode_Scripts.zip",
                mime="application/zip",
                key="dl_rating_scale_recode_scripts_zip",
            )

        category_evidence = rating_scale_category_evidence_table(result, diagnostics)
        if isinstance(category_evidence, pd.DataFrame) and not category_evidence.empty:
            with st.expander("Category-level evidence: counts + curves + fit", expanded=False):
                st.caption(
                    "This table joins observed category support with the averaged category-curve "
                    "peak/dominance diagnostics. Use it to see which exact category drives a review row."
                )
                st.dataframe(category_evidence, width="stretch", hide_index=True)
                st.download_button(
                    "Download category-level evidence (CSV)",
                    data=to_csv_bytes(category_evidence),
                    file_name="mfrm_rating_scale_category_evidence.csv",
                    mime="text/csv",
                    key="dl_rating_scale_category_evidence",
                )

    if calc_cat_fn and obs_df is not None and not obs_df.empty:
        cat_tbl = calc_cat_fn(obs_df, result)
        if not cat_tbl.empty:
            st.dataframe(cat_tbl, width="stretch")

            # Category bar charts
        

            cats = cat_tbl["Category"].astype(str)
            fig_cat = make_subplots(rows=1, cols=2, subplot_titles=["Category Counts", "Category Percent"])
            fig_cat.add_trace(go.Bar(x=cats, y=cat_tbl["Count"], marker_color="#1b9e77", showlegend=False), row=1, col=1)
            fig_cat.update_xaxes(title_text="Category", row=1, col=1)
            fig_cat.update_yaxes(title_text="Count", row=1, col=1)
            if "Percent" in cat_tbl.columns:
                fig_cat.add_trace(go.Bar(x=cats, y=cat_tbl["Percent"], marker_color="#d95f02", showlegend=False), row=1, col=2)
                fig_cat.update_xaxes(title_text="Category", row=1, col=2)
                fig_cat.update_yaxes(title_text="Percent", row=1, col=2)
            fig_cat.update_layout(height=370, template="plotly_white")
            st.plotly_chart(fig_cat, width="stretch")

            # Average measures monotonicity check
            if "AvgPersonMeasure" in cat_tbl.columns:
                avg_sorted = cat_tbl.dropna(subset=["AvgPersonMeasure"]).sort_values("Category")
                if len(avg_sorted) >= 2:
                    is_monotonic = avg_sorted["AvgPersonMeasure"].is_monotonic_increasing
                    if is_monotonic:
                        st.success(t("categories_steps.monotonic_success"))
                    else:
                        st.warning(t("categories_steps.monotonic_warning"))

            # Category warnings
            step_order = None
            if calc_step_fn and result.get("steps") is not None:
                step_order = calc_step_fn(result["steps"])

            if cat_warn_fn:
                warnings_text = cat_warn_fn(cat_tbl, step_order)
                if "No major" in warnings_text:
                    st.success(warnings_text)
                else:
                    st.warning(warnings_text)

            with st.expander(t("categories_steps.interpret_screen_expander"), expanded=False):
                low_count_levels = cat_tbl.loc[cat_tbl["Count"] < 10, "Category"].tolist() if "Count" in cat_tbl.columns else []
                avg_tbl_for_note = (
                    cat_tbl.dropna(subset=["AvgPersonMeasure"]).sort_values("Category")
                    if "AvgPersonMeasure" in cat_tbl.columns else pd.DataFrame()
                )
                avg_ok = bool(len(avg_tbl_for_note) < 3 or avg_tbl_for_note["AvgPersonMeasure"].is_monotonic_increasing)
                disordered_levels = (
                    step_order.loc[step_order["Ordered"] == False, "Step"].astype(str).tolist()
                    if isinstance(step_order, pd.DataFrame) and not step_order.empty and "Ordered" in step_order.columns else []
                )
                notes = []
                if low_count_levels:
                    notes.append(
                        t(
                            "categories_steps.screen_note_sparse_template",
                            levels=", ".join(map(str, low_count_levels)),
                        )
                    )
                else:
                    notes.append(t("categories_steps.screen_note_counts_ok"))
                notes.append(
                    t("categories_steps.screen_note_avg_ok")
                    if avg_ok else
                    t("categories_steps.screen_note_avg_not_monotonic")
                )
                if disordered_levels:
                    notes.append(
                        t(
                            "categories_steps.screen_note_disordered_template",
                            levels=", ".join(disordered_levels),
                        )
                    )
                else:
                    notes.append(t("categories_steps.screen_note_no_disordered"))
                notes.append(t("categories_steps.screen_note_residual_advice"))
                st.markdown("\n".join(notes))

            st.download_button(
                t("categories_steps.download_button"),
                data=to_csv_bytes(cat_tbl),
                file_name="mfrm_category_stats.csv",
                mime="text/csv",
            )
        else:
            st.info(t("categories_steps.no_diagnostics_info"))
    else:
        st.info(t("categories_steps.no_calc_fn_info"))

    # Step ordering
    header_cols = st.columns([5, 1])
    with header_cols[0]:
        st.subheader(t("categories_steps.step_subheader"))
    with header_cols[1]:
        render_help_popover("threshold_map")
    st.caption(t("categories_steps.step_caption"))
    step_tbl = result.get("steps")
    if step_tbl is not None and not step_tbl.empty:
        st.dataframe(step_tbl, width="stretch")
        calc_step_fn = core.get("calc_step_order")
        if calc_step_fn:
            step_order = calc_step_fn(step_tbl)
            if not step_order.empty:
                st.dataframe(step_order, width="stretch")
                disordered = step_order[step_order.get("Ordered", pd.Series(dtype=bool)) == False]
                if not disordered.empty:
                    st.warning(
                        t("categories_steps.step_disordered_warning_template", n=len(disordered))
                    )
                else:
                    st.success(t("categories_steps.step_ordered_success"))
    else:
        st.caption(t("categories_steps.step_no_params_caption"))

    slope_tbl = result.get("slopes", pd.DataFrame())
    if isinstance(slope_tbl, pd.DataFrame) and not slope_tbl.empty:
        st.subheader(t("categories_steps.slope_subheader"))
        st.caption(t("categories_steps.slope_caption"))
        st.dataframe(slope_tbl, width="stretch")


# ---------------------------------------------------------------------------
# Facet Dashboard tab
# ---------------------------------------------------------------------------

def show_facet_dashboard(
    result: dict, diagnostics: dict, facet_cols: list[str],
    *, all_bias_results: dict | None = None,
) -> None:
    """Single-screen facet quality summary: severity, fit, central tendency, bias flags."""
    st.subheader(t("facet_dashboard.subheader"))
    st.caption(t("facet_dashboard.intro_caption"))

    measures = diagnostics.get("measures", pd.DataFrame())
    if measures.empty or "Facet" not in measures.columns:
        st.info(t("facet_dashboard.no_measures_info"))
        return

    # --- Identify rater facet ---
    config_facet_names = result.get("config", {}).get("facet_names", facet_cols)
    if not config_facet_names:
        st.info(t("facet_dashboard.no_facet_cols_info"))
        return

    rater_facet = st.selectbox(
        t("facet_dashboard.target_facet_label"),
        list(config_facet_names),
        index=0,
        key="rater_dashboard_facet",
        help=t("facet_dashboard.target_facet_help"),
    )

    rater_df = measures[measures["Facet"] == rater_facet].copy()
    if rater_df.empty:
        st.info(t("facet_dashboard.no_facet_measures_info_template", facet=rater_facet))
        return

    # Ensure numeric columns
    for col in ["Estimate", "SE", "Infit", "Outfit", "Infit_ZSTD", "Outfit_ZSTD"]:
        if col in rater_df.columns:
            rater_df[col] = pd.to_numeric(rater_df[col], errors="coerce")

    estimates = rater_df["Estimate"].dropna()
    n_raters = len(rater_df)
    if n_raters < 2:
        st.info(t("facet_dashboard.need_two_elements_info_template", facet=rater_facet))
        return

    mean_sev = float(estimates.mean())
    sd_sev = float(estimates.std())

    # --- Flag columns ---
    flags = []

    # 1) Severity outlier: |severity| > 2 SD from mean
    if sd_sev > 0:
        rater_df["Severity_Z"] = ((rater_df["Estimate"] - mean_sev) / sd_sev).round(2)
        rater_df["Flag_Severity"] = rater_df["Severity_Z"].abs() > 2.0
    else:
        rater_df["Severity_Z"] = 0.0
        rater_df["Flag_Severity"] = False
    flags.append("Flag_Severity")

    # 2) Misfit: Infit > 1.5 or Infit < 0.5 or Outfit > 2.0
    rater_df["Flag_Misfit"] = False
    if "Infit" in rater_df.columns:
        rater_df["Flag_Misfit"] = (
            (rater_df["Infit"] > 1.5) | (rater_df["Infit"] < 0.5)
        )
    if "Outfit" in rater_df.columns:
        rater_df["Flag_Misfit"] = rater_df["Flag_Misfit"] | (rater_df["Outfit"] > 2.0)
    flags.append("Flag_Misfit")

    # 3) Central tendency (Myford & Wolfe, 2003): Infit ≤ 1.40 may indicate
    #    restricted use of scale. We check Outfit_ZSTD < -2.0 as a proxy for
    #    overly predictable (central tendency) patterns.
    rater_df["Flag_Central"] = False
    if "Outfit_ZSTD" in rater_df.columns and "Infit" in rater_df.columns:
        rater_df["Flag_Central"] = (
            (rater_df["Outfit_ZSTD"] < -2.0) & (rater_df["Infit"] <= 1.4)
        )
    flags.append("Flag_Central")

    # 4) Significant bias count (from all_bias_results)
    bias_counts: dict[str, int] = {}
    all_bias = all_bias_results or {}
    for pair_key, br in all_bias.items():
        if rater_facet not in pair_key:
            continue
        tbl = br.get("table", pd.DataFrame())
        if tbl.empty or "t" not in tbl.columns:
            continue
        t_col = pd.to_numeric(tbl["t"], errors="coerce")
        # Identify which column holds the rater element
        rater_col = None
        for c in [rater_facet, "FacetA", "FacetB"]:
            if c in tbl.columns:
                rater_col = c
                break
        if rater_col is None:
            continue
        sig_mask = t_col.abs() >= 2.0
        for elem, cnt in tbl.loc[sig_mask, rater_col].value_counts().items():
            bias_counts[elem] = bias_counts.get(elem, 0) + int(cnt)

    elem_col = "Element" if "Element" in rater_df.columns else rater_df.columns[1]
    rater_df["Sig_Bias_Count"] = rater_df[elem_col].map(bias_counts).fillna(0).astype(int)
    rater_df["Flag_Bias"] = rater_df["Sig_Bias_Count"] > 0
    flags.append("Flag_Bias")

    # --- Summary metrics ---
    n_flagged_any = int(rater_df[flags].any(axis=1).sum())
    col1, col2, col3, col4, col5 = st.columns(5)
    col1.metric(t("facet_dashboard.metric_elements"), n_raters)
    col2.metric(
        t("facet_dashboard.metric_severity_outliers"),
        int(rater_df["Flag_Severity"].sum()),
        help=t("facet_dashboard.metric_severity_outliers_help"),
    )
    col3.metric(
        t("facet_dashboard.metric_misfitting"),
        int(rater_df["Flag_Misfit"].sum()),
        help=t("facet_dashboard.metric_misfitting_help"),
    )
    col4.metric(
        t("facet_dashboard.metric_central_tendency"),
        int(rater_df["Flag_Central"].sum()),
        help=t("facet_dashboard.metric_central_tendency_help"),
    )
    col5.metric(t("facet_dashboard.metric_any_flag"), n_flagged_any)

    if n_flagged_any == 0:
        st.success(t("facet_dashboard.all_clean_success_template", facet=rater_facet))
    else:
        st.warning(
            t(
                "facet_dashboard.flagged_warning_template",
                n_flagged=n_flagged_any,
                n_total=n_raters,
                facet=rater_facet,
            )
        )

    # --- Full rater table ---
    display_cols = [elem_col, "Estimate", "SE", "Severity_Z"]
    for c in ["Infit", "Outfit", "Infit_ZSTD", "Outfit_ZSTD"]:
        if c in rater_df.columns:
            display_cols.append(c)
    display_cols.extend(["Sig_Bias_Count"] + flags)

    st.subheader(t("facet_dashboard.detail_subheader_template", facet=rater_facet))
    show_flagged_only = st.checkbox(
        t("facet_dashboard.show_flagged_only_label"), value=False, key="rater_dash_flagged",
        help=t("facet_dashboard.show_flagged_only_help"),
    )
    display_df = rater_df[display_cols].copy()
    if show_flagged_only:
        display_df = display_df[display_df[flags].any(axis=1)]

    st.dataframe(
        display_df.style.map(
            lambda v: "background-color: #ffcccc" if v is True else "",
            subset=flags,
        ),
        width="stretch",
    )

    # --- Severity distribution chart ---
    st.subheader(t("facet_dashboard.distribution_subheader_template", facet=rater_facet))
    sev_vals = rater_df["Estimate"].dropna().values
    colors_sev = ["#e74c3c" if f else "#3498db" for f in rater_df["Flag_Severity"]]
    labels_sev = [str(v) for v in rater_df[elem_col].values]
    labels_sev_compact = _compact_label_list(labels_sev, max_chars=44)

    fig_sev = go.Figure(go.Bar(
        x=sev_vals,
        y=labels_sev,
        orientation="h",
        marker_color=colors_sev,
        customdata=np.array(labels_sev, dtype=object),
        hovertemplate="%{customdata}<br>Severity=%{x:.2f}<extra></extra>",
    ))
    fig_sev.add_vline(x=mean_sev, line_dash="dash", line_color="black", line_width=1,
                      annotation_text=f"Mean = {mean_sev:.2f}")
    if sd_sev > 0:
        fig_sev.add_vline(x=mean_sev - 2 * sd_sev, line_dash="dot", line_color="red", line_width=0.7,
                          annotation_text="−2 SD")
        fig_sev.add_vline(x=mean_sev + 2 * sd_sev, line_dash="dot", line_color="red", line_width=0.7,
                          annotation_text="+2 SD")
    fig_sev.update_layout(
        xaxis_title="Severity (logits)", height=max(280, len(rater_df) * 25),
        yaxis=dict(autorange="reversed"), template="plotly_white",
        margin=_readable_plot_margins(y_labels=labels_sev, base_left=140),
    )
    fig_sev.update_yaxes(tickmode="array", tickvals=labels_sev, ticktext=labels_sev_compact, automargin=True)
    st.plotly_chart(fig_sev, width="stretch")
    _offer_fig_download(fig_sev, "facet_severity", "Download Measure Distribution (PNG 300 DPI)")

    # --- Interpretation guide ---
    with st.expander(t("facet_dashboard.interpretation_expander")):
        st.markdown(t("facet_dashboard.interpretation_body_template", facet=rater_facet))

    st.download_button(
        t("facet_dashboard.download_button"),
        data=to_csv_bytes(display_df),
        file_name="mfrm_rater_dashboard.csv",
        mime="text/csv",
        key="dl_rater_dashboard",
    )


# ---------------------------------------------------------------------------
# Inter-rater Agreement tab
# ---------------------------------------------------------------------------

def show_agreement_section(
    result: dict, diagnostics: dict, facet_cols: list[str], core: dict
) -> None:
    """Render inter-rater agreement metrics."""
    header_cols = st.columns([5, 1])
    with header_cols[0]:
        st.subheader(t("agreement.subheader"))
    with header_cols[1]:
        render_help_popover("rater_agreement")
    st.caption(t("agreement.intro_caption"))

    calc_agreement_fn = core.get("calc_interrater_agreement")
    obs_df = diagnostics.get("obs")

    if not calc_agreement_fn:
        st.info(t("agreement.no_calc_fn_info"))
        return

    if obs_df is None or obs_df.empty:
        st.info(t("agreement.no_obs_info"))
        return

    config_facet_names = result.get("config", {}).get("facet_names", facet_cols)
    if not config_facet_names:
        st.info(t("agreement.no_facet_cols_info"))
        return

    facet_options = list(config_facet_names)
    default_agreement_facet = _infer_facet_by_role(result, diagnostics, facet_options, "rater")
    default_facet_index = (
        facet_options.index(default_agreement_facet)
        if default_agreement_facet in facet_options else
        0
    )
    agreement_facet = st.selectbox(
        t("agreement.facet_select_label"),
        facet_options,
        index=default_facet_index,
        key="agreement_facet",
        help=t("agreement.facet_select_help"),
    )

    all_facet_cols = ["Person"] + list(config_facet_names)
    agreement = calc_agreement_fn(obs_df, all_facet_cols, agreement_facet, res=result)

    if agreement["summary"].empty:
        st.info(t("agreement.no_summary_info_template", facet=agreement_facet))
        return

    st.subheader(t("agreement.summary_subheader"))
    st.dataframe(agreement["summary"], width="stretch")

    # Interpretation
    summary = agreement["summary"]
    if "ExactAgreement" in summary.columns:
        exact_pct = summary["ExactAgreement"].iloc[0]
        if np.isfinite(exact_pct):
            exact_pct_100 = exact_pct * 100
            pct_str = f"{exact_pct_100:.1f}"
            if exact_pct_100 >= 70:
                st.success(t("agreement.exact_good_template", pct=pct_str, facet=agreement_facet))
            elif exact_pct_100 >= 50:
                st.info(t("agreement.exact_moderate_template", pct=pct_str, facet=agreement_facet))
            else:
                st.warning(t("agreement.exact_low_template", pct=pct_str, facet=agreement_facet))

    calc_alpha_fn = core.get("calc_krippendorff_alpha")
    if calc_alpha_fn:
        with st.expander(t("agreement.krippendorff_expander"), expanded=False):
            st.caption(t("agreement.krippendorff_caption"))
            alpha_metric = st.selectbox(
                t("agreement.krippendorff_metric_label"),
                list(KRIPPENDORFF_ALPHA_METRICS),
                index=0,
                format_func=lambda value: t(f"agreement.krippendorff_metric_{value}"),
                key=f"krippendorff_metric_{agreement_facet}",
                help=t("agreement.krippendorff_metric_help"),
            )
            alpha_result = calc_alpha_fn(
                obs_df,
                all_facet_cols,
                agreement_facet,
                metric=str(alpha_metric),
            )
            alpha_summary = alpha_result.get("summary", pd.DataFrame())
            alpha_coverage = alpha_result.get("coverage", pd.DataFrame())
            if isinstance(alpha_summary, pd.DataFrame) and not alpha_summary.empty:
                row = alpha_summary.iloc[0]
                status = str(row.get("Status", "Unavailable"))
                plain = str(row.get("PlainLanguage", ""))
                if status == "Ready":
                    st.success(t("agreement.krippendorff_status_template", status=status, message=plain))
                elif status == "Caution":
                    st.info(t("agreement.krippendorff_status_template", status=status, message=plain))
                elif status == "Review":
                    st.warning(t("agreement.krippendorff_status_template", status=status, message=plain))
                else:
                    st.info(t("agreement.krippendorff_status_template", status=status, message=plain))
                st.dataframe(alpha_summary, width="stretch", hide_index=True)
                st.caption(t("agreement.krippendorff_interpretation_caption"))
                if isinstance(alpha_coverage, pd.DataFrame) and not alpha_coverage.empty:
                    with st.expander(t("agreement.krippendorff_coverage_expander"), expanded=False):
                        st.dataframe(alpha_coverage, width="stretch", hide_index=True)
                st.download_button(
                    t("agreement.krippendorff_download_button"),
                    data=to_csv_bytes(alpha_summary),
                    file_name="mfrm_krippendorff_alpha_experimental.csv",
                    mime="text/csv",
                    key=f"dl_krippendorff_alpha_{agreement_facet}_{alpha_metric}",
                )
            else:
                st.info(t("agreement.krippendorff_unavailable_info"))

    try:
        scoring_decision = build_scoring_consistency_decision(
            result,
            diagnostics,
            all_facet_cols,
            rater_facet=agreement_facet,
        )
    except Exception:
        scoring_decision = pd.DataFrame()
    if isinstance(scoring_decision, pd.DataFrame) and not scoring_decision.empty:
        try:
            first_read_summary = build_scoring_quality_first_read_summary(
                result,
                diagnostics,
                all_facet_cols,
                rater_facet=agreement_facet,
            )
        except Exception:
            first_read_summary = pd.DataFrame()
        if isinstance(first_read_summary, pd.DataFrame) and not first_read_summary.empty:
            first_row = first_read_summary.iloc[0]
            with st.container(border=True):
                st.markdown(f"#### {t('agreement.first_read_subheader')}")
                st.caption(t("agreement.first_read_caption"))
                c1, c2, c3 = st.columns(3)
                c1.metric(t("agreement.first_read_readiness_label"), str(first_row.get("ReadinessLabel", "")))
                c2.metric(t("agreement.first_read_blockers_label"), str(first_row.get("BlockingItems", "")))
                c3.metric(t("agreement.first_read_caveats_label"), str(first_row.get("CaveatItems", "")))
                st.markdown(f"**{t('agreement.first_read_next_action_label')}:** {first_row.get('NextAction', '')}")
                st.markdown(f"**{t('agreement.first_read_owner_label')}:** {first_row.get('NextOwner', '')}")
                st.markdown(f"**{t('agreement.first_read_evidence_label')}:** `{first_row.get('FirstEvidenceToOpen', '')}`")
                st.caption(str(first_row.get("SafeClaim", "")))
                st.download_button(
                    t("agreement.first_read_download_button"),
                    data=to_csv_bytes(first_read_summary),
                    file_name="mfrm_scoring_quality_first_read_summary.csv",
                    mime="text/csv",
                    key=f"dl_scoring_quality_first_read_summary_{agreement_facet}",
                )

        st.subheader(t("agreement.scoring_consistency_subheader"))
        st.caption(t("agreement.scoring_consistency_caption"))
        st.dataframe(scoring_decision, width="stretch", hide_index=True)
        dl_cols = st.columns(2)
        with dl_cols[0]:
            st.download_button(
                t("agreement.scoring_consistency_download_button"),
                data=to_csv_bytes(scoring_decision),
                file_name="mfrm_scoring_consistency_decision.csv",
                mime="text/csv",
                key=f"dl_scoring_consistency_decision_{agreement_facet}",
            )
        try:
            qc_recommendations = build_quality_control_recommendations(
                result,
                diagnostics,
                all_facet_cols,
                rater_facet=agreement_facet,
            )
        except Exception:
            qc_recommendations = pd.DataFrame()
        if isinstance(qc_recommendations, pd.DataFrame) and not qc_recommendations.empty:
            st.subheader(t("agreement.qc_recommendations_subheader"))
            st.caption(t("agreement.qc_recommendations_caption"))
            st.dataframe(qc_recommendations, width="stretch", hide_index=True)
            with dl_cols[1]:
                st.download_button(
                    t("agreement.qc_recommendations_download_button"),
                    data=to_csv_bytes(qc_recommendations),
                    file_name="mfrm_quality_control_recommendations.csv",
                    mime="text/csv",
                    key=f"dl_quality_control_recommendations_{agreement_facet}",
                )
        else:
            qc_recommendations = pd.DataFrame()

        try:
            qc_todo = build_quality_control_todo_checklist(
                result,
                diagnostics,
                all_facet_cols,
                rater_facet=agreement_facet,
            )
        except Exception:
            qc_todo = pd.DataFrame()
        if isinstance(qc_todo, pd.DataFrame) and not qc_todo.empty:
            st.subheader(t("agreement.qc_todo_subheader"))
            st.caption(t("agreement.qc_todo_caption"))
            disabled_cols = [col for col in qc_todo.columns if col != "Done"]
            try:
                st.data_editor(
                    qc_todo,
                    width="stretch",
                    hide_index=True,
                    disabled=disabled_cols,
                    column_config={
                        "Done": st.column_config.CheckboxColumn(
                            t("agreement.qc_todo_done_column"),
                            help=t("agreement.qc_todo_done_help"),
                        ),
                        "BlockingForReport": st.column_config.CheckboxColumn(
                            t("agreement.qc_todo_blocking_column"),
                            disabled=True,
                        ),
                        "NeedsCaveat": st.column_config.CheckboxColumn(
                            t("agreement.qc_todo_caveat_column"),
                            disabled=True,
                        ),
                    },
                    key=f"qc_todo_editor_{agreement_facet}",
                )
            except Exception:
                st.dataframe(qc_todo, width="stretch", hide_index=True)
            st.download_button(
                t("agreement.qc_todo_download_button"),
                data=to_csv_bytes(qc_todo),
                file_name="mfrm_quality_control_todo_checklist.csv",
                mime="text/csv",
                key=f"dl_quality_control_todo_checklist_{agreement_facet}",
            )

        with st.expander(t("agreement.term_guide_expander"), expanded=False):
            term_guide = scoring_quality_term_guide()
            st.caption(t("agreement.term_guide_caption"))
            st.dataframe(term_guide, width="stretch", hide_index=True)
            st.download_button(
                t("agreement.term_guide_download_button"),
                data=to_csv_bytes(term_guide),
                file_name="mfrm_scoring_quality_term_guide.csv",
                mime="text/csv",
                key=f"dl_scoring_quality_term_guide_{agreement_facet}",
            )

        with st.expander(t("agreement.apa_draft_expander"), expanded=False):
            apa_draft = generate_apa_scoring_quality_draft(
                result,
                diagnostics,
                decision_table=scoring_decision,
                qc_table=qc_recommendations,
            )
            st.markdown(apa_draft)
            st.download_button(
                t("agreement.apa_draft_download_button"),
                data=apa_draft.encode("utf-8"),
                file_name="apa_scoring_quality_draft.md",
                mime="text/markdown",
                key=f"dl_apa_scoring_quality_draft_{agreement_facet}",
            )

    st.subheader(t("agreement.pairwise_subheader"))
    pairs_tbl = agreement.get("pairs", pd.DataFrame())
    if not pairs_tbl.empty:
        st.dataframe(pairs_tbl, width="stretch")

        # Correlation heatmap (if enough pairs)
        if len(pairs_tbl) >= 3 and "Corr" in pairs_tbl.columns:
            raters = sorted(set(pairs_tbl["Element1"].tolist() + pairs_tbl["Element2"].tolist()))
            n = len(raters)
            corr_matrix = np.full((n, n), np.nan)
            np.fill_diagonal(corr_matrix, 1.0)
            rater_idx = {r: i for i, r in enumerate(raters)}
            for _, row in pairs_tbl.iterrows():
                i, j = rater_idx[row["Element1"]], rater_idx[row["Element2"]]
                corr_matrix[i, j] = row["Corr"]
                corr_matrix[j, i] = row["Corr"]

            # Plotly heatmap
            text_matrix = [[f"{corr_matrix[i, j]:.2f}" if np.isfinite(corr_matrix[i, j]) else ""
                            for j in range(n)] for i in range(n)]
            fig_hm = go.Figure(go.Heatmap(
                z=corr_matrix, x=raters, y=raters,
                colorscale="RdYlGn", zmin=0, zmax=1,
                text=text_matrix, texttemplate="%{text}", textfont=dict(size=10),
                colorbar=dict(title="Correlation"),
            ))
            fig_hm.update_layout(title=f"{agreement_facet} Correlation Matrix",
                                 height=max(350, n * 40), template="plotly_white")
            st.plotly_chart(fig_hm, width="stretch")

        st.download_button(
            t("agreement.pairs_download_button"),
            data=to_csv_bytes(pairs_tbl),
            file_name="mfrm_agreement_pairs.csv",
            mime="text/csv",
        )
    else:
        st.caption(t("agreement.no_pairs_caption"))


# ---------------------------------------------------------------------------
# Reproducible script generators
# ---------------------------------------------------------------------------

def _records_json_for_script(df: pd.DataFrame, columns: list[str] | None = None) -> str:
    if not isinstance(df, pd.DataFrame) or df.empty:
        return "[]"
    out = df.copy()
    if columns is not None:
        out = out[[col for col in columns if col in out.columns]]
    out = out.where(pd.notna(out), None)
    return json.dumps(out.to_dict("records"), ensure_ascii=False, default=str)


def build_script_support_status(result: dict) -> dict:
    """Describe which downloadable scripts can reproduce the current run."""
    config = result.get("config", {}) if isinstance(result, dict) else {}
    model = str(config.get("model", "RSM")).upper()
    method = str(config.get("method", "JMLE")).upper()
    pop = config.get("population_model", {})
    uses_latent_regression = bool(isinstance(pop, dict) and pop.get("enabled"))
    uses_gpcm = model == "GPCM"
    portable_blockers = []
    if uses_gpcm:
        portable_blockers.append("bounded GPCM")
    if uses_latent_regression:
        portable_blockers.append("latent-regression population_formula")
    portable_available = not portable_blockers
    portable_scope = (
        "RSM/PCM fixed-effect JMLE reproducibility check"
        if portable_available else
        "unsupported stub only"
    )
    portable_action = (
        "Use for a compact fixed-effect check; app-engine runner is still the exact current path for MML outputs."
        if portable_available and method == "MML" else
        "Use for exact fixed-effect JMLE reproduction of ordinary RSM/PCM runs."
        if portable_available else
        "Use the Python app-engine runner; portable self-contained JMLE/R scripts do not implement "
        + " + ".join(portable_blockers) + "."
    )
    rows = [
        {
            "Script": "Python app-engine runner",
            "Available": True,
            "ExactCurrentPath": True,
            "Scope": "Imports streamlit_app.py and uses the current embedded engine, including MML, GPCM, latent regression, prediction, simulation, and diagnostics.",
            "Action": "Use this for reproducibility of the current app result.",
        },
        {
            "Script": "Python portable self-contained JMLE",
            "Available": portable_available,
            "ExactCurrentPath": portable_available and method == "JMLE",
            "Scope": portable_scope,
            "Action": portable_action,
        },
        {
            "Script": "R portable self-contained JMLE",
            "Available": portable_available,
            "ExactCurrentPath": portable_available and method == "JMLE",
            "Scope": portable_scope,
            "Action": portable_action,
        },
    ]
    table = pd.DataFrame(rows)
    return {
        "table": table,
        "portable_available": bool(portable_available),
        "portable_blockers": portable_blockers,
        "app_engine_exact": True,
        "scope": (
            "app_engine_exact; portable_jmle_available_for_rsm_pcm_fixed_effect_checks"
            if portable_available else
            "app_engine_exact; portable_jmle_unsupported_stub_for_current_model"
        ),
    }


def _generate_app_engine_runner_script(
    result: dict,
    diagnostics: dict,
    bias_pairs: list[tuple[str, str]] | None = None,
) -> str:
    """Generate a runner that reuses this app's current embedded engine."""
    config = result.get("config", {})
    out = st.session_state.get("facets_mode_output", {})

    method = config.get("method", "JMLE")
    model = config.get("model", "RSM")
    facet_names = config.get("facet_names", [])
    step_facet = config.get("step_facet")
    slope_facet = config.get("slope_facet")
    weight_col = config.get("weight_col")
    keep_original = bool(out.get("_keep_original", config.get("keep_original", False)))
    input_rating_min = out.get("_rating_min", config.get("input_rating_min"))
    input_rating_max = out.get("_rating_max", config.get("input_rating_max"))
    maxit = out.get("_maxit", config.get("maxit", 400))
    reltol = out.get("_reltol", config.get("reltol", 1e-6))
    quad_points = int(config.get("quad_points") or out.get("_quad_points", 15) or 15)
    mml_engine = (
        config.get("mml_engine_requested")
        or config.get("ui_mml_engine")
        or config.get("mml_engine")
        or "EM"
    )
    compute_pca = bool(config.get("compute_residual_pca", diagnostics.get("pca_enabled", True)))
    compute_marginal = bool(config.get("compute_strict_marginal", diagnostics.get("marginal_fit_enabled", False)))
    strict_pairwise = bool(config.get("strict_marginal_pairwise", False))
    strict_max_pair_cells = int(config.get("strict_marginal_max_pair_cells") or 400)
    compute_pv = bool(config.get("compute_plausible_values", False))
    n_pv = int(config.get("n_plausible_values") or 0)
    pv_seed = config.get("plausible_seed")
    if pv_seed is None:
        pv_seed = 20260411

    anchor_audit = config.get("anchor_audit", {})
    anchor_settings = anchor_audit.get("settings", {}) if isinstance(anchor_audit, dict) else {}
    valid_anchors = anchor_audit.get("valid_anchors", pd.DataFrame()) if isinstance(anchor_audit, dict) else pd.DataFrame()
    valid_group_anchors = anchor_audit.get("valid_group_anchors", pd.DataFrame()) if isinstance(anchor_audit, dict) else pd.DataFrame()
    anchor_json = _records_json_for_script(valid_anchors, ["Facet", "Level", "Anchor"])
    group_anchor_json = _records_json_for_script(valid_group_anchors, ["Facet", "Level", "Group", "GroupValue"])
    population_bundle = result.get("population", {})
    population_person = population_bundle.get("person_data", pd.DataFrame()) if isinstance(population_bundle, dict) else pd.DataFrame()
    population_json = _records_json_for_script(population_person) if isinstance(population_person, pd.DataFrame) else "[]"
    bias_pairs_repr = repr(list(bias_pairs or []))

    script = f'''\
#!/usr/bin/env python3
"""
Current-engine MFRM runner.

This script imports streamlit_app.py and calls the same embedded Python engine
used by the app. Use it when you need to reproduce the current optimizer path,
including MML Auto/Direct/Hybrid/EM, PCM, strict marginal diagnostics, posterior
scoring, plausible values, GPCM slope estimates, latent-regression population
models, score-support handling, and anchor audit filtering.

Place this file next to streamlit_app.py and pass a data CSV:

    python mfrm_app_engine_runner.py --input your_data.csv --output-dir mfrm_outputs
"""

from __future__ import annotations

import argparse
import importlib.util
import json
from itertools import combinations
from pathlib import Path

import pandas as pd


DATA_FILE = "your_data.csv"
NEW_DESIGN_FILE = ""  # Optional CSV/TSV with Person + fitted facet columns for scenario prediction.
APP_PATH = Path(__file__).with_name("streamlit_app.py")
OUTPUT_DIR = Path("mfrm_outputs")

PERSON_COL = {repr(out.get("person_col", "Person"))}
FACET_COLS = {repr(list(out.get("facet_cols", facet_names)))}
SCORE_COL = {repr(out.get("score_col", "Score"))}
WEIGHT_COL = {repr(weight_col)}
MODEL = {repr(model)}
METHOD = {repr(method)}
STEP_FACET = {repr(step_facet)}
SLOPE_FACET = {repr(slope_facet)}
NONCENTER_FACET = {repr(config.get("noncenter_facet", "Person"))}
DUMMY_FACETS = {repr(list(config.get("dummy_facets", [])))}
POSITIVE_FACETS = {repr(list(config.get("positive_facets", [])))}
KEEP_ORIGINAL = {repr(keep_original)}
RATING_MIN = {repr(input_rating_min)}
RATING_MAX = {repr(input_rating_max)}
QUAD_POINTS = {quad_points}
POPULATION_PRIOR_SD = {repr(float(config.get("population_prior_sd") or 1.0))}
MAXIT = {int(maxit)}
RELTOL = {float(reltol)}
MML_ENGINE = {repr(mml_engine)}
POPULATION_FORMULA = {repr(config.get("population_formula", ""))}
POPULATION_STANDARDIZE_NUMERIC = {repr(bool(config.get("population_standardize_numeric", False)))}
POPULATION_CATEGORICAL_TERMS = {repr(list(config.get("population_categorical_terms", [])))}
POPULATION_NUMERIC_TERMS = {repr(list(config.get("population_numeric_terms", [])))}
PERSON_ID_COL = "Person"
ANCHOR_POLICY = {repr(config.get("anchor_policy", "warn"))}
MIN_COMMON_ANCHORS = {int(anchor_settings.get("min_common_anchors", 2))}
MIN_OBS_PER_ELEMENT = {int(anchor_settings.get("min_obs_per_element", 2))}
MIN_OBS_PER_CATEGORY = {int(anchor_settings.get("min_obs_per_category", 1))}
COMPUTE_PCA = {repr(compute_pca)}
COMPUTE_STRICT_MARGINAL = {repr(compute_marginal)}
STRICT_MARGINAL_PAIRWISE = {repr(strict_pairwise)}
STRICT_MARGINAL_MAX_PAIR_CELLS = {strict_max_pair_cells}
COMPUTE_EB_SHRINKAGE = {repr(bool(config.get("compute_eb_shrinkage", diagnostics.get("eb_shrinkage_enabled", False))))}
COMPUTE_PLAUSIBLE_VALUES = {repr(compute_pv)}
N_PLAUSIBLE_VALUES = {n_pv}
PLAUSIBLE_SEED = {int(pv_seed)}
RUN_FITTED_SIMULATION = False
SIMULATION_REPLICATES = {int(st.session_state.get("prediction_sim_replicates", 100) or 100)}
SIMULATION_SEED = {int(st.session_state.get("prediction_sim_seed", 20260411) or 20260411)}
RUN_REFIT_SIMULATION = False
REFIT_SIMULATION_REPLICATES = {int(st.session_state.get("refit_sim_replicates", 3) or 3)}
REFIT_SIMULATION_MISSING_RATE = {float(st.session_state.get("refit_sim_missing_rate", 0.0) or 0.0)}
REFIT_SIMULATION_MAXIT = {int(st.session_state.get("refit_sim_maxit", 30) or 30)}
REFIT_SIMULATION_SEED = {int(st.session_state.get("refit_sim_seed", 20260411) or 20260411)}
REFIT_SIMULATION_METHOD = {repr(st.session_state.get("refit_sim_method") or method)}
BIAS_MODE = {repr(config.get("bias_mode", "Selected pair"))}
SELECTED_BIAS_PAIR = {repr(config.get("selected_bias_pair"))}
BIAS_PAIRS = {bias_pairs_repr}

ANCHOR_RECORDS = json.loads({anchor_json!r})
GROUP_ANCHOR_RECORDS = json.loads({group_anchor_json!r})
POPULATION_PERSON_RECORDS = json.loads({population_json!r})


def load_app_engine(app_path: Path):
    if not app_path.exists():
        raise FileNotFoundError(
            f"Cannot find {{app_path}}. Place this runner next to streamlit_app.py "
            "or edit APP_PATH."
        )
    spec = importlib.util.spec_from_file_location("mfrm_streamlit_app_engine", app_path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Could not import app engine from {{app_path}}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def parse_args():
    parser = argparse.ArgumentParser(description="Run the MFRM Streamlit app engine locally.")
    parser.add_argument("--input", default=DATA_FILE, help="Long-format rating data CSV.")
    parser.add_argument("--output-dir", default=str(OUTPUT_DIR), help="Folder for generated CSV outputs.")
    parser.add_argument("--app-path", default=str(APP_PATH), help="Path to streamlit_app.py.")
    parser.add_argument("--new-design", default=NEW_DESIGN_FILE, help="Optional held-out design CSV/TSV.")
    return parser.parse_args()


def write_csv(name: str, frame) -> bool:
    if isinstance(frame, pd.DataFrame) and not frame.empty:
        OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
        out_path = OUTPUT_DIR / f"mfrm_{{name}}.csv"
        frame.to_csv(out_path, index=False)
        print(f"  wrote {{out_path}} ({{len(frame)}} rows)")
        return True
    return False


def main() -> None:
    global OUTPUT_DIR
    args = parse_args()
    OUTPUT_DIR = Path(args.output_dir).expanduser()
    app = load_app_engine(Path(args.app_path).expanduser())
    data = pd.read_csv(args.input)
    anchor_df = pd.DataFrame(ANCHOR_RECORDS)
    group_anchor_df = pd.DataFrame(GROUP_ANCHOR_RECORDS)
    population_person_df = pd.DataFrame(POPULATION_PERSON_RECORDS)

    result = app.mfrm_estimate(
        data=data,
        person_col=PERSON_COL,
        facet_cols=FACET_COLS,
        score_col=SCORE_COL,
        rating_min=RATING_MIN,
        rating_max=RATING_MAX,
        weight_col=WEIGHT_COL,
        keep_original=KEEP_ORIGINAL,
        model=MODEL,
        method=METHOD,
        step_facet=STEP_FACET,
        slope_facet=SLOPE_FACET,
        person_data=population_person_df,
        person_id_col=PERSON_ID_COL,
        population_formula=POPULATION_FORMULA,
        population_standardize_numeric=POPULATION_STANDARDIZE_NUMERIC,
        population_categorical_terms=POPULATION_CATEGORICAL_TERMS,
        population_numeric_terms=POPULATION_NUMERIC_TERMS,
        anchor_df=anchor_df,
        group_anchor_df=group_anchor_df,
        noncenter_facet=NONCENTER_FACET,
        dummy_facets=DUMMY_FACETS,
        positive_facets=POSITIVE_FACETS,
        quad_points=QUAD_POINTS,
        population_prior_sd=POPULATION_PRIOR_SD,
        maxit=MAXIT,
        reltol=RELTOL,
        mml_engine=MML_ENGINE,
        anchor_policy=ANCHOR_POLICY,
        min_common_anchors=MIN_COMMON_ANCHORS,
        min_obs_per_element=MIN_OBS_PER_ELEMENT,
        min_obs_per_category=MIN_OBS_PER_CATEGORY,
        compute_plausible_values=COMPUTE_PLAUSIBLE_VALUES,
        n_plausible_values=N_PLAUSIBLE_VALUES,
        plausible_seed=PLAUSIBLE_SEED,
    )

    diagnostics = app.mfrm_diagnostics(
        result,
        compute_pca=COMPUTE_PCA,
        compute_marginal=COMPUTE_STRICT_MARGINAL,
        marginal_pairwise=STRICT_MARGINAL_PAIRWISE,
        marginal_max_pair_cells=STRICT_MARGINAL_MAX_PAIR_CELLS,
        compute_eb_shrinkage=COMPUTE_EB_SHRINKAGE,
    )

    print(result["summary"].to_string(index=False))
    print("\\nWriting CSV outputs:")
    write_csv("summary", result.get("summary"))
    write_csv("convergence", result.get("convergence"))
    write_csv("score_map", result.get("prep", {{}}).get("score_map"))
    write_csv("person_measures", result.get("facets", {{}}).get("person"))
    write_csv("facet_measures", result.get("facets", {{}}).get("others"))
    write_csv("steps", result.get("steps"))
    write_csv("gpcm_slopes", result.get("slopes"))
    population = result.get("population", {{}})
    if isinstance(population, dict):
        write_csv("population_coefficients", population.get("coefficients"))
        write_csv("population_person_data", population.get("person_data"))
        write_csv("population_numeric_transforms", population.get("numeric_transforms"))
        term_types = pd.DataFrame([
            {{"Term": term, "Type": term_type}}
            for term, term_type in dict(population.get("term_types", {{}})).items()
        ])
        write_csv("population_term_types", term_types)
    write_csv("diagnostic_measures", diagnostics.get("measures"))
    write_csv("fit_statistics", diagnostics.get("fit"))
    write_csv("reliability", diagnostics.get("reliability"))
    write_csv("krippendorff_alpha_experimental", diagnostics.get("krippendorff_alpha"))
    if hasattr(app, "build_krippendorff_alpha_interpretation"):
        write_csv("krippendorff_alpha_interpretation", app.build_krippendorff_alpha_interpretation(result, diagnostics))
    if hasattr(app, "build_scoring_consistency_decision"):
        write_csv("scoring_consistency_decision", app.build_scoring_consistency_decision(result, diagnostics))
    if hasattr(app, "build_help_reference_coverage"):
        write_csv("help_reference_coverage", app.build_help_reference_coverage())
    if hasattr(app, "build_quality_control_recommendations"):
        write_csv("quality_control_recommendations", app.build_quality_control_recommendations(result, diagnostics))
    if hasattr(app, "build_quality_control_todo_checklist"):
        write_csv("quality_control_todo_checklist", app.build_quality_control_todo_checklist(result, diagnostics))
    if hasattr(app, "build_scoring_quality_first_read_summary"):
        write_csv("scoring_quality_first_read_summary", app.build_scoring_quality_first_read_summary(result, diagnostics))
    if hasattr(app, "scoring_quality_term_guide"):
        write_csv("scoring_quality_term_guide", app.scoring_quality_term_guide())
    if hasattr(app, "generate_apa_scoring_quality_draft"):
        draft = app.generate_apa_scoring_quality_draft(result, diagnostics)
        OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
        draft_path = OUTPUT_DIR / "apa_scoring_quality_draft.md"
        draft_path.write_text(draft, encoding="utf-8")
        print(f"  wrote {{draft_path}}")
    if hasattr(app, "rating_scale_functioning_dashboard"):
        write_csv("rating_scale_functioning_dashboard", app.rating_scale_functioning_dashboard(result, diagnostics))
    if hasattr(app, "rating_scale_decision_support_table"):
        write_csv("rating_scale_decision_support", app.rating_scale_decision_support_table(result, diagnostics))
    if hasattr(app, "category_collapse_action_center_table"):
        write_csv("category_collapse_action_center", app.category_collapse_action_center_table(result, diagnostics))
    if hasattr(app, "rating_scale_recode_candidate_table"):
        write_csv("rating_scale_recode_candidates", app.rating_scale_recode_candidate_table(result, diagnostics))
    if hasattr(app, "rating_scale_recode_map_long_table"):
        write_csv("rating_scale_recode_map_long", app.rating_scale_recode_map_long_table(result, diagnostics))
    if hasattr(app, "rating_scale_category_evidence_table"):
        write_csv("rating_scale_category_evidence", app.rating_scale_category_evidence_table(result, diagnostics))
    if hasattr(app, "generate_category_collapse_sensitivity_draft"):
        draft = app.generate_category_collapse_sensitivity_draft(result, diagnostics)
        OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
        draft_path = OUTPUT_DIR / "apa_category_collapse_sensitivity_draft.md"
        draft_path.write_text(draft, encoding="utf-8")
        print(f"  wrote {{draft_path}}")
    write_csv("bias", diagnostics.get("bias"))
    write_csv("interactions", diagnostics.get("interactions"))
    write_csv("scorefile", app.compute_scorefile(result))
    if hasattr(app, "compute_fitted_prediction_table"):
        write_csv("fitted_predictions", app.compute_fitted_prediction_table(result))
    if args.new_design and hasattr(app, "predict_mfrm_design"):
        sep = "\\t" if str(args.new_design).lower().endswith((".tsv", ".txt")) else ","
        new_design = pd.read_csv(args.new_design, sep=sep)
        new_pred = app.predict_mfrm_design(
            result,
            new_design,
            person_col="Person",
            score_col="Score" if "Score" in new_design.columns else None,
            person_data=population_person_df,
            person_id_col=PERSON_ID_COL,
        )
        if isinstance(new_pred, dict):
            write_csv("new_design_predictions", new_pred.get("table"))
    if hasattr(app, "evaluate_design_from_fitted"):
        design = app.evaluate_design_from_fitted(result, diagnostics, forecast_multipliers=(2.0,))
        if isinstance(design, dict):
            write_csv("design_overview", design.get("overview"))
            write_csv("design_evaluation", design.get("summary"))
            write_csv("design_reliability_forecast", design.get("forecast"))
            write_csv("design_facet_counts", design.get("facet_counts"))
            write_csv("facet_sample_size_summary", design.get("sample_size_summary"))
            write_csv("facet_sample_size_adequacy", design.get("sample_size_adequacy"))
            write_csv("facet_nesting_audit", design.get("nesting_audit"))
            write_csv("intraclass_icc_design_effect", design.get("design_effect"))
    shrinkage = diagnostics.get("eb_shrinkage", {{}})
    if isinstance(shrinkage, dict):
        write_csv("eb_shrinkage_report", shrinkage.get("report"))
        write_csv("eb_shrinkage_measures", shrinkage.get("measures"))
    if hasattr(app, "build_weighting_policy_audit"):
        write_csv("weighting_policy_audit", app.build_weighting_policy_audit(result))
    if RUN_FITTED_SIMULATION and hasattr(app, "simulate_from_fitted_model"):
        sim = app.simulate_from_fitted_model(
            result,
            n_replicates=SIMULATION_REPLICATES,
            seed=SIMULATION_SEED,
            include_row_draws=False,
        )
        if isinstance(sim, dict):
            write_csv("simulation_summary", sim.get("summary"))
            write_csv("simulation_category_counts", sim.get("category_counts"))
    if RUN_REFIT_SIMULATION and hasattr(app, "simulate_refit_design"):
        refit_sim = app.simulate_refit_design(
            result,
            n_replicates=REFIT_SIMULATION_REPLICATES,
            seed=REFIT_SIMULATION_SEED,
            missing_rate=REFIT_SIMULATION_MISSING_RATE,
            refit_maxit=REFIT_SIMULATION_MAXIT,
            refit_method=REFIT_SIMULATION_METHOD,
        )
        if isinstance(refit_sim, dict):
            write_csv("refit_simulation_summary", refit_sim.get("summary"))
            write_csv("refit_simulation_category_counts", refit_sim.get("category_counts"))
    write_csv("residuals", app.compute_residual_file(result))

    if BIAS_MODE == "All facet pairs":
        bias_scan_pairs = list(combinations(["Person"] + FACET_COLS, 2))
    elif BIAS_MODE == "Selected pair" and SELECTED_BIAS_PAIR:
        bias_scan_pairs = [tuple(SELECTED_BIAS_PAIR)]
    else:
        bias_scan_pairs = []
    if bias_scan_pairs and hasattr(app, "estimate_bias_interaction"):
        for fa, fb in bias_scan_pairs:
            bundle = app.estimate_bias_interaction(
                result,
                diagnostics,
                fa,
                fb,
                max_abs=10.0,
                omit_extreme=True,
            )
            safe_pair = f"{{fa}}_{{fb}}".replace(" ", "_").replace("/", "_")
            if isinstance(bundle, dict):
                write_csv(f"bias_{{safe_pair}}", bundle.get("table"))
                write_csv(f"bias_{{safe_pair}}_summary", bundle.get("summary"))
                if hasattr(app, "build_dff_bias_screening_table"):
                    write_csv(f"dff_bias_{{safe_pair}}", app.build_dff_bias_screening_table(bundle))

    posterior = result.get("posterior", {{}})
    if isinstance(posterior, dict):
        write_csv("posterior_scores", posterior.get("scores"))
        write_csv("plausible_values", posterior.get("plausible_values"))

    marginal = diagnostics.get("marginal_fit", {{}})
    if isinstance(marginal, dict):
        write_csv("marginal_fit_summary", marginal.get("summary"))
        write_csv("marginal_fit_counts", marginal.get("counts"))
        pairwise = marginal.get("pairwise", {{}})
        if isinstance(pairwise, dict):
            write_csv("marginal_pairwise_summary", pairwise.get("summary"))
            write_csv("marginal_pairwise_counts", pairwise.get("counts"))

    anchor_audit = result.get("config", {{}}).get("anchor_audit", {{}})
    if isinstance(anchor_audit, dict):
        write_csv("anchor_audit_summary", anchor_audit.get("summary"))
        write_csv("anchor_audit_issues", anchor_audit.get("issues"))
        write_csv("valid_anchor_inputs", anchor_audit.get("valid_anchors"))
        write_csv("valid_group_anchor_inputs", anchor_audit.get("valid_group_anchors"))
    anchor_drift = result.get("anchor_drift", {{}})
    if isinstance(anchor_drift, dict):
        write_csv("anchor_drift_summary", anchor_drift.get("summary"))
        write_csv("anchor_drift", anchor_drift.get("anchor_drift"))
        write_csv("group_anchor_drift", anchor_drift.get("group_drift"))
    equating_chain = result.get("equating_chain", {{}})
    if isinstance(equating_chain, dict):
        write_csv("equating_chain_summary", equating_chain.get("summary"))
        write_csv("equating_chain_edges", equating_chain.get("edges"))
    write_csv("anchor_equating_workflow", result.get("anchor_equating_workflow"))


if __name__ == "__main__":
    main()
'''
    return script


def _generate_repro_python_script(result: dict, bias_pairs: list[tuple[str, str]] | None = None) -> str:
    """Generate a portable self-contained JMLE script for fixed-effect checks.

    Embeds the complete likelihood, optimisation, diagnostics, and fit statistics
    so the user does not need any external MFRM package. For the exact current
    app path (MML/PV/strict marginal), use the app-engine runner instead.
    """
    config = result.get("config", {})
    prep = result.get("prep", {})

