def is_advanced_response_model(name: str | None) -> bool:
    """True if `name` is one of the Stan-first-only advanced models."""
    if not name:
        return False
    return str(name).upper() in _ADVANCED_RESPONSE_MODELS


def advanced_model_metadata(name: str) -> dict[str, str]:
    """Return the registry entry for an advanced model, or an empty dict."""
    return dict(_ADVANCED_RESPONSE_MODELS.get(str(name).upper(), {}))


def advanced_model_options() -> list[tuple[str, str]]:
    """List of `(key, human_label)` tuples for the sidebar picker."""
    return [(k, v["label"]) for k, v in _ADVANCED_RESPONSE_MODELS.items()]


def advanced_model_data_template(model_name: str) -> dict:
    """Return a small user-facing data template for the selected Stan model."""
    name = str(model_name or "").upper()
    if name == "DINA":
        df = pd.DataFrame({
            "person": ["P1", "P2", "P3"],
            "I1": [1, 0, 1],
            "I2": [0, 1, 1],
            "I3": [1, 1, 0],
        })
        note = "Wide binary response matrix. Pair with a Q-matrix whose item rows match I1, I2, I3."
        file_name = "mfrm_dina_response_matrix_template.csv"
    elif name == "HRM":
        df = pd.DataFrame({
            "person": ["P1", "P1", "P2", "P2"],
            "item": ["Task1", "Task1", "Task1", "Task2"],
            "rater": ["R1", "R2", "R1", "R2"],
            "score": [3, 4, 2, 3],
        })
        note = "Long ordinal ratings. Map labels to 1-based integer IDs before passing data to Stan."
        file_name = "mfrm_hrm_long_template.csv"
    elif name in {"TESTLET_RI", "TESTLET_BIFACTOR"}:
        df = pd.DataFrame({
            "person": ["P1", "P1", "P2", "P2"],
            "item": ["Item1", "Item2", "Item1", "Item3"],
            "testlet": ["PassageA", "PassageA", "PassageA", "PassageB"],
            "score": [1, 2, 0, 1],
        })
        note = (
            "Long ordinal ratings with a testlet/passage column. "
            "Use when local dependence is expected within item bundles."
        )
        file_name = f"mfrm_{name.lower()}_long_template.csv"
    elif name == "MIXTURE_RASCH":
        df = pd.DataFrame({
            "person": ["P1", "P1", "P2", "P2"],
            "item": ["Item1", "Item2", "Item1", "Item2"],
            "score": [1, 0, 0, 1],
        })
        note = (
            "Binary long-format responses for latent-class Rasch. "
            "This mixture is a latent response-pattern class model, not a response-time model."
        )
        file_name = "mfrm_mixture_rasch_long_template.csv"
    elif name == "IRT_2PL_BINARY":
        df = pd.DataFrame({
            "person": ["P1", "P1", "P2", "P2"],
            "item": ["Item1", "Item2", "Item1", "Item2"],
            "score": [1, 0, 0, 1],
        })
        note = "Binary long-format responses for a 2PL model with item discrimination."
        file_name = "mfrm_2pl_binary_long_template.csv"
    elif name == "PAIRWISE_BTL":
        df = pd.DataFrame({
            "object_a": ["EssayA", "EssayA", "EssayB"],
            "object_b": ["EssayB", "EssayC", "EssayC"],
            "wins_a": [1, 0, 1],
        })
        note = "Pairwise-comparison outcomes. wins_a is 1 when object_a is preferred to object_b."
        file_name = "mfrm_pairwise_btl_template.csv"
    elif name == "UTO_BAYESIAN_MFRM":
        df = pd.DataFrame({
            "person": ["P1", "P1", "P2", "P2"],
            "rater": ["R1", "R2", "R1", "R2"],
            "task": ["Essay1", "Essay1", "Essay1", "Essay2"],
            "criterion": ["Content", "Content", "Organization", "Organization"],
            "time_block": [1, 1, 2, 2],
            "score": [4, 3, 2, 4],
        })
        note = (
            "Long ordinal ratings for a Uto-family Bayesian MFRM scaffold. "
            "Criterion indexes multidimensional rubric traits; time_block supports rater severity drift."
        )
        file_name = "mfrm_uto_bayesian_mfrm_long_template.csv"
    else:
        df = pd.DataFrame()
        note = "No template is registered for this model."
        file_name = "mfrm_advanced_model_template.csv"
    return {"data": df, "file_name": file_name, "note": note}


def advanced_model_scope_notes(model_name: str) -> str:
    """Boundary-safe wording for advanced Stan model boundaries."""
    name = str(model_name or "").upper()
    if name in {"TESTLET_RI", "TESTLET_BIFACTOR"}:
        return (
            "Local dependence here means residual association among items that share a passage, station, "
            "or testlet after the main trait is accounted for. The generated Stan code models that dependence "
            "with testlet random effects. It is separate from the fixed non-person facet interactions in the "
            "FACETS-mode bias table."
        )
    if name == "MIXTURE_RASCH":
        return (
            "Mixture Rasch here means unobserved latent classes with class-specific item difficulties. "
            "It does not use response time. If response time is part of the study, extend the Stan data block "
            "and likelihood explicitly rather than treating this mixture as a speed or inattentive-rating model."
        )
    if name == "HRM":
        return (
            "The hierarchical rater model separates rater accuracy and rater bias in a Bayesian ordinal model. "
            "Run it locally in Stan when rater behavior itself is the target of inference."
        )
    if name == "DINA":
        return (
            "DINA is for binary cognitive-diagnostic data with a Q-matrix. It is not a many-facet rating-scale "
            "replacement unless the assessment design is explicitly attribute based."
        )
    if name == "UTO_BAYESIAN_MFRM":
        return (
            "This scaffold is aligned with the Uto-family Bayesian MFRM references in the method audit: "
            "generalized Bayesian MFRM (Uto & Ueno, 2020), multidimensional rubric criteria (Uto, 2021), "
            "and Markov-style rater severity drift (Uto, 2023). It is a research template, not a claim "
            "that the current app has already validated those extensions for the uploaded run."
        )
    return (
        "The generated Stan model is a local-analysis template. Check priors, constraints, and data indexing "
        "before using posterior summaries in a report."
    )


# ---------------------------------------------------------------------------
# Stan code generators (C2 – C6)
# ---------------------------------------------------------------------------
# Each generator returns a complete, well-formed Stan program as a string.
# The programs are written to be compiled with cmdstan / cmdstanpy / rstan
# on the user's own machine; this file does not compile or sample them.

def generate_dina_stan_code(n_items: int, n_attributes: int) -> str:
    """DINA CDM (de la Torre 2009) with slip / guess priors and profile class.

    Signature matches `Y[person, item] ~ Bernoulli(phi)` where
    phi = (1 - s_i) * eta + g_i * (1 - eta), eta = prod_k alpha_k^{q_ik}.
    """
    return f"""data {{
  int<lower=1> J;                // persons
  int<lower=1> I;                // items
  int<lower=1> K;                // attributes
  int<lower=0, upper=1> Y[J, I]; // response matrix
  matrix<lower=0, upper=1>[I, K] Q;
}}
transformed data {{
  int<lower=1> C = 1;
  for (k in 1:K) C = C * 2;
  matrix[C, K] profile;
  for (c in 1:C) {{
    int rem = c - 1;
    for (k in 1:K) {{
      profile[c, k] = rem % 2;
      rem = rem / 2;
    }}
  }}
}}
parameters {{
  simplex[C] class_probs;
  vector<lower=0, upper=0.5>[I] slip;
  vector<lower=0, upper=0.5>[I] guess;
}}
model {{
  slip ~ beta(2, 10);
  guess ~ beta(2, 10);
  for (j in 1:J) {{
    vector[C] lps;
    for (c in 1:C) {{
      real lp = log(class_probs[c]);
      for (i in 1:I) {{
        real eta = 1.0;
        for (k in 1:K) eta = eta * (Q[i, k] == 0 ? 1.0 : profile[c, k]);
        real phi = (1 - slip[i]) * eta + guess[i] * (1 - eta);
        lp += bernoulli_lpmf(Y[j, i] | phi);
      }}
      lps[c] = lp;
    }}
    target += log_sum_exp(lps);
  }}
}}
generated quantities {{
  int<lower=1, upper=C> profile_class[J];
  vector[J] log_lik;
  for (j in 1:J) {{
    vector[C] lps;
    for (c in 1:C) {{
      real lp = log(class_probs[c]);
      for (i in 1:I) {{
        real eta = 1.0;
        for (k in 1:K) eta = eta * (Q[i, k] == 0 ? 1.0 : profile[c, k]);
        real phi = (1 - slip[i]) * eta + guess[i] * (1 - eta);
        lp += bernoulli_lpmf(Y[j, i] | phi);
      }}
      lps[c] = lp;
    }}
    log_lik[j] = log_sum_exp(lps);
    profile_class[j] = categorical_rng(softmax(lps));
  }}
}}
"""


def generate_hrm_stan_code(n_categories: int) -> str:
    """Hierarchical Rater Model (Patz et al. 2002) with signal-detection
    parameters phi (accuracy) and eta (bias)."""
    return f"""data {{
  int<lower=1> N;                              // number of observations
  int<lower=1> J;                              // persons
  int<lower=1> I;                              // items
  int<lower=1> R;                              // raters
  int<lower=2> K;                              // number of categories ({n_categories} expected)
  int<lower=1, upper=J> person[N];
  int<lower=1, upper=I> item[N];
  int<lower=1, upper=R> rater[N];
  int<lower=1, upper=K> y[N];
}}
parameters {{
  vector[J] theta;
  vector[I] beta_item;
  ordered[K-1] kappa;                          // global step thresholds
  vector<lower=0>[R] phi;                      // rater accuracy (signal)
  vector[R] eta;                               // rater bias
  real<lower=0> sigma_phi;
  real<lower=0> sigma_eta;
}}
model {{
  theta ~ std_normal();
  beta_item ~ normal(0, 1);
  kappa ~ normal(0, 2);
  phi ~ lognormal(0, sigma_phi);
  eta ~ normal(0, sigma_eta);
  sigma_phi ~ normal(0, 1);
  sigma_eta ~ normal(0, 1);
  for (n in 1:N) {{
    vector[K] ps;
    real mu = phi[rater[n]] * (theta[person[n]] - beta_item[item[n]]) + eta[rater[n]];
    for (k in 1:K) ps[k] = 0;
    for (k in 2:K) ps[k] = ps[k-1] + mu - kappa[k-1];
    y[n] ~ categorical_logit(ps);
  }}
}}
generated quantities {{
  vector[N] log_lik;
  int<lower=1, upper=K> y_rep[N];
  for (n in 1:N) {{
    vector[K] ps;
    real mu = phi[rater[n]] * (theta[person[n]] - beta_item[item[n]]) + eta[rater[n]];
    ps[1] = 0;
    for (k in 2:K) ps[k] = ps[k-1] + mu - kappa[k-1];
    log_lik[n] = categorical_logit_lpmf(y[n] | ps);
    y_rep[n] = categorical_logit_rng(ps);
  }}
}}
"""


def generate_testlet_stan_code(n_categories: int, *, bifactor: bool = False) -> str:
    """Testlet model: random intercept (Bradlow 1999) or bifactor (DeMars 2006)."""
    extra_theta = "  vector[T] theta_testlet_general;\n" if bifactor else ""
    gen_mu = (
        "    real mu = theta[person[n]] + theta_testlet_general[testlet[n]]"
        " + gamma_testlet[testlet[n]] - beta_item[item[n]];"
        if bifactor
        else "    real mu = theta[person[n]] + gamma_testlet[testlet[n]] - beta_item[item[n]];"
    )
    bifactor_prior = (
        "  theta_testlet_general ~ normal(0, sigma_general);\n"
        "  real<lower=0> sigma_general = 1;\n"
        if bifactor
        else ""
    )
    return f"""data {{
  int<lower=1> N;
  int<lower=1> J;
  int<lower=1> I;
  int<lower=1> T;                 // number of testlets
  int<lower=2> K;                 // {n_categories} categories
  int<lower=1, upper=J> person[N];
  int<lower=1, upper=I> item[N];
  int<lower=1, upper=T> testlet[N];
  int<lower=1, upper=K> y[N];
}}
parameters {{
  vector[J] theta;
  vector[I] beta_item;
  ordered[K-1] kappa;
  vector[T] gamma_testlet;        // testlet random intercepts
  real<lower=0> sigma_testlet;
{extra_theta}}}
model {{
  theta ~ std_normal();
  beta_item ~ normal(0, 1);
  kappa ~ normal(0, 2);
  gamma_testlet ~ normal(0, sigma_testlet);
  sigma_testlet ~ normal(0, 1);
{bifactor_prior}  for (n in 1:N) {{
    vector[K] ps;
{gen_mu}
    ps[1] = 0;
    for (k in 2:K) ps[k] = ps[k-1] + mu - kappa[k-1];
    y[n] ~ categorical_logit(ps);
  }}
}}
generated quantities {{
  vector[N] log_lik;
  int<lower=1, upper=K> y_rep[N];
  for (n in 1:N) {{
    vector[K] ps;
{gen_mu}
    ps[1] = 0;
    for (k in 2:K) ps[k] = ps[k-1] + mu - kappa[k-1];
    log_lik[n] = categorical_logit_lpmf(y[n] | ps);
    y_rep[n] = categorical_logit_rng(ps);
  }}
}}
"""


def generate_mixture_rasch_stan_code(n_classes: int) -> str:
    """Mixture Rasch (Rost 1990): latent classes with class-specific item difficulties."""
    return f"""data {{
  int<lower=1> N;
  int<lower=1> J;
  int<lower=1> I;
  int<lower=2> C_mix;                  // number of latent classes ({n_classes})
  int<lower=1, upper=J> person[N];
  int<lower=1, upper=I> item[N];
  int<lower=0, upper=1> y[N];
}}
parameters {{
  simplex[C_mix] class_probs;
  vector[J] theta;
  matrix[C_mix, I] beta_class;
}}
model {{
  class_probs ~ dirichlet(rep_vector(1, C_mix));
  theta ~ std_normal();
  to_vector(beta_class) ~ normal(0, 2);
  for (j in 1:J) {{
    vector[C_mix] lps;
    for (c in 1:C_mix) {{
      real lp = log(class_probs[c]);
      for (n in 1:N) {{
        if (person[n] == j) {{
          lp += bernoulli_logit_lpmf(y[n] | theta[j] - beta_class[c, item[n]]);
        }}
      }}
      lps[c] = lp;
    }}
    target += log_sum_exp(lps);
  }}
}}
generated quantities {{
  int<lower=1, upper=C_mix> person_class[J];
  vector[J] log_lik;
  for (j in 1:J) {{
    vector[C_mix] lps;
    for (c in 1:C_mix) {{
      real lp = log(class_probs[c]);
      for (n in 1:N) {{
        if (person[n] == j) {{
          lp += bernoulli_logit_lpmf(y[n] | theta[j] - beta_class[c, item[n]]);
        }}
      }}
      lps[c] = lp;
    }}
    person_class[j] = categorical_rng(softmax(lps));
    log_lik[j] = log_sum_exp(lps);
  }}
}}
"""


def generate_2pl_binary_stan_code() -> str:
    """2PL Binary (Birnbaum 1968): free discrimination + difficulty."""
    return """data {
  int<lower=1> N;
  int<lower=1> J;
  int<lower=1> I;
  int<lower=1, upper=J> person[N];
  int<lower=1, upper=I> item[N];
  int<lower=0, upper=1> y[N];
}
parameters {
  vector[J] theta;
  vector[I] beta_item;
  vector<lower=0>[I] alpha_item;
}
model {
  theta ~ std_normal();
  beta_item ~ normal(0, 1);
  alpha_item ~ lognormal(0, 0.5);
  for (n in 1:N) {
    y[n] ~ bernoulli_logit(alpha_item[item[n]] * (theta[person[n]] - beta_item[item[n]]));
  }
}
generated quantities {
  vector[N] log_lik;
  int<lower=0, upper=1> y_rep[N];
  for (n in 1:N) {
    real logit_p = alpha_item[item[n]] * (theta[person[n]] - beta_item[item[n]]);
    log_lik[n] = bernoulli_logit_lpmf(y[n] | logit_p);
    y_rep[n] = bernoulli_logit_rng(logit_p);
  }
}
"""


def generate_pairwise_btl_stan_code() -> str:
    """Pairwise Bradley-Terry-Luce: probability that object A beats opponent B."""
    return """data {
  int<lower=1> N;                       // comparisons
  int<lower=1> J;                       // objects being compared
  int<lower=1, upper=J> object_a[N];
  int<lower=1, upper=J> object_b[N];
  int<lower=0, upper=1> wins_a[N];
}
parameters {
  vector[J] ability;
}
model {
  ability ~ std_normal();
  for (n in 1:N) {
    wins_a[n] ~ bernoulli_logit(ability[object_a[n]] - ability[object_b[n]]);
  }
}
generated quantities {
  vector[N] log_lik;
  int<lower=0, upper=1> wins_rep[N];
  for (n in 1:N) {
    real diff = ability[object_a[n]] - ability[object_b[n]];
    log_lik[n] = bernoulli_logit_lpmf(wins_a[n] | diff);
    wins_rep[n] = bernoulli_logit_rng(diff);
  }
}
"""


def generate_uto_bayesian_mfrm_stan_code(n_categories: int) -> str:
    """Uto-family Bayesian MFRM scaffold with multidimensional criteria and drift."""
    return f"""// Uto-family Bayesian MFRM scaffold.
// Reference basis in this app's method audit:
// - Uto & Ueno (2020): generalized MFRM and Bayesian HMC estimation.
// - Uto (2021): multidimensional generalized MFRM for rubric criteria.
// - Uto (2023): Bayesian MFRM with Markov modeling for rater severity drift.
// This is a transparent research scaffold, not a validated exact reproduction
// of any one paper's full parameterization.

data {{
  int<lower=1> N;                         // observations
  int<lower=1> J;                         // persons
  int<lower=1> R;                         // raters
  int<lower=1> I;                         // tasks/items
  int<lower=1> C_dim;                     // rubric criteria / dimensions
  int<lower=1> S;                         // ordered time blocks for drift
  int<lower=2> K;                         // rating categories ({n_categories} expected)
  array[N] int<lower=1, upper=J> person;
  array[N] int<lower=1, upper=R> rater;
  array[N] int<lower=1, upper=I> task;
  array[N] int<lower=1, upper=C_dim> criterion;
  array[N] int<lower=1, upper=S> time_block;
  array[N] int<lower=1, upper=K> y;
}}

parameters {{
  vector[C_dim] theta_mu;
  vector<lower=0>[C_dim] theta_sigma;
  cholesky_factor_corr[C_dim] L_theta_corr;
  matrix[J, C_dim] theta_raw;
  vector[I] task_raw;
  vector[C_dim] criterion_raw;
  vector[R] rater_base_raw;
  matrix[R, S] rater_drift_raw;
  real<lower=0> sigma_task;
  real<lower=0> sigma_criterion;
  real<lower=0> sigma_rater;
  real<lower=0> sigma_drift;
  ordered[K - 1] kappa;
}}

transformed parameters {{
  matrix[C_dim, J] theta_latent;
  vector[I] task_difficulty;
  vector[C_dim] criterion_difficulty;
  vector[R] rater_base;
  matrix[R, S] rater_severity;

  theta_latent = diag_pre_multiply(theta_sigma, L_theta_corr) * theta_raw';
  task_difficulty = (task_raw - mean(task_raw)) * sigma_task;
  criterion_difficulty = (criterion_raw - mean(criterion_raw)) * sigma_criterion;
  rater_base = (rater_base_raw - mean(rater_base_raw)) * sigma_rater;

  for (r in 1:R) {{
    rater_severity[r, 1] = rater_base[r] + sigma_drift * rater_drift_raw[r, 1];
    if (S > 1) {{
      for (s in 2:S) {{
        rater_severity[r, s] = rater_severity[r, s - 1] + sigma_drift * rater_drift_raw[r, s];
      }}
    }}
  }}
}}

model {{
  theta_mu ~ normal(0, 1);
  theta_sigma ~ normal(0, 1);
  L_theta_corr ~ lkj_corr_cholesky(2);
  to_vector(theta_raw) ~ std_normal();

  task_raw ~ std_normal();
  criterion_raw ~ std_normal();
  rater_base_raw ~ std_normal();
  to_vector(rater_drift_raw) ~ std_normal();

  sigma_task ~ normal(0, 1);
  sigma_criterion ~ normal(0, 1);
  sigma_rater ~ normal(0, 1);
  sigma_drift ~ normal(0, 0.5);
  kappa ~ normal(0, 2);

  for (n in 1:N) {{
    real eta = theta_mu[criterion[n]]
      + theta_latent[criterion[n], person[n]]
      - task_difficulty[task[n]]
      - criterion_difficulty[criterion[n]]
      - rater_severity[rater[n], time_block[n]];
    y[n] ~ ordered_logistic(eta, kappa);
  }}
}}

generated quantities {{
  corr_matrix[C_dim] theta_corr;
  vector[N] log_lik;
  array[N] int<lower=1, upper=K> y_rep;

  theta_corr = multiply_lower_tri_self_transpose(L_theta_corr);
  for (n in 1:N) {{
    real eta = theta_mu[criterion[n]]
      + theta_latent[criterion[n], person[n]]
      - task_difficulty[task[n]]
      - criterion_difficulty[criterion[n]]
      - rater_severity[rater[n], time_block[n]];
    log_lik[n] = ordered_logistic_lpmf(y[n] | eta, kappa);
    y_rep[n] = ordered_logistic_rng(eta, kappa);
  }}
}}
"""


def generate_advanced_model_stan_code(
    model_name: str,
    *,
    n_items: int = 10,
    n_attributes: int = 3,
    n_categories: int = 5,
    n_classes: int = 2,
) -> str:
    """Dispatch to the right Stan-code generator for an advanced model."""
    name = str(model_name).upper()
    if name == "DINA":
        code = generate_dina_stan_code(n_items, n_attributes)
    elif name == "HRM":
        code = generate_hrm_stan_code(n_categories)
    elif name == "TESTLET_RI":
        code = generate_testlet_stan_code(n_categories, bifactor=False)
    elif name == "TESTLET_BIFACTOR":
        code = generate_testlet_stan_code(n_categories, bifactor=True)
    elif name == "MIXTURE_RASCH":
        code = generate_mixture_rasch_stan_code(n_classes)
    elif name == "IRT_2PL_BINARY":
        code = generate_2pl_binary_stan_code()
    elif name == "PAIRWISE_BTL":
        code = generate_pairwise_btl_stan_code()
    elif name == "UTO_BAYESIAN_MFRM":
        code = generate_uto_bayesian_mfrm_stan_code(n_categories)
    else:
        raise ValueError(f"Unknown advanced model: {model_name}")
    label = advanced_model_metadata(name).get("label", name)
    return stan_code_sensitivity_notice(label) + "\n" + code


def validate_q_matrix(q_df: pd.DataFrame) -> dict:
    """Validate a user-supplied Q-matrix for DINA / G-DINA.

    Returns a dict with
      - `valid` (bool)
      - `messages` (list[str])  — human-readable problems (empty if valid)
      - `n_items`, `n_attributes`, `coverage`
    """
    messages: list[str] = []
    if q_df is None or q_df.empty:
        return {"valid": False, "messages": ["Q-matrix is empty."], "n_items": 0, "n_attributes": 0, "coverage": 0.0}
    numeric = q_df.apply(pd.to_numeric, errors="coerce")
    if numeric.isna().any().any():
        messages.append("Q-matrix contains non-numeric values (cells must be 0 or 1).")
    unique = set(pd.unique(numeric.values.ravel())) - {np.nan}
    if not unique.issubset({0, 1, 0.0, 1.0}):
        messages.append(f"Q-matrix values must be 0 or 1; found {sorted(unique)}.")
    row_sums = numeric.fillna(0).sum(axis=1)
    if (row_sums <= 0).any():
        messages.append(f"{int((row_sums <= 0).sum())} item(s) have no attributes (empty row in Q).")
    col_sums = numeric.fillna(0).sum(axis=0)
    if (col_sums <= 0).any():
        messages.append(f"{int((col_sums <= 0).sum())} attribute(s) cover no items (empty column in Q).")
    n_items, n_attributes = numeric.shape
    coverage = float((numeric.fillna(0) > 0).values.mean()) if numeric.size else 0.0
    return {
        "valid": not messages,
        "messages": messages,
        "n_items": int(n_items),
        "n_attributes": int(n_attributes),
        "coverage": coverage,
    }


def render_keyboard_shortcuts_help() -> None:
    """Collapsed sidebar expander summarising keyboard shortcuts.

    Streamlit itself ships with several built-in shortcuts; the app adds
    none of its own because the hotkey surface is shared with every
    widget. This section just documents what already works so users
    don't have to guess.
    """
    with st.sidebar.expander("Keyboard shortcuts", expanded=False):
        st.markdown(
            "| Key | Action |\n"
            "|---|---|\n"
            "| `R` | Re-run the app (also: top-right ⋮ menu → Rerun) |\n"
            "| `C` | Clear the app cache (⋮ menu → Clear cache) |\n"
            "| `Esc` | Close modals / dialogs |\n"
            "| `?` | Keyboard shortcuts cheat sheet (this list) |\n"
            "| `Tab` / `Shift+Tab` | Move focus across widgets |\n"
            "| `Space` / `Enter` | Toggle checkboxes / activate buttons |\n"
            "| `Ctrl/Cmd + F` | Browser page search (works across tabs) |\n"
            "\n"
            "The **Run FACETS-mode estimation** button is the primary "
            "Streamlit button on the sidebar — `Tab` to reach it, `Enter` to fire."
        )


